def _resolve_config_execution_policy(config: dict[str, Any]) -> ExecutionPolicy:
    """Resolve the one execution policy shared by all live verify gates."""
    pipeline = VerificationPipeline(str(config.get("pipeline") or "sc").lower())
    mode = VerificationAuditMode(str(config.get("mode") or "core").lower())
    backend = VerificationBackend(
        str(config.get("cli_backend") or "claude").lower()
    )
    language = str(config.get("language") or "").lower()
    if not language:
        language = "rust" if pipeline is VerificationPipeline.L1 else "evm"
    ecosystem = VerificationEcosystem(language)
    platform = (
        VerificationPlatform.WINDOWS
        if os.name == "nt"
        else VerificationPlatform.POSIX
    )
    return resolve_execution_policy(
        mode,
        backend,
        pipeline,
        ecosystem,
        platform,
    )


