def _codex_mandatory_secondary_names(
    phase_name: str, pipeline: str, mode: str, scratchpad: Optional[Path]
) -> list[str]:
    """Return a phase's mandatory pre-created SECONDARY artifact filenames.

    Scalar-arg sibling of `_codex_secondary_artifact_targets` (which needs a
    Phase object) so prompt-construction code can call it. Single source of
    truth for both (a) the pre-created-fill directive and (b) the Codex depth
    Expected-Output-Contract widening. Derives names from the same canonical
    sources (`sc_never_cut_groups` / `l1_never_cut_groups`,
    `_required_niche_worker_jobs`, `_recon_worker_jobs`); for `[A|B]`
    alternations only the first representative is returned.
    """
    pipeline = (pipeline or "sc").lower()
    mode = (mode or "core").lower()
    names: list[str] = []
    if phase_name == "depth":
        try:
            groups = (
                l1_never_cut_groups(mode)
                if pipeline == "l1"
                else sc_never_cut_groups(mode)
            )
        except Exception:
            groups = []
        for group in groups:
            if group:
                name = group[0]
                if name not in {
                    "confidence_scores.md",
                    "confidence_consensus_authority.json",
                    "consensus_map.md",
                }:
                    names.append(name)
        if scratchpad is not None:
            try:
                for job in _required_niche_worker_jobs(scratchpad):
                    out = job.get("output")
                    if out:
                        names.append(out)
            except Exception:
                pass
    elif phase_name == "recon":
        try:
            for job in _recon_worker_jobs({"mode": mode, "pipeline": pipeline}):
                out = job.get("output")
                if out:
                    names.append(out)
        except Exception:
            pass
    seen: set = set()
    return [n for n in names if n and not (n in seen or seen.add(n))]


def _codex_widen_depth_output_contract(
    prompt_text: str, secondary_names: list[str]
) -> str:
    """Codex-only: add the mandatory secondary artifacts to the depth phase's
    EXPECTED OUTPUT FILES (HARD CONTRACT) section.

    The base depth prompt's `OUTPUT ALLOWLIST (HARD)` and `PHASE ISOLATION
    CONTRACT` both derive their allowed/writable set from "this phase's Expected
    Output Contract" — which lists only `depth_*_findings.md` (the core glob from
    `phase.expected_artifacts`). On Codex (single-turn, full base prompt) the
    model reads that allowlist literally, treats the never-cut scanners /
    validation / confidence / niche artifacts as "an output file outside this
    allowlist", and refuses to write them — failing the never-cut gate even
    though it precreated them and the checklist asked for them. By listing the
    secondaries INSIDE the Expected Output Contract, both downstream HARD
    references include them and the contradiction is gone.

    Claude PTY never reaches this: its depth prompt is replaced by the
    worker-pool stub (one allowlisted worker per artifact). This function runs
    only inside `_translate_prompt_for_codex` (`if backend == "codex"`), so it
    cannot affect a Claude run. Skips gracefully (returns input unchanged) if
    the anchor header is absent or there are no secondaries — never corrupts.
    """
    if not secondary_names:
        return prompt_text
    header = (
        "## EXPECTED OUTPUT FILES (HARD CONTRACT -- GATE WILL FAIL IF VIOLATED)"
    )
    if header not in prompt_text:
        return prompt_text  # base prompt shape changed — skip, do not corrupt
    block_lines = [
        "",
        "### Mandatory secondary outputs (part of THIS contract and your allowlist)",
        "",
        "The artifacts below are PART of this phase's Expected Output Contract "
        "and your OUTPUT ALLOWLIST — NOT 'outside the allowlist'. They are "
        "pre-created EMPTY on disk (apply_patch can modify them; they already "
        "exist). You MUST fill EACH with real first-pass content this phase. The "
        "post-phase never-cut gate FAILS the phase if any is missing or empty, "
        "so these are mandatory, not optional:",
        "",
    ]
    block_lines += [f"- `{n}`" for n in secondary_names]
    block = "\n".join(block_lines) + "\n"
    return prompt_text.replace(header, header + "\n" + block, 1)


def _codex_precreated_fill_directive(
    phase_name: str, pipeline: str, mode: str, scratchpad: Optional[Path]
) -> str:
    """Codex-only directive naming the pre-created secondary files to fill.

    `_precreate_codex_artifacts` seeds empty files for the phase's mandatory
    secondary artifacts (never-cut scanners/validation/confidence, triggered
    niches, recon shards) because Codex's apply_patch cannot create new files.
    This tells the model those EMPTY files already exist on disk and MUST be
    filled with real content this phase — an empty seed still fails the
    never-cut/stub gate, so leaving them blank degrades the phase.

    Derives the same filenames as `_codex_secondary_artifact_targets` from the
    existing sources so the prompt and the seeding stay in sync.
    """
    deduped = _codex_mandatory_secondary_names(
        phase_name, pipeline, mode, scratchpad
    )
    if not deduped:
        return ""

    lines = [
        "## PRE-CREATED SECONDARY ARTIFACTS (Codex — MUST FILL)",
        "",
        "The following files have already been created EMPTY on disk so your",
        "apply_patch tool has valid targets (apply_patch cannot create new",
        "files). You MUST fill EACH with real first-pass content this phase.",
        "An empty file still FAILS the mandatory artifact gate, so leaving any",
        "of these blank degrades the phase:",
        "",
    ]
    lines += [f"- {n}" for n in deduped]
    lines.append("")
    return "\n".join(lines)


def _translate_prompt_for_codex(prompt_text: str, *,
                               phase_name: str = "",
                               pipeline: str = "",
                               mode: str = "",
                               scratchpad: Optional[Path] = None) -> str:
    """Translate Claude-specific prompt content for Codex runtime.

    Path translation: only rewrite ~/.claude/ → ~/.codex/plamen/ when the
    target directory actually exists on disk.  Otherwise keep ~/.claude/ as-is
    — the Codex sandbox can read the entire filesystem, so the original paths
    resolve fine.

    Also strips Claude-specific references that create noise or contradiction
    in a Codex subprocess (MCP timeout mentions, AskUserQuestion references,
    "Task tool" phrasing).

    Multi-agent phases (breadth, depth, rescan, recon) get the spawn_agent
    preamble instead of the single-agent preamble, enabling parallel sub-agent
    execution within the phase.

    For the depth phase, injects a mandatory artifact checklist with an
    explicit spawn plan so gpt-5.6-sol produces all required artifacts on
    attempt 1 (v2.6.2).
    """
    codex_home = Path.home() / ".codex" / "plamen"
    if not codex_home.is_dir():
        raise RuntimeError(
            f"Codex backend is active but {codex_home} does not exist. "
            f"Create it as a symlink to your Plamen install "
            f"(e.g., mklink /D \"{codex_home}\" \"{Path.home() / '.claude'}\")"
        )
    # Rewrite every ~/.claude reference to the Codex methodology mirror, covering
    # ALL forms the prompts / methodology files can carry, on every platform:
    #   ~/.claude/ , $HOME/.claude/ , <expanded-home>/.claude(/) , and the
    #   no-trailing-slash variants (sys.path.insert('~/.claude'), --add-dir ~/.claude).
    translated = prompt_text.replace("~/.claude/", "~/.codex/plamen/")
    translated = translated.replace("$HOME/.claude/", "~/.codex/plamen/")
    home_fwd = str(Path.home()).replace("\\", "/")
    translated = translated.replace(f"{home_fwd}/.claude/", "~/.codex/plamen/")
    if "\\" in str(Path.home()):
        translated = translated.replace(
            f"{str(Path.home())}\\.claude\\", "~/.codex/plamen/"
        )
    translated = translated.replace("$HOME/.claude", "~/.codex/plamen")
    translated = re.sub(r"~/\.claude(?![\w./])", "~/.codex/plamen", translated)

    translated = translated.replace("claude -p subprocess", "codex exec subprocess")
    translated = translated.replace("Claude Code's MCP timeout is 300s", "MCP tools are unavailable in this runtime")
    translated = translated.replace(
        "Claude Code's tool timeout is set to 300s (5 min) via MCP_TOOL_TIMEOUT in settings.json to accommodate ChromaDB cold start.",
        "MCP tools are unavailable in this runtime.",
    )
    translated = re.sub(
        r"do NOT call AskUserQuestion\b",
        "do NOT ask the user questions",
        translated,
    )
    is_multi = phase_name in _CODEX_MULTI_AGENT_PHASES
    if is_multi:
        # Multi-agent phases: rewrite Task tool references to spawn_agent.
        # Keep Task() block structure intact — the preamble tells the model
        # how to translate them to spawn_agent calls.
        translated = re.sub(
            r"\buse the Task tool\b",
            "use spawn_agent",
            translated,
            flags=re.IGNORECASE,
        )
    else:
        # Single-agent phases: tell model to execute directly.
        translated = re.sub(
            r"\buse the Task tool\b",
            "execute the analysis directly",
            translated,
            flags=re.IGNORECASE,
        )

    preamble = _codex_tool_preamble(
        multi_agent=is_multi,
        external_search_allowed=phase_name in {"recon", "rag_sweep"},
    )

    # v2.6.2: inject mandatory artifact checklist for depth phase.
    # gpt-5.6-sol reliably spawns the core depth agents but misses Thorough
    # sub-steps (confidence scoring, DST, perturbation, skill checklist)
    # without an explicit spawn plan.
    depth_checklist = ""
    if phase_name == "depth" and is_multi:
        depth_checklist = _codex_depth_artifact_checklist(
            pipeline or "sc", mode or "core"
        ) + "\n"

    # Codex-only: name the pre-created secondary artifact files (seeded by
    # _precreate_codex_artifacts) the model must fill this phase.
    fill_directive = _codex_precreated_fill_directive(
        phase_name, pipeline or "sc", mode or "core", scratchpad
    )
    if fill_directive:
        fill_directive += "\n"

    # Codex-only: the base depth prompt's OUTPUT ALLOWLIST (HARD) and PHASE
    # ISOLATION CONTRACT derive their allowed set from the Expected Output
    # Contract, which lists only the depth_*_findings.md core glob. The model
    # then refuses the never-cut secondaries (blind-spot scanners, validation
    # sweep, confidence, niche) as "outside the allowlist". List those inside
    # the Expected Output Contract so the allowlist includes them. Depth only;
    # core depth_* reps are already covered by the glob, so drop them here.
    if phase_name == "depth":
        _secondary = [
            n
            for n in _codex_mandatory_secondary_names(
                phase_name, pipeline or "sc", mode or "core", scratchpad
            )
            if not (n.startswith("depth_") and n.endswith("_findings.md"))
        ]
        translated = _codex_widen_depth_output_contract(translated, _secondary)

    return preamble + "\n" + depth_checklist + fill_directive + translated


_CODEX_CONTEXT_LIMITS: dict[str, int] = {
    # Conservative token limits per model (chars ÷ 4 ≈ tokens).
    # Codex hard-errors on exceed (not silent truncation).
    # GPT-5.6 family: 1.05M context; keep a conservative 80% prompt ceiling.
    "gpt-5.6-sol": 840_000,
    "gpt-5.6-terra": 840_000,
    "gpt-5.6-luna": 840_000,
    # Legacy (deprecated Feb 2026, API sunset Oct 2026)
    "o3": 200_000,
    "o4-mini": 200_000,
    "gpt-4.1": 1_000_000,
    "gpt-4.1-mini": 1_000_000,
    "gpt-4.1-nano": 1_000_000,
}


def _codex_prompt_fits(prompt: str, model: str) -> bool:
    """Check if prompt likely fits the model's context window.

    Returns True if safe, False if prompt is dangerously large.
    Uses ~4 chars/token heuristic with a 20% safety margin for
    tool outputs and response tokens.
    """
    limit = _CODEX_CONTEXT_LIMITS.get(model, 272_000)
    # Reserve 20% for response + tool outputs
    effective_limit = int(limit * 0.80)
    estimated_tokens = len(prompt) // 4
    return estimated_tokens <= effective_limit


def _codex_auth_available() -> bool:
    """Check if Codex authentication is available (OAuth or API key).

    Without auth, `codex exec` will attempt interactive browser login,
    hanging indefinitely in a subprocess with no TTY.
    """
    if os.environ.get("CODEX_API_KEY") or os.environ.get("OPENAI_API_KEY"):
        return True
    auth_path = Path.home() / ".codex" / "auth.json"
    return auth_path.exists()


def _codex_auth_material_bytes() -> bytes:
    """Return exact auth bytes for an attempt-scoped isolated Codex home.

    API-key authentication needs no file material and is represented by an
    empty byte string. ChatGPT/OAuth authentication is copied only into the
    provider-owned auxiliary lease; the canonical profile is never exposed as
    a low-integrity writable root.
    """

    if os.environ.get("CODEX_API_KEY") or os.environ.get("OPENAI_API_KEY"):
        return b""
    auth_path = Path.home() / ".codex" / "auth.json"
    try:
        if not auth_path.is_file() or auth_path.is_symlink():
            raise RuntimeError("Codex auth.json is not a safe regular file")
        raw = auth_path.read_bytes()
    except OSError as exc:
        raise RuntimeError("Codex auth.json cannot be read") from exc
    if not raw or len(raw) > 1024 * 1024:
        raise RuntimeError("Codex auth.json has an invalid size")
    try:
        value = json.loads(raw.decode("utf-8", errors="strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("Codex auth.json is not strict JSON") from exc
    if not isinstance(value, dict):
        raise RuntimeError("Codex auth.json must contain a JSON object")
    return raw


def _backend_available(backend: str) -> bool:
    """Check whether *backend* is installed and authenticated.

    Reuses the existing Codex availability gate (binary + OAuth/API-key
    auth). Claude is the driver's unconditional default backend -- its own
    spawn path already surfaces a missing binary/auth failure directly, so
    it has no separate pre-check here (matches every other `cli_backend`
    read site, which treats "claude" as always selectable).
    """
    backend = (backend or "").strip().lower()
    if backend == "codex":
        return bool(CODEX_BIN) and _codex_auth_available()
    return True


def _effective_backend(config: dict, phase: "Phase") -> str:
    """Resolve the CLI backend to use for *phase*.

    Cross-vendor override (Wave-4 M1): `config["phase_backend_overrides"]`
    is an optional `{phase_name: backend}` map. When it names a backend for
    *phase* that differs from `config["cli_backend"]` AND that backend is
    actually available/authenticated, use it. Otherwise (no override, same
    backend, or override backend unavailable) fall back to
    `config["cli_backend"]` -- NEVER raises and NEVER fails the phase.

    With no `phase_backend_overrides` key (or none for this phase's name),
    this returns exactly `config.get("cli_backend", "claude")` -- the
    pre-existing default-path behavior is unchanged.
    """
    default_backend = (config.get("cli_backend") or "claude").strip().lower()
    overrides = config.get("phase_backend_overrides") or {}
    phase_name = getattr(phase, "name", phase)
    override = overrides.get(phase_name) if isinstance(overrides, dict) else None
    if not override:
        return default_backend
    override = str(override).strip().lower()
    if override == default_backend:
        return default_backend
    if _backend_available(override):
        return override
    log.warning(
        f"[{phase_name}] phase_backend_overrides requested backend "
        f"{override!r} but it is not available/authenticated -- falling "
        f"back to the configured cli_backend {default_backend!r}."
    )
    return default_backend


_CLAUDE_PROJECTION_CURRENT_ASSERT_ARG = (
    "--codex-install-assert-claude-projection-current"
)
_CLAUDE_PROJECTION_CURRENT_ASSERT_STDOUT = (
    b'{"schema":"plamen.claude_projection_current.v1","state":"CURRENT"}\n'
)
_DIRECT_CLAUDE_MCP_SELECTION: Mapping[str, Any] | None = None


class DirectDriverProjectionAdmissionError(RuntimeError):
    """A direct Claude driver launch lacks CURRENT installed projection state."""


def _direct_driver_installed_front_path() -> Path:
    """Resolve the installed front independently of checkout methodology paths."""

    return Path(os.path.abspath(os.path.expanduser("~/.plamen/plamen.py")))


def _installed_mcp_public_front_path() -> Path:
    """Resolve the receipt-authenticated public MCP launcher front."""

    leaf = "plamen.cmd" if os.name == "nt" else "plamen"
    return Path(os.path.abspath(os.path.expanduser(f"~/.local/bin/{leaf}")))


def _assert_claude_mcp_selection_current(
    *, timeout_s: int = 120
) -> dict[str, Any]:
    """Authenticate and freeze the current immutable Claude MCP generation."""

    command = [
        os.fspath(_installed_mcp_public_front_path()),
        "mcp-selection",
        "--json",
        "--backend",
        "claude",
    ]
    try:
        completed = subprocess.run(
            command,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=max(1, int(timeout_s)),
            check=False,
        )
    except (OSError, subprocess.SubprocessError, ValueError) as exc:
        raise DirectDriverProjectionAdmissionError(
            "installed MCP current-selection assertion could not execute: "
            f"{type(exc).__name__}"
        ) from exc
    raw = completed.stdout
    if (
        completed.returncode != 0
        or completed.stderr != b""
        or not isinstance(raw, bytes)
        or not raw.endswith(b"\n")
        or raw.count(b"\n") != 1
    ):
        raise DirectDriverProjectionAdmissionError(
            "installed Claude MCP selection is not authenticated CURRENT "
            f"state (assertion exit={completed.returncode})"
        )
    try:
        decoded = json.loads(raw[:-1].decode("utf-8"))
        selection = replay_mcp_current_selection(decoded)
        canonical = json.dumps(
            selection,
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8") + b"\n"
    except (
        ClaudeLaunchSecurityError,
        json.JSONDecodeError,
        TypeError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise DirectDriverProjectionAdmissionError(
            "installed Claude MCP selection response is malformed"
        ) from exc
    if raw != canonical:
        raise DirectDriverProjectionAdmissionError(
            "installed Claude MCP selection response is not canonical"
        )
    return selection


def _configured_audit_uses_claude(config: Mapping[str, Any]) -> bool:
    """Return whether this audit can select Claude for any configured phase.

    A Codex primary backend with no effective Claude override is genuinely
    Codex-only and must remain independent of Claude projection state.
    Conversely, a Claude primary backend or the dispatcher's effective skeptic
    override can execute a projected Claude worker and therefore requires
    CURRENT projection authority before the audit mutates project/scratch state.
    """

    primary = str(config.get("cli_backend") or "claude").strip().lower()
    if primary != "codex":
        return True
    overrides = config.get("phase_backend_overrides")
    if not isinstance(overrides, Mapping):
        return False
    # The live dispatcher currently consults overrides only for skeptic (see
    # run_phase).  An unrelated inert map entry cannot make a Codex audit use
    # Claude and therefore must not create a false Claude-state dependency.
    skeptic_override = str(overrides.get("skeptic") or "").strip().lower()
    return skeptic_override not in {"", "codex"}


def _admit_model_prompt_filesystem_roots(config: Mapping[str, Any]) -> None:
    """Reject filesystem roots that cannot be safely embedded in prompts.

    Prompts and the headless routing suffix use stable relative identifiers,
    but an unsafe root must still be rejected centrally before prompt creation
    or provider launch.  This prevents a future absolute-path interpolation
    from silently reintroducing Markdown or Unicode line-control injection.
    """

    for field in ("project_root", "scratchpad"):
        value = config.get(field)
        if not isinstance(value, str) or not value:
            raise ValueError(f"{field} must be a nonempty filesystem path")
        for component in Path(value).parts:
            if "`" in component or any(
                unicodedata.category(character).startswith("C")
                or unicodedata.category(character) in {"Zl", "Zp"}
                for character in component
            ):
                raise ValueError(
                    f"{field} contains a prompt-unsafe path component"
                )


def _assert_direct_claude_projection_current(*, timeout_s: int = 120) -> None:
    """Ask the authenticated installed front to prove CURRENT Claude state.

    The installed front owns receipt/signature/live-roster validation.  The
    driver supplies no state or path hints and accepts only its canonical
    success response, preventing a stale projected checkout from self-attesting
    or recursively launching another driver.
    """

    front = _direct_driver_installed_front_path()
    command = [
        sys.executable,
        "-I",
        "-B",
        os.fspath(front),
        _CLAUDE_PROJECTION_CURRENT_ASSERT_ARG,
    ]
    # A normally managed driver may itself hold a one-use borrowed-reader
    # capability from the parent front.  Those numeric handles are neither
    # valid nor delegable in this assertion child (`nested_child_authority` is
    # false).  Remove only that exhausted capability envelope so the installed
    # front opens its own authenticated read lease; all ordinary user/runtime
    # environment remains intact.
    assertion_environment = {
        key: value
        for key, value in os.environ.items()
        if key not in _PLAMEN_BORROWED_READER_ENV
    }
    try:
        completed = subprocess.run(
            command,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=max(1, int(timeout_s)),
            check=False,
            env=assertion_environment,
        )
    except (OSError, subprocess.SubprocessError, ValueError) as exc:
        raise DirectDriverProjectionAdmissionError(
            "installed Claude projection CURRENT assertion could not execute: "
            f"{type(exc).__name__}"
        ) from exc
    if (
        completed.returncode != 0
        or completed.stdout != _CLAUDE_PROJECTION_CURRENT_ASSERT_STDOUT
    ):
        raise DirectDriverProjectionAdmissionError(
            "installed Claude projection is not authenticated CURRENT state "
            f"(assertion exit={completed.returncode})"
        )


def _admit_direct_driver_projection(config: Mapping[str, Any]) -> None:
    """Fail closed for Claude-capable direct launches; bypass Codex-only runs."""

    global _DIRECT_CLAUDE_MCP_SELECTION
    if not _configured_audit_uses_claude(config):
        _DIRECT_CLAUDE_MCP_SELECTION = None
        return
    _assert_direct_claude_projection_current()
    _DIRECT_CLAUDE_MCP_SELECTION = _assert_claude_mcp_selection_current()


def _codex_auth_is_chatgpt() -> bool:
    """Return True if Codex is authenticated via ChatGPT OAuth (not API key).

    ChatGPT-auth accounts cannot use `--model` flag — the server rejects ALL
    explicit model names with "not supported when using Codex with a ChatGPT
    account". The account's subscription tier determines the default model
    automatically (Pro → GPT-5, Plus → GPT-4.1, etc).
    """
    if os.environ.get("CODEX_API_KEY") or os.environ.get("OPENAI_API_KEY"):
        return False
    auth_path = Path.home() / ".codex" / "auth.json"
    if not auth_path.exists():
        return False
    try:
        data = json.loads(auth_path.read_text(encoding="utf-8"))
        return data.get("auth_mode") == "chatgpt"
    except Exception:
        return False


def _codex_robustness_overrides() -> list[str]:
    """Inline `-c` config overrides applied to every `codex exec` invocation.

    Both codex command builders pass `--ignore-user-config` (so config.toml is
    NOT read live); these research-backed settings must therefore be inline:

    - `model_auto_compact_token_limit=220000` — force early history compaction
      instead of the bogus "context window exceeded (~N tokens)" PERMANENT
      failure caused by the token-counter corruption bug (openai/codex #16068,
      #19409). NEVER set `model_context_window` (the trigger for that bug).
    - `service_tier="flex"` — a built-in tier value so `spawn_agent` can resolve
      the child model. Without a valid tier, sub-agent spawning fails with
      "could not resolve the child model for service tier validation" (#27297),
      which degrades the fan-out-heavy recon phase. Only `flex`/`fast` are valid
      on older parsers; `default`/`priority` are rejected.

    Uses the same proven `-c key=value` form already used for
    `model_reasoning_effort`. If a future codex version rejects either key it
    surfaces as a config error; the context-exceeded handler now degrades the
    phase and continues rather than perma-failing the run.
    """
    return [
        "-c", "model_auto_compact_token_limit=220000",
        "-c", 'service_tier="flex"',
    ]


def _build_codex_cmd(effective_model: str, *, needs_mcp: bool = False,
                     output_last_message: str = "",
                     writable_dirs: list[str] | None = None,
                     live_search: bool = False) -> list[str]:
    """Build the codex exec command array for a phase subprocess.

    Uses --dangerously-bypass-approvals-and-sandbox to skip Codex's built-in
    approval prompts and sandbox restrictions. Without this flag, `codex exec`
    auto-rejects all tool calls (apply_patch, shell) with "rejected by user
    approval settings" — making zero artifact writes possible. This is
    Codex's equivalent of Claude Code's --dangerously-skip-permissions.

    The Plamen driver already controls the subprocess lifecycle, timeout, and
    output validation — the external orchestration IS the sandbox.

    --skip-git-repo-check: audit targets may not be git repos (extracted archives).
    --output-last-message: writes final agent message to a file for reliable extraction.
    --add-dir: retained for documentation; harmless with bypass active.

    ChatGPT-auth accounts cannot use --model flag at all — the server rejects
    every explicit model name with "not supported when using Codex with a
    ChatGPT account". The subscription tier (Free/Plus/Pro) determines the
    default model automatically. Only API-key auth supports --model.
    """
    # `--search` is a global Codex flag and must precede the `exec`
    # subcommand. It is enabled only for the receipt-gated R-EXT leaf.
    cmd = [CODEX_BIN]
    if live_search:
        cmd.append("--search")
    cmd.append("exec")
    # ChatGPT-auth accounts may reject --model depending on plan/token state.
    # Always try with --model first; the caller retries without it on failure
    # (see _detect_codex_model_rejection).
    cmd.extend(["--model", effective_model])
    cmd.extend([
        "--json",
        "--ephemeral",
        "--dangerously-bypass-approvals-and-sandbox",
        "--skip-git-repo-check",
        "--ignore-user-config",
        "--ignore-rules",
    ])
    cmd.extend(_codex_robustness_overrides())
    if writable_dirs:
        for d in writable_dirs:
            cmd.extend(["--add-dir", d])
    if output_last_message:
        cmd.extend(["--output-last-message", output_last_message])
    if effective_model in ("o3", "o4-mini"):
        cmd.extend(["-c", 'model_reasoning_effort="high"'])
    cmd.append("-")  # read prompt from stdin
    return cmd


def _detect_codex_model_rejection(log_path: Path) -> bool:
    """Detect if Codex rejected the --model flag (ChatGPT account restriction).

    ChatGPT-auth accounts may reject explicit --model depending on plan state
    or token freshness. When detected, the driver retries without --model,
    letting the subscription tier determine the default model automatically.
    """
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return "not supported when using Codex with a ChatGPT account" in text


def _detect_codex_model_not_available(log_path: Path) -> bool:
    """Detect if Codex failed because the requested model isn't on the user's plan.

    API-key accounts that lack access to a specific model (e.g., gpt-5.6-sol
    requires a higher-tier plan) get a 404 "model not found" or 403 "access
    denied" that is distinct from a credential failure. This must be checked
    BEFORE _detect_codex_auth_error, which would otherwise misclassify it as
    a permanent auth failure instead of a recoverable model-downgrade scenario.
    """
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    signal = re.compile(
        r"(?:model.*(?:not\s+found|does\s+not\s+exist|not\s+available)"
        r"|(?:not\s+found|does\s+not\s+exist).*model"
        r"|access.*denied.*model|model.*access.*denied"
        r"|you\s+do\s+not\s+have\s+access.*model"
        r"|insufficient.*(?:plan|tier|quota).*model"
        r"|status[=:\s]+404.*model|model.*status[=:\s]+404"
        r"|The\s+model\s+`[^`]+`\s+does\s+not\s+exist)",
        re.IGNORECASE,
    )

    # ``codex exec --json`` interleaves provider events with arbitrary model
    # messages and command stdout.  Audited source or an analysis artifact can
    # legitimately contain phrases such as "model not available"; those bytes
    # are data, not provider-routing authority.  Accept only typed provider
    # error events, plus narrowly scoped pre-JSON CLI diagnostics.
    provider_errors: list[str] = []
    raw_errors: list[str] = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("# _stdio_"):
            continue
        try:
            event = json.loads(line)
        except (json.JSONDecodeError, TypeError, ValueError):
            raw_errors.append(line)
            continue
        if not isinstance(event, Mapping):
            continue
        event_type = str(event.get("type") or "").strip().lower()
        if event_type == "error":
            provider_errors.append(
                str(event.get("message") or event.get("error") or "")
            )
            continue
        item = event.get("item")
        if (
            event_type in {"item.completed", "item.failed"}
            and isinstance(item, Mapping)
            and str(item.get("type") or "").strip().lower() == "error"
        ):
            provider_errors.append(
                str(item.get("message") or item.get("error") or "")
            )
            continue
        # Some early Codex failures are emitted as a bare JSON error object
        # without the normal event envelope.
        nested = event.get("error")
        if isinstance(nested, Mapping):
            provider_errors.append(
                " ".join(
                    str(nested.get(key) or "")
                    for key in ("message", "code", "status")
                )
            )
        elif isinstance(nested, str) and nested:
            provider_errors.append(nested)

    if signal.search("\n".join(provider_errors)):
        return True
    raw_signal = re.compile(
        r"^(?:error:\s*)?(?:The\s+model\s+`[^`]+`\s+does\s+not\s+exist"
        r"|model[^\r\n]{0,120}(?:not\s+found|does\s+not\s+exist|not\s+available)"
        r"|access\s+denied[^\r\n]{0,120}model"
        r"|(?:codex|openai|provider|api)\s+error[^\r\n]{0,160}model)",
        re.IGNORECASE,
    )
    return any(raw_signal.search(line) for line in raw_errors)


def _detect_codex_model_capacity(log_path: Path) -> bool:
    """Detect transient Codex/OpenAI selected-model capacity failures."""
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return bool(re.search(
        r"(?:selected\s+model\s+is\s+at\s+capacity|model\s+is\s+at\s+capacity)",
        text,
        re.IGNORECASE,
    ))


def _codex_next_fallback_model(current_model: str, attempted: list[str] | None = None) -> Optional[str]:
    """Return the next configured Codex fallback model after a capacity miss."""
    attempted_set = {m for m in (attempted or []) if m}
    attempted_set.add(current_model)
    for candidate in _CODEX_FALLBACK_MODEL_ORDER:
        if candidate and candidate not in attempted_set:
            return candidate
    return None


def _model_fallback_authorized(config: dict) -> bool:
    """True only after an explicit per-run model-routing authorization."""
    return config.get("allow_model_fallback") is True


def _build_codex_cmd_no_model(*, needs_mcp: bool = False,
                              output_last_message: str = "",
                              writable_dirs: list[str] | None = None,
                              live_search: bool = False) -> list[str]:
    """Build codex exec command WITHOUT --model flag (ChatGPT-auth fallback).

    Uses --dangerously-bypass-approvals-and-sandbox for same reason as
    _build_codex_cmd — without it, all tool calls are auto-rejected.
    """
    cmd = [CODEX_BIN]
    if live_search:
        cmd.append("--search")
    cmd.extend([
        "exec",
        "--json",
        "--ephemeral",
        "--dangerously-bypass-approvals-and-sandbox",
        "--skip-git-repo-check",
        "--ignore-user-config",
        "--ignore-rules",
    ])
    cmd.extend(_codex_robustness_overrides())
    if writable_dirs:
        for d in writable_dirs:
            cmd.extend(["--add-dir", d])
    if output_last_message:
        cmd.extend(["--output-last-message", output_last_message])
    cmd.append("-")
    return cmd


def _detect_codex_cli_crash(log_path: Path) -> bool:
    """Detect if Codex subprocess crashed due to invalid CLI arguments.

    CLI argument errors (e.g., --disallowedTools not recognized) are permanent
    failures — retrying with identical args is pointless. The driver should
    surface the error instead of burning retry budget.
    """
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return bool(re.search(
        r"(?:unexpected argument|unrecognized option|Usage: codex exec"
        r"|error:.*found\b.*tip:)",
        text, re.IGNORECASE,
    ))


def _detect_codex_auth_error(log_path: Path) -> bool:
    """Check if a Codex subprocess failed due to authentication issues.

    Auth errors (401/403, token expiry) should NOT trigger rate-limit pause
    logic — they need re-authentication, not backoff.

    IMPORTANT: Call _detect_codex_model_not_available BEFORE this function.
    Model-not-available (404/403 for missing model access) would otherwise
    match the 401/403 patterns here and cause a permanent halt instead of
    a graceful model downgrade.
    """
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    # Exclude model/capacity/rate-limit patterns from auth classification.
    if _detect_codex_model_not_available(log_path) or _CODEX_RATE_LIMIT_RE.search(text):
        return False

    # `codex exec --json` writes command executions into the same JSONL stream
    # as provider failures.  Those command rows can contain arbitrary audited
    # source (for example Solidity `error Unauthorized();`) and must never be
    # treated as transport evidence.  Inspect only top-level/provider error
    # events.  A small raw-line fallback remains for CLI failures emitted before
    # JSON event streaming starts.
    provider_errors: list[str] = []
    raw_errors: list[str] = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("# _stdio_"):
            continue
        try:
            event = json.loads(line)
        except (json.JSONDecodeError, TypeError, ValueError):
            raw_errors.append(line)
            continue
        if not isinstance(event, Mapping):
            continue
        event_type = str(event.get("type") or "").strip().lower()
        if event_type == "error":
            provider_errors.append(str(event.get("message") or event.get("error") or ""))
            continue
        item = event.get("item")
        if (
            event_type in {"item.completed", "item.failed"}
            and isinstance(item, Mapping)
            and str(item.get("type") or "").strip().lower() == "error"
        ):
            provider_errors.append(
                str(item.get("message") or item.get("error") or "")
            )

    structured = "\n".join(provider_errors)
    auth_signal = re.compile(
        r"(?:status[=:\s]+401|HTTP\s+401|\b401\b[^\r\n]{0,80}"
        r"(?:unauthorized|invalid[_ -]?api[_ -]?key|authentication)"
        r"|unauthorized|invalid[_ -]?api[_ -]?key"
        r"|token[^\r\n]{0,40}expired"
        r"|authentication[^\r\n]{0,40}(?:failed|error))",
        re.IGNORECASE,
    )
    if auth_signal.search(structured):
        return True
    raw_signal = re.compile(
        r"^(?:error:\s*)?(?:HTTP\s+401|status[=:\s]+401|"
        r"(?:codex|openai|provider|api)\s+error[^\r\n]{0,160}"
        r"(?:unauthorized|invalid[_ -]?api[_ -]?key|"
        r"token[^\r\n]{0,40}expired|authentication[^\r\n]{0,40}failed))",
        re.IGNORECASE,
    )
    return any(raw_signal.search(line) for line in raw_errors)


def _detect_codex_rate_limit(log_path: Path, returncode: int) -> bool:
    """Check if a Codex subprocess failed due to rate limiting.

    Checks JSONL output regardless of returncode because Codex may report
    usage_limit_reached in the event stream with rc=0 (graceful stop).

    Returns False for auth errors (401) — those need re-auth, not backoff.
    """
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    # Auth errors are NOT rate limits — discriminate early
    if _detect_codex_auth_error(log_path):
        return False
    if returncode == 0:
        # On success, only check for plan-cap exhaustion (not transient 429s).
        # Codex can graceful-stop (rc=0) with the usage cap in-stream, and that
        # message is NATURAL LANGUAGE — so match the plan-cap phrases too, not
        # just the structured tokens.
        return bool(re.search(
            r"usage_limit_reached|billing_hard_limit_reached|insufficient_quota"
            r"|purchase\s+more\s+credits"
            r"|chatgpt\.com/codex/settings/usage"
            r"|(?:reached|hit)\s+your\s+(?:usage|rate|monthly)\s+limit",
            text, re.IGNORECASE))
    return bool(_CODEX_RATE_LIMIT_RE.search(text))


def _detect_codex_context_exceeded(log_path: Path) -> bool:
    """Check if a Codex subprocess failed because prompt exceeded context window.

    Codex hard-errors (not truncates) when input exceeds the model's context.
    This needs different handling than rate limits: shrink prompt or use bigger model.
    """
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return bool(re.search(
        r"exceeds.*context.window|context_length_exceeded|max_tokens_exceeded"
        r"|maximum context length",
        text, re.IGNORECASE,
    ))


def _detect_codex_content_filter(log_path: Path) -> bool:
    """Detect if a Codex subprocess was killed by OpenAI's content safety filter.

    The safety filter flags security audit prompts as "cybersecurity risk" and
    terminates the turn before any subagent work can proceed.  The error is
    nondeterministic — a retry with a slightly different prompt shape (e.g. the
    retry hint prepended) often passes.  Treated as transient: the driver gets
    one bonus retry that does NOT consume the normal retry budget.
    """
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return bool(re.search(
        r"flagged for (?:possible )?cybersecurity risk"
        r"|Trusted Access for Cyber",
        text, re.IGNORECASE,
    ))


def _codex_secondary_artifact_targets(
    phase: "Phase", scratchpad: Path, config: Optional[dict] = None
) -> list[str]:
    """Return the phase's mandatory first-pass SECONDARY artifact filenames.

    `phase.expected_artifacts` only declares the glob of CORE outputs (e.g.
    `depth_*_findings.md` → the 4/5 core depth findings). The never-cut gate
    additionally requires the blind-spot scanners, validation sweep, and
    triggered niche outputs (and recon's worker shards). Driver-owned
    confidence artifacts are deliberately excluded: the model returns only a
    transient routing proposal and the driver publishes the canonical files
    after the worker wave. Codex's apply_patch cannot create new files, so
    model-owned secondary outputs must be pre-seeded or the never-cut gate
    degrades the phase.

    This derives the secondary filenames from EXISTING single-sources-of-truth
    (`sc_never_cut_groups` / `l1_never_cut_groups`, `_required_niche_worker_jobs`,
    `_recon_worker_jobs`) rather than a hardcoded parallel list. For never-cut
    `[A|B]` alternations only the FIRST representative is seeded (one valid
    target is enough; the gate accepts either). Only TRIGGERED niches (from the
    manifest) are seeded, never all possible.
    """
    cfg = config or {}
    mode = str(cfg.get("mode") or "core").lower()
    pipeline = str(cfg.get("pipeline") or "sc").lower()
    targets: list[str] = []

    if phase.name == "depth":
        try:
            groups = (
                l1_never_cut_groups(mode)
                if pipeline == "l1"
                else sc_never_cut_groups(mode)
            )
        except Exception:
            groups = []
        for group in groups:
            # `group` is a list of alternations ([A|B]); seed ONE representative.
            if group:
                targets.append(group[0])
        # Triggered niche outputs from the instantiate manifest (manifest-driven,
        # only required/triggered rows return).
        try:
            for job in _required_niche_worker_jobs(scratchpad):
                out = job.get("output")
                if out:
                    targets.append(out)
        except Exception:
            pass
    elif phase.name == "recon":
        try:
            for job in _recon_worker_jobs(cfg):
                out = job.get("output")
                if out:
                    targets.append(out)
        except Exception:
            pass

    # De-dupe while preserving order; drop any that overlap a core glob target
    # already covered by expected_artifacts handling (those are seeded anyway).
    seen: set = set()
    deduped: list[str] = []
    driver_owned_confidence = {
        "confidence_scores.md",
        "confidence_consensus_authority.json",
        "consensus_map.md",
    }
    for name in targets:
        if (
            name
            and name not in driver_owned_confidence
            and name not in seen
        ):
            seen.add(name)
            deduped.append(name)
    return deduped


def _precreate_codex_artifacts(
    phase: "Phase", scratchpad: Path, config: Optional[dict] = None
) -> None:
    """Seed empty files for expected artifacts so apply_patch has targets.

    Codex's apply_patch tool cannot create new files — it only modifies
    existing ones. By pre-creating each expected artifact as an empty file,
    the model can use apply_patch to write content into them. Files that
    already have content (from a prior attempt or phase) are left untouched.
    Glob patterns with wildcards are expanded to a single representative
    filename using the phase's example_tokens if available.

    In addition to `phase.expected_artifacts` (the CORE outputs), this also
    seeds the phase's mandatory first-pass SECONDARY artifacts — the never-cut
    model-owned scanner/validation files, triggered niche outputs, and recon
    worker shards — so Codex can fill the full first-pass set rather than only
    the core glob. Driver-owned confidence artifacts are never seeded for the
    model. Secondary names are derived from existing sources (see
    `_codex_secondary_artifact_targets`); seeding is additive and an unfilled
    empty seed still fails the stub/never-cut gate (no false-pass).
    """
    def _seed(concrete: str) -> None:
        target = scratchpad / concrete
        if not target.exists():
            try:
                target.write_text("", encoding="utf-8")
            except OSError:
                pass

    for pattern in phase.expected_artifacts:
        if "*" in pattern or "?" in pattern:
            if phase.example_tokens:
                for token in phase.example_tokens:
                    _seed(pattern.replace("*", token, 1))
        else:
            _seed(pattern)

    for name in _codex_secondary_artifact_targets(phase, scratchpad, config):
        _seed(name)


def _update_depth_alias_markers(path: Path, expected_name: str) -> None:
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return
    new = re.sub(
        r"<!--\s*PLAMEN_ARTIFACT:\s*[^>]+-->",
        f"<!-- PLAMEN_ARTIFACT: {expected_name} -->",
        text,
        count=1,
    )
    new = re.sub(
        r"<!--\s*EXPECTED_OUTPUT:\s*[^>]+-->",
        f"<!-- EXPECTED_OUTPUT: {expected_name} -->",
        new,
        count=1,
    )
    if new != text:
        try:
            path.write_text(new, encoding="utf-8")
        except OSError:
            pass


def _canonicalize_depth_iter_filenames(scratchpad: Path) -> list[str]:
    """Rename non-canonical iter2/iter3 outputs to the canonical _findings.md form.

    The driver's depth manifest instructs the LLM to write
    `depth_iter2_*_findings.md` (and `depth_iter3_*_findings.md`), but the
    orchestrator routinely drops the `_findings` segment and emits
    `depth_iter2_state_trace.md`, `depth_iter3_targeted.md`, etc. Multiple
    downstream consumers (inventory parsers, validators, never-cut gate)
    glob for the strict suffix and miss these files, causing false-fail
    retries that re-spend the entire opus depth phase.

    Same class as v2.3.4's `depth_perturbation_findings.md` →
    `perturbation_findings.md` canonicalization. Idempotent and safe to
    re-run — if the canonical name already exists we skip to avoid
    clobbering.

    Returns the list of (source, target) pairs renamed for logging.
    """
    renamed: list[str] = []

    # Devil's-Advocate coordinators often write `da_iter2_*` / `da_iter3_*`
    # without the depth prefix. Canonicalize those first so the downstream
    # `depth_*_findings.md` gate sees them before spending a full retry.
    da_token_re = re.compile(r"^da[_-]?iter(?:ation)?[_-]?([23])[_-]?(.*)$", re.IGNORECASE)
    for src in sorted(scratchpad.glob("da_iter*.md")) + sorted(scratchpad.glob("da-iter*.md")):
        m = da_token_re.match(src.stem)
        if not m:
            continue
        n = m.group(1)
        role = re.sub(r"_?findings$", "", m.group(2), flags=re.IGNORECASE)
        role = re.sub(r"[_\-]+", "_", role).strip("_-")
        if role:
            target_name = f"depth_da_iter{n}_{role}_findings.md"
        else:
            target_name = f"depth_da_iter{n}_findings.md"
        target = src.with_name(target_name)
        if target.exists():
            continue
        try:
            src.rename(target)
            _update_depth_alias_markers(target, target_name)
            renamed.append(f"{src.name} -> {target.name}")
        except OSError:
            pass

    # The orchestrator is reliably TRYING to write depth iteration-2/3
    # findings, but the token order and spelling drift. Observed and
    # plausible variants — all semantically "depth iteration N findings
    # for <role>":
    #   depth_iter2_state_trace.md                (canonical prefix, no _findings)
    #   depth_iter2_state_trace_findings.md       (fully canonical — skip)
    #   depth_state_trace_iteration2_findings.md  (role-first, spelled out)
    #   depth_iteration2_state_trace_findings.md  (prefix, spelled out)
    #   depth_state_trace_iter2.md                (role-first, abbreviated)
    #   depth_state_trace_iter_2_findings.md      (underscore before digit)
    # ...with `iter` or `iteration`, an optional `_`/`-` before the digit,
    # and the role segment in either position. Canonical target for ALL:
    #   depth_iter{N}_{role}_findings.md
    #
    # Rather than enumerate variants (a losing game — the LLM keeps finding
    # new orderings), DECOMPOSE each `depth_*.md` filename: locate the
    # iteration token, lift N, treat everything else as the role, rebuild
    # canonically. A false "no iter2 artifacts" retry re-spends the whole
    # opus depth phase (~$4 observed on a prior audit) — same class as
    # v2.3.4's perturbation_findings canonicalization.
    #
    # `depth_da_*` / `depth_da3_*` are a SEPARATE recognized Devil's-Advocate
    # iteration form and must be left untouched.
    iter_token_re = re.compile(r"iter(?:ation)?[_-]?([23])", re.IGNORECASE)
    for src in sorted(scratchpad.glob("depth_*.md")):
        if src.name.lower().startswith(("depth_da_", "depth_da3_")):
            continue  # recognized DA form — not an iter-prefixed file
        stem = src.stem
        if not stem.startswith("depth_"):
            continue
        body = stem[len("depth_"):]
        m = iter_token_re.search(body)
        if not m:
            continue  # no iteration token → iter1 base file or non-iter file
        n = m.group(1)
        # Role = everything except the iteration token and the _findings
        # suffix, with separators collapsed.
        role = body[:m.start()] + body[m.end():]
        role = re.sub(r"_?findings", "", role, flags=re.IGNORECASE)
        role = re.sub(r"[_\-]+", "_", role).strip("_-")
        if not role:
            continue  # can't canonicalize without a role segment
        target_name = f"depth_iter{n}_{role}_findings.md"
        if src.name == target_name:
            continue  # already canonical
        target = src.with_name(target_name)
        if target.exists():
            continue  # don't clobber existing canonical
        try:
            src.rename(target)
            _update_depth_alias_markers(target, target_name)
            renamed.append(f"{src.name} -> {target.name}")
        except OSError:
            # Best-effort: any FS error and we leave the file alone.
            # The iter2 gate's tolerant glob is the defense-in-depth path.
            pass
    return renamed


# S1.3 — mechanical confidence scoring (driver-owned). Evidence-source tag
# scores per ~/.plamen/rules/phase4-confidence-scoring.md, extended with the
# PoC/proof tags depth findings actually carry.
_EVIDENCE_TAG_SCORE = {
    "[PROD-ONCHAIN]": 1.0, "[MEDUSA-PASS]": 1.0, "[POC-PASS]": 1.0,
    "[PROD-SOURCE]": 0.9, "[PROD-FORK]": 0.9, "[FUZZ-PASS]": 0.9,
    "[NON-DET-PASS]": 0.9, "[CONFORMANCE-PASS]": 0.9, "[DIFF-PASS]": 0.9,
    "[CODE]": 0.8, "[CODE-TRACE]": 0.8, "[LSP-TRACE]": 0.7,
    "[DOC]": 0.4, "[MOCK]": 0.2, "[POC-FAIL]": 0.15, "[EXT-UNV]": 0.1,
}
# Ship A (fixes SW07-4): single source of truth in plamen_types. The former
# local copy dropped NON-DET/ASYMMETRIC/MEDUSA-PASS/etc., so L1 + network depth
# findings scored lower than identical SC findings in the confidence ranking.
_DEPTH_EVIDENCE_TAG_RE = DEPTH_EVIDENCE_TAG_RE
# F2.0: permissive bracket-content capture. The old `[A-Z]{1,8}-\d+[A-Z\d-]*`
# rejected blind-spot IDs of shape `BLIND-A-1` (the `\d+` immediately after
# the first hyphen rejects the `A-` letter segment) — in a prior run this matched
# 0/14 blind-spot findings, silently under-scoring real findings in
# confidence. The `## Finding [...]` syntax is itself the source-of-truth
# contract: whatever the agent put in the brackets is the ID.
# Ship D (fixes SW07-3/5): single source of truth in plamen_types. The former
# local copy was H2-ONLY, so the confidence synthesizer saw ZERO findings on
# the prompt-mandated H3 `### Finding [ID]` depth blocks and wrote a
# "(no findings produced)" placeholder confidence_scores.md.
_FINDING_HEADING_RE = FINDING_BLOCK_HEADING_RE


def _iter_finding_blocks(text: str):
    """Yield (finding_id, block_text) for each `## Finding [ID]` section.

    F2.0: id is the raw bracket content; callers dedupe on the normalized
    form (with raw-uppercase fallback for new/unrecognized prefixes) to
    avoid raw-vs-normalized double-counting.
    """
    matches = list(_FINDING_HEADING_RE.finditer(text))
    for i, m in enumerate(matches):
        start = m.start()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
        yield m.group(1).strip(), text[start:end]


def _compute_depth_confidence(
    scratchpad: Path,
    mode: str,
    *,
    consensus_authority: Mapping[str, Any] | None = None,
) -> int:
    """S1.3: write a real, per-finding confidence_scores.md (driver-owned).

    Evidence and analysis quality are derived mechanically from each finding.
    In Thorough mode, Consensus comes only from the typed independent-
    corroboration authority: a single observer, location collision, assigned
    skill, or stale/unbound worker never earns an agreement bonus. Historical
    precedent is context only and contributes no numeric score. Core uses its
    documented two-axis formula; Thorough uses three code-evidence axes. The
    Header-driven downstream parsers consume the composite directly; no
    placeholder precedent column is emitted.
    Returns the finding-row count.
    """
    mode_key = str(mode or "core").strip().lower()
    formula_mode = (
        "THOROUGH_3_AXIS" if mode_key == "thorough" else "CORE_2_AXIS"
    )
    try:
        consensus_authority = (
            dict(consensus_authority)
            if isinstance(consensus_authority, Mapping)
            else write_confidence_consensus_artifacts(scratchpad)
        )
        consensus_by_identity = _confidence_consensus_score_map(
            consensus_authority
        )
    except Exception as exc:
        # Confidence is routing telemetry, never verdict authority. A broken
        # corroboration substrate degrades to no agreement bonus, keeping the
        # finding eligible for more analysis rather than falsely closing it.
        consensus_by_identity = {}
        try:
            _append_phase_io_debt(
                scratchpad,
                "depth",
                "CONFIDENCE_CONSENSUS_AUTHORITY_DEBT",
                str(exc),
            )
        except Exception:
            pass
    finding_files = sorted(
        list(scratchpad.glob("depth_*_findings.md"))
        + list(scratchpad.glob("blind_spot_*_findings.md"))
        + list(scratchpad.glob("niche_*_findings.md"))
        + list(scratchpad.glob("validation_sweep_findings.md"))
        + list(scratchpad.glob("scanner_*_findings.md"))
        + list(scratchpad.glob("design_stress_findings.md"))
        + list(scratchpad.glob("perturbation_findings.md"))
    )
    seen: set[str] = set()
    rows: list[str] = []
    for fpath in finding_files:
        try:
            text = fpath.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        for raw_id, block in _iter_finding_blocks(text):
            # F2.0: dedupe on the NORMALIZED form (with raw-uppercase
            # fallback for new/unrecognized prefixes) so the same finding
            # surfacing in two formats does not produce two rows.
            norm_id = _normalize_finding_id(raw_id)
            key = norm_id or raw_id.upper()
            if key in seen:
                continue
            seen.add(key)
            display_id = norm_id or raw_id
            tag_scores = [s for t, s in _EVIDENCE_TAG_SCORE.items() if t in block]
            evidence = max(tag_scores) if tag_scores else 0.5
            dtags = len(_DEPTH_EVIDENCE_TAG_RE.findall(block))
            quality = (
                1.0 if dtags >= 3 else
                0.7 if dtags == 2 else
                0.4 if dtags == 1 else 0.1
            )
            consensus = float(
                consensus_by_identity.get(
                    (fpath.name, display_id.upper()), 0.0
                )
            )
            if mode_key == "thorough":
                composite = round(
                    evidence * 0.25 + consensus * 0.25
                    + quality * 0.3,
                    2,
                )
            else:
                composite = round(evidence * 0.5 + quality * 0.5, 2)
            classification = (
                "CONFIDENT" if composite >= 0.7 else
                "UNCERTAIN" if composite >= 0.4 else "LOW_CONFIDENCE"
            )
            rows.append(
                f"| {display_id} | {evidence:.2f} | {consensus:.2f} | {quality:.2f} "
                f"| {composite:.2f} | {classification} "
                f"| {fpath.name} |"
            )
    lines = [
        "# Confidence Scores (driver-computed)",
        "",
        "> **Status**: DRIVER-COMPUTED — per-finding mechanical scoring. "
        "Evidence/Quality derive from finding text; Consensus derives from "
        "typed independent-corroboration authority; historical precedent is "
        "context only and has no numeric scoring authority.",
        f"> Mode: {formula_mode}",
        "",
        "| Finding ID | Evidence | Consensus | Quality | Composite "
        "| Classification | Source |",
        "|------------|----------|-----------|---------|-----------"
        "|----------------|--------|",
    ]
    lines.extend(rows)
    if not rows:
        lines.append("| - | - | - | - | - | - | - | (no findings produced) |")
    try:
        (scratchpad / "confidence_scores.md").write_text(
            "\n".join(lines) + "\n", encoding="utf-8"
        )
    except OSError:
        pass
    return len(rows)


def _confidence_consensus_payload(scratchpad: Path) -> dict[str, Any]:
    path = Path(scratchpad) / "confidence_consensus_authority.json"
    payload = json.loads(path.read_text(encoding="utf-8", errors="strict"))
    if not isinstance(payload, dict):
        raise ValueError("confidence consensus authority root is not an object")
    return payload


def _confidence_consensus_input_paths(
    scratchpad: Path,
    payload: Mapping[str, Any],
) -> tuple[str, ...]:
    """Resolve and verify the exact source denominator named by P1-G."""

    rows = payload.get("input_bindings")
    if not isinstance(rows, list) or not rows:
        raise ValueError("confidence consensus input bindings are absent")
    paths: dict[str, str] = {}
    for raw in rows:
        if not isinstance(raw, Mapping):
            raise ValueError("confidence consensus input binding is not an object")
        relative = str(raw.get("path") or "").strip()
        digest = str(raw.get("sha256") or "").strip().lower()
        parsed = Path(relative)
        if (
            not relative
            or parsed.is_absolute()
            or ".." in parsed.parts
            or not re.fullmatch(r"[0-9a-f]{64}", digest)
            or relative in paths
        ):
            raise ValueError(
                "confidence consensus input binding identity is invalid"
            )
        source = Path(scratchpad) / parsed
        if not source.is_file():
            raise ValueError(
                f"confidence consensus PhaseIO input missing: {relative}"
            )
        observed = hashlib.sha256(source.read_bytes()).hexdigest()
        if observed != digest:
            raise ValueError(
                f"confidence consensus PhaseIO input drift: {relative}"
            )
        paths[relative] = digest
    return tuple(sorted(paths))


def _confidence_consensus_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    payload: Mapping[str, Any],
    timeout_s: int = 120,
) -> tuple[Any, LaunchSpec]:
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="depth",
        work_unit_id="confidence_consensus",
        exact_inputs=_confidence_consensus_input_paths(scratchpad, payload),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(timeout_s)),
        exec_mode="python",
        tool_policy=(),
    )
    return contract, launch


def _arm_deterministic_driver_work_unit(
    *,
    scratchpad: Path,
    project_root: Path,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    successor_plan: Any | None = None,
    preexecution_authority: Mapping[str, Any] | None = None,
) -> tuple[bool, list[str]]:
    """Arm one DRIVER producer before its first output-side effect.

    Returns ``(execute, issues)``.  A byte-current committed replay returns
    ``execute=False``.  Input-driven refresh first creates an explicit stale
    authorization; unowned/pre-existing output bytes remain INPUT_DEBT and are
    never overwritten or retroactively blessed.
    """

    root = Path(scratchpad)
    project = Path(project_root)
    prior_input_issues = validate_work_unit_inputs(
        root,
        project,
        contract,
        launch,
        run_id=run_id,
        preexecution_authority=preexecution_authority,
    )
    prior_output_issues = validate_work_unit_artifacts(
        root,
        project,
        contract,
        launch,
        run_id=run_id,
        actor="DRIVER",
        preexecution_authority=preexecution_authority,
    )
    if not prior_input_issues and not prior_output_issues:
        return False, []
    try:
        ledger = read_artifact_ledger(root)
        prior = ledger.get("work_units", {}).get(contract.key)
        if (
            isinstance(prior, Mapping)
            and prior.get("run_id") == run_id
            and prior.get("contract_digest") == contract.digest
            and prior.get("launch_digest") == launch.digest
            and prior.get("semantic_status") == "INPUTS_BOUND"
            and prior.get("execution_state") == "INPUTS_BOUND_PREEXECUTION"
            and prior.get("artifacts") == {}
        ):
            # Crash recovery resumes the exact pre-output denominator.  Never
            # re-record inputs after output bytes may already have been
            # materialized: doing so would observe those bytes as an unowned
            # predecessor and destroy the arm-before-write proof.
            if successor_plan is not None:
                record_work_unit_inputs(
                    root,
                    project,
                    contract,
                    launch,
                    run_id=run_id,
                    successor_plan=successor_plan,
                    preexecution_authority=preexecution_authority,
                )
                prior_input_issues = validate_work_unit_inputs(
                    root,
                    project,
                    contract,
                    launch,
                    run_id=run_id,
                    preexecution_authority=preexecution_authority,
                )
            elif preexecution_authority is not None:
                record_work_unit_inputs(
                    root,
                    project,
                    contract,
                    launch,
                    run_id=run_id,
                    preexecution_authority=preexecution_authority,
                )
                prior_input_issues = validate_work_unit_inputs(
                    root,
                    project,
                    contract,
                    launch,
                    run_id=run_id,
                    preexecution_authority=preexecution_authority,
                )
            return (not prior_input_issues), list(
                dict.fromkeys(prior_input_issues)
            )
        if (
            isinstance(prior, Mapping)
            and prior.get("semantic_status") == "ACTIVE"
            and prior.get("execution_state") == "OUTPUT_COMMITTED"
        ):
            authorize_deterministic_work_unit_reexecution(
                root,
                project,
                contract,
                launch,
                run_id=run_id,
            )
        unit = record_work_unit_inputs(
            root,
            project,
            contract,
            launch,
            run_id=run_id,
            successor_plan=successor_plan,
            preexecution_authority=preexecution_authority,
        )
    except ArtifactLedgerError as exc:
        return False, [f"{contract.key}: deterministic prebind failed: {exc}"]
    issues = validate_work_unit_inputs(
        root,
        project,
        contract,
        launch,
        run_id=run_id,
        preexecution_authority=preexecution_authority,
    )
    if (
        contract.phase in {"verify_queue", "sc_verify_queue"}
        and contract.work_unit_id == "routing"
    ):
        # Queue routing is a semantic successor boundary.  Generic PhaseIO
        # permits raw external preimages, but this work unit may consume only
        # current producer-owned inventory/successor authority.  Enforce that
        # rule in the shared prebind seam as well as the high-level driver so a
        # direct caller cannot launder hidden causal debt into clean outputs.
        try:
            current_ledger = read_artifact_ledger(root)
            current_unit = current_ledger.get("work_units", {}).get(
                contract.key
            )
            current_inputs = (
                current_unit.get("input_bindings")
                if isinstance(current_unit, Mapping)
                else None
            )
            if not isinstance(current_inputs, Mapping):
                issues.append(
                    f"{contract.key}: queue semantic input bindings are absent"
                )
            else:
                mandatory_queue_inputs = {
                    "scratchpad:findings_inventory.md",
                    "scratchpad:preverify_inventory_successor.json",
                    "scratchpad:finding_delivery_successor.json",
                }
                for identity in sorted(
                    mandatory_queue_inputs
                    & set(contract.immutable_inputs)
                ):
                    record = current_inputs.get(identity)
                    if not isinstance(record, Mapping):
                        issues.append(
                            f"{identity}: queue semantic input binding is absent"
                        )
                        continue
                    issues.extend(
                        semantic_input_producer_authority_issues(
                            current_ledger,
                            record,
                            run_id=run_id,
                        )
                    )
        except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
            issues.append(
                f"{contract.key}: queue semantic producer authority failed: "
                f"{type(exc).__name__}: {exc}"
            )
    execute = bool(
        not issues
        and unit.get("semantic_status") == "INPUTS_BOUND"
        and unit.get("execution_state") == "INPUTS_BOUND_PREEXECUTION"
        and unit.get("artifacts") == {}
    )
    return execute, list(dict.fromkeys(issues))


def _commit_deterministic_driver_work_unit(
    *,
    scratchpad: Path,
    project_root: Path,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    domain_issues: Sequence[str] = (),
    conditional_receipts: Mapping[str, ConditionalOutputReceipt] | None = None,
    merge_events: Mapping[str, Any] | None = None,
    expected_output_records: Mapping[
        str, Mapping[str, Any]
    ] | None = None,
    preexecution_authority: Mapping[str, Any] | None = None,
) -> list[str]:
    """Commit only a prebound deterministic execution and replay it."""

    issues = [
        str(value).strip()
        for value in domain_issues
        if str(value).strip()
    ]
    try:
        record_work_unit_artifacts(
            Path(scratchpad),
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
            precommit_issues=issues,
            conditional_receipts=dict(conditional_receipts or {}),
            merge_events=merge_events,
            expected_output_records=expected_output_records,
        )
        issues.extend(
            validate_work_unit_artifacts(
                Path(scratchpad),
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
                preexecution_authority=preexecution_authority,
            )
        )
    except ArtifactLedgerError as exc:
        issues.append(f"{contract.key}: deterministic commit failed: {exc}")
    return list(dict.fromkeys(issues))


def _write_and_record_confidence_consensus_phase_io(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> list[str]:
    """Prebind, derive, validate, and commit exact confidence authority."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["confidence consensus PhaseIO cannot bind without a run_id"]
    project_root = Path(str(config.get("project_root") or root.parent))
    try:
        payload = build_confidence_consensus_authority(root)
        contract, launch = _confidence_consensus_contract_and_launch(
            scratchpad=root,
            config=config,
            payload=payload,
            timeout_s=phase.base_timeout_s,
        )
        execute, phase_io_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if phase_io_issues or not execute:
            return phase_io_issues
        written = write_confidence_consensus_artifacts(root)
        _compute_depth_confidence(
            root,
            str(config.get("mode") or "core"),
            consensus_authority=written,
        )
        domain_issues = validate_confidence_consensus_artifacts(root)
        if written != payload:
            domain_issues.append(
                "confidence consensus derivation changed after prebind"
            )
        return _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=domain_issues,
        )
    except (
        ArtifactLedgerError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "confidence consensus PhaseIO reconciliation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _validate_confidence_consensus_phase_io(
    *,
    scratchpad: Path,
    project_root: Path,
    mode: str,
    language: str,
    pipeline: str,
    backend: str,
    timeout_s: int = 120,
) -> list[str]:
    """Side-effect-free P1-G current-source and ledger replay for resume."""

    root = Path(scratchpad)
    try:
        issues = validate_confidence_consensus_artifacts(root)
        if issues:
            return issues
        payload = _confidence_consensus_payload(root)
        config = {
            "pipeline": pipeline,
            "mode": mode,
            "language": language,
            "cli_backend": backend,
        }
        contract, launch = _confidence_consensus_contract_and_launch(
            scratchpad=root,
            config=config,
            payload=payload,
            timeout_s=timeout_s,
        )
        run_id = _report_disposition_run_id(root)
        issues = validate_work_unit_inputs(
            root, Path(project_root), contract, launch, run_id=run_id
        )
        issues.extend(
            validate_work_unit_artifacts(
                root,
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            )
        )
        return list(dict.fromkeys(issues))
    except (
        ArtifactLedgerError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "confidence consensus resume PhaseIO failure: "
            f"{type(exc).__name__}: {exc}"
        ]


def _inventory_reconciliation_output_names(
    phase_name: str,
) -> tuple[str, str]:
    if str(phase_name).startswith("inventory_chunk_"):
        return (
            f"{phase_name}.reconciliation.json",
            f"{phase_name}.human_review.md",
        )
    return (
        "inventory_reconciliation.json",
        "inventory_reconciliation_human_review.md",
    )


def _inventory_reconciliation_input_paths(
    scratchpad: Path,
    payload: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return the exact current P0-L source/manifest/evidence denominator."""

    root = Path(scratchpad)
    bindings: dict[str, str] = {}

    def add(relative: object, digest: object) -> None:
        value = str(relative or "").strip().replace("\\", "/")
        sha = str(digest or "").strip().lower()
        parsed = Path(value)
        if (
            not value
            or parsed.is_absolute()
            or ".." in parsed.parts
            or not re.fullmatch(r"[0-9a-f]{64}", sha)
        ):
            raise ValueError(
                "inventory reconciliation input binding identity is invalid"
            )
        prior = bindings.get(value)
        if prior is not None and prior != sha:
            raise ValueError(
                f"inventory reconciliation has conflicting digest: {value}"
            )
        path = root / parsed
        if not path.is_file():
            raise ValueError(
                f"inventory reconciliation PhaseIO input missing: {value}"
            )
        current = hashlib.sha256(path.read_bytes()).hexdigest()
        if current != sha:
            raise ValueError(
                f"inventory reconciliation PhaseIO input drift: {value}"
            )
        bindings[value] = sha

    for collection in (
        payload.get("source_artifacts"),
        payload.get("manifest_artifacts"),
        payload.get("observed_artifacts"),
    ):
        if not isinstance(collection, list):
            raise ValueError(
                "inventory reconciliation input collection is not a list"
            )
        for raw in collection:
            if not isinstance(raw, Mapping):
                raise ValueError(
                    "inventory reconciliation input row is not an object"
                )
            add(raw.get("artifact"), raw.get("sha256"))

    authority_name = str(payload.get("authority_artifact") or "").strip()
    authority_sha = str(payload.get("authority_sha256") or "").strip()
    if bool(authority_name) != bool(authority_sha):
        raise ValueError("inventory disposition authority binding is partial")
    if authority_name:
        add(authority_name, authority_sha)
        authority_path = root / authority_name
        authority = json.loads(
            authority_path.read_text(encoding="utf-8", errors="strict")
        )
        if not isinstance(authority, Mapping):
            raise ValueError("inventory disposition authority is not an object")
        for raw in authority.get("rows") or []:
            if not isinstance(raw, Mapping):
                raise ValueError(
                    "inventory disposition authority row is not an object"
                )
            evidence_name = str(raw.get("evidence_artifact") or "").strip()
            evidence_sha = str(raw.get("evidence_sha256") or "").strip()
            if bool(evidence_name) != bool(evidence_sha):
                # Merge authority intentionally has no negative-evidence file.
                if evidence_name or evidence_sha:
                    raise ValueError(
                        "inventory negative-evidence binding is partial"
                    )
                continue
            if evidence_name:
                add(evidence_name, evidence_sha)
    reemit_name = str(payload.get("reemit_authority_artifact") or "").strip()
    reemit_sha = str(payload.get("reemit_authority_sha256") or "").strip()
    if bool(reemit_name) != bool(reemit_sha):
        raise ValueError("inventory re-emission authority binding is partial")
    if reemit_name:
        add(reemit_name, reemit_sha)
        intent = root / "inventory_reemit_intent.json"
        if not intent.is_file():
            raise ValueError("inventory re-emission intent is missing")
        add(intent.name, hashlib.sha256(intent.read_bytes()).hexdigest())
    return tuple(sorted(bindings))


def _inventory_reconciliation_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase_name: str,
    payload: Mapping[str, Any],
    timeout_s: int,
) -> tuple[Any, LaunchSpec]:
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase=phase_name,
        work_unit_id="exact_reconciliation",
        exact_inputs=_inventory_reconciliation_input_paths(
            scratchpad, payload
        ),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _recover_quarantined_inventory_reemit_transaction(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
    unit: Mapping[str, Any] | None,
) -> list[str]:
    """Restore and re-arm the exact five-output additive successor.

    A rejected MERGE commit owns quarantined postimages, so the ordinary
    ACTIVE-producer precheck cannot repair it.  Re-derive the three canonical
    predecessor byte streams, restore the two originally absent sidecars, and
    let the generic successor recovery retain the sealed plan with an empty
    ordered-progress head.
    """

    if not (
        isinstance(unit, Mapping)
        and unit.get("run_id") == run_id
        and unit.get("semantic_status") == "QUARANTINED"
        and unit.get("execution_state") == "OUTPUT_QUARANTINED"
    ):
        return []
    root = Path(scratchpad)
    try:
        manifest = unit.get("contract_manifest")
        launch_manifest = unit.get("launch_manifest")
        if not isinstance(manifest, Mapping) or not isinstance(
            launch_manifest, Mapping
        ):
            raise ValueError(
                "quarantined inventory re-emission authority is malformed"
            )
        semantic_inputs = [
            *list(manifest.get("immutable_inputs") or []),
            *list(manifest.get("bounded_lookup_inputs") or []),
        ]
        if (
            any(
                not isinstance(identity, str)
                or not identity.startswith("scratchpad:")
                for identity in semantic_inputs
            )
            or len(semantic_inputs) != len(set(semantic_inputs))
        ):
            raise ValueError(
                "quarantined inventory re-emission input denominator "
                "is invalid"
            )
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="inventory",
            work_unit_id="additive_reemit",
            exact_inputs=tuple(
                identity.split(":", 1)[1]
                for identity in semantic_inputs
            ),
        )
        timeout_value = launch_manifest.get("timeout_s")
        if type(timeout_value) is not int or timeout_value < 1:
            raise ValueError(
                "quarantined inventory launch timeout_s must be a positive integer"
            )
        launch = LaunchSpec(
            work_unit_key=str(
                launch_manifest.get("work_unit_key") or ""
            ),
            pipeline=str(launch_manifest.get("pipeline") or ""),
            mode=str(launch_manifest.get("mode") or ""),
            ecosystem=str(launch_manifest.get("ecosystem") or ""),
            backend=str(launch_manifest.get("backend") or ""),
            model=str(launch_manifest.get("model") or ""),
            timeout_s=timeout_value,
            exec_mode=str(launch_manifest.get("exec_mode") or ""),
            tool_policy=tuple(
                launch_manifest.get("tool_policy") or ()
            ),
            launch_version=str(
                launch_manifest.get("launch_version") or ""
            ),
        )
        if (
            contract.digest != unit.get("contract_digest")
            or contract.to_dict() != dict(manifest)
            or launch.digest != unit.get("launch_digest")
            or launch.to_dict() != dict(launch_manifest)
        ):
            raise ValueError(
                "quarantined inventory re-emission contract/launch "
                "does not replay"
            )
        canonical_outputs = planned_inventory_output_bytes(
            _load_inventory_aggregate_plan(root)
        )
        delta = decode_inventory_allocation_delta(
            (root / "inventory_id_allocation_delta.json").read_bytes()
        )
        id_merge_receipt = decode_inventory_id_ledger_merge_receipt(
            (
                root
                / "inventory_id_ledger_merge_receipt.json"
            ).read_bytes(),
            delta=delta,
        )
        restored_bytes = {
            "scratchpad:findings_inventory.md": canonical_outputs[
                "findings_inventory.md"
            ],
            "scratchpad:finding_records.json": canonical_outputs[
                "finding_records.json"
            ],
            "scratchpad:_id_ledger.json": str(
                id_merge_receipt.get("successor_payload") or ""
            ).encode("utf-8"),
        }
        prestates = unit.get("output_prestates")
        bindings = read_artifact_ledger(root).get(
            "artifact_bindings", {}
        )
        if (
            not isinstance(prestates, Mapping)
            or set(prestates)
            != {spec.identity for spec in contract.outputs}
        ):
            raise ValueError(
                "quarantined inventory re-emission prestates are invalid"
            )
        for spec in contract.outputs:
            identity = spec.identity
            prestate = prestates.get(identity)
            binding = (
                bindings.get(identity)
                if isinstance(bindings, Mapping)
                else None
            )
            if not isinstance(prestate, Mapping):
                raise ValueError(
                    f"{identity}: quarantined recovery ownership differs"
                )
            path = root / spec.path
            status = str(prestate.get("status") or "")
            if status == "ABSENT":
                if isinstance(binding, Mapping) and not (
                    binding.get("owner_key") == contract.key
                    and binding.get("status")
                    in {"MISSING", "QUARANTINED"}
                ):
                    raise ValueError(
                        f"{identity}: quarantined absent-output binding differs"
                    )
                if path.exists() or path.is_symlink():
                    _durable_driver_unlink(path)
                continue
            if not (
                isinstance(binding, Mapping)
                and binding.get("owner_key") == contract.key
                and binding.get("status") == "QUARANTINED"
            ):
                raise ValueError(
                    f"{identity}: quarantined recovery ownership differs"
                )
            raw = restored_bytes.get(identity)
            if (
                status not in {
                    "ACTIVE_PREIMAGE",
                    "ACTIVE_REGISTERED_PREDECESSOR",
                }
                or raw is None
                or hashlib.sha256(raw).hexdigest()
                != prestate.get("sha256")
                or len(raw) != prestate.get("size")
            ):
                raise ValueError(
                    f"{identity}: canonical recovery preimage differs"
                )
            if (
                not path.is_file()
                or path.is_symlink()
                or path.read_bytes() != raw
            ):
                _atomic_driver_bytes(path, raw)
        if not recover_quarantined_deterministic_work_unit_prestate(
            root,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
        ):
            raise ValueError(
                "quarantined inventory re-emission did not recover"
            )
    except (
        ArtifactLedgerError,
        InventoryIDLedgerMergeError,
        KeyError,
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "inventory additive re-emission quarantine recovery failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    return []


def _record_inventory_reemit_phase_io(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
) -> list[str]:
    """Plan, prebind, apply, and commit additive inventory repair."""

    root = Path(scratchpad)
    try:
        ledger = read_artifact_ledger(root)
        prefix = "/".join(
            (
                str(config.get("pipeline") or "sc").lower(),
                str(config.get("mode") or "core").lower(),
                str(config.get("language") or "unknown").lower(),
                str(config.get("cli_backend") or "claude").lower(),
                "inventory",
            )
        )
        canonical_key = f"{prefix}/canonical_aggregate"
        id_merge_key = f"{prefix}/id_ledger_merge"
        reemit_key = f"{prefix}/additive_reemit"
        canonical = ledger.get("work_units", {}).get(canonical_key)
        id_merge = ledger.get("work_units", {}).get(id_merge_key)
        recovery_issues = (
            _recover_quarantined_inventory_reemit_transaction(
                scratchpad=root,
                project_root=project_root,
                config=config,
                run_id=run_id,
                unit=ledger.get("work_units", {}).get(reemit_key),
            )
        )
        if recovery_issues:
            return recovery_issues
        if isinstance(
            ledger.get("work_units", {}).get(reemit_key), Mapping
        ) and ledger["work_units"][reemit_key].get(
            "semantic_status"
        ) == "QUARANTINED":
            ledger = read_artifact_ledger(root)
            canonical = ledger.get("work_units", {}).get(
                canonical_key
            )
            id_merge = ledger.get("work_units", {}).get(id_merge_key)
        inventory_binding = ledger.get("artifact_bindings", {}).get(
            "scratchpad:findings_inventory.md"
        )
        plan_binding = ledger.get("artifact_bindings", {}).get(
            "scratchpad:inventory_aggregate_derivation.json"
        )
        id_binding = ledger.get("artifact_bindings", {}).get(
            "scratchpad:_id_ledger.json"
        )
        id_receipt_binding = ledger.get("artifact_bindings", {}).get(
            "scratchpad:inventory_id_ledger_merge_receipt.json"
        )
        if (
            not isinstance(canonical, Mapping)
            or canonical.get("run_id") != run_id
            or canonical.get("execution_state") != "OUTPUT_COMMITTED"
            or canonical.get("semantic_status") not in {"ACTIVE", "SUPERSEDED"}
            or not isinstance(inventory_binding, Mapping)
            or inventory_binding.get("owner_key")
            not in {canonical_key, reemit_key}
            or inventory_binding.get("status") != "ACTIVE"
            or not isinstance(plan_binding, Mapping)
            or plan_binding.get("status") != "ACTIVE"
            or not isinstance(id_merge, Mapping)
            or id_merge.get("run_id") != run_id
            or id_merge.get("execution_state") != "OUTPUT_COMMITTED"
            or id_merge.get("semantic_status") != "ACTIVE"
            or not isinstance(id_binding, Mapping)
            or id_binding.get("owner_key") not in {id_merge_key, reemit_key}
            or id_binding.get("status") != "ACTIVE"
            or not isinstance(id_receipt_binding, Mapping)
            or id_receipt_binding.get("owner_key") != id_merge_key
            or id_receipt_binding.get("status") != "ACTIVE"
            or not (root / "inventory_aggregate_derivation.json").is_file()
        ):
            return [
                "inventory additive re-emission requires an ACTIVE canonical "
                "aggregate producer authority"
            ]
        plan = _build_inventory_reemit_plan(root)
        if plan.get("status") == "NO_DEBT":
            return []
        intent = plan.get("intent")
        receipt = plan.get("receipt")
        rows = (
            intent.get("rows")
            if isinstance(intent, Mapping)
            else receipt.get("rows")
            if isinstance(receipt, Mapping)
            else None
        )
        if not isinstance(rows, list) or not rows:
            raise ValueError("inventory re-emission plan rows are absent")
        sources = tuple(sorted({
            str(row.get("source_artifact") or "")
            for row in rows
            if isinstance(row, Mapping)
        }))
        if not sources or any(
            not source
            or Path(source).name != source
            or not (root / source).is_file()
            for source in sources
        ):
            raise ValueError("inventory re-emission source denominator is invalid")
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="inventory",
            work_unit_id="additive_reemit",
            exact_inputs=(
                "inventory_aggregate_derivation.json",
                "inventory_id_allocation_delta.json",
                "inventory_id_ledger_merge_receipt.json",
                *sources,
            ),
        )
        launch = LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver",
            timeout_s=30,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        inventory_path = root / "findings_inventory.md"
        canonical_outputs = planned_inventory_output_bytes(
            _load_inventory_aggregate_plan(root)
        )
        delta = decode_inventory_allocation_delta(
            (root / "inventory_id_allocation_delta.json").read_bytes()
        )
        id_merge_receipt = decode_inventory_id_ledger_merge_receipt(
            (root / "inventory_id_ledger_merge_receipt.json").read_bytes(),
            delta=delta,
        )
        canonical_id_ledger = str(
            id_merge_receipt.get("successor_payload") or ""
        ).encode("utf-8")
        id_merge_artifact = (
            id_merge.get("artifacts", {}).get(
                "scratchpad:_id_ledger.json"
            )
            if isinstance(id_merge, Mapping)
            and isinstance(id_merge.get("artifacts"), Mapping)
            else None
        )
        if (
            not canonical_id_ledger
            or hashlib.sha256(canonical_id_ledger).hexdigest()
            != (
                id_merge_artifact.get("sha256")
                if isinstance(id_merge_artifact, Mapping)
                else None
            )
        ):
            raise ValueError(
                "inventory re-emission ID-ledger predecessor differs from "
                "the typed merge successor"
            )
        before_outputs = {
            "findings_inventory.md": canonical_outputs[
                "findings_inventory.md"
            ],
            "finding_records.json": canonical_outputs[
                "finding_records.json"
            ],
            "_id_ledger.json": canonical_id_ledger,
        }
        if hashlib.sha256(
            before_outputs["findings_inventory.md"]
        ).hexdigest() != str(intent.get("inventory_before_sha256") or ""):
            raise ValueError(
                "inventory re-emission intent does not descend from the "
                "canonical aggregate preimage"
            )
        if not isinstance(intent, Mapping):
            raise ValueError(
                "inventory re-emission intent is not an object"
            )
        if (
            intent.get("id_ledger_preimage_exists") is not True
            or str(intent.get("id_ledger_preimage_sha256") or "")
            != hashlib.sha256(
                before_outputs["_id_ledger.json"]
            ).hexdigest()
        ):
            raise ValueError(
                "inventory re-emission intent does not bind the exact "
                "ID-ledger predecessor"
            )
        materialization = _plan_inventory_reemit_materialization(
            before_outputs["findings_inventory.md"],
            intent,
        )
        inventory_raw = materialization["findings_inventory.md"]
        if hashlib.sha256(inventory_raw).hexdigest() != str(
            intent.get("inventory_after_sha256") or ""
        ):
            raise ValueError(
                "inventory re-emission did not materialize its planned "
                "inventory successor"
            )
        records = _records_from_inventory_text(
            inventory_raw.decode("utf-8", errors="replace")
        )
        records_payload = {
            "schema_version": "plamen.finding_records.v2",
            "source": "findings_inventory.md",
            "source_sha256": hashlib.sha256(inventory_raw).hexdigest(),
            "records": records,
        }
        records_after = (
            json.dumps(
                records_payload,
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")
        id_payload = json.loads(
            before_outputs["_id_ledger.json"].decode(
                "utf-8", errors="strict"
            )
        )
        if (
            not isinstance(id_payload, Mapping)
            or id_payload.get("schema_version") != _ID_LEDGER_SCHEMA_VERSION
            or not isinstance(id_payload.get("allocations"), list)
        ):
            raise ValueError("inventory re-emission ID ledger is malformed")
        allocations = [
            dict(row)
            for row in id_payload["allocations"]
            if isinstance(row, Mapping)
        ]
        allocated = {
            str(row.get("id") or "").upper() for row in allocations
        }
        reserved_inventory_ids = sorted(
            (
                finding_id
                for finding_id in allocated
                if re.fullmatch(r"INV-\d+", finding_id)
            ),
            key=lambda value: (
                int(value.split("-", 1)[1]),
                value,
            ),
        )
        if list(intent.get("reserved_inventory_ids") or []) != (
            reserved_inventory_ids
        ):
            raise ValueError(
                "inventory re-emission intent reserved-ID denominator "
                "differs from the exact ID-ledger predecessor"
            )
        records_by_id = {
            str(row.get("inventory_id") or "").upper(): row
            for row in records
            if isinstance(row, Mapping)
        }
        planned_receipt = json.loads(
            materialization["inventory_reemit_receipt.json"].decode(
                "utf-8", errors="strict"
            )
        )
        if not isinstance(planned_receipt, Mapping):
            raise ValueError(
                "inventory re-emission receipt is not an object"
            )
        for row in planned_receipt.get("rows") or []:
            if not isinstance(row, Mapping):
                raise ValueError("inventory re-emission receipt row is malformed")
            finding_id = str(row.get("target_finding_id") or "").upper()
            if not re.fullmatch(r"INV-\d+", finding_id):
                raise ValueError(
                    "inventory re-emission target ID is malformed"
                )
            if finding_id in allocated:
                raise ValueError(
                    "inventory re-emission target ID is already durably "
                    f"allocated: {finding_id}"
                )
            title = str(
                records_by_id.get(finding_id, {}).get("title")
                or "Preserved discovery candidate"
            )
            allocations.append(
                {
                    "id": finding_id,
                    "prefix": "INV-",
                    "owner_phase": "inventory",
                    "owner_attempt": 1,
                    "owning_artifact": "findings_inventory.md",
                    "title_hash": _title_hash(title),
                    "title_preview": title[:120],
                    "allocated_at": "1970-01-01T00:00:00+00:00",
                }
            )
            allocated.add(finding_id)
        allocations_by_id = {
            str(row.get("id") or "").upper(): row
            for row in allocations
            if isinstance(row, Mapping)
        }
        for row in planned_receipt.get("rows") or []:
            finding_id = str(
                row.get("target_finding_id") or ""
            ).upper()
            record = records_by_id.get(finding_id)
            allocation = allocations_by_id.get(finding_id)
            if (
                not isinstance(record, Mapping)
                or not isinstance(allocation, Mapping)
                or allocation.get("owner_phase") != "inventory"
                or allocation.get("owning_artifact")
                != "findings_inventory.md"
                or str(allocation.get("title_hash") or "")
                != _title_hash(str(record.get("title") or ""))
            ):
                raise ValueError(
                    "inventory re-emission target allocation is not "
                    f"semantically compatible: {finding_id}"
                )
        ledger_after = (
            json.dumps(
                {
                    "schema_version": _ID_LEDGER_SCHEMA_VERSION,
                    "allocations": allocations,
                },
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                indent=2,
            )
            + "\n"
        ).encode("utf-8")
        after_outputs = {
            "findings_inventory.md": inventory_raw,
            "finding_records.json": records_after,
            "_id_ledger.json": ledger_after,
        }

        def identities(name: str, raw: bytes) -> tuple[str, ...]:
            if name == "findings_inventory.md":
                return tuple(sorted({
                    (_normalize_finding_id(value) or str(value).upper())
                    for value, _block in _iter_finding_blocks(
                        raw.decode("utf-8", errors="replace")
                    )
                }))
            payload = json.loads(raw.decode("utf-8", errors="strict"))
            rows = (
                payload.get("records")
                if name == "finding_records.json"
                else payload.get("allocations")
            )
            field = "inventory_id" if name == "finding_records.json" else "id"
            return tuple(sorted({
                str(row.get(field) or "").upper()
                for row in rows or []
                if isinstance(row, Mapping) and str(row.get(field) or "")
            }))

        merge_sources = tuple(
            f"scratchpad:{source}" for source in sources
        )
        events = {
            f"scratchpad:{name}": DriverMergeEvent(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity=f"scratchpad:{name}",
                before_sha256=hashlib.sha256(before_outputs[name]).hexdigest(),
                after_sha256=hashlib.sha256(after_outputs[name]).hexdigest(),
                source_identities=merge_sources,
                identities_before=identities(name, before_outputs[name]),
                identities_after=identities(name, after_outputs[name]),
            )
            for name in before_outputs
        }
        planned_output_bytes = {
            "scratchpad:inventory_reemit_intent.json": materialization[
                "inventory_reemit_intent.json"
            ],
            "scratchpad:findings_inventory.md": inventory_raw,
            "scratchpad:inventory_reemit_receipt.json": materialization[
                "inventory_reemit_receipt.json"
            ],
            "scratchpad:finding_records.json": records_after,
            "scratchpad:_id_ledger.json": ledger_after,
        }
        current_unit = read_artifact_ledger(root).get(
            "work_units", {}
        ).get(contract.key)
        if (
            isinstance(current_unit, Mapping)
            and "successor_consumption_authority" in current_unit
        ):
            expected_records = {
                identity: {
                    "sha256": hashlib.sha256(raw).hexdigest(),
                    "size": len(raw),
                }
                for identity, raw in planned_output_bytes.items()
            }
            try:
                successor_plan = load_driver_successor_plan(
                    root,
                    project_root,
                    contract,
                    launch,
                    run_id=run_id,
                )
            except ArtifactLedgerError as exc:
                issue = (
                    "inventory re-emission successor resume authority "
                    f"failed: {exc}"
                )
                quarantine_issues = _commit_deterministic_driver_work_unit(
                    scratchpad=root,
                    project_root=project_root,
                    contract=contract,
                    launch=launch,
                    run_id=run_id,
                    domain_issues=(issue,),
                    merge_events=events,
                    expected_output_records=expected_records,
                )
                return list(
                    dict.fromkeys((issue, *quarantine_issues))
                )
            if successor_plan.expected_output_records != expected_records:
                raise ValueError(
                    "inventory re-emission resume bytes differ from "
                    "the armed successor plan"
                )
            planned_event_payloads = {
                transition.artifact_identity: (
                    transition.merge_event.to_dict()
                    if transition.merge_event is not None
                    else None
                )
                for transition in successor_plan.transitions
                if transition.merge_event is not None
            }
            if planned_event_payloads != {
                identity: event.to_dict()
                for identity, event in events.items()
            }:
                raise ValueError(
                    "inventory re-emission resume merge events differ "
                    "from the armed successor plan"
                )
        else:
            successor_plan = plan_driver_successor_transaction(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
                planned_output_bytes=planned_output_bytes,
                merge_events=events,
            )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            successor_plan=successor_plan,
        )
        if issues or not execute:
            return issues

        ordered_materialization = (
            (
                "inventory_reemit_intent.json",
                materialization["inventory_reemit_intent.json"],
            ),
            ("findings_inventory.md", inventory_raw),
            (
                "inventory_reemit_receipt.json",
                materialization["inventory_reemit_receipt.json"],
            ),
            ("finding_records.json", records_after),
            ("_id_ledger.json", ledger_after),
        )
        failpoint = str(
            config.get("_inventory_reemit_failpoint") or ""
        ).strip()
        for ordinal, (name, raw) in enumerate(
            ordered_materialization,
            start=1,
        ):
            progress = begin_driver_successor_step(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
                ordinal=ordinal,
            )
            if progress.get("state") != "STEP_APPLIED":
                output_path = root / name
                # An exact no-op transition is still an ordered applied step,
                # but replacing identical bytes changes the physical identity
                # and makes the sealed preimage impossible to replay.
                _materialize_driver_successor_bytes(output_path, raw)
                complete_driver_successor_step(
                    root,
                    project_root,
                    contract,
                    launch,
                    run_id=run_id,
                    ordinal=ordinal,
                )
            aliases = {
                f"after_{name}",
                f"after_output_{ordinal}",
            }
            if ordinal == 3:
                aliases.update({"after_apply", "after_inventory"})
            elif ordinal == 4:
                aliases.add("after_records")
            elif ordinal == 5:
                aliases.add("after_id_ledger")
            if failpoint and failpoint in aliases:
                return [
                    "inventory re-emission injected failpoint: "
                    f"{failpoint}"
                ]

        applied = _validate_inventory_reemit_materialization(
            root,
            materialization,
        )
        domain_issues = (
            []
            if applied.get("status") == "APPLIED"
            else ["inventory additive re-emission did not reach APPLIED"]
        )
        return _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            domain_issues=domain_issues,
            merge_events=events,
            expected_output_records=(
                successor_plan.expected_output_records
            ),
        )
    except (
        ArtifactLedgerError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "inventory additive re-emission PhaseIO failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _inventory_chunk_model_producer_issues(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase_name: str,
) -> list[str]:
    """Require the exact current-run MODEL owner for one chunk output."""

    root = Path(scratchpad)
    identity = f"scratchpad:findings_{phase_name}.md"
    expected_prefix = "/".join((
        str(config.get("pipeline") or "sc").lower(),
        str(config.get("mode") or "core").lower(),
        str(config.get("language") or "unknown").lower(),
        str(config.get("cli_backend") or "claude").lower(),
        phase_name,
        "",
    ))
    run_id = str(config.get("_run_id") or "")
    try:
        raw = (root / f"findings_{phase_name}.md").read_bytes()
        ledger = read_artifact_ledger(root)
    except (ArtifactLedgerError, OSError) as exc:
        return [
            f"{phase_name}: exact MODEL producer is unavailable: "
            f"{type(exc).__name__}: {exc}"
        ]
    binding = ledger.get("artifact_bindings", {}).get(identity)
    owner = (
        str(binding.get("owner_key") or "")
        if isinstance(binding, Mapping)
        else ""
    )
    unit = ledger.get("work_units", {}).get(owner)
    artifact = (
        unit.get("artifacts", {}).get(identity)
        if isinstance(unit, Mapping)
        and isinstance(unit.get("artifacts"), Mapping)
        else None
    )
    input_bindings = (
        unit.get("input_bindings")
        if isinstance(unit, Mapping)
        else None
    )
    expected_sha = hashlib.sha256(raw).hexdigest()
    if (
        not isinstance(binding, Mapping)
        or not owner.startswith(expected_prefix)
        or not re.fullmatch(r"model\.attempt[0-9]{4}", owner.rsplit("/", 1)[-1])
        or binding.get("writer") != "MODEL"
        or binding.get("status") != "ACTIVE"
        or binding.get("run_id") != run_id
        or binding.get("sha256") != expected_sha
        or binding.get("size") != len(raw)
        or not isinstance(unit, Mapping)
        or unit.get("semantic_status") != "ACTIVE"
        or unit.get("execution_state") != "OUTPUT_COMMITTED"
        or unit.get("run_id") != run_id
        or unit.get("contract_digest") != binding.get("contract_digest")
        or not isinstance(artifact, Mapping)
        or artifact.get("status") != "ACTIVE"
        or artifact.get("sha256") != expected_sha
        or artifact.get("contract_digest") != binding.get("contract_digest")
        or not isinstance(input_bindings, Mapping)
    ):
        return [
            f"{phase_name}: chunk output lacks exact ACTIVE same-run MODEL "
            "producer authority"
        ]
    for input_identity, recorded in sorted(input_bindings.items()):
        if (
            not isinstance(input_identity, str)
            or not isinstance(recorded, Mapping)
            or recorded.get("status") != "ACTIVE"
        ):
            return [
                f"{phase_name}: chunk MODEL input denominator is malformed "
                "or inactive"
            ]
        if input_identity.startswith("scratchpad:"):
            base = root
            relative = input_identity[len("scratchpad:"):]
        elif input_identity.startswith("project:"):
            base = Path(str(config.get("project_root") or root.parent))
            relative = input_identity[len("project:"):]
        else:
            return [
                f"{phase_name}: chunk MODEL input identity is unsupported: "
                f"{input_identity}"
            ]
        candidate = base / relative
        try:
            resolved_base = base.resolve(strict=False)
            resolved_candidate = candidate.resolve(strict=False)
            safe = os.path.normcase(os.path.commonpath(
                (str(resolved_base), str(resolved_candidate))
            )) == os.path.normcase(str(resolved_base))
            current = candidate.read_bytes() if safe else b""
        except (OSError, ValueError):
            safe = False
            current = b""
        if (
            not safe
            or recorded.get("sha256") != hashlib.sha256(current).hexdigest()
            or recorded.get("size") != len(current)
        ):
            return [
                f"{phase_name}: chunk MODEL exact input changed after "
                f"execution: {input_identity}"
            ]
        recorded_producer = str(
            recorded.get("producer_work_unit_key") or ""
        )
        if recorded_producer:
            current_binding = ledger.get("artifact_bindings", {}).get(
                input_identity
            )
            if (
                not isinstance(current_binding, Mapping)
                or current_binding.get("owner_key") != recorded_producer
                or current_binding.get("contract_digest")
                != recorded.get("producer_contract_digest")
                or current_binding.get("status") != "ACTIVE"
                or current_binding.get("run_id") != run_id
            ):
                return [
                    f"{phase_name}: chunk MODEL upstream input authority "
                    f"changed: {input_identity}"
                ]
    return []


def _inventory_active_chunk_letters(scratchpad: Path) -> tuple[str, ...]:
    root = Path(scratchpad)
    plan = root / "inventory_shard_plan.md"
    if plan.is_file():
        text = plan.read_text(encoding="utf-8", errors="replace")
        match = re.search(
            r"(?im)^\s*-\s*Active shard count\s*:\s*([1-3])\s*$",
            text,
        )
        if match:
            count = int(match.group(1))
            return tuple("abc"[:count])
    live = {
        match.group(1)
        for path in root.glob("findings_inventory_chunk_[abc].md")
        for match in [
            re.fullmatch(r"findings_inventory_chunk_([abc])\.md", path.name)
        ]
        if match is not None
    }
    return tuple(sorted(live))


def _inventory_aggregate_source_roster(
    scratchpad: Path,
    *,
    derivation_kind: str,
) -> tuple[str, ...]:
    """Enumerate the complete, terminal chunk/manifests/source denominator."""

    root = Path(scratchpad)
    manifests = tuple(
        sorted(path.name for path in root.glob("inventory_chunk_[abc].manifest.md"))
    )
    chunks = tuple(
        sorted(path.name for path in root.glob("findings_inventory_chunk_[abc].md"))
    )
    manifest_letters = {
        re.search(r"_([abc])\.manifest", name).group(1)
        for name in manifests
    }
    chunk_letters = {
        re.search(r"_([abc])\.md", name).group(1) for name in chunks
    }
    if not manifests or manifest_letters != chunk_letters:
        raise InventoryAggregateError(
            "terminal inventory chunk roster is incomplete or has a late "
            "unpaired chunk/manifest"
        )
    active_letters = set(_inventory_active_chunk_letters(root))
    if not active_letters or not active_letters.issubset(manifest_letters):
        raise InventoryAggregateError(
            "inventory shard plan active roster is missing or incomplete"
        )
    manifests = tuple(
        name
        for name in manifests
        if re.search(r"_([abc])\.manifest", name).group(1) in active_letters
    )
    chunks = tuple(
        name
        for name in chunks
        if re.search(r"_([abc])\.md", name).group(1) in active_letters
    )
    manifest_letters = active_letters
    source_names: set[str] = {*manifests, *chunks}
    if (root / "inventory_shard_plan.md").is_file():
        source_names.add("inventory_shard_plan.md")
    ledger = read_artifact_ledger(root)
    for letter in sorted(manifest_letters):
        phase_name = f"inventory_chunk_{letter}"
        assigned = set(parse_inventory_shard_manifest(root, phase_name))
        chunk_identity = f"scratchpad:findings_{phase_name}.md"
        chunk_binding = ledger.get("artifact_bindings", {}).get(chunk_identity)
        owner = (
            str(chunk_binding.get("owner_key") or "")
            if isinstance(chunk_binding, Mapping)
            else ""
        )
        unit = ledger.get("work_units", {}).get(owner)
        if isinstance(unit, Mapping):
            for identity in unit.get("input_bindings", {}):
                prefix = "scratchpad:"
                if (
                    isinstance(identity, str)
                    and identity.startswith(prefix)
                    and identity != f"{prefix}{phase_name}.manifest.md"
                ):
                    assigned.add(identity[len(prefix):])
        for name in sorted(assigned):
            normalized = str(name or "").strip().replace("\\", "/")
            parsed = Path(normalized)
            if (
                not normalized
                or parsed.is_absolute()
                or ".." in parsed.parts
                or not (root / parsed).is_file()
            ):
                raise InventoryAggregateError(
                    f"{phase_name} assigned source is missing or unsafe: "
                    f"{normalized!r}"
                )
            source_names.add(normalized)
    if derivation_kind == "floor_reconstruction":
        # The manifest assignment is the exact floor denominator.  No glob
        # fallback may silently widen it after the plan has been armed.
        floor_names = {
            name
            for name in source_names
            if name not in manifests
            and name not in chunks
            and name != "inventory_shard_plan.md"
        }
        if not floor_names:
            raise InventoryAggregateError(
                "floor reconstruction has no manifest-bound source artifacts"
            )
    return tuple(sorted(source_names))


def _inventory_aggregate_source_bindings(
    scratchpad: Path,
    source_names: Sequence[str],
) -> list[dict[str, Any]]:
    """Capture exact bytes plus producer identity for every planned input."""

    root = Path(scratchpad)
    ledger = read_artifact_ledger(root)
    bindings = ledger.get("artifact_bindings", {})
    rows: list[dict[str, Any]] = []
    for name in source_names:
        path = root / name
        raw = path.read_bytes()
        identity = f"scratchpad:{name}"
        binding = (
            bindings.get(identity) if isinstance(bindings, Mapping) else None
        )
        rows.append(
            {
                "artifact": name,
                "sha256": hashlib.sha256(raw).hexdigest(),
                "size": len(raw),
                "producer_work_unit_key": (
                    str(binding.get("owner_key") or "")
                    if isinstance(binding, Mapping)
                    else ""
                ),
                "producer_contract_digest": (
                    str(binding.get("contract_digest") or "")
                    if isinstance(binding, Mapping)
                    else ""
                ),
                "producer_status": (
                    str(binding.get("status") or "")
                    if isinstance(binding, Mapping)
                    else "UNOWNED_INPUT"
                ),
            }
        )
    return rows


def _inventory_aggregate_contract_and_launch(
    *,
    config: Mapping[str, Any],
    work_unit_id: str,
    exact_inputs: Sequence[str],
    timeout_s: int,
) -> tuple[PhaseIOContract, LaunchSpec]:
    outputs = (
        ("inventory_aggregate_derivation.json",)
        if work_unit_id.startswith("aggregate_plan.")
        else tuple(INVENTORY_AGGREGATE_OUTPUT_NAMES)
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="inventory",
        work_unit_id=work_unit_id,
        exact_inputs=tuple(exact_inputs),
        exact_outputs=outputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _inventory_id_ledger_contract_and_launch(
    *,
    config: Mapping[str, Any],
    timeout_s: int,
) -> tuple[PhaseIOContract, LaunchSpec]:
    inputs = (
        "inventory_aggregate_derivation.json",
        "inventory_id_allocation_delta.json",
        "findings_inventory.md",
        "finding_records.json",
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="inventory",
        work_unit_id="id_ledger_merge",
        exact_inputs=inputs,
        exact_outputs=(
            "_id_ledger.json",
            "inventory_id_ledger_merge_receipt.json",
        ),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _run_inventory_id_ledger_merge_transaction(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    timeout_s: int,
) -> list[str]:
    """Arm, CAS, and commit the canonical allocation delta into the ID ledger."""

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["inventory ID-ledger merge cannot bind without run_id"]
    contract, launch = _inventory_id_ledger_contract_and_launch(
        config=config,
        timeout_s=timeout_s,
    )
    try:
        with _ledger_transaction_lock(root):
            delta_path = root / "inventory_id_allocation_delta.json"
            delta = decode_inventory_allocation_delta(delta_path.read_bytes())
            inventory_raw = (root / "findings_inventory.md").read_bytes()
            records_raw = (root / "finding_records.json").read_bytes()
            if (
                delta.get("run_id") != run_id
                or delta.get("inventory_sha256")
                != hashlib.sha256(inventory_raw).hexdigest()
                or delta.get("records_sha256")
                != hashlib.sha256(records_raw).hexdigest()
            ):
                return [
                    "inventory ID-ledger allocation projection differs from its "
                    "canonical inventory/records anchors"
                ]
            execute, issues = _arm_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
            if issues or not execute:
                return issues
            ledger_state = read_artifact_ledger(root)
            unit = ledger_state.get("work_units", {}).get(contract.key)
            prestate = (
                unit.get("output_prestates", {}).get(
                    "scratchpad:_id_ledger.json"
                )
                if isinstance(unit, Mapping)
                else None
            )
            if not isinstance(prestate, Mapping):
                return ["inventory ID-ledger merge prestate receipt is absent"]
            expected_before = str(prestate.get("sha256") or "")
            expected_size = int(prestate.get("size") or 0)
            preexisting_typed = prestate.get("status") == "ACTIVE_PREIMAGE"
            failpoint = str(
                config.get("_inventory_id_ledger_merge_failpoint") or ""
            ).strip()
            if failpoint == "after_arm":
                return [
                    "inventory ID-ledger merge injected failpoint: after_arm"
                ]

            ledger_path = root / "_id_ledger.json"
            receipt_path = root / "inventory_id_ledger_merge_receipt.json"
            existed = ledger_path.is_file()
            live_raw = ledger_path.read_bytes() if existed else b""
            live_sha = hashlib.sha256(live_raw).hexdigest()
            receipt = (
                decode_inventory_id_ledger_merge_receipt(
                    receipt_path.read_bytes(), delta=delta
                )
                if receipt_path.is_file()
                else None
            )
            if receipt is None:
                if (
                    live_sha != expected_before
                    or len(live_raw) != expected_size
                    or bool(prestate.get("existed")) != existed
                ):
                    return [
                        "inventory ID-ledger CAS rejected third-state drift "
                        "after arm"
                    ]
                receipt = build_inventory_id_ledger_merge_receipt(
                    delta=delta,
                    before_raw=live_raw if existed else None,
                    preexisting_typed=preexisting_typed,
                )
                _atomic_driver_bytes(
                    receipt_path,
                    encode_inventory_id_ledger_merge_receipt(
                        receipt, delta=delta
                    ),
                )
            if (
                receipt.get("before_sha256") != expected_before
                or bool(receipt.get("before_existed"))
                != bool(prestate.get("existed"))
                or receipt.get("delta_digest") != delta.get("delta_digest")
            ):
                return [
                    "inventory ID-ledger merge receipt differs from the "
                    "armed preimage"
                ]
            if failpoint == "after_receipt":
                return [
                    "inventory ID-ledger merge injected failpoint: "
                    "after_receipt"
                ]
            debt_issues = [
                str(value)
                for value in receipt.get("issues") or []
                if str(value)
            ]
            successor = str(
                receipt.get("successor_payload") or ""
            ).encode("utf-8")
            expected_after = str(receipt.get("after_sha256") or "")
            live_raw = ledger_path.read_bytes() if ledger_path.is_file() else b""
            live_sha = hashlib.sha256(live_raw).hexdigest()
            if debt_issues:
                if live_sha != expected_before:
                    return [
                        "inventory ID-ledger debt path observed third-state "
                        "drift; bytes were preserved"
                    ]
            elif live_sha == expected_before:
                # The shared interprocess ledger lock serializes compliant
                # writers.  Re-read immediately before the atomic replace so
                # an external/non-compliant writer still cannot win the CAS.
                cas_raw = (
                    ledger_path.read_bytes() if ledger_path.is_file() else b""
                )
                if (
                    hashlib.sha256(cas_raw).hexdigest() != expected_before
                    or len(cas_raw) != expected_size
                ):
                    return [
                        "inventory ID-ledger CAS rejected concurrent "
                        "third-state drift"
                    ]
                _atomic_driver_bytes(ledger_path, successor)
            elif live_sha != expected_after:
                return [
                    "inventory ID-ledger CAS rejected third-state drift "
                    "during resume"
                ]
            if failpoint == "after_write":
                return [
                    "inventory ID-ledger merge injected failpoint: after_write"
                ]

            identities_before = tuple(
                str(value) for value in receipt.get("before_ids") or []
            )
            identities_after = tuple(
                str(value) for value in receipt.get("after_ids") or []
            )
            event = DriverMergeEvent(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity="scratchpad:_id_ledger.json",
                before_sha256=expected_before,
                after_sha256=str(receipt.get("after_sha256") or ""),
                source_identities=tuple(sorted(
                    set(contract.immutable_inputs)
                    | set(contract.bounded_lookup_inputs)
                )),
                identities_before=identities_before,
                identities_after=identities_after,
            )
            domain_issues = [
                str(value)
                for value in receipt.get("issues") or []
                if str(value)
            ]
            return _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=domain_issues,
                merge_events={
                    "scratchpad:_id_ledger.json": event,
                },
            )
    except (
        ArtifactLedgerError,
        InventoryIDLedgerMergeError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "inventory ID-ledger merge transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _validate_inventory_id_ledger_merge_phase_io(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    timeout_s: int,
) -> list[str]:
    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "")
    try:
        contract, launch = _inventory_id_ledger_contract_and_launch(
            config=config,
            timeout_s=timeout_s,
        )
        delta = decode_inventory_allocation_delta(
            (root / "inventory_id_allocation_delta.json").read_bytes()
        )
        receipt = decode_inventory_id_ledger_merge_receipt(
            (root / "inventory_id_ledger_merge_receipt.json").read_bytes(),
            delta=delta,
        )
        ledger_sha = hashlib.sha256(
            (root / "_id_ledger.json").read_bytes()
        ).hexdigest()
        domain: list[str] = []
        if receipt.get("issues"):
            domain.extend(str(value) for value in receipt["issues"])
        if ledger_sha != receipt.get("after_sha256"):
            domain.append(
                "inventory ID-ledger bytes differ from committed merge receipt"
            )
        return list(dict.fromkeys([
            *domain,
            *validate_work_unit_inputs(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
            ),
            *validate_work_unit_artifacts(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            ),
        ]))
    except (
        ArtifactLedgerError,
        InventoryIDLedgerMergeError,
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "inventory ID-ledger merge validation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _canonical_inventory_transaction_started(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> bool:
    """Return whether legacy MODEL fallback is no longer admissible.

    The canonical plan is the durable transaction boundary.  A typed work-unit
    prebind also counts even when a crash happened before the plan bytes were
    materialized.  Corrupt typed state is conservatively treated as started:
    it is never permission to let a second writer overwrite canonical outputs.
    """

    root = Path(scratchpad)
    try:
        if rooted_io.lexists(root / "inventory_aggregate_derivation.json"):
            return True
    except OSError:
        # Failure to observe a canonical control path is never evidence of an
        # unused scratchpad.  Exclude the legacy writer and preserve repair
        # debt for the typed path validator.
        return True
    # The typed ledger's canonical filename is owned by ``artifact_ledger``.
    # A stale private spelling here made an already-prebound inventory
    # transaction look absent and could reopen the legacy MODEL writer.
    ledger_path = root / ARTIFACT_LEDGER_NAME
    # ``Path.exists`` follows links and reports a dangling link/reparse as
    # absent.  Any canonical control-path object is transaction state; the
    # ledger reader below decides whether its bytes are valid.
    try:
        if not rooted_io.lexists(ledger_path):
            return False
    except OSError:
        return True
    try:
        ledger = read_artifact_ledger(root)
    except (ArtifactLedgerError, OSError, TypeError, ValueError):
        return True
    # Transaction start is scratchpad-global, not scoped to mutable resume
    # configuration.  Re-entering the same scratchpad under another
    # mode/backend/ecosystem must not reopen the legacy writer.  Validate the
    # six-component PhaseIO key before recognizing only the inventory units
    # that establish this boundary.
    for key in ledger.get("work_units", {}):
        if not isinstance(key, str):
            continue
        parts = key.split("/")
        if len(parts) != 6:
            continue
        try:
            if canonical_work_unit_key(*parts) != key:
                continue
        except (TypeError, ValueError):
            continue
        phase_name, work_unit_id = parts[4], parts[5]
        if phase_name == "inventory" and (
            work_unit_id in {"canonical_aggregate", "id_ledger_merge"}
            or work_unit_id.startswith("aggregate_plan.")
        ):
            return True
    return False


def _enforce_canonical_inventory_debt_boundary(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    checkpoint: Checkpoint,
) -> None:
    """Stop before the legacy MODEL writer after a canonical transaction.

    This is an interim repair boundary.  Exact typed artifacts and debt remain
    resumable; downstream debt-safe continuation is a separate acceptance
    condition and is not claimed here.
    """

    if not _canonical_inventory_transaction_started(scratchpad, config):
        return
    checkpoint.save(Path(scratchpad))
    raise SystemExit(EXIT_DEGRADED)


def _load_inventory_aggregate_plan(
    scratchpad: Path,
) -> dict[str, Any]:
    path = Path(scratchpad) / "inventory_aggregate_derivation.json"
    payload = json.loads(path.read_text(encoding="utf-8", errors="strict"))
    validate_inventory_aggregate_derivation(payload)
    return dict(payload)


def _validate_inventory_aggregate_plan_sources(
    scratchpad: Path,
    payload: Mapping[str, Any],
) -> list[str]:
    root = Path(scratchpad)
    issues: list[str] = []
    rows = payload.get("source_artifacts")
    if not isinstance(rows, list) or not rows:
        return ["canonical inventory aggregate plan has no source denominator"]
    recorded_names: list[str] = []
    for row in rows:
        if not isinstance(row, Mapping):
            issues.append("canonical inventory aggregate source row is malformed")
            continue
        name = str(row.get("artifact") or "")
        recorded_names.append(name)
        path = root / name
        if not name or Path(name).is_absolute() or ".." in Path(name).parts:
            issues.append("canonical inventory aggregate source path is unsafe")
            continue
        if not path.is_file():
            issues.append(f"canonical inventory aggregate source missing: {name}")
            continue
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        if digest != str(row.get("sha256") or ""):
            issues.append(f"canonical inventory aggregate source drift: {name}")
    active_letters = set(_inventory_active_chunk_letters(root))
    live_manifests = {
        path.name
        for path in root.glob("inventory_chunk_[abc].manifest.md")
        if re.search(r"_([abc])\.manifest", path.name).group(1)
        in active_letters
    }
    live_chunks = {
        path.name
        for path in root.glob("findings_inventory_chunk_[abc].md")
        if re.search(r"_([abc])\.md", path.name).group(1) in active_letters
    }
    planned = set(recorded_names)
    late = sorted((live_manifests | live_chunks) - planned)
    if late:
        issues.append(
            "canonical inventory aggregate late chunk/manifest invalidation: "
            + ", ".join(late)
        )
    return list(dict.fromkeys(issues))


def _validate_inventory_canonical_aggregate_phase_io(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    include_id_ledger_merge: bool = True,
) -> list[str]:
    """Replay exact plan/source/output authority without mutating disk."""

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["canonical inventory aggregate validation has no run_id"]
    try:
        payload = _load_inventory_aggregate_plan(root)
        source_issues = _validate_inventory_aggregate_plan_sources(root, payload)
        kind = str(payload.get("derivation_kind") or "")
        plan_inputs = tuple(
            str(row.get("artifact") or "")
            for row in payload.get("source_artifacts", [])
            if isinstance(row, Mapping)
        )
        plan_contract, plan_launch = _inventory_aggregate_contract_and_launch(
            config=config,
            work_unit_id=f"aggregate_plan.{kind}",
            exact_inputs=plan_inputs,
            timeout_s=phase.base_timeout_s,
        )
        aggregate_contract, aggregate_launch = (
            _inventory_aggregate_contract_and_launch(
                config=config,
                work_unit_id="canonical_aggregate",
                exact_inputs=(
                    "inventory_aggregate_derivation.json",
                    *plan_inputs,
                ),
                timeout_s=phase.base_timeout_s,
            )
        )
        output_issues: list[str] = []
        for name, digest in payload["output_sha256"].items():
            path = root / str(name)
            if not path.is_file():
                output_issues.append(
                    f"canonical inventory aggregate output missing: {name}"
                )
            elif hashlib.sha256(path.read_bytes()).hexdigest() != digest:
                output_issues.append(
                    f"canonical inventory aggregate output drift: {name}"
                )
        issues = list(
            dict.fromkeys(
                [
                    *source_issues,
                    *validate_work_unit_inputs(
                        root,
                        project_root,
                        plan_contract,
                        plan_launch,
                        run_id=run_id,
                    ),
                    *validate_work_unit_artifacts(
                        root,
                        project_root,
                        plan_contract,
                        plan_launch,
                        run_id=run_id,
                        actor="DRIVER",
                    ),
                    *validate_work_unit_inputs(
                        root,
                        project_root,
                        aggregate_contract,
                        aggregate_launch,
                        run_id=run_id,
                    ),
                    *validate_work_unit_artifacts(
                        root,
                        project_root,
                        aggregate_contract,
                        aggregate_launch,
                        run_id=run_id,
                        actor="DRIVER",
                    ),
                    *output_issues,
                ]
            )
        )
        if include_id_ledger_merge:
            issues.extend(
                _validate_inventory_id_ledger_merge_phase_io(
                    scratchpad=root,
                    config=config,
                    timeout_s=phase.base_timeout_s,
                )
            )
        return list(dict.fromkeys(issues))
    except (
        ArtifactLedgerError,
        InventoryAggregateError,
        KeyError,
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "canonical inventory aggregate validation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _run_inventory_canonical_aggregate_transaction(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    derivation_kind: str,
) -> tuple[dict[str, Any], list[str]]:
    """Pure derive -> prebind -> materialize -> validate -> commit."""

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    kind = str(derivation_kind or "").strip()
    if not run_id:
        return {}, ["canonical inventory aggregate cannot bind without run_id"]
    if kind not in INVENTORY_AGGREGATE_DERIVATION_KINDS:
        return {}, [f"unsupported canonical inventory derivation kind: {kind!r}"]
    try:
        resume_payload: dict[str, Any] = {}
        # A completed aggregate is immutable for this run.  Replays validate
        # the exact source and producer denominator and never replan from its
        # own output files.
        if (root / "inventory_aggregate_derivation.json").is_file():
            try:
                prior = _load_inventory_aggregate_plan(root)
            except (
                InventoryAggregateError,
                OSError,
                UnicodeError,
                ValueError,
                json.JSONDecodeError,
            ):
                prior = {}
            if prior.get("derivation_kind") == kind:
                replay_issues = _validate_inventory_canonical_aggregate_phase_io(
                    scratchpad=root,
                    config=config,
                    phase=phase,
                    include_id_ledger_merge=False,
                )
                ledger = read_artifact_ledger(root)
                canonical = ledger.get("work_units", {}).get(
                    "/".join(
                        (
                            str(config.get("pipeline") or "sc").lower(),
                            str(config.get("mode") or "core").lower(),
                            str(config.get("language") or "unknown").lower(),
                            str(config.get("cli_backend") or "claude").lower(),
                            "inventory",
                            "canonical_aggregate",
                        )
                    )
                )
                if (
                    isinstance(canonical, Mapping)
                    and canonical.get("semantic_status") == "ACTIVE"
                ):
                    if replay_issues:
                        return prior, replay_issues
                    merge_issues = (
                        _run_inventory_id_ledger_merge_transaction(
                            scratchpad=root,
                            config=config,
                            timeout_s=phase.base_timeout_s,
                        )
                    )
                    if merge_issues:
                        return prior, merge_issues
                    return prior, (
                        _validate_inventory_canonical_aggregate_phase_io(
                            scratchpad=root,
                            config=config,
                            phase=phase,
                        )
                    )
                if (
                    isinstance(canonical, Mapping)
                    and canonical.get("run_id") == run_id
                    and canonical.get("semantic_status") == "INPUTS_BOUND"
                    and canonical.get("execution_state")
                    == "INPUTS_BOUND_PREEXECUTION"
                    and canonical.get("artifacts") == {}
                ):
                    # A crash after one or more output writes must resume from
                    # the already committed plan denominator.  Re-enumerating
                    # here could mistake a partial output (notably the ID
                    # ledger) for a newly discovered semantic input.
                    resume_payload = dict(prior)

        source_names = (
            tuple(
                str(row.get("artifact") or "")
                for row in resume_payload.get("source_artifacts", [])
                if isinstance(row, Mapping)
            )
            if resume_payload
            else _inventory_aggregate_source_roster(
                root, derivation_kind=kind
            )
        )
        chunk_phases = sorted(
            {
                re.search(r"findings_(inventory_chunk_[abc])\.md", name).group(1)
                for name in source_names
                if re.fullmatch(r"findings_inventory_chunk_[abc]\.md", name)
            }
        )
        producer_issues: list[str] = []
        for phase_name in chunk_phases:
            producer_issues.extend(
                _inventory_chunk_model_producer_issues(
                    scratchpad=root,
                    config=config,
                    phase_name=phase_name,
                )
            )
        if producer_issues:
            return {}, list(dict.fromkeys(producer_issues))

        payload = (
            resume_payload
            if resume_payload
            else build_inventory_aggregate_derivation(
                root,
                derivation_kind=kind,
                run_id=run_id,
                source_names=source_names,
                source_bindings=_inventory_aggregate_source_bindings(
                    root, source_names
                ),
            )
        )
        plan_contract, plan_launch = _inventory_aggregate_contract_and_launch(
            config=config,
            work_unit_id=f"aggregate_plan.{kind}",
            exact_inputs=source_names,
            timeout_s=phase.base_timeout_s,
        )
        if resume_payload:
            issues = list(dict.fromkeys([
                *_validate_inventory_aggregate_plan_sources(root, payload),
                *validate_work_unit_inputs(
                    root,
                    project_root,
                    plan_contract,
                    plan_launch,
                    run_id=run_id,
                ),
                *validate_work_unit_artifacts(
                    root,
                    project_root,
                    plan_contract,
                    plan_launch,
                    run_id=run_id,
                    actor="DRIVER",
                ),
            ]))
            if issues:
                return payload, issues
        else:
            execute_plan, issues = _arm_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=plan_contract,
                launch=plan_launch,
                run_id=run_id,
            )
            if issues:
                return payload, issues
            if execute_plan:
                _atomic_driver_bytes(
                    root / "inventory_aggregate_derivation.json",
                    encode_inventory_aggregate_derivation(payload),
                )
                issues.extend(
                    _commit_deterministic_driver_work_unit(
                        scratchpad=root,
                        project_root=project_root,
                        contract=plan_contract,
                        launch=plan_launch,
                        run_id=run_id,
                    )
                )
                if issues:
                    return payload, issues
            else:
                payload = _load_inventory_aggregate_plan(root)

        aggregate_inputs = (
            "inventory_aggregate_derivation.json",
            *tuple(
                str(row.get("artifact") or "")
                for row in payload["source_artifacts"]
            ),
        )
        aggregate_contract, aggregate_launch = (
            _inventory_aggregate_contract_and_launch(
                config=config,
                work_unit_id="canonical_aggregate",
                exact_inputs=aggregate_inputs,
                timeout_s=phase.base_timeout_s,
            )
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=aggregate_contract,
            launch=aggregate_launch,
            run_id=run_id,
        )
        if issues or not execute:
            return payload, issues

        planned = planned_inventory_output_bytes(payload)
        for index, name in enumerate(INVENTORY_AGGREGATE_OUTPUT_NAMES):
            _atomic_driver_bytes(root / name, planned[name])
            failpoint = str(
                config.get("_inventory_aggregate_failpoint") or ""
            ).strip()
            if failpoint and failpoint in {
                f"after_{name}",
                (
                    "after_inventory"
                    if name == "findings_inventory.md"
                    else ""
                ),
                f"after_output_{index + 1}",
            }:
                return payload, [
                    f"inventory aggregate injected failpoint: {failpoint}"
                ]

        domain_issues = _validate_inventory_aggregate_plan_sources(root, payload)
        for name, expected in payload["output_sha256"].items():
            observed = hashlib.sha256((root / name).read_bytes()).hexdigest()
            if observed != expected:
                domain_issues.append(
                    f"canonical inventory aggregate output drift: {name}"
                )
        issues.extend(
            _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=aggregate_contract,
                launch=aggregate_launch,
                run_id=run_id,
                domain_issues=domain_issues,
            )
        )
        if not issues:
            issues.extend(
                _run_inventory_id_ledger_merge_transaction(
                    scratchpad=root,
                    config=config,
                    timeout_s=phase.base_timeout_s,
                )
            )
        if not issues:
            issues.extend(
                _validate_inventory_canonical_aggregate_phase_io(
                    scratchpad=root,
                    config=config,
                    phase=phase,
                )
            )
        return payload, list(dict.fromkeys(issues))
    except (
        ArtifactLedgerError,
        InventoryAggregateError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return {}, [
            "canonical inventory aggregate transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _record_inventory_reconciliation_phase_io_named(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase_name: str,
    timeout_s: int,
    refresh_reemit_owner: bool | None = None,
) -> list[str]:
    """Materialize and bind exact raw-discovery disposition artifacts."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["inventory reconciliation PhaseIO cannot bind without a run_id"]
    project_root = Path(str(config.get("project_root") or root.parent))
    phase_name = str(phase_name)
    is_chunk = phase_name.startswith("inventory_chunk_")
    scope = phase_name if is_chunk else None
    if is_chunk and refresh_reemit_owner is True:
        return [
            f"{phase_name}: chunk reconciliation cannot arm additive reemit"
        ]
    should_refresh_reemit = (
        not is_chunk
        if refresh_reemit_owner is None
        else bool(refresh_reemit_owner)
    )
    closure_issues: list[str] = []
    if not is_chunk:
        _refresh_central_negative_closure_authority(root, closure_issues)
    try:
        if is_chunk:
            producer_issues = _inventory_chunk_model_producer_issues(
                scratchpad=root,
                config=config,
                phase_name=phase_name,
            )
            if producer_issues:
                return producer_issues
        if should_refresh_reemit:
            reemit_issues = _record_inventory_reemit_phase_io(
                scratchpad=root,
                project_root=project_root,
                config=config,
                run_id=run_id,
            )
            if reemit_issues:
                return reemit_issues
        payload = _reconcile_exact_inventory(
            root, phase_name=scope, persist=False
        )
        contract, launch = _inventory_reconciliation_contract_and_launch(
            scratchpad=root,
            config=config,
            phase_name=phase_name,
            payload=payload,
            timeout_s=timeout_s,
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues or not execute:
            return list(dict.fromkeys([*closure_issues, *issues]))
        written = _write_exact_inventory_receipt(root, phase_name=scope)
        receipt_issues = _validate_exact_inventory_receipt(
            root, phase_name=scope
        )
        if written != payload:
            receipt_issues.append(
                "inventory reconciliation derivation changed after prebind"
            )
        issues.extend(
            _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=receipt_issues,
            )
        )
        return list(dict.fromkeys([*closure_issues, *issues]))
    except (
        ArtifactLedgerError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            *closure_issues,
            "inventory reconciliation PhaseIO failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _record_inventory_reconciliation_phase_io(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> list[str]:
    """Phase-shaped compatibility wrapper for exact reconciliation."""

    return _record_inventory_reconciliation_phase_io_named(
        scratchpad=Path(scratchpad),
        config=config,
        phase_name=str(phase.name),
        timeout_s=int(phase.base_timeout_s),
    )


def _refresh_final_inventory_reconciliation_phase_io(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Re-derive stale final sidecars after authorized inventory mutations.

    Depth promotion, additive re-emission, and receipt-authorized semantic
    dedup can legitimately mutate ``findings_inventory.md`` after the initial
    inventory reconciliation committed.  Those mutations invalidate the
    reconciliation work unit by design.  Before terminal assurance consumes
    its sidecars, re-execute the same deterministic, exact-input contract so
    the current sidecar bytes have current producer authority.  Missing
    sidecars remain missing; this is refresh, not late fabrication.
    """

    root = Path(scratchpad)
    if not (root / "inventory_reconciliation.json").is_file():
        return []
    phase_table = (
        L1_PHASES
        if str(config.get("pipeline") or "sc") == "l1"
        else SC_PHASES
    )
    inventory_phase = next(
        (phase for phase in phase_table if phase.name == "inventory"), None
    )
    if inventory_phase is None:
        return ["inventory reconciliation refresh has no inventory phase"]
    return _record_inventory_reconciliation_phase_io_named(
        scratchpad=root,
        config=config,
        phase_name="inventory",
        timeout_s=int(inventory_phase.base_timeout_s),
        refresh_reemit_owner=False,
    )


def _validate_inventory_reconciliation_phase_io(
    *,
    scratchpad: Path,
    project_root: Path,
    phase_name: str,
    mode: str,
    language: str,
    pipeline: str,
    backend: str,
    timeout_s: int,
) -> list[str]:
    """Side-effect-free exact P0-L receipt/ledger replay."""

    root = Path(scratchpad)
    scope = phase_name if phase_name.startswith("inventory_chunk_") else None
    receipt_name, _human_name = _inventory_reconciliation_output_names(
        phase_name
    )
    try:
        receipt_issues = _validate_exact_inventory_receipt(
            root, phase_name=scope
        )
        if receipt_issues:
            return receipt_issues
        payload = json.loads(
            (root / receipt_name).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        config = {
            "pipeline": pipeline,
            "mode": mode,
            "language": language,
            "cli_backend": backend,
        }
        contract, launch = _inventory_reconciliation_contract_and_launch(
            scratchpad=root,
            config=config,
            phase_name=phase_name,
            payload=payload,
            timeout_s=timeout_s,
        )
        run_id = _report_disposition_run_id(root)
        issues = validate_work_unit_inputs(
            root, Path(project_root), contract, launch, run_id=run_id
        )
        issues.extend(
            validate_work_unit_artifacts(
                root,
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            )
        )
        return list(dict.fromkeys(issues))
    except (
        ArtifactLedgerError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "inventory reconciliation resume PhaseIO failure: "
            f"{type(exc).__name__}: {exc}"
        ]


def _synthesize_depth_lifecycle_artifacts(
    scratchpad: Path, pipeline: str, *, force: bool = False,
    mode: str = "core",
    config: Mapping[str, Any] | None = None,
    phase: Phase | None = None,
) -> list[str]:
    """Auto-generate never_cut_checkpoint.md and depth_exit.md from disk state.

    Codex/GPT models reliably produce finding files but frequently omit the
    lifecycle metadata artifacts the gate requires, or write them in a format
    the validator rejects.  These are mechanically derivable from what's on
    disk — no LLM reasoning needed.

    When *force* is True (Codex backend), always overwrite — the driver's
    mechanical version is more reliable than whatever the LLM wrote.

    v2.6.3: mode-aware — Thorough-only roles (design-stress, perturbation,
    skill-execution-checklist) are only included when mode == "thorough".

    Returns list of files synthesized (for logging).
    """
    synthesized: list[str] = []

    # F2.a: rebuild order matters. confidence_scores.md must be recomputed
    # BEFORE never_cut_checkpoint.md and depth_exit.md, because the latter
    # two read confidence's existence/size to mark `confidence-scoring`
    # status. Original order rebuilt the checkpoint with stale/missing
    # confidence info, then recomputed confidence — so the checkpoint
    # recorded `SKIPPED NO_APPLICABLE_FLAG` despite real findings.

    # --- confidence_scores.md (S1.3 — driver-owned mechanical scoring) ---
    # Recompute the driver-owned authority on every finalization.  A
    # substantive LLM-written table is still a proposal: it cannot override
    # typed corroboration provenance or preserve stale pre-DA scores.  The
    # computation is deterministic/idempotent, so retries and resume obtain
    # the same bytes while newly completed DA findings are incorporated.
    cs = scratchpad / "confidence_scores.md"
    if config is not None and phase is not None:
        confidence_issues = _write_and_record_confidence_consensus_phase_io(
            scratchpad=scratchpad,
            config=config,
            phase=phase,
        )
        for issue in confidence_issues:
            _append_phase_io_debt(
                scratchpad,
                "depth",
                "CONFIDENCE_CONSENSUS_PHASE_IO",
                issue,
            )
    else:
        # Compatibility for pure formatter/unit-test callers that have no run
        # authority.  Live orchestration always supplies config+phase and uses
        # the pre-execution transaction above.
        _compute_depth_confidence(scratchpad, mode)
    if cs.exists():
        synthesized.append("confidence_scores.md")

    # --- never_cut_checkpoint.md ---
    # F2.a: ALWAYS rebuild. Purely mechanical 9-line status derived from
    # on-disk findings; previously guarded by `if force or not ncc.exists()`
    # which left the file frozen at the attempt-1 all-SKIPPED snapshot even
    # after attempt 2 produced real findings.
    ncc = scratchpad / "never_cut_checkpoint.md"
    if pipeline == "l1":
        role_file_map = {
            "depth-consensus-invariant": "depth_consensus_invariant_findings.md",
            "depth-network-surface": "depth_network_surface_findings.md",
            "depth-state-trace": "depth_state_trace_findings.md",
            "depth-external": "depth_external_findings.md",
            "depth-edge-case": "depth_edge_case_findings.md",
            "confidence-scoring": "confidence_scores.md",
        }
    else:
        role_file_map = {
            "depth-token-flow": "depth_token_flow_findings.md",
            "depth-state-trace": "depth_state_trace_findings.md",
            "depth-edge-case": "depth_edge_case_findings.md",
            "depth-external": "depth_external_findings.md",
            "confidence-scoring": "confidence_scores.md",
        }
    if mode == "thorough":
        role_file_map.update({
            "design-stress": "design_stress_findings.md",
            "perturbation": "perturbation_findings.md",
            "skill-execution-checklist": "skill_execution_gaps.md",
        })
    ncc_lines = ["# Never-Cut Checkpoint (auto-synthesized by driver)\n"]
    for role, filename in role_file_map.items():
        fpath = scratchpad / filename
        alias = f"depth_{filename}" if not filename.startswith("depth_") else None
        exists = fpath.exists() and fpath.stat().st_size > 0
        if not exists and alias:
            alias_p = scratchpad / alias
            if alias_p.exists() and alias_p.stat().st_size > 0:
                exists = True
                fpath = alias_p
        # v2.0.3 (A3 / Codex Claim 7): substance-aware status. A header-only
        # 29-byte file produced by an orphaned background agent must NOT be
        # reported as SPAWNED — that hides the orphan from downstream
        # diagnostics. Mirror the gate's substance check.
        if exists:
            stub_reason = _depth_artifact_is_stub(fpath)
            if stub_reason:
                status = f"STUB ({stub_reason})"
            else:
                status = "SPAWNED"
        else:
            status = "SKIPPED NO_APPLICABLE_FLAG"
        ncc_lines.append(f"- {role}: {status}")
    try:
        ncc.write_text("\n".join(ncc_lines) + "\n", encoding="utf-8")
        synthesized.append("never_cut_checkpoint.md")
    except OSError:
        pass

    # --- depth_exit.md ---
    # F2.a + F2.c: ALWAYS rebuild the structured header; preserve genuine
    # LLM body content under `## Original LLM depth exit (preserved)`, but
    # FIRST strip any prior driver-generated wrapper from the existing
    # file so the preservation does not nest itself recursively across
    # repeated calls. Without this strip, each call would wrap the prior
    # call's full file (including its own header) as "original LLM body",
    # bloating the file unboundedly across attempts/repairs.
    dep = scratchpad / "depth_exit.md"
    dep_existing_text = ""
    if dep.exists() and not force:
        try:
            dep_existing_text = dep.read_text(encoding="utf-8", errors="replace")
        except Exception:
            dep_existing_text = ""
    # Strip prior driver wrapper.
    llm_only = dep_existing_text
    if llm_only:
        # If there's a previously-preserved LLM block, keep only what's
        # below the `## Original LLM depth exit (preserved)` marker.
        m = re.search(
            r"(?ms)^##\s+Original\s+LLM\s+depth\s+exit\s+\(preserved\)\s*\n+",
            llm_only,
        )
        if m:
            llm_only = llm_only[m.end():]
        # Or if no marker but the text starts with the driver header, the
        # whole file is a prior driver wrapper with no real LLM body.
        elif re.match(
            r"\s*#\s+Depth\s+Exit\s+\(auto-synthesized", llm_only
        ):
            llm_only = ""
    # v2.0.3 (A3): split depth files into substantive vs stub.
    # depth_exit.md must NOT list stub files under "completed roles" —
    # that produces a misleading exit rationale when orphan-background
    # leaves header-only files on disk.
    depth_files = list(scratchpad.glob("depth_*_findings.md"))
    completed: list[str] = []
    stub_paths: list[str] = []
    for f in depth_files:
        if f.stat().st_size == 0:
            continue
        if _depth_artifact_is_stub(f):
            stub_paths.append(f.name)
        else:
            completed.append(f.name)
    dep_lines = [
        "# Depth Exit (auto-synthesized by driver)\n",
        "- criterion: 1",
        "- rationale: Substance-aware exit (v2.0.3). Stub files are listed "
        "separately and NOT counted as completion.",
        "- explored_paths:",
    ]
    for name in completed:
        dep_lines.append(f"  - {name}")
    if not completed:
        dep_lines.append("  - (no substantive depth findings files found)")
    if stub_paths:
        dep_lines.append("- stub_paths (NOT counted as completion):")
        for name in stub_paths:
            dep_lines.append(f"  - {name}")
    if llm_only.strip() and not force:
        dep_lines.append("\n---\n")
        dep_lines.append("## Original LLM depth exit (preserved)\n")
        # rstrip to stabilize across repeated calls — without it, each
        # iteration's `"\n".join` would accumulate a trailing newline.
        dep_lines.append(llm_only.rstrip())
    try:
        dep.write_text("\n".join(dep_lines) + "\n", encoding="utf-8")
        synthesized.append("depth_exit.md")
    except OSError:
        pass

    return synthesized


def _estimate_codex_cost(model: str, input_tokens: int, output_tokens: int) -> float:
    """Estimate USD cost from Codex token counts."""
    inp_rate, out_rate = _CODEX_PRICING.get(model, (2.00, 8.00))
    return (input_tokens * inp_rate + output_tokens * out_rate) / 1_000_000


def _parse_codex_output(log_path: Path, model: str = "") -> dict:
    """Parse streaming JSONL from Codex subprocess output log.

    Codex --json emits one JSON event per line:
      - type=turn.completed → usage {input_tokens, output_tokens, ...}
      - type=item.completed + item.type=agent_message → output text
      - type=turn.failed / type=error → error info
    We accumulate usage across all turn.completed events.
    Model must be passed in since JSONL events don't include it.
    """
    result: dict[str, Any] = {"output": "", "cost_usd": 0.0, "duration_ms": 0,
                              "tokens": 0, "model": model}
    total_input = 0
    total_output = 0
    output_parts: list[str] = []
    try:
        text = log_path.read_text(encoding="utf-8", errors="replace")
        for line in text.splitlines():
            line = line.strip()
            if not line.startswith("{"):
                continue
            try:
                event = json.loads(line)
            except json.JSONDecodeError:
                continue
            etype = event.get("type", "")
            if etype == "error":
                result["error"] = event.get("message", "unknown_error")
                return result
            if etype == "turn.failed":
                err = event.get("error") or {}
                result["error"] = err.get("message", "turn_failed")
                return result
            if etype == "turn.completed":
                usage = event.get("usage") or {}
                total_input += usage.get("input_tokens", 0)
                total_output += usage.get("output_tokens", 0)
            if etype == "item.completed":
                item = event.get("item") or {}
                if item.get("type") == "agent_message":
                    msg = item.get("text", "")
                    if msg:
                        output_parts.append(msg)
    except OSError:
        pass
    result["output"] = "\n".join(output_parts)
    result["tokens"] = total_input + total_output
    result["input_tokens"] = total_input
    result["output_tokens"] = total_output
    result["cost_usd"] = _estimate_codex_cost(model, total_input, total_output)
    return result


# ── Process management ────────────────────────────────────────────────────

def _terminate_process_tree(proc: subprocess.Popen, grace_s: float = 5.0) -> None:
    """Terminate a phase subprocess and its children best-effort."""
    if sys.platform == "win32":
        try:
            subprocess.run(
                ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=max(1.0, grace_s + 0.5),
                check=False,
            )
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
        try:
            proc.wait(timeout=grace_s)
        except Exception:
            pass
        return

    try:
        os.killpg(proc.pid, signal.SIGTERM)
    except Exception:
        try:
            proc.terminate()
        except Exception:
            pass
    try:
        proc.wait(timeout=grace_s)
        return
    except Exception:
        pass
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass
    try:
        proc.wait(timeout=grace_s)
    except Exception:
        pass


_HALT_TERMINATE_GRACE_S = 2.0
_ACTIVE_WORKER_SESSIONS: set[Any] = set()
_ACTIVE_WORKER_SESSIONS_LOCK = threading.Lock()
_WORKER_CANCEL_CONTEXT = threading.local()


def _current_worker_cancel_token() -> threading.Event | None:
    token = getattr(_WORKER_CANCEL_CONTEXT, "token", None)
    return token if isinstance(token, threading.Event) else None


class _JoiningWorkerPool(concurrent.futures.ThreadPoolExecutor):
    """Executor that cannot return while a submitted worker remains active.

    Cancellation first closes provider-owned sessions and cancels work that
    never launched.  Context exit then joins every started worker so phase
    teardown, input restoration, and checkpointing cannot race a late model
    write or an unfinished WorkerTransaction.
    """

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self.cancel_event = threading.Event()

    def submit(self, fn: Any, /, *args: Any, **kwargs: Any) -> Any:
        cancel_event = self.cancel_event

        def run_bound() -> Any:
            _WORKER_CANCEL_CONTEXT.token = cancel_event
            try:
                return fn(*args, **kwargs)
            finally:
                _WORKER_CANCEL_CONTEXT.token = None

        return super().submit(run_bound)

    def request_cancel(self) -> None:
        self.cancel_event.set()

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        if exc_type is not None:
            self.request_cancel()
        try:
            self.shutdown(wait=True, cancel_futures=True)
        except TypeError:
            self.shutdown(wait=True)
        return False


def _register_active_worker_session(session: Any) -> None:
    try:
        with _ACTIVE_WORKER_SESSIONS_LOCK:
            _ACTIVE_WORKER_SESSIONS.add(session)
    except Exception:
        pass


def _unregister_active_worker_session(session: Any) -> None:
    try:
        with _ACTIVE_WORKER_SESSIONS_LOCK:
            _ACTIVE_WORKER_SESSIONS.discard(session)
    except Exception:
        pass


def _terminate_active_worker_sessions(grace_s: float = _HALT_TERMINATE_GRACE_S) -> None:
    try:
        with _ACTIVE_WORKER_SESSIONS_LOCK:
            sessions = list(_ACTIVE_WORKER_SESSIONS)
    except Exception:
        sessions = []
    for session in sessions:
        try:
            session.terminate(grace_s=grace_s)
        except Exception:
            pass


def _cancel_pending_worker_futures(
    pending_futs: set[concurrent.futures.Future],
    executor: concurrent.futures.ThreadPoolExecutor,
) -> None:
    """Cancel queued work, close started providers, and join all workers."""
    request_cancel = getattr(executor, "request_cancel", None)
    if callable(request_cancel):
        request_cancel()
    _terminate_active_worker_sessions()
    for fut in list(pending_futs):
        fut.cancel()
    try:
        executor.shutdown(wait=True, cancel_futures=True)
    except TypeError:
        executor.shutdown(wait=True)


def _hard_exit_after_user_stop(exit_code: int = 0) -> None:
    """Exit after explicit user stop without waiting on worker threads.

    The normal scheduler now joins every started worker.  This last-resort
    process exit remains only for the explicit UI stop boundary after active
    providers have been asked to terminate and the run lock is released.
    """
    try:
        display.graceful_stop.finalizing = True
        display.pause_toggle._suspended = True
        restore = getattr(display.pause_toggle, "restore_terminal", None)
        if callable(restore):
            restore()
    except Exception:
        pass
    try:
        _terminate_active_worker_sessions(grace_s=_HALT_TERMINATE_GRACE_S)
    except Exception:
        pass
    try:
        _release_run_lock()
    except Exception:
        pass
    try:
        sys.stdout.flush()
        sys.stderr.flush()
    except Exception:
        pass
    os._exit(exit_code)


def _backfill_legacy_unmarked_completed_phase(
    scratchpad: Path, phase: Phase
) -> list[str]:
    """Backfill the COMPLETE marker for an ALREADY-CHECKPOINTED supervised
    phase whose only gate failure is a content-valid artifact that lost its
    status marker (e.g. a worker whose final marker write was dropped by
    context compaction).

    On a fresh-audit scratchpad a marker-less artifact is classified
    IN_PROGRESS purely because the marker is absent, BEFORE its content is
    judged. For a phase already in ``checkpoint.completed`` that is a false
    rewind trigger: the phase finished, only the process signal is missing.

    This backfills ``<!-- PLAMEN_STATUS: COMPLETE -->`` for each such file
    ONLY when its CONTENT passes the same structural completeness gate the
    fresh-audit path uses. Returns the list of files marked. It is a strict
    no-op (returns ``[]``) when ANY expected row is genuinely incomplete
    (missing / stub / marked-but-IN_PROGRESS / structural_fail) so a real
    rewind still proceeds, and only acts on the supervised phases that carry
    legacy-unmarked classification (breadth, depth).
    """
    if phase.name == "breadth":
        rows = compute_breadth_row_statuses(scratchpad, phase)
    elif phase.name == "depth":
        rows = compute_depth_row_statuses(scratchpad, phase)
    else:
        return []
    if not rows:
        return []
    legacy_candidates: list[str] = []
    for row in rows:
        status = row.get("status")
        if status == "complete":
            continue
        reasons = row.get("reasons") or []
        # Only marker-less-on-fresh-audit rows are eligible. Any other
        # non-complete status (missing/stub/structural_fail, or a
        # marked-but-IN_PROGRESS file) is a genuine hole -> abort backfill.
        if status == "in_progress" and "legacy-unmarked on fresh audit" in reasons:
            legacy_candidates.append(str(row.get("name", "")))
        else:
            return []
    backfilled: list[str] = []
    for name in legacy_candidates:
        path = scratchpad / name
        ok, _why = _structural_completeness_ok(
            path,
            required_headings=(),
            placeholder_strings=("TODO", "FILL_ME", "<placeholder>"),
        )
        if not ok:
            # Content does not actually pass -> do not mask a real hole.
            return []
        try:
            with path.open("a", encoding="utf-8") as fh:
                fh.write("\n<!-- PLAMEN_STATUS: COMPLETE -->\n")
            backfilled.append(name)
        except Exception as exc:  # pragma: no cover - I/O failure path
            log.warning(
                "[resume] marker backfill failed for %s: %r", name, exc
            )
            return []
    return backfilled


def _reconcile_completed_checkpoint_artifacts(
    scratchpad: Path,
    project_root: str,
    checkpoint: Checkpoint,
    phases: list[Phase],
    mode: str,
    language: str = "",
    pipeline: str = "",
    backend: str = "",
) -> list[str]:
    """Rewind completed checkpoint entries whose artifacts no longer pass.

    Resume safety is a contract between `_v2_checkpoint.json` and the current
    phase graph. A completed phase is only skippable if its active artifact
    gate still passes. When an earlier completed phase is invalid, every
    downstream completed phase is also unsafe because it may have consumed the
    stale or missing output.
    """
    active = [phase for phase in phases if mode in phase.modes]
    active_names = {phase.name for phase in active}
    unknown = checkpoint.validate_phase_names(active_names)
    if unknown:
        raise RuntimeError(
            "checkpoint references phases outside the active graph: "
            + ", ".join(sorted(unknown))
        )

    original_completed = list(checkpoint.completed or [])
    first_invalid_idx: int | None = None
    first_missing: list[str] = []
    completed_names = set(checkpoint.completed or [])
    first_hole_idx: int | None = None
    for idx, phase in enumerate(active):
        if phase.name not in completed_names:
            if first_hole_idx is None:
                first_hole_idx = idx
            continue
        if first_hole_idx is not None:
            first_invalid_idx = first_hole_idx
            first_missing = [
                "checkpoint completion is not prefix-closed: "
                f"{phase.name} is completed after incomplete phase "
                f"{active[first_hole_idx].name}"
            ]
            log.warning("[resume] %s", first_missing[0])
            break

    # P0-Z: shape-valid output is not fresh merely because its filename still
    # exists.  Recompute every exact typed input receipt before honoring phase
    # completion, invalidate its transitive typed consumers, and preserve only
    # siblings whose own input denominator proves independence.  During the
    # sidecar migration an untyped downstream phase is not assumed independent:
    # the repair conservatively falls back to the legacy suffix rewind there.
    semantic_removed: list[str] = []
    if checkpoint.run_id:
        ledger_path = Path(scratchpad) / "_artifact_state.json"
        mutation_path = Path(scratchpad) / "_semantic_mutations.json"
        if ledger_path.is_file() or mutation_path.is_file():
            semantic_reason = "INPUT_DRIFT"
            semantic_plan: dict[str, Any] | None = None
            invalidated_keys: list[str] = []
            cross_run_keys: list[str] = []
            coverage_fallback: list[str] = []
            recovered_mutation_ids: list[str] = []
            mutation_event_ids_to_ack: list[str] = []
            marker_repair_event_ids: list[str] = []
            mutation_quarantine_reason = ""
            try:
                recover_armed_semantic_mutations(
                    Path(scratchpad), Path(project_root),
                    run_id=str(checkpoint.run_id),
                )
                all_mutations = semantic_mutation_events(Path(scratchpad))
                known_event_ids = {
                    str(row.get("event_id") or "") for row in all_mutations
                }
                if any(
                    identity not in known_event_ids
                    for identity in checkpoint.semantic_mutation_acks
                ):
                    raise ArtifactLedgerError(
                        "checkpoint acknowledges an absent semantic mutation"
                    )
                recovered_mutations = []
                for row in all_mutations:
                    event_id = str(row.get("event_id") or "")
                    status = str(row.get("status") or "")
                    checkpoint_ack = checkpoint.semantic_mutation_acks.get(
                        event_id, ""
                    )
                    authority_digest = semantic_mutation_authority_digest(row)
                    if status == "NO_CHANGE":
                        if checkpoint_ack:
                            raise ArtifactLedgerError(
                                "NO_CHANGE mutation unexpectedly has checkpoint authority"
                            )
                        continue
                    if checkpoint_ack:
                        if checkpoint_ack != authority_digest:
                            raise ArtifactLedgerError(
                                "semantic mutation/checkpoint acknowledgement mismatch"
                            )
                        if not row.get("checkpoint_reconciled"):
                            marker_repair_event_ids.append(event_id)
                        continue
                    if row.get("checkpoint_reconciled"):
                        raise ArtifactLedgerError(
                            "semantic mutation self-ack lacks checkpoint authority"
                        )
                    recovered_mutations.append(row)
                recovered_mutation_ids = [
                    str(row.get("event_id") or "")
                    for row in recovered_mutations
                    if row.get("event_id")
                ]
                mutation_event_ids_to_ack = [
                    str(row.get("event_id") or "")
                    for row in recovered_mutations
                    if row.get("status") == "INVALIDATION_APPLIED"
                ]
                # Recovery itself can apply the dependency invalidation before
                # the ordinary drift scan runs.  Carry those exact descendants
                # forward rather than relying on the second scan to rediscover
                # an already-staled work unit.
                invalidated_keys = sorted({
                    str(key)
                    for row in recovered_mutations
                    for key in (row.get("invalidated_work_unit_keys") or ())
                    if str(key)
                })
                drift = detect_semantic_input_drift(
                    Path(scratchpad), Path(project_root),
                    run_id=str(checkpoint.run_id),
                )
                cross_run_keys = list(drift.get("cross_run_work_unit_keys") or [])
                changed = list(drift.get("changed_input_identities") or [])
                if changed:
                    ledger = read_artifact_ledger(Path(scratchpad))
                    semantic_plan = semantic_dependency_invalidation_plan(
                        ledger, changed, run_id=str(checkpoint.run_id),
                    )
                    apply_semantic_invalidation(
                        Path(scratchpad), semantic_plan,
                        run_id=str(checkpoint.run_id),
                    )
                    invalidated_keys = sorted({
                        *invalidated_keys,
                        *(
                            semantic_plan.get("invalidated_work_unit_keys")
                            or []
                        ),
                    })

                def _phase_from_key(key: str) -> str:
                    parts = str(key).split("/")
                    return parts[4] if len(parts) == 6 else ""

                invalidated_phases = {
                    _phase_from_key(key) for key in invalidated_keys
                } - {""}
                cross_run_phases = {
                    _phase_from_key(key) for key in cross_run_keys
                } - {""}
                remove_names = set(invalidated_phases) | set(cross_run_phases)

                foreign_mutations = [
                    row for row in recovered_mutations
                    if row.get("run_id") != checkpoint.run_id
                ]
                if foreign_mutations:
                    remove_names.update(original_completed)
                    coverage_fallback = list(original_completed)
                    semantic_reason = "CROSS_RUN_SEMANTIC_MUTATION"
                    if any(row.get("status") == "ARMED" for row in foreign_mutations):
                        mutation_quarantine_reason = (
                            "foreign ARMED semantic mutation was disposed by full rewind"
                        )

                changed_without_typed_descendants = any(
                    row.get("status") == "INVALIDATION_APPLIED"
                    and not row.get("invalidated_work_unit_keys")
                    and row.get("run_id") == checkpoint.run_id
                    for row in recovered_mutations
                )
                if changed_without_typed_descendants and not remove_names:
                    # The durable arm proves that a semantic source changed,
                    # but a missing/legacy dependency ledger cannot prove which
                    # completed descendants are independent.  Preserve the
                    # bytes and use the safe migration fallback: re-run all
                    # completed phases instead of silently accepting stale work.
                    remove_names.update(original_completed)
                    coverage_fallback = list(original_completed)
                    semantic_reason = "MUTATION_WITHOUT_TYPED_DESCENDANTS"

                if remove_names:
                    ledger = read_artifact_ledger(Path(scratchpad))
                    units = ledger.get("work_units", {})
                    exact_input_phases: set[str] = set()
                    unbound_phases: set[str] = set()
                    if isinstance(units, dict):
                        for key, unit in units.items():
                            if not isinstance(unit, dict):
                                continue
                            phase_name = _phase_from_key(str(key))
                            if not phase_name or unit.get("run_id") != checkpoint.run_id:
                                continue
                            bindings = unit.get("input_bindings")
                            if isinstance(bindings, dict) and bindings:
                                exact_input_phases.add(phase_name)
                            elif phase_name:
                                unbound_phases.add(phase_name)

                    positions = {
                        phase.name: idx for idx, phase in enumerate(active)
                    }
                    roots = [positions[name] for name in remove_names if name in positions]
                    if roots:
                        first_root = min(roots)
                        # A phase with any output-only compatibility work unit
                        # lacks complete input-denominator authority.  Once one
                        # appears downstream of a changed stage, use the safe
                        # legacy suffix repair from that boundary.
                        for phase in active[first_root + 1:]:
                            if phase.name not in completed_names or phase.name in remove_names:
                                continue
                            if (
                                phase.name not in exact_input_phases
                                or phase.name in unbound_phases
                            ):
                                coverage_fallback = [
                                    later.name for later in active[
                                        positions[phase.name]:
                                    ]
                                ]
                                remove_names.update(coverage_fallback)
                                semantic_reason = "INPUT_DRIFT_WITH_UNTYPED_DESCENDANT"
                                break

                if remove_names:
                    semantic_removed = [
                        name for name in original_completed if name in remove_names
                    ]
            except ArtifactLedgerError as exc:
                # A corrupt semantic graph has no authority to bless old output.
                # Preserve the bytes, record the reason, and repair through the
                # ordinary phase runner instead of archiving/resetting the run.
                semantic_reason = f"SEMANTIC_LEDGER_INVALID:{type(exc).__name__}:{exc}"
                semantic_removed = list(original_completed)
                invalidated_keys = []
                cross_run_keys = []
                mutation_quarantine_reason = semantic_reason

            if semantic_removed:
                remove_set = set(semantic_removed)
                removed_degraded = [
                    name for name in checkpoint.degraded if name in remove_set
                ]
                checkpoint.completed = [
                    name for name in checkpoint.completed if name not in remove_set
                ]
                checkpoint.degraded = [
                    name for name in checkpoint.degraded if name not in remove_set
                ]
                checkpoint.phase_commits = {
                    key: commit for key, commit in checkpoint.phase_commits.items()
                    if commit.phase_name not in remove_set
                }
                for name in removed_degraded:
                    checkpoint.clear_degraded_sentinel(Path(scratchpad), name)
                if checkpoint.rate_limited_at in remove_set:
                    checkpoint.rate_limited_at = None
                _atomic_driver_json_record(
                    Path(scratchpad) / "semantic_resume_invalidation.json",
                    {
                        "schema": "plamen.semantic_resume_invalidation.v1",
                        "run_id": checkpoint.run_id,
                        "reason": semantic_reason,
                        "removed_completed_phases": semantic_removed,
                        "invalidated_work_unit_keys": sorted(invalidated_keys),
                        "cross_run_work_unit_keys": sorted(cross_run_keys),
                        "coverage_fallback_phases": coverage_fallback,
                        "recovered_mutation_event_ids": recovered_mutation_ids,
                        "plan_digest": (
                            semantic_plan.get("plan_digest", "")
                            if isinstance(semantic_plan, dict) else ""
                        ),
                    },
                )
                completed_names = set(checkpoint.completed or [])
                log.warning(
                    "[resume] semantic freshness invalidated completed phase(s): %s",
                    ", ".join(semantic_removed),
                )

            if mutation_quarantine_reason:
                # Clear stale checkpoint acknowledgements before preserving and
                # replacing the invalid/foreign mutation ledger.  The repaired
                # checkpoint is durable first; a crash can only repeat repair.
                checkpoint.semantic_mutation_acks = {}
                checkpoint.save(Path(scratchpad))
                try:
                    quarantine_invalid_semantic_mutation_ledger(
                        Path(scratchpad),
                        reconciled_by_run_id=str(checkpoint.run_id),
                        reason=mutation_quarantine_reason,
                    )
                except ArtifactLedgerError as exc:
                    log.warning(
                        "[resume] semantic mutation quarantine retained for "
                        "safe replay: %s",
                        exc,
                    )
            elif mutation_event_ids_to_ack:
                # Durability order is deliberate: repaired checkpoint first,
                # then event acknowledgement.  A crash between the two causes
                # a harmless repeated repair; the reverse order could bless a
                # stale checkpoint after the finalize-to-rewind crash window.
                all_by_id = {
                    str(row.get("event_id") or ""): row
                    for row in semantic_mutation_events(Path(scratchpad))
                }
                checkpoint.semantic_mutation_acks.update({
                    event_id: semantic_mutation_authority_digest(
                        all_by_id[event_id]
                    )
                    for event_id in mutation_event_ids_to_ack
                })
                checkpoint.save(Path(scratchpad))
                try:
                    acknowledge_semantic_mutations(
                        Path(scratchpad),
                        mutation_event_ids_to_ack,
                        reconciled_by_run_id=str(checkpoint.run_id),
                    )
                except ArtifactLedgerError as exc:
                    log.warning(
                        "[resume] semantic mutation acknowledgement retained "
                        "for safe replay: %s",
                        exc,
                    )
            elif marker_repair_event_ids:
                try:
                    acknowledge_semantic_mutations(
                        Path(scratchpad),
                        marker_repair_event_ids,
                        reconciled_by_run_id=str(checkpoint.run_id),
                    )
                except ArtifactLedgerError as exc:
                    log.warning(
                        "[resume] semantic mutation marker repair retained: %s",
                        exc,
                    )

    for idx, phase in enumerate(active):
        if first_invalid_idx is not None:
            break
        if phase.name not in checkpoint.completed:
            continue
        semantic_config = {
            "mode": mode,
            "language": language,
            "pipeline": pipeline,
            "cli_backend": backend,
            "_run_id": str(checkpoint.run_id),
        }
        missing = _resume_semantic_issues(
            phase,
            semantic_config,
            scratchpad,
            project_root,
        )
        if missing and scratchpad_is_fresh_audit(scratchpad):
            # A completed-and-checkpointed phase must NOT be rewound merely
            # because a content-valid artifact lost its COMPLETE marker.
            # Backfill the marker for legacy-unmarked content-valid rows,
            # then re-validate. Genuine holes leave `missing` non-empty.
            backfilled = _backfill_legacy_unmarked_completed_phase(
                scratchpad, phase
            )
            if backfilled:
                missing = _resume_semantic_issues(
                    phase,
                    semantic_config,
                    scratchpad,
                    project_root,
                )
                if not missing:
                    log.info(
                        "[resume] completed phase %s: backfilled COMPLETE "
                        "marker for content-valid artifact(s) instead of "
                        "rewinding: %s",
                        phase.name,
                        ", ".join(backfilled),
                    )
        if missing:
            first_invalid_idx = idx
            first_missing = list(missing)
            log.warning(
                "[resume] completed phase %s failed contract reconciliation: %s",
                phase.name,
                ", ".join(first_missing),
            )
            break

    if first_invalid_idx is None:
        return semantic_removed

    rewind_names = {phase.name for phase in active[first_invalid_idx:]}
    removed = [name for name in checkpoint.completed if name in rewind_names]
    removed_degraded = [name for name in checkpoint.degraded if name in rewind_names]
    checkpoint.completed = [name for name in checkpoint.completed if name not in rewind_names]
    checkpoint.degraded = [name for name in checkpoint.degraded if name not in rewind_names]
    for name in removed_degraded:
        checkpoint.clear_degraded_sentinel(scratchpad, name)
    if checkpoint.rate_limited_at in rewind_names:
        checkpoint.rate_limited_at = None
    return list(dict.fromkeys(semantic_removed + removed))


def _rewind_checkpoint_semantic_work_units(
    checkpoint: Checkpoint,
    scratchpad: Path,
    work_unit_keys: list[str] | tuple[str, ...],
) -> list[str]:
    """Remove only phase completions named by exact invalidated work units."""
    phases = {
        parts[4]
        for key in work_unit_keys
        for parts in [str(key).split("/")]
        if len(parts) == 6 and parts[4]
    }
    removed = [name for name in checkpoint.completed if name in phases]
    if not removed:
        return []
    remove_set = set(removed)
    checkpoint.completed = [
        name for name in checkpoint.completed if name not in remove_set
    ]
    removed_degraded = [
        name for name in checkpoint.degraded if name in remove_set
    ]
    checkpoint.degraded = [
        name for name in checkpoint.degraded if name not in remove_set
    ]
    checkpoint.phase_commits = {
        key: commit for key, commit in checkpoint.phase_commits.items()
        if commit.phase_name not in remove_set
    }
    for name in removed_degraded:
        checkpoint.clear_degraded_sentinel(Path(scratchpad), name)
    if checkpoint.rate_limited_at in remove_set:
        checkpoint.rate_limited_at = None
    return removed


_STALE_DYNAMIC_REPORT_PHASE_RE = re.compile(
    r"^report(?:_body_writer)?_(?:critical_high|medium|low_info)_[a-z]$"
)


def _prune_stale_dynamic_report_checkpoint_entries(
    checkpoint: Checkpoint,
    scratchpad: Path,
    active_phase_names: set[str],
) -> list[str]:
    """Remove every projection of report shards retired by manifest refresh.

    The typed commit is the semantic authority.  Removing only the legacy
    ``completed``/``degraded`` arrays leaves a stale commit that can later be
    re-projected as completed debt.  Derive the stale set from all three
    projections and retire them atomically in the in-memory checkpoint.
    """

    candidates = {
        *checkpoint.completed,
        *checkpoint.degraded,
        *(commit.phase_name for commit in checkpoint.phase_commits.values()),
    }
    stale = {
        name
        for name in candidates
        if _STALE_DYNAMIC_REPORT_PHASE_RE.match(name)
        and name not in active_phase_names
    }
    if not stale:
        return []
    checkpoint.completed = [
        name for name in checkpoint.completed if name not in stale
    ]
    checkpoint.degraded = [
        name for name in checkpoint.degraded if name not in stale
    ]
    checkpoint.phase_commits = {
        key: commit
        for key, commit in checkpoint.phase_commits.items()
        if commit.phase_name not in stale
    }
    for name in stale:
        checkpoint.clear_degraded_sentinel(Path(scratchpad), name)
    return sorted(stale)


def _rewind_late_verification_descendants(
    checkpoint: Checkpoint,
    scratchpad: Path,
    phases: list[Phase],
    mode: str,
    pipeline: str,
) -> list[str]:
    """Invalidate the aggregate and its active descendants, never verify shards.

    A late queue identity changes the aggregate/skeptic/cross-batch/report
    denominator but does not invalidate evidence already produced for unrelated
    shard assignments.  Every active descendant is deliberately marked
    degraded until its normal runner commits fresh output; this also blocks
    generic artifact-recovery from blessing an uncheckpointed, shape-valid
    partial projection from the old denominator.
    """
    aggregate_name = (
        "verify_aggregate" if str(pipeline).lower() == "l1"
        else "sc_verify_aggregate"
    )
    active_names = [phase.name for phase in phases if mode in phase.modes]
    if aggregate_name not in active_names:
        return []
    suffix_names = active_names[active_names.index(aggregate_name):]
    suffix = set(suffix_names)
    removed = [name for name in checkpoint.completed if name in suffix]
    remove_set = set(removed)
    checkpoint.completed = [
        name for name in checkpoint.completed if name not in remove_set
    ]
    # Also arm not-yet-checkpointed descendants. They may have shape-valid
    # partial artifacts from an interrupted phase; generic artifact recovery
    # must not certify those bytes against the old queue denominator.
    for name in suffix_names:
        if name not in checkpoint.degraded:
            checkpoint.degraded.append(name)
    checkpoint.phase_commits = {
        key: commit for key, commit in checkpoint.phase_commits.items()
        if commit.phase_name not in suffix
    }
    if checkpoint.rate_limited_at in suffix:
        checkpoint.rate_limited_at = None
    checkpoint.save(Path(scratchpad))
    return removed


def _write_late_unverified_fallback(
    scratchpad: Path,
    rows: list[tuple[str, dict[str, str]]],
    *,
    owner_phase: str,
) -> list[str]:
    """Last-resort, severity-preserving delivery for failed late recovery.

    This is explicitly not verification proof.  It exists so a provider,
    prompt, or filesystem recovery failure cannot make completed shard gates
    erase the newly active identity or force unrelated shard reruns.
    """
    written: list[str] = []
    stamp = datetime.now(timezone.utc).isoformat()
    for fid, row in rows:
        path = Path(scratchpad) / f"verify_{fid}.md"
        severity = str(row.get("severity") or "Unknown").strip() or "Unknown"
        title = str(row.get("title") or fid).strip() or fid
        location = str(row.get("location") or "Unresolved").strip() or "Unresolved"
        mechanism = str(
            row.get("mechanism") or row.get("description")
            or "Semantic mechanism was not projected by the source authority."
        ).strip()
        evidence = str(
            row.get("evidence") or row.get("evidence_pointer")
            or row.get("primary artifact") or "Unresolved"
        ).strip()
        source_digest = str(row.get("source_candidate_digest") or "UNBOUND").strip()
        source_identity = str(
            row.get("source_work_item_id") or row.get("source_identity") or "UNBOUND"
        ).strip()
        try:
            path.write_text(
                f"# Verification: {fid}\n\n"
                f"**Finding ID**: {fid}\n"
                f"**Title**: {title}\n"
                f"**Severity**: {severity}\n"
                f"**Location**: {location}\n\n"
                f"**Source Candidate Digest**: {source_digest}\n"
                f"**Source Identity**: {source_identity}\n\n"
                "**Verdict**: UNVERIFIED\n"
                "**Evidence Tag**: [CODE-TRACE]\n"
                "**Preferred Tag**: [CODE-TRACE]\n\n"
                "## VERIFICATION NOT EXECUTED - HUMAN REVIEW REQUIRED\n\n"
                "The driver recovered this persisted inventory candidate after "
                "ordinary verifier shards had completed, but its bounded "
                "recovery verifier did not produce an output. This artifact is "
                "unresolved pipeline debt, not proof and not an exclusion.\n\n"
                f"- Recovery state: UNVERIFIED/UNRESOLVED\n"
                f"- Original severity preserved: {severity}\n"
                f"- Public retention: BODY_OR_HUMAN_REVIEW\n"
                f"- Timestamp: {stamp}\n\n"
                "## Exact unresolved semantic claim\n\n"
                f"- Mechanism: {mechanism}\n"
                f"- Evidence: {evidence}\n\n"
                "Human reviewer must independently assess the candidate.\n",
                encoding="utf-8",
            )
        except Exception as exc:
            _append_phase_io_debt(
                Path(scratchpad),
                owner_phase,
                "LATE_VERIFICATION_FALLBACK_WRITE_DEBT",
                f"{fid}: {type(exc).__name__}: {exc}",
            )
            continue
        written.append(fid)
    return written


def _late_verify_output_requires_recovery(scratchpad: Path, finding_id: str) -> bool:
    """True when the canonical output is absent or only an unresolved stub."""
    path = Path(scratchpad) / f"verify_{finding_id}.md"
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return True
    if len(text.encode("utf-8")) < 100:
        return True
    return bool(re.search(
        r"(?im)^\*\*Verdict\*\*:\s*UNVERIFIED\b|"
        r"VERIFICATION NOT EXECUTED|STUB-RECOVERED",
        text,
    ))


def _p0o_scope_recovery_output_issues(
    scratchpad: Path,
    unit: Mapping[str, Any],
) -> list[str]:
    """Validate exact P0-O recovery outputs without granting queue authority.

    These outputs close only the grouped proof-scope repair obligation. They do
    not rewrite the immutable primary QueueWorkPlan and cannot self-certify a
    report disposition. The ordinary aggregate/report consumers receive the
    driver-owned recovery status as an additive supplement.
    """
    root = Path(scratchpad)
    issues: list[str] = []
    expected_ids = [str(row.get("finding id") or "") for row in unit["rows"]]
    expected_names = [
        output_name
        for fid in expected_ids
        for output_name in (
            f"verify_{fid}.md",
            f"verify_{fid}.severity_proposal.json",
        )
    ]
    if expected_names != list(unit.get("expected_output_files") or []):
        return [f"{unit['unit_id']}: expected output ownership drift"]
    for fid in expected_ids:
        name = f"verify_{fid}.md"
        case_issue = _canonical_output_case_issue(root, name)
        if case_issue:
            issues.append(case_issue)
            continue
        path = root / name
        if not path.is_file():
            issues.append(f"{fid}: grouped proof-scope recovery output missing")
            continue
        try:
            raw = path.read_bytes()
            text = raw.decode("utf-8", errors="replace")
        except OSError as exc:
            issues.append(f"{fid}: recovery output unreadable: {exc}")
            continue
        if len(raw) < 100:
            issues.append(f"{fid}: recovery output is below 100-byte floor")
        if not _field_from_markdown(text, ("Severity", "Final Severity")):
            issues.append(f"{fid}: recovery output lacks Severity")
        if not _field_from_markdown(text, ("Evidence Tag", "Evidence Tags")):
            issues.append(f"{fid}: recovery output lacks Evidence Tag")
        if not _field_from_markdown(text, ("Verdict", "Final Verdict")):
            issues.append(f"{fid}: recovery output lacks Verdict")
        if re.search(
            r"(?im)^\*\*Verdict\*\*:\s*UNVERIFIED\b|"
            r"VERIFICATION NOT EXECUTED|STUB-RECOVERED",
            text,
        ):
            issues.append(f"{fid}: recovery output is an unresolved fallback stub")
        proposal_path = root / f"verify_{fid}.severity_proposal.json"
        if not proposal_path.is_file():
            issues.append(f"{fid}: recovery severity proposal missing")
            continue
        try:
            proposal = parse_severity_proposal(proposal_path.read_bytes())
        except Exception as exc:
            issues.append(
                f"{fid}: recovery severity proposal invalid: "
                f"{type(exc).__name__}: {exc}"
            )
            continue
        if proposal.get("candidate_id") != fid:
            issues.append(f"{fid}: recovery severity proposal identity mismatch")
        if proposal.get("constituent_ids") != [fid]:
            issues.append(f"{fid}: recovery severity proposal scope must be exact")
    return list(dict.fromkeys(issues))


def _run_p0o_scope_recovery(
    scratchpad: Path,
    config: dict[str, Any],
) -> dict[str, list[str]]:
    """Consume P0-O repair debt through bounded late-recovery workers.

    Work is planned in immutable units of at most four exact constituent IDs.
    Each unit is armed before launch and receives a driver-owned, byte-bound
    receipt after output validation. An ARMED crash window is recovered without
    a duplicate launch; invalid/missing output becomes visible debt and leaves
    the pre-demotion severity intact. The primary queue and QueueWorkPlan are
    never mutated inside or after aggregate.
    """
    root = Path(scratchpad)
    result: dict[str, list[str]] = {
        "attempted": [],
        "recovered": [],
        "unresolved": [],
        "changed": [],
        "issues": [],
    }
    if not (root / "poc_demotion_scope_repair.json").is_file():
        return result
    try:
        plan = build_scope_recovery_plan(root, max_findings_per_unit=4)
    except Exception as exc:
        detail = f"P0-O recovery planning failed: {type(exc).__name__}: {exc}"
        result["issues"].append(detail)
        _append_phase_io_debt(
            root,
            "sc_verify_aggregate" if config.get("pipeline") != "l1" else "verify_aggregate",
            "GROUPED_POC_RECOVERY_PLANNING_DEBT",
            detail,
        )
        return result

    for unit in plan.get("units") or []:
        receipt, receipt_issues = _validate_p0o_recovery_unit_receipt(
            root, plan, unit
        )
        if receipt and not receipt_issues and receipt.get("status") == "COMPLETED":
            result["recovered"].extend(
                str(row["finding id"]) for row in unit["rows"]
            )
            continue
        if receipt and not receipt_issues and receipt.get("status") == "DEBT":
            ids = [str(row["finding id"]) for row in unit["rows"]]
            result["unresolved"].extend(ids)
            result["issues"].extend(
                str(issue) for issue in receipt.get("issues") or []
            )
            # A driver-owned DEBT receipt is a terminal, visible disposition
            # for this exact attempt. Do not rewrite it, relaunch it, or rewind
            # descendants again on an unchanged resume.
            continue

        paths = _p0o_recovery_unit_paths(root, str(unit["unit_id"]))
        try:
            attempt_preexisted = paths["attempt"].is_file()
            attempt = _write_p0o_recovery_attempt(root, plan, unit)
            _write_queue_subset_manifest(paths["manifest"], list(unit["rows"]))
            before = attempt.get("outputs_before_launch") or {}
            preexisting_unbound = [
                name for name, state in before.items()
                if isinstance(state, dict) and state.get("exists")
            ]
            output_issues = _p0o_scope_recovery_output_issues(root, unit)
            if attempt_preexisted:
                # Crash recovery: the immutable ARMED intent proves this exact
                # unit launched. Valid current bytes may be receipted; invalid
                # bytes remain debt. Never launch the same intent twice.
                issues = list(output_issues)
            elif preexisting_unbound:
                issues = [
                    "pre-existing unbound output(s) cannot be adopted: "
                    + ", ".join(sorted(preexisting_unbound))
                ]
            else:
                result["attempted"].append(str(unit["unit_id"]))
                recovery_config = dict(config)
                recovery_config["_verification_recovery_kind"] = "GROUPED_SCOPE_REPAIR"
                _run_verify_recovery_shard(
                    recovery_config,
                    [
                        (str(row["finding id"]), dict(row))
                        for row in unit["rows"]
                    ],
                )
                # Preserve the exact manifest/prompt bytes beside the unit;
                # the legacy global recovery paths may be overwritten by the
                # next bounded unit but are never receipt authority.
                global_manifest = root / "verification_queue_recovery.md"
                if global_manifest.is_file():
                    shutil.copy2(global_manifest, paths["manifest"])
                global_prompt = root / "_prompt_verify_recovery.attempt1.md"
                if global_prompt.is_file():
                    shutil.copy2(global_prompt, paths["prompt"])
                issues = _p0o_scope_recovery_output_issues(root, unit)
            prompt_hash = (
                hashlib.sha256(paths["prompt"].read_bytes()).hexdigest()
                if paths["prompt"].is_file()
                else None
            )
            status = "COMPLETED" if not issues else "DEBT"
            _write_p0o_recovery_unit_receipt(
                root,
                plan,
                unit,
                status=status,
                issues=issues,
                prompt_sha256=prompt_hash,
            )
            ids = [str(row["finding id"]) for row in unit["rows"]]
            if status == "COMPLETED":
                result["recovered"].extend(ids)
            else:
                result["unresolved"].extend(ids)
                result["issues"].extend(issues)
            result["changed"].extend(ids)
        except Exception as exc:
            ids = [str(row["finding id"]) for row in unit["rows"]]
            result["unresolved"].extend(ids)
            detail = (
                f"{unit['unit_id']} grouped PoC recovery failed: "
                f"{type(exc).__name__}: {exc}"
            )
            result["issues"].append(detail)
            try:
                if paths["attempt"].is_file():
                    _write_p0o_recovery_unit_receipt(
                        root,
                        plan,
                        unit,
                        status="DEBT",
                        issues=(detail,),
                    )
            except Exception:
                pass

    status = _write_p0o_recovery_status(root, plan)
    result["recovered"] = list(dict.fromkeys(
        [*result["recovered"], *status.get("recovered_constituent_ids", [])]
    ))
    result["unresolved"] = list(dict.fromkeys(
        [*result["unresolved"], *status.get("unresolved_constituent_ids", [])]
    ))
    if result["unresolved"]:
        detail = (
            "grouped PoC proof-scope recovery remains unresolved at "
            "pre-demotion severity: " + ", ".join(result["unresolved"])
        )
        _append_phase_io_debt(
            root,
            "sc_verify_aggregate" if config.get("pipeline") != "l1" else "verify_aggregate",
            "GROUPED_POC_RECOVERY_UNRESOLVED",
            detail,
        )
    return result


def _repair_late_verification_backfill(
    scratchpad: Path,
    config: dict[str, Any],
    checkpoint: Checkpoint,
    phases: list[Phase],
    mode: str,
) -> dict[str, list[str]]:
    """Actively route and boundedly verify resume-detected queue dropouts.

    Before any verifier shard has completed, this is ordinary active queue
    repair.  After shards complete, only the late identities are assigned to a
    recovery manifest; existing shard artifacts remain untouched.  Recovery
    failure produces explicit UNVERIFIED/HUMAN_REVIEW debt at the upstream
    severity.  Exact resume is a no-op because active routing closes the
    unrouted identity set on the first call.
    """
    root = Path(scratchpad)
    aggregate_name = (
        "verify_aggregate"
        if str(config.get("pipeline") or "sc").lower() == "l1"
        else "sc_verify_aggregate"
    )
    result: dict[str, list[str]] = {
        "backfilled": [],
        "recovered": [],
        "unresolved": [],
        "rewound": [],
    }
    # P0-O is a post-aggregate proof-scope obligation. Consume it on the next
    # startup through bounded late-recovery units without mutating the already
    # committed primary queue/work-plan transaction.
    p0o = _run_p0o_scope_recovery(root, config)
    if (root / "poc_demotion_scope_repair.json").is_file():
        result["grouped_poc_recovered"] = list(p0o["recovered"])
        result["grouped_poc_unresolved"] = list(p0o["unresolved"])
    if successor_projection_present(root):
        # The live T0--T8 publication is immutable transaction output.  Legacy
        # Markdown/JSON backfill would create a second, unauthenticated queue
        # while leaving verification_queue.work_items.json and its receipt
        # unchanged.  Artifact reconciliation below owns replay of a stale or
        # incomplete publication.
        if p0o["changed"]:
            result["rewound"] = _rewind_late_verification_descendants(
                checkpoint,
                root,
                phases,
                mode,
                str(config.get("pipeline") or "sc"),
            )
        return result

    backfilled = backfill_unrouted_inventory_into_queue(root)
    result["backfilled"] = list(backfilled)
    if not backfilled:
        if p0o["changed"]:
            result["rewound"] = _rewind_late_verification_descendants(
                checkpoint,
                root,
                phases,
                mode,
                str(config.get("pipeline") or "sc"),
            )
        return result

    completed = set(checkpoint.completed or [])
    shard_names = set(L1_VERIFY_PHASE_NAMES) | set(SC_VERIFY_PHASE_NAMES)
    if not (completed & shard_names):
        return result

    wanted = set(backfilled)
    late_rows = [
        (str(row.get("finding id") or "").strip(), row)
        for row in parse_verification_queue_rows(root)
        if str(row.get("finding id") or "").strip() in wanted
    ]
    order = {fid: idx for idx, fid in enumerate(backfilled)}
    late_rows.sort(key=lambda item: order.get(item[0], len(order)))
    manifest_ready = True
    try:
        _write_queue_subset_manifest(
            root / "verification_queue_recovery.md",
            [row for _fid, row in late_rows],
        )
    except Exception as exc:
        manifest_ready = False
        _append_phase_io_debt(
            root,
            aggregate_name,
            "LATE_VERIFICATION_MANIFEST_DEBT",
            f"{type(exc).__name__}: {exc}",
        )

    missing = [
        (fid, row) for fid, row in late_rows
        if _late_verify_output_requires_recovery(root, fid)
    ]
    if missing and manifest_ready:
        try:
            recovery_config = dict(config)
            recovery_config["_verification_recovery_kind"] = "LATE_OPERATOR_CANDIDATE"
            _run_verify_recovery_shard(recovery_config, missing)
        except Exception as exc:
            _append_phase_io_debt(
                root,
                aggregate_name,
                "LATE_VERIFICATION_RECOVERY_DEBT",
                f"{type(exc).__name__}: {exc}",
            )

    # Trust files, not worker self-report.  A worker may return success without
    # writing one or more assigned outputs; those identities remain unresolved.
    unresolved_set = {
        fid for fid in wanted if _late_verify_output_requires_recovery(root, fid)
    }
    unresolved_rows = [
        (fid, row) for fid, row in late_rows if fid in unresolved_set
    ]
    if unresolved_rows:
        fallback_written = set(_write_late_unverified_fallback(
            root, unresolved_rows, owner_phase=aggregate_name
        ))
        unresolved_set |= {
            fid for fid, _row in unresolved_rows if fid not in fallback_written
        }
        result["unresolved"] = [
            fid for fid in backfilled if fid in unresolved_set
        ]
        _append_phase_io_debt(
            root,
            aggregate_name,
            "LATE_VERIFICATION_UNRESOLVED",
            "bounded recovery unavailable/failed for active candidate(s): "
            + ", ".join(result["unresolved"]),
        )

    result["recovered"] = [
        fid for fid in backfilled if fid not in set(result["unresolved"])
    ]

    # The aggregate is a deterministic projection; rebuild it now so even a
    # crash before the phase loop leaves the late identity visible.  Its
    # checkpoint plus all semantic descendants are still invalidated below.
    _generate_verify_core_if_missing(root)
    result["rewound"] = _rewind_late_verification_descendants(
        checkpoint,
        root,
        phases,
        mode,
        str(config.get("pipeline") or "sc"),
    )
    return result


def _promote_findings_with_semantic_invalidation(
    scratchpad: Path,
    config: dict[str, Any],
    checkpoint: Checkpoint,
    *,
    owner_phase: str = "semantic_mutation",
) -> list[str]:
    """Advance the canonical inventory pair, then invalidate consumers.

    ``findings_inventory.md``, ``finding_records.json``, and
    ``_id_ledger.json`` are three projections of the same allocated finding
    set.  A late additive promotion therefore arms all three before any write
    and regenerates the structured projection before finalizing the semantic
    successors.  Treating only the Markdown file as mutated leaves either the
    JSON projection or allocator ledger owned by a stale inventory generation
    and makes the next paired RMW boundary correctly fail closed.
    """
    scratchpad = Path(scratchpad)
    run_id = str(checkpoint.run_id or config.get("_run_id") or "").strip()
    project_root = Path(config.get("project_root") or scratchpad.parent)
    if not run_id:
        return _promote_depth_findings_to_inventory(scratchpad)
    events: list[Mapping[str, Any]] = []
    try:
        # Arm the derived projection first.  If its predecessor authority is
        # unavailable, no canonical inventory byte has been touched yet.
        for identity, kind in (
            (
                "scratchpad:_id_ledger.json",
                "FINDING_PROMOTION_ID_LEDGER",
            ),
            (
                "scratchpad:finding_records.json",
                "FINDING_PROMOTION_RECORDS",
            ),
            (
                "scratchpad:findings_inventory.md",
                "FINDING_PROMOTION",
            ),
        ):
            events.append(
                arm_semantic_mutation(
                    scratchpad,
                    project_root,
                    artifact_identity=identity,
                    mutation_kind=kind,
                    run_id=run_id,
                )
            )
    except ArtifactLedgerError as exc:
        # The promotion remains recall-additive.  If its transaction receipt
        # cannot arm, keep the new candidates but conservatively rewind every
        # already-completed phase after the current boundary.
        for event in _driver_semantic_mutation_finalize_order(events):
            _finalize_driver_semantic_mutation(
                scratchpad,
                config,
                checkpoint,
                event,
                owner_phase=owner_phase,
            )
        promoted = _promote_depth_findings_to_inventory(scratchpad)
        _append_phase_io_debt(
            scratchpad, owner_phase, "SEMANTIC_MUTATION_ARM_DEBT", str(exc)
        )
        active = list(config.get("_active_phase_names") or [])
        if owner_phase in active:
            suffix = set(active[active.index(owner_phase) + 1:])
            _rewind_checkpoint_semantic_work_units(
                checkpoint,
                scratchpad,
                [f"sc/core/unknown/claude/{name}/fallback" for name in suffix],
            )
            checkpoint.save(scratchpad)
        return promoted

    try:
        promoted = _promote_depth_findings_to_inventory(scratchpad)
        if promoted:
            inventory_raw = (
                scratchpad / "findings_inventory.md"
            ).read_bytes()
            records_raw = derive_preverify_finding_records_bytes(
                inventory_raw
            )
            _atomic_driver_bytes(
                scratchpad / "finding_records.json", records_raw
            )
    except Exception as exc:
        for event in _driver_semantic_mutation_finalize_order(events):
            _finalize_driver_semantic_mutation(
                scratchpad,
                config,
                checkpoint,
                event,
                owner_phase=owner_phase,
            )
        _append_phase_io_debt(
            scratchpad, owner_phase, "FINDING_PROMOTION_DEBT",
            f"{type(exc).__name__}: {exc}",
        )
        return []

    affected = tuple(promoted)
    for event in _driver_semantic_mutation_finalize_order(events):
        _finalize_driver_semantic_mutation(
            scratchpad,
            config,
            checkpoint,
            event,
            owner_phase=owner_phase,
            affected_record_ids=affected,
        )
    return promoted


def _finalize_driver_semantic_mutation(
    scratchpad: Path,
    config: Mapping[str, Any],
    checkpoint: Checkpoint,
    event: Mapping[str, Any],
    *,
    owner_phase: str,
    affected_record_ids: tuple[str, ...] = (),
) -> list[str]:
    """Finalize one armed driver mutation and durably reconcile consumers."""

    root = Path(scratchpad)
    run_id = str(checkpoint.run_id or config.get("_run_id") or "").strip()
    project_root = Path(str(config.get("project_root") or root.parent))
    if not run_id or not str(event.get("event_id") or ""):
        return ["semantic mutation finalization identity is missing"]
    try:
        finalized = finalize_semantic_mutation(
            root,
            project_root,
            str(event["event_id"]),
            run_id=run_id,
            affected_record_ids=affected_record_ids,
        )
        invalidated_keys = list(
            finalized.get("invalidated_work_unit_keys") or []
        )
        checkpoint_rewind_keys = _driver_semantic_checkpoint_rewind_keys(
            config,
            owner_phase=owner_phase,
            invalidated_work_unit_keys=invalidated_keys,
        )
        removed = _rewind_checkpoint_semantic_work_units(
            checkpoint, root, checkpoint_rewind_keys,
        )
        # Every changed event needs checkpoint authority, including coupled
        # sidecars whose own dependency fan-out is empty.  Keying this on the
        # invalidation list left those sidecars finalized-but-unacknowledged;
        # startup then treated them as an untyped crash and conservatively
        # rewound the entire completed run.
        if finalized.get("status") == "INVALIDATION_APPLIED":
            checkpoint.semantic_mutation_acks[str(finalized["event_id"])] = (
                semantic_mutation_authority_digest(finalized)
            )
            checkpoint.save(root)
            acknowledge_semantic_mutations(
                root,
                [str(finalized["event_id"])],
                reconciled_by_run_id=run_id,
            )
        if removed:
            log.warning(
                "[%s] semantic mutation invalidated completed consumer(s): %s",
                owner_phase,
                ", ".join(removed),
            )
        return []
    except (ArtifactLedgerError, OSError, RuntimeError, ValueError) as exc:
        issue = f"{type(exc).__name__}: {exc}"
        _append_phase_io_debt(
            root, owner_phase, "SEMANTIC_MUTATION_FINALIZE_DEBT", issue
        )
        return [issue]


def _driver_semantic_mutation_finalize_order(
    events: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    """Finalize the canonical inventory root before its coupled sidecars.

    All roots are armed before any write.  Publishing the root with the typed
    dependency fan-out first makes every crash prefix recoverable through that
    exact plan; the record and ID-ledger siblings can then contribute their
    independent lineage without creating an untyped-only recovery prefix.
    """

    priority = {
        "scratchpad:findings_inventory.md": 0,
        "scratchpad:finding_records.json": 1,
        "scratchpad:_id_ledger.json": 2,
    }
    return sorted(
        list(events),
        key=lambda event: (
            priority.get(str(event.get("artifact_identity") or ""), 10),
            str(event.get("event_id") or ""),
        ),
    )


def _driver_semantic_checkpoint_rewind_keys(
    config: Mapping[str, Any],
    *,
    owner_phase: str,
    invalidated_work_unit_keys: Sequence[str],
) -> list[str]:
    """Rewind only accepted consumers at/after the mutation owner boundary.

    A current downstream phase may intentionally advance an earlier canonical
    artifact under a journaled semantic-successor transaction.  Its historical
    producer/consumer receipts become stale, but the earlier phases still ran
    and their completion markers must remain prefix-closed.  Already accepted
    work at the owner or later boundary is not protected and is rewound.

    If the active graph or owner is unavailable, retain the conservative
    legacy behavior and return every typed invalidation key.
    """

    active = [str(value) for value in config.get("_active_phase_names", ())]
    if owner_phase not in active:
        return [str(value) for value in invalidated_work_unit_keys]
    positions = {name: index for index, name in enumerate(active)}
    owner_index = positions[owner_phase]
    selected: list[str] = []
    for raw_key in invalidated_work_unit_keys:
        key = str(raw_key)
        parts = key.split("/")
        phase_name = parts[4] if len(parts) == 6 else ""
        phase_index = positions.get(phase_name)
        if phase_index is None or phase_index >= owner_index:
            selected.append(key)
    return selected


def _auto_map_unmapped_depth_findings_with_semantic_authority(
    scratchpad: Path,
    config: dict[str, Any],
    *,
    owner_phase: str,
    gate_issues: Sequence[str],
) -> tuple[list[str], list[str]]:
    """Apply the final auto-map through one recoverable paired successor."""

    if not gate_issues:
        return [], []
    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    project = Path(config.get("project_root") or root.parent)
    if not run_id:
        try:
            mapped = _auto_map_unmapped_depth_findings(root)
        except Exception as exc:
            return [], [
                "chain final auto-map failed without run authority: "
                f"{type(exc).__name__}: {exc}"
            ]
        return mapped, [
            "chain final auto-map run_id is absent; mutable roots remain "
            "unprojectable and must be reviewed"
        ]
    result = run_chain_pair_auto_map_transaction(
        scratchpad=root,
        project_root=project,
        config=config,
        run_id=run_id,
        derive=_derive_auto_map_unmapped_depth_findings,
    )
    mapped = [
        str(value) for value in result.get("mapped_ids", ())
        if str(value)
    ]
    issues = [str(value) for value in result.get("issues", ()) if str(value)]
    if result.get("safe_to_project") is not True:
        issues.append(
            "chain final auto-map paired successor did not commit; "
            f"state={result.get('state')}; candidates remain preserved in "
            "their discovery/inventory artifacts"
        )
    return mapped, list(dict.fromkeys(issues))


def _resume_phase_contract_issues(
    scratchpad: Path,
    project_root: str,
    phase: Phase,
    mode: str = "core",
    language: str = "",
    pipeline: str = "",
    backend: str = "",
) -> list[str]:
    """Side-effect-free subset of phase completion contracts for resume."""
    issues: list[str] = []
    if (
        phase.expected_artifacts
        or getattr(phase, "any_of", None)
        or phase.name in L1_VERIFY_PHASE_NAMES
        or phase.name in SC_VERIFY_PHASE_NAMES
    ):
        passed, missing = gate_passes(scratchpad, project_root, phase)
        if not passed:
            issues.extend(missing)

    if phase.name == "inventory":
        # v2.8.6: skip parity on resume — inventory is modified by downstream
        # phases (depth promotion, dedup) so the merge receipt is stale. The
        # parity check was already enforced when the inventory was first created.
        # Only run the structure check (headings/format) on resume.
        issues.extend(_validate_inventory_structure(scratchpad))
    elif phase.name == "recon" and "build_status.md" in set(phase.expected_artifacts):
        hard, _soft = _validate_recon_content_structure(scratchpad)
        issues.extend(hard)
    elif phase.name == "instantiate":
        issues.extend(
            _validate_spawn_manifest_schema(scratchpad, mode, language)
        )
    elif phase.name == "invariants_p2" and mode == "thorough":
        issues.extend(
            semantic_invariant_authority
            .validate_semantic_invariant_final_byte_authority(
                Path(scratchpad),
                ecosystem=language,
                mode=mode,
                run_id=trust_current_run_id(Path(scratchpad)),
                backend=backend or "claude",
            )
        )
    elif phase.name == "depth" and any(
        (Path(scratchpad) / name).is_file()
        for name in (
            "_depth_worker_pool_contract.json",
            "confidence_consensus_authority.json",
            "consensus_map.md",
            "confidence_scores.md",
        )
    ):
        issues.extend(validate_confidence_consensus_artifacts(Path(scratchpad)))
        issues.extend(
            _validate_confidence_consensus_phase_io(
                scratchpad=Path(scratchpad),
                project_root=Path(project_root),
                mode=mode,
                language=language,
                pipeline=pipeline,
                backend=backend,
                timeout_s=phase.base_timeout_s,
            )
        )
    elif phase.name in (
        "inventory_chunk_a", "inventory_chunk_b", "inventory_chunk_c"
    ):
        issues.extend(_validate_inventory_chunk_structure(scratchpad, phase.name))
        receipt_name, _ = _inventory_reconciliation_output_names(phase.name)
        if (Path(scratchpad) / receipt_name).is_file():
            issues.extend(
                _validate_inventory_reconciliation_phase_io(
                    scratchpad=Path(scratchpad),
                    project_root=Path(project_root),
                    phase_name=phase.name,
                    mode=mode,
                    language=language,
                    pipeline=pipeline,
                    backend=backend,
                    timeout_s=phase.base_timeout_s,
                )
            )
    elif phase.name in ("verify_queue", "sc_verify_queue"):
        try:
            from post_verify_candidate_delta import (
                PostVerifyCandidateDeltaError,
                load_authenticated_queue_publication,
            )

            load_authenticated_queue_publication(
                Path(scratchpad),
                project_root=Path(project_root),
                run_id=trust_current_run_id(Path(scratchpad)),
            )
        except (
            PostVerifyCandidateDeltaError,
            OSError,
            RuntimeError,
            TypeError,
            ValueError,
        ) as exc:
            issues.append(
                "live T9 verification-queue publication is not resumable: "
                f"{type(exc).__name__}: {exc}"
            )
        p0af_resume_config = {
            "pipeline": pipeline or "sc",
            "mode": mode,
            "language": language or "unknown",
            "cli_backend": backend or "claude",
            "project_root": project_root,
            "_run_id": trust_current_run_id(Path(scratchpad)),
        }
        if phase.name == "sc_verify_queue":
            issues.extend(
                p0af_v2_resume_contract_issues(scratchpad, p0af_resume_config)
            )
        issues.extend(_validate_verification_queue_inventory_parity(
            scratchpad,
            authorized_external_ids=(
                _p0af_v2_authorized_external_ids(
                    scratchpad, p0af_resume_config
                )
                if phase.name == "sc_verify_queue"
                else ()
            ),
        ))
        if phase.name == "sc_verify_queue" and mode != "thorough":
            low_info = [
                r.get("finding id", "")
                for r in parse_verification_queue_rows(scratchpad)
                if _severity_bucket(r.get("severity", "")) in {"low", "info"}
            ]
            if low_info:
                issues.append(
                    "SC verification queue contains Low/Info active row(s) "
                    f"in {mode} mode: {', '.join(low_info[:8])}"
                )
    elif (
        phase.name in L1_VERIFY_PHASE_NAMES
        or phase.name in SC_VERIFY_PHASE_NAMES
    ) and (Path(scratchpad) / _DYNAMIC_VERIFIER_ROSTER_NAME).is_file():
        # A retained runtime-debt row keeps a candidate visible downstream;
        # it is not verifier completion.  Resume must therefore replay the
        # exact dynamic unit receipt instead of accepting plausible prose or
        # a prior aggregate marker as proof that the child finished.
        try:
            plan = read_queue_work_plan(Path(scratchpad))
            assigned = tuple(plan.shard(phase.name).ordered_work_item_ids)
        except Exception as exc:
            issues.append(
                "dynamic verifier resume plan invalid: "
                f"{type(exc).__name__}: {exc}"
            )
        else:
            for work_item_id in assigned:
                item_issues = _verifier_completion_authority_issues(
                    Path(scratchpad), work_item_id
                )
                if item_issues:
                    issues.append(
                        f"{work_item_id}: dynamic verifier resume requires "
                        "exact retry (" + "; ".join(item_issues[:2]) + ")"
                    )
    elif phase.name == "severity_adjudication_shadow":
        issues.extend(_trust_evidence_provider_resume_issues(
            Path(scratchpad),
            {
                "pipeline": pipeline or "sc",
                "mode": mode,
                "language": language or "unknown",
                "cli_backend": backend or "claude",
                "project_root": project_root,
                "_run_id": trust_current_run_id(Path(scratchpad)),
            },
        ))
    elif phase.name == "report_index":
        issues.extend(_validate_security_obligation_lifecycle_phase_io(
            Path(scratchpad),
            {
                "pipeline": pipeline or "sc",
                "mode": mode,
                "language": language or "unknown",
                "cli_backend": backend or "claude",
                "project_root": project_root,
                "_run_id": trust_current_run_id(Path(scratchpad)),
            },
        ))
        issues.extend(_validate_report_index_inputs(
            scratchpad,
            expected_run_id=trust_current_run_id(Path(scratchpad)),
            expected_mode=mode,
        ))
        issues.extend(_check_index_completeness(
            scratchpad,
            project_root,
            write_retry_hint=False,
            run_id=_report_disposition_run_id(scratchpad),
        ))
        issues.extend(_validate_report_coverage_accounting(scratchpad))
    elif phase.name == "report_floor":
        try:
            validate_report_disposition_authority(
                Path(scratchpad),
                Path(project_root),
                run_id=_report_disposition_run_id(Path(scratchpad)),
            )
        except Exception as exc:
            issues.append(
                "report disposition resume authority/sidecar invalid: "
                f"{type(exc).__name__}: {exc}"
            )
        issues.extend(_validate_report_disposition_phase_io(
            scratchpad=Path(scratchpad),
            project_root=Path(project_root),
            mode=mode,
            language=language,
            pipeline=pipeline,
            backend=backend,
        ))
        issues.extend(_validate_chain_grouping_assurance_phase_io(
            scratchpad=Path(scratchpad),
            project_root=Path(project_root),
            mode=mode,
            language=language,
            pipeline=pipeline,
            backend=backend,
        ))
    elif phase.name in ("verify_aggregate", "sc_verify_aggregate"):
        issues.extend(_validate_verify_files_for_queue(scratchpad))
        issues.extend(_validate_verify_evidence_tags(scratchpad))
        if (Path(scratchpad) / _DYNAMIC_VERIFIER_ROSTER_NAME).is_file():
            for row in parse_verification_queue_rows(Path(scratchpad)):
                work_item_id = str(row.get("finding id") or "").strip()
                if not work_item_id:
                    continue
                item_issues = _verifier_completion_authority_issues(
                    Path(scratchpad), work_item_id
                )
                if item_issues:
                    issues.append(
                        f"{work_item_id}: aggregate cannot classify retained "
                        "runtime debt as verifier completion ("
                        + "; ".join(item_issues[:2])
                        + ")"
                    )
        # Migration boundary: pre-feature checkpoints legitimately have no
        # independent-severity projection.  Current runs arm a PhaseIO work
        # unit before aggregate completion; once that arm (or either projection
        # byte set) exists, deletion/corruption remains a hard resume issue.
        # This prevents a newly introduced sidecar from rewinding an otherwise
        # valid legacy run while retaining fail-closed behavior for runs that
        # actually claimed the typed feature.
        _independent_severity_armed = any(
            (Path(scratchpad) / name).is_file()
            for name in (
                "independent_severity_challenges.json",
                "independent_severity_challenges.md",
            )
        )
        if not _independent_severity_armed:
            try:
                _independent_severity_armed = any(
                    str(key).endswith("/independent_severity_reconcile")
                    for key in read_artifact_ledger(Path(scratchpad)).get(
                        "work_units", {}
                    )
                )
            except (ArtifactLedgerError, OSError, TypeError, ValueError):
                # A corrupt typed ledger is handled by the common ledger gates;
                # do not reinterpret corruption as affirmative feature absence.
                _independent_severity_armed = True
        if (
            mode != "light"
            and parse_verification_queue_rows(scratchpad)
            and _independent_severity_armed
        ):
            issues.extend(
                _validate_independent_severity_challenge_receipt(scratchpad)
            )
    elif phase.name == "skeptic":
        issues.extend(_validate_skeptic_full_ch_coverage(scratchpad))
        issues.extend(_validate_skeptic_challenge_receipt(scratchpad))
    elif phase.name == "chain" and str(pipeline or "sc").lower() == "sc":
        from state_symbol_authority import validate_chain_state_resolution

        issues.extend(validate_chain_state_resolution(Path(scratchpad)))
        issues.extend(_validate_chain_state_resolution_phase_io(
            scratchpad=Path(scratchpad),
            project_root=Path(project_root),
            mode=mode,
            language=language,
            pipeline=pipeline,
            backend=backend,
            timeout_s=phase.base_timeout_s,
        ))
    elif phase.name == "chain_iter2":
        try:
            _tail_manifest = json.loads(
                (Path(scratchpad) / "chain_candidate_pairs_iter2.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            if _tail_manifest.get("schema_version") == "plamen.chain_tail_manifest.v2":
                from chain_tail_authority import validate_chain_tail_authority

                issues.extend(
                    validate_chain_tail_authority(
                        Path(scratchpad), require_complete=True
                    )
                )
        except FileNotFoundError:
            pass
        except Exception as exc:
            issues.append(
                "typed chain-tail resume authority unavailable: "
                f"{type(exc).__name__}: {exc}"
            )
    elif phase.name == "report_assemble":
        # RESUME-2: the resume reconcile probe must be side-effect-free. The full
        # _run_report_quality_gate writes AUDIT_REPORT.md + report_quality.md and
        # applies prose checks -- it belongs only on the live post-assembly path.
        # Here use a content-only presence/structure check plus the mechanical
        # degraded-sentinel check (meaningful on a genuine resume).
        issues.extend(_report_assemble_content_only_issues(project_root))
        issues.extend(_validate_assemble_not_degraded(scratchpad))
    elif (
        phase.name in (
            "report_critical_high", "report_medium", "report_low_info",
            "report_body_writer_critical_high",
            "report_body_writer_medium",
            "report_body_writer_low_info",
        )
        or re.match(r"^report_(critical_high|medium|low_info)_[a-z]$", phase.name)
        or re.match(r"^report_body_writer_(critical_high|medium|low_info)_[a-z]$", phase.name)
    ):
        check_phase_name = phase.name.replace("report_body_writer_", "report_")
        issues.extend(_validate_tier_body_against_manifest(scratchpad, check_phase_name))

    # P1-C: a completed depth phase is not resumable from Markdown presence
    # alone.  Re-derive the current POST authority and verify its exact DRIVER
    # input/output receipt.  PRE is intentionally not revalidated after POST
    # has taken ownership; worker receipts retain the PRE binding in history.
    _p1c_sidecar_evidence = phase.name == "depth" and any(
        (Path(scratchpad) / name).is_file()
        for name in (
            security_obligation_authority.FEATURE_FACT_FILE,
            security_obligation_authority.AUTHORITY_FILE,
            security_obligation_authority.PROJECTION_FILE,
        )
    )
    _p1c_typed_post_evidence = False
    if phase.name == "depth":
        try:
            _p1c_units = read_artifact_ledger(Path(scratchpad)).get(
                "work_units", {}
            )
            _p1c_typed_post_evidence = any(
                str(key).endswith(
                    "/depth/security_obligations.post_depth"
                )
                for key in _p1c_units
            )
        except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
            # An existing but unreadable ledger cannot silently turn a typed
            # run into a legacy run.  A genuinely legacy scratchpad has no
            # artifact-state file and remains resumable under its old gates.
            if (Path(scratchpad) / "_artifact_state.json").is_file():
                issues.append(
                    "security-obligation typed POST presence could not be "
                    f"determined: {type(exc).__name__}: {exc}"
                )
    if phase.name == "depth" and (
        _p1c_sidecar_evidence or _p1c_typed_post_evidence
    ):
        _checkpoint_payload: Mapping[str, Any] = {}
        try:
            loaded_checkpoint = json.loads(
                (Path(scratchpad) / "_v2_checkpoint.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            if isinstance(loaded_checkpoint, Mapping):
                _checkpoint_payload = loaded_checkpoint
        except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
            pass
        issues.extend(_validate_security_obligation_phase_io(
            Path(scratchpad),
            {
                "pipeline": pipeline or "sc",
                "mode": mode,
                "language": language or "unknown",
                "cli_backend": backend or "claude",
                "project_root": project_root,
                "_run_id": str(_checkpoint_payload.get("run_id") or ""),
                "_audit_snapshot": (
                    _checkpoint_payload.get("audit_snapshot")
                    if isinstance(
                        _checkpoint_payload.get("audit_snapshot"), Mapping
                    )
                    else {}
                ),
            },
            stage="post_depth",
        ))

    # P0-AD/P0-A resume freshness: typed selection/consumer receipts are part
    # of the semantic phase contract, not optional cache files.  New SC runs
    # pass pipeline explicitly.  Direct legacy helper callers with no typed
    # artifacts preserve their old behavior.
    expected_pipeline = str(pipeline or "").strip().lower()
    typed_present = any(
        (Path(scratchpad) / name).exists()
        for name in (
            "skill_selection_catalog.json",
            "skill_consumer_coverage.json",
        )
    )
    if (expected_pipeline == "sc" or (not expected_pipeline and typed_present)):
        authority = {}
        try:
            authority = json.loads(
                (Path(scratchpad) / "skill_selection_catalog.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            ).get("authority") or {}
        except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
            pass
        authority_backend = str(
            backend or authority.get("backend") or "unknown"
        ).lower()
        authority_mode = str(mode or authority.get("mode") or "core").lower()
        authority_language = str(
            language or authority.get("ecosystem") or ""
        ).lower()
        if phase.name == "recon":
            issues.extend(_skill_selection_gate_issues(
                Path(scratchpad),
                language=authority_language,
                pipeline="sc",
                mode=authority_mode,
                backend=authority_backend,
            ))
        elif phase.name == "instantiate":
            issues.extend(_skill_authority_gate_issues(
                Path(scratchpad),
                language=authority_language,
                pipeline="sc",
                mode=authority_mode,
                backend=authority_backend,
            ))

    return sorted(set(issues))


def _phase_content_gate_issues(
    phase: Phase,
    config: dict,
    scratchpad: Path,
    project_root: str,
) -> list[str]:
    """Side-effect-free CONTENT re-validation for a phase, mirroring the
    resume-skip decision.

    Returns the list of content/disk issues (empty == artifacts on disk are
    content-valid). This is the same gate the resume loop uses to decide
    whether a completed phase can be skipped, so the degrade/halt path can
    re-check content before forcing a CRITICAL halt (FC4 safety net). It is
    DELIBERATELY content-only: it does not re-run prose/quality retry-hint
    generation, only the validators that prove the artifacts are usable.
    """
    mode = config.get("mode", "core")
    if phase.name in L1_VERIFY_PHASE_NAMES or phase.name in SC_VERIFY_PHASE_NAMES:
        dynamic_issues = _dynamic_verifier_phase_issues(
            phase, scratchpad, config
        )
        if dynamic_issues is not None:
            return list(dynamic_issues)
        if (Path(scratchpad) / _DYNAMIC_VERIFIER_PLANNING_DEBT_NAME).is_file():
            return [
                "dynamic verifier roster unavailable; exact planning debt retained"
            ]
        return list(_validate_verify_completion(
            scratchpad,
            phase.name,
            mode=mode,
            execution_policy=_resolve_config_execution_policy(config),
            launch_digest=_resolved_phase_launch_digest(phase, config),
        ))
    if phase.name == "attention_repair":
        hard, _soft = _validate_attention_repair(scratchpad, mode)
        return list(hard)
    if phase.name == "exploration_skeptic":
        # Resume validation must be side-effect-free and must preserve typed
        # committed-invariant debt as an incomplete phase boundary.
        return list(dict.fromkeys([
            *_validate_invariant_commitment(
                scratchpad, mode, recover=False
            ),
            *_exploration_clear_resume_issues(
                scratchpad, Path(project_root), mode=mode
            ),
        ]))
    if phase.name == "skeptic":
        # A completed skeptic phase is resumable only when every verifier CI
        # replays as durable next-run authority and candidate persistence.
        return _validate_invariant_commitment(
            scratchpad, mode, recover=False
        )
    if phase.name == "enumgap_exploration":
        # Soft, additive phase (validator always returns []) — content-valid on
        # resume so it never causes a false resume-halt.
        return _enumgap_disposition_resume_issues(
            scratchpad, Path(project_root), mode=mode
        )
    if phase.name == "axis_coverage":
        return _axis_disposition_resume_issues(
            scratchpad=Path(scratchpad),
            project_root=Path(project_root),
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(mode),
            language=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            run_id=str(config.get("_run_id") or ""),
        )
    if phase.name == "report_assemble":
        # RESUME-3: the FC4 content re-check must be SIDE-EFFECT-FREE and
        # content-only. Do NOT run _run_report_quality_gate here (it writes
        # AUDIT_REPORT.md + report_quality.md and applies prose checks), and do
        # NOT consult the {phase}.degraded sentinel the driver just wrote one
        # branch earlier (it is not independent evidence). Only verify the
        # delivered report is present and structurally non-stub.
        return _report_assemble_content_only_issues(project_root)
    return list(_resume_phase_contract_issues(
        scratchpad, project_root, phase, mode,
        str(config.get("language", "")),
        str(config.get("pipeline", "")),
        str(config.get("cli_backend", "")),
    ))


def _report_assemble_content_only_issues(project_root: str) -> list[str]:
    """Mechanical, side-effect-free presence/structure check for the delivered
    AUDIT_REPORT.md. Returns [] when the report exists and is non-stub.

    Used by RESUME-2 (resume reconcile) and RESUME-3 (FC4 degrade re-check) so a
    content-valid report is never rewound/halted by the side-effecting prose
    quality gate. The full _run_report_quality_gate still runs on the live
    post-assembly path where its self-heal writes belong.
    """
    issues: list[str] = []
    report = Path(project_root) / "AUDIT_REPORT.md"
    if not report.exists():
        return ["AUDIT_REPORT.md missing"]
    try:
        text = report.read_text(encoding="utf-8", errors="replace")
    except Exception as exc:
        return [f"AUDIT_REPORT.md unreadable ({exc})"]
    if len(text) < 500:
        issues.append("AUDIT_REPORT.md is a stub (<500 bytes)")
    # Structurally non-stub: at least one finding section OR an explicit
    # Summary / severity section heading (a clean no-findings report is valid).
    if not (
        re.search(r"(?im)^###\s+\[?[CHMLI]-\d", text)
        or re.search(r"(?im)^##\s+(?:Summary|Critical|High|Medium|Low|Informational)\b", text)
    ):
        issues.append("AUDIT_REPORT.md has no finding sections or severity/summary headings")
    return issues


def _stable_payload_digest(payload: object) -> str:
    encoded = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), ensure_ascii=True
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _typed_worker_unit_id(agent_id: str, attempt: int = 1) -> str:
    token = re.sub(r"[^a-z0-9_.-]+", "_", str(agent_id).strip().lower())
    token = token.strip("_.-") or "worker"
    ordinal = max(1, int(attempt or 1))
    suffix = "" if ordinal == 1 else f".attempt-{ordinal:04d}"
    return f"worker.{token}{suffix}"


