def _typed_worker_registered_input_paths(
    *,
    phase_name: str,
    scratchpad: Path,
    config: Mapping[str, Any],
    agent_id: str,
    output: str,
    agent_role: str | None = None,
    work_category: str = "*",
    focus_area: str = "",
    attempt: int = 1,
) -> tuple[str, ...]:
    """Return one finite, job-aware PhaseIO evidence denominator.

    This selector is shared by prompt compilation, prebinding, launch replay,
    and postcommit.  It never enumerates the scratchpad: dynamic rows come only
    from authenticated/declared manifests and every remaining path is a closed
    driver constant.
    """

    phase_n = str(phase_name or "").strip().lower()
    pipeline = str(config.get("pipeline") or "sc").strip().lower()
    category = str(work_category or "*").strip().lower()
    role = str(agent_role or "").strip().lower()
    values: list[str]
    impact_map_present = False
    if phase_n in {"recon", "breadth", "depth"}:
        try:
            impact_map_present = (
                Path(str(config.get("project_root") or "")) / "impact_map.md"
            ).is_file()
        except OSError:
            impact_map_present = False

    # Older fan-out seams pass only the stable worker/output identity. Resolve
    # missing job metadata from the same finite driver roster used to render
    # the prompt, never from scratchpad enumeration.
    if phase_n in {"breadth", "depth"} and (
        not focus_area or category in {"", "*"} or not role
    ):
        roster = (
            _breadth_worker_jobs(Path(scratchpad), dict(config))
            if phase_n == "breadth"
            else _depth_worker_jobs(Path(scratchpad), dict(config))
        )
        matched = next(
            (
                row for row in roster
                if str(row.get("agent_id") or "") == str(agent_id)
                or str(row.get("output") or "") == str(output)
            ),
            None,
        )
        if matched is not None:
            if not focus_area:
                focus_area = str(
                    matched.get("focus_area") or matched.get("focus") or ""
                )
            if category in {"", "*"}:
                category = str(matched.get("category") or "*").strip().lower()
            if not role:
                role = str(matched.get("role") or "").strip().lower()

    if phase_n == "recon":
        if (
            str(agent_id).strip(),
            None if agent_role is None else str(agent_role).strip(),
            str(output).strip(),
        ) == _RECON_DEPENDENCY_RESEARCH_TUPLE:
            # R-EXT is a post-base conditional producer, not an ordinary
            # recon leaf.  Its registered denominator is the obligation
            # authority plus every mode-selected base shard.  Keeping this in
            # the common selector makes prompt compilation, prebinding,
            # launch replay, and postcommit consume the identical closed set.
            # Return immediately: project-level impact-map evidence is valid
            # for ordinary recon leaves but is not registered in R-EXT's
            # deliberately smaller PhaseIO contract.
            return _recon_dependency_research_registered_inputs(config)
        else:
            values = list(
                ("primitive_status.md",)
                if pipeline == "l1"
                else _SC_RECON_WORKER_INPUTS
            )
            if _recon_outer_attempt_from_worker(attempt) > 1:
                values.append("recon_retry_plan.json")
    elif phase_n == "breadth":
        values = list(
            (
                "recon_summary.md", "attack_surface.md", "subsystem_map.md",
                "trust_boundaries.md", "template_recommendations.md",
                "primitive_status.md",
            )
            if pipeline == "l1"
            else (
                "recon_summary.md", "attack_surface.md",
                "contract_inventory.md", "function_list.md",
                "state_variables.md", "template_recommendations.md",
            )
        )
        values.append(_opengrep_shard_filename(agent_id, focus_area))
    elif phase_n == "rescan":
        values = [
            *( _L1_RECON_DOWNSTREAM_INPUTS
               if pipeline == "l1" else _SC_RECON_DOWNSTREAM_INPUTS),
            "rescan_manifest.md",
            (
                "opengrep_hits_ranked.md"
                if pipeline == "l1" else "opengrep_findings.md"
            ),
        ]
        # The breadth manifest is the sole authority for dynamic prior rows.
        values.extend(parse_breadth_manifest_outputs(Path(scratchpad)) or ())
    elif phase_n == "depth":
        values = [
            *( _L1_RECON_DOWNSTREAM_INPUTS
               if pipeline == "l1" else _SC_RECON_DOWNSTREAM_INPUTS),
            "findings_inventory.md",
            (
                "opengrep_hits_ranked.md"
                if pipeline == "l1" else "opengrep_findings.md"
            ),
            *(
                (
                    "instantiation.json", "opengrep_hits_ranked.md",
                    "confidence_scores.md", "violations.md",
                )
                if pipeline == "l1" else ()
            ),
            *(
                _L1_DEPTH_GRAPH_INPUTS
                if pipeline == "l1" else _SC_DEPTH_GRAPH_INPUTS
            ),
            *(
                ("semantic_invariants.md", "semantic_invariant_coverage_gaps.md")
                if str(config.get("mode") or "core").lower()
                in {"core", "thorough"}
                else ()
            ),
            *(
                (
                    "security_feature_facts.json",
                    "security_obligation_authority.json",
                    "security_obligations.md",
                )
                if pipeline == "sc" else ()
            ),
            *(
                ("semantic_invariant_final_byte_authority.json",)
                if str(config.get("mode") or "core").lower() == "thorough"
                else ()
            ),
        ]
        # Breadth outputs are a finite manifest-declared predecessor set, not
        # a scratchpad scan. The standard depth methodology explicitly uses
        # these finding cards as its starting evidence.
        values.extend(parse_breadth_manifest_outputs(Path(scratchpad)) or ())
        # Additional historical graph projections remain optional.  The typed
        # graph, depth candidate routing, and four methodology-mandated graph
        # views above are produced by the exact Inventory-to-Depth handoff.
        if pipeline == "sc":
            values.extend(
                name for name in _SC_DEPTH_OPTIONAL_GRAPH_INPUTS
                if (Path(scratchpad) / name).is_file()
                and name not in _SC_DEPTH_GRAPH_INPUTS
            )
        if pipeline == "l1":
            l1_call_graph = {
                "consensus_invariant": "scip/call_graph_consensus.md",
                "network_surface": "scip/call_graph_p2p.md",
                "state_trace": "scip/call_graph_execution.md",
            }.get(role)
            if l1_call_graph:
                values.append(l1_call_graph)
        if category in {"scanner", "fuzz"} or role in {
            "blind_spot_a", "blind_spot_b", "blind_spot_c",
            "validation_sweep", "design_stress", "invariant_fuzz",
            "medusa_fuzz", "state_trace",
        }:
            values.extend(
                name for name in ("constraint_variables.md", "modifiers.md")
                if (Path(scratchpad) / name).is_file()
            )
        if category == "fuzz":
            values.append("fuzz_workspace_index.json")
        if category in {"sibling", "post_producer"} or role in {
            "perturbation", "skill_execution_checklist",
        }:
            values.extend(
                str(job.get("output") or "")
                for job in _depth_worker_jobs(Path(scratchpad), dict(config))
                if str(job.get("output") or "") != str(output)
                and str(job.get("category") or "")
                in {"standard", "scanner", "niche"}
            )
    else:
        return ()

    if impact_map_present:
        values.append(_IMPACT_MAP_EVIDENCE_FILE)

    return tuple(sorted(dict.fromkeys(
        str(value).strip() for value in values
        if str(value).strip() and str(value).strip() != str(output)
    )))


_RECON_DEPENDENCY_RESEARCH_TUPLE = (
    "R-EXT",
    "external_dependency_research",
    "recon_external_dependency_research.md",
)


def _recon_dependency_research_registered_inputs(
    config: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return the finite, mode-specific PhaseIO denominator for R-EXT."""

    base_shards = tuple(
        str(job.get("output") or "").strip()
        for job in _recon_worker_jobs(dict(config))
    )
    return tuple(sorted(dict.fromkeys((
        "external_dependency_obligations.json",
        *(path for path in base_shards if path),
    ))))


def _typed_worker_work_unit_selector(
    *,
    pipeline: str,
    phase_name: str,
    agent_id: str,
    role: str | None,
    output: str,
    attempt: int,
) -> str:
    """Select one canonical typed worker identity for every driver seam.

    R-EXT is not a generic recon worker: its mode-specific PhaseIO contract
    binds the obligation denominator and all already-committed base shards.
    Treat any partial spelling of that reserved tuple as an error so a typo
    cannot silently fall back to ``worker.r-ext`` authority.
    """

    phase_token = str(phase_name or "").strip().lower()
    pipeline_token = str(pipeline or "").strip().lower()
    agent_token = str(agent_id or "").strip()
    role_token = None if role is None else str(role).strip()
    output_token = str(output or "").strip()
    reserved = (
        agent_token.upper() == "R-EXT"
        or role_token == _RECON_DEPENDENCY_RESEARCH_TUPLE[1]
        or output_token == _RECON_DEPENDENCY_RESEARCH_TUPLE[2]
    )
    if reserved:
        if (
            pipeline_token != "sc"
            or phase_token != "recon"
            or (
                agent_token,
                role_token,
                output_token,
            )
            != _RECON_DEPENDENCY_RESEARCH_TUPLE
        ):
            raise ValueError(
                "reserved R-EXT work-unit tuple differs from "
                "R-EXT/external_dependency_research/"
                "recon_external_dependency_research.md"
            )
        ordinal = int(attempt or 1)
        if ordinal < 1 or ordinal > 9999:
            raise ValueError("R-EXT attempt ordinal is outside 1..9999")
        return (
            "dependency_research"
            if ordinal == 1
            else f"dependency_research.attempt-{ordinal:04d}"
        )
    return _typed_worker_unit_id(agent_token, attempt)


def _compile_typed_worker_prompt(
    prompt: str,
    *,
    config: dict[str, Any],
    phase_name: str,
    agent_id: str,
    agent_role: str | None = None,
    output: str,
    source_phase: str = "",
    work_category: str = "*",
    focus_area: str = "",
    exact_inputs: Sequence[str] | None = None,
    attempt: int = 1,
) -> str:
    """Append the exact runtime I/O authority used by ownership and gates."""
    work_unit_id = (
        "methodology_repair.model"
        if agent_id == "methodology_repair"
        else _typed_worker_work_unit_selector(
            pipeline=str(config.get("pipeline") or "sc"),
            phase_name=phase_name,
            agent_id=agent_id,
            role=agent_role,
            output=output,
            attempt=attempt,
        )
    )
    prompt_contract_backend = (
        str(config.get("cli_backend") or "claude")
        if work_unit_id == "methodology_repair.model"
        else "backend-neutral"
    )
    registered_inputs = tuple(exact_inputs) if exact_inputs is not None else (
        _typed_worker_registered_input_paths(
            phase_name=phase_name,
            scratchpad=Path(str(config.get("scratchpad") or ".")),
            config=config,
            agent_id=agent_id,
            agent_role=agent_role,
            output=output,
            work_category=work_category,
            focus_area=focus_area,
            attempt=attempt,
        )
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        # Regular worker prompt authority is backend-neutral: launch/receipt
        # provenance records the actual Claude/Codex backend separately, so
        # equivalent methodology cannot drift solely because the executor
        # changed. Methodology-repair is the deliberate exception: its typed
        # repair contract and attempt receipt are backend-bound, and must keep
        # the configured runtime backend in the compiled prompt authority.
        backend=prompt_contract_backend,
        phase=phase_name,
        work_unit_id=work_unit_id,
        exact_outputs=(str(output),),
        exact_inputs=registered_inputs,
        source_phase=source_phase,
    )
    if (
        phase_name == "recon"
        and agent_id != "methodology_repair"
        and _recon_outer_attempt_from_worker(attempt) > 1
    ):
        # Retry evidence is already part of ``registered_inputs``.  Never add
        # the legacy free-form coordinator hint as a second authority channel.
        if "scratchpad:recon_retry_plan.json" not in (
            *contract.immutable_inputs, *contract.bounded_lookup_inputs,
        ):
            raise ValueError("recon retry prompt lacks registered retry plan input")
    compiled = compile_phase_io_prompt(prompt, contract, actor="MODEL")
    try:
        capability = resolve_work_unit_capability(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            phase=phase_name,
            category=work_category,
        )
    except WorkCapabilityResolutionError:
        return compiled
    return compile_work_unit_capability_contract(compiled, capability)


def _typed_model_worker_contract_and_launch(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    project_root: str,
    agent_id: str,
    agent_role: str | None = None,
    output: str,
    timeout_s: float,
    source_phase: str = "",
    work_category: str = "*",
    focus_area: str = "",
    exact_inputs: Sequence[str] | None = None,
    attempt: int = 1,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the one worker contract used before launch and after output.

    Keeping this construction in one place prevents a backend/transport or
    timeout discrepancy from turning a genuine prelaunch receipt into an
    apparently different post-execution work unit.
    """
    phase_name = source_phase or phase.name
    work_unit_id = (
        "methodology_repair.model"
        if agent_id == "methodology_repair"
        else _typed_worker_work_unit_selector(
            pipeline=str(config.get("pipeline") or "sc"),
            phase_name=phase_name,
            agent_id=agent_id,
            role=agent_role,
            output=output,
            attempt=attempt,
        )
    )
    runtime_config = (
        config
        if config.get("project_root")
        else {**config, "project_root": str(project_root)}
    )
    runtime = _live_phase_runtime_launch_policy(
        phase, scratchpad, runtime_config
    )
    registered_inputs = tuple(exact_inputs) if exact_inputs is not None else (
        _typed_worker_registered_input_paths(
            phase_name=phase_name,
            scratchpad=Path(scratchpad),
            config=config,
            agent_id=agent_id,
            agent_role=agent_role,
            output=output,
            work_category=work_category,
            focus_area=focus_area,
            attempt=attempt,
        )
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(runtime["backend"]),
        phase=phase_name,
        work_unit_id=work_unit_id,
        exact_outputs=(str(output),),
        exact_inputs=registered_inputs,
        source_phase=source_phase,
    )
    if (
        phase_name == "recon"
        and agent_id != "methodology_repair"
        and _recon_outer_attempt_from_worker(attempt) > 1
    ):
        # Retry authority is part of the immutable semantic denominator.  A
        # separate worker attempt may bind the post-quarantine state, but it
        # may never silently inherit attempt one's input receipt.
        _validated_recon_retry_plan(
            scratchpad,
            config,
            worker_attempt=attempt,
            phase=phase,
        )
        if "scratchpad:recon_retry_plan.json" not in (
            *contract.immutable_inputs, *contract.bounded_lookup_inputs,
        ):
            raise ValueError("recon retry contract lacks registered retry plan input")
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model=str(runtime["model"]),
        timeout_s=max(1, int(timeout_s)),
        exec_mode=str(runtime["exec_mode"]),
        tool_policy=(
            ("filesystem", "mcp", "network")
            if (
                phase.needs_mcp
                and contract.backend == "claude"
                and str(runtime["exec_mode"]).lower() == "headless"
            )
            else (
                ("filesystem", "network")
                if (
                    phase.needs_mcp
                    or (
                        phase_name == "recon"
                        and str(agent_id).upper() == "R-EXT"
                    )
                )
                else ("filesystem",)
            )
        ),
    )
    return contract, launch


def _bind_typed_model_worker_inputs(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    project_root: str,
    agent_id: str,
    agent_role: str | None = None,
    output: str,
    timeout_s: float,
    source_phase: str = "",
    work_category: str = "*",
    focus_area: str = "",
    exact_inputs: Sequence[str] | None = None,
    attempt: int = 1,
) -> list[str]:
    """Persist a worker's exact semantic denominator before model launch."""
    try:
        contract, launch = _typed_model_worker_contract_and_launch(
            phase=phase,
            config=config,
            scratchpad=scratchpad,
            project_root=project_root,
            agent_id=agent_id,
            agent_role=agent_role,
            output=output,
            timeout_s=timeout_s,
            source_phase=source_phase,
            work_category=work_category,
            focus_area=focus_area,
            exact_inputs=exact_inputs,
            attempt=attempt,
        )
        run_id = str(config.get("_run_id") or "test-unbound")
        record_work_unit_inputs(
            scratchpad,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
        )
        return validate_work_unit_inputs(
            scratchpad,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [str(exc)]


def _validate_typed_model_worker_inputs(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    project_root: str,
    agent_id: str,
    agent_role: str | None = None,
    output: str,
    timeout_s: float,
    source_phase: str = "",
    work_category: str = "*",
    focus_area: str = "",
    exact_inputs: Sequence[str] | None = None,
    attempt: int = 1,
) -> list[str]:
    """Revalidate the already-bound denominator immediately before spawn."""
    try:
        contract, launch = _typed_model_worker_contract_and_launch(
            phase=phase,
            config=config,
            scratchpad=scratchpad,
            project_root=project_root,
            agent_id=agent_id,
            agent_role=agent_role,
            output=output,
            timeout_s=timeout_s,
            source_phase=source_phase,
            work_category=work_category,
            focus_area=focus_area,
            exact_inputs=exact_inputs,
            attempt=attempt,
        )
        return validate_work_unit_inputs(
            scratchpad,
            Path(project_root),
            contract,
            launch,
            run_id=str(config.get("_run_id") or "test-unbound"),
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [str(exc)]


def _typed_worker_input_issue_is_fatal(output: str, issue: str) -> bool:
    if "semantic input missing at binding" not in issue:
        return True
    return (
        output in {"invariant_fuzz_results.md", "medusa_fuzz_findings.md"}
        and fuzz_workspace_authority.WORKSPACE_INDEX_FILE in issue
    )


def _prepare_typed_model_worker_launch(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    project_root: str,
    agent_id: str,
    agent_role: str | None = None,
    output: str,
    timeout_s: float,
    source_phase: str = "",
    work_category: str = "*",
    focus_area: str = "",
    exact_inputs: Sequence[str] | None = None,
    debt_phase: str = "",
    debt_code: str = "",
    attempt: int = 1,
) -> list[str]:
    """Bind exact worker inputs and return only launch-blocking issues.

    A missing semantic input is durable INPUT_DEBT, not permission for the
    model to certify safety and not a reason to discard recall candidates.
    Every other discrepancy (most importantly input drift) blocks the model
    invocation so post-model bytes can never be rebound as if they were the
    original denominator.
    """
    if phase.name in {"recon", "breadth", "depth"}:
        projection_issues = _materialize_impact_map_evidence(
            project_root=project_root,
            scratchpad=scratchpad,
        )
        if projection_issues:
            return projection_issues
    issues = _bind_typed_model_worker_inputs(
        phase=phase,
        config=config,
        scratchpad=scratchpad,
        project_root=project_root,
        agent_id=agent_id,
        agent_role=agent_role,
        output=output,
        timeout_s=timeout_s,
        source_phase=source_phase,
        work_category=work_category,
        focus_area=focus_area,
        exact_inputs=exact_inputs,
        attempt=attempt,
    )
    phase_label = debt_phase or source_phase or phase.name
    category = debt_code or (
        f"{re.sub(r'[^A-Z0-9]+', '_', phase_label.upper()).strip('_')}"
        "_WORKER_PRELAUNCH_INPUT_DEBT"
    )
    for issue in issues:
        _append_phase_io_debt(
            scratchpad,
            phase_label,
            category,
            f"{output}: {issue}",
        )
        log.warning(
            "[%s] prelaunch input binding debt for %s: %s",
            phase_label,
            output,
            issue,
        )
    return [
        issue for issue in issues
        if _typed_worker_input_issue_is_fatal(output, issue)
    ]


def _record_typed_model_worker_artifact(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    project_root: str,
    agent_id: str,
    agent_role: str | None = None,
    output: str,
    timeout_s: float,
    source_phase: str = "",
    work_category: str = "*",
    focus_area: str = "",
    exact_inputs: Sequence[str] | None = None,
    attempt: int = 1,
) -> list[str]:
    """Record or replay one exact completed worker output.

    The transactional headless runtime incorporates its staged output and
    records the resulting execution authority atomically.  Fan-out callers
    still share this post-worker hook with the legacy PTY route, so an exact
    already-incorporated unit must be replayed here instead of being recorded
    a second time.  A second record would mint a successor attempt without the
    original AttemptArm lineage or execution authority.
    """
    try:
        contract, launch = _typed_model_worker_contract_and_launch(
            phase=phase,
            config=config,
            scratchpad=scratchpad,
            project_root=project_root,
            agent_id=agent_id,
            agent_role=agent_role,
            output=output,
            timeout_s=timeout_s,
            source_phase=source_phase,
            work_category=work_category,
            focus_area=focus_area,
            exact_inputs=exact_inputs,
            attempt=attempt,
        )
        run_id = str(config.get("_run_id") or "test-unbound")
        prior = read_artifact_ledger(scratchpad).get("work_units", {}).get(
            contract.key
        )
        dependency_research = (
            contract.phase == "recon"
            and re.fullmatch(
                r"dependency_research(?:\.attempt-[0-9]{4})?",
                str(contract.work_unit_id),
            )
            is not None
        )
        if isinstance(prior, Mapping) and isinstance(
            prior.get("execution_authority"), Mapping
        ):
            # Fail closed on any malformed, stale, or drifted incorporated
            # authority.  validate_work_unit_artifacts replays the exact
            # execution/incorporation chain and canonical bytes; it is not a
            # content-only shortcut.
            return list(dict.fromkeys(validate_work_unit_artifacts(
                scratchpad,
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
                actor="MODEL",
            )))
        if dependency_research:
            return [
                f"{contract.key}: R-EXT requires transactional execution "
                "authority; legacy canonical-byte adoption is forbidden"
            ]
        conditional_receipts = {
            spec.identity: ConditionalOutputReceipt(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity=spec.identity,
                condition_id=spec.condition_id,
                state="PRODUCED",
                expected_denominator=1,
                produced_identities=(spec.identity,),
            )
            for spec in contract.outputs
            if spec.writer == "MODEL" and spec.artifact_class == "CONDITIONAL"
        }
        input_issues = validate_work_unit_inputs(
            scratchpad,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
        )
        record_work_unit_artifacts(
            scratchpad,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
            conditional_receipts=conditional_receipts,
            actor="MODEL",
            precommit_issues=input_issues,
        )
        return list(dict.fromkeys(input_issues + validate_work_unit_artifacts(
            scratchpad,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
            actor="MODEL",
        )))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [str(exc)]


_CHAIN_DELTA_HEADING_RE = re.compile(
    r"(?im)^#{2,4}\s+(?:Chain\s+Hypothesis\s+)?(CH-\d+)\b[^\r\n]*$"
)
_CHAIN_TAIL_HEADING_RE = re.compile(
    r"(?im)^##\s+Tail\s+Pair\s+Dispositions\s*$"
)


def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _durable_driver_replace(source: Path, destination: Path) -> None:
    """Durably publish a same-directory driver successor."""

    rooted_io.durable_replace(source, destination)


def _atomic_driver_bytes(path: Path, data: bytes) -> None:
    target = Path(path)
    rooted_io.ensure_directory(
        target.parent,
        parents=True,
        label="driver successor parent",
    )
    fd, temporary = rooted_io.exclusive_temp_file(
        target.parent,
        prefix="_.p.",
        suffix=".tmp",
    )
    try:
        with os.fdopen(fd, "wb") as handle:
            fd = -1
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        _durable_driver_replace(temporary, target)
    finally:
        if fd >= 0:
            os.close(fd)
        if rooted_io.lexists(temporary):
            rooted_io.unlink(temporary)


def _materialize_driver_successor_bytes(
    path: Path, data: bytes,
) -> bool:
    """Publish one successor postimage, preserving an exact no-op preimage.

    Return ``True`` only when a replacement occurred.  Physical-identity
    validation remains in the transaction authority; this helper merely
    prevents an exact transition from replacing the inode it is required to
    preserve.
    """

    target = Path(path)
    try:
        metadata = rooted_io.lstat(target)
        reparse = bool(
            getattr(metadata, "st_file_attributes", 0) & 0x400
        )
        if (
            stat.S_ISREG(metadata.st_mode)
            and not reparse
            and int(getattr(metadata, "st_nlink", 1) or 1) == 1
            and rooted_io.read_bytes(
                target,
                label="driver successor output",
                require_single_link=True,
            )
            == data
        ):
            confirmed = rooted_io.lstat(target)
            if (
                int(getattr(confirmed, "st_dev", 0))
                == int(getattr(metadata, "st_dev", 0))
                and int(getattr(confirmed, "st_ino", 0))
                == int(getattr(metadata, "st_ino", 0))
                and int(confirmed.st_size) == int(metadata.st_size)
                and int(confirmed.st_mtime_ns)
                == int(metadata.st_mtime_ns)
                and int(getattr(confirmed, "st_nlink", 1) or 1) == 1
                and stat.S_ISREG(confirmed.st_mode)
                and not bool(
                    getattr(confirmed, "st_file_attributes", 0) & 0x400
                )
            ):
                return False
    except (FileNotFoundError, OSError):
        pass
    _atomic_driver_bytes(target, data)
    return True


def _durable_driver_unlink(path: Path) -> None:
    """Remove one exact driver-owned sidecar and persist the directory entry."""

    target = Path(path)
    rooted_io.durable_unlink(target)


def _atomic_driver_json_record(path: Path, payload: dict[str, Any]) -> None:
    _atomic_driver_bytes(
        path,
        (json.dumps(payload, indent=2, sort_keys=True) + "\n").encode("utf-8"),
    )


_AUXILIARY_ROOT_RUNTIME_DEBT_ID = (
    "AUXILIARY-WRITABLE-ROOT-STARTUP"
)


def _run_auxiliary_writable_root_startup_boundary(
    scratchpad: Path,
    config: dict[str, Any],
    checkpoint: Checkpoint,
) -> dict[str, Any]:
    """Reconcile provider-owned writable roots before any new worker lease.

    A quarantine is recoverable runtime debt and remains phase-independent.
    A denial is also persisted before the caller stops the run.  Only a
    replayed, allocation-permitted receipt is exposed to worker launchers.
    """

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or checkpoint.run_id or "")
    if (
        not run_id
        or checkpoint.run_id != run_id
    ):
        raise auxiliary_root_startup.AuxiliaryWritableRootStartupError(
            "auxiliary-root startup run authority is absent or mismatched"
        )
    receipt = auxiliary_root_startup.reconcile_and_persist_startup_receipt(
        scratchpad=root,
        run_id=run_id,
    )
    startup_epoch = str(receipt.get("startup_epoch") or "")
    replay = auxiliary_root_startup.load_and_replay_startup_receipt(
        scratchpad=root,
        expected_run_id=run_id,
        expected_startup_epoch=startup_epoch,
    )
    if replay.get("valid") is not True:
        raise auxiliary_root_startup.AuxiliaryWritableRootStartupError(
            "auxiliary-root startup receipt did not replay"
        )
    disposition = str(replay["allocation_disposition"])
    digest = str(replay["receipt_sha256"])
    prior_digest = checkpoint.runtime_debts.get(
        _AUXILIARY_ROOT_RUNTIME_DEBT_ID
    )
    if disposition == "ALLOW_NEW_LEASES":
        if prior_digest is not None:
            checkpoint.clear_runtime_debt(
                _AUXILIARY_ROOT_RUNTIME_DEBT_ID,
                prior_digest,
            )
    else:
        checkpoint.record_runtime_debt(
            _AUXILIARY_ROOT_RUNTIME_DEBT_ID,
            digest,
        )
    if replay.get("allocation_permitted") is True:
        config["_auxiliary_writable_root_startup_binding"] = dict(
            replay["binding"]
        )
    else:
        config.pop(
            "_auxiliary_writable_root_startup_binding",
            None,
        )
    checkpoint.save(root)
    return replay


def _current_auxiliary_writable_root_startup_binding(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Re-read the exact receipt immediately before a worker is prepared."""

    run_id = str(config.get("_run_id") or "")
    configured = config.get(
        "_auxiliary_writable_root_startup_binding"
    )
    if not isinstance(configured, Mapping):
        raise auxiliary_root_startup.AuxiliaryWritableRootStartupError(
            "auxiliary-root startup binding is absent"
        )
    replay = auxiliary_root_startup.replay_startup_permit_binding(
        scratchpad=Path(scratchpad),
        expected_run_id=run_id,
        binding=configured,
    )
    binding = replay.get("binding")
    if (
        replay.get("valid") is not True
        or replay.get("allocation_permitted") is not True
        or not isinstance(binding, dict)
        or dict(configured) != binding
    ):
        raise auxiliary_root_startup.AuxiliaryWritableRootStartupError(
            "auxiliary-root startup binding drifted"
        )
    return dict(binding)


def _pipeline_terminal_exit_code(checkpoint: Checkpoint) -> int:
    """Return clean success only when phase and process-level debt are empty."""

    return (
        EXIT_SUCCESS
        if not checkpoint.degraded and not checkpoint.runtime_debts
        else EXIT_DEGRADED
    )


def _chain_heading_ids(text: str) -> list[str]:
    return [match.group(1).upper() for match in _CHAIN_DELTA_HEADING_RE.finditer(text)]


def _chain_delta_sections(text: str) -> tuple[list[tuple[str, str]], list[str]]:
    """Extract full CH sections without trusting a model-authored summary."""
    matches = list(_CHAIN_DELTA_HEADING_RE.finditer(text))
    tail = _CHAIN_TAIL_HEADING_RE.search(text)
    sections: list[tuple[str, str]] = []
    ids: list[str] = []
    for index, match in enumerate(matches):
        cid = match.group(1).upper()
        end = matches[index + 1].start() if index + 1 < len(matches) else len(text)
        if tail is not None and tail.start() > match.start():
            end = min(end, tail.start())
        section = text[match.start():end].strip()
        if section:
            sections.append((cid, section))
            ids.append(cid)
    duplicate_ids = sorted({cid for cid in ids if ids.count(cid) > 1})
    return sections, duplicate_ids


def _chain_tail_table(text: str) -> str:
    """Return only the exact reconciliation table under the tail heading."""
    heading = _CHAIN_TAIL_HEADING_RE.search(text)
    if heading is None:
        return ""
    rows: list[str] = []
    started = False
    for line in text[heading.end():].splitlines():
        stripped = line.strip()
        if stripped.startswith("|") and stripped.endswith("|"):
            rows.append(stripped)
            started = True
            continue
        if started and stripped:
            break
    if len(rows) < 3:
        return ""
    header_cells = [
        cell.strip() for cell in rows[0].strip("|").split("|")
    ]
    if (
        len(header_cells) >= 5
        and re.sub(r"[^a-z0-9]+", "", header_cells[0].lower())
        in {"pairid", "pair", "manifestpairid"}
    ):
        # The typed aggregate retains Pair ID as its exact join key.  The
        # legacy composition_coverage projection has a four-column schema, so
        # drop only that first presentation column during the driver-owned
        # merge.  Full identity remains in the hash-bound ledger/receipt.
        projected: list[str] = []
        for row in rows:
            cells = [cell.strip() for cell in row.strip("|").split("|")]
            if len(cells) < 5:
                return ""
            projected.append("| " + " | ".join(cells[1:]) + " |")
        rows = projected
    return "\n".join(rows)


_CHAIN_PAIR_ID_RE = re.compile(r"\b[A-Z][A-Z0-9_]*-\d+\b", re.I)


def _chain_coverage_pair_ids(text: str) -> list[str]:
    pairs: set[str] = set()
    for line in text.splitlines():
        stripped = line.strip()
        if not (stripped.startswith("|") and stripped.endswith("|")):
            continue
        if re.fullmatch(r"\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?", stripped):
            continue
        cells = [cell.strip() for cell in stripped.strip("|").split("|")]
        if len(cells) < 2:
            continue
        left = _CHAIN_PAIR_ID_RE.search(cells[0])
        right = _CHAIN_PAIR_ID_RE.search(cells[1])
        if left and right:
            pairs.add("|".join(sorted((left.group(0).upper(), right.group(0).upper()))))
    return sorted(pairs)


def _chain_iter2_merge_failure(
    scratchpad: Path,
    *,
    issue: str,
    contract_key: str,
    contract_digest: str,
    source_sha256: str = "",
    collision_ids: tuple[str, ...] = (),
    preserve_applied_receipt: bool = False,
) -> dict[str, Any]:
    result: dict[str, Any] = {
        "schema": "plamen.chain-iter2-driver-merge.v1",
        "status": "FAILED",
        "work_unit_key": contract_key,
        "contract_digest": contract_digest,
        "source_sha256": source_sha256,
        "added_chain_ids": [],
        "collision_ids": list(collision_ids),
        "issues": [issue],
        "events": [],
        "targets": {},
    }
    try:
        _append_chain_iter2_debt_sentinel(scratchpad, issue)
        _pass, _shards, generation_id = (
            _chain_tail_generation_from_work_unit_key(
                contract_key,
                role="driver_merge",
            )
        )
        receipt_name = (
            f"_chain_iter2_merge_failure.{generation_id}.json"
            if preserve_applied_receipt
            else f"_chain_iter2_merge_receipt.{generation_id}.json"
        )
        _atomic_driver_json_record(scratchpad / receipt_name, result)
    except (OSError, TypeError, ValueError):
        # An unscoped/legacy key may retain the durable debt sentinel, but it
        # must never create or replace a fixed legacy merge receipt.
        pass
    return result


def _append_chain_iter2_debt_sentinel(scratchpad: Path, issue: str) -> None:
    sentinel = Path(scratchpad) / "chain_iter2.degraded"
    existing = (
        sentinel.read_text(encoding="utf-8", errors="replace")
        if sentinel.exists() else ""
    )
    line = f"[CHAIN_ITER2_MERGE_DEBT] {issue}\n"
    if line not in existing:
        _atomic_driver_bytes(sentinel, (existing + line).encode("utf-8"))


def _resume_chain_iter2_merge_intent(
    scratchpad: Path,
    intent: dict[str, Any],
    *,
    contract_key: str,
    contract_digest: str,
    source_sha256: str,
) -> dict[str, Any]:
    """Finish a crash-interrupted two-target merge from its durable intent."""
    _pass, _shards, generation_id = _chain_tail_generation_from_work_unit_key(
        contract_key,
        role="driver_merge",
    )
    receipt = intent.get("receipt")
    blocks = intent.get("append_blocks")
    if not isinstance(receipt, dict) or not isinstance(blocks, dict):
        return _chain_iter2_merge_failure(
            scratchpad,
            issue="chain iteration 2 merge intent is malformed",
            contract_key=contract_key,
            contract_digest=contract_digest,
            source_sha256=source_sha256,
        )
    if (
        intent.get("source_sha256") != source_sha256
        or receipt.get("contract_digest") != contract_digest
        or receipt.get("work_unit_key") != contract_key
    ):
        return _chain_iter2_merge_failure(
            scratchpad,
            issue="chain iteration 2 merge intent/source digest mismatch",
            contract_key=contract_key,
            contract_digest=contract_digest,
            source_sha256=source_sha256,
        )
    targets = receipt.get("targets") or {}
    for name in ("chain_hypotheses.md", "composition_coverage.md"):
        target = scratchpad / name
        expected = targets.get(name) or {}
        if not target.exists():
            return _chain_iter2_merge_failure(
                scratchpad,
                issue=f"driver merge target missing during intent recovery: {name}",
                contract_key=contract_key,
                contract_digest=contract_digest,
                source_sha256=source_sha256,
            )
        current = _sha256_bytes(target.read_bytes())
        before = expected.get("before_sha256")
        after = expected.get("after_sha256")
        if current == after:
            continue
        if current != before:
            return _chain_iter2_merge_failure(
                scratchpad,
                issue=f"driver merge target drifted outside intent: {name}",
                contract_key=contract_key,
                contract_digest=contract_digest,
                source_sha256=source_sha256,
            )
        planned_bytes = (
            target.read_bytes().rstrip()
            + str(blocks.get(name) or "").encode("utf-8")
        )
        if _sha256_bytes(planned_bytes) != after:
            return _chain_iter2_merge_failure(
                scratchpad,
                issue=f"driver merge intent cannot reproduce planned hash: {name}",
                contract_key=contract_key,
                contract_digest=contract_digest,
                source_sha256=source_sha256,
            )
        _atomic_driver_bytes(target, planned_bytes)
    _atomic_driver_json_record(
        scratchpad / f"_chain_iter2_merge_receipt.{generation_id}.json",
        receipt,
    )
    return receipt


def _apply_chain_iter2_driver_merge(
    scratchpad: Path, config: dict[str, Any],
) -> dict[str, Any]:
    """Apply the gated model delta using a driver-owned, monotonic merge.

    The source and both aggregate artifacts are retained on every validation
    failure.  A durable intent makes a crash between the two target replaces
    resumable without replaying or trusting model prose.
    """
    scratchpad = Path(scratchpad)
    pass_index, shard_count, generation_id = (
        _current_chain_tail_generation(scratchpad)
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or config.get("backend") or "claude"),
        phase="chain_iter2",
        work_unit_id=_chain_tail_scoped_work_unit_id(
            "driver_merge",
            pass_index,
            shard_count,
        ),
    )
    source = scratchpad / "chain_iteration2.md"
    chain_target = scratchpad / "chain_hypotheses.md"
    coverage_target = scratchpad / "composition_coverage.md"
    if not source.exists():
        return _chain_iter2_merge_failure(
            scratchpad,
            issue="chain iteration 2 delta missing before driver merge",
            contract_key=contract.key,
            contract_digest=contract.digest,
        )
    source_bytes = source.read_bytes()
    source_sha = _sha256_bytes(source_bytes)

    receipt_path = (
        scratchpad / f"_chain_iter2_merge_receipt.{generation_id}.json"
    )
    if receipt_path.exists():
        try:
            prior = json.loads(receipt_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            prior = {}
        if prior.get("status") == "APPLIED":
            if prior.get("source_sha256") != source_sha:
                return _chain_iter2_merge_failure(
                    scratchpad,
                    issue="completed chain iteration 2 merge source digest changed",
                    contract_key=contract.key,
                    contract_digest=contract.digest,
                    source_sha256=source_sha,
                    preserve_applied_receipt=True,
                )
            for name in ("chain_hypotheses.md", "composition_coverage.md"):
                path = scratchpad / name
                expected = ((prior.get("targets") or {}).get(name) or {}).get(
                    "after_sha256"
                )
                if not path.exists() or _sha256_bytes(path.read_bytes()) != expected:
                    return _chain_iter2_merge_failure(
                        scratchpad,
                        issue=f"completed chain iteration 2 merge target drifted: {name}",
                        contract_key=contract.key,
                        contract_digest=contract.digest,
                        source_sha256=source_sha,
                        preserve_applied_receipt=True,
                    )
            return prior

    intent_path = (
        scratchpad / f"_chain_iter2_merge_intent.{generation_id}.json"
    )
    if intent_path.exists():
        try:
            intent = json.loads(intent_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            intent = {}
        return _resume_chain_iter2_merge_intent(
            scratchpad,
            intent,
            contract_key=contract.key,
            contract_digest=contract.digest,
            source_sha256=source_sha,
        )

    if not chain_target.exists() or not coverage_target.exists():
        missing = [
            path.name for path in (chain_target, coverage_target) if not path.exists()
        ]
        return _chain_iter2_merge_failure(
            scratchpad,
            issue="driver merge target missing: " + ", ".join(missing),
            contract_key=contract.key,
            contract_digest=contract.digest,
            source_sha256=source_sha,
        )

    delta_text = source_bytes.decode("utf-8", errors="replace").replace(
        "\r\n", "\n"
    ).replace("\r", "\n")
    sections, duplicate_ids = _chain_delta_sections(delta_text)
    tail_table = _chain_tail_table(delta_text)
    if duplicate_ids:
        return _chain_iter2_merge_failure(
            scratchpad,
            issue="duplicate chain identity inside delta: " + ", ".join(duplicate_ids),
            contract_key=contract.key,
            contract_digest=contract.digest,
            source_sha256=source_sha,
            collision_ids=tuple(duplicate_ids),
        )
    if not tail_table:
        return _chain_iter2_merge_failure(
            scratchpad,
            issue="chain iteration 2 delta lacks an exact tail disposition table",
            contract_key=contract.key,
            contract_digest=contract.digest,
            source_sha256=source_sha,
        )

    chain_before_bytes = chain_target.read_bytes()
    coverage_before_bytes = coverage_target.read_bytes()
    chain_before = chain_before_bytes.decode("utf-8", errors="replace").replace(
        "\r\n", "\n"
    ).replace("\r", "\n")
    coverage_before = coverage_before_bytes.decode(
        "utf-8", errors="replace"
    ).replace("\r\n", "\n").replace("\r", "\n")
    prior_ids = _chain_heading_ids(chain_before)
    delta_ids = [cid for cid, _ in sections]
    collisions = tuple(sorted(set(prior_ids) & set(delta_ids)))
    if collisions:
        return _chain_iter2_merge_failure(
            scratchpad,
            issue="chain identity collision blocks driver merge: " + ", ".join(collisions),
            contract_key=contract.key,
            contract_digest=contract.digest,
            source_sha256=source_sha,
            collision_ids=collisions,
        )

    marker = f"plamen:chain-iter2:{source_sha}"
    chain_block = (
        "\n\n<!-- " + marker + ":chains BEGIN -->\n"
        + ("\n\n".join(section for _, section in sections) if sections else
           "_No additional chain hypotheses were emitted._")
        + "\n<!-- " + marker + ":chains END -->\n"
    )
    coverage_block = (
        "\n\n<!-- " + marker + ":coverage BEGIN -->\n"
        "## Iteration 2 Coverage Delta\n\n"
        + tail_table
        + "\n<!-- " + marker + ":coverage END -->\n"
    )
    chain_after_bytes = chain_before_bytes.rstrip() + chain_block.encode("utf-8")
    coverage_after_bytes = coverage_before_bytes.rstrip() + coverage_block.encode("utf-8")
    chain_before_ids = tuple(sorted(set(prior_ids)))
    chain_after_ids = tuple(sorted(set(prior_ids) | set(delta_ids)))
    coverage_before_ids = tuple(_chain_coverage_pair_ids(coverage_before))
    coverage_after_ids = tuple(sorted(
        set(coverage_before_ids) | set(_chain_coverage_pair_ids(tail_table))
    ))

    events: list[DriverMergeEvent] = []
    for artifact, before_bytes, after_bytes, identities_before, identities_after in (
        (
            "scratchpad:chain_hypotheses.md", chain_before_bytes,
            chain_after_bytes, chain_before_ids, chain_after_ids,
        ),
        (
            "scratchpad:composition_coverage.md", coverage_before_bytes,
            coverage_after_bytes, coverage_before_ids, coverage_after_ids,
        ),
    ):
        event = DriverMergeEvent(
            work_unit_key=contract.key,
            contract_digest=contract.digest,
            artifact_identity=artifact,
            before_sha256=_sha256_bytes(before_bytes),
            after_sha256=_sha256_bytes(after_bytes),
            source_identities=("scratchpad:chain_iteration2.md",),
            identities_before=identities_before,
            identities_after=identities_after,
        )
        event.validate_against(contract)
        events.append(event)

    receipt: dict[str, Any] = {
        "schema": "plamen.chain-iter2-driver-merge.v1",
        "status": "APPLIED",
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "source_sha256": source_sha,
        "added_chain_ids": sorted(delta_ids),
        "collision_ids": [],
        "issues": [],
        "events": [event.to_dict() for event in events],
        "targets": {
            "chain_hypotheses.md": {
                "before_sha256": _sha256_bytes(chain_before_bytes),
                "after_sha256": _sha256_bytes(chain_after_bytes),
            },
            "composition_coverage.md": {
                "before_sha256": _sha256_bytes(coverage_before_bytes),
                "after_sha256": _sha256_bytes(coverage_after_bytes),
            },
        },
    }
    intent = {
        "schema": "plamen.chain-iter2-driver-merge-intent.v1",
        "status": "INTENT",
        "source_sha256": source_sha,
        "receipt": receipt,
        "append_blocks": {
            "chain_hypotheses.md": chain_block,
            "composition_coverage.md": coverage_block,
        },
    }
    _atomic_driver_json_record(intent_path, intent)
    return _resume_chain_iter2_merge_intent(
        scratchpad,
        intent,
        contract_key=contract.key,
        contract_digest=contract.digest,
        source_sha256=source_sha,
    )


def _chain_iter2_driver_merge_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the exact deterministic chain-delta merge boundary."""

    root = Path(scratchpad)
    pipeline = str(config.get("pipeline") or "sc")
    mode = str(config.get("mode") or "thorough")
    ecosystem = str(config.get("language") or "unknown")
    backend = str(config.get("cli_backend") or config.get("backend") or "claude")
    pass_index, shard_count, _generation_id = (
        _current_chain_tail_generation(root)
    )
    contract = resolve_phase_io_contract(
        pipeline=pipeline,
        mode=mode,
        ecosystem=ecosystem,
        backend=backend,
        phase="chain_iter2",
        work_unit_id=_chain_tail_scoped_work_unit_id(
            "driver_merge",
            pass_index,
            shard_count,
        ),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=pipeline,
        mode=mode,
        ecosystem=ecosystem,
        backend=backend,
        model="driver",
        timeout_s=30,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    # Resolve the path now so a malformed caller cannot arm against one root
    # and execute against another through a late Path coercion.
    root.resolve()
    return contract, launch


def _chain_iter2_merge_events_from_receipt(
    receipt: Mapping[str, Any],
    contract: PhaseIOContract,
) -> dict[str, DriverMergeEvent]:
    """Rehydrate and validate the complete merge-event denominator."""

    if (
        receipt.get("schema") != "plamen.chain-iter2-driver-merge.v1"
        or receipt.get("status") != "APPLIED"
        or receipt.get("work_unit_key") != contract.key
        or receipt.get("contract_digest") != contract.digest
    ):
        raise ValueError("chain iteration 2 merge receipt authority mismatch")
    raw_events = receipt.get("events")
    if not isinstance(raw_events, list):
        raise ValueError("chain iteration 2 merge events are absent")
    events: dict[str, DriverMergeEvent] = {}
    for raw in raw_events:
        if not isinstance(raw, Mapping):
            raise ValueError("chain iteration 2 merge event is malformed")
        event = DriverMergeEvent(
            work_unit_key=str(raw.get("work_unit_key") or ""),
            contract_digest=str(raw.get("contract_digest") or ""),
            artifact_identity=str(raw.get("artifact_identity") or ""),
            before_sha256=str(raw.get("before_sha256") or ""),
            after_sha256=str(raw.get("after_sha256") or ""),
            source_identities=tuple(raw.get("source_identities") or ()),
            identities_before=tuple(raw.get("identities_before") or ()),
            identities_after=tuple(raw.get("identities_after") or ()),
            event_version=str(
                raw.get("event_version") or "plamen.driver_merge.v1"
            ),
        )
        event.validate_against(contract)
        if event.artifact_identity in events:
            raise ValueError(
                "duplicate chain iteration 2 merge event identity"
            )
        events[event.artifact_identity] = event
    expected = {
        spec.identity
        for spec in contract.outputs
        if spec.writer == "DRIVER" and spec.write_mode == "MERGE"
    }
    if set(events) != expected:
        raise ValueError(
            "chain iteration 2 merge event denominator mismatch"
        )
    return events


def _full_committed_producer_authority(
    scratchpad: Path,
    project_root: Path,
    *,
    ledger: Mapping[str, Any],
    outer_work_unit_key: str,
    run_id: str,
    expected_input_identities: Sequence[str] | None,
    expected_output_identities: Sequence[str],
    actor: str,
    require_live_input_authority: bool = True,
) -> tuple[Mapping[str, Any] | None, list[str]]:
    """Replay one exact committed producer through generic ArtifactLedger APIs."""

    key = str(outer_work_unit_key or "").strip()
    run = str(run_id or "").strip()
    actor_n = str(actor or "").strip().upper()
    issues: list[str] = []
    units = ledger.get("work_units")
    unit = units.get(key) if isinstance(units, Mapping) and key else None
    if not isinstance(unit, Mapping):
        return None, [f"{key or '<missing>'}: producer authority is absent"]
    if unit.get("schema") != "plamen.artifact-work-unit.v2":
        issues.append(f"{key}: producer work-unit schema mismatch")
    if unit.get("work_unit_key") != key:
        issues.append(
            f"{key}: outer/inner producer work-unit key mismatch"
        )
    if unit.get("run_id") != run or not run:
        issues.append(f"{key}: producer run_id mismatch")
    if actor_n not in {"DRIVER", "MODEL"}:
        issues.append(f"{key}: producer validation actor is invalid")
    elif unit.get("model_invoked") is not (actor_n == "MODEL"):
        issues.append(f"{key}: producer actor/model-invocation mismatch")

    parts = key.split("/")
    if len(parts) != 6:
        issues.append(f"{key}: producer work-unit key is malformed")
        return unit, list(dict.fromkeys(issues))

    manifest = unit.get("contract_manifest")
    manifest_inputs: list[str] = []
    manifest_outputs: list[str] = []
    if not isinstance(manifest, Mapping):
        issues.append(f"{key}: producer contract manifest is absent")
    else:
        immutable = manifest.get("immutable_inputs")
        bounded = manifest.get("bounded_lookup_inputs")
        output_rows = manifest.get("outputs")
        if (
            not isinstance(immutable, list)
            or not isinstance(bounded, list)
            or any(
                not isinstance(identity, str)
                for identity in (*immutable, *bounded)
            )
            or len(set((*immutable, *bounded)))
            != len(immutable) + len(bounded)
        ):
            issues.append(f"{key}: producer input denominator is malformed")
        else:
            manifest_inputs = [*immutable, *bounded]
        if (
            not isinstance(output_rows, list)
            or any(not isinstance(row, Mapping) for row in output_rows)
        ):
            issues.append(f"{key}: producer output denominator is malformed")
        else:
            manifest_outputs = [
                str(row.get("identity") or "") for row in output_rows
            ]
            if (
                any(not identity for identity in manifest_outputs)
                or len(set(manifest_outputs)) != len(manifest_outputs)
            ):
                issues.append(
                    f"{key}: producer output denominator is malformed"
                )

    if expected_input_identities is not None:
        expected_inputs = tuple(
            str(identity) for identity in expected_input_identities
        )
        if (
            len(set(expected_inputs)) != len(expected_inputs)
            or set(manifest_inputs) != set(expected_inputs)
        ):
            issues.append(
                f"{key}: producer input denominator differs from expectation"
            )
    expected_outputs = tuple(
        str(identity) for identity in expected_output_identities
    )
    if (
        len(set(expected_outputs)) != len(expected_outputs)
        or set(manifest_outputs) != set(expected_outputs)
    ):
        issues.append(
            f"{key}: producer output denominator differs from expectation"
        )

    contract: PhaseIOContract | None = None
    try:
        if any(
            not identity.startswith("scratchpad:")
            for identity in (*manifest_inputs, *manifest_outputs)
        ):
            raise ValueError(
                "chain producer identities must be scratchpad-relative"
            )
        contract = resolve_phase_io_contract(
            pipeline=parts[0],
            mode=parts[1],
            ecosystem=parts[2],
            backend=parts[3],
            phase=parts[4],
            work_unit_id=parts[5],
            exact_inputs=tuple(
                identity.split(":", 1)[1] for identity in manifest_inputs
            ),
            exact_outputs=tuple(
                identity.split(":", 1)[1] for identity in manifest_outputs
            ),
        )
        if (
            contract.key != key
            or contract.digest != unit.get("contract_digest")
            or contract.to_dict() != manifest
        ):
            issues.append(
                f"{key}: producer contract manifest/digest does not replay"
            )
        if actor_n in {"DRIVER", "MODEL"} and any(
            spec.writer != actor_n for spec in contract.outputs
        ):
            issues.append(f"{key}: producer contract writer mismatch")
    except (IndexError, KeyError, TypeError, ValueError) as exc:
        issues.append(
            f"{key}: producer registered contract is invalid: {exc}"
        )

    launch: LaunchSpec | None = None
    launch_manifest = unit.get("launch_manifest")
    launch_fields = {
        "launch_version",
        "work_unit_key",
        "pipeline",
        "mode",
        "ecosystem",
        "backend",
        "model",
        "timeout_s",
        "exec_mode",
        "tool_policy",
    }
    if (
        not isinstance(launch_manifest, Mapping)
        or set(launch_manifest) != launch_fields
    ):
        issues.append(f"{key}: producer launch manifest is malformed")
    else:
        try:
            launch = LaunchSpec(
                work_unit_key=launch_manifest["work_unit_key"],
                pipeline=launch_manifest["pipeline"],
                mode=launch_manifest["mode"],
                ecosystem=launch_manifest["ecosystem"],
                backend=launch_manifest["backend"],
                model=launch_manifest["model"],
                timeout_s=launch_manifest["timeout_s"],
                exec_mode=launch_manifest["exec_mode"],
                tool_policy=tuple(launch_manifest["tool_policy"]),
                launch_version=launch_manifest["launch_version"],
            )
            expected_exec = (
                "python"
                if actor_n == "DRIVER"
                else "codex"
                if parts[3] == "codex"
                else "headless"
            )
            if (
                launch.work_unit_key != key
                or (
                    launch.pipeline,
                    launch.mode,
                    launch.ecosystem,
                    launch.backend,
                )
                != tuple(parts[:4])
                or launch.launch_version != "plamen.launch.v1"
                or launch.exec_mode != expected_exec
                or launch.tool_policy != ("filesystem",)
                or (actor_n == "DRIVER" and launch.model != "driver")
                or (actor_n == "MODEL" and launch.model == "driver")
            ):
                issues.append(
                    f"{key}: producer launch profile does not replay"
                )
        except (KeyError, TypeError, ValueError) as exc:
            issues.append(
                f"{key}: producer launch manifest is invalid: {exc}"
            )

    try:
        issues.extend(active_committed_work_unit_authority_issues(
            ledger,
            work_unit_key=key,
            run_id=run,
            expected_artifact_identities=expected_outputs,
        ))
    except (AttributeError, KeyError, TypeError, ValueError) as exc:
        issues.append(
            f"{key}: generic producer authority replay failed: {exc}"
        )
    if contract is not None and launch is not None:
        issues.extend(validate_work_unit_artifacts(
            Path(scratchpad),
            Path(project_root),
            contract,
            launch,
            run_id=run,
            actor=actor_n,
            require_live_input_authority=require_live_input_authority,
        ))
    return unit, list(dict.fromkeys(issues))


def _read_current_chain_iter2_driver_merge_replay(
    scratchpad: Path,
    project_root: Path,
    *,
    ledger: Mapping[str, Any],
    contract: PhaseIOContract,
    run_id: str,
    generation_id: str,
) -> dict[str, Any]:
    """Validate and return one exact committed current-G merge read-only."""

    root = Path(scratchpad)
    source_identity = "scratchpad:chain_iteration2.md"
    target_names = {
        "scratchpad:chain_hypotheses.md": "chain_hypotheses.md",
        "scratchpad:composition_coverage.md": "composition_coverage.md",
    }
    target_identities = tuple(target_names)
    units = ledger.get("work_units")
    unit = (
        units.get(contract.key)
        if isinstance(units, Mapping)
        else None
    )
    if (
        not isinstance(unit, Mapping)
        or unit.get("semantic_status") != "ACTIVE"
        or unit.get("execution_state") != "OUTPUT_COMMITTED"
    ):
        raise ValueError("current merge unit is not exactly committed")

    bindings = ledger.get("artifact_bindings")
    if not isinstance(bindings, Mapping):
        raise ValueError("current merge artifact bindings are absent")
    for identity in target_identities:
        binding = bindings.get(identity)
        if (
            not isinstance(binding, Mapping)
            or binding.get("owner_key") != contract.key
        ):
            raise ValueError("current merge target owner mismatch")

    committed_unit, authority_issues = _full_committed_producer_authority(
        root,
        Path(project_root),
        ledger=ledger,
        outer_work_unit_key=contract.key,
        run_id=run_id,
        expected_input_identities=(source_identity,),
        expected_output_identities=target_identities,
        actor="DRIVER",
        require_live_input_authority=True,
    )
    if authority_issues or not isinstance(committed_unit, Mapping):
        raise ValueError("current merge committed authority does not replay")

    receipt_path = (
        root / f"_chain_iter2_merge_receipt.{generation_id}.json"
    )
    raw_receipt = receipt_path.read_bytes()
    receipt = json.loads(raw_receipt.decode("utf-8"))
    if type(receipt) is not dict:
        raise ValueError("current merge receipt is not an object")
    if raw_receipt != (
        json.dumps(receipt, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8"):
        raise ValueError("current merge receipt is not canonical")

    receipt_fields = {
        "schema",
        "status",
        "work_unit_key",
        "contract_digest",
        "source_sha256",
        "added_chain_ids",
        "collision_ids",
        "issues",
        "events",
        "targets",
    }
    if set(receipt) != receipt_fields:
        raise ValueError("current merge receipt field set mismatch")
    if (
        receipt.get("schema")
        != "plamen.chain-iter2-driver-merge.v1"
        or receipt.get("status") != "APPLIED"
        or receipt.get("work_unit_key") != contract.key
        or receipt.get("contract_digest") != contract.digest
        or receipt.get("collision_ids") != []
        or receipt.get("issues") != []
    ):
        raise ValueError("current merge receipt authority mismatch")

    raw_added = receipt.get("added_chain_ids")
    if (
        type(raw_added) is not list
        or any(
            type(identity) is not str
            or not identity
            or identity != identity.strip()
            for identity in raw_added
        )
        or raw_added != sorted(set(raw_added))
    ):
        raise ValueError("current merge added identity set is malformed")

    raw_events = receipt.get("events")
    if (
        type(raw_events) is not list
        or len(raw_events) != len(target_identities)
        or any(type(event) is not dict for event in raw_events)
    ):
        raise ValueError("current merge receipt event set is malformed")
    events = _chain_iter2_merge_events_from_receipt(receipt, contract)
    if [
        event.get("artifact_identity") for event in raw_events
    ] != list(target_identities):
        raise ValueError("current merge receipt event order mismatch")
    if any(
        raw_event != events[identity].to_dict()
        for raw_event, identity in zip(
            raw_events, target_identities, strict=True
        )
    ):
        raise ValueError("current merge receipt event shape mismatch")
    if any(
        event.source_identities != (source_identity,)
        for event in events.values()
    ):
        raise ValueError("current merge receipt source denominator mismatch")
    if raw_added != list(
        events["scratchpad:chain_hypotheses.md"].added_identities
    ):
        raise ValueError("current merge added identity delta mismatch")

    input_bindings = committed_unit.get("input_bindings")
    artifacts = committed_unit.get("artifacts")
    output_prestates = committed_unit.get("output_prestates")
    commit_authority = committed_unit.get("commit_authority")
    transitions = (
        commit_authority.get("read_modify_write_transitions")
        if isinstance(commit_authority, Mapping)
        else None
    )
    if (
        not isinstance(input_bindings, Mapping)
        or set(input_bindings) != {source_identity}
        or not isinstance(artifacts, Mapping)
        or set(artifacts) != set(target_identities)
        or not isinstance(output_prestates, Mapping)
        or set(output_prestates) != set(target_identities)
        or not isinstance(transitions, Mapping)
        or set(transitions) != set(target_identities)
    ):
        raise ValueError("current merge committed denominator mismatch")

    source_path = root / "chain_iteration2.md"
    source_bytes = source_path.read_bytes()
    source_sha256 = _sha256_bytes(source_bytes)
    source_input = input_bindings.get(source_identity)
    source_binding = bindings.get(source_identity)
    if (
        not isinstance(source_input, Mapping)
        or not isinstance(source_binding, Mapping)
        or receipt.get("source_sha256") != source_sha256
        or source_input.get("sha256") != source_sha256
        or source_input.get("size") != len(source_bytes)
        or source_binding.get("sha256") != source_sha256
        or source_binding.get("size") != len(source_bytes)
    ):
        raise ValueError("current merge source digest mismatch")

    raw_targets = receipt.get("targets")
    if (
        type(raw_targets) is not dict
        or set(raw_targets) != set(target_names.values())
    ):
        raise ValueError("current merge receipt target set mismatch")
    for identity, name in target_names.items():
        raw_target = raw_targets.get(name)
        event = events[identity]
        prestate = output_prestates.get(identity)
        artifact = artifacts.get(identity)
        binding = bindings.get(identity)
        transition = transitions.get(identity)
        if (
            type(raw_target) is not dict
            or set(raw_target) != {
                "before_sha256",
                "after_sha256",
            }
            or not isinstance(prestate, Mapping)
            or not isinstance(artifact, Mapping)
            or not isinstance(binding, Mapping)
            or not isinstance(transition, Mapping)
        ):
            raise ValueError("current merge target authority is malformed")

        expected_transition = {
            "write_mode": "MERGE",
            "preimage_sha256": event.before_sha256,
            "successor_sha256": event.after_sha256,
            "source_identities": list(event.source_identities),
            "identities_before": list(event.identities_before),
            "identities_after": list(event.identities_after),
            "merge_event_digest": event.digest,
        }
        target_bytes = (root / name).read_bytes()
        target_sha256 = _sha256_bytes(target_bytes)
        if (
            raw_target.get("before_sha256") != event.before_sha256
            or raw_target.get("before_sha256")
            != prestate.get("sha256")
            or raw_target.get("after_sha256") != event.after_sha256
            or transition != expected_transition
            or artifact.get("sha256") != event.after_sha256
            or artifact.get("size") != len(target_bytes)
            or binding.get("owner_key") != contract.key
            or binding.get("sha256") != event.after_sha256
            or binding.get("size") != len(target_bytes)
            or target_sha256 != event.after_sha256
        ):
            raise ValueError("current merge target digest mismatch")
    return dict(receipt)


def _run_and_record_chain_iter2_driver_merge(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[dict[str, Any], list[str]]:
    """Arm, execute, and commit the deterministic chain merge transaction."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return (
            {"status": "FAILED", "issues": ["chain merge run_id is absent"]},
            ["chain iteration 2 merge PhaseIO cannot bind without a run_id"],
        )
    project_root = Path(str(config.get("project_root") or root.parent))
    try:
        artifact_state = read_artifact_ledger(root)
        pass_index, shard_count, generation_id = (
            _current_chain_tail_generation(root)
        )
        source_identity = "scratchpad:chain_iteration2.md"
        source_binding = artifact_state.get("artifact_bindings", {}).get(
            source_identity
        )
        terminal_prefix = (
            f"{str(config.get('pipeline') or 'sc')}/"
            f"{str(config.get('mode') or 'thorough')}/"
            f"{str(config.get('language') or 'unknown')}/"
            f"{str(config.get('cli_backend') or config.get('backend') or 'claude')}/"
            "chain_iter2/"
        )
        expected_parent_key = (
            terminal_prefix
            + _chain_tail_scoped_work_unit_id(
                "tail_reconcile",
                pass_index,
                shard_count,
            )
        )
        parent_key = (
            str(source_binding.get("owner_key") or "")
            if isinstance(source_binding, Mapping)
            else ""
        )
        parent_inputs = {
            f"scratchpad:{_CHAIN_TAIL_CONTROL_MANIFEST}",
            "scratchpad:chain_tail_terminal_snapshot.json",
            *(
                {"scratchpad:chain_hypotheses.md"}
                if (root / "chain_hypotheses.md").is_file()
                else set()
            ),
        }
        parent_unit, parent_issues = _full_committed_producer_authority(
            root,
            project_root,
            ledger=artifact_state,
            outer_work_unit_key=expected_parent_key,
            run_id=run_id,
            expected_input_identities=tuple(sorted(parent_inputs)),
            expected_output_identities=tuple(
                f"scratchpad:{name}"
                for name in _CHAIN_TAIL_FINAL_PUBLICATION_OUTPUTS
            ),
            actor="DRIVER",
            require_live_input_authority=False,
        )
        snapshot_identity = (
            "scratchpad:chain_tail_terminal_snapshot.json"
        )
        parent_snapshot = (
            parent_unit.get("input_bindings", {}).get(snapshot_identity)
            if isinstance(parent_unit, Mapping)
            and isinstance(parent_unit.get("input_bindings"), Mapping)
            else None
        )
        snapshot_key = (
            terminal_prefix
            + _chain_tail_scoped_work_unit_id(
                "tail_snapshot",
                pass_index,
                shard_count,
            )
        )
        snapshot_unit, snapshot_issues = (
            _full_committed_producer_authority(
                root,
                project_root,
                ledger=artifact_state,
                outer_work_unit_key=snapshot_key,
                run_id=run_id,
                expected_input_identities=None,
                expected_output_identities=(snapshot_identity,),
                actor="DRIVER",
                require_live_input_authority=False,
            )
        )
        snapshot_artifact = (
            snapshot_unit.get("artifacts", {}).get(snapshot_identity)
            if isinstance(snapshot_unit, Mapping)
            and isinstance(snapshot_unit.get("artifacts"), Mapping)
            else None
        )
        snapshot_commit = (
            snapshot_unit.get("commit_authority")
            if isinstance(snapshot_unit, Mapping)
            else None
        )
        snapshot_generation_exact = bool(
            isinstance(parent_snapshot, Mapping)
            and isinstance(snapshot_unit, Mapping)
            and isinstance(snapshot_artifact, Mapping)
            and isinstance(snapshot_commit, Mapping)
            and parent_snapshot.get("status") == "ACTIVE"
            and parent_snapshot.get("producer_work_unit_key")
            == snapshot_key
            and parent_snapshot.get("producer_run_id") == run_id
            and parent_snapshot.get("producer_writer") == "DRIVER"
            and parent_snapshot.get("producer_contract_digest")
            == snapshot_unit.get("contract_digest")
            and parent_snapshot.get("producer_launch_digest")
            == snapshot_unit.get("launch_digest")
            and parent_snapshot.get("producer_commit_receipt_digest")
            == snapshot_commit.get("receipt_digest")
            and parent_snapshot.get("sha256")
            == snapshot_artifact.get("sha256")
            and parent_snapshot.get("size") == snapshot_artifact.get("size")
        )
        try:
            snapshot_payload_generation_exact = (
                _chain_tail_terminal_snapshot_generation(root)
                == (pass_index, shard_count, generation_id)
            )
        except (
            OSError,
            TypeError,
            ValueError,
            json.JSONDecodeError,
        ):
            snapshot_payload_generation_exact = False
        if (
            parent_key != expected_parent_key
            or not isinstance(source_binding, Mapping)
            or parent_issues
            or snapshot_issues
            or not snapshot_generation_exact
            or not snapshot_payload_generation_exact
        ):
            issue = (
                "chain iteration 2 driver merge requires the exact committed "
                "tail_reconcile parent"
            )
            return ({"status": "FAILED", "issues": [issue]}, [issue])

        contract, launch = _chain_iter2_driver_merge_contract_and_launch(
            root, config
        )
        expected_merge_key = (
            terminal_prefix
            + _chain_tail_scoped_work_unit_id(
                "driver_merge",
                pass_index,
                shard_count,
            )
        )
        if contract.key != expected_merge_key:
            issue = (
                "chain iteration 2 driver merge contract differs from "
                "current control generation"
            )
            return ({"status": "FAILED", "issues": [issue]}, [issue])

        bindings = artifact_state.get("artifact_bindings")
        target_identities = (
            "scratchpad:chain_hypotheses.md",
            "scratchpad:composition_coverage.md",
        )
        target_owners = tuple(
            str(binding.get("owner_key") or "")
            if isinstance(binding, Mapping)
            else ""
            for binding in (
                bindings.get(identity)
                if isinstance(bindings, Mapping)
                else None
                for identity in target_identities
            )
        )
        units = artifact_state.get("work_units")
        merge_unit_exists = bool(
            isinstance(units, Mapping)
            and expected_merge_key in units
        )
        merge_unit = (
            units.get(expected_merge_key)
            if isinstance(units, Mapping)
            else None
        )
        committed_current_unit = bool(
            isinstance(merge_unit, Mapping)
            and merge_unit.get("semantic_status") == "ACTIVE"
            and merge_unit.get("execution_state") == "OUTPUT_COMMITTED"
        )
        current_binding_claim = any(
            owner == expected_merge_key for owner in target_owners
        )
        current_replay_issue = (
            "chain iteration 2 driver merge current-generation replay "
            "authority invalid"
        )
        if committed_current_unit or current_binding_claim:
            try:
                receipt = _read_current_chain_iter2_driver_merge_replay(
                    root,
                    project_root,
                    ledger=artifact_state,
                    contract=contract,
                    run_id=run_id,
                    generation_id=generation_id,
                )
            except (
                ArtifactLedgerError,
                AttributeError,
                KeyError,
                OSError,
                TypeError,
                ValueError,
            ):
                return (
                    {
                        "status": "FAILED",
                        "issues": [current_replay_issue],
                    },
                    [current_replay_issue],
                )
            return receipt, []

        preexecution_input_issues: list[str] = []
        if merge_unit_exists:
            try:
                preexecution_input_issues = validate_work_unit_inputs(
                    root,
                    project_root,
                    contract,
                    launch,
                    run_id=run_id,
                )
            except (
                ArtifactLedgerError,
                AttributeError,
                KeyError,
                OSError,
                TypeError,
                ValueError,
            ):
                preexecution_input_issues = [current_replay_issue]
        preexecution_recovery = bool(
            isinstance(merge_unit, Mapping)
            and merge_unit.get("semantic_status") == "INPUTS_BOUND"
            and merge_unit.get("execution_state")
            == "INPUTS_BOUND_PREEXECUTION"
            and merge_unit.get("artifacts") == {}
            and merge_unit.get("run_id") == run_id
            and merge_unit.get("contract_digest") == contract.digest
            and merge_unit.get("launch_digest") == launch.digest
            and not preexecution_input_issues
        )
        if merge_unit_exists and not preexecution_recovery:
            return (
                {
                    "status": "FAILED",
                    "issues": [current_replay_issue],
                },
                [current_replay_issue],
            )

        # The two merge prestates form one atomic lineage.  Generation zero
        # starts from the exact ChainAgent2 MODEL owner; every later merge
        # must consume both siblings from one strictly earlier driver_merge G.
        target_lineages: set[tuple[str, int, int]] = set()
        expected_model_owner = (
            terminal_prefix.rsplit("/chain_iter2/", 1)[0]
            + "/chain_agent2/model"
        )
        for target_identity in target_identities:
            target_binding = (
                bindings.get(target_identity)
                if isinstance(bindings, Mapping)
                else None
            )
            target_owner = (
                str(target_binding.get("owner_key") or "")
                if isinstance(target_binding, Mapping)
                else ""
            )
            if target_owner == expected_model_owner:
                target_lineages.add(("MODEL", -1, -1))
                continue
            if not target_owner.startswith(terminal_prefix):
                target_lineages.add(("INVALID", -1, -1))
                continue
            try:
                prior_pass, prior_shards, _prior_generation_id = (
                    _chain_tail_generation_from_work_unit_key(
                        target_owner,
                        role="driver_merge",
                    )
                )
            except ValueError:
                target_lineages.add(("INVALID", -1, -1))
                continue
            if (prior_pass, prior_shards) >= (pass_index, shard_count):
                target_lineages.add(("INVALID", prior_pass, prior_shards))
                continue
            target_lineages.add(("DRIVER", prior_pass, prior_shards))
        if (
            len(target_lineages) != 1
            or next(iter(target_lineages))[0] == "INVALID"
        ):
            issue = (
                "chain iteration 2 driver merge requires one strictly "
                "earlier monotonic prestate lineage"
            )
            return ({"status": "FAILED", "issues": [issue]}, [issue])

        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return (
                {"status": "FAILED", "issues": list(issues)},
                list(issues),
            )
        if not execute:
            return (
                {
                    "status": "FAILED",
                    "issues": [current_replay_issue],
                },
                [current_replay_issue],
            )

        receipt = _apply_chain_iter2_driver_merge(root, dict(config))
        domain_issues: list[str] = []
        events: dict[str, DriverMergeEvent] = {}
        if receipt.get("status") != "APPLIED":
            domain_issues.extend(
                str(issue)
                for issue in (
                    receipt.get("issues")
                    or ["chain iteration 2 merge did not reach APPLIED"]
                )
            )
        else:
            try:
                events = _chain_iter2_merge_events_from_receipt(
                    receipt, contract
                )
            except (TypeError, ValueError) as exc:
                domain_issues.append(
                    "chain iteration 2 merge receipt invalid: "
                    f"{type(exc).__name__}: {exc}"
                )
        commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            domain_issues=domain_issues,
            merge_events=events,
        )
        return dict(receipt), list(dict.fromkeys(commit_issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        issue = (
            "chain iteration 2 merge PhaseIO failed: "
            f"{type(exc).__name__}: {exc}"
        )
        return ({"status": "FAILED", "issues": [issue]}, [issue])


def _run_chain_iter2_bounded_continuations(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> dict[str, Any]:
    """Close the typed chain tail through bounded, resume-stable work units.

    The normal phase subprocess produced shard zero.  Every later subprocess
    is launched through the same backend/runtime policy with a distinct attempt
    identity after the authority advances the exact cursor and rewrites only
    the bounded packet projection.  A declared shard/time budget or worker
    failure is durable assurance debt, never false phase completion.
    """
    from chain_tail_authority import _read_progress_receipt

    configured_shards = config.get("chain_tail_max_shards_per_run")
    if configured_shards is None:
        configured_shards = os.environ.get("PLAMEN_CHAIN_TAIL_MAX_SHARDS", "8")
    try:
        max_shards = max(1, min(128, int(configured_shards)))
    except (TypeError, ValueError):
        max_shards = 8
    configured_seconds = config.get("chain_tail_max_seconds")
    if configured_seconds is None:
        configured_seconds = os.environ.get("PLAMEN_CHAIN_TAIL_MAX_SECONDS", "")
    try:
        max_seconds = float(configured_seconds) if configured_seconds else None
        if max_seconds is not None:
            max_seconds = max(60.0, max_seconds)
    except (TypeError, ValueError):
        max_seconds = None

    root = Path(scratchpad)
    if not (
        root / "_chain_tail_control" / "scheduler_journal.json"
    ).is_file():
        legacy_issues: list[str] = []
        if not bool(config.get("_allow_legacy_chain_tail_adapter")):
            legacy_issues.append(
                "chain-tail legacy adapter lacks explicit eligibility"
            )
        shard_parent = root / "_chain_tail_shards"
        isolation_dirs = (
            [
                path
                for path in shard_parent.glob("shard_[0-9][0-9][0-9][0-9]")
                if path.is_dir()
            ]
            if shard_parent.is_dir()
            else []
        )
        if isolation_dirs:
            legacy_issues.append(
                "chain-tail isolation shard exists while scheduler journal is "
                "missing; legacy fallback is forbidden"
            )
        for marker in (
            "chain_tail_terminal_snapshot.json",
            "chain_tail_primary_receipt.json",
            "_chain_tail_control/final_publication.armed",
        ):
            if (root / marker).exists():
                legacy_issues.append(
                    f"chain-tail isolation marker forbids legacy adapter: {marker}"
                )
        try:
            units = read_artifact_ledger(root).get("work_units", {})
        except (ArtifactLedgerError, OSError, TypeError, ValueError):
            units = {}
        if any(
            isinstance(unit, Mapping)
            and "/chain_iter2/" in str(key)
            and any(
                token in str(key)
                for token in (
                    "tail_shard_",
                    "tail_primary",
                    "tail_snapshot",
                    "tail_reconcile",
                )
            )
            for key, unit in (
                units.items() if isinstance(units, Mapping) else ()
            )
        ):
            legacy_issues.append(
                "chain-tail PhaseIO isolation history forbids legacy adapter"
            )
        if legacy_issues:
            for issue in legacy_issues:
                _append_chain_iter2_debt_sentinel(root, issue)
            try:
                prior = _read_progress_receipt(root)
            except Exception:
                prior = {}
            return {
                **dict(prior),
                "status": "DEGRADED_UNRESOLVED",
                "issues": list(dict.fromkeys([
                    *(prior.get("issues") or []),
                    *legacy_issues,
                ])),
            }
        # Compatibility adapter for pre-isolation/direct-library callers.
        # Production materializes a shard before any model launch and therefore
        # always has the scheduler journal; it never enters this shared-path
        # adapter.
        from chain_tail_authority import run_chain_tail_shard_loop

        def legacy_execute(shard: dict[str, Any]) -> int:
            shard_index = int(shard.get("shard_index") or 0)
            continuation_config = dict(config)
            continuation_config["_chain_tail_shard_index"] = shard_index
            continuation_config["_chain_tail_manifest_sha256"] = str(
                shard.get("manifest_sha256") or ""
            )
            return run_phase(
                phase, continuation_config, 1001 + shard_index
            )

        return run_chain_tail_shard_loop(
            root,
            legacy_execute,
            max_shards_per_run=max_shards,
            max_seconds=max_seconds,
        )

    started = time.monotonic()
    processed_this_run = 1
    receipt = _read_progress_receipt(root)
    while receipt.get("status") == "CONTINUE":
        if processed_this_run >= max_shards:
            receipt, budget_issues = (
                _run_chain_tail_budget_stop_transaction(
                    scratchpad=root,
                    config=config,
                    phase=phase,
                    reason="CHAIN_TAIL_SHARD_BUDGET",
                )
            )
            if budget_issues:
                for issue in budget_issues:
                    _append_chain_iter2_debt_sentinel(root, issue)
                return {
                    **dict(receipt),
                    "status": "DEGRADED_UNRESOLVED",
                    "issues": list(dict.fromkeys([
                        *(receipt.get("issues") or []),
                        *budget_issues,
                    ])),
                }
            break
        if max_seconds is not None and time.monotonic() - started >= max_seconds:
            receipt, budget_issues = (
                _run_chain_tail_budget_stop_transaction(
                    scratchpad=root,
                    config=config,
                    phase=phase,
                    reason="CHAIN_TAIL_TIME_BUDGET",
                )
            )
            if budget_issues:
                for issue in budget_issues:
                    _append_chain_iter2_debt_sentinel(root, issue)
                return {
                    **dict(receipt),
                    "status": "DEGRADED_UNRESOLVED",
                    "issues": list(dict.fromkeys([
                        *(receipt.get("issues") or []),
                        *budget_issues,
                    ])),
                }
            break
        sources = tuple(
            name
            for name in (
                "composition_coverage.md",
                "chain_hypotheses.md",
                "findings_inventory.md",
                precedent_evidence_authority.CONTEXT_NAME,
            )
            if (root / name).is_file()
            and (
                name != precedent_evidence_authority.CONTEXT_NAME
                or bool(
                    config.get(
                        "_precedent_consumer_projection_state", {}
                    ).get("chain_iter2", False)
                )
            )
        )
        isolated, prepare_issues = _run_chain_tail_shard_prepare_transaction(
            scratchpad=root,
            config=config,
            phase=phase,
            source_names=sources,
        )
        if prepare_issues:
            for issue in prepare_issues:
                _append_chain_iter2_debt_sentinel(root, issue)
            return {
                **dict(receipt),
                "status": "DEGRADED_UNRESOLVED",
                "issues": list(dict.fromkeys([
                    *(receipt.get("issues") or []),
                    *prepare_issues,
                ])),
            }
        if not isolated.get("pair_ids"):
            break
        shard_index = int(isolated.get("shard_index") or 0)
        continuation_config = dict(config)
        continuation_config["scratchpad"] = str(root)
        continuation_config["_chain_tail_active_isolated"] = dict(isolated)
        continuation_config["_chain_tail_shard_index"] = shard_index
        continuation_config["_chain_tail_manifest_sha256"] = str(
            isolated.get("manifest_sha256") or ""
        )
        log.info(
            "[chain_iter2] launching bounded continuation shard %d (%d pair(s))",
            shard_index,
            len(isolated.get("pair_ids") or []),
        )
        try:
            model_contract, model_launch = (
                _chain_tail_shard_model_contract_and_launch(
                    scratchpad=root,
                    config=continuation_config,
                    phase=phase,
                    isolated=isolated,
                )
            )
            project_root = Path(
                continuation_config.get("project_root") or root.parent
            )
            run_id = str(
                continuation_config.get("_run_id") or "test-unbound"
            )
            record_work_unit_inputs(
                root,
                project_root,
                model_contract,
                model_launch,
                run_id=run_id,
            )
            arm_issues = validate_work_unit_inputs(
                root,
                project_root,
                model_contract,
                model_launch,
                run_id=run_id,
            )
            if arm_issues:
                raise ArtifactLedgerError("; ".join(arm_issues))
            # Attempts 1001+ are a separate namespace from the outer phase's
            # ordinary retry attempts and remain stable across a cursor replay.
            rc = run_phase(
                replace(
                    phase,
                    expected_artifacts=[isolated["transcript_path"]],
                ),
                continuation_config,
                1001 + shard_index,
            )
            processed_this_run += 1
            if rc != 0:
                failure_commit_issues = _run_chain_tail_failure_transaction(
                    scratchpad=root,
                    config=continuation_config,
                    phase=phase,
                    isolated=isolated,
                    reason=(
                        "CHAIN_TAIL_WORKER_TIMEOUT"
                        if rc == -2
                        else "CHAIN_TAIL_WORKER_FAILURE"
                    ),
                )
                if failure_commit_issues:
                    raise ArtifactLedgerError(
                        "; ".join(failure_commit_issues)
                    )
                receipt = _read_progress_receipt(root)
                break
            receipt = _read_progress_receipt(root)
        except Exception as exc:
            failure_commit_issues = _run_chain_tail_failure_transaction(
                scratchpad=root,
                config=continuation_config,
                phase=phase,
                isolated=isolated,
                reason=f"CHAIN_TAIL_CONTINUATION_{type(exc).__name__}",
            )
            issue = (
                "chain-tail continuation transaction failed haltlessly: "
                f"{type(exc).__name__}: {exc}"
            )
            _append_chain_iter2_debt_sentinel(root, issue)
            for failure_issue in failure_commit_issues:
                _append_chain_iter2_debt_sentinel(root, failure_issue)
            if failure_commit_issues:
                receipt = {
                    **dict(_read_progress_receipt(root)),
                    "status": "DEGRADED_UNRESOLVED",
                    "issues": list(dict.fromkeys([
                        issue,
                        *failure_commit_issues,
                    ])),
                }
            else:
                receipt = _read_progress_receipt(root)
            break

    final_receipt, final_issues = _run_chain_tail_final_reconcile_transaction(
        root, config, phase
    )
    for issue in final_issues:
        _append_chain_iter2_debt_sentinel(root, issue)
    return final_receipt if not final_issues else {
        **final_receipt,
        "issues": list(dict.fromkeys([
            *(final_receipt.get("issues") or []),
            *final_issues,
        ])),
    }


