def _validated_chain_tail_generation(
    pass_index: Any,
    shard_count: Any,
) -> tuple[int, int, str]:
    """Return one exact bounded chain-tail generation and its canonical id."""

    from chain_tail_authority import chain_tail_generation_id

    if (
        not isinstance(pass_index, int)
        or isinstance(pass_index, bool)
        or not isinstance(shard_count, int)
        or isinstance(shard_count, bool)
        or not 0 <= pass_index <= 9999
        or not 0 <= shard_count <= 9999
    ):
        raise ValueError("chain-tail generation is outside the exact bounds")
    generation_id = chain_tail_generation_id(pass_index, shard_count)
    expected = f"p{pass_index:04d}.s{shard_count:04d}"
    if generation_id != expected:
        raise ValueError("chain-tail generation helper returned a non-canonical id")
    return pass_index, shard_count, generation_id


def _current_chain_tail_generation(
    scratchpad: Path,
) -> tuple[int, int, str]:
    """Derive G only from CTA's validated authoritative control ledger."""

    from chain_tail_authority import chain_tail_control_generation

    generation = chain_tail_control_generation(Path(scratchpad))
    if (
        not isinstance(generation, tuple)
        or len(generation) != 2
    ):
        raise ValueError("chain-tail control generation helper is malformed")
    return _validated_chain_tail_generation(*generation)


def _chain_tail_scoped_work_unit_id(
    role: str,
    pass_index: int,
    shard_count: int,
) -> str:
    """Build one exact generation-scoped terminal work-unit id."""

    role_n = str(role or "").strip()
    if role_n not in {"tail_snapshot", "tail_reconcile", "driver_merge"}:
        raise ValueError(f"unsupported chain-tail terminal role: {role!r}")
    _pass, _shards, generation_id = _validated_chain_tail_generation(
        pass_index,
        shard_count,
    )
    return f"{role_n}.{generation_id}"


def _chain_tail_generation_from_work_unit_key(
    work_unit_key: str,
    *,
    role: str,
) -> tuple[int, int, str]:
    """Parse one exact full terminal key without scan/latest fallback."""

    parts = str(work_unit_key or "").split("/")
    if len(parts) != 6:
        raise ValueError("chain-tail terminal work-unit key is malformed")
    match = re.fullmatch(
        rf"{re.escape(role)}\.p(\d{{4}})\.s(\d{{4}})",
        parts[-1],
    )
    if match is None:
        raise ValueError(
            f"chain-tail terminal work-unit is not exact {role} authority"
        )
    return _validated_chain_tail_generation(
        int(match.group(1)),
        int(match.group(2)),
    )


def _chain_tail_terminal_snapshot_generation(
    scratchpad: Path,
) -> tuple[int, int, str]:
    """Validate and return frozen v2 snapshot G, including semantic-ledger join."""

    root = Path(scratchpad)
    payload = json.loads(
        (root / "chain_tail_terminal_snapshot.json").read_text(
            encoding="utf-8",
            errors="strict",
        )
    )
    if (
        not isinstance(payload, Mapping)
        or payload.get("schema_version")
        != "plamen.chain_tail.terminal_snapshot.v2"
    ):
        raise ValueError(
            "chain-tail terminal snapshot is legacy or has an invalid schema"
        )
    generation = payload.get("terminal_generation")
    semantic_ledger = payload.get("semantic_ledger")
    if (
        not isinstance(generation, Mapping)
        or set(generation)
        != {"pass_index", "shard_count", "generation_id"}
        or not isinstance(semantic_ledger, Mapping)
        or not isinstance(semantic_ledger.get("shards"), list)
    ):
        raise ValueError(
            "chain-tail terminal snapshot generation denominator is malformed"
        )
    pass_index, shard_count, generation_id = _validated_chain_tail_generation(
        generation.get("pass_index"),
        generation.get("shard_count"),
    )
    if (
        generation.get("generation_id") != generation_id
        or semantic_ledger.get("pass_index") != pass_index
        or len(semantic_ledger.get("shards") or []) != shard_count
    ):
        raise ValueError(
            "chain-tail terminal snapshot generation does not join its "
            "semantic ledger"
        )
    return pass_index, shard_count, generation_id


def _chain_tail_root_semantic_generation(
    scratchpad: Path,
) -> tuple[int, int, str]:
    """Return exact G from the frozen root semantic ledger."""

    root_ledger = json.loads(
        (Path(scratchpad) / "chain_tail_disposition_ledger.json").read_text(
            encoding="utf-8",
            errors="strict",
        )
    )
    if (
        not isinstance(root_ledger, Mapping)
        or not isinstance(root_ledger.get("shards"), list)
    ):
        raise ValueError("chain-tail root semantic ledger is malformed")
    return _validated_chain_tail_generation(
        root_ledger.get("pass_index"),
        len(root_ledger.get("shards") or []),
    )


def _chain_tail_legacy_fixed_generation_issues(
    scratchpad: Path,
    config: Mapping[str, Any] | None = None,
) -> list[str]:
    """Report exact legacy fixed residue without reading it as authority."""

    root = Path(scratchpad)
    residue: list[str] = []
    for name in (
        "_chain_iter2_merge_receipt.json",
        "_chain_iter2_merge_intent.json",
        "_chain_iter2_merge_failure.json",
    ):
        if (root / name).exists():
            residue.append(name)

    try:
        units = read_artifact_ledger(root).get("work_units")
    except (ArtifactLedgerError, OSError, TypeError, ValueError):
        units = {}
    fixed_roles = {
        "tail_snapshot",
        "tail_reconcile",
        "driver_merge",
    }
    if isinstance(units, Mapping):
        for raw_key in units:
            key = str(raw_key or "")
            parts = key.split("/")
            if (
                len(parts) != 6
                or parts[4] != "chain_iter2"
                or parts[5] not in fixed_roles
            ):
                continue
            try:
                if canonical_work_unit_key(*parts) == key:
                    residue.append(key)
            except (TypeError, ValueError):
                continue

    if not residue:
        return []
    return [
        "CHAIN_TAIL_LEGACY_FIXED_GENERATION: "
        + ", ".join(sorted(set(residue)))
    ]


def _chain_state_resolution_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve P0-AB from the exact sources the state loader can consume."""

    root = Path(scratchpad)
    from chain_prep import _CROSS_DOMAIN_SOURCE_GLOBS

    exact_inputs = tuple(sorted({
        "findings_inventory.md",
        *(
            name
            for name in (
                "_mechanical_graph.json",
                "state_write_map.md",
                "state_variables.md",
            )
            if (root / name).is_file()
        ),
        *(
            path.relative_to(root).as_posix()
            for pattern in _CROSS_DOMAIN_SOURCE_GLOBS
            for path in root.glob(pattern)
            if path.is_file() and not path.is_symlink()
        ),
    }))
    exact_outputs = (
        "chain_state_resolution.json",
        *(
            _CHAIN_TAIL_INITIALIZATION_OUTPUTS
            if bool(config.get("_chain_state_resolution_initializes_tail"))
            else ()
        ),
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="chain",
        work_unit_id="state_resolution",
        exact_inputs=exact_inputs,
        exact_outputs=exact_outputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _chain_tail_initial_contracts_and_launches(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> tuple[
    tuple[PhaseIOContract, LaunchSpec],
    tuple[PhaseIOContract, LaunchSpec],
]:
    """Resolve immutable-manifest and initial mutable-control transactions."""

    state_contract, _state_launch = _chain_state_resolution_contract_and_launch(
        scratchpad=scratchpad,
        config=config,
        phase=phase,
    )
    exact_inputs = tuple(
        identity.split(":", 1)[1]
        for identity in state_contract.immutable_inputs
        if identity.startswith("scratchpad:")
    )
    dimensions = {
        "pipeline": str(config.get("pipeline") or "sc"),
        "mode": str(config.get("mode") or "thorough"),
        "ecosystem": str(config.get("language") or "unknown"),
        "backend": str(config.get("cli_backend") or "claude"),
    }

    def pair(
        work_unit_id: str,
        outputs: tuple[str, ...],
    ) -> tuple[PhaseIOContract, LaunchSpec]:
        contract = resolve_phase_io_contract(
            **dimensions,
            phase="chain",
            work_unit_id=work_unit_id,
            exact_inputs=exact_inputs,
            exact_outputs=outputs,
        )
        return contract, LaunchSpec(
            work_unit_key=contract.key,
            **dimensions,
            model="driver",
            timeout_s=max(1, int(phase.base_timeout_s)),
            exec_mode="python",
            tool_policy=("filesystem",),
        )

    return (
        pair("tail_manifest", (_CHAIN_TAIL_CONTROL_MANIFEST,)),
        pair("tail_control_init", _CHAIN_TAIL_INITIAL_CONTROL_OUTPUTS),
    )


