def _validate_chain_state_resolution_phase_io(
    *,
    scratchpad: Path,
    project_root: Path,
    mode: str,
    language: str,
    pipeline: str,
    backend: str,
    timeout_s: int,
) -> list[str]:
    """Side-effect-free P0-AB PhaseIO validation for completed resume."""
    try:
        payload = json.loads((
            Path(scratchpad) / "chain_state_resolution.json"
        ).read_text(encoding="utf-8", errors="strict"))
        exact_inputs = tuple(sorted({
            "findings_inventory.md",
            *(
                str(name).replace("\\", "/")
                for name in (payload.get("source_artifact_digests") or {})
                if str(name) and (Path(scratchpad) / str(name)).is_file()
            ),
        }))
        contract = resolve_phase_io_contract(
            pipeline=str(pipeline or "sc"),
            mode=str(mode or "thorough"),
            ecosystem=str(language or "unknown"),
            backend=str(backend or "claude"),
            phase="chain",
            work_unit_id="state_resolution",
            exact_inputs=exact_inputs,
            exact_outputs=(
                "chain_state_resolution.json",
                *(
                    _CHAIN_TAIL_INITIALIZATION_OUTPUTS
                    if (
                        Path(scratchpad)
                        / "chain_candidate_pairs_iter2.json"
                    ).is_file()
                    else ()
                ),
            ),
        )
        launch = LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver",
            timeout_s=max(1, int(timeout_s)),
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        run_id = "test-unbound"
        checkpoint_path = Path(scratchpad) / "_v2_checkpoint.json"
        if checkpoint_path.is_file():
            checkpoint_payload = json.loads(
                checkpoint_path.read_text(encoding="utf-8", errors="strict")
            )
            run_id = str(checkpoint_payload.get("run_id") or run_id)
        issues = validate_work_unit_inputs(
            scratchpad, project_root, contract, launch, run_id=run_id
        )
        issues.extend(validate_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
        return issues
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError, json.JSONDecodeError) as exc:
        return [
            "chain state resolution resume PhaseIO failure: "
            f"{type(exc).__name__}: {exc}"
        ]


def _clear_chain_state_resolution_debt(scratchpad: Path) -> None:
    """Clear only superseded P0-AB debt, preserving unrelated chain debt."""
    path = Path(scratchpad) / "chain.degraded"
    if not path.is_file():
        return
    existing = path.read_text(encoding="utf-8", errors="replace")
    kept = [
        line
        for line in existing.splitlines()
        if not line.startswith("[STATE_GRAPH_APPLICATION]")
        and not line.startswith("[STATE_RESOLUTION_PHASE_IO]")
    ]
    if kept:
        _atomic_driver_bytes(path, ("\n".join(kept).rstrip() + "\n").encode("utf-8"))
    else:
        try:
            path.unlink()
        except FileNotFoundError:
            pass


def _commit_chain_state_resolution_authority(
    *,
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> list[str]:
    """Persist graph-application and PhaseIO debt without halting chain work."""
    from state_symbol_authority import (
        DEGRADED_STATUS,
        validate_chain_state_resolution,
    )

    _clear_chain_state_resolution_debt(scratchpad)
    issues = list(validate_chain_state_resolution(scratchpad))
    try:
        payload = json.loads((
            Path(scratchpad) / "chain_state_resolution.json"
        ).read_text(encoding="utf-8", errors="strict"))
        state_status = str(payload.get("status") or "")
        if state_status == DEGRADED_STATUS:
            issues.append(
                "DEGRADED_GRAPH_APPLICATION: populated mechanical state graph "
                "resolved zero finding-to-state edges; exact unresolved sets "
                "are retained in chain_state_resolution.json"
            )
        elif state_status.startswith("DEGRADED_"):
            issues.append(
                f"{state_status}: typed state application remains incomplete; "
                "exact reasons and unresolved identities are retained in "
                "chain_state_resolution.json"
            )
    except (OSError, UnicodeError, json.JSONDecodeError):
        # The structural validator already emitted the exact missing/unreadable
        # issue; do not manufacture a second semantic claim.
        pass
    phase_io_issues = _record_chain_state_resolution_phase_io(
        scratchpad=Path(scratchpad), config=config, phase=phase
    )
    issues.extend(phase_io_issues)
    for issue in sorted(set(issues)):
        category = (
            "STATE_RESOLUTION_PHASE_IO"
            if issue in phase_io_issues else "STATE_GRAPH_APPLICATION"
        )
        _append_phase_io_debt(scratchpad, "chain", category, issue)
    return issues


def _chain_tail_shard_model_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    isolated: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve one path-isolated chain-tail MODEL transaction."""

    from chain_tail_authority import load_isolated_chain_tail_work_unit

    root = Path(scratchpad)
    work_path = str(isolated.get("work_unit_path") or "").replace("\\", "/")
    work = load_isolated_chain_tail_work_unit(
        root,
        isolated,
        expected_source_names=isolated.get("authoritative_source_paths") or (),
    )
    originals = sorted(
        str(binding.get("authority_identity") or "").split(":", 1)[1]
        for binding in (work.get("authoritative_sources") or {}).values()
        if isinstance(binding, Mapping)
        and str(binding.get("authority_identity") or "").startswith("scratchpad:")
    )
    copies = sorted(
        str(binding.get("copy_path") or "")
        for binding in (work.get("authoritative_sources") or {}).values()
        if isinstance(binding, Mapping) and str(binding.get("copy_path") or "")
    )
    exact_inputs = tuple(sorted({
        _CHAIN_TAIL_CONTROL_MANIFEST,
        work_path,
        str(isolated.get("packet_path") or "").replace("\\", "/"),
        *originals,
        *copies,
    }))
    transcript = str(isolated.get("transcript_path") or "").replace("\\", "/")
    shard_index = int(isolated.get("shard_index") or 0)
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="chain_iter2",
        work_unit_id=f"tail_shard_model.{shard_index:04d}",
        exact_inputs=exact_inputs,
        exact_outputs=(transcript,),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model=phase_model(phase, str(config.get("mode") or "thorough"), dict(config)),
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode=("codex" if contract.backend == "codex" else "headless"),
        tool_policy=("filesystem",),
    )
    return contract, launch


