def _chain_agent2_model_producer_binding(
    scratchpad: Path,
    *,
    expected_work_unit_key: str,
    expected_run_id: str,
    expected_binding: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, list[str]]:
    """Validate and summarize the exact same-run ChainAgent2 MODEL producer.

    This is deliberately stricter than file presence: the model work unit,
    contract/input denominator, committed outputs, global ownership bindings,
    and live raw bytes must all agree before DRIVER reconciliation may consume
    the Markdown.  The returned summary is embedded in the primary receipt so
    final publication can replay the same proof without trusting prose.
    """

    root = Path(scratchpad)
    label = "ChainAgent2 MODEL producer"
    issues: list[str] = []
    try:
        ledger = read_artifact_ledger(root)
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return None, [f"{label} ledger unavailable: {exc}"]
    required_outputs = {
        "scratchpad:chain_hypotheses.md",
        "scratchpad:composition_coverage.md",
        "scratchpad:synthesis_full.md",
    }
    unit, authority_issues = _full_committed_producer_authority(
        root,
        root.parent,
        ledger=ledger,
        outer_work_unit_key=expected_work_unit_key,
        run_id=expected_run_id,
        expected_input_identities=None,
        expected_output_identities=tuple(sorted(required_outputs)),
        actor="MODEL",
    )
    issues.extend(
        f"{label}: {issue}" for issue in authority_issues
    )
    if not isinstance(unit, Mapping):
        issues.append(f"{label} is missing for {expected_work_unit_key}")
    artifacts = (
        unit.get("artifacts")
        if isinstance(unit, Mapping)
        else None
    )
    output_digests: dict[str, dict[str, Any]] = {}
    if isinstance(artifacts, Mapping) and not issues:
        for identity in sorted(required_outputs):
            row = artifacts.get(identity)
            if isinstance(row, Mapping):
                output_digests[identity] = {
                    "sha256": str(row.get("sha256") or ""),
                    "size": row.get("size"),
                }

    if issues:
        return None, list(dict.fromkeys(issues))
    if set(output_digests) != required_outputs:
        return None, [f"{label} output digest denominator mismatch"]
    binding: dict[str, Any] = {
        "schema_version": "plamen.chain_agent2_model_binding.v1",
        "work_unit_key": expected_work_unit_key,
        "run_id": expected_run_id,
        "contract_digest": str(unit.get("contract_digest") or ""),
        "input_set_digest": str(unit.get("input_set_digest") or ""),
        "execution_state": "OUTPUT_COMMITTED",
        "semantic_status": "ACTIVE",
        "output_digests": output_digests,
    }
    binding["binding_digest"] = hashlib.sha256(json.dumps(
        binding, sort_keys=True, separators=(",", ":"), ensure_ascii=True
    ).encode("utf-8")).hexdigest()
    if expected_binding is not None and dict(expected_binding) != binding:
        return None, [f"{label} embedded binding parity mismatch"]
    return binding, []


def _run_chain_tail_primary_reconciliation_transaction(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> tuple[dict[str, Any], list[str]]:
    from chain_tail_authority import (
        begin_isolated_chain_tail_scheduler,
        ingest_primary_chain_coverage,
        write_primary_chain_tail_receipt,
    )

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        producer_key = (
            f"{str(config.get('pipeline') or 'sc')}/"
            f"{str(config.get('mode') or 'thorough')}/"
            f"{str(config.get('language') or 'unknown')}/"
            f"{str(config.get('cli_backend') or 'claude')}/chain_agent2/model"
        )
        model_binding, model_issues = _chain_agent2_model_producer_binding(
            root,
            expected_work_unit_key=producer_key,
            expected_run_id=run_id,
        )
        if model_issues or model_binding is None:
            return (
                {"status": "DEGRADED_UNRESOLVED"},
                list(model_issues) or [
                    "ChainAgent2 MODEL producer binding is unavailable"
                ],
            )
        control_contract, control_launch = (
            _chain_tail_primary_control_contract_and_launch(
                scratchpad=root, config=config, phase=phase
            )
        )
        contract, launch = _chain_tail_primary_contract_and_launch(
            scratchpad=root, config=config, phase=phase
        )
        control_execute, control_arm_issues = (
            _arm_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=control_contract,
                launch=control_launch,
                run_id=run_id,
            )
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        combined_arm_issues = list(dict.fromkeys([
            *control_arm_issues,
            *arm_issues,
        ]))
        if combined_arm_issues:
            return {"status": "DEGRADED_UNRESOLVED"}, combined_arm_issues
        if control_execute:
            begin_isolated_chain_tail_scheduler(root)
            progress = ingest_primary_chain_coverage(
                root,
                activate_next_shard=False,
            )
        else:
            progress = json.loads(
                (
                    root
                    / "_chain_tail_control"
                    / "chain_tail_coverage_receipt.json"
                ).read_text(encoding="utf-8", errors="strict")
            )
        control_commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=control_contract,
            launch=control_launch,
            run_id=run_id,
        )
        if control_commit_issues:
            return (
                {"status": "DEGRADED_UNRESOLVED"},
                list(dict.fromkeys(control_commit_issues)),
            )
        if execute:
            primary = write_primary_chain_tail_receipt(
                root,
                chain_agent2_model_binding=model_binding,
            )
        else:
            primary = json.loads(
                (root / "chain_tail_primary_receipt.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
        commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        return {
            **dict(progress),
            "primary_receipt_sha256": primary.get("receipt_sha256"),
        }, list(dict.fromkeys(commit_issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        issue = (
            "chain-tail primary reconciliation transaction failed: "
            f"{type(exc).__name__}: {exc}"
        )
        return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]


def _chain_tail_shard_prepare_contracts_and_launches(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    shard_index: int,
    source_names: Sequence[str],
) -> tuple[
    tuple[PhaseIOContract, LaunchSpec],
    tuple[PhaseIOContract, LaunchSpec],
]:
    """Resolve mutable-control and immutable-packet owners for one shard."""

    from chain_tail_authority import (
        isolated_chain_tail_materialization_paths,
    )

    descriptor = isolated_chain_tail_materialization_paths(
        int(shard_index),
        source_names=tuple(source_names),
    )
    exact_inputs = tuple(sorted({
        _CHAIN_TAIL_CONTROL_MANIFEST,
        *(
            str(name).replace("\\", "/")
            for name in source_names
        ),
    }))
    immutable_outputs = tuple(dict.fromkeys([
        str(descriptor["archive_packet_path"]),
        str(descriptor["work_unit_path"]),
        str(descriptor["packet_path"]),
        *(
            str(path)
            for path in descriptor["source_copy_paths"]
        ),
    ]))
    dimensions = {
        "pipeline": str(config.get("pipeline") or "sc"),
        "mode": str(config.get("mode") or "thorough"),
        "ecosystem": str(config.get("language") or "unknown"),
        "backend": str(config.get("cli_backend") or "claude"),
    }

    def pair(
        work_unit_id: str,
        outputs: tuple[str, ...],
    ) -> tuple[PhaseIOContract, LaunchSpec]:
        contract = resolve_phase_io_contract(
            **dimensions,
            phase="chain_iter2",
            work_unit_id=work_unit_id,
            exact_inputs=exact_inputs,
            exact_outputs=outputs,
        )
        return contract, LaunchSpec(
            work_unit_key=contract.key,
            **dimensions,
            model="driver",
            timeout_s=max(1, int(phase.base_timeout_s)),
            exec_mode="python",
            tool_policy=("filesystem",),
        )

    suffix = f"{int(shard_index):04d}"
    return (
        pair(
            f"tail_shard_prepare_control.{suffix}",
            _CHAIN_TAIL_MUTABLE_CONTROL_OUTPUTS,
        ),
        pair(
            f"tail_shard_prepare_artifacts.{suffix}",
            immutable_outputs,
        ),
    )


def _run_chain_tail_shard_prepare_transaction(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    source_names: Sequence[str],
) -> tuple[dict[str, Any], list[str]]:
    """Advance/materialize one shard under split durable ownership."""

    from chain_tail_authority import (
        begin_isolated_chain_tail_scheduler,
        current_chain_tail_shard,
        load_materialized_isolated_chain_tail_shard,
        materialize_isolated_chain_tail_shard,
        prepare_next_chain_tail_shard,
    )

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        shard = current_chain_tail_shard(root)
        shard_index = int(shard.get("shard_index") or 0)
        control_pair, artifact_pair = (
            _chain_tail_shard_prepare_contracts_and_launches(
                scratchpad=root,
                config=config,
                phase=phase,
                shard_index=shard_index,
                source_names=tuple(source_names),
            )
        )
        armed: list[tuple[PhaseIOContract, LaunchSpec, bool]] = []
        arm_issues: list[str] = []
        for contract, launch in (control_pair, artifact_pair):
            execute, local = _arm_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
            armed.append((contract, launch, execute))
            arm_issues.extend(local)
        if arm_issues:
            return {}, list(dict.fromkeys(arm_issues))
        control_execute = armed[0][2]
        artifact_execute = armed[1][2]
        if control_execute != artifact_execute:
            # Commit ordering makes only immutable-first/control-pending a
            # valid partial state. The inverse would mean committed mutable
            # state lacks its immutable packet and must fail closed.
            if not control_execute and artifact_execute:
                return {}, [
                    "chain-tail prepare control committed before immutable "
                    "packet authority"
                ]
        if control_execute or artifact_execute:
            begin_isolated_chain_tail_scheduler(root)
            shard = prepare_next_chain_tail_shard(root)
            if not shard.get("pair_ids"):
                return {}, []
            isolated = materialize_isolated_chain_tail_shard(
                root,
                shard,
                source_names=tuple(source_names),
            )
        else:
            shard = current_chain_tail_shard(root)
            if not shard.get("pair_ids"):
                return {}, []
            isolated = load_materialized_isolated_chain_tail_shard(
                root,
                shard,
                source_names=tuple(source_names),
            )

        artifact_contract, artifact_launch, _ = armed[1]
        artifact_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=artifact_contract,
            launch=artifact_launch,
            run_id=run_id,
        )
        if artifact_issues:
            return dict(isolated), list(dict.fromkeys(artifact_issues))
        control_contract, control_launch, _ = armed[0]
        control_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=control_contract,
            launch=control_launch,
            run_id=run_id,
        )
        return dict(isolated), list(dict.fromkeys(control_issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        issue = (
            "chain-tail shard prepare transaction failed: "
            f"{type(exc).__name__}: {exc}"
        )
        return {}, [issue]


def _chain_tail_shard_disposition_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    isolated: Mapping[str, Any],
    failure: bool = False,
    bind_committed_model: bool = False,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the DRIVER parser/terminal receipt linked to one model unit."""

    from chain_tail_authority import load_isolated_chain_tail_work_unit

    root = Path(scratchpad)
    work = load_isolated_chain_tail_work_unit(
        root,
        isolated,
        expected_source_names=isolated.get("authoritative_source_paths") or (),
    )
    work_path = str(work.get("work_unit_path") or isolated.get(
        "work_unit_path"
    ) or "").replace("\\", "/")
    if not work_path:
        work_path = str(isolated.get("work_unit_path") or "").replace("\\", "/")
    transcript = str(isolated.get("transcript_path") or "").replace("\\", "/")
    disposition = str(
        isolated.get("disposition_receipt_path") or ""
    ).replace("\\", "/")
    terminal_plan = str(
        isolated.get("terminal_plan_path") or ""
    ).replace("\\", "/")
    shard_index = int(isolated.get("shard_index") or 0)
    exact_inputs = {
        _CHAIN_TAIL_CONTROL_MANIFEST,
        work_path,
    }
    if not failure or bind_committed_model:
        exact_inputs.add(transcript)
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="chain_iter2",
        work_unit_id=(
            f"tail_shard_failure.{shard_index:04d}"
            if failure
            else f"tail_shard_disposition.{shard_index:04d}"
        ),
        exact_inputs=tuple(sorted(exact_inputs)),
        exact_outputs=(terminal_plan, disposition),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _chain_tail_shard_terminal_control_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    isolated: Mapping[str, Any],
    failure: bool,
    bind_committed_model: bool,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Own only the mutable scheduler roll-forward for one terminal shard."""

    work_path = str(isolated.get("work_unit_path") or "").replace("\\", "/")
    transcript = str(isolated.get("transcript_path") or "").replace("\\", "/")
    shard_index = int(isolated.get("shard_index") or 0)
    exact_inputs = {
        _CHAIN_TAIL_CONTROL_MANIFEST,
        work_path,
    }
    if not failure or bind_committed_model:
        exact_inputs.add(transcript)
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="chain_iter2",
        work_unit_id=(
            f"tail_shard_failure_control.{shard_index:04d}"
            if failure
            else f"tail_shard_disposition_control.{shard_index:04d}"
        ),
        exact_inputs=tuple(sorted(exact_inputs)),
        exact_outputs=_CHAIN_TAIL_MUTABLE_CONTROL_OUTPUTS,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _chain_tail_budget_stop_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> tuple[PhaseIOContract, LaunchSpec, dict[str, Any]]:
    """Bind one quiescent scheduler generation before budget-stop mutation."""

    from chain_tail_authority import chain_tail_budget_stop_generation

    generation = chain_tail_budget_stop_generation(Path(scratchpad))
    pass_index = int(generation["pass_index"])
    next_shard_index = int(generation["next_shard_index"])
    if not (0 <= pass_index <= 9999 and 0 <= next_shard_index <= 9999):
        raise ValueError("chain-tail budget-stop generation exceeds PhaseIO range")
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="chain_iter2",
        work_unit_id=(
            f"tail_budget_stop.p{pass_index:04d}.s{next_shard_index:04d}"
        ),
        exact_inputs=(_CHAIN_TAIL_CONTROL_MANIFEST,),
        exact_outputs=_CHAIN_TAIL_MUTABLE_CONTROL_OUTPUTS,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch, generation


def _run_chain_tail_budget_stop_transaction(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    reason: str,
) -> tuple[dict[str, Any], list[str]]:
    """Durably roll all mutable control projections into one budget stop."""

    from chain_tail_authority import (
        _read_progress_receipt,
        mark_chain_tail_budget_stop,
    )

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        contract, launch, generation = (
            _chain_tail_budget_stop_contract_and_launch(
                scratchpad=root,
                config=config,
                phase=phase,
            )
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if arm_issues:
            return dict(_read_progress_receipt(root)), list(
                dict.fromkeys(arm_issues)
            )
        receipt = (
            mark_chain_tail_budget_stop(
                root,
                reason,
                expected_pass_index=int(generation["pass_index"]),
                expected_next_shard_index=int(
                    generation["next_shard_index"]
                ),
                expected_ledger_sha256=str(generation["ledger_sha256"]),
            )
            if execute
            else _read_progress_receipt(root)
        )
        commit_issues = (
            _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
            if execute
            else []
        )
        return dict(receipt), list(dict.fromkeys(commit_issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        try:
            receipt = dict(_read_progress_receipt(root))
        except Exception:
            receipt = {"status": "DEGRADED_UNRESOLVED"}
        return receipt, [
            "chain-tail budget-stop transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _committed_chain_tail_model_binding(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    isolated: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Return the exact live MODEL predecessor when it is fully committed."""

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        contract, launch = _chain_tail_shard_model_contract_and_launch(
            scratchpad=root,
            config=config,
            phase=phase,
            isolated=isolated,
        )
        validation_issues = validate_work_unit_inputs(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
        )
        validation_issues.extend(
            validate_work_unit_artifacts(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
                actor="MODEL",
            )
        )
        if validation_issues:
            return None
        unit = read_artifact_ledger(root).get("work_units", {}).get(contract.key)
        transcript = str(isolated.get("transcript_path") or "").replace(
            "\\", "/"
        )
        artifact = (
            unit.get("artifacts", {}).get(f"scratchpad:{transcript}")
            if isinstance(unit, Mapping)
            else None
        )
        if (
            not isinstance(unit, Mapping)
            or unit.get("run_id") != run_id
            or unit.get("execution_state") != "OUTPUT_COMMITTED"
            or unit.get("semantic_status") != "ACTIVE"
            or not isinstance(artifact, Mapping)
            or not (root / transcript).is_file()
            or hashlib.sha256((root / transcript).read_bytes()).hexdigest()
            != artifact.get("sha256")
        ):
            return None
        return {
            "work_unit_key": contract.key,
            "run_id": run_id,
            "contract_digest": contract.digest,
            "input_set_digest": str(unit.get("input_set_digest") or ""),
            "execution_state": str(unit.get("execution_state") or ""),
            "semantic_status": str(unit.get("semantic_status") or ""),
            "transcript_sha256": str(artifact.get("sha256") or ""),
        }
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ):
        return None


def _prepared_chain_tail_model_binding(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    isolated: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Bind an abandoned pre-armed MODEL attempt without inventing output."""

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        contract, launch = _chain_tail_shard_model_contract_and_launch(
            scratchpad=root,
            config=config,
            phase=phase,
            isolated=isolated,
        )
        if validate_work_unit_inputs(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
        ):
            return None
        unit = read_artifact_ledger(root).get("work_units", {}).get(contract.key)
        transcript = str(isolated.get("transcript_path") or "").replace(
            "\\", "/"
        )
        if (
            not isinstance(unit, Mapping)
            or unit.get("run_id") != run_id
            or unit.get("execution_state") != "INPUTS_BOUND_PREEXECUTION"
            or unit.get("semantic_status") != "INPUTS_BOUND"
            or (root / transcript).exists()
        ):
            return None
        return {
            "work_unit_key": contract.key,
            "run_id": run_id,
            "contract_digest": contract.digest,
            "input_set_digest": str(unit.get("input_set_digest") or ""),
            "execution_state": str(unit.get("execution_state") or ""),
            "semantic_status": str(unit.get("semantic_status") or ""),
            "expected_transcript_path": transcript,
            "output_present": False,
        }
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ):
        return None


def _run_chain_tail_failure_transaction(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    isolated: Mapping[str, Any],
    reason: str,
) -> list[str]:
    from chain_tail_authority import record_isolated_chain_tail_failure

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        model_binding = _committed_chain_tail_model_binding(
            scratchpad=root,
            config=config,
            phase=phase,
            isolated=isolated,
        )
        abandoned_model_binding = (
            None
            if model_binding is not None
            else _prepared_chain_tail_model_binding(
                scratchpad=root,
                config=config,
                phase=phase,
                isolated=isolated,
            )
        )
        failure_contract, failure_launch = (
            _chain_tail_shard_disposition_contract_and_launch(
                scratchpad=root,
                config=config,
                phase=phase,
                isolated=isolated,
                failure=True,
                bind_committed_model=model_binding is not None,
            )
        )
        control_contract, control_launch = (
            _chain_tail_shard_terminal_control_contract_and_launch(
                scratchpad=root,
                config=config,
                phase=phase,
                isolated=isolated,
                failure=True,
                bind_committed_model=model_binding is not None,
            )
        )
        control_execute, control_arm_issues = (
            _arm_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=control_contract,
                launch=control_launch,
                run_id=run_id,
            )
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=failure_contract,
            launch=failure_launch,
            run_id=run_id,
        )
        combined_arm_issues = list(dict.fromkeys([
            *control_arm_issues,
            *arm_issues,
        ]))
        if combined_arm_issues:
            return combined_arm_issues
        if execute or control_execute:
            record_isolated_chain_tail_failure(
                root,
                disposition_receipt_name=str(
                    isolated["disposition_receipt_path"]
                ),
                reason=reason,
                transcript_path=(
                    str(isolated.get("transcript_path") or "")
                    if model_binding is not None
                    else ""
                ),
                model_binding=model_binding,
                abandoned_model_binding=abandoned_model_binding,
            )
        commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=failure_contract,
            launch=failure_launch,
            run_id=run_id,
        )
        if commit_issues:
            return list(dict.fromkeys(commit_issues))
        control_commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=control_contract,
            launch=control_launch,
            run_id=run_id,
        )
        return list(dict.fromkeys(control_commit_issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "isolated chain-tail failure transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _chain_tail_final_reconcile_readiness_issues(
    scratchpad: Path,
    *,
    expected_run_id: str | None = None,
) -> list[str]:
    """Prove exact isolated roster and committed producer ancestry."""

    from chain_tail_authority import (
        CONTROL_DIR,
        CONTROL_JOURNAL_NAME,
        _digest as chain_tail_digest,
        _load_manifest_ledger,
        load_isolated_chain_tail_work_unit,
    )

    root = Path(scratchpad)
    journal_path = root / CONTROL_DIR / CONTROL_JOURNAL_NAME
    try:
        manifest, ledger = _load_manifest_ledger(root)
    except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        return [f"chain-tail manifest/ledger is unavailable: {exc}"]
    shard_parent = root / "_chain_tail_shards"
    shard_dirs: dict[str, Path] = {}
    if shard_parent.is_dir():
        for candidate in shard_parent.iterdir():
            if candidate.is_dir() and re.fullmatch(
                r"shard_\d{4}", candidate.name
            ):
                shard_dirs[candidate.name.split("_", 1)[1]] = candidate
    isolation_markers = bool(shard_dirs) or journal_path.exists()
    try:
        artifact_state = read_artifact_ledger(root)
    except (ArtifactLedgerError, OSError, TypeError, ValueError):
        artifact_state = {}
    artifact_units = artifact_state.get("work_units", {})
    artifact_bindings = artifact_state.get("artifact_bindings", {})
    active_run_id = ""

    def committed_output_unit(
        *,
        identity: str,
        key_suffixes: tuple[str, ...],
        required_outputs: set[str],
        required_inputs: set[str],
        actor: str,
    ) -> tuple[Mapping[str, Any] | None, list[str]]:
        matches: list[tuple[str, Mapping[str, Any]]] = []
        for key, unit in (
            artifact_units.items()
            if isinstance(artifact_units, Mapping)
            else ()
        ):
            if (
                isinstance(unit, Mapping)
                and any(str(key).endswith(suffix) for suffix in key_suffixes)
                and identity in (unit.get("artifacts") or {})
            ):
                matches.append((str(key), unit))
        if len(matches) != 1:
            return None, [
                f"{identity}: expected exactly one committed producer, "
                f"observed {len(matches)}"
            ]
        if not active_run_id:
            return None, [
                f"{identity}: expected active run authority is unavailable"
            ]
        outer_key, unit = matches[0]
        replayed, local = _full_committed_producer_authority(
            root,
            root.parent,
            ledger=artifact_state,
            outer_work_unit_key=outer_key,
            run_id=active_run_id,
            expected_input_identities=tuple(sorted(required_inputs)),
            expected_output_identities=tuple(sorted(required_outputs)),
            actor=actor,
        )
        return replayed or unit, local

    if not isolation_markers:
        terminal = {"EXPLORED", "REJECTED", "COMPOSED"}
        if (
            not isinstance(ledger.get("active_shard"), Mapping)
            and all(
                str(row.get("disposition") or "") in terminal
                for row in ledger.get("pairs") or []
            )
            and not isinstance(ledger.get("primary_coverage"), Mapping)
        ):
            # Explicit zero-work and direct-library legacy remain compatible.
            return []
        denominator = int(manifest.get("denominator") or 0)
        return [
            "chain-tail isolation/legacy eligibility is unavailable for "
            f"non-terminal or primary denominator ({denominator})"
        ]
    if not journal_path.is_file():
        return ["chain-tail isolation roster exists but scheduler journal is missing"]
    try:
        journal = json.loads(journal_path.read_text(
            encoding="utf-8", errors="strict"
        ))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return [f"chain-tail scheduler journal is invalid: {exc}"]
    issues: list[str] = []
    manifest_identity = f"scratchpad:{_CHAIN_TAIL_CONTROL_MANIFEST}"
    manifest_matches = [
        (str(key), unit)
        for key, unit in (
            artifact_units.items()
            if isinstance(artifact_units, Mapping)
            else ()
        )
        if (
            isinstance(unit, Mapping)
            and str(key).endswith("/chain/tail_manifest")
            and manifest_identity in (unit.get("artifacts") or {})
        )
    ]
    canonical_run_id = ""
    if len(manifest_matches) != 1:
        issues.append(
            "chain-tail active run authority: expected exactly one immutable "
            f"manifest producer, observed {len(manifest_matches)}"
        )
    else:
        manifest_key, manifest_unit = manifest_matches[0]
        manifest_artifacts = manifest_unit.get("artifacts")
        manifest_row = (
            manifest_artifacts.get(manifest_identity)
            if isinstance(manifest_artifacts, Mapping)
            else None
        )
        manifest_global = (
            artifact_bindings.get(manifest_identity)
            if isinstance(artifact_bindings, Mapping)
            else None
        )
        manifest_path = root / _CHAIN_TAIL_CONTROL_MANIFEST
        candidate_run_id = str(manifest_unit.get("run_id") or "").strip()
        manifest_commit = manifest_unit.get("commit_authority")
        if (
            not candidate_run_id
            or manifest_unit.get("schema") != "plamen.artifact-work-unit.v2"
            or manifest_unit.get("work_unit_key") != manifest_key
            or manifest_unit.get("execution_state") != "OUTPUT_COMMITTED"
            or manifest_unit.get("semantic_status") != "ACTIVE"
            or not isinstance(manifest_commit, Mapping)
            or manifest_commit.get("run_id") != candidate_run_id
            or not isinstance(manifest_row, Mapping)
            or not isinstance(manifest_global, Mapping)
            or manifest_row.get("status") != "ACTIVE"
            or manifest_global.get("status") != "ACTIVE"
            or manifest_row.get("owner_key") != manifest_key
            or manifest_global.get("owner_key") != manifest_key
            or manifest_row.get("run_id") != candidate_run_id
            or manifest_global.get("run_id") != candidate_run_id
            or not manifest_path.is_file()
            or manifest_row.get("sha256")
            != hashlib.sha256(manifest_path.read_bytes()).hexdigest()
            or manifest_global.get("sha256") != manifest_row.get("sha256")
        ):
            issues.append(
                "chain-tail active run authority: immutable manifest producer "
                "binding is invalid"
            )
        else:
            canonical_run_id = candidate_run_id
    supplied_run_id = (
        str(expected_run_id).strip()
        if expected_run_id is not None
        else canonical_run_id
    )
    if not supplied_run_id:
        issues.append("chain-tail expected active run_id is unavailable")
    elif supplied_run_id != canonical_run_id:
        issues.append(
            "chain-tail expected run_id differs from immutable manifest authority"
        )
    else:
        active_run_id = supplied_run_id
    started = journal.get("started_shards") or {}
    if not isinstance(started, Mapping):
        return ["chain-tail scheduler started-shard denominator is malformed"]
    if set(started) != set(shard_dirs):
        issues.append(
            "chain-tail shard roster denominator mismatch across journal and "
            "canonical shard directories"
        )
    ledger_indices = {
        f"{int(row.get('shard_index') or 0):04d}"
        for row in ledger.get("shards") or []
        if isinstance(row, Mapping)
    }
    if ledger_indices != set(shard_dirs):
        issues.append(
            "chain-tail shard roster denominator mismatch across ledger and "
            "canonical shard directories"
        )
    primary_path = root / "chain_tail_primary_receipt.json"
    if isinstance(ledger.get("primary_coverage"), Mapping) and not primary_path.is_file():
        issues.append(
            "chain-tail primary coverage lacks its committed terminal receipt"
        )
    if primary_path.is_file():
        primary_identity = "scratchpad:chain_tail_primary_receipt.json"
        primary_unit, primary_issues = committed_output_unit(
            identity=primary_identity,
            key_suffixes=("/chain_iter2/tail_primary",),
            required_outputs={primary_identity},
            required_inputs={
                f"scratchpad:{_CHAIN_TAIL_CONTROL_MANIFEST}",
                "scratchpad:composition_coverage.md",
                "scratchpad:chain_hypotheses.md",
            },
            actor="DRIVER",
        )
        issues.extend(
            f"chain-tail primary producer: {value}"
            for value in primary_issues
        )
        try:
            primary = json.loads(
                primary_path.read_text(encoding="utf-8", errors="strict")
            )
            if (
                primary.get("schema_version")
                != "plamen.chain_tail.primary_receipt.v1"
                or primary.get("receipt_sha256")
                != chain_tail_digest(primary, "receipt_sha256")
                or primary.get("manifest_sha256")
                != manifest.get("manifest_sha256")
            ):
                issues.append("chain-tail primary receipt is invalid or stale")
            if (
                primary.get("composition_coverage_sha256")
                != hashlib.sha256(
                    (root / "composition_coverage.md").read_bytes()
                ).hexdigest()
                or primary.get("chain_hypotheses_sha256")
                != hashlib.sha256(
                    (root / "chain_hypotheses.md").read_bytes()
                ).hexdigest()
            ):
                issues.append(
                    "chain-tail primary source output digest binding mismatch"
                )
            if isinstance(primary_unit, Mapping):
                primary_key = str(primary_unit.get("work_unit_key") or "")
                prefix, separator, _tail = primary_key.partition(
                    "/chain_iter2/tail_primary"
                )
                expected_model_key = (
                    f"{prefix}/chain_agent2/model" if separator else ""
                )
                embedded = primary.get("chain_agent2_model_binding")
                if (
                    not expected_model_key
                    or not isinstance(embedded, Mapping)
                ):
                    issues.append(
                        "chain-tail primary lacks ChainAgent2 MODEL producer binding"
                    )
                else:
                    _binding, binding_issues = (
                        _chain_agent2_model_producer_binding(
                            root,
                            expected_work_unit_key=expected_model_key,
                            expected_run_id=active_run_id,
                            expected_binding=embedded,
                        )
                    )
                    issues.extend(
                        f"chain-tail primary producer: {value}"
                        for value in binding_issues
                    )
        except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError):
            issues.append("chain-tail primary receipt is invalid")
    for shard_key, row in sorted(started.items()):
        if not isinstance(row, Mapping):
            issues.append(f"started shard {shard_key} journal row is malformed")
            continue
        terminal = str(row.get("terminal_status") or "")
        isolated = {
            "shard_index": int(shard_key),
            "pair_ids": list(row.get("pair_ids") or []),
            "work_unit_path": str(row.get("work_unit_path") or ""),
            "packet_path": (
                f"_chain_tail_shards/shard_{shard_key}/"
                "chain_candidate_pairs_iter2.md"
            ),
            "authoritative_source_paths": [],
            "transcript_path": str(row.get("transcript_path") or ""),
            "terminal_plan_path": str(row.get("terminal_plan_path") or ""),
            "disposition_receipt_path": str(
                row.get("disposition_receipt_path") or ""
            ),
        }
        try:
            raw_work = json.loads(
                (root / isolated["work_unit_path"]).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            isolated["authoritative_source_paths"] = sorted(
                (raw_work.get("authoritative_sources") or {}).keys()
            )
            work = load_isolated_chain_tail_work_unit(
                root,
                isolated,
                expected_source_names=isolated["authoritative_source_paths"],
            )
        except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
            issues.append(f"started shard {shard_key} work binding invalid: {exc}")
            continue
        transcript_path = root / str(row.get("transcript_path") or "")
        receipt_path = root / str(row.get("disposition_receipt_path") or "")
        plan_path = root / str(row.get("terminal_plan_path") or "")
        if terminal not in {"COMMITTED", "DEBT"}:
            issues.append(f"started shard {shard_key} is not terminal")
            continue
        if not receipt_path.is_file():
            issues.append(f"started shard {shard_key} disposition receipt is missing")
            continue
        if not plan_path.is_file():
            issues.append(f"started shard {shard_key} terminal plan is missing")
            continue
        try:
            receipt = json.loads(receipt_path.read_text(
                encoding="utf-8", errors="strict"
            ))
            if receipt.get("receipt_sha256") != chain_tail_digest(
                receipt, "receipt_sha256"
            ):
                issues.append(
                    f"started shard {shard_key} disposition receipt digest mismatch"
                )
            if str(receipt.get("terminal_status") or "") != terminal:
                issues.append(
                    f"started shard {shard_key} terminal status changed"
                )
            transcript_declared = bool(str(receipt.get("transcript_path") or ""))
            if transcript_declared and not transcript_path.is_file():
                issues.append(f"started shard {shard_key} transcript is missing")
            if not transcript_declared and terminal != "DEBT":
                issues.append(
                    f"started shard {shard_key} lacks a transcript without debt"
                )
            model_binding = receipt.get("model_binding")
            receipt_identity = (
                f"scratchpad:{row.get('disposition_receipt_path')}"
            )
            plan_identity = f"scratchpad:{row.get('terminal_plan_path')}"
            terminal_inputs = {
                f"scratchpad:{_CHAIN_TAIL_CONTROL_MANIFEST}",
                f"scratchpad:{row.get('work_unit_path')}",
            }
            if transcript_declared:
                terminal_inputs.add(f"scratchpad:{row.get('transcript_path')}")
            terminal_kind = str(receipt.get("terminal_kind") or "")
            if terminal_kind not in {"DISPOSITION", "FAILURE"}:
                issues.append(
                    f"started shard {shard_key} terminal kind is invalid"
                )
            terminal_suffix = (
                f"/chain_iter2/tail_shard_failure.{shard_key}"
                if terminal_kind == "FAILURE"
                else f"/chain_iter2/tail_shard_disposition.{shard_key}"
            )
            _terminal_unit, terminal_issues = committed_output_unit(
                identity=receipt_identity,
                key_suffixes=(terminal_suffix,),
                required_outputs={receipt_identity, plan_identity},
                required_inputs=terminal_inputs,
                actor="DRIVER",
            )
            issues.extend(
                f"started shard {shard_key} terminal producer: {value}"
                for value in terminal_issues
            )
            if transcript_declared:
                if not isinstance(model_binding, Mapping):
                    issues.append(
                        f"started shard {shard_key} model binding is missing"
                    )
                else:
                    model_key = str(model_binding.get("work_unit_key") or "")
                    model_unit = (
                        artifact_units.get(model_key)
                        if isinstance(artifact_units, Mapping)
                        else None
                    )
                    if (
                        not isinstance(model_unit, Mapping)
                        or model_unit.get("run_id") != active_run_id
                        or model_binding.get("run_id") != active_run_id
                        or model_unit.get("execution_state") != "OUTPUT_COMMITTED"
                        or model_unit.get("semantic_status") != "ACTIVE"
                        or model_unit.get("contract_digest")
                        != model_binding.get("contract_digest")
                        or model_unit.get("input_set_digest")
                        != model_binding.get("input_set_digest")
                    ):
                        issues.append(
                            f"started shard {shard_key} model receipt is not committed"
                        )
                    model_identity = f"scratchpad:{row.get('transcript_path')}"
                    model_inputs = {
                        f"scratchpad:{_CHAIN_TAIL_CONTROL_MANIFEST}",
                        f"scratchpad:{row.get('work_unit_path')}",
                        f"scratchpad:{work.get('packet_path')}",
                        *{
                            f"scratchpad:{name}"
                            for name in work.get("authoritative_sources") or {}
                        },
                        *{
                            f"scratchpad:{binding.get('copy_path')}"
                            for binding in (
                                work.get("authoritative_sources") or {}
                            ).values()
                            if isinstance(binding, Mapping)
                        },
                    }
                    _model_unit, model_issues = committed_output_unit(
                        identity=model_identity,
                        key_suffixes=(
                            f"/chain_iter2/tail_shard_model.{shard_key}",
                        ),
                        required_outputs={model_identity},
                        required_inputs=model_inputs,
                        actor="MODEL",
                    )
                    issues.extend(
                        f"started shard {shard_key} model producer: {value}"
                        for value in model_issues
                    )
            elif terminal_kind == "FAILURE":
                abandoned = receipt.get("abandoned_model_binding")
                if not isinstance(abandoned, Mapping):
                    issues.append(
                        f"started shard {shard_key} failure lacks its abandoned "
                        "MODEL input binding"
                    )
                else:
                    abandoned_key = str(
                        abandoned.get("work_unit_key") or ""
                    )
                    expected_model_suffix = (
                        f"/chain_iter2/tail_shard_model.{shard_key}"
                    )
                    abandoned_unit = (
                        artifact_units.get(abandoned_key)
                        if isinstance(artifact_units, Mapping)
                        else None
                    )
                    if (
                        not abandoned_key.endswith(expected_model_suffix)
                        or not isinstance(abandoned_unit, Mapping)
                        or abandoned_unit.get("run_id") != active_run_id
                        or abandoned.get("run_id") != active_run_id
                        or abandoned_unit.get("execution_state")
                        != "INPUTS_BOUND_PREEXECUTION"
                        or abandoned_unit.get("semantic_status")
                        != "INPUTS_BOUND"
                        or abandoned_unit.get("contract_digest")
                        != abandoned.get("contract_digest")
                        or abandoned_unit.get("input_set_digest")
                        != abandoned.get("input_set_digest")
                        or abandoned.get("execution_state")
                        != "INPUTS_BOUND_PREEXECUTION"
                        or abandoned.get("semantic_status") != "INPUTS_BOUND"
                        or abandoned.get("output_present") is not False
                        or abandoned.get("expected_transcript_path")
                        != str(row.get("transcript_path") or "")
                        or transcript_path.exists()
                    ):
                        issues.append(
                            f"started shard {shard_key} abandoned MODEL binding "
                            "is not exact"
                        )
            if transcript_path.is_file():
                transcript_sha = hashlib.sha256(
                    transcript_path.read_bytes()
                ).hexdigest()
                if receipt.get("transcript_sha256") != transcript_sha:
                    issues.append(
                        f"started shard {shard_key} transcript digest mismatch"
                    )
                if (
                    isinstance(model_binding, Mapping)
                    and model_binding.get("transcript_sha256") != transcript_sha
                ):
                    issues.append(
                        f"started shard {shard_key} model/transcript binding mismatch"
                    )
        except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError):
            issues.append(f"started shard {shard_key} disposition receipt is invalid")
    return list(dict.fromkeys(issues))


def _chain_tail_phase_completion_issues(
    scratchpad: Path,
    *,
    expected_run_id: str | None = None,
    config: Mapping[str, Any] | None = None,
) -> list[str]:
    """Refuse a soft phase checkpoint while typed tail work is non-terminal."""

    from chain_tail_authority import (
        _digest as chain_tail_digest,
        _load_manifest_ledger,
        _read_progress_receipt,
    )

    root = Path(scratchpad)
    issues = list(_chain_tail_legacy_fixed_generation_issues(
        root,
        config,
    ))
    issues.extend(_chain_tail_final_reconcile_readiness_issues(
        root,
        expected_run_id=expected_run_id,
    ))
    try:
        _manifest, ledger = _load_manifest_ledger(root)
        receipt = _read_progress_receipt(root)
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        TypeError,
        ValueError,
    ) as exc:
        return list(dict.fromkeys([
            *issues,
            "chain-tail completion authority unavailable: "
            f"{type(exc).__name__}: {exc}",
        ]))

    if isinstance(ledger.get("active_shard"), Mapping):
        issues.append("chain-tail completion retains an active shard")
    pending_rows = [
        str(row.get("pair_id") or "")
        for row in ledger.get("pairs") or []
        if isinstance(row, Mapping)
        and (
            str(row.get("reason") or "") == "PENDING_ANALYSIS"
            or (
                int(row.get("attempts") or 0) == 0
                and not str(row.get("reason") or "").startswith("BUDGET_STOP_")
            )
        )
    ]
    if pending_rows:
        issues.append(
            "chain-tail completion retains PENDING_ANALYSIS rows: "
            + ", ".join(pending_rows)
        )
    if str(receipt.get("status") or "") in {"", "UNKNOWN", "PENDING", "CONTINUE"}:
        issues.append(
            "chain-tail completion receipt is non-terminal: "
            f"{receipt.get('status')}"
        )

    try:
        units = read_artifact_ledger(root).get("work_units", {})
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        issues.append(
            "chain-tail completion artifact authority unavailable: "
            f"{type(exc).__name__}: {exc}"
        )
        units = {}
    for key, unit in (
        units.items() if isinstance(units, Mapping) else ()
    ):
        key_text = str(key)
        if (
            not isinstance(unit, Mapping)
            or "/chain_iter2/" not in key_text
            or not any(
                token in key_text
                for token in (
                    "tail_shard_",
                    "tail_primary",
                    "tail_snapshot",
                    "tail_reconcile",
                    "driver_merge",
                )
            )
        ):
            continue
        if (
            unit.get("execution_state") == "OUTPUT_COMMITTED"
            and unit.get("semantic_status") == "ACTIVE"
        ):
            continue
        if (
            "/chain_iter2/tail_shard_model." in key_text
            and unit.get("execution_state") == "INPUTS_BOUND_PREEXECUTION"
            and unit.get("semantic_status") == "INPUTS_BOUND"
        ):
            shard_suffix = key_text.rsplit(
                "/chain_iter2/tail_shard_model.", 1
            )[1]
            failure_key = key_text.rsplit(
                "/chain_iter2/tail_shard_model.", 1
            )[0] + (
                "/chain_iter2/tail_shard_failure." + shard_suffix
            )
            failure_unit = (
                units.get(failure_key)
                if isinstance(units, Mapping)
                else None
            )
            disposition_path = (
                root
                / "_chain_tail_shards"
                / f"shard_{shard_suffix}"
                / "disposition_receipt.json"
            )
            try:
                failure_receipt = json.loads(
                    disposition_path.read_text(
                        encoding="utf-8", errors="strict"
                    )
                )
            except (
                OSError,
                UnicodeError,
                json.JSONDecodeError,
                TypeError,
                ValueError,
            ):
                failure_receipt = {}
            abandoned = failure_receipt.get("abandoned_model_binding")
            expected_transcript = (
                root
                / "_chain_tail_shards"
                / f"shard_{shard_suffix}"
                / "chain_iteration2.md"
            )
            if (
                isinstance(failure_unit, Mapping)
                and failure_unit.get("execution_state")
                == "OUTPUT_COMMITTED"
                and failure_unit.get("semantic_status") == "ACTIVE"
                and failure_receipt.get("terminal_kind") == "FAILURE"
                and failure_receipt.get("receipt_sha256")
                == chain_tail_digest(failure_receipt, "receipt_sha256")
                and isinstance(abandoned, Mapping)
                and abandoned.get("work_unit_key") == key_text
                and abandoned.get("contract_digest")
                == unit.get("contract_digest")
                and abandoned.get("input_set_digest")
                == unit.get("input_set_digest")
                and abandoned.get("execution_state")
                == "INPUTS_BOUND_PREEXECUTION"
                and abandoned.get("semantic_status") == "INPUTS_BOUND"
                and abandoned.get("output_present") is False
                and abandoned.get("expected_transcript_path")
                == (
                    f"_chain_tail_shards/shard_{shard_suffix}/"
                    "chain_iteration2.md"
                )
                and not expected_transcript.exists()
            ):
                continue
        issues.append(
            "chain-tail completion retains a prepared/non-terminal "
            f"PhaseIO unit: {key_text}"
        )
    return list(dict.fromkeys(issues))


def _chain_tail_snapshot_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> tuple[PhaseIOContract, LaunchSpec]:
    root = Path(scratchpad)
    pass_index, shard_count, _generation_id = (
        _current_chain_tail_generation(root)
    )
    exact_inputs: set[str] = {
        _CHAIN_TAIL_CONTROL_MANIFEST,
        *_CHAIN_TAIL_MUTABLE_CONTROL_OUTPUTS,
    }
    primary = root / "chain_tail_primary_receipt.json"
    if primary.is_file():
        exact_inputs.update({
            "chain_tail_primary_receipt.json",
            "composition_coverage.md",
            "chain_hypotheses.md",
        })
    shard_parent = root / "_chain_tail_shards"
    if shard_parent.is_dir():
        for shard_dir in sorted(shard_parent.glob("shard_[0-9][0-9][0-9][0-9]")):
            if not shard_dir.is_dir():
                continue
            relative = shard_dir.relative_to(root).as_posix()
            for name in (
                "work_unit.json",
                "terminal_plan.json",
                "disposition_receipt.json",
            ):
                exact_inputs.add(f"{relative}/{name}")
            transcript = shard_dir / "chain_iteration2.md"
            if transcript.is_file():
                exact_inputs.add(f"{relative}/chain_iteration2.md")
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(
            config.get("cli_backend")
            or config.get("backend")
            or "claude"
        ),
        phase="chain_iter2",
        work_unit_id=_chain_tail_scoped_work_unit_id(
            "tail_snapshot",
            pass_index,
            shard_count,
        ),
        exact_inputs=tuple(sorted(exact_inputs)),
        exact_outputs=("chain_tail_terminal_snapshot.json",),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _run_chain_tail_snapshot_transaction(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> tuple[dict[str, Any], list[str]]:
    from chain_tail_authority import build_chain_tail_terminal_snapshot

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        issue = "chain-tail terminal snapshot requires an active driver run_id"
        return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]
    readiness = _chain_tail_final_reconcile_readiness_issues(
        root,
        expected_run_id=run_id,
    )
    if readiness:
        return {"status": "DEGRADED_UNRESOLVED"}, readiness
    project_root = Path(config.get("project_root") or root.parent)
    try:
        contract, launch = _chain_tail_snapshot_contract_and_launch(
            scratchpad=root, config=config, phase=phase
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if arm_issues:
            return {"status": "DEGRADED_UNRESOLVED"}, arm_issues
        snapshot = (
            build_chain_tail_terminal_snapshot(root)
            if execute
            else json.loads(
                (root / "chain_tail_terminal_snapshot.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
        )
        expected_generation = (
            _chain_tail_generation_from_work_unit_key(
                contract.key,
                role="tail_snapshot",
            )
        )
        observed_generation = _chain_tail_terminal_snapshot_generation(root)
        if observed_generation != expected_generation:
            raise ValueError(
                "chain-tail terminal snapshot differs from its scoped "
                "producer generation"
            )
        commit_issues = (
            _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
            if execute
            else []
        )
        return dict(snapshot), commit_issues
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        issue = (
            "chain-tail terminal snapshot transaction failed: "
            f"{type(exc).__name__}: {exc}"
        )
        return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]


def _chain_tail_rearm_generation_contract_and_launch(
    *,
    config: Mapping[str, Any],
    phase: Phase,
    pass_index: int,
    next_shard_index: int,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve one explicit retry-pass/control-cursor generation."""

    target_pass = int(pass_index)
    next_shard = int(next_shard_index)
    if target_pass < 1 or next_shard < 0:
        raise ValueError("chain-tail rearm generation is invalid")
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(
            config.get("cli_backend")
            or config.get("backend")
            or "claude"
        ),
        phase="chain_iter2",
        work_unit_id=(
            f"tail_rearm_control.p{target_pass:04d}."
            f"s{next_shard:04d}"
        ),
        exact_inputs=(
            _CHAIN_TAIL_CONTROL_MANIFEST,
            *_CHAIN_TAIL_FINAL_ROOT_OUTPUTS,
        ),
        exact_outputs=_CHAIN_TAIL_MUTABLE_CONTROL_OUTPUTS,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _chain_tail_rearm_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve one retry-pass control generation before CTA mutates it."""

    from chain_tail_authority import _load_manifest_ledger

    root = Path(scratchpad)
    _manifest, ledger = _load_manifest_ledger(root)
    if isinstance(ledger.get("active_shard"), Mapping):
        raise ValueError("chain-tail rearm cannot replace an active shard")
    return _chain_tail_rearm_generation_contract_and_launch(
        config=config,
        phase=phase,
        pass_index=int(ledger.get("pass_index") or 0) + 1,
        next_shard_index=len(ledger.get("shards") or []),
    )


def _planned_chain_tail_rearm_postimages(
    scratchpad: Path,
) -> tuple[dict[str, bytes], dict[str, Any], int, int]:
    """Resolve CTA's pure rearm transform into the PhaseIO denominator."""

    from chain_tail_authority import (
        MUTABLE_CONTROL_PATHS,
        plan_rearm_unresolved_chain_tail,
    )

    root = Path(scratchpad)
    planned = plan_rearm_unresolved_chain_tail(root)
    if not isinstance(planned, Mapping):
        raise ValueError("chain-tail rearm plan is malformed")
    pass_index = planned.get("pass_index")
    next_shard_index = planned.get("next_shard_index")
    receipt = planned.get("receipt")
    postimages = planned.get("postimages")
    if (
        not isinstance(pass_index, int)
        or isinstance(pass_index, bool)
        or pass_index < 1
        or not isinstance(next_shard_index, int)
        or isinstance(next_shard_index, bool)
        or next_shard_index < 0
        or not isinstance(receipt, Mapping)
        or not isinstance(postimages, Mapping)
        or set(postimages) != set(MUTABLE_CONTROL_PATHS)
    ):
        raise ValueError(
            "chain-tail rearm plan denominator or generation is malformed"
        )
    normalized: dict[str, bytes] = {}
    for relative in MUTABLE_CONTROL_PATHS:
        raw = postimages.get(relative)
        if type(raw) is not bytes:
            raise ValueError(
                f"{relative}: chain-tail rearm postimage is not bytes"
            )
        normalized[f"scratchpad:{relative}"] = raw
    if (
        receipt.get("status") != "CONTINUE"
        or receipt.get("pass_index") != pass_index
    ):
        raise ValueError(
            "chain-tail rearm planned receipt differs from its generation"
        )
    return normalized, dict(receipt), pass_index, next_shard_index


def _apply_chain_tail_rearm_successor_plan(
    scratchpad: Path,
    project_root: Path,
    *,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    successor_plan: Any,
    planned_output_bytes: Mapping[str, bytes],
) -> None:
    """Resume the exact ordered control-only successor transition."""

    root = Path(scratchpad)
    expected_records = {
        identity: {
            "sha256": hashlib.sha256(raw).hexdigest(),
            "size": len(raw),
        }
        for identity, raw in planned_output_bytes.items()
    }
    if successor_plan.expected_output_records != expected_records:
        raise ValueError(
            "chain-tail rearm successor plan differs from the pure CTA "
            "postimages"
        )
    transitions = tuple(successor_plan.transitions)
    if {
        transition.artifact_identity for transition in transitions
    } != set(planned_output_bytes):
        raise ValueError(
            "chain-tail rearm successor transition denominator differs"
        )
    for transition in transitions:
        identity = transition.artifact_identity
        ordinal = int(transition.ordinal)
        progress = begin_driver_successor_step(
            root,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
            ordinal=ordinal,
        )
        if progress.get("state") == "STEP_APPLIED":
            continue
        if not identity.startswith("scratchpad:"):
            raise ValueError(
                "chain-tail rearm successor output is not scratchpad-local"
            )
        _materialize_driver_successor_bytes(
            root / identity.removeprefix("scratchpad:"),
            planned_output_bytes[identity],
        )
        complete_driver_successor_step(
            root,
            Path(project_root),
            contract,
            launch,
            run_id=run_id,
            ordinal=ordinal,
        )


def _materialized_chain_tail_rearm_issues(
    scratchpad: Path,
    project_root: Path,
    *,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    unit: Mapping[str, Any],
    run_id: str,
) -> list[str]:
    """Prove a precommit CTA rearm is the exact bound predecessor transform."""

    from chain_tail_authority import (
        COMPOSITION_CANDIDATES_NAME,
        CONTROL_DIR,
        LEDGER_NAME,
        PROJECTION_NAME,
        RECEIPT_NAME,
        _composition_candidate_payload,
        _digest as chain_tail_digest,
        _load_manifest_ledger,
        _receipt_from_state,
        _render_projection,
    )

    root = Path(scratchpad)
    issues = validate_work_unit_inputs(
        root,
        Path(project_root),
        contract,
        launch,
        run_id=run_id,
    )
    manifest, control_ledger = _load_manifest_ledger(root)
    root_ledger = json.loads(
        (root / LEDGER_NAME).read_text(encoding="utf-8", errors="strict")
    )
    if not isinstance(root_ledger, dict):
        return [*issues, "chain-tail rearm root ledger is malformed"]
    expected_ledger = json.loads(json.dumps(root_ledger))
    unresolved_ids = [
        str(row.get("pair_id") or "")
        for row in expected_ledger.get("pairs") or []
        if (
            isinstance(row, Mapping)
            and row.get("disposition") == "UNRESOLVED_COMPOSITION"
        )
    ]
    expected_ledger["retry_pair_ids"] = unresolved_ids
    expected_ledger["retry_cursor"] = 0
    expected_ledger["pass_index"] = (
        int(root_ledger.get("pass_index") or 0) + 1
    )
    expected_ledger["budget_stop_reason"] = ""
    expected_ledger["ledger_sha256"] = chain_tail_digest(
        expected_ledger,
        "ledger_sha256",
    )
    generation = re.fullmatch(
        r"tail_rearm_control\.p(\d{4})\.s(\d{4})",
        contract.work_unit_id,
    )
    if (
        generation is None
        or int(generation.group(1))
        != int(expected_ledger["pass_index"])
        or int(generation.group(2))
        != len(expected_ledger.get("shards") or [])
    ):
        issues.append("chain-tail rearm work-unit generation mismatch")
    if not unresolved_ids:
        issues.append("chain-tail rearm has no unresolved denominator")
    if control_ledger != expected_ledger:
        issues.append(
            "chain-tail rearm materialized control ledger differs from the "
            "exact terminal predecessor transform"
        )

    expected_candidates = _composition_candidate_payload(
        manifest,
        expected_ledger,
    )
    expected_receipt = _receipt_from_state(
        manifest,
        expected_ledger,
    )
    expected_projection = _render_projection(
        expected_receipt,
        expected_ledger,
    )
    observed_candidates = json.loads(
        (
            root / CONTROL_DIR / COMPOSITION_CANDIDATES_NAME
        ).read_text(encoding="utf-8", errors="strict")
    )
    observed_receipt = json.loads(
        (root / CONTROL_DIR / RECEIPT_NAME).read_text(
            encoding="utf-8",
            errors="strict",
        )
    )
    observed_projection = (
        root / CONTROL_DIR / PROJECTION_NAME
    ).read_text(encoding="utf-8", errors="strict")
    if observed_candidates != expected_candidates:
        issues.append(
            "chain-tail rearm candidate control projection mismatch"
        )
    if observed_receipt != expected_receipt:
        issues.append("chain-tail rearm progress receipt mismatch")
    if observed_projection != expected_projection:
        issues.append("chain-tail rearm Markdown control projection mismatch")

    journal_identity = (
        "scratchpad:_chain_tail_control/scheduler_journal.json"
    )
    output_prestates = unit.get("output_prestates")
    journal_prestate = (
        output_prestates.get(journal_identity)
        if isinstance(output_prestates, Mapping)
        else None
    )
    journal_path = root / "_chain_tail_control" / "scheduler_journal.json"
    if (
        not isinstance(journal_prestate, Mapping)
        or not journal_path.is_file()
        or journal_prestate.get("sha256")
        != hashlib.sha256(journal_path.read_bytes()).hexdigest()
        or journal_prestate.get("size") != journal_path.stat().st_size
    ):
        issues.append(
            "chain-tail rearm changed the scheduler journal predecessor"
        )
    return list(dict.fromkeys(issues))


def _run_chain_tail_rearm_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> tuple[dict[str, Any], list[str]]:
    """Own one terminal-generation retry rearm before ordinary shard prepare."""

    from chain_tail_authority import (
        _load_manifest_ledger,
        _read_progress_receipt,
        _terminal_publication_is_complete,
    )

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        issue = "chain-tail rearm requires an active driver run_id"
        return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]
    try:
        artifact_state = read_artifact_ledger(root)
        _manifest, control_ledger = _load_manifest_ledger(root)
        current_pass = int(control_ledger.get("pass_index") or 0)
        current_shard = len(control_ledger.get("shards") or [])
        if current_pass >= 1:
            recovery_contract, recovery_launch = (
                _chain_tail_rearm_generation_contract_and_launch(
                    config=config,
                    phase=phase,
                    pass_index=current_pass,
                    next_shard_index=current_shard,
                )
            )
            recovery_unit = artifact_state.get(
                "work_units", {}
            ).get(recovery_contract.key)
            if isinstance(recovery_unit, Mapping):
                recovery_state = (
                    recovery_unit.get("execution_state"),
                    recovery_unit.get("semantic_status"),
                )
                if recovery_state == (
                    "INPUTS_BOUND_PREEXECUTION",
                    "INPUTS_BOUND",
                ):
                    (
                        planned_output_bytes,
                        _planned_receipt,
                        planned_pass,
                        planned_shard,
                    ) = _planned_chain_tail_rearm_postimages(root)
                    if (
                        planned_pass != current_pass
                        or planned_shard != current_shard
                    ):
                        return (
                            {"status": "DEGRADED_UNRESOLVED"},
                            [
                                "chain-tail rearm recovery generation "
                                "differs from the pure CTA plan"
                            ],
                        )
                    successor_plan = load_driver_successor_plan(
                        root,
                        project_root,
                        recovery_contract,
                        recovery_launch,
                        run_id=run_id,
                    )
                    execute, recovery_arm_issues = (
                        _arm_deterministic_driver_work_unit(
                            scratchpad=root,
                            project_root=project_root,
                            contract=recovery_contract,
                            launch=recovery_launch,
                            run_id=run_id,
                            successor_plan=successor_plan,
                        )
                    )
                    if recovery_arm_issues or not execute:
                        return (
                            {"status": "DEGRADED_UNRESOLVED"},
                            list(dict.fromkeys([
                                *recovery_arm_issues,
                                *(
                                    []
                                    if execute
                                    else [
                                        "chain-tail rearm prepared recovery "
                                        "is not executable"
                                    ]
                                ),
                            ])),
                        )
                    _apply_chain_tail_rearm_successor_plan(
                        root,
                        project_root,
                        contract=recovery_contract,
                        launch=recovery_launch,
                        run_id=run_id,
                        successor_plan=successor_plan,
                        planned_output_bytes=planned_output_bytes,
                    )
                    artifact_state = read_artifact_ledger(root)
                    recovery_unit = artifact_state.get(
                        "work_units", {}
                    ).get(recovery_contract.key)
                    materialized_issues = (
                        _materialized_chain_tail_rearm_issues(
                            root,
                            project_root,
                            contract=recovery_contract,
                            launch=recovery_launch,
                            unit=recovery_unit,
                            run_id=run_id,
                        )
                        if isinstance(recovery_unit, Mapping)
                        else [
                            "chain-tail rearm prepared recovery unit "
                            "disappeared"
                        ]
                    )
                    if materialized_issues:
                        return (
                            {"status": "DEGRADED_UNRESOLVED"},
                            materialized_issues,
                        )
                    recovery_commit_issues = (
                        _commit_deterministic_driver_work_unit(
                            scratchpad=root,
                            project_root=project_root,
                            contract=recovery_contract,
                            launch=recovery_launch,
                            run_id=run_id,
                            expected_output_records=(
                                successor_plan.expected_output_records
                            ),
                        )
                    )
                    if recovery_commit_issues:
                        return (
                            {"status": "DEGRADED_UNRESOLVED"},
                            list(dict.fromkeys(recovery_commit_issues)),
                        )
                    artifact_state = read_artifact_ledger(root)
                    _recovered, replay_issues = (
                        _full_committed_producer_authority(
                            root,
                            project_root,
                            ledger=artifact_state,
                            outer_work_unit_key=recovery_contract.key,
                            run_id=run_id,
                            expected_input_identities=tuple(
                                recovery_contract.immutable_inputs
                            ),
                            expected_output_identities=tuple(
                                f"scratchpad:{name}"
                                for name in _CHAIN_TAIL_MUTABLE_CONTROL_OUTPUTS
                            ),
                            actor="DRIVER",
                        )
                    )
                    if replay_issues:
                        return (
                            {"status": "DEGRADED_UNRESOLVED"},
                            replay_issues,
                        )
                    return dict(_read_progress_receipt(root)), []
                if recovery_state == (
                    "OUTPUT_COMMITTED",
                    "ACTIVE",
                ):
                    materialized_issues = (
                        _materialized_chain_tail_rearm_issues(
                            root,
                            project_root,
                            contract=recovery_contract,
                            launch=recovery_launch,
                            unit=recovery_unit,
                            run_id=run_id,
                        )
                    )
                    _recovered, replay_issues = (
                        _full_committed_producer_authority(
                            root,
                            project_root,
                            ledger=artifact_state,
                            outer_work_unit_key=recovery_contract.key,
                            run_id=run_id,
                            expected_input_identities=tuple(
                                recovery_contract.immutable_inputs
                            ),
                            expected_output_identities=tuple(
                                f"scratchpad:{name}"
                                for name in _CHAIN_TAIL_MUTABLE_CONTROL_OUTPUTS
                            ),
                            actor="DRIVER",
                        )
                    )
                    combined_replay_issues = list(dict.fromkeys([
                        *materialized_issues,
                        *replay_issues,
                    ]))
                    if combined_replay_issues:
                        return (
                            {"status": "DEGRADED_UNRESOLVED"},
                            combined_replay_issues,
                        )
                    return dict(_read_progress_receipt(root)), []
                return (
                    {"status": "DEGRADED_UNRESOLVED"},
                    [
                        "chain-tail rearm recovery unit is neither exact "
                        "PREPARED nor ACTIVE/OUTPUT_COMMITTED"
                    ],
                )
        prior = _read_progress_receipt(root)
        if (
            prior.get("status")
            not in {"DEGRADED_UNRESOLVED", "BUDGET_STOP"}
            or not _terminal_publication_is_complete(root)
        ):
            issue = (
                "chain-tail rearm requires one exact terminal unresolved "
                "publication generation"
            )
            return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]
        snapshot_generation = _chain_tail_terminal_snapshot_generation(root)
        root_generation = _chain_tail_root_semantic_generation(root)
        control_generation = _current_chain_tail_generation(root)
        if (
            snapshot_generation != root_generation
            or snapshot_generation != control_generation
        ):
            issue = (
                "chain-tail rearm requires snapshot, root semantic ledger, "
                "and control ledger to share one exact generation"
            )
            return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]
        predecessor_pass, predecessor_shards, _generation_id = (
            snapshot_generation
        )
        final_key = (
            f"{str(config.get('pipeline') or 'sc')}/"
            f"{str(config.get('mode') or 'thorough')}/"
            f"{str(config.get('language') or 'unknown')}/"
            f"{str(config.get('cli_backend') or config.get('backend') or 'claude')}/"
            "chain_iter2/"
            + _chain_tail_scoped_work_unit_id(
                "tail_reconcile",
                predecessor_pass,
                predecessor_shards,
            )
        )
        final_inputs = {
            f"scratchpad:{_CHAIN_TAIL_CONTROL_MANIFEST}",
            "scratchpad:chain_tail_terminal_snapshot.json",
            *(
                {"scratchpad:chain_hypotheses.md"}
                if (root / "chain_hypotheses.md").is_file()
                else set()
            ),
        }
        final_unit, final_issues = _full_committed_producer_authority(
            root,
            project_root,
            ledger=artifact_state,
            outer_work_unit_key=final_key,
            run_id=run_id,
            expected_input_identities=tuple(sorted(final_inputs)),
            expected_output_identities=tuple(
                f"scratchpad:{name}"
                for name in _CHAIN_TAIL_FINAL_PUBLICATION_OUTPUTS
            ),
            actor="DRIVER",
            require_live_input_authority=False,
        )
        snapshot_identity = "scratchpad:chain_tail_terminal_snapshot.json"
        final_snapshot_binding = (
            final_unit.get("input_bindings", {}).get(snapshot_identity)
            if isinstance(final_unit, Mapping)
            and isinstance(final_unit.get("input_bindings"), Mapping)
            else None
        )
        expected_snapshot_key = (
            final_key.rsplit("/", 1)[0]
            + "/"
            + _chain_tail_scoped_work_unit_id(
                "tail_snapshot",
                predecessor_pass,
                predecessor_shards,
            )
        )
        if (
            final_issues
            or not isinstance(final_snapshot_binding, Mapping)
            or final_snapshot_binding.get("producer_work_unit_key")
            != expected_snapshot_key
        ):
            return (
                {"status": "DEGRADED_UNRESOLVED"},
                [
                    "chain-tail rearm final producer authority is invalid: "
                    + "; ".join(
                        final_issues
                        or [
                            "terminal snapshot producer generation mismatch"
                        ]
                    )
                ],
            )
        contract, launch = _chain_tail_rearm_contract_and_launch(
            scratchpad=root,
            config=config,
            phase=phase,
        )
        (
            planned_output_bytes,
            planned_receipt,
            planned_pass,
            planned_shard,
        ) = _planned_chain_tail_rearm_postimages(root)
        if (
            planned_pass,
            planned_shard,
        ) != (
            predecessor_pass + 1,
            predecessor_shards,
        ):
            raise ValueError(
                "chain-tail rearm successor is not exact (P+1,S) from "
                "the frozen terminal predecessor"
            )
        expected_work_unit_id = (
            f"tail_rearm_control.p{planned_pass:04d}."
            f"s{planned_shard:04d}"
        )
        if contract.work_unit_id != expected_work_unit_id:
            raise ValueError(
                "chain-tail rearm contract generation differs from the "
                "pure CTA plan"
            )
        successor_plan = plan_driver_successor_transaction(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            planned_output_bytes=planned_output_bytes,
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            successor_plan=successor_plan,
        )
        if arm_issues:
            return {"status": "DEGRADED_UNRESOLVED"}, arm_issues
        if not execute:
            issue = (
                "chain-tail rearm successor unexpectedly replayed as "
                "already committed"
            )
            return {"status": "DEGRADED_UNRESOLVED"}, [issue]
        _apply_chain_tail_rearm_successor_plan(
            root,
            project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            successor_plan=successor_plan,
            planned_output_bytes=planned_output_bytes,
        )
        receipt = _read_progress_receipt(root)
        if dict(receipt) != planned_receipt:
            raise ValueError(
                "chain-tail rearm materialized receipt differs from the "
                "pure CTA plan"
            )
        artifact_state = read_artifact_ledger(root)
        armed_unit = artifact_state.get(
            "work_units", {}
        ).get(contract.key)
        materialized_issues = (
            _materialized_chain_tail_rearm_issues(
                root,
                project_root,
                contract=contract,
                launch=launch,
                unit=armed_unit,
                run_id=run_id,
            )
            if isinstance(armed_unit, Mapping)
            else ["chain-tail rearm armed work unit disappeared"]
        )
        commit_issues = (
            _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=materialized_issues,
                expected_output_records=(
                    successor_plan.expected_output_records
                ),
            )
        )
        return dict(receipt), list(dict.fromkeys(commit_issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        issue = (
            "chain-tail rearm transaction failed: "
            f"{type(exc).__name__}: {exc}"
        )
        return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]


def _chain_tail_final_contract_and_launch(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve final publication from the exact terminal shard denominator."""

    from chain_tail_authority import CONTROL_DIR, CONTROL_JOURNAL_NAME

    root = Path(scratchpad)
    snapshot_run_id = str(config.get("_run_id") or "").strip()
    if not snapshot_run_id:
        raise ValueError(
            "chain-tail final publication requires an active driver run_id"
        )
    readiness = _chain_tail_final_reconcile_readiness_issues(
        root,
        expected_run_id=snapshot_run_id,
    )
    if readiness:
        raise ValueError("; ".join(readiness))
    pass_index, shard_count, generation_id = (
        _current_chain_tail_generation(root)
    )
    snapshot = root / "chain_tail_terminal_snapshot.json"
    if not snapshot.is_file():
        raise ValueError("chain-tail terminal snapshot is unavailable")
    snapshot_generation = _chain_tail_terminal_snapshot_generation(root)
    if snapshot_generation != (pass_index, shard_count, generation_id):
        raise ValueError(
            "chain-tail terminal snapshot is not the current control generation"
        )
    snapshot_contract, snapshot_launch = _chain_tail_snapshot_contract_and_launch(
        scratchpad=root, config=config, phase=phase
    )
    expected_snapshot_id = _chain_tail_scoped_work_unit_id(
        "tail_snapshot",
        pass_index,
        shard_count,
    )
    if snapshot_contract.work_unit_id != expected_snapshot_id:
        raise ValueError(
            "chain-tail terminal snapshot contract generation mismatch"
        )
    snapshot_project = Path(config.get("project_root") or root.parent)
    snapshot_producer_issues = validate_work_unit_inputs(
        root,
        snapshot_project,
        snapshot_contract,
        snapshot_launch,
        run_id=snapshot_run_id,
    )
    snapshot_producer_issues.extend(
        validate_work_unit_artifacts(
            root,
            snapshot_project,
            snapshot_contract,
            snapshot_launch,
            run_id=snapshot_run_id,
            actor="DRIVER",
        )
    )
    if snapshot_producer_issues:
        raise ValueError(
            "chain-tail terminal snapshot producer is invalid: "
            + "; ".join(dict.fromkeys(snapshot_producer_issues))
        )
    exact_inputs: set[str] = {
        _CHAIN_TAIL_CONTROL_MANIFEST,
        "chain_tail_terminal_snapshot.json",
    }
    if (root / "chain_hypotheses.md").is_file():
        exact_inputs.add("chain_hypotheses.md")
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(
            config.get("cli_backend")
            or config.get("backend")
            or "claude"
        ),
        phase="chain_iter2",
        work_unit_id=_chain_tail_scoped_work_unit_id(
            "tail_reconcile",
            pass_index,
            shard_count,
        ),
        exact_inputs=tuple(sorted(exact_inputs)),
        exact_outputs=_CHAIN_TAIL_FINAL_PUBLICATION_OUTPUTS,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _read_exact_current_chain_tail_final_replay(
    scratchpad: Path,
    project_root: Path,
    *,
    config: Mapping[str, Any],
    phase: Phase,
    run_id: str,
) -> dict[str, Any] | None:
    """Return exact current-G final authority without mutating live state."""

    from chain_tail_authority import (
        COMPOSITION_CANDIDATES_NAME,
        CONTROL_DIR,
        LEDGER_NAME,
        PROJECTION_NAME,
        PUBLICATION_ARMED_NAME,
        RECEIPT_NAME,
        TERMINAL_SNAPSHOT_NAME,
        _digest as chain_tail_digest,
        _read_json as read_chain_tail_json,
        _terminal_publication_is_complete,
    )

    root = Path(scratchpad)
    artifact_state = read_artifact_ledger(root)
    units = artifact_state.get("work_units")
    bindings = artifact_state.get("artifact_bindings")
    marker_path = root / CONTROL_DIR / PUBLICATION_ARMED_NAME
    marker_temp_path = marker_path.with_name(f"{marker_path.name}.tmp")
    final_identities = tuple(
        f"scratchpad:{name}"
        for name in _CHAIN_TAIL_FINAL_PUBLICATION_OUTPUTS
    )
    pipeline = str(config.get("pipeline") or "sc")
    mode = str(config.get("mode") or "thorough")
    ecosystem = str(config.get("language") or "unknown")
    backend = str(
        config.get("cli_backend")
        or config.get("backend")
        or "claude"
    )
    key_prefix = (
        f"{pipeline}/{mode}/{ecosystem}/{backend}/chain_iter2/"
    )

    try:
        pass_index, shard_count, generation_id = (
            _current_chain_tail_generation(root)
        )
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        terminal_claim = bool(
            marker_path.exists()
            or marker_path.is_symlink()
            or marker_temp_path.exists()
            or marker_temp_path.is_symlink()
        )
        if isinstance(units, Mapping):
            terminal_claim = terminal_claim or any(
                isinstance(key, str)
                and re.fullmatch(
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"chain_iter2/tail_reconcile\.p\d{4}\.s\d{4}",
                    key,
                    flags=re.ASCII,
                )
                is not None
                for key in units
            )
        if isinstance(bindings, Mapping):
            terminal_claim = terminal_claim or any(
                isinstance(binding, Mapping)
                and isinstance(binding.get("owner_key"), str)
                and re.fullmatch(
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"[a-z0-9][a-z0-9_.-]*/"
                    r"chain_iter2/tail_reconcile\.p\d{4}\.s\d{4}",
                    str(binding.get("owner_key")),
                    flags=re.ASCII,
                )
                is not None
                for identity, binding in bindings.items()
                if identity in final_identities
            )
        if terminal_claim:
            raise ValueError(
                "current final publication generation is unavailable"
            )
        return None

    final_work_unit_id = _chain_tail_scoped_work_unit_id(
        "tail_reconcile",
        pass_index,
        shard_count,
    )
    expected_key = key_prefix + final_work_unit_id
    current_suffix = f"/chain_iter2/{final_work_unit_id}"
    exact_unit_claim = bool(
        isinstance(units, Mapping) and expected_key in units
    )
    exact_output_claim = False
    ambiguous_output_claim = False
    if isinstance(bindings, Mapping):
        for identity in final_identities:
            binding = bindings.get(identity)
            owner = (
                str(binding.get("owner_key") or "")
                if isinstance(binding, Mapping)
                else ""
            )
            exact_output_claim = exact_output_claim or owner == expected_key
            ambiguous_output_claim = ambiguous_output_claim or bool(
                owner.endswith(current_suffix) and owner != expected_key
            )
    claimed = bool(
        exact_unit_claim
        or exact_output_claim
        or ambiguous_output_claim
        or marker_path.exists()
        or marker_path.is_symlink()
        or marker_temp_path.exists()
        or marker_temp_path.is_symlink()
    )
    if not claimed:
        return None
    if ambiguous_output_claim:
        raise ValueError("current final publication ownership is ambiguous")
    if not isinstance(units, Mapping) or not isinstance(bindings, Mapping):
        raise ValueError("current final publication ledger is malformed")

    exact_inputs: set[str] = {
        _CHAIN_TAIL_CONTROL_MANIFEST,
        TERMINAL_SNAPSHOT_NAME,
    }
    if (root / "chain_hypotheses.md").is_file():
        exact_inputs.add("chain_hypotheses.md")
    contract = resolve_phase_io_contract(
        pipeline=pipeline,
        mode=mode,
        ecosystem=ecosystem,
        backend=backend,
        phase="chain_iter2",
        work_unit_id=final_work_unit_id,
        exact_inputs=tuple(sorted(exact_inputs)),
        exact_outputs=_CHAIN_TAIL_FINAL_PUBLICATION_OUTPUTS,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=max(1, int(phase.base_timeout_s)),
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    if contract.key != expected_key:
        raise ValueError("current final publication key does not replay")

    prepared_unit = units.get(expected_key)
    if (
        isinstance(prepared_unit, Mapping)
        and prepared_unit.get("execution_state")
        == "INPUTS_BOUND_PREEXECUTION"
        and prepared_unit.get("semantic_status") == "INPUTS_BOUND"
    ):
        expected_input_identities = {
            *contract.immutable_inputs,
            *contract.bounded_lookup_inputs,
        }
        prepared_input_bindings = prepared_unit.get("input_bindings")
        if (
            exact_output_claim
            or ambiguous_output_claim
            or prepared_unit.get("schema")
            != "plamen.artifact-work-unit.v2"
            or prepared_unit.get("work_unit_key") != expected_key
            or prepared_unit.get("run_id") != run_id
            or prepared_unit.get("model_invoked") is not False
            or prepared_unit.get("contract_manifest") != contract.to_dict()
            or prepared_unit.get("contract_digest") != contract.digest
            or prepared_unit.get("launch_manifest") != launch.to_dict()
            or prepared_unit.get("launch_digest") != launch.digest
            or prepared_unit.get("artifacts") != {}
            or not isinstance(prepared_input_bindings, Mapping)
            or set(prepared_input_bindings) != expected_input_identities
            or prepared_unit.get("input_set_digest")
            != _input_set_digest(prepared_input_bindings)
            or validate_work_unit_inputs(
                root,
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
            )
        ):
            raise ValueError(
                "current final publication prepared authority is invalid"
            )

        snapshot = read_chain_tail_json(root / TERMINAL_SNAPSHOT_NAME)
        expected_marker: dict[str, Any] = {
            "schema_version": "plamen.chain_tail.final_publication.v1",
            "authority": "CONTROL_ONLY",
            "state": "ARMED",
            "snapshot_sha256": str(
                snapshot.get("snapshot_sha256") or ""
            ),
            "producer_key": expected_key,
            "producer_contract_digest": contract.digest,
        }
        if (
            not expected_marker["snapshot_sha256"]
            or expected_marker["snapshot_sha256"]
            != chain_tail_digest(snapshot, "snapshot_sha256")
        ):
            raise ValueError(
                "current final publication prepared snapshot is invalid"
            )
        expected_marker["marker_sha256"] = chain_tail_digest(
            expected_marker,
            "marker_sha256",
        )
        expected_marker_bytes = (
            json.dumps(expected_marker, indent=2, sort_keys=True) + "\n"
        ).encode("utf-8")

        marker_present = bool(
            marker_path.exists() or marker_path.is_symlink()
        )
        marker_temp_present = bool(
            marker_temp_path.exists() or marker_temp_path.is_symlink()
        )
        if marker_present and marker_temp_present:
            raise ValueError(
                "current final publication prepared marker is ambiguous"
            )
        for candidate in (
            *((marker_path,) if marker_present else ()),
            *((marker_temp_path,) if marker_temp_present else ()),
        ):
            candidate_stat = candidate.lstat()
            if (
                not stat.S_ISREG(candidate_stat.st_mode)
                or int(candidate_stat.st_nlink) != 1
                or candidate.read_bytes() != expected_marker_bytes
            ):
                raise ValueError(
                    "current final publication prepared marker is invalid"
                )
        return None

    final_unit, final_issues = _full_committed_producer_authority(
        root,
        Path(project_root),
        ledger=artifact_state,
        outer_work_unit_key=expected_key,
        run_id=run_id,
        expected_input_identities=tuple(
            (*contract.immutable_inputs, *contract.bounded_lookup_inputs)
        ),
        expected_output_identities=final_identities,
        actor="DRIVER",
        require_live_input_authority=False,
    )
    if (
        final_issues
        or not isinstance(final_unit, Mapping)
        or final_unit.get("contract_manifest") != contract.to_dict()
        or final_unit.get("contract_digest") != contract.digest
        or final_unit.get("launch_manifest") != launch.to_dict()
        or final_unit.get("launch_digest") != launch.digest
        or final_unit.get("run_id") != run_id
        or final_unit.get("model_invoked") is not False
        or final_unit.get("semantic_status") != "ACTIVE"
        or final_unit.get("execution_state") != "OUTPUT_COMMITTED"
    ):
        raise ValueError(
            "current final publication producer authority does not replay"
        )

    snapshot_contract, snapshot_launch = (
        _chain_tail_snapshot_contract_and_launch(
            scratchpad=root,
            config=config,
            phase=phase,
        )
    )
    expected_snapshot_key = key_prefix + _chain_tail_scoped_work_unit_id(
        "tail_snapshot",
        pass_index,
        shard_count,
    )
    if snapshot_contract.key != expected_snapshot_key:
        raise ValueError("current terminal snapshot key does not replay")
    snapshot_unit, snapshot_issues = _full_committed_producer_authority(
        root,
        Path(project_root),
        ledger=artifact_state,
        outer_work_unit_key=expected_snapshot_key,
        run_id=run_id,
        expected_input_identities=tuple(
            (
                *snapshot_contract.immutable_inputs,
                *snapshot_contract.bounded_lookup_inputs,
            )
        ),
        expected_output_identities=(
            f"scratchpad:{TERMINAL_SNAPSHOT_NAME}",
        ),
        actor="DRIVER",
        require_live_input_authority=False,
    )
    if (
        snapshot_issues
        or not isinstance(snapshot_unit, Mapping)
        or snapshot_unit.get("contract_manifest")
        != snapshot_contract.to_dict()
        or snapshot_unit.get("contract_digest") != snapshot_contract.digest
        or snapshot_unit.get("launch_manifest")
        != snapshot_launch.to_dict()
        or snapshot_unit.get("launch_digest") != snapshot_launch.digest
        or snapshot_unit.get("run_id") != run_id
        or snapshot_unit.get("model_invoked") is not False
        or snapshot_unit.get("semantic_status") != "ACTIVE"
        or snapshot_unit.get("execution_state") != "OUTPUT_COMMITTED"
    ):
        raise ValueError(
            "current terminal snapshot producer authority does not replay"
        )

    snapshot_identity = f"scratchpad:{TERMINAL_SNAPSHOT_NAME}"
    input_bindings = final_unit.get("input_bindings")
    snapshot_binding = (
        input_bindings.get(snapshot_identity)
        if isinstance(input_bindings, Mapping)
        else None
    )
    snapshot_artifacts = snapshot_unit.get("artifacts")
    snapshot_artifact = (
        snapshot_artifacts.get(snapshot_identity)
        if isinstance(snapshot_artifacts, Mapping)
        else None
    )
    snapshot_commit = snapshot_unit.get("commit_authority")
    snapshot_path = root / TERMINAL_SNAPSHOT_NAME
    snapshot_bytes = snapshot_path.read_bytes()
    snapshot_sha256 = hashlib.sha256(snapshot_bytes).hexdigest()
    if (
        not isinstance(snapshot_binding, Mapping)
        or snapshot_binding.get("status") != "ACTIVE"
        or snapshot_binding.get("sha256") != snapshot_sha256
        or snapshot_binding.get("size") != len(snapshot_bytes)
        or snapshot_binding.get("producer_work_unit_key")
        != expected_snapshot_key
        or snapshot_binding.get("producer_run_id") != run_id
        or snapshot_binding.get("producer_contract_digest")
        != snapshot_contract.digest
        or snapshot_binding.get("producer_launch_digest")
        != snapshot_launch.digest
        or not isinstance(snapshot_artifact, Mapping)
        or snapshot_artifact.get("status") != "ACTIVE"
        or snapshot_artifact.get("sha256") != snapshot_sha256
        or snapshot_artifact.get("size") != len(snapshot_bytes)
        or not isinstance(snapshot_commit, Mapping)
        or snapshot_binding.get("producer_commit_receipt_digest")
        != snapshot_commit.get("receipt_digest")
    ):
        raise ValueError(
            "current final publication snapshot binding is invalid"
        )

    for identity in final_identities:
        binding = bindings.get(identity)
        if (
            not isinstance(binding, Mapping)
            or binding.get("owner_key") != expected_key
            or binding.get("writer") != "DRIVER"
            or binding.get("status") != "ACTIVE"
        ):
            raise ValueError(
                "current final publication output ownership is invalid"
            )

    snapshot = read_chain_tail_json(snapshot_path)
    root_ledger_path = root / LEDGER_NAME
    control_ledger_path = root / CONTROL_DIR / LEDGER_NAME
    root_ledger_bytes = root_ledger_path.read_bytes()
    control_ledger_bytes = control_ledger_path.read_bytes()
    root_ledger = read_chain_tail_json(root_ledger_path)
    control_ledger = read_chain_tail_json(control_ledger_path)
    receipt_path = root / RECEIPT_NAME
    receipt_bytes = receipt_path.read_bytes()
    receipt = read_chain_tail_json(receipt_path)
    candidates = read_chain_tail_json(root / COMPOSITION_CANDIDATES_NAME)
    semantic_ledger = snapshot.get("semantic_ledger")
    generation = (pass_index, shard_count, generation_id)
    if (
        _chain_tail_terminal_snapshot_generation(root) != generation
        or _chain_tail_root_semantic_generation(root) != generation
        or _current_chain_tail_generation(root) != generation
        or not isinstance(semantic_ledger, Mapping)
        or dict(semantic_ledger) != root_ledger
        or root_ledger != control_ledger
        or root_ledger_bytes != control_ledger_bytes
        or snapshot.get("snapshot_sha256")
        != chain_tail_digest(snapshot, "snapshot_sha256")
        or root_ledger.get("ledger_sha256")
        != chain_tail_digest(root_ledger, "ledger_sha256")
        or root_ledger.get("ledger_sha256")
        != semantic_ledger.get("ledger_sha256")
        or receipt.get("ledger_sha256")
        != root_ledger.get("ledger_sha256")
        or receipt.get("authority_digest")
        != chain_tail_digest(receipt, "authority_digest")
        or receipt_bytes
        != (
            json.dumps(receipt, indent=2, sort_keys=True) + "\n"
        ).encode("utf-8")
        or candidates.get("ledger_sha256")
        != root_ledger.get("ledger_sha256")
        or candidates.get("candidate_digest")
        != chain_tail_digest(candidates, "candidate_digest")
    ):
        raise ValueError(
            "current final publication semantic authority is invalid"
        )

    for name in (
        LEDGER_NAME,
        RECEIPT_NAME,
        COMPOSITION_CANDIDATES_NAME,
        PROJECTION_NAME,
    ):
        if (
            (root / name).read_bytes()
            != (root / CONTROL_DIR / name).read_bytes()
        ):
            raise ValueError(
                "current final publication root/control parity is invalid"
            )

    if marker_temp_path.exists() or marker_temp_path.is_symlink():
        raise ValueError(
            "current final publication retains a temporary marker"
        )
    marker_present = bool(
        marker_path.exists() or marker_path.is_symlink()
    )
    if marker_present:
        marker_stat = marker_path.lstat()
        if (
            not stat.S_ISREG(marker_stat.st_mode)
            or int(marker_stat.st_nlink) != 1
        ):
            raise ValueError(
                "current final publication marker is not an exact file"
            )
        marker_bytes = marker_path.read_bytes()
        marker = read_chain_tail_json(marker_path)
        if (
            set(marker)
            != {
                "schema_version",
                "authority",
                "state",
                "snapshot_sha256",
                "producer_key",
                "producer_contract_digest",
                "marker_sha256",
            }
            or marker.get("schema_version")
            != "plamen.chain_tail.final_publication.v1"
            or marker.get("authority") != "CONTROL_ONLY"
            or marker.get("state") != "ARMED"
            or marker.get("snapshot_sha256")
            != str(snapshot.get("snapshot_sha256") or "")
            or marker.get("producer_key") != expected_key
            or marker.get("producer_contract_digest") != contract.digest
            or marker.get("marker_sha256")
            != chain_tail_digest(marker, "marker_sha256")
            or marker_bytes
            != (
                json.dumps(marker, indent=2, sort_keys=True) + "\n"
            ).encode("utf-8")
        ):
            raise ValueError(
                "current final publication marker authority is invalid"
            )
    elif not _terminal_publication_is_complete(root):
        raise ValueError(
            "current final publication is not completely materialized"
        )

    return {
        "receipt": dict(receipt),
        "publication_armed": marker_present,
        "snapshot_sha256": str(snapshot.get("snapshot_sha256") or ""),
        "producer_key": expected_key,
        "producer_contract_digest": contract.digest,
    }


def _run_chain_tail_final_reconcile_transaction(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> tuple[dict[str, Any], list[str]]:
    """Pre-arm once, publish once, then commit the exact terminal shard set."""

    from chain_tail_authority import (
        align_terminal_control_generation,
        begin_isolated_chain_tail_scheduler,
        commit_final_chain_tail_publication,
        finalize_chain_tail_aggregate_output,
        prepare_final_chain_tail_publication,
    )

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        issue = "chain-tail final reconcile requires an active driver run_id"
        return {"status": "DEGRADED_UNRESOLVED", "issues": [issue]}, [issue]
    replay_issue = (
        "chain-tail final publication current-generation replay "
        "authority invalid"
    )
    try:
        replay = _read_exact_current_chain_tail_final_replay(
            root,
            project_root,
            config=config,
            phase=phase,
            run_id=run_id,
        )
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ):
        return (
            {"status": "DEGRADED_UNRESOLVED", "issues": [replay_issue]},
            [replay_issue],
        )
    if replay is not None:
        if replay["publication_armed"]:
            try:
                commit_final_chain_tail_publication(
                    root,
                    snapshot_sha256=replay["snapshot_sha256"],
                    producer_key=replay["producer_key"],
                    producer_contract_digest=(
                        replay["producer_contract_digest"]
                    ),
                )
            except (
                OSError,
                TypeError,
                ValueError,
                json.JSONDecodeError,
            ):
                return (
                    {
                        "status": "DEGRADED_UNRESOLVED",
                        "issues": [replay_issue],
                    },
                    [replay_issue],
                )
        return dict(replay["receipt"]), []
    try:
        begin_isolated_chain_tail_scheduler(root)
        readiness = _chain_tail_final_reconcile_readiness_issues(
            root,
            expected_run_id=run_id,
        )
        if readiness:
            return (
                {"status": "DEGRADED_UNRESOLVED"},
                list(readiness),
            )
        _snapshot, snapshot_issues = _run_chain_tail_snapshot_transaction(
            root, config, phase
        )
        if snapshot_issues:
            return ({"status": "DEGRADED_UNRESOLVED"}, snapshot_issues)
        contract, launch = _chain_tail_final_contract_and_launch(
            scratchpad=root,
            config=config,
            phase=phase,
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if arm_issues:
            return ({"status": "DEGRADED_UNRESOLVED"}, arm_issues)
        if execute:
            prepare_final_chain_tail_publication(
                root,
                snapshot_sha256=str(_snapshot.get("snapshot_sha256") or ""),
                producer_key=contract.key,
                producer_contract_digest=contract.digest,
            )
        receipt = (
            finalize_chain_tail_aggregate_output(
                root,
                terminal_snapshot_name="chain_tail_terminal_snapshot.json",
            )
            if execute
            else json.loads(
                (root / "chain_tail_coverage_receipt.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
        )
        if execute:
            align_terminal_control_generation(
                root,
                terminal_snapshot_name=(
                    "chain_tail_terminal_snapshot.json"
                ),
            )
        commit_issues = (
            _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
            if execute
            else []
        )
        # Publication is a second durable commit boundary.  If the first
        # attempt committed PhaseIO outputs and then crashed while consuming
        # the arm marker, an exact replay returns execute=False.  The marker
        # itself is therefore the recovery authority: consume it after a
        # successful idempotent PhaseIO commit without rewriting root outputs.
        publication_armed = (
            root / "_chain_tail_control" / "final_publication.armed"
        ).is_file()
        if publication_armed and not commit_issues:
            commit_final_chain_tail_publication(
                root,
                snapshot_sha256=str(_snapshot.get("snapshot_sha256") or ""),
                producer_key=contract.key,
                producer_contract_digest=contract.digest,
            )
        return dict(receipt), list(dict.fromkeys(commit_issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return (
            {"status": "DEGRADED_UNRESOLVED"},
            [
                "chain-tail final reconcile transaction failed: "
                f"{type(exc).__name__}: {exc}"
            ],
        )


def _record_chain_tail_authority_phase_io(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> list[str]:
    """Commit-only compatibility hook; it never initializes live authority."""
    try:
        if not (
            Path(scratchpad)
            / "_chain_tail_control"
            / "scheduler_journal.json"
        ).is_file():
            if not bool(config.get("_allow_legacy_chain_tail_adapter")):
                return [
                    "chain-tail legacy PhaseIO adapter lacks explicit eligibility"
                ]
            _receipt, compatibility_issues = (
                _run_chain_tail_final_reconcile_transaction(
                    Path(scratchpad), config, phase
                )
            )
            return compatibility_issues
        contract, launch = _chain_tail_final_contract_and_launch(
            scratchpad=Path(scratchpad),
            config=config,
            phase=phase,
        )
        run_id = str(config.get("_run_id") or "").strip()
        if not run_id:
            return [
                "chain-tail authority PhaseIO requires an active driver run_id"
            ]
        project_root = Path(config.get("project_root") or Path(scratchpad).parent)
        issues = validate_work_unit_inputs(
            scratchpad, project_root, contract, launch, run_id=run_id
        )
        if issues:
            return list(dict.fromkeys(issues))
        record_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        issues.extend(validate_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
        return issues
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            "chain-tail authority PhaseIO failure: "
            f"{type(exc).__name__}: {exc}"
        ]


def _strict_claude_exec_mode(
    config: Mapping[str, Any],
    *,
    raw_backend: str,
) -> tuple[str, str]:
    """Resolve Claude transport without silently changing explicit intent.

    A literal config field has authority over the compatibility environment.
    Fresh configs with neither derive headless; startup separately refuses to
    reinterpret an existing legacy checkpoint.  The backend alias is an
    explicit headless request and therefore rejects a conflicting field.
    """

    backend = str(raw_backend).strip().lower()
    if backend not in {"claude", "claude-headless", "codex"}:
        raise ValueError(
            f"unsupported cli_backend identity {backend!r}; expected "
            "'claude', 'claude-headless', or 'codex'"
        )
    if "claude_exec_mode" in config:
        raw_mode = config.get("claude_exec_mode")
        source = "config"
    elif "PLAMEN_CLAUDE_EXEC_MODE" in os.environ:
        raw_mode = os.environ.get("PLAMEN_CLAUDE_EXEC_MODE")
        source = "environment"
    elif backend == "claude-headless":
        raw_mode = "headless"
        source = "backend-alias"
    else:
        raw_mode = "headless"
        source = "fresh-default"
    mode = str(raw_mode).strip().lower() if raw_mode is not None else ""
    if mode not in {"pty", "headless"}:
        raise ValueError(
            f"invalid claude_exec_mode={raw_mode!r} from {source}; expected "
            "'pty' or 'headless'"
        )
    if backend == "claude-headless" and mode != "headless":
        raise ValueError(
            "cli_backend='claude-headless' conflicts with "
            f"claude_exec_mode={mode!r} from {source}"
        )
    return ("headless" if backend == "claude-headless" else mode), source


def _pre_admission_scratchpad_path(
    config: Mapping[str, Any], config_path: Path
) -> Path:
    """Resolve the scratch destination read-only before startup mutations."""

    raw = config.get("scratchpad")
    if not isinstance(raw, str) or not raw:
        raise ValueError("scratchpad must be a nonempty path")
    path = Path(raw)
    if path.is_absolute():
        return path.resolve(strict=False)
    cwd_candidate = (Path.cwd() / path).resolve(strict=False)
    config_candidate = (
        Path(config_path).resolve(strict=False).parent / path
    ).resolve(strict=False)
    if not cwd_candidate.exists() and config_candidate.exists():
        return config_candidate
    return cwd_candidate


def _admit_driver_transport_cutover(
    config: dict[str, Any], *, config_path: Path
) -> None:
    """Admit only the current SC Thorough headless Claude transport.

    This executes before projection/provider discovery or filesystem mutation.
    A missing mode is a headless default only for a genuinely fresh destination;
    an existing checkpoint is preserved and stopped rather than silently
    changing its historical PTY transport.
    """

    if not _configured_audit_uses_claude(config):
        return
    pipeline = str(config.get("pipeline") or "").strip().lower()
    mode = str(config.get("mode") or "").strip().lower()
    if (pipeline, mode) != ("sc", "thorough"):
        raise ValueError(
            "Claude transport is currently supported only for SC Thorough"
        )
    resolved, source = _strict_claude_exec_mode(
        config,
        raw_backend=str(config.get("cli_backend") or "claude"),
    )
    if resolved != "headless":
        raise ValueError(
            f"Claude PTY transport from {source} is no longer supported"
        )
    if source == "fresh-default":
        checkpoint = (
            _pre_admission_scratchpad_path(config, config_path)
            / "_v2_checkpoint.json"
        )
        if checkpoint.exists():
            raise ValueError(
                "existing legacy checkpoint has no claude_exec_mode; its "
                "evidence was preserved and cannot be reinterpreted as headless"
            )
        # Process-local derivation only. The user's config file is not rewritten.
        config["claude_exec_mode"] = "headless"


def _live_phase_runtime_launch_policy(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> dict[str, Any]:
    """Resolve the model launch fields used by both run_phase and PhaseIO."""

    root = Path(scratchpad)
    hyp_count = 0
    if phase.name in (*L1_VERIFY_PHASE_NAMES, *SC_VERIFY_PHASE_NAMES):
        try:
            shards = (
                compute_sc_verify_shards(root)
                if phase.name in SC_VERIFY_PHASE_NAMES
                else compute_verify_shards(root)
            )
            hyp_count = len(shards.get(phase.name, []))
        except Exception:
            pass
    if phase.name in ("verify_aggregate", "sc_verify_aggregate"):
        try:
            shards = (
                compute_sc_verify_shards(root)
                if phase.name == "sc_verify_aggregate"
                else compute_verify_shards(root)
            )
            hyp_count = sum(len(values) for values in shards.values())
        except Exception:
            pass
    if phase.name in {
        "chain", "chain_agent2", "crossbatch", "report_index",
        "sc_semantic_dedup",
    } and hyp_count == 0:
        try:
            hyp_count = len(
                _report_candidate_rows(root)
                if phase.name == "report_index"
                else parse_verification_queue_rows(root)
            )
        except Exception:
            pass
        if hyp_count == 0:
            try:
                inventory = root / "findings_inventory.md"
                if inventory.is_file():
                    hyp_count = inventory.read_text(
                        encoding="utf-8", errors="replace"
                    ).count("\n| H-")
            except Exception:
                pass

    raw_backend = str(
        _effective_backend(config, phase)
        if phase.name == "skeptic"
        else config.get("cli_backend", "claude")
    ).strip().lower()
    claude_exec_mode, exec_mode_source = _strict_claude_exec_mode(
        config,
        raw_backend=raw_backend,
    )
    backend = "claude" if raw_backend == "claude-headless" else raw_backend
    warnings: list[str] = []
    exec_mode = (
        "codex" if backend == "codex" else
        "headless" if claude_exec_mode == "headless"
        else "pty"
    )
    timeout = scale_timeout(
        phase.base_timeout_s,
        str(config["project_root"]),
        str(config["language"]),
        mode=config.get("mode"),
        hypothesis_count=hyp_count,
        backend=backend,
    )
    return {
        "backend": backend,
        "model": phase_model(phase, str(config.get("mode") or "core"), config),
        "timeout_s": max(1, int(timeout)),
        "exec_mode": exec_mode,
        "claude_exec_mode": claude_exec_mode,
        "explicit_claude_exec_mode": (
            claude_exec_mode if exec_mode_source != "fresh-default" else None
        ),
        "claude_exec_mode_source": exec_mode_source,
        "hypothesis_count": hyp_count,
        "warnings": warnings,
    }


_R10_REPORT_PREWORK_ROSTER = (
    "external_assumption_undemotion_compute.json",
    "external_assumption_undemotions.json",
    "external_assumption_undemotions.md",
    "external_assumption_undemotion_debt.json",
)


def _report_index_prework_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the deterministic report-index prework boundary."""

    dimensions = {
        "pipeline": str(config.get("pipeline") or "sc"),
        "mode": str(config.get("mode") or "core"),
        "ecosystem": str(config.get("language") or "unknown"),
        "backend": str(config.get("cli_backend") or "claude"),
    }
    bb_inputs: tuple[str, ...] = ()
    if bool(config.get("_bb_policy_report_projection_ready")):
        bb_inputs = (BB_POLICY_REPORT_RECONCILIATION_PATH,)
    r10_inputs: tuple[str, ...] = ()
    if dimensions["pipeline"].strip().lower() == "sc":
        r10_inputs = _r10_report_prework_input_paths(
            Path(scratchpad),
            expected_run_id=str(config.get("_run_id") or ""),
            expected_mode=dimensions["mode"],
        )
    contract = resolve_phase_io_contract(
        **dimensions,
        phase="report_index",
        work_unit_id="prework",
        exact_inputs=tuple(dict.fromkeys((
            "verification_queue.md",
            "finding_mapping.md",
            "dedup_decisions.md",
            *bb_inputs,
            *r10_inputs,
            *_report_candidate_input_paths(
                Path(scratchpad),
                run_id=str(config.get("_run_id") or "") or None,
            ),
        ))),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        **dimensions,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _r10_report_prework_authority_issues(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    contract: PhaseIOContract | None = None,
    launch: LaunchSpec | None = None,
    _validation_context: _ArtifactValidationContext | None = None,
    _resolver_paths_validated: bool = False,
) -> list[str]:
    """Replay the R10 producer and the report unit's exact consumption bind."""

    if str(config.get("pipeline") or "sc").strip().lower() != "sc":
        return []
    root = Path(scratchpad)
    project = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["R10 report-prework consumer run_id is absent"]
    if _validation_context is None:
        try:
            validation_context = _ArtifactValidationContext(root, project)
        except ArtifactLedgerError as exc:
            return [f"R10 report-prework validation context is invalid: {exc}"]
        issues = _r10_report_prework_authority_issues(
            root,
            config,
            contract=contract,
            launch=launch,
            _validation_context=validation_context,
            _resolver_paths_validated=_resolver_paths_validated,
        )
        issues.extend(validation_context.finish())
        return list(dict.fromkeys(issues))
    try:
        if contract is None or launch is None:
            contract, launch = _report_index_prework_contract_and_launch(
                root, config
            )
        contract_r10 = {
            identity.split(":", 1)[1]
            for identity in contract.immutable_inputs
            if identity.split(":", 1)[1] in _R10_REPORT_PREWORK_ROSTER
        }
        # Contract resolution already performs the full current-source R10
        # replay.  Consumers that pass that exact freshly resolved contract may
        # reuse its conditional roster inside this validation epoch; repeating
        # the complete queue/publication/provenance traversal here adds no
        # independent evidence.  Callers without that resolver witness retain
        # the ordinary full replay.
        expected_paths = (
            set(contract_r10)
            if _resolver_paths_validated
            else set(_r10_report_prework_input_paths(
                root,
                expected_run_id=run_id,
                expected_mode=str(config.get("mode") or "core"),
            ))
        )
        issues = []
        if contract_r10 != expected_paths:
            issues.append(
                "R10 report-prework contract input denominator differs from "
                "the committed conditional universe"
            )
        issues.extend(validate_work_unit_inputs(
            root,
            project,
            contract,
            launch,
            run_id=run_id,
            _validation_context=_validation_context,
        ))
        issues.extend(validate_work_unit_explicit_absence_bindings(
            root,
            project,
            contract,
            launch,
            run_id=run_id,
            require=True,
            _validation_context=_validation_context,
        ))
        ledger = _validation_context.ledger
        unit = ledger.get("work_units", {}).get(contract.key)
        inputs = (
            unit.get("input_bindings")
            if isinstance(unit, Mapping)
            else None
        )
        if not isinstance(inputs, Mapping):
            issues.append("R10 report-prework input bindings are absent")
            inputs = {}
        producer_keys: set[str] = set()
        for relative in sorted(expected_paths):
            identity = f"scratchpad:{relative}"
            record = inputs.get(identity)
            if not isinstance(record, Mapping):
                issues.append(f"{identity}: R10 report input binding is absent")
                continue
            issues.extend(semantic_input_producer_authority_issues(
                ledger, record, run_id=run_id
            ))
            producer_key = str(record.get("producer_work_unit_key") or "")
            if producer_key:
                producer_keys.add(producer_key)
        if len(producer_keys) != 1 or not next(
            iter(producer_keys), ""
        ).endswith("/external_assumption_undemotion_reconcile"):
            issues.append(
                "R10 report inputs do not share one current committed producer"
            )
        receipt = (
            unit.get("explicit_absence_authority")
            if isinstance(unit, Mapping)
            else None
        )
        expected_roster = sorted(
            f"scratchpad:{name}" for name in _R10_REPORT_PREWORK_ROSTER
        )
        if (
            not isinstance(receipt, Mapping)
            or receipt.get("roster_identities") != expected_roster
        ):
            issues.append("R10 conditional absence roster is incomplete")
        return list(dict.fromkeys(issues))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "R10 report-prework authority is unavailable: "
            f"{type(exc).__name__}: {exc}"
        ]


def _prepare_bb_policy_report_consumer(
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Validate the bounded BB report view before report PhaseIO can bind it."""

    config.pop("_bb_policy_report_projection_ready", None)
    config.pop("_bb_policy_report_projection_sha256", None)
    if not bb_policy_configured(config):
        return []
    root = Path(scratchpad)
    terminal_path = root / BB_POLICY_TERMINAL_RECONCILIATION_PATH
    projection_path = root / BB_POLICY_REPORT_RECONCILIATION_PATH
    try:
        if (
            terminal_path.is_symlink()
            or projection_path.is_symlink()
            or not terminal_path.is_file()
            or not projection_path.is_file()
        ):
            raise BBVerificationPolicyError(
                "bounded BB report reconciliation artifacts are unavailable"
            )
        terminal_raw = json.loads(
            terminal_path.read_text(encoding="utf-8", errors="strict")
        )
        if not isinstance(terminal_raw, Mapping):
            raise BBVerificationPolicyError(
                "BB terminal reconciliation is not one object"
            )
        expected_ingress = build_bb_policy_ingress_payload(
            config,
            driver_run_id=str(config.get("_run_id") or ""),
        )
        if expected_ingress is None:
            raise BBVerificationPolicyError(
                "configured BB report consumer has no ingress"
            )
        terminal = validate_bb_policy_terminal_reconciliation(
            terminal_raw,
            expected_ingress_sha256=expected_ingress["ingress_sha256"],
            expected_driver_run_id=expected_ingress["driver_run_id"],
            expected_candidate_denominator_sha256=str(
                terminal_raw.get("candidate_denominator_sha256") or ""
            ),
        )
        expected = (
            build_bb_policy_downstream_reconciliation_projection(
                terminal,
                consumer_kind="REPORT",
            )
        )
        observed_raw = json.loads(
            projection_path.read_text(encoding="utf-8", errors="strict")
        )
        observed = validate_bb_policy_downstream_reconciliation_projection(
            observed_raw,
            expected_consumer_kind="REPORT",
            expected_reconciliation_sha256=terminal[
                "reconciliation_sha256"
            ],
        )
        if observed != expected:
            raise BBVerificationPolicyError(
                "BB report reconciliation differs from the terminal view"
            )
        config["_bb_policy_report_projection_ready"] = True
        config["_bb_policy_report_projection_sha256"] = observed[
            "projection_sha256"
        ]
        return []
    except (
        BBVerificationPolicyError,
        OSError,
        UnicodeError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "bounded BB report reconciliation is unavailable or invalid: "
            f"{type(exc).__name__}: {exc}"
        ]


def _bb_policy_report_prompt_suffix(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> str:
    """Render only a local bounded-view pointer, never private policy prose."""

    if not bool(config.get("_bb_policy_report_projection_ready")):
        return ""
    digest = str(
        config.get("_bb_policy_report_projection_sha256") or ""
    ).strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise BBVerificationPolicyError(
            "BB report projection prompt digest is invalid"
        )
    projection_path = (
        Path(scratchpad) / BB_POLICY_REPORT_RECONCILIATION_PATH
    )
    return (
        "\n\n## Bound bug-bounty policy reconciliation (evidence only)\n\n"
        f"Read `{projection_path.as_posix()}`. Its exact projection "
        f"digest is `{digest}`. It contains only candidate reconciliation "
        "states and local evidence references, never normative program-policy "
        "text. Keep every `RETAIN_REQUEUE_REVIEW` candidate visible in the "
        "report and flag its unresolved policy application for human review. "
        "A `RECONCILED` state proves only delivery/application parity; it does "
        "not prove safety, change scope or severity, authorize a dismissal, "
        "or substitute for executed PoC evidence.\n"
    )


def _arm_report_index_prework_artifacts(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[bool, list[str]]:
    """Bind report prework sources before any report projection is written."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return False, ["report-index prework PhaseIO run_id is absent"]
    try:
        contract, launch = _report_index_prework_contract_and_launch(
            root, config
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=Path(str(config.get("project_root") or root.parent)),
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return execute, issues
        if str(config.get("pipeline") or "sc").strip().lower() == "sc":
            project = Path(str(config.get("project_root") or root.parent))
            record_work_unit_explicit_absence_bindings(
                root,
                project,
                contract,
                launch,
                run_id=run_id,
                presence_roster=_R10_REPORT_PREWORK_ROSTER,
            )
            issues.extend(_r10_report_prework_authority_issues(
                root,
                config,
                contract=contract,
                launch=launch,
                _resolver_paths_validated=True,
            ))
        return execute, list(dict.fromkeys(issues))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return False, [
            "report-index prework PhaseIO prebind failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _record_report_index_prework_artifacts(
    scratchpad: Path,
    config: dict[str, Any],
    *,
    severity_denominator: int,
    status_denominator: int,
    external_gap_denominator: int,
) -> list[str]:
    """Commit deterministic report inputs against their pre-execution bind."""

    scratchpad = Path(scratchpad)
    try:
        contract, launch = _report_index_prework_contract_and_launch(
            scratchpad, config
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "report-index prework PhaseIO resolution failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    r10_issues = _r10_report_prework_authority_issues(
        scratchpad,
        config,
        contract=contract,
        launch=launch,
        _resolver_paths_validated=True,
    )
    if r10_issues:
        return r10_issues
    denominators = {
        "severity_rows_present": max(0, int(severity_denominator)),
        "status_rows_present": max(0, int(status_denominator)),
        "external_research_gaps_present": max(0, int(external_gap_denominator)),
    }
    receipts: dict[str, ConditionalOutputReceipt] = {}
    for spec in contract.outputs:
        if spec.artifact_class != "CONDITIONAL":
            continue
        denominator = denominators.get(spec.condition_id, 0)
        present = (scratchpad / spec.path).is_file()
        if denominator > 0 and present:
            receipts[spec.identity] = ConditionalOutputReceipt(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity=spec.identity,
                condition_id=spec.condition_id,
                state="PRODUCED",
                expected_denominator=denominator,
                produced_identities=(spec.identity,),
            )
        elif denominator == 0 and not present:
            receipts[spec.identity] = ConditionalOutputReceipt(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity=spec.identity,
                condition_id=spec.condition_id,
                state="NOT_TRIGGERED",
                expected_denominator=0,
            )
        else:
            receipts[spec.identity] = ConditionalOutputReceipt(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity=spec.identity,
                condition_id=spec.condition_id,
                state="FAILED",
                expected_denominator=denominator,
                failure_ids=(
                    "expected_output_missing" if denominator else
                    "stale_output_without_trigger",
                ),
            )
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["report-index prework PhaseIO run_id is absent"]
    project_root = Path(config.get("project_root") or scratchpad.parent)
    return _commit_deterministic_driver_work_unit(
        scratchpad=scratchpad,
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
        conditional_receipts=receipts,
    )


_R10_REPORT_CONSUMER_READY_KEY = "_r10_report_consumer_ready"


def _clear_r10_report_consumer_ready(config: Mapping[str, Any]) -> None:
    """Clear the ephemeral report-consumer claim without touching evidence."""

    if isinstance(config, dict):
        config.pop(_R10_REPORT_CONSUMER_READY_KEY, None)


def _report_index_prework_committed_authority_issues(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    contract: PhaseIOContract | None = None,
    launch: LaunchSpec | None = None,
    _validation_context: _ArtifactValidationContext | None = None,
    _authority_out: dict[str, Any] | None = None,
) -> list[str]:
    """Replay the exact committed prework producer and its live R10 inputs."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["report-index prework consumer run_id is absent"]
    project = Path(str(config.get("project_root") or root.parent))
    if _validation_context is None:
        try:
            validation_context = _ArtifactValidationContext(root, project)
        except ArtifactLedgerError as exc:
            return [
                "report-index committed prework validation context is invalid: "
                f"{exc}"
            ]
        issues = _report_index_prework_committed_authority_issues(
            root,
            config,
            contract=contract,
            launch=launch,
            _validation_context=validation_context,
            _authority_out=_authority_out,
        )
        issues.extend(validation_context.finish())
        return list(dict.fromkeys(issues))
    try:
        if contract is None or launch is None:
            contract, launch = _report_index_prework_contract_and_launch(
                root, config
            )
        ledger = _validation_context.ledger
        unit = ledger.get("work_units", {}).get(contract.key)
        issues = _r10_report_prework_authority_issues(
            root,
            config,
            contract=contract,
            launch=launch,
            _validation_context=_validation_context,
            _resolver_paths_validated=True,
        )
        is_sc = (
            str(config.get("pipeline") or "sc").strip().lower() == "sc"
        )
        if (
            not isinstance(unit, Mapping)
            or unit.get("semantic_status") != "ACTIVE"
            or unit.get("execution_state") != "OUTPUT_COMMITTED"
            or unit.get("run_id") != run_id
            or unit.get("contract_digest") != contract.digest
            or unit.get("launch_digest") != launch.digest
        ):
            issues.append(
                "report-index prework is not one exact current committed producer"
            )
        # The SC R10 replay above already validates the complete immutable
        # input denominator and its explicit-absence receipt in this exact
        # shared snapshot.  Do not repeat that expensive semantic replay two
        # more times while validating outputs.  L1 has no R10 producer and
        # therefore retains the ordinary artifact validator's live-input pass.
        if not is_sc:
            issues.extend(validate_work_unit_explicit_absence_bindings(
                root,
                project,
                contract,
                launch,
                run_id=run_id,
                require=False,
                _validation_context=_validation_context,
            ))
        issues.extend(validate_work_unit_artifacts(
            root,
            project,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
            require_live_input_authority=not is_sc,
            _validation_context=_validation_context,
        ))
        if _authority_out is not None:
            _authority_out["contract"] = contract
            _authority_out["launch"] = launch
        return list(dict.fromkeys(issues))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "report-index committed prework authority is unavailable: "
            f"{type(exc).__name__}: {exc}"
        ]


def _establish_r10_report_consumer_ready(
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Record readiness only after a complete committed-producer replay."""

    _clear_r10_report_consumer_ready(config)
    authority: dict[str, Any] = {}
    issues = _report_index_prework_committed_authority_issues(
        scratchpad,
        config,
        _authority_out=authority,
    )
    if issues:
        return issues
    contract = authority.get("contract")
    launch = authority.get("launch")
    if not isinstance(contract, PhaseIOContract) or not isinstance(
        launch, LaunchSpec
    ):
        return [
            "report-index consumer-ready state cannot retain its validated "
            "producer authority"
        ]
    config[_R10_REPORT_CONSUMER_READY_KEY] = {
        "run_id": str(config.get("_run_id") or ""),
        "mode": str(config.get("mode") or "core").strip().lower(),
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "launch_digest": launch.digest,
    }
    return []


def _r10_report_consumer_ready_issues(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Revalidate report authority at every later semantic consumer boundary."""

    # R10 is an SC-only reconciliation.  L1 report prework has its own exact
    # PhaseIO transaction, but it must not be made dependent on an inapplicable
    # SC producer or its ephemeral readiness claim.
    if str(config.get("pipeline") or "sc").strip().lower() != "sc":
        return []
    state = config.get(_R10_REPORT_CONSUMER_READY_KEY)
    if not isinstance(state, Mapping):
        return ["R10 report consumer-ready state is absent"]
    try:
        contract, launch = _report_index_prework_contract_and_launch(
            Path(scratchpad), config
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "R10 report consumer-ready context is unavailable: "
            f"{type(exc).__name__}: {exc}"
        ]
    expected = {
        "run_id": str(config.get("_run_id") or ""),
        "mode": str(config.get("mode") or "core").strip().lower(),
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "launch_digest": launch.digest,
    }
    issues: list[str] = []
    if dict(state) != expected:
        issues.append("R10 report consumer-ready context changed after commit")
    issues.extend(_report_index_prework_committed_authority_issues(
        scratchpad,
        config,
        contract=contract,
        launch=launch,
    ))
    if issues:
        _clear_r10_report_consumer_ready(config)
    return list(dict.fromkeys(issues))


def _write_report_index_binding_tables(
    scratchpad: Path,
    *,
    expected_run_id: str,
    expected_mode: str,
) -> tuple[int, int]:
    """Materialize the two bounded report tables under explicit R10 context."""

    root = Path(scratchpad)
    severities = _expected_report_index_severities(
        root,
        expected_run_id=expected_run_id,
        expected_mode=expected_mode,
    )
    if severities:
        lines = [
            "# Severity Binding Table",
            "",
            "Driver-computed expected severities from verify files and "
            "verification queue. The Index Agent MUST use these severities "
            "unless a Trust Adj. reason is documented.",
            "",
            "| Finding ID | Expected Severity |",
            "|------------|-------------------|",
            *(
                f"| {fid} | {severities[fid]} |"
                for fid in sorted(severities, key=lambda value: value.upper())
            ),
        ]
        (root / "severity_binding.md").write_text(
            "\n".join(lines) + "\n", encoding="utf-8"
        )

    statuses = _expected_report_index_statuses(root)
    if statuses:
        lines = [
            "# Verification Status Binding Table",
            "",
            "Driver-computed canonical verification-status token per finding, "
            "from (verifier verdict, best evidence tag). The Index Agent MUST "
            "use these tokens for BOTH the report_index Verification column "
            "AND the body `### [X-NN] Title [STATUS]` header tag.",
            "",
            "- VERIFIED  = verdict CONFIRMED + proof-grade evidence "
            "([POC-PASS]/[MEDUSA-PASS]/[PROD-*])",
            "- CONFIRMED = verdict CONFIRMED but only [CODE-TRACE]",
            "- CONTESTED = disputed (CONTESTED/UNRESOLVED/PARTIAL)",
            "- UNVERIFIED = refuted / none",
            "",
            "| Finding ID | Verification Status |",
            "|------------|---------------------|",
            *(
                f"| {fid} | {statuses[fid]} |"
                for fid in sorted(statuses, key=lambda value: value.upper())
            ),
        ]
        (root / "status_binding.md").write_text(
            "\n".join(lines) + "\n", encoding="utf-8"
        )
    return len(severities), len(statuses)


def _run_report_index_prework_transaction(
    scratchpad: Path,
    config: dict[str, Any],
) -> tuple[bool, list[str]]:
    """Arm, materialize, commit, and replay report prework as one boundary."""

    root = Path(scratchpad)
    _clear_r10_report_consumer_ready(config)
    execute, issues = _arm_report_index_prework_artifacts(root, config)
    if issues:
        return False, list(dict.fromkeys(issues))
    if not execute:
        replay = _establish_r10_report_consumer_ready(root, config)
        return not replay, replay

    run_id = str(config.get("_run_id") or "").strip()
    mode = str(config.get("mode") or "core").strip().lower()
    try:
        severity_count, status_count = _write_report_index_binding_tables(
            root,
            expected_run_id=run_id,
            expected_mode=mode,
        )
        seed_rows = _write_report_index_coverage_seed(
            root,
            expected_run_id=run_id,
            expected_mode=mode,
        )
        facet_count = _write_candidate_semantic_facets(root)
        external_gap_count = _check_external_research_citation_gaps(root)
        log.info(
            "[report_index] prework materialized severity=%d status=%d "
            "coverage=%d facets=%d external-gaps=%d",
            severity_count,
            status_count,
            seed_rows,
            facet_count,
            external_gap_count,
        )
    except Exception as exc:
        return False, [
            "report-index prework materialization failed before commit: "
            f"{type(exc).__name__}: {exc}"
        ]

    commit_issues = _record_report_index_prework_artifacts(
        root,
        config,
        severity_denominator=severity_count,
        status_denominator=status_count,
        external_gap_denominator=external_gap_count,
    )
    if commit_issues:
        return False, list(dict.fromkeys(commit_issues))
    replay_issues = _establish_r10_report_consumer_ready(root, config)
    return not replay_issues, replay_issues


def _p1dm_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    phase_name: str,
    work_unit_id: str,
    phase: Phase | None = None,
    exact_inputs: Sequence[str] = (),
    exact_outputs: Sequence[str] = (),
    actor: str,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve one fixed P1-D/P1-M work unit and its live launch authority."""
    actor_n = str(actor or "").strip().upper()
    if actor_n not in {"MODEL", "DRIVER"}:
        raise ValueError("P1-D/P1-M actor must be MODEL or DRIVER")
    runtime: Mapping[str, Any] = {}
    if actor_n == "MODEL":
        if phase is None:
            raise ValueError("MODEL P1-D/P1-M work requires a runtime phase")
        runtime = _live_phase_runtime_launch_policy(
            phase, Path(scratchpad), dict(config)
        )
    backend = str(
        runtime.get("backend")
        if runtime
        else config.get("cli_backend") or "claude"
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=backend,
        phase=phase_name,
        work_unit_id=work_unit_id,
        exact_inputs=tuple(str(value) for value in exact_inputs),
        exact_outputs=tuple(str(value) for value in exact_outputs),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model=(str(runtime["model"]) if runtime else "driver"),
        timeout_s=(int(runtime["timeout_s"]) if runtime else 120),
        # Auxiliary Claude leaves deliberately use the one-turn headless
        # transport below; record that exact executor rather than inheriting
        # the parent phase's PTY mode and creating false provenance. Codex
        # uses its native exec transport. Driver units remain Python.
        exec_mode=(
            "codex"
            if runtime and backend == "codex"
            else "headless"
            if runtime
            else "python"
        ),
        # DRIVER_PYTHON_NO_TOOLS contracts are closed deterministic Python
        # transactions. Model leaves retain their bounded filesystem policy.
        tool_policy=(("filesystem",) if runtime else ()),
    )
    return contract, launch


def _record_p1dm_driver_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    phase_name: str,
    work_unit_id: str,
    action: Callable[[], Any],
    validate: Callable[[], Sequence[str]],
    exact_inputs: Sequence[str] = (),
    exact_outputs: Sequence[str] = (),
) -> list[str]:
    """Execute and exact-bind one deterministic authority transaction.

    Input drift after a committed denominator is never silently rebound.  A
    first-run missing input remains visible INPUT_DEBT, but the haltless action
    still emits an explicit UNMEASURABLE/NOT_TRIGGERED authority when its
    domain library can do so without inventing evidence.
    """
    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return [f"{phase_name}/{work_unit_id} cannot bind without a run_id"]
    try:
        contract, launch = _p1dm_contract_and_launch(
            root,
            config,
            phase_name=phase_name,
            work_unit_id=work_unit_id,
            exact_inputs=exact_inputs,
            exact_outputs=exact_outputs,
            actor="DRIVER",
        )
        record_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        )
        issues = validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        )
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            f"{phase_name}/{work_unit_id} input transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    try:
        action()
        issues.extend(str(value) for value in validate())
        record_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
            precommit_issues=issues,
        )
        issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        issues.append(
            f"{phase_name}/{work_unit_id} output transaction failed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(issues))


def _validate_existing_p1dm_driver_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    phase_name: str,
    work_unit_id: str,
    validate: Callable[[], Sequence[str]],
    exact_inputs: Sequence[str] = (),
    exact_outputs: Sequence[str] = (),
) -> list[str]:
    """Validate an exact committed DRIVER transaction without recommitting it.

    A committed producer's receipt is part of every downstream frozen input
    binding.  Re-recording identical output bytes would create a new receipt
    ordinal and retroactively invalidate those consumers.  Resume therefore
    performs a read-only contract/input/output replay.
    """

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return [f"{phase_name}/{work_unit_id} cannot replay without a run_id"]
    try:
        contract, launch = _p1dm_contract_and_launch(
            root,
            config,
            phase_name=phase_name,
            work_unit_id=work_unit_id,
            exact_inputs=exact_inputs,
            exact_outputs=exact_outputs,
            actor="DRIVER",
        )
        issues = list(validate_work_unit_inputs(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
        ))
        issues.extend(str(value) for value in validate())
        issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            f"{phase_name}/{work_unit_id} committed replay failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    return list(dict.fromkeys(issues))


def _depth_handoff_input_roster(scratchpad: Path) -> tuple[str, ...]:
    """Return the manifest-exact evidence used by the SC depth handoff."""

    breadth_outputs = tuple(parse_breadth_manifest_outputs(scratchpad) or ())
    return tuple(dict.fromkeys((
        "_mechanical_graph.json",
        "findings_inventory.md",
        "contract_inventory.md",
        "attack_surface.md",
        "spawn_manifest.md",
        *breadth_outputs,
    )))


def _prepare_depth_handoff(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Create or replay the exact Inventory/graph-to-Depth handoff.

    Both Codex and Claude depth launchers call this shared boundary.  Existing
    unowned files are never overwritten: an upgraded/resumed run must either
    replay the committed deterministic transaction or start a distinct run.
    """

    if str(config.get("pipeline") or "sc").lower() != "sc":
        return []
    root = Path(scratchpad)
    breadth_outputs = tuple(parse_breadth_manifest_outputs(root) or ())
    if not breadth_outputs:
        return [
            "inventory/depth_handoff cannot derive a manifest-exact breadth "
            "denominator"
        ]
    transaction = {
        "phase_name": "inventory",
        "work_unit_id": "depth_handoff",
        "exact_inputs": _depth_handoff_input_roster(root),
        "exact_outputs": depth_handoff_authority.OUTPUTS,
    }
    validate = lambda: depth_handoff_authority.validate_depth_handoff(  # noqa: E731
        root, breadth_outputs
    )
    try:
        contract, _launch = _p1dm_contract_and_launch(
            root,
            config,
            actor="DRIVER",
            **transaction,
        )
        work_units = read_artifact_ledger(root).get("work_units")
        replay = isinstance(work_units, Mapping) and contract.key in work_units
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            "inventory/depth_handoff replay selection failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    if replay:
        return _validate_existing_p1dm_driver_transaction(
            root,
            config,
            validate=validate,
            **transaction,
        )
    collisions = [
        name for name in depth_handoff_authority.OUTPUTS
        if (root / name).exists()
    ]
    if collisions:
        return [
            "inventory/depth_handoff outputs exist without the registered "
            "transaction: " + ", ".join(collisions)
        ]
    return _record_p1dm_driver_transaction(
        root,
        config,
        action=lambda: depth_handoff_authority.write_depth_handoff(
            root, breadth_outputs
        ),
        validate=validate,
        **transaction,
    )


def _prepare_codex_dependency_fetch_receipt(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Fetch/hash every Codex R-EXT source under a distinct DRIVER unit."""

    root = Path(scratchpad)
    transaction = {
        "phase_name": "recon",
        "work_unit_id": "codex_dependency_fetch",
        "exact_inputs": ("recon_external_dependency_research.md",),
        "exact_outputs": (
            codex_dependency_research_authority.FETCH_RECEIPT_FILE,
        ),
    }
    report = root / "recon_external_dependency_research.md"
    receipt = root / codex_dependency_research_authority.FETCH_RECEIPT_FILE
    validate = lambda: (  # noqa: E731
        codex_dependency_research_authority.validate_fetch_receipt(
            report, receipt
        )
    )
    try:
        contract, _launch = _p1dm_contract_and_launch(
            root, config, actor="DRIVER", **transaction
        )
        work_units = read_artifact_ledger(root).get("work_units")
        replay = isinstance(work_units, Mapping) and contract.key in work_units
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            "recon/codex_dependency_fetch replay selection failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    if replay:
        return _validate_existing_p1dm_driver_transaction(
            root, config, validate=validate, **transaction
        )
    if receipt.exists():
        return [
            "Codex dependency fetch receipt exists without its registered "
            "transaction"
        ]
    return _record_p1dm_driver_transaction(
        root,
        config,
        action=lambda: (
            codex_dependency_research_authority.write_fetch_receipt(
                report, receipt
            )
        ),
        validate=validate,
        **transaction,
    )


_CHAIN_SUMMARY_SOURCE_GLOBS = (
    "depth_*_findings.md",
    "blind_spot_*_findings.md",
    "scanner_*_findings.md",
    "validation_sweep_findings.md",
    "niche_*_findings.md",
    "design_stress_findings.md",
    "sibling_propagation_findings.md",
    "enumgap_exploration_findings.md",
)


def _chain_summary_source_roster(scratchpad: Path) -> tuple[str, ...]:
    """Return the exact source set consumed by summary compaction."""

    root = Path(scratchpad)
    return tuple(sorted({
        "_v2_checkpoint.json",
        *(
            path.relative_to(root).as_posix()
            for pattern in _CHAIN_SUMMARY_SOURCE_GLOBS
            for path in root.glob(pattern)
            if path.is_file() and not path.is_symlink()
        ),
    }))


def _validate_nonempty_regular_outputs(
    scratchpad: Path,
    names: Sequence[str],
) -> list[str]:
    issues: list[str] = []
    root = Path(scratchpad)
    for name in names:
        path = root / name
        try:
            if (
                not path.is_file()
                or path.is_symlink()
                or path.stat().st_size <= 0
            ):
                issues.append(f"{name}: required regular output is unavailable")
        except OSError as exc:
            issues.append(f"{name}: output inspection failed: {exc}")
    return issues


def _run_chain_summary_compaction_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Extract compact summaries under one exact DRIVER denominator."""

    root = Path(scratchpad)
    return _record_p1dm_driver_transaction(
        root,
        config,
        phase_name="chain",
        work_unit_id="summary_compaction",
        exact_inputs=_chain_summary_source_roster(root),
        exact_outputs=("chain_summaries_compact.md",),
        action=lambda: _extract_chain_summaries_compact(root),
        validate=lambda: _validate_nonempty_regular_outputs(
            root, ("chain_summaries_compact.md",)
        ),
    )


def _run_chain_scaffold_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[list[str], list[str]]:
    """Publish the recall-safe crash scaffold with explicit PhaseIO ownership."""

    root = Path(scratchpad)
    outputs = ("hypotheses.md", "finding_mapping.md", "enabler_results.md")
    written: list[str] = []

    def _write() -> None:
        written.extend(_write_chain_passthrough_outputs(
            root,
            "pre-run scaffold safety net; Chain Agent 1 may overwrite "
            "these artifacts with grouped hypotheses and enabler analysis",
        ))

    issues = _record_p1dm_driver_transaction(
        root,
        config,
        phase_name="chain",
        work_unit_id="scaffold",
        exact_inputs=("findings_inventory.md",),
        exact_outputs=outputs,
        action=_write,
        validate=lambda: _validate_nonempty_regular_outputs(root, outputs),
    )
    return written, issues


def _prepare_semantic_invariant_pre_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Materialize, derive, and exact-bind the P1-D PRE denominator."""
    root = Path(scratchpad)
    transaction = {
        "phase_name": "invariants",
        "work_unit_id": "semantic_invariants.pre",
        "exact_inputs": (),
        "exact_outputs": (),
    }
    def validate() -> Sequence[str]:
        return semantic_invariant_authority.validate_semantic_invariant_authority(
            root,
            ecosystem=str(config.get("language") or ""),
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
        )
    try:
        contract, _launch = _p1dm_contract_and_launch(
            root,
            config,
            actor="DRIVER",
            **transaction,
        )
        work_units = read_artifact_ledger(root).get("work_units")
        replay = isinstance(work_units, Mapping) and contract.key in work_units
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            "invariants/semantic_invariants.pre replay selection failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    if replay:
        return _validate_existing_p1dm_driver_transaction(
            root,
            config,
            validate=validate,
            **transaction,
        )
    semantic_invariant_authority.materialize_semantic_invariant_compatibility_inputs(
        root
    )
    return _record_p1dm_driver_transaction(
        root,
        config,
        action=lambda: semantic_invariant_authority.write_semantic_invariant_authority(
            root,
            ecosystem=str(config.get("language") or ""),
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
        ),
        validate=validate,
        **transaction,
    )


def _compile_semantic_invariant_model_prompt(
    prompt: str,
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> str:
    """Bind the invariant worker to its finite state denominator and trace."""
    contract, _launch = _p1dm_contract_and_launch(
        Path(scratchpad),
        config,
        phase_name="invariants",
        work_unit_id="worker.semantic_invariants",
        phase=phase,
        actor="MODEL",
    )
    trace_contract = f"""

# P1-D EXACT SEMANTIC-INVARIANT APPLICATION CONTRACT

The files `{semantic_invariant_authority.AUTHORITY_FILE}` and
`{semantic_invariant_authority.WORKLIST_FILE}` are the complete typed state
denominator for this pass. Enumerate every worklist row. Bare-name mentions in
prose are not application evidence. Preserve the normal human analysis in
`semantic_invariants.md`, and include exactly one JSON object between these
sentinels:

{semantic_invariant_authority.TRACE_BEGIN}
{{
  "schema_version": "{semantic_invariant_authority.APPLICATION_TRACE_SCHEMA}",
  "run_binding_digest": "<exact worklist run binding digest>",
  "authority_digest": "<exact worklist authority digest>",
  "worklist_digest": "<exact worklist digest>",
  "producer_operator_digest": "<64 lowercase hex digest of this operator/SOP>",
  "rows": [{{
    "state_id": "<exact STATE-* id>",
    "disposition": "DELIVERED|DEFERRED|UNMEASURABLE",
    "evidence_loci": ["path.ext:LNN"],
    "write_site_status": "COMPLETE|INCOMPLETE|BOUNDED|UNKNOWN",
    "semantic_status": "SEMANTICS_OK|SEMANTICS_SUSPECT|SEMANTICS_UNKNOWN|NOT_APPLICABLE",
    "result": "<bounded state-specific conclusion>"
  }}],
  "payload_digest": "<sha256 of canonical JSON without payload_digest>"
}}
{semantic_invariant_authority.TRACE_END}

Use a local deterministic JSON/hash command before finishing. Missing rows,
invalid loci, or a digest mismatch remain UNMEASURABLE and cannot certify
coverage. This is producer delivery only; a distinct depth consumer must
independently apply it before APPLIED status is possible.
"""
    return compile_phase_io_prompt(prompt + trace_contract, contract, actor="MODEL")


def _compile_semantic_invariant_pass2_model_prompt(
    prompt: str,
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> str:
    """Bind Pass 2 to a distinct append-only producer identity."""
    contract, _launch = _p1dm_contract_and_launch(
        Path(scratchpad),
        config,
        phase_name="invariants_p2",
        work_unit_id="worker.semantic_invariants_pass2",
        phase=phase,
        actor="MODEL",
    )
    append_contract = f"""

# P1-D PASS-2 EXACT APPEND CONTRACT

`{semantic_invariant_authority.PASS2_PRE_FILE}` binds the immutable Pass-1
receipt and exact byte prefix. Append only the required Pass-2 section to
`semantic_invariants.md`; do not rewrite, truncate, normalize, or delete any
existing byte. This producer cannot certify its own append. The driver will
reconcile the exact pre/post hashes into
`{semantic_invariant_authority.FINAL_BYTE_AUTHORITY_FILE}` under a distinct
work identity. If the append cannot be completed, leave the original file
unchanged; the driver will record visible UNMEASURABLE debt.
"""
    return compile_phase_io_prompt(prompt + append_contract, contract, actor="MODEL")


def _semantic_invariant_fallback_replay_issues(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str] | None:
    """Return fallback replay debt, or ``None`` when no fallback was published."""

    root = Path(scratchpad)
    transaction = {
        "phase_name": "invariants",
        "work_unit_id": "semantic_invariants.fallback",
        "exact_inputs": (),
        "exact_outputs": (),
    }
    try:
        contract, _launch = _p1dm_contract_and_launch(
            root,
            config,
            actor="DRIVER",
            **transaction,
        )
        work_units = read_artifact_ledger(root).get("work_units")
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            "invariants/semantic_invariants.fallback replay selection failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    if not isinstance(work_units, Mapping) or contract.key not in work_units:
        return None
    return _validate_existing_p1dm_driver_transaction(
        root,
        config,
        validate=lambda: _validate_semantic_invariant_producer_trace(
            root, config
        ),
        **transaction,
    )


def _run_semantic_invariant_fallback_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: Phase,
    reason: str,
) -> tuple[list[str], list[str], list[str]]:
    """Retain the MODEL proposal, then publish a distinct DRIVER fallback."""

    root = Path(scratchpad)
    proposal_issues: list[str] = []
    semantic_path = root / "semantic_invariants.md"
    try:
        has_proposal = semantic_path.is_file() and semantic_path.stat().st_size > 0
    except OSError:
        has_proposal = False
    if has_proposal:
        proposal_issues.extend(
            _record_typed_model_phase_artifacts(phase, root, dict(config))
        )

    existing = _semantic_invariant_fallback_replay_issues(root, config)
    if existing is not None:
        return [], list(dict.fromkeys(proposal_issues)), existing

    written: list[str] = []

    def write() -> None:
        written.extend(_write_semantic_invariants_fallback(root, reason))

    transaction_issues = _record_p1dm_driver_transaction(
        root,
        config,
        phase_name="invariants",
        work_unit_id="semantic_invariants.fallback",
        action=write,
        validate=lambda: _validate_semantic_invariant_producer_trace(
            root, config
        ),
    )
    return (
        written,
        list(dict.fromkeys(proposal_issues)),
        list(dict.fromkeys(transaction_issues)),
    )


def _finalize_semantic_invariant_post_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Record the accepted producer output, then enumerate/diff P1-D POST."""
    root = Path(scratchpad)
    phase_set = L1_PHASES if str(config.get("pipeline") or "sc") == "l1" else SC_PHASES
    phase = next(row for row in phase_set if row.name == "invariants")
    fallback_issues = _semantic_invariant_fallback_replay_issues(root, config)
    issues = (
        _record_typed_model_phase_artifacts(phase, root, dict(config))
        if fallback_issues is None
        else list(fallback_issues)
    )
    issues.extend(_record_p1dm_driver_transaction(
        root,
        config,
        phase_name="invariants",
        work_unit_id="semantic_invariants.post",
        action=lambda: semantic_invariant_authority.reconcile_semantic_invariant_application(
            root,
            ecosystem=str(config.get("language") or ""),
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
            load_independent_from_disk=False,
        ),
        validate=lambda: semantic_invariant_authority.validate_semantic_invariant_application(
            root,
            ecosystem=str(config.get("language") or ""),
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
            load_independent_from_disk=False,
        ),
    ))
    return list(dict.fromkeys(issues))


def _semantic_pass2_kwargs(config: Mapping[str, Any]) -> dict[str, str]:
    return {
        "ecosystem": str(config.get("language") or ""),
        "mode": str(config.get("mode") or ""),
        "run_id": str(config.get("_run_id") or ""),
        "backend": str(config.get("cli_backend") or "claude"),
    }


def _prepare_semantic_invariant_pass2_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Freeze Pass-1 receipt/bytes before the Thorough-only append worker."""
    if str(config.get("mode") or "").strip().lower() != "thorough":
        return []
    root = Path(scratchpad)
    kwargs = _semantic_pass2_kwargs(config)
    final_path = root / semantic_invariant_authority.FINAL_BYTE_AUTHORITY_FILE
    if final_path.is_file():
        issues = (
            semantic_invariant_authority
            .validate_semantic_invariant_final_byte_authority(root, **kwargs)
        )
        if issues:
            return list(dict.fromkeys(issues))
        try:
            final = json.loads(final_path.read_text(encoding="utf-8", errors="strict"))
        except Exception as exc:
            return [f"final-byte authority malformed: {type(exc).__name__}"]
        return semantic_invariant_authority.semantic_invariant_pass2_debt_issues(
            final
        )

    pre_path = root / semantic_invariant_authority.PASS2_PRE_FILE
    transaction = {
        "phase_name": "invariants_p2",
        "work_unit_id": "semantic_invariants.pass2_pre",
        "exact_inputs": (),
        "exact_outputs": (),
    }
    validate = lambda: (  # noqa: E731 - exact replay callback
        semantic_invariant_authority
        .validate_semantic_invariant_pass2_pre_authority(root, **kwargs)
    )
    try:
        contract, _launch = _p1dm_contract_and_launch(
            root,
            config,
            actor="DRIVER",
            **transaction,
        )
        work_units = read_artifact_ledger(root).get("work_units")
        replay = isinstance(work_units, Mapping) and contract.key in work_units
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            "invariants_p2/semantic_invariants.pass2_pre replay selection failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    if replay:
        return _validate_existing_p1dm_driver_transaction(
            root,
            config,
            validate=validate,
            **transaction,
        )
    if pre_path.exists():
        return [
            "Pass-2 PRE output exists without its exact committed work-unit record"
        ]
    try:
        pre = semantic_invariant_authority.derive_semantic_invariant_pass2_pre_authority(
            root, **kwargs
        )
    except (ValueError, OSError, UnicodeError) as exc:
        return [f"Pass-2 PRE authority failed: {type(exc).__name__}: {exc}"]
    transaction_issues = _record_p1dm_driver_transaction(
        root,
        config,
        action=lambda: semantic_invariant_authority.write_semantic_invariant_pass2_pre_authority(
            root, **kwargs
        ),
        validate=validate,
        **transaction,
    )
    semantic_issues: list[str] = []
    if pre.get("status") != "READY":
        semantic_issues.extend(str(value) for value in pre.get("issues") or [])
    return list(dict.fromkeys([*transaction_issues, *semantic_issues]))


def _finalize_semantic_invariant_pass2_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Commit an immutable exact-byte successor after the Pass-2 append."""
    if str(config.get("mode") or "").strip().lower() != "thorough":
        return []
    root = Path(scratchpad)
    kwargs = _semantic_pass2_kwargs(config)
    final_path = root / semantic_invariant_authority.FINAL_BYTE_AUTHORITY_FILE
    if final_path.is_file():
        issues = (
            semantic_invariant_authority
            .validate_semantic_invariant_final_byte_authority(root, **kwargs)
        )
        if issues:
            return list(dict.fromkeys(issues))
        try:
            final = json.loads(final_path.read_text(encoding="utf-8", errors="strict"))
        except Exception as exc:
            return [f"final-byte authority malformed: {type(exc).__name__}"]
        return semantic_invariant_authority.semantic_invariant_pass2_debt_issues(
            final
        )

    transaction_issues = _record_p1dm_driver_transaction(
        root,
        config,
        phase_name="invariants_p2",
        work_unit_id="semantic_invariants.pass2_reconcile",
        action=lambda: semantic_invariant_authority.write_semantic_invariant_final_byte_authority(
            root, **kwargs
        ),
        validate=lambda: semantic_invariant_authority.validate_semantic_invariant_final_byte_authority(
            root, **kwargs
        ),
    )
    # Missing inputs must remain haltless but visible.  The ledger may reject
    # the transaction before its action; still emit a decision-negative typed
    # successor so depth cannot fall back to the stale Pass-1 receipt.
    if not final_path.is_file():
        try:
            semantic_invariant_authority.write_semantic_invariant_final_byte_authority(
                root, **kwargs
            )
        except (ValueError, OSError, UnicodeError) as exc:
            transaction_issues.append(
                f"Pass-2 final-byte authority failed: {type(exc).__name__}: {exc}"
            )
    try:
        final = json.loads(final_path.read_text(encoding="utf-8", errors="strict"))
    except Exception as exc:
        transaction_issues.append(
            f"final-byte authority missing or malformed: {type(exc).__name__}"
        )
    else:
        transaction_issues.extend(
            semantic_invariant_authority.semantic_invariant_pass2_debt_issues(
                final
            )
        )
    return list(dict.fromkeys(transaction_issues))


def _validate_semantic_invariant_producer_trace(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Reject producer non-application while allowing source-authority debt."""
    root = Path(scratchpad)
    authority_issues = semantic_invariant_authority.validate_semantic_invariant_authority(
        root,
        ecosystem=str(config.get("language") or ""),
        mode=str(config.get("mode") or ""),
        run_id=str(config.get("_run_id") or ""),
    )
    if authority_issues:
        return list(authority_issues)
    try:
        semantic_text = (root / "semantic_invariants.md").read_text(
            encoding="utf-8", errors="strict"
        )
        semantic_invariant_authority.parse_semantic_invariant_application_trace(
            semantic_text
        )
        receipt, _projection = (
            semantic_invariant_authority.derive_semantic_invariant_application(
                root,
                semantic_text=semantic_text,
                ecosystem=str(config.get("language") or ""),
                mode=str(config.get("mode") or ""),
                run_id=str(config.get("_run_id") or "test-unbound"),
                load_independent_from_disk=False,
            )
        )
    except Exception as exc:
        return [f"semantic invariant typed producer trace invalid: {exc}"]
    issues: list[str] = []
    # Source conflicts/unsupported graph facts remain typed open debt and are
    # not repairable by re-running the model. Trace schema/binding failures and
    # omitted/invalid rows are producer non-application, so they do consume the
    # bounded ordinary phase retry.
    for issue in receipt.get("issues") or []:
        text = str(issue)
        if "application trace" in text.casefold():
            issues.append(text)
    for row in receipt.get("states") or []:
        if not isinstance(row, Mapping):
            continue
        row_issues = [str(value) for value in row.get("issues") or []]
        if any(
            "typed application row is missing or invalid" in value.casefold()
            for value in row_issues
        ):
            issues.append(
                f"state {row.get('state_id')}: exact typed application row "
                "missing or invalid"
            )
    return list(dict.fromkeys(issues))


def _execute_auxiliary_model_work_unit(
    *,
    prompt: str,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    output: str,
    label: str,
    launch: LaunchSpec,
    contract: PhaseIOContract,
) -> int:
    """Execute one PhaseIO-armed, non-orchestrating model leaf."""
    if launch.backend == "codex":
        return _run_one_codex_exec(
            prompt=prompt,
            phase=phase,
            config=config,
            scratchpad=Path(scratchpad),
            attempt=1,
            label=label,
            expected_outputs=[output],
            timeout=float(launch.timeout_s),
            effective_model=launch.model,
            phase_io_contract=contract,
            phase_io_launch=launch,
        )
    return _run_one_claude_headless_breadth_worker(
        prompt=prompt,
        job={"agent_id": label, "output": output},
        phase=phase,
        config=config,
        scratchpad=Path(scratchpad),
        attempt=1,
        timeout=float(launch.timeout_s),
        effective_model=launch.model,
        label_prefix="typed_aux",
        # These fixed typed leaves read and write scratchpad-relative
        # artifacts.  The legacy Claude transport otherwise inherits the
        # project root as cwd, which can turn a correct response into a
        # missing typed sidecar (or a stray project-root file).  Keep source
        # analysis available through --add-dir while making the contracted
        # artifact namespace the actual working directory.
        working_directory=str(Path(scratchpad).resolve()),
        analysis_directories=(str(Path(config["project_root"]).resolve()),),
        phase_io_contract=contract,
        phase_io_launch=launch,
    )


def _run_p1dm_model_work_unit(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
    *,
    phase_name: str,
    work_unit_id: str,
    output: str,
    prompt: str,
    validate: Callable[[], Sequence[str]],
    exact_inputs: Sequence[str] = (),
) -> list[str]:
    """Prebind, execute, validate, and record a fixed typed model leaf."""
    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return [f"{phase_name}/{work_unit_id} cannot bind without a run_id"]
    try:
        contract, launch = _p1dm_contract_and_launch(
            root,
            config,
            phase_name=phase_name,
            work_unit_id=work_unit_id,
            phase=phase,
            exact_inputs=exact_inputs,
            exact_outputs=(output,),
            actor="MODEL",
        )
        # An exact, already-valid receipt is the only resume fast path.
        prior_input_issues = validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        )
        prior_output_issues = validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="MODEL",
        )
        if not prior_input_issues and not prior_output_issues and not list(validate()):
            return []
        record_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        )
        issues = validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        )
        if issues:
            # Arm-before-trust for auxiliary leaves: an INPUT_DEBT receipt is
            # evidence that no exact semantic denominator existed. It is not
            # a degraded launch authorization. The caller can still emit an
            # explicit UNMEASURABLE DRIVER authority without model prose.
            return list(dict.fromkeys(issues))
        # Semantic inputs are immutable across the auxiliary model turn.
        protected: dict[Path, bytes] = {}
        for identity in contract.immutable_inputs:
            prefix, relative = identity.split(":", 1)
            path = (root if prefix == "scratchpad" else project_root) / relative
            if path.is_file():
                protected[path] = path.read_bytes()
        input_snapshot = _snapshot_worker_input_artifacts(root, {output})
        try:
            before_names = {
                path.name for path in root.iterdir()
                if path.is_file() and not path.name.startswith("_")
            }
        except OSError:
            before_names = set()
        compiled = compile_phase_io_prompt(prompt, contract, actor="MODEL")
        rc = _execute_auxiliary_model_work_unit(
            prompt=compiled,
            phase=phase,
            config=config,
            scratchpad=root,
            output=output,
            label=work_unit_id.replace(".", "_"),
            contract=contract,
            launch=launch,
        )
        mutated: list[str] = []
        for path, before in protected.items():
            try:
                if not path.is_file() or path.read_bytes() == before:
                    continue
                temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.restore")
                temporary.write_bytes(before)
                temporary.replace(path)
                mutated.append(path.name)
            except OSError:
                mutated.append(f"{path.name}:restore-failed")
        if mutated:
            issues.append(
                "auxiliary worker mutated immutable semantic input(s): "
                + ", ".join(sorted(mutated))
            )
        restored = _restore_worker_input_artifacts(root, input_snapshot)
        try:
            after_names = {
                path.name for path in root.iterdir()
                if path.is_file() and not path.name.startswith("_")
            }
        except OSError:
            after_names = set()
        foreign_new = sorted((after_names - before_names) - {output})
        if foreign_new:
            quarantine = (
                root / "_quarantine" / "typed_aux_containment" /
                work_unit_id.replace(".", "_")
            )
            quarantine.mkdir(parents=True, exist_ok=True)
            for name in foreign_new:
                try:
                    (root / name).replace(quarantine / name)
                except OSError:
                    pass
        if restored or foreign_new:
            issues.append(
                "auxiliary worker containment violation: "
                f"restored={sorted(restored)} foreign_new={foreign_new}"
            )
        if rc != 0:
            issues.append(f"auxiliary model exited rc={rc}")
        issues.extend(str(value) for value in validate())
        committed_output_issues = validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="MODEL",
        )
        if issues or committed_output_issues:
            # Transactional headless execution publishes the output and its
            # CAS-backed authority before returning. Re-recording that clean
            # commit here creates a second attempt without a corresponding
            # semantic re-execution transition, which makes the otherwise
            # valid producer impossible to replay. Compatibility/fake
            # executors do not publish, so retain the wrapper-owned commit for
            # them; semantic failures likewise need a quarantined wrapper
            # decision rather than accepting the inner byte-only commit.
            record_work_unit_artifacts(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
                actor="MODEL",
                precommit_issues=issues,
            )
            issues.extend(validate_work_unit_artifacts(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
                actor="MODEL",
            ))
        return list(dict.fromkeys(issues))
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        return [
            f"{phase_name}/{work_unit_id} model transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _l1_composition_context(config: Mapping[str, Any]) -> dict[str, str]:
    """Bind P1-L to the same immutable run/snapshot identity as the audit."""
    return {
        "pipeline": str(config.get("pipeline") or "l1"),
        "mode": str(config.get("mode") or "core"),
        "language": str(config.get("language") or "other"),
        "run_id": str(config.get("_run_id") or ""),
        "snapshot_digest": _security_obligation_source_snapshot_digest(config),
    }


def _l1_composition_fact_prompt(
    producer_identity: str, producer_invocation_id: str
) -> str:
    return f"""# Independent L1 composition fact producer

Read the exact finite occurrence denominator in
`{l1_composition_runtime.FACT_WORKLIST_NAME}` and the source artifact named by
every row. Write ONLY `{l1_composition_runtime.TYPED_RECORDS_NAME}` with schema
`{l1_composition_runtime.TYPED_RECORDS_SCHEMA}`. The root fields are exactly
schema_version, run_id, snapshot_digest, producer_identity,
producer_invocation_id, records. Emit exactly one record in worklist order for
every occurrence. Each record has exactly candidate_id, source_artifact,
source_block_sha256, language, layer, subsystem, root_cause_id,
candidate_state, requires, produces, touches. Preserve the three exact source
binding fields.

The driver-bound producer_identity is `{producer_identity}` and the
driver-bound producer_invocation_id is `{producer_invocation_id}`. Copy these
exact values; model-chosen identity strings have no authority.

Atom rows have exactly kind and atom_id. kind is one of STATE, EVENT, TIMING,
VALIDATION, RESOURCE, ACTIVATION, ROLLBACK, TRUST_BOUNDARY. Atom IDs, layer,
subsystem, and root_cause_id are bounded structural tokens, not prose. Use
candidate_state CONFIRMED, CONTESTED, UNRESOLVED, or REFUTED according to the
source record, but producer-local REFUTED never grants terminal negative
authority and remains composition-eligible. Record empty atom arrays when no
typed relation is supportable; never infer atoms from similar words alone.
This worker proposes facts only and cannot infer a composition, finding,
proof, severity, suppression, or report disposition. Write no other file.
"""


def _l1_composition_disposition_prompt(
    producer_identity: str, producer_invocation_id: str
) -> str:
    return f"""# Independent L1 composition obligation discriminator

Read `{l1_composition_runtime.RUNTIME_NAME}` as the complete finite obligation
denominator and only the exact source artifacts bound by the PhaseIO contract
when needed to reason about composed reachability. Write ONLY
`{l1_composition_runtime.MODEL_DISPOSITIONS_NAME}` with schema
`{l1_composition_runtime.MODEL_DISPOSITIONS_SCHEMA}`. Root fields are exactly
schema_version, run_id, snapshot_digest, producer_identity,
producer_invocation_id, runtime_digest, graph_digest, work_packets_digest,
dispositions. Bind every digest exactly and emit one disposition for every
work packet, in packet order. Each disposition has exactly obligation_id,
disposition, rationale. disposition is COMPOUND_CANDIDATE, RESTATEMENT,
INCOMPATIBLE, UNREACHABLE, or NEEDS_EVIDENCE.

The driver-bound producer_identity is `{producer_identity}` and the
driver-bound producer_invocation_id is `{producer_invocation_id}`. Copy these
exact values; model-chosen identity strings have no authority.

Use a producer identity and invocation distinct from the typed fact producer.
COMPOUND_CANDIDATE is a low-confidence proposal for ordinary independent
verification, never proof. A negative label is local reasoning only and grants
no finding deletion, suppression, demotion, or report authority. Preserve all
packet identities; do not omit uncertain rows (use NEEDS_EVIDENCE). Write no
other file.
"""


def _validate_l1_composition_dispositions(
    root: Path,
    *,
    expected_producer_identity: str = "",
    expected_producer_invocation_id: str = "",
) -> list[str]:
    try:
        runtime = json.loads(
            (root / l1_composition_runtime.RUNTIME_NAME).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        dispositions = json.loads(
            (root / l1_composition_runtime.MODEL_DISPOSITIONS_NAME).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        receipt = reconcile_l1_composition_runtime(runtime, dispositions)
    except Exception as exc:
        return [f"L1 composition dispositions missing/malformed: {type(exc).__name__}: {exc}"]
    issues: list[str] = []
    if (
        expected_producer_identity
        and dispositions.get("producer_identity") != expected_producer_identity
    ):
        issues.append("L1 composition disposition producer identity is not driver-bound")
    if (
        expected_producer_invocation_id
        and dispositions.get("producer_invocation_id")
        != expected_producer_invocation_id
    ):
        issues.append("L1 composition disposition invocation is not driver-bound")
    if not receipt.get("deliverable_obligation_coverage_exact"):
        issues.append("L1 composition disposition denominator is not exact")
    issues.extend(
        str(row.get("code") or "L1_COMPOSITION_DISPOSITION_DEBT")
        for row in receipt.get("debts") or []
        if isinstance(row, Mapping)
        and str(row.get("code") or "") in {
            "MODEL_DISPOSITION_ARTIFACT_MALFORMED",
            "MODEL_DISPOSITION_CONTEXT_MISMATCH",
            "MODEL_DISPOSITION_SELF_CERTIFICATION",
            "L1_COMPOSITION_COVERAGE_INCOMPLETE",
        }
    )
    return list(dict.fromkeys(issues))


def _run_l1_composition_live_boundary(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> list[str]:
    """Run P1-L fact -> enumerate -> discriminate -> reconcile lifecycle."""
    if (
        str(config.get("pipeline") or "").strip().lower() != "l1"
        or str(config.get("mode") or "").strip().lower() not in {"core", "thorough"}
    ):
        return []
    root = Path(scratchpad)
    context = _l1_composition_context(config)
    issues: list[str] = []
    # Producer bindings are live launch authority, never reusable in-memory
    # state from an earlier invocation or resume attempt.
    config.pop("_l1_composition_producer_bindings", None)
    source_inputs = l1_composition_runtime.l1_composition_source_artifacts(
        root, pipeline=context["pipeline"], mode=context["mode"]
    )
    issues.extend(_record_p1dm_driver_transaction(
        root,
        config,
        phase_name="verify_queue",
        work_unit_id="l1_composition.fact_worklist",
        exact_inputs=source_inputs,
        exact_outputs=(l1_composition_runtime.FACT_WORKLIST_NAME,),
        action=lambda: l1_composition_runtime.write_l1_composition_fact_worklist(
            root, **context
        ),
        validate=lambda: l1_composition_runtime.validate_l1_composition_fact_worklist(
            json.loads((root / l1_composition_runtime.FACT_WORKLIST_NAME).read_text(
                encoding="utf-8", errors="strict"
            )), root, **context
        ),
    ))
    try:
        fact_worklist = json.loads(
            (root / l1_composition_runtime.FACT_WORKLIST_NAME).read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except Exception:
        fact_worklist = {}
    if (
        not source_inputs
        and not l1_composition_runtime.l1_composition_source_artifacts(
            root, pipeline=context["pipeline"], mode=context["mode"]
        )
        and int(fact_worklist.get("occurrence_count") or 0) == 0
        and not l1_composition_runtime.validate_l1_composition_fact_worklist(
            fact_worklist, root, **context
        )
    ):
        # Exact no-source activation has no semantic fact row to assign.  The
        # queue boundary validates this worklist as the no-work authority.
        return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))
    auxiliary_phase = next(
        row for row in L1_PHASES if row.name == "application_skeptic"
    )
    fact_contract, fact_launch = _p1dm_contract_and_launch(
        root,
        config,
        phase_name="verify_queue",
        work_unit_id="worker.l1_composition_facts",
        phase=auxiliary_phase,
        exact_inputs=(l1_composition_runtime.FACT_WORKLIST_NAME, *source_inputs),
        exact_outputs=(l1_composition_runtime.TYPED_RECORDS_NAME,),
        actor="MODEL",
    )
    fact_producer_identity = fact_contract.key
    fact_producer_invocation = fact_launch.digest
    issues.extend(_run_p1dm_model_work_unit(
        root,
        config,
        auxiliary_phase,
        phase_name="verify_queue",
        work_unit_id="worker.l1_composition_facts",
        output=l1_composition_runtime.TYPED_RECORDS_NAME,
        exact_inputs=(l1_composition_runtime.FACT_WORKLIST_NAME, *source_inputs),
        prompt=_l1_composition_fact_prompt(
            fact_producer_identity, fact_producer_invocation
        ),
        validate=lambda: l1_composition_runtime.validate_l1_composition_fact_records(
            root,
            **context,
            expected_producer_identity=fact_producer_identity,
            expected_producer_invocation_id=fact_producer_invocation,
        ),
    ))
    runtime_inputs = (*source_inputs, l1_composition_runtime.TYPED_RECORDS_NAME)
    issues.extend(_record_p1dm_driver_transaction(
        root,
        config,
        phase_name="verify_queue",
        work_unit_id="l1_composition.runtime",
        exact_inputs=runtime_inputs,
        exact_outputs=(l1_composition_runtime.RUNTIME_NAME,),
        action=lambda: write_l1_composition_runtime(root, **context),
        validate=lambda: l1_composition_runtime.validate_l1_composition_runtime(
            json.loads((root / l1_composition_runtime.RUNTIME_NAME).read_text(
                encoding="utf-8", errors="strict"
            )), root, **context
        ),
    ))
    try:
        live_runtime = json.loads(
            (root / l1_composition_runtime.RUNTIME_NAME).read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except Exception:
        live_runtime = {}
    if (
        not live_runtime.get("work_packets")
        and not l1_composition_runtime.validate_l1_composition_runtime(
            live_runtime, root, **context
        )
    ):
        # A validated empty obligation denominator needs no model judgment.
        return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))
    disposition_contract, disposition_launch = _p1dm_contract_and_launch(
        root,
        config,
        phase_name="verify_queue",
        work_unit_id="worker.l1_composition_dispositions",
        phase=auxiliary_phase,
        exact_inputs=(l1_composition_runtime.RUNTIME_NAME, *source_inputs),
        exact_outputs=(l1_composition_runtime.MODEL_DISPOSITIONS_NAME,),
        actor="MODEL",
    )
    disposition_producer_identity = disposition_contract.key
    disposition_producer_invocation = disposition_launch.digest
    config["_l1_composition_producer_bindings"] = {
        "fact_producer_identity": fact_producer_identity,
        "fact_producer_invocation_id": fact_producer_invocation,
        "disposition_producer_identity": disposition_producer_identity,
        "disposition_producer_invocation_id": disposition_producer_invocation,
    }
    issues.extend(_run_p1dm_model_work_unit(
        root,
        config,
        auxiliary_phase,
        phase_name="verify_queue",
        work_unit_id="worker.l1_composition_dispositions",
        output=l1_composition_runtime.MODEL_DISPOSITIONS_NAME,
        exact_inputs=(l1_composition_runtime.RUNTIME_NAME, *source_inputs),
        prompt=_l1_composition_disposition_prompt(
            disposition_producer_identity, disposition_producer_invocation
        ),
        validate=lambda: _validate_l1_composition_dispositions(
            root,
            expected_producer_identity=disposition_producer_identity,
            expected_producer_invocation_id=disposition_producer_invocation,
        ),
    ))
    def write_receipt() -> None:
        runtime = json.loads(
            (root / l1_composition_runtime.RUNTIME_NAME).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        try:
            dispositions: Mapping[str, Any] = json.loads(
                (root / l1_composition_runtime.MODEL_DISPOSITIONS_NAME).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
        except Exception:
            dispositions = {}
        try:
            typed_facts = json.loads(
                (root / l1_composition_runtime.TYPED_RECORDS_NAME).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
        except Exception:
            typed_facts = {}
        if (
            typed_facts.get("producer_identity") != fact_producer_identity
            or typed_facts.get("producer_invocation_id")
            != fact_producer_invocation
            or dispositions.get("producer_identity")
            != disposition_producer_identity
            or dispositions.get("producer_invocation_id")
            != disposition_producer_invocation
        ):
            # Distinct model-chosen strings are not proof of independence.  A
            # principal mismatch deterministically removes every deliverable
            # handoff while retaining a degraded reconciliation receipt.
            dispositions = {}
        # The explicit pure reconciliation call keeps proposal authority
        # inspectable at the driver boundary; the writer persists these bytes.
        reconcile_l1_composition_runtime(runtime, dispositions)
        l1_composition_runtime.write_l1_composition_receipt(
            root, runtime, dispositions
        )

    issues.extend(_record_p1dm_driver_transaction(
        root,
        config,
        phase_name="verify_queue",
        work_unit_id="l1_composition.reconcile",
        exact_inputs=(
            l1_composition_runtime.RUNTIME_NAME,
            l1_composition_runtime.MODEL_DISPOSITIONS_NAME,
        ),
        exact_outputs=(l1_composition_runtime.RECEIPT_NAME,),
        action=write_receipt,
        validate=lambda: _validate_l1_composition_dispositions(
            root,
            expected_producer_identity=disposition_producer_identity,
            expected_producer_invocation_id=disposition_producer_invocation,
        ),
    ))
    return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))


def _semantic_independent_prompt() -> str:
    return f"""# Independent semantic-invariant application consumer

Read the exact P1-D authority, worklist, producer trace in
`semantic_invariants.md`, and its delivery receipt/gaps. Independently trace
the current bytes only when the Thorough-mode successor
`{semantic_invariant_authority.FINAL_BYTE_AUTHORITY_FILE}` validates; it binds
the distinct Pass-2 append producer to the final semantic artifact without
granting that producer semantic or proof authority. Independently trace
the relevant source paths and write ONLY
`{semantic_invariant_authority.INDEPENDENT_TRACE_FILE}` as JSON schema
`{semantic_invariant_authority.INDEPENDENT_TRACE_SCHEMA}`. Include the exact
run/authority/worklist digests, producer payload digest, consumer_kind
`DEPTH_STATE_TRACE`, a consumer_operator_digest distinct from the producer,
and one row per producer DELIVERED state. The JSON object has exactly these
fields: schema_version, run_binding_digest, authority_digest, worklist_digest,
producer_payload_digest, consumer_kind, consumer_operator_digest, rows,
payload_digest. Each row has exactly state_id, disposition,
producer_row_digest, evidence_loci, result. The independent disposition is
`APPLIED` only when the depth trace actually re-applied the producer row;
otherwise use `DEFERRED`. Finish with a canonical SHA-256 payload_digest of
the sorted compact JSON object with payload_digest omitted.
Never convert a missing, deferred, conflicted, or unmeasurable producer row to
proof. Write no other file and stop.
"""


def _validate_independent_trace_shape(root: Path) -> list[str]:
    try:
        payload = json.loads(
            (Path(root) / semantic_invariant_authority.INDEPENDENT_TRACE_FILE)
            .read_text(encoding="utf-8", errors="strict")
        )
    except Exception as exc:
        return [f"independent semantic trace missing/malformed: {type(exc).__name__}"]
    if not isinstance(payload, dict):
        return ["independent semantic trace root is not an object"]
    issues: list[str] = []
    expected_fields = {
        "schema_version", "run_binding_digest", "authority_digest",
        "worklist_digest", "producer_payload_digest", "consumer_kind",
        "consumer_operator_digest", "rows", "payload_digest",
    }
    if set(payload) != expected_fields:
        issues.append("independent semantic trace fields mismatch")
    if payload.get("schema_version") != semantic_invariant_authority.INDEPENDENT_TRACE_SCHEMA:
        issues.append("independent semantic trace schema mismatch")
    if payload.get("payload_digest") != semantic_invariant_authority.payload_digest(payload):
        issues.append("independent semantic trace payload digest mismatch")
    try:
        worklist = json.loads(
            (Path(root) / semantic_invariant_authority.WORKLIST_FILE)
            .read_text(encoding="utf-8", errors="strict")
        )
        producer = semantic_invariant_authority.parse_semantic_invariant_application_trace(
            (Path(root) / "semantic_invariants.md").read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except Exception as exc:
        return [*issues, f"independent trace binding source invalid: {exc}"]
    expected = {
        "run_binding_digest": (worklist.get("run_binding") or {}).get("binding_digest"),
        "authority_digest": worklist.get("authority_digest"),
        "worklist_digest": worklist.get("worklist_digest"),
        "producer_payload_digest": producer.get("payload_digest"),
    }
    for field, value in expected.items():
        if payload.get(field) != value:
            issues.append(f"independent semantic trace {field} mismatch")
    if payload.get("consumer_kind") not in {"DEPTH_STATE_TRACE", "APPLICATION_SKEPTIC"}:
        issues.append("independent semantic trace consumer kind invalid")
    if payload.get("consumer_operator_digest") == producer.get("producer_operator_digest"):
        issues.append("independent consumer operator is not distinct")
    rows = payload.get("rows")
    if not isinstance(rows, list):
        issues.append("independent semantic trace rows is not an array")
    else:
        expected_row_fields = {
            "state_id", "disposition", "producer_row_digest",
            "evidence_loci", "result",
        }
        producer_by_id = {
            str(row.get("state_id") or ""): row
            for row in producer.get("rows") or [] if isinstance(row, Mapping)
        }
        for row in rows:
            if not isinstance(row, Mapping) or set(row) != expected_row_fields:
                issues.append("independent semantic trace row fields mismatch")
                continue
            state_id = str(row.get("state_id") or "")
            bound = producer_by_id.get(state_id)
            if bound is None:
                issues.append(f"independent semantic trace unknown state: {state_id}")
            elif row.get("producer_row_digest") != semantic_invariant_authority.producer_row_digest(bound):
                issues.append(f"independent semantic trace row digest mismatch: {state_id}")
            if row.get("disposition") not in {"APPLIED", "DEFERRED"}:
                issues.append(f"independent semantic trace disposition invalid: {state_id}")
    return list(dict.fromkeys(issues))


def _semantic_invariant_final_input_issues(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Return decision-negative debt for an invalid Thorough final authority."""
    if str(config.get("mode") or "").strip().lower() != "thorough":
        return []
    root = Path(scratchpad)
    issues = (
        semantic_invariant_authority
        .validate_semantic_invariant_final_byte_authority(
            root, **_semantic_pass2_kwargs(config)
        )
    )
    if issues:
        return list(dict.fromkeys(issues))
    try:
        final_payload = json.loads(
            (
                root / semantic_invariant_authority.FINAL_BYTE_AUTHORITY_FILE
            ).read_text(encoding="utf-8", errors="strict")
        )
    except Exception as exc:
        return [f"final-byte authority malformed: {type(exc).__name__}"]
    debt = semantic_invariant_authority.semantic_invariant_pass2_debt_issues(
        final_payload
    )
    if debt:
        return debt
    return _semantic_invariant_depth_receipt_lineage_issues(
        root, final_payload
    )


def _semantic_invariant_depth_receipt_lineage_issues(
    scratchpad: Path,
    final_payload: Mapping[str, Any],
) -> list[str]:
    """Accept only the sealed prior receipt or its exact depth successor."""
    root = Path(scratchpad)
    try:
        pre = json.loads(
            (root / semantic_invariant_authority.PASS2_PRE_FILE).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        receipt_path = root / semantic_invariant_authority.APPLICATION_RECEIPT_FILE
        receipt_bytes = receipt_path.read_bytes()
    except Exception as exc:
        return [f"semantic receipt lineage unavailable: {type(exc).__name__}"]
    if (
        hashlib.sha256(receipt_bytes).hexdigest()
        == str(pre.get("prior_application_receipt_sha256") or "")
        and len(receipt_bytes)
        == int(pre.get("prior_application_receipt_byte_count") or -1)
    ):
        return []
    try:
        receipt = json.loads(receipt_bytes.decode("utf-8", errors="strict"))
    except Exception as exc:
        return [f"semantic receipt successor malformed: {type(exc).__name__}"]
    issues: list[str] = []
    if not isinstance(receipt, Mapping):
        return ["semantic receipt successor root is not an object"]
    if receipt.get("schema_version") != semantic_invariant_authority.APPLICATION_RECEIPT_SCHEMA:
        issues.append("semantic receipt successor schema mismatch")
    unsigned = {
        key: value for key, value in receipt.items() if key != "receipt_digest"
    }
    expected_digest = hashlib.sha256(
        json.dumps(
            unsigned,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    if receipt.get("receipt_digest") != expected_digest:
        issues.append("semantic receipt successor digest mismatch")
    prior = pre.get("prior_application_receipt")
    if not isinstance(prior, Mapping):
        issues.append("sealed prior semantic receipt is unavailable")
        prior = {}
    for field in (
        "run_binding",
        "authority_digest",
        "worklist_digest",
        "application_payload_digest",
        "producer_operator_digest",
    ):
        if receipt.get(field) != prior.get(field):
            issues.append(f"semantic receipt successor {field} mismatch")
    if (
        receipt.get("status") != "APPLIED"
        or receipt.get("independent_application_confirmed") is not True
        or not re.fullmatch(
            r"[0-9a-f]{64}", str(receipt.get("independent_payload_digest") or "")
        )
    ):
        issues.append("semantic receipt successor lacks independent APPLIED authority")
    semantic_bindings = [
        row
        for row in receipt.get("input_bindings") or []
        if isinstance(row, Mapping)
        and row.get("artifact") == "semantic_invariants.md"
    ]
    if (
        len(semantic_bindings) != 1
        or semantic_bindings[0].get("sha256")
        != final_payload.get("post_semantic_sha256")
        or semantic_bindings[0].get("byte_count")
        != final_payload.get("post_semantic_byte_count")
    ):
        issues.append("semantic receipt successor final-byte binding mismatch")
    try:
        ledger = read_artifact_ledger(root)
        final_identity = (
            "scratchpad:"
            + semantic_invariant_authority.FINAL_BYTE_AUTHORITY_FILE
        )
        receipt_identity = (
            "scratchpad:"
            + semantic_invariant_authority.APPLICATION_RECEIPT_FILE
        )
        prefix = str(final_payload.get("reconciliation_work_identity") or "").split(
            "/invariants_p2/", 1
        )[0]
        expected_owner = (
            f"{prefix}/depth/semantic_invariants.independent_application"
        )
        binding = (ledger.get("artifact_bindings") or {}).get(receipt_identity) or {}
        unit = (ledger.get("work_units") or {}).get(expected_owner) or {}
        final_input = (unit.get("input_bindings") or {}).get(final_identity) or {}
        if (
            binding.get("owner_key") != expected_owner
            or binding.get("sha256") != hashlib.sha256(receipt_bytes).hexdigest()
            or unit.get("semantic_status") != "ACTIVE"
            or final_input.get("sha256")
            != hashlib.sha256(
                (
                    root
                    / semantic_invariant_authority.FINAL_BYTE_AUTHORITY_FILE
                ).read_bytes()
            ).hexdigest()
        ):
            issues.append("semantic receipt successor PhaseIO authority mismatch")
    except Exception as exc:
        issues.append(
            f"semantic receipt successor PhaseIO unavailable: {type(exc).__name__}"
        )
    return list(dict.fromkeys(issues))


def _run_semantic_invariant_independent_boundary(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> list[str]:
    """Run the distinct depth consumer, then transfer result ownership."""
    root = Path(scratchpad)
    required = (
        semantic_invariant_authority.AUTHORITY_FILE,
        semantic_invariant_authority.WORKLIST_FILE,
        "semantic_invariants.md",
        semantic_invariant_authority.APPLICATION_RECEIPT_FILE,
        semantic_invariant_authority.GAPS_PROJECTION_FILE,
    )
    # Light mode deliberately has no invariant pre-pass. Absence of the whole
    # producer family is a deterministic non-activation, not permission to
    # launch an unbound consumer. A partial family remains visible debt below.
    if not any((root / name).is_file() for name in required):
        return []
    if str(config.get("mode") or "").strip().lower() == "thorough":
        final_issues = _semantic_invariant_final_input_issues(root, config)
        if final_issues:
            return [
                "semantic invariant final-byte authority invalid; depth "
                "consumer not launched: " + "; ".join(final_issues)
            ]
    issues = _run_p1dm_model_work_unit(
        root,
        config,
        phase,
        phase_name="depth",
        work_unit_id="worker.semantic_invariant_independent",
        output=semantic_invariant_authority.INDEPENDENT_TRACE_FILE,
        prompt=_semantic_independent_prompt(),
        validate=lambda: _validate_independent_trace_shape(root),
    )
    issues.extend(_record_p1dm_driver_transaction(
        root,
        config,
        phase_name="depth",
        work_unit_id="semantic_invariants.independent_application",
        action=lambda: semantic_invariant_authority.reconcile_semantic_invariant_application(
            root,
            ecosystem=str(config.get("language") or ""),
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
        ),
        validate=lambda: semantic_invariant_authority.validate_semantic_invariant_application(
            root,
            ecosystem=str(config.get("language") or ""),
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
        ),
    ))
    return list(dict.fromkeys(issues))


def _authentication_role_prompt() -> str:
    return f"""# EVM typed authentication-role fact worker

Inspect the complete in-scope EVM source and the mechanical graph. Write ONLY
`{authentication_role_authority.TRACE_FILE}` as JSON schema
`{authentication_role_authority.FACT_TRACE_SCHEMA}`. Enumerate independent
ANCHOR and DERIVED_IDENTITY facts by trust_domain_id. The root object has
exactly schema_version, run_binding_digest, ecosystem, operator_id,
operator_digest, facts, payload_digest. Every fact has exactly
producer_fact_id, role, trust_domain_id, polarity, provenance,
anchor_identity, anchor_default, derived_identity, degenerate_input_domain,
privileged_effect, evidence, external_dependency, external_surface. Every
evidence row has exactly claim, locus, result.

For a positive ANCHOR the evidence claims are UNARMED_DEFAULT,
OPERATIONAL_WHILE_UNARMED, PRIVILEGED_EFFECT_REACHABLE. Refutation claims are
ATOMICALLY_ARMED, INERT_UNTIL_ARMED, NONZERO_REQUIRED,
DEARM_ATOMIC_OR_INERT. For a positive DERIVED_IDENTITY the evidence claims are
DEGENERATE_INPUT_IN_DOMAIN, DERIVES_DEFAULT_IDENTITY,
DEFAULT_IDENTITY_ACCEPTED, PRIVILEGED_EFFECT_REACHABLE. Refutation claims are
DEGENERATE_INPUT_REJECTED, DEFAULT_IDENTITY_REJECTED, FAIL_CLOSED,
PRIVILEGED_EFFECT_UNREACHABLE. Optional lifecycle claims are
DEARM_REACHES_UNARMED and ARMING_PATH_EXISTS. Use exact `path.sol:LNN` loci.

Record polarity REFUTED or UNKNOWN when contrary/missing evidence exists.
Out-of-scope semantics use provenance EXTERNAL and remain unknown. The run
binding digest is SHA-256 of canonical sorted compact JSON with run_id,
source_snapshot_digest, source_scope_digest, ecosystem, mode, pipeline from
the checkpoint. Include operator id/digest and a canonical payload_digest
computed with payload_digest omitted. Do not infer a composed vulnerability
and do not write prose or any other artifact. The deterministic driver alone
pairs facts.
"""


def _validate_authentication_role_trace(root: Path) -> list[str]:
    path = Path(root) / authentication_role_authority.TRACE_FILE
    if not path.is_file():
        return ["typed authentication-role trace missing"]
    try:
        payload = json.loads(path.read_text(encoding="utf-8", errors="strict"))
    except Exception as exc:
        return [f"typed authentication-role trace malformed: {type(exc).__name__}"]
    try:
        authority, _composition, _research, _projection = (
            authentication_role_authority.derive_authentication_role_authority(
                Path(root), trace_payload=payload
            )
        )
    except Exception as exc:
        return [f"typed authentication-role trace validation failed: {exc}"]
    if authority.get("status") == "UNMEASURABLE":
        return [
            str(value) for value in authority.get("issues") or
            ["typed authentication-role trace is unmeasurable"]
        ]
    return []


ARM_BEFORE_TRUST_CHAIN_ANALYSIS_FILE = "arm_before_trust_chain_analysis.input.json"
ARM_BEFORE_TRUST_COMPOUND_CANDIDATES_FILE = (
    "arm_before_trust_compound_candidates.json"
)
ARM_BEFORE_TRUST_COMPOUND_WORK_PLAN_FILE = (
    "arm_before_trust_compound_work_plan.json"
)
ARM_BEFORE_TRUST_ROUTE_DEBT_FILE = "arm_before_trust_p0af_route_debt.json"
_ARM_BEFORE_TRUST_COMPOUND_OUTPUTS = (
    ARM_BEFORE_TRUST_COMPOUND_CANDIDATES_FILE,
    ARM_BEFORE_TRUST_COMPOUND_WORK_PLAN_FILE,
    ARM_BEFORE_TRUST_ROUTE_DEBT_FILE,
)
_CANONICAL_FINDING_IDENTITY_FILE = "_canonical_finding_ids.json"


def _p1m_current_identity_denominator(
    root: Path,
) -> tuple[set[str], str]:
    """Load the exact pre-chain canonical finding/chain identity namespace."""
    path = Path(root) / _CANONICAL_FINDING_IDENTITY_FILE
    raw = path.read_bytes()
    payload = json.loads(raw.decode("utf-8", errors="strict"))
    if (
        not isinstance(payload, Mapping)
        or payload.get("schema_version") != "plamen.canonical_finding_ids.v1"
        or not isinstance(payload.get("records"), list)
        or payload.get("record_count") != len(payload.get("records") or [])
    ):
        raise ValueError("canonical finding identity denominator is malformed")
    identities: set[str] = set()
    for index, row in enumerate(payload["records"]):
        if not isinstance(row, Mapping):
            raise ValueError(
                f"canonical finding identity row {index} is malformed"
            )
        values: list[Any] = [
            row.get("canonical_id"),
            row.get("local_id"),
            row.get("local_id_raw"),
            *(row.get("referenced_ids") or []),
        ]
        for value in values:
            identity = str(value or "").strip().upper()
            if re.fullmatch(r"[A-Z][A-Z0-9_]*(?:-[A-Z0-9_]+)+", identity):
                identities.add(identity)
    return identities, hashlib.sha256(raw).hexdigest()


def _authentication_chain_prompt() -> str:
    return f"""# Independent arm-before-trust composition consumer

Read only the four exact authentication-role authority artifacts and inspect
the in-scope source needed to test their composed reachability. Write ONLY
`{ARM_BEFORE_TRUST_CHAIN_ANALYSIS_FILE}`. The root JSON fields are exactly
schema_version, composition_digest, operator_digest, candidates,
payload_digest, with schema
`plamen.arm_before_trust_chain_analysis.v1`. Emit exactly one candidate row
for every typed composition obligation. Each row has exactly candidate_id,
obligation_id, obligation_digest, constituent_fact_ids, disposition,
reachability_evidence, composition_result, harm_result, proof_authority,
route. Preserve the exact obligation/fact identities and digests.

Disposition is NOMINATED, DEFERRED, or REFUTED. proof_authority is always
NONE and route is always P0_AF_V2_QUEUE_ADAPTER_REQUIRED: this worker cannot
prove, suppress, or report the compound claim. NOMINATED requires exact
`path.sol:LNN` reachability evidence and bounded composition/harm results.
Use an operator digest distinct from the fact producer and compute the final
canonical SHA-256 payload digest with payload_digest omitted. Write no chain
hypothesis, queue, verifier, finding, report, or other file.
"""


def _validate_authentication_chain_analysis(root: Path) -> list[str]:
    root = Path(root)
    try:
        payload = json.loads(
            (root / ARM_BEFORE_TRUST_CHAIN_ANALYSIS_FILE).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        composition = json.loads(
            (root / authentication_role_authority.COMPOSITION_FILE).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        authority = json.loads(
            (root / authentication_role_authority.AUTHORITY_FILE).read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except Exception as exc:
        return [f"arm-before-trust chain analysis missing/malformed: {type(exc).__name__}"]
    issues: list[str] = []
    root_fields = {
        "schema_version", "composition_digest", "operator_digest",
        "candidates", "payload_digest",
    }
    if not isinstance(payload, Mapping) or set(payload) != root_fields:
        return ["arm-before-trust chain analysis root fields mismatch"]
    if payload.get("schema_version") != "plamen.arm_before_trust_chain_analysis.v1":
        issues.append("arm-before-trust chain analysis schema mismatch")
    if payload.get("composition_digest") != composition.get("composition_digest"):
        issues.append("arm-before-trust chain analysis composition digest mismatch")
    if payload.get("payload_digest") != _stable_payload_digest(
        {key: value for key, value in payload.items() if key != "payload_digest"}
    ):
        issues.append("arm-before-trust chain analysis payload digest mismatch")
    operator = str(payload.get("operator_digest") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", operator):
        issues.append("arm-before-trust chain operator digest invalid")
    if operator and operator == str(authority.get("operator_digest") or ""):
        issues.append("arm-before-trust chain operator is not distinct")
    obligations = {
        str(row.get("obligation_id") or ""): row
        for row in composition.get("obligations") or []
        if isinstance(row, Mapping)
    }
    candidates = payload.get("candidates")
    if not isinstance(candidates, list):
        return [*issues, "arm-before-trust chain candidates is not an array"]
    seen: set[str] = set()
    row_fields = {
        "candidate_id", "obligation_id", "obligation_digest",
        "constituent_fact_ids", "disposition", "reachability_evidence",
        "composition_result", "harm_result", "proof_authority", "route",
    }
    for index, row in enumerate(candidates):
        if not isinstance(row, Mapping) or set(row) != row_fields:
            issues.append(f"arm-before-trust candidate {index} fields mismatch")
            continue
        obligation_id = str(row.get("obligation_id") or "")
        if obligation_id in seen:
            issues.append(f"arm-before-trust obligation duplicated: {obligation_id}")
        seen.add(obligation_id)
        obligation = obligations.get(obligation_id)
        if obligation is None:
            issues.append(f"arm-before-trust candidate unknown obligation: {obligation_id}")
            continue
        if row.get("obligation_digest") != obligation.get("obligation_digest"):
            issues.append(f"arm-before-trust obligation digest mismatch: {obligation_id}")
        if row.get("constituent_fact_ids") != obligation.get("constituent_fact_ids"):
            issues.append(f"arm-before-trust fact constituents mismatch: {obligation_id}")
        if not re.fullmatch(r"MZO-CAND-[A-Z0-9_-]{1,64}", str(row.get("candidate_id") or "")):
            issues.append(f"arm-before-trust candidate identity invalid: {obligation_id}")
        disposition = str(row.get("disposition") or "")
        if disposition not in {"NOMINATED", "DEFERRED", "REFUTED"}:
            issues.append(f"arm-before-trust disposition invalid: {obligation_id}")
        if row.get("proof_authority") != "NONE":
            issues.append(f"arm-before-trust candidate granted proof: {obligation_id}")
        if row.get("route") != "P0_AF_V2_QUEUE_ADAPTER_REQUIRED":
            issues.append(f"arm-before-trust candidate route invalid: {obligation_id}")
        if disposition == "NOMINATED" and (
            not isinstance(row.get("reachability_evidence"), list)
            or not row.get("reachability_evidence")
            or not str(row.get("composition_result") or "").strip()
            or not str(row.get("harm_result") or "").strip()
        ):
            issues.append(f"arm-before-trust nomination evidence incomplete: {obligation_id}")
    missing = sorted(set(obligations) - seen)
    if missing:
        issues.append(
            "arm-before-trust obligations missing from chain analysis: "
            + ", ".join(missing)
        )
    return list(dict.fromkeys(issues))


def _write_p1m_json(path: Path, payload: Mapping[str, Any]) -> None:
    """Atomically replace one deterministic P1-M JSON authority."""
    path = Path(path)
    encoded = (
        json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2) + "\n"
    ).encode("utf-8")
    if path.is_file() and path.read_bytes() == encoded:
        return
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    try:
        temporary.write_bytes(encoded)
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def _p1m_compound_chain_id(
    obligation_id: str,
    obligation_digest: str,
    reserved: set[str],
) -> str:
    """Mint one deterministic valid CH-N identity without semantic aliases."""
    seed = hashlib.sha256(
        f"{obligation_id}\0{obligation_digest}".encode("utf-8")
    ).hexdigest()
    number = 100_000 + (int(seed[:16], 16) % 900_000)
    for _ in range(900_000):
        identity = f"CH-{number}"
        if identity not in reserved:
            reserved.add(identity)
            return identity
        number = 100_000 if number == 999_999 else number + 1
    raise ValueError("arm-before-trust CH identity namespace exhausted")


def _build_authentication_compound_work_authority(root: Path) -> None:
    """Compile nominated typed role facts into v2 P0-AF work authority.

    This boundary deliberately stops before ordinary queue delivery.  A role
    fact remains an immutable EVIDENCE_FACT constituent and therefore cannot
    be satisfied by, or projected as, a standalone finding identity.
    """
    root = Path(root)
    analysis = json.loads(
        (root / ARM_BEFORE_TRUST_CHAIN_ANALYSIS_FILE).read_text(
            encoding="utf-8", errors="strict"
        )
    )
    composition = json.loads(
        (root / authentication_role_authority.COMPOSITION_FILE).read_text(
            encoding="utf-8", errors="strict"
        )
    )
    authority = json.loads(
        (root / authentication_role_authority.AUTHORITY_FILE).read_text(
            encoding="utf-8", errors="strict"
        )
    )
    validation_issues = _validate_authentication_chain_analysis(root)
    if validation_issues:
        raise ValueError(
            "arm-before-trust chain analysis is not compileable: "
            + "; ".join(validation_issues)
        )

    obligations = {
        str(row.get("obligation_id") or ""): row
        for row in composition.get("obligations") or []
        if isinstance(row, Mapping)
    }
    facts = {
        str(row.get("fact_id") or ""): row
        for row in authority.get("facts") or []
        if isinstance(row, Mapping)
    }
    authority_digest = str(authority.get("authority_digest") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", authority_digest):
        raise ValueError("authentication fact authority digest is invalid")

    known_identities, identity_denominator_digest = (
        _p1m_current_identity_denominator(root)
    )
    reserved: set[str] = {
        identity
        for identity in known_identities
        if re.fullmatch(r"CH-\d{1,6}", identity)
    }
    candidates: list[CompoundCandidate] = []
    known_bindings: list[ConstituentAuthorityBinding] = []
    for row in sorted(
        (value for value in analysis.get("candidates") or [] if isinstance(value, Mapping)),
        key=lambda value: str(value.get("obligation_id") or ""),
    ):
        if row.get("disposition") != "NOMINATED":
            continue
        obligation_id = str(row.get("obligation_id") or "")
        obligation = obligations.get(obligation_id)
        if obligation is None:
            raise ValueError(f"unknown arm-before-trust obligation: {obligation_id}")
        bindings: list[ConstituentAuthorityBinding] = []
        for fact_id in row.get("constituent_fact_ids") or []:
            fact = facts.get(str(fact_id))
            if fact is None:
                raise ValueError(f"unknown authentication fact: {fact_id}")
            binding = ConstituentAuthorityBinding.create({
                "constituent_id": str(fact_id),
                "constituent_kind": "EVIDENCE_FACT",
                "fact_digest": str(fact.get("fact_digest") or ""),
                "authority_digest": authority_digest,
                "source_artifact": authentication_role_authority.AUTHORITY_FILE,
            })
            bindings.append(binding)
            known_bindings.append(binding)
        chain_id = _p1m_compound_chain_id(
            obligation_id,
            str(obligation.get("obligation_digest") or ""),
            reserved,
        )
        reachability = tuple(
            str(value).strip()
            for value in row.get("reachability_evidence") or []
            if str(value).strip()
        )
        candidates.append(CompoundCandidate.create(
            chain_id=chain_id,
            constituents=tuple(binding.constituent_id for binding in bindings),
            evidence_constituent_bindings=tuple(bindings),
            # This asserts only that the composition claim is distinct enough
            # to require work. It does not assert a severity or proof outcome.
            severity_upgrade_justified=True,
            ordering_edges=(),
            preconditions=(
                str(obligation.get("question") or "").strip(),
                "Reachability loci: " + ", ".join(reachability),
            ),
            postconditions=(
                "Independent execution must establish composition and material harm.",
            ),
            combined_impact_claim=(
                str(row.get("composition_result") or "").strip()
                + " "
                + str(row.get("harm_result") or "").strip()
            ).strip(),
            proposed_severity="Medium",
            source_lineage=(
                f"{ARM_BEFORE_TRUST_CHAIN_ANALYSIS_FILE}:candidate="
                f"{row.get('candidate_id')}:sha256={analysis.get('payload_digest')}",
                f"{authentication_role_authority.COMPOSITION_FILE}:obligation="
                f"{obligation_id}:sha256={obligation.get('obligation_digest')}",
            ),
            coverage_lineage=(
                obligation_id,
                *(binding.constituent_id for binding in bindings),
            ),
            pipeline="SC",
            mode=str(
                (authority.get("run_binding") or {}).get("mode") or "thorough"
            ),
        ))

    # Duplicate known bindings are harmless only when byte-identical.  The
    # compiler enforces conflicts; de-duplicate exact rows deterministically.
    known_by_id: dict[str, ConstituentAuthorityBinding] = {}
    for binding in known_bindings:
        prior = known_by_id.get(binding.constituent_id)
        if prior is not None and prior != binding:
            raise ValueError(
                "conflicting authentication fact authority: "
                + binding.constituent_id
            )
        known_by_id[binding.constituent_id] = binding
    plan = compile_compound_work_plan(
        candidates,
        known_constituent_identities=known_identities,
        known_evidence_constituents=tuple(
            known_by_id[key] for key in sorted(known_by_id)
        ),
    )
    if candidates and any(
        item.readiness is not CompoundWorkReadiness.READY
        for item in plan.work_items
    ):
        raise ValueError("typed authentication compound work is not READY")

    candidate_payload: dict[str, Any] = {
        "schema_version": "plamen.arm_before_trust_compound_candidates.v1",
        "source_analysis_digest": str(analysis.get("payload_digest") or ""),
        "source_composition_digest": str(composition.get("composition_digest") or ""),
        "source_fact_authority_digest": authority_digest,
        "identity_denominator_artifact": _CANONICAL_FINDING_IDENTITY_FILE,
        "identity_denominator_digest": identity_denominator_digest,
        "proof_authority": "NONE",
        "candidate_count": len(candidates),
        "candidates": [candidate.to_record() for candidate in candidates],
    }
    candidate_payload["payload_digest"] = _stable_payload_digest(candidate_payload)
    plan_payload: dict[str, Any] = {
        "schema_version": "plamen.arm_before_trust_compound_work_authority.v1",
        "candidate_payload_digest": candidate_payload["payload_digest"],
        "proof_authority": "NONE",
        "compound_work_plan": plan.to_record(),
    }
    plan_payload["payload_digest"] = _stable_payload_digest(plan_payload)
    ready = sorted(
        item.subject_id
        for item in plan.work_items
        if item.readiness is CompoundWorkReadiness.READY
    )
    debt_payload: dict[str, Any] = {
        "schema_version": "plamen.arm_before_trust_p0af_route_debt.v1",
        "status": "READY_PENDING_QUEUE_DELIVERY" if ready else "CLEAN_NO_NOMINATION",
        "work_authority_digest": plan_payload["payload_digest"],
        "ready_work_item_ids": ready,
        "ordinary_verification_required": bool(ready),
        "route": "P0_AF_V2_QUEUE_ADAPTER_REQUIRED",
        "proof_authority": "NONE",
    }
    debt_payload["payload_digest"] = _stable_payload_digest(debt_payload)
    _write_p1m_json(root / ARM_BEFORE_TRUST_COMPOUND_CANDIDATES_FILE, candidate_payload)
    _write_p1m_json(root / ARM_BEFORE_TRUST_COMPOUND_WORK_PLAN_FILE, plan_payload)
    _write_p1m_json(root / ARM_BEFORE_TRUST_ROUTE_DEBT_FILE, debt_payload)


def _validate_authentication_compound_work_authority(root: Path) -> list[str]:
    root = Path(root)
    try:
        candidates = json.loads(
            (root / ARM_BEFORE_TRUST_COMPOUND_CANDIDATES_FILE).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        plan = json.loads(
            (root / ARM_BEFORE_TRUST_COMPOUND_WORK_PLAN_FILE).read_text(
                encoding="utf-8", errors="strict"
            )
        )
        debt = json.loads(
            (root / ARM_BEFORE_TRUST_ROUTE_DEBT_FILE).read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except Exception as exc:
        return [f"authentication compound work missing/malformed: {type(exc).__name__}"]
    issues: list[str] = []
    try:
        known_identities, identity_denominator_digest = (
            _p1m_current_identity_denominator(root)
        )
    except Exception as exc:
        known_identities, identity_denominator_digest = set(), ""
        issues.append(
            "authentication compound identity denominator unavailable: "
            + type(exc).__name__
        )
    for label, payload, schema in (
        (
            "candidates", candidates,
            "plamen.arm_before_trust_compound_candidates.v1",
        ),
        (
            "work authority", plan,
            "plamen.arm_before_trust_compound_work_authority.v1",
        ),
        (
            "route debt", debt,
            "plamen.arm_before_trust_p0af_route_debt.v1",
        ),
    ):
        if not isinstance(payload, Mapping) or payload.get("schema_version") != schema:
            issues.append(f"authentication compound {label} schema mismatch")
            continue
        if payload.get("payload_digest") != _stable_payload_digest(
            {key: value for key, value in payload.items() if key != "payload_digest"}
        ):
            issues.append(f"authentication compound {label} digest mismatch")
        if payload.get("proof_authority") != "NONE":
            issues.append(f"authentication compound {label} granted proof")
    candidate_rows = candidates.get("candidates") if isinstance(candidates, Mapping) else []
    work_plan = plan.get("compound_work_plan") if isinstance(plan, Mapping) else {}
    work_items = work_plan.get("work_items") if isinstance(work_plan, Mapping) else []
    if candidates.get("candidate_count") != len(candidate_rows or []):
        issues.append("authentication compound candidate count mismatch")
    if (
        candidates.get("identity_denominator_artifact")
        != _CANONICAL_FINDING_IDENTITY_FILE
        or candidates.get("identity_denominator_digest")
        != identity_denominator_digest
    ):
        issues.append("authentication compound identity denominator drift")
    if candidates.get("payload_digest") != plan.get("candidate_payload_digest"):
        issues.append("authentication compound plan source digest mismatch")
    ready = sorted(
        str(row.get("subject_id") or "")
        for row in work_items or []
        if isinstance(row, Mapping) and row.get("readiness") == "READY"
    )
    if ready != debt.get("ready_work_item_ids"):
        issues.append("authentication compound route denominator mismatch")
    if bool(ready) != bool(debt.get("ordinary_verification_required")):
        issues.append("authentication compound route requirement mismatch")
    if ready and work_plan.get("schema_version") != "plamen.compound_work_plan.v2":
        issues.append("authentication compound READY work is not typed v2")
    for row in work_items or []:
        if not isinstance(row, Mapping):
            issues.append("authentication compound work item is not an object")
            continue
        if not re.fullmatch(r"CH-\d{1,6}", str(row.get("subject_id") or "")):
            issues.append("authentication compound work identity is not valid CH-N")
        if str(row.get("subject_id") or "") in known_identities:
            issues.append("authentication compound work identity collision")
        if row.get("readiness") != "READY":
            issues.append(
                "authentication compound non-READY work remains at route boundary"
            )
        if not row.get("constituent_authority_bindings"):
            issues.append("authentication compound work lost typed fact bindings")
    if ready and debt.get("status") != "READY_PENDING_QUEUE_DELIVERY":
        issues.append("authentication compound queue delivery debt is not explicit")
    if debt.get("route") != "P0_AF_V2_QUEUE_ADAPTER_REQUIRED":
        issues.append("authentication compound downstream route mismatch")
    return list(dict.fromkeys(issues))


def _run_authentication_chain_consumer_boundary(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> list[str]:
    """Conditionally stage distinct typed composition analysis, never P0-AF."""
    root = Path(scratchpad)
    composition_path = root / authentication_role_authority.COMPOSITION_FILE
    if not composition_path.is_file():
        # The entire P1-M family is absent on a legacy/light boundary. Do not
        # launch an unbound compatibility worker.
        return []
    try:
        composition = json.loads(
            composition_path.read_text(encoding="utf-8", errors="strict")
        )
    except Exception as exc:
        return [f"authentication composition malformed before chain: {exc}"]
    obligations = composition.get("obligations")
    if not isinstance(obligations, list):
        return ["authentication composition obligations is not an array"]
    if not obligations:
        return []
    issues = _run_p1dm_model_work_unit(
        root,
        config,
        phase,
        phase_name="chain",
        work_unit_id="worker.arm_before_trust",
        output=ARM_BEFORE_TRUST_CHAIN_ANALYSIS_FILE,
        prompt=_authentication_chain_prompt(),
        validate=lambda: _validate_authentication_chain_analysis(root),
    )
    if _validate_authentication_chain_analysis(root):
        return list(dict.fromkeys(issues))
    transaction = {
        "phase_name": "chain",
        "work_unit_id": "authentication_roles.compound_work",
        "exact_inputs": (
            ARM_BEFORE_TRUST_CHAIN_ANALYSIS_FILE,
            authentication_role_authority.COMPOSITION_FILE,
            authentication_role_authority.AUTHORITY_FILE,
            _CANONICAL_FINDING_IDENTITY_FILE,
        ),
        "exact_outputs": _ARM_BEFORE_TRUST_COMPOUND_OUTPUTS,
    }
    validate = lambda: _validate_authentication_compound_work_authority(root)  # noqa: E731
    try:
        contract, _launch = _p1dm_contract_and_launch(
            root,
            config,
            actor="DRIVER",
            **transaction,
        )
        work_units = read_artifact_ledger(root).get("work_units")
        replay = isinstance(work_units, Mapping) and contract.key in work_units
    except (ArtifactLedgerError, ValueError, OSError, UnicodeError) as exc:
        issues.append(
            "chain/authentication_roles.compound_work replay selection failed: "
            f"{type(exc).__name__}: {exc}"
        )
    else:
        if replay:
            issues.extend(_validate_existing_p1dm_driver_transaction(
                root,
                config,
                validate=validate,
                **transaction,
            ))
        else:
            issues.extend(_record_p1dm_driver_transaction(
                root,
                config,
                action=lambda: _build_authentication_compound_work_authority(root),
                validate=validate,
                **transaction,
            ))
    # Replay the semantic validator even when the ledger rejected a committed
    # input rebind.  This cannot rewrite the frozen authority, but it makes a
    # newly colliding/drifted identity denominator explicit at the live phase
    # boundary instead of leaving an old READY file as the only visible state.
    issues.extend(_validate_authentication_compound_work_authority(root))
    return list(dict.fromkeys(issues))


def _run_p0af_v2_live_queue_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[bool, list[str]]:
    """Deliver authenticated P1-M work after the legacy queue reaches stability.

    Returns ``(safe_to_shard, issues)``.  A producer precondition debt leaves
    the prior ordinary queue intact and is safe to shard; an interrupted or
    invalid prepared transaction is not consumable and therefore blocks shard
    materialization until deterministic recovery succeeds.
    """

    root = Path(scratchpad)
    if str(config.get("pipeline") or "sc").lower() == "l1":
        return True, []
    route_path = root / ARM_BEFORE_TRUST_ROUTE_DEBT_FILE
    if not route_path.is_file():
        if not p0af_v2_runtime_state_present(root, config):
            return True, []
        validation_issues = validate_p0af_v2_queue_commit(root, config)
        return False, [
            "P0-AF v2 prior transaction lost its authenticated P1-M route"
        ] + validation_issues

    # The legacy composition adapter is an independent producer and must reach
    # its stable result first.  The sharder repeats it later and proves that it
    # cannot mutate the P0-AF-v2 receipt-bound projections.
    _deliver_compound_candidates_to_queue(root, "sc")
    try:
        outcome = run_p0af_v2_queue_delivery(root, config)
    except P0AFV2QueueRuntimeError:
        # Driver-only publish recovery is deterministic and does not retry a
        # model/tool.  One immediate replay closes a fault between fixed-path
        # replacements; another failure remains explicit transaction debt.
        try:
            outcome = run_p0af_v2_queue_delivery(root, config)
        except P0AFV2QueueRuntimeError as exc:
            return False, [f"P0-AF v2 queue transaction unresolved: {exc}"]
    issues = list(outcome.issues)
    transaction_pending = False
    journal_path = root / P0AF_V2_QUEUE_JOURNAL_FILE
    if journal_path.is_file():
        # Once a transaction journal exists, only an issue-free committed
        # successor can authorize the sharder.  A semantically valid committed
        # delivery debt is the one exception: it preserves the ordinary queue
        # and remains fail-visible for human review without infinite rewind.
        valid_delivery_debt = False
        if outcome.status.get("state") == "COMPLETED_WITH_DEBT":
            valid_delivery_debt = not validate_p0af_v2_queue_commit(root, config)
        transaction_pending = bool(issues) and not valid_delivery_debt
        try:
            transaction_pending = transaction_pending or json.loads(
                journal_path.read_text(encoding="utf-8", errors="strict")
            ).get("state") != "COMMITTED"
        except Exception:
            transaction_pending = True
    return not transaction_pending, issues


def _p0af_v2_authorized_external_ids(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[str, ...]:
    status = Path(scratchpad) / P0AF_V2_QUEUE_STATUS_FILE
    if not status.is_file():
        return ()
    try:
        return authorized_p0af_v2_work_item_ids(scratchpad, config)
    except Exception:
        return ()


def _run_authentication_role_boundary(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> list[str]:
    """Stage the EVM-only typed role worker and disjoint driver authorities."""
    root = Path(scratchpad)
    ecosystem = re.sub(
        r"[^a-z0-9_]+", "", str(config.get("language") or "").lower()
    )
    issues: list[str] = []
    if ecosystem == "evm":
        issues.extend(_run_p1dm_model_work_unit(
            root,
            config,
            phase,
            phase_name="depth",
            work_unit_id="worker.authentication_role_facts",
            output=authentication_role_authority.TRACE_FILE,
            prompt=_authentication_role_prompt(),
            validate=lambda: _validate_authentication_role_trace(root),
        ))
    fact_inputs = (
        () if ecosystem == "evm" else ("_v2_checkpoint.json",)
    )
    issues.extend(_record_p1dm_driver_transaction(
        root,
        config,
        phase_name="depth",
        work_unit_id="authentication_roles.fact_authority",
        exact_inputs=fact_inputs,
        action=lambda: authentication_role_authority.write_authentication_role_fact_authority(
            root,
            ecosystem=ecosystem,
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
        ),
        validate=lambda: authentication_role_authority.validate_authentication_role_fact_authority(
            root,
            ecosystem=ecosystem,
            mode=str(config.get("mode") or ""),
            run_id=str(config.get("_run_id") or ""),
        ),
    ))
    # Composition consumes only the immutable fact authority.  It never reads
    # the model trace or any free-form compatibility prose.
    issues.extend(_record_p1dm_driver_transaction(
        root,
        config,
        phase_name="depth",
        work_unit_id="authentication_roles.composition",
        action=lambda: authentication_role_authority.write_authentication_role_composition(
            root
        ),
        validate=lambda: authentication_role_authority.validate_authentication_role_composition(
            root
        ),
    ))
    try:
        research = json.loads(
            (root / authentication_role_authority.EXTERNAL_RESEARCH_FILE)
            .read_text(encoding="utf-8", errors="strict")
        )
        research_count = int(research.get("obligation_count") or 0)
    except Exception:
        research_count = 0
    if research_count:
        issues.append(
            f"{research_count} authentication external research obligation(s) "
            "remain UNKNOWN; favorable or adverse external semantics are not "
            "asserted and the obligations require governed research/human review"
        )
    return list(dict.fromkeys(issues))


def _precedent_run_binding(config: Mapping[str, Any]) -> tuple[str, str]:
    run_id = str(config.get("_run_id") or "").strip()
    snapshot_digest = _security_obligation_source_snapshot_digest(config)
    return run_id, snapshot_digest


def _load_validated_precedent_facts(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Load only a current, provider-derived P1-F fact denominator."""

    root = Path(scratchpad)
    run_id, snapshot_digest = _precedent_run_binding(config)
    payload = precedent_evidence_authority.read_canonical_json_artifact(
        root / precedent_finding_fact_provider.FACTS_NAME
    )
    issues = precedent_finding_fact_provider.validate_precedent_finding_facts(
        payload,
        root,
        run_id=run_id,
        snapshot_digest=snapshot_digest,
    )
    if issues:
        raise ValueError("; ".join(issues))
    return payload


def _prepare_precedent_facts_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Build and exact-bind precedent facts before research prompt rendering."""

    root = Path(scratchpad)
    run_id, snapshot_digest = _precedent_run_binding(config)
    return _record_p1dm_driver_transaction(
        root,
        config,
        phase_name="rag_sweep",
        work_unit_id="precedent_facts",
        exact_inputs=("finding_records.json", "findings_inventory.md"),
        exact_outputs=(precedent_finding_fact_provider.FACTS_NAME,),
        action=lambda: precedent_finding_fact_provider.write_precedent_finding_facts(
            root,
            run_id=run_id,
            snapshot_digest=snapshot_digest,
        ),
        validate=lambda: precedent_finding_fact_provider.validate_precedent_finding_facts(
            precedent_evidence_authority.read_canonical_json_artifact(
                root / precedent_finding_fact_provider.FACTS_NAME
            ),
            root,
            run_id=run_id,
            snapshot_digest=snapshot_digest,
        ),
    )


def _normalize_precedent_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    root = Path(scratchpad)

    def action() -> None:
        facts = _load_validated_precedent_facts(root, config)
        precedent_evidence_authority.write_precedent_proposal_artifact(root, facts)

    def validate() -> list[str]:
        facts = _load_validated_precedent_facts(root, config)
        return precedent_evidence_authority.validate_precedent_proposal_artifact(
            root, facts
        )

    return _record_p1dm_driver_transaction(
        root,
        config,
        phase_name="rag_sweep",
        work_unit_id="precedent_normalize",
        exact_inputs=(precedent_finding_fact_provider.FACTS_NAME, "rag_validation.md"),
        exact_outputs=(precedent_evidence_authority.PROPOSALS_NAME,),
        action=action,
        validate=validate,
    )


def _reconcile_precedent_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    root = Path(scratchpad)

    def inputs() -> tuple[dict[str, Any], dict[str, Any]]:
        facts = _load_validated_precedent_facts(root, config)
        proposals = precedent_evidence_authority.read_canonical_json_artifact(
            root / precedent_evidence_authority.PROPOSALS_NAME
        )
        proposal_issues = (
            precedent_evidence_authority.validate_precedent_proposal_artifact(
                root, facts
            )
        )
        if proposal_issues:
            raise ValueError("; ".join(proposal_issues))
        return facts, proposals

    def action() -> None:
        facts, proposals = inputs()
        # No source-evidence artifact is accepted here until a neutral driver
        # capture unit safe-resolves and hashes the actual bounded source bytes.
        precedent_evidence_authority.write_precedent_evidence_artifacts(
            root, facts, proposals, source_evidence_artifact=None
        )

    def validate() -> list[str]:
        facts, proposals = inputs()
        payload = precedent_evidence_authority.read_canonical_json_artifact(
            root / precedent_evidence_authority.AUTHORITY_NAME
        )
        return precedent_evidence_authority.validate_precedent_evidence_artifacts(
            root,
            payload,
            facts,
            proposals,
            source_evidence_artifact=None,
        )

    return _record_p1dm_driver_transaction(
        root,
        config,
        phase_name="rag_sweep",
        work_unit_id="precedent_reconcile",
        exact_inputs=(
            precedent_evidence_authority.PROPOSALS_NAME,
            precedent_finding_fact_provider.FACTS_NAME,
        ),
        exact_outputs=(
            precedent_evidence_authority.AUTHORITY_NAME,
            precedent_evidence_authority.CONTEXT_NAME,
            precedent_evidence_authority.REPORT_CONTEXT_NAME,
        ),
        action=action,
        validate=validate,
    )


def _finalize_precedent_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Normalize and reconcile accepted model transport without decision power."""

    issues = _normalize_precedent_boundary(scratchpad, config)
    issues.extend(_reconcile_precedent_boundary(scratchpad, config))
    return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))


def _prepare_precedent_consumer_boundary(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Repair-or-omit P1-F projections before a model consumer can bind.

    Raw research is never a fallback.  If current facts, normalized proposals,
    authority, projections, or producer receipts cannot be reconciled, both
    legacy projection paths are atomically neutralized and excluded from the
    exact chain/report input denominator.  This is haltless without permitting
    a stale positive or refuting source to become current model evidence.
    """

    if phase.name not in {"chain_agent2", "chain_iter2", "report_index"}:
        return []
    state = config.setdefault("_precedent_consumer_projection_state", {})
    if str(config.get("mode") or "").strip().lower() == "light":
        state[phase.name] = False
        return []

    root = Path(scratchpad)
    issues: list[str] = []
    issues.extend(_prepare_precedent_facts_boundary(root, config))
    issues.extend(_finalize_precedent_boundary(root, config))
    if not issues:
        try:
            facts = _load_validated_precedent_facts(root, config)
            proposals = precedent_evidence_authority.read_canonical_json_artifact(
                root / precedent_evidence_authority.PROPOSALS_NAME
            )
            proposal_issues = (
                precedent_evidence_authority.validate_precedent_proposal_artifact(
                    root, facts
                )
            )
            if proposal_issues:
                issues.extend(proposal_issues)
            payload = precedent_evidence_authority.read_canonical_json_artifact(
                root / precedent_evidence_authority.AUTHORITY_NAME
            )
            issues.extend(
                precedent_evidence_authority.validate_precedent_evidence_artifacts(
                    root,
                    payload,
                    facts,
                    proposals,
                    source_evidence_artifact=None,
                )
            )
        except (OSError, UnicodeError, ValueError) as exc:
            issues.append(
                "precedent consumer authority validation failed: "
                f"{type(exc).__name__}: {exc}"
            )

    if issues:
        state[phase.name] = False
        try:
            precedent_evidence_authority.neutralize_precedent_consumer_projections(
                root
            )
        except OSError as exc:
            issues.append(f"precedent projection neutralization failed: {exc}")
        return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))

    state[phase.name] = True
    return []


def _precedent_model_input_receipt_issues(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Return debt unless rag output was preceded by its exact input binding."""

    try:
        contract, launch = _typed_model_phase_contract_and_launch(
            phase, Path(scratchpad), config
        )
        if contract is None or launch is None:
            return ["precedent research model contract is unavailable"]
        return validate_work_unit_inputs(
            Path(scratchpad),
            Path(config.get("project_root") or Path(scratchpad).parent),
            contract,
            launch,
            run_id=str(config.get("_run_id") or ""),
        )
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        return [f"precedent research input receipt invalid: {exc}"]


def _validated_attempt_map(
    config: Mapping[str, Any], key: str
) -> Mapping[str, int]:
    """Return one exact JSON string->nonnegative-integer attempt map.

    ``bool`` is an ``int`` subclass in Python, but it is a distinct JSON type.
    These maps can survive in checkpoint-backed configuration and influence
    retry, quarantine, and work-unit identity.  Validate the entire map before
    selecting any counter so an unrelated malformed entry cannot remain latent
    until a later phase.
    """

    raw = config.get(key)
    if raw is None:
        return {}
    if not isinstance(raw, Mapping):
        raise ArtifactLedgerError(f"{key} attempt map must be an object")
    for phase_name, value in raw.items():
        if (
            not isinstance(phase_name, str)
            or not phase_name
            or type(value) is not int
            or value < 0
        ):
            raise ArtifactLedgerError(
                f"{key} attempt map values must be exact nonnegative integers"
            )
    return raw


def _mutable_attempt_map(config: dict[str, Any], key: str) -> dict[str, int]:
    """Validate and return a mutable attempt map without normalizing debt."""

    raw = config.setdefault(key, {})
    _validated_attempt_map(config, key)
    if not isinstance(raw, dict):
        raise ArtifactLedgerError(f"{key} attempt map must be mutable")
    return raw


def _attempt_map_ordinal(
    config: Mapping[str, Any],
    key: str,
    phase_name: str,
    *,
    default: int,
    minimum: int = 0,
) -> int:
    attempts = _validated_attempt_map(config, key)
    value = attempts.get(phase_name, default)
    if value < minimum:
        raise ArtifactLedgerError(
            f"{key} attempt ordinal must be an integer >= {minimum}"
        )
    return value


def _exact_attempt_ordinal(value: Any, *, label: str) -> int:
    if type(value) is not int or value < 1:
        raise ArtifactLedgerError(f"{label} attempt must be a positive integer")
    return value


def _report_index_model_attempt_ordinal(
    scratchpad: Path, config: dict[str, Any]
) -> int:
    """Recover the immutable report-index MODEL attempt identity on resume."""

    attempts = _mutable_attempt_map(config, "_phase_io_model_attempts")
    configured = _attempt_map_ordinal(
        config,
        "_phase_io_model_attempts",
        "report_index",
        default=0,
    )
    if configured >= 1:
        return configured
    highest = 0
    try:
        ledger = read_artifact_ledger(Path(scratchpad))
        run_id = str(config.get("_run_id") or "")
        expected_prefix = (
            str(config.get("pipeline") or "sc").lower(),
            str(config.get("mode") or "core").lower(),
            str(config.get("language") or "unknown").lower(),
            str(config.get("cli_backend") or "claude").lower(),
            "report_index",
        )
        for key, unit in ledger.get("work_units", {}).items():
            if (
                not isinstance(unit, Mapping)
                or unit.get("run_id") != run_id
                or unit.get("model_invoked") is not True
            ):
                continue
            parts = str(key).split("/")
            if len(parts) != 6 or tuple(parts[:5]) != expected_prefix:
                continue
            if parts[5] == "model":
                highest = max(highest, 1)
                continue
            match = re.fullmatch(r"model\.attempt-(\d{4})", parts[5])
            if match is not None:
                highest = max(highest, int(match.group(1)))
    except (ArtifactLedgerError, OSError, TypeError, ValueError):
        highest = 0
    attempts["report_index"] = max(1, highest)
    return attempts["report_index"]


def _exact_existing_model_inputs(
    scratchpad: Path,
    *,
    required: Sequence[str] = (),
    optional: Sequence[str] = (),
    project_root: Path | None = None,
) -> tuple[str, ...]:
    """Return one traversal-free, non-symlink semantic input denominator."""

    root = Path(scratchpad)
    selected: set[str] = set()
    missing: list[str] = []
    for raw in (*required, *optional):
        value = str(raw or "").strip().replace("\\", "/")
        is_project = value.startswith("project::")
        relative = value[len("project::"):] if is_project else value
        candidate = Path(relative)
        if (
            not relative
            or candidate.is_absolute()
            or ".." in candidate.parts
            or candidate.as_posix() != relative
        ):
            raise ArtifactLedgerError(
                f"model input identity is not canonical: {value!r}"
            )
        base = (
            Path(project_root if project_root is not None else root.parent)
            if is_project
            else root
        )
        path = base / relative
        exists = path.is_file() and not path.is_symlink()
        if value in required and not exists:
            missing.append(value)
        elif exists:
            selected.add(value)
    if missing:
        raise ArtifactLedgerError(
            "exact model input denominator is unavailable: "
            + ", ".join(sorted(missing))
        )
    return tuple(sorted(selected))


def _postverify_extract_exact_inputs(scratchpad: Path) -> tuple[str, ...]:
    root = Path(scratchpad)
    verify_files = tuple(sorted(
        path.relative_to(root).as_posix()
        for path in root.glob("verify_*.md")
        if path.is_file() and not path.is_symlink()
    ))
    if not verify_files:
        raise ArtifactLedgerError(
            "post_verify_extract has no exact verify-file denominator"
        )
    return _exact_existing_model_inputs(
        root,
        required=(
            "findings_inventory.md",
            "hypotheses.md",
            "verification_queue.md",
            *verify_files,
        ),
    )


def _skeptic_exact_inputs(scratchpad: Path) -> tuple[str, ...]:
    """Bind the manifest-named verifier set plus its mechanical authority."""

    root = Path(scratchpad)
    manifest_path = root / "skeptic_manifest.json"
    try:
        payload = json.loads(
            manifest_path.read_text(encoding="utf-8", errors="strict")
        )
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
    ) as exc:
        raise ArtifactLedgerError(
            f"skeptic manifest is unavailable or invalid: {exc}"
        ) from exc
    rows = payload.get("findings")
    if not isinstance(rows, list):
        raise ArtifactLedgerError("skeptic manifest findings must be a list")
    if payload.get("required_count") != len(rows):
        raise ArtifactLedgerError(
            "skeptic manifest required_count disagrees with findings"
        )
    verify_files: set[str] = set()
    companion_inputs: set[str] = set()
    for row in rows:
        if not isinstance(row, Mapping):
            raise ArtifactLedgerError("skeptic manifest row is not an object")
        relative = str(row.get("verify_file") or "").strip().replace("\\", "/")
        if not re.fullmatch(r"verify_[A-Za-z0-9_.-]+\.md", relative):
            raise ArtifactLedgerError(
                f"skeptic manifest verify_file is invalid: {relative!r}"
            )
        verify_files.add(relative)
        stem = relative[:-3]
        for suffix in (
            ".identity.json",
            ".receipt.json",
            ".severity_proposal.json",
            ".mechanical_successor.receipt.json",
            ".execution_scope_assessment.json",
            ".execution_scope_runtime_source.json",
            ".execution_scope_evidence.json",
        ):
            candidate = f"{stem}{suffix}"
            if (root / candidate).is_file() and not (root / candidate).is_symlink():
                companion_inputs.add(candidate)
    optional = {
        "verdict_manifest.json",
        "mechanical_verify_manifest.json",
        "mechanical_successor_authority.json",
        "verify_core.md",
        *companion_inputs,
    }
    return _exact_existing_model_inputs(
        root,
        required=(
            "skeptic_manifest.json",
            "verification_queue.md",
            *sorted(verify_files),
        ),
        optional=tuple(sorted(optional)),
    )


def _crossbatch_exact_inputs(scratchpad: Path) -> tuple[str, ...]:
    """Bind every manifest-named verifier and optional comparison authority."""

    root = Path(scratchpad)
    manifest_path = root / "crossbatch_manifest.json"
    try:
        payload = json.loads(
            manifest_path.read_text(encoding="utf-8", errors="strict")
        )
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
    ) as exc:
        raise ArtifactLedgerError(
            f"crossbatch manifest is unavailable or invalid: {exc}"
        ) from exc
    rows = payload.get("findings")
    if not isinstance(rows, list):
        raise ArtifactLedgerError("crossbatch manifest findings must be a list")
    if payload.get("required_count") != len(rows):
        raise ArtifactLedgerError(
            "crossbatch manifest required_count disagrees with findings"
        )
    verify_files: set[str] = set()
    for row in rows:
        if not isinstance(row, Mapping):
            raise ArtifactLedgerError("crossbatch manifest row is not an object")
        relative = str(row.get("verify_file") or "").strip().replace("\\", "/")
        if not re.fullmatch(r"verify_[A-Za-z0-9_.-]+\.md", relative):
            raise ArtifactLedgerError(
                f"crossbatch manifest verify_file is invalid: {relative!r}"
            )
        verify_files.add(relative)
    optional = {
        "verify_core.md",
        "skeptic_findings.md",
        "skeptic_judge_decisions.md",
        "dedup_candidate_pairs.md",
        *(
            path.relative_to(root).as_posix()
            for path in root.glob("judge_*.md")
            if path.is_file() and not path.is_symlink()
        ),
    }
    return _exact_existing_model_inputs(
        root,
        required=("crossbatch_manifest.json", *sorted(verify_files)),
        optional=tuple(sorted(optional)),
    )


def _instantiate_exact_inputs(scratchpad: Path) -> tuple[str, ...]:
    """Bind the complete mechanically accepted recon handoff."""

    return _exact_existing_model_inputs(
        Path(scratchpad),
        required=(
            "skill_selection_catalog.json",
            "template_recommendations.md",
            "detected_patterns.md",
            "design_context.md",
            "attack_surface.md",
            "contract_inventory.md",
            "function_list.md",
            "state_variables.md",
        ),
        optional=(
            "recon_summary.md",
            "external_dependency_research.md",
            "recon_signal_transform_receipt.json",
        ),
    )


def _typed_model_phase_contract_and_launch(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> tuple[Any, LaunchSpec] | tuple[None, None]:
    """Resolve the exact contract shared by prompt, prelaunch, and commit."""
    is_report_body = phase.name.startswith("report_body_writer_")
    is_inventory_chunk = phase.name in {
        "inventory_chunk_a",
        "inventory_chunk_b",
        "inventory_chunk_c",
    }
    recon_direct_retry_authority = (
        _pending_recon_direct_retry_authority(Path(scratchpad), config)
        if phase.name == "recon"
        else None
    )
    is_recon_direct_retry = isinstance(
        recon_direct_retry_authority, Mapping
    )
    if phase.name not in {
        "instantiate",
        "inventory", "invariants", "invariants_p2", "chain_agent2", "chain_iter2",
        "chain", "rag_sweep", "report_index", "exploration_skeptic",
        "enumgap_exploration", "axis_coverage",
        "semantic_dedup", "sc_semantic_dedup",
        "post_verify_extract", "skeptic", "crossbatch", "report_dedup_agent",
        "report_disposition",
    } and not is_report_body and not is_inventory_chunk and not is_recon_direct_retry:
        return None, None
    exact_inputs: tuple[str, ...] = ()
    if is_recon_direct_retry:
        exact_inputs = _exact_existing_model_inputs(
            Path(scratchpad), required=("recon_retry_plan.json",)
        )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "instantiate":
        exact_inputs = _instantiate_exact_inputs(Path(scratchpad))
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if is_inventory_chunk:
        payload = _reconcile_exact_inventory(
            Path(scratchpad), phase_name=phase.name, persist=False
        )
        exact_inputs = tuple(sorted({
            str(row.get("artifact") or "")
            for collection in (
                payload.get("source_artifacts") or [],
                payload.get("manifest_artifacts") or [],
            )
            for row in collection
            if isinstance(row, Mapping)
            and str(row.get("artifact") or "")
        }))
        manifest_name = f"{phase.name}.manifest.md"
        if manifest_name not in exact_inputs:
            raise ArtifactLedgerError(
                f"{phase.name}: exact shard manifest is unavailable"
            )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name in {"exploration_skeptic", "enumgap_exploration"}:
        root = Path(scratchpad)
        own_output = set(phase.expected_artifacts)
        mandatory = (
            ("enumgap_worklist.json",)
            if phase.name == "enumgap_exploration"
            else ()
        )
        role_patterns = (
            "findings_inventory.md",
            "confidence_scores.md",
            "consensus_map.md",
            "semantic_invariants.md",
            "depth*.md",
            "niche*.md",
            "blind_spot*.md",
            "coverage*.md",
            "_canonical_finding_ids.json",
            "_enumeration_obligations.json",
            "enumeration_obligations.md",
            "exploration_clear_prior_aliases.json",
            "exploration_clear_receipt.json",
            "exploration_clear_obligations.json",
        )
        discovered = {
            path.relative_to(root).as_posix()
            for pattern in role_patterns
            for path in root.glob(pattern)
            if path.is_file()
            and path.relative_to(root).as_posix() not in own_output
        }
        exact_inputs = tuple(sorted({*mandatory, *discovered}))
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "axis_coverage":
        exact_inputs = _axis_disposition_exact_inputs(
            Path(scratchpad),
            work_unit_id="model",
        )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "inventory":
        exact_inputs = tuple(sorted({
            path.relative_to(Path(scratchpad)).as_posix()
            for pattern in (
                "findings_inventory_chunk_*.md",
                "inventory_chunk_*.manifest.md",
                "inventory_shard_plan.md",
            )
            for path in Path(scratchpad).glob(pattern)
            if path.is_file()
        }))
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "post_verify_extract":
        exact_inputs = _postverify_extract_exact_inputs(Path(scratchpad))
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "skeptic":
        exact_inputs = _skeptic_exact_inputs(Path(scratchpad))
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "crossbatch":
        exact_inputs = _crossbatch_exact_inputs(Path(scratchpad))
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "report_dedup_agent":
        exact_inputs = _exact_existing_model_inputs(
            Path(scratchpad),
            required=(
                "project::AUDIT_REPORT.md",
                "report_index.md",
                "finding_mapping.md",
                "report_dedup_candidate_pairs.json",
            ),
            optional=("report_dedup_candidate_pairs.md",),
            project_root=Path(config.get("project_root") or scratchpad.parent),
        )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "report_disposition":
        exact_inputs = _exact_existing_model_inputs(
            Path(scratchpad),
            required=("project::AUDIT_REPORT.md",),
            project_root=Path(config.get("project_root") or scratchpad.parent),
        )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name in {"semantic_dedup", "sc_semantic_dedup"}:
        root = Path(scratchpad)
        if phase.name == "semantic_dedup":
            # L1's live packet has one typed DRIVER owner.  Legacy round files
            # are incidental compatibility telemetry and must not replace or
            # mutate this exact model denominator.
            packet_paths = [
                name
                for name in (
                    "dedup_blocks.md",
                    "dedup_candidate_pairs.md",
                )
                if (root / name).is_file()
                and not (root / name).is_symlink()
            ]
            focus_paths = [
                "dedup_focus_inventory.md"
            ] if (
                (root / "dedup_focus_inventory.md").is_file()
                and not (root / "dedup_focus_inventory.md").is_symlink()
            ) else []
        else:
            round_pairs = sorted(
                root.glob("dedup_candidate_pairs_round*.md"),
                key=lambda path: _dedup_round_index(path.name),
            )
            if round_pairs:
                packet_paths = [
                    path.relative_to(root).as_posix()
                    for path in round_pairs
                    if path.is_file() and not path.is_symlink()
                ]
                focus_paths = [
                    path.relative_to(root).as_posix()
                    for path in sorted(
                        root.glob("dedup_focus_inventory_round*.md"),
                        key=lambda path: _dedup_round_index(path.name),
                    )
                    if path.is_file() and not path.is_symlink()
                ]
            else:
                packet_paths = [
                    "dedup_candidate_pairs.md"
                ] if (root / "dedup_candidate_pairs.md").is_file() else []
                focus_paths = [
                    "dedup_focus_inventory.md"
                ] if (root / "dedup_focus_inventory.md").is_file() else []
        exact_inputs = tuple((*packet_paths, *focus_paths))
        if (
            phase.name == "semantic_dedup"
            and set(exact_inputs)
            != {
                "dedup_blocks.md",
                "dedup_candidate_pairs.md",
                "dedup_focus_inventory.md",
            }
        ):
            raise ArtifactLedgerError(
                "semantic_dedup: exact typed block/pair/focus packet is "
                "incomplete"
            )
        if not packet_paths:
            raise ArtifactLedgerError(
                f"{phase.name}: exact bounded candidate packet is unavailable"
            )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "rag_sweep":
        exact_inputs = (
            "build_status.md",
            "findings_inventory.md",
            precedent_finding_fact_provider.FACTS_NAME,
        )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name in {"chain_agent2", "chain_iter2"}:
        static = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase=phase.name,
            work_unit_id="model",
        )
        precedent_available = bool(
            config.get("_precedent_consumer_projection_state", {}).get(
                phase.name, False
            )
        )
        exact_inputs = tuple(
            identity.split(":", 1)[1]
            for identity in static.immutable_inputs
            if (
                identity.split(":", 1)[1]
                != precedent_evidence_authority.CONTEXT_NAME
                or precedent_available
            )
        )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "chain":
        root = Path(scratchpad)
        mandatory = {
            "_v2_checkpoint.json",
            "findings_inventory.md",
            "chain_summaries_compact.md",
            "attack_surface.md",
            "chain_enabler_baseline.md",
        }
        optional = {
            "confidence_scores.md",
            *(
                path.relative_to(root).as_posix()
                for path in root.glob("depth_*_findings.md")
                if path.is_file() and not path.is_symlink()
            ),
        }
        exact_inputs = tuple(sorted({
            *mandatory,
            *(
                relative
                for relative in optional
                if (root / relative).is_file()
            ),
        }))
        missing = sorted(
            relative for relative in mandatory
            if not (root / relative).is_file()
        )
        if missing:
            raise ArtifactLedgerError(
                "chain/model exact semantic denominator is unavailable: "
                + ", ".join(missing)
            )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if phase.name == "report_index":
        r10_consumer_issues = _r10_report_consumer_ready_issues(
            Path(scratchpad), config
        )
        if r10_consumer_issues:
            raise ArtifactLedgerError(
                "report_index/model R10 consumer authority is invalid: "
                + "; ".join(r10_consumer_issues[:8])
            )
        static = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase=phase.name,
            work_unit_id="model",
        )
        optional = {
            "severity_binding.md", "status_binding.md",
            "external_research_gaps.md",
            precedent_evidence_authority.REPORT_CONTEXT_NAME,
            security_obligation_authority.FEATURE_FACT_FILE,
            security_obligation_authority.AUTHORITY_FILE,
            security_obligation_authority.PROJECTION_FILE,
            security_obligation_lifecycle.AUTHORITY_FILE,
            security_obligation_lifecycle.PROJECTION_FILE,
            security_obligation_lifecycle.REPORT_RETENTION_FILE,
        }
        lifecycle_inputs = {
            security_obligation_lifecycle.AUTHORITY_FILE,
            security_obligation_lifecycle.PROJECTION_FILE,
            security_obligation_lifecycle.REPORT_RETENTION_FILE,
        }
        lifecycle_ready = bool(
            config.get(
                "_security_obligation_lifecycle_consumer_state", {}
            ).get(phase.name, False)
        )
        exact_inputs = tuple(
            identity.split(":", 1)[1]
            for identity in static.immutable_inputs
            if (
                identity.split(":", 1)[1] not in optional
                or (
                    identity.split(":", 1)[1] in lifecycle_inputs
                    and lifecycle_ready
                    and (
                        Path(scratchpad) / identity.split(":", 1)[1]
                    ).is_file()
                )
                or (
                    identity.split(":", 1)[1]
                    == precedent_evidence_authority.REPORT_CONTEXT_NAME
                    and bool(
                        config.get(
                            "_precedent_consumer_projection_state", {}
                        ).get(phase.name, False)
                    )
                )
                or (
                    identity.split(":", 1)[1]
                    not in {
                        precedent_evidence_authority.REPORT_CONTEXT_NAME,
                        *lifecycle_inputs,
                    }
                    and (
                        Path(scratchpad) / identity.split(":", 1)[1]
                    ).is_file()
                )
            )
        )
        exact_inputs = tuple(dict.fromkeys((
            *exact_inputs,
            *_report_candidate_input_paths(
                Path(scratchpad),
                run_id=str(config.get("_run_id") or "") or None,
            ),
            *(
                (BB_POLICY_REPORT_RECONCILIATION_PATH,)
                if bool(
                    config.get("_bb_policy_report_projection_ready")
                )
                else ()
            ),
        )))
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    if is_report_body:
        try:
            validate_report_evidence_runtime(Path(scratchpad))
        except (OSError, ReportEvidenceError, ValueError) as exc:
            raise ArtifactLedgerError(
                f"report body typed evidence authority is invalid: {exc}"
            ) from exc
        shard = "report_" + phase.name[len("report_body_writer_") :]
        body_manifest = f"body_manifests/{shard}.json"
        typed_manifest = f"report_evidence_manifests/{shard}.json"
        body_path = Path(scratchpad) / body_manifest
        typed_path = Path(scratchpad) / typed_manifest
        if not body_path.is_file() or not typed_path.is_file():
            raise ArtifactLedgerError(
                f"report body model source manifests are unavailable for {shard}"
            )
        try:
            manifest = json.loads(
                body_path.read_text(encoding="utf-8", errors="strict")
            )
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ArtifactLedgerError(
                f"report body model manifest is invalid for {shard}: {exc}"
            ) from exc
        verify_files: set[str] = set()
        runtime_debt_inputs: set[str] = set()
        for row in manifest.get("findings") or []:
            if not isinstance(row, Mapping):
                raise ArtifactLedgerError(
                    f"report body model manifest row is invalid for {shard}"
                )
            raw_files = row.get("verify_files") or (
                [row.get("verify_file")] if row.get("verify_file") else []
            )
            for raw in raw_files:
                relative = str(raw or "").strip().replace("\\", "/")
                candidate = Path(relative)
                if (
                    not relative
                    or candidate.is_absolute()
                    or ".." in candidate.parts
                    or not re.fullmatch(r"verify_[A-Za-z0-9_.-]+\.md", relative)
                ):
                    raise ArtifactLedgerError(
                        f"report body model verifier input is invalid: {relative!r}"
                    )
                if (Path(scratchpad) / relative).is_file():
                    verify_files.add(relative)
                    continue
                debt = row.get("verification_runtime_debt")
                if (
                    not isinstance(debt, Mapping)
                    or debt.get("artifact") != _DYNAMIC_VERIFIER_DEBT_NAME
                    or not (Path(scratchpad) / _DYNAMIC_VERIFIER_DEBT_NAME).is_file()
                ):
                    raise ArtifactLedgerError(
                        "report body model verifier input is absent without "
                        f"exact runtime-debt retention: {relative!r}"
                    )
                runtime_debt_inputs.add(_DYNAMIC_VERIFIER_DEBT_NAME)
        exact_inputs = tuple(
            sorted({
                body_manifest,
                typed_manifest,
                *verify_files,
                *runtime_debt_inputs,
            })
        )
        config.setdefault("_phase_io_exact_inputs", {})[phase.name] = list(
            exact_inputs
        )
    runtime = _live_phase_runtime_launch_policy(phase, scratchpad, config)
    report_index_attempt = (
        _report_index_model_attempt_ordinal(Path(scratchpad), config)
        if phase.name == "report_index"
        else 1
    )
    work_unit_id = (
        "direct_retry.attempt-"
        f"{_attempt_map_ordinal(config, '_active_model_attempts', phase.name, default=0, minimum=2):04d}"
        if is_recon_direct_retry
        else
        "worker.semantic_invariants"
        if phase.name == "invariants"
        else "worker.semantic_invariants_pass2"
        if phase.name == "invariants_p2"
        else "model." + "report_" + phase.name[len("report_body_writer_") :]
        if is_report_body
        else "precedent_research"
        if phase.name == "rag_sweep"
        else (
            "model"
            if report_index_attempt == 1
            else f"model.attempt-{report_index_attempt:04d}"
        )
        if phase.name == "report_index"
        else (
            "model.attempt"
            f"{_attempt_map_ordinal(config, '_phase_io_model_attempts', phase.name, default=1, minimum=1):04d}"
        )
        if is_inventory_chunk
        else (
            "model"
            if _attempt_map_ordinal(
                config,
                "_active_model_attempts",
                phase.name,
                default=1,
                minimum=1,
            ) <= 1
            else "model.attempt-"
            f"{_attempt_map_ordinal(config, '_active_model_attempts', phase.name, default=1, minimum=1):04d}"
        )
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(runtime["backend"]),
        phase="report_body" if is_report_body else phase.name,
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
        exact_outputs=(
            ("spawn_manifest_proposal.md",)
            if phase.name == "instantiate"
            else recon_direct_retry_output_paths(
                str(config.get("pipeline") or "sc"),
                _attempt_map_ordinal(
                    config,
                    "_active_model_attempts",
                    phase.name,
                    default=0,
                    minimum=2,
                ),
            )
            if is_recon_direct_retry
            else tuple(phase.expected_artifacts)
            if (
                is_report_body
                or phase.name in {"rag_sweep", "chain"}
                or phase.name in {
                    "semantic_dedup", "sc_semantic_dedup",
                }
                or phase.name == "axis_coverage"
                or phase.name in {
                    "post_verify_extract", "skeptic", "crossbatch",
                    "report_dedup_agent", "report_disposition",
                }
                or is_inventory_chunk
            )
            else ()
        ),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model=str(runtime["model"]),
        timeout_s=int(runtime["timeout_s"]),
        exec_mode=str(runtime["exec_mode"]),
        tool_policy=(
            ("filesystem", "mcp", "network")
            if (
                phase.needs_mcp
                and contract.backend == "claude"
                and str(runtime["exec_mode"]).lower() == "headless"
            )
            else (
                ("filesystem", "network")
                if phase.needs_mcp
                else ("filesystem",)
            )
        ),
    )
    return contract, launch


_INSTANTIATE_RECONCILE_RECEIPT = (
    "instantiate_manifest_reconcile_receipt.json"
)
_INSTANTIATE_RECONCILE_SCHEMA = (
    "plamen.instantiate_manifest_reconcile.v1"
)
_INSTANTIATE_ATTEMPT_RECEIPT = (
    "_attempt_history/instantiate/transition_receipt.json"
)
_INSTANTIATE_ATTEMPT_SCHEMA = "plamen.instantiate_attempt_transition.v1"


def _instantiate_attempt_receipt_digest(payload: Mapping[str, Any]) -> str:
    unsigned = {
        key: value for key, value in payload.items()
        if key != "receipt_digest"
    }
    return hashlib.sha256(
        json.dumps(
            unsigned,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _instantiate_history_path(root: Path, attempt: int) -> Path:
    ordinal = _exact_attempt_ordinal(
        attempt, label="instantiate history attempt"
    )
    relative = (
        f"_attempt_history/instantiate/model-attempt-{ordinal:04d}/"
        "spawn_manifest_proposal.md"
    )
    return rooted_io.safe_descendant(
        Path(root),
        relative,
        label="instantiate proposal history",
        allow_missing=True,
    )


def _instantiate_history_record(
    scratchpad: Path,
    *,
    attempt: int,
) -> dict[str, Any]:
    root = Path(scratchpad)
    destination = _instantiate_history_path(root, attempt)
    if not rooted_io.lexists(destination):
        return {
            "attempt": int(attempt),
            "state": "ABSENT",
            "path": "",
            "sha256": "",
            "size": 0,
        }
    raw = rooted_io.read_bytes(
        destination,
        label="instantiate archived proposal",
        require_single_link=True,
    )
    return {
        "attempt": int(attempt),
        "state": "ARCHIVED",
        "path": destination.relative_to(root).as_posix(),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "size": len(raw),
    }


def _archive_instantiate_retry_proposal(
    scratchpad: Path,
    *,
    prior_attempt: int,
) -> tuple[list[str], list[str]]:
    """Move a prior MODEL proposal into immutable attempt-scoped history.

    Instantiate proposals cannot use the generic retry quarantine: that helper
    intentionally leaves sub-500-byte stubs live and later restores/deletes
    backups using size heuristics.  Both behaviors are unsafe for a typed MODEL
    output.  Archive every regular proposal byte-for-byte before the next
    attempt is armed, regardless of size, and never feed this history through
    generic retry cleanup.
    """

    root = Path(scratchpad)
    source = root / "spawn_manifest_proposal.md"
    try:
        ordinal = _exact_attempt_ordinal(
            prior_attempt, label="instantiate prior attempt"
        )
        source = rooted_io.safe_descendant(
            root,
            "spawn_manifest_proposal.md",
            label="instantiate live proposal",
            allow_missing=True,
        )
        destination = _instantiate_history_path(root, ordinal)
        rooted_io.ensure_directory(
            destination.parent,
            parents=True,
            label="instantiate attempt history parent",
        )
        stage = rooted_io.safe_descendant(
            root,
            f"_.instantiate-proposal-attempt-{ordinal:04d}.stage",
            label="instantiate proposal archive stage",
            allow_missing=True,
        )
        source_present = rooted_io.lexists(source)
        stage_present = rooted_io.lexists(stage)
        if source_present and stage_present:
            raise OSError(
                "live proposal and archive stage coexist for one attempt"
            )
        if stage_present:
            raw = rooted_io.read_bytes(
                stage,
                label="instantiate proposal archive stage",
                require_single_link=True,
            )
        elif source_present:
            raw = rooted_io.read_bytes(
                source,
                label="instantiate live proposal",
                require_single_link=True,
            )
            rooted_io.durable_write_once_bytes(destination, raw)
            rooted_io.durable_publish_new(source, stage)
            staged = rooted_io.read_bytes(
                stage,
                label="instantiate moved proposal stage",
                require_single_link=True,
            )
            if staged != raw:
                raise OSError(
                    "live proposal identity changed during archival"
                )
        else:
            # A crash after durable publication and retirement of the live
            # name resumes here. The history object is still revalidated below.
            if not rooted_io.lexists(destination):
                return [], []
            raw = rooted_io.read_bytes(
                destination,
                label="instantiate archived proposal",
                require_single_link=True,
            )
        rooted_io.durable_write_once_bytes(destination, raw)
        archived = rooted_io.read_bytes(
            destination,
            label="instantiate archived proposal",
            require_single_link=True,
        )
        if archived != raw:
            raise OSError("archived proposal postimage digest mismatch")
        if rooted_io.lexists(stage):
            rooted_io.durable_unlink(stage)
        return [destination.relative_to(root).as_posix()], []
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        return [], [
            "instantiate prior proposal archival failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _load_instantiate_attempt_receipt(
    scratchpad: Path,
    *,
    run_id: str,
) -> tuple[dict[str, Any] | None, list[str]]:
    root = Path(scratchpad)
    path = root / _INSTANTIATE_ATTEMPT_RECEIPT
    if not rooted_io.lexists(path):
        return None, []
    try:
        payload = json.loads(rooted_io.read_bytes(
            path,
            label="instantiate attempt transition receipt",
            require_single_link=True,
        ).decode("utf-8", errors="strict"))
        required = {
            "schema_version", "run_id", "state", "active_attempt",
            "from_attempt", "to_attempt", "history",
            "predecessor_receipt_digest", "receipt_digest",
        }
        if not isinstance(payload, dict) or set(payload) != required:
            raise ValueError("attempt transition receipt keys are invalid")
        if payload["schema_version"] != _INSTANTIATE_ATTEMPT_SCHEMA:
            raise ValueError("attempt transition receipt schema is invalid")
        if payload["run_id"] != run_id or not run_id:
            raise ValueError("attempt transition receipt run_id mismatch")
        active = _exact_attempt_ordinal(
            payload["active_attempt"], label="instantiate durable attempt"
        )
        if active > 3:
            raise ValueError("instantiate durable attempt exceeds retry budget")
        state = payload["state"]
        from_attempt = _exact_attempt_ordinal(
            payload["from_attempt"], label="instantiate transition from"
        )
        to_attempt = _exact_attempt_ordinal(
            payload["to_attempt"], label="instantiate transition to"
        )
        if state == "ACTIVE":
            if from_attempt != active or to_attempt != active:
                raise ValueError("ACTIVE instantiate receipt ordinals drift")
        elif state == "PREPARING":
            if (
                from_attempt != active
                or to_attempt != active + 1
                or to_attempt > 3
            ):
                raise ValueError("PREPARING instantiate receipt ordinals drift")
        else:
            raise ValueError("instantiate attempt receipt state is invalid")
        history = payload["history"]
        if not isinstance(history, list) or len(history) != active - 1:
            raise ValueError("instantiate attempt history denominator mismatch")
        for expected_attempt, row in enumerate(history, start=1):
            if not isinstance(row, dict) or set(row) != {
                "attempt", "state", "path", "sha256", "size"
            }:
                raise ValueError("instantiate attempt history row is invalid")
            if row["attempt"] != expected_attempt:
                raise ValueError("instantiate attempt history is non-monotonic")
            observed = _instantiate_history_record(
                root, attempt=expected_attempt
            )
            if row != observed:
                raise ValueError(
                    "instantiate archived proposal history digest mismatch"
                )
        predecessor = payload["predecessor_receipt_digest"]
        if (
            (state == "ACTIVE" and active == 1 and predecessor != "")
            or (
                not (state == "ACTIVE" and active == 1)
                and not re.fullmatch(r"[0-9a-f]{64}", predecessor)
            )
        ):
            raise ValueError(
                "instantiate predecessor receipt digest is invalid"
            )
        if state == "ACTIVE":
            ahead_history = _instantiate_history_path(root, active)
            ahead_stage = root / (
                f"_.instantiate-proposal-attempt-{active:04d}.stage"
            )
            if rooted_io.lexists(ahead_history) or rooted_io.lexists(ahead_stage):
                raise ValueError(
                    "ACTIVE instantiate receipt has uncommitted successor state"
                )
        if payload["receipt_digest"] != _instantiate_attempt_receipt_digest(
            payload
        ):
            raise ValueError("instantiate attempt receipt digest mismatch")
        return payload, []
    except (
        OSError, RuntimeError, TypeError, UnicodeError, ValueError,
        json.JSONDecodeError,
    ) as exc:
        return None, [
            "instantiate attempt receipt validation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _publish_instantiate_attempt_receipt(
    scratchpad: Path,
    *,
    run_id: str,
    state: str,
    active_attempt: int,
    from_attempt: int,
    to_attempt: int,
    history: Sequence[Mapping[str, Any]],
    predecessor_receipt_digest: str,
) -> list[str]:
    root = Path(scratchpad)
    payload: dict[str, Any] = {
        "schema_version": _INSTANTIATE_ATTEMPT_SCHEMA,
        "run_id": run_id,
        "state": str(state),
        "active_attempt": _exact_attempt_ordinal(
            active_attempt, label="instantiate published attempt"
        ),
        "from_attempt": _exact_attempt_ordinal(
            from_attempt, label="instantiate published transition from"
        ),
        "to_attempt": _exact_attempt_ordinal(
            to_attempt, label="instantiate published transition to"
        ),
        "history": [dict(row) for row in history],
        "predecessor_receipt_digest": str(predecessor_receipt_digest),
    }
    payload["receipt_digest"] = _instantiate_attempt_receipt_digest(payload)
    try:
        existing, existing_issues = _load_instantiate_attempt_receipt(
            root, run_id=run_id
        )
        if existing_issues:
            return existing_issues
        if existing == payload:
            return []
        if state == "PREPARING":
            if (
                existing is None
                or existing["state"] != "ACTIVE"
                or existing["active_attempt"] != active_attempt
                or predecessor_receipt_digest
                != existing["receipt_digest"]
            ):
                return [
                    "instantiate PREPARING receipt lacks exact ACTIVE predecessor"
                ]
        elif int(active_attempt) == 1:
            if existing is not None:
                return [
                    "instantiate initial ACTIVE receipt already has predecessor"
                ]
        elif (
            existing is None
            or existing["state"] != "PREPARING"
            or existing["to_attempt"] != active_attempt
            or predecessor_receipt_digest != existing["receipt_digest"]
        ):
            return [
                "instantiate ACTIVE successor lacks exact PREPARING predecessor"
            ]
        _atomic_driver_json_record(
            root / _INSTANTIATE_ATTEMPT_RECEIPT, payload
        )
        observed, issues = _load_instantiate_attempt_receipt(
            root, run_id=run_id
        )
        if issues or observed != payload:
            return issues or ["instantiate attempt receipt postimage mismatch"]
        return []
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        return [
            "instantiate attempt receipt publication failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _instantiate_attempt_ordinal(config: Mapping[str, Any]) -> int:
    return _attempt_map_ordinal(
        config,
        "_active_model_attempts",
        "instantiate",
        default=1,
        minimum=1,
    )


def _instantiate_reconcile_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec, tuple[str, ...]]:
    """Resolve the exact MODEL-proposal -> DRIVER-canonical successor."""

    ordinal = _instantiate_attempt_ordinal(config)
    work_unit_id = (
        "manifest_reconcile"
        if ordinal == 1
        else f"manifest_reconcile.attempt-{ordinal:04d}"
    )
    exact_inputs = tuple(dict.fromkeys((
        *_instantiate_exact_inputs(Path(scratchpad)),
        "spawn_manifest_proposal.md",
    )))
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="instantiate",
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch, exact_inputs


def _instantiate_reconcile_receipt_digest(
    payload: Mapping[str, Any],
) -> str:
    unsigned = {
        key: value for key, value in payload.items()
        if key != "receipt_digest"
    }
    return hashlib.sha256(
        json.dumps(
            unsigned,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _derive_instantiate_manifest_successor(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    contract: PhaseIOContract,
    exact_inputs: Sequence[str],
) -> tuple[bytes, dict[str, Any], list[str]]:
    """Purely derive canonical manifest bytes and their reconciliation receipt."""

    root = Path(scratchpad)
    proposal_path = root / "spawn_manifest_proposal.md"
    proposal_bytes = proposal_path.read_bytes()
    proposal_text = proposal_bytes.decode("utf-8", errors="strict")
    upstream_required = _required_niche_manifest_union(root)
    proposed_niches = _niche_tokens_from_required_table(proposal_text)
    invalid_model_niches = sorted(
        niche
        for niche in (proposed_niches - upstream_required)
        if not _niche_skill_path_for_role(niche).is_file()
    )
    retained_model_niches = (
        proposed_niches - set(invalid_model_niches)
    )
    final_niches = upstream_required | retained_model_niches
    canonical_text = _rewrite_niche_required_table(
        proposal_text, final_niches
    )
    canonical_bytes = canonical_text.encode("utf-8")

    input_records: list[dict[str, Any]] = []
    for relative in exact_inputs:
        path = root / relative
        raw = path.read_bytes()
        input_records.append({
            "path": relative,
            "sha256": hashlib.sha256(raw).hexdigest(),
            "size": len(raw),
        })
    ordinal = _instantiate_attempt_ordinal(config)
    receipt: dict[str, Any] = {
        "schema_version": _INSTANTIATE_RECONCILE_SCHEMA,
        "run_id": str(config.get("_run_id") or ""),
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "attempt_ordinal": ordinal,
        "proposal": {
            "path": "spawn_manifest_proposal.md",
            "sha256": hashlib.sha256(proposal_bytes).hexdigest(),
            "size": len(proposal_bytes),
        },
        "canonical": {
            "path": "spawn_manifest.md",
            "sha256": hashlib.sha256(canonical_bytes).hexdigest(),
            "size": len(canonical_bytes),
        },
        "input_records": input_records,
        "upstream_required_niches": sorted(upstream_required),
        "proposal_niches": sorted(proposed_niches),
        "retained_model_only_niches": sorted(
            retained_model_niches - upstream_required
        ),
        "added_upstream_niches": sorted(
            upstream_required - proposed_niches
        ),
        "invalid_model_only_niches": invalid_model_niches,
        "reconciliation": (
            "RECALL_SAFE_POSITIVE_UNION"
            if not invalid_model_niches
            else "INVALID_MODEL_NICHE"
        ),
    }
    receipt["receipt_digest"] = _instantiate_reconcile_receipt_digest(
        receipt
    )
    issues = (
        [
            "spawn manifest proposal contains model-only niche(s) with no "
            "resolvable niche methodology: "
            + ", ".join(invalid_model_niches)
        ]
        if invalid_model_niches
        else []
    )
    return canonical_bytes, receipt, issues


def _instantiate_consumer_compatibility_issues(
    scratchpad: Path,
    manifest_bytes: bytes,
    *,
    mode: str,
) -> list[str]:
    """Reject explicit skill assignments outside their typed consumers."""

    root = Path(scratchpad)
    try:
        catalog = json.loads(
            (root / "skill_selection_catalog.json").read_text(
                encoding="utf-8", errors="strict"
            )
        )
        if not isinstance(catalog, Mapping):
            return ["skill selection catalog is not an object"]
        scheduled, existing = _scheduled_typed_skill_consumers(
            manifest_text=manifest_bytes.decode("utf-8", errors="replace"),
            selection_catalog=catalog,
            pipeline="sc",
            mode=mode,
        )
        coverage = _build_typed_skill_consumer_coverage(
            selection_catalog=catalog,
            scheduled_consumers=scheduled,
            existing_bindings=existing,
        )
        issues: list[str] = []
        for debt in coverage.get("debts") or []:
            if debt.get("code") not in {
                "INELIGIBLE_EXISTING_BINDING", "UNKNOWN_EXPLICIT_BINDING",
            }:
                continue
            declared = ", ".join(
                str(value) for value in debt.get("declared_consumers") or []
            ) or "none"
            if debt.get("code") == "UNKNOWN_EXPLICIT_BINDING":
                issues.append(
                    "spawn_manifest assigns unknown skill "
                    f"{debt.get('skill_id')} to consumer "
                    f"{debt.get('consumer_id')}; skill is absent from the "
                    "exact selection catalog"
                )
            else:
                issues.append(
                    "spawn_manifest assigns selected skill "
                    f"{debt.get('skill_id')} to ineligible consumer "
                    f"{debt.get('consumer_id')}; declared consumers: {declared}"
                )
        return sorted(set(issues))
    except (
        OSError,
        UnicodeError,
        ValueError,
        TypeError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "spawn manifest consumer compatibility validation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _validate_instantiate_manifest_successor(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    contract: PhaseIOContract,
    exact_inputs: Sequence[str],
    staged_canonical: bytes | None = None,
) -> list[str]:
    """Replay the pure derivation and validate schema without mutating inputs."""

    root = Path(scratchpad)
    try:
        expected, receipt, issues = _derive_instantiate_manifest_successor(
            root,
            config,
            contract=contract,
            exact_inputs=exact_inputs,
        )
        candidate = staged_canonical
        if candidate is None:
            candidate = (root / "spawn_manifest.md").read_bytes()
            actual_receipt = json.loads(
                (root / _INSTANTIATE_RECONCILE_RECEIPT).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            if actual_receipt != receipt:
                issues.append(
                    "instantiate reconciliation receipt disagrees with "
                    "current exact inputs"
                )
            if (
                not isinstance(actual_receipt, Mapping)
                or actual_receipt.get("receipt_digest")
                != _instantiate_reconcile_receipt_digest(actual_receipt)
            ):
                issues.append(
                    "instantiate reconciliation receipt digest is invalid"
                )
        if candidate != expected:
            issues.append(
                "spawn_manifest.md is not the deterministic recall-safe "
                "successor of spawn_manifest_proposal.md"
            )

        # The existing producer schema validator is path-based.  Run it over a
        # disposable exact-input projection so validation never writes to or
        # trusts the live canonical path before commit.
        with tempfile.TemporaryDirectory(
            prefix=".instantiate-reconcile-", dir=str(root)
        ) as temporary:
            stage = Path(temporary)
            for relative in exact_inputs:
                source = root / relative
                destination = stage / relative
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(source, destination)
            (stage / "spawn_manifest.md").write_bytes(candidate)
            issues.extend(_validate_spawn_manifest_schema(
                stage,
                str(config.get("mode") or "core"),
                str(config.get("language") or ""),
            ))
            issues.extend(_instantiate_consumer_compatibility_issues(
                stage,
                candidate,
                mode=str(config.get("mode") or "core"),
            ))
        return list(dict.fromkeys(str(value) for value in issues if str(value)))
    except (
        OSError,
        UnicodeError,
        ValueError,
        TypeError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "instantiate manifest successor validation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _run_instantiate_manifest_reconcile_transaction(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Commit one crash-resumable deterministic instantiate successor."""

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["instantiate manifest reconciliation has no run_id"]
    try:
        contract, launch, exact_inputs = (
            _instantiate_reconcile_contract_and_launch(root, config)
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return list(dict.fromkeys(issues))
        if not execute:
            return _validate_instantiate_manifest_successor(
                root,
                config,
                contract=contract,
                exact_inputs=exact_inputs,
            )

        failpoint = str(
            config.get("_instantiate_reconcile_failpoint") or ""
        ).strip()
        if failpoint == "after_arm":
            return ["instantiate reconciliation injected failpoint: after_arm"]
        canonical_bytes, receipt, derivation_issues = (
            _derive_instantiate_manifest_successor(
                root,
                config,
                contract=contract,
                exact_inputs=exact_inputs,
            )
        )
        if derivation_issues:
            return list(dict.fromkeys(derivation_issues))
        staged_issues = _validate_instantiate_manifest_successor(
            root,
            config,
            contract=contract,
            exact_inputs=exact_inputs,
            staged_canonical=canonical_bytes,
        )
        if staged_issues:
            return staged_issues
        _atomic_driver_bytes(root / "spawn_manifest.md", canonical_bytes)
        if failpoint == "after_manifest":
            return [
                "instantiate reconciliation injected failpoint: after_manifest"
            ]
        _atomic_driver_json_record(
            root / _INSTANTIATE_RECONCILE_RECEIPT, receipt
        )
        if failpoint == "after_receipt":
            return [
                "instantiate reconciliation injected failpoint: after_receipt"
            ]
        domain_issues = _validate_instantiate_manifest_successor(
            root,
            config,
            contract=contract,
            exact_inputs=exact_inputs,
        )
        if domain_issues:
            return domain_issues
        return _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
    except (
        ArtifactLedgerError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "instantiate manifest reconciliation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _instantiate_retry_consumer_contract(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> str:
    """Render the exact selected-skill consumer denominator for a retry.

    A retry predicate is additive: repairing a breadth-count floor may not
    invalidate the independent catalog-consumer predicate.  Keep the catalog
    bytes as authority and expose only their compact closed destination map to
    the model; the canonical validator still replays the full catalog.
    """

    if _instantiate_attempt_ordinal(config) <= 1:
        return ""
    root = Path(scratchpad)
    raw = rooted_io.read_bytes(
        root / "skill_selection_catalog.json",
        label="instantiate retry skill selection catalog",
        require_single_link=True,
    )
    catalog = json.loads(raw.decode("utf-8", errors="strict"))
    if not isinstance(catalog, Mapping) or not isinstance(
        catalog.get("skills"), list
    ):
        raise ValueError("instantiate retry skill selection catalog is malformed")

    destination_names = {
        "depth:token_flow": "depth-token-flow",
        "depth:state_trace": "depth-state-trace",
        "depth:edge_case": "depth-edge-case",
        "depth:external": "depth-external",
        "recon": "BUILTIN-RECON (no breadth/B# assignment)",
        "verification:*": "BUILTIN-VERIFICATION (no breadth/B# assignment)",
        "invariant_fuzz": "BUILTIN-INVARIANT-FUZZ (no breadth/B# assignment)",
    }
    rows: list[str] = []
    for skill in sorted(
        (
            value for value in catalog["skills"]
            if isinstance(value, Mapping) and value.get("state") == "REQUIRED"
        ),
        key=lambda value: str(value.get("skill_id") or ""),
    ):
        skill_id = str(skill.get("skill_id") or "").strip()
        consumers = skill.get("index_consumers")
        if (
            not skill_id
            or skill.get("consumer_metadata_status") != "CURRENT"
            or not isinstance(consumers, list)
            or not consumers
            or any(not isinstance(value, str) or not value for value in consumers)
        ):
            raise ValueError(
                "instantiate retry selected skill lacks current closed consumer "
                f"metadata: {skill_id or '<missing>'}"
            )
        destinations: list[str] = []
        for consumer in consumers:
            if consumer == "breadth:*":
                destinations.append("BREADTH (Template cell or B# binding)")
            elif consumer == "breadth:cross_chain_encoding":
                destinations.append(
                    "BREADTH-CROSS-CHAIN-ENCODING (matching-focus Template/B#)"
                )
            elif consumer.startswith("niche:"):
                destinations.append("NICHE-AUTO (no breadth/B# assignment)")
            elif consumer in destination_names:
                destinations.append(destination_names[consumer])
            else:
                raise ValueError(
                    "instantiate retry selected skill has unknown consumer: "
                    f"{skill_id}:{consumer}"
                )
        rows.append(
            f"| {skill_id} | {', '.join(dict.fromkeys(destinations))} |"
        )

    return "\n".join((
        "## Driver-bound conjunctive retry contract (HARD)",
        "",
        "The retry hint identifies the previously failed predicate; it does not ",
        "replace any other schema or consumer-compatibility predicate. Satisfy ",
        "the breadth floor and this exact catalog-derived destination matrix in ",
        "the same proposal.",
        "",
        "If the prior failure is a breadth-floor deficit, add `GENERAL` breadth ",
        "rows until the required floor is reached. Do not use a selected skill ",
        "to create a floor-fill row unless its row below explicitly permits a ",
        "BREADTH destination. A depth-only skill must remain in its listed ",
        "`depth-*` binding(s), never a breadth Template cell or B# binding.",
        "",
        f"Catalog SHA-256: `{hashlib.sha256(raw).hexdigest()}`",
        "",
        "| Selected skill | Only permitted manifest destination(s) |",
        "|---|---|",
        *rows,
        "",
    ))


def _compile_instantiate_model_prompt(
    prompt: str,
    *,
    scratchpad: Path | None = None,
    config: Mapping[str, Any] | None = None,
) -> str:
    """Route the model to an immutable proposal; the driver owns canonical."""

    compiled = str(prompt).replace(
        "spawn_manifest.md", "spawn_manifest_proposal.md"
    )
    # The inherited methodology names the canonical scratchpad path as a
    # positive Write destination.  Restricted workers may write only to the
    # transaction-private path appended by the runtime, so neutralize that
    # instruction before the supervisor route is added.  Keep the logical
    # artifact name for schema/content guidance without advertising it as a
    # writable filesystem path.
    compiled = re.sub(
        r"(?m)^\*\*Write spawn manifest\*\* to "
        r"`[^`\r\n]*spawn_manifest_proposal\.md`:$",
        "**Prepare spawn manifest content** for the logical artifact "
        "`spawn_manifest_proposal.md`. The final Runtime output routing "
        "block supplies its only writable destination:",
        compiled,
    )
    retry_contract = ""
    if scratchpad is not None and config is not None:
        retry_contract = _instantiate_retry_consumer_contract(
            Path(scratchpad), config
        )
    return (
        compiled.rstrip()
        + (("\n\n" + retry_contract.rstrip()) if retry_contract else "")
        + "\n\n"
        + "## Typed instantiate output boundary\n\n"
        + "The sole model-authored artifact is logically named "
        + "`spawn_manifest_proposal.md`. Write it only to the exact "
        + "attempt-owned destination in the final Runtime output routing "
        + "block; never write a bare, scratchpad-relative, or absolute "
        + "canonical proposal path. Do not create or modify "
        + "`spawn_manifest.md`; "
        + "the deterministic driver reconciles the recall-safe positive niche "
        + "union and owns that canonical artifact. Do not modify any recon "
        + "input artifact.\n"
    )


_CLAUDE_EXACT_CONSUMER_PHASES = frozenset({
    "axis_coverage", "chain_agent2", "chain_iter2", "report_index",
})

_CLAUDE_PROVIDER_AUTH_ROUTES = frozenset({
    "OAUTH_TOKEN",
    "STORED_SUBSCRIPTION_OAUTH",
})
_CLAUDE_PROVIDER_DEFAULT_AUTH_ROUTE = "STORED_SUBSCRIPTION_OAUTH"
_CLAUDE_PROVIDER_MAX_LINE_BYTES = 2 * 1024 * 1024
_CLAUDE_PROVIDER_MAX_STREAM_BYTES = 16 * 1024 * 1024
_CLAUDE_PROVIDER_SAFE_BUILTIN_TOOLS = frozenset({
    "Bash",
    "Edit",
    "Glob",
    "Grep",
    "Read",
    "Write",
})
_CLAUDE_RESTRICTED_ANALYSIS_TOOLS = frozenset({
    "Edit", "Glob", "Grep", "Read", "Write",
})


def _claude_restricted_analysis_launch(
    phase: Phase,
    launch: LaunchSpec,
) -> bool:
    """Select command-free Claude leaves eligible for the restricted lane."""

    if not (
        str(launch.backend).lower() == "claude"
        and bool(launch.model)
    ):
        return False
    tools = set(launch.tool_policy)
    if tools == {"filesystem"}:
        return True
    return (
        phase.name == "recon"
        and tools == {"filesystem", "network"}
        and re.search(
            r"/recon/dependency_research(?:\.attempt-[0-9]{4})?$",
            str(launch.work_unit_key),
        )
        is not None
    )


def _claude_dependency_research_launch(
    phase: Phase,
    launch: LaunchSpec,
) -> bool:
    return bool(
        phase.name == "recon"
        and str(launch.backend).lower() == "claude"
        and set(launch.tool_policy) == {"filesystem", "network"}
        and re.search(
            r"/recon/dependency_research(?:\.attempt-[0-9]{4})?$",
            str(launch.work_unit_key),
        )
    )
_CLAUDE_PROVIDER_FUNCTIONAL_CONTROLS = {
    "CLAUDE_CODE_DISABLE_AUTO_MEMORY": "1",
    "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC": "1",
    "CLAUDE_CODE_DISABLE_OFFICIAL_MARKETPLACE_AUTOINSTALL": "1",
    "CLAUDE_CODE_SKIP_PROMPT_HISTORY": "1",
    "CLAUDE_CODE_SUBPROCESS_ENV_SCRUB": "1",
    "DISABLE_AUTOUPDATER": "1",
    "DISABLE_ERROR_REPORTING": "1",
    "DISABLE_TELEMETRY": "1",
    "DISABLE_UPDATES": "1",
    "ENABLE_CLAUDEAI_MCP_SERVERS": "false",
}
_CLAUDE_UPDATE_DISABLE_ENV = {
    "DISABLE_AUTOUPDATER": "1",
    "DISABLE_UPDATES": "1",
}


@dataclass(frozen=True)
class _ClaudeDriverProviderAuthority:
    """Private driver-to-headless provider authority for one semantic unit."""

    preparation: ClaudeProviderPreparation = field(
        repr=False,
        compare=False,
    )
    base_argv_template: tuple[str, ...]
    public_arguments: Mapping[str, Any]
    runtime_local_inputs: Mapping[str, Any] = field(
        repr=False,
        compare=False,
    )
    bound_settings_bytes: bytes | None = field(
        default=None,
        repr=False,
        compare=False,
    )
    selected_mcp_config_bytes: bytes | None = field(
        default=None,
        repr=False,
        compare=False,
    )


def _selected_claude_provider_auth_route(
    config: Mapping[str, Any],
) -> str:
    """Return one explicit supported route; never infer it from credentials."""

    selected = config.get(
        "claude_auth_route",
        config.get(
            "_claude_auth_route",
            _CLAUDE_PROVIDER_DEFAULT_AUTH_ROUTE,
        ),
    )
    if selected not in _CLAUDE_PROVIDER_AUTH_ROUTES:
        raise HeadlessWorkerRuntimeError(
            "Claude provider auth route is absent or unsupported"
        )
    return str(selected)


def _claude_provider_environment_policies(
    launch: LaunchSpec,
) -> tuple[str, ...]:
    """Derive the reviewed toolchain environment denominator from LaunchSpec."""

    policies = {"base", "certificates", "git", "plamen"}
    ecosystem = str(launch.ecosystem).lower()
    if ecosystem == "evm":
        policies.update({"evm", "node"})
    elif ecosystem == "solana":
        policies.update({"node", "rust", "solana"})
    elif ecosystem == "aptos":
        policies.update({"aptos", "node", "rust"})
    elif ecosystem == "sui":
        policies.update({"node", "rust", "sui"})
    elif ecosystem == "soroban":
        policies.update({"node", "rust", "soroban"})
    elif ecosystem in {"l1", "l1-native"}:
        policies.update({"go", "l1-native", "node", "rust"})
    return tuple(sorted(policies))


def _selected_claude_mcp_config_bytes(
    *, server_names: Sequence[str]
) -> bytes:
    """Compile only authenticated generation-bound public launcher entries."""

    selection = _DIRECT_CLAUDE_MCP_SELECTION
    if selection is None:
        raise HeadlessWorkerRuntimeError(
            "Claude MCP runtime selection was not admitted before provider "
            "compilation",
            reason_code="CLAUDE_MCP_SELECTION_UNAVAILABLE",
        )
    try:
        selected = replay_mcp_current_selection(selection)
    except ClaudeLaunchSecurityError as exc:
        raise HeadlessWorkerRuntimeError(
            "Claude MCP runtime selection no longer replays",
            reason_code="CLAUDE_MCP_SELECTION_DRIFT",
        ) from exc
    front = os.fspath(_installed_mcp_public_front_path())
    servers: dict[str, dict[str, Any]] = {}
    for server_name in sorted(server_names):
        if server_name not in selected["server_launches"]:
            raise HeadlessWorkerRuntimeError(
                f"Claude MCP server {server_name!r} is absent from the signed "
                "runtime selection",
                reason_code="CLAUDE_MCP_SERVER_UNAVAILABLE",
            )
        servers[server_name] = {
            "command": front,
            "args": [
                "mcp-launch",
                "--backend",
                "claude",
                "--server",
                server_name,
                "--generation",
                selected["generation_id"],
                "--receipt-sha256",
                selected["receipt_sha256"],
                "--census-sha256",
                selected["census_sha256"],
                "--request-sha256",
                selected["request_sha256"],
                "--policy-sha256",
                selected["generation_policy_sha256"],
            ],
        }
    return json.dumps(
        {"mcpServers": servers},
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8") + b"\n"


def _selected_claude_backend_argv_prefix() -> tuple[str, ...]:
    """Return the authenticated front command for the selected Claude CLI."""

    selection = _DIRECT_CLAUDE_MCP_SELECTION
    if selection is None:
        raise HeadlessWorkerRuntimeError(
            "Claude backend runtime selection was not admitted",
            reason_code="CLAUDE_BACKEND_SELECTION_UNAVAILABLE",
        )
    selected = replay_mcp_current_selection(selection)
    if selected["backend_launches"]["claude"]["version"] != "2.1.252":
        raise HeadlessWorkerRuntimeError(
            "Claude backend generation version is unsupported",
            reason_code="CLAUDE_BACKEND_VERSION_UNSUPPORTED",
        )
    return (
        os.fspath(_installed_mcp_public_front_path()),
        "backend-launch",
        "--backend",
        "claude",
        "--generation",
        selected["generation_id"],
        "--receipt-sha256",
        selected["receipt_sha256"],
        "--census-sha256",
        selected["census_sha256"],
        "--request-sha256",
        selected["request_sha256"],
        "--policy-sha256",
        selected["generation_policy_sha256"],
        "--",
    )


def _selected_claude_backend_argv(
    claude_arguments: Sequence[str],
) -> tuple[str, ...]:
    """Project Claude arguments through the authenticated generation front."""

    if isinstance(claude_arguments, (str, bytes)) or not isinstance(
        claude_arguments, Sequence
    ):
        raise HeadlessWorkerRuntimeError(
            "Claude backend argument vector is malformed",
            reason_code="CLAUDE_BACKEND_ARGV_INVALID",
        )
    suffix = tuple(str(value) for value in claude_arguments)
    if any(not value or "\x00" in value for value in suffix):
        raise HeadlessWorkerRuntimeError(
            "Claude backend argument vector is malformed",
            reason_code="CLAUDE_BACKEND_ARGV_INVALID",
        )
    return (*_selected_claude_backend_argv_prefix(), *suffix)


def _replace_claude_executable_with_selected_front(
    argv: Sequence[str],
) -> tuple[str, ...]:
    if isinstance(argv, (str, bytes)) or not isinstance(argv, Sequence) or not argv:
        raise HeadlessWorkerRuntimeError(
            "Claude backend launch vector is malformed",
            reason_code="CLAUDE_BACKEND_ARGV_INVALID",
        )
    return _selected_claude_backend_argv(tuple(str(value) for value in argv[1:]))


def _compile_claude_driver_provider_authority(
    *,
    phase: Phase,
    config: Mapping[str, Any],
    scratchpad: Path,
    project_root: Path,
    cwd: Path,
    launch: LaunchSpec,
    session_id: str,
    startup_authority_binding: Mapping[str, Any],
    source_snapshot_sha256: str,
) -> _ClaudeDriverProviderAuthority:
    """Compile the production, attempt-independent Claude provider parent."""

    run_id = str(config.get("_run_id") or "test-unbound")
    desired_auth_route = _selected_claude_provider_auth_route(config)
    ambient_environment = dict(os.environ)
    ambient_environment.update({
        "PLAMEN_AUDIT_ROOT": str(project_root),
        "PLAMEN_RUN_ID": run_id,
        "PLAMEN_SCRATCHPAD": str(scratchpad),
    })
    phase_environment_policies = (
        _claude_provider_environment_policies(launch)
    )
    exact_consumer = phase.name in _CLAUDE_EXACT_CONSUMER_PHASES
    restricted_analysis = _claude_restricted_analysis_launch(phase, launch)
    dependency_research = _claude_dependency_research_launch(phase, launch)
    selected_mcp_consumer = "mcp" in launch.tool_policy
    if selected_mcp_consumer and (
        phase.name != "rag_sweep" or exact_consumer
    ):
        raise HeadlessWorkerRuntimeError(
            f"{phase.name}: Claude selected MCP phase denominator is "
            "unsupported",
            reason_code="CLAUDE_SELECTED_MCP_PHASE_UNSUPPORTED",
        )
    mcp_source_manifest_sha256: str | None = None
    mcp_server_names: tuple[str, ...] = ()
    if restricted_analysis:
        permission_mode = "default"
        boundaries = config.get(
            "_claude_phase_tool_boundaries",
            {},
        )
        boundary = (
            boundaries.get(phase.name)
            if isinstance(boundaries, Mapping)
            else None
        )
        if not isinstance(boundary, Mapping):
            raise HeadlessWorkerRuntimeError(
                f"{phase.name}: Claude restricted-analysis boundary is absent"
            )
        try:
            settings_path = Path(str(boundary["settings_path"]))
            policy_path = Path(str(boundary["policy_path"]))
            mcp_path = Path(str(boundary["mcp_config_path"]))
            if (
                not settings_path.is_absolute()
                or not policy_path.is_absolute()
                or not mcp_path.is_absolute()
            ):
                raise ValueError("exact-consumer paths are not absolute")
            bound_settings_bytes = settings_path.read_bytes()
            external_policy_bytes = policy_path.read_bytes()
            selected_mcp_config_bytes = mcp_path.read_bytes()
            written_policy = claude_phase_tool_policy.load_policy(policy_path)
            builtin_tools = set(
                claude_phase_tool_policy.provider_builtin_tools(
                    written_policy
                )
            )
        except (KeyError, OSError, TypeError, ValueError) as exc:
            raise HeadlessWorkerRuntimeError(
                f"{phase.name}: Claude restricted-analysis source authority "
                "is unavailable",
                reason_code="CLAUDE_EXACT_CONSUMER_SOURCE_UNAVAILABLE",
            ) from exc
        settings_mode = "BOUND_SETTINGS"
    elif selected_mcp_consumer:
        builtin_tools = set(_CLAUDE_PROVIDER_SAFE_BUILTIN_TOOLS)
        if "network" in launch.tool_policy:
            builtin_tools.update({"WebFetch", "WebSearch"})
        permission_mode = "bypassPermissions"
        settings_mode = "BOUND_SETTINGS"
        mcp_server_names = ("unified-vuln-db",)
        try:
            selected_mcp_config_bytes = _selected_claude_mcp_config_bytes(
                server_names=mcp_server_names
            )
            selection = replay_mcp_current_selection(
                _DIRECT_CLAUDE_MCP_SELECTION
            )
            mcp_source_manifest_sha256 = selection["receipt_sha256"]
            bound_settings_bytes = (
                claude_phase_tool_policy.canonical_json_bytes(
                    {
                        "enabledPlugins": {},
                        "hooks": {},
                        "mcpServers": {},
                        "permissions": {
                            "deny": ["Agent", "Task"],
                        },
                    }
                )
            )
            external_policy_bytes = selected_mcp_config_bytes
        except (
            ClaudeLaunchSecurityError,
            TypeError,
            ValueError,
        ) as exc:
            raise HeadlessWorkerRuntimeError(
                f"{phase.name}: Claude selected MCP source is unavailable "
                "or malformed",
                reason_code="CLAUDE_SELECTED_MCP_SOURCE_DEBT",
            ) from exc
    else:
        builtin_tools = set(_CLAUDE_PROVIDER_SAFE_BUILTIN_TOOLS)
        if "network" in launch.tool_policy:
            builtin_tools.update({"WebFetch", "WebSearch"})
        permission_mode = "bypassPermissions"
        bound_settings_bytes = None
        external_policy_bytes = None
        selected_mcp_config_bytes = None
        settings_mode = "SAFE_MODE"
    forbidden_tools = {"Agent", "Task"}
    if restricted_analysis:
        forbidden_tools.update({"Bash", "PowerShell"})
    if "network" not in launch.tool_policy:
        forbidden_tools.update({"WebFetch", "WebSearch"})

    semantic_intent = compile_claude_provider_semantic_intent(
        run_id=run_id,
        phase=phase.name,
        backend="claude",
        launch_model=launch.model,
        accepted_models=(launch.model,),
        cwd=str(cwd),
        session_id=session_id,
        max_line_bytes=_CLAUDE_PROVIDER_MAX_LINE_BYTES,
        max_stream_bytes=_CLAUDE_PROVIDER_MAX_STREAM_BYTES,
        desired_auth_route=desired_auth_route,
        home_variable_policy="PRESERVE_TOOLCHAIN_HOME",
        phase_environment_policies=phase_environment_policies,
        functional_controls=_CLAUDE_PROVIDER_FUNCTIONAL_CONTROLS,
        required_capabilities=(
            (RESTRICTED_WEB_ANALYSIS_CAPABILITY,)
            if dependency_research
            else ("vendor-restricted-analysis",)
            if restricted_analysis
            else ()
        ),
        forbidden_capabilities=("remote-agents",),
        accepted_output_styles=("default",),
    )
    phase_tool_policy = compile_claude_phase_tool_policy(
        phase=phase.name,
        permission_mode=permission_mode,
        builtin_tools=tuple(sorted(builtin_tools)),
        required_tools=("Read", "Write"),
        forbidden_tools=tuple(sorted(forbidden_tools)),
    )
    settings_policy = compile_claude_settings_policy(
        mode=settings_mode,
        settings_sha256=(
            None
            if bound_settings_bytes is None
            else hashlib.sha256(bound_settings_bytes).hexdigest()
        ),
        external_policy_sha256=(
            None
            if external_policy_bytes is None
            else hashlib.sha256(external_policy_bytes).hexdigest()
        ),
    )
    mcp_policy = compile_claude_mcp_policy(
        settings_mode=settings_mode,
        server_names=mcp_server_names,
        source_manifest_sha256=mcp_source_manifest_sha256,
        selected_config_sha256=(
            None
            if selected_mcp_config_bytes is None
            else hashlib.sha256(
                selected_mcp_config_bytes
            ).hexdigest()
        ),
        runtime_selection=_DIRECT_CLAUDE_MCP_SELECTION,
    )
    if desired_auth_route == "STORED_SUBSCRIPTION_OAUTH":
        source_config_dir = Path(
            str(
                config.get("claude_source_config_dir")
                or os.environ.get("CLAUDE_CONFIG_DIR")
                or (Path.home() / ".claude")
            )
        )
        stored_subscription_source_path: Path | None = (
            source_config_dir / ".credentials.json"
        )
    else:
        source_config_dir = None
        stored_subscription_source_path = None

    try:
        preparation = prepare_claude_provider(
            semantic_intent=semantic_intent,
            phase_tool_policy=phase_tool_policy,
            settings_policy=settings_policy,
            mcp_policy=mcp_policy,
            configured_claude_bin=_selected_claude_backend_argv_prefix()[0],
            ambient_environment=ambient_environment,
            settings_evidence={},
            stored_subscription_source_path=(
                stored_subscription_source_path
            ),
            source_config_dir=source_config_dir,
            project_root=project_root,
            trusted_cwds=(cwd,),
            startup_authority_binding=startup_authority_binding,
            startup_scratchpad=scratchpad,
            source_snapshot_sha256=source_snapshot_sha256,
        )
        if not preparation.eligible:
            debt = preparation.record["debts"][0]
            raise HeadlessWorkerRuntimeError(
                "Claude provider preparation carries capability debt: "
                f"{debt['code']} ({debt['subject']})"
            )
        public = preparation.public_headless_arguments()
        record = preparation.record
        profile_flags = tuple(record["headless_profile"]["cli_flags"])
        final_template = preparation.command_for_bound_stdin()
    except ClaudeProviderPreparationError as exc:
        raise HeadlessWorkerRuntimeError(
            f"Claude provider preparation failed: {exc}"
        ) from exc
    if (
        not profile_flags
        or tuple(final_template[-len(profile_flags):]) != profile_flags
    ):
        raise HeadlessWorkerRuntimeError(
            "Claude provider command template is not canonically separable"
        )
    base_argv_template = tuple(final_template[:-len(profile_flags)])
    if (
        base_argv_template.count("-p") != 1
        or base_argv_template.count("--model") != 1
        or base_argv_template.index("--model")
        != base_argv_template.index("-p") + 1
    ):
        raise HeadlessWorkerRuntimeError(
            "Claude provider command template is not canonical stdin-only"
        )
    runtime_local_inputs = {
        "ambient_environment": ambient_environment,
        "source_config_dir": source_config_dir,
        "trusted_cwds": (cwd,),
    }
    return _ClaudeDriverProviderAuthority(
        preparation=preparation,
        base_argv_template=base_argv_template,
        public_arguments=public,
        runtime_local_inputs=runtime_local_inputs,
        bound_settings_bytes=bound_settings_bytes,
        selected_mcp_config_bytes=selected_mcp_config_bytes,
    )


def _phase_identity_path(
    identity: str, *, scratchpad: Path, project_root: Path,
) -> Path:
    root, relative = str(identity).split(":", 1)
    if root == "scratchpad":
        return Path(scratchpad) / relative
    if root == "project":
        return Path(project_root) / relative
    raise ValueError(f"unsupported phase artifact root: {root!r}")


def _claude_methodology_read_roots(phase_name: str) -> tuple[Path, ...]:
    """Return the finite legacy methodology capability for one phase.

    Breadth methodology is projected into its prompt before the transaction is
    armed, so granting the installed tree as an additional read root would be
    both unnecessary and incompatible with Claude's project-root restriction.
    """

    if str(phase_name) in {"application_skeptic", "breadth"}:
        return ()
    return (plamen_home(),)


def _prepare_claude_phase_tool_boundary(
    *,
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
    attempt: int,
    prompt_snapshot: Path,
    transaction_output_directory: Path | None = None,
    expected_cwd: Path | None = None,
    contract: PhaseIOContract | None = None,
    launch: LaunchSpec | None = None,
) -> dict[str, Any] | None:
    """Compile a command-free Claude capability boundary for one transaction.

    This is deliberately target-only.  It converts an already-bound PhaseIO
    denominator into runtime Read/Write capabilities and refuses construction
    if the ledger no longer validates those bytes.
    """

    authority_scratchpad = Path(scratchpad)
    supplied_contract = contract
    supplied_launch = launch
    isolated = config.get("_chain_tail_active_isolated")
    if supplied_contract is not None or supplied_launch is not None:
        if supplied_contract is None or supplied_launch is None:
            raise ArtifactLedgerError(
                f"{phase.name}: partial Claude consumer authority is forbidden"
            )
        contract, launch = supplied_contract, supplied_launch
    elif (
        phase.name == "chain_iter2"
        and isinstance(isolated, Mapping)
        and config.get("_chain_tail_authority_scratchpad")
    ):
        authority_scratchpad = Path(
            str(config["_chain_tail_authority_scratchpad"])
        )
        contract, launch = _chain_tail_shard_model_contract_and_launch(
            scratchpad=authority_scratchpad,
            config=config,
            phase=phase,
            isolated=isolated,
        )
    else:
        contract, launch = _typed_model_phase_contract_and_launch(
            phase, Path(scratchpad), config
        )
    if contract is None or launch is None or not contract.model_invoked:
        raise ArtifactLedgerError(
            f"{phase.name}: exact Claude consumer contract is unavailable"
        )
    if str(launch.backend).lower() != "claude":
        return None
    if not _claude_restricted_analysis_launch(phase, launch):
        return None
    root = authority_scratchpad.resolve(strict=True)
    project = Path(config["project_root"]).resolve(strict=True)
    policy_cwd = (
        Path(expected_cwd).resolve(strict=True)
        if expected_cwd is not None else project
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    input_issues = validate_work_unit_inputs(
        root, project, contract, launch, run_id=run_id
    )
    if input_issues:
        raise ArtifactLedgerError(
            f"{phase.name}: exact input authority is invalid before tool policy: "
            + "; ".join(input_issues)
        )
    ledger = read_artifact_ledger(root)
    unit = ledger.get("work_units", {}).get(contract.key)
    if not isinstance(unit, Mapping):
        raise ArtifactLedgerError(
            f"{phase.name}: exact input work-unit receipt is missing"
        )
    input_set_digest = str(unit.get("input_set_digest") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", input_set_digest):
        raise ArtifactLedgerError(
            f"{phase.name}: exact input-set digest is malformed"
        )
    snapshot = Path(prompt_snapshot).resolve(strict=True)
    snapshot_sha = hashlib.sha256(snapshot.read_bytes()).hexdigest()
    transaction_output = (
        Path(os.path.abspath(transaction_output_directory))
        if transaction_output_directory is not None
        else None
    )
    token = hashlib.sha256(
        "\0".join((
            run_id, phase.name, str(attempt), contract.digest,
            input_set_digest, snapshot_sha,
            transaction_output.as_posix() if transaction_output else "canonical",
        )).encode("utf-8")
    ).hexdigest()[:20]
    # Keep this deliberately short.  A normal pytest/project path plus a
    # 64-hex receipt filename can otherwise cross legacy Windows MAX_PATH and
    # turn every otherwise-allowed call into RECEIPT_PERSISTENCE_FAILED.
    boundary_root = root / "_ctp" / token[:16]
    policy_path = boundary_root / "p.json"
    settings_path = boundary_root / "s.json"
    mcp_config_path = boundary_root / "m.json"
    receipt_directory = boundary_root / "r"
    exact_inputs = tuple(contract.immutable_inputs) + tuple(
        contract.bounded_lookup_inputs
    )
    exact_read_files = [
        _phase_identity_path(
            identity, scratchpad=root, project_root=project
        )
        for identity in exact_inputs
    ]
    exact_read_files.append(snapshot)
    exact_write_files = []
    for spec in contract.outputs:
        if transaction_output is None:
            output_path = _phase_identity_path(
                spec.identity, scratchpad=root, project_root=project
            )
        else:
            identity = str(spec.identity)
            if not identity.startswith("scratchpad:"):
                raise ArtifactLedgerError(
                    f"{phase.name}: transactional Claude output is not "
                    f"scratchpad-relative: {identity}"
                )
            relative = identity.removeprefix("scratchpad:")
            candidate = Path(relative)
            if (
                not relative
                or candidate.is_absolute()
                or ".." in candidate.parts
            ):
                raise ArtifactLedgerError(
                    f"{phase.name}: transactional Claude output identity is "
                    f"invalid: {identity}"
                )
            output_path = transaction_output / candidate
        exact_write_files.append(output_path)
    forbidden_names = {
        "rag_validation.md",
        precedent_evidence_authority.AUTHORITY_NAME,
        precedent_evidence_authority.PROPOSALS_NAME,
        precedent_evidence_authority.SOURCE_EVIDENCE_NAME,
        precedent_finding_fact_provider.FACTS_NAME,
    }
    if phase.name in {"chain_agent2", "chain_iter2"}:
        forbidden_names.add(precedent_evidence_authority.REPORT_CONTEXT_NAME)
    if phase.name == "report_index":
        forbidden_names.add(precedent_evidence_authority.CONTEXT_NAME)
    dependency_research = _claude_dependency_research_launch(phase, launch)
    policy_writer = claude_phase_tool_policy.write_policy_bundle
    policy_extra: dict[str, Any] = {}
    if dependency_research:
        obligations_path = root / "external_dependency_obligations.json"
        try:
            obligations = json.loads(
                obligations_path.read_text(encoding="utf-8", errors="strict"),
                object_pairs_hook=_reject_duplicate_json_pairs,
            )
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as exc:
            raise ArtifactLedgerError(
                "recon: R-EXT obligation authority is unreadable"
            ) from exc
        if (
            not isinstance(obligations, Mapping)
            or not isinstance(obligations.get("obligations"), list)
            or not obligations["obligations"]
        ):
            raise ArtifactLedgerError(
                "recon: R-EXT requires nonempty obligations before tool policy"
            )
        policy_writer = (
            claude_phase_tool_policy.write_dependency_research_policy_bundle
        )
        policy_extra = {"obligations": obligations}
    policy, _settings = policy_writer(
        policy_path=policy_path,
        settings_path=settings_path,
        hook_script=Path(claude_phase_tool_policy.__file__),
        run_id=run_id,
        phase=phase.name,
        attempt=attempt,
        expected_cwd=policy_cwd,
        project_root=project,
        scratchpad_root=root,
        methodology_read_roots=_claude_methodology_read_roots(contract.phase),
        exact_read_files=exact_read_files,
        exact_write_files=exact_write_files,
        forbidden_read_files=tuple(root / name for name in sorted(forbidden_names)),
        receipt_directory=receipt_directory,
        **policy_extra,
    )
    mcp_config_path.write_bytes(
        claude_phase_tool_policy.canonical_json_bytes({"mcpServers": {}})
    )
    state = {
        "phase": phase.name,
        "attempt": attempt,
        "contract_key": contract.key,
        "contract_digest": contract.digest,
        "input_set_digest": input_set_digest,
        "manifest_digest": policy["manifest_digest"],
        "policy_path": policy_path.resolve(strict=True).as_posix(),
        "settings_path": settings_path.resolve(strict=True).as_posix(),
        "mcp_config_path": mcp_config_path.resolve(strict=True).as_posix(),
        "receipt_directory": receipt_directory.resolve(strict=True).as_posix(),
        "write_namespace": (
            transaction_output.as_posix()
            if transaction_output is not None
            else "canonical"
        ),
    }
    config.setdefault("_claude_phase_tool_boundaries", {})[phase.name] = state
    return state


def _validate_claude_phase_tool_boundary_outputs(
    phase: Phase, config: Mapping[str, Any], contract: PhaseIOContract,
) -> list[str]:
    """Require hook-authorized output writes before granting model authority."""

    exact_consumer = (
        phase.name in _CLAUDE_EXACT_CONSUMER_PHASES
        or (
            phase.name == "recon"
            and re.fullmatch(
                r"dependency_research(?:\.attempt-[0-9]{4})?",
                str(contract.work_unit_id),
            )
            is not None
        )
    )
    if (
        not exact_consumer
        or str(contract.backend).lower() != "claude"
        or not contract.model_invoked
    ):
        return []
    state = config.get("_claude_phase_tool_boundaries", {}).get(phase.name)
    if not isinstance(state, Mapping):
        return [f"{phase.name}: Claude exact-consumer tool boundary is missing"]
    if (
        state.get("contract_key") != contract.key
        or state.get("contract_digest") != contract.digest
    ):
        return [f"{phase.name}: Claude tool-boundary contract drift"]
    try:
        policy = claude_phase_tool_policy.load_policy(
            Path(str(state.get("policy_path") or ""))
        )
    except (OSError, claude_phase_tool_policy.ClaudePhaseToolPolicyError) as exc:
        return [f"{phase.name}: Claude tool policy is invalid: {exc}"]
    if policy.get("manifest_digest") != state.get("manifest_digest"):
        return [f"{phase.name}: Claude tool policy manifest drift"]
    return claude_phase_tool_policy.validate_write_receipt_coverage(policy)


def _claude_exact_consumer_cli_flags(
    boundary: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return the fail-closed Claude argv suffix for one compiled boundary."""

    settings = Path(str(boundary.get("settings_path") or ""))
    mcp = Path(str(boundary.get("mcp_config_path") or ""))
    if not settings.is_absolute() or not settings.is_file():
        raise ValueError("Claude exact-consumer settings path is unavailable")
    if not mcp.is_absolute() or not mcp.is_file():
        raise ValueError("Claude exact-consumer MCP config path is unavailable")
    policy_path = Path(str(boundary.get("policy_path") or ""))
    if not policy_path.is_absolute() or not policy_path.is_file():
        raise ValueError("Claude exact-consumer tool policy is unavailable")
    policy = claude_phase_tool_policy.load_policy(policy_path)
    written_tools = set(
        claude_phase_tool_policy.provider_builtin_tools(policy)
    )
    # Preserve the established CLI order while deriving the complete set from
    # the actual written policy.  Ordering has no grant semantics, but stable
    # argv bytes matter to launch receipts and compatibility tests.
    provider_tools = tuple(
        value
        for value in (
            "Read", "Glob", "Grep", "Write", "Edit",
            "WebSearch", "WebFetch",
        )
        if value in written_tools
    )
    if set(provider_tools) != written_tools:
        raise ValueError("Claude exact-consumer policy contains an unknown tool")
    if not provider_tools:
        raise ValueError("Claude exact-consumer tool denominator is empty")
    bounded_web = policy.get("external_network_policy") == "BOUNDED_RECEIPTS"
    permission_mode = "default" if bounded_web else "dontAsk"
    return (
        "--permission-mode", permission_mode,
        "--tools", ",".join(provider_tools),
        *(
            ("--allowedTools", "Glob,Grep,Read")
            if bounded_web
            else ()
        ),
        "--disable-slash-commands",
        # A separate empty argv value is dropped by the Windows claude.cmd
        # shim, causing the next flag to be consumed as a setting source.
        # The single-token equals form survives both Windows and POSIX.
        "--setting-sources=",
        "--no-chrome",
        "--settings", settings.as_posix(),
        "--strict-mcp-config", "--mcp-config", mcp.as_posix(),
    )


def _bind_typed_model_phase_inputs(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Persist the exact semantic denominator before a model can execute."""
    if (
        phase.name == "attention_repair"
        and isinstance(
            config.get("_attention_repair_shard_plan"),
            Mapping,
        )
    ):
        # Each bounded leaf receives its own exact source/shard denominator;
        # the aggregate is a separately owned DRIVER transaction.
        return []
    try:
        if phase.name == "chain_iter2":
            from chain_tail_authority import (
                _read_progress_receipt,
                _terminal_publication_is_complete,
            )

            root = Path(scratchpad)
            if _terminal_publication_is_complete(root):
                progress = _read_progress_receipt(root)
                if progress.get("status") in {
                    "DEGRADED_UNRESOLVED",
                    "BUDGET_STOP",
                }:
                    _rearm_receipt, rearm_issues = (
                        _run_chain_tail_rearm_transaction(
                            root,
                            config,
                            phase,
                        )
                    )
                    if rearm_issues:
                        return list(dict.fromkeys(rearm_issues))
            sources = [
                name
                for name in (
                    "composition_coverage.md",
                    "chain_hypotheses.md",
                    "findings_inventory.md",
                    precedent_evidence_authority.CONTEXT_NAME,
                )
                if (root / name).is_file()
                and (
                    name != precedent_evidence_authority.CONTEXT_NAME
                    or bool(
                        config.get(
                            "_precedent_consumer_projection_state", {}
                        ).get(phase.name, False)
                    )
                )
            ]
            isolated, prepare_issues = (
                _run_chain_tail_shard_prepare_transaction(
                    scratchpad=root,
                    config=config,
                    phase=phase,
                    source_names=tuple(sources),
                )
            )
            if prepare_issues:
                return list(dict.fromkeys(prepare_issues))
            if not isolated.get("pair_ids"):
                # The exact zero-work/finalized path is handled before launch.
                return []
            contract, launch = _chain_tail_shard_model_contract_and_launch(
                scratchpad=Path(scratchpad),
                config=config,
                phase=phase,
                isolated=isolated,
            )
            run_id = str(config.get("_run_id") or "test-unbound")
            project_root = Path(
                config.get("project_root") or Path(scratchpad).parent
            )
            record_work_unit_inputs(
                Path(scratchpad),
                project_root,
                contract,
                launch,
                run_id=run_id,
            )
            issues = validate_work_unit_inputs(
                Path(scratchpad),
                project_root,
                contract,
                launch,
                run_id=run_id,
            )
            if not issues:
                config["_chain_tail_active_isolated"] = dict(isolated)
                # The outer generic disk gate now observes the unique transcript.
                # The inner phase clone retains its local `chain_iteration2.md`.
                phase.expected_artifacts = [isolated["transcript_path"]]
            return issues
        contract, launch = _typed_model_phase_contract_and_launch(
            phase, scratchpad, config
        )
        if contract is None or launch is None:
            return []
        run_id = str(config.get("_run_id") or "test-unbound")
        project_root = Path(
            config.get("project_root") or Path(scratchpad).parent
        )
        record_work_unit_inputs(
            Path(scratchpad), project_root, contract, launch, run_id=run_id
        )
        issues = validate_work_unit_inputs(
            Path(scratchpad), project_root, contract, launch, run_id=run_id
        )
        if phase.name.startswith("report_body_writer_"):
            try:
                validate_report_evidence_runtime(Path(scratchpad))
            except (OSError, ReportEvidenceError, ValueError) as exc:
                issues.append(
                    "report body typed evidence authority changed during "
                    f"model input binding: {exc}"
                )
        return issues
    except (ArtifactLedgerError, ReportEvidenceError, OSError, ValueError) as exc:
        return [str(exc)]


def _record_typed_model_phase_artifacts(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
    *,
    allow_report_index_preimage: bool = False,
    _resolved_contract: PhaseIOContract | None = None,
    _resolved_launch: LaunchSpec | None = None,
) -> list[str]:
    """Bind a migrated monolithic model phase to its exact model contract."""
    if (
        phase.name == "attention_repair"
        and isinstance(
            config.get("_attention_repair_shard_plan"),
            Mapping,
        )
    ):
        return []
    try:
        if phase.name == "report_index" and not allow_report_index_preimage:
            # The accepted report-index proposal is recorded inside the
            # Summary-parity transaction immediately before its separately
            # armed DRIVER successor.  Recording it again at the generic parent
            # boundary would retroactively bless the repaired postimage.
            return []
        if phase.name == "chain_iter2" and config.get(
            "_chain_tail_active_isolated"
        ):
            # Each transcript was already committed under its unique MODEL
            # contract before deterministic disposition.  The final aggregate
            # is DRIVER-owned; the legacy global model contract is forbidden.
            return []
        if (_resolved_contract is None) != (_resolved_launch is None):
            raise ArtifactLedgerError(
                "typed MODEL pre-resolved contract/launch pair is incomplete"
            )
        contract, launch = (
            (_resolved_contract, _resolved_launch)
            if _resolved_contract is not None
            else _typed_model_phase_contract_and_launch(
                phase, scratchpad, config
            )
        )
        if contract is None or launch is None:
            return []
        run_id = str(config.get("_run_id") or "test-unbound")
        project_root = Path(
            config.get("project_root") or Path(scratchpad).parent
        )
        # Never create a pre-execution receipt while recovering already-written
        # model bytes.  A legacy output without the original exact receipt is
        # retained proposal-only by the shared commit boundary.
        ledger = read_artifact_ledger(Path(scratchpad))
        unit = ledger.get("work_units", {}).get(contract.key)
        if (
            isinstance(unit, Mapping)
            and unit.get("execution_state") == "OUTPUT_COMMITTED"
        ):
            validation_context = _ArtifactValidationContext(
                Path(scratchpad), project_root, ledger=ledger
            )
            issues = validate_work_unit_inputs(
                Path(scratchpad),
                project_root,
                contract,
                launch,
                run_id=run_id,
                _validation_context=validation_context,
            )
            # Recovery may revisit an exact MODEL proposal after its durable
            # output commit but before the parent phase commit.  Validate that
            # immutable producer instead of attempting a second producer
            # transition, which is correctly forbidden by the ledger.
            issues.extend(_validate_claude_phase_tool_boundary_outputs(
                phase, config, contract
            ))
            issues.extend(validate_work_unit_artifacts(
                scratchpad,
                project_root,
                contract,
                launch,
                run_id=run_id,
                actor="MODEL",
                _validation_context=validation_context,
            ))
            issues.extend(validation_context.finish())
            if unit.get("semantic_status") != "ACTIVE":
                issues.append(
                    f"{contract.key}: committed MODEL producer is not ACTIVE"
                )
            return list(dict.fromkeys(issues))
        issues = validate_work_unit_inputs(
            Path(scratchpad), project_root, contract, launch, run_id=run_id
        )
        if phase.name == "semantic_dedup" and not issues:
            # A typed DRIVER passthrough may exist as a crash-safety or
            # no-work predecessor.  Merely launching the model does not turn
            # those unchanged bytes into MODEL-authored analysis.  Require an
            # actual post-launch byte change before the registered
            # noop_proposal -> model handoff can occur.
            ledger = read_artifact_ledger(Path(scratchpad))
            unit = ledger.get("work_units", {}).get(contract.key)
            prestates = (
                unit.get("output_prestates", {})
                if isinstance(unit, Mapping)
                else {}
            )
            prestate = (
                prestates.get("scratchpad:dedup_decisions.md")
                if isinstance(prestates, Mapping)
                else None
            )
            predecessor = (
                str(prestate.get("predecessor_owner_key") or "")
                if isinstance(prestate, Mapping)
                else ""
            )
            decision_path = Path(scratchpad) / "dedup_decisions.md"
            if (
                predecessor.endswith("/semantic_dedup/noop_proposal")
                and isinstance(prestate, Mapping)
                and prestate.get("status")
                in {"PRESENT", "ACTIVE_REGISTERED_PREDECESSOR"}
                and decision_path.is_file()
            ):
                current_raw = decision_path.read_bytes()
                if (
                    hashlib.sha256(current_raw).hexdigest()
                    == prestate.get("sha256")
                    and len(current_raw) == prestate.get("size")
                ):
                    return [
                        "semantic_dedup/model did not replace the typed DRIVER "
                        "passthrough; unchanged scaffold cannot be attributed "
                        "to MODEL"
                    ]
        issues.extend(_validate_claude_phase_tool_boundary_outputs(
            phase, config, contract
        ))
        record_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="MODEL",
            precommit_issues=issues,
        )
        issues.extend(validate_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="MODEL",
        ))
        return list(dict.fromkeys(issues))
    except (ArtifactLedgerError, ReportEvidenceError, OSError, ValueError) as exc:
        return [str(exc)]


_REPORT_INDEX_SUMMARY_PARITY_RECEIPT = (
    "report_index_summary_parity_receipt.json"
)
_REPORT_INDEX_SUMMARY_PARITY_SCHEMA = (
    "plamen.report_index_summary_parity.v1"
)


def _report_index_summary_parity_attempt_ordinal(
    config: Mapping[str, Any],
) -> int:
    return _attempt_map_ordinal(
        config,
        "_phase_io_model_attempts",
        "report_index",
        default=1,
        minimum=1,
    )


def _report_index_summary_parity_receipt_name(
    config: Mapping[str, Any],
) -> str:
    ordinal = _report_index_summary_parity_attempt_ordinal(config)
    if ordinal == 1:
        return _REPORT_INDEX_SUMMARY_PARITY_RECEIPT
    return (
        "report_index_summary_parity_receipt."
        f"attempt-{ordinal:04d}.json"
    )


def _report_index_summary_parity_contract_and_launch(
    config: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec]:
    ordinal = _report_index_summary_parity_attempt_ordinal(config)
    work_unit_id = (
        "summary_parity"
        if ordinal == 1
        else f"summary_parity.attempt-{ordinal:04d}"
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="report_index",
        work_unit_id=work_unit_id,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _summary_parity_receipt_digest(payload: Mapping[str, Any]) -> str:
    unsigned = {
        key: value for key, value in payload.items()
        if key != "receipt_digest"
    }
    return hashlib.sha256(
        json.dumps(
            unsigned,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _summary_parity_receipt_bytes(payload: Mapping[str, Any]) -> bytes:
    return (
        json.dumps(
            dict(payload),
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        + "\n"
    ).encode("utf-8")


def _build_summary_parity_receipt(
    derivation: Any,
    *,
    contract: PhaseIOContract,
    run_id: str,
    model_work_unit_key: str,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "schema_version": _REPORT_INDEX_SUMMARY_PARITY_SCHEMA,
        "run_id": str(run_id),
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "artifact_identity": "scratchpad:report_index.md",
        "model_work_unit_key": str(model_work_unit_key),
        "before_sha256": str(derivation.before_sha256),
        "before_size": len(derivation.input_bytes),
        "after_sha256": str(derivation.after_sha256),
        "after_size": len(derivation.output_bytes),
        "summary_before_sha256": str(
            derivation.summary_before_sha256
        ),
        "summary_after_sha256": str(derivation.summary_after_sha256),
        "master_section_sha256": str(
            derivation.master_section_sha256
        ),
        "outside_summary_sha256": str(
            derivation.outside_summary_sha256
        ),
        "master_counts": dict(derivation.master_counts),
        "summary_counts_before": dict(derivation.summary_counts),
        "deltas": [
            {"label": label, "change": change}
            for label, change in derivation.deltas
        ],
        "repair_kind": "SUMMARY_COUNTS_FROM_MASTER_CARDINALITY",
    }
    payload["receipt_digest"] = _summary_parity_receipt_digest(payload)
    return payload


def _read_summary_parity_receipt(path: Path) -> tuple[dict[str, Any], bytes]:
    raw = Path(path).read_bytes()
    payload = json.loads(raw.decode("utf-8", errors="strict"))
    if not isinstance(payload, dict):
        raise ValueError("Summary parity receipt must be a JSON object")
    if raw != _summary_parity_receipt_bytes(payload):
        raise ValueError("Summary parity receipt bytes are non-canonical")
    if payload.get("receipt_digest") != _summary_parity_receipt_digest(
        payload
    ):
        raise ValueError("Summary parity receipt digest is invalid")
    return payload, raw


def _validate_summary_parity_receipt(
    payload: Mapping[str, Any],
    *,
    contract: PhaseIOContract,
    run_id: str,
    model_work_unit_key: str,
    prestate: Mapping[str, Any],
    current: bytes,
    before_derivation: Any | None = None,
) -> list[str]:
    issues: list[str] = []
    expected_header = {
        "schema_version": _REPORT_INDEX_SUMMARY_PARITY_SCHEMA,
        "run_id": run_id,
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "artifact_identity": "scratchpad:report_index.md",
        "model_work_unit_key": model_work_unit_key,
        "repair_kind": "SUMMARY_COUNTS_FROM_MASTER_CARDINALITY",
    }
    for field, expected in expected_header.items():
        if payload.get(field) != expected:
            issues.append(
                f"Summary parity receipt {field} mismatch"
            )
    if payload.get("before_sha256") != prestate.get("sha256"):
        issues.append("Summary parity receipt/model preimage digest mismatch")
    if payload.get("before_size") != prestate.get("size"):
        issues.append("Summary parity receipt/model preimage size mismatch")
    if (
        prestate.get("predecessor_owner_key") != model_work_unit_key
        or prestate.get("status") != "ACTIVE_REGISTERED_PREDECESSOR"
    ):
        issues.append(
            "Summary parity successor is not bound to the exact active MODEL "
            "preimage"
        )
    if payload.get("receipt_digest") != _summary_parity_receipt_digest(
        payload
    ):
        issues.append("Summary parity receipt digest is invalid")

    if before_derivation is not None:
        expected = _build_summary_parity_receipt(
            before_derivation,
            contract=contract,
            run_id=run_id,
            model_work_unit_key=model_work_unit_key,
        )
        if dict(payload) != expected:
            issues.append(
                "Summary parity receipt disagrees with the pure preimage "
                "derivation"
            )
    current_sha256 = hashlib.sha256(current).hexdigest()
    if current_sha256 == payload.get("after_sha256"):
        current_derivation = derive_report_index_summary_master_parity(
            current
        )
        if (
            current_derivation.issues
            or current_derivation.repair_required
            or current_derivation.status not in {"CLEAN", "NOT_APPLICABLE"}
        ):
            issues.append(
                "Summary parity postimage is not a clean pure replay"
            )
        if len(current) != payload.get("after_size"):
            issues.append("Summary parity postimage size mismatch")
        for field, observed in (
            (
                "summary_after_sha256",
                current_derivation.summary_before_sha256,
            ),
            (
                "master_section_sha256",
                current_derivation.master_section_sha256,
            ),
            (
                "outside_summary_sha256",
                current_derivation.outside_summary_sha256,
            ),
        ):
            if payload.get(field) != observed:
                issues.append(
                    f"Summary parity postimage {field} mismatch"
                )
    return list(dict.fromkeys(issues))


def _record_report_index_model_preimage(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> tuple[PhaseIOContract | None, list[str]]:
    """Commit the exact accepted MODEL bytes before any Summary mutation."""

    contract, launch = _typed_model_phase_contract_and_launch(
        phase, Path(scratchpad), config
    )
    if contract is None or launch is None:
        return None, ["report_index MODEL PhaseIO contract is unavailable"]
    issues = _record_typed_model_phase_artifacts(
        phase,
        Path(scratchpad),
        config,
        allow_report_index_preimage=True,
        _resolved_contract=contract,
        _resolved_launch=launch,
    )
    if issues:
        return contract, issues
    try:
        ledger = read_artifact_ledger(Path(scratchpad))
        unit = ledger.get("work_units", {}).get(contract.key)
        record = (
            unit.get("artifacts", {}).get("scratchpad:report_index.md")
            if isinstance(unit, Mapping)
            else None
        )
        current = (Path(scratchpad) / "report_index.md").read_bytes()
        if (
            not isinstance(unit, Mapping)
            or unit.get("semantic_status") != "ACTIVE"
            or unit.get("execution_state") != "OUTPUT_COMMITTED"
            or not isinstance(record, Mapping)
            or record.get("writer") != "MODEL"
            or record.get("sha256")
            != hashlib.sha256(current).hexdigest()
            or record.get("size") != len(current)
        ):
            return contract, [
                "report_index raw MODEL preimage did not commit as exact "
                "ACTIVE authority"
            ]
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return contract, [
            "report_index raw MODEL preimage validation failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    return contract, []


def _run_report_index_summary_parity_successor(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
    *,
    fault_inject: Callable[[str], None] | None = None,
) -> list[str]:
    """Record MODEL, then publish or resume one exact Summary-only successor."""

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["report_index Summary parity successor has no run_id"]
    report_path = root / "report_index.md"
    receipt_path = (
        root / _report_index_summary_parity_receipt_name(config)
    )
    contract, launch = _report_index_summary_parity_contract_and_launch(
        config
    )
    passthrough_paths = tuple(
        spec.path
        for spec in contract.outputs
        if spec.path in {"report_coverage.md", "report_records.json"}
    )
    expected_model_contract, _expected_model_launch = (
        _typed_model_phase_contract_and_launch(phase, root, config)
    )
    if expected_model_contract is None:
        return ["report_index Summary parity MODEL contract is unavailable"]

    def fault(point: str) -> None:
        if fault_inject is not None:
            fault_inject(point)

    def passthrough_issues(
        current_ledger: Mapping[str, Any],
        successor_unit: Mapping[str, Any],
        model_contract: PhaseIOContract,
        *,
        committed_successor: bool = False,
    ) -> list[str]:
        """Require exact stable MODEL bytes for every non-derived head member."""

        issues: list[str] = []
        model_unit = current_ledger.get("work_units", {}).get(
            model_contract.key
        )
        if not isinstance(model_unit, Mapping) or (
            model_unit.get("semantic_status") != "ACTIVE"
            or model_unit.get("execution_state") != "OUTPUT_COMMITTED"
            or model_unit.get("run_id") != run_id
            or model_unit.get("contract_digest") != model_contract.digest
            or not _active_commit_receipt_is_valid(
                model_unit,
                work_unit_key=model_contract.key,
                run_id=run_id,
            )
        ):
            return [
                "report_index Summary parity passthrough MODEL authority is "
                "not an active current-run commit"
            ]
        prestates = successor_unit.get("output_prestates", {})
        model_records = model_unit.get("artifacts", {})
        bindings = current_ledger.get("artifact_bindings", {})
        if not isinstance(prestates, Mapping) or not isinstance(
            model_records, Mapping
        ) or not isinstance(bindings, Mapping):
            return [
                "report_index Summary parity passthrough authority is malformed"
            ]
        for relative in passthrough_paths:
            identity = f"scratchpad:{relative}"
            prestate = prestates.get(identity)
            model_record = model_records.get(identity)
            binding = bindings.get(identity)
            if not isinstance(prestate, Mapping) or not isinstance(
                model_record, Mapping
            ) or not isinstance(binding, Mapping):
                issues.append(
                    f"{identity}: Summary parity passthrough prestate is absent"
                )
                continue
            if (
                prestate.get("status")
                != "ACTIVE_REGISTERED_PREDECESSOR"
                or prestate.get("predecessor_owner_key")
                != model_contract.key
                or prestate.get("predecessor_contract_digest")
                != model_contract.digest
                or prestate.get("predecessor_launch_digest")
                != model_unit.get("launch_digest")
                or binding.get("status") != "ACTIVE"
                or binding.get("owner_key")
                != (
                    contract.key
                    if committed_successor
                    else model_contract.key
                )
                or binding.get("run_id") != run_id
                or binding.get("contract_digest")
                != (
                    contract.digest
                    if committed_successor
                    else model_contract.digest
                )
                or binding.get("launch_digest")
                != (
                    launch.digest
                    if committed_successor
                    else model_unit.get("launch_digest")
                )
                or binding.get("writer")
                != ("DRIVER" if committed_successor else "MODEL")
                or model_record.get("writer") != "MODEL"
                or model_record.get("sha256") != prestate.get("sha256")
                or model_record.get("size") != prestate.get("size")
                or binding.get("sha256") != prestate.get("sha256")
                or binding.get("size") != prestate.get("size")
            ):
                issues.append(
                    f"{identity}: Summary parity passthrough is not the exact "
                    "registered MODEL predecessor"
                )
                continue
            try:
                path = root / relative
                first = path.read_bytes()
                second = path.read_bytes()
            except OSError as exc:
                issues.append(
                    f"{identity}: Summary parity passthrough is unreadable: "
                    f"{exc}"
                )
                continue
            if first != second:
                issues.append(
                    f"{identity}: Summary parity passthrough is unstable"
                )
                continue
            if (
                len(first) != prestate.get("size")
                or hashlib.sha256(first).hexdigest()
                != prestate.get("sha256")
            ):
                issues.append(
                    f"{identity}: Summary parity passthrough bytes changed "
                    "after arm"
                )
        return issues

    # Exact committed replay is read-only.  Validate the receipt and current
    # bytes without trying to reactivate historical MODEL authority.
    try:
        ledger = read_artifact_ledger(root)
        existing = ledger.get("work_units", {}).get(contract.key)
    except (ArtifactLedgerError, OSError, TypeError, ValueError):
        existing = None
    if (
        isinstance(existing, Mapping)
        and existing.get("semantic_status") == "ACTIVE"
        and existing.get("execution_state") == "OUTPUT_COMMITTED"
    ):
        replay_issues = validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        try:
            receipt, _raw = _read_summary_parity_receipt(receipt_path)
            prestate = existing.get("output_prestates", {}).get(
                "scratchpad:report_index.md"
            )
            if not isinstance(prestate, Mapping):
                raise ValueError("Summary parity output prestate is missing")
            replay_issues.extend(_validate_summary_parity_receipt(
                receipt,
                contract=contract,
                run_id=run_id,
                model_work_unit_key=str(
                    prestate.get("predecessor_owner_key") or ""
                ),
                prestate=prestate,
                current=report_path.read_bytes(),
            ))
            replay_issues.extend(
                passthrough_issues(
                    ledger,
                    existing,
                    expected_model_contract,
                    committed_successor=True,
                )
            )
        except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
            replay_issues.append(
                "Summary parity committed replay is invalid: "
                f"{type(exc).__name__}: {exc}"
            )
        return list(dict.fromkeys(replay_issues))

    try:
        current_before_arm = report_path.read_bytes()
    except OSError as exc:
        return [f"report_index MODEL preimage is unreadable: {exc}"]
    armed_recovery = bool(
        isinstance(existing, Mapping)
        and existing.get("semantic_status") == "INPUTS_BOUND"
        and existing.get("execution_state") == "INPUTS_BOUND_PREEXECUTION"
        and existing.get("artifacts") == {}
    )
    derivation: Any | None = None
    if armed_recovery:
        prestate = existing.get("output_prestates", {}).get(
            "scratchpad:report_index.md"
        )
        if not isinstance(prestate, Mapping):
            return ["report_index Summary parity recovery prestate is missing"]
        model_contract = expected_model_contract
        if (
            model_contract.key != prestate.get("predecessor_owner_key")
        ):
            return [
                "report_index Summary parity recovery MODEL identity drift"
            ]
        current_sha256 = hashlib.sha256(current_before_arm).hexdigest()
        if current_sha256 == prestate.get("sha256"):
            derivation = derive_report_index_summary_master_parity(
                current_before_arm
            )
            if derivation.issues or not derivation.repair_required:
                return list(derivation.issues) or [
                    "report_index Summary parity armed preimage no longer "
                    "requires its planned repair"
                ]
        elif receipt_path.is_file():
            try:
                recovery_receipt, _receipt_raw = (
                    _read_summary_parity_receipt(receipt_path)
                )
            except (
                OSError,
                UnicodeError,
                ValueError,
                json.JSONDecodeError,
            ) as exc:
                return [
                    "report_index Summary parity recovery receipt invalid: "
                    f"{type(exc).__name__}: {exc}"
                ]
            if current_sha256 != recovery_receipt.get("after_sha256"):
                return [
                    "REPORT_INDEX_SUMMARY_PARITY_ARBITRARY_THIRD_STATE: "
                    "current report_index.md matches neither the armed MODEL "
                    "preimage nor the receipt-bound DRIVER successor; bytes "
                    "preserved as debt"
                ]
        else:
            return [
                "REPORT_INDEX_SUMMARY_PARITY_ARBITRARY_THIRD_STATE: current "
                "report_index.md differs from the armed MODEL preimage and no "
                "successor receipt exists; bytes preserved as debt"
            ]
    else:
        model_contract, model_issues = _record_report_index_model_preimage(
            phase, root, config
        )
        if model_issues or model_contract is None:
            return list(dict.fromkeys(model_issues))
        # Re-read after the atomic MODEL commit and bind the pure derivation to
        # exactly those committed bytes.
        try:
            current_before_arm = report_path.read_bytes()
        except OSError as exc:
            return [f"report_index MODEL preimage is unreadable: {exc}"]
        derivation = derive_report_index_summary_master_parity(
            current_before_arm
        )
        if derivation.issues:
            return list(derivation.issues)
        if not derivation.repair_required:
            return []

    fault("before_successor_arm")
    execute, arm_issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    if arm_issues:
        return arm_issues
    if not execute:
        return [
            "report_index Summary parity successor is neither executable nor "
            "a valid committed replay"
        ]
    fault("after_successor_arm")

    try:
        ledger = read_artifact_ledger(root)
        unit = ledger.get("work_units", {}).get(contract.key)
        prestate = (
            unit.get("output_prestates", {}).get(
                "scratchpad:report_index.md"
            )
            if isinstance(unit, Mapping)
            else None
        )
        receipt_prestate = (
            unit.get("output_prestates", {}).get(
                f"scratchpad:{receipt_path.name}"
            )
            if isinstance(unit, Mapping)
            else None
        )
        if (
            not isinstance(unit, Mapping)
            or unit.get("semantic_status") != "INPUTS_BOUND"
            or unit.get("execution_state") != "INPUTS_BOUND_PREEXECUTION"
            or not isinstance(prestate, Mapping)
            or not isinstance(receipt_prestate, Mapping)
        ):
            return ["report_index Summary parity arm receipt is malformed"]
        model_key = model_contract.key
        model_unit = ledger.get("work_units", {}).get(model_key)
        model_record = (
            model_unit.get("artifacts", {}).get(
                "scratchpad:report_index.md"
            )
            if isinstance(model_unit, Mapping)
            else None
        )
        if (
            prestate.get("predecessor_owner_key") != model_key
            or prestate.get("status") != "ACTIVE_REGISTERED_PREDECESSOR"
            or not isinstance(model_record, Mapping)
            or model_record.get("writer") != "MODEL"
            or model_record.get("sha256") != prestate.get("sha256")
            or model_record.get("size") != prestate.get("size")
            or (
                derivation is not None
                and (
                    prestate.get("sha256") != derivation.before_sha256
                    or prestate.get("size")
                    != len(derivation.input_bytes)
                )
            )
        ):
            return [
                "report_index Summary parity arm is not bound to the exact "
                "raw MODEL preimage"
            ]
        passthrough_arm_issues = passthrough_issues(
            ledger,
            unit,
            model_contract,
        )
        if passthrough_arm_issues:
            return passthrough_arm_issues

        if receipt_path.is_file():
            receipt, _receipt_raw = _read_summary_parity_receipt(receipt_path)
        else:
            if receipt_prestate.get("status") != "ABSENT":
                return [
                    "report_index Summary parity receipt has an untrusted "
                    "pre-existing state"
                ]
            if derivation is None:
                return [
                    "report_index Summary parity successor postimage has no "
                    "durable receipt; bytes preserved as debt"
                ]
            receipt = _build_summary_parity_receipt(
                derivation,
                contract=contract,
                run_id=run_id,
                model_work_unit_key=model_key,
            )
            _atomic_driver_bytes(
                receipt_path, _summary_parity_receipt_bytes(receipt)
            )
        receipt_issues = _validate_summary_parity_receipt(
            receipt,
            contract=contract,
            run_id=run_id,
            model_work_unit_key=model_key,
            prestate=prestate,
            current=report_path.read_bytes(),
            before_derivation=(
                derivation
                if hashlib.sha256(report_path.read_bytes()).hexdigest()
                == prestate.get("sha256")
                else None
            ),
        )
        if receipt_issues:
            return receipt_issues
        fault("after_successor_receipt_write")

        current = report_path.read_bytes()
        current_sha256 = hashlib.sha256(current).hexdigest()
        if current_sha256 == receipt.get("before_sha256"):
            current_derivation = derive_report_index_summary_master_parity(
                current
            )
            if current_derivation.issues or not (
                current_derivation.repair_required
            ):
                return list(current_derivation.issues) or [
                    "report_index Summary parity preimage is no longer "
                    "repairable"
                ]
            expected_receipt = _build_summary_parity_receipt(
                current_derivation,
                contract=contract,
                run_id=run_id,
                model_work_unit_key=model_key,
            )
            if (
                dict(receipt) != expected_receipt
            ):
                return [
                    "report_index Summary parity preimage no longer derives "
                    "the receipt-bound successor"
                ]
            derivation = current_derivation
            _atomic_driver_bytes(report_path, current_derivation.output_bytes)
            current = report_path.read_bytes()
            fault("after_successor_report_write")
        elif current_sha256 == receipt.get("after_sha256"):
            # Post-write/pre-commit recovery: validate below, never rewrite.
            pass
        else:
            return [
                "REPORT_INDEX_SUMMARY_PARITY_ARBITRARY_THIRD_STATE: current "
                "report_index.md matches neither the exact MODEL preimage nor "
                "the receipt-bound DRIVER successor; bytes preserved as debt"
            ]

        post_issues = _validate_summary_parity_receipt(
            receipt,
            contract=contract,
            run_id=run_id,
            model_work_unit_key=model_key,
            prestate=prestate,
            current=current,
        )
        if post_issues:
            return post_issues
        fault("before_successor_commit")
        precommit_ledger = read_artifact_ledger(root)
        precommit_unit = precommit_ledger.get("work_units", {}).get(
            contract.key
        )
        if not isinstance(precommit_unit, Mapping):
            return [
                "report_index Summary parity precommit authority is missing"
            ]
        precommit_passthrough_issues = passthrough_issues(
            precommit_ledger,
            precommit_unit,
            model_contract,
        )
        if precommit_passthrough_issues:
            return precommit_passthrough_issues
        return _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
    except (
        ArtifactLedgerError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "report_index Summary parity successor degraded: "
            f"{type(exc).__name__}: {exc}"
        ]


def _quarantine_inventory_chunk_model_attempt(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
    attempt: int,
) -> list[str]:
    """Terminalize one rejected chunk proposal before a retry can launch."""

    try:
        attempts = _mutable_attempt_map(config, "_phase_io_model_attempts")
        attempts[phase.name] = _exact_attempt_ordinal(
            attempt, label=f"{phase.name} quarantine"
        )
        contract, launch = _typed_model_phase_contract_and_launch(
            phase, Path(scratchpad), config
        )
        if contract is None or launch is None:
            return [f"{phase.name}: prior MODEL attempt contract is unavailable"]
        project_root = Path(
            config.get("project_root") or Path(scratchpad).parent
        )
        run_id = str(config.get("_run_id") or "test-unbound")
        input_issues = validate_work_unit_inputs(
            Path(scratchpad),
            project_root,
            contract,
            launch,
            run_id=run_id,
        )
        record_work_unit_artifacts(
            Path(scratchpad),
            project_root,
            contract,
            launch,
            run_id=run_id,
            status="QUARANTINED",
            actor="MODEL",
            precommit_issues=(
                *input_issues,
                f"{phase.name}: attempt {attempt} rejected before retry",
            ),
        )
        return []
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        return [
            f"{phase.name}: prior MODEL attempt quarantine failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _report_index_mechanical_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the L1 mechanical index transaction."""

    r10_consumer_issues = _r10_report_consumer_ready_issues(
        Path(scratchpad), config
    )
    if r10_consumer_issues:
        raise ArtifactLedgerError(
            "report_index/mechanical R10 consumer authority is invalid: "
            + "; ".join(r10_consumer_issues[:8])
        )

    exact_inputs = [
        "verification_queue.md", "finding_mapping.md", "dedup_decisions.md",
        *_report_candidate_input_paths(
            Path(scratchpad),
            run_id=str(config.get("_run_id") or "") or None,
        ),
    ]
    exact_inputs = list(dict.fromkeys(exact_inputs))
    lifecycle_inputs = (
        security_obligation_lifecycle.AUTHORITY_FILE,
        security_obligation_lifecycle.PROJECTION_FILE,
        security_obligation_lifecycle.REPORT_RETENTION_FILE,
    )
    if all((Path(scratchpad) / name).is_file() for name in lifecycle_inputs):
        exact_inputs.extend(lifecycle_inputs)
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "l1"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="report_index",
        work_unit_id="mechanical",
        exact_inputs=tuple(exact_inputs),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _arm_report_index_mechanical_artifacts(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[bool, list[str]]:
    """Bind the mechanical index denominator before its first write."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return False, ["report-index mechanical PhaseIO run_id is absent"]
    try:
        contract, launch = _report_index_mechanical_contract_and_launch(
            root, config
        )
        return _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=Path(str(config.get("project_root") or root.parent)),
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return False, [
            "report-index mechanical PhaseIO prebind failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _record_report_index_mechanical_artifacts(
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Commit L1 mechanical index bytes only from a prebound execution."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["report-index mechanical PhaseIO run_id is absent"]
    try:
        contract, launch = _report_index_mechanical_contract_and_launch(
            root, config
        )
        return _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=Path(str(config.get("project_root") or root.parent)),
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "report-index mechanical PhaseIO commit failed: "
            f"{type(exc).__name__}: {exc}"
        ]


_REPORT_INDEX_CANONICAL_RECEIPT = (
    "report_index_canonicalization_receipt.json"
)
_REPORT_INDEX_CANONICAL_SCHEMA = "plamen.report_index_canonicalization.v1"
_REPORT_INDEX_CANONICAL_JOURNAL = (
    "report_index_canonicalization_journal.json"
)
_REPORT_INDEX_CANONICAL_JOURNAL_SCHEMA = (
    "plamen.report_index_canonicalization_journal.v1"
)
_REPORT_INDEX_CANONICAL_OUTPUTS = (
    "report_index.md",
    "report_coverage.md",
    "report_index_status_projection.json",
    "_severity_override_ledger.json",
    "severity_overrides.md",
    "report_dropout_retention.json",
    "report_semantic_report_dropouts.md",
    _REPORT_INDEX_CANONICAL_RECEIPT,
)


def _report_index_canonical_work_unit_id(
    config: Mapping[str, Any],
) -> str:
    ordinal = _report_index_summary_parity_attempt_ordinal(config)
    if ordinal == 1:
        return "canonicalize"
    return f"canonicalize.attempt-{ordinal:04d}"


def _report_verifier_phaseio_graph_paths(root: Path) -> tuple[str, ...]:
    """Enumerate exact scratchpad bytes read by verifier producer replay.

    The report validator replays every output and semantic input of the MODEL
    work unit that owns a verifier result.  A hand-maintained suffix list can
    therefore copy the visible receipt while omitting an operator application
    or context input, producing split authority in the isolated stage.
    """

    scratchpad = Path(root)
    ledger_path = scratchpad / "_artifact_state.json"
    if not ledger_path.is_file():
        return ()
    ledger = read_artifact_ledger(scratchpad)
    bindings = ledger.get("artifact_bindings")
    units = ledger.get("work_units")
    if not isinstance(bindings, Mapping) or not isinstance(units, Mapping):
        raise ValueError("verifier PhaseIO graph ledger tables are malformed")
    paths: set[str] = set()
    for output in sorted(scratchpad.glob("verify_*.md")):
        if not output.is_file() or output.is_symlink():
            continue
        identity = f"scratchpad:{output.name}"
        binding = bindings.get(identity)
        if not isinstance(binding, Mapping):
            continue
        owner_key = str(binding.get("owner_key") or "")
        unit = units.get(owner_key)
        if not isinstance(unit, Mapping):
            raise ValueError(
                f"verifier PhaseIO owner is absent for {output.name}"
            )
        for table_name in ("artifacts", "input_bindings"):
            table = unit.get(table_name)
            if not isinstance(table, Mapping):
                raise ValueError(
                    f"verifier PhaseIO {table_name} is malformed for "
                    f"{output.name}"
                )
            for raw_identity, record in table.items():
                scope, separator, relative = str(raw_identity).partition(":")
                if (
                    not separator
                    or scope != "scratchpad"
                    or not isinstance(record, Mapping)
                    or record.get("status") != "ACTIVE"
                ):
                    continue
                candidate = scratchpad / Path(relative)
                if not candidate.is_file() or candidate.is_symlink():
                    raise ValueError(
                        "verifier PhaseIO graph artifact is unavailable: "
                        f"{raw_identity}"
                    )
                raw = candidate.read_bytes()
                if (
                    record.get("sha256")
                    != hashlib.sha256(raw).hexdigest()
                    or record.get("size") != len(raw)
                ):
                    raise ValueError(
                        "verifier PhaseIO graph artifact is stale: "
                        f"{raw_identity}"
                    )
                paths.add(PurePosixPath(relative).as_posix())
    return tuple(sorted(paths))


def _report_verifier_phaseio_authority_projection(
    root: Path,
) -> dict[str, Any]:
    """Project only verifier producer authority from the mutable ledger.

    The full artifact ledger necessarily changes when the canonical report
    work unit arms, quarantines, retries, and commits.  Binding its raw bytes
    would make a deterministic retry produce different journal/receipt bytes.
    This projection retains exactly the verifier MODEL and control work units
    consumed by completion replay, excluding unrelated orchestration history.
    """

    scratchpad = Path(root)
    ledger = read_artifact_ledger(scratchpad)
    bindings = ledger.get("artifact_bindings")
    units = ledger.get("work_units")
    if not isinstance(bindings, Mapping) or not isinstance(units, Mapping):
        raise ValueError("verifier authority projection ledger is malformed")
    relative_paths = set(_report_verifier_phaseio_graph_paths(scratchpad))
    runtime_root = scratchpad / "_verifier_runtime_units"
    if runtime_root.is_dir() and not runtime_root.is_symlink():
        for pattern in ("*/gate_receipt.json", "*/unit_receipt.json"):
            relative_paths.update(
                path.relative_to(scratchpad).as_posix()
                for path in runtime_root.glob(pattern)
                if path.is_file() and not path.is_symlink()
            )

    selected_bindings: dict[str, Any] = {}
    selected_units: dict[str, Any] = {}
    for relative in sorted(relative_paths):
        identity = f"scratchpad:{relative}"
        binding = bindings.get(identity)
        if not isinstance(binding, Mapping):
            # Several receipt-only compatibility artifacts are intentionally
            # not PhaseIO-owned.  They contribute bytes through the contract,
            # but no producer record can be projected for them.
            continue
        selected_bindings[identity] = dict(binding)
        owner_key = str(binding.get("owner_key") or "")
        unit = units.get(owner_key)
        if owner_key and isinstance(unit, Mapping):
            selected_units[owner_key] = dict(unit)
    return {
        "schema_version": "plamen.report_verifier_phaseio_authority.v1",
        "artifact_bindings": {
            key: selected_bindings[key] for key in sorted(selected_bindings)
        },
        "work_units": {
            key: selected_units[key] for key in sorted(selected_units)
        },
    }


def _report_index_canonical_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec]:
    root = Path(scratchpad)
    r10_consumer_issues = _r10_report_consumer_ready_issues(root, config)
    if r10_consumer_issues:
        raise ArtifactLedgerError(
            "report_index/canonical R10 consumer authority is invalid: "
            + "; ".join(r10_consumer_issues[:8])
        )
    configured = config.get("_phase_io_exact_inputs")
    configured_report_inputs = (
        configured.get("report_index", ())
        if isinstance(configured, Mapping)
        else ()
    )
    exact_inputs_set = {
        str(value)
        for value in configured_report_inputs
        if str(value or "").strip()
    }
    exact_inputs_set.update(_report_candidate_input_paths(
        root,
        run_id=str(config.get("_run_id") or "") or None,
    ))
    # The canonical DRIVER successor performs deterministic repairs that read
    # exact verifier/mechanical authority artifacts beyond the model's compact
    # prompt denominator.  Bind those bytes explicitly; staging must never
    # discover semantic inputs through an unregistered directory scan.
    direct_candidates = {
        "config.json",
        "report_index_coverage_seed.md",
        "verification_queue.md",
        "verification_queue.work_items.json",
        "verification_queue.work_plan.json",
        "finding_mapping.md",
        "dedup_decisions.md",
        "severity_binding.md",
        "status_binding.md",
        "build_status.md",
        "depth_identity_preservation_debt.json",
        "external_assumption_undemotion_compute.json",
        "external_assumption_undemotions.json",
        "external_assumption_undemotion_debt.json",
        "external_assumption_undemotions.md",
        "mechanical_verify_manifest.json",
        "verdict_manifest.json",
        "mechanical_successor_authority.json",
        "verification_runtime_roster.json",
        "verification_runtime_debt.json",
        "verification_runtime_debt.md",
        "_v2_checkpoint.json",
        "severity_decision_ledger.shadow.json",
        "trust_evidence_authority.json",
        "trust_evidence_provider_receipt.json",
    }
    exact_inputs_set.update(
        name for name in direct_candidates
        if (root / name).is_file()
    )
    for pattern in (
        "verify_*.md",
        "verify_*.identity.json",
        "verify_*.receipt.json",
        "verify_*.severity_proposal.json",
        "verify_*.mechanical_successor.receipt.json",
    ):
        exact_inputs_set.update(
            path.relative_to(root).as_posix()
            for path in root.glob(pattern)
            if path.is_file() and not path.is_symlink()
        )
    try:
        exact_inputs_set.update(_report_verifier_phaseio_graph_paths(root))
    except Exception as exc:
        raise ValueError(
            "report-index canonical verifier PhaseIO enumeration failed: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    # Negative-closure decisions are authoritative only through the validated
    # transitive provider graph.  Recursive directory membership is not
    # semantics: unrelated receipts, diagnostics, and stale files must neither
    # expand nor stale this transaction.
    try:
        exact_inputs_set.update(
            central_negative_closure_provider_read_set(root)
        )
    except Exception as exc:
        raise ValueError(
            "report-index canonical negative-closure enumeration failed: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    try:
        disposition = build_report_disposition_authority(
            root,
            run_id=str(config.get("_run_id") or "validation-unbound"),
        )
    except Exception as exc:
        raise ValueError(
            "report-index canonical source-authority enumeration failed: "
            f"{type(exc).__name__}: {exc}"
        ) from exc
    for row in disposition.get("source_artifacts") or []:
        if not isinstance(row, Mapping):
            continue
        relative = str(row.get("path") or "").strip()
        if relative and (root / relative).is_file():
            exact_inputs_set.add(relative)
    # This file is a root-addressed replay projection.  Binding/copying it
    # into the off-live stage would make the stage compare a live-root digest
    # against a different root and would incorrectly turn a valid provider
    # bundle into negative-closure debt.  The exact bundle sources above are
    # the authority and the stage deterministically rebuilds this projection.
    exact_inputs_set.discard("negative_closure_broker_authority.json")
    canonical_outputs = set(_REPORT_INDEX_CANONICAL_OUTPUTS) | {
        "report_records.json",
    }
    exact_inputs = tuple(sorted(
        value for value in exact_inputs_set
        if value not in canonical_outputs
    ))
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="report_index",
        work_unit_id=_report_index_canonical_work_unit_id(config),
        exact_inputs=tuple(exact_inputs),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _report_index_canonical_receipt_name(
    contract: PhaseIOContract,
) -> str:
    names = [
        item.path for item in contract.outputs
        if item.path.startswith("report_index_canonicalization_receipt")
        and item.path.endswith(".json")
    ]
    if len(names) != 1:
        raise ValueError(
            "report-index canonical contract has no singular receipt output"
        )
    return names[0]


def _canonical_json_bytes(payload: Mapping[str, Any]) -> bytes:
    return (
        json.dumps(
            dict(payload),
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        + "\n"
    ).encode("utf-8")


def _ensure_report_index_canonical_zero_row_envelope(
    scratchpad: Path,
    *,
    pipeline: str,
) -> tuple[bool, list[str]]:
    """Materialize one deterministic report bundle for an exact empty queue.

    Empty is an authenticated denominator state, not the absence of parseable
    rows.  The report-index model/mechanical predecessor may express it as
    prose, but downstream status, parity, routing, and resume code require the
    same typed table envelope as a non-empty audit.
    """

    root = Path(scratchpad)
    candidate_count, issues = validate_report_candidate_denominator(root)
    if issues:
        return False, list(dict.fromkeys(issues))
    if candidate_count != 0:
        return False, []

    index = (
        "# Report Index\n\n"
        "## Summary Counts\n\n"
        "| Severity | Count |\n"
        "|----------|-------|\n"
        "| Critical | 0 |\n"
        "| High | 0 |\n"
        "| Medium | 0 |\n"
        "| Low | 0 |\n"
        "| Informational | 0 |\n"
        "| Total | 0 |\n\n"
        "## Master Finding Index\n\n"
        "| Report ID | Title | Severity | Location | Verification | "
        "Trust Adj. | Internal Hypothesis ID |\n"
        "|-----------|-------|----------|----------|--------------|"
        "------------|------------------------|\n\n"
        "_No reportable findings exist in the authenticated candidate "
        "denominator._\n\n"
        "## Excluded Findings\n\n"
        "| Source ID | Reason |\n"
        "|-----------|--------|\n\n"
        "_No candidate required an excluded or non-body disposition._\n"
    ).encode("utf-8")
    coverage = (
        "# Report Coverage\n\n"
        "This is the deterministic zero-row projection of the authenticated "
        "verification denominator.\n\n"
        "## Raw Candidate Ledger\n\n"
        "| Source Artifact | Candidate ID | Disposition |\n"
        "|-----------------|--------------|-------------|\n\n"
        "_No candidates were present; the exact denominator count is zero._\n"
    ).encode("utf-8")
    _atomic_driver_bytes(root / "report_index.md", index)
    _atomic_driver_bytes(root / "report_coverage.md", coverage)
    if str(pipeline or "").strip().lower() == "l1":
        _atomic_driver_bytes(
            root / "report_records.json",
            _canonical_json_bytes({
                "schema_version": "plamen.report_records.v1",
                "source": "report_index.md",
                "active": [],
                "excluded": [],
                "consolidation_map": [],
            }),
        )
    return True, []


def _ensure_empty_report_index_canonical_outputs(
    scratchpad: Path,
    *,
    reset_optional: bool = False,
) -> None:
    """Publish deterministic empty envelopes for optional repair classes."""

    root = Path(scratchpad)
    status_projection = root / "report_index_status_projection.json"
    if not status_projection.is_file():
        _project_report_index_status_authority(root)

    severity_json = root / "_severity_override_ledger.json"
    severity_md = root / "severity_overrides.md"
    if reset_optional or not severity_json.is_file():
        _atomic_driver_bytes(
            severity_json,
            _canonical_json_bytes({
                "schema_version": "plamen.severity_overrides.v1",
                "row_count": 0,
                "overrides": [],
            }),
        )
    if reset_optional or not severity_md.is_file():
        _atomic_driver_bytes(
            severity_md,
            (
                "# Severity Overrides (Auto-Correction Ledger)\n\n"
                "No deterministic severity override was required.\n"
            ).encode("utf-8"),
        )

    dropout_projection = root / "report_semantic_report_dropouts.md"
    dropout_receipt = root / "report_dropout_retention.json"
    if reset_optional or not dropout_projection.is_file():
        projection = (
            "# Report Index Dropout Retention\n\n"
            "**Retention target**: HUMAN_REVIEW\n\n"
            "No omitted candidate required dropout retention.\n"
        ).encode("utf-8")
        _atomic_driver_bytes(dropout_projection, projection)
    if reset_optional or not dropout_receipt.is_file():
        projection = dropout_projection.read_bytes()
        unsigned = {
            "schema_version": "plamen.report_dropout_retention.v1",
            "projection_artifact": dropout_projection.name,
            "projection_sha256": hashlib.sha256(projection).hexdigest(),
            "row_count": 0,
            "rows": [],
        }
        payload = {
            **unsigned,
            "receipt_sha256": hashlib.sha256(
                json.dumps(
                    unsigned,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
        }
        _atomic_driver_bytes(
            dropout_receipt,
            (
                json.dumps(payload, indent=2, sort_keys=True) + "\n"
            ).encode("utf-8"),
        )


def _report_index_bundle_records(
    scratchpad: Path,
    names: Sequence[str],
) -> dict[str, dict[str, Any]]:
    records: dict[str, dict[str, Any]] = {}
    for name in names:
        path = Path(scratchpad) / name
        raw = path.read_bytes()
        records[name] = {
            "sha256": hashlib.sha256(raw).hexdigest(),
            "size": len(raw),
        }
    return records


def _report_index_bundle_records_from_bytes(
    values: Mapping[str, bytes],
) -> dict[str, dict[str, Any]]:
    return {
        str(name): {
            "sha256": hashlib.sha256(bytes(raw)).hexdigest(),
            "size": len(bytes(raw)),
        }
        for name, raw in sorted(values.items())
    }


def _report_index_canonical_target_bytes(
    staged_target: Path,
    contract: PhaseIOContract,
) -> dict[str, bytes]:
    stage = Path(staged_target)
    values: dict[str, bytes] = {}
    for item in contract.outputs:
        path = stage / Path(item.path)
        if not path.is_file() or path.is_symlink():
            raise ValueError(
                "report-index canonical target output is unavailable: "
                f"{item.path}"
            )
        values[item.path] = path.read_bytes()
    return values


def _report_index_canonical_stage_allowed_paths(
    contract: PhaseIOContract,
) -> set[str]:
    """Return the only files permitted inside an off-live canonical stage."""

    allowed = {
        item.path for item in contract.outputs
    } | {
        # Stage-local copy of the already validated post-arm ledger.  Dynamic
        # verifier receipts require their producer graph, while the mutable
        # live ledger itself cannot be a self-referential PhaseIO input.
        "_artifact_state.json",
    }
    for identity in (
        *contract.immutable_inputs,
        *contract.bounded_lookup_inputs,
    ):
        scope, separator, relative = str(identity).partition(":")
        if separator and scope == "scratchpad" and relative:
            allowed.add(PurePosixPath(relative).as_posix())
    return allowed


def _report_index_canonical_stage_file_bytes(
    stage: Path,
    *,
    contract: PhaseIOContract,
) -> tuple[dict[str, bytes], list[str]]:
    """Read one exact, symlink-free snapshot of the staged file denominator."""

    root = Path(stage)
    allowed = _report_index_canonical_stage_allowed_paths(contract)
    snapshot: dict[str, bytes] = {}
    issues: list[str] = []
    try:
        for path in sorted(
            root.rglob("*"), key=lambda value: value.as_posix()
        ):
            if path.is_symlink():
                issues.append(
                    "REPORT_INDEX_CANONICAL_STAGE_UNSAFE_ENTRY: "
                    f"{path.relative_to(root).as_posix()}"
                )
                continue
            if not path.is_file():
                continue
            relative = path.relative_to(root).as_posix()
            if relative not in allowed:
                issues.append(
                    "REPORT_INDEX_CANONICAL_STAGE_UNDECLARED_FILE: "
                    f"{relative}"
                )
                continue
            snapshot[relative] = path.read_bytes()
    except (OSError, ValueError) as exc:
        issues.append(
            "REPORT_INDEX_CANONICAL_STAGE_SNAPSHOT_FAILED: "
            f"{type(exc).__name__}: {exc}"
        )
    return snapshot, list(dict.fromkeys(issues))


def _report_index_canonical_stage_immutable_records(
    stage: Path,
    *,
    contract: PhaseIOContract,
) -> tuple[dict[str, bytes], list[str]]:
    """Seal exact immutable input bytes before any staged transform runs."""

    root = Path(stage)
    records: dict[str, bytes] = {}
    issues: list[str] = []
    for identity in (
        *contract.immutable_inputs,
        *contract.bounded_lookup_inputs,
    ):
        scope, separator, relative = str(identity).partition(":")
        if not separator or scope != "scratchpad":
            continue
        path = root / Path(relative)
        if not path.is_file() or path.is_symlink():
            issues.append(
                "REPORT_INDEX_CANONICAL_STAGE_INPUT_ABSENT: "
                f"{identity}"
            )
            continue
        try:
            records[PurePosixPath(relative).as_posix()] = path.read_bytes()
        except OSError as exc:
            issues.append(
                "REPORT_INDEX_CANONICAL_STAGE_INPUT_UNREADABLE: "
                f"{identity}: {type(exc).__name__}: {exc}"
            )
    ledger_projection = root / "_artifact_state.json"
    if ledger_projection.is_file() and not ledger_projection.is_symlink():
        try:
            records["_artifact_state.json"] = ledger_projection.read_bytes()
        except OSError as exc:
            issues.append(
                "REPORT_INDEX_CANONICAL_STAGE_INPUT_UNREADABLE: "
                "scratchpad:_artifact_state.json: "
                f"{type(exc).__name__}: {exc}"
            )
    return records, list(dict.fromkeys(issues))


def _report_index_canonical_stage_integrity_issues(
    stage: Path,
    *,
    contract: PhaseIOContract,
    immutable_records: Mapping[str, bytes],
    expected_state: Mapping[str, bytes] | None = None,
) -> list[str]:
    """Reject input drift, undeclared files, or an altered transform boundary."""

    observed, issues = _report_index_canonical_stage_file_bytes(
        stage, contract=contract
    )
    for relative, expected in immutable_records.items():
        if observed.get(relative) != expected:
            issues.append(
                "REPORT_INDEX_CANONICAL_STAGE_INPUT_DRIFT: "
                f"{relative}"
            )
    if expected_state is not None:
        expected = dict(expected_state)
        if set(observed) != set(expected):
            issues.append(
                "REPORT_INDEX_CANONICAL_STAGE_DENOMINATOR_DRIFT: "
                f"expected={sorted(expected)}, observed={sorted(observed)}"
            )
        for relative in sorted(set(observed) & set(expected)):
            if observed[relative] != expected[relative]:
                issues.append(
                    "REPORT_INDEX_CANONICAL_STAGE_TRANSFORM_DRIFT: "
                    f"{relative}"
                )
    return list(dict.fromkeys(issues))


def _report_index_bundle_state(
    scratchpad: Path,
    names: Sequence[str],
) -> dict[str, dict[str, Any]]:
    state: dict[str, dict[str, Any]] = {}
    for name in names:
        path = Path(scratchpad) / name
        if not path.is_file():
            state[name] = {"status": "ABSENT", "sha256": "", "size": 0}
            continue
        raw = path.read_bytes()
        state[name] = {
            "status": "ACTIVE",
            "sha256": hashlib.sha256(raw).hexdigest(),
            "size": len(raw),
        }
    return state


def _report_index_canonical_state_names(
    contract: PhaseIOContract,
) -> tuple[str, ...]:
    receipt_name = _report_index_canonical_receipt_name(contract)
    return tuple(
        item.path for item in contract.outputs
        if item.path not in {
            receipt_name,
            _REPORT_INDEX_CANONICAL_JOURNAL,
        }
    )


def _report_index_canonical_recovery_names(
    contract: PhaseIOContract,
) -> tuple[str, ...]:
    """Return every live output whose old bytes bound staged publication."""

    return tuple(item.path for item in contract.outputs)


def _report_index_prestate_bundle_state(
    prestates: Mapping[str, Any],
    names: Sequence[str],
) -> dict[str, dict[str, Any]]:
    state: dict[str, dict[str, Any]] = {}
    for name in names:
        record = prestates.get(f"scratchpad:{name}")
        if not isinstance(record, Mapping):
            raise ValueError(
                f"report-index canonical prestate missing for {name}"
            )
        status = str(record.get("status") or "")
        if status == "ABSENT":
            state[name] = {"status": "ABSENT", "sha256": "", "size": 0}
        else:
            state[name] = {
                "status": "ACTIVE",
                "sha256": str(record.get("sha256") or ""),
                "size": int(record.get("size") or 0),
            }
    return state


def _report_index_canonical_recovery_dir(
    scratchpad: Path,
    contract: PhaseIOContract,
) -> Path:
    """Return an attempt-scoped, non-semantic recovery workspace."""

    key_digest = hashlib.sha256(
        contract.key.encode("utf-8")
    ).hexdigest()[:24]
    return (
        Path(scratchpad)
        # This is non-semantic recovery state.  Compact path components keep
        # deeply nested verifier receipts below legacy Windows path limits;
        # the full contract key/digest remains bound inside the source/journal
        # manifests rather than being weakened to this directory name.
        / ".pio"
        / "ri"
        / key_digest
    )


def _report_index_canonical_source_manifest(
    *,
    contract: PhaseIOContract,
    run_id: str,
    prestates: Mapping[str, Any],
    names: Sequence[str],
) -> dict[str, Any]:
    sources: dict[str, dict[str, Any]] = {}
    for name in names:
        record = prestates.get(f"scratchpad:{name}")
        if not isinstance(record, Mapping):
            raise ValueError(
                f"report-index canonical prestate missing for {name}"
            )
        status = str(record.get("status") or "")
        sources[name] = {
            "status": status,
            "sha256": (
                ""
                if status == "ABSENT"
                else str(record.get("sha256") or "")
            ),
            "size": (
                0 if status == "ABSENT" else int(record.get("size") or 0)
            ),
        }
    payload: dict[str, Any] = {
        "schema_version": (
            "plamen.report_index_canonical_source_snapshot.v1"
        ),
        "run_id": str(run_id),
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "sources": sources,
    }
    payload["manifest_digest"] = _stable_payload_digest(payload)
    return payload


def _prepare_report_index_canonical_source_snapshots(
    scratchpad: Path,
    *,
    contract: PhaseIOContract,
    run_id: str,
    prestates: Mapping[str, Any],
) -> list[str]:
    """Persist exact pre-arm bytes before any canonical output is replaced.

    These files are recovery auxiliaries, not semantic authority.  Every byte
    used from them is independently matched to the already-bound artifact
    ledger prestate, so a re-authored manifest cannot bless different bytes.
    """

    root = Path(scratchpad)
    names = _report_index_canonical_recovery_names(contract)
    recovery = _report_index_canonical_recovery_dir(root, contract)
    sources_root = recovery / "sources"
    issues: list[str] = []
    try:
        sources_root.mkdir(parents=True, exist_ok=True)
        manifest = _report_index_canonical_source_manifest(
            contract=contract,
            run_id=run_id,
            prestates=prestates,
            names=names,
        )
        for name in names:
            record = manifest["sources"][name]
            snapshot = sources_root / Path(name)
            if record["status"] == "ABSENT":
                if snapshot.exists() or snapshot.is_symlink():
                    issues.append(
                        "report-index canonical absent prestate has a "
                        f"recovery snapshot: {name}"
                    )
                continue
            expected_sha = str(record.get("sha256") or "")
            expected_size = int(record.get("size") or 0)
            if not re.fullmatch(r"[0-9a-f]{64}", expected_sha):
                issues.append(
                    f"report-index canonical prestate digest invalid: {name}"
                )
                continue
            if snapshot.is_symlink():
                issues.append(
                    f"report-index canonical recovery snapshot is a symlink: {name}"
                )
                continue
            if snapshot.is_file():
                raw = snapshot.read_bytes()
            else:
                live = root / Path(name)
                if not live.is_file() or live.is_symlink():
                    issues.append(
                        "report-index canonical source is unavailable before "
                        f"first mutation: {name}"
                    )
                    continue
                raw = live.read_bytes()
                if (
                    len(raw) != expected_size
                    or hashlib.sha256(raw).hexdigest() != expected_sha
                ):
                    issues.append(
                        "report-index canonical live source differs from "
                        f"the bound prestate: {name}"
                    )
                    continue
                snapshot.parent.mkdir(parents=True, exist_ok=True)
                _atomic_driver_bytes(snapshot, raw)
            if (
                len(raw) != expected_size
                or hashlib.sha256(raw).hexdigest() != expected_sha
            ):
                issues.append(
                    "report-index canonical recovery snapshot differs from "
                    f"the bound prestate: {name}"
                )
        if issues:
            return list(dict.fromkeys(issues))
        _atomic_driver_bytes(
            recovery / "source_manifest.json",
            _canonical_json_bytes(manifest),
        )
    except (OSError, TypeError, ValueError) as exc:
        issues.append(
            "report-index canonical source snapshot failed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(issues))


def _restore_report_index_canonical_bound_prestate(
    scratchpad: Path,
    *,
    contract: PhaseIOContract,
    run_id: str,
    prestates: Mapping[str, Any],
) -> list[str]:
    """Restore only ledger-bound source bytes before deterministic replay."""

    root = Path(scratchpad)
    names = _report_index_canonical_recovery_names(contract)
    recovery = _report_index_canonical_recovery_dir(root, contract)
    expected_manifest = _report_index_canonical_source_manifest(
        contract=contract,
        run_id=run_id,
        prestates=prestates,
        names=names,
    )
    issues: list[str] = []
    try:
        manifest_path = recovery / "source_manifest.json"
        raw_manifest = manifest_path.read_bytes()
        observed_manifest = json.loads(
            raw_manifest.decode("utf-8", errors="strict")
        )
        if (
            raw_manifest != _canonical_json_bytes(observed_manifest)
            or observed_manifest != expected_manifest
        ):
            return [
                "report-index canonical source manifest differs from the "
                "ledger-bound prestate"
            ]
        for name in names:
            record = expected_manifest["sources"][name]
            live = root / Path(name)
            snapshot = recovery / "sources" / Path(name)
            if record["status"] == "ABSENT":
                if live.is_dir() and not live.is_symlink():
                    issues.append(
                        "report-index canonical absent output is a directory: "
                        f"{name}"
                    )
                elif live.exists() or live.is_symlink():
                    live.unlink()
                continue
            if not snapshot.is_file() or snapshot.is_symlink():
                issues.append(
                    "report-index canonical recovery snapshot unavailable: "
                    f"{name}"
                )
                continue
            raw = snapshot.read_bytes()
            if (
                len(raw) != int(record.get("size") or 0)
                or hashlib.sha256(raw).hexdigest()
                != str(record.get("sha256") or "")
            ):
                issues.append(
                    "report-index canonical recovery snapshot failed its "
                    f"ledger-bound byte check: {name}"
                )
                continue
            _atomic_driver_bytes(live, raw)
    except (
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        issues.append(
            "report-index canonical prestate restore failed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(issues))


def _cleanup_report_index_canonical_recovery(
    scratchpad: Path,
    contract: PhaseIOContract,
) -> None:
    """Best-effort cleanup after the semantic commit is independently valid."""

    recovery = _report_index_canonical_recovery_dir(scratchpad, contract)
    try:
        shutil.rmtree(recovery)
        parent = recovery.parent
        if parent.is_dir() and not any(parent.iterdir()):
            parent.rmdir()
        grandparent = parent.parent
        if grandparent.is_dir() and not any(grandparent.iterdir()):
            grandparent.rmdir()
    except OSError:
        pass


def _stage_report_index_canonical_preimage(
    scratchpad: Path,
    project_root: Path,
    *,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    prestates: Mapping[str, Any],
) -> tuple[Path | None, list[str]]:
    """Build a fresh off-live derivation root from authenticated inputs."""

    root = Path(scratchpad)
    project = Path(project_root)
    input_issues = validate_work_unit_inputs(
        root,
        project,
        contract,
        launch,
        run_id=run_id,
    )
    if input_issues:
        return None, [
            "report-index canonical staged input validation failed: "
            f"{issue}"
            for issue in input_issues
        ]
    try:
        ledger = read_artifact_ledger(root)
        unit = ledger.get("work_units", {}).get(contract.key)
        input_bindings = (
            unit.get("input_bindings")
            if isinstance(unit, Mapping)
            else None
        )
    except ArtifactLedgerError as exc:
        return None, [
            "report-index canonical staged input ledger failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    if not isinstance(input_bindings, Mapping):
        return None, [
            "report-index canonical staged input bindings are absent"
        ]
    snapshot_issues = _prepare_report_index_canonical_source_snapshots(
        root,
        contract=contract,
        run_id=run_id,
        prestates=prestates,
    )
    if snapshot_issues:
        return None, snapshot_issues

    recovery = _report_index_canonical_recovery_dir(root, contract)
    stage = recovery / "staged_target"
    try:
        if stage.exists():
            if stage.is_symlink() or not stage.is_dir():
                return None, [
                    "report-index canonical staged target has an unsafe type"
                ]
            shutil.rmtree(stage)
        stage.mkdir(parents=True, exist_ok=False)

        # The canonical input arm has already replayed the live artifact
        # ledger and recorded this transaction's exact input bindings.  Copy
        # those validated bytes into the isolated root so dynamic verifier
        # completion can replay upstream MODEL/DRIVER ownership without
        # binding the mutable live ledger as a self-referential input.
        ledger_path = root / "_artifact_state.json"
        if not ledger_path.is_file() or ledger_path.is_symlink():
            return None, [
                "report-index canonical staged producer ledger is unavailable"
            ]
        ledger_raw = ledger_path.read_bytes()
        # Re-read through the strict parser immediately before projection;
        # malformed or concurrently replaced ledger bytes fail closed.
        read_artifact_ledger(root)
        if ledger_path.read_bytes() != ledger_raw:
            return None, [
                "report-index canonical staged producer ledger changed "
                "during projection"
            ]
        _atomic_driver_bytes(stage / "_artifact_state.json", ledger_raw)

        expected_manifest = _report_index_canonical_source_manifest(
            contract=contract,
            run_id=run_id,
            prestates=prestates,
            names=_report_index_canonical_recovery_names(contract),
        )
        semantic_sources = set(
            _report_index_canonical_state_names(contract)
        )
        for name in sorted(semantic_sources):
            record = expected_manifest["sources"][name]
            if record["status"] == "ABSENT":
                continue
            source = recovery / "sources" / Path(name)
            raw = source.read_bytes()
            if (
                len(raw) != int(record.get("size") or 0)
                or hashlib.sha256(raw).hexdigest()
                != str(record.get("sha256") or "")
            ):
                return None, [
                    "report-index canonical staged source failed its "
                    f"ledger-bound byte check: {name}"
                ]
            target = stage / Path(name)
            target.parent.mkdir(parents=True, exist_ok=True)
            _atomic_driver_bytes(target, raw)

        exact_inputs = tuple(dict.fromkeys((
            *contract.immutable_inputs,
            *contract.bounded_lookup_inputs,
        )))
        for identity in exact_inputs:
            scope, separator, relative = str(identity).partition(":")
            if not separator or not relative:
                return None, [
                    "report-index canonical staged input identity is "
                    f"malformed: {identity}"
                ]
            if scope != "scratchpad":
                # Canonical report transforms receive only a scratchpad root.
                # Project-scoped inputs remain protected by the PhaseIO input
                # receipt but are not read by these deterministic transforms.
                continue
            relative_path = Path(relative)
            if relative_path.is_absolute() or ".." in relative_path.parts:
                return None, [
                    "report-index canonical staged input path is unsafe: "
                    f"{identity}"
                ]
            source = root / relative_path
            if not source.is_file() or source.is_symlink():
                return None, [
                    "report-index canonical staged input is unavailable: "
                    f"{identity}"
                ]
            raw = source.read_bytes()
            binding = input_bindings.get(identity)
            if (
                not isinstance(binding, Mapping)
                or binding.get("status") != "ACTIVE"
                or binding.get("sha256")
                != hashlib.sha256(raw).hexdigest()
                or binding.get("size") != len(raw)
            ):
                return None, [
                    "report-index canonical staged input differs from its "
                    f"armed binding: {identity}"
                ]
            target = stage / relative_path
            if target.is_file():
                if target.read_bytes() != raw:
                    return None, [
                        "report-index canonical input/output preimage "
                        f"collision differs: {identity}"
                    ]
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            _atomic_driver_bytes(target, raw)
    except (OSError, TypeError, ValueError) as exc:
        return None, [
            "report-index canonical staged preimage failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    return stage, []


def _report_index_canonical_old_or_target_issues(
    scratchpad: Path,
    *,
    contract: PhaseIOContract,
    run_id: str,
    prestates: Mapping[str, Any],
    expected_target: Mapping[str, bytes],
) -> list[str]:
    """Reject any live byte that is neither its bound old nor derived target."""

    root = Path(scratchpad)
    recovery = _report_index_canonical_recovery_dir(root, contract)
    expected_manifest = _report_index_canonical_source_manifest(
        contract=contract,
        run_id=run_id,
        prestates=prestates,
        names=_report_index_canonical_recovery_names(contract),
    )
    issues: list[str] = []
    for name in _report_index_canonical_recovery_names(contract):
        live = root / Path(name)
        target_raw = expected_target.get(name)
        if not isinstance(target_raw, bytes):
            issues.append(
                f"report-index canonical sealed target is absent: {name}"
            )
            continue
        if live.is_file() and not live.is_symlink():
            live_raw: bytes | None = live.read_bytes()
            if live_raw == target_raw:
                continue
        elif live.exists() or live.is_symlink():
            issues.append(
                "REPORT_INDEX_CANONICAL_ARBITRARY_THIRD_STATE: live output "
                f"has an unsafe type: {name}"
            )
            continue
        else:
            live_raw = None

        record = expected_manifest["sources"][name]
        if record["status"] == "ABSENT":
            old_matches = live_raw is None
        else:
            snapshot = recovery / "sources" / Path(name)
            old_matches = bool(
                live_raw is not None
                and snapshot.is_file()
                and not snapshot.is_symlink()
                and live_raw == snapshot.read_bytes()
            )
        if not old_matches:
            issues.append(
                "REPORT_INDEX_CANONICAL_ARBITRARY_THIRD_STATE: live output "
                f"is neither its bound predecessor nor derived target: {name}"
            )
    return list(dict.fromkeys(issues))


def _publish_report_index_canonical_target(
    scratchpad: Path,
    *,
    contract: PhaseIOContract,
    expected_target: Mapping[str, bytes],
    fault: Callable[[str], None],
) -> list[str]:
    """Publish each validated target once, with the receipt strictly last."""

    root = Path(scratchpad)
    receipt_name = _report_index_canonical_receipt_name(contract)
    names = [
        item.path for item in contract.outputs
        if item.path != receipt_name
    ]
    names.append(receipt_name)
    try:
        for name in names:
            raw = expected_target.get(name)
            if not isinstance(raw, bytes):
                raise ValueError(
                    f"sealed canonical target is absent: {name}"
                )
            fault(f"before_publish:{name}")
            live = root / Path(name)
            if not live.is_file() or live.is_symlink() or live.read_bytes() != raw:
                _atomic_driver_bytes(live, raw)
            fault(f"after_publish:{name}")
    except (OSError, TypeError, ValueError) as exc:
        return [
            "report-index canonical target publication failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    return []


def _derive_report_index_canonical_staged_target(
    staged_target: Path,
    *,
    contract: PhaseIOContract,
    run_id: str,
    expected_severities: Mapping[str, str],
    predecessor_records: Mapping[str, Any],
    fault: Callable[[str], None],
) -> tuple[dict[str, bytes] | None, list[str]]:
    """Derive and validate the complete canonical bundle off live paths."""

    stage = Path(staged_target)
    transformations = [
        "EXACT_EMPTY_ZERO_ROW_ENVELOPE",
        "RESET_OPTIONAL_GENERATION_PROJECTIONS",
        "DROPOUT_BODY_RECOVERY",
        "DROPOUT_HUMAN_REVIEW_RETENTION",
        "STATUS_AUTHORITY_PROJECTION",
        "SEVERITY_PROVENANCE_REPAIR",
        "SUMMARY_MASTER_PARITY",
        "EMPTY_OPTIONAL_ENVELOPES",
    ]
    try:
        transformation_issues: list[str] = []
        severity_repairs: list[Mapping[str, Any]] = []
        immutable_records, immutable_issues = (
            _report_index_canonical_stage_immutable_records(
                stage, contract=contract
            )
        )
        _initial_state, initial_state_issues = (
            _report_index_canonical_stage_file_bytes(
                stage, contract=contract
            )
        )
        if immutable_issues or initial_state_issues:
            return None, list(dict.fromkeys(
                [*immutable_issues, *initial_state_issues]
            ))

        def guarded_fault(point: str) -> list[str]:
            expected_state, snapshot_issues = (
                _report_index_canonical_stage_file_bytes(
                    stage, contract=contract
                )
            )
            if snapshot_issues:
                return snapshot_issues
            fault(point)
            return _report_index_canonical_stage_integrity_issues(
                stage,
                contract=contract,
                immutable_records=immutable_records,
                expected_state=expected_state,
            )

        _write_report_index_canonical_journal_stage(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            stage="ARMED",
        )
        guard_issues = guarded_fault("after_canonical_arm")
        if guard_issues:
            return None, guard_issues

        _empty_projected, denominator_issues = (
            _ensure_report_index_canonical_zero_row_envelope(
                stage, pipeline=contract.pipeline
            )
        )
        if denominator_issues:
            return None, denominator_issues
        _write_report_index_canonical_journal_stage(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            stage="DENOMINATOR_VALIDATED",
        )
        guard_issues = guarded_fault("after_denominator_projection")
        if guard_issues:
            return None, guard_issues

        _ensure_empty_report_index_canonical_outputs(
            stage, reset_optional=True
        )
        _write_report_index_canonical_journal_stage(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            stage="OPTIONALS_RESET",
        )
        guard_issues = guarded_fault("after_optional_reset")
        if guard_issues:
            return None, guard_issues

        _repair_report_index_dropouts(stage)
        residual = _report_index_dropped_ids(stage, run_id=run_id)
        verify_norm = {
            re.sub(r"-0+(\d)", r"-\1", value)
            for value in _collect_verify_hypothesis_ids(stage)
        }
        residual_verify = [
            value for value in residual
            if re.sub(r"-0+(\d)", r"-\1", value) in verify_norm
        ]
        if residual and not residual_verify:
            _backfill_report_coverage_dropouts(stage)
        residual_after_repair = _report_index_dropped_ids(
            stage, run_id=run_id
        )
        if residual_after_repair:
            transformation_issues.append(
                "report-index dropout repair left unaccounted identities: "
                + ", ".join(residual_after_repair[:8])
            )
        _write_report_index_canonical_journal_stage(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            stage="DROPOUT_PROJECTED",
        )
        guard_issues = guarded_fault("after_dropout_projection")
        if guard_issues:
            return None, guard_issues

        transformation_issues.extend(
            _project_report_index_status_with_debt(stage)
        )
        _write_report_index_canonical_journal_stage(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            stage="STATUS_PROJECTED",
        )
        guard_issues = guarded_fault("after_status_projection")
        if guard_issues:
            return None, guard_issues

        severity_repairs = list(
            _repair_report_index_severity_provenance(
                stage,
                expected_run_id=run_id,
                expected_mode=contract.mode,
                expected_severities=expected_severities,
            )
        )
        if severity_repairs:
            transformation_issues.extend(
                _project_report_index_status_with_debt(stage)
            )
        _write_report_index_canonical_journal_stage(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            stage="SEVERITY_PROJECTED",
        )
        guard_issues = guarded_fault("after_severity_projection")
        if guard_issues:
            return None, guard_issues

        derivation = derive_report_index_summary_master_parity(
            (stage / "report_index.md").read_bytes()
        )
        if derivation.issues:
            return None, list(derivation.issues)
        if derivation.repair_required:
            _atomic_driver_bytes(
                stage / "report_index.md", derivation.output_bytes
            )
        transformation_issues.extend(
            _project_report_index_status_with_debt(stage)
        )
        _ensure_empty_report_index_canonical_outputs(stage)
        semantic_issues = validate_report_index_canonical_bundle(
            stage,
            pipeline=contract.pipeline,
            run_id=run_id,
            transformation_issues=transformation_issues,
            severity_repairs=severity_repairs,
            expected_severities=expected_severities,
        )
        if semantic_issues:
            return None, semantic_issues
        _write_report_index_canonical_journal_stage(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            stage="FINAL_BUNDLE",
        )
        receipt_name = _report_index_canonical_receipt_name(contract)
        nonreceipt_names = [
            item.path for item in contract.outputs
            if item.path != receipt_name
        ]
        sealed_nonreceipt = {
            name: (stage / Path(name)).read_bytes()
            for name in nonreceipt_names
        }
        guard_issues = guarded_fault("after_summary_projection")
        if guard_issues:
            return None, guard_issues

        if any(
            not (stage / Path(name)).is_file()
            or (stage / Path(name)).is_symlink()
            or (stage / Path(name)).read_bytes() != raw
            for name, raw in sealed_nonreceipt.items()
        ):
            return None, [
                "REPORT_INDEX_CANONICAL_SEALED_TARGET_DRIFT: staged "
                "canonical bytes changed after deterministic derivation"
            ]
        output_records = _report_index_bundle_records_from_bytes(
            sealed_nonreceipt
        )
        receipt = _report_index_canonical_receipt_payload(
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            output_records=output_records,
            transformations=transformations,
        )
        receipt_raw = _canonical_json_bytes(receipt)
        _atomic_driver_bytes(
            stage / receipt_name,
            receipt_raw,
        )
        expected_target = {
            **sealed_nonreceipt,
            receipt_name: receipt_raw,
        }
        receipt_issues = _validate_report_index_canonical_receipt(
            stage,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            expected_severities=expected_severities,
            expected_target=expected_target,
        )
        return (
            None if receipt_issues else expected_target,
            receipt_issues,
        )
    except (
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return None, [
            "report-index canonical staged derivation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _report_index_canonical_journal_digest(
    payload: Mapping[str, Any],
) -> str:
    unsigned = {
        key: value for key, value in payload.items()
        if key != "journal_digest"
    }
    return _stable_payload_digest(unsigned)


def _read_report_index_canonical_journal(
    path: Path,
) -> tuple[dict[str, Any], bytes]:
    raw = Path(path).read_bytes()
    payload = json.loads(raw.decode("utf-8", errors="strict"))
    if not isinstance(payload, dict):
        raise ValueError("report-index canonical journal is not an object")
    if raw != _canonical_json_bytes(payload):
        raise ValueError(
            "report-index canonical journal bytes are non-canonical"
        )
    if payload.get("journal_digest") != (
        _report_index_canonical_journal_digest(payload)
    ):
        raise ValueError("report-index canonical journal digest is invalid")
    ledger_projection = payload.get("producer_ledger_projection")
    if not isinstance(ledger_projection, Mapping):
        raise ValueError(
            "report-index canonical journal producer-ledger projection is absent"
        )
    if set(ledger_projection) != {"status", "sha256", "size"}:
        raise ValueError(
            "report-index canonical journal producer-ledger projection is malformed"
        )
    if ledger_projection.get("status") == "ACTIVE":
        if (
            not re.fullmatch(
                r"[0-9a-f]{64}", str(ledger_projection.get("sha256") or "")
            )
            or type(ledger_projection.get("size")) is not int
            or int(ledger_projection["size"]) <= 0
        ):
            raise ValueError(
                "report-index canonical journal producer-ledger binding is invalid"
            )
    elif ledger_projection != {"status": "ABSENT", "sha256": "", "size": 0}:
        raise ValueError(
            "report-index canonical journal producer-ledger absence is malformed"
        )
    return payload, raw


def _write_report_index_canonical_journal_stage(
    scratchpad: Path,
    *,
    contract: PhaseIOContract,
    run_id: str,
    predecessor_records: Mapping[str, Any],
    stage: str,
) -> dict[str, Any]:
    root = Path(scratchpad)
    path = root / _REPORT_INDEX_CANONICAL_JOURNAL
    state = _report_index_bundle_state(
        root, _report_index_canonical_state_names(contract)
    )
    ledger_path = root / "_artifact_state.json"
    if ledger_path.is_file() and not ledger_path.is_symlink():
        ledger_projection_raw = _canonical_json_bytes(
            _report_verifier_phaseio_authority_projection(root)
        )
        ledger_projection = {
            "status": "ACTIVE",
            "sha256": hashlib.sha256(ledger_projection_raw).hexdigest(),
            "size": len(ledger_projection_raw),
        }
    else:
        ledger_projection = {
            "status": "ABSENT",
            "sha256": "",
            "size": 0,
        }
    payload: dict[str, Any]
    try:
        current, _raw = _read_report_index_canonical_journal(path)
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        current = {}
    if (
        current.get("schema_version")
        == _REPORT_INDEX_CANONICAL_JOURNAL_SCHEMA
        and current.get("run_id") == run_id
        and current.get("work_unit_key") == contract.key
        and current.get("contract_digest") == contract.digest
        and current.get("predecessors") == dict(predecessor_records)
        and current.get("producer_ledger_projection") == ledger_projection
        and isinstance(current.get("states"), list)
    ):
        payload = dict(current)
    else:
        payload = {
            "schema_version": _REPORT_INDEX_CANONICAL_JOURNAL_SCHEMA,
            "run_id": run_id,
            "work_unit_key": contract.key,
            "contract_digest": contract.digest,
            "predecessors": dict(predecessor_records),
            "producer_ledger_projection": ledger_projection,
            "states": [],
        }
    entry = {"stage": str(stage), "artifacts": state}
    states = list(payload.get("states") or [])
    stage_order = {
        "ARMED": 0,
        "DENOMINATOR_VALIDATED": 1,
        "OPTIONALS_RESET": 2,
        "DROPOUT_PROJECTED": 3,
        "STATUS_PROJECTED": 4,
        "SEVERITY_PROJECTED": 5,
        "FINAL_BUNDLE": 6,
    }
    requested_order = stage_order.get(str(stage), -1)
    matching_orders = [
        stage_order.get(str(existing.get("stage") or ""), -1)
        for existing in states
        if isinstance(existing, Mapping)
        and existing.get("artifacts") == state
    ]
    if matching_orders and max(matching_orders) >= requested_order:
        return payload
    if not states or states[-1] != entry:
        states.append(entry)
    payload["states"] = states
    payload["journal_digest"] = _report_index_canonical_journal_digest(
        payload
    )
    _atomic_driver_bytes(path, _canonical_json_bytes(payload))
    return payload


def _validate_report_index_canonical_resume_state(
    scratchpad: Path,
    *,
    contract: PhaseIOContract,
    run_id: str,
    predecessor_records: Mapping[str, Any],
) -> list[str]:
    root = Path(scratchpad)
    path = root / _REPORT_INDEX_CANONICAL_JOURNAL
    try:
        payload, _raw = _read_report_index_canonical_journal(path)
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
        return [
            "REPORT_INDEX_CANONICAL_ARBITRARY_THIRD_STATE: journal missing "
            f"or invalid after arm ({type(exc).__name__}: {exc})"
        ]
    expected_header = {
        "schema_version": _REPORT_INDEX_CANONICAL_JOURNAL_SCHEMA,
        "run_id": run_id,
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "predecessors": dict(predecessor_records),
    }
    issues = [
        f"report-index canonical journal {field} mismatch"
        for field, expected in expected_header.items()
        if payload.get(field) != expected
    ]
    states = payload.get("states")
    ledger_projection = payload.get("producer_ledger_projection")
    if not isinstance(ledger_projection, Mapping):
        issues.append(
            "report-index canonical journal producer-ledger projection missing"
        )
    if not isinstance(states, list) or not states:
        issues.append("report-index canonical journal state set is empty")
        return issues
    current = _report_index_bundle_state(
        root, _report_index_canonical_state_names(contract)
    )
    if not any(
        isinstance(entry, Mapping)
        and entry.get("artifacts") == current
        for entry in states
    ):
        issues.append(
            "REPORT_INDEX_CANONICAL_ARBITRARY_THIRD_STATE: current bundle "
            "matches no journaled deterministic prefix"
        )
    return list(dict.fromkeys(issues))


def _report_index_canonical_receipt_payload(
    *,
    contract: PhaseIOContract,
    run_id: str,
    predecessor_records: Mapping[str, Any],
    output_records: Mapping[str, Any],
    transformations: Sequence[str],
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "schema_version": _REPORT_INDEX_CANONICAL_SCHEMA,
        "run_id": run_id,
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "predecessors": dict(predecessor_records),
        "transformations": list(transformations),
        "outputs": dict(output_records),
    }
    payload["receipt_digest"] = _stable_payload_digest(payload)
    return payload


def _validate_report_index_canonical_receipt(
    scratchpad: Path,
    *,
    contract: PhaseIOContract,
    run_id: str,
    predecessor_records: Mapping[str, Any],
    expected_severities: Mapping[str, str],
    expected_target: Mapping[str, bytes] | None = None,
) -> list[str]:
    receipt_name = _report_index_canonical_receipt_name(contract)
    path = Path(scratchpad) / receipt_name
    try:
        raw = path.read_bytes()
        payload = json.loads(raw.decode("utf-8", errors="strict"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return [
            "report-index canonical receipt is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ]
    if not isinstance(payload, Mapping):
        return ["report-index canonical receipt is not an object"]
    unsigned = dict(payload)
    claimed_digest = unsigned.pop("receipt_digest", None)
    issues: list[str] = []
    if expected_target is not None:
        expected_names = {item.path for item in contract.outputs}
        if set(expected_target) != expected_names:
            issues.append(
                "report-index canonical sealed target denominator mismatch"
            )
        expected_receipt_raw = expected_target.get(receipt_name)
        if (
            not isinstance(expected_receipt_raw, bytes)
            or raw != expected_receipt_raw
        ):
            issues.append(
                "report-index canonical live receipt differs from the "
                "independently sealed target"
            )
    if raw != _canonical_json_bytes(payload):
        issues.append("report-index canonical receipt bytes are non-canonical")
    if claimed_digest != _stable_payload_digest(unsigned):
        issues.append("report-index canonical receipt digest is invalid")
    expected_header = {
        "schema_version": _REPORT_INDEX_CANONICAL_SCHEMA,
        "run_id": run_id,
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
    }
    for field, expected in expected_header.items():
        if payload.get(field) != expected:
            issues.append(
                f"report-index canonical receipt {field} mismatch"
            )
    if payload.get("predecessors") != dict(predecessor_records):
        issues.append(
            "report-index canonical receipt predecessor set mismatch"
        )
    output_names = [
        item.path for item in contract.outputs
        if item.path != receipt_name
    ]
    if expected_target is not None:
        expected_output_records = (
            _report_index_bundle_records_from_bytes({
                name: expected_target[name]
                for name in output_names
                if isinstance(expected_target.get(name), bytes)
            })
        )
        if (
            len(expected_output_records) != len(output_names)
            or payload.get("outputs") != expected_output_records
        ):
            issues.append(
                "report-index canonical receipt does not bind the sealed "
                "target outputs"
            )
    try:
        observed = _report_index_bundle_records(
            Path(scratchpad), output_names
        )
    except OSError as exc:
        issues.append(f"report-index canonical output unreadable: {exc}")
    else:
        if payload.get("outputs") != observed:
            issues.append(
                "report-index canonical receipt output bundle mismatch"
            )
        if (
            expected_target is not None
            and any(
                (Path(scratchpad) / Path(name)).read_bytes()
                != expected_target.get(name)
                for name in output_names
                if isinstance(expected_target.get(name), bytes)
            )
        ):
            issues.append(
                "report-index canonical live output differs from the "
                "independently sealed target"
            )
    issues.extend(
        validate_report_index_canonical_bundle(
            Path(scratchpad),
            pipeline=contract.pipeline,
            run_id=run_id,
            expected_severities=expected_severities,
        )
    )
    return list(dict.fromkeys(issues))


def _run_report_index_canonicalization_transaction(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
    *,
    fault_inject: Callable[[str], None] | None = None,
) -> list[str]:
    """Publish the complete report-index semantic projection once."""

    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["report-index canonicalization run_id is absent"]
    try:
        contract, launch = _report_index_canonical_contract_and_launch(
            root, config
        )
        ledger = read_artifact_ledger(root)
        existing = ledger.get("work_units", {}).get(contract.key)
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "report-index canonicalization contract resolution failed: "
            f"{type(exc).__name__}: {exc}"
        ]

    def fault(point: str) -> None:
        if fault_inject is not None:
            fault_inject(point)

    if (
        isinstance(existing, Mapping)
        and existing.get("semantic_status") == "ACTIVE"
        and existing.get("execution_state") == "OUTPUT_COMMITTED"
    ):
        expected_severities = _expected_report_index_severities(
            root,
            expected_run_id=run_id,
            expected_mode=str(config.get("mode") or ""),
        )
        prestates = existing.get("output_prestates")
        predecessor_records = {
            identity: dict(record)
            for identity, record in dict(prestates or {}).items()
            if isinstance(record, Mapping)
        }
        issues = validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        issues.extend(_validate_report_index_canonical_receipt(
            root,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            expected_severities=expected_severities,
        ))
        if not issues:
            _cleanup_report_index_canonical_recovery(root, contract)
        return list(dict.fromkeys(issues))

    if (
        isinstance(existing, Mapping)
        and existing.get("semantic_status") == "QUARANTINED"
        and existing.get("execution_state") == "OUTPUT_QUARANTINED"
    ):
        quarantine_prestates = {
            identity: dict(record)
            for identity, record in dict(
                existing.get("output_prestates") or {}
            ).items()
            if isinstance(record, Mapping)
        }
        restore_issues = _restore_report_index_canonical_bound_prestate(
            root,
            contract=contract,
            run_id=run_id,
            prestates=quarantine_prestates,
        )
        if restore_issues:
            return [
                "report-index canonical quarantined prestate recovery "
                f"failed: {issue}"
                for issue in restore_issues
            ]
        try:
            recovered = (
                recover_quarantined_deterministic_work_unit_prestate(
                    root,
                    project_root,
                    contract,
                    launch,
                    run_id=run_id,
                )
            )
            if not recovered:
                return [
                    "report-index canonical quarantined work unit was not "
                    "eligible for exact predecessor recovery"
                ]
            ledger = read_artifact_ledger(root)
            existing = ledger.get("work_units", {}).get(contract.key)
        except ArtifactLedgerError as exc:
            return [
                "report-index canonical quarantined ledger recovery failed: "
                f"{exc}"
            ]

    armed_recovery = bool(
        isinstance(existing, Mapping)
        and existing.get("semantic_status") == "INPUTS_BOUND"
        and existing.get("execution_state") == "INPUTS_BOUND_PREEXECUTION"
        and existing.get("artifacts") == {}
    )
    if not armed_recovery:
        try:
            ledger = read_artifact_ledger(root)
            binding = ledger.get("artifact_bindings", {}).get(
                "scratchpad:report_index.md"
            )
        except ArtifactLedgerError:
            binding = None
        if not isinstance(binding, Mapping):
            if str(config.get("pipeline") or "sc").lower() != "sc":
                return [
                    "L1 report-index canonicalization has no committed "
                    "mechanical predecessor"
                ]
            _model_contract, model_issues = (
                _record_report_index_model_preimage(phase, root, config)
            )
            if model_issues:
                return list(dict.fromkeys(model_issues))

        strict_roots = [
            "scratchpad:report_index.md",
            "scratchpad:report_coverage.md",
        ]
        if str(config.get("pipeline") or "sc").lower() == "l1":
            strict_roots.append("scratchpad:report_records.json")
        authority_issues = semantic_input_prebind_producer_authority_issues(
            root,
            project_root,
            strict_roots,
            run_id=run_id,
        )
        verifier_inputs = sorted(
            identity
            for identity in contract.immutable_inputs
            if identity.startswith("scratchpad:verify_")
            and identity.endswith(".md")
        )
        if verifier_inputs:
            authority_issues.extend(
                semantic_input_prebind_producer_authority_issues(
                    root,
                    project_root,
                    verifier_inputs,
                    run_id=run_id,
                )
            )
        if authority_issues:
            return [
                "report-index canonical predecessor authority failed: "
                f"{issue}"
                for issue in authority_issues
            ]

    fault("before_canonical_arm")
    execute, issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    if issues:
        return list(dict.fromkeys(issues))
    if not execute:
        return [
            "report-index canonicalization is neither executable nor a "
            "valid committed replay"
        ]

    # R10 producer authority is meaningful only on the live scratchpad: an
    # off-live canonical stage necessarily has different physical file
    # identities.  Derive this immutable severity projection after the exact
    # canonical input arm and pass it explicitly to every staged consumer.
    # The staging transaction immediately revalidates all bound input bytes,
    # so any source mutation during this derivation fails before publication.
    expected_severities = _expected_report_index_severities(
        root,
        expected_run_id=run_id,
        expected_mode=str(config.get("mode") or ""),
    )

    try:
        ledger = read_artifact_ledger(root)
        unit = ledger.get("work_units", {}).get(contract.key)
        prestates = (
            unit.get("output_prestates")
            if isinstance(unit, Mapping)
            else None
        )
        if not isinstance(prestates, Mapping):
            return ["report-index canonical arm prestates are absent"]
        predecessor_records = {
            identity: dict(record)
            for identity, record in prestates.items()
            if isinstance(record, Mapping)
        }
        for identity in (
            "scratchpad:report_index.md",
            "scratchpad:report_coverage.md",
        ):
            record = predecessor_records.get(identity)
            if not isinstance(record, Mapping) or record.get("status") != (
                "ACTIVE_REGISTERED_PREDECESSOR"
            ):
                return [
                    f"report-index canonical predecessor {identity} is not "
                    "an active registered producer"
                ]

        staged_target, stage_issues = (
            _stage_report_index_canonical_preimage(
                root,
                project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                prestates=prestates,
            )
        )
        if stage_issues or staged_target is None:
            return list(dict.fromkeys(stage_issues or [
                "report-index canonical staged preimage is unavailable"
            ]))
        with authenticated_historical_typed_stage_scope(
            root,
            staged_target,
            run_id=run_id,
        ):
            expected_target, derive_issues = (
                _derive_report_index_canonical_staged_target(
                    staged_target,
                    contract=contract,
                    run_id=run_id,
                    expected_severities=expected_severities,
                    predecessor_records=predecessor_records,
                    fault=fault,
                )
            )
        if derive_issues or expected_target is None:
            return list(dict.fromkeys(derive_issues))

        guard_issues = _report_index_canonical_old_or_target_issues(
            root,
            contract=contract,
            run_id=run_id,
            prestates=prestates,
            expected_target=expected_target,
        )
        if guard_issues:
            return guard_issues
        publish_issues = _publish_report_index_canonical_target(
            root,
            contract=contract,
            expected_target=expected_target,
            fault=fault,
        )
        if publish_issues:
            return publish_issues

        receipt_issues = _validate_report_index_canonical_receipt(
            root,
            contract=contract,
            run_id=run_id,
            predecessor_records=predecessor_records,
            expected_severities=expected_severities,
            expected_target=expected_target,
        )
        if receipt_issues:
            return receipt_issues
        fault("before_canonical_commit")
        commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            expected_output_records={
                f"scratchpad:{name}": record
                for name, record in (
                    _report_index_bundle_records_from_bytes(
                        expected_target
                    )
                ).items()
            },
        )
        if not commit_issues:
            _cleanup_report_index_canonical_recovery(root, contract)
        return commit_issues
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "report-index canonicalization degraded: "
            f"{type(exc).__name__}: {exc}"
        ]


def _plan_report_index_routing_outputs(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[dict[str, dict], tuple[str, ...]]:
    """Derive the exact routing output names without mutating disk."""

    root = Path(scratchpad)
    is_l1 = str(config.get("pipeline") or "sc").lower() == "l1"
    manifests = (
        _build_body_writer_manifests(
            root, persist=False, materialize_evidence=False
        )
        if is_l1
        else _build_sc_body_writer_manifests(
            root, persist=False, materialize_evidence=False
        )
    )
    outputs = {
        f"body_manifests/{name}.json" for name in manifests
    }
    if not is_l1:
        outputs.add("report_records.json")
    if not outputs:
        raise ValueError("report-index routing plan is empty")
    return manifests, tuple(sorted(outputs))


def _report_index_routing_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    exact_outputs: Sequence[str],
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve one exact deterministic report-routing transaction."""

    canonical_contract, _canonical_launch = (
        _report_index_canonical_contract_and_launch(
            Path(scratchpad), config
        )
    )
    # Routing validates the canonical successor receipt and consumes the
    # resulting report projection. Bind the complete canonical output
    # denominator, not merely the two user-facing Markdown files, so replay
    # preserves that dependency and no authority sidecar can change between
    # validation and materialization without invalidating the transaction.
    routing_inputs = [
        *(spec.path for spec in canonical_contract.outputs),
        *_report_candidate_input_paths(
            Path(scratchpad),
            run_id=str(config.get("_run_id") or "") or None,
        ),
    ]
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="report_index",
        work_unit_id="routing",
        exact_inputs=tuple(dict.fromkeys(routing_inputs)),
        exact_outputs=tuple(str(value) for value in exact_outputs),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _run_report_index_routing_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[dict[str, dict], list[str]]:
    """Plan, prebind, materialize, and commit report body routing."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return {}, ["report-index routing PhaseIO run_id is absent"]
    project_root = Path(str(config.get("project_root") or root.parent))
    try:
        canonical_contract, _canonical_launch = (
            _report_index_canonical_contract_and_launch(root, config)
        )
        strict_roots = [
            spec.identity for spec in canonical_contract.outputs
        ]
        authority_issues = semantic_input_prebind_producer_authority_issues(
            root,
            project_root,
            strict_roots,
            run_id=run_id,
        )
        if authority_issues:
            return {}, [
                "report-index routing refused an unauthenticated canonical "
                f"root: {issue}"
                for issue in authority_issues
            ]
        ledger = read_artifact_ledger(root)
        canonical_unit = ledger.get("work_units", {}).get(
            canonical_contract.key
        )
        if not (
            isinstance(canonical_unit, Mapping)
            and canonical_unit.get("semantic_status") == "ACTIVE"
            and canonical_unit.get("execution_state") == "OUTPUT_COMMITTED"
        ):
            return {}, [
                "report-index routing requires the exact active canonical "
                "successor work unit"
            ]
        for identity in strict_roots:
            binding = ledger.get("artifact_bindings", {}).get(identity)
            if (
                not isinstance(binding, Mapping)
                or binding.get("owner_key") != canonical_contract.key
            ):
                return {}, [
                    "report-index routing canonical owner mismatch for "
                    f"{identity}"
                ]
        canonical_prestates = {
            identity: dict(record)
            for identity, record in dict(
                canonical_unit.get("output_prestates") or {}
            ).items()
            if isinstance(record, Mapping)
        }
        expected_severities = _expected_report_index_severities(
            root,
            expected_run_id=run_id,
            expected_mode=str(config.get("mode") or ""),
        )
        receipt_issues = _validate_report_index_canonical_receipt(
            root,
            contract=canonical_contract,
            run_id=run_id,
            predecessor_records=canonical_prestates,
            expected_severities=expected_severities,
        )
        if receipt_issues:
            return {}, [
                "report-index routing canonical receipt invalid: "
                f"{issue}"
                for issue in receipt_issues
            ]
        manifests, exact_outputs = _plan_report_index_routing_outputs(
            root, config
        )
        contract, launch = _report_index_routing_contract_and_launch(
            root, config, exact_outputs=exact_outputs
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return manifests, issues
        if execute:
            if str(config.get("pipeline") or "sc").lower() == "l1":
                built = _build_body_writer_manifests(
                    root, persist=True, materialize_evidence=False
                )
            else:
                built = _build_sc_body_writer_manifests(
                    root, persist=True, materialize_evidence=False
                )
            if set(built) != set(manifests):
                return manifests, [
                    "report-index routing plan changed during materialization"
                ]
            issues = _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
        return manifests, list(dict.fromkeys(issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return {}, [
            "report-index routing transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


# P1-K: one typed report-evidence boundary, one bounded semantic repair, and
# one final delivery receipt. These are driver plumbing transactions; model
# prose never becomes evidence, severity, verdict, or disposition authority.
_REPORT_EVIDENCE_REPAIR_ATTEMPT = "report_evidence_repair_attempt.json"
_REPORT_EVIDENCE_REPAIR_PROMPT = "_prompt_report_evidence_repair.md"
_REPORT_EVIDENCE_REPAIR_RESPONSE = "report_evidence_repair_response.json"
_REPORT_EVIDENCE_REPAIR_PLAN = "report_evidence_repair_apply_plan.json"
_REPORT_EVIDENCE_REPAIR_RECEIPT = "report_evidence_repair_receipt.json"
_REPORT_EVIDENCE_ATTEMPT_SCHEMA = "plamen.report_evidence_repair_attempt.v1"
_REPORT_EVIDENCE_MAX_RESPONSE_BYTES = 8 * 1024 * 1024


def _report_evidence_debt(scratchpad: Path, code: str, detail: object) -> None:
    """Persist stable, reviewable debt without deleting a finding."""

    token = re.sub(r"[^A-Z0-9_]+", "_", str(code or "UNKNOWN").upper()).strip("_")
    message = re.sub(r"\s+", " ", str(detail or "unknown debt")).strip()[:1200]
    path = Path(scratchpad) / "report_evidence_runtime_debt.md"
    header = (
        "# Report Evidence Runtime Debt\n\n"
        "Typed report evidence did not complete cleanly. All report assignments "
        "remain retained, but evidence assurance and report-field quality require "
        "human review.\n\n"
    )
    line = f"- [{token or 'UNKNOWN'}] {message}\n"
    try:
        current = path.read_text(encoding="utf-8") if path.is_file() else header
        if line not in current:
            _atomic_driver_bytes(
                path, (current.rstrip() + "\n" + line).encode("utf-8")
            )
    except OSError:
        pass


def _report_evidence_source_inputs(scratchpad: Path) -> tuple[str, ...]:
    """Enumerate exact existing scratchpad inputs used by the P1-K adapter."""

    root = Path(scratchpad)
    paths: set[str] = {"report_records.json"}
    manifest_dir = root / "body_manifests"
    if manifest_dir.is_dir():
        manifests = sorted(manifest_dir.glob("report_*.json"))
        for manifest_path in manifests:
            try:
                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError):
                continue
            findings = manifest.get("findings")
            canonical_empty = (
                manifest_path.name == "report_empty.json"
                and manifest.get("schema_version")
                == "plamen.empty_report_denominator.v1"
                and manifest.get("shard") == "report_empty"
                and manifest.get("denominator_state") == "EMPTY"
                and findings == []
            )
            if (
                not isinstance(findings, list)
                or (not findings and not canonical_empty)
            ):
                continue
            paths.add(f"body_manifests/{manifest_path.name}")
            for row in findings:
                if not isinstance(row, Mapping):
                    continue
                verify_files = row.get("verify_files") or (
                    [row.get("verify_file")] if row.get("verify_file") else []
                )
                for raw in verify_files:
                    name = str(raw or "").strip().replace("\\", "/")
                    relative = Path(name)
                    if not name or relative.is_absolute() or ".." in relative.parts:
                        continue
                    if (root / name).is_file():
                        paths.add(name)
                    candidate = relative.stem
                    if candidate.lower().startswith("verify_"):
                        cid = candidate[7:]
                        for suffix in (
                            ".execution_scope_assessment.json",
                            ".execution_scope_runtime_source.json",
                            ".execution_scope_evidence.json",
                            ".mechanical_successor.receipt.json",
                        ):
                            candidate_path = f"verify_{cid}{suffix}"
                            if (root / candidate_path).is_file():
                                paths.add(candidate_path)
                runtime_debt = row.get("verification_runtime_debt")
                if (
                    isinstance(runtime_debt, Mapping)
                    and runtime_debt.get("artifact")
                    == _DYNAMIC_VERIFIER_DEBT_NAME
                    and (root / _DYNAMIC_VERIFIER_DEBT_NAME).is_file()
                ):
                    paths.add(_DYNAMIC_VERIFIER_DEBT_NAME)
    # The checkpoint is orchestration state, not a semantic input consumed by
    # the report-evidence adapter.  Binding it here made the shared evidence
    # transaction drift after every body-writer checkpoint update, even when
    # every report source byte was unchanged.
    for name in ("mechanical_verify_manifest.json",):
        if (root / name).is_file():
            paths.add(name)
    execution_dir = root / "mechanical_execution_evidence"
    if execution_dir.is_dir():
        paths.update(
            f"mechanical_execution_evidence/{path.name}"
            for path in execution_dir.glob("*.json")
            if path.is_file()
        )
    return tuple(sorted(paths))


def _validate_report_evidence_upstream_ownership(
    scratchpad: Path,
    config: Mapping[str, Any],
    inputs: Sequence[str],
) -> list[str]:
    """Require live PhaseIO producers before the adapter can mint authority."""

    root = Path(scratchpad)
    try:
        ledger = read_artifact_ledger(root)
    except ArtifactLedgerError as exc:
        return [f"report evidence upstream producer ledger is invalid: {exc}"]
    run_id = str(config.get("_run_id") or "test-unbound")
    required = {
        path
        for path in inputs
        if path == "report_records.json"
        or path.startswith("body_manifests/")
        or re.fullmatch(r"verify_[A-Za-z0-9_.-]+\.md", path)
        or path == _DYNAMIC_VERIFIER_DEBT_NAME
    }
    issues: list[str] = []
    bindings = ledger.get("artifact_bindings")
    work_units = ledger.get("work_units")
    if not isinstance(bindings, Mapping) or not isinstance(work_units, Mapping):
        return ["report evidence upstream producer ledger tables are malformed"]
    for relative in sorted(required):
        identity = f"scratchpad:{relative}"
        binding = bindings.get(identity)
        if not isinstance(binding, Mapping):
            issues.append(f"unowned upstream report evidence input: {relative}")
            continue
        owner = str(binding.get("owner_key") or "")
        parts = owner.split("/")
        expected_report_source = (
            relative == "report_records.json"
            or relative.startswith("body_manifests/")
        )
        producer_shape_ok = False
        if len(parts) == 6:
            owner_phase, owner_work = parts[4], parts[5]
            if expected_report_source:
                producer_shape_ok = (
                    owner_phase == "report_index"
                    and owner_work == "routing"
                    and binding.get("writer") == "DRIVER"
                )
            elif relative == _DYNAMIC_VERIFIER_DEBT_NAME:
                producer_shape_ok = (
                    owner_phase == "verify"
                    and owner_work == "runtime_debt"
                    and binding.get("writer") == "DRIVER"
                )
            else:
                producer_shape_ok = (
                    binding.get("writer") == "MODEL"
                    and (
                        owner_phase == "verify_recovery"
                        or owner_phase == "verify"
                        or owner_phase.startswith("verify_")
                        or owner_phase.startswith("sc_verify_")
                    )
                )
        if not producer_shape_ok:
            issues.append(
                f"unauthorized upstream producer for {relative}: {owner or 'missing'}"
            )
            continue
        unit = work_units.get(owner)
        artifact = (
            unit.get("artifacts", {}).get(identity)
            if isinstance(unit, Mapping)
            and isinstance(unit.get("artifacts"), Mapping)
            else None
        )
        manifest = unit.get("contract_manifest") if isinstance(unit, Mapping) else None
        outputs = manifest.get("outputs") if isinstance(manifest, Mapping) else None
        declared_output = next(
            (
                row
                for row in outputs or []
                if isinstance(row, Mapping) and row.get("identity") == identity
            ),
            None,
        )
        try:
            current_sha = hashlib.sha256((root / relative).read_bytes()).hexdigest()
        except OSError:
            current_sha = ""
        if (
            not isinstance(unit, Mapping)
            or unit.get("run_id") != run_id
            or unit.get("contract_digest") != binding.get("contract_digest")
            or not isinstance(unit.get("input_bindings"), Mapping)
            or not isinstance(artifact, Mapping)
            or artifact.get("status") != "ACTIVE"
            or binding.get("status") != "ACTIVE"
            or artifact.get("sha256") != current_sha
            or binding.get("sha256") != current_sha
            or not isinstance(declared_output, Mapping)
        ):
            issues.append(
                f"upstream producer authority is stale or incomplete for {relative}"
            )
    return issues


def _validate_repaired_report_evidence_successor_ownership(
    scratchpad: Path, outputs: Sequence[str]
) -> list[str]:
    """A repaired bundle remains owned by the committed apply successor."""

    try:
        ledger = read_artifact_ledger(Path(scratchpad))
    except ArtifactLedgerError as exc:
        return [f"report evidence repair successor ledger is invalid: {exc}"]
    issues: list[str] = []
    for relative in outputs:
        identity = f"scratchpad:{relative}"
        binding = ledger.get("artifact_bindings", {}).get(identity)
        owner = str(binding.get("owner_key") or "") if isinstance(binding, Mapping) else ""
        try:
            current = hashlib.sha256(
                (Path(scratchpad) / relative).read_bytes()
            ).hexdigest()
        except OSError:
            current = ""
        if (
            not isinstance(binding, Mapping)
            or not owner.endswith("/report_body/evidence_repair.apply")
            or binding.get("status") != "ACTIVE"
            or binding.get("sha256") != current
        ):
            issues.append(
                f"repaired report evidence successor ownership is invalid for {relative}"
            )
    return issues


def _report_evidence_runtime_outputs(scratchpad: Path) -> tuple[str, ...]:
    root = Path(scratchpad)
    outputs = [
        "report_evidence_records.json",
        "report_evidence_repair_request.json",
        "report_evidence_projection.md",
    ]
    typed = root / "report_evidence_manifests"
    if typed.is_dir():
        outputs.extend(
            f"report_evidence_manifests/{path.name}"
            for path in sorted(typed.glob("report_*.json"))
            if path.is_file()
        )
    return tuple(outputs)


def _report_evidence_repair_inputs(scratchpad: Path) -> tuple[str, ...]:
    root = Path(scratchpad)
    paths = set(_report_evidence_source_inputs(root))
    paths.update(_report_evidence_runtime_outputs(root))
    try:
        bundle = validate_report_evidence_runtime(root)["bundle"]
        for record in bundle["records"]:
            for source in record["evidence_sources"]:
                artifact = str(source.get("artifact") or "")
                if artifact and (root / artifact).is_file():
                    paths.add(artifact)
    except (ReportEvidenceError, OSError, ValueError):
        pass
    return tuple(sorted(paths))


def _report_evidence_launch(
    *, config: Mapping[str, Any], contract: PhaseIOContract,
    actor: str, model: str, timeout_s: int,
) -> LaunchSpec:
    backend = str(config.get("cli_backend") or "claude").lower()
    return LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model=model,
        timeout_s=max(1, int(timeout_s)),
        exec_mode=(
            "python" if actor == "DRIVER" else
            ("codex" if backend == "codex" else "headless")
        ),
        tool_policy=("filesystem",),
    )


def _bind_report_evidence_io(
    *, scratchpad: Path, config: Mapping[str, Any], work_unit_id: str,
    exact_inputs: tuple[str, ...], exact_outputs: tuple[str, ...],
    actor: str, model: str, timeout_s: int,
    planned_output_bytes: Mapping[str, bytes] | None = None,
) -> tuple[PhaseIOContract, LaunchSpec, list[str]]:
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="report_body",
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
        exact_outputs=exact_outputs,
    )
    launch = _report_evidence_launch(
        config=config, contract=contract, actor=actor,
        model=model, timeout_s=timeout_s,
    )
    project = Path(str(config.get("project_root") or Path(scratchpad).parent))
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        successor_plan = None
        if planned_output_bytes is not None:
            planned = dict(planned_output_bytes)
            if set(planned) != {spec.identity for spec in contract.outputs}:
                raise ArtifactLedgerError(
                    "P1-K successor planned-output denominator differs "
                    "from the contract"
                )
            ledger = read_artifact_ledger(Path(scratchpad))
            if contract.key in ledger.get("work_units", {}):
                successor_plan = load_driver_successor_plan(
                    Path(scratchpad),
                    project,
                    contract,
                    launch,
                    run_id=run_id,
                )
                expected_postimages = {
                    identity: (
                        hashlib.sha256(raw).hexdigest(),
                        len(raw),
                    )
                    for identity, raw in planned.items()
                }
                stored_postimages = {
                    row.artifact_identity: (
                        row.after_sha256,
                        row.after_size,
                    )
                    for row in successor_plan.transitions
                }
                if stored_postimages != expected_postimages:
                    raise ArtifactLedgerError(
                        "P1-K successor stored plan differs from the "
                        "current deterministic postimage"
                    )
            else:
                successor_plan = plan_driver_successor_transaction(
                    Path(scratchpad),
                    project,
                    contract,
                    launch,
                    run_id=run_id,
                    planned_output_bytes=planned,
                )
        record_work_unit_inputs(
            scratchpad,
            project,
            contract,
            launch,
            run_id=run_id,
            successor_plan=successor_plan,
        )
        issues = validate_work_unit_inputs(
            scratchpad, project, contract, launch, run_id=run_id
        )
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        issues = [f"P1-K PhaseIO input binding failed: {exc}"]
    return contract, launch, issues


def _finish_report_evidence_io(
    *, scratchpad: Path, config: Mapping[str, Any], contract: PhaseIOContract,
    launch: LaunchSpec, actor: str,
) -> list[str]:
    project = Path(str(config.get("project_root") or Path(scratchpad).parent))
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        issues = validate_work_unit_inputs(
            scratchpad, project, contract, launch, run_id=run_id
        )
        prior = read_artifact_ledger(Path(scratchpad)).get(
            "work_units", {}
        ).get(contract.key)
        if (
            isinstance(prior, Mapping)
            and prior.get("execution_state") == "OUTPUT_COMMITTED"
        ):
            # A committed producer receipt is immutable authority, not a
            # timestamped status marker.  Reissuing it on exact resume changes
            # its digest and invalidates every already-bound downstream input
            # even when the output bytes are identical.  Resume is therefore
            # validate-only; changed bytes fail artifact validation below.
            issues.extend(validate_work_unit_artifacts(
                scratchpad, project, contract, launch,
                run_id=run_id, actor=actor,
            ))
            return issues
        record_work_unit_artifacts(
            scratchpad, project, contract, launch, run_id=run_id, actor=actor
        )
        issues.extend(validate_work_unit_artifacts(
            scratchpad, project, contract, launch,
            run_id=run_id, actor=actor,
        ))
        return issues
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        return [f"P1-K PhaseIO artifact binding failed: {exc}"]


def _report_evidence_input_manifest(
    scratchpad: Path, paths: Sequence[str]
) -> list[dict[str, Any]]:
    root = Path(scratchpad).resolve()
    rows: list[dict[str, Any]] = []
    for relative in sorted(set(paths)):
        path = (root / relative).resolve()
        try:
            path.relative_to(root)
            raw = path.read_bytes()
        except (OSError, ValueError) as exc:
            raise ReportEvidenceError(
                f"repair input is unavailable or escapes scratchpad: {relative}: {exc}"
            ) from exc
        rows.append({
            "artifact": relative,
            "size": len(raw),
            "sha256": hashlib.sha256(raw).hexdigest(),
        })
    return rows


def _report_evidence_template_path() -> Path:
    return (
        Path(__file__).resolve().parents[1]
        / "prompts" / "shared" / "v2"
        / "phase6b0-report-evidence-repair.md"
    )


def _render_report_evidence_repair_prompt(
    scratchpad: Path, input_manifest: Sequence[Mapping[str, Any]]
) -> tuple[str, str]:
    template_path = _report_evidence_template_path()
    template_raw = template_path.read_bytes()
    artifacts = "\n".join(
        f"- `{(Path(scratchpad) / str(row['artifact'])).as_posix()}` "
        f"(sha256 `{row['sha256']}`)"
        for row in input_manifest
    )
    rendered = (
        template_raw.decode("utf-8", errors="strict").rstrip()
        + "\n\n## DRIVER-BOUND INPUT MANIFEST\n\n"
        + "Read only the exact immutable artifacts below. Do not read any "
          "other scratchpad or project file. If these inputs cannot ground a "
          "requested field, emit the empty value required by the contract.\n\n"
        + artifacts
        + "\n\nWrite the JSON response only to `"
        + (Path(scratchpad) / _REPORT_EVIDENCE_REPAIR_RESPONSE).as_posix()
        + "`.\n"
    )
    return rendered, hashlib.sha256(template_raw).hexdigest()


def _report_evidence_attempt_digest(value: Mapping[str, Any]) -> str:
    unsigned = dict(value)
    unsigned["attempt_digest"] = ""
    return hashlib.sha256(json.dumps(
        unsigned, ensure_ascii=False, allow_nan=False,
        sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")).hexdigest()


def _validate_report_evidence_attempt(
    value: Mapping[str, Any], *, scratchpad: Path
) -> dict[str, Any]:
    fields = {
        "schema_version", "run_id", "request_digest", "bundle_digest",
        "input_manifest", "prompt_template_sha256", "rendered_prompt_sha256",
        "backend", "model", "timeout_s", "attempt_id", "attempt_digest",
    }
    if not isinstance(value, Mapping) or set(value) != fields:
        raise ReportEvidenceError("report repair attempt schema mismatch")
    out = dict(value)
    if out.get("schema_version") != _REPORT_EVIDENCE_ATTEMPT_SCHEMA:
        raise ReportEvidenceError("report repair attempt version mismatch")
    if out.get("attempt_digest") != _report_evidence_attempt_digest(out):
        raise ReportEvidenceError("report repair attempt digest mismatch")
    manifest = out.get("input_manifest")
    if not isinstance(manifest, list) or manifest != sorted(
        manifest,
        key=lambda row: str(
            row.get("artifact") if isinstance(row, Mapping) else ""
        ),
    ):
        raise ReportEvidenceError("report repair input manifest is non-canonical")
    expected = _report_evidence_input_manifest(
        scratchpad,
        [
            str(row.get("artifact") or "")
            for row in manifest if isinstance(row, Mapping)
        ],
    )
    if manifest != expected:
        raise ReportEvidenceError("report repair input manifest drifted")
    prompt_path = Path(scratchpad) / _REPORT_EVIDENCE_REPAIR_PROMPT
    try:
        prompt_sha = hashlib.sha256(prompt_path.read_bytes()).hexdigest()
    except OSError as exc:
        raise ReportEvidenceError("report repair prompt snapshot is missing") from exc
    if prompt_sha != out.get("rendered_prompt_sha256"):
        raise ReportEvidenceError("report repair prompt snapshot drifted")
    attempt_id = "RERA-" + hashlib.sha256(
        (
            str(out.get("run_id")) + "\0" + str(out.get("request_digest"))
        ).encode("utf-8")
    ).hexdigest()[:24].upper()
    if out.get("attempt_id") != attempt_id:
        raise ReportEvidenceError("report repair attempt identity mismatch")
    if (
        not isinstance(out.get("timeout_s"), int)
        or isinstance(out.get("timeout_s"), bool)
        or not 1 <= int(out["timeout_s"]) <= 3600
    ):
        raise ReportEvidenceError("report repair attempt timeout is invalid")
    return out


def _read_report_evidence_response(path: Path) -> dict[str, Any]:
    try:
        raw = path.read_bytes()
    except OSError as exc:
        raise ReportEvidenceError("report repair response is unavailable") from exc
    if len(raw) > _REPORT_EVIDENCE_MAX_RESPONSE_BYTES:
        raise ReportEvidenceError("report repair response exceeds byte budget")

    def _pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        out: dict[str, Any] = {}
        for key, item in pairs:
            if key in out:
                raise ReportEvidenceError(
                    f"report repair response contains duplicate key {key!r}"
                )
            out[key] = item
        return out

    try:
        value = json.loads(
            raw.decode("utf-8", errors="strict"),
            object_pairs_hook=_pairs,
            parse_constant=lambda token: (_ for _ in ()).throw(
                ReportEvidenceError(
                    f"report repair response contains non-finite number {token}"
                )
            ),
        )
    except ReportEvidenceError:
        raise
    except (UnicodeError, json.JSONDecodeError, RecursionError) as exc:
        raise ReportEvidenceError(
            f"report repair response is invalid JSON: {exc}"
        ) from exc
    if not isinstance(value, dict):
        raise ReportEvidenceError("report repair response must be an object")
    return value


def _snapshot_exact_report_repair_inputs(
    scratchpad: Path, paths: Sequence[str]
) -> dict[str, bytes]:
    return {
        relative: (Path(scratchpad) / relative).read_bytes()
        for relative in paths
        if (Path(scratchpad) / relative).is_file()
    }


def _restore_exact_report_repair_inputs(
    scratchpad: Path, snapshot: Mapping[str, bytes]
) -> list[str]:
    restored: list[str] = []
    for relative, expected in snapshot.items():
        path = Path(scratchpad) / relative
        try:
            current = path.read_bytes() if path.is_file() else None
            if current == expected:
                continue
            _atomic_driver_bytes(path, expected)
            restored.append(relative)
        except OSError:
            restored.append(relative)
    return restored


def _materialize_report_evidence_pre_body(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    *,
    enforce_upstream_ownership: bool = True,
) -> tuple[dict[str, Any] | None, list[str]]:
    """Materialize and PhaseIO-bind P1-K before any body model launch."""

    root = Path(scratchpad)
    issues: list[str] = []
    inputs = _report_evidence_source_inputs(root)
    if (
        "report_records.json" not in inputs
        or not any(path.startswith("body_manifests/") for path in inputs)
    ):
        return None, ["report records/body manifests are unavailable"]
    if enforce_upstream_ownership:
        upstream_issues = _validate_report_evidence_upstream_ownership(
            root, config, inputs
        )
        if upstream_issues:
            return None, upstream_issues
    # Crash recovery: an armed apply plan plus a response is sufficient to
    # finish the exact before->after transaction before runtime validation.
    if (
        (root / _REPORT_EVIDENCE_REPAIR_PLAN).is_file()
        and not (root / _REPORT_EVIDENCE_REPAIR_RECEIPT).is_file()
    ):
        response_path = root / _REPORT_EVIDENCE_REPAIR_RESPONSE
        if response_path.is_file():
            try:
                response = _read_report_evidence_response(response_path)
                apply_report_evidence_repair_response(root, response)
            except (ReportEvidenceError, OSError, ValueError) as exc:
                issues.append(f"crash-interrupted repair apply did not recover: {exc}")
        else:
            issues.append("repair apply plan exists without its bound response")
    try:
        contract, launch, input_issues = _bind_report_evidence_io(
            scratchpad=root,
            config=config,
            work_unit_id="evidence_pre",
            exact_inputs=inputs,
            exact_outputs=(
                "report_evidence_records.json",
                "report_evidence_repair_request.json",
                "report_evidence_projection.md",
                *tuple(
                    "report_evidence_manifests/"
                    + Path(path).name
                    for path in inputs
                    if path.startswith("body_manifests/")
                ),
            ),
            actor="DRIVER",
            model="driver",
            timeout_s=120,
        )
        issues.extend(input_issues)
        if input_issues:
            return None, issues
        runtime = materialize_report_evidence_runtime(root)
        if (root / _REPORT_EVIDENCE_REPAIR_RECEIPT).is_file():
            # The baseline adapter may re-derive and compare the source
            # boundary, but it cannot take ownership back from the committed
            # repair successor merely because an exact resume occurred.
            issues.extend(
                _validate_repaired_report_evidence_successor_ownership(
                    root, _report_evidence_runtime_outputs(root)
                )
            )
        else:
            issues.extend(_finish_report_evidence_io(
                scratchpad=root,
                config=config,
                contract=contract,
                launch=launch,
                actor="DRIVER",
            ))
        if issues:
            return runtime, issues
        return runtime, []
    except (ArtifactLedgerError, ReportEvidenceError, OSError, ValueError) as exc:
        issues.append(f"typed pre-body boundary failed: {type(exc).__name__}: {exc}")
        return None, issues


def _prepare_and_apply_report_evidence_response(
    *, scratchpad: Path, config: dict[str, Any], response: Mapping[str, Any]
) -> list[str]:
    root = Path(scratchpad)
    issues: list[str] = []
    prepare_inputs = (
        "report_evidence_records.json",
        "report_evidence_repair_request.json",
        _REPORT_EVIDENCE_REPAIR_RESPONSE,
    )
    prepare_contract, prepare_launch, prepare_issues = _bind_report_evidence_io(
        scratchpad=root,
        config=config,
        work_unit_id="evidence_repair.prepare",
        exact_inputs=prepare_inputs,
        exact_outputs=(_REPORT_EVIDENCE_REPAIR_PLAN,),
        actor="DRIVER",
        model="driver",
        timeout_s=120,
    )
    issues.extend(prepare_issues)
    if prepare_issues:
        return issues
    prepare_report_evidence_repair_apply_plan(root, response)
    issues.extend(_finish_report_evidence_io(
        scratchpad=root,
        config=config,
        contract=prepare_contract,
        launch=prepare_launch,
        actor="DRIVER",
    ))
    if issues:
        return issues
    body_manifests = tuple(
        f"body_manifests/{path.name}"
        for path in sorted((root / "body_manifests").glob("report_*.json"))
    )
    apply_outputs = (
        "report_evidence_records.json",
        "report_evidence_repair_request.json",
        "report_evidence_projection.md",
        *tuple(
            f"report_evidence_manifests/{path.name}"
            for path in sorted(
                (root / "report_evidence_manifests").glob("report_*.json")
            )
        ),
        # Receipt is the semantic commit point and is therefore always the
        # final transition in the transaction-bound successor plan.
        _REPORT_EVIDENCE_REPAIR_RECEIPT,
    )
    apply_inputs = (
        _REPORT_EVIDENCE_REPAIR_PLAN,
        _REPORT_EVIDENCE_REPAIR_RESPONSE,
        *body_manifests,
    )
    planned_relative = plan_report_evidence_repair_output_bytes(
        root, response
    )
    planned_identities = {
        f"scratchpad:{relative}": raw
        for relative, raw in planned_relative.items()
    }
    apply_contract, apply_launch, apply_issues = _bind_report_evidence_io(
        scratchpad=root,
        config=config,
        work_unit_id="evidence_repair.apply",
        exact_inputs=apply_inputs,
        exact_outputs=apply_outputs,
        actor="DRIVER",
        model="driver",
        timeout_s=120,
        planned_output_bytes=planned_identities,
    )
    issues.extend(apply_issues)
    if apply_issues:
        return issues
    project_root = Path(
        str(config.get("project_root") or root.parent)
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        for ordinal, spec in enumerate(apply_contract.outputs, start=1):
            begin_driver_successor_step(
                root,
                project_root,
                apply_contract,
                apply_launch,
                run_id=run_id,
                ordinal=ordinal,
            )
            raw = planned_relative[spec.path]
            path = root / spec.path
            if (
                not path.is_file()
                or path.is_symlink()
                or path.read_bytes() != raw
            ):
                _atomic_driver_bytes(path, raw)
            complete_driver_successor_step(
                root,
                project_root,
                apply_contract,
                apply_launch,
                run_id=run_id,
                ordinal=ordinal,
            )
        validate_report_evidence_runtime(root)
    except (
        ArtifactLedgerError,
        OSError,
        ReportEvidenceError,
        ValueError,
    ) as exc:
        issues.append(
            "report evidence successor apply failed: "
            f"{type(exc).__name__}: {exc}"
        )
        return list(dict.fromkeys(issues))
    issues.extend(_finish_report_evidence_io(
        scratchpad=root,
        config=config,
        contract=apply_contract,
        launch=apply_launch,
        actor="DRIVER",
    ))
    return list(dict.fromkeys(issues))


def _run_report_evidence_repair_once(
    phase: Phase, config: dict[str, Any], scratchpad: Path
) -> list[str]:
    """Run at most one request-bound repair worker, then deterministically apply."""

    root = Path(scratchpad)
    issues: list[str] = []
    try:
        runtime = validate_report_evidence_runtime(root)
        request_raw = json.loads(
            (root / "report_evidence_repair_request.json").read_text(
                encoding="utf-8", errors="strict"
            )
        )
        request = validate_report_evidence_repair_request(
            request_raw,
            bundle_digest=runtime["bundle"]["bundle_digest"],
        )
    except (OSError, UnicodeError, json.JSONDecodeError, ReportEvidenceError) as exc:
        return [f"repair request/runtime invalid: {exc}"]
    if not request["items"] or (root / _REPORT_EVIDENCE_REPAIR_RECEIPT).is_file():
        return []

    response_path = root / _REPORT_EVIDENCE_REPAIR_RESPONSE
    attempt_path = root / _REPORT_EVIDENCE_REPAIR_ATTEMPT
    repair_inputs = _report_evidence_repair_inputs(root)
    input_manifest = _report_evidence_input_manifest(root, repair_inputs)
    prompt, template_sha = _render_report_evidence_repair_prompt(
        root, input_manifest
    )
    prompt_path = root / _REPORT_EVIDENCE_REPAIR_PROMPT
    timeout_s = int(max(60, min(
        3600, int(config.get("report_evidence_repair_timeout_s") or 900)
    )))
    model = phase_model(
        phase, str(config.get("mode") or "thorough"), config
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    attempt_id = "RERA-" + hashlib.sha256(
        (run_id + "\0" + request["request_digest"]).encode("utf-8")
    ).hexdigest()[:24].upper()
    expected_attempt: dict[str, Any] = {
        "schema_version": _REPORT_EVIDENCE_ATTEMPT_SCHEMA,
        "run_id": run_id,
        "request_digest": request["request_digest"],
        "bundle_digest": request["bundle_digest"],
        "input_manifest": input_manifest,
        "prompt_template_sha256": template_sha,
        "rendered_prompt_sha256": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
        "backend": str(config.get("cli_backend") or "claude").lower(),
        "model": model,
        "timeout_s": timeout_s,
        "attempt_id": attempt_id,
        "attempt_digest": "",
    }
    expected_attempt["attempt_digest"] = _report_evidence_attempt_digest(
        expected_attempt
    )

    if attempt_path.exists():
        try:
            existing = json.loads(attempt_path.read_text(encoding="utf-8"))
            attempt = _validate_report_evidence_attempt(
                existing, scratchpad=root
            )
            if attempt != expected_attempt:
                raise ReportEvidenceError(
                    "repair attempt does not bind the current exact request"
                )
        except (OSError, UnicodeError, json.JSONDecodeError, ReportEvidenceError) as exc:
            return [f"existing one-shot repair attempt is invalid: {exc}"]
        if not response_path.is_file():
            return [
                "one-shot report repair was armed but produced no response; "
                "the attempt will not be relaunched"
            ]
    else:
        if response_path.exists():
            return ["unowned report repair response exists without an armed attempt"]
        arm_inputs = repair_inputs
        arm_contract, arm_launch, arm_issues = _bind_report_evidence_io(
            scratchpad=root,
            config=config,
            work_unit_id="evidence_repair.arm",
            exact_inputs=arm_inputs,
            exact_outputs=(
                _REPORT_EVIDENCE_REPAIR_ATTEMPT,
                _REPORT_EVIDENCE_REPAIR_PROMPT,
            ),
            actor="DRIVER",
            model="driver",
            timeout_s=120,
        )
        issues.extend(arm_issues)
        if arm_issues:
            return issues
        # The arm records an ABSENT (or exact resumed) output prestate before
        # either DRIVER-owned byte is materialized. Writing the prompt first
        # would let a current file be mistaken for an authorized predecessor
        # and defeats the transaction boundary.
        if prompt_path.exists():
            try:
                if prompt_path.read_text(encoding="utf-8") != prompt:
                    return ["pre-existing report repair prompt snapshot drifted"]
            except (OSError, UnicodeError) as exc:
                return [f"report repair prompt snapshot is unreadable: {exc}"]
        else:
            _atomic_driver_bytes(prompt_path, prompt.encode("utf-8"))
        _atomic_driver_json(attempt_path, expected_attempt)
        issues.extend(_finish_report_evidence_io(
            scratchpad=root, config=config, contract=arm_contract,
            launch=arm_launch, actor="DRIVER",
        ))
        if issues:
            return issues
    model_inputs = tuple(sorted(set(repair_inputs) | {
        _REPORT_EVIDENCE_REPAIR_ATTEMPT,
        _REPORT_EVIDENCE_REPAIR_PROMPT,
    }))
    model_contract, model_launch, model_issues = _bind_report_evidence_io(
        scratchpad=root,
        config=config,
        work_unit_id="evidence_repair.model",
        exact_inputs=model_inputs,
        exact_outputs=(_REPORT_EVIDENCE_REPAIR_RESPONSE,),
        actor="MODEL",
        model=model,
        timeout_s=timeout_s,
    )
    issues.extend(model_issues)
    if model_issues:
        return issues
    if not response_path.is_file():
        protected = _snapshot_exact_report_repair_inputs(root, model_inputs)
        try:
            if str(config.get("cli_backend") or "claude").lower() == "codex":
                rc = _run_one_codex_exec(
                    prompt=prompt,
                    phase=phase,
                    config=config,
                    scratchpad=root,
                    attempt=1,
                    label="report_evidence_repair",
                    expected_outputs=[_REPORT_EVIDENCE_REPAIR_RESPONSE],
                    timeout=float(timeout_s),
                    effective_model=model,
                    phase_io_contract=model_contract,
                    phase_io_launch=model_launch,
                )
            else:
                rc = _run_one_claude_headless_breadth_worker(
                    prompt=prompt,
                    job={
                        "agent_id": "REPORT_EVIDENCE_REPAIR",
                        "output": _REPORT_EVIDENCE_REPAIR_RESPONSE,
                    },
                    phase=phase,
                    config=config,
                    scratchpad=root,
                    attempt=1,
                    timeout=float(timeout_s),
                    effective_model=model,
                    label_prefix="report_evidence",
                    phase_io_contract=model_contract,
                    phase_io_launch=model_launch,
                )
        except Exception as exc:
            rc = EXIT_ERROR
            issues.append(
                f"report evidence repair launch failed: {type(exc).__name__}: {exc}"
            )
        restored = _restore_exact_report_repair_inputs(root, protected)
        if restored:
            issues.append(
                "report repair worker modified protected inputs; restored: "
                + ", ".join(restored)
            )
        if rc != 0 or not response_path.is_file():
            issues.append(
                f"one-shot report repair produced no usable response (rc={rc})"
            )
            return list(dict.fromkeys(issues))
        issues.extend(_finish_report_evidence_io(
            scratchpad=root, config=config, contract=model_contract,
            launch=model_launch, actor="MODEL",
        ))
        if issues:
            return list(dict.fromkeys(issues))
    else:
        # Resume may only reuse bytes that were already bound as this model
        # work-unit's output.  Validate before recording again; otherwise a
        # post-launch disk edit could be silently laundered into a fresh MODEL
        # ownership record on resume.  An unrecorded response remains eligible
        # for crash recovery (worker wrote it, driver died before commit).
        try:
            prior_unit = read_artifact_ledger(root).get("work_units", {}).get(
                model_contract.key
            )
            prior_output = (
                prior_unit.get("artifacts", {}).get(
                    f"scratchpad:{_REPORT_EVIDENCE_REPAIR_RESPONSE}"
                )
                if isinstance(prior_unit, Mapping)
                else None
            )
            if (
                isinstance(prior_output, Mapping)
                and prior_output.get("status") == "ACTIVE"
                and prior_output.get("sha256")
            ):
                prior_output_issues = validate_work_unit_artifacts(
                    root,
                    Path(str(config.get("project_root") or root.parent)),
                    model_contract,
                    model_launch,
                    run_id=str(config.get("_run_id") or "test-unbound"),
                    actor="MODEL",
                )
                if prior_output_issues:
                    return [
                        "recorded report repair response drifted before resume: "
                        + "; ".join(prior_output_issues)
                    ]
        except (ArtifactLedgerError, OSError, ValueError) as exc:
            return [f"recorded report repair response cannot be trusted: {exc}"]
        issues.extend(_finish_report_evidence_io(
            scratchpad=root, config=config, contract=model_contract,
            launch=model_launch, actor="MODEL",
        ))
        if issues:
            return list(dict.fromkeys(issues))

    try:
        response = _read_report_evidence_response(response_path)
        validate_report_evidence_repair_response(
            response, request_digest=request["request_digest"]
        )
        issues.extend(_prepare_and_apply_report_evidence_response(
            scratchpad=root, config=config, response=response
        ))
    except (ArtifactLedgerError, ReportEvidenceError, OSError, ValueError) as exc:
        issues.append(
            f"report repair response reconciliation failed: {type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(issues))


def _ensure_report_evidence_before_body_writer(
    phase: Phase, config: dict[str, Any], scratchpad: Path
) -> list[str]:
    runtime, issues = _materialize_report_evidence_pre_body(
        phase,
        config,
        scratchpad,
        # A live driver run always has a checkpoint before report phases.
        # Isolated unit/API harnesses exercise transaction mechanics without a
        # reproduced upstream phase graph; the low-level boundary remains
        # strict by default and production cannot enter this compatibility
        # path.
        enforce_upstream_ownership=(
            Path(scratchpad) / "_v2_checkpoint.json"
        ).is_file(),
    )
    if runtime is not None and not issues:
        issues.extend(_run_report_evidence_repair_once(
            phase, config, scratchpad
        ))
    for issue in list(dict.fromkeys(issues)):
        _report_evidence_debt(scratchpad, "P1K_PRE_BODY_DEBT", issue)
        _append_phase_io_debt(
            scratchpad, phase.name, "P1K_PRE_BODY_DEBT", issue
        )
    return list(dict.fromkeys(issues))


def _materialize_runtime_debt_report_body(
    phase: Phase, config: dict[str, Any], scratchpad: Path
) -> tuple[bool, list[str]]:
    """Render an explicitly unverified body when verifier work is retained debt.

    This is a typed DRIVER fallback, not a verifier or report-model substitute.
    It preserves every assigned row, marks absent evidence REPORT-BLOCKED and
    UNRESOLVED, and binds the exact runtime-debt receipt.  Normal verified
    shards continue to use the legacy Claude body writer.
    """

    if not phase.name.startswith("report_body_writer_"):
        return False, []
    root = Path(scratchpad)
    shard = "report_" + phase.name[len("report_body_writer_") :]
    typed_relative = f"report_evidence_manifests/{shard}.json"
    bundle_relative = "report_evidence_records.json"
    if not (root / typed_relative).is_file() or not (
        root / bundle_relative
    ).is_file():
        return False, []
    try:
        _bundle, records = load_typed_report_evidence_shard(root, shard)
    except (OSError, ReportEvidenceError, ValueError) as exc:
        return False, [f"runtime-debt report fallback inputs are invalid: {exc}"]
    if not records:
        return False, []
    if not any(
        "VERIFICATION_RUNTIME_DEBT_UNRESOLVED" in record.get("limitations", ())
        for record in records
    ):
        return False, []
    exact_inputs = (bundle_relative, typed_relative)
    output = str(phase.expected_artifacts[0])
    try:
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "thorough"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="report_body",
            work_unit_id=f"{shard}.runtime_debt_fallback",
            exact_inputs=exact_inputs,
            exact_outputs=(output,),
        )
        launch = LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver",
            timeout_s=120,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        project_root = Path(str(config.get("project_root") or root.parent))
        run_id = str(config.get("_run_id") or "test-unbound")
        prior_unit = read_artifact_ledger(root).get(
            "work_units", {}
        ).get(contract.key)
        if not (
            isinstance(prior_unit, Mapping)
            and prior_unit.get("execution_state")
            == "INPUTS_BOUND_PREEXECUTION"
        ):
            record_work_unit_inputs(
                root,
                project_root,
                contract,
                launch,
                run_id=run_id,
            )
        input_issues = validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        )
        if input_issues:
            return False, [
                "runtime-debt report fallback input authority failed: "
                + "; ".join(input_issues)
            ]
        rendered = render_typed_report_evidence_shard(root, shard)
        body_issues = validate_typed_report_evidence_shard_markdown(
            root, shard, rendered
        )
        if body_issues:
            return False, [
                "runtime-debt report fallback body validation failed: "
                + "; ".join(body_issues)
            ]

        output_path = root / output
        rendered_bytes = rendered.encode("utf-8")
        after_sha = hashlib.sha256(rendered_bytes).hexdigest()
        transaction_dir = root / "_report_body_transactions"
        transaction_dir.mkdir(parents=True, exist_ok=True)
        transaction_path = transaction_dir / f"{shard}.runtime_debt.json"
        backup_path = transaction_dir / f"{shard}.runtime_debt.before"
        input_digests = {
            relative: hashlib.sha256((root / relative).read_bytes()).hexdigest()
            for relative in exact_inputs
        }
        current_bytes = output_path.read_bytes() if output_path.is_file() else None
        current_sha = (
            hashlib.sha256(current_bytes).hexdigest()
            if current_bytes is not None
            else ""
        )

        if transaction_path.is_file():
            transaction = json.loads(
                transaction_path.read_text(encoding="utf-8", errors="strict")
            )
            unsigned = dict(transaction)
            recorded_digest = unsigned.pop("transaction_digest", "")
            expected_digest = hashlib.sha256(
                json.dumps(
                    unsigned,
                    ensure_ascii=False,
                    allow_nan=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            if (
                recorded_digest != expected_digest
                or transaction.get("schema_version")
                != "plamen.runtime_debt_report_transaction.v1"
                or transaction.get("run_id") != run_id
                or transaction.get("contract_digest") != contract.digest
                or transaction.get("input_sha256") != input_digests
                or transaction.get("output") != output
                or transaction.get("after_sha256") != after_sha
                or transaction.get("state") != "ARMED"
            ):
                return False, [
                    "runtime-debt report fallback recovery transaction is stale or tampered"
                ]
            before_present = bool(transaction.get("before_present"))
            before_sha = str(transaction.get("before_sha256") or "")
            if before_present:
                if (
                    not backup_path.is_file()
                    or hashlib.sha256(backup_path.read_bytes()).hexdigest()
                    != before_sha
                ):
                    return False, [
                        "runtime-debt report fallback recovery backup is unavailable"
                    ]
            if current_sha not in {before_sha, after_sha}:
                return False, [
                    "runtime-debt report fallback output changed outside its armed transaction"
                ]
        else:
            # Never silently replace an unrelated or tampered tier.  A current
            # model-owned tier may be superseded only when the ledger binds its
            # exact bytes in this run; the durable transaction below preserves
            # those bytes until the DRIVER successor commits.
            if current_bytes is not None:
                ledger = read_artifact_ledger(root)
                binding = ledger.get("artifact_bindings", {}).get(
                    f"scratchpad:{output}"
                )
                owner = str(binding.get("owner_key") or "") if isinstance(
                    binding, Mapping
                ) else ""
                allowed_owner = (
                    owner == contract.key
                    or owner.endswith(f"/report_body/model.{shard}")
                )
                if (
                    not isinstance(binding, Mapping)
                    or not allowed_owner
                    or binding.get("run_id") != run_id
                    or binding.get("status") != "ACTIVE"
                    or binding.get("sha256") != current_sha
                ):
                    return False, [
                        "runtime-debt report fallback refused to overwrite an unowned tier"
                    ]
                _atomic_driver_bytes(backup_path, current_bytes)
            else:
                backup_path.unlink(missing_ok=True)
            unsigned = {
                "schema_version": "plamen.runtime_debt_report_transaction.v1",
                "state": "ARMED",
                "run_id": run_id,
                "contract_digest": contract.digest,
                "input_sha256": input_digests,
                "output": output,
                "before_present": current_bytes is not None,
                "before_sha256": current_sha,
                "after_sha256": after_sha,
            }
            transaction = {
                **unsigned,
                "transaction_digest": hashlib.sha256(
                    json.dumps(
                        unsigned,
                        ensure_ascii=False,
                        allow_nan=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest(),
            }
            _atomic_driver_json_record(transaction_path, transaction)

        if current_sha != after_sha:
            _atomic_driver_bytes(output_path, rendered_bytes)
        record_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        output_issues = validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        if output_issues:
            return False, [
                "runtime-debt report fallback output authority failed: "
                + "; ".join(output_issues)
            ]
        transaction_path.unlink(missing_ok=True)
        backup_path.unlink(missing_ok=True)
    except (
        ArtifactLedgerError,
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ReportEvidenceError,
        ValueError,
    ) as exc:
        return False, [
            "runtime-debt report fallback transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    return True, []


def _project_report_evidence_file(
    scratchpad: Path, report_path: Path
) -> tuple[bool, list[str]]:
    """Project typed fields into one tier/final report, without widening claims."""

    try:
        runtime = validate_report_evidence_runtime(scratchpad)
        before = Path(report_path).read_text(encoding="utf-8", errors="strict")
        after = project_report_evidence_markdown(before, runtime["bundle"])
        if after != before:
            _atomic_driver_bytes(
                Path(report_path), (after.rstrip() + "\n").encode("utf-8")
            )
            return True, []
        return False, []
    except (OSError, UnicodeError, ReportEvidenceError, ValueError) as exc:
        issue = f"typed report evidence projection failed: {type(exc).__name__}: {exc}"
        _report_evidence_debt(scratchpad, "P1K_PROJECTION_DEBT", issue)
        return False, [issue]


def _validate_report_evidence_projection_file(
    scratchpad: Path, report_path: Path
) -> list[str]:
    """Assert the current projection is a fixed point without rewriting bytes."""

    try:
        runtime = validate_report_evidence_runtime(Path(scratchpad))
        before = Path(report_path).read_text(encoding="utf-8", errors="strict")
        after = project_report_evidence_markdown(before, runtime["bundle"])
        if after != before:
            return [
                "report evidence and assurance projections did not reach a "
                "stable fixed point"
            ]
        return []
    except (OSError, UnicodeError, ReportEvidenceError, ValueError) as exc:
        return [
            "typed report evidence fixed-point validation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _project_report_evidence_transaction(
    scratchpad: Path,
    project_root: Path,
    *,
    run_id: str,
    phase: str,
) -> tuple[bool, list[str]]:
    """Project typed evidence as a recoverable successor report transaction."""
    root = Path(scratchpad)
    project = Path(project_root)
    candidate_relative = f"{phase}.candidate.md"
    try:
        state = report_mutation_transaction_state(
            scratchpad=root, run_id=run_id, phase=phase
        )
        if state is not None:
            result = recover_report_mutation_transaction(
                scratchpad=root,
                project_root=project,
                run_id=run_id,
                phase=phase,
                report_candidate_sidecar=candidate_relative,
            )
            if result is None:
                raise ReportMutationTransactionError(
                    "typed evidence successor has no armed manifest"
                )
            return result.changed, []
        exact_inputs = _report_evidence_repair_inputs(root)
        input_snapshot = capture_report_transaction_inputs(
            root, exact_inputs
        )
        runtime = validate_report_evidence_runtime(root)
        report_path = project / "AUDIT_REPORT.md"
        before = report_path.read_text(encoding="utf-8", errors="strict")
        projected = project_report_evidence_markdown(before, runtime["bundle"])
        after = (projected.rstrip() + "\n").encode("utf-8")
        result = apply_report_mutation_transaction(
            scratchpad=root,
            project_root=project,
            run_id=run_id,
            phase=phase,
            post_report=after,
            exact_inputs=exact_inputs,
            expected_inputs=input_snapshot,
            sidecars={candidate_relative: after},
        )
        return result.changed, []
    except (
        OSError,
        UnicodeError,
        ReportEvidenceError,
        ReportMutationTransactionError,
        ValueError,
    ) as exc:
        issue = (
            "typed report evidence transaction failed: "
            f"{type(exc).__name__}: {exc}"
        )
        _report_evidence_debt(root, "P1K_PROJECTION_DEBT", issue)
        return False, [issue]


def _finalize_report_evidence_quality(
    scratchpad: Path,
    config: dict[str, Any],
    *,
    compare_only: bool = False,
    accepted_report_sha256: list[str] | None = None,
) -> list[str]:
    root = Path(scratchpad)
    report_path = Path(config["project_root"]) / "AUDIT_REPORT.md"
    if accepted_report_sha256 is not None:
        accepted_report_sha256.clear()
    inputs = list(_report_evidence_runtime_outputs(root))
    if (root / _REPORT_EVIDENCE_REPAIR_RECEIPT).is_file():
        inputs.append(_REPORT_EVIDENCE_REPAIR_RECEIPT)
    try:
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "thorough"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="report_floor",
            work_unit_id="evidence_quality",
            exact_inputs=tuple(sorted(set(inputs))),
            exact_outputs=("report_evidence_quality_receipt.json",),
        )
        launch = _report_evidence_launch(
            config=config, contract=contract, actor="DRIVER",
            model="driver", timeout_s=120,
        )
        project = Path(config["project_root"])
        run_id = str(config.get("_run_id") or "test-unbound")
        if not compare_only:
            record_work_unit_inputs(
                root, project, contract, launch, run_id=run_id
            )
        issues = validate_work_unit_inputs(
            root, project, contract, launch, run_id=run_id
        )
        if issues:
            return issues
        receipt = finalize_report_evidence_delivery(
            root,
            report_path=report_path,
            compare_only=compare_only,
        )
        if not compare_only:
            record_work_unit_artifacts(
                root,
                project,
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            )
        artifact_issues = validate_work_unit_artifacts(
            root, project, contract, launch, run_id=run_id, actor="DRIVER"
        )
        if receipt.get("unauthorized_proof_grade_report_ids"):
            artifact_issues.append(
                "unauthorized proof-grade report claims: "
                + ", ".join(receipt["unauthorized_proof_grade_report_ids"])
            )
        if (
            receipt.get("delivery_state")
            == "STRUCTURAL_DELIVERY_INCOMPLETE"
            or receipt.get("structurally_delivered") is not True
        ):
            artifact_issues.append(
                "structural report-evidence delivery is incomplete"
            )
        report_sha256 = receipt.get("report_sha256")
        if not artifact_issues and accepted_report_sha256 is not None:
            if not isinstance(report_sha256, str) or not re.fullmatch(
                r"[0-9a-f]{64}", report_sha256
            ):
                artifact_issues.append(
                    "terminal report evidence receipt has no authenticated "
                    "report digest"
                )
            else:
                accepted_report_sha256.append(report_sha256)
        return list(dict.fromkeys(artifact_issues))
    except (ArtifactLedgerError, ReportEvidenceError, OSError, ValueError) as exc:
        issue = f"final report evidence quality binding failed: {type(exc).__name__}: {exc}"
        _report_evidence_debt(root, "P1K_FINAL_QUALITY_DEBT", issue)
        return [issue]


def _canonical_identity_projection_issues(root: Path) -> list[str]:
    """Validate the two deterministic semantic-identity projections."""

    issues: list[str] = []
    expectations = {
        "_canonical_finding_ids.json": (
            "plamen.canonical_finding_ids.v1",
            "record_count",
            "records",
        ),
        "_unmapped_id_tokens.json": (
            "plamen.unmapped_id_tokens.v1",
            "token_count",
            "tokens",
        ),
    }
    for name, (schema, count_field, rows_field) in expectations.items():
        try:
            payload = json.loads(
                (Path(root) / name).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            issues.append(
                f"{name}: semantic identity projection is unreadable: "
                f"{type(exc).__name__}: {exc}"
            )
            continue
        rows = payload.get(rows_field) if isinstance(payload, Mapping) else None
        if (
            not isinstance(payload, Mapping)
            or payload.get("schema_version") != schema
            or not isinstance(rows, list)
            or payload.get(count_field) != len(rows)
        ):
            issues.append(
                f"{name}: semantic identity projection schema/count is invalid"
            )
    return issues


def _run_canonical_identity_projection_transaction(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    source_phase: str,
) -> dict[str, Any]:
    """Refresh canonical identity sidecars under one exact DRIVER receipt."""

    root = Path(scratchpad)
    project = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return {
            "safe_to_consume": False,
            "mapped": 0,
            "issues": ["semantic identity projection run_id is absent"],
        }
    token = re.sub(
        r"[^a-z0-9_.-]+",
        "-",
        str(source_phase or "unknown").strip().lower(),
    ).strip("-.") or "unknown"
    try:
        from plamen_mechanical import (
            _producer_artifact_paths_for_identity,
        )

        source_names = tuple(sorted({
            path.relative_to(root).as_posix()
            for path in _producer_artifact_paths_for_identity(root)
            if path.is_file()
        }))
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "thorough"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="semantic_identity",
            work_unit_id=f"projection.{token}",
            exact_inputs=source_names,
            exact_outputs=(
                "_canonical_finding_ids.json",
                "_unmapped_id_tokens.json",
            ),
        )
        launch = LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver",
            timeout_s=120,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if arm_issues:
            return {
                "safe_to_consume": False,
                "mapped": 0,
                "issues": list(dict.fromkeys(arm_issues)),
            }
        mapped = 0
        if execute:
            mapped = _write_canonical_finding_identity_map(
                root,
                phase_name=str(source_phase or ""),
                pipeline=str(config.get("pipeline") or ""),
                mode=str(config.get("mode") or ""),
            )
            projection_issues = _canonical_identity_projection_issues(root)
            if projection_issues:
                return {
                    "safe_to_consume": False,
                    "mapped": mapped,
                    "issues": projection_issues,
                }
            commit_issues = _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
            if commit_issues:
                return {
                    "safe_to_consume": False,
                    "mapped": mapped,
                    "issues": list(dict.fromkeys(commit_issues)),
                }
        else:
            projection_issues = _canonical_identity_projection_issues(root)
            if projection_issues:
                return {
                    "safe_to_consume": False,
                    "mapped": 0,
                    "issues": projection_issues,
                }
            payload = json.loads(
                (root / "_canonical_finding_ids.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            mapped = int(payload.get("record_count") or 0)
        return {
            "safe_to_consume": True,
            "mapped": mapped,
            "issues": [],
            "work_unit_key": contract.key,
        }
    except (
        ArtifactLedgerError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
    ) as exc:
        return {
            "safe_to_consume": False,
            "mapped": 0,
            "issues": [
                "semantic identity projection transaction failed: "
                f"{type(exc).__name__}: {exc}"
            ],
        }


