def _preverify_capture_input_authority_issues(
    scratchpad: Path,
    contract: PhaseIOContract,
    *,
    run_id: str,
) -> list[str]:
    """Reject semantic capture roots that are merely unowned local bytes."""

    try:
        ledger = read_artifact_ledger(Path(scratchpad))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "preverify capture producer authority ledger is unavailable: "
            f"{type(exc).__name__}: {exc}"
        ]
    unit = ledger.get("work_units", {}).get(contract.key)
    bindings = (
        unit.get("input_bindings")
        if isinstance(unit, Mapping)
        else None
    )
    if not isinstance(bindings, Mapping):
        return [
            "preverify capture has no armed semantic input denominator"
        ]
    issues: list[str] = []
    for identity in sorted(contract.immutable_inputs):
        # Project source loci remain governed by the run snapshot/capture-plan
        # roster.  Scratchpad semantic artifacts must descend from an active
        # current-run producer or a validated durable mutation successor.
        if not identity.startswith("scratchpad:"):
            continue
        record = bindings.get(identity)
        if not isinstance(record, Mapping):
            issues.append(
                f"{identity}: preverify capture input binding is absent"
            )
            continue
        if identity == "scratchpad:_semantic_mutations.json":
            # This is an artifact-ledger system control, not an ordinary
            # phase output.  Its writer durably arms each transition before
            # semantic bytes change and the public reader validates the full
            # event/digest chain.  It therefore needs validation as a trusted
            # control preimage rather than a fictitious PhaseIO producer.
            try:
                mutation_rows = semantic_mutation_events(Path(scratchpad))
            except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
                issues.append(
                    f"{identity}: semantic-mutation control authority is "
                    f"invalid: {type(exc).__name__}: {exc}"
                )
                continue
            armed = [
                str(row.get("event_id") or "")
                for row in mutation_rows
                if (
                    row.get("run_id") == run_id
                    and row.get("status") == "ARMED"
                )
            ]
            if armed:
                issues.append(
                    f"{identity}: semantic-mutation control has unresolved "
                    "current-run ARMED event(s): " + ", ".join(armed)
                )
            continue
        issues.extend(
            semantic_input_producer_authority_issues(
                ledger,
                record,
                run_id=run_id,
            )
        )
    try:
        frozen_authority = resolve_exact_frozen_capture_authority(
            input_bindings=bindings,
            ledger=ledger,
            run_id=run_id,
            identities=contract.immutable_inputs,
        )
    except PreverifyProjectionAuthorityError as exc:
        issues.append(str(exc))
    else:
        expected_suffix = (
            f"/{contract.phase}/preverify_frozen_projection."
            f"{frozen_authority['frozen_generation']}"
        )
        if not str(frozen_authority["producer_key"]).endswith(
            expected_suffix
        ):
            issues.append(
                "preverify frozen capture producer belongs to a different "
                "phase authority"
            )
    return list(dict.fromkeys(issues))


def _finalize_preverify_inventory_successors(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    phase_name: str,
    frozen_projection: Mapping[str, Any] | None = None,
) -> list[str]:
    """Publish the sole queue-consumable final inventory/delivery authority.

    Producer-local promotion receipts may be generated before later additive
    mutators.  This transaction therefore runs once at the final pre-queue
    boundary and binds the exact final inventory plus every materialized
    registered producer.  A changed inventory/source forces a new authorized
    successor generation; stale bytes can never be silently reused.
    """

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["preverify inventory successor requires a non-empty run_id"]
    identity_result = _run_canonical_identity_projection_transaction(
        scratchpad=root,
        config=config,
        source_phase=f"{phase_name}.preverify",
    )
    if identity_result.get("safe_to_consume") is not True:
        return [
            "preverify canonical identity projection is unavailable: "
            + "; ".join(
                str(value)
                for value in identity_result.get("issues") or (
                    "unknown semantic identity debt",
                )
            )
        ]
    try:
        logical_to_physical = (
            dict(frozen_projection.get("logical_to_physical") or {})
            if isinstance(frozen_projection, Mapping)
            else {}
        )
        inventory_source = str(
            logical_to_physical.get(
                "findings_inventory.md",
                "findings_inventory.md",
            )
        )
        records_source = str(
            logical_to_physical.get(
                "finding_records.json",
                "finding_records.json",
            )
        )
        evidence_source = str(
            logical_to_physical.get(
                "inventory_evidence_validation.md",
                "",
            )
        )
        projection_receipt = str(
            frozen_projection.get("receipt_path") or ""
        ) if isinstance(frozen_projection, Mapping) else ""

        def _recompute_generation() -> tuple[
            PreverifyCapturePlan,
            dict[str, Any],
            dict[str, Any],
            str,
            dict[str, Any],
        ]:
            inventory_text = (root / inventory_source).read_text(
                encoding="utf-8", errors="strict"
            )
            scan = _scan_registered_finding_delivery_sources(root)
            delivery_payload = (
                _build_registered_finding_delivery_receipt_payload(
                    root,
                    scan,
                    inventory_text,
                    inventory_source_artifact=inventory_source,
                )
            )
            producer_names = tuple(sorted({
                str(row.get("artifact") or "")
                for row in (scan.get("artifacts") or [])
                if (
                    isinstance(row, Mapping)
                    and str(row.get("artifact") or "")
                )
            }))
            capture_plan = _build_current_preverify_capture_plan(
                root,
                config,
                producer_names=producer_names,
                inventory_source_artifact=inventory_source,
                records_source_artifact=records_source,
                evidence_source_artifact=evidence_source,
                additional_control_artifacts=(
                    (projection_receipt,) if projection_receipt else ()
                ),
            )
            mutation_names = tuple(
                name
                for name in _PREVERIFY_MUTATION_AUTHORITY_CANDIDATES
                if (root / name).is_file()
            )
            final_payload, registered_payload = (
                build_preverify_successor_payloads(
                    root,
                    run_id=run_id,
                    delivery_payload=delivery_payload,
                    producer_artifacts=producer_names,
                    mutation_authority_artifacts=mutation_names,
                    inventory_source_artifact=inventory_source,
                )
            )
            generation_name, generation_payload = (
                build_successor_generation_payload(
                    run_id=run_id,
                    final_payload=final_payload,
                    delivery_payload=registered_payload,
                    capture_plan=capture_plan,
                )
            )
            return (
                capture_plan,
                final_payload,
                registered_payload,
                generation_name,
                generation_payload,
            )

        (
            capture_plan,
            final_payload,
            registered_payload,
            generation_name,
            generation_payload,
        ) = _recompute_generation()
        generation_digest = str(
            generation_payload["generation_digest"]
        )
        capture_contract, capture_launch = (
            _preverify_capture_contract_and_launch(
                phase_name,
                config,
                generation_name=generation_name,
                generation_digest=generation_digest,
                exact_inputs=capture_plan.exact_inputs,
            )
        )
        capture_execute, capture_arm_issues = (
            _arm_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=capture_contract,
                launch=capture_launch,
                run_id=run_id,
            )
        )
        if capture_arm_issues:
            return list(dict.fromkeys(capture_arm_issues))
        capture_authority_issues = (
            _preverify_capture_input_authority_issues(
                root,
                capture_contract,
                run_id=run_id,
            )
        )
        if capture_authority_issues:
            return capture_authority_issues
        if capture_execute:
            (
                after_arm_plan,
                after_arm_final,
                after_arm_delivery,
                after_arm_name,
                after_arm_generation,
            ) = _recompute_generation()
            validate_preverify_capture_plan(
                root,
                capture_plan,
                expected_plan=after_arm_plan,
            )
            if (
                after_arm_name != generation_name
                or after_arm_generation != generation_payload
            ):
                return [
                    "preverify capture producer/control denominator drifted "
                    "after arm; generation was not published"
                ]
            capture_input_issues = validate_work_unit_inputs(
                root,
                project_root,
                capture_contract,
                capture_launch,
                run_id=run_id,
            )
            if capture_input_issues:
                return list(dict.fromkeys(capture_input_issues))
            final_payload = after_arm_final
            registered_payload = after_arm_delivery
            generation_payload = after_arm_generation
            _atomic_driver_bytes(
                root / generation_name,
                encode_successor_payload(generation_payload),
            )
            (
                before_commit_plan,
                _before_commit_final,
                _before_commit_delivery,
                before_commit_name,
                before_commit_generation,
            ) = _recompute_generation()
            validate_preverify_capture_plan(
                root,
                capture_plan,
                expected_plan=before_commit_plan,
            )
            if (
                before_commit_name != generation_name
                or before_commit_generation != generation_payload
            ):
                return [
                    "preverify capture producer/control denominator drifted "
                    "before commit; generation bytes preserved as debt"
                ]
            capture_domain_issues: list[str] = []
            try:
                validate_successor_generation_payload(
                    root,
                    payload=generation_payload,
                    artifact_name=generation_name,
                    expected_capture_plan=before_commit_plan,
                )
            except PreverifyInventorySuccessorError as exc:
                capture_domain_issues.append(str(exc))
            capture_commit_issues = _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=capture_contract,
                launch=capture_launch,
                run_id=run_id,
                domain_issues=capture_domain_issues,
            )
            if capture_commit_issues:
                return list(dict.fromkeys(capture_commit_issues))
        try:
            current_generation = json.loads(
                (root / generation_name).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            validate_successor_generation_payload(
                root,
                payload=current_generation,
                artifact_name=generation_name,
                expected_capture_plan=capture_plan,
            )
            captured_final = current_generation.get("final_payload")
            captured_delivery = current_generation.get("delivery_payload")
            if not isinstance(captured_final, Mapping) or not isinstance(
                captured_delivery, Mapping
            ):
                raise PreverifyInventorySuccessorError(
                    "preverify capture has no structural successor payloads"
                )
            final_payload = dict(captured_final)
            registered_payload = dict(captured_delivery)
        except (
            OSError,
            UnicodeError,
            json.JSONDecodeError,
            PreverifyInventorySuccessorError,
        ) as exc:
            return [
                "preverify content-addressed capture validation failed: "
                f"{type(exc).__name__}: {exc}"
            ]
        contract, launch = _preverify_successor_contract_and_launch(
            phase_name,
            root,
            config,
            exact_inputs=(generation_name,),
        )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if arm_issues:
            return list(dict.fromkeys(arm_issues))
        if execute:
            _atomic_driver_bytes(
                root / PREVERIFY_INVENTORY_SUCCESSOR_NAME,
                encode_successor_payload(final_payload),
            )
            _atomic_driver_bytes(
                root / PREVERIFY_DELIVERY_SUCCESSOR_NAME,
                encode_successor_payload(registered_payload),
            )
            domain_issues: list[str] = []
            try:
                validate_preverify_successor_payloads(
                    root,
                    final_payload=final_payload,
                    delivery_payload=registered_payload,
                    run_id=run_id,
                    validate_current_sources=False,
                )
            except PreverifyInventorySuccessorError as exc:
                domain_issues.append(str(exc))
            commit_issues = _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=domain_issues,
            )
            if commit_issues:
                return list(dict.fromkeys(commit_issues))
        try:
            current_final = json.loads(
                (root / PREVERIFY_INVENTORY_SUCCESSOR_NAME).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            current_delivery = json.loads(
                (root / PREVERIFY_DELIVERY_SUCCESSOR_NAME).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            validate_preverify_successor_payloads(
                root,
                final_payload=current_final,
                delivery_payload=current_delivery,
                run_id=run_id,
                validate_current_sources=False,
            )
        except (
            OSError,
            UnicodeError,
            json.JSONDecodeError,
            PreverifyInventorySuccessorError,
        ) as exc:
            return [
                "preverify inventory/delivery successor validation failed: "
                f"{type(exc).__name__}: {exc}"
            ]
        return []
    except (
        ArtifactLedgerError,
        OSError,
        UnicodeError,
        ValueError,
        PreverifyInventorySuccessorError,
    ) as exc:
        return [
            "preverify inventory/delivery successor transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


_VERIFY_QUEUE_OPTIONAL_CONTEXT_INPUTS = (
    "application_skeptic_proposals.md",
    "candidate_negative_skeptic_proposals.md",
    "hypotheses.md",
    "finding_mapping.md",
    "chain_grouping_relations.json",
    "chain_anti_absorption_applied_receipt.json",
    "chain_equivalence_proposals.json",
    "chain_composition_verification_candidates.json",
    "chain_hypotheses.md",
)


def _resolve_verify_queue_optional_context_inputs(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[set[str], list[str]]:
    """Freeze one closed-policy context selection; invalid context is debt."""

    root = Path(scratchpad)
    try:
        ledger = read_artifact_ledger(root)
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        ledger = {}
        ledger_error = f"{type(exc).__name__}: {exc}"
    else:
        ledger_error = ""
    snapshot = capture_verify_queue_context_snapshot(root, ledger)
    selection = select_verify_queue_context(
        snapshot,
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        run_id=str(config.get("_run_id") or "test-unbound"),
    )
    if isinstance(config, dict):
        # Runtime config is also the durable checkpoint config in production.
        # Never place a dataclass instance in that JSON boundary: a crash after
        # T0 must still be able to commit retryable debt.  The deterministic
        # status projection contains the complete selected denominator needed
        # by the routing transaction and is JSON-native.
        config["_verify_queue_context_selection"] = (
            build_verify_queue_context_status(selection)
        )
    issues = [
        (
            f"{issue.artifact}: "
            + ", ".join(issue.codes)
            + (
                " (" + "; ".join(issue.details) + ")"
                if issue.details
                else ""
            )
        )
        for issue in selection.issues
    ]
    if ledger_error:
        issues.insert(0, f"artifact authority unavailable ({ledger_error})")
    return set(selection.accepted_paths), list(dict.fromkeys(issues))


def _typed_verify_queue_routing_contract_and_launch(
    phase_name: str,
    scratchpad: Path,
    config: dict[str, Any],
    *,
    optional_inputs: set[str] | None = None,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the stable queue/shard transaction before any output exists."""

    if phase_name == "verify_queue":
        manifests = L1_VERIFY_SHARD_MANIFESTS
    elif phase_name == "sc_verify_queue":
        manifests = SC_VERIFY_SHARD_MANIFESTS
    else:
        raise ValueError(
            f"unsupported typed verify-queue phase: {phase_name}"
        )

    markdown_paths = {"verification_queue.md", *manifests.values()}
    exact_outputs: set[str] = set()
    for relative in markdown_paths:
        path = Path(relative)
        exact_outputs.update({
            path.as_posix(),
            path.with_suffix(".json").as_posix(),
            path.with_suffix(".work_items.json").as_posix(),
        })
    exact_outputs.add("verification_queue.work_plan.json")
    exact_outputs.update({
        "compound_candidates.json",
        "compound_verification_work_plan.json",
        MANDATORY_REVERIFICATION_DENOMINATOR_FILE,
        MANDATORY_REVERIFICATION_ROUTING_FILE,
        "verification_context_packets.json",
        "verification_methodology_reachability.json",
        "verify_queue_context_input_status.json",
    })
    routing_inputs = {
        "findings_inventory.md",
        PREVERIFY_INVENTORY_SUCCESSOR_NAME,
        PREVERIFY_DELIVERY_SUCCESSOR_NAME,
    }
    selected_optional = optional_inputs
    if selected_optional is None:
        selected_optional, _omitted = (
            _resolve_verify_queue_optional_context_inputs(
                scratchpad, config
            )
        )
    routing_inputs.update(selected_optional)
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase=phase_name,
        work_unit_id="routing",
        exact_inputs=tuple(sorted(routing_inputs)),
        exact_outputs=tuple(sorted(exact_outputs)),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
    )
    return contract, launch


def _arm_typed_verify_queue_routing_artifacts(
    phase_name: str,
    scratchpad: Path,
    config: dict[str, Any],
    *,
    materialize_context_status: bool = True,
) -> tuple[bool, list[str]]:
    """Bind queue inputs and clean output prestates before route generation.

    ``materialize_context_status=False`` is the live T0--T9 pre-arm path.  It
    grants the runtime projection resolver an authenticated routing-consumer
    capability without creating any public output before T9.  Legacy callers
    retain the historical status materialization behavior by default.
    """

    if not isinstance(materialize_context_status, bool):
        return False, ["materialize_context_status must be boolean"]

    run_id = str(config.get("_run_id") or "test-unbound")
    project_root = Path(config.get("project_root") or Path(scratchpad).parent)
    optional_inputs, optional_issues = (
        _resolve_verify_queue_optional_context_inputs(
            Path(scratchpad), config
        )
    )
    selection = config.get("_verify_queue_context_selection")
    try:
        expected_consumer_key = canonical_work_unit_key(
            str(config.get("pipeline") or "sc"),
            str(config.get("mode") or "core"),
            str(config.get("language") or "unknown"),
            str(config.get("cli_backend") or "claude"),
            phase_name,
            "routing",
        )
    except ValueError as exc:
        return False, [
            "queue runtime authority is invalid: "
            f"{type(exc).__name__}: {exc}"
        ]
    successor_issues = _validate_registered_finding_delivery_receipt(
        Path(scratchpad),
        expected_consumer_work_unit_key=expected_consumer_key,
        expected_run_id=run_id,
    )
    if successor_issues:
        return False, [
            "queue refused non-current registered-delivery authority: "
            + issue
            for issue in successor_issues
        ]
    try:
        contract, launch = _typed_verify_queue_routing_contract_and_launch(
            phase_name,
            Path(scratchpad),
            config,
            optional_inputs=optional_inputs,
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=Path(scratchpad),
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if execute and not issues and materialize_context_status:
            if (
                isinstance(selection, Mapping)
                and selection.get("schema_version")
                == "plamen.verify_queue_context_input_status.v1"
            ):
                status = dict(selection)
            else:
                status = {
                    "schema_version": (
                        "plamen.verify_queue_context_input_status.v1"
                    ),
                    "pipeline": str(config.get("pipeline") or "sc"),
                    "mode": str(config.get("mode") or "thorough"),
                    "ecosystem": str(
                        config.get("language") or "unknown"
                    ),
                    "backend": str(
                        config.get("cli_backend") or "claude"
                    ),
                    "run_id": run_id,
                    "state": (
                        "COMPLETED_WITH_DEBT_SAFE_BASE"
                        if optional_issues
                        else "COMMITTED_CLEAN_NOOP"
                    ),
                    "safe_to_consume": True,
                    "safe_base_routing": True,
                    "proof_authority": "NONE",
                    "accepted_artifacts": [
                        {"artifact": name}
                        for name in sorted(optional_inputs)
                    ],
                    "omitted_artifacts": [
                        {"detail": issue}
                        for issue in optional_issues
                    ],
                }
                status["receipt_digest"] = hashlib.sha256(
                    json.dumps(
                        status,
                        ensure_ascii=True,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
            _atomic_driver_json_record(
                Path(scratchpad)
                / "verify_queue_context_input_status.json",
                status,
            )
        # This is an execution-local projection, not resume configuration.
        # Its source artifacts and resulting status output carry the durable
        # authority, so retaining it in checkpoint.config would only duplicate
        # a potentially large denominator.
        config.pop("_verify_queue_context_selection", None)
        return execute, list(dict.fromkeys(issues))
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        return False, [str(exc)]


def _record_typed_verify_queue_routing_artifacts(
    phase_name: str,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Commit only a queue transaction that was armed before its outputs."""

    run_id = str(config.get("_run_id") or "test-unbound")
    project_root = Path(config.get("project_root") or Path(scratchpad).parent)
    try:
        ledger = read_artifact_ledger(Path(scratchpad))
        unit_key = "/".join((
            str(config.get("pipeline") or "sc").lower(),
            str(config.get("mode") or "core").lower(),
            str(config.get("language") or "unknown").lower(),
            str(config.get("cli_backend") or "claude").lower(),
            phase_name,
            "routing",
        ))
        unit = ledger.get("work_units", {}).get(unit_key)
        if not isinstance(unit, Mapping):
            return [
                "typed verify-queue routing outputs were not armed before "
                "generation"
            ]
        input_bindings = unit.get("input_bindings")
        if not isinstance(input_bindings, Mapping):
            return [
                "typed verify-queue routing has no frozen input denominator"
            ]
        mandatory = {
            "findings_inventory.md",
            PREVERIFY_INVENTORY_SUCCESSOR_NAME,
            PREVERIFY_DELIVERY_SUCCESSOR_NAME,
        }
        optional_inputs = {
            identity.split(":", 1)[1]
            for identity in input_bindings
            if (
                isinstance(identity, str)
                and identity.startswith("scratchpad:")
                and identity.split(":", 1)[1] not in mandatory
            )
        }
        contract, launch = _typed_verify_queue_routing_contract_and_launch(
            phase_name,
            Path(scratchpad),
            config,
            optional_inputs=optional_inputs,
        )
        if contract.key != unit_key:
            return [
                "typed verify-queue routing frozen work-unit key mismatch"
            ]
        if unit.get("execution_state") == "OUTPUT_COMMITTED":
            issues = validate_work_unit_inputs(
                Path(scratchpad),
                project_root,
                contract,
                launch,
                run_id=run_id,
            )
            issues.extend(validate_work_unit_artifacts(
                Path(scratchpad),
                project_root,
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            ))
            return list(dict.fromkeys(issues))
        domain_issues: list[str] = []
        typed_queue_path = (
            Path(scratchpad) / "verification_queue.work_items.json"
        )
        try:
            typed_root = json.loads(
                typed_queue_path.read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            if not (
                isinstance(typed_root, dict)
                and str(typed_root.get("schema_version") or "").startswith(
                    "plamen.queue_work_items.v"
                )
            ):
                raise ValueError(
                    "typed queue schema is unavailable for method context"
                )
            queue_items = _read_typed_queue_work_items(
                Path(scratchpad) / "verification_queue.md"
            )
            context_payload = build_verification_context_packets(
                rows=[item.to_dict() for item in queue_items],
                scratchpad=Path(scratchpad),
                project_root=project_root,
            )
            write_or_validate_context_packets(
                Path(scratchpad) / "verification_context_packets.json",
                context_payload,
            )
            reachability = validate_methodology_reachability(
                Path(__file__).resolve().parent.parent
            )
            _atomic_driver_json_record(
                Path(scratchpad)
                / "verification_methodology_reachability.json",
                reachability,
            )
            if not reachability.get("ok"):
                domain_issues.append(
                    "verification methodology reachability has "
                    "orphan/dead rules: "
                    + "; ".join(
                        str(item.get("code") or "UNKNOWN")
                        for item in reachability.get("issues", [])
                    )
                )
        except Exception as exc:
            domain_issues.append(
                "verification context/method authority failed: "
                f"{type(exc).__name__}: {exc}"
            )
        return _commit_deterministic_driver_work_unit(
            scratchpad=Path(scratchpad),
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            domain_issues=domain_issues,
        )
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        return [str(exc)]


def _prepare_mandatory_primary_reverification(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Compile and apply NC-5 reopen bypass after ordinary queue filters."""

    root = Path(scratchpad)
    issues: list[str] = []
    try:
        denominator = compile_primary_reopen_denominator(
            root,
            run_id=str(config.get("_run_id") or "test-unbound"),
        )
        write_or_validate_mandatory_artifact(
            root / MANDATORY_REVERIFICATION_DENOMINATOR_FILE,
            denominator,
        )
        routing = apply_primary_reopens_to_queue(root, denominator)
        for debt in denominator.get("input_debts", []):
            issues.append(
                "mandatory reopen source debt "
                f"{debt.get('source_identity')}: {debt.get('reason_code')}: "
                f"{debt.get('detail')}"
            )
        for debt in routing.get("debts", []):
            issues.append(
                "mandatory reopen routing debt "
                f"{debt.get('obligation_id')}: {debt.get('reason_code')}"
            )
    except Exception as exc:
        issues.append(
            "mandatory reopen queue authority failed closed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(issues))


def _reconcile_mandatory_primary_reverification(
    scratchpad: Path,
) -> tuple[dict[str, Any] | None, list[str]]:
    """Bind every reopen once and replay exact verifier completion authority."""

    root = Path(scratchpad)
    denominator_path = root / MANDATORY_REVERIFICATION_DENOMINATOR_FILE
    routing_path = root / MANDATORY_REVERIFICATION_ROUTING_FILE
    if not denominator_path.is_file() and not routing_path.is_file():
        return None, []
    try:
        denominator = validate_mandatory_reverification_denominator(
            json.loads(
                denominator_path.read_text(encoding="utf-8", errors="strict")
            )
        )
        routing = json.loads(
            routing_path.read_text(encoding="utf-8", errors="strict")
        )
        if denominator["candidate_count"] == 0:
            return None, [
                "mandatory reopen source debt remains unresolved: "
                f"{debt.get('source_identity')}: {debt.get('reason_code')}"
                for debt in denominator.get("input_debts", [])
            ]
        assignment = bind_primary_reopen_assignments_from_scratchpad(
            root, denominator, routing
        )
        completion = reconcile_primary_reopen_completion_from_scratchpad(
            root,
            denominator,
            assignment,
            completion_validator=_verifier_completion_authority_issues,
        )
        issues: list[str] = []
        for debt in assignment.get("debts", []):
            issues.append(
                "mandatory reopen assignment debt "
                f"{debt.get('obligation_id')}: {debt.get('reason_code')}"
            )
        for row in completion.get("rows", []):
            if row.get("completion_state") != "EXACTLY_COMPLETED":
                issues.append(
                    "mandatory reopen exact verifier retry required: "
                    f"{row.get('obligation_id')} -> "
                    f"{row.get('assigned_work_item_id') or 'UNASSIGNED'}"
                )
        for debt in denominator.get("input_debts", []):
            issues.append(
                "mandatory reopen source debt remains unresolved: "
                f"{debt.get('source_identity')}: {debt.get('reason_code')}"
            )
        return completion, list(dict.fromkeys(issues))
    except Exception as exc:
        return None, [
            "mandatory reopen completion authority failed closed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _mandatory_recovery_execution_evidence(
    scratchpad: Path,
    denominator: Mapping[str, Any],
) -> tuple[dict[str, dict[str, Any]], list[str]]:
    """Collect only exact compiler-bound MANDATORY_REOPEN executions."""

    root = Path(scratchpad)
    authority = validate_mandatory_reverification_denominator(denominator)
    expected = {
        "MRVW-" + row["obligation_id"][4:]: row
        for row in authority["candidates"]
    }
    evidence: dict[str, dict[str, Any]] = {}
    ambiguous: set[str] = set()
    issues: list[str] = []
    recovery_root = root / "_verification_recovery"
    if not recovery_root.is_dir():
        return {}, [
            "mandatory recovery execution root is absent"
        ] if expected else []
    repo_root = Path(__file__).resolve().parent.parent
    for contract_path in sorted(
        recovery_root.glob("VREC-*/contract.json"),
        key=lambda value: value.as_posix(),
    ):
        try:
            contract = validate_verification_recovery_contract(
                json.loads(
                    contract_path.read_text(encoding="utf-8", errors="strict")
                ),
                repo_root=repo_root,
            )
            if contract["recovery_kind"] != "MANDATORY_REOPEN":
                continue
            if contract["run_id"] != authority["run_id"]:
                raise ValueError("mandatory recovery run identity mismatch")
            directory = contract_path.parent
            launch = VerifierLaunchSpec.from_json(
                (directory / "launch_spec.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            execution = _load_current_verify_recovery_execution_receipt(
                directory / "execution_receipt.json",
                contract=contract,
                launch_spec=launch,
                scratchpad=root,
            )
            unresolved = set(execution["unresolved_work_item_ids"])
            for recovery_row in contract["rows"]:
                work_id = str(recovery_row["work_item_id"])
                candidate = expected.get(work_id)
                if candidate is None:
                    continue
                obligation_id = str(candidate["obligation_id"])
                exact = (
                    recovery_row["source_candidate_digest"]
                    == candidate["candidate_packet_sha256"]
                    and recovery_row["source_work_item_id"]
                    == candidate["candidate_id"]
                    and recovery_row["source_identity"]
                    == candidate["source_candidate_id"]
                    and recovery_row["finding_lifecycle_obligation_id"]
                    == candidate["source_obligation_id"]
                    and recovery_row["mechanism"] == candidate["premise"]
                    and recovery_row["harm"] == candidate["harm"]
                    and recovery_row["evidence"] == candidate["evidence"]
                    and recovery_row["independent_discriminator_required"] is True
                )
                if not exact or work_id in unresolved:
                    issues.append(
                        f"{obligation_id}: mandatory recovery packet is "
                        "unresolved or not exact"
                    )
                    continue
                output_name = f"verify_{work_id}.md"
                receipt_name = f"verify_{work_id}.operator_receipt.json"
                output_sha = execution["output_sha256"].get(output_name)
                receipt_sha = execution["operator_receipt_sha256"].get(
                    receipt_name
                )
                if not output_sha or not receipt_sha:
                    issues.append(
                        f"{obligation_id}: mandatory recovery exact output/"
                        "operator receipt is absent"
                    )
                    continue
                row_evidence = {
                    "obligation_id": obligation_id,
                    "candidate_packet_sha256": candidate[
                        "candidate_packet_sha256"
                    ],
                    "source_obligation_id": candidate["source_obligation_id"],
                    "work_item_id": work_id,
                    "completion_authorized": True,
                    "output_sha256": output_sha,
                    "receipt_sha256": receipt_sha,
                    "contract_digest": contract["contract_digest"],
                    "execution_receipt_digest": execution["receipt_digest"],
                }
                if obligation_id in evidence and evidence[obligation_id] != row_evidence:
                    ambiguous.add(obligation_id)
                    issues.append(
                        f"{obligation_id}: multiple mandatory recovery authorities "
                        "disagree"
                    )
                else:
                    evidence[obligation_id] = row_evidence
        except Exception as exc:
            issues.append(
                "mandatory recovery execution authority failed closed for "
                f"{contract_path.parent.name}: {type(exc).__name__}: {exc}"
            )
    for obligation_id in ambiguous:
        evidence.pop(obligation_id, None)
    return evidence, list(dict.fromkeys(issues))


def _mandatory_public_report_routes(
    scratchpad: Path,
    denominator: Mapping[str, Any],
    *,
    project_root: Path,
) -> dict[str, dict[str, Any]]:
    """Project actual report identities; planned routes are never delivery."""

    root = Path(scratchpad)
    authority = validate_mandatory_reverification_denominator(denominator)
    disposition_path = root / "report_disposition_authority.json"
    bindings = {
        str(row["artifact"]): str(row["sha256"])
        for row in authority["source_bindings"]
    }
    if bindings.get(disposition_path.name) != hashlib.sha256(
        disposition_path.read_bytes()
    ).hexdigest():
        raise ValueError(
            "mandatory public report routes are stale for disposition authority"
        )
    payload = json.loads(
        disposition_path.read_text(
            encoding="utf-8", errors="strict"
        )
    )
    validated = validate_report_disposition_authority(
        root,
        Path(project_root),
        run_id=str(authority["run_id"]),
    )
    if validated != payload:
        raise ValueError(
            "mandatory public report delivery authority changed on replay"
        )
    routes: dict[str, dict[str, Any]] = {}
    for row in payload.get("rows") or []:
        if not isinstance(row, Mapping):
            continue
        candidate_id = str(row.get("candidate_id") or "").strip()
        raw_ids = row.get("report_ids")
        report_ids = sorted({
            str(value).strip()
            for value in raw_ids
            if str(value).strip()
        }) if isinstance(raw_ids, list) else []
        target = str(row.get("public_retention_target") or "").upper()
        state = (
            "DELIVERED_BODY" if target == "BODY" and report_ids
            else "DELIVERED_HUMAN_REVIEW"
            if target == "HUMAN_REVIEW" and report_ids
            else "REPORT_DELIVERY_DEBT"
        )
        if candidate_id:
            routes[candidate_id] = {
                "report_delivery_state": state,
                "public_report_ids": report_ids if state != "REPORT_DELIVERY_DEBT" else [],
            }
    return routes


def _run_mandatory_report_reverification(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Launch/report exact NC-5 recovery without granting disposition authority."""

    root = Path(scratchpad)
    issues: list[str] = []
    try:
        denominator = compile_report_reopen_denominator(
            root,
            run_id=str(config.get("_run_id") or "test-unbound"),
            project_root=Path(config.get("project_root") or root.parent),
        )
        write_or_validate_mandatory_artifact(
            root / MANDATORY_REVERIFICATION_REPORT_DENOMINATOR_FILE,
            denominator,
        )
        rows = mandatory_recovery_rows(denominator)
        if rows:
            recovery_config = dict(config)
            recovery_config["_verification_recovery_kind"] = "MANDATORY_REOPEN"
            unresolved = _run_verify_recovery_shard(
                recovery_config,
                [(str(row["work_item_id"]), row) for row in rows],
            )
            issues.extend(
                f"mandatory report recovery retry required: {work_id}"
                for work_id in unresolved
            )
        evidence, evidence_issues = _mandatory_recovery_execution_evidence(
            root, denominator
        )
        issues.extend(evidence_issues)
        completion = reconcile_mandatory_recovery_completion(
            denominator=denominator,
            recovery_evidence=evidence,
        )
        write_or_advance_mandatory_completion(
            root / MANDATORY_REVERIFICATION_REPORT_COMPLETION_FILE,
            completion,
            denominator=denominator,
        )
        for row in completion["rows"]:
            if row["completion_state"] != "EXACTLY_COMPLETED":
                issues.append(
                    "mandatory report recovery exact completion debt: "
                    f"{row['obligation_id']}"
                )
        for debt in denominator["input_debts"]:
            issues.append(
                "mandatory report recovery source debt "
                f"{debt['source_identity']}: {debt['reason_code']}"
            )
        routes = _mandatory_public_report_routes(
            root,
            denominator,
            project_root=Path(config.get("project_root") or root.parent),
        )
        delivery = reconcile_mandatory_reverification_delivery(
            denominator=denominator,
            completion=completion,
            report_routes=routes,
        )
        write_or_validate_mandatory_delivery(
            root / MANDATORY_REVERIFICATION_REPORT_DELIVERY_FILE,
            delivery,
            denominator=denominator,
        )
        for row in delivery["rows"]:
            if row["report_delivery_state"] == "REPORT_DELIVERY_DEBT":
                issues.append(
                    "mandatory report recovery public delivery debt: "
                    f"{row['obligation_id']}"
                )

        primary_denominator_path = (
            root / MANDATORY_REVERIFICATION_DENOMINATOR_FILE
        )
        if primary_denominator_path.is_file():
            primary_denominator = validate_mandatory_reverification_denominator(
                json.loads(
                    primary_denominator_path.read_text(
                        encoding="utf-8", errors="strict"
                    )
                )
            )
            primary_completion = None
            primary_completion_path = (
                root / MANDATORY_REVERIFICATION_COMPLETION_FILE
            )
            if primary_completion_path.is_file():
                primary_completion = load_mandatory_completion(
                    primary_completion_path,
                    denominator=primary_denominator,
                )
            primary_delivery = reconcile_mandatory_reverification_delivery(
                denominator=primary_denominator,
                completion=primary_completion,
                report_routes=routes,
            )
            write_or_validate_mandatory_delivery(
                root / MANDATORY_REVERIFICATION_DELIVERY_FILE,
                primary_delivery,
                denominator=primary_denominator,
            )
            for row in primary_delivery["rows"]:
                if (
                    row["verification_state"] != "EXACTLY_COMPLETED"
                    or row["report_delivery_state"] == "REPORT_DELIVERY_DEBT"
                ):
                    issues.append(
                        "mandatory primary reopen final accounting debt: "
                        f"{row['obligation_id']}"
                    )
    except Exception as exc:
        issues.append(
            "mandatory report re-verification failed closed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(issues))


def _security_obligation_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    stage: str,
    exact_inputs: Sequence[str] | None = None,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve one exact DRIVER-only P1-C PRE or POST transaction."""
    stage_n = str(stage or "").strip().lower()
    if stage_n not in {
        security_obligation_authority.PRE_DEPTH_STAGE,
        security_obligation_authority.POST_DEPTH_STAGE,
    }:
        raise ValueError(f"unsupported security-obligation stage: {stage!r}")
    inputs = tuple(
        exact_inputs
        if exact_inputs is not None
        else security_obligation_authority.security_obligation_input_artifacts(
            Path(scratchpad), stage=stage_n
        )
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="depth",
        work_unit_id=f"security_obligations.{stage_n}",
        exact_inputs=inputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _security_obligation_source_snapshot_digest(
    config: Mapping[str, Any],
) -> str:
    snapshot = config.get("_audit_snapshot") or config.get("audit_snapshot") or {}
    return (
        str(snapshot.get("snapshot_digest") or "")
        if isinstance(snapshot, Mapping)
        else ""
    )


def _record_security_obligation_phase_io(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    stage: str,
) -> list[str]:
    """Derive and bind P1-C at an exact stable PRE/POST depth boundary.

    Optional inputs are discovered from the authority's single denominator
    API.  A bounded compare-and-swap loop handles a file arriving before any
    DRIVER output is committed; committed denominators remain immutable and
    require the ordinary semantic-invalidation path.
    """
    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["security-obligation PhaseIO cannot bind without a run_id"]
    snapshot_digest = _security_obligation_source_snapshot_digest(config)
    stage_n = str(stage or "").strip().lower()
    if all(
        (root / name).is_file()
        for name in (
            security_obligation_authority.FEATURE_FACT_FILE,
            security_obligation_authority.AUTHORITY_FILE,
            security_obligation_authority.PROJECTION_FILE,
        )
    ):
        resume_issues = _validate_security_obligation_phase_io(
            root, config, stage=stage_n
        )
        if not resume_issues:
            return []
    prior_contract: PhaseIOContract | None = None
    prior_unit: Mapping[str, Any] | None = None
    contract: PhaseIOContract | None = None
    launch: LaunchSpec | None = None
    authority_payload: Mapping[str, Any] | None = None
    stabilized = False
    issues: list[str] = []
    try:
        for _attempt in range(3):
            before = (
                security_obligation_authority.security_obligation_input_artifacts(
                    root, stage=stage_n
                )
            )
            contract, launch = _security_obligation_contract_and_launch(
                root, config, stage=stage_n, exact_inputs=before
            )
            if prior_contract is not None and prior_unit is not None:
                bound_unit = replace_uncommitted_driver_input_denominator(
                    root,
                    project_root,
                    prior_contract,
                    contract,
                    launch,
                    run_id=run_id,
                    expected_prior_input_set_digest=str(
                        prior_unit.get("input_set_digest") or ""
                    ),
                    reason_code=(
                        "DYNAMIC_INPUT_DENOMINATOR_DRIFT_BEFORE_OUTPUT_COMMIT"
                    ),
                )
            else:
                existing = read_artifact_ledger(root).get("work_units", {}).get(
                    contract.key
                )
                if (
                    isinstance(existing, Mapping)
                    and existing.get("semantic_status") == "INPUTS_BOUND"
                    and existing.get("execution_state")
                    == "INPUTS_BOUND_PREEXECUTION"
                    and existing.get("artifacts") == {}
                    and existing.get("contract_digest") == contract.digest
                    and existing.get("contract_manifest") == contract.to_dict()
                    and existing.get("launch_digest") == launch.digest
                    and existing.get("launch_manifest") == launch.to_dict()
                ):
                    # Crash recovery after durable output publication but
                    # before artifact commit must preserve the original
                    # pre-execution output prestates. Re-arming the same unit
                    # here would observe its own crash-persisted outputs as
                    # unowned pre-existing bytes and manufacture INPUT_DEBT.
                    bound_unit = dict(existing)
                elif (
                    isinstance(existing, Mapping)
                    and existing.get("semantic_status") == "INPUTS_BOUND"
                    and existing.get("artifacts") == {}
                    and existing.get("contract_digest") != contract.digest
                ):
                    bound_unit = recover_uncommitted_driver_input_denominator(
                        root,
                        project_root,
                        contract,
                        launch,
                        run_id=run_id,
                        reason_code=(
                            "DYNAMIC_INPUT_DENOMINATOR_DRIFT_BEFORE_OUTPUT_COMMIT"
                        ),
                    )
                else:
                    bound_unit = record_work_unit_inputs(
                        root,
                        project_root,
                        contract,
                        launch,
                        run_id=run_id,
                    )

            authority_payload = (
                security_obligation_authority.write_security_obligation_authority(
                root,
                mode=str(config.get("mode") or "core"),
                ecosystem=str(config.get("language") or "unknown"),
                run_id=run_id,
                source_snapshot_digest=snapshot_digest,
                stage=stage_n,
                )
            )
            after = (
                security_obligation_authority.security_obligation_input_artifacts(
                    root, stage=stage_n
                )
            )
            if after == before:
                stabilized = True
                break
            prior_contract = contract
            prior_unit = bound_unit
        if not stabilized or contract is None or launch is None:
            return [
                "security-obligation inputs did not stabilize before output commit"
            ]
        issues.extend(validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        ))
        issues.extend(
            security_obligation_authority.validate_security_obligation_authority(
                root,
                mode=str(config.get("mode") or "core"),
                ecosystem=str(config.get("language") or "unknown"),
                run_id=run_id,
                source_snapshot_digest=snapshot_digest,
                stage=stage_n,
            )
        )
        if isinstance(authority_payload, Mapping):
            for authority_issue in authority_payload.get("issues") or []:
                if str(authority_issue).strip():
                    issues.append(
                        "security-obligation authority debt: "
                        + str(authority_issue).strip()
                    )
        record_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        issues.append(
            "security-obligation PhaseIO transaction failed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))


def _validate_security_obligation_phase_io(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    stage: str,
) -> list[str]:
    """Side-effect-free exact P1-C authority and PhaseIO resume check."""
    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["security-obligation PhaseIO cannot validate without a run_id"]
    snapshot_digest = _security_obligation_source_snapshot_digest(config)
    stage_n = str(stage or "").strip().lower()
    issues: list[str] = []
    try:
        contract, launch = _security_obligation_contract_and_launch(
            root, config, stage=stage_n
        )
        issues.extend(
            security_obligation_authority.validate_security_obligation_authority(
                root,
                mode=str(config.get("mode") or "core"),
                ecosystem=str(config.get("language") or "unknown"),
                run_id=run_id,
                source_snapshot_digest=snapshot_digest,
                stage=stage_n,
            )
        )
        issues.extend(validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        ))
        issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        issues.append(
            "security-obligation PhaseIO validation failed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))


def _security_obligation_lifecycle_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    exact_inputs: Sequence[str] | None = None,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the final DRIVER-owned exact alias lifecycle transaction."""

    inputs = tuple(
        exact_inputs
        if exact_inputs is not None
        else security_obligation_lifecycle
        .security_obligation_lifecycle_input_artifacts(Path(scratchpad))
    )
    outputs = (
        security_obligation_lifecycle.AUTHORITY_FILE,
        security_obligation_lifecycle.PROJECTION_FILE,
        security_obligation_lifecycle.REPORT_RETENTION_FILE,
    )
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="report_index",
        work_unit_id="security_obligation_lifecycle.final",
        exact_inputs=inputs,
        exact_outputs=outputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _record_security_obligation_lifecycle_phase_io(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Publish the final post-verifier lifecycle before report indexing.

    This boundary is haltless: malformed/missing inputs become typed lifecycle
    debt and non-authorized aliases remain in the dedicated report-retention
    projection. No row is deleted and no negative/severity authority is added.
    """

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["security-obligation lifecycle cannot bind without a run_id"]
    if all(
        (root / name).is_file()
        for name in (
            security_obligation_lifecycle.AUTHORITY_FILE,
            security_obligation_lifecycle.PROJECTION_FILE,
            security_obligation_lifecycle.REPORT_RETENTION_FILE,
        )
    ):
        resume_issues = _validate_security_obligation_lifecycle_phase_io(
            root, config
        )
        if not resume_issues:
            return []
    prior_contract: PhaseIOContract | None = None
    prior_unit: Mapping[str, Any] | None = None
    contract: PhaseIOContract | None = None
    launch: LaunchSpec | None = None
    authority: Mapping[str, Any] | None = None
    stabilized = False
    issues: list[str] = []
    try:
        for _attempt in range(3):
            before = (
                security_obligation_lifecycle
                .security_obligation_lifecycle_input_artifacts(root)
            )
            contract, launch = _security_obligation_lifecycle_contract_and_launch(
                root, config, exact_inputs=before
            )
            if prior_contract is not None and prior_unit is not None:
                bound_unit = replace_uncommitted_driver_input_denominator(
                    root,
                    project_root,
                    prior_contract,
                    contract,
                    launch,
                    run_id=run_id,
                    expected_prior_input_set_digest=str(
                        prior_unit.get("input_set_digest") or ""
                    ),
                    reason_code=(
                        "DYNAMIC_INPUT_DENOMINATOR_DRIFT_BEFORE_OUTPUT_COMMIT"
                    ),
                )
            else:
                existing = read_artifact_ledger(root).get("work_units", {}).get(
                    contract.key
                )
                if (
                    isinstance(existing, Mapping)
                    and existing.get("semantic_status") == "INPUTS_BOUND"
                    and existing.get("execution_state")
                    == "INPUTS_BOUND_PREEXECUTION"
                    and existing.get("artifacts") == {}
                    and existing.get("contract_digest") == contract.digest
                    and existing.get("contract_manifest") == contract.to_dict()
                    and existing.get("launch_digest") == launch.digest
                    and existing.get("launch_manifest") == launch.to_dict()
                ):
                    # Resume the exact pre-execution receipt that authorized
                    # the already-published bytes. Rebinding after the crash
                    # would observe those bytes as unowned output prestates.
                    bound_unit = dict(existing)
                elif (
                    isinstance(existing, Mapping)
                    and existing.get("semantic_status") == "INPUTS_BOUND"
                    and existing.get("artifacts") == {}
                    and existing.get("contract_digest") != contract.digest
                ):
                    bound_unit = recover_uncommitted_driver_input_denominator(
                        root,
                        project_root,
                        contract,
                        launch,
                        run_id=run_id,
                        reason_code=(
                            "DYNAMIC_INPUT_DENOMINATOR_DRIFT_BEFORE_OUTPUT_COMMIT"
                        ),
                    )
                else:
                    bound_unit = record_work_unit_inputs(
                        root, project_root, contract, launch, run_id=run_id
                    )
            expected_inputs = {
                str(identity).split(":", 1)[1]: str(binding.get("sha256") or "")
                for identity, binding in (
                    bound_unit.get("input_bindings") or {}
                ).items()
                if str(identity).startswith("scratchpad:")
                and isinstance(binding, Mapping)
                and re.fullmatch(r"[0-9a-f]{64}", str(binding.get("sha256") or ""))
            }
            authority = (
                security_obligation_lifecycle
                .write_security_obligation_lifecycle(
                    root, expected_input_sha256=expected_inputs
                )
            )
            after = (
                security_obligation_lifecycle
                .security_obligation_lifecycle_input_artifacts(root)
            )
            live_input_issues = validate_work_unit_inputs(
                root, project_root, contract, launch, run_id=run_id
            )
            binding_drift = any(
                isinstance(binding, Mapping)
                and binding.get("expected_sha256") is not None
                and binding.get("binding_state") != "CURRENT"
                for binding in authority.get("input_bindings") or []
            )
            if after == before and not live_input_issues and not binding_drift:
                stabilized = True
                break
            prior_contract = contract
            prior_unit = bound_unit
        if not stabilized or contract is None or launch is None:
            return [
                "security-obligation lifecycle inputs did not stabilize "
                "before output commit"
            ]
        if not isinstance(authority, Mapping) or authority.get("run_id") != run_id:
            raise ValueError(
                "security-obligation lifecycle run_id differs from driver run_id"
            )
        final_input_issues = validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        )
        if final_input_issues:
            return [
                "security-obligation lifecycle inputs changed before output commit: "
                + "; ".join(final_input_issues)
            ]
        issues.extend(
            security_obligation_lifecycle
            .validate_security_obligation_lifecycle(
                root, expected_input_sha256=expected_inputs
            )
        )
        if authority.get("status") == "DEGRADED_HUMAN_REVIEW":
            issues.append(
                "security-obligation lifecycle retained unresolved/debt aliases "
                "for human review"
            )
        record_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        issues.append(
            "security-obligation lifecycle PhaseIO transaction failed "
            "haltlessly: "
            f"{type(exc).__name__}: {exc}"
        )
        # Best-effort publication still preserves explicit, non-clean debt if
        # the typed ledger itself was unavailable. A filesystem failure remains
        # visible through the report_index degraded sentinel below.
        try:
            security_obligation_lifecycle.write_security_obligation_lifecycle(
                root
            )
        except Exception as fallback_exc:
            issues.append(
                "security-obligation lifecycle fallback publication failed: "
                f"{type(fallback_exc).__name__}: {fallback_exc}"
            )
    return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))


def _validate_security_obligation_lifecycle_phase_io(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Side-effect-free current-input and PhaseIO resume validation."""

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["security-obligation lifecycle cannot validate without a run_id"]
    issues: list[str] = []
    try:
        contract, launch = _security_obligation_lifecycle_contract_and_launch(
            root, config
        )
        unit = read_artifact_ledger(root).get("work_units", {}).get(contract.key)
        expected_inputs = {
            str(identity).split(":", 1)[1]: str(binding.get("sha256") or "")
            for identity, binding in (
                (unit.get("input_bindings") or {})
                if isinstance(unit, Mapping)
                else {}
            ).items()
            if str(identity).startswith("scratchpad:")
            and isinstance(binding, Mapping)
            and re.fullmatch(r"[0-9a-f]{64}", str(binding.get("sha256") or ""))
        }
        issues.extend(
            security_obligation_lifecycle
            .validate_security_obligation_lifecycle(
                root, expected_input_sha256=expected_inputs
            )
        )
        authority_path = root / security_obligation_lifecycle.AUTHORITY_FILE
        recorded_authority = json.loads(
            authority_path.read_text(encoding="utf-8", errors="strict")
        )
        if recorded_authority.get("run_id") != run_id:
            issues.append(
                "security-obligation lifecycle run_id differs from driver run_id"
            )
        issues.extend(validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        ))
        issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        issues.append(
            "security-obligation lifecycle PhaseIO validation failed: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(str(issue) for issue in issues if str(issue)))


def _append_phase_io_debt(
    scratchpad: Path,
    phase_name: str,
    category: str,
    issue: str,
) -> None:
    """Append one stable typed-I/O debt line without erasing prior debt."""
    safe_category = re.sub(r"[^A-Z0-9_]+", "_", category.upper()).strip("_")
    sentinel = Path(scratchpad) / f"{phase_name}.degraded"
    existing = (
        sentinel.read_text(encoding="utf-8", errors="replace")
        if sentinel.exists() else ""
    )
    line = f"[{safe_category or 'PHASE_IO_DEBT'}] {issue}\n"
    if line not in existing:
        _atomic_driver_bytes(sentinel, (existing + line).encode("utf-8"))


class ReconPrepassDispatchBlocked(RuntimeError):
    """Recon model dispatch lacks a current committed prepass producer."""


_RECON_PREPASS_DISPATCH_DEBT = "RECON_PREPASS_DISPATCH_AUTHORITY"


def _record_recon_prepass_dispatch_debt(
    scratchpad: Path, blocked: BaseException,
) -> None:
    detail = re.sub(r"\s+", " ", str(blocked)).strip()[:4096]
    _append_phase_io_debt(
        Path(scratchpad),
        "recon",
        _RECON_PREPASS_DISPATCH_DEBT,
        detail or type(blocked).__name__,
    )


def _clear_recon_prepass_dispatch_debt(scratchpad: Path) -> None:
    """Clear only a superseded startup barrier failure after a valid replay."""

    sentinel = Path(scratchpad) / "recon.degraded"
    if not sentinel.is_file():
        return
    prefix = f"[{_RECON_PREPASS_DISPATCH_DEBT}]"
    lines = sentinel.read_text(
        encoding="utf-8", errors="strict"
    ).splitlines()
    retained = [line for line in lines if not line.startswith(prefix)]
    if retained:
        _atomic_driver_bytes(
            sentinel,
            ("\n".join(retained).rstrip() + "\n").encode("utf-8"),
        )
    else:
        rooted_io.unlink(sentinel)


def _run_recon_prepass_dispatch_barrier(
    config: dict[str, Any],
    scratchpad: Path,
    *,
    run_prepass=None,
    assert_dispatch_authority=None,
) -> tuple[Any, str]:
    """Run/recover prepass and prove its exact owner before model dispatch.

    ``run_recon_prepass`` owns every recoverable successor transition.  An
    exception escaping it is therefore terminal for this invocation.  The
    second call is deliberately independent: a renderer return value is not
    producer authority, and no recon worker may launch until the artifact
    ledger and current capture prove one exact ACTIVE/OUTPUT_COMMITTED owner.
    """

    try:
        if run_prepass is None or assert_dispatch_authority is None:
            from recon_prepass import (
                assert_recon_prepass_dispatch_authority as default_assert,
                run_recon_prepass as default_run,
            )

            run_prepass = run_prepass or default_run
            assert_dispatch_authority = (
                assert_dispatch_authority or default_assert
            )
        from recon_prepass import recon_prepass_expected_owner_prefix

        status = run_prepass(config)
        owner_key = assert_dispatch_authority(config)
        expected_prefix = recon_prepass_expected_owner_prefix(config) + "/"
        if (
            not isinstance(owner_key, str)
            or not owner_key.startswith(expected_prefix)
            or len(owner_key.split("/")) != 6
            or re.fullmatch(
                r"prepass(?:\.attempt-(?:000[2-9]|00[1-9][0-9]|0[1-9][0-9]{2}|[1-9][0-9]{3}))?",
                owner_key.rsplit("/", 1)[-1],
            ) is None
        ):
            raise ReconPrepassDispatchBlocked(
                "prepass authority verifier returned an invalid owner key"
            )
        _clear_recon_prepass_dispatch_debt(Path(scratchpad))
        config["_recon_prepass_dispatch_owner_key"] = owner_key
        return status, owner_key
    except Exception as exc:
        if isinstance(exc, ReconPrepassDispatchBlocked):
            blocked = exc
        else:
            blocked = ReconPrepassDispatchBlocked(
                "recon prepass dispatch authority failed: "
                f"{type(exc).__name__}: {exc}"
            )
        try:
            _record_recon_prepass_dispatch_debt(Path(scratchpad), blocked)
        except Exception as debt_exc:
            raise ReconPrepassDispatchBlocked(
                f"{blocked}; durable failure projection failed: "
                f"{type(debt_exc).__name__}: {debt_exc}"
            ) from exc
        if blocked is exc:
            raise
        raise blocked from exc


def _assert_current_recon_prepass_dispatch_authority(
    config: Mapping[str, Any],
    *,
    assert_dispatch_authority=None,
) -> str:
    """Recheck the startup admission immediately before a recon model spawn."""

    if assert_dispatch_authority is None:
        from recon_prepass import assert_recon_prepass_dispatch_authority

        assert_dispatch_authority = assert_recon_prepass_dispatch_authority
    expected = config.get("_recon_prepass_dispatch_owner_key")
    if not isinstance(expected, str) or not expected:
        raise ReconPrepassDispatchBlocked(
            "recon prepass startup dispatch authority is absent"
        )
    current = assert_dispatch_authority(config)
    if current != expected:
        raise ReconPrepassDispatchBlocked(
            "recon prepass dispatch owner changed after startup admission"
        )
    return expected


def _enforce_recon_model_prelaunch_barrier(
    config: Mapping[str, Any],
    scratchpad: Path,
    *,
    assert_dispatch_authority=None,
) -> str:
    """Persist a typed veto and raise before any recon provider subprocess."""

    try:
        return _assert_current_recon_prepass_dispatch_authority(
            config,
            assert_dispatch_authority=assert_dispatch_authority,
        )
    except Exception as exc:
        blocked = (
            exc
            if isinstance(exc, ReconPrepassDispatchBlocked)
            else ReconPrepassDispatchBlocked(
                "recon prepass prelaunch authority failed: "
                f"{type(exc).__name__}: {exc}"
            )
        )
        try:
            _record_recon_prepass_dispatch_debt(Path(scratchpad), blocked)
        except Exception as debt_exc:
            raise ReconPrepassDispatchBlocked(
                f"{blocked}; durable failure projection failed: "
                f"{type(debt_exc).__name__}: {debt_exc}"
            ) from exc
        if blocked is exc:
            raise
        raise blocked from exc


_RECON_DIRECT_RETRY_DISPATCH_AUTHORITY_KEY = (
    "_recon_direct_retry_dispatch_authority"
)


def _enforce_recon_current_dispatch_authority(
    config: Mapping[str, Any],
    scratchpad: Path,
    *,
    direct_retry_authority: Mapping[str, Any] | None = None,
) -> None:
    """Recheck the exact current recon generation without launching it."""

    bound_direct = direct_retry_authority
    if bound_direct is None:
        runtime_direct = config.get(
            _RECON_DIRECT_RETRY_DISPATCH_AUTHORITY_KEY
        )
        if isinstance(runtime_direct, Mapping):
            bound_direct = runtime_direct
    if bound_direct is None:
        _enforce_recon_model_prelaunch_barrier(config, Path(scratchpad))
    else:
        try:
            current = validate_recon_direct_retry_launch_authority(
                Path(scratchpad), dict(config)
            )
            if dict(current) != dict(bound_direct):
                raise ReconPrepassDispatchBlocked(
                    "recon direct-retry authority changed before provider "
                    "dispatch"
                )
        except Exception as exc:
            blocked = (
                exc
                if isinstance(exc, ReconPrepassDispatchBlocked)
                else ReconPrepassDispatchBlocked(
                    "recon direct-retry prelaunch authority failed: "
                    f"{type(exc).__name__}: {exc}"
                )
            )
            try:
                _record_recon_prepass_dispatch_debt(
                    Path(scratchpad), blocked
                )
            except Exception as debt_exc:
                raise ReconPrepassDispatchBlocked(
                    f"{blocked}; durable failure projection failed: "
                    f"{type(debt_exc).__name__}: {debt_exc}"
                ) from exc
            if blocked is exc:
                raise
            raise blocked from exc


def _call_recon_provider_with_dispatch_authority(
    config: Mapping[str, Any],
    scratchpad: Path,
    provider_call: Callable[[], Any],
    *,
    direct_retry_authority: Mapping[str, Any] | None = None,
) -> Any:
    """Recheck the exact current recon generation at provider spawn."""

    _enforce_recon_current_dispatch_authority(
        config,
        Path(scratchpad),
        direct_retry_authority=direct_retry_authority,
    )
    return provider_call()


_PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_ID = (
    "PROGRAM-FACTS-STAGE2-EMIT-ONLY"
)
_PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_PATH = (
    "_program_facts_stage2_runtime_debt.json"
)


def _record_program_facts_stage2_runtime_debt(
    scratchpad: Path,
    checkpoint: Checkpoint,
    issue: str,
) -> str:
    """Persist phase-independent PF debt before haltless continuation."""

    run_id = str(checkpoint.run_id or "")
    message = str(issue).strip()
    if not run_id or not message:
        raise RuntimeError(
            "Program Facts runtime debt requires run and issue authority"
        )
    if len(message) > 16_384:
        message = message[:16_384]
    payload = {
        "schema_version": "plamen.program_facts_stage2_runtime_debt.v1",
        "run_id": run_id,
        "debt_id": _PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_ID,
        "issue": message,
        "consumer_activation": False,
    }
    raw = (
        json.dumps(
            payload,
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        + "\n"
    ).encode("utf-8")
    receipt_path = (
        Path(scratchpad) / _PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_PATH
    )
    _atomic_driver_bytes(receipt_path, raw)
    replay = rooted_io.read_bytes(
        receipt_path,
        label="Program Facts Stage-2 runtime debt receipt",
        require_single_link=True,
    )
    if replay != raw:
        raise RuntimeError(
            "Program Facts runtime debt receipt failed exact replay"
        )
    receipt_sha256 = hashlib.sha256(raw).hexdigest()
    checkpoint.record_runtime_debt(
        _PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_ID,
        receipt_sha256,
    )
    checkpoint.save(Path(scratchpad))
    return receipt_sha256


def _clear_program_facts_stage2_runtime_debt(
    scratchpad: Path,
    checkpoint: Checkpoint,
) -> bool:
    """Compare-and-clear a prior PF failure only after a valid publication."""

    receipt_path = (
        Path(scratchpad) / _PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_PATH
    )
    prior = checkpoint.runtime_debts.get(
        _PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_ID
    )
    if prior is None:
        if rooted_io.lexists(receipt_path):
            _durable_driver_unlink(receipt_path)
        return False
    raw = rooted_io.read_bytes(
        receipt_path,
        label="Program Facts Stage-2 runtime debt clearance receipt",
        require_single_link=True,
    )
    if hashlib.sha256(raw).hexdigest() != prior:
        raise RuntimeError(
            "Program Facts runtime debt receipt differs from checkpoint"
        )
    try:
        payload = json.loads(raw.decode("utf-8", errors="strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError(
            "Program Facts runtime debt receipt is invalid"
        ) from exc
    if (
        not isinstance(payload, dict)
        or payload.get("schema_version")
        != "plamen.program_facts_stage2_runtime_debt.v1"
        or payload.get("run_id") != checkpoint.run_id
        or payload.get("debt_id")
        != _PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_ID
        or payload.get("consumer_activation") is not False
    ):
        raise RuntimeError(
            "Program Facts runtime debt receipt authority mismatch"
        )
    if not checkpoint.clear_runtime_debt(
        _PROGRAM_FACTS_STAGE2_RUNTIME_DEBT_ID,
        prior,
    ):
        raise RuntimeError(
            "Program Facts runtime debt compare-and-clear failed"
        )
    checkpoint.save(Path(scratchpad))
    _durable_driver_unlink(receipt_path)
    return True


def _set_chain_grouping_driver_debt(
    scratchpad: Path,
    category: str,
    issues: Sequence[str],
) -> None:
    """Set one idempotent P0-W debt section without replacing relation debt.

    ``chain_grouping_authority`` owns the equivalence-decision table in this
    file.  The driver may additionally need to expose validator, repair, or
    PhaseIO failures.  Category-scoped markers let a later successful recheck
    clear only the superseded driver debt while preserving the relation table
    and any other unresolved failure class.
    """
    safe_category = re.sub(r"[^A-Z0-9_]+", "_", category.upper()).strip("_")
    safe_category = safe_category or "UNRESOLVED"
    start = f"<!-- P0-W DRIVER-DEBT {safe_category} START -->"
    end = f"<!-- P0-W DRIVER-DEBT {safe_category} END -->"
    path = Path(scratchpad) / "chain_grouping_debt.md"
    try:
        existing = (
            path.read_text(encoding="utf-8", errors="replace")
            if path.is_file() else ""
        )
    except OSError:
        existing = ""

    pattern = re.compile(
        re.escape(start) + r".*?" + re.escape(end) + r"\n?",
        re.DOTALL,
    )
    retained = pattern.sub("", existing).rstrip()
    normalized = sorted({
        re.sub(r"\s+", " ", str(issue)).strip()
        for issue in issues
        if str(issue).strip()
    })
    if normalized:
        block_lines = [
            start,
            f"## Driver debt: {safe_category}",
            "",
            "The relation-only repair could not establish a clean applied "
            "boundary for this condition. Original group cards remain "
            "composition aliases only; every base member remains independently "
            "addressable and requires per-member verification evidence.",
            "",
            *[f"- {issue}" for issue in normalized],
            end,
        ]
        updated = ((retained + "\n\n") if retained else "") + "\n".join(block_lines) + "\n"
    elif retained:
        updated = retained + "\n"
    else:
        # Do not manufacture an empty debt artifact on a clean no-group run.
        return
    if updated != existing:
        _atomic_driver_bytes(path, updated.encode("utf-8"))


def _clear_skill_authority_debt(
    scratchpad: Path, phase_name: str,
) -> None:
    """Remove only superseded skill-authority debt from a phase sentinel."""
    sentinel = Path(scratchpad) / f"{phase_name}.degraded"
    if not sentinel.is_file():
        return
    try:
        lines = sentinel.read_text(
            encoding="utf-8", errors="replace"
        ).splitlines()
    except OSError:
        return
    retained = [
        line for line in lines
        if not re.match(
            r"^\[SKILL_(?:SELECTION|CONSUMER|AUTHORITY|PHASE_IO)[A-Z0-9_]*\]",
            line,
        )
    ]
    if retained:
        _atomic_driver_bytes(
            sentinel, ("\n".join(retained).rstrip() + "\n").encode("utf-8")
        )
    else:
        try:
            sentinel.unlink()
        except OSError:
            pass


def _skill_authority_contract_and_launch(
    scratchpad: Path,
    config: dict[str, Any],
    *,
    phase_name: str,
    work_unit_id: str,
    exact_inputs: tuple[str, ...] = (),
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve one deterministic skill-authority producer."""
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase=phase_name,
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _record_skill_authority_phase_io(
    scratchpad: Path,
    config: dict[str, Any],
    *,
    phase_name: str,
    work_unit_id: str,
    exact_inputs: tuple[str, ...] = (),
    domain_issues: Sequence[str] = (),
) -> list[str]:
    """Commit an already-prebound driver-owned skill-authority producer."""
    contract, launch = _skill_authority_contract_and_launch(
        scratchpad,
        config,
        phase_name=phase_name,
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    project_root = Path(config.get("project_root") or Path(scratchpad).parent)
    return _commit_deterministic_driver_work_unit(
        scratchpad=Path(scratchpad),
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
        domain_issues=domain_issues,
    )


def _materialize_live_skill_selection_boundary(
    scratchpad: Path, config: dict[str, Any],
) -> list[str]:
    """Materialize recon's exact-polarity skill authority, haltlessly.

    A broken producer cannot be called CLEAN, but it also cannot stop the
    audit.  The durable phase debt keeps the run honest while legacy positive
    routes remain available to consumers as a recall-safe fallback.
    """
    if str(config.get("pipeline") or "sc").lower() != "sc":
        return []
    try:
        catalog, plan_issues = _materialize_skill_selection_authority(
            Path(scratchpad),
            language=str(config.get("language") or ""),
            pipeline="sc",
            mode=str(config.get("mode") or "core"),
            backend=str(config.get("cli_backend") or "claude"),
            persist=False,
        )
        source_names = tuple(
            str(row.get("source") or "")
            for row in ((catalog.get("authority") or {}).get("source_digests") or [])
            if str(row.get("source") or "")
            and (Path(scratchpad) / str(row.get("source") or "")).is_file()
        )
        contract, launch = _skill_authority_contract_and_launch(
            Path(scratchpad),
            config,
            phase_name="recon",
            work_unit_id="skill_selection_authority",
            exact_inputs=source_names,
        )
        run_id = str(config.get("_run_id") or "test-unbound")
        project_root = Path(config.get("project_root") or Path(scratchpad).parent)
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=Path(scratchpad),
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        issues = [*plan_issues, *arm_issues]
        if execute:
            _catalog, materialize_issues = _materialize_skill_selection_authority(
                Path(scratchpad),
                language=str(config.get("language") or ""),
                pipeline="sc",
                mode=str(config.get("mode") or "core"),
                backend=str(config.get("cli_backend") or "claude"),
                persist=True,
                planned_catalog=catalog,
            )
            issues.extend(materialize_issues)
            issues.extend(_commit_deterministic_driver_work_unit(
                scratchpad=Path(scratchpad),
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=issues,
            ))
    except Exception as exc:
        issues = [
            "skill selection authority materialization failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    issues = sorted(set(str(issue) for issue in issues if str(issue)))
    if issues:
        for issue in issues:
            _append_phase_io_debt(
                Path(scratchpad), "recon", "SKILL_SELECTION_AUTHORITY_DEBT", issue
            )
    else:
        _clear_skill_authority_debt(Path(scratchpad), "recon")
    return issues


def _materialize_live_skill_consumer_boundary(
    scratchpad: Path, config: dict[str, Any],
) -> list[str]:
    """Materialize exact selected-to-scheduled consumer closure, haltlessly."""
    if str(config.get("pipeline") or "sc").lower() != "sc":
        return []
    try:
        catalog_path = Path(scratchpad) / "skill_selection_catalog.json"
        catalog, catalog_read_issues = _read_skill_authority_artifact(catalog_path)
        coverage, plan_issues = _materialize_skill_consumer_authority(
            Path(scratchpad),
            language=str(config.get("language") or ""),
            pipeline="sc",
            mode=str(config.get("mode") or "core"),
            backend=str(config.get("cli_backend") or "claude"),
            persist=False,
            selection_catalog=catalog,
        )
        contract, launch = _skill_authority_contract_and_launch(
            Path(scratchpad),
            config,
            phase_name="instantiate",
            work_unit_id="skill_consumer_authority",
        )
        run_id = str(config.get("_run_id") or "test-unbound")
        project_root = Path(config.get("project_root") or Path(scratchpad).parent)
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=Path(scratchpad),
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        issues = [
            *catalog_read_issues,
            *plan_issues,
            *arm_issues,
        ]
        if execute:
            _coverage, materialize_issues = _materialize_skill_consumer_authority(
                Path(scratchpad),
                language=str(config.get("language") or ""),
                pipeline="sc",
                mode=str(config.get("mode") or "core"),
                backend=str(config.get("cli_backend") or "claude"),
                persist=True,
                selection_catalog=catalog,
                planned_coverage=coverage,
            )
            issues.extend(materialize_issues)
            issues.extend(_commit_deterministic_driver_work_unit(
                scratchpad=Path(scratchpad),
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=issues,
            ))
    except Exception as exc:
        issues = [
            "skill consumer authority materialization failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    issues = sorted(set(str(issue) for issue in issues if str(issue)))
    if issues:
        for issue in issues:
            _append_phase_io_debt(
                Path(scratchpad), "instantiate", "SKILL_CONSUMER_AUTHORITY_DEBT", issue
            )
    else:
        _clear_skill_authority_debt(Path(scratchpad), "instantiate")
    return issues


def _project_report_index_status_with_debt(scratchpad: Path) -> list[str]:
    """Apply the derived status projection and persist any typed debt.

    This is deliberately a report-index projection only.  It never writes a
    verifier or source artifact.  Authority degradation is haltless but cannot
    clean-complete: the canonical receipt keeps the conservative status while
    the phase sentinel feeds the typed commit controller.
    """
    try:
        _project_report_index_status_authority(Path(scratchpad))
    except Exception as exc:
        issue = (
            "report index status projection failed: "
            f"{type(exc).__name__}: {exc}"
        )
        _append_phase_io_debt(
            Path(scratchpad), "report_index",
            "REPORT_INDEX_STATUS_AUTHORITY_DEBT", issue,
        )
        return [issue]
    validation = _validate_report_index_status_authority(Path(scratchpad))
    debt = _report_index_status_projection_debt(Path(scratchpad))
    for issue in debt:
        _append_phase_io_debt(
            Path(scratchpad), "report_index",
            "REPORT_INDEX_STATUS_AUTHORITY_DEBT", issue,
        )
    return validation


def _resolved_phase_contract_digest(phase: Phase, config: dict) -> str:
    """Digest the executable portion of the legacy phase contract.

    This is the migration bridge for P0-AE.  The complete PhaseIOContract
    compiler will replace the remaining hand-maintained lists, but commits are
    bound to the phase/mode/backend contract immediately rather than recording
    an unqualified `completed` bit.
    """
    return _stable_payload_digest({
        "pipeline": config.get("pipeline", ""),
        "mode": config.get("mode", ""),
        "language": config.get("language", ""),
        "backend": config.get("cli_backend", "claude"),
        "phase": phase.name,
        "expected_artifacts": list(phase.expected_artifacts),
        "any_of": [list(group) for group in getattr(phase, "any_of", [])],
        "min_artifact_bytes": phase.min_artifact_bytes,
        "min_artifacts_count": phase.min_artifacts_count,
        "appends_existing_artifact": bool(
            getattr(phase, "appends_existing_artifact", False)
        ),
        # A producer registration changes identity/delivery/containment/resume
        # semantics even when the legacy phase declaration itself is unchanged.
        "finding_producer_registry_digest": _finding_producer_registry_digest(),
    })


def _resolved_phase_input_digest(phase: Phase, config: dict) -> str:
    """Transitional input binding until PhaseIOContract supplies exact inputs."""
    snapshot = config.get("_audit_snapshot") or config.get("audit_snapshot") or {}
    return _stable_payload_digest({
        "phase": phase.name,
        "pipeline": config.get("pipeline", ""),
        "mode": config.get("mode", ""),
        "language": config.get("language", ""),
        "backend": config.get("cli_backend", "claude"),
        "audit_snapshot": snapshot,
    })


def _resolved_phase_launch_digest(phase: Phase, config: dict) -> str:
    return _stable_payload_digest({
        "backend": config.get("cli_backend", "claude"),
        "model": phase_model(phase, config.get("mode", "core"), config),
        "timeout_s": phase.base_timeout_s,
        "pipeline": config.get("pipeline", ""),
        "mode": config.get("mode", ""),
        "language": config.get("language", ""),
        "phase": phase.name,
    })


def _resolved_phase_artifact_digest(
    phase: Phase, scratchpad: Path, project_root: str,
) -> str:
    """Hash every currently materialized output named by the phase contract."""
    patterns = list(phase.expected_artifacts)
    for group in getattr(phase, "any_of", []):
        patterns.extend(group)
    patterns.extend(_registered_producer_patterns(
        "resume_hashing", owner_phase=phase.name
    ))
    patterns = list(dict.fromkeys(patterns))
    rows: list[dict[str, object]] = []
    roots = (Path(scratchpad), Path(project_root))
    seen: set[Path] = set()
    for root in roots:
        for pattern in patterns:
            for candidate in sorted(root.glob(pattern)):
                try:
                    resolved = candidate.resolve()
                    if resolved in seen or not candidate.is_file():
                        continue
                    seen.add(resolved)
                    data = candidate.read_bytes()
                    rows.append({
                        "path": str(candidate.relative_to(root)).replace("\\", "/"),
                        "root": "scratchpad" if root == Path(scratchpad) else "project",
                        "size": len(data),
                        "sha256": hashlib.sha256(data).hexdigest(),
                    })
                except Exception as exc:
                    rows.append({
                        "path": str(candidate),
                        "error": type(exc).__name__,
                    })
    return _stable_payload_digest(rows)


_LEGACY_GATE_REGISTRY: tuple[tuple[re.Pattern[str], str, str], ...] = (
    (re.compile(
        r"CHAIN_ITER2_COVERAGE_GAPS|DEGRADED_COVERAGE_GAPS|"
        r"tail pair dispositions?|overflow pairs?", re.I
     ), "methodology_application.tail_pair_disposition",
     "METHODOLOGY_APPLICATION"),
    (re.compile(r"containment|foreign|rogue", re.I),
     "containment.write_set", "CONTAINMENT"),
    (re.compile(r"collision|id[- ]ledger|redefined|anti[- ]absorption", re.I),
     "semantic_identity.id_ledger", "SEMANTIC_IDENTITY"),
    (re.compile(r"binding manifest|skill[- ]selection|recommendation parity", re.I),
     "methodology_selection.binding_manifest", "METHODOLOGY_SELECTION"),
    (re.compile(
        r"methodology application|application parity|dispatch parity|"
        r"selected[- ]skill.*consumer|consumer application", re.I
     ), "methodology_application.consumer_parity", "METHODOLOGY_APPLICATION"),
    (re.compile(r"poc|proof|evidence integrity|execution result", re.I),
     "evidence_integrity.execution", "EVIDENCE_INTEGRITY"),
    (re.compile(r"disposition|skeptic|judge|independent adjudication", re.I),
     "independent_disposition.coverage", "INDEPENDENT_DISPOSITION"),
    (re.compile(r"promotion dropout|coverage accounting|delivered|report_index", re.I),
     "delivered_projection.completeness", "DELIVERED_PROJECTION"),
    (re.compile(r"schema|malformed|structure|parseable|format", re.I),
     "schema.output_contract", "SCHEMA"),
    (re.compile(r"missing|absent|stub|too small|empty", re.I),
     "artifact_presence.required_output", "ARTIFACT_PRESENCE"),
)


def _registered_gate_identity(issue: str) -> tuple[str, str]:
    """Map legacy prose to a stable migration gate, never a message hash.

    New validators must emit GateFailure directly.  The fallback is a loud,
    non-advisory untyped validator debt so unknown prose cannot become a clean
    or low-priority result.
    """
    for pattern, gate_suffix, gate_class in _LEGACY_GATE_REGISTRY:
        if pattern.search(str(issue)):
            return gate_suffix, gate_class
    return "legacy_validator.untyped", "SCHEMA"


def _fallback_for_gate_class(gate_class: str) -> str:
    if gate_class == "REPORT_INTEGRITY":
        return (
            "Quarantine the non-authoritative report. Do not deliver it or "
            "create a timestamped report snapshot until the exact projection "
            "and ownership predicates validate."
        )
    if gate_class == "SEMANTIC_IDENTITY":
        return (
            "Preserve every conflicting version and route the identity family "
            "to repair/human review; downstream may consume only unaffected IDs."
        )
    if gate_class == "CONTAINMENT":
        return (
            "No semantic consumption is authorized; foreign writes must remain "
            "quarantined and the phase boundary requires repair."
        )
    if gate_class in {"METHODOLOGY_SELECTION", "METHODOLOGY_APPLICATION"}:
        return (
            "Content may feed downstream discovery, but it is not proof that "
            "the selected methodology was assigned or applied."
        )
    if gate_class == "EVIDENCE_INTEGRITY":
        return (
            "Retain the claim as unproven/human-review visible; do not grant a "
            "proof-grade verdict from the failed evidence predicate."
        )
    if gate_class == "INDEPENDENT_DISPOSITION":
        return (
            "Retain all candidate branches without a terminal disposition and "
            "route them to independent review."
        )
    if gate_class == "DELIVERED_PROJECTION":
        return (
            "Preserve missing identities in the assurance/human-review "
            "projection; do not treat the client report as complete."
        )
    return (
        "Downstream may consume structurally usable output while this exact "
        "non-advisory predicate remains unresolved."
    )


def _fallback_policy_for_gate_class(gate_class: str) -> str:
    return {
        "SEMANTIC_IDENTITY": "BLOCK_AS_AUTHORITY",
        "CONTAINMENT": "BLOCK_AS_AUTHORITY",
        "METHODOLOGY_SELECTION": "CONSUME_WITH_DEBT",
        "METHODOLOGY_APPLICATION": "CONSUME_WITH_DEBT",
        "EVIDENCE_INTEGRITY": "UNPROVEN_ONLY",
        "INDEPENDENT_DISPOSITION": "RETAIN_UNDISPOSED",
        "DELIVERED_PROJECTION": "HUMAN_REVIEW_DELIVERY",
        "ARTIFACT_PRESENCE": "CONSUME_WITH_DEBT",
        "SCHEMA": "CONSUME_WITH_DEBT",
        "ADVISORY_QUALITY": "CONSUME_WITH_DEBT",
        "REPORT_INTEGRITY": "NO_SHIP_QUARANTINE",
    }[gate_class]


def _gate_failures_from_issues(
    phase: Phase,
    issues: list[str],
    *,
    contract_digest: str,
    output_digest: str,
    scratchpad: Path,
    allowed_fallback: str = "",
    input_digest: str = "",
) -> tuple[GateFailure, ...]:
    grouped: dict[tuple[str, str], list[str]] = {}
    evidence_paths = []
    for candidate in (
        scratchpad / f"{phase.name}.degraded",
        scratchpad / f"{phase.name}_retry_hint.md",
        scratchpad / "_retry_quarantine" / phase.name,
    ):
        if candidate.exists():
            try:
                evidence_paths.append(str(candidate.relative_to(scratchpad)))
            except ValueError:
                evidence_paths.append(str(candidate))
    for issue in issues or ["phase gate failed without a structured issue"]:
        message = str(issue).strip() or "phase gate failed"
        gate_suffix, gate_class = _registered_gate_identity(message)
        if (
            phase.name == "report_dedup_agent"
            and gate_class in {"ARTIFACT_PRESENCE", "SCHEMA"}
        ):
            gate_suffix = "independent_disposition.candidate_pair_parity"
            gate_class = "INDEPENDENT_DISPOSITION"
        grouped.setdefault((gate_suffix, gate_class), []).append(message)
    failures: list[GateFailure] = []
    for (gate_suffix, gate_class), messages in grouped.items():
        message = " | ".join(dict.fromkeys(messages))
        affected = tuple(sorted(set(re.findall(
            r"\b(?:[A-Z]{1,12}|INV|CH)-\d+\b", message
        ))))
        gate_id = f"{phase.name}.{gate_suffix}"
        denominator_count = None
        denominator_digest = ""
        if phase.name == "report_dedup_agent":
            try:
                _dedup_detail = _report_dedup_exact_pair_coverage_detail(
                    scratchpad
                )
                denominator_count = int(
                    _dedup_detail.get("denominator_count") or 0
                )
                denominator_digest = str(
                    _dedup_detail.get("denominator_digest") or ""
                )
            except Exception:
                pass
        failures.append(GateFailure(
            gate_id=gate_id,
            gate_class=gate_class,
            message=message,
            affected_identities=affected,
            input_digest=input_digest or _stable_payload_digest({
                "contract_digest": contract_digest,
                "evidence_paths": evidence_paths,
            }),
            output_digest=output_digest,
            contract_digest=contract_digest,
            evidence_paths=tuple(evidence_paths),
            repair_owner=phase.name,
            fallback_policy=_fallback_policy_for_gate_class(gate_class),
            allowed_fallback=allowed_fallback or _fallback_for_gate_class(
                gate_class
            ),
            schema_id=f"{gate_id}/v1",
            schema_version=1,
            denominator_count=denominator_count,
            denominator_digest=denominator_digest,
        ))
    return tuple(failures)


def _write_phase_commit_debt_projection(
    scratchpad: Path, checkpoint: Checkpoint,
) -> None:
    """Write the human-review projection from typed checkpoint authority."""
    rows: list[str] = [
        "# Phase Completion Debt",
        "",
        "This driver-owned ledger lists semantic gates that remain unresolved. "
        "Artifact presence does not clear these predicates.",
        "",
        "| Phase | State | Gate ID | Class | Affected identities | Failure | Fallback |",
        "|---|---|---|---|---|---|---|",
    ]
    for phase_name in sorted(checkpoint.phase_commits):
        commit = checkpoint.phase_commits[phase_name]
        for failure in commit.unresolved_failures:
            safe_message = failure.message.replace("|", "\\|").replace("\n", " ")
            safe_fallback = failure.allowed_fallback.replace("|", "\\|").replace("\n", " ")
            rows.append(
                f"| {phase_name} | {commit.state} | `{failure.gate_id}` | "
                f"{failure.gate_class} | "
                f"{', '.join(failure.affected_identities) or '-'} | "
                f"{safe_message} | {safe_fallback or '-'} |"
            )
    if len(rows) == 5:
        rows.append("| (none) | CLEAN | - | - | - | no unresolved debt | - |")
    path = scratchpad / "phase_completion_debt.md"
    tmp = path.with_suffix(".md.tmp")
    tmp.write_text("\n".join(rows) + "\n", encoding="utf-8")
    os.replace(tmp, path)


class PhaseCommitController:
    """Single semantic commit authority introduced by P0-AC/P0-AE.

    Legacy completion arrays remain compatibility projections during the
    staged migration.  Completed debt-bearing commits remain in both
    projections so downstream may continue.  ``INCOMPLETE_WITH_DEBT`` records
    a failed attempt without adding a completion token, so resume must retry it.
    """

    def __init__(
        self, checkpoint: Checkpoint, scratchpad: Path, project_root: str,
        config: dict,
    ) -> None:
        if not checkpoint.run_id:
            raise RuntimeError("phase commit requires a checkpoint run_id")
        self.checkpoint = checkpoint
        self.scratchpad = Path(scratchpad)
        self.project_root = str(project_root)
        self.config = config

    def commit(
        self,
        phase: Phase,
        state: str,
        failures: tuple[GateFailure, ...] = (),
        *,
        work_unit_id: str = "phase",
        clean_transients: bool = False,
        clearance_events: tuple[GateClearance, ...] = (),
        artifact_digest: str | None = None,
    ) -> PhaseCommit:
        contract_digest = _resolved_phase_contract_digest(phase, self.config)
        launch_digest = _resolved_phase_launch_digest(phase, self.config)
        resolved_artifact_digest = (
            _resolved_phase_artifact_digest(
                phase, self.scratchpad, self.project_root
            )
            if artifact_digest is None
            else str(artifact_digest)
        )
        commit_key = (
            phase.name if work_unit_id == "phase"
            else f"{phase.name}::{work_unit_id}"
        )
        previous = self.checkpoint.phase_commits.get(commit_key)
        previous_failures = {
            failure.gate_id: failure
            for failure in (previous.unresolved_failures if previous else ())
        }
        clearance_by_gate = {
            clearance.gate_id: clearance for clearance in clearance_events
        }
        for gate_id, clearance in clearance_by_gate.items():
            if gate_id not in previous_failures:
                raise RuntimeError(
                    f"clearance references unknown prior gate {gate_id!r}"
                )
            if clearance.clearing_gate_id != gate_id:
                raise RuntimeError(
                    "only same-gate clearance is registered in this release"
                )
        retained_previous = {
            gate_id: failure for gate_id, failure in previous_failures.items()
            if gate_id not in clearance_by_gate
        }
        current_failures = {failure.gate_id: failure for failure in failures}
        unresolved = tuple(
            sorted(
                {**retained_previous, **current_failures}.values(),
                key=lambda failure: failure.gate_id,
            )
        )
        if state == "CLEAN" and unresolved:
            raise RuntimeError(
                "cannot replace a debt-bearing commit with CLEAN without an "
                "explicit same-gate clearance event"
            )
        if state != "CLEAN" and not unresolved:
            raise RuntimeError(f"{state} requires unresolved gate failures")
        sibling_unresolved = [
            failure
            for key, sibling in self.checkpoint.phase_commits.items()
            if key != commit_key and sibling.phase_name == phase.name
            for failure in sibling.unresolved_failures
        ]
        if work_unit_id == "phase" and state == "CLEAN" and sibling_unresolved:
            raise RuntimeError(
                "cannot commit a CLEAN parent phase while a child work unit "
                "has unresolved gate failures"
            )
        commit = PhaseCommit(
            phase_name=phase.name,
            state=state,
            run_id=str(self.checkpoint.run_id),
            work_unit_id=work_unit_id,
            contract_digest=contract_digest,
            launch_digest=launch_digest,
            artifact_digest=resolved_artifact_digest,
            unresolved_failures=unresolved,
            clearance_events=tuple(clearance_events),
            committed_at=datetime.now(timezone.utc).isoformat(),
        )
        self.checkpoint.phase_commits[commit_key] = commit
        incomplete = state == "INCOMPLETE_WITH_DEBT"
        if work_unit_id == "phase":
            if incomplete:
                self.checkpoint.completed = [
                    name
                    for name in self.checkpoint.completed
                    if name != phase.name
                ]
            elif phase.name not in self.checkpoint.completed:
                self.checkpoint.completed.append(phase.name)
        phase_has_debt = bool(unresolved or sibling_unresolved)
        if state == "CLEAN" and not phase_has_debt:
            self.checkpoint.degraded = [
                name for name in self.checkpoint.degraded if name != phase.name
            ]
            if work_unit_id == "phase":
                self.checkpoint.clear_degraded_sentinel(
                    self.scratchpad, phase.name
                )
                if clean_transients:
                    _clear_retry_hint(self.scratchpad, phase.name)
                    _cleanup_quarantine_backups(self.scratchpad, phase)
        else:
            if phase.name not in self.checkpoint.degraded:
                self.checkpoint.degraded.append(phase.name)
            sentinel = self.scratchpad / f"{phase.name}.degraded"
            if not sentinel.exists():
                sentinel.write_text(
                    f"Phase {phase.name} committed as {state}.\n"
                    + "\n".join(f"- {failure.message}" for failure in failures)
                    + "\n",
                    encoding="utf-8",
                )
        if (
            work_unit_id == "phase"
            and not incomplete
            and self.checkpoint.rate_limited_at == phase.name
        ):
            self.checkpoint.rate_limited_at = None
        self.checkpoint.save(self.scratchpad)
        try:
            _write_phase_commit_debt_projection(self.scratchpad, self.checkpoint)
        except Exception as exc:
            log.warning(
                "[%s] typed phase commit persisted but debt projection failed: %r",
                phase.name,
                exc,
            )
        return commit


_INCOMPLETE_RETRY_ARM_SCHEMA = "plamen.phase_incomplete_retry_arm.v1"


def _incomplete_retry_arm_path(scratchpad: Path, phase_name: str) -> Path:
    safe = re.sub(r"[^A-Za-z0-9_.-]", "_", str(phase_name))
    return Path(scratchpad) / "_phase_attempts" / f"{safe}.retry_arm.json"


def _phase_commit_digest(commit: PhaseCommit) -> str:
    return _stable_payload_digest(commit.to_dict())


def _arm_incomplete_phase_retry(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
) -> bool:
    """Prepare a retry without erasing the prior typed failed attempt.

    The stale human projection is removed before execution so fresh phase debt
    can be distinguished from the prior attempt.  The immutable checkpoint
    commit remains authoritative; a crash at any point still leaves the phase
    incomplete and therefore retryable.
    """

    previous = checkpoint.phase_commits.get(phase.name)
    if previous is None or previous.state != "INCOMPLETE_WITH_DEBT":
        return False
    unsigned = {
        "schema_version": _INCOMPLETE_RETRY_ARM_SCHEMA,
        "run_id": checkpoint.run_id,
        "phase_name": phase.name,
        "prior_commit_sha256": _phase_commit_digest(previous),
        "prior_gate_ids": sorted(
            failure.gate_id for failure in previous.unresolved_failures
        ),
    }
    payload = {**unsigned, "arm_sha256": _stable_payload_digest(unsigned)}
    arm = _incomplete_retry_arm_path(scratchpad, phase.name)
    arm.parent.mkdir(parents=True, exist_ok=True)
    _atomic_driver_json(arm, payload)
    try:
        (Path(scratchpad) / f"{phase.name}.degraded").unlink(missing_ok=True)
    except OSError:
        # The typed commit still blocks completion.  Leave the retry armed;
        # accepted commit will refuse clearance if a stale/new sentinel remains.
        pass
    return True


def _incomplete_retry_clearances(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    artifact_digest: str | None = None,
) -> tuple[GateClearance, ...]:
    previous = checkpoint.phase_commits.get(phase.name)
    if previous is None or previous.state != "INCOMPLETE_WITH_DEBT":
        return ()
    arm_path = _incomplete_retry_arm_path(scratchpad, phase.name)
    try:
        arm = json.loads(arm_path.read_text(encoding="utf-8", errors="strict"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return ()
    unsigned = {key: value for key, value in arm.items() if key != "arm_sha256"}
    expected_gates = sorted(
        failure.gate_id for failure in previous.unresolved_failures
    )
    if (
        set(arm) != {
            "schema_version",
            "run_id",
            "phase_name",
            "prior_commit_sha256",
            "prior_gate_ids",
            "arm_sha256",
        }
        or arm.get("schema_version") != _INCOMPLETE_RETRY_ARM_SCHEMA
        or arm.get("run_id") != checkpoint.run_id
        or arm.get("phase_name") != phase.name
        or arm.get("prior_commit_sha256") != _phase_commit_digest(previous)
        or arm.get("prior_gate_ids") != expected_gates
        or arm.get("arm_sha256") != _stable_payload_digest(unsigned)
    ):
        return ()
    current_evidence = {
        "schema_version": "plamen.phase_incomplete_retry_clearance.v1",
        "run_id": checkpoint.run_id,
        "phase_name": phase.name,
        "prior_commit_sha256": arm["prior_commit_sha256"],
        "input_digest": _resolved_phase_input_digest(phase, dict(config)),
        "artifact_digest": (
            _resolved_phase_artifact_digest(
                phase, Path(scratchpad), str(config["project_root"])
            )
            if artifact_digest is None
            else str(artifact_digest)
        ),
        "contract_digest": _resolved_phase_contract_digest(
            phase, dict(config)
        ),
        "launch_digest": _resolved_phase_launch_digest(phase, dict(config)),
    }
    evidence_digest = _stable_payload_digest(current_evidence)
    stamp = datetime.now(timezone.utc).isoformat()
    return tuple(
        GateClearance(
            gate_id=failure.gate_id,
            clearing_gate_id=failure.gate_id,
            evidence_digest=evidence_digest,
            authority="DRIVER_SAME_GATE_RETRY_VALIDATOR",
            cleared_at=stamp,
        )
        for failure in previous.unresolved_failures
    )


def _retire_incomplete_retry_arm(scratchpad: Path, phase_name: str) -> None:
    try:
        _incomplete_retry_arm_path(scratchpad, phase_name).unlink(
            missing_ok=True
        )
    except OSError:
        pass


def _commit_incomplete_phase_attempt(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: Mapping[str, Any],
    issues: Sequence[str],
) -> PhaseCommit:
    artifact_digest = _resolved_phase_artifact_digest(
        phase, Path(scratchpad), str(config["project_root"])
    )
    failures = _gate_failures_from_issues(
        phase,
        list(issues) or ["phase attempt ended without accepted completion"],
        contract_digest=_resolved_phase_contract_digest(phase, dict(config)),
        output_digest=artifact_digest,
        scratchpad=Path(scratchpad),
        input_digest=_resolved_phase_input_digest(phase, dict(config)),
    )
    result = PhaseCommitController(
        checkpoint, Path(scratchpad), str(config["project_root"]), dict(config)
    ).commit(
        phase,
        "INCOMPLETE_WITH_DEBT",
        failures,
        clean_transients=False,
        artifact_digest=artifact_digest,
    )
    _retire_incomplete_retry_arm(Path(scratchpad), phase.name)
    return result


def _commit_phase_from_disk_debt(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    phases: list[Phase],
    *,
    clean_transients: bool,
) -> PhaseCommit:
    """Single parent-commit projection for normal and recovered phase paths."""
    _record_phase_artifact_state(
        scratchpad,
        config["project_root"],
        phases,
        phase.name,
        config["pipeline"],
    )
    sentinel = Path(scratchpad) / f"{phase.name}.degraded"
    controller = PhaseCommitController(
        checkpoint, scratchpad, config["project_root"], config
    )
    artifact_digest = _resolved_phase_artifact_digest(
        phase, scratchpad, config["project_root"]
    )
    clearances = _incomplete_retry_clearances(
        phase,
        checkpoint,
        scratchpad,
        config,
        artifact_digest=artifact_digest,
    )
    if not sentinel.exists():
        result = controller.commit(
            phase,
            "CLEAN",
            (),
            clean_transients=clean_transients,
            clearance_events=clearances,
            artifact_digest=artifact_digest,
        )
        _retire_incomplete_retry_arm(scratchpad, phase.name)
        return result
    try:
        issue = sentinel.read_text(
            encoding="utf-8", errors="replace"
        ).strip()
    except Exception as exc:
        issue = f"degraded sentinel unreadable: {type(exc).__name__}"
    contract_digest = _resolved_phase_contract_digest(phase, config)
    failures = _gate_failures_from_issues(
        phase,
        [issue or "phase validator recorded degraded coverage"],
        contract_digest=contract_digest,
        output_digest=artifact_digest,
        scratchpad=scratchpad,
        allowed_fallback=(
            "Downstream may consume the output, but the recorded "
            "coverage/quality debt remains unresolved."
        ),
        input_digest=_resolved_phase_input_digest(phase, config),
    )
    result = controller.commit(
        phase,
        "COMPLETED_WITH_DEBT",
        failures,
        clean_transients=False,
        clearance_events=clearances,
        artifact_digest=artifact_digest,
    )
    _retire_incomplete_retry_arm(scratchpad, phase.name)
    return result


def _commit_accepted_phase_from_disk(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    phases: list[Phase],
) -> PhaseCommit:
    """Typed replacement for legacy mark/clear/save completion triples."""

    return _commit_phase_from_disk_debt(
        phase,
        checkpoint,
        scratchpad,
        config,
        phases,
        clean_transients=True,
    )


_DYNAMIC_VERIFIER_ROSTER_NAME = "verification_runtime_roster.json"
_UNTRUSTED_COMPLETION_TRANSPORT_RC = -4
_DYNAMIC_VERIFIER_PLANNING_DEBT_NAME = "verification_runtime_planning_debt.json"
_DYNAMIC_VERIFIER_STATUS_NAME = "verification_runtime_status.json"
_DYNAMIC_VERIFIER_DEBT_NAME = "verification_runtime_debt.json"
_DYNAMIC_VERIFIER_UNIT_DIR = "_verifier_runtime_units"
_DYNAMIC_VERIFIER_COORDINATORS = {
    "sc": {
        "critical_high": "sc_verify_crithigh",
        "medium": "sc_verify_medium_a",
        "low_info": "sc_verify_low_a",
    },
    "l1": {
        "critical_high": "verify_crithigh",
        "medium": "verify_medium_a",
        "low_info": "verify_low_a",
    },
}


def _dynamic_verifier_coordinator_map(config: Mapping[str, Any]) -> dict[str, str]:
    pipeline = "l1" if str(config.get("pipeline")) == "l1" else "sc"
    return dict(_DYNAMIC_VERIFIER_COORDINATORS[pipeline])


def _dynamic_verifier_tier_for_phase(
    phase_name: str, config: Mapping[str, Any]
) -> str | None:
    for tier, coordinator in _dynamic_verifier_coordinator_map(config).items():
        if phase_name == coordinator:
            return tier
    return None


def _dynamic_verifier_bundle_digest(paths: Iterable[Path]) -> str:
    records: list[dict[str, str]] = []
    for path in sorted((Path(value) for value in paths), key=lambda value: value.as_posix()):
        if not path.is_file():
            raise FileNotFoundError(path)
        records.append(
            {
                "path": path.as_posix(),
                "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            }
        )
    return hashlib.sha256(
        json.dumps(
            records,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _dynamic_verifier_method_digest(config: Mapping[str, Any]) -> str:
    root = Path(__file__).resolve().parent.parent
    reachability = validate_methodology_reachability(root)
    if not reachability.get("ok"):
        raise ValueError("verification methodology reachability is not clean")
    return verification_method_stable_digest({
        "registry_digest": verification_method_registry_digest(root),
        "reachability_manifest_sha256": reachability["manifest_sha256"],
        "poc_execution_sha256": hashlib.sha256(
            (root / "rules" / "phase5-poc-execution.md").read_bytes()
        ).hexdigest(),
        "severity_contract_sha256": hashlib.sha256(
            (root / "scripts" / "severity_decision_ledger.py").read_bytes()
        ).hexdigest(),
    })


def _dynamic_verifier_context_digest(config: Mapping[str, Any]) -> str:
    path = Path(str(config["scratchpad"])) / "verification_context_packets.json"
    payload = json.loads(path.read_text(encoding="utf-8", errors="strict"))
    digest = str(payload.get("context_digest") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise ValueError("verification context packet authority has no digest")
    unsigned = {
        key: value for key, value in payload.items()
        if key != "context_digest"
    }
    if verification_method_stable_digest(unsigned) != digest:
        raise ValueError("verification context packet digest mismatch")
    return digest


def _write_dynamic_verifier_planning_debt(
    scratchpad: Path,
    outcome: VerifierRosterPlanningOutcome,
) -> Path:
    payload = {
        "schema_version": "plamen.verifier_runtime_planning_debt.v1",
        "state": "COMPLETED_WITH_DEBT",
        "debts": [debt.to_dict() for debt in outcome.debts],
    }
    path = Path(scratchpad) / _DYNAMIC_VERIFIER_PLANNING_DEBT_NAME
    _atomic_driver_json_record(path, payload)
    return path


def _prepare_dynamic_verifier_roster(
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
) -> VerifierRosterPlanningOutcome:
    """Compile the immutable queue plan into bounded live child authority."""

    plan = read_queue_work_plan(scratchpad)
    execution_policy = _resolve_config_execution_policy(config)
    backend = execution_policy.backend.value
    transport = "exec"
    if backend == "claude":
        transport, _transport_source = _strict_claude_exec_mode(
            config,
            raw_backend=str(config.get("cli_backend") or "claude"),
        )
    timeout = int(
        scale_timeout(
            phase.base_timeout_s,
            str(config["project_root"]),
            str(config.get("language") or "unknown"),
            mode=config.get("mode"),
            hypothesis_count=DEFAULT_MAX_FINDINGS_PER_VERIFIER,
            backend=backend,
        )
    )
    runtime_policy = build_verifier_runtime_policy(
        backend=backend,
        model=phase_model(phase, str(config.get("mode") or "core"), config),
        timeout_seconds=max(1, timeout),
        max_concurrency=max(
            1,
            int(
                config.get(
                    "verifier_max_concurrency", VERIFIER_DEFAULT_MAX_CONCURRENCY
                )
            ),
        ),
        source_root=str(Path(str(config["project_root"])).resolve()),
        transport=transport,
    )
    outcome = prepare_verifier_work_roster_haltless(
        Path(scratchpad) / _DYNAMIC_VERIFIER_ROSTER_NAME,
        plan,
        pipeline="l1" if str(config.get("pipeline")) == "l1" else "sc",
        ecosystem=str(config.get("language") or "unknown"),
        mode=str(config.get("mode") or "core"),
        runtime_policy=runtime_policy,
        method_registry_digest=_dynamic_verifier_method_digest(config),
        context_packet_digest=_dynamic_verifier_context_digest(config),
        max_findings_per_verifier=DEFAULT_MAX_FINDINGS_PER_VERIFIER,
    )
    if outcome.roster is None:
        _write_dynamic_verifier_planning_debt(scratchpad, outcome)
    else:
        (Path(scratchpad) / _DYNAMIC_VERIFIER_PLANNING_DEBT_NAME).unlink(
            missing_ok=True
        )
    return outcome


def _load_dynamic_verifier_roster(
    scratchpad: Path,
    *,
    require_current_plan: bool = True,
) -> VerifierWorkRoster:
    path = Path(scratchpad) / _DYNAMIC_VERIFIER_ROSTER_NAME
    roster = VerifierWorkRoster.from_json(
        path.read_text(encoding="utf-8", errors="strict")
    )
    if require_current_plan:
        plan = read_queue_work_plan(scratchpad)
        if roster.parent_queue_work_plan_digest != plan.digest:
            raise ValueError("verifier roster is stale for the current QueueWorkPlan")
        if roster.ordered_work_item_ids != plan.ordered_work_item_ids:
            raise ValueError("verifier roster denominator differs from QueueWorkPlan")
    if any(
        len(unit.ordered_work_item_ids) > DEFAULT_MAX_FINDINGS_PER_VERIFIER
        for unit in roster.work_units
    ):
        raise ValueError("verifier roster contains an oversized work unit")
    return roster


def _dynamic_verifier_unit_paths(
    scratchpad: Path, work_unit_id: str
) -> dict[str, Path]:
    directory = Path(scratchpad) / _DYNAMIC_VERIFIER_UNIT_DIR / work_unit_id
    return {
        "directory": directory,
        "manifest": directory / "manifest.md",
        "method_dispatch": directory / "method_dispatch.json",
        "prompt": directory / "prompt.md",
        "launch_spec": directory / "launch_spec.json",
        "stdio": directory / "stdio.log",
        "gate": directory / "gate_receipt.json",
        "receipt": directory / "unit_receipt.json",
        "debt": directory / "debt.json",
        "bb_policy_work": directory / "bb_policy_work.json",
        "bb_policy_application": directory / "bb_policy_application.json",
        "bb_policy_receipt": directory / "bb_policy_consumption_receipt.json",
    }


def _write_or_validate_bb_policy_json(
    path: Path,
    payload: Mapping[str, Any],
    *,
    validator: Callable[[Any], Mapping[str, Any]],
) -> None:
    target = Path(path)
    expected = dict(validator(payload))
    if target.is_file():
        try:
            current = validator(
                json.loads(target.read_text(encoding="utf-8", errors="strict"))
            )
        except (
            OSError,
            UnicodeError,
            json.JSONDecodeError,
            BBVerificationPolicyError,
        ) as exc:
            raise BBVerificationPolicyError(
                f"typed BB policy artifact is malformed: {target.name}: {exc}"
            ) from exc
        if dict(current) != expected:
            raise BBVerificationPolicyError(
                f"typed BB policy artifact drift: {target.name}"
            )
        return
    _atomic_driver_json_record(target, expected)


def _bb_policy_severity_token(value: Any) -> str:
    """Project driver severity labels into the closed BB-policy vocabulary."""

    severity = str(value or "").strip().lower()
    if severity == "info":
        severity = "informational"
    if severity not in {
        "critical",
        "high",
        "medium",
        "low",
        "informational",
    }:
        return "unresolved"
    return severity


def _expected_dynamic_verifier_bb_policy(
    scratchpad: Path,
    config: Mapping[str, Any],
    unit,
) -> dict[str, Any] | None:
    """Compile one exact verification-only packet without writing it."""
    if not bb_policy_configured(config):
        return None
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        raise BBVerificationPolicyError(
            "BB verifier work cannot bind without a driver run identity"
        )
    expected_ingress = build_bb_policy_ingress_payload(
        config,
        driver_run_id=run_id,
    )
    if expected_ingress is None:
        raise BBVerificationPolicyError(
            "configured BB policy produced no ingress"
        )
    ingress = _load_bound_bb_policy_ingress(
        Path(scratchpad), expected_ingress
    )
    queue_items = {
        item.work_item_id: item
        for item in _read_typed_queue_work_items(
            Path(scratchpad) / "verification_queue.md"
        )
    }
    missing = [
        work_id
        for work_id in unit.ordered_work_item_ids
        if work_id not in queue_items
    ]
    if missing:
        raise BBVerificationPolicyError(
            "BB policy work rows missing from typed verification queue: "
            + ", ".join(missing)
        )
    return build_bb_policy_work_projection(
        ingress,
        consumer_work_unit_id=unit.work_unit_id,
        consumer_kind="PRIMARY",
        work_items=[
            {
                "work_item_id": work_id,
                "severity": _bb_policy_severity_token(
                    queue_items[work_id].severity_proposal.level
                ),
                # Program impact identities are a distinct authority. Queue
                # aliases/titles must never be guessed into that namespace.
                "impact_ids": [],
            }
            for work_id in unit.ordered_work_item_ids
        ],
    )


def _prepare_dynamic_verifier_bb_policy(
    scratchpad: Path,
    config: Mapping[str, Any],
    unit,
) -> dict[str, Any] | None:
    """Materialize one exact verification-only packet for a primary unit."""
    projection = _expected_dynamic_verifier_bb_policy(
        Path(scratchpad), config, unit
    )
    if projection is None:
        return None
    paths = _dynamic_verifier_unit_paths(
        Path(scratchpad), unit.work_unit_id
    )
    relative_output = paths["bb_policy_work"].relative_to(
        scratchpad
    ).as_posix()
    validate_projection = lambda: (
        ()
        if dict(validate_bb_policy_work_projection(json.loads(
            paths["bb_policy_work"].read_text(
                encoding="utf-8", errors="strict"
            )
        ))) == projection
        else ("BB policy work projection differs from its denominator",)
    )
    transaction = (
        _validate_existing_p1dm_driver_transaction
        if paths["bb_policy_work"].is_file()
        else _record_p1dm_driver_transaction
    )
    transaction_kwargs: dict[str, Any] = {
        "phase_name": "bb_policy",
        "work_unit_id": f"projection.{unit.work_unit_id}",
        "exact_inputs": (BB_POLICY_LOCAL_INGRESS_PATH,),
        "exact_outputs": (relative_output,),
        "validate": validate_projection,
    }
    if transaction is _record_p1dm_driver_transaction:
        transaction_kwargs["action"] = lambda: _write_or_validate_bb_policy_json(
            paths["bb_policy_work"],
            projection,
            validator=validate_bb_policy_work_projection,
        )
    issues = transaction(
        Path(scratchpad),
        config,
        **transaction_kwargs,
    )
    if issues:
        raise BBVerificationPolicyError(
            "BB policy work PhaseIO binding failed: " + "; ".join(issues)
        )
    return projection


def _build_dynamic_verifier_bb_policy_receipt(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    unit,
    work_projection: Mapping[str, Any],
    launch_digest: str,
    method_dispatch_path: Path,
) -> dict[str, Any]:
    paths = _dynamic_verifier_unit_paths(
        Path(scratchpad), unit.work_unit_id
    )
    try:
        proposal = json.loads(
            paths["bb_policy_application"].read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise BBVerificationPolicyError(
            "BB policy application proposal is absent or malformed"
        ) from exc
    output_roster = [
        {
            "work_item_id": work_id,
            "artifact": f"verify_{work_id}.md",
            "sha256": hashlib.sha256(
                (
                    Path(scratchpad) / f"verify_{work_id}.md"
                ).read_bytes()
            ).hexdigest(),
        }
        for work_id in unit.ordered_work_item_ids
    ]
    verifier_output_sha256 = hashlib.sha256(
        json.dumps(
            {"outputs": output_roster},
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return build_bb_policy_consumption_receipt(
        _load_bound_bb_policy_ingress(
            Path(scratchpad),
            build_bb_policy_ingress_payload(
                config,
                driver_run_id=str(config.get("_run_id") or ""),
            )
            or {},
        ),
        work_projection=work_projection,
        proposal=proposal,
        launch_digest=launch_digest,
        method_dispatch_sha256=hashlib.sha256(
            Path(method_dispatch_path).read_bytes()
        ).hexdigest(),
        verifier_output_sha256=verifier_output_sha256,
        # A model-authored policy application is not independent evidence.
        # Typed corroborations are added only by a separate deterministic
        # provider; until then, results remain visible PROPOSAL_ONLY debt.
        corroborations=(),
    )


def _bind_dynamic_verifier_bb_policy_receipt(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    unit,
    work_projection: Mapping[str, Any],
    launch_digest: str,
    method_dispatch_path: Path,
) -> str:
    paths = _dynamic_verifier_unit_paths(
        Path(scratchpad), unit.work_unit_id
    )
    receipt = _build_dynamic_verifier_bb_policy_receipt(
        scratchpad=Path(scratchpad),
        config=config,
        unit=unit,
        work_projection=work_projection,
        launch_digest=launch_digest,
        method_dispatch_path=method_dispatch_path,
    )
    receipt_relative = paths["bb_policy_receipt"].relative_to(
        scratchpad
    ).as_posix()
    exact_inputs = (
        paths["bb_policy_work"].relative_to(scratchpad).as_posix(),
        paths["bb_policy_application"].relative_to(
            scratchpad
        ).as_posix(),
        paths["method_dispatch"].relative_to(scratchpad).as_posix(),
        paths["launch_spec"].relative_to(scratchpad).as_posix(),
        *(
            f"verify_{work_id}.md"
            for work_id in unit.ordered_work_item_ids
        ),
    )
    issues = _record_p1dm_driver_transaction(
        Path(scratchpad),
        config,
        phase_name="bb_policy",
        work_unit_id=f"consumption.{unit.work_unit_id}",
        exact_inputs=exact_inputs,
        exact_outputs=(receipt_relative,),
        action=lambda: _write_or_validate_bb_policy_json(
            paths["bb_policy_receipt"],
            receipt,
            validator=validate_bb_policy_consumption_receipt,
        ),
        validate=lambda: (
            ()
            if validate_bb_policy_consumption_receipt(json.loads(
                paths["bb_policy_receipt"].read_text(
                    encoding="utf-8", errors="strict"
                )
            )) == receipt
            else ("BB policy consumption receipt differs from inputs",)
        ),
    )
    if issues:
        raise BBVerificationPolicyError(
            "BB policy consumption PhaseIO binding failed: "
            + "; ".join(issues)
        )
    return hashlib.sha256(paths["bb_policy_receipt"].read_bytes()).hexdigest()


def _bb_policy_consumption_phaseio_issues(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    work_unit_id: str,
    exact_inputs: Sequence[str],
    exact_output: str,
) -> list[str]:
    try:
        contract, launch = _p1dm_contract_and_launch(
            Path(scratchpad),
            config,
            phase_name="bb_policy",
            work_unit_id=work_unit_id,
            exact_inputs=tuple(exact_inputs),
            exact_outputs=(exact_output,),
            actor="DRIVER",
        )
        run_id = str(config.get("_run_id") or "").strip()
        project = Path(
            str(config.get("project_root") or Path(scratchpad).parent)
        )
        issues = validate_work_unit_inputs(
            Path(scratchpad), project, contract, launch, run_id=run_id
        )
        issues.extend(validate_work_unit_artifacts(
            Path(scratchpad),
            project,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
        issues.extend(active_committed_work_unit_authority_issues(
            read_artifact_ledger(Path(scratchpad)),
            work_unit_key=contract.key,
            run_id=run_id,
            expected_artifact_identities=tuple(
                output.identity for output in contract.outputs
            ),
        ))
        return list(dict.fromkeys(issues))
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        return [
            "BB policy consumption PhaseIO replay failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _persist_dynamic_verifier_unit_receipt(
    path: Path, receipt: VerifierUnitReceipt
) -> None:
    _atomic_driver_json_record(Path(path), receipt.to_dict())


def _dynamic_verifier_unit_gate_issues(
    scratchpad: Path,
    phase_name: str,
    roster: VerifierWorkRoster,
    unit,
    config: dict[str, Any],
) -> list[str]:
    paths = _dynamic_verifier_unit_paths(scratchpad, unit.work_unit_id)
    try:
        receipt = VerifierUnitReceipt.from_json(
            paths["receipt"].read_text(encoding="utf-8", errors="strict")
        )
        if receipt.status != "COMPLETED":
            return [
                f"{unit.work_unit_id} retained {receipt.reason_class or 'execution'} debt"
            ]
        if receipt.work_unit_resume_digest != unit.resume_digest:
            return [f"{unit.work_unit_id} completion receipt is stale"]
        launch_spec = VerifierLaunchSpec.from_json(
            paths["launch_spec"].read_text(encoding="utf-8", errors="strict")
        )
        if receipt.launch_spec_digest != launch_spec.digest:
            return [f"{unit.work_unit_id} launch-spec receipt mismatch"]
        current_dispatch = _compile_dynamic_verifier_method_dispatch(
            Path(scratchpad),
            config,
            unit,
            manifest_path=paths["manifest"],
        )
        recorded_dispatch = json.loads(
            paths["method_dispatch"].read_text(
                encoding="utf-8", errors="strict"
            )
        )
        if recorded_dispatch != dispatch_receipt_payload(current_dispatch):
            return [f"{unit.work_unit_id} method dispatch is stale"]
        bb_policy_work = _expected_dynamic_verifier_bb_policy(
            Path(scratchpad), config, unit
        )
        if bb_policy_work is not None:
            if not paths["bb_policy_work"].is_file():
                return [
                    f"{unit.work_unit_id} BB policy work projection is absent"
                ]
            recorded_bb_work = validate_bb_policy_work_projection(
                json.loads(paths["bb_policy_work"].read_text(
                    encoding="utf-8", errors="strict"
                ))
            )
            if recorded_bb_work != bb_policy_work:
                return [
                    f"{unit.work_unit_id} BB policy work projection is stale"
                ]
        method_model_outputs = tuple(
            name
            for work_id in unit.ordered_work_item_ids
            for name in (
                f"verify_{work_id}.md",
                f"verify_{work_id}.severity_proposal.json",
                f"verify_{work_id}.operator_application.json",
            )
        ) + (
            (
                paths["bb_policy_application"].relative_to(
                    scratchpad
                ).as_posix(),
            )
            if bb_policy_work is not None
            else ()
        )
        method_operator_receipts = tuple(
            f"verify_{work_id}.operator_receipt.json"
            for work_id in unit.ordered_work_item_ids
        )
        (
            prelaunch_io_contract,
            model_io_contract,
            control_io_contract,
        ) = _write_verifier_method_phase_io_contracts(
            directory=paths["directory"],
            scratchpad=Path(scratchpad),
            config=config,
            phase_name=phase_name,
            work_unit_id=unit.work_unit_id,
            model_outputs=method_model_outputs,
            operator_receipts=method_operator_receipts,
            immutable_launch_inputs=(
                paths["manifest"],
                Path(scratchpad) / "verification_context_packets.json",
                *(
                    (paths["bb_policy_work"],)
                    if bb_policy_work is not None
                    else ()
                ),
                paths["method_dispatch"],
                paths["prompt"],
                paths["launch_spec"],
            ),
            shared_immutable_inputs=(
                Path(scratchpad) / "verification_context_packets.json",
                *(
                    (paths["bb_policy_work"],)
                    if bb_policy_work is not None
                    else ()
                ),
            ),
            driver_outputs=(
                paths["method_dispatch"], paths["prompt"], paths["launch_spec"],
                paths["gate"], paths["receipt"], paths["debt"],
            ),
        )
        phase_io_issues = _record_verifier_method_phase_io_authority(
            prelaunch_contract=prelaunch_io_contract,
            model_contract=model_io_contract,
            control_contract=control_io_contract,
            launch_spec=launch_spec,
            scratchpad=Path(scratchpad),
            project_root=Path(
                config.get("project_root") or Path(scratchpad).parent
            ),
            run_id=str(config.get("_run_id") or "test-unbound"),
            include_outputs=True,
            allow_initialize=False,
        )
        if phase_io_issues:
            return [
                f"{unit.work_unit_id} PhaseIO completion authority invalid: "
                + "; ".join(phase_io_issues)
            ]
        operator_receipt_digests: list[str] = []
        for work_id in unit.ordered_work_item_ids:
            proposal_path = (
                Path(scratchpad)
                / f"verify_{work_id}.operator_application.json"
            )
            verify_path = Path(scratchpad) / f"verify_{work_id}.md"
            operator_receipt_path = (
                Path(scratchpad)
                / f"verify_{work_id}.operator_receipt.json"
            )
            load_bound_operator_receipt(
                receipt_path=operator_receipt_path,
                proposal_path=proposal_path,
                verify_path=verify_path,
                dispatch=current_dispatch,
                launch_digest=launch_spec.digest,
            )
            operator_receipt_digests.append(
                hashlib.sha256(
                    operator_receipt_path.read_bytes()
                ).hexdigest()
            )
        bb_policy_receipt_digest = ""
        if bb_policy_work is not None:
            if not paths["bb_policy_receipt"].is_file():
                return [
                    f"{unit.work_unit_id} BB policy consumption receipt is absent"
                ]
            expected_bb_receipt = (
                _build_dynamic_verifier_bb_policy_receipt(
                    scratchpad=Path(scratchpad),
                    config=config,
                    unit=unit,
                    work_projection=bb_policy_work,
                    launch_digest=launch_spec.digest,
                    method_dispatch_path=paths["method_dispatch"],
                )
            )
            recorded_bb_receipt = validate_bb_policy_consumption_receipt(
                json.loads(paths["bb_policy_receipt"].read_text(
                    encoding="utf-8", errors="strict"
                ))
            )
            if recorded_bb_receipt != expected_bb_receipt:
                return [
                    f"{unit.work_unit_id} BB policy consumption receipt is stale"
                ]
            bb_phaseio_issues = _bb_policy_consumption_phaseio_issues(
                scratchpad=Path(scratchpad),
                config=config,
                work_unit_id=f"consumption.{unit.work_unit_id}",
                exact_inputs=(
                    paths["bb_policy_work"].relative_to(
                        scratchpad
                    ).as_posix(),
                    paths["bb_policy_application"].relative_to(
                        scratchpad
                    ).as_posix(),
                    paths["method_dispatch"].relative_to(
                        scratchpad
                    ).as_posix(),
                    paths["launch_spec"].relative_to(
                        scratchpad
                    ).as_posix(),
                    *(
                        f"verify_{work_id}.md"
                        for work_id in unit.ordered_work_item_ids
                    ),
                ),
                exact_output=paths["bb_policy_receipt"].relative_to(
                    scratchpad
                ).as_posix(),
            )
            if bb_phaseio_issues:
                return [
                    f"{unit.work_unit_id} BB policy PhaseIO authority invalid: "
                    + "; ".join(bb_phaseio_issues)
                ]
            bb_policy_receipt_digest = hashlib.sha256(
                paths["bb_policy_receipt"].read_bytes()
            ).hexdigest()
        actual_output_receipt_digests = tuple(
            hashlib.sha256(
                (Path(scratchpad) / f"verify_{work_id}.receipt.json").read_bytes()
            ).hexdigest()
            for work_id in unit.ordered_work_item_ids
        )
        if receipt.output_receipt_digests != actual_output_receipt_digests:
            return [f"{unit.work_unit_id} output receipt bytes changed"]
        gate_digest = hashlib.sha256(paths["gate"].read_bytes()).hexdigest()
        if receipt.gate_receipt_digests != (gate_digest,):
            return [f"{unit.work_unit_id} gate receipt bytes changed"]
        gate_payload = json.loads(
            paths["gate"].read_text(encoding="utf-8", errors="strict")
        )
        if gate_payload.get("method_dispatch_id") != current_dispatch["dispatch_id"]:
            return [f"{unit.work_unit_id} gate method dispatch mismatch"]
        if tuple(gate_payload.get("operator_receipt_digests") or ()) != tuple(
            operator_receipt_digests
        ):
            return [f"{unit.work_unit_id} gate operator receipt mismatch"]
        if (
            str(gate_payload.get("bb_policy_receipt_digest") or "")
            != bb_policy_receipt_digest
        ):
            return [f"{unit.work_unit_id} gate BB policy receipt mismatch"]
        issues = _validate_verify_completion(
            Path(scratchpad),
            phase_name,
            min_bytes=100,
            mode=str(config.get("mode") or "core"),
            execution_policy=_resolve_config_execution_policy(config),
            launch_digest=launch_spec.digest,
            assigned_work_item_ids=unit.ordered_work_item_ids,
        )
        if not issues:
            policy = _resolve_config_execution_policy(config)
            issues.extend(
                validate_shadow_severity_for_shard(
                    Path(scratchpad),
                    phase_name,
                    backend=policy.backend.value,
                    launch_digest=launch_spec.digest,
                    run_id=str(config.get("_run_id") or "test-unbound"),
                    assigned_work_item_ids=unit.ordered_work_item_ids,
                )
            )
        return list(issues)
    except Exception as exc:
        return [
            f"{unit.work_unit_id} completion authority unavailable or invalid: "
            f"{type(exc).__name__}: {exc}"
        ]


def _write_dynamic_verifier_status(
    scratchpad: Path,
    roster: VerifierWorkRoster,
) -> tuple[Any, list[str]]:
    receipts: list[VerifierUnitReceipt] = []
    malformed: list[str] = []
    for unit in roster.work_units:
        path = _dynamic_verifier_unit_paths(
            scratchpad, unit.work_unit_id
        )["receipt"]
        if not path.is_file():
            continue
        try:
            receipts.append(
                VerifierUnitReceipt.from_json(
                    path.read_text(encoding="utf-8", errors="strict")
                )
            )
        except Exception as exc:
            malformed.append(
                f"{unit.work_unit_id}: {type(exc).__name__}: {exc}"
            )
    status = reconcile_verifier_work_roster(roster, receipts)
    payload = status.to_dict()
    _atomic_driver_json_record(
        Path(scratchpad) / _DYNAMIC_VERIFIER_STATUS_NAME, payload
    )
    return status, malformed


def _materialize_dynamic_verifier_manifest(
    scratchpad: Path, unit, path: Path
) -> None:
    rows = parse_verification_queue_rows(scratchpad)
    by_id = {(row.get("finding id") or "").strip(): row for row in rows}
    missing = [work_id for work_id in unit.ordered_work_item_ids if work_id not in by_id]
    if missing:
        raise ValueError(
            "runtime verifier rows missing from canonical queue: "
            + ", ".join(missing)
        )
    path.parent.mkdir(parents=True, exist_ok=True)
    _write_queue_subset_manifest(path, [by_id[work_id] for work_id in unit.ordered_work_item_ids])
    typed = _read_typed_queue_work_items(path)
    if tuple(item.work_item_id for item in typed) != unit.ordered_work_item_ids:
        raise ValueError("runtime manifest typed projection changed unit membership")


def _normalize_dynamic_verifier_context_roots(
    context_path: Path,
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    """Match the relocation-safe root tokens emitted by live queue T7.

    T7 builds packets in an isolated transaction workspace and therefore
    replaces only the two absolute root fields with its canonical symbolic
    identities.  The dynamic verifier recomputes packets against the live
    roots before dispatch.  Permit that exact representation bridge while
    leaving every graph, row, packet, and binding byte under the existing
    equality and digest checks.
    """

    value = dict(payload)
    target = Path(context_path)
    if not target.is_file():
        return value
    existing = json.loads(
        target.read_text(encoding="utf-8", errors="strict")
    )
    if not isinstance(existing, dict):
        return value
    roots = (
        existing.get("project_root"),
        existing.get("scratchpad"),
    )
    if roots != ("project::", "scratchpad::"):
        return value
    value["project_root"] = "project::"
    value["scratchpad"] = "scratchpad::"
    unsigned = {
        key: item for key, item in value.items()
        if key != "context_digest"
    }
    value["context_digest"] = verification_method_stable_digest(unsigned)
    return value


def _compile_dynamic_verifier_method_dispatch(
    scratchpad: Path,
    config: Mapping[str, Any],
    unit,
    *,
    manifest_path: Path,
) -> dict[str, Any]:
    all_items = {
        item.work_item_id: item
        for item in _read_typed_queue_work_items(
            Path(scratchpad) / "verification_queue.md"
        )
    }
    missing = [
        work_id for work_id in unit.ordered_work_item_ids
        if work_id not in all_items
    ]
    if missing:
        raise ValueError(
            "method dispatch rows missing from typed queue: "
            + ", ".join(missing)
        )
    context_path = (
        Path(scratchpad) / "verification_context_packets.json"
    )
    # Recompute every time, including completed-unit resume validation.  The
    # packet transitively binds the exact primary evidence and reference-graph
    # bytes; merely reloading an internally consistent old packet would let
    # those authorities disappear or change without invalidating a verifier
    # completion receipt.
    context_payload = build_verification_context_packets(
        rows=[item.to_dict() for item in all_items.values()],
        scratchpad=Path(scratchpad),
        project_root=Path(
            config.get("project_root") or Path(scratchpad).parent
        ),
    )
    context_payload = _normalize_dynamic_verifier_context_roots(
        context_path,
        context_payload,
    )
    write_or_validate_context_packets(context_path, context_payload)
    return compile_verification_method_dispatch(
        pipeline="l1" if str(config.get("pipeline")) == "l1" else "sc",
        ecosystem=str(config.get("language") or "unknown").lower(),
        backend=str(config.get("cli_backend") or "claude").lower(),
        rows=[
            all_items[work_id].to_dict()
            for work_id in unit.ordered_work_item_ids
        ],
        context_packets=context_payload,
        manifest_path=str(
            manifest_path.relative_to(scratchpad).as_posix()
        ),
        scratchpad_path=str(Path(scratchpad)),
        root=Path(__file__).resolve().parent.parent,
    )


def _verifier_markdown_verdict(path: Path) -> str:
    text = Path(path).read_text(encoding="utf-8", errors="replace")
    match = re.search(
        r"(?im)^\s*(?:[-*]\s*)?\*{0,2}Verdict\*{0,2}\s*:\s*"
        r"([A-Z][A-Z0-9_-]*)",
        text,
    )
    return match.group(1).upper() if match else "CONTESTED"


def _bind_dynamic_verifier_operator_receipts(
    *,
    scratchpad: Path,
    unit,
    dispatch: Mapping[str, Any],
    launch_digest: str,
) -> tuple[str, ...]:
    digests: list[str] = []
    for work_id in unit.ordered_work_item_ids:
        verify_path = Path(scratchpad) / f"verify_{work_id}.md"
        proposal_path = (
            Path(scratchpad)
            / f"verify_{work_id}.operator_application.json"
        )
        receipt_path = (
            Path(scratchpad)
            / f"verify_{work_id}.operator_receipt.json"
        )
        bind_operator_application_receipt(
            proposal_path=proposal_path,
            verify_path=verify_path,
            receipt_path=receipt_path,
            dispatch=dispatch,
            launch_digest=launch_digest,
            verdict=_verifier_markdown_verdict(verify_path),
            root=Path(__file__).resolve().parent.parent,
        )
        load_bound_operator_receipt(
            receipt_path=receipt_path,
            proposal_path=proposal_path,
            verify_path=verify_path,
            dispatch=dispatch,
            launch_digest=launch_digest,
        )
        digests.append(hashlib.sha256(receipt_path.read_bytes()).hexdigest())
    return tuple(digests)


def _strict_rooted_worker_json(path: Path, *, label: str) -> dict[str, Any]:
    """Read one immutable worker-transaction JSON object without aliasing."""

    raw = rooted_io.read_bytes(
        path,
        label=label,
        require_single_link=True,
    )
    if len(raw) > 16 * 1024 * 1024:
        raise ValueError(f"{label} exceeds the bounded JSON size")

    def reject_duplicate_pairs(
        pairs: list[tuple[str, Any]],
    ) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"{label} contains duplicate key {key!r}")
            value[key] = item
        return value

    def reject_constant(value: str) -> None:
        raise ValueError(f"{label} contains non-finite number {value!r}")

    decoded = json.loads(
        raw.decode("utf-8", errors="strict"),
        object_pairs_hook=reject_duplicate_pairs,
        parse_constant=reject_constant,
    )
    if not isinstance(decoded, dict):
        raise ValueError(f"{label} must be a JSON object")
    return decoded


def _replay_committed_model_worker(
    *,
    scratchpad: Path,
    project_root: Path,
    run_id: str,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    methodology_digests: Sequence[str],
    source_snapshot_digest: str,
) -> tuple[dict[str, Any], dict[str, Any]] | None:
    """Replay an exact incorporated MODEL transaction, or report no commit.

    A committed row is never treated as an invitation to re-arm.  Once such a
    row exists, every authority ingredient must replay against the *current*
    contract, launch, input set, provider model, methodology, source snapshot,
    final roster, and output denominator.  Any discrepancy is typed debt and
    fails closed before a provider can be called.
    """

    root = Path(scratchpad)
    ledger_before = read_artifact_ledger(root)
    unit_before = ledger_before.get("work_units", {}).get(contract.key)
    if not (
        isinstance(unit_before, Mapping)
        and unit_before.get("semantic_status") == "ACTIVE"
        and unit_before.get("execution_state") == "OUTPUT_COMMITTED"
    ):
        return None

    artifact_issues = validate_work_unit_artifacts(
        root,
        Path(project_root),
        contract,
        launch,
        run_id=run_id,
        actor="MODEL",
    )
    if artifact_issues:
        raise ValueError(
            "committed model PhaseIO authority is invalid: "
            + "; ".join(artifact_issues)
        )
    ledger_after_validation = read_artifact_ledger(root)
    unit = ledger_after_validation.get("work_units", {}).get(contract.key)
    if unit != unit_before:
        raise ValueError("committed model PhaseIO authority changed during replay")
    authority = unit.get("execution_authority") if isinstance(unit, Mapping) else None
    if not isinstance(authority, Mapping):
        raise ValueError("committed model PhaseIO lacks worker execution authority")

    from worker_transaction import (
        validate_work_plan_phase_roster,
        validate_worker_execution_authority,
    )

    normalized = validate_worker_execution_authority(
        scratchpad=root,
        authority=authority,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    attempt_relative = Path(normalized["attempt_completion_relative_path"])
    if attempt_relative.name != "completion.json":
        raise ValueError("worker attempt completion path is non-canonical")
    attempt_directory = attempt_relative.parent
    if attempt_directory.name != normalized["attempt_id"]:
        raise ValueError("worker attempt path differs from its authority identity")
    plan_path = rooted_io.safe_descendant(
        root,
        (attempt_directory / "view" / "plan.json").as_posix(),
        allow_missing=False,
        label="worker replay plan",
    )
    roster_path = rooted_io.safe_descendant(
        root,
        (attempt_directory / "view" / "phase_roster.json").as_posix(),
        allow_missing=False,
        label="worker replay phase roster",
    )
    worker_plan = _strict_rooted_worker_json(plan_path, label="worker replay plan")
    phase_roster = _strict_rooted_worker_json(
        roster_path,
        label="worker replay phase roster",
    )
    validate_work_plan_phase_roster(worker_plan, phase_roster)

    provider = worker_plan.get("provider")
    members = worker_plan.get("assignment", {}).get("members")
    observed_outputs = sorted(
        str(row.get("canonical_identity") or "")
        for row in members
        if isinstance(row, Mapping)
    ) if isinstance(members, list) else []
    expected_outputs = sorted(spec.identity for spec in contract.outputs)
    expected_methods = sorted(str(value) for value in methodology_digests)
    if (
        worker_plan.get("work_plan_digest") != normalized["work_plan_digest"]
        or worker_plan.get("run_id") != run_id
        or worker_plan.get("phase") != contract.phase
        or worker_plan.get("work_unit_id") != contract.work_unit_id
        or worker_plan.get("phase_io_contract_digest") != contract.digest
        or worker_plan.get("phase_io_launch_digest") != launch.digest
        or worker_plan.get("phase_io_input_set_digest")
        != unit.get("input_set_digest")
        or worker_plan.get("methodology_digests") != expected_methods
        or worker_plan.get("source_snapshot_digest") != source_snapshot_digest
        or not isinstance(provider, Mapping)
        or provider.get("backend") != launch.backend
        or provider.get("model") != launch.model
        or provider.get("transport") != launch.exec_mode
        or provider.get("timeout_seconds") != launch.timeout_s
        or observed_outputs != expected_outputs
        or len(observed_outputs) != len(expected_outputs)
    ):
        raise ValueError(
            "committed worker plan differs from the current execution authority"
        )
    ledger_after_replay = read_artifact_ledger(root)
    if ledger_after_replay.get("work_units", {}).get(contract.key) != unit:
        raise ValueError("committed model PhaseIO authority changed during replay")
    return normalized, worker_plan


def _completed_execution_from_worker_replay(
    *,
    scratchpad: Path,
    authority: Mapping[str, Any],
    exact_outputs: Sequence[str],
) -> CompletedExecution:
    """Recover the provider handle only from a validated outer authority."""

    root = Path(scratchpad)
    provider_relative = str(authority["provider_completion_relative_path"])
    provider_receipt = rooted_io.safe_descendant(
        root,
        provider_relative,
        allow_missing=False,
        label="replayed provider completion",
    )
    provider = _strict_rooted_worker_json(
        provider_receipt,
        label="replayed provider completion",
    )
    if provider.get("completion_sha256") != authority["provider_completion_digest"]:
        raise ValueError("provider completion differs from outer authority")
    arm_name = str(provider.get("arm_relative_path") or "")
    if Path(arm_name).name != arm_name or not arm_name:
        raise ValueError("replayed provider arm path is invalid")
    arm_path = rooted_io.safe_descendant(
        root,
        (Path(provider_relative).parent / arm_name).as_posix(),
        allow_missing=False,
        label="replayed provider arm",
    )
    arm_sha256 = str(provider.get("arm_sha256") or "")
    if re.fullmatch(r"[0-9a-f]{64}", arm_sha256) is None:
        raise ValueError("replayed provider arm digest is invalid")

    publish_paths: list[Path] = []
    with rooted_io.scandir(provider_receipt.parent) as entries:
        for entry in entries:
            if (
                re.fullmatch(r"publish_[0-9a-f]{64}\.json", entry.name)
                and rooted_io.is_file(Path(entry.path))
            ):
                publish_paths.append(Path(entry.path))
    if len(publish_paths) != 1:
        raise ValueError("replayed provider publication is absent or ambiguous")
    publish_path = publish_paths[0]
    publish_match = re.fullmatch(r"publish_([0-9a-f]{64})\.json", publish_path.name)
    assert publish_match is not None
    return CompletedExecution(
        receipt_path=provider_receipt,
        completion_sha256=str(authority["provider_completion_digest"]),
        arm_path=arm_path,
        arm_sha256=arm_sha256,
        publish_receipt_path=publish_path,
        publish_sha256=publish_match.group(1),
        published_paths=tuple(root / name for name in exact_outputs),
    )


def _execute_dynamic_verifier_launch(
    spec: VerifierLaunchSpec,
    *,
    prompt_path: Path,
    log_path: Path,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    model_io_contract: PhaseIOContract | None = None,
    model_io_launch: LaunchSpec | None = None,
) -> int:
    """Execute one exact leaf policy in the foreground and always join it."""

    env = {
        **_filtered_child_subprocess_environ(),
        **_CLAUDE_UPDATE_DISABLE_ENV,
        "ANTHROPIC_DEFAULT_OPUS_MODEL": str(PLAMEN_OPUS_MODEL),
        "ANTHROPIC_DEFAULT_SONNET_MODEL": str(PLAMEN_SONNET_MODEL),
        "ANTHROPIC_DEFAULT_HAIKU_MODEL": str(PLAMEN_HAIKU_MODEL),
        "PLAMEN_SCRATCHPAD": str(Path(scratchpad).resolve()),
        "BASH_MAX_OUTPUT_LENGTH": os.environ.get("BASH_MAX_OUTPUT_LENGTH", "30000"),
        "MAX_MCP_OUTPUT_TOKENS": os.environ.get("MAX_MCP_OUTPUT_TOKENS", "8000"),
    }
    log_path.parent.mkdir(parents=True, exist_ok=True)
    start = time.time()
    if spec.backend == "claude" and spec.transport == "pty":
        debt = {
            "schema_version": "plamen.semantic_transport_debt.v1",
            "status": "COMPLETED_WITH_DEBT",
            "reason_code": "UNTRUSTED_COMPLETION_TRANSPORT",
            "backend": spec.backend,
            "transport": spec.transport,
            "work_unit_id": spec.work_unit_id,
            "launch_spec_digest": spec.digest,
            "detail": (
                "Claude PTY terminal heuristics are not admissible semantic "
                "completion evidence; use the receipt-validated headless "
                "stream-json transport"
            ),
        }
        _atomic_driver_json_record(log_path, debt)
        _append_phase_io_debt(
            Path(scratchpad),
            str(phase.name),
            "UNTRUSTED_COMPLETION_TRANSPORT",
            (
                f"{spec.work_unit_id}: Claude PTY completion was rejected "
                f"before provider launch ({spec.digest})"
            ),
        )
        log.warning(
            "[%s] %s: refused Claude PTY launch for %s",
            phase.name,
            debt["reason_code"],
            spec.work_unit_id,
        )
        return _UNTRUSTED_COMPLETION_TRANSPORT_RC
    if spec.transport != "pty" and (
        model_io_contract is not None or model_io_launch is not None
    ):
        if model_io_contract is None or model_io_launch is None:
            log_path.write_text(
                "dynamic verifier transactional authority is incomplete\n",
                encoding="utf-8",
            )
            return EXIT_ERROR
        prompt_raw = prompt_path.read_bytes()
        if (
            hashlib.sha256(prompt_raw).hexdigest() != spec.prompt_sha256
            or len(prompt_raw) != spec.prompt_size_bytes
        ):
            log_path.write_text(
                "dynamic verifier prompt differs from launch authority\n",
                encoding="utf-8",
            )
            return EXIT_ERROR

        try:
            root = Path(scratchpad).resolve(strict=True)
            project_root = Path(
                config.get("project_root") or root.parent
            ).resolve(strict=True)
            runtime_cwd = Path(spec.cwd).resolve(strict=True)
            source_snapshot_sha256 = (
                _security_obligation_source_snapshot_digest(config)
            )
            startup_binding = (
                _current_auxiliary_writable_root_startup_binding(root, config)
            )
            claude_provider_authority: (
                _ClaudeDriverProviderAuthority | None
            ) = None
            prelaunch_claude_boundary = None
            if spec.backend == "claude":
                if any(
                    value == "--dangerously-skip-permissions"
                    for value in spec.argv
                ):
                    raise HeadlessWorkerRuntimeError(
                        "handcrafted Claude bypass argv is forbidden"
                    )
                prelaunch_claude_boundary = (
                    _replay_explicit_claude_headless_launch_boundary(
                        phase=phase,
                        config=config,
                        scratchpad=root,
                        contract=model_io_contract,
                        launch=model_io_launch,
                    )
                )
                startup_binding = prelaunch_claude_boundary[0]
                claude_provider_authority = (
                    _compile_claude_driver_provider_authority(
                        phase=phase,
                        config=config,
                        scratchpad=root,
                        project_root=project_root,
                        cwd=runtime_cwd,
                        launch=model_io_launch,
                        session_id=claude_semantic_session_id(
                            work_unit_id=spec.work_unit_id,
                            work_unit_resume_digest=(
                                spec.work_unit_resume_digest
                            ),
                            prompt_sha256=spec.prompt_sha256,
                        ),
                        startup_authority_binding=startup_binding,
                        source_snapshot_sha256=source_snapshot_sha256,
                    )
                )
                public_claude_arguments = (
                    claude_provider_authority.public_arguments
                )
                env = dict(public_claude_arguments["environment"])
                environment_allowlist = tuple(
                    public_claude_arguments["environment_allowlist"]
                )
                if (
                    _replay_explicit_claude_headless_launch_boundary(
                        phase=phase,
                        config=config,
                        scratchpad=root,
                        contract=model_io_contract,
                        launch=model_io_launch,
                    )
                    != prelaunch_claude_boundary
                ):
                    raise HeadlessWorkerRuntimeError(
                        "Claude verifier boundary changed before launch"
                    )
            else:
                public_claude_arguments = {}
                environment_allowlist = tuple(sorted(env))

            def command_builder(output_directory: Path) -> Sequence[str]:
                if spec.backend == "claude":
                    if claude_provider_authority is None:
                        raise HeadlessWorkerRuntimeError(
                            "Claude verifier provider authority is unavailable"
                        )
                    return claude_provider_authority.base_argv_template
                argv = list(spec.argv)
                addition = ["--add-dir", output_directory.as_posix()]
                if argv and argv[-1] == "-":
                    argv[-1:-1] = addition
                else:
                    argv.extend(addition)
                return argv

            result = execute_headless_worker(
                scratchpad=root,
                project_root=project_root,
                run_id=str(config.get("_run_id") or "test-unbound"),
                phase_io_contract=model_io_contract,
                phase_io_launch=model_io_launch,
                prompt=prompt_raw.decode("utf-8", errors="strict"),
                command_builder=command_builder,
                cwd=runtime_cwd,
                environment=env,
                environment_allowlist=environment_allowlist,
                source_snapshot_digest=source_snapshot_sha256,
                methodology_digests=(
                    _dynamic_verifier_method_digest(config),
                ),
                startup_authority_binding=startup_binding,
                provider_stdout_evidence_configuration=(
                    public_claude_arguments.get(
                        "provider_stdout_evidence_configuration"
                    )
                ),
                claude_launch_security=public_claude_arguments.get(
                    "claude_launch_security"
                ),
                claude_launch_security_request=(
                    public_claude_arguments.get(
                        "claude_launch_security_request"
                    )
                ),
                claude_provider_preparation=(
                    None
                    if claude_provider_authority is None
                    else claude_provider_authority.preparation
                ),
                claude_runtime_local_inputs=(
                    None
                    if claude_provider_authority is None
                    else claude_provider_authority.runtime_local_inputs
                ),
                claude_bound_settings_bytes=(
                    None
                    if claude_provider_authority is None
                    else claude_provider_authority.bound_settings_bytes
                ),
                claude_selected_mcp_config_bytes=(
                    None
                    if claude_provider_authority is None
                    else (
                        claude_provider_authority
                        .selected_mcp_config_bytes
                    )
                ),
            )
            log_path.write_bytes(
                _headless_log_bytes(result.stdout, result.stderr)
            )
            return 0
        except (
            HeadlessWorkerRuntimeError,
            auxiliary_root_startup.AuxiliaryWritableRootStartupError,
            OSError,
            UnicodeError,
        ) as exc:
            if isinstance(exc, HeadlessWorkerRuntimeError):
                payload = _headless_log_bytes(exc.stdout, exc.stderr)
                rc = (
                    -2
                    if exc.reason_code == "TIMEOUT"
                    else int(exc.returncode)
                    if exc.returncode is not None
                    else EXIT_ERROR
                )
            else:
                payload = b""
                rc = EXIT_ERROR
            if not payload:
                payload = (
                    "dynamic verifier transactional launch failed: "
                    f"{type(exc).__name__}: {exc}\n"
                ).encode("utf-8")
            log_path.write_bytes(payload)
            return rc
    # All non-PTY verifier launches must carry an exact MODEL transaction.
    # The former direct-Popen fallback could write canonical verifier files
    # without a WorkPlan, process-tree receipt, or pre-incorporation gate.
    log_path.write_text(
        "dynamic verifier non-PTY launch lacks exact transaction authority\n",
        encoding="utf-8",
    )
    return EXIT_ERROR


def _execute_or_replay_dynamic_verifier_model(
    spec: VerifierLaunchSpec,
    *,
    prompt_path: Path,
    log_path: Path,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    model_io_contract: PhaseIOContract,
    model_io_launch: LaunchSpec,
) -> tuple[int, tuple[dict[str, Any], dict[str, Any]] | None]:
    """Continue an incorporated verifier attempt without another provider."""

    replay = _replay_committed_model_worker(
        scratchpad=Path(scratchpad),
        project_root=Path(
            config.get("project_root") or Path(scratchpad).parent
        ),
        run_id=str(config.get("_run_id") or "test-unbound"),
        contract=model_io_contract,
        launch=model_io_launch,
        methodology_digests=(
            _dynamic_verifier_method_digest(config),
        ),
        source_snapshot_digest=(
            _security_obligation_source_snapshot_digest(config)
        ),
    )
    if replay is not None:
        return 0, replay
    return (
        _execute_dynamic_verifier_launch(
            spec,
            prompt_path=prompt_path,
            log_path=log_path,
            scratchpad=scratchpad,
            phase=phase,
            config=config,
            model_io_contract=model_io_contract,
            model_io_launch=model_io_launch,
        ),
        None,
    )


def _run_dynamic_verifier_unit(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
    roster: VerifierWorkRoster,
    unit,
) -> list[str]:
    paths = _dynamic_verifier_unit_paths(scratchpad, unit.work_unit_id)
    control_prebound = False
    existing_issues = _dynamic_verifier_unit_gate_issues(
        scratchpad, phase.name, roster, unit, config
    )
    if not existing_issues:
        return []
    if paths["receipt"].is_file():
        try:
            recorded = VerifierUnitReceipt.from_json(
                paths["receipt"].read_text(encoding="utf-8", errors="strict")
            )
            if recorded.status == "COMPLETED":
                return existing_issues
        except Exception:
            return existing_issues
    try:
        unit_config = dict(config)
        unit_config["_dynamic_verifier_work_unit_id"] = unit.work_unit_id
        unit_config["_dynamic_verifier_work_item_ids"] = tuple(
            unit.ordered_work_item_ids
        )
        unit_config["_dynamic_verifier_manifest"] = str(
            paths["manifest"].relative_to(scratchpad).as_posix()
        )
        bb_policy_work = _prepare_dynamic_verifier_bb_policy(
            Path(scratchpad), config, unit
        )
        method_dispatch = _compile_dynamic_verifier_method_dispatch(
            scratchpad,
            unit_config,
            unit,
            manifest_path=paths["manifest"],
        )
        unit_config["_verification_method_dispatch"] = method_dispatch
        prompt = build_phase_prompt(
            resolve_v1_prompt(str(config.get("pipeline") or "sc")),
            phase,
            unit_config,
        )
        if bb_policy_work is not None:
            prompt += bb_policy_work_prompt_suffix(
                paths["bb_policy_work"].relative_to(
                    scratchpad
                ).as_posix(),
                bb_policy_work,
                application_relative_path=(
                    paths["bb_policy_application"].relative_to(
                        scratchpad
                    ).as_posix()
                ),
            )
        spec = build_verifier_launch_spec(
            roster,
            unit.work_unit_id,
            prompt_bytes=prompt.encode("utf-8"),
            claude_executable=_selected_claude_backend_argv_prefix()[0],
            codex_executable=str(CODEX_BIN),
        )
        if spec.backend == "claude":
            spec = VerifierLaunchSpec(
                **{
                    **{
                        field: getattr(spec, field)
                        for field in spec.__dataclass_fields__
                    },
                    "argv": _replace_claude_executable_with_selected_front(
                        spec.argv
                    ),
                }
            )
        method_model_outputs = tuple(
            name
            for work_id in unit.ordered_work_item_ids
            for name in (
                f"verify_{work_id}.md",
                f"verify_{work_id}.severity_proposal.json",
                f"verify_{work_id}.operator_application.json",
            )
        ) + (
            (
                paths["bb_policy_application"].relative_to(
                    scratchpad
                ).as_posix(),
            )
            if bb_policy_work is not None
            else ()
        )
        method_operator_receipts = tuple(
            f"verify_{work_id}.operator_receipt.json"
            for work_id in unit.ordered_work_item_ids
        )
        (
            prelaunch_io_contract,
            model_io_contract,
            control_io_contract,
        ) = _write_verifier_method_phase_io_contracts(
            directory=paths["directory"],
            scratchpad=Path(scratchpad),
            config=config,
            phase_name=phase.name,
            work_unit_id=unit.work_unit_id,
            model_outputs=method_model_outputs,
            operator_receipts=method_operator_receipts,
            immutable_launch_inputs=(
                paths["manifest"],
                Path(scratchpad) / "verification_context_packets.json",
                *(
                    (paths["bb_policy_work"],)
                    if bb_policy_work is not None
                    else ()
                ),
                paths["method_dispatch"],
                paths["prompt"],
                paths["launch_spec"],
            ),
            shared_immutable_inputs=(
                Path(scratchpad) / "verification_context_packets.json",
                *(
                    (paths["bb_policy_work"],)
                    if bb_policy_work is not None
                    else ()
                ),
            ),
            driver_outputs=(
                paths["method_dispatch"], paths["prompt"], paths["launch_spec"],
                paths["gate"], paths["receipt"], paths["debt"],
            ),
        )
        prelaunch_launch = LaunchSpec(
            work_unit_key=prelaunch_io_contract.key,
            pipeline=prelaunch_io_contract.pipeline,
            mode=prelaunch_io_contract.mode,
            ecosystem=prelaunch_io_contract.ecosystem,
            backend=prelaunch_io_contract.backend,
            model="driver",
            timeout_s=spec.timeout_seconds,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        prelaunch_execute, prelaunch_arm_issues = (
            _arm_deterministic_driver_work_unit(
                scratchpad=Path(scratchpad),
                project_root=Path(
                    config.get("project_root")
                    or Path(scratchpad).parent
                ),
                contract=prelaunch_io_contract,
                launch=prelaunch_launch,
                run_id=str(config.get("_run_id") or "test-unbound"),
            )
        )
        if prelaunch_arm_issues:
            raise ValueError(
                "verifier prelaunch arm invalid: "
                + "; ".join(prelaunch_arm_issues)
            )
        if prelaunch_execute:
            _materialize_dynamic_verifier_manifest(
                scratchpad, unit, paths["manifest"]
            )
            write_or_validate_method_dispatch(
                paths["method_dispatch"], method_dispatch
            )
            paths["directory"].mkdir(parents=True, exist_ok=True)
            paths["prompt"].write_text(
                prompt, encoding="utf-8", newline="\n"
            )
            _atomic_driver_json_record(
                paths["launch_spec"], spec.to_dict()
            )
            _materialize_verifier_method_phase_io_contracts(
                paths["directory"],
                prelaunch_contract=prelaunch_io_contract,
                model_contract=model_io_contract,
                control_contract=control_io_contract,
            )
            prelaunch_commit_issues = (
                _commit_deterministic_driver_work_unit(
                    scratchpad=Path(scratchpad),
                    project_root=Path(
                        config.get("project_root")
                        or Path(scratchpad).parent
                    ),
                    contract=prelaunch_io_contract,
                    launch=prelaunch_launch,
                    run_id=str(
                        config.get("_run_id") or "test-unbound"
                    ),
                    domain_issues=(),
                )
            )
            if prelaunch_commit_issues:
                raise ValueError(
                    "verifier prelaunch commit invalid: "
                    + "; ".join(prelaunch_commit_issues)
                )
        prelaunch_authority_issues = (
            _record_verifier_method_phase_io_authority(
                prelaunch_contract=prelaunch_io_contract,
                model_contract=model_io_contract,
                control_contract=control_io_contract,
                launch_spec=spec,
                scratchpad=Path(scratchpad),
                project_root=Path(
                    config.get("project_root") or Path(scratchpad).parent
                ),
                run_id=str(config.get("_run_id") or "test-unbound"),
                include_outputs=False,
            )
        )
        if prelaunch_authority_issues:
            raise ValueError(
                "verifier prelaunch PhaseIO authority invalid: "
                + "; ".join(prelaunch_authority_issues)
            )
        model_launch = LaunchSpec(
            work_unit_key=model_io_contract.key,
            pipeline=model_io_contract.pipeline,
            mode=model_io_contract.mode,
            ecosystem=model_io_contract.ecosystem,
            backend=model_io_contract.backend,
            model=spec.model,
            timeout_s=spec.timeout_seconds,
            exec_mode=spec.transport,
            tool_policy=("filesystem", "shell", "foreground-only"),
        )
        control_launch = LaunchSpec(
            work_unit_key=control_io_contract.key,
            pipeline=control_io_contract.pipeline,
            mode=control_io_contract.mode,
            ecosystem=control_io_contract.ecosystem,
            backend=control_io_contract.backend,
            model="driver",
            timeout_s=spec.timeout_seconds,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        control_prior = read_artifact_ledger(
            Path(scratchpad)
        ).get("work_units", {}).get(control_io_contract.key)
        if not (
            isinstance(control_prior, Mapping)
            and control_prior.get("execution_state")
            == "INPUTS_BOUND_PREEXECUTION"
        ):
            record_work_unit_inputs(
                Path(scratchpad),
                Path(
                    config.get("project_root")
                    or Path(scratchpad).parent
                ),
                control_io_contract,
                control_launch,
                run_id=str(
                    config.get("_run_id") or "test-unbound"
                ),
            )
        control_input_issues = validate_work_unit_inputs(
            Path(scratchpad),
            Path(
                config.get("project_root")
                or Path(scratchpad).parent
            ),
            control_io_contract,
            control_launch,
            run_id=str(config.get("_run_id") or "test-unbound"),
        )
        if control_input_issues:
            raise ValueError(
                "verifier control preexecution invalid: "
                + "; ".join(control_input_issues)
            )
        control_prebound = True
        rc, committed_model_replay = (
            _execute_or_replay_dynamic_verifier_model(
                spec,
                prompt_path=paths["prompt"],
                log_path=paths["stdio"],
                scratchpad=scratchpad,
                phase=phase,
                config=unit_config,
                model_io_contract=model_io_contract,
                model_io_launch=model_launch,
            )
        )
        if rc != 0:
            reason = (
                "UNTRUSTED_COMPLETION_TRANSPORT"
                if (
                    rc == _UNTRUSTED_COMPLETION_TRANSPORT_RC
                    and spec.backend == "claude"
                    and spec.transport == "pty"
                )
                else "RATE_LIMIT_DEBT"
                if rc == 1
                else "TIMEOUT_DEBT"
                if rc == -2
                else "WORKER_EXECUTION_DEBT"
            )
            debt_receipt = VerifierUnitReceipt.debt_for(
                unit, reason_class=reason
            )
            _persist_dynamic_verifier_unit_receipt(paths["receipt"], debt_receipt)
            _atomic_driver_json_record(
                paths["debt"],
                {
                    "schema_version": (
                        "plamen.verifier_unit_execution_debt.v1"
                    ),
                    "state": "COMPLETED_WITH_DEBT",
                    "work_unit_id": unit.work_unit_id,
                    "affected_work_item_ids": list(
                        unit.ordered_work_item_ids
                    ),
                    "detail": reason,
                    "fallback_action": "RETRY_EXACT_WORK_UNIT",
                },
            )
            return [f"{unit.work_unit_id} exited rc={rc} ({reason})"]
        policy = _resolve_config_execution_policy(config)
        issues = _validate_verifier_outputs_before_receipt(
            Path(scratchpad),
            phase.name,
            min_bytes=100,
            mode=str(config.get("mode") or "core"),
            execution_policy=policy,
            require_severity_proposals=True,
            assigned_work_item_ids=unit.ordered_work_item_ids,
        )
        if issues:
            raise ValueError("; ".join(issues))
        if committed_model_replay is None:
            record_work_unit_artifacts(
                Path(scratchpad),
                Path(
                    config.get("project_root")
                    or Path(scratchpad).parent
                ),
                model_io_contract,
                model_launch,
                run_id=str(config.get("_run_id") or "test-unbound"),
                actor="MODEL",
            )
        model_output_issues = validate_work_unit_artifacts(
            Path(scratchpad),
            Path(
                config.get("project_root")
                or Path(scratchpad).parent
            ),
            model_io_contract,
            model_launch,
            run_id=str(config.get("_run_id") or "test-unbound"),
            actor="MODEL",
        )
        if model_output_issues:
            raise ValueError(
                "verifier model output PhaseIO invalid: "
                + "; ".join(model_output_issues)
            )
        operator_receipt_digests = (
            _bind_dynamic_verifier_operator_receipts(
                scratchpad=Path(scratchpad),
                unit=unit,
                dispatch=method_dispatch,
                launch_digest=spec.digest,
            )
        )
        bb_policy_receipt_digest = ""
        if bb_policy_work is not None:
            bb_policy_receipt_digest = (
                _bind_dynamic_verifier_bb_policy_receipt(
                    scratchpad=Path(scratchpad),
                    config=config,
                    unit=unit,
                    work_projection=bb_policy_work,
                    launch_digest=spec.digest,
                    method_dispatch_path=paths["method_dispatch"],
                )
            )
        _persist_verifier_output_receipts(
            Path(scratchpad),
            phase.name,
            execution_policy=policy,
            launch_digest=spec.digest,
            assigned_work_item_ids=unit.ordered_work_item_ids,
        )
        _written, severity_issues = ensure_shadow_severity_for_shard(
            Path(scratchpad),
            phase.name,
            backend=policy.backend.value,
            launch_digest=spec.digest,
            run_id=str(config.get("_run_id") or "test-unbound"),
            assigned_work_item_ids=unit.ordered_work_item_ids,
        )
        if severity_issues:
            raise ValueError("; ".join(severity_issues))
        issues = _validate_verify_completion(
            Path(scratchpad),
            phase.name,
            min_bytes=100,
            mode=str(config.get("mode") or "core"),
            execution_policy=policy,
            launch_digest=spec.digest,
            assigned_work_item_ids=unit.ordered_work_item_ids,
        )
        if issues:
            raise ValueError("; ".join(issues))
        gate_payload = {
            "schema_version": "plamen.verifier_unit_gate_receipt.v1",
            "state": "CLEAN",
            "work_unit_id": unit.work_unit_id,
            "work_unit_resume_digest": unit.resume_digest,
            "roster_digest": roster.digest,
            "launch_spec_digest": spec.digest,
            "method_dispatch_id": method_dispatch["dispatch_id"],
            "method_dispatch_sha256": hashlib.sha256(
                paths["method_dispatch"].read_bytes()
            ).hexdigest(),
            "ordered_work_item_ids": list(unit.ordered_work_item_ids),
            "operator_receipt_digests": list(
                operator_receipt_digests
            ),
            "output_sha256": {
                name: hashlib.sha256((Path(scratchpad) / name).read_bytes()).hexdigest()
                for name in unit.expected_output_files
            },
        }
        if bb_policy_work is not None:
            gate_payload["bb_policy_receipt_digest"] = (
                bb_policy_receipt_digest
            )
        _atomic_driver_json_record(paths["gate"], gate_payload)
        output_receipt_digests = tuple(
            hashlib.sha256(
                (Path(scratchpad) / f"verify_{work_id}.receipt.json").read_bytes()
            ).hexdigest()
            for work_id in unit.ordered_work_item_ids
        )
        completion = VerifierUnitReceipt.completed_for(
            unit,
            launch_spec_digest=spec.digest,
            output_receipt_digests=output_receipt_digests,
            gate_receipt_digests=(
                hashlib.sha256(paths["gate"].read_bytes()).hexdigest(),
            ),
        )
        _persist_dynamic_verifier_unit_receipt(paths["receipt"], completion)
        _atomic_driver_json_record(
            paths["debt"],
            {
                "schema_version": (
                    "plamen.verifier_unit_execution_debt.v1"
                ),
                "state": "CLEARED",
                "work_unit_id": unit.work_unit_id,
                "affected_work_item_ids": [],
                "detail": "exact verifier work unit completed",
                "fallback_action": "NONE",
            },
        )
        record_work_unit_artifacts(
            Path(scratchpad),
            Path(
                config.get("project_root")
                or Path(scratchpad).parent
            ),
            control_io_contract,
            control_launch,
            run_id=str(config.get("_run_id") or "test-unbound"),
            actor="DRIVER",
        )
        completion_authority_issues = (
            _record_verifier_method_phase_io_authority(
                prelaunch_contract=prelaunch_io_contract,
                model_contract=model_io_contract,
                control_contract=control_io_contract,
                launch_spec=spec,
                scratchpad=Path(scratchpad),
                project_root=Path(
                    config.get("project_root") or Path(scratchpad).parent
                ),
                run_id=str(config.get("_run_id") or "test-unbound"),
                include_outputs=True,
                allow_initialize=False,
            )
        )
        if completion_authority_issues:
            raise ValueError(
                "verifier completion PhaseIO authority invalid: "
                + "; ".join(completion_authority_issues)
            )
        return _dynamic_verifier_unit_gate_issues(
            scratchpad, phase.name, roster, unit, config
        )
    except Exception as exc:
        if control_prebound:
            debt = VerifierUnitReceipt.debt_for(
                unit, reason_class="VALIDATION_DEBT"
            )
            _persist_dynamic_verifier_unit_receipt(paths["receipt"], debt)
            _atomic_driver_json_record(
                paths["debt"],
                {
                    "schema_version": "plamen.verifier_unit_execution_debt.v1",
                    "state": "COMPLETED_WITH_DEBT",
                    "work_unit_id": unit.work_unit_id,
                    "affected_work_item_ids": list(
                        unit.ordered_work_item_ids
                    ),
                    "detail": f"{type(exc).__name__}: {exc}",
                    "fallback_action": "RETRY_EXACT_WORK_UNIT",
                },
            )
        return [
            f"{unit.work_unit_id} validation debt: {type(exc).__name__}: {exc}"
        ]


def _dynamic_verifier_phase_issues(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str] | None:
    """Return roster-aware issues, or None when no roster authority exists."""

    try:
        roster = _load_dynamic_verifier_roster(scratchpad)
    except Exception:
        return None
    tier = _dynamic_verifier_tier_for_phase(phase.name, config)
    if tier is None:
        return []
    issues: list[str] = []
    for unit in roster.work_units:
        if unit.tier_pool == tier:
            issues.extend(
                _dynamic_verifier_unit_gate_issues(
                    scratchpad, phase.name, roster, unit, config
                )
            )
    return issues


def _handle_dynamic_verifier_phase(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    phases: list[Phase],
    *,
    phase_idx: int,
    total_active: int,
) -> bool:
    """Run/skip one legacy verifier phase under the dynamic roster authority."""

    if phase.name not in {*L1_VERIFY_PHASE_NAMES, *SC_VERIFY_PHASE_NAMES}:
        return False
    planner_phase_name = _dynamic_verifier_coordinator_map(config)[
        "critical_high"
    ]
    planner_phase = next(
        (candidate for candidate in phases if candidate.name == planner_phase_name),
        phase,
    )
    outcome = _prepare_dynamic_verifier_roster(
        scratchpad, config, planner_phase
    )
    if outcome.roster is None:
        issues = [
            f"{debt.reason_class}: {debt.detail}" for debt in outcome.debts
        ]
    else:
        roster = outcome.roster
        tier = _dynamic_verifier_tier_for_phase(phase.name, config)
        if tier is None:
            issues = []
        else:
            issues = []
            for unit in roster.work_units:
                if unit.tier_pool != tier:
                    continue
                issues.extend(
                    _run_dynamic_verifier_unit(
                        phase, scratchpad, config, roster, unit
                    )
                )
            _write_dynamic_verifier_status(scratchpad, roster)
    sentinel = Path(scratchpad) / f"{phase.name}.degraded"
    if issues:
        sentinel.write_text(
            "Dynamic verifier roster committed with exact unresolved debt.\n"
            + "\n".join(f"- {issue}" for issue in issues)
            + "\n",
            encoding="utf-8",
        )
        for issue in issues:
            _append_phase_io_debt(
                scratchpad,
                phase.name,
                "DYNAMIC_VERIFIER_DEBT",
                issue,
            )
    else:
        sentinel.unlink(missing_ok=True)
    _commit_verification_transaction(
        phase,
        checkpoint,
        scratchpad,
        config,
        phases,
        clean_transients=not issues,
    )
    detail = (
        f"dynamic roster ({len(issues)} debt item(s))"
        if issues
        else (
            "dynamic roster tier complete"
            if _dynamic_verifier_tier_for_phase(phase.name, config)
            else "dynamic roster compatibility projection"
        )
    )
    display.print_phase_skipped(
        phase_idx + 1, total_active, phase.name, detail
    )
    return True


def _dynamic_verifier_aggregate_issues(
    scratchpad: Path,
    config: dict[str, Any],
) -> tuple[list[str], tuple[str, ...]]:
    try:
        roster = _load_dynamic_verifier_roster(scratchpad)
    except Exception as exc:
        try:
            pending = tuple(read_queue_work_plan(scratchpad).ordered_work_item_ids)
        except Exception:
            # The work plan is an optimization/partitioning authority, not a
            # recall boundary.  If both it and the roster are malformed, keep
            # the complete parseable queue denominator visible instead of
            # silently converting an infrastructure failure into zero debt.
            pending = tuple(
                dict.fromkeys(
                    str(row.get("finding id") or "").strip()
                    for row in parse_verification_queue_rows(scratchpad)
                    if str(row.get("finding id") or "").strip()
                )
            )
        return (
            [
                "dynamic verifier roster unavailable or invalid: "
                f"{type(exc).__name__}: {exc}"
            ],
            pending,
        )
    issues: list[str] = []
    pending_ids: list[str] = []
    coordinators = _dynamic_verifier_coordinator_map(config)
    for unit in roster.work_units:
        unit_issues = _dynamic_verifier_unit_gate_issues(
            scratchpad,
            coordinators[unit.tier_pool],
            roster,
            unit,
            config,
        )
        if unit_issues:
            issues.extend(unit_issues)
            pending_ids.extend(unit.ordered_work_item_ids)
    _status, malformed = _write_dynamic_verifier_status(scratchpad, roster)
    issues.extend(f"malformed unit receipt: {detail}" for detail in malformed)
    return issues, tuple(dict.fromkeys(pending_ids))


_DYNAMIC_VERIFICATION_DEBT_MARKER = (
    "<!-- PLAMEN_DYNAMIC_VERIFICATION_DEBT -->"
)


def _strip_dynamic_verification_debt_projection(markdown: str) -> str:
    """Remove only the DRIVER-owned runtime-debt suffix from an aggregate."""

    prefix, marker, _suffix = str(markdown).partition(
        _DYNAMIC_VERIFICATION_DEBT_MARKER
    )
    if not marker:
        return str(markdown)
    return prefix.rstrip() + "\n"


def _retire_dynamic_verification_debt(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Retire stale visible debt after every exact verifier child succeeds.

    Runtime debt is an additive fallback state, never a sticky verdict.  A
    successful replay therefore removes its JSON/Markdown projections and the
    bounded suffix in ``verify_core.md``.  A live PhaseIO binding is first
    transitioned to ``SUPERSEDED`` while its exact bytes still exist.  Only
    then are the projections removed, so a crash cannot leave an ACTIVE ledger
    row silently pointing at deleted evidence.
    """

    root = Path(scratchpad)
    issues: list[str] = []
    if (root / "_artifact_state.json").is_file():
        try:
            ledger = read_artifact_ledger(root)
            identity = f"scratchpad:{_DYNAMIC_VERIFIER_DEBT_NAME}"
            binding = ledger.get("artifact_bindings", {}).get(identity)
            if isinstance(binding, Mapping) and binding.get("status") == "ACTIVE":
                owner = str(binding.get("owner_key") or "")
                parts = owner.split("/")
                unit = ledger.get("work_units", {}).get(owner)
                if (
                    len(parts) != 6
                    or parts[-2:] != ["verify", "runtime_debt"]
                    or not isinstance(unit, Mapping)
                    or not isinstance(unit.get("input_bindings"), Mapping)
                ):
                    raise ArtifactLedgerError(
                        "runtime-debt ACTIVE binding has no exact retirement authority"
                    )
                exact_inputs: list[str] = []
                for input_identity in unit["input_bindings"]:
                    input_text = str(input_identity)
                    if not input_text.startswith("scratchpad:"):
                        raise ArtifactLedgerError(
                            "runtime-debt retirement encountered a foreign input root"
                        )
                    exact_inputs.append(input_text.split(":", 1)[1])
                contract = resolve_phase_io_contract(
                    pipeline=parts[0],
                    mode=parts[1],
                    ecosystem=parts[2],
                    backend=parts[3],
                    phase="verify",
                    work_unit_id="runtime_debt",
                    exact_inputs=tuple(exact_inputs),
                    exact_outputs=(
                        _DYNAMIC_VERIFIER_DEBT_NAME,
                        "verification_runtime_debt.md",
                    ),
                )
                launch = LaunchSpec(
                    work_unit_key=contract.key,
                    pipeline=contract.pipeline,
                    mode=contract.mode,
                    ecosystem=contract.ecosystem,
                    backend=contract.backend,
                    model="driver",
                    timeout_s=120,
                    exec_mode="python",
                    tool_policy=("filesystem",),
                )
                if (
                    contract.digest != unit.get("contract_digest")
                    or launch.digest != unit.get("launch_digest")
                ):
                    raise ArtifactLedgerError(
                        "runtime-debt retirement contract or launch drifted"
                    )
                record_work_unit_artifacts(
                    root,
                    Path(str(config.get("project_root") or root.parent)),
                    contract,
                    launch,
                    run_id=str(binding.get("run_id") or ""),
                    status="SUPERSEDED",
                    actor="DRIVER",
                )
                retired = read_artifact_ledger(root).get(
                    "artifact_bindings", {}
                ).get(identity)
                if (
                    not isinstance(retired, Mapping)
                    or retired.get("status") != "SUPERSEDED"
                ):
                    raise ArtifactLedgerError(
                        "runtime-debt retirement did not commit SUPERSEDED state"
                    )
        except (ArtifactLedgerError, OSError, ValueError) as exc:
            issues.append(
                "runtime-debt PhaseIO retirement failed: "
                f"{type(exc).__name__}: {exc}"
            )

    # Remove stale user-facing debt after exact verifier success.  If the
    # ledger transition failed, retain its sidecars for diagnosis and let the
    # stale binding fail closed rather than deleting the underlying evidence.
    core_path = root / "verify_core.md"
    if core_path.is_file():
        existing = core_path.read_text(encoding="utf-8", errors="strict")
        cleaned = _strip_dynamic_verification_debt_projection(existing)
        if cleaned != existing:
            _atomic_driver_bytes(core_path, cleaned.encode("utf-8"))
    if issues:
        return issues
    for relative in (
        _DYNAMIC_VERIFIER_DEBT_NAME,
        "verification_runtime_debt.md",
    ):
        (root / relative).unlink(missing_ok=True)
    return []


def _retain_dynamic_verification_debt(
    scratchpad: Path,
    config: Mapping[str, Any],
    issues: Iterable[str],
    pending_ids: Iterable[str],
) -> None:
    pending = tuple(dict.fromkeys(str(value) for value in pending_ids))
    issue_rows = tuple(str(value) for value in issues)
    rows = parse_verification_queue_rows(scratchpad)
    by_id = {(row.get("finding id") or "").strip(): row for row in rows}
    queue_path = Path(scratchpad) / "verification_queue.md"
    queue_sha256 = (
        hashlib.sha256(queue_path.read_bytes()).hexdigest()
        if queue_path.is_file()
        else ""
    )
    plan_path = Path(scratchpad) / "verification_queue.work_plan.json"
    plan_sha256 = (
        hashlib.sha256(plan_path.read_bytes()).hexdigest()
        if plan_path.is_file()
        else ""
    )
    debt_contract: PhaseIOContract | None = None
    debt_launch: LaunchSpec | None = None
    debt_ledger_issue = ""
    # In a live run the retention receipt is itself a typed DRIVER work unit.
    # Isolated unit fixtures may intentionally omit the ledger; production
    # report evidence will refuse an unowned receipt, so this compatibility
    # branch cannot accidentally authorize delivery.
    if (Path(scratchpad) / "_artifact_state.json").is_file():
        try:
            exact_inputs = ["verification_queue.md"]
            if plan_sha256:
                exact_inputs.append("verification_queue.work_plan.json")
            debt_contract = resolve_phase_io_contract(
                pipeline=str(config.get("pipeline") or "sc"),
                mode=str(config.get("mode") or "thorough"),
                ecosystem=str(config.get("language") or "unknown"),
                backend=str(config.get("cli_backend") or "claude"),
                phase="verify",
                work_unit_id="runtime_debt",
                exact_inputs=tuple(exact_inputs),
                exact_outputs=(
                    _DYNAMIC_VERIFIER_DEBT_NAME,
                    "verification_runtime_debt.md",
                ),
            )
            debt_launch = LaunchSpec(
                work_unit_key=debt_contract.key,
                pipeline=debt_contract.pipeline,
                mode=debt_contract.mode,
                ecosystem=debt_contract.ecosystem,
                backend=debt_contract.backend,
                model="driver",
                timeout_s=120,
                exec_mode="python",
                tool_policy=("filesystem",),
            )
            record_work_unit_inputs(
                Path(scratchpad),
                Path(str(config.get("project_root") or Path(scratchpad).parent)),
                debt_contract,
                debt_launch,
                run_id=str(config.get("_run_id") or "test-unbound"),
            )
        except (ArtifactLedgerError, OSError, ValueError) as exc:
            debt_contract = None
            debt_launch = None
            debt_ledger_issue = (
                "typed runtime-debt precommit failed: "
                f"{type(exc).__name__}: {exc}"
            )
    payload = {
        "schema_version": "plamen.verification_runtime_debt.v2",
        "state": "COMPLETED_WITH_DEBT",
        "proof_authority": "NONE",
        "verifier_status": "UNRESOLVED",
        "report_verification_projection": "CONTESTED",
        "run_id": str(config.get("_run_id") or "test-unbound"),
        "queue_artifact": "verification_queue.md",
        "queue_sha256": queue_sha256,
        "queue_work_plan_artifact": (
            "verification_queue.work_plan.json" if plan_sha256 else ""
        ),
        "queue_work_plan_sha256": plan_sha256,
        "pending_work_item_ids": list(pending),
        "pending_queue_rows": [by_id[value] for value in pending if value in by_id],
        "issues": [*issue_rows, *([debt_ledger_issue] if debt_ledger_issue else [])],
        "fallback_action": "HUMAN_REVIEW_OR_RETRY_EXACT_WORK_UNITS",
    }
    payload["receipt_digest"] = hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    _atomic_driver_json_record(
        Path(scratchpad) / _DYNAMIC_VERIFIER_DEBT_NAME, payload
    )
    lines = [
        "# Verification Runtime Debt",
        "",
        "**State**: COMPLETED_WITH_DEBT",
        "**Proof Authority**: NONE",
        "",
        "The candidates below were not granted verifier proof authority. They",
        "remain in the reporting/human-review denominator and MUST NOT be",
        "interpreted as SAFE, REFUTED, or proof-grade verifier output.",
        "",
        "## Pending candidates",
        "",
    ]
    for work_id in pending:
        row = by_id.get(work_id, {})
        lines.append(
            f"- `{work_id}` | proposed severity "
            f"`{row.get('severity', 'Unknown')}` | "
            f"{row.get('title', 'title unavailable')} | Verdict: UNRESOLVED "
            "| Report projection: CONTESTED"
        )
    lines.extend(("", "## Runtime issues", ""))
    lines.extend(f"- {issue}" for issue in issue_rows)
    if debt_ledger_issue:
        lines.append(f"- {debt_ledger_issue}")
    debt_markdown = "\n".join(lines).rstrip() + "\n"
    (Path(scratchpad) / "verification_runtime_debt.md").write_text(
        debt_markdown, encoding="utf-8"
    )
    if debt_contract is not None and debt_launch is not None:
        try:
            record_work_unit_artifacts(
                Path(scratchpad),
                Path(str(config.get("project_root") or Path(scratchpad).parent)),
                debt_contract,
                debt_launch,
                run_id=str(config.get("_run_id") or "test-unbound"),
                actor="DRIVER",
            )
        except (ArtifactLedgerError, OSError, ValueError) as exc:
            # The bytes remain visibly proof-free, but P1-K will reject them as
            # an authority source until the exact transaction can be repaired.
            _append_phase_io_debt(
                Path(scratchpad),
                "verify",
                "VERIFICATION_RUNTIME_DEBT_LEDGER_DEBT",
                f"{type(exc).__name__}: {exc}",
            )
    core_path = Path(scratchpad) / "verify_core.md"
    existing = (
        core_path.read_text(encoding="utf-8", errors="replace")
        if core_path.is_file()
        else "# Verification Aggregate\n\n"
    )
    # Rebuild the bounded suffix on every retry.  Append-once semantics leave
    # old candidates visible when {A,B} narrows to {B}, which is both a report
    # quality defect and an authority mismatch with the current JSON receipt.
    base = _strip_dynamic_verification_debt_projection(existing).rstrip()
    _atomic_driver_bytes(
        core_path,
        (
            base
            + "\n\n"
            + _DYNAMIC_VERIFICATION_DEBT_MARKER
            + "\n\n"
            + debt_markdown
        ).encode("utf-8"),
    )


def _validate_verification_precommit(
    phase: Phase,
    scratchpad: Path,
    config: dict[str, Any],
    phases: list[Phase],
) -> list[str]:
    """Validate the typed verification denominator before parent commit."""
    issues: list[str] = []
    EMPTY_QUEUE = "EMPTY_QUEUE"
    EMPTY_SHARD = "EMPTY_SHARD"
    EMPTY_WORK = "EMPTY_WORK"

    if phase.name in {"verify_queue", "sc_verify_queue"}:
        try:
            plan = read_queue_work_plan(scratchpad)
            if not plan.ordered_work_item_ids:
                _ = EMPTY_QUEUE
        except Exception as exc:
            issues.append(
                "verification queue work plan invalid: "
                f"{type(exc).__name__}: {exc}"
            )
        live_cutover = config.get("_live_verify_queue_cutover_result")
        if isinstance(live_cutover, Mapping):
            live_plan = live_cutover.get("plan")
            if (
                live_cutover.get("safe_to_consume") is not True
                or not isinstance(live_plan, Mapping)
                or live_cutover.get("phase_name") != phase.name
            ):
                issues.append(
                    "live verify-queue cutover result is not consumable"
                )
            else:
                try:
                    from verify_queue_transaction import (
                        validate_live_verify_queue_publication,
                    )

                    live_validation = (
                        validate_live_verify_queue_publication(
                            scratchpad=Path(scratchpad),
                            project_root=Path(config["project_root"]),
                            plan=live_plan,
                            run_id=str(config.get("_run_id") or ""),
                        )
                    )
                    if live_validation.get("safe_to_consume") is not True:
                        issues.extend(
                            "live verify-queue publication: " + str(issue)
                            for issue in (
                                live_validation.get("issues") or (
                                    "publication authority unavailable",
                                )
                            )
                        )
                except Exception as exc:
                    issues.append(
                        "live verify-queue publication validation failed: "
                        f"{type(exc).__name__}: {exc}"
                    )
        else:
            # Compatibility only for isolated legacy fixtures.  Production
            # queue phases set the live cutover result and must not re-enter
            # this mutating routing authority after T9 publication.
            issues.extend(
                _record_typed_verify_queue_routing_artifacts(
                    phase.name, scratchpad, config
                )
            )
        if not issues:
            coordinator_name = _dynamic_verifier_coordinator_map(config)[
                "critical_high"
            ]
            coordinator = next(
                (
                    candidate
                    for candidate in phases
                    if candidate.name == coordinator_name
                ),
                phase,
            )
            try:
                outcome = _prepare_dynamic_verifier_roster(
                    scratchpad, config, coordinator
                )
                if outcome.roster is None:
                    issues.extend(
                        f"dynamic verifier {debt.reason_class}: {debt.detail}"
                        for debt in outcome.debts
                    )
            except Exception as exc:
                issues.append(
                    "dynamic verifier roster materialization failed: "
                    f"{type(exc).__name__}: {exc}"
                )
        return issues

    if phase.name in L1_VERIFY_PHASE_NAMES or phase.name in SC_VERIFY_PHASE_NAMES:
        dynamic_issues = _dynamic_verifier_phase_issues(
            phase, scratchpad, config
        )
        if dynamic_issues is not None:
            return list(dynamic_issues)
        if (Path(scratchpad) / _DYNAMIC_VERIFIER_PLANNING_DEBT_NAME).is_file():
            return [
                "dynamic verifier roster unavailable; exact planning debt retained"
            ]
        try:
            plan = read_queue_work_plan(scratchpad)
            shard = plan.shard(phase.name)
            if not shard.ordered_work_item_ids:
                _ = EMPTY_SHARD
                return issues
            items_by_id = {
                item.work_item_id: item
                for item in _read_typed_queue_work_items(
                    scratchpad / "verification_queue.md"
                )
            }
            receipt_reconciliation = _validate_verifier_output_receipts(
                scratchpad,
                phase.name,
                plan,
                items_by_id,
                execution_policy=_resolve_config_execution_policy(config),
                launch_digest=_resolved_phase_launch_digest(phase, config),
            )
            issues.extend(receipt_reconciliation)
            if not receipt_reconciliation:
                execution_policy = _resolve_config_execution_policy(config)
                issues.extend(
                    validate_shadow_severity_for_shard(
                        scratchpad,
                        phase.name,
                        backend=execution_policy.backend.value,
                        launch_digest=_resolved_phase_launch_digest(
                            phase, config
                        ),
                        run_id=str(config.get("_run_id") or "test-unbound"),
                    )
                )
        except Exception as exc:
            issues.append(
                "verification receipt reconciliation failed: "
                f"{type(exc).__name__}: {exc}"
            )
        return issues

    if phase.name in {"mechanical_verify", "sc_mechanical_verify"}:
        _ = EMPTY_WORK
        for pattern in phase.expected_artifacts:
            if not list(Path(scratchpad).glob(pattern)):
                issues.append(
                    f"mechanical verification output missing before commit: {pattern}"
                )
        manifest = Path(scratchpad) / "mechanical_verify_manifest.md"
        if manifest.is_file():
            text = manifest.read_text(
                encoding="utf-8", errors="replace"
            ).lower()
            total_match = re.search(
                r"\*\*total verify files\*\*\s*:\s*(\d+)", text
            )
            total_work = int(total_match.group(1)) if total_match else None
            unavailable_or_skipped = any(
                int(match.group(1)) > 0
                for match in re.finditer(
                    r"(?im)^\|\s*(?:toolchain_unavailable|skipped)\s*"
                    r"\|\s*(\d+)\s*\|",
                    text,
                )
            )
            explicit_failure = bool(re.search(
                r"(?im)^\s*(?:\*\*)?status(?:\*\*)?\s*:\s*"
                r"(?:skipped|error)\b|\"status\"\s*:\s*\"error\"",
                text,
            ))
            if total_work != 0 and (unavailable_or_skipped or explicit_failure):
                issues.append(
                    "mechanical verification did not establish execution coverage"
                )
        authority = _mechanical_successor_authority_view(scratchpad)
        if authority.get("status") == "DEGRADED":
            authority_issues = list(authority.get("issues") or [])
            if not authority_issues:
                authority_issues = [
                    "mechanical successor authority is degraded without detail"
                ]
            issues.extend(
                "MECHANICAL_SUCCESSOR_AUTHORITY: " + str(issue)
                for issue in authority_issues
            )
        return issues

    issues.append(f"unsupported verification transaction phase: {phase.name}")
    return issues


def _commit_verification_transaction(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    phases: list[Phase],
    *,
    clean_transients: bool,
) -> PhaseCommit:
    """Run verification precommit checks, then use the shared commit authority."""
    if (
        phase.name in L1_VERIFY_PHASE_NAMES or phase.name in SC_VERIFY_PHASE_NAMES
    ) and _dynamic_verifier_phase_issues(
        phase, scratchpad, config
    ) is None and not (
        Path(scratchpad) / _DYNAMIC_VERIFIER_PLANNING_DEBT_NAME
    ).is_file():
        try:
            policy = _resolve_config_execution_policy(config)
            ensure_shadow_severity_for_shard(
                scratchpad,
                phase.name,
                backend=policy.backend.value,
                launch_digest=_resolved_phase_launch_digest(phase, config),
                run_id=str(config.get("_run_id") or "test-unbound"),
            )
        except Exception:
            # The side-effect-free precommit validator below is the sole debt
            # authority.  This best-effort deterministic repair must not create
            # a second state machine or a false debt when tests/backends supply
            # an intentionally synthetic transaction.
            pass
    try:
        issues = _validate_verification_precommit(
            phase, scratchpad, config, phases
        )
    except Exception as exc:
        issues = [
            "verification precommit validator raised: "
            f"{type(exc).__name__}: {exc}"
        ]
    for issue in issues:
        _append_phase_io_debt(
            scratchpad,
            phase.name,
            "VERIFICATION_PRECOMMIT_DEBT",
            issue,
        )
    return _commit_phase_from_disk_debt(
        phase,
        checkpoint,
        scratchpad,
        config,
        phases,
        clean_transients=clean_transients and not issues,
    )


def _retry_receipt_status(
    failures_before: tuple[GateFailure, ...],
    failures_after: tuple[GateFailure, ...],
) -> str:
    """Classify semantic progress; changed bytes alone are never progress."""
    if not failures_after:
        return "CLEARED"
    before = {failure.gate_id: failure for failure in failures_before}
    after = {failure.gate_id: failure for failure in failures_after}
    before_ids = set(before)
    after_ids = set(after)
    if after_ids < before_ids:
        return "PROGRESSED"
    if not after_ids.issubset(before_ids):
        return "FAILED"
    for gate_id in sorted(after_ids):
        old = before[gate_id]
        new = after[gate_id]
        if (
            old.denominator_count is not None
            and new.denominator_count is not None
            and new.denominator_count < old.denominator_count
        ):
            return "PROGRESSED"
        if len(new.affected_identities) < len(old.affected_identities):
            return "PROGRESSED"
    return "NO_PROGRESS"


def _write_retry_receipt(scratchpad: Path, receipt: RetryReceipt) -> Path:
    safe_work_unit = re.sub(r"[^A-Za-z0-9_.-]+", "_", receipt.work_unit_id)
    directory = Path(scratchpad) / "_retry_receipts" / receipt.phase_name
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / f"{safe_work_unit}.attempt{receipt.attempt}.json"
    payload = json.dumps(receipt.to_dict(), indent=2, sort_keys=True) + "\n"
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(payload, encoding="utf-8")
    os.replace(tmp, path)
    return path


def _write_retry_plan(
    scratchpad: Path,
    checkpoint: Checkpoint,
    phase: Phase,
    config: dict,
    failures: tuple[GateFailure, ...],
    *,
    attempt: int,
) -> Path:
    """Persist the semantic contract the retry prompt must carry in-band."""
    if not checkpoint.run_id:
        raise RuntimeError("retry plan requires checkpoint run_id")
    path = Path(scratchpad) / f"{phase.name}_retry_plan.json"
    payload = {
        "schema": "plamen.retry-plan/v1",
        "run_id": checkpoint.run_id,
        "phase_name": phase.name,
        "work_unit_id": "phase",
        "attempt": attempt,
        "input_digest": _resolved_phase_input_digest(phase, config),
        "output_digest_before": _resolved_phase_artifact_digest(
            phase, scratchpad, config["project_root"]
        ),
        "contract_digest": _resolved_phase_contract_digest(phase, config),
        "launch_digest": _resolved_phase_launch_digest(phase, config),
        "required_output_schema": [
            {
                "pattern": pattern,
                "minimum_bytes": phase.min_artifact_bytes,
                "minimum_count": phase.min_artifacts_count,
            }
            for pattern in phase.expected_artifacts
        ],
        "failed_predicates": [failure.to_dict() for failure in failures],
        "semantic_retry": any(
            failure.gate_class not in {
                "ARTIFACT_PRESENCE", "ADVISORY_QUALITY"
            }
            for failure in failures
        ),
    }
    tmp = path.with_suffix(".json.tmp")
    tmp.write_text(
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    os.replace(tmp, path)
    return path


def _build_retry_receipt(
    *,
    checkpoint: Checkpoint,
    phase: Phase,
    config: dict,
    scratchpad: Path,
    attempt: int,
    failures_before: tuple[GateFailure, ...],
    failures_after: tuple[GateFailure, ...],
    output_digest_before: str,
    output_digest_after: str,
    work_unit_id: str = "phase",
) -> RetryReceipt:
    if not checkpoint.run_id:
        raise RuntimeError("retry receipt requires checkpoint run_id")
    hint = _read_retry_hint(scratchpad, phase.name)
    prompt_digest = _stable_payload_digest({
        "phase": phase.name,
        "work_unit_id": work_unit_id,
        "retry_hint": hint,
        "failed_gate_ids": [failure.gate_id for failure in failures_before],
    })
    before_predicate = _stable_payload_digest([
        {
            "gate_id": failure.gate_id,
            "predicate_digest": failure.predicate_digest,
            "affected": list(failure.affected_identities),
            "denominator_count": failure.denominator_count,
            "denominator_digest": failure.denominator_digest,
        }
        for failure in failures_before
    ])
    after_predicate = _stable_payload_digest([
        {
            "gate_id": failure.gate_id,
            "predicate_digest": failure.predicate_digest,
            "affected": list(failure.affected_identities),
            "denominator_count": failure.denominator_count,
            "denominator_digest": failure.denominator_digest,
        }
        for failure in failures_after
    ])
    denominator_counts = [
        failure.denominator_count for failure in failures_before
        if failure.denominator_count is not None
    ]
    denominator_digests = sorted({
        failure.denominator_digest for failure in failures_before
        if failure.denominator_digest
    })
    quarantine = Path(scratchpad) / "_retry_quarantine" / phase.name
    lineage_paths = [
        str(path.relative_to(scratchpad)).replace("\\", "/")
        for path in sorted(quarantine.rglob("*"))
        if path.is_file()
    ] if quarantine.exists() else []
    if phase.name == "instantiate":
        history_root = Path(scratchpad) / "_attempt_history" / "instantiate"
        if history_root.exists():
            lineage_paths.extend(
                str(path.relative_to(scratchpad)).replace("\\", "/")
                for path in sorted(history_root.rglob("*"))
                if path.is_file()
            )
    lineage = tuple(dict.fromkeys(lineage_paths))
    schema_ids = sorted({failure.schema_id for failure in failures_before})
    schema_versions = [failure.schema_version for failure in failures_before]
    return RetryReceipt(
        run_id=str(checkpoint.run_id),
        phase_name=phase.name,
        work_unit_id=work_unit_id,
        attempt=attempt,
        status=_retry_receipt_status(failures_before, failures_after),
        failure_instance_ids_before=tuple(
            failure.failure_instance_id for failure in failures_before
        ),
        failure_instance_ids_after=tuple(
            failure.failure_instance_id for failure in failures_after
        ),
        gate_ids_before=tuple(failure.gate_id for failure in failures_before),
        gate_ids_after=tuple(failure.gate_id for failure in failures_after),
        schema_id="+".join(schema_ids) or "phase-gate/v1",
        schema_version=max(schema_versions or [1]),
        denominator_count=(sum(denominator_counts) if denominator_counts else None),
        denominator_digest=_stable_payload_digest(denominator_digests),
        input_digest=_resolved_phase_input_digest(phase, config),
        output_digest_before=output_digest_before,
        output_digest_after=output_digest_after,
        predicate_digest_before=before_predicate,
        predicate_digest_after=after_predicate,
        repair_owner=phase.name,
        prompt_digest=prompt_digest,
        launch_digest=_resolved_phase_launch_digest(phase, config),
        contract_digest=_resolved_phase_contract_digest(phase, config),
        quarantine_lineage=lineage,
        created_at=datetime.now(timezone.utc).isoformat(),
    )


def _commit_content_with_gate_debt(
    phase: Phase,
    config: dict,
    scratchpad: Path,
    checkpoint: Checkpoint,
    original_issues: list[str],
) -> "list[str] | None":
    """Continue haltlessly only by preserving the original semantic debt.

    Content presence proves that downstream has an input; it does not prove the
    failed identity, methodology, evidence, containment, disposition, or
    delivery predicate.  When content is usable, this records
    COMPLETED_WITH_DEBT and leaves retry/quarantine evidence intact.  Genuine
    content failures are returned to the caller and retain the halt path.
    """
    content_issues = _phase_content_gate_issues(
        phase, config, scratchpad, config["project_root"]
    )
    if content_issues:
        return list(content_issues)
    contract_digest = _resolved_phase_contract_digest(phase, config)
    output_digest = _resolved_phase_artifact_digest(
        phase, scratchpad, config["project_root"]
    )
    failures = _gate_failures_from_issues(
        phase,
        list(original_issues),
        contract_digest=contract_digest,
        output_digest=output_digest,
        scratchpad=scratchpad,
        allowed_fallback="",
        input_digest=_resolved_phase_input_digest(phase, config),
    )
    log.warning(
        f"[{phase.name}] degraded on retry-hint/quality gate but artifacts pass "
        "the content gate on re-check - continuing with durable semantic debt"
    )
    PhaseCommitController(
        checkpoint, scratchpad, config["project_root"], config
    ).commit(
        phase,
        "COMPLETED_WITH_DEBT",
        failures,
        clean_transients=False,
    )
    return None


def _inventory_has_usable_findings(scratchpad: Path, min_blocks: int = 3) -> bool:
    """True when findings_inventory.md holds enough parseable finding blocks to
    feed downstream phases (chain/verify/report).

    Used by the inventory degrade-and-continue branch: a STRUCTURE /
    field-completeness gate failure on an inventory that nonetheless contains
    >= `min_blocks` usable finding blocks is a quality shortfall, not a
    catastrophe — downstream phases can still operate. A missing/near-empty
    inventory (0 blocks) still funnels to the critical-halt path.
    """
    inv_path = scratchpad / "findings_inventory.md"
    try:
        if not inv_path.exists():
            return False
        text = inv_path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return False
    if len(text.strip()) < 500:
        return False
    try:
        return len(_inventory_blocks(text)) >= min_blocks
    except Exception:
        return False


def _inventory_degrade_floor_ok(scratchpad: Path) -> bool:
    """B2 verify graceful fallback: decide the inventory degrade branch.

    Returns True (degrade-and-continue, NEVER terminal halt) when either:

      * the inventory already holds usable finding blocks, OR
      * the B1 floor can reconstruct a structurally valid inventory from the
        completed breadth/depth/chunk artifacts. The floor is honest: it only
        carries forward findings that actually exist (never fabricates), and a
        genuinely empty audit (0 findings anywhere) still yields a valid empty
        inventory, not a crash.

    `ensure_findings_inventory_floor` is a NO-OP when a real inventory already
    exists, so calling it here cannot clobber a good inventory or invent
    findings. The only path that should NOT reach this branch is one where the
    floor itself raised — in which case we return False and let the caller fall
    through to the critical-halt diagnostics so the failure is surfaced, not
    silently swallowed.
    """
    if _inventory_has_usable_findings(scratchpad):
        return True
    try:
        n_findings, n_sources = ensure_findings_inventory_floor(scratchpad)
    except Exception as exc:
        log.error(f"[inventory] floor reconstruction raised: {exc}")
        return False
    inv_path = scratchpad / "findings_inventory.md"
    if not inv_path.exists():
        # Floor must always write a file (even the empty path); absence means an
        # unexpected failure — surface it via the critical-halt path.
        return False
    if n_findings > 0:
        log.warning(
            f"[inventory] degraded with no usable inventory on disk; floor "
            f"reconstructed {n_findings} finding(s) from {n_sources} source "
            "artifact(s) -- degrading and continuing (verification proceeds on "
            "the honest reconstructed inventory)"
        )
    else:
        log.warning(
            f"[inventory] degraded and {n_sources} source artifact(s) yielded "
            "0 findings (genuinely empty audit); wrote a valid empty inventory "
            "-- degrading and continuing"
        )
    return True


_BODY_CONTENT_RETRY_CAP = 2


def _body_content_retry_path(scratchpad: Path, phase_name: str) -> Path:
    return scratchpad / f".{phase_name}.content_retry"


def _body_content_retry_exhausted(scratchpad: Path, phase_name: str) -> bool:
    """Bucket 3: True once the bounded productive content-retry budget for a
    body-writer phase is spent, so content shortfall stops triggering retries
    and the phase WARN-ships its current (best-effort) sections."""
    try:
        return int(_body_content_retry_path(scratchpad, phase_name).read_text(encoding="utf-8")) >= _BODY_CONTENT_RETRY_CAP
    except Exception:
        return False


def _bump_body_content_retry(scratchpad: Path, phase_name: str) -> None:
    p = _body_content_retry_path(scratchpad, phase_name)
    try:
        n = int(p.read_text(encoding="utf-8"))
    except Exception:
        n = 0
    try:
        p.write_text(str(n + 1), encoding="utf-8")
    except Exception:
        pass


def _body_content_retry_hint(phase_name: str, content_short: list) -> str:
    """Delta-injected (convergent) retry hint: names the specific thin sections
    so the body-writer enriches THEM, never an identical re-prompt (LLM-8)."""
    return (
        f"## Body content quality retry for {phase_name}\n\n"
        "The previous attempt shipped section(s) with a thin or missing "
        "**Impact** or **PoC Result**. Enrich ONLY the sections listed below with "
        "concrete, specific detail tied to the verifier evidence (or, for a "
        "genuinely minor Low/Info one-liner with no security nuance, move it to "
        "the `## Quality Observations` megasection). Do NOT pad with boilerplate "
        "and do NOT alter any other section.\n\n"
        "Sections needing enrichment:\n"
        + "\n".join(f"- {c}" for c in content_short[:20])
        + "\n"
    )


def _record_phase_cost(scratchpad: Path, phase_name: str, model: str,
                       attempt: int, stdio_log: Path, duration_s: float,
                       backend: str = "claude") -> None:
    """Parse the claude -p JSON envelope for cost + append to a ledger.

    Pure observability. Does not affect pipeline decisions. Envelope
    fields captured when present: total_cost_usd, num_turns, duration_ms,
    stop_reason, is_error.
    """
    ledger_path = scratchpad / "_v2_cost_ledger.md"
    try:
        if not stdio_log.exists():
            return
        with stdio_log.open("rb") as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - 32768))
            tail = f.read().decode("utf-8", errors="replace")
        fields: dict[str, Any] = {}
        if backend == "codex":
            parsed = _parse_codex_output(stdio_log, model=model)
            fields["total_cost_usd"] = f"{parsed.get('cost_usd', 0):.4f}"
            fields["stop_reason"] = "error" if parsed.get("error") else "end"
            fields["is_error"] = bool(parsed.get("error"))
            # _parse_codex_output accumulates input/output tokens separately
            # from turn.completed usage dicts in the JSONL stream.
            fields["input_tokens"] = parsed.get("input_tokens", 0) or "?"
            fields["output_tokens"] = parsed.get("output_tokens", 0) or "?"
            # Count turns from JSONL
            num_turns = 0
            try:
                for line in tail.splitlines():
                    if '"turn.completed"' in line:
                        num_turns += 1
            except Exception:
                pass
            fields["num_turns"] = num_turns or 1
        elif backend == "claude-pty":
            fields.update(parse_transcript_usage(stdio_log))
        else:
            envelope = _extract_json_envelope(tail)
            if envelope:
                for key in ("total_cost_usd", "num_turns", "stop_reason",
                            "is_error", "api_error_status"):
                    if key in envelope:
                        fields[key] = envelope[key]
                # Cache metrics — essential for measuring whether prompt caching
                # is already helping us (cache_read = cheap hits at 0.1x input
                # price; cache_creation = one-time writes at 1.25x input).
                # claude-cli exposes these via the `usage` field in the JSON
                # envelope (Anthropic API convention).
                usage = envelope.get("usage") or {}
                if isinstance(usage, dict):
                    for key in ("input_tokens", "output_tokens",
                                "cache_read_input_tokens",
                                "cache_creation_input_tokens"):
                        if key in usage:
                            fields[key] = usage[key]
        # First write: create header row with cache columns
        if not ledger_path.exists():
            ledger_path.write_text(
                "# Phase Cost Ledger\n\n"
                "Cache columns explain where money went:\n"
                "- InTok = raw input tokens billed at 1x\n"
                "- OutTok = output tokens billed at 5x (sonnet)\n"
                "- CacheRd = input tokens served from cache at 0.1x (savings)\n"
                "- CacheWr = input tokens written to cache at 1.25x (one-time)\n"
                "- TotalInTok = InTok + CacheRd + CacheWr (Anthropic long-context threshold: 200k)\n"
                "- LongCtx = ⚠️ when TotalInTok > 200k (long-context pricing tier applies)\n"
                "- High CacheRd / TotalInTok ratio = good cache reuse\n\n"
                "| Phase | Attempt | Model | Dur(s) | Cost(USD) | Turns | "
                "InTok | OutTok | CacheRd | CacheWr | TotalInTok | LongCtx | "
                "CacheHit% | StopReason | Err |\n"
                "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n",
                encoding="utf-8",
            )
        cost = fields.get("total_cost_usd", "?")
        turns = fields.get("num_turns", "?")
        stop = fields.get("stop_reason", "?")
        err = fields.get("is_error", False)
        api_err = fields.get("api_error_status")
        err_s = f"{api_err}" if api_err else ("true" if err else "")
        in_tok = fields.get("input_tokens", "?")
        out_tok = fields.get("output_tokens", "?")
        cache_rd = fields.get("cache_read_input_tokens", 0)
        cache_wr = fields.get("cache_creation_input_tokens", 0)
        # Compute total input tokens (InTok + CacheRd + CacheWr) — this is
        # what Anthropic compares against the 200k long-context threshold.
        try:
            total_in = int(in_tok) + int(cache_rd) + int(cache_wr)
            long_ctx = "⚠️" if total_in > 200000 else ""
            total_in_s = str(total_in)
        except Exception:
            total_in = None
            long_ctx = ""
            total_in_s = "?"
        # Compute cache hit % against TotalInTok denominator (matches the
        # header doc and is the meaningful reuse ratio).
        try:
            if total_in is not None and total_in > 0:
                cache_hit_pct = f"{100.0 * int(cache_rd) / total_in:.0f}%"
            else:
                cache_hit_pct = "?"
        except Exception:
            cache_hit_pct = "?"
        with ledger_path.open("a", encoding="utf-8") as f:
            f.write(
                f"| {phase_name} | {attempt} | {model} | "
                f"{duration_s:.0f} | {cost} | {turns} | "
                f"{in_tok} | {out_tok} | {cache_rd} | {cache_wr} | "
                f"{total_in_s} | {long_ctx} | "
                f"{cache_hit_pct} | {stop} | {err_s} |\n"
            )
    except Exception:
        # Telemetry must never break the pipeline.
        pass


def _restore_tier_body_from_overflow(scratchpad: Path, phase_name: str) -> bool:
    """Recover a valid tier body quarantined by an older containment pass."""
    if not re.match(r"^report_(critical_high|medium|low_info)(?:_[a-z])?$", phase_name):
        return False
    dest = scratchpad / f"{phase_name}.md"
    overflow = scratchpad / "_overflow"
    if not overflow.exists():
        return False
    candidates = sorted(
        overflow.glob(f"**/{phase_name}.md"),
        key=lambda p: p.stat().st_mtime if p.exists() else 0,
        reverse=True,
    )
    for src in candidates:
        try:
            if not src.exists() or src.stat().st_size <= 100:
                continue
            shutil.copy2(src, dest)
            if _validate_tier_body_against_manifest(scratchpad, phase_name):
                dest.unlink(missing_ok=True)
                continue
            return True
        except Exception as exc:
            log.warning(f"[{phase_name}] overflow restore failed for {src}: {exc!r}")
    return False


def _extract_json_envelope(tail_text: str) -> Optional[dict]:
    """Find the terminal Claude result or legacy JSON envelope in log text.

    Modern transactional workers emit NDJSON and may legally emit a small
    provider progress row (currently ``prompt_suggestion``) after the result.
    Prefer the last top-level ``type == "result"`` row.  The backward brace
    scan remains only for legacy ``--output-format json`` compatibility.
    This helper is telemetry/rate-limit compatibility code, never completion
    authority; the receipt layer replays the strict byte stream separately.
    """
    for raw_line in reversed(tail_text.splitlines()):
        line = raw_line.strip()
        if not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            event = json.loads(line)
        except Exception:
            continue
        if isinstance(event, dict) and event.get("type") == "result":
            return event

    # Scan backward for `{` then try to json.loads progressively.
    # Practical heuristic: the envelope is at the very end (or very near it)
    # and is well-formed. Try the last 64KB first.
    for end_marker in ("\n}\n", "}\n", "}"):
        idx = tail_text.rfind(end_marker)
        if idx == -1:
            continue
        # Find matching opening brace
        depth = 0
        for i in range(idx, -1, -1):
            ch = tail_text[i]
            if ch == "}":
                depth += 1
            elif ch == "{":
                depth -= 1
                if depth == 0:
                    candidate = tail_text[i:idx + len(end_marker)]
                    try:
                        return json.loads(candidate)
                    except Exception:
                        break
    return None


def _detect_rate_limit_jsonl_tail(tail_text: str) -> bool:
    """Detect rate limits in Claude Code session JSONL events."""
    for line in tail_text.splitlines()[-200:]:
        line = line.strip()
        if not line.startswith("{"):
            continue
        try:
            event = json.loads(line)
        except Exception:
            continue
        if isinstance(event, dict) and event_is_rate_limited(event):
            return True
    return False


def detect_rate_limit(stdio_log: Path, tail_bytes: int = 65536) -> bool:
    """Return True iff an actual API rate limit is detected.

    Strategy:
    1. Read the last ~64KB of the stdio log.
    2. Try to parse a JSON envelope. If found, check structured fields
       (`is_error`, `api_error_status`, error `type`).
    3. If no JSON envelope (crash pre-envelope), fall back to a STRUCTURED
       text regex that requires an HTTP status or API error prefix. Plain
       LLM prose no longer triggers.
    """
    if not stdio_log.exists():
        return False
    try:
        with stdio_log.open("rb") as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - tail_bytes))
            tail = f.read().decode("utf-8", errors="replace")
    except Exception:
        return False

    if "PLAMEN_RATE_LIMIT_DETECTED=1" in tail:
        return True

    envelope = _extract_json_envelope(tail)
    if envelope is not None:
        # Structured path: trust only fields, ignore prose.
        if event_is_rate_limited(envelope):
            return True
        if envelope.get("is_error") is True:
            status = envelope.get("api_error_status")
            try:
                status_code = int(status)
            except Exception:
                status_code = None
            if status_code in _API_RATE_LIMIT_STATUSES:
                return True
            err = envelope.get("error") or {}
            if isinstance(err, dict):
                err_type = (err.get("type") or "").lower()
                if "rate_limit" in err_type or "overloaded" in err_type:
                    return True
        stop_reason = (envelope.get("stop_reason") or "").lower()
        if stop_reason in ("rate_limited", "rate_limit", "overloaded"):
            return True
        terminal_reason = (envelope.get("terminal_reason") or "").lower()
        if "rate" in terminal_reason and "limit" in terminal_reason:
            return True
        # Envelope parsed cleanly, no structured rate-limit signal → NOT
        # rate-limited. Do NOT fall through to text regex — that's the
        # false-positive path.
        if _detect_rate_limit_jsonl_tail(tail):
            return True
        return False

    # Envelope not parseable (subprocess likely crashed pre-envelope).
    # Use strict text regex: requires structured error prefix.
    if _detect_rate_limit_jsonl_tail(tail):
        return True
    if text_shows_rate_limit(tail):
        return True
    return bool(_STRUCTURED_RATE_LIMIT_RE.search(tail))


_NOT_LOGGED_IN_RE = re.compile(
    r"not\s+logged\s+in|/login|please\s+log\s+in|"
    r"run\s+`?claude`?\s+(?:interactively\s+)?to\s+(?:log\s*in|authenticate)",
    re.IGNORECASE,
)


def detect_not_logged_in(stdio_log: Path, tail_bytes: int = 65536) -> bool:
    """Return True iff the `claude` CLI emitted an authentication error (v2.0.1).

    An unauthenticated `claude -p` returns rc=0 (or rc!=0 on newer builds) with a
    "Not logged in" / "/login" message; without this the driver retries the same
    unauthenticated CLI and degrades the phase, masking the real cause.
    """
    if not stdio_log.exists():
        return False
    try:
        with stdio_log.open("rb") as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - tail_bytes))
            tail = f.read().decode("utf-8", errors="replace")
    except Exception:
        return False
    return bool(_NOT_LOGGED_IN_RE.search(tail))


# ── 529 overload (transient provider overload) ──────────────────────────────
#
# A 529 / `overloaded_error` is Anthropic being temporarily overloaded
# provider-wide. It is NOT the user's account rate/usage cap (429 / "weekly
# limit"). `detect_rate_limit` returns True for BOTH (the structured paths and
# the regexes cover 429+529 alike). `detect_overloaded` narrows to the 529
# class so the depth-retry path can give transient overloads short-backoff
# retries BEFORE ever surfacing the usage-cap pause panel. Genuine 429s skip
# this path entirely and keep their existing long-wait + pause behavior.

# Short exponential backoff schedule for transient 529 overloads (seconds).
# Capped at ~3 min per the design; >=4 attempts before any pause is surfaced.
_OVERLOAD_BACKOFF_SCHEDULE_S = (30, 60, 120, 180)


def _detect_overloaded_jsonl_tail(tail_text: str) -> bool:
    """Detect 529/overloaded signals in Claude Code session JSONL events."""
    for line in tail_text.splitlines()[-200:]:
        line = line.strip()
        if not line.startswith("{"):
            continue
        try:
            event = json.loads(line)
        except Exception:
            continue
        if isinstance(event, dict) and event_is_overloaded(event):
            return True
    return False


def detect_overloaded(stdio_log: Path, tail_bytes: int = 65536) -> bool:
    """Return True iff a transient 529 / `overloaded_error` is detected.

    Strict subset of `detect_rate_limit`: matches ONLY the 529/overload class,
    never the 429 usage-cap class. Same envelope-first/text-fallback strategy.
    """
    if not stdio_log.exists():
        return False
    try:
        with stdio_log.open("rb") as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - tail_bytes))
            tail = f.read().decode("utf-8", errors="replace")
    except Exception:
        return False

    envelope = _extract_json_envelope(tail)
    if envelope is not None:
        # Structured path: trust only fields.
        if event_is_overloaded(envelope):
            return True
        if envelope.get("is_error") is True:
            status = envelope.get("api_error_status")
            try:
                status_code = int(status)
            except Exception:
                status_code = None
            if status_code == 529:
                return True
            err = envelope.get("error") or {}
            if isinstance(err, dict):
                err_type = (err.get("type") or "").lower()
                if "overloaded" in err_type:
                    return True
        stop_reason = (envelope.get("stop_reason") or "").lower()
        if stop_reason == "overloaded":
            return True
        if _detect_overloaded_jsonl_tail(tail):
            return True
        return False

    # Envelope not parseable.
    if _detect_overloaded_jsonl_tail(tail):
        return True
    return bool(text_shows_overloaded(tail))


def overload_backoff_plan(
    attempts_so_far: int,
    *,
    max_attempts: int = len(_OVERLOAD_BACKOFF_SCHEDULE_S),
    schedule: tuple[int, ...] = _OVERLOAD_BACKOFF_SCHEDULE_S,
) -> tuple[bool, int]:
    """Pure decision helper for 529 overload handling (unit-testable).

    `attempts_so_far` = number of short-backoff overload retries ALREADY made
    for this phase (0 before the first retry).

    Returns ``(should_retry, wait_seconds)``:
    - If more overload retries remain → ``(True, <backoff for this attempt>)``.
    - If the overload budget is exhausted → ``(False, 0)`` and the caller MUST
      fall back to the existing pause-for-resume path (haltless floor).
    """
    if attempts_so_far < 0:
        attempts_so_far = 0
    if attempts_so_far >= max_attempts:
        return False, 0
    idx = min(attempts_so_far, len(schedule) - 1)
    return True, schedule[idx]


def _overload_sleep_seconds(wait_s: int) -> int:
    """Resolve the actual sleep length for a 529 backoff step.

    In tests the env var PLAMEN_OVERLOAD_BACKOFF_TEST_S forces a short sleep so
    real wall-clock backoff never runs in the suite. Production uses the real
    schedule value.
    """
    override = os.environ.get("PLAMEN_OVERLOAD_BACKOFF_TEST_S")
    if override:
        try:
            return max(0, int(override))
        except Exception:
            return 0
    return max(0, int(wait_s))


def _append_rate_limit_sentinel(
    stdio_log: Path,
    *,
    phase_name: str,
    source: str,
) -> None:
    """Stamp a phase log with a structured rate-limit marker.

    Worker-pool phases can detect rate limits inside child PTYs even when the
    child transcript tail does not include a parseable Anthropic JSON envelope.
    The outer retry loop only inspects the aggregate `_stdio_<phase>.log`, so
    every internal rate-limit rc must be surfaced there in a structured form.
    """
    try:
        with stdio_log.open("a", encoding="utf-8", errors="replace") as f:
            f.write(
                "\nPLAMEN_RATE_LIMIT_DETECTED=1 "
                "api_error_status=429 "
                "type=rate_limit_error "
                f"phase={phase_name} "
                f"source={source}\n"
            )
    except Exception:
        pass


# v2.0.3 (A2): orphaned-background-agent detection. The LLM uses Task with
# run_in_background:true on multiple agents, then end_turn — agents are
# killed when the subprocess exits, leaving WRITE-THEN-VERIFY reservation
# headers on disk. Detection runs post-subprocess; writes a diagnostic file
# that the retry-hint dispatcher (A4) consumes. Does NOT affect gate
# pass/fail (substance gate from Stage 1.5 is the authority).
_PLAMEN_STUB_HEADER_RE = re.compile(
    r"\A\s*#+\s+[^\n]{1,80}\s*\n?\s*\Z",
    re.MULTILINE,
)


def _is_header_only_stub(path: Path, max_bytes: int = 120) -> bool:
    """True iff `path` is a header-only file (≤120 bytes containing only a
    single markdown heading). This is the orphan-background fingerprint:
    the WRITE-THEN-VERIFY reservation header reached disk; full content
    never did.
    """
    try:
        size = path.stat().st_size
        if size == 0 or size > max_bytes:
            return False
        content = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return bool(_PLAMEN_STUB_HEADER_RE.match(content))


def _resolve_never_cut_targets(scratchpad: Path, phase_name: str,
                                 mode: str, pipeline: str) -> list[str]:
    """Return the flat list of canonical artifact filenames that the phase
    is expected to produce per the never-cut groups (any-of groups are
    collapsed to the first canonical name). Used by the orphan detector to
    enumerate which files to scan for stub fingerprints — works around
    `Phase.expected_artifacts=["depth_*_findings.md"]` (a glob, not an
    enumeration) per Codex Round-1 Claim 5.
    """
    if phase_name != "depth":
        return []
    try:
        if pipeline == "l1":
            groups = l1_never_cut_groups(mode)
        else:
            groups = sc_never_cut_groups(mode)
    except Exception:
        return []
    # any-of group: pick the first canonical name (e.g.
    # ["validation_sweep_findings.md", "scanner_validation_findings.md"]
    # collapses to "validation_sweep_findings.md").
    return [group[0] for group in groups if group]


def _slugify_cwd_for_transcript(project_root: str) -> str:
    """v2.0.5 (B1): convert a project root path to the Claude Code
    transcript directory slug. Claude Code stores per-session transcript
    JSONL files at `~/.claude/projects/{slug}/{session_id}.jsonl` where
    the slug replaces path separators, the drive colon, AND spaces with
    dashes (verified empirically against
    `~/.claude/projects/D--Programming-Web3-Contests-Example-Protocol-...`).

    Example: ``D:\\Programming\\X Audit\\repo`` →
    ``D--Programming-X-Audit-repo``.
    """
    s = str(project_root)
    # Drive letter + colon → drive letter + double-dash
    s = re.sub(r"^([A-Za-z]):", r"\1-", s)
    # Path separators (\, /) AND whitespace → dash
    s = re.sub(r"[\\/\s]+", "-", s)
    return s


def _find_transcript_jsonl(project_root: str) -> Optional[Path]:
    """v2.0.5 (B1): locate the most recent Claude Code transcript JSONL
    for the given project root. Returns None if not discoverable.

    Multiple session files may exist per project (one per `claude -p`
    invocation). The most recent file by mtime is the one corresponding
    to the just-finished subprocess.
    """
    slug = _slugify_cwd_for_transcript(project_root)
    candidates = (
        Path.home() / ".claude" / "projects" / slug,
        plamen_home().parent / "projects" / slug,
    )
    for parent in candidates:
        if not parent.is_dir():
            continue
        files = sorted(parent.glob("*.jsonl"),
                       key=lambda p: p.stat().st_mtime, reverse=True)
        if files:
            return files[0]
    return None


# v2.0.5 (B1): Claude Code's Task tool surfaces as either name="Task"
# (older transcripts) or name="Agent" (newer Claude Code releases).
# Both must be scanned for the orphan fingerprint.
_TRANSCRIPT_TASK_NAMES = ("Task", "Agent")


def _walk_transcript_tool_uses(obj: Any, out: list[dict]) -> None:
    """v2.0.5 (B1): iterative walk over a parsed JSONL entry collecting
    every nested `tool_use` whose name is in `_TRANSCRIPT_TASK_NAMES`
    (Task | Agent). Mutates `out` in place — module-level so the
    structural-integrity test doesn't flag a nested closure.
    """
    stack: list[Any] = [obj]
    while stack:
        cur = stack.pop()
        if isinstance(cur, dict):
            if (cur.get("type") == "tool_use"
                    and cur.get("name") in _TRANSCRIPT_TASK_NAMES):
                inp = cur.get("input") or {}
                if isinstance(inp, dict):
                    out.append({
                        "id": cur.get("id", ""),
                        "subagent_type": inp.get("subagent_type", ""),
                        "description": (inp.get("description") or "")[:120],
                        "run_in_background": bool(inp.get("run_in_background")),
                    })
            stack.extend(cur.values())
        elif isinstance(cur, list):
            stack.extend(cur)


def _scan_transcript_for_background_orphan(
    transcript_path: Path,
) -> Optional[dict]:
    """v2.0.5 (B1): definitive-evidence path for orphan-background
    detection. Parse a Claude Code session JSONL and look for ≥2
    tool_use calls (name ∈ {Task, Agent}) with run_in_background:true
    followed by stop_reason=end_turn without a subsequent collection.

    Returns a partial dict with structured evidence, or None.
    """
    if not transcript_path.is_file():
        return None
    all_calls: list[dict] = []
    last_stop_reason: Optional[str] = None
    try:
        with transcript_path.open(encoding="utf-8", errors="replace") as f:
            for line in f:
                if not line.strip():
                    continue
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError:
                    continue
                _walk_transcript_tool_uses(obj, all_calls)
                if obj.get("type") == "assistant":
                    sr = (obj.get("message") or {}).get("stop_reason")
                    if sr:
                        last_stop_reason = sr
    except OSError:
        return None

    bg_calls = [c for c in all_calls if c["run_in_background"]]
    if len(bg_calls) < 2:
        return None
    if last_stop_reason != "end_turn":
        # Crash/rate-limit/different terminal — not the orphan signature.
        return None
    return {
        "transcript_path": str(transcript_path),
        "task_count_background": len(bg_calls),
        "turn_ended_at": last_stop_reason,
        "agent_ids": [c["id"] for c in bg_calls],
        "subagent_types": [c["subagent_type"] for c in bg_calls],
    }


def detect_background_orphan(
    stdio_log: Path,
    scratchpad: Path,
    phase_name: str,
    mode: str,
    pipeline: str,
    rc: int,
    *,
    backend: str = "claude",
    project_root: Optional[str] = None,
) -> Optional[dict]:
    """Detect the orphaned-background-agent pattern after a subprocess exits.

    Returns a diagnostic dict if the pattern is detected and writes it to
    `{scratchpad}/_diagnostic_orphan_{phase_name}.json`. Returns None
    otherwise.

    Detection priority (Codex Round-2 Claim 10):
      - **Definitive evidence:** transcript JSONL proves ≥2 Task calls
        with `run_in_background:true` followed by `end_turn` without
        subsequent collection AND ≥2 expected files are header-only stubs
        → emit diagnostic REGARDLESS of rc.
      - **Heuristic path:** transcript unavailable / unparseable; `rc == 0`
        AND ≥2 expected files are header-only stubs → emit with
        `evidence:"heuristic"`.
      - Otherwise → return None (silent).
    """
    targets = _resolve_never_cut_targets(scratchpad, phase_name, mode, pipeline)
    if not targets:
        return None
    stub_files = [t for t in targets if _is_header_only_stub(scratchpad / t)]
    if len(stub_files) < 2:
        return None

    # v2.0.5 (B1): definitive-evidence path via transcript JSONL.
    # Works regardless of rc (per Codex Round-2 Claim 10) — the LLM's
    # documented behavior is the diagnosis; rc quirks must not suppress.
    transcript_evidence: Optional[dict] = None
    if backend == "claude" and project_root:
        transcript_path = _find_transcript_jsonl(project_root)
        if transcript_path is not None:
            transcript_evidence = _scan_transcript_for_background_orphan(
                transcript_path
            )

    if transcript_evidence:
        diag = {
            "phase": phase_name,
            "evidence": "transcript_jsonl",
            "rc": rc,
            "backend": backend,
            "stub_files": stub_files,
            "stub_count": len(stub_files),
            "fingerprint": "tool_use_run_in_background_then_end_turn",
            "detected_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            **transcript_evidence,
        }
    else:
        # Heuristic path: rc==0 required (orphan is a clean exit). If the
        # subprocess crashed or timed out, the cause is different.
        if rc != 0:
            return None
        diag = {
            "phase": phase_name,
            "evidence": "heuristic",
            "rc": rc,
            "backend": backend,
            "stub_files": stub_files,
            "stub_count": len(stub_files),
            "fingerprint": "header_only_files_with_clean_rc",
            "detected_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
    try:
        out = scratchpad / f"_diagnostic_orphan_{phase_name}.json"
        out.write_text(json.dumps(diag, indent=2), encoding="utf-8")
    except OSError:
        pass
    return diag


_INVENTORY_CHUNK_RE = re.compile(r"^findings_inventory_chunk_([a-z])\.md$")


def _is_valid_inventory_chunk_output(path: Path) -> bool:
    """v2.0.4 (A'2): lightweight side-effect-free validator for an
    inventory chunk artifact. Replicates the substantive checks of the
    inventory_chunk_* gate WITHOUT calling _run_phase_validators (which
    has side effects per Codex Round-2 Claim 11).

    Inventory chunk gate requirements (derived from
    phase4a-inventory-prompt body lines 200-208 and the prompt-builder
    inventory_scope_directive at plamen_prompt.py:2206-2280):

      - file size >= 200 bytes (gate min_artifact_bytes)
      - contains at least one `### Finding [CC-` heading (the
        chunk-row contract; CC-N IDs are mandatory per the prompt body)
      - contains at least one `**Impact**:` line (checklist requirement
        — every CC block must list the impact)
      - contains at least one `**Source IDs**:` reference (cross-phase
        parity contract — downstream merge maps CC IDs back to upstream)

    Returns True iff all four hold. No side effects. The general
    `_run_phase_validators` belongs to Phase C with a `dry_run=True`
    extraction; A' uses this lightweight check.
    """
    try:
        if path.stat().st_size < 200:
            return False
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    # CC-N chunk-row heading (mandatory). Tolerant `#{2,4}` + optional `:` after
    # the bracketed ID so `### Finding [CC-1]` and `#### Finding [CC-1]: title`
    # both match (strict superset of the old `^###\s+Finding\s+\[CC-`).
    if not re.search(r"(?im)^\s*#{2,6}\s+Finding\s+\[CC-", _llm_norm(text)):
        return False
    # Impact + Source-ID presence via the shared tolerant extractor: accepts
    # bold/bullet/plain/table-cell renderings, `:`/`-`/`=`/em-dash separators,
    # and the `Source ID` singular alias — fixing the futile chain-chunk retries
    # the old literal `^**Impact**:` / `^**Source IDs**:` regexes caused on
    # complete-but-differently-rendered chunks.
    impact_val, _ = _field_anywhere(text, ("Impact",), table_ok=True)
    if not impact_val:
        return False
    src_val, _ = _field_anywhere(
        text, ("Source IDs", "Source ID", "Source Finding IDs"), table_ok=True
    )
    if not src_val:
        return False
    return True


def _record_artifact_adoption(
    scratchpad: Path,
    project_root: str,
    name: str,
    *,
    owning_phase: str,
    adopted_from: str,
) -> None:
    """v2.0.4 (A'2): record adoption provenance in `_artifact_state.json`.

    Extends the existing `_artifact_record` schema (validators.py:1321)
    with three optional fields:
      - `adopted_from`: the phase that physically produced the file
      - `adopted_at`: ISO timestamp of adoption
      - `adoption_owning_phase`: the phase whose expected_artifact this is

    Backward-compatible: artifacts without these fields are normal
    phase-owned outputs.
    """
    try:
        state = _read_artifact_state(scratchpad)
    except Exception as e:
        log.debug(f"[adoption] could not read artifact state: {e}")
        return
    artifacts = state.setdefault("artifacts", {})
    record = _artifact_record(
        scratchpad, project_root, name,
        owner_phase=owning_phase, status="ACTIVE",
    )
    if record is None:
        return
    record["adopted_from"] = adopted_from
    record["adopted_at"] = datetime.now(timezone.utc).isoformat()
    record["adoption_owning_phase"] = owning_phase
    artifacts[name] = record
    try:
        _write_artifact_state(scratchpad, state)
    except Exception as e:
        log.debug(f"[adoption] could not write artifact state: {e}")


def _try_adopt_inventory_sibling(
    scratchpad: Path,
    project_root: str,
    current_phase_name: str,
    foreign_name: str,
) -> bool:
    """v2.0.4 (A'2): attempt to adopt a sibling inventory_chunk output.

    Adoption semantics (Phase A' tactical, inventory-scoped):
      - The foreign artifact must be a sibling chunk's expected output
        (e.g., chunk_a is running and the foreign file is
        findings_inventory_chunk_b.md).
      - The foreign file's content must pass the lightweight inventory
        chunk validator (no side effects, no recursion into the general
        phase validator per Codex Round-2 Claim 11).
      - On success: the file STAYS in the scratchpad root at its
        expected name. Provenance is recorded in `_artifact_state.json`.
        The downstream chunk_b phase will execute, but its subprocess
        will see the existing substantive file via the resumption
        protocol and exit immediately without re-deriving.
      - Phase C will generalize this with full skip-by-adoption via
        the declarative `Phase.adoptable_outputs` contract and
        `_run_phase_validators_readonly`.

    Returns True iff the adoption is accepted. False → caller should
    quarantine instead.
    """
    m = _INVENTORY_CHUNK_RE.match(foreign_name)
    if not m:
        return False
    owning_chunk_letter = m.group(1)
    owning_phase_name = f"inventory_chunk_{owning_chunk_letter}"
    if owning_phase_name == current_phase_name:
        return False  # not a sibling — it's our own output
    foreign_path = scratchpad / foreign_name
    if not foreign_path.exists():
        return False
    if not _is_valid_inventory_chunk_output(foreign_path):
        log.warning(
            f"[{current_phase_name}] cannot adopt {foreign_name}: "
            f"failed inventory chunk validator (size/CC-heading/"
            f"Impact/Source IDs missing). Will quarantine instead."
        )
        return False
    _record_artifact_adoption(
        scratchpad, project_root, foreign_name,
        owning_phase=owning_phase_name,
        adopted_from=current_phase_name,
    )
    log.warning(
        f"[{current_phase_name}] adopted {foreign_name} for "
        f"{owning_phase_name} (validator passed; provenance recorded). "
        f"{owning_phase_name} subprocess will exit via resumption protocol."
    )
    return True


def _archive_orphan_stubs(
    scratchpad: Path, phase_name: str, diag: dict
) -> Optional[Path]:
    """v2.0.3 (A4): move orphan-background stub files out of the scratchpad
    into `_overflow/{phase_name}/orphan_stubs/{timestamp}/` along with a
    manifest. Returns the archive directory path or None on failure.

    Rationale: the retry attempt should treat orphan stubs as MISSING, not
    as partial work. Moving them out of the scratchpad root ensures the
    resumption-protocol substantive-content check sees them as absent.
    The archive also provides a concrete regression fixture for tests.
    """
    stubs = diag.get("stub_files") or []
    if not stubs:
        return None
    ts = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    archive_dir = scratchpad / "_overflow" / phase_name / "orphan_stubs" / ts
    try:
        archive_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        return None
    moved: list[str] = []
    for name in stubs:
        src = scratchpad / name
        if not src.exists():
            continue
        try:
            dst = archive_dir / name
            src.rename(dst)
            moved.append(name)
        except OSError as e:
            log.debug(f"[{phase_name}] could not archive stub {name}: {e}")
    try:
        manifest = archive_dir / "manifest.txt"
        manifest.write_text(
            f"# Orphan-background stub archive ({phase_name})\n"
            f"# Detected at: {diag.get('detected_at','unknown')}\n"
            f"# Evidence: {diag.get('evidence','unknown')}\n"
            f"# rc: {diag.get('rc','unknown')}\n"
            f"# Backend: {diag.get('backend','unknown')}\n"
            f"# Fingerprint: {diag.get('fingerprint','unknown')}\n"
            f"# Stub files archived:\n"
            + "".join(f"#   - {m}\n" for m in moved),
            encoding="utf-8",
        )
    except OSError:
        pass
    return archive_dir


# Retry-hint sharding must understand the same identity surface as the queue
# and mapping parsers. A narrower local expression previously truncated
# ``L1-H-12`` to ``H-12`` and missed split/group families entirely.
_VERIFY_HINT_ID_RE = _INTERNAL_FINDING_ID_RE


_SEMANTIC_DEDUP_PASSTHROUGH_PREFIX = (
    "semantic dedup: PASSTHROUGH unchanged despite live candidate pairs"
)


def _write_sc_semantic_dedup_safety_net(
    scratchpad: Path, reason: str,
) -> list[str]:
    """Keep the legacy SC scaffold isolated from the typed L1 proposal path."""

    return _write_semantic_dedup_skip_outputs(
        Path(scratchpad), "sc_semantic_dedup", str(reason)
    )


def _semantic_dedup_pair_count(scratchpad: Path) -> int:
    pairs_file = scratchpad / "dedup_candidate_pairs.md"
    if not pairs_file.exists():
        return 0
    try:
        pair_text = pairs_file.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return 0
    return sum(
        1
        for line in pair_text.splitlines()
        if line.lstrip().startswith("|")
        and not re.match(r"\s*\|\s*-+", line)
        and "Finding A" not in line
    )


def _semantic_dedup_passthrough_issue(scratchpad: Path) -> Optional[str]:
    pair_rows = _semantic_dedup_pair_count(scratchpad)
    if pair_rows <= 0:
        return None
    decisions = scratchpad / "dedup_decisions.md"
    if not decisions.exists():
        return None
    try:
        dec_text = decisions.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return None
    if re.search(r"(?im)^\s*\*?\*?Status\*?\*?\s*:\s*PASSTHROUGH\b", dec_text):
        return (
            f"{_SEMANTIC_DEDUP_PASSTHROUGH_PREFIX} "
            f"({pair_rows} candidate pair(s)); subprocess preserved the "
            "pre-run safety net instead of evaluating merge/keep decisions"
        )
    return None


def _is_semantic_dedup_passthrough_failure(missing: list[Any]) -> bool:
    return any(
        str(item).startswith(_SEMANTIC_DEDUP_PASSTHROUGH_PREFIX)
        for item in missing
    )


# FIX (#5): phases whose disk gate can pass on a driver pre-written
# scaffold/placeholder rather than real completed work. The zombie-phase
# early-complete (in `_pty_poll`) must NEVER fire for these — the existing
# continuation-budget / timeout path owns them. chain_agent2 / chain_iter2 are
# deliberately NOT here: they write real synthesis artifacts with no scaffold,
# so they are exactly the idle-zombie case the recovery is meant to rescue
# (chain_agent2 once blocked the full ~90-min LOC-scaled timeout after writing
# all three of its artifacts).
_ZOMBIE_SCAFFOLD_EXCLUDED_NAMES = frozenset({
    "sc_semantic_dedup", "semantic_dedup",   # PASSTHROUGH scaffold
    "chain",                                  # chain Agent 1 — MECHANICAL_BASELINE
})
_ZOMBIE_SCAFFOLD_EXCLUDED_PREFIXES = (
    "report_critical_high", "report_medium", "report_low_info",  # placeholder pre-writes
)


def _zombie_phase_is_scaffold_excluded(phase: Any) -> bool:
    """True when `phase` may pass its gate on a pre-written scaffold/placeholder
    and therefore must not be early-completed by zombie-phase recovery."""
    name = getattr(phase, "name", "") or ""
    if name in _ZOMBIE_SCAFFOLD_EXCLUDED_NAMES:
        return True
    if getattr(phase, "appends_existing_artifact", False):
        return True
    return any(name.startswith(pfx) for pfx in _ZOMBIE_SCAFFOLD_EXCLUDED_PREFIXES)


def _dedup_passthrough_should_continue(
    phase_name: str, attempt: int, budget: int, scratchpad: Path
) -> bool:
    """True when the in-session continuation loop should spend a turn driving
    a fresh missing-only continuation for a semantic-dedup phase instead of
    accepting the gate's pass.

    The gate "passes" the moment the driver's crash-safety PASSTHROUGH
    scaffold exists on disk — so a subprocess that compacted mid-write and
    never overwrote the scaffold looks complete and the continuation budget
    is never used. This predicate fires ONLY when ALL hold:

      - the phase is the semantic-dedup phase (SC or L1),
      - continuation budget remains (attempt <= budget), and
      - dedup_decisions.md still carries Status: PASSTHROUGH while
        dedup_candidate_pairs.md has live candidate rows
        (``_semantic_dedup_passthrough_issue`` is the single source of truth).

    When it returns False on a dedup phase because the budget is spent, the
    caller accepts the passthrough floor (returns 0) — it MUST NOT escalate to
    a whole-phase-retry sentinel, because this phase is critical=True and that
    would cascade to a critical halt. Recall is preserved downstream by the
    mechanical passthrough disposition, supplemental dedup, and the
    Python-native report_dedup pass.
    """
    if phase_name not in ("semantic_dedup", "sc_semantic_dedup"):
        return False
    if attempt > budget:
        return False
    return bool(_semantic_dedup_passthrough_issue(scratchpad))


# Regex for the LLM/mechanical absorbed->survivor relationship rows in
# dedup_decisions.md. Two formats are recognized (mirrors
# _extract_dedup_absorbed_ids, but captures BOTH endpoints so the survivor can
# be propagated into finding_mapping):
#   1. LLM semantic dedup status row:
#        | INV-013 | MERGED into INV-014 | <coupled-content> | <notes> |
#   2. Mechanical fallback/supplement:
#        | MECHANICAL_MERGE | INV-013 | INV-014 | <signal> |
#        | MECHANICAL_SUPPLEMENT | INV-013 | INV-014 | <signal> |
_DEDUP_MERGED_INTO_RE = re.compile(
    r"^\|\s*([A-Za-z]+-\d+)\s*\|\s*MERGED\s+into\s+([A-Za-z]+-\d+)\b"
    r"(?:\s*\|\s*([^|]*))?",
    re.MULTILINE | re.IGNORECASE,
)
_DEDUP_MECHANICAL_ROW_RE = re.compile(
    r"^\|\s*MECHANICAL_(?:MERGE|SUPPLEMENT)\s*\|\s*([A-Za-z]+-\d+)\s*\|\s*"
    r"([A-Za-z]+-\d+)\s*\|\s*([^|]*)",
    re.MULTILINE | re.IGNORECASE,
)


def _dedup_absorbed_survivor_mapping(
    scratchpad: Path,
) -> dict[str, dict[str, str]]:
    """Return ``{absorbed_id: {"survivor": id, "coupled": text}}`` from dedup.

    Parses ``dedup_decisions.md`` for both the LLM ``MERGED into`` status rows
    and the mechanical ``MECHANICAL_MERGE/SUPPLEMENT`` rows. Captures the
    survivor AND the coupled-content / signal cell so the absorbed finding's
    distinct content can be recorded alongside the constituent mapping. This is
    additive bookkeeping — it never drops a finding; it only records which
    survivor a previously-absorbed finding was consolidated into so the
    tier-writer Rule 10 coupling path (read finding_mapping.md, pull each source
    finding's distinct root cause into the report finding) reaches the absorbed
    lineage.
    """
    # P0-S: Markdown decisions are proposals, never applied authority.  Only a
    # valid immutable receipt chain whose accepted set equals the actual
    # pre/post identity delta may feed alias, chain, coverage, or report
    # propagation. Missing/tampered/stale/conflicting receipts fail closed to
    # no aliases; the independently-live findings remain in the canonical
    # inventory/queue and continue through verification.
    try:
        from semantic_dedup_authority import load_applied_aliases

        return load_applied_aliases(Path(scratchpad))
    except Exception as exc:
        log.warning(
            "[dedup-authority] applied alias receipt unavailable/invalid; "
            "raw proposals will not propagate: %r",
            exc,
        )
        return {}


def _write_dedup_absorbed_map(
    scratchpad: Path,
    mapping: dict[str, dict[str, str]],
) -> int:
    """Write the driver-owned ``dedup_absorbed_map.md`` sidecar.

    Chain Agent 1 reads this file (see prompts/shared/v2/phase4c-chain-agent1.md
    Inputs) and the mechanical chain baseline folds it into Constituent
    Findings. Each row records an absorbed ID, its survivor, and the absorbed
    finding's distinct coupled content so no attack path / route / impact is
    lost when the survivor is consolidated. Returns the number of rows written.
    """
    scratchpad = Path(scratchpad)
    lines = [
        "# Dedup Absorbed Map",
        "",
        "**Status**: DRIVER_PROPAGATION",
        "",
        "Driver-written record of semantic-dedup merges. Each row is an "
        "`Absorbed ID -> Survivor ID` consolidation. Chain Agent 1 MUST record "
        "every Absorbed ID as a Constituent Finding of its Survivor's "
        "hypothesis and preserve the absorbed finding's distinct attack path / "
        "route / call-site / impact in the survivor hypothesis description so "
        "the tier-writer Rule 10 path couples both with ZERO DATA LOSS. Do NOT "
        "re-create an Absorbed ID as its own standalone hypothesis.",
        "",
        "| Absorbed ID | Survivor ID | Coupled Distinct Content |",
        "|-------------|-------------|--------------------------|",
    ]
    n = 0
    for absorbed in sorted(mapping):
        info = mapping[absorbed]
        survivor = info.get("survivor", "")
        coupled = (info.get("coupled") or "").replace("|", "/").strip()
        if not survivor:
            continue
        lines.append(f"| {absorbed} | {survivor} | {coupled} |")
        n += 1
    if n == 0:
        lines.append("| (none) | (none) | no dedup merges recorded |")
    (scratchpad / "dedup_absorbed_map.md").write_text(
        "\n".join(lines) + "\n", encoding="utf-8"
    )
    return n


# R0-2b: finding_mapping is consumed only through the canonical typed parser.
# ID breadth comes from its central hypothesis grammar; table identity comes
# from R0-2a's header roles, never from permissive whole-row regex scanning.
def _report_candidate_rows(
    scratchpad: Path,
    *,
    run_id: str | None = None,
) -> list[dict[str, Any]]:
    """Return the authenticated report denominator after typed cutover."""

    root = Path(scratchpad)
    if report_candidate_universe_requires_typed_authority(root):
        return current_report_candidate_universe_legacy_rows(
            root,
            run_id=run_id,
            project_root=root.parent,
        )
    return parse_verification_queue_rows(root)


def _report_candidate_input_paths(
    scratchpad: Path,
    *,
    run_id: str | None = None,
) -> tuple[str, ...]:
    """Exact transitive PhaseIO inputs for the report candidate universe."""

    root = Path(scratchpad)
    if not report_candidate_universe_requires_typed_authority(root):
        return ()
    publication = None
    live_selected = (
        (root / "verify_queue_transaction.receipt.json").exists()
        or (root / QUEUE_PLAN_AUTHORITY).exists()
    )
    if live_selected:
        publication = load_authenticated_queue_publication(
            root,
            project_root=root.parent,
            run_id=run_id,
        )
    authority = load_candidate_universe_authority(
        root,
        run_id=run_id,
        authenticated_publication=publication,
    )
    paths = set(authority.input_artifacts)
    if publication is not None:
        paths.update({
            QUEUE_PLAN_AUTHORITY,
            "verify_queue_transaction.receipt.json",
            "verification_queue.work_plan.json",
            "verification_queue.md",
        })
    late_authority_path = (
        root / "post_verify_late_verification_authority.json"
    )
    if late_authority_path.is_file():
        effective_run_id = run_id or authority.run_id
        if not effective_run_id:
            raise ValueError(
                "late verification PhaseIO inputs require a run identity"
            )
        late_authority = load_late_verification_authority(
            root,
            run_id=effective_run_id,
            repo_root=Path(__file__).resolve().parent.parent,
        )
        paths.add(late_authority_path.name)
        artifact_fields = (
            "contract_artifact",
            "launch_spec_artifact",
            "execution_artifact",
            "verify_artifact",
            "severity_proposal_artifact",
            "operator_application_artifact",
            "operator_receipt_artifact",
        )
        for row in late_authority["rows"]:
            paths.update(
                str(row[field])
                for field in artifact_fields
                if row.get(field)
            )
    elif (root / "post_verify_late_delivery.json").is_file():
        paths.add("post_verify_late_delivery.json")
        paths.update(
            row.item.expected_output_file
            for row in authority.candidates
            if row.source_kind != "BASE_VERIFICATION_QUEUE"
        )
    return tuple(sorted(paths))


def _write_report_index_coverage_seed(
    scratchpad: Path,
    *,
    expected_run_id: str = "",
    expected_mode: str = "",
) -> int:
    """Write the driver-owned ``report_index_coverage_seed.md``.

    This is the mechanical completeness backbone for the report_index phase. It
    enumerates EVERY finding/hypothesis ID from BOUNDED, driver-written ledgers
    (the verification queue + computed severities, the dedup absorbed->survivor
    map, and finding_mapping) so the Index Agent never has to re-derive the ID
    set by bulk-reading the 100K+ ``findings_inventory.md`` — the exact context
    -collapse trigger this artifact exists to remove.

    Recall-safety: the seed is a SUPERSET — it lists every ID present in any of
    the bounded sources. Coverage/completeness is still enforced by the existing
    Step 6a.1 gate (``hypothesis_count == report_ids + excluded + consolidated``)
    and STEP 5.5 ledger, which now run over a bounded ID list rather than over
    finding prose. Returns the number of seed rows written.
    """
    scratchpad = Path(scratchpad)

    # 1. Per-finding expected severity from the bounded verification queue.
    try:
        sev_map = _expected_report_index_severities(
            scratchpad,
            expected_run_id=expected_run_id,
            expected_mode=expected_mode,
        )
    except Exception:
        sev_map = {}

    # 2. Per-finding verdict + mapped hypothesis from the verification queue.
    #    Also capture the raw queue Severity column as a routing fallback: the
    #    severity-matrix sev_map can return a conservative default (Low) when a
    #    verify file is missing, but the queue Severity is the always-present
    #    bounded signal. Tier-shard routing prefers the matrix severity when set
    #    and falls back to the queue severity so shards stay accurately partitioned.
    verdict_map: dict[str, str] = {}
    queue_sev_map: dict[str, str] = {}
    try:
        for row in _report_candidate_rows(scratchpad):
            fid = (row.get("finding id") or "").strip().upper()
            if not fid:
                continue
            verdict_map[fid] = (
                row.get("verdict")
                or row.get("status")
                or row.get("preferred verification")
                or ""
            ).strip()
            qsev = (row.get("severity") or "").strip()
            if qsev:
                queue_sev_map[fid] = qsev
    except Exception:
        pass

    # 3. finding_id -> hypothesis_id from finding_mapping.md (bounded).
    hyp_map: dict[str, list[str]] = {}
    mapping_hypothesis_ids: set[str] = set()
    try:
        fm_path = scratchpad / "finding_mapping.md"
        if fm_path.is_file():
            fm_text = fm_path.read_text(encoding="utf-8", errors="replace")
            for row in parse_finding_mapping_rows(fm_text):
                source_ids = [str(fid).upper() for fid in row["source_ids"]]
                hypothesis_ids = [
                    str(fid).upper() for fid in row["hypothesis_ids"]
                ]
                mapping_hypothesis_ids.update(hypothesis_ids)
                for source_id in source_ids:
                    targets = hyp_map.setdefault(source_id, [])
                    for hypothesis_id in hypothesis_ids:
                        if hypothesis_id not in targets:
                            targets.append(hypothesis_id)
    except Exception:
        pass

    # 4. absorbed -> survivor relations from the dedup decisions (bounded).
    try:
        absorbed_map = _dedup_absorbed_survivor_mapping(scratchpad)
    except Exception:
        absorbed_map = {}

    # 5. Force-include justified High/Critical chains (and their constituents)
    #    REGARDLESS of mode. A chain upgraded ABOVE its constituents (e.g.
    #    PARTIAL/Low → High via a justified Combined-Impact) would otherwise
    #    never be promoted to the verify queue / body in any mode. Purely
    #    additive to the seed superset — ADD-only, never demotes/drops.
    try:
        forced_chains = _forced_chain_seed_rows(scratchpad)
    except Exception:
        forced_chains = {}

    # 6. P0-O grouped-PoC repair is a bounded additive coverage source.  The
    # source-bound scope/repair receipts preserve exact constituents even when
    # the primary verification queue contains only their grouped hypothesis.
    # Recovery output is a supplement, never implicit severity authority: until
    # an ordinary typed adjudicator consumes it, route at the pre-demotion
    # severity. Invalid/missing recovery status is conservatively PENDING.
    p0o_ids: set[str] = set()
    p0o_relation_map: dict[str, str] = {}
    try:
        _p0o_scope, _p0o_repair = _load_validated_p0o_scope_repair(scratchpad)
        try:
            _p0o_status = _load_validated_p0o_recovery_status(scratchpad)
        except Exception:
            _p0o_status = None
        _p0o_recovered = {
            str(value).upper()
            for value in ((_p0o_status or {}).get("recovered_constituent_ids") or [])
        }
        _p0o_unresolved = {
            str(value).upper()
            for value in ((_p0o_status or {}).get("unresolved_constituent_ids") or [])
        }
        for _work in _p0o_repair.get("work_items") or []:
            if not isinstance(_work, dict):
                continue
            _hypothesis_id = str(_work.get("hypothesis_id") or "").upper()
            _records = {
                str(record.get("constituent_id") or "").upper(): record
                for record in (_work.get("constituents") or [])
                if isinstance(record, dict)
            }
            for _raw_cid in _work.get("constituent_ids") or []:
                _cid = str(_raw_cid).upper()
                if not _cid or _cid not in _records:
                    continue
                p0o_ids.add(_cid)
                if _hypothesis_id:
                    p0o_ids.add(_hypothesis_id)
                    _targets = hyp_map.setdefault(_cid, [])
                    if _hypothesis_id not in _targets:
                        _targets.append(_hypothesis_id)
                _pre_severity = str(_records[_cid].get("severity") or "")
                sev_map[_cid] = _more_severe_label(
                    str(sev_map.get(_cid) or ""), _pre_severity
                )
                queue_sev_map[_cid] = _more_severe_label(
                    str(queue_sev_map.get(_cid) or ""), _pre_severity
                )
                if _cid in _p0o_recovered:
                    _state = "P0-O REVERIFIED SUPPLEMENT"
                elif _cid in _p0o_unresolved:
                    _state = "P0-O REVERIFICATION DEBT"
                else:
                    _state = "P0-O REVERIFICATION PENDING"
                verdict_map.setdefault(_cid, _state)
                p0o_relation_map[_cid] = (
                    f"{_state}; PRE-DEMOTION SEVERITY RETAINED"
                )
    except Exception:
        # No validated repair means no additional cap or status authority. The
        # grouped queue row remains visible through the ordinary sources.
        pass

    # Union of every ID that appears in any bounded source. This is the
    # authoritative completeness set — a SUPERSET, never a filtered subset.
    all_ids: set[str] = set()
    all_ids.update(sev_map.keys())
    all_ids.update(verdict_map.keys())
    all_ids.update(hyp_map.keys())
    all_ids.update(mapping_hypothesis_ids)
    all_ids.update(p0o_ids)
    for absorbed, info in absorbed_map.items():
        all_ids.add(absorbed)
        surv = (info or {}).get("survivor", "")
        if surv:
            all_ids.add(surv.upper())
    for cid, info in forced_chains.items():
        all_ids.add(cid)
        # Record the chain's upgraded severity in the seed (only when the
        # severity-matrix sev_map did not already carry a value for it).
        sev_map.setdefault(cid, str((info or {}).get("severity", "")))
        for con in (info or {}).get("constituents", []) or []:
            all_ids.add(con)

    lines = [
        "# Report Index Coverage Seed",
        "",
        "**Status**: DRIVER_ENUMERATED",
        "",
        "Driver-enumerated ID list of EVERY finding/hypothesis from bounded "
        "ledgers (verification queue, severity binding, finding_mapping, dedup "
        "absorbed map). The Index Agent MUST account for every ID below in the "
        "Master Finding Index or the Excluded Findings / Consolidation Map. "
        "This is the mechanical completeness backbone — enumerate the full ID "
        "set from HERE, not by bulk-reading findings_inventory.md.",
        "",
        "| Finding/Hyp ID | Expected Severity | Verdict | Mapped Hypothesis | Dedup Relation |",
        "|----------------|-------------------|---------|-------------------|----------------|",
    ]
    n = 0
    for fid in sorted(all_ids, key=lambda x: x.upper()):
        sev = sev_map.get(fid, "")
        verdict = verdict_map.get(fid, "")
        hyp = ", ".join(hyp_map.get(fid, []))
        relation = ""
        if fid in absorbed_map:
            surv = (absorbed_map[fid] or {}).get("survivor", "")
            relation = f"ABSORBED into {surv}" if surv else ""
        else:
            absorbed_into_this = [
                a for a, info in absorbed_map.items()
                if (info or {}).get("survivor", "").upper() == fid
            ]
            if absorbed_into_this:
                relation = "SURVIVOR of " + ",".join(sorted(absorbed_into_this))
        if fid in p0o_relation_map:
            relation = "; ".join(
                value for value in (relation, p0o_relation_map[fid]) if value
            )
        lines.append(
            f"| {fid} | {sev} | {verdict} | {hyp} | {relation} |"
        )
        n += 1
    if n == 0:
        lines.append("| (none) | | | | no bounded IDs found |")
    (scratchpad / "report_index_coverage_seed.md").write_text(
        "\n".join(lines) + "\n", encoding="utf-8"
    )

    # R3/R4 (TASK C): tier-shard the coverage seed so the report_index LLM can
    # process one tier-batch at a time and NEVER hold the whole working set in
    # a single turn (the context-collapse trigger that froze a prior run ~27min).
    # Completeness stays guaranteed mechanically because every seed row lands in
    # exactly one tier shard (full seed == union of shards, zero drops) and the
    # post-phase reconciliation gate (_check_index_completeness) validates the
    # merged report_index.md against the FULL seed superset.
    try:
        _write_report_index_seed_shards(
            scratchpad,
            seed_rows=[
                {
                    "id": fid,
                    "severity": sev_map.get(fid, ""),
                    # Routing severity: take the MORE-SEVERE of the matrix sev_map
                    # and the raw queue Severity. The matrix defaults to Low when
                    # a verify file is absent; the queue Severity is the always-
                    # present bounded signal. Routing UP never drops a finding
                    # (the gate reconciles the full seed regardless of tier), so
                    # using the max keeps a Critical/High finding in its tier even
                    # if the matrix conservatively reported Low.
                    "route_severity": _more_severe_label(
                        sev_map.get(fid, ""), queue_sev_map.get(fid, "")
                    ),
                    "verdict": verdict_map.get(fid, ""),
                    "hyp": ", ".join(hyp_map.get(fid, [])),
                    "absorbed_map": absorbed_map,
                }
                for fid in sorted(all_ids, key=lambda x: x.upper())
            ],
        )
    except Exception as exc:  # best-effort: shards are a convenience layer
        log.warning(f"[report_index] seed-shard partition skipped: {exc!r}")
    return n


# Coverage-seed tier shards. Each shard is a BOUNDED subset of
# report_index_coverage_seed.md restricted to one report tier-batch, so the
# Index Agent processes STEP 1.5 consolidation + STEP 5/5.5 coverage over a
# small ID list per turn instead of the full set. The driver owns the
# partition (severity -> tier) and the post-phase reconciliation, so the LLM
# can never let a finding fall between shards.
_REPORT_INDEX_TIER_SHARDS: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("critical_high", ("Critical", "High")),
    ("medium", ("Medium",)),
    ("low_info", ("Low", "Informational", "Info")),
)


def _more_severe_label(a: str, b: str) -> str:
    """Return whichever severity label is MORE severe (recall-safe routing).

    Used to pick a tier-shard routing severity from two bounded signals (the
    severity-matrix map and the raw queue Severity). Routing a finding to a
    higher tier never drops it — the completeness gate reconciles the full seed
    regardless of which shard a row landed in — so taking the max keeps a
    Critical/High finding in its tier even when one signal is conservative.
    """
    ra, rb = severity_rank(a), severity_rank(b)
    if rb > ra:
        return b
    return a or b


def _report_index_tier_for_severity(severity: str) -> str:
    """Map an expected severity string to its coverage-seed tier-shard key.

    Unknown / blank severities route to ``low_info`` so an under-classified row
    is never dropped from the shard partition — it still gets exactly one
    disposition and the reconciliation gate over the full seed catches drift.
    """
    sev = (severity or "").strip().lower()
    for tier, names in _REPORT_INDEX_TIER_SHARDS:
        if any(sev == n.lower() for n in names):
            return tier
    return "low_info"


def _write_report_index_seed_shards(
    scratchpad: Path, seed_rows: list[dict]
) -> dict[str, int]:
    """Partition the coverage seed into per-tier shard files.

    Returns {tier_key: row_count}. Every seed row lands in exactly ONE shard
    (partition, not overlap), so ``union(shards) == full seed`` mechanically.
    The Index Agent reads one shard per turn; the driver assembles the merged
    report_index.md and reconciles it against the FULL seed afterward.
    """
    scratchpad = Path(scratchpad)
    buckets: dict[str, list[dict]] = {t: [] for t, _ in _REPORT_INDEX_TIER_SHARDS}
    for row in seed_rows:
        route_sev = row.get("route_severity") or row.get("severity", "")
        tier = _report_index_tier_for_severity(route_sev)
        buckets[tier].append(row)

    counts: dict[str, int] = {}
    for tier, _names in _REPORT_INDEX_TIER_SHARDS:
        rows = buckets[tier]
        lines = [
            f"# Report Index Coverage Seed — Tier Shard: {tier}",
            "",
            "**Status**: DRIVER_ENUMERATED",
            "",
            "Bounded per-tier slice of report_index_coverage_seed.md. Process "
            "this shard's IDs in ONE turn: run STEP 1.5 consolidation and STEP "
            "5/5.5 coverage over THESE IDs only, then move to the next tier "
            "shard. Do NOT hold every tier's working set at once — that is the "
            "context-collapse trigger this partition removes. Every ID below "
            "MUST receive exactly one disposition (report ID, exclusion, or "
            "consolidation) in report_index.md.",
            "",
            "| Finding/Hyp ID | Expected Severity | Verdict | Mapped Hypothesis | Dedup Relation |",
            "|----------------|-------------------|---------|-------------------|----------------|",
        ]
        for row in rows:
            fid = row["id"]
            absorbed_map = row.get("absorbed_map") or {}
            relation = ""
            if fid in absorbed_map:
                surv = (absorbed_map[fid] or {}).get("survivor", "")
                relation = f"ABSORBED into {surv}" if surv else ""
            else:
                absorbed_into_this = [
                    a for a, info in absorbed_map.items()
                    if (info or {}).get("survivor", "").upper() == fid.upper()
                ]
                if absorbed_into_this:
                    relation = "SURVIVOR of " + ",".join(sorted(absorbed_into_this))
            lines.append(
                f"| {fid} | {row.get('severity', '')} | {row.get('verdict', '')} "
                f"| {row.get('hyp', '')} | {relation} |"
            )
        if not rows:
            lines.append("| (none) | | | | no IDs in this tier |")
        (scratchpad / f"report_index_seed_{tier}.md").write_text(
            "\n".join(lines) + "\n", encoding="utf-8"
        )
        counts[tier] = len(rows)
    return counts


def _run_gate_v_for_phase(phase_name: str, scratchpad: Path) -> dict:
    """Gate V (Fix A, recall) driver entry: 3-axis Variant-Family Coverage.

    Axis 1 (co-reference) is the existing G1/G2 gate (`run_enumeration_gate`,
    called separately, immediately before this) — UNCHANGED. Axes 2
    (boundary-input) and 3 (symmetric-operation), reached via
    `enumeration_gate.compute_variant_gaps`, are additive derivers over the
    same `_mechanical_graph.json` + `chain_candidate_pairs.md` data, emitted
    through the SAME append-only, idempotent inventory path. Unconditional
    (not Thorough-only, not confidence-gated) — a confidently-wrong agent is
    exactly the failure mode this closes.

    Never raises; a no-op (returns `{"emitted": 0}`) when the graph or the
    chain-candidate-pairs file is absent, mirroring `enumeration_gate`'s own
    no-op contract. Wired into `_run_phase_validators`'s L1 and SC
    depth-phase post-processing branches, immediately after
    `run_enumeration_gate`.
    """
    try:
        import enumeration_gate as _eg
        res = _eg.compute_variant_gaps(scratchpad)
    except Exception as exc:
        log.warning(
            f"[{phase_name}] variant gate skipped (non-blocking): {exc}"
        )
        return {
            "status": "FAILED",
            "emitted": 0,
            "error": f"{type(exc).__name__}: {exc}",
        }
    if res.get("emitted"):
        log.info(
            f"[{phase_name}] variant gate: emitted {res['emitted']} "
            f"VARGAP candidate(s) (axis2/boundary="
            f"{res.get('axis2_emitted', 0)}, axis3/symmetric="
            f"{res.get('axis3_emitted', 0)}) for verification"
        )
    return res


_DEPTH_FINALIZATION_RECEIPT = "depth_finalization_receipt.json"
_DEPTH_FINALIZATION_REVIEW = "depth_finalization_human_review.md"
_DEPTH_FINALIZATION_SOURCE_PATTERNS = (
    "depth_*_findings.md",
    "depth_findings.md",
    "niche_*_findings.md",
    "blind_spot_*_findings.md",
    "scanner_*_findings.md",
    "validation_sweep_findings.md",
    "design_stress_findings.md",
    "perturbation_findings.md",
    "_mechanical_graph.json",
    "chain_candidate_pairs.md",
    "function_summary.md",
)
_DEPTH_FINALIZATION_OWNED_INVENTORY_SECTIONS = frozenset({
    "niche-promoted findings",
    "blind-spot-recovered findings",
    "enumeration-coverage candidates (enumgap)",
})


def _depth_finalization_inventory_base(text: str) -> str:
    """Remove only inventory sections owned by these postprocessors."""
    h2 = list(re.finditer(r"(?im)^##\s+(.+?)\s*$", text or ""))
    if not h2:
        base = (text or "").rstrip()
        return base + ("\n" if base else "")
    pieces: list[str] = []
    cursor = 0
    for index, heading in enumerate(h2):
        title = re.sub(r"\s+", " ", heading.group(1)).strip().casefold()
        end = h2[index + 1].start() if index + 1 < len(h2) else len(text)
        if title not in _DEPTH_FINALIZATION_OWNED_INVENTORY_SECTIONS:
            continue
        pieces.append(text[cursor:heading.start()])
        cursor = end
    pieces.append(text[cursor:])
    base = "".join(pieces).rstrip()
    return base + ("\n" if base else "")


def _depth_finalization_source_digest(
    scratchpad: Path,
) -> tuple[str, list[str]]:
    """Bind depth finalization to immutable producer/mechanical inputs.

    The pre-finalization portion of the canonical inventory is included while
    sections owned by these processors are stripped. Thus an upstream
    inventory edit invalidates the journal, but a processor cannot invalidate
    its own transaction. Raw depth/niche/scanner or mechanical input changes
    likewise replay every idempotent processor.
    """
    scratchpad = Path(scratchpad)
    paths: dict[str, Path] = {}
    for pattern in _DEPTH_FINALIZATION_SOURCE_PATTERNS:
        for path in scratchpad.glob(pattern):
            if not path.is_file():
                continue
            name = path.relative_to(scratchpad).as_posix()
            paths[name] = path

    inventory_base: bytes | None = None
    inventory = scratchpad / "findings_inventory.md"
    if inventory.is_file():
        try:
            inventory_base = _depth_finalization_inventory_base(
                inventory.read_text(encoding="utf-8", errors="replace")
            ).encode("utf-8")
        except OSError:
            inventory_base = None

    digest = hashlib.sha256()
    names = sorted(paths)
    source_names = list(names)
    if inventory_base is not None:
        source_names.append("findings_inventory.md#pre-finalization-base")
    if not source_names:
        digest.update(b"PLAMEN_DEPTH_FINALIZATION_EMPTY_SOURCE_V1\0")
    for name in names:
        name_bytes = name.encode("utf-8", errors="surrogatepass")
        digest.update(len(name_bytes).to_bytes(8, "big"))
        digest.update(name_bytes)
        with paths[name].open("rb") as handle:
            while chunk := handle.read(1024 * 1024):
                digest.update(len(chunk).to_bytes(8, "big"))
                digest.update(chunk)
        digest.update((0).to_bytes(8, "big"))
    if inventory_base is not None:
        virtual_name = "findings_inventory.md#pre-finalization-base"
        name_bytes = virtual_name.encode("utf-8")
        digest.update(len(name_bytes).to_bytes(8, "big"))
        digest.update(name_bytes)
        digest.update(len(inventory_base).to_bytes(8, "big"))
        digest.update(inventory_base)
        digest.update((0).to_bytes(8, "big"))
    return digest.hexdigest(), source_names


def _write_depth_finalization_receipt(
    scratchpad: Path, receipt: dict[str, Any]
) -> None:
    """Atomically persist the journal after every processor transition."""
    path = Path(scratchpad) / _DEPTH_FINALIZATION_RECEIPT
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(
        json.dumps(receipt, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    os.replace(temporary, path)


def _load_depth_finalization_receipt(scratchpad: Path) -> dict[str, Any]:
    path = Path(scratchpad) / _DEPTH_FINALIZATION_RECEIPT
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
        return value if isinstance(value, dict) else {}
    except (OSError, UnicodeError, json.JSONDecodeError):
        return {}


def _depth_inventory_structural_referents(
    scratchpad: Path,
) -> dict[str, set[str]]:
    """Return finding-heading -> canonical Source-ID tokens.

    Identity is accepted only from a Source ID(s) field inside an actual
    finding block. Free-form mentions elsewhere in the inventory do not count.
    """
    path = Path(scratchpad) / "findings_inventory.md"
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {}
    out: dict[str, set[str]] = {}
    headings = list(FINDING_BLOCK_HEADING_RE.finditer(text))
    for index, heading in enumerate(headings):
        end = headings[index + 1].start() if index + 1 < len(headings) else len(text)
        block = text[heading.start():end]
        source_field = _field_from_markdown(block, ("Source IDs", "Source ID"))
        if not source_field:
            continue
        tokens = {
            token.upper()
            for token in re.findall(
                r"\b(?:[A-Z][A-Z0-9_]*(?:-[A-Z0-9_]+)+|"
                r"ENUMGAP|VARGAP|INVARIANT|AXISGAP)\b",
                source_field,
                re.IGNORECASE,
            )
        }
        if tokens:
            out[heading.group(1).strip().upper()] = tokens
    return out


def _depth_processor_output_count(name: str, result: Any) -> int:
    if name == "niche_promotion" and isinstance(result, dict):
        return max(0, int(result.get("appended", 0) or 0))
    if name == "blind_spot_recovery" and isinstance(result, dict):
        return max(0, int(result.get("recovered", 0) or 0))
    if name in {"enumeration_gate", "variant_gate"} and isinstance(result, dict):
        return max(0, int(result.get("emitted", 0) or 0))
    return 0


def _depth_processor_outcome(
    before: dict[str, set[str]], after: dict[str, set[str]]
) -> dict[str, Any]:
    referents = [
        {"finding_id": finding_id, "source_ids": sorted(after[finding_id])}
        for finding_id in sorted(set(after) - set(before))
    ]
    return {"inventory_referents": referents}


def _niche_identity_debt_attestation(
    identity_debt: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind the mutable debt projection to its immutable lifecycle head."""

    if identity_debt.get("lifecycle_authority_schema") != NICHE_LIFECYCLE_SCHEMA:
        raise RuntimeError(
            "niche identity-debt projection has no immutable lifecycle authority"
        )
    lifecycle_status = str(
        identity_debt.get("lifecycle_authority_status") or ""
    )
    lifecycle_head = str(identity_debt.get("lifecycle_head_sha256") or "")
    lifecycle_run_id = str(identity_debt.get("lifecycle_run_id") or "")
    lifecycle_audit_id = str(
        identity_debt.get("lifecycle_audit_instance_id") or ""
    )
    lifecycle_attempt = identity_debt.get("lifecycle_attempt_ordinal")
    lifecycle_dimensions = {
        field: str(identity_debt.get(f"lifecycle_{field}") or "")
        for field in (
            "pipeline", "mode", "ecosystem", "backend", "phase", "producer"
        )
    }
    lifecycle_context_sha = str(
        identity_debt.get("lifecycle_context_sha256") or ""
    )
    if (
        lifecycle_status not in {"CURRENT", "BLOCKED"}
        or re.fullmatch(r"[0-9a-f]{64}", lifecycle_head) is None
        or re.fullmatch(r"[0-9a-f]{64}", lifecycle_audit_id) is None
        or not lifecycle_run_id
        or not isinstance(lifecycle_attempt, int)
        or isinstance(lifecycle_attempt, bool)
        or lifecycle_attempt < 1
        or re.fullmatch(r"[0-9a-f]{64}", lifecycle_context_sha) is None
        or re.fullmatch(
            r"[0-9a-f]{64}",
            str(identity_debt.get("lifecycle_delivery_record_set_sha256") or ""),
        ) is None
        or any(not value for value in lifecycle_dimensions.values())
    ):
        raise RuntimeError(
            "niche identity-debt lifecycle head binding is malformed"
        )
    return {
        "identity_debt_artifact": "niche_identity_debt.json",
        "identity_debt_sha256": str(
            identity_debt.get("artifact_sha256") or ""
        ),
        "identity_debt_count": int(
            identity_debt.get("blocking_debt_count", 0) or 0
        ),
        "identity_debt_candidate_count": int(
            identity_debt.get("candidate_count", 0) or 0
        ),
        "identity_debt_source_error_count": int(
            identity_debt.get("source_error_count", 0) or 0
        ),
        "identity_debt_denominator_complete": bool(
            identity_debt.get("denominator_complete")
        ),
        "identity_debt_action_count": int(
            identity_debt.get("action_count", 0) or 0
        ),
        "identity_debt_action_set_sha256": str(
            identity_debt.get("action_set_sha256") or ""
        ),
        "identity_debt_live_action_denominator_sha256": str(
            identity_debt.get("live_action_denominator_sha256") or ""
        ),
        "identity_debt_source_namespace": identity_debt.get(
            "source_namespace"
        ),
        "identity_debt_source_namespace_sha256": str(
            identity_debt.get("source_namespace_sha256") or ""
        ),
        "identity_debt_source_snapshots": identity_debt.get(
            "source_snapshots"
        ),
        "identity_debt_lifecycle_count": int(
            identity_debt.get("lifecycle_count", 0) or 0
        ),
        "identity_debt_lifecycle_set_sha256": str(
            identity_debt.get("lifecycle_set_sha256") or ""
        ),
        "identity_debt_removed_action_count": int(
            identity_debt.get("removed_action_count", 0) or 0
        ),
        "identity_debt_removed_action_set_sha256": str(
            identity_debt.get("removed_action_set_sha256") or ""
        ),
        "identity_debt_lifecycle_authority_schema": NICHE_LIFECYCLE_SCHEMA,
        "identity_debt_lifecycle_authority_status": lifecycle_status,
        "identity_debt_lifecycle_audit_instance_id": lifecycle_audit_id,
        "identity_debt_lifecycle_run_id": lifecycle_run_id,
        **{
            f"identity_debt_lifecycle_{field}": value
            for field, value in lifecycle_dimensions.items()
        },
        "identity_debt_lifecycle_context_sha256": lifecycle_context_sha,
        "identity_debt_lifecycle_attempt_ordinal": lifecycle_attempt,
        "identity_debt_lifecycle_head_sha256": lifecycle_head,
        "identity_debt_lifecycle_action_denominator_sha256": str(
            identity_debt.get("lifecycle_action_denominator_sha256") or ""
        ),
        "identity_debt_lifecycle_transition_set_sha256": str(
            identity_debt.get("lifecycle_transition_set_sha256") or ""
        ),
        "identity_debt_lifecycle_history_set_sha256": str(
            identity_debt.get("lifecycle_history_set_sha256") or ""
        ),
        "identity_debt_lifecycle_blocking_count": int(
            identity_debt.get("lifecycle_blocking_count", 0) or 0
        ),
        "identity_debt_lifecycle_delivery_record_count": int(
            identity_debt.get("lifecycle_delivery_record_count", 0) or 0
        ),
        "identity_debt_lifecycle_delivery_record_set_sha256": str(
            identity_debt.get("lifecycle_delivery_record_set_sha256") or ""
        ),
        "identity_debt_validation_status": "LIVE_VALIDATED",
    }


def _depth_finalization_execution_context(
    phase_name: str,
    scratchpad: Path,
    config: Optional[Mapping[str, Any]],
) -> dict[str, str]:
    root = Path(scratchpad)
    if config is None:
        project = root.parent
        run_id = ""
        checkpoint = root / "_v2_checkpoint.json"
        try:
            value = json.loads(checkpoint.read_text(encoding="utf-8"))
            if isinstance(value, Mapping):
                run_id = str(value.get("run_id") or "").strip()
        except (OSError, UnicodeError, json.JSONDecodeError):
            run_id = ""
        if not run_id:
            identity = os.path.normcase(
                os.path.normpath(os.fspath(root.resolve()))
            )
            run_id = "standalone-" + hashlib.sha256(
                identity.encode("utf-8")
            ).hexdigest()[:32]
        dimensions = {
            "pipeline": "sc", "mode": "thorough", "ecosystem": "evm",
            "backend": "claude", "phase": phase_name,
            "producer": "niche_promotion",
        }
    else:
        project = Path(str(config.get("project_root") or root.parent))
        run_id = str(config.get("_run_id") or "").strip()
        if not run_id:
            raise RuntimeError(
                "depth finalization requires the canonical driver run_id"
            )
        pipeline = str(config.get("pipeline") or "sc").strip().lower()
        dimensions = {
            "pipeline": pipeline,
            "mode": str(config.get("mode") or "thorough").strip().lower(),
            "ecosystem": str(
                config.get("language")
                or config.get("ecosystem")
                or ("l1" if pipeline == "l1" else "evm")
            ).strip().lower(),
            "backend": str(
                config.get("cli_backend") or config.get("backend") or "claude"
            ).strip().lower(),
            "phase": phase_name,
            "producer": "niche_promotion",
        }
    return niche_lifecycle_context(
        project_root=project,
        run_id=run_id,
        dimensions=dimensions,
    )


def _depth_processor_outcome_valid(
    scratchpad: Path,
    name: str,
    row: dict[str, Any],
    *,
    expected_context: Optional[Mapping[str, str]] = None,
) -> tuple[bool, str]:
    if name == "niche_promotion":
        try:
            identity_debt = read_niche_identity_debt_sidecar(scratchpad)
            if identity_debt is not None:
                expected_attestation = _niche_identity_debt_attestation(
                    identity_debt
                )
        except Exception as exc:
            return False, str(exc)
        if identity_debt is None:
            return False, "missing niche_identity_debt.json attestation"
        result = row.get("result") if isinstance(row, dict) else None
        if not isinstance(result, dict):
            return False, "niche result has no identity-debt attestation binding"
        for field, expected_value in expected_attestation.items():
            if result.get(field) != expected_value:
                return False, f"niche identity-debt binding changed: {field}"
        if expected_context is not None:
            context_attestation = {
                "audit_instance_id": expected_attestation[
                    "identity_debt_lifecycle_audit_instance_id"
                ],
                "run_id": expected_attestation[
                    "identity_debt_lifecycle_run_id"
                ],
                **{
                    field: expected_attestation[
                        f"identity_debt_lifecycle_{field}"
                    ]
                    for field in (
                        "pipeline", "mode", "ecosystem", "backend", "phase",
                        "producer",
                    )
                },
                "context_sha256": expected_attestation[
                    "identity_debt_lifecycle_context_sha256"
                ],
            }
            if context_attestation != dict(expected_context):
                return False, "niche lifecycle execution context changed"
        if expected_attestation["identity_debt_count"] > 0:
            return False, (
                "unresolved niche producer identity debt requires "
                "RECONCILE_PRODUCER_IDENTITY"
            )
    result = row.get("result") if isinstance(row, dict) else None
    outcome = row.get("outcome") if isinstance(row, dict) else None
    # Legacy/no-output rows remain reusable. Positive-output rows must carry
    # and retain their structural referents.
    output_count = 0
    if isinstance(result, dict):
        for key in ("appended", "recovered", "emitted"):
            output_count = max(output_count, int(result.get(key, 0) or 0))
    if not isinstance(outcome, dict):
        return (output_count == 0, "positive result has no outcome binding")
    expected = outcome.get("inventory_referents")
    if not isinstance(expected, list):
        return (output_count == 0, "outcome referent list missing")
    current = _depth_inventory_structural_referents(scratchpad)
    for referent in expected:
        if not isinstance(referent, dict):
            return False, "malformed outcome referent"
        finding_id = str(referent.get("finding_id", "")).strip().upper()
        source_ids = {
            str(value).strip().upper()
            for value in referent.get("source_ids", [])
            if str(value).strip()
        }
        if not finding_id or finding_id not in current:
            return False, f"finding referent vanished: {finding_id or '(empty)'}"
        if not source_ids.issubset(current[finding_id]):
            return False, f"Source IDs changed for {finding_id}"
    if output_count > len(expected):
        return False, "fewer structural referents than emitted/promoted outputs"
    return True, ""


def _write_depth_finalization_review(
    scratchpad: Path, receipt: dict[str, Any]
) -> None:
    failed = [
        (name, row)
        for name, row in receipt.get("processors", {}).items()
        if isinstance(row, dict) and row.get("status") == "FAILED"
    ]
    path = Path(scratchpad) / _DEPTH_FINALIZATION_REVIEW
    if not failed:
        try:
            path.unlink(missing_ok=True)
        except OSError:
            pass
        return
    lines = [
        "# Depth Finalization — Human Review Required",
        "",
        "**Status**: DEGRADED_HUMAN_REVIEW",
        f"**Source digest**: `{receipt.get('source_digest', '')}`",
        "",
        "One or more additive recall postprocessors failed after the accepted "
        "depth boundary. The pipeline may continue, but their candidate class "
        "must be reviewed manually; this record must not be treated as a clean "
        "methodology-application receipt.",
        "",
        "| Processor | Error |",
        "|---|---|",
    ]
    for name, row in failed:
        error = str(row.get("error", "unknown error")).replace("|", "/")
        lines.append(f"| {name} | {error} |")
    lines.extend(["", "<!-- PLAMEN_STATUS: COMPLETE -->", ""])
    path.write_text("\n".join(lines), encoding="utf-8")


def _run_accepted_depth_postprocessors(
    phase_name: str,
    scratchpad: Path,
    *,
    accepted: bool,
    recovery_preflight: bool,
    config: Optional[Mapping[str, Any]] = None,
) -> dict[str, Any]:
    """Finalize additive depth outputs once, after the depth gate accepts.

    These generators/promoters mutate the canonical inventory and maintain
    bounded per-run receipts.  Running them after a structurally failed worker
    attempt consumed a fresh candidate tranche before the retry and amplified
    duplicate seeds.  The raw worker artifacts remain on disk during retry;
    finalization is therefore lossless when deferred until acceptance.
    """
    if not accepted:
        return {"status": "DEFERRED_UNTIL_ACCEPTED"}

    execution_context = _depth_finalization_execution_context(
        phase_name, Path(scratchpad), config
    )
    source_digest, source_files = _depth_finalization_source_digest(scratchpad)
    prior = _load_depth_finalization_receipt(scratchpad)
    if (
        prior.get("schema_version") == 2
        and prior.get("phase") == phase_name
        and prior.get("source_digest") == source_digest
        and prior.get("execution_context") == {
            key: value for key, value in execution_context.items()
            if key != "context_sha256"
        }
        and prior.get("execution_context_sha256")
        == execution_context["context_sha256"]
    ):
        receipt = prior
    else:
        prior_processors = (
            prior.get("processors")
            if isinstance(prior.get("processors"), Mapping)
            else {}
        )
        carried_processors: dict[str, Any] = {}
        carried_invalidated: list[str] = []
        for processor_name, processor_row in prior_processors.items():
            if not isinstance(processor_row, Mapping):
                continue
            carried_processors[str(processor_name)] = {
                "status": "INVALIDATED",
                "invalidated_at": datetime.now(timezone.utc).isoformat(),
                "error": "depth finalization execution context changed",
                "previous": dict(processor_row),
            }
            carried_invalidated.append(str(processor_name))
        receipt = {
            "schema_version": 2,
            "phase": phase_name,
            "source_digest": source_digest,
            "source_files": source_files,
            "execution_context": {
                key: value for key, value in execution_context.items()
                if key != "context_sha256"
            },
            "execution_context_sha256": execution_context["context_sha256"],
            "status": "IN_PROGRESS",
            "processors": carried_processors,
        }
        if carried_invalidated:
            receipt["invalidated_processors"] = sorted(carried_invalidated)

    processors = receipt.setdefault("processors", {})
    expected = (
        "niche_promotion",
        "blind_spot_recovery",
        "enumeration_gate",
        "variant_gate",
    )
    all_complete = all(
        isinstance(processors.get(name), dict)
        and processors[name].get("status") == "COMPLETE"
        for name in expected
    )
    if all_complete:
        invalidated: list[str] = []
        for name in expected:
            valid, reason = _depth_processor_outcome_valid(
                scratchpad,
                name,
                processors[name],
                expected_context=execution_context,
            )
            if valid:
                continue
            previous = dict(processors[name])
            processors[name] = {
                "status": "INVALIDATED",
                "invalidated_at": datetime.now(timezone.utc).isoformat(),
                "error": reason,
                "previous": previous,
            }
            invalidated.append(name)
        if invalidated:
            receipt["status"] = "IN_PROGRESS"
            receipt["reused"] = False
            receipt["invalidated_processors"] = invalidated
            _write_depth_finalization_receipt(scratchpad, receipt)
        else:
            receipt["status"] = "FINALIZED"
            receipt["reused"] = True
            _write_depth_finalization_receipt(scratchpad, receipt)
            _write_depth_finalization_review(scratchpad, receipt)
            return receipt

    def _niche() -> dict[str, Any]:
        promotion_kwargs: dict[str, Any] = {}
        if config is not None:
            run_id = str(config.get("_run_id") or "").strip()
            if not run_id:
                raise RuntimeError(
                    "niche lifecycle promotion requires the canonical driver run_id"
                )
            pipeline = str(config.get("pipeline") or "sc").strip().lower()
            ecosystem = str(
                config.get("language")
                or config.get("ecosystem")
                or ("l1" if pipeline == "l1" else "evm")
            ).strip().lower()
            promotion_kwargs = {
                "project_root": Path(
                    str(config.get("project_root") or Path(scratchpad).parent)
                ),
                "run_id": run_id,
                "pipeline": pipeline,
                "mode": str(config.get("mode") or "thorough").strip().lower(),
                "ecosystem": ecosystem,
                "backend": str(
                    config.get("cli_backend")
                    or config.get("backend")
                    or "claude"
                ).strip().lower(),
            }
        parsed, appended = promote_niche_to_inventory(
            scratchpad,
            **promotion_kwargs,
        )
        identity_debt = read_niche_identity_debt_sidecar(scratchpad)
        if identity_debt is None:
            raise RuntimeError(
                "niche promotion did not publish niche_identity_debt.json"
            )
        attestation = _niche_identity_debt_attestation(identity_debt)
        if attestation["identity_debt_count"] > 0:
            return {
                "status": "FAILED",
                "parsed": parsed,
                "appended": appended,
                "artifact": "niche_identity_debt.json",
                "artifact_sha256": attestation["identity_debt_sha256"],
                "blocking_debt_count": attestation["identity_debt_count"],
                "required_action": "RECONCILE_PRODUCER_IDENTITY",
                "error": (
                    "unresolved niche producer identity debt; clean "
                    "finalization authority denied"
                ),
                **attestation,
            }
        if appended:
            log.info(
                f"[{phase_name}] promoted {appended} niche finding(s) to "
                f"findings_inventory.md (parsed {parsed} total; see "
                "niche_promotion_receipt.md)"
            )
        elif parsed:
            log.info(
                f"[{phase_name}] niche promotion: {parsed} parsed, 0 newly "
                "appended (already promoted on prior accepted boundary)"
            )
        return {"parsed": parsed, "appended": appended, **attestation}

    def _blind_spot() -> dict[str, int]:
        parsed, recovered = promote_blind_spot_to_inventory(scratchpad)
        if recovered:
            log.info(
                f"[{phase_name}] recovered {recovered} LEAKED blind-spot "
                f"finding(s) into findings_inventory.md (parsed {parsed}; see "
                "blind_spot_promotion_receipt.md)"
            )
        return {"parsed": parsed, "recovered": recovered}

    def _enumeration() -> dict[str, Any]:
        import enumeration_gate as _eg

        result = _eg.run_enumeration_gate(scratchpad)
        if result.get("emitted"):
            log.info(
                f"[{phase_name}] enumeration gate: {result['obligations']} "
                f"obligation(s), emitted {result['emitted']} ENUMGAP "
                "candidate(s) for verification (see "
                "enumeration_obligations.md)"
            )
        return result

    def _variant() -> dict[str, Any]:
        result = _run_gate_v_for_phase(phase_name, scratchpad)
        if isinstance(result, dict) and result.get("status") == "FAILED":
            raise RuntimeError(str(result.get("error", "variant gate failed")))
        return result

    runners: tuple[tuple[str, Callable[[], Any]], ...] = (
        ("niche_promotion", _niche),
        ("blind_spot_recovery", _blind_spot),
        ("enumeration_gate", _enumeration),
        ("variant_gate", _variant),
    )
    receipt["reused"] = False
    receipt["recovery_preflight"] = bool(recovery_preflight)
    for name, runner in runners:
        current = processors.get(name)
        required_outcome: dict[str, Any] | None = None
        if isinstance(current, dict):
            if isinstance(current.get("outcome"), dict):
                required_outcome = current["outcome"]
            elif isinstance(current.get("previous"), dict) and isinstance(
                current["previous"].get("outcome"), dict
            ):
                required_outcome = current["previous"]["outcome"]
        if isinstance(current, dict) and current.get("status") == "COMPLETE":
            valid, reason = _depth_processor_outcome_valid(
                scratchpad,
                name,
                current,
                expected_context=execution_context,
            )
            if valid:
                continue
            processors[name] = {
                "status": "INVALIDATED",
                "invalidated_at": datetime.now(timezone.utc).isoformat(),
                "error": reason,
                "previous": dict(current),
            }
        processors[name] = {
            "status": "RUNNING",
            "started_at": datetime.now(timezone.utc).isoformat(),
        }
        receipt["status"] = "IN_PROGRESS"
        _write_depth_finalization_receipt(scratchpad, receipt)
        result: Any = None
        try:
            before_referents = _depth_inventory_structural_referents(scratchpad)
            result = runner()
            if isinstance(result, dict) and str(result.get("status", "")).upper() in {
                "ERROR", "FAILED", "FAILURE"
            }:
                raise RuntimeError(
                    str(result.get("error") or result.get("reason") or result["status"])
                )
            after_referents = _depth_inventory_structural_referents(scratchpad)
            outcome = _depth_processor_outcome(before_referents, after_referents)
            if required_outcome:
                missing_required: list[str] = []
                for referent in required_outcome.get("inventory_referents", []):
                    if not isinstance(referent, dict):
                        missing_required.append("(malformed)")
                        continue
                    finding_id = str(referent.get("finding_id", "")).upper()
                    source_ids = {
                        str(value).upper()
                        for value in referent.get("source_ids", [])
                    }
                    if (
                        finding_id not in after_referents
                        or not source_ids.issubset(after_referents[finding_id])
                    ):
                        missing_required.append(finding_id or "(empty)")
                if missing_required:
                    raise RuntimeError(
                        "processor did not restore invalidated structural "
                        "referent(s): " + ", ".join(missing_required[:12])
                    )
                existing_bound = {
                    str(row.get("finding_id", "")).upper()
                    for row in outcome["inventory_referents"]
                    if isinstance(row, dict)
                }
                for referent in required_outcome.get("inventory_referents", []):
                    if not isinstance(referent, dict):
                        continue
                    if str(referent.get("finding_id", "")).upper() not in existing_bound:
                        outcome["inventory_referents"].append(referent)
            output_count = _depth_processor_output_count(name, result)
            if output_count > len(outcome["inventory_referents"]):
                raise RuntimeError(
                    f"{output_count} output(s) reported but only "
                    f"{len(outcome['inventory_referents'])} new structural "
                    "inventory referent(s) exist"
                )
            processors[name] = {
                "status": "COMPLETE",
                "completed_at": datetime.now(timezone.utc).isoformat(),
                "result": result,
                "outcome": outcome,
            }
        except Exception as exc:
            processors[name] = {
                "status": "FAILED",
                "completed_at": datetime.now(timezone.utc).isoformat(),
                "error": f"{type(exc).__name__}: {exc}"[:2000],
            }
            if (
                isinstance(result, dict)
                and str(result.get("status", "")).upper()
                in {"ERROR", "FAILED", "FAILURE"}
            ):
                processors[name]["result"] = result
            log.warning(
                "[%s] accepted-depth postprocessor %s failed; durable human "
                "review required: %s",
                phase_name,
                name,
                exc,
            )
        _write_depth_finalization_receipt(scratchpad, receipt)

    failed = [
        name
        for name in expected
        if not isinstance(processors.get(name), dict)
        or processors[name].get("status") != "COMPLETE"
    ]
    receipt["status"] = (
        "DEGRADED_HUMAN_REVIEW" if failed else "FINALIZED"
    )
    receipt["failed_processors"] = failed
    receipt["completed_at"] = datetime.now(timezone.utc).isoformat()
    _write_depth_finalization_receipt(scratchpad, receipt)
    _write_depth_finalization_review(scratchpad, receipt)
    return receipt


# ─────────────────────────────────────────────────────────────────────────
# Gate P (Fix C, recall): coverage-seed backfill for promotion-gate output.
#
# `route_promotion_orphans` (plamen_mechanical.py) appends BODY-disposed
# orphans to `findings_inventory.md` as fresh `INV-NNN` NEEDS_VERIFICATION
# candidates AFTER `report_index_coverage_seed.md` has already been written
# (Gate P reconciles against the seed, so it must run after the seed exists —
# see `compute_promotion_orphans`'s no-op-when-seed-absent contract). Left
# alone, those new IDs would be invisible to the Index Agent's STEP 5
# completeness check, which is told to enumerate from the bounded seed/shards
# rather than bulk-reading `findings_inventory.md`.
#
# This helper closes that gap the same way the rest of the coverage-seed
# machinery does: a pure ADDITIVE, idempotent superset append — never
# rewrites or removes an existing row, never touches severity/verdict of any
# other finding. It is a convenience backfill only: even if it fails or is
# skipped, the PROMOGAP findings still physically exist in
# `findings_inventory.md` and are not lost (recall-safe by construction).
# ─────────────────────────────────────────────────────────────────────────

_PROMOGAP_SECTION_RE = re.compile(
    r"##\s*Promotion-Completeness Candidates \(PROMOGAP\)(.*?)(?=\n##\s|\Z)",
    re.DOTALL,
)
_PROMOGAP_BLOCK_RE = re.compile(
    r"###\s*Finding\s*\[(INV-\d+)\][^\n]*\n"
    r"\*\*Severity\*\*:\s*([^\n]*)\n"
    r".*?\*\*Verdict\*\*:\s*([^\n]*)",
    re.DOTALL,
)


_PROMOTION_STRUCTURED_ID_RE = re.compile(
    r"(?<![A-Za-z0-9_-])"
    r"([A-Za-z][A-Za-z0-9]*(?:[_-][A-Za-z0-9]+)*-\d+)"
    r"(?![A-Za-z0-9_-])"
)


def _write_promotion_coverage_seed(scratchpad: Path) -> int:
    """Write the exact pre-verification denominator consumed by Gate P.

    Only structured identity positions are enumerated: inventory finding
    headings, Source-ID fields, canonical finding-mapping rows, and applied
    dedup identities.  Narrative ID-shaped text is deliberately ignored so a
    prose citation cannot falsely mark a lost candidate as already delivered.
    """

    root = Path(scratchpad)
    ids: set[str] = set()
    try:
        subjects: set[str] = set(promotion_reconciled_subjects(root))
    except Exception:
        # No exact retained denominator means no suppression, never a guessed
        # ID/location fallback. Gate P will harvest recall-safely and emit cap
        # debt if the wider denominator exceeds its bound.
        subjects = set()
    inventory = root / "findings_inventory.md"
    if inventory.is_file():
        try:
            text = inventory.read_text(encoding="utf-8", errors="replace")
        except Exception:
            text = ""
        for match in re.finditer(
            r"(?im)^\s*#{2,4}\s+Finding\s+\[([^\]\r\n]+)\]", text
        ):
            identity = match.group(1).strip().upper()
            if _PROMOTION_STRUCTURED_ID_RE.fullmatch(identity):
                ids.add(identity)
        for match in re.finditer(
            r"(?im)^\s*(?:[-*]\s*)?(?:\*\*)?Source\s+IDs?(?:\*\*)?\s*:\s*([^\r\n]+)",
            text,
        ):
            ids.update(
                item.group(1).upper()
                for item in _PROMOTION_STRUCTURED_ID_RE.finditer(match.group(1))
            )
        subjects.update(re.findall(
            r"(?im)^\s*\*\*Promotion Subject SHA256\*\*:\s*([0-9a-f]{64})\s*$",
            text,
        ))

    mapping = root / "finding_mapping.md"
    if mapping.is_file():
        try:
            for row in parse_finding_mapping_rows(
                mapping.read_text(encoding="utf-8", errors="replace")
            ):
                ids.update(str(item).upper() for item in row.get("source_ids", []))
                ids.update(str(item).upper() for item in row.get("hypothesis_ids", []))
        except Exception:
            pass

    try:
        for absorbed, info in _dedup_absorbed_survivor_mapping(root).items():
            ids.add(str(absorbed).upper())
            survivor = str((info or {}).get("survivor") or "").upper()
            if survivor:
                ids.add(survivor)
    except Exception:
        pass

    ids = {
        identity for identity in ids
        if _PROMOTION_STRUCTURED_ID_RE.fullmatch(identity)
    }
    lines = [
        "# Promotion Coverage Seed",
        "",
        "**Status**: DRIVER_ENUMERATED_PREVERIFY",
        "",
        "Exact structured identities already retained before the verification "
        "queue freezes. Gate P uses this only as a coverage denominator.",
        "",
        "| Finding/Hyp ID | Expected Severity | Verdict | Mapped Hypothesis | Dedup Relation |",
        "|---|---|---|---|---|",
    ]
    lines.extend(f"| {identity} | | RETAINED | | |" for identity in sorted(ids))
    if not ids:
        lines.append("| (none) | | | | no structured identities found |")
    lines.extend([
        "",
        "## Delivered Promotion Subjects",
        "",
        "Full cryptographic subjects already materialized in the canonical "
        "inventory. Producer-local IDs and location similarity are not subject "
        "identity.",
        "",
        "| Subject SHA256 | Status |",
        "|---|---|",
    ])
    lines.extend(
        f"| {subject} | DELIVERED |" for subject in sorted(subjects)
    )
    if not subjects:
        lines.append("| (none) | no delivered promotion subjects |")
    _atomic_driver_bytes(
        root / "promotion_coverage_seed.md",
        ("\n".join(lines) + "\n").encode("utf-8"),
    )
    return len(ids)


def _run_gate_p_before_verify_queue(
    scratchpad: Path, *, owner_phase: str = "verify_queue"
) -> dict:
    """Harvest promotion gaps before semantic dedup / queue immutability."""

    root = Path(scratchpad)
    zero_result = {
        "harvested": 0,
        "body_candidates": 0,
        "appendix_c": 0,
        "appendix_a": 0,
        "emitted_to_inventory": 0,
    }
    try:
        _write_promotion_coverage_seed(root)
        orphans = compute_promotion_orphans(root)
        result = route_promotion_orphans(root, orphans)
    except Exception as exc:
        _append_phase_io_debt(
            root,
            owner_phase,
            "PROMOTION_PREVERIFY_DEBT",
            f"Gate P preverify transaction failed: {type(exc).__name__}: {exc}",
        )
        return zero_result
    if result.get("emitted_to_inventory"):
        log.info(
            "[%s] Gate P delivered %d recovered candidate(s) before the "
            "next destructive boundary",
            owner_phase,
            result["emitted_to_inventory"],
        )
    return result


def _run_gate_p_with_semantic_invalidation(
    scratchpad: Path,
    config: Mapping[str, Any],
    checkpoint: Checkpoint,
    *,
    owner_phase: str,
) -> dict[str, Any]:
    """Run Gate P under an exact paired arm-before-write transaction."""

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(checkpoint.run_id or config.get("_run_id") or "").strip()
    events: list[Mapping[str, Any]] = []
    if run_id:
        try:
            for identity, kind in (
                (
                    "scratchpad:_id_ledger.json",
                    "GATE_P_ADDITIVE_PROMOTION_ID_LEDGER",
                ),
                (
                    "scratchpad:finding_records.json",
                    "GATE_P_ADDITIVE_PROMOTION_RECORDS",
                ),
                (
                    "scratchpad:findings_inventory.md",
                    "GATE_P_ADDITIVE_PROMOTION",
                ),
            ):
                events.append(
                    arm_semantic_mutation(
                        root,
                        project_root,
                        artifact_identity=identity,
                        mutation_kind=kind,
                        run_id=run_id,
                    )
                )
        except ArtifactLedgerError as exc:
            for event in _driver_semantic_mutation_finalize_order(events):
                _finalize_driver_semantic_mutation(
                    root,
                    config,
                    checkpoint,
                    event,
                    owner_phase=owner_phase,
                )
            _append_phase_io_debt(
                root, owner_phase, "SEMANTIC_MUTATION_ARM_DEBT", str(exc)
            )
            # Gate P's source artifacts remain intact.  Do not publish a
            # half-owned canonical pair merely to keep this additive pass
            # moving; the next run may retry from the same denominator.
            return {
                "harvested": 0,
                "body_candidates": 0,
                "appendix_c": 0,
                "appendix_a": 0,
                "emitted_to_inventory": 0,
            }
    result = _run_gate_p_before_verify_queue(
        root, owner_phase=owner_phase
    )
    if result.get("emitted_to_inventory"):
        try:
            inventory_raw = (root / "findings_inventory.md").read_bytes()
            _atomic_driver_bytes(
                root / "finding_records.json",
                derive_preverify_finding_records_bytes(inventory_raw),
            )
        except (OSError, RuntimeError, TypeError, ValueError) as exc:
            _append_phase_io_debt(
                root,
                owner_phase,
                "GATE_P_RECORD_PROJECTION_DEBT",
                f"{type(exc).__name__}: {exc}",
            )
    for event in _driver_semantic_mutation_finalize_order(events):
        for issue in _finalize_driver_semantic_mutation(
            root,
            config,
            checkpoint,
            event,
            owner_phase=owner_phase,
        ):
            _append_phase_io_debt(
                root,
                owner_phase,
                "SEMANTIC_MUTATION_CHECKPOINT_DEBT",
                issue,
            )
    return result


def _promote_cross_domain_with_semantic_invalidation(
    scratchpad: Path,
    config: Mapping[str, Any],
    checkpoint: Checkpoint,
    *,
    owner_phase: str,
) -> list[str]:
    """Append L1 cross-domain candidates under arm-before-write authority."""

    root = Path(scratchpad)
    project_root = Path(str(config.get("project_root") or root.parent))
    run_id = str(checkpoint.run_id or config.get("_run_id") or "").strip()
    events: list[Mapping[str, Any]] = []
    if run_id:
        try:
            for identity, kind in (
                (
                    "scratchpad:_id_ledger.json",
                    "L1_CROSS_DOMAIN_ADDITIVE_PROMOTION_ID_LEDGER",
                ),
                (
                    "scratchpad:finding_records.json",
                    "L1_CROSS_DOMAIN_ADDITIVE_PROMOTION_RECORDS",
                ),
                (
                    "scratchpad:findings_inventory.md",
                    "L1_CROSS_DOMAIN_ADDITIVE_PROMOTION",
                ),
            ):
                events.append(
                    arm_semantic_mutation(
                        root,
                        project_root,
                        artifact_identity=identity,
                        mutation_kind=kind,
                        run_id=run_id,
                    )
                )
        except ArtifactLedgerError as exc:
            for event in _driver_semantic_mutation_finalize_order(events):
                _finalize_driver_semantic_mutation(
                    root,
                    config,
                    checkpoint,
                    event,
                    owner_phase=owner_phase,
                )
            _append_phase_io_debt(
                root, owner_phase, "SEMANTIC_MUTATION_ARM_DEBT", str(exc)
            )
            # A destructive consumer must not inherit an unowned additive
            # postimage. Leave the candidate source visible and retry under a
            # valid current-run authority instead of writing anyway.
            return []
    promoted = _promote_cross_domain_candidates_to_inventory(root)
    if promoted:
        try:
            inventory_raw = (root / "findings_inventory.md").read_bytes()
            _atomic_driver_bytes(
                root / "finding_records.json",
                derive_preverify_finding_records_bytes(inventory_raw),
            )
        except (OSError, RuntimeError, TypeError, ValueError) as exc:
            _append_phase_io_debt(
                root,
                owner_phase,
                "CROSS_DOMAIN_RECORD_PROJECTION_DEBT",
                f"{type(exc).__name__}: {exc}",
            )
    for event in _driver_semantic_mutation_finalize_order(events):
        for issue in _finalize_driver_semantic_mutation(
            root,
            config,
            checkpoint,
            event,
            owner_phase=owner_phase,
        ):
            _append_phase_io_debt(
                root,
                owner_phase,
                "SEMANTIC_MUTATION_CHECKPOINT_DEBT",
                issue,
            )
    return promoted


_L1_DEDUP_PAIR_PACKET_OUTPUTS = (
    "dedup_blocks.md",
    "dedup_candidate_pairs.md",
    "dedup_candidate_pairs_full.md",
    "dedup_focus_inventory.md",
)


def _l1_dedup_pair_candidate_contract_and_launch(
    *,
    config: Mapping[str, Any],
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the sole typed producer for the L1 bounded dedup packet."""

    contract = resolve_phase_io_contract(
        pipeline="l1",
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(
            config.get("ecosystem") or config.get("language") or "rust"
        ),
        backend=str(
            config.get("cli_backend") or config.get("backend") or "claude"
        ),
        phase="semantic_dedup",
        work_unit_id="dedup_pair_candidates",
        exact_inputs=("findings_inventory.md",),
        exact_outputs=_L1_DEDUP_PAIR_PACKET_OUTPUTS,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=(),
    )
    return contract, launch


def _dedup_packet_blocked_count(blocks_raw: bytes) -> int:
    """Recover the informational placed count without rerunning enumeration."""

    try:
        text = blocks_raw.decode("utf-8", errors="strict")
    except UnicodeError:
        return 0
    match = re.search(
        r"(?im)^\s*(\d+)\s+finding\(s\)\s+grouped\s+into\s+\d+\s+block",
        text,
    )
    return int(match.group(1)) if match else 0


def _materialize_complete_l1_dedup_pair_packet(
    root: Path,
    *,
    blocked: int,
) -> None:
    """Fill only deterministic empty/compat projections after the typed arm."""

    blocks = root / "dedup_blocks.md"
    pairs = root / "dedup_candidate_pairs.md"
    full = root / "dedup_candidate_pairs_full.md"
    focus = root / "dedup_focus_inventory.md"
    if not blocks.is_file():
        _atomic_driver_bytes(
            blocks,
            (
                "# Dedup Candidate Blocks\n\n"
                "No candidate duplicate blocks found.\n"
            ).encode("utf-8"),
        )
    if not pairs.is_file():
        _atomic_driver_bytes(
            pairs,
            (
                "# Dedup Candidate Pairs\n\n"
                "No candidate duplicate pairs found.\n"
            ).encode("utf-8"),
        )
    # The legacy pair builder emits the full-set sidecar only when its live cap
    # defers rows.  When every pair is live, the live packet is the exact full
    # denominator and can be projected byte-for-byte.
    if not full.is_file():
        _atomic_driver_bytes(full, pairs.read_bytes())
    if not focus.is_file():
        if blocked > 0:
            # A missing non-empty focus projection means the best-effort parser
            # failed after enumeration.  Preserve recall with the complete
            # inventory instead of publishing an empty body packet.
            _atomic_driver_bytes(
                focus,
                (root / "findings_inventory.md").read_bytes(),
            )
        else:
            _atomic_driver_bytes(
                focus,
                (
                    "# Dedup Focus Inventory\n\n"
                    "No candidate finding bodies were selected.\n"
                ).encode("utf-8"),
            )


def _run_l1_dedup_pair_candidate_phase(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
) -> tuple[int, list[str]]:
    """Arm, enumerate, and commit the L1 dedup signal denominator."""

    root = Path(scratchpad)
    project = Path(project_root)
    run = str(run_id or config.get("_run_id") or "").strip()
    if not run:
        return 0, ["L1 dedup pair-candidate PhaseIO run_id is absent"]
    contract, launch = _l1_dedup_pair_candidate_contract_and_launch(
        config=config
    )
    execute, issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=project,
        contract=contract,
        launch=launch,
        run_id=run,
    )
    if issues:
        return 0, list(dict.fromkeys(issues))
    if not execute:
        blocks_path = root / "dedup_blocks.md"
        blocked = (
            _dedup_packet_blocked_count(blocks_path.read_bytes())
            if blocks_path.is_file()
            else 0
        )
        return blocked, []

    # The parser owns no authority itself.  This is deliberately the first
    # output-side effect after the exact inventory input has been armed.
    # A deterministic producer fault must not escape and halt a recall-safe
    # precision phase.  Leave the INPUTS_BOUND unit and any partial bytes
    # untrusted, return durable debt to the caller, and let the separately
    # typed inventory-only passthrough preserve every canonical finding.
    try:
        blocked = int(_compute_dedup_candidate_blocks(root) or 0)
        _materialize_complete_l1_dedup_pair_packet(root, blocked=blocked)
        issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run,
        )
        return blocked, list(dict.fromkeys(issues))
    except Exception as exc:
        return 0, [
            "DEDUP_PAIR_CANDIDATE deterministic producer failed after "
            f"pre-execution arm: {type(exc).__name__}: {exc}"
        ]


def _l1_prequeue_apply_authority_exists(
    root: Path,
    *,
    config: Mapping[str, Any],
    run_id: str,
) -> bool:
    """Whether transaction recovery, rather than preparation, owns the phase."""

    run = str(run_id or config.get("_run_id") or "").strip()
    if not run:
        return False
    key = canonical_work_unit_key(
        "l1",
        str(config.get("mode") or "thorough"),
        str(config.get("ecosystem") or config.get("language") or "rust"),
        str(config.get("cli_backend") or config.get("backend") or "claude"),
        "semantic_dedup",
        "prequeue_apply",
    )
    try:
        unit = read_artifact_ledger(Path(root)).get(
            "work_units", {}
        ).get(key)
    except ArtifactLedgerError:
        return False
    return bool(
        isinstance(unit, Mapping)
        and unit.get("run_id") == run
        and (
            (
                unit.get("semantic_status") == "INPUTS_BOUND"
                and unit.get("execution_state")
                == "INPUTS_BOUND_PREEXECUTION"
            )
            or (
                unit.get("semantic_status") == "ACTIVE"
                and unit.get("execution_state") == "OUTPUT_COMMITTED"
            )
        )
    )


def _l1_prequeue_apply_is_committed(
    root: Path,
    *,
    config: Mapping[str, Any],
    run_id: str,
) -> bool:
    """Whether the paired successor is fully committed and phase-skippable."""

    run = str(run_id or config.get("_run_id") or "").strip()
    if not run:
        return False
    key = canonical_work_unit_key(
        "l1",
        str(config.get("mode") or "thorough"),
        str(config.get("ecosystem") or config.get("language") or "rust"),
        str(config.get("cli_backend") or config.get("backend") or "claude"),
        "semantic_dedup",
        "prequeue_apply",
    )
    root_path = Path(root)
    project = Path(str(config.get("project_root") or root_path.parent))
    try:
        unit = read_artifact_ledger(root_path).get(
            "work_units", {}
        ).get(key)
        if not (
            isinstance(unit, Mapping)
            and unit.get("run_id") == run
            and unit.get("semantic_status") == "ACTIVE"
            and unit.get("execution_state") == "OUTPUT_COMMITTED"
        ):
            return False
        bindings = unit.get("input_bindings")
        if not isinstance(bindings, Mapping):
            return False
        observed_inputs = set(bindings)
        if observed_inputs == {"scratchpad:dedup_decisions.md"}:
            exact_inputs = ("dedup_decisions.md",)
        elif observed_inputs == {
            "scratchpad:dedup_decisions.md",
            "scratchpad:" + _L1_SUPPLEMENTAL_PROPOSAL_NAME,
        }:
            exact_inputs = (
                "dedup_decisions.md",
                _L1_SUPPLEMENTAL_PROPOSAL_NAME,
            )
        else:
            return False
        contract = resolve_phase_io_contract(
            pipeline="l1",
            mode=str(config.get("mode") or "thorough"),
            ecosystem=str(
                config.get("ecosystem") or config.get("language") or "rust"
            ),
            backend=str(
                config.get("cli_backend")
                or config.get("backend")
                or "claude"
            ),
            phase="semantic_dedup",
            work_unit_id="prequeue_apply",
            exact_inputs=exact_inputs,
            exact_outputs=tuple(SEMANTIC_DEDUP_TRANSACTION_OUTPUTS),
        )
        launch = LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver",
            timeout_s=300,
            exec_mode="python",
            tool_policy=(),
        )
        if (
            unit.get("contract_digest") != contract.digest
            or unit.get("launch_digest") != launch.digest
            or validate_work_unit_artifacts(
                root_path,
                project,
                contract,
                launch,
                run_id=run,
                actor="DRIVER",
                # A committed semantic transaction owns a frozen generation.
                # Its proposal is historical evidence, not a live resume
                # dependency; exact generation/receipt replay happens before
                # any downstream consumer is authorized.
                require_live_input_authority=False,
            )
        ):
            return False
        import semantic_dedup_authority as dedup_authority

        inventory = (root_path / "findings_inventory.md").read_text(
            encoding="utf-8", errors="strict"
        )
        dedup_authority.load_applied_aliases(
            root_path, canonical_text=inventory
        )
        return True
    except (
        ArtifactLedgerError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
    ):
        return False


def _prepare_l1_semantic_dedup_inventory(
    *,
    scratchpad: Path,
    config: dict[str, Any],
    checkpoint: Checkpoint,
) -> list[str]:
    """Freeze every ordinary L1 additive producer before semantic dedup.

    This boundary is deliberately earlier than ``verify_queue``. A semantic
    merge is allowed to reduce only the complete ordinary inventory, never an
    already-published queue. Compound-composition proposals remain a separate
    additive T4 queue delta and therefore cannot cause an ordinary row to
    disappear.
    """

    root = Path(scratchpad)
    issues: list[str] = []
    run_id = str(checkpoint.run_id or config.get("_run_id") or "")
    config.pop("_l1_semantic_dedup_packet_launch_veto", None)
    if _l1_prequeue_apply_authority_exists(
        root,
        config=config,
        run_id=run_id,
    ):
        # The paired RMW transaction has already frozen its exact proposal and
        # output prestates.  Re-running additive feeders or packet enumeration
        # here would create a new denominator behind that authority.  Recover
        # and validate that exact transaction now; status bits alone are never
        # permission to skip over tampered or incomplete successor bytes.
        try:
            replayed = _run_l1_prequeue_semantic_dedup_transaction(
                scratchpad=root,
                project_root=Path(
                    str(config.get("project_root") or root.parent)
                ),
                config=config,
                run_id=run_id,
            )
            if (
                replayed.get("safe_to_consume") is not True
                or not _l1_prequeue_apply_is_committed(
                    root,
                    config=config,
                    run_id=run_id,
                )
            ):
                raise ArtifactLedgerError(
                    "existing prequeue semantic-dedup successor did not "
                    "replay as exact committed authority"
                )
            return []
        except Exception as exc:
            issue = (
                "L1_PREQUEUE_SEMANTIC_DEDUP_RECOVERY failed: "
                f"{type(exc).__name__}: {exc}"
            )
            config["_l1_semantic_dedup_packet_launch_veto"] = True
            _append_phase_io_debt(
                root,
                "semantic_dedup",
                "L1_PREQUEUE_SEMANTIC_DEDUP_RECOVERY",
                issue,
            )
            return [issue]
    if not _inventory_has_usable_findings(root):
        floor_n, floor_sources = ensure_findings_inventory_floor(root)
        if floor_n <= 0 and floor_sources > 0:
            issues.append(
                "inventory floor found no usable finding among completed "
                f"sources ({floor_sources} scanned)"
            )

    promoted = _promote_findings_with_semantic_invalidation(
        root,
        config,
        checkpoint,
        owner_phase="semantic_dedup",
    )
    if promoted:
        log.info(
            "[semantic_dedup] promoted %d depth finding(s) before the "
            "destructive precision boundary",
            len(promoted),
        )
    cross_domain = _promote_cross_domain_with_semantic_invalidation(
        root,
        config,
        checkpoint,
        owner_phase="semantic_dedup",
    )
    if cross_domain:
        log.info(
            "[semantic_dedup] promoted %d cross-domain candidate(s) before "
            "semantic dedup",
            len(cross_domain),
        )
    _run_gate_p_with_semantic_invalidation(
        root,
        config,
        checkpoint,
        owner_phase="semantic_dedup",
    )
    delivery_issues = _validate_registered_finding_delivery_receipt(root)
    if delivery_issues:
        issues.extend(str(item) for item in delivery_issues)
        _append_phase_io_debt(
            root,
            "semantic_dedup",
            "REGISTERED_PRODUCER_DELIVERY_DEBT",
            "; ".join(delivery_issues),
        )

    cap = _dedup_live_pair_cap()
    blocked, packet_issues = _run_l1_dedup_pair_candidate_phase(
        scratchpad=root,
        project_root=Path(
            str(config.get("project_root") or root.parent)
        ),
        config=config,
        run_id=run_id,
    )
    if packet_issues:
        config["_l1_semantic_dedup_packet_launch_veto"] = True
        issues.extend(packet_issues)
        _append_phase_io_debt(
            root,
            "semantic_dedup",
            "DEDUP_PAIR_CANDIDATE_PHASE_IO",
            "; ".join(packet_issues),
        )
        try:
            degraded = _run_l1_semantic_dedup_noop_proposal(
                scratchpad=root,
                project_root=Path(
                    str(config.get("project_root") or root.parent)
                ),
                config=config,
                run_id=run_id,
                reason=(
                    "dedup pair-packet producer unavailable; signal "
                    "enumeration is unavailable and grants no negative "
                    "conclusion"
                ),
            )
            if degraded.get("safe_to_consume") is not True:
                raise ArtifactLedgerError(
                    "inventory-only degraded semantic-dedup successor did "
                    "not commit"
                )
            config.pop("_l1_semantic_dedup_packet_launch_veto", None)
        except Exception as exc:
            degrade_issue = (
                "L1_DEDUP_PACKET_DEGRADED_PASSTHROUGH failed: "
                f"{type(exc).__name__}: {exc}"
            )
            issues.append(degrade_issue)
            _append_phase_io_debt(
                root,
                "semantic_dedup",
                "L1_DEDUP_PACKET_DEGRADED_PASSTHROUGH",
                degrade_issue,
            )
    log.info(
        "[semantic_dedup] compatibility pair cap=%d; prepared %d inventory "
        "finding(s) in bounded candidate blocks",
        cap,
        blocked,
    )
    issues.extend(_validate_depth_promotion_dedup(root))
    return list(dict.fromkeys(str(item) for item in issues if str(item)))


def _semantic_dedup_attestation(
    request: SemanticDedupAuthorityRequest,
    *,
    action: str,
    authority_kind: str,
    status: str,
    authority_id: str,
    evidence: Mapping[str, Any],
) -> dict[str, Any]:
    """Build one deterministic external-authority attestation for `_sdt`."""

    unsigned = {
        "schema_version": "plamen.semantic_dedup_external_attestation.v1",
        "run_id": request.run_id,
        "phase": request.phase,
        "generation_digest": request.generation_digest,
        "action": action,
        "authority_kind": authority_kind,
        "status": status,
        "authority_id": str(authority_id),
        "evidence": json.loads(json.dumps(
            dict(evidence),
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        )),
    }
    digest = hashlib.sha256(
        json.dumps(
            unsigned,
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return {**unsigned, "authority_digest": digest}


def _semantic_dedup_core_rows_from_unit(
    unit: Mapping[str, Any],
    contract: PhaseIOContract,
) -> tuple[tuple[dict[str, Any], ...], tuple[dict[str, Any], ...]]:
    """Translate the immutable PhaseIO arm into `_sdt`'s minimal rows."""

    raw_inputs = unit.get("input_bindings")
    raw_prestates = unit.get("output_prestates")
    if not isinstance(raw_inputs, Mapping) or not isinstance(
        raw_prestates, Mapping
    ):
        raise ArtifactLedgerError(
            "semantic-dedup PhaseIO arm has no exact input/prestate receipt"
        )
    expected_input_ids = set(contract.immutable_inputs) | set(
        contract.bounded_lookup_inputs
    )
    if set(raw_inputs) != expected_input_ids:
        raise ArtifactLedgerError(
            "semantic-dedup PhaseIO input denominator changed"
        )
    inputs: list[dict[str, Any]] = []
    for identity in sorted(expected_input_ids):
        row = raw_inputs.get(identity)
        if (
            not isinstance(row, Mapping)
            or row.get("status") != "ACTIVE"
            or not re.fullmatch(
                r"[0-9a-f]{64}", str(row.get("sha256") or "")
            )
            or not isinstance(row.get("size"), int)
        ):
            raise ArtifactLedgerError(
                f"{identity}: semantic-dedup input arm is not active"
            )
        root_name, relative = identity.split(":", 1)
        if root_name != "scratchpad":
            raise ArtifactLedgerError(
                "semantic-dedup transaction accepts scratchpad inputs only"
            )
        inputs.append({
            "path": relative,
            "sha256": str(row["sha256"]),
            "size_bytes": int(row["size"]),
        })

    expected_output_ids = {spec.identity for spec in contract.outputs}
    if set(raw_prestates) != expected_output_ids:
        raise ArtifactLedgerError(
            "semantic-dedup PhaseIO output-prestate denominator changed"
        )
    prestates: list[dict[str, Any]] = []
    for identity in sorted(expected_output_ids):
        row = raw_prestates.get(identity)
        if not isinstance(row, Mapping):
            raise ArtifactLedgerError(
                f"{identity}: semantic-dedup output prestate is malformed"
            )
        root_name, relative = identity.split(":", 1)
        if root_name != "scratchpad":
            raise ArtifactLedgerError(
                "semantic-dedup transaction accepts scratchpad outputs only"
            )
        if row.get("status") in {"MISSING", "ABSENT"}:
            prestates.append({"path": relative, "status": "MISSING"})
            continue
        if (
            not re.fullmatch(
                r"[0-9a-f]{64}", str(row.get("sha256") or "")
            )
            or not isinstance(row.get("size"), int)
        ):
            raise ArtifactLedgerError(
                f"{identity}: semantic-dedup output prestate has no exact bytes"
            )
        prestates.append({
            "path": relative,
            "status": "PRESENT",
            "sha256": str(row["sha256"]),
            "size_bytes": int(row["size"]),
        })
    return tuple(inputs), tuple(prestates)


def _semantic_dedup_phaseio_binding(
    unit: Mapping[str, Any],
    contract: PhaseIOContract,
    launch: LaunchSpec,
    *,
    run_id: str,
    scratchpad: Path,
) -> dict[str, Any]:
    """Stable transaction binding, including semantic-current prestates."""

    prestates = unit.get("output_prestates")
    lineage: dict[str, Any] = {}
    if isinstance(prestates, Mapping):
        for identity, raw in sorted(prestates.items()):
            if not isinstance(raw, Mapping):
                continue
            row: dict[str, Any] = {
                "status": str(raw.get("status") or ""),
                "sha256": str(raw.get("sha256") or ""),
                "size": int(raw.get("size") or 0),
            }
            semantic = raw.get("semantic_predecessor_authority")
            if isinstance(semantic, Mapping):
                row["semantic_predecessor_authority"] = dict(semantic)
            lineage[str(identity)] = row
    input_authority: dict[str, Any] = {}
    raw_inputs = unit.get("input_bindings")
    if isinstance(raw_inputs, Mapping):
        for identity, raw in sorted(raw_inputs.items()):
            if not isinstance(raw, Mapping):
                continue
            bound = {
                key: raw.get(key)
                for key in (
                    "sha256",
                    "size",
                    "producer_work_unit_key",
                    "producer_contract_digest",
                    "producer_launch_digest",
                    "producer_commit_receipt_digest",
                )
                if raw.get(key) not in {None, ""}
            }
            # The apply unit froze the producer receipt when its inputs were
            # bound.  Never reconstruct that denominator from the producer's
            # live ledger row: later repair/quarantine may issue a different
            # terminal receipt for the historical producer without changing
            # the exact bytes consumed by this already-armed transaction.
            input_authority[str(identity)] = bound
    return {
        "schema_version": "plamen.semantic_dedup_phaseio_binding.v1",
        "run_id": run_id,
        "phase": "semantic_dedup",
        "work_unit_key": contract.key,
        "contract_digest": contract.digest,
        "launch_digest": launch.digest,
        "input_set_digest": str(unit.get("input_set_digest") or ""),
        "output_prestate_digest": str(
            unit.get("output_prestate_digest") or ""
        ),
        "input_authority": input_authority,
        "output_prestate_authority": lineage,
    }


_L1_SUPPLEMENTAL_PROPOSAL_NAME = (
    "semantic_dedup_supplemental_proposals.json"
)
_L1_SUPPLEMENTAL_SOURCE_NAMES = (
    "findings_inventory.md",
    "dedup_decisions.md",
    "dedup_candidate_pairs.md",
    "dedup_candidate_pairs_full.md",
)


def _derive_l1_supplemental_dedup_proposals(
    *,
    inventory_raw: bytes,
    decisions_raw: bytes,
    candidate_pairs_raw: bytes,
    candidate_pairs_full_raw: bytes,
    run_id: str,
) -> bytes:
    """Pure conservative proposal deriver exposed for fixture injection."""

    from l1_semantic_dedup_supplemental import (
        derive_supplemental_proposals,
    )

    return derive_supplemental_proposals(
        inventory_raw=inventory_raw,
        decisions_raw=decisions_raw,
        candidate_pairs_raw=candidate_pairs_raw,
        candidate_pairs_full_raw=candidate_pairs_full_raw,
        run_id=run_id,
    )


def _run_l1_supplemental_dedup_proposal_phase(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
) -> Mapping[str, Any]:
    """Publish the deterministic supplemental proposal under DRIVER PhaseIO."""

    from l1_semantic_dedup_supplemental import (
        derive_degraded_supplemental_proposals,
        validate_supplemental_proposals,
    )

    root = Path(scratchpad)
    project = Path(project_root)
    run = str(run_id or config.get("_run_id") or "").strip()
    if not run:
        raise ArtifactLedgerError(
            "L1 supplemental semantic-dedup run_id is absent"
        )
    missing = [
        relative
        for relative in _L1_SUPPLEMENTAL_SOURCE_NAMES
        if not (root / relative).is_file()
    ]
    if missing:
        raise ArtifactLedgerError(
            "L1 supplemental proposal denominator is incomplete: "
            + ", ".join(missing)
        )
    ecosystem = str(
        config.get("ecosystem") or config.get("language") or "rust"
    )
    backend = str(
        config.get("cli_backend") or config.get("backend") or "claude"
    )

    contract = resolve_phase_io_contract(
        pipeline="l1",
        mode=str(config.get("mode") or "thorough"),
        ecosystem=ecosystem,
        backend=backend,
        phase="semantic_dedup",
        work_unit_id="supplemental_proposals",
        exact_inputs=_L1_SUPPLEMENTAL_SOURCE_NAMES,
        exact_outputs=(_L1_SUPPLEMENTAL_PROPOSAL_NAME,),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=(),
    )
    proposal_path = root / _L1_SUPPLEMENTAL_PROPOSAL_NAME
    execute, arm_issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=project,
        contract=contract,
        launch=launch,
        run_id=run,
    )
    if arm_issues:
        raise ArtifactLedgerError(
            "L1 supplemental proposal input authority failed: "
            + "; ".join(arm_issues)
        )
    if execute:
        source = {
            name: (root / name).read_bytes()
            for name in _L1_SUPPLEMENTAL_SOURCE_NAMES
        }
        try:
            proposal_raw = _derive_l1_supplemental_dedup_proposals(
                inventory_raw=source["findings_inventory.md"],
                decisions_raw=source["dedup_decisions.md"],
                candidate_pairs_raw=source["dedup_candidate_pairs.md"],
                candidate_pairs_full_raw=source[
                    "dedup_candidate_pairs_full.md"
                ],
                run_id=run,
            )
        except Exception as exc:
            proposal_raw = derive_degraded_supplemental_proposals(
                inventory_raw=source["findings_inventory.md"],
                decisions_raw=source["dedup_decisions.md"],
                candidate_pairs_raw=source["dedup_candidate_pairs.md"],
                candidate_pairs_full_raw=source[
                    "dedup_candidate_pairs_full.md"
                ],
                run_id=run,
                debt=f"{type(exc).__name__}: {exc}",
            )
        _atomic_driver_bytes(proposal_path, proposal_raw)
        commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run,
        )
        if commit_issues:
            raise ArtifactLedgerError(
                "L1 supplemental proposal output authority failed: "
                + "; ".join(commit_issues)
            )

    ledger = read_artifact_ledger(root)
    unit = ledger.get("work_units", {}).get(contract.key)
    if not (
        isinstance(unit, Mapping)
        and unit.get("run_id") == run
        and unit.get("contract_digest") == contract.digest
        and unit.get("launch_digest") == launch.digest
        and unit.get("execution_state") == "OUTPUT_COMMITTED"
        and unit.get("semantic_status") == "ACTIVE"
    ):
        raise ArtifactLedgerError(
            "L1 supplemental proposal lacks active committed authority"
        )
    if not execute:
        artifact = unit.get("artifacts", {}).get(
            f"scratchpad:{_L1_SUPPLEMENTAL_PROPOSAL_NAME}"
        )
        binding = ledger.get("artifact_bindings", {}).get(
            f"scratchpad:{_L1_SUPPLEMENTAL_PROPOSAL_NAME}"
        )
        if not (
            isinstance(artifact, Mapping)
            and isinstance(binding, Mapping)
            and binding.get("owner_key") == contract.key
            and binding.get("status") == "ACTIVE"
            and proposal_path.is_file()
            and artifact.get("sha256")
            == hashlib.sha256(proposal_path.read_bytes()).hexdigest()
            and artifact.get("size") == proposal_path.stat().st_size
        ):
            raise ArtifactLedgerError(
                "L1 supplemental proposal committed bytes changed"
            )
    source_inventory = (
        unit.get("input_bindings", {})
        .get("scratchpad:findings_inventory.md", {})
    )
    inventory_raw = (
        root / "findings_inventory.md"
    ).read_bytes()
    # Before prequeue publication current bytes equal the proposal source.
    # On replay, validation below is performed by the signed proposal itself
    # against its recorded source digest, while the prequeue transaction owns
    # the historical inventory poststate.
    if (
        hashlib.sha256(inventory_raw).hexdigest()
        != source_inventory.get("sha256")
    ):
        inventory_raw = (
            root
            / "_sdt"
            / next(
                (
                    path.name
                    for path in (root / "_sdt").glob("g_*")
                    if path.is_dir()
                ),
                "",
            )
            / "b0.bin"
        ).read_bytes()
    decisions_raw = (root / "dedup_decisions.md").read_bytes()
    payload = validate_supplemental_proposals(
        proposal_path.read_bytes(),
        inventory_raw=inventory_raw,
        decisions_raw=decisions_raw,
        run_id=run,
    )
    commit = unit.get("commit_authority")
    return {
        "state": str(payload.get("state") or ""),
        "debt": list(payload.get("debt") or ()),
        "proposal_path": _L1_SUPPLEMENTAL_PROPOSAL_NAME,
        "proposal_sha256": hashlib.sha256(
            proposal_path.read_bytes()
        ).hexdigest(),
        "work_unit_key": contract.key,
        "commit_receipt_digest": (
            str(commit.get("receipt_digest") or "")
            if isinstance(commit, Mapping)
            else ""
        ),
    }


def _derive_l1_semantic_dedup_postimages(
    *,
    inventory_raw: bytes,
    decisions_raw: bytes,
    supplemental_proposal_raw: bytes | None = None,
    run_id: str = "",
) -> tuple[
    bytes,
    bytes,
    dict[str, bytes],
    dict[str, dict[str, str]],
    dict[str, Any],
]:
    """Run the existing lossless engine off-canonical and return exact bytes."""

    import semantic_dedup_authority as dedup_authority

    with tempfile.TemporaryDirectory(
        prefix="plamen_l1_semantic_dedup_"
    ) as temp_name:
        staging = Path(temp_name)
        if supplemental_proposal_raw is not None:
            from l1_semantic_dedup_supplemental import (
                apply_supplemental_in_staging,
            )

            combined = apply_supplemental_in_staging(
                staging_dir=staging / "supplemental",
                inventory_raw=inventory_raw,
                model_decisions_raw=decisions_raw,
                proposal_raw=supplemental_proposal_raw,
                run_id=run_id,
            )
            post_inventory = bytes(combined["final_inventory"])
            receipt_raw = bytes(combined["combined_receipt"])
            (staging / "findings_inventory.md").write_bytes(
                post_inventory
            )
            (staging / dedup_authority.PRIMARY_RECEIPT_NAME).write_bytes(
                receipt_raw
            )
            post_text = post_inventory.decode("utf-8", errors="strict")
            aliases = dedup_authority.load_applied_aliases(
                staging, canonical_text=post_text
            )
            _write_dedup_absorbed_map(staging, aliases)
            post_records = derive_preverify_finding_records_bytes(
                post_inventory
            )
            sidecars = {
                SEMANTIC_DEDUP_APPLIED_RECEIPT: receipt_raw,
                SEMANTIC_DEDUP_ABSORBED_MAP: (
                    staging / SEMANTIC_DEDUP_ABSORBED_MAP
                ).read_bytes(),
                SEMANTIC_DEDUP_DEDUPED_INVENTORY: post_inventory,
            }
            return (
                post_inventory,
                post_records,
                sidecars,
                aliases,
                {
                    "supplemental_state": str(
                        combined.get("supplemental_state") or ""
                    ),
                    "supplemental_debt": list(
                        combined.get("supplemental_debt") or ()
                    ),
                },
            )
        (staging / "findings_inventory.md").write_bytes(inventory_raw)
        (staging / "dedup_decisions.md").write_bytes(decisions_raw)
        # KEEP/PASSTHROUGH must still yield a complete successor and receipt.
        (staging / "findings_inventory_deduped.md").write_bytes(
            inventory_raw
        )
        apply_llm_dedup_decisions(staging, "semantic_dedup")
        post_path = staging / "findings_inventory_deduped.md"
        post_inventory = post_path.read_bytes()
        receipt_path = staging / dedup_authority.PRIMARY_RECEIPT_NAME
        if not receipt_path.is_file():
            proposal_text = decisions_raw.decode("utf-8", errors="strict")
            input_text = inventory_raw.decode("utf-8", errors="strict")
            output_text = post_inventory.decode("utf-8", errors="strict")
            dedup_authority.write_applied_receipt(
                staging,
                phase_name="semantic_dedup",
                application_kind="PRIMARY",
                proposal_text=proposal_text,
                proposals=dedup_authority.parse_dedup_proposals(
                    proposal_text
                ),
                input_text=input_text,
                output_text=output_text,
                applied_merges=(),
                rejection_reasons={},
            )
        post_text = post_inventory.decode("utf-8", errors="strict")
        aliases = dedup_authority.load_applied_aliases(
            staging, canonical_text=post_text
        )
        _write_dedup_absorbed_map(staging, aliases)
        post_records = derive_preverify_finding_records_bytes(
            post_inventory
        )
        sidecars = {
            SEMANTIC_DEDUP_APPLIED_RECEIPT: receipt_path.read_bytes(),
            SEMANTIC_DEDUP_ABSORBED_MAP: (
                staging / SEMANTIC_DEDUP_ABSORBED_MAP
            ).read_bytes(),
            SEMANTIC_DEDUP_DEDUPED_INVENTORY: post_inventory,
        }
        return (
            post_inventory,
            post_records,
            sidecars,
            aliases,
            {
                "supplemental_state": "NOT_AVAILABLE",
                "supplemental_debt": [],
            },
        )


_L1_SEMANTIC_DEDUP_NOOP_INPUTS = (
    "findings_inventory.md",
    "dedup_blocks.md",
    "dedup_candidate_pairs.md",
    "dedup_candidate_pairs_full.md",
)


def _l1_dedup_packet_has_current_driver_authority(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
) -> bool:
    """Whether a no-op may bind the complete typed signal denominator."""

    root = Path(scratchpad)
    if any(
        not (root / relative).is_file()
        for relative in _L1_SEMANTIC_DEDUP_NOOP_INPUTS
    ):
        return False
    try:
        contract, launch = _l1_dedup_pair_candidate_contract_and_launch(
            config=config
        )
        return not (
            validate_work_unit_inputs(
                root,
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
            )
            or validate_work_unit_artifacts(
                root,
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            )
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError):
        return False


def _l1_noop_exact_inputs_from_existing_unit(
    unit: Mapping[str, Any] | None,
) -> tuple[str, ...] | None:
    """Recover the immutable no-op denominator across post-apply replay."""

    if not isinstance(unit, Mapping):
        return None
    bindings = unit.get("input_bindings")
    if not isinstance(bindings, Mapping):
        return None
    relative = tuple(
        identity.split(":", 1)[1]
        for identity in bindings
        if str(identity).startswith("scratchpad:")
    )
    observed = set(relative)
    if observed == {"findings_inventory.md"}:
        return ("findings_inventory.md",)
    if observed == set(_L1_SEMANTIC_DEDUP_NOOP_INPUTS):
        return _L1_SEMANTIC_DEDUP_NOOP_INPUTS
    return None


def _run_l1_semantic_dedup_noop_proposal(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
    reason: str,
    fault_hook: Callable[[str], None] | None = None,
) -> Mapping[str, Any]:
    """Publish an honest DRIVER passthrough, then run the normal RMW apply.

    No-signal, malformed-budget, and model-degrade paths are still semantic
    decisions.  This work unit binds the exact signal denominator that caused
    the passthrough and never fabricates a MODEL invocation.
    """

    root = Path(scratchpad)
    project = Path(project_root)
    run = str(run_id or config.get("_run_id") or "").strip()
    why = str(reason or "").strip()
    if not run or not why:
        raise ArtifactLedgerError(
            "L1 semantic-dedup noop proposal run/reason is absent"
        )
    ecosystem = str(
        config.get("ecosystem") or config.get("language") or "rust"
    )
    backend = str(
        config.get("cli_backend") or config.get("backend") or "claude"
    )
    apply_key = canonical_work_unit_key(
        "l1",
        str(config.get("mode") or "thorough"),
        ecosystem,
        backend,
        "semantic_dedup",
        "prequeue_apply",
    )
    apply_unit = read_artifact_ledger(root).get(
        "work_units", {}
    ).get(apply_key)
    if (
        isinstance(apply_unit, Mapping)
        and apply_unit.get("run_id") == run
        and apply_unit.get("semantic_status") in {
            "INPUTS_BOUND",
            "ACTIVE",
        }
        and apply_unit.get("execution_state") in {
            "INPUTS_BOUND_PREEXECUTION",
            "OUTPUT_COMMITTED",
        }
    ):
        # The apply transaction has already frozen its exact decision and
        # supplemental inputs.  A later validator asking for a conservative
        # fallback may recover that transaction, but must not replace an
        # immutable input behind its arm-before-write authority.
        return _run_l1_prequeue_semantic_dedup_transaction(
            scratchpad=root,
            project_root=project,
            config=config,
            run_id=run,
            fault_hook=fault_hook,
        )
    noop_key = canonical_work_unit_key(
        "l1",
        str(config.get("mode") or "thorough"),
        ecosystem,
        backend,
        "semantic_dedup",
        "noop_proposal",
    )
    ledger = read_artifact_ledger(root)
    prior_unit = ledger.get("work_units", {}).get(noop_key)
    signal_inputs = _l1_noop_exact_inputs_from_existing_unit(
        prior_unit if isinstance(prior_unit, Mapping) else None
    )
    if signal_inputs is None:
        signal_inputs = (
            _L1_SEMANTIC_DEDUP_NOOP_INPUTS
            if _l1_dedup_packet_has_current_driver_authority(
                scratchpad=root,
                project_root=project,
                config=config,
                run_id=run,
            )
            else ("findings_inventory.md",)
        )
    if not (root / "findings_inventory.md").is_file():
        raise ArtifactLedgerError(
            "semantic-dedup passthrough inventory denominator is absent"
        )
    contract = resolve_phase_io_contract(
        pipeline="l1",
        mode=str(config.get("mode") or "thorough"),
        ecosystem=ecosystem,
        backend=backend,
        phase="semantic_dedup",
        work_unit_id="noop_proposal",
        exact_inputs=signal_inputs,
        exact_outputs=("dedup_decisions.md",),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=60,
        exec_mode="python",
        tool_policy=(),
    )
    unit = ledger.get("work_units", {}).get(contract.key)
    committed = bool(
        isinstance(unit, Mapping)
        and unit.get("run_id") == run
        and unit.get("contract_digest") == contract.digest
        and unit.get("launch_digest") == launch.digest
        and unit.get("execution_state") == "OUTPUT_COMMITTED"
        and unit.get("semantic_status") == "ACTIVE"
    )
    if not committed:
        if not isinstance(unit, Mapping):
            record_work_unit_inputs(
                root, project, contract, launch, run_id=run
            )
        input_issues = validate_work_unit_inputs(
            root, project, contract, launch, run_id=run
        )
        if input_issues:
            raise ArtifactLedgerError(
                "semantic-dedup noop proposal input authority failed: "
                + "; ".join(input_issues)
            )
        decision_raw = (
            "# Semantic Dedup Decisions\n\n"
            "**Status**: PASSTHROUGH\n\n"
            f"**Reason**: {why}.\n\n"
            + (
                "**Signal Authority**: UNAVAILABLE. No absence-of-duplicates "
                "or other negative conclusion is asserted.\n\n"
                if signal_inputs == ("findings_inventory.md",)
                else
                "**Signal Authority**: EXACT BOUNDED PACKET.\n\n"
            )
            + "No semantic merge decision was applied. Every upstream finding "
            "remains active.\n"
        ).encode("utf-8")
        _atomic_driver_bytes(root / "dedup_decisions.md", decision_raw)
        unit = record_work_unit_artifacts(
            root,
            project,
            contract,
            launch,
            run_id=run,
            actor="DRIVER",
        )
        if not (
            unit.get("execution_state") == "OUTPUT_COMMITTED"
            and unit.get("semantic_status") == "ACTIVE"
        ):
            raise ArtifactLedgerError(
                "semantic-dedup noop proposal was quarantined"
            )
    if committed:
        # ``findings_inventory.md`` is an exact input to this historical
        # proposal and is intentionally replaced by its registered
        # prequeue_apply successor.  Re-validating producer freshness here
        # would reject every legitimate replay.  Instead, validate the
        # proposal's own immutable committed bytes; the successor transaction
        # independently revalidates its exact input receipt below.
        ledger = read_artifact_ledger(root)
        unit = ledger.get("work_units", {}).get(contract.key)
        artifact = (
            unit.get("artifacts", {}).get(
                "scratchpad:dedup_decisions.md"
            )
            if isinstance(unit, Mapping)
            else None
        )
        binding = ledger.get("artifact_bindings", {}).get(
            "scratchpad:dedup_decisions.md"
        )
        decision_path = root / "dedup_decisions.md"
        if not (
            isinstance(artifact, Mapping)
            and isinstance(binding, Mapping)
            and binding.get("owner_key") == contract.key
            and binding.get("status") == "ACTIVE"
            and decision_path.is_file()
            and artifact.get("sha256")
            == hashlib.sha256(decision_path.read_bytes()).hexdigest()
            and artifact.get("size") == decision_path.stat().st_size
        ):
            raise ArtifactLedgerError(
                "semantic-dedup committed noop proposal bytes changed"
            )
    else:
        output_issues = validate_work_unit_artifacts(
            root,
            project,
            contract,
            launch,
            run_id=run,
            actor="DRIVER",
        )
        if output_issues:
            raise ArtifactLedgerError(
                "semantic-dedup noop proposal authority failed: "
                + "; ".join(output_issues)
            )
    return _run_l1_prequeue_semantic_dedup_transaction(
        scratchpad=root,
        project_root=project,
        config=config,
        run_id=run,
        fault_hook=fault_hook,
    )


def _run_l1_prequeue_semantic_dedup_transaction(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
    fault_hook: Callable[[str], None] | None = None,
) -> Mapping[str, Any]:
    """Apply L1 semantic dedup as one crash-safe five-output RMW successor."""

    root = Path(scratchpad)
    project = Path(project_root)
    run = str(run_id or config.get("_run_id") or "").strip()
    if not run:
        raise ArtifactLedgerError(
            "L1 semantic-dedup transaction run_id is absent"
        )
    ecosystem = str(
        config.get("ecosystem") or config.get("language") or "rust"
    )
    backend = str(
        config.get("cli_backend") or config.get("backend") or "claude"
    )

    existing_apply_key = canonical_work_unit_key(
        "l1",
        str(config.get("mode") or "thorough"),
        ecosystem,
        backend,
        "semantic_dedup",
        "prequeue_apply",
    )
    ledger = read_artifact_ledger(root)
    existing_apply_unit = ledger.get("work_units", {}).get(
        existing_apply_key
    )
    recovering_apply = bool(
        isinstance(existing_apply_unit, Mapping)
        and existing_apply_unit.get("run_id") == run
        and existing_apply_unit.get("semantic_status") in {
            "INPUTS_BOUND",
            "ACTIVE",
        }
        and existing_apply_unit.get("execution_state") in {
            "INPUTS_BOUND_PREEXECUTION",
            "OUTPUT_COMMITTED",
        }
    )

    # Attribute the raw decision proposal only before the deterministic
    # consumer freezes it.  Recovery validates the apply unit's immutable
    # input receipt and generation bytes; asking the historical MODEL producer
    # to self-certify again after its packet was consumed can quarantine that
    # producer and must not revoke an already-armed successor.
    decision_binding = ledger.get("artifact_bindings", {}).get(
        "scratchpad:dedup_decisions.md"
    )
    if (
        not recovering_apply
        and not (
            isinstance(decision_binding, Mapping)
            and decision_binding.get("run_id") == run
            and decision_binding.get("status") == "ACTIVE"
        )
    ):
        phase = next(
            item for item in L1_PHASES if item.name == "semantic_dedup"
        )
        producer_issues = _record_typed_model_phase_artifacts(
            phase, root, dict(config)
        )
        if producer_issues:
            raise ArtifactLedgerError(
                "semantic-dedup proposal producer is not active: "
                + "; ".join(producer_issues)
            )

    # An inventory-only no-op is the explicit haltless exit for an unavailable
    # packet producer.  Stray or partial packet bytes remain visible debt but
    # are outside this proposal's immutable denominator and therefore cannot
    # activate the supplemental consumer.
    ledger = read_artifact_ledger(root)
    decision_binding = ledger.get("artifact_bindings", {}).get(
        "scratchpad:dedup_decisions.md"
    )
    decision_owner_key = (
        str(decision_binding.get("owner_key") or "")
        if isinstance(decision_binding, Mapping)
        else ""
    )
    decision_owner = ledger.get("work_units", {}).get(decision_owner_key)
    decision_inputs = (
        set(decision_owner.get("input_bindings", {}))
        if isinstance(decision_owner, Mapping)
        and isinstance(decision_owner.get("input_bindings"), Mapping)
        else set()
    )
    inventory_only_noop = bool(
        decision_owner_key.endswith("/semantic_dedup/noop_proposal")
        and decision_inputs == {"scratchpad:findings_inventory.md"}
    )
    pair_presence = {
        name: (root / name).is_file()
        for name in (
            "dedup_candidate_pairs.md",
            "dedup_candidate_pairs_full.md",
        )
    }
    supplemental_result: Mapping[str, Any] = {
        "state": "NOT_AVAILABLE",
        "debt": [],
    }
    supplemental_enabled = bool(
        not inventory_only_noop and all(pair_presence.values())
    )
    if (
        not inventory_only_noop
        and any(pair_presence.values())
        and not supplemental_enabled
    ):
        raise ArtifactLedgerError(
            "L1 supplemental candidate-pair denominator is partial"
        )
    existing_apply_unit = read_artifact_ledger(root).get(
        "work_units", {}
    ).get(existing_apply_key)
    if supplemental_enabled:
        if (
            isinstance(existing_apply_unit, Mapping)
            and existing_apply_unit.get("run_id") == run
            and existing_apply_unit.get("execution_state")
            in {"INPUTS_BOUND_PREEXECUTION", "OUTPUT_COMMITTED"}
        ):
            try:
                _proposal_payload = json.loads(
                    (
                        root / _L1_SUPPLEMENTAL_PROPOSAL_NAME
                    ).read_text(encoding="utf-8", errors="strict")
                )
            except (OSError, UnicodeError, json.JSONDecodeError) as exc:
                raise ArtifactLedgerError(
                    "L1 supplemental proposal is unavailable during apply "
                    f"recovery: {exc}"
                ) from exc
            supplemental_result = {
                "state": str(_proposal_payload.get("state") or ""),
                "debt": list(_proposal_payload.get("debt") or ()),
            }
        else:
            supplemental_result = (
                _run_l1_supplemental_dedup_proposal_phase(
                    scratchpad=root,
                    project_root=project,
                    config=config,
                    run_id=run,
                )
            )
    apply_inputs = (
        (
            "dedup_decisions.md",
            _L1_SUPPLEMENTAL_PROPOSAL_NAME,
        )
        if supplemental_enabled
        else ("dedup_decisions.md",)
    )
    contract = resolve_phase_io_contract(
        pipeline="l1",
        mode=str(config.get("mode") or "thorough"),
        ecosystem=ecosystem,
        backend=backend,
        phase="semantic_dedup",
        work_unit_id="prequeue_apply",
        exact_inputs=apply_inputs,
        exact_outputs=tuple(SEMANTIC_DEDUP_TRANSACTION_OUTPUTS),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=300,
        exec_mode="python",
        tool_policy=(),
    )

    ledger = read_artifact_ledger(root)
    unit = ledger.get("work_units", {}).get(contract.key)
    if not isinstance(unit, Mapping):
        record_work_unit_inputs(
            root, project, contract, launch, run_id=run
        )
        arm_issues = validate_work_unit_inputs(
            root, project, contract, launch, run_id=run
        )
        if arm_issues:
            raise ArtifactLedgerError(
                "semantic-dedup PhaseIO arm failed: "
                + "; ".join(arm_issues)
            )
        ledger = read_artifact_ledger(root)
        unit = ledger.get("work_units", {}).get(contract.key)
    if not (
        isinstance(unit, Mapping)
        and unit.get("run_id") == run
        and unit.get("contract_digest") == contract.digest
        and unit.get("launch_digest") == launch.digest
        and unit.get("semantic_status")
        in {"INPUTS_BOUND", "ACTIVE"}
        and unit.get("execution_state")
        in {"INPUTS_BOUND_PREEXECUTION", "OUTPUT_COMMITTED"}
    ):
        raise ArtifactLedgerError(
            "semantic-dedup PhaseIO unit is not an admissible armed/committed "
            "successor: "
            + json.dumps(
                {
                    key: unit.get(key) if isinstance(unit, Mapping) else None
                    for key in (
                        "run_id",
                        "contract_digest",
                        "launch_digest",
                        "semantic_status",
                        "execution_state",
                        "reason_codes",
                        "precommit_issues",
                        "input_debt",
                        "input_bindings",
                        "output_prestates",
                    )
                },
                sort_keys=True,
                default=str,
            )
        )

    expected_inputs, expected_prestates = (
        _semantic_dedup_core_rows_from_unit(unit, contract)
    )
    authority_binding = _semantic_dedup_phaseio_binding(
        unit, contract, launch, run_id=run, scratchpad=root
    )

    def phaseio_arm(
        request: SemanticDedupAuthorityRequest,
    ) -> Mapping[str, Any]:
        current = read_artifact_ledger(root).get("work_units", {}).get(
            contract.key
        )
        if not (
            isinstance(current, Mapping)
            and current.get("run_id") == run
            and current.get("contract_digest") == contract.digest
            and current.get("launch_digest") == launch.digest
            and current.get("input_set_digest")
            == authority_binding["input_set_digest"]
            and current.get("output_prestate_digest")
            == authority_binding["output_prestate_digest"]
        ):
            raise ArtifactLedgerError(
                "semantic-dedup PhaseIO arm changed during transaction"
            )
        return _semantic_dedup_attestation(
            request,
            action="PHASEIO_ARM",
            authority_kind="PHASE_IO",
            status="ARMED",
            authority_id=contract.key,
            evidence={
                "contract_digest": contract.digest,
                "launch_digest": launch.digest,
                "input_set_digest": authority_binding["input_set_digest"],
                "output_prestate_digest": authority_binding[
                    "output_prestate_digest"
                ],
            },
        )

    def phaseio_commit(
        request: SemanticDedupAuthorityRequest,
    ) -> Mapping[str, Any]:
        expected_records = {
            f"scratchpad:{relative}": {
                "sha256": str(row["after"]["sha256"]),
                "size": int(row["after"]["size_bytes"]),
            }
            for relative, row in request.outputs.items()
        }
        current = read_artifact_ledger(root).get("work_units", {}).get(
            contract.key
        )
        if not (
            isinstance(current, Mapping)
            and current.get("execution_state") == "OUTPUT_COMMITTED"
            and current.get("semantic_status") == "ACTIVE"
        ):
            current = record_work_unit_artifacts(
                root,
                project,
                contract,
                launch,
                run_id=run,
                actor="DRIVER",
                expected_output_records=expected_records,
            )
        if not (
            isinstance(current, Mapping)
            and current.get("execution_state") == "OUTPUT_COMMITTED"
            and current.get("semantic_status") == "ACTIVE"
        ):
            raise ArtifactLedgerError(
                "semantic-dedup PhaseIO terminal commit was quarantined"
            )
        issues = validate_work_unit_artifacts(
            root,
            project,
            contract,
            launch,
            run_id=run,
            actor="DRIVER",
            # The semantic transaction generation already froze the exact
            # proposal bytes and their producer receipts.  Once this apply
            # unit is committed, historical producer quarantine must not
            # retroactively revoke its content-addressed successor.
            require_live_input_authority=not (
                isinstance(current, Mapping)
                and current.get("execution_state") == "OUTPUT_COMMITTED"
                and current.get("semantic_status") == "ACTIVE"
            ),
        )
        if issues:
            raise ArtifactLedgerError(
                "semantic-dedup committed output authority is invalid: "
                + "; ".join(issues)
            )
        commit = current.get("commit_authority")
        if not isinstance(commit, Mapping):
            raise ArtifactLedgerError(
                "semantic-dedup commit authority receipt is absent"
            )
        return _semantic_dedup_attestation(
            request,
            action="PHASEIO_COMMIT",
            authority_kind="PHASE_IO",
            status="COMMITTED",
            authority_id=contract.key,
            evidence={
                "contract_digest": contract.digest,
                "commit_receipt_digest": str(
                    commit.get("receipt_digest") or ""
                ),
                "expected_output_records": expected_records,
            },
        )

    def _mutation_spec(
        request: SemanticDedupAuthorityRequest,
    ) -> tuple[tuple[str, str], ...]:
        suffix = request.generation_digest[:20].upper()
        return (
            (
                "scratchpad:findings_inventory.md",
                f"SEMANTIC_DEDUP_TRANSACTION_{suffix}_INVENTORY",
            ),
            (
                "scratchpad:finding_records.json",
                f"SEMANTIC_DEDUP_TRANSACTION_{suffix}_RECORDS",
            ),
        )

    def mutation_arm(
        request: SemanticDedupAuthorityRequest,
    ) -> Mapping[str, Any]:
        stable_events: list[dict[str, Any]] = []
        for identity, kind in _mutation_spec(request):
            relative = identity.split(":", 1)[1]
            before = request.outputs[relative]["before"]
            event = find_semantic_mutation_event(
                root,
                run_id=run,
                mutation_kind=kind,
                artifact_identity=identity,
            )
            if event is None:
                path = root / relative
                if not (
                    before.get("status") == "PRESENT"
                    and path.is_file()
                    and hashlib.sha256(path.read_bytes()).hexdigest()
                    == before.get("sha256")
                    and path.stat().st_size == before.get("size_bytes")
                ):
                    raise ArtifactLedgerError(
                        f"{identity}: mutation arm no longer sees its preimage"
                    )
                event = arm_semantic_mutation(
                    root,
                    project,
                    artifact_identity=identity,
                    mutation_kind=kind,
                    run_id=run,
                )
            event_before = event.get("before")
            if not (
                isinstance(event_before, Mapping)
                and event_before.get("status") == "ACTIVE"
                and event_before.get("sha256") == before.get("sha256")
                and event_before.get("size") == before.get("size_bytes")
            ):
                raise ArtifactLedgerError(
                    f"{identity}: mutation event is not bound to the RMW preimage"
                )
            stable_events.append({
                "event_id": str(event.get("event_id") or ""),
                "artifact_identity": identity,
                "mutation_kind": kind,
                "before": dict(event_before),
            })
        return _semantic_dedup_attestation(
            request,
            action="MUTATION_ARM",
            authority_kind="SEMANTIC_MUTATION",
            status="ARMED",
            authority_id=contract.key + ":paired-mutation",
            evidence={"events": stable_events},
        )

    def mutation_finalize(
        request: SemanticDedupAuthorityRequest,
    ) -> Mapping[str, Any]:
        finalized: list[dict[str, Any]] = []
        for identity, kind in _mutation_spec(request):
            event = find_semantic_mutation_event(
                root,
                run_id=run,
                mutation_kind=kind,
                artifact_identity=identity,
            )
            if event is None:
                raise ArtifactLedgerError(
                    f"{identity}: transaction mutation event is absent"
                )
            if event.get("status") == "ARMED":
                event = finalize_semantic_mutation(
                    root,
                    project,
                    str(event.get("event_id") or ""),
                    run_id=run,
                    closed_rmw_work_unit_keys=(
                        *(
                            (
                                canonical_work_unit_key(
                                    "l1",
                                    str(config.get("mode") or "thorough"),
                                    ecosystem,
                                    backend,
                                    "semantic_dedup",
                                    "supplemental_proposals",
                                ),
                            )
                            if supplemental_enabled
                            else ()
                        ),
                        contract.key,
                    ),
                )
            if event.get("status") not in {
                "NO_CHANGE", "INVALIDATION_APPLIED"
            }:
                raise ArtifactLedgerError(
                    f"{identity}: transaction mutation was not finalized"
                )
            finalized.append({
                "event_id": str(event.get("event_id") or ""),
                "event_digest": str(event.get("event_digest") or ""),
                "artifact_identity": identity,
                "status": str(event.get("status") or ""),
                "after": dict(event.get("after") or {}),
                "plan_digest": str(event.get("plan_digest") or ""),
            })
            pending_rows = config.get(
                "_pending_phase_semantic_mutations"
            ) if isinstance(config, dict) else None
            if isinstance(pending_rows, list) and not any(
                isinstance(row, Mapping)
                and isinstance(row.get("event"), Mapping)
                and row["event"].get("event_id") == event.get("event_id")
                for row in pending_rows
            ):
                pending_rows.append({
                    "owner_phase": "semantic_dedup",
                    "event": dict(event),
                })
        return _semantic_dedup_attestation(
            request,
            action="MUTATION_FINALIZE",
            authority_kind="SEMANTIC_MUTATION",
            status="FINALIZED",
            authority_id=contract.key + ":paired-mutation",
            evidence={"events": finalized},
        )

    callbacks = SemanticDedupAuthorityCallbacks(
        phaseio_arm=phaseio_arm,
        phaseio_commit=phaseio_commit,
        mutation_arm=mutation_arm,
        mutation_finalize=mutation_finalize,
    )

    def repair_arm(
        request: SemanticDedupAuthorityRequest,
        pending: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        return arm_exact_committed_output_repair(
            root,
            project,
            contract,
            launch,
            run_id=run,
            generation_digest=request.generation_digest,
            transaction_receipt_sha256=str(
                pending.get("transaction_receipt_sha256") or ""
            ),
            repair_pending_sha256=str(
                pending.get("repair_pending_sha256") or ""
            ),
        )

    def repair_finalize(
        request: SemanticDedupAuthorityRequest,
        pending: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        return authorize_exact_committed_output_repair(
            root,
            project,
            contract,
            launch,
            run_id=run,
            generation_digest=request.generation_digest,
            transaction_receipt_sha256=str(
                pending.get("transaction_receipt_sha256") or ""
            ),
            repair_pending_sha256=str(
                pending.get("repair_pending_sha256") or ""
            ),
        )
    committed = bool(
        unit.get("execution_state") == "OUTPUT_COMMITTED"
        and unit.get("semantic_status") == "ACTIVE"
    )
    repair_result = None
    try:
        recovered = recover_semantic_dedup_transaction(
            scratchpad=root,
            run_id=run,
            phase="semantic_dedup",
            authority_binding=authority_binding,
            authority=callbacks,
            fault_hook=fault_hook,
        )
    except SemanticDedupTransactionError:
        if not committed:
            raise
        # A committed receipt plus its immutable private generation may repair
        # a torn/corrupted public successor without rerunning the MODEL,
        # candidate enumeration, or supplemental derivation.  The repair core
        # accepts only the exact already-authorized five postimages.
        repair_result = repair_committed_semantic_dedup_transaction(
            scratchpad=root,
            run_id=run,
            phase="semantic_dedup",
            authority_binding=authority_binding,
            authority=callbacks,
            repair_arm_authority=repair_arm,
            repair_finalize_authority=repair_finalize,
            fault_hook=fault_hook,
        )
        recovered = recover_semantic_dedup_transaction(
            scratchpad=root,
            run_id=run,
            phase="semantic_dedup",
            authority_binding=authority_binding,
            authority=callbacks,
            fault_hook=fault_hook,
        )
    application_meta: dict[str, Any] = {
        "supplemental_state": str(
            supplemental_result.get("state") or "NOT_AVAILABLE"
        ),
        "supplemental_debt": list(
            supplemental_result.get("debt") or ()
        ),
    }
    if recovered is not None:
        transaction_result = recovered
    else:
        if committed:
            if repair_result is None:
                repair_result = repair_committed_semantic_dedup_transaction(
                    scratchpad=root,
                    run_id=run,
                    phase="semantic_dedup",
                    authority_binding=authority_binding,
                    authority=callbacks,
                    repair_arm_authority=repair_arm,
                    repair_finalize_authority=repair_finalize,
                    fault_hook=fault_hook,
                )
            post_inventory = (root / "findings_inventory.md").read_bytes()
            post_records = (root / "finding_records.json").read_bytes()
            sidecars = {
                name: (root / name).read_bytes()
                for name in (
                    SEMANTIC_DEDUP_APPLIED_RECEIPT,
                    SEMANTIC_DEDUP_ABSORBED_MAP,
                    SEMANTIC_DEDUP_DEDUPED_INVENTORY,
                )
            }
            import semantic_dedup_authority as dedup_authority
            aliases = dedup_authority.load_applied_aliases(
                root,
                canonical_text=post_inventory.decode(
                    "utf-8", errors="strict"
                ),
            )
            try:
                receipt_payload = json.loads(
                    sidecars[
                        SEMANTIC_DEDUP_APPLIED_RECEIPT
                    ].decode("utf-8", errors="strict")
                )
            except (UnicodeError, json.JSONDecodeError):
                receipt_payload = {}
            application_meta = {
                "supplemental_state": str(
                    receipt_payload.get("supplemental_state")
                    or application_meta["supplemental_state"]
                ),
                "supplemental_debt": list(
                    receipt_payload.get("supplemental_debt")
                    or application_meta["supplemental_debt"]
                ),
            }
        else:
            inventory_raw = (root / "findings_inventory.md").read_bytes()
            decisions_raw = (root / "dedup_decisions.md").read_bytes()
            (
                post_inventory,
                post_records,
                sidecars,
                aliases,
                application_meta,
            ) = _derive_l1_semantic_dedup_postimages(
                inventory_raw=inventory_raw,
                decisions_raw=decisions_raw,
                supplemental_proposal_raw=(
                    (
                        root / _L1_SUPPLEMENTAL_PROPOSAL_NAME
                    ).read_bytes()
                    if supplemental_enabled
                    else None
                ),
                run_id=run,
            )
        transaction_result = apply_semantic_dedup_transaction(
            scratchpad=root,
            run_id=run,
            phase="semantic_dedup",
            post_inventory=post_inventory,
            post_records=post_records,
            exact_inputs=tuple(
                identity.split(":", 1)[1]
                for identity in contract.immutable_inputs
            ),
            proposal_inputs=apply_inputs,
            expected_inputs=expected_inputs,
            expected_output_prestate=expected_prestates,
            staged_sidecars=sidecars,
            authority_binding=authority_binding,
            authority=callbacks,
            fault_hook=fault_hook,
        )

    import semantic_dedup_authority as dedup_authority
    final_inventory = (root / "findings_inventory.md").read_text(
        encoding="utf-8", errors="strict"
    )
    final_aliases = dedup_authority.load_applied_aliases(
        root, canonical_text=final_inventory
    )
    # Recovery may begin from an ACTIVE supplemental proposal whose staged
    # application later degraded to primary-only.  The durable applied receipt
    # is the terminal authority for that outcome; proposal metadata is only the
    # pre-execution intent and must never overwrite it on resume.
    try:
        final_receipt_payload = json.loads(
            (root / SEMANTIC_DEDUP_APPLIED_RECEIPT).read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ArtifactLedgerError(
            "semantic-dedup committed applied receipt is unreadable: "
            f"{exc}"
        ) from exc
    if not isinstance(final_receipt_payload, Mapping):
        raise ArtifactLedgerError(
            "semantic-dedup committed applied receipt is not an object"
        )
    final_supplemental_state = str(
        final_receipt_payload.get("supplemental_state") or ""
    ).strip()
    if final_supplemental_state:
        application_meta["supplemental_state"] = final_supplemental_state
    if "supplemental_debt" in final_receipt_payload:
        final_supplemental_debt = final_receipt_payload.get(
            "supplemental_debt"
        )
        if not isinstance(final_supplemental_debt, list):
            raise ArtifactLedgerError(
                "semantic-dedup committed supplemental debt is malformed"
            )
        application_meta["supplemental_debt"] = list(
            final_supplemental_debt
        )
    input_ids = sorted(
        dedup_authority.extract_finding_records(
            (
                root
                / "_sdt"
                / f"g_{transaction_result.generation_digest}"
                / "b0.bin"
            ).read_text(encoding="utf-8", errors="strict")
        )
    )
    active_ids = sorted(
        dedup_authority.extract_finding_records(final_inventory)
    )
    return {
        "run_id": transaction_result.run_id,
        "phase": transaction_result.phase,
        "generation_digest": transaction_result.generation_digest,
        "recovered": transaction_result.recovered,
        "changed": transaction_result.changed,
        "state": transaction_result.state,
        "safe_to_consume": transaction_result.safe_to_consume,
        "receipt_sha256": transaction_result.receipt_sha256,
        "repair_performed": bool(
            repair_result is not None and repair_result.repaired
        ),
        "repair_receipt_path": (
            repair_result.repair_receipt_path
            if repair_result is not None
            else ""
        ),
        "repair_receipt_sha256": (
            repair_result.repair_receipt_sha256
            if repair_result is not None
            else ""
        ),
        "input_candidate_ids": input_ids,
        "active_candidate_ids": active_ids,
        "absorbed_candidate_ids": sorted(final_aliases),
        "supplemental_state": application_meta["supplemental_state"],
        "supplemental_debt": application_meta["supplemental_debt"],
    }


_L1_CANONICAL_INVENTORY_STATUS = (
    "canonical_inventory_successor_status.json"
)
_L1_CANONICAL_INVENTORY_STATUS_SCHEMA = (
    "plamen.l1_canonical_inventory_successor_status.v1"
)


def _l1_canonical_inventory_status_record(
    *,
    scratchpad: Path,
    run_id: str,
    state: str,
    downstream_phase: str,
    issues: Sequence[str] = (),
    authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    root = Path(scratchpad)
    inventory = root / "findings_inventory.md"
    inventory_binding: dict[str, Any] = {
        "path": "findings_inventory.md",
        "status": "MISSING",
        "sha256": "",
        "size_bytes": 0,
    }
    try:
        if inventory.is_file():
            raw = inventory.read_bytes()
            inventory_binding = {
                "path": "findings_inventory.md",
                "status": "PRESENT",
                "sha256": hashlib.sha256(raw).hexdigest(),
                "size_bytes": len(raw),
            }
    except OSError as exc:
        issues = (
            *issues,
            "canonical inventory status snapshot failed: "
            f"{type(exc).__name__}: {exc}",
        )
        state = "QUARANTINED"
    unsigned = {
        "schema_version": _L1_CANONICAL_INVENTORY_STATUS_SCHEMA,
        "run_id": str(run_id),
        "state": str(state),
        "safe_to_consume": state in {
            "COMMITTED_SUCCESSOR",
            "RECALL_FLOOR_PREDECESSOR",
        },
        "downstream_phase": str(downstream_phase),
        "inventory": inventory_binding,
        "authority": dict(authority or {}),
        "issues": list(dict.fromkeys(str(value) for value in issues if str(value))),
    }
    return {
        **unsigned,
        "status_digest": hashlib.sha256(
            json.dumps(
                unsigned,
                ensure_ascii=True,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest(),
    }


def _write_l1_canonical_inventory_status(
    scratchpad: Path,
    record: Mapping[str, Any],
) -> None:
    path = Path(scratchpad) / _L1_CANONICAL_INVENTORY_STATUS
    _atomic_driver_json_record(path, dict(record))
    try:
        replay = json.loads(path.read_text(encoding="utf-8", errors="strict"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ArtifactLedgerError(
            "canonical inventory successor status is unreadable after "
            f"publication: {type(exc).__name__}: {exc}"
        ) from exc
    unsigned = dict(replay) if isinstance(replay, dict) else {}
    digest = str(unsigned.pop("status_digest", "") or "")
    if (
        replay != dict(record)
        or replay.get("schema_version")
        != _L1_CANONICAL_INVENTORY_STATUS_SCHEMA
        or digest
        != hashlib.sha256(
            json.dumps(
                unsigned,
                ensure_ascii=True,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
    ):
        raise ArtifactLedgerError(
            "canonical inventory successor status changed after publication"
        )


def _l1_semantic_transaction_context(
    scratchpad: Path,
    *,
    config: Mapping[str, Any],
    run_id: str,
) -> tuple[bool, list[str]]:
    """Detect transaction intent without trusting its active-authority bit."""

    root = Path(scratchpad)
    issues: list[str] = []
    key = canonical_work_unit_key(
        "l1",
        str(config.get("mode") or "thorough"),
        str(config.get("ecosystem") or config.get("language") or "rust"),
        str(config.get("cli_backend") or config.get("backend") or "claude"),
        "semantic_dedup",
        "prequeue_apply",
    )
    try:
        ledger = read_artifact_ledger(root)
    except ArtifactLedgerError as exc:
        return True, [
            "L1 semantic transaction ledger is invalid: "
            f"{type(exc).__name__}: {exc}"
        ]
    unit = ledger.get("work_units", {}).get(key)
    if unit is not None:
        if not isinstance(unit, Mapping) or unit.get("run_id") != run_id:
            issues.append(
                "L1 semantic transaction work-unit context is foreign or "
                "malformed"
            )
        return True, issues

    private = root / "_sdt"
    try:
        if private.exists():
            if not private.is_dir() or private.is_symlink():
                return True, ["L1 semantic transaction private root is unsafe"]
            relevant = any(
                child.name in {"p.json", "repair_pending.json"}
                or child.name.startswith(("g_", "c_", "r_"))
                for child in private.iterdir()
            )
            if relevant:
                return True, issues
    except OSError as exc:
        return True, [
            "L1 semantic transaction private context is unreadable: "
            f"{type(exc).__name__}: {exc}"
        ]
    try:
        relevant_mutation = any(
            event.get("run_id") == run_id
            and str(event.get("mutation_kind") or "").startswith(
                "SEMANTIC_DEDUP_TRANSACTION_"
            )
            for event in semantic_mutation_events(root)
        )
    except ArtifactLedgerError as exc:
        return True, [
            "L1 semantic mutation context is invalid: "
            f"{type(exc).__name__}: {exc}"
        ]
    return relevant_mutation, issues


def _l1_recall_floor_predecessor_authority(
    scratchpad: Path,
    project_root: Path,
    *,
    config: Mapping[str, Any],
    run_id: str,
    semantic_phase_completed: bool,
) -> tuple[dict[str, Any] | None, list[str]]:
    if semantic_phase_completed:
        return None, [
            "semantic_dedup is checkpoint-complete but its committed "
            "successor transaction is absent"
        ]
    root = Path(scratchpad)
    issues = semantic_input_prebind_producer_authority_issues(
        root,
        Path(project_root),
        ("scratchpad:findings_inventory.md",),
        run_id=run_id,
    )
    if issues:
        return None, list(issues)
    try:
        ledger = read_artifact_ledger(root)
        binding = ledger.get("artifact_bindings", {}).get(
            "scratchpad:findings_inventory.md"
        )
    except ArtifactLedgerError as exc:
        return None, [
            "recall-floor predecessor ledger is invalid: "
            f"{type(exc).__name__}: {exc}"
        ]
    if not isinstance(binding, Mapping):
        return None, ["recall-floor predecessor binding is absent"]
    return {
        "authority_kind": "ACTIVE_UPSTREAM_RECALL_FLOOR",
        "artifact_identity": "scratchpad:findings_inventory.md",
        "producer_work_unit_key": str(binding.get("owner_key") or ""),
        "producer_contract_digest": str(
            binding.get("contract_digest") or ""
        ),
        "producer_launch_digest": str(binding.get("launch_digest") or ""),
        "producer_writer": str(binding.get("writer") or ""),
        "sha256": str(binding.get("sha256") or ""),
        "size_bytes": int(binding.get("size") or 0),
    }, []


def _ensure_l1_prequeue_successor_for_downstream(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
    downstream_phase: str,
    semantic_phase_completed: bool = False,
) -> Mapping[str, Any]:
    """Authenticate or exactly repair L1's committed inventory successor.

    Downstream consumers call this instead of trusting checkpoint completion
    or Markdown presence.  A successful repair republishes only the five
    postimages already bound by the immutable semantic-dedup generation and
    committed receipt.  Failure is durable launch-blocking debt; it never
    invokes semantic analysis or treats the damaged public bytes as a new
    denominator.
    """

    root = Path(scratchpad)
    phase_name = str(downstream_phase or "downstream").strip() or "downstream"
    run = str(run_id or config.get("_run_id") or "").strip()
    if not run:
        issue = "L1 canonical inventory successor recovery run_id is absent"
        _append_phase_io_debt(
            root,
            phase_name,
            "CANONICAL_INVENTORY_QUARANTINE",
            issue,
        )
        return {
            "safe_to_consume": False,
            "repaired": False,
            "state": "QUARANTINED",
            "issues": [issue],
            "repair_receipt_path": "",
        }
    context_present, context_issues = _l1_semantic_transaction_context(
        root,
        config=config,
        run_id=run,
    )
    if not context_present:
        predecessor, predecessor_issues = (
            _l1_recall_floor_predecessor_authority(
                root,
                Path(project_root),
                config=config,
                run_id=run,
                semantic_phase_completed=semantic_phase_completed,
            )
        )
        if predecessor is not None and not predecessor_issues:
            status = _l1_canonical_inventory_status_record(
                scratchpad=root,
                run_id=run,
                state="RECALL_FLOOR_PREDECESSOR",
                downstream_phase=phase_name,
                authority=predecessor,
            )
            try:
                _write_l1_canonical_inventory_status(root, status)
            except Exception as exc:
                context_issues.append(
                    "recall-floor status authority could not be persisted: "
                    f"{type(exc).__name__}: {exc}"
                )
            else:
                _append_phase_io_debt(
                    root,
                    phase_name,
                    "SEMANTIC_DEDUP_RECALL_FLOOR_PREDECESSOR",
                    (
                        "semantic precision successor is unavailable; "
                        "consuming the exact active upstream inventory "
                        "preserves recall"
                    ),
                )
                return {
                    "safe_to_consume": True,
                    "repaired": False,
                    "state": "RECALL_FLOOR_PREDECESSOR",
                    "issues": [],
                    "repair_receipt_path": "",
                    "canonical_inventory_status": status,
                }
        context_issues.extend(predecessor_issues)
    try:
        if context_issues:
            raise ArtifactLedgerError("; ".join(context_issues))
        if not _l1_prequeue_apply_authority_exists(
            root,
            config=config,
            run_id=run,
        ):
            raise ArtifactLedgerError(
                "L1 semantic transaction context exists but its prequeue "
                "apply authority is missing or malformed"
            )
        result = _run_l1_prequeue_semantic_dedup_transaction(
            scratchpad=root,
            project_root=Path(project_root),
            config=config,
            run_id=run,
        )
        if (
            result.get("safe_to_consume") is not True
            or not _l1_prequeue_apply_is_committed(
                root,
                config=config,
                run_id=run,
            )
        ):
            raise ArtifactLedgerError(
                "L1 canonical inventory successor lacks exact committed "
                "postimage authority after recovery"
            )
        repaired = bool(result.get("repair_performed"))
        repair_path = str(result.get("repair_receipt_path") or "")
        if repaired:
            _append_phase_io_debt(
                root,
                "semantic_dedup",
                "COMMITTED_SUCCESSOR_EXACT_POSTIMAGE_REPAIR",
                (
                    f"restored exact generation "
                    f"{result.get('generation_digest') or 'UNKNOWN'} before "
                    f"{phase_name}; receipt={repair_path or 'UNAVAILABLE'}"
                ),
            )
        status = _l1_canonical_inventory_status_record(
            scratchpad=root,
            run_id=run,
            state="COMMITTED_SUCCESSOR",
            downstream_phase=phase_name,
            authority={
                "authority_kind": "L1_PREQUEUE_APPLY_COMMIT",
                "generation_digest": str(
                    result.get("generation_digest") or ""
                ),
                "transaction_receipt_sha256": str(
                    result.get("receipt_sha256") or ""
                ),
                "repair_receipt_path": repair_path,
            },
        )
        _write_l1_canonical_inventory_status(root, status)
        return {
            **dict(result),
            "safe_to_consume": True,
            "repaired": repaired,
            "state": (
                "RECOVERED"
                if repaired
                else "ALREADY_RECOVERED"
                if repair_path
                else "ALREADY_CURRENT"
            ),
            "issues": [],
            "repair_receipt_path": repair_path,
            "canonical_inventory_status": status,
        }
    except Exception as exc:
        issue = (
            "L1_CANONICAL_INVENTORY_SUCCESSOR_QUARANTINED before "
            f"{phase_name}: "
            f"{type(exc).__name__}: {exc}"
        )
        _append_phase_io_debt(
            root,
            phase_name,
            "CANONICAL_INVENTORY_QUARANTINE",
            issue,
        )
        status = _l1_canonical_inventory_status_record(
            scratchpad=root,
            run_id=run,
            state="QUARANTINED",
            downstream_phase=phase_name,
            issues=[issue],
            authority={
                "authority_kind": "NO_CONSUMPTION_AUTHORITY",
            },
        )
        try:
            _write_l1_canonical_inventory_status(root, status)
        except Exception as status_exc:
            issue += (
                "; canonical inventory quarantine status write failed: "
                f"{type(status_exc).__name__}: {status_exc}"
            )
        return {
            "safe_to_consume": False,
            "repaired": False,
            "state": "QUARANTINED",
            "issues": [issue],
            "repair_receipt_path": "",
            "canonical_inventory_status": status,
        }


def _append_promogap_ids_to_coverage_seed(scratchpad: Path) -> int:
    """Additively backfill newly-emitted PROMOGAP IDs into the coverage seed.

    Scans the `## Promotion-Completeness Candidates (PROMOGAP)` section of
    `findings_inventory.md` (bounded — only that section, never the full
    100K+ file) for `### Finding [INV-NNN]:` blocks, and appends one seed row
    per ID not already present in `report_index_coverage_seed.md` (both the
    flat file and its matching tier shard). Idempotent: a second call with no
    new PROMOGAP IDs appends nothing. Never raises; any failure degrades to
    "no backfill" — the findings remain in `findings_inventory.md` regardless.
    Returns the number of IDs newly added to the seed.
    """
    scratchpad = Path(scratchpad)
    inv_path = scratchpad / "findings_inventory.md"
    seed_path = scratchpad / "report_index_coverage_seed.md"
    if not inv_path.exists() or not seed_path.exists():
        return 0
    try:
        inv_text = inv_path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return 0
    sect_m = _PROMOGAP_SECTION_RE.search(inv_text)
    if not sect_m:
        return 0
    section = sect_m.group(1)

    try:
        seed_text = seed_path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return 0
    existing_ids = {m.group(0).upper() for m in re.finditer(r"\bINV-\d+\b", seed_text)}

    new_rows: list[tuple[str, str, str]] = []  # (id, severity, tier)
    for m in _PROMOGAP_BLOCK_RE.finditer(section):
        fid = m.group(1).strip().upper()
        if fid in existing_ids:
            continue
        existing_ids.add(fid)
        sev = m.group(2).strip() or "Medium"
        tier = _report_index_tier_for_severity(sev)
        new_rows.append((fid, sev, tier))

    if not new_rows:
        return 0

    try:
        seed_lines = seed_text.rstrip("\n").split("\n")
        # Drop a lone "no bounded IDs found" placeholder row before appending
        # real rows so the seed table stays well-formed.
        seed_lines = [
            ln for ln in seed_lines
            if "no bounded IDs found" not in ln
        ]
        for fid, sev, _tier in new_rows:
            seed_lines.append(f"| {fid} | {sev} | NEEDS_VERIFICATION | | |")
        seed_path.write_text("\n".join(seed_lines) + "\n", encoding="utf-8")
    except Exception:
        return 0

    # Best-effort: also backfill the matching tier-shard file so the Index
    # Agent's per-tier-batch pass sees the row too. A failure here only loses
    # the tier-shard convenience copy; the flat seed above is the primary
    # completeness source and already carries the row.
    by_tier: dict[str, list[tuple[str, str]]] = {}
    for fid, sev, tier in new_rows:
        by_tier.setdefault(tier, []).append((fid, sev))
    for tier, rows in by_tier.items():
        shard_path = scratchpad / f"report_index_seed_{tier}.md"
        if not shard_path.exists():
            continue
        try:
            shard_text = shard_path.read_text(encoding="utf-8", errors="replace")
            shard_lines = shard_text.rstrip("\n").split("\n")
            shard_lines = [
                ln for ln in shard_lines if "no IDs in this tier" not in ln
            ]
            for fid, sev in rows:
                shard_lines.append(f"| {fid} | {sev} | NEEDS_VERIFICATION | | |")
            shard_path.write_text("\n".join(shard_lines) + "\n", encoding="utf-8")
        except Exception:
            continue

    return len(new_rows)


def _run_gate_p_for_report_index(scratchpad: Path) -> dict:
    """Gate P (Fix C, recall) driver entry: content-shaped Promotion
    Completeness (Class C pipeline-loss).

    Calls `compute_promotion_orphans` + `route_promotion_orphans`
    (plamen_mechanical.py) and, when any orphan was routed to the report
    BODY, additively backfills its ID into `report_index_coverage_seed.md`
    so the Index Agent's completeness check still finds it. Never raises —
    any failure logs a warning and returns the zeroed result shape (mirrors
    `route_promotion_orphans`'s own graph/ledger-absent no-op contract).

    Wired into `main()`'s shared `report_index` pre-hook, immediately after
    `_write_report_index_coverage_seed` (Gate P reconciles against that
    seed, so it must run after the seed exists) and before the LLM Index
    Agent spawns — i.e. "before report" per the design.
    """
    scratchpad = Path(scratchpad)
    zero_result = {
        "harvested": 0, "body_candidates": 0, "appendix_c": 0,
        "appendix_a": 0, "emitted_to_inventory": 0,
    }
    try:
        orphans = compute_promotion_orphans(scratchpad)
        result = route_promotion_orphans(scratchpad, orphans)
    except Exception as exc:
        log.warning(
            f"[report_index] promotion gate skipped (non-blocking): {exc}"
        )
        return zero_result
    if result.get("harvested"):
        log.info(
            f"[report_index] promotion gate: harvested "
            f"{result['harvested']} orphan(s) -> "
            f"{result.get('emitted_to_inventory', 0)} to body "
            f"(NEEDS_VERIFICATION), {result.get('appendix_c', 0)} "
            f"to Appendix C, {result.get('appendix_a', 0)} to "
            "Appendix A (see promotion_orphans.md / promotion_routing.md)"
        )
    if result.get("emitted_to_inventory"):
        try:
            backfilled = _append_promogap_ids_to_coverage_seed(scratchpad)
            if backfilled:
                log.info(
                    f"[report_index] backfilled {backfilled} PROMOGAP "
                    "ID(s) into report_index_coverage_seed.md"
                )
        except Exception as exc:
            log.warning(
                "[report_index] PROMOGAP coverage-seed backfill failed "
                f"(non-blocking): {exc!r}"
            )
    return result


# ─────────────────────────────────────────────────────────────────────────
# Hook-4 (Fix B, recall): haltless WARN gate for uncited external-dependency
# research assumptions.
#
# Mirrors the existing report_index/verify completeness asserts: a pure
# telemetry scan that never blocks a phase, never mutates a finding's
# severity or disposition, and degrades to a no-op when its source artifacts
# are absent. Reads `findings_inventory.md` + `verify_*.md` for findings
# whose severity leans on an `[EXTERNAL-ASSUMPTION: ...]` tag (R10 burden-
# inversion) or whose Location falls inside a `file:line` recorded in
# `external_dependency_research.md`'s Integration Surface column (Hook 1's
# recon-baked research ledger), and flags any such finding that lacks a
# matching `[EXT-CITED: ...]` reference or a `NEEDS_DEPENDENCY_RESEARCH`
# escalation line. Writes `external_research_gaps.md`.
# ─────────────────────────────────────────────────────────────────────────

_ERG_FINDING_BLOCK_RE = re.compile(
    r"(?:^|\n)#{2,3}\s*Finding\s*\[([A-Za-z0-9\-]+)\][^\n]*\n"
    r"(.*?)(?=\n#{2,3}\s*Finding\s*\[|\Z)",
    re.DOTALL,
)
_ERG_LOCATION_RE = re.compile(r"\*\*Location\*\*:\s*`?([^`\n]+?)`?\s*(?:\n|$)")
_ERG_SURFACE_ROW_RE = re.compile(
    r"^\|\s*`?([^|`]+?)`?\s*\|\s*([^|]+?)\s*\|", re.MULTILINE
)
_ERG_LOC_TOKEN_RE = re.compile(r"[\w./\\-]+\.[A-Za-z]+:L?\d+")


def _external_dependency_research_surfaces(
    scratchpad: Path,
) -> list[tuple[str, str]]:
    """Parse `external_dependency_research.md`'s Integration Surface column.

    Returns a list of (dependency, file:line) pairs, one per surface token
    found in each ledger row. Never raises; returns [] when the ledger is
    absent or unparseable (recall-neutral no-op — Hook-4 simply has nothing
    to cross-reference for the location axis, the [EXTERNAL-ASSUMPTION] tag
    axis still runs independently).
    """
    scratchpad = Path(scratchpad)
    path = scratchpad / "external_dependency_research.md"
    if not path.exists():
        return []
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return []
    out: list[tuple[str, str]] = []
    for m in _ERG_SURFACE_ROW_RE.finditer(text):
        dep = m.group(1).strip()
        if not dep or dep.lower() in (
            "dependency", "---", "name/namespace", "-", ""
        ):
            continue
        surfaces_cell = m.group(2)
        for loc in _ERG_LOC_TOKEN_RE.findall(surfaces_cell):
            out.append((dep, loc))
    return out


def _check_external_research_citation_gaps(scratchpad: Path) -> int:
    """Hook-4 driver entry: scan for uncited external-assumption findings.

    Never raises. Idempotent (rewrites the ledger from current state each
    call, so resume never accumulates duplicate rows). Returns the number of
    gap rows written to `external_research_gaps.md`.
    """
    scratchpad = Path(scratchpad)
    try:
        surfaces = _external_dependency_research_surfaces(scratchpad)
    except Exception:
        surfaces = []

    sources: list[tuple[str, str]] = []  # (source_label, text)
    inv_path = scratchpad / "findings_inventory.md"
    if inv_path.exists():
        try:
            sources.append(
                ("findings_inventory.md",
                 inv_path.read_text(encoding="utf-8", errors="replace"))
            )
        except Exception:
            pass
    try:
        for vf in sorted(scratchpad.glob("verify_*.md")):
            try:
                sources.append(
                    (vf.name, vf.read_text(encoding="utf-8", errors="replace"))
                )
            except Exception:
                continue
    except Exception:
        pass

    gap_rows: list[tuple[str, str, str, str]] = []  # fid, dep, location, reason
    seen_keys: set[tuple[str, str]] = set()
    for source_label, text in sources:
        try:
            for m in _ERG_FINDING_BLOCK_RE.finditer(text):
                fid = m.group(1).strip()
                block = m.group(2)
                has_assumption = "[EXTERNAL-ASSUMPTION" in block
                loc_m = _ERG_LOCATION_RE.search(block)
                loc = loc_m.group(1).strip() if loc_m else ""
                matched_dep = ""
                if loc:
                    for dep, surf in surfaces:
                        if surf and surf in loc:
                            matched_dep = dep
                            break
                if not has_assumption and not matched_dep:
                    continue
                if "[EXT-CITED" in block or "NEEDS_DEPENDENCY_RESEARCH" in block:
                    continue
                key = (fid, loc or source_label)
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                reason = (
                    "uncited [EXTERNAL-ASSUMPTION] tag" if has_assumption
                    else "location within a researched external-dependency "
                         "integration surface, uncited"
                )
                gap_rows.append((fid, matched_dep or "(unnamed)", loc or "-", reason))
        except Exception:
            continue

    # This is a CONDITIONAL output. A zero denominator is represented by an
    # absent projection plus the typed NOT_TRIGGERED receipt written by the
    # report-index prework transaction. Remove a prior projection so resume
    # cannot mistake stale gap rows for current work.
    if not gap_rows:
        try:
            (scratchpad / "external_research_gaps.md").unlink(missing_ok=True)
        except Exception:
            pass
        return 0

    lines = [
        "# External-Dependency Research Gaps",
        "",
        "Hook-4 (Fix B) haltless WARN gate. Findings listed below either carry "
        "an `[EXTERNAL-ASSUMPTION: ...]` tag or sit at a location inside a "
        "researched external-dependency integration surface, WITHOUT a "
        "matching `[EXT-CITED: ...]` citation or `NEEDS_DEPENDENCY_RESEARCH` "
        "escalation. This never changes a finding's severity or disposition "
        "— it is an advisory flag only: recommend manual verification of the "
        "assumed external behavior before relying on the reported severity.",
        "",
        "| Finding ID | Dependency | Integration Surface | Reason |",
        "|------------|------------|----------------------|--------|",
    ]
    for fid, dep, loc, reason in gap_rows:
        lines.append(f"| {fid} | {dep} | `{loc}` | {reason} |")
    try:
        (scratchpad / "external_research_gaps.md").write_text(
            "\n".join(lines) + "\n", encoding="utf-8"
        )
    except Exception:
        pass
    return len(gap_rows)


def _append_external_research_appendix_note(
    scratchpad: Path,
    project_root: Path,
    *,
    run_id: str = "test-unbound",
) -> int:
    """Surface Hook-4's advisory through an exact report transaction."""
    scratchpad = Path(scratchpad)
    project_root = Path(project_root)
    ledger_path = scratchpad / "external_research_gaps.md"
    report_path = project_root / "AUDIT_REPORT.md"
    exact_inputs = ("external_research_gaps.md",)
    transaction_phase = "report_floor.external_research_appendix"
    candidate_relative = "external_research_appendix.candidate.md"
    try:
        state = report_mutation_transaction_state(
            scratchpad=scratchpad,
            run_id=str(run_id or "test-unbound"),
            phase=transaction_phase,
        )
        if state in {"ARMED", "COMMITTED"}:
            recover_report_mutation_transaction(
                scratchpad=scratchpad,
                project_root=project_root,
                run_id=str(run_id or "test-unbound"),
                phase=transaction_phase,
                report_candidate_sidecar=candidate_relative,
            )
            payload = json.loads(
                (scratchpad / "external_research_appendix_authority.json").read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            # Preserve the helper's legacy idempotency contract: a committed
            # replay reports no newly surfaced rows.  Recovery above still
            # validates the exact report/input/sidecar postimage first, so an
            # existing transaction can never turn drift into a false-clean
            # no-op.
            return 0 if state == "COMMITTED" else len(payload.get("finding_ids") or [])
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ReportMutationTransactionError,
    ) as exc:
        log.warning(
            "[report_floor] external-research transaction recovery refused: %r",
            exc,
        )
        return -1
    if not ledger_path.is_file() or not report_path.is_file():
        return 0
    try:
        input_snapshot = capture_report_transaction_inputs(
            scratchpad, exact_inputs
        )
    except ReportMutationTransactionError:
        return -1
    try:
        ledger_bytes = ledger_path.read_bytes()
        ledger_text = ledger_bytes.decode("utf-8", errors="strict")
        report_bytes = report_path.read_bytes()
        report_text = report_bytes.decode("utf-8", errors="strict")
    except (OSError, UnicodeError):
        return -1
    rows: list[str] = []
    for line in ledger_text.splitlines():
        stripped = line.strip()
        if not stripped.startswith("|") or not stripped.endswith("|"):
            continue
        cells = [cell.strip() for cell in stripped.strip("|").split("|")]
        row = cells[0] if cells else ""
        if (
            re.fullmatch(r"[A-Za-z0-9-]+", row)
            and row.lower() != "finding id"
            and not re.fullmatch(r"-+", row)
        ):
            rows.append(row)
    if not rows:
        return 0
    heading = "## Appendix D: External-Dependency Research Gaps (Advisory)"
    section = (
        f"{heading}\n\n"
        "The following findings rely on an assumed worst-case external-"
        "dependency behavior (per R10) without a citation to researched "
        "real-world dependency semantics. This is an advisory note only — it "
        "does not change any finding's reported severity or disposition. "
        "Recommend manual verification of the named external dependency's "
        "actual behavior before relying on the assumed-worst-case severity.\n\n"
        f"Affected finding(s): {', '.join(sorted(set(rows)))}\n"
    )
    # A Markdown heading is presentation, never completion authority.  A stale
    # or model-authored Appendix D must not suppress the current typed gap
    # denominator.  Canonicalize the one driver-owned section from the ledger;
    # duplicate owned headings are ambiguous and degrade visibly instead of
    # guessing which content may be discarded.
    appendix_re = re.compile(
        rf"(?ms)^{re.escape(heading)}[ \t]*\r?\n.*?(?=^##[ \t]+|\Z)"
    )
    existing = list(appendix_re.finditer(report_text))
    if len(existing) > 1:
        return -1
    if existing:
        match = existing[0]
        post_text = (
            report_text[: match.start()]
            + section
            + report_text[match.end() :].lstrip("\n")
        )
    else:
        post_text = report_text.rstrip("\n") + "\n\n" + section
    post_bytes = post_text.encode("utf-8")
    authority_unsigned = {
        "schema_version": "plamen.external_research_appendix_authority.v1",
        "run_id": str(run_id or "test-unbound"),
        "source": "external_research_gaps.md",
        "source_sha256": hashlib.sha256(ledger_bytes).hexdigest(),
        "pre_report_sha256": hashlib.sha256(report_bytes).hexdigest(),
        "post_report_sha256": hashlib.sha256(post_bytes).hexdigest(),
        "finding_ids": sorted(set(rows)),
        "advisory_only": True,
    }
    authority = {
        **authority_unsigned,
        "authority_sha256": hashlib.sha256(
            json.dumps(
                authority_unsigned,
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest(),
    }
    authority_bytes = (
        json.dumps(
            authority,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        + b"\n"
    )
    try:
        apply_report_mutation_transaction(
            scratchpad=scratchpad,
            project_root=project_root,
            run_id=str(run_id or "test-unbound"),
            phase=transaction_phase,
            post_report=post_bytes,
            exact_inputs=exact_inputs,
            expected_inputs=input_snapshot,
            sidecars={
                candidate_relative: post_bytes,
                "external_research_appendix_authority.json": authority_bytes,
            },
        )
    except (OSError, UnicodeError, ReportMutationTransactionError) as exc:
        log.warning(
            "[report_floor] external-research transaction refused: %r", exc
        )
        return -1
    return len(rows)


_LEGACY_PHASE_DEBT_APPENDIX_RE = re.compile(
    r"(?:\r?\n)*^## Appendix E: Unresolved Phase-Completion Debt\s*$"
    r".*?(?=^##\s|\Z)",
    re.MULTILINE | re.DOTALL,
)
_LEGACY_PHASE_DEBT_TABLE_HEADER = (
    "| Phase | State | Gate class | Affected identities | Limitation |"
)


def _is_generated_legacy_phase_debt_appendix(block: str) -> bool:
    """Recognize the exact pre-P0-E driver projection, never a heading alone."""
    def cells(row: str) -> list[str]:
        return [
            value.strip()
            for value in re.split(r"(?<!\\)\|", row.strip().strip("|"))
        ]

    lines = [line.strip() for line in str(block).strip().splitlines()]
    if not lines or lines[0] != "## Appendix E: Unresolved Phase-Completion Debt":
        return False
    content = [line for line in lines[1:] if line]
    if len(content) < 3 or content[0] != _LEGACY_PHASE_DEBT_TABLE_HEADER:
        return False
    divider = cells(content[1])
    if len(divider) != 5 or any(
        re.fullmatch(r":?-{3,}:?", cell) is None for cell in divider
    ):
        return False
    known_phases = {phase.name for phase in (*SC_PHASES, *L1_PHASES)}
    debt_states = set(PHASE_COMMIT_STATES) - {"CLEAN"}
    debt_states.add("LEGACY_DEGRADED")
    for row in content[2:]:
        if not row.startswith("|") or not row.endswith("|"):
            return False
        row_cells = cells(row)
        if len(row_cells) != 5:
            return False
        phase_name, state, gate_class, affected, limitation = row_cells
        if phase_name not in known_phases or state not in debt_states:
            return False
        if not gate_class or not limitation:
            return False
        if affected != "-":
            identities = [item.strip() for item in affected.split(",")]
            if not identities or any(
                re.fullmatch(r"[A-Z][A-Z0-9_-]*-\d+", item) is None
                for item in identities
            ):
                return False
        if re.search(r"(?:human|author)[-_ ]", phase_name, re.IGNORECASE):
            return False
    return True


def _legacy_phase_debt_rows(block: str) -> list[dict[str, Any]]:
    if not _is_generated_legacy_phase_debt_appendix(block):
        return []
    content = [
        line.strip()
        for line in str(block).strip().splitlines()[1:]
        if line.strip()
    ]
    rows: list[dict[str, Any]] = []
    for row in content[2:]:
        cells = [
            value.strip()
            for value in re.split(r"(?<!\\)\|", row.strip().strip("|"))
        ]
        affected = (
            [] if cells[3] == "-"
            else sorted(item.strip() for item in cells[3].split(","))
        )
        rows.append(
            {
                "phase": cells[0],
                "state": cells[1],
                "gate_class": cells[2],
                "affected_identities": affected,
                "message": cells[4],
            }
        )
    return rows


def _legacy_phase_debt_matches_checkpoint(
    block: str, checkpoint: Checkpoint,
) -> bool:
    """Require every deletable legacy row to derive from current typed debt."""
    legacy_rows = _legacy_phase_debt_rows(block)
    expected_rows = list(build_assurance_manifest(checkpoint).get("rows") or [])
    if not legacy_rows or len(legacy_rows) != len(expected_rows):
        return False
    unmatched = list(expected_rows)
    known_gate_classes = set(GATE_FAILURE_CLASSES) | {
        "LEGACY_UNTYPED_DEGRADATION"
    }
    for legacy in legacy_rows:
        match_index: Optional[int] = None
        for index, expected in enumerate(unmatched):
            if legacy["phase"] != str(expected.get("phase") or ""):
                continue
            if legacy["state"] != str(expected.get("state") or ""):
                continue
            if legacy["affected_identities"] != sorted(
                str(item) for item in expected.get("affected_identities") or []
            ):
                continue
            legacy_gate = str(legacy["gate_class"])
            expected_gate = str(expected.get("gate_class") or "")
            if (
                legacy_gate not in known_gate_classes
                and legacy_gate != "old"
            ):
                continue
            if legacy_gate in known_gate_classes and legacy_gate != expected_gate:
                continue
            # Recognized modern rows must also preserve the exact limitation.
            # The literal `old` gate is the fingerprinted pre-typed legacy
            # schema used by the migration fixture; it has no recoverable
            # message provenance beyond phase/state/identity parity.
            if (
                legacy_gate in known_gate_classes
                and legacy["message"] != str(expected.get("message") or "")
            ):
                continue
            match_index = index
            break
        if match_index is None:
            return False
        unmatched.pop(match_index)
    return not unmatched


def _legacy_assurance_migration_ambiguity(
    scratchpad: Path, report_path: Path, checkpoint: Checkpoint,
) -> str:
    """Identify a legacy-shaped collision without deleting its content."""
    scratchpad = Path(scratchpad)
    report_path = Path(report_path)
    if not report_path.is_file() or any(
        (scratchpad / name).exists()
        for name in ("assurance_limitations.json", "assurance_limitations.md")
    ):
        return ""
    try:
        report = report_path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return ""
    if ASSURANCE_START_MARKER in report:
        return ""
    blocks = list(_LEGACY_PHASE_DEBT_APPENDIX_RE.finditer(report))
    legacy_looking = [
        match for match in blocks
        if _LEGACY_PHASE_DEBT_TABLE_HEADER in match.group(0)
    ]
    exact = [
        match for match in blocks
        if _is_generated_legacy_phase_debt_appendix(match.group(0))
        and _legacy_phase_debt_matches_checkpoint(
            match.group(0), checkpoint
        )
    ]
    if legacy_looking and (len(blocks) != 1 or len(exact) != 1):
        return (
            "legacy assurance Appendix-E content is ambiguous; preserved "
            "without destructive migration and requires human review"
        )
    return ""


def _legacy_assurance_migration_required(
    scratchpad: Path, report_path: Path, checkpoint: Checkpoint,
) -> bool:
    """Return true only for an unambiguous pre-P0-E Appendix-E report.

    Existing managed markers or sidecars mean this is not a legacy migration;
    they are current integrity evidence and must be validated, never rewritten
    around.  This narrow predicate keeps resume migration from becoming a
    general tamper-repair escape hatch.
    """
    scratchpad = Path(scratchpad)
    report_path = Path(report_path)
    if not report_path.is_file():
        return False
    if any(
        (scratchpad / name).exists()
        for name in ("assurance_limitations.json", "assurance_limitations.md")
    ):
        return False
    try:
        report = report_path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return False
    if ASSURANCE_START_MARKER in report:
        return False
    matches = list(_LEGACY_PHASE_DEBT_APPENDIX_RE.finditer(report))
    return (
        len(matches) == 1
        and _is_generated_legacy_phase_debt_appendix(matches[0].group(0))
        and _legacy_phase_debt_matches_checkpoint(
            matches[0].group(0), checkpoint
        )
    )


def _remove_legacy_phase_debt_appendix(
    report_path: Path, checkpoint: Checkpoint,
) -> bool:
    """Atomically remove exactly one generated legacy Appendix-E block."""
    report_path = Path(report_path)
    original = report_path.read_bytes()
    text = original.decode("utf-8")
    matches = list(_LEGACY_PHASE_DEBT_APPENDIX_RE.finditer(text))
    if (
        len(matches) != 1
        or not _is_generated_legacy_phase_debt_appendix(matches[0].group(0))
        or not _legacy_phase_debt_matches_checkpoint(
            matches[0].group(0), checkpoint
        )
    ):
        if matches:
            raise RuntimeError(
                "legacy assurance migration requires exactly one fingerprinted "
                "driver-generated Appendix-E block"
            )
        return False
    migrated = _LEGACY_PHASE_DEBT_APPENDIX_RE.sub("\n", text, count=1)
    _atomic_driver_bytes(
        report_path,
        migrated.rstrip("\r\n").encode("utf-8") + b"\n",
    )
    return True


def _checkpoint_delivery_payload(checkpoint: Checkpoint) -> dict[str, Any]:
    """Mirror the exact durable Checkpoint.save payload without writing it."""
    payload: dict[str, Any] = {
        "completed": list(checkpoint.completed),
        "degraded": list(checkpoint.degraded),
        "rate_limited_at": checkpoint.rate_limited_at,
    }
    if checkpoint.config is not None:
        payload["config"] = checkpoint.config
    if checkpoint.audit_snapshot is not None:
        payload["audit_snapshot"] = checkpoint.audit_snapshot
    if checkpoint.run_id is not None:
        payload["run_id"] = checkpoint.run_id
    if checkpoint.phase_commits:
        payload["phase_commits"] = {
            key: commit.to_dict()
            for key, commit in checkpoint.phase_commits.items()
        }
    if checkpoint.semantic_mutation_acks:
        payload["semantic_mutation_acks"] = dict(
            sorted(checkpoint.semantic_mutation_acks.items())
        )
    if checkpoint.runtime_debts:
        payload["runtime_debts"] = dict(
            sorted(checkpoint.runtime_debts.items())
        )
    return payload


def _checkpoint_memory_disk_parity_issues(
    checkpoint: Checkpoint, scratchpad: Path,
) -> list[str]:
    """Require renderer authority and PhaseIO source to be the same bytes."""
    path = Path(scratchpad) / "_v2_checkpoint.json"
    try:
        durable = json.loads(path.read_text(encoding="utf-8"))
        in_memory = _checkpoint_delivery_payload(checkpoint)
        # Canonical encoding also proves that the in-memory shape is JSON-safe
        # before any report or sidecar mutation is attempted.
        durable_digest = _stable_payload_digest(durable)
        memory_digest = _stable_payload_digest(in_memory)
    except (OSError, UnicodeError, TypeError, ValueError, json.JSONDecodeError) as exc:
        return [
            "assurance checkpoint source unreadable or non-canonical: "
            f"{type(exc).__name__}: {exc}"
        ]
    if durable != in_memory:
        return [
            "assurance checkpoint in-memory/disk parity mismatch "
            f"(memory={memory_digest}, disk={durable_digest})"
        ]
    return []


def _driver_projection_launch(contract: PhaseIOContract) -> LaunchSpec:
    return LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )


def _run_zero_input_driver_projection_transaction(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase: str,
    work_unit_id: str,
    output_name: str,
    output_bytes: bytes,
) -> list[str]:
    """Publish one already-computed DRIVER projection through exact PhaseIO."""

    root = Path(scratchpad)
    project = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return [f"{phase}/{work_unit_id}: projection run_id is absent"]
    if type(output_bytes) is not bytes:
        return [f"{phase}/{work_unit_id}: projection is not exact bytes"]
    try:
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase=phase,
            work_unit_id=work_unit_id,
            exact_inputs=(),
            exact_outputs=(output_name,),
        )
        launch = _driver_projection_launch(contract)
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return list(dict.fromkeys(issues))
        output = root / output_name
        if execute:
            rooted_io.durable_write_once_bytes(output, output_bytes)
            issues.extend(
                _commit_deterministic_driver_work_unit(
                    scratchpad=root,
                    project_root=project,
                    contract=contract,
                    launch=launch,
                    run_id=run_id,
                    expected_output_records={
                        f"scratchpad:{output_name}": {
                            "sha256": hashlib.sha256(output_bytes).hexdigest(),
                            "size": len(output_bytes),
                        }
                    },
                )
            )
        if output.read_bytes() != output_bytes:
            issues.append(
                f"{phase}/{work_unit_id}: committed projection bytes differ"
            )
        return list(dict.fromkeys(issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        ValueError,
    ) as exc:
        return [
            f"{phase}/{work_unit_id}: projection transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _depth_finalization_report_authority_bytes(
    scratchpad: Path,
    receipt: Mapping[str, Any],
    *,
    run_id: str,
    phase_name: str,
) -> bytes:
    processors = receipt.get("processors")
    if not isinstance(processors, Mapping):
        raise ValueError("depth finalization processor denominator is absent")
    processor_rows = []
    for name, row in sorted(processors.items()):
        if not isinstance(row, Mapping):
            raise ValueError("depth finalization processor row is malformed")
        processor_rows.append({
            "name": str(name),
            "status": str(row.get("status") or ""),
            "error": str(row.get("error") or ""),
        })
    review_path = Path(scratchpad) / _DEPTH_FINALIZATION_REVIEW
    review_raw = review_path.read_bytes() if review_path.is_file() else None
    failed = [row for row in processor_rows if row["status"] == "FAILED"]
    if bool(failed) != bool(review_raw):
        raise ValueError("depth finalization review presence differs from failures")
    unsigned = {
        "schema": "plamen.depth_finalization_report_authority.v1",
        "authority_class": "NON_EVIDENCE_REPORT_DEBT",
        "permitted_use": "INTERNAL_REPORT_REVIEW_ONLY",
        "publication_eligible": False,
        "run_id": str(run_id),
        "phase": str(phase_name),
        "status": str(receipt.get("status") or ""),
        "source_digest": str(receipt.get("source_digest") or ""),
        "processors": processor_rows,
        "review": {
            "presence": "PRESENT" if review_raw is not None else "ABSENT",
            "sha256": (
                hashlib.sha256(review_raw).hexdigest()
                if review_raw is not None
                else ""
            ),
            "size": len(review_raw) if review_raw is not None else 0,
            "content": (
                review_raw.decode("utf-8", errors="strict")
                if review_raw is not None
                else ""
            ),
        },
    }
    payload = {
        **unsigned,
        "authority_digest": hashlib.sha256(
            json.dumps(
                unsigned,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
            ).encode("utf-8")
        ).hexdigest(),
    }
    return (
        json.dumps(
            payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        )
        + "\n"
    ).encode("utf-8")


def _run_depth_finalization_report_authority_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
    receipt: Mapping[str, Any],
    *,
    phase_name: str,
) -> list[str]:
    try:
        raw = _depth_finalization_report_authority_bytes(
            scratchpad,
            receipt,
            run_id=str(config.get("_run_id") or ""),
            phase_name=phase_name,
        )
    except (OSError, UnicodeError, TypeError, ValueError) as exc:
        return [
            "depth finalization report authority construction failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    return _run_zero_input_driver_projection_transaction(
        scratchpad=Path(scratchpad),
        config=config,
        phase="depth",
        work_unit_id="finalization_report_authority",
        output_name="depth_finalization_report_authority.json",
        output_bytes=raw,
    )


def _run_chain_deferred_report_transaction(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Materialize deferred-chain review through exact live source authority."""

    root = Path(scratchpad)
    project = Path(str(config.get("project_root") or root.parent))
    run_id = str(config.get("_run_id") or "").strip()
    try:
        _ids, raw = _deferred_chain_notes_projection(root)
        if raw is None:
            if (root / "report_semantic_chain_deferred.md").exists():
                return ["stale deferred-chain review exists without a live projection"]
            return []
        exact_inputs = tuple(sorted(
            name
            for name in (
                "chain_hypotheses.md",
                "verification_queue.json",
                "verification_queue.md",
            )
            if (root / name).is_file()
        ))
        requirements = resolve_exact_report_input_authorities(
            scratchpad=root,
            project_root=project,
            run_id=run_id,
            expected_config=config,
            input_paths=exact_inputs,
        )
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="report_index",
            work_unit_id="chain_deferred_authority",
            exact_inputs=exact_inputs,
            exact_outputs=("report_semantic_chain_deferred.md",),
            exact_input_authorities={
                requirement.identity.split(":", 1)[1]: requirement
                for requirement in requirements
            },
        )
        launch = _driver_projection_launch(contract)
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return list(dict.fromkeys(issues))
        _terminal_ids, terminal_raw = _deferred_chain_notes_projection(root)
        if terminal_raw != raw:
            return ["deferred-chain projection drifted after PhaseIO arm"]
        output = root / "report_semantic_chain_deferred.md"
        if execute:
            rooted_io.durable_write_once_bytes(output, raw)
            issues.extend(
                _commit_deterministic_driver_work_unit(
                    scratchpad=root,
                    project_root=project,
                    contract=contract,
                    launch=launch,
                    run_id=run_id,
                    expected_output_records={
                        "scratchpad:report_semantic_chain_deferred.md": {
                            "sha256": hashlib.sha256(raw).hexdigest(),
                            "size": len(raw),
                        }
                    },
                )
            )
        if output.read_bytes() != raw:
            issues.append("committed deferred-chain review bytes differ")
        return list(dict.fromkeys(issues))
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
    ) as exc:
        return [
            "deferred-chain report transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


