def _assert_assurance_status(
    checkpoint: Checkpoint,
    scratchpad: Path,
    project_root: Path | None = None,
) -> list[str]:
    """Assert that the manifest cannot authorize a stronger audit claim."""
    expected = build_current_assurance_manifest(
        checkpoint,
        Path(scratchpad),
        Path(project_root) if project_root is not None else Path(scratchpad).parent,
    )
    manifest_path = Path(scratchpad) / "assurance_limitations.json"
    try:
        actual = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return [f"assurance status manifest unreadable: {type(exc).__name__}"]
    expected_allowed = bool(expected["clean_full_audit_claim_allowed"])
    actual_allowed = bool(actual.get("clean_full_audit_claim_allowed"))
    if actual_allowed and not expected_allowed:
        return [
            "assurance status contains a false clean/full-audit authorization "
            "despite active recall, verification, or report-integrity debt"
        ]
    if actual_allowed != expected_allowed:
        return ["assurance status differs from authoritative checkpoint debt"]
    return []


def _prepare_assurance_projection_reexecution(
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Arm an exact input-driven refresh before projection bytes change."""

    contract, launch = _assurance_projection_contract_and_launch(
        dict(config), Path(scratchpad)
    )
    run_id = str(checkpoint.run_id or config.get("_run_id") or "").strip()
    if not run_id:
        return ["assurance projection cannot prepare without a run_id"]
    try:
        authorize_deterministic_work_unit_reexecution(
            Path(scratchpad),
            Path(str(config["project_root"])),
            contract,
            launch,
            run_id=run_id,
            byte_identical_successor_owners={
                "project:AUDIT_REPORT.md": (
                    contract.key.rsplit("/", 1)[0]
                    + "/disposition_authority",
                ),
            },
            authenticated_successor_owners={
                "project:AUDIT_REPORT.md": (
                    contract.key.rsplit("/", 1)[0]
                    + "/disposition_authority",
                ),
            },
            durable_mutation_successor_identities=(
                "project:AUDIT_REPORT.md",
            ),
        )
        return []
    except (ArtifactLedgerError, OSError, RuntimeError, ValueError) as exc:
        return [
            "assurance projection pre-write authority failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _record_assurance_projection_artifacts(
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Bind checkpoint source plus all driver-owned projection outputs."""
    contract, launch = _assurance_projection_contract_and_launch(
        config, Path(scratchpad)
    )
    run_id = str(checkpoint.run_id or config.get("_run_id") or "")
    if not run_id:
        return ["assurance projection cannot bind artifacts without a run_id"]
    try:
        project_root = Path(config["project_root"])
        scratchpad = Path(scratchpad)
        input_issues = validate_work_unit_inputs(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
        )
        output_issues = validate_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        if not input_issues and not output_issues:
            # Exact resume: do not churn ledger timestamps around byte-identical
            # sources/outputs that already have the right owner/digests.
            return []

        # A pre-P0-E work unit can legitimately contain output bindings but no
        # input denominator.  Accept only that exact empty legacy shape; a
        # partially populated or digest-bearing denominator is integrity
        # evidence and must not be silently reblessed.
        legacy_unbound_inputs = False
        unit: Mapping[str, Any] | None = None
        try:
            ledger = read_artifact_ledger(scratchpad)
            unit = ledger.get("work_units", {}).get(contract.key)
            legacy_unbound_inputs = bool(
                isinstance(unit, dict)
                and unit.get("input_bindings") == {}
                and not unit.get("input_set_digest")
            )
        except (ArtifactLedgerError, OSError, RuntimeError, ValueError):
            legacy_unbound_inputs = False

        # The assurance projection is a deterministic mutable view of the
        # authoritative checkpoint/report denominator.  If those exact inputs
        # changed, invalidate this one terminal work unit before rebinding it;
        # never use record_work_unit_inputs itself as overwrite authority.
        authorized_semantic_refresh = False
        if (
            input_issues
            and isinstance(unit, Mapping)
            and isinstance(unit.get("artifacts"), Mapping)
            and bool(unit.get("artifacts"))
        ):
            if unit.get("semantic_status") == "STALE_INPUT":
                authorized_semantic_refresh = True
            else:
                drift = detect_semantic_input_drift(
                    scratchpad, project_root, run_id=run_id
                )
                row = next(
                    (
                        item
                        for item in drift.get("rows", [])
                        if isinstance(item, Mapping)
                        and item.get("work_unit_key") == contract.key
                    ),
                    None,
                )
                if isinstance(row, Mapping):
                    changed_identities = tuple(
                        str(identity)
                        for identity in row.get("input_identities", [])
                        if str(identity)
                    )
                    plan = semantic_dependency_invalidation_plan(
                        ledger,
                        changed_identities,
                        run_id=run_id,
                    )
                    if set(plan.get("invalidated_work_unit_keys") or ()) != {
                        contract.key
                    }:
                        return [
                            "assurance projection semantic invalidation was "
                            "not exact to its work unit"
                        ]
                    apply_semantic_invalidation(
                        scratchpad, plan, run_id=run_id
                    )
                    authorized_semantic_refresh = True

        output_refreshable = all(
            "no exact work-unit artifact record" in issue
            or "content hash changed since work-unit record" in issue
            or "status=MISSING" in issue
            or (
                authorized_semantic_refresh
                and "status=STALE_INPUT" in issue
            )
            for issue in output_issues
        )
        input_refreshable = (
            authorized_semantic_refresh
            or
            all(
                "no exact work-unit input record" in issue
                or "semantic input hash changed" in issue
                for issue in input_issues
            )
            or legacy_unbound_inputs
        )
        if not output_refreshable or not input_refreshable:
            # Owner/run/contract/launch/status corruption is evidence, not an
            # invitation for this renderer to overwrite and rebless the ledger.
            return list(dict.fromkeys(input_issues + output_issues))
        record_work_unit_inputs(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
        )
        record_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        )
        return list(dict.fromkeys(
            validate_work_unit_inputs(
                scratchpad,
                project_root,
                contract,
                launch,
                run_id=run_id,
            )
            + validate_work_unit_artifacts(
                scratchpad,
                project_root,
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            )
        ))
    except (ArtifactLedgerError, OSError, RuntimeError, ValueError) as exc:
        return [
            "assurance projection ownership ledger failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _refresh_assurance_projection(
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    *,
    allow_legacy_migration: bool = False,
) -> list[str]:
    """Project, validate, and ledger-bind the driver-owned report section."""
    scratchpad = Path(scratchpad)
    report_path = Path(config["project_root"]) / "AUDIT_REPORT.md"
    issues: list[str] = []
    parity_issues = _checkpoint_memory_disk_parity_issues(
        checkpoint, scratchpad
    )
    if parity_issues:
        return parity_issues
    inventory_reconciliation_issues = (
        _refresh_final_inventory_reconciliation_phase_io(
            scratchpad=scratchpad,
            config=config,
        )
    )
    if inventory_reconciliation_issues:
        # Terminal assurance cannot consume stale or owner-less reconciliation
        # bytes.  Preserve the report and exact debt for repair; never weaken
        # PhaseIO or silently omit the affected human-review surface.
        return inventory_reconciliation_issues
    contract, launch = _assurance_projection_contract_and_launch(
        config, scratchpad
    )
    run_id = str(checkpoint.run_id or config.get("_run_id") or "").strip()
    if not run_id:
        return ["assurance projection cannot prepare without a run_id"]
    project_root = Path(config["project_root"])
    execute, prewrite_issues = _arm_deterministic_driver_work_unit(
        scratchpad=scratchpad,
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    if prewrite_issues:
        # A downstream crash-safe report mutation is an explicit successor,
        # not an unowned overwrite.  Authorize only that exact durable event
        # and then retry the ordinary arm path.
        recovery_issues = _prepare_assurance_projection_reexecution(
            checkpoint, scratchpad, config
        )
        if recovery_issues:
            return prewrite_issues
        execute, prewrite_issues = _arm_deterministic_driver_work_unit(
            scratchpad=scratchpad,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
    if prewrite_issues:
        return prewrite_issues
    if not execute:
        return _validate_final_assurance_delivery(
            checkpoint, scratchpad, config
        )
    try:
        before_report = report_path.read_bytes()
    except OSError as exc:
        return [f"assurance projection report preimage unreadable: {exc}"]
    intent_path = scratchpad / "assurance_projection_merge_intent.json"
    try:
        ledger = read_artifact_ledger(scratchpad)
        unit = ledger["work_units"][contract.key]
        prestate = unit["output_prestates"]["project:AUDIT_REPORT.md"]
        intent_prestate = unit["output_prestates"][
            "scratchpad:assurance_projection_merge_intent.json"
        ]
        prestate_sha256 = str(prestate["sha256"])
        report_id_pattern = re.compile(
            rb"\[([CHMLI]-[0-9]+)\]", re.IGNORECASE
        )
        sources = tuple(sorted({
            *contract.immutable_inputs,
            *contract.bounded_lookup_inputs,
        }))
        reuse_crash_intent = bool(
            intent_path.is_file()
            and intent_prestate.get("status") == "ABSENT"
        )
        if reuse_crash_intent:
            intent = json.loads(
                intent_path.read_text(encoding="utf-8", errors="strict")
            )
            unsigned_intent = {
                key: value
                for key, value in intent.items()
                if key != "intent_digest"
            }
            expected_intent_digest = hashlib.sha256(
                json.dumps(
                    unsigned_intent,
                    ensure_ascii=False,
                    allow_nan=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            if (
                intent.get("schema_version")
                != "plamen.assurance_projection_merge_intent.v1"
                or intent.get("contract_digest") != contract.digest
                or intent.get("run_id") != run_id
                or intent.get("artifact_identity")
                != "project:AUDIT_REPORT.md"
                or intent.get("before_sha256") != prestate_sha256
                or intent.get("source_identities") != list(sources)
                or intent.get("intent_digest") != expected_intent_digest
            ):
                return ["assurance projection merge intent is stale or invalid"]
        else:
            before_sha256 = hashlib.sha256(before_report).hexdigest()
            if before_sha256 != prestate_sha256:
                return [
                    "assurance projection report preimage changed after arm"
                ]
            unsigned_intent = {
                "schema_version": (
                    "plamen.assurance_projection_merge_intent.v1"
                ),
                "contract_digest": contract.digest,
                "run_id": run_id,
                "artifact_identity": "project:AUDIT_REPORT.md",
                "before_sha256": before_sha256,
                "source_identities": list(sources),
                "identities_before": sorted({
                    match.group(1).decode("ascii").upper()
                    for match in report_id_pattern.finditer(before_report)
                }),
            }
            intent = {
                **unsigned_intent,
                "intent_digest": hashlib.sha256(
                    json.dumps(
                        unsigned_intent,
                        ensure_ascii=False,
                        allow_nan=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest(),
            }
            _atomic_driver_json(intent_path, intent)
    except (
        ArtifactLedgerError,
        KeyError,
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "assurance projection merge intent failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    try:
        if allow_legacy_migration:
            ambiguity = _legacy_assurance_migration_ambiguity(
                scratchpad, report_path, checkpoint
            )
            if ambiguity:
                return [ambiguity]
        if allow_legacy_migration and _legacy_assurance_migration_required(
            scratchpad, report_path, checkpoint
        ):
            _remove_legacy_phase_debt_appendix(report_path, checkpoint)
        project_assurance_limitations(checkpoint, scratchpad, report_path)
    except Exception as exc:
        # Data-shape and renderer defects degrade through the same typed
        # report-integrity path as I/O faults.  Process-control exceptions
        # (KeyboardInterrupt/SystemExit) inherit directly from BaseException
        # and deliberately remain outside this haltless boundary.
        return [
            "assurance projection failed: "
            f"{type(exc).__name__}: {exc}"
        ]
    issues.extend(
        validate_assurance_projection(checkpoint, scratchpad, report_path)
    )
    issues.extend(
        _assert_assurance_status(
            checkpoint, scratchpad, Path(config["project_root"])
        )
    )
    try:
        _final_report_text = report_path.read_text(
            encoding="utf-8", errors="strict"
        )
    except (OSError, UnicodeError) as exc:
        issues.append(f"final report status authority unreadable: {exc}")
    else:
        issues.extend(_validate_report_body_status_authority(
            scratchpad, _final_report_text
        ))
    if not issues and execute:
        try:
            after_report = report_path.read_bytes()
            before_ids = tuple(intent["identities_before"])
            after_ids = tuple(sorted({
                match.group(1).decode("ascii").upper()
                for match in report_id_pattern.finditer(after_report)
            }))
            event = DriverMergeEvent(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity="project:AUDIT_REPORT.md",
                before_sha256=str(intent["before_sha256"]),
                after_sha256=hashlib.sha256(after_report).hexdigest(),
                source_identities=tuple(intent["source_identities"]),
                identities_before=before_ids,
                identities_after=after_ids,
            )
            issues.extend(_commit_deterministic_driver_work_unit(
                scratchpad=scratchpad,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                merge_events={event.artifact_identity: event},
            ))
        except (ArtifactLedgerError, OSError, ValueError) as exc:
            issues.append(
                "assurance projection ownership commit failed: "
                f"{type(exc).__name__}: {exc}"
            )
    return list(dict.fromkeys(issues))


def _validate_final_assurance_delivery(
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Side-effect-free final delivery gate; current bytes cannot be reblessed."""
    scratchpad = Path(scratchpad)
    report_path = Path(config["project_root"]) / "AUDIT_REPORT.md"
    issues = _checkpoint_memory_disk_parity_issues(checkpoint, scratchpad)
    issues.extend(
        validate_assurance_projection(checkpoint, scratchpad, report_path)
    )
    issues.extend(
        _assert_assurance_status(
            checkpoint, scratchpad, Path(config["project_root"])
        )
    )
    try:
        _final_report_text = report_path.read_text(
            encoding="utf-8", errors="strict"
        )
    except (OSError, UnicodeError) as exc:
        issues.append(f"final report status authority unreadable: {exc}")
    else:
        issues.extend(_validate_report_body_status_authority(
            scratchpad, _final_report_text
        ))
    contract, launch = _assurance_projection_contract_and_launch(
        config, Path(scratchpad)
    )
    run_id = str(checkpoint.run_id or config.get("_run_id") or "")
    if not run_id:
        issues.append("assurance delivery has no run_id")
    else:
        issues.extend(
            validate_work_unit_inputs(
                scratchpad,
                Path(config["project_root"]),
                contract,
                launch,
                run_id=run_id,
            )
        )
        issues.extend(
            validate_work_unit_artifacts(
                scratchpad,
                Path(config["project_root"]),
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
            )
        )
    return list(dict.fromkeys(issues))


def _commit_report_integrity_no_ship(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    issues: list[str],
) -> PhaseCommit:
    """Persist a typed no-ship predicate without weakening earlier debt."""
    message = " | ".join(dict.fromkeys(str(item) for item in issues if item))
    if not message:
        message = "report integrity failed without a structured issue"
    report_path = Path(config["project_root"]) / "AUDIT_REPORT.md"
    try:
        output_digest = hashlib.sha256(report_path.read_bytes()).hexdigest()
    except OSError:
        output_digest = ""
    contract_digest = _resolved_phase_contract_digest(phase, config)
    failure = GateFailure(
        gate_id=f"{phase.name}.report_integrity.no_ship",
        gate_class="REPORT_INTEGRITY",
        message=message,
        input_digest=_resolved_phase_input_digest(phase, config),
        output_digest=output_digest,
        contract_digest=contract_digest,
        evidence_paths=tuple(
            name
            for name in (
                "assurance_limitations.json",
                "assurance_limitations.md",
                "../AUDIT_REPORT.md",
            )
            if (Path(scratchpad) / name).exists()
            or (name == "../AUDIT_REPORT.md" and report_path.exists())
        ),
        repair_owner=phase.name,
        fallback_policy="NO_SHIP_QUARANTINE",
        allowed_fallback=_fallback_for_gate_class("REPORT_INTEGRITY"),
        schema_id="plamen.report_integrity.no_ship.v1",
        schema_version=1,
    )
    return PhaseCommitController(
        checkpoint, Path(scratchpad), config["project_root"], config
    ).commit(
        phase,
        "COMPLETED_WITH_DEBT",
        (failure,),
        clean_transients=False,
    )


def _report_integrity_delivery_phase(phases: Sequence[Phase]) -> Phase:
    """Choose the exact terminal report owner without eager fallback lookup."""
    for name in ("report_floor", "report_assemble"):
        for phase in phases:
            if phase.name == name:
                return phase
    raise RuntimeError(
        "report-integrity no-ship requires report_floor or report_assemble"
    )


def _checkpoint_has_report_integrity_no_ship(checkpoint: Checkpoint) -> bool:
    return any(
        failure.gate_class == "REPORT_INTEGRITY"
        or failure.fallback_policy == "NO_SHIP_QUARANTINE"
        for commit in checkpoint.phase_commits.values()
        for failure in commit.unresolved_failures
    )


def _validated_assurance_clearance_evidence(
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
) -> tuple[str, dict[str, str], list[str]]:
    """Return a source/output-bound proof digest for same-gate clearance."""
    issues = _validate_final_assurance_delivery(
        checkpoint, Path(scratchpad), config
    )
    if issues:
        return "", {}, issues
    contract, _launch = _assurance_projection_contract_and_launch(
        config, Path(scratchpad)
    )
    try:
        manifest = json.loads(
            (Path(scratchpad) / "assurance_limitations.json").read_text(
                encoding="utf-8"
            )
        )
        ledger = read_artifact_ledger(Path(scratchpad))
        unit = ledger["work_units"][contract.key]
        artifacts = unit["artifacts"]
        inputs = unit["input_bindings"]
        current_hashes: dict[str, str] = {}
        bound_hashes: dict[str, str] = {}

        def current_path(identity: str) -> Path:
            root_name, relative = identity.split(":", 1)
            if root_name == "scratchpad":
                return Path(scratchpad) / relative
            if root_name == "project":
                return Path(config["project_root"]) / relative
            raise ValueError(f"unknown assurance evidence root: {root_name}")

        # Include the complete current input denominator, not only the
        # checkpoint.  Supplemental verifier/grouping authorities are what
        # determine whether the managed report may claim clean assurance; a
        # same-gate clearance must therefore bind every one of those bytes.
        for identity, record in inputs.items():
            current_hashes[identity] = hashlib.sha256(
                current_path(identity).read_bytes()
            ).hexdigest()
            bound_hashes[identity] = str(record["sha256"])
        for identity, record in artifacts.items():
            current_hashes[identity] = hashlib.sha256(
                current_path(identity).read_bytes()
            ).hexdigest()
            output_hash = str(record["sha256"])
            prior = bound_hashes.get(identity)
            if prior is not None and prior != output_hash:
                return "", {}, [
                    f"assurance clearance input/output bindings disagree: {identity}"
                ]
            bound_hashes[identity] = output_hash
        if current_hashes != bound_hashes:
            return "", {}, [
                "assurance clearance bytes changed after validation or differ "
                "from the exact PhaseIO bindings"
            ]
        evidence = {
            "schema": "plamen.assurance-clearance-evidence.v2",
            "run_id": checkpoint.run_id,
            "checkpoint_sha256": bound_hashes[
                "scratchpad:_v2_checkpoint.json"
            ],
            "manifest_sha256": str(manifest["manifest_sha256"]),
            "input_set_digest": str(unit["input_set_digest"]),
            "bound_sha256": bound_hashes,
        }
        return _stable_payload_digest(evidence), bound_hashes, []
    except (
        ArtifactLedgerError,
        KeyError,
        OSError,
        RuntimeError,
        TypeError,
        UnicodeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return "", {}, [
            "assurance clearance proof unavailable: "
            f"{type(exc).__name__}: {exc}"
        ]


def _current_assurance_delivery_hashes(
    scratchpad: Path, project_root: str,
) -> dict[str, str]:
    paths = {
        "scratchpad:_v2_checkpoint.json": Path(scratchpad) / "_v2_checkpoint.json",
        "scratchpad:assurance_limitations.json": (
            Path(scratchpad) / "assurance_limitations.json"
        ),
        "scratchpad:assurance_limitations.md": (
            Path(scratchpad) / "assurance_limitations.md"
        ),
        "scratchpad:assurance_limitations_projection.json": (
            Path(scratchpad) / "assurance_limitations_projection.json"
        ),
        "scratchpad:assurance_projection_merge_intent.json": (
            Path(scratchpad) / "assurance_projection_merge_intent.json"
        ),
        "project:AUDIT_REPORT.md": Path(project_root) / "AUDIT_REPORT.md",
    }
    return {
        identity: hashlib.sha256(path.read_bytes()).hexdigest()
        for identity, path in paths.items()
    }


def _commit_report_phase_success(
    phase: Phase,
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    phases: list[Phase],
) -> PhaseCommit:
    """Commit validated report bytes and explicitly clear prior no-ship debt."""
    previous = checkpoint.phase_commits.get(phase.name)
    report_failures = tuple(
        failure
        for failure in (previous.unresolved_failures if previous else ())
        if failure.gate_class == "REPORT_INTEGRITY"
        or failure.fallback_policy == "NO_SHIP_QUARANTINE"
    )
    evidence_digest = ""
    validated_hashes: dict[str, str] = {}
    if report_failures:
        (
            evidence_digest,
            validated_hashes,
            proof_issues,
        ) = _validated_assurance_clearance_evidence(
            checkpoint, Path(scratchpad), config
        )
        if proof_issues:
            log.error(
                "[%s] refusing report-integrity clearance without exact "
                "assurance proof: %s",
                phase.name,
                "; ".join(proof_issues),
            )
            # Keep the already-persisted no-ship authority unchanged.  The
            # caller may repair/reproject and retry, but arbitrary report bytes
            # cannot manufacture a clearance event.
            if previous is None:
                raise RuntimeError(
                    "report-integrity debt has no prior typed commit"
                )
            return previous

    _record_phase_artifact_state(
        Path(scratchpad),
        config["project_root"],
        phases,
        phase.name,
        config["pipeline"],
    )
    if report_failures:
        try:
            current_hashes = _current_assurance_delivery_hashes(
                Path(scratchpad), config["project_root"]
            )
        except (OSError, RuntimeError, TypeError, ValueError) as exc:
            current_hashes = {}
            log.error(
                "[%s] refusing report-integrity clearance because exact "
                "evidence could not be re-read: %r",
                phase.name,
                exc,
            )
        if current_hashes != validated_hashes:
            log.error(
                "[%s] refusing report-integrity clearance because bound "
                "checkpoint/report/projection bytes changed after validation",
                phase.name,
            )
            if previous is None:
                raise RuntimeError(
                    "report-integrity debt has no prior typed commit"
                )
            return previous
    clearances = tuple(
        GateClearance(
            gate_id=failure.gate_id,
            clearing_gate_id=failure.gate_id,
            evidence_digest=evidence_digest,
            authority="DRIVER_ASSURANCE_VALIDATOR",
            cleared_at=datetime.now(timezone.utc).isoformat(),
        )
        for failure in report_failures
    )
    remaining = tuple(
        failure
        for failure in (previous.unresolved_failures if previous else ())
        if failure not in report_failures
    )
    return PhaseCommitController(
        checkpoint, Path(scratchpad), config["project_root"], config
    ).commit(
        phase,
        "COMPLETED_WITH_DEBT" if remaining else "CLEAN",
        (),
        clean_transients=not remaining,
        clearance_events=clearances,
    )


def _quarantine_report_integrity_no_ship(
    scratchpad: Path,
    project_root: str,
    checkpoint: Checkpoint,
) -> Optional[Path]:
    """Remove a non-authoritative report from the canonical delivery path."""
    if not _checkpoint_has_report_integrity_no_ship(checkpoint):
        return None
    report = Path(project_root) / "AUDIT_REPORT.md"
    if not report.is_file():
        return None
    try:
        quarantine = Path(scratchpad) / "_overflow" / "report_integrity_no_ship"
        destination = _quarantine_canonical_report_fail_closed(
            report,
            quarantine,
            run_id=str(checkpoint.run_id or ""),
            reason="typed REPORT_INTEGRITY no-ship debt",
        )
        if destination is None:
            log.error(
                "[report-integrity] canonical report remains NO_SHIP; "
                "see AUDIT_REPORT.NO_SHIP.json and quarantine failure receipt"
            )
            return None
        digest = hashlib.sha256(destination.read_bytes()).hexdigest()
        _atomic_driver_json(
            quarantine / "receipt.json",
            {
                "schema_version": "plamen.report_integrity_quarantine.v1",
                "run_id": checkpoint.run_id,
                "source": "../AUDIT_REPORT.md",
                "destination": str(destination.relative_to(scratchpad)).replace(
                    "\\", "/"
                ),
                "sha256": digest,
                "method": "SHARED_FAIL_CLOSED_QUARANTINE",
                "canonical_path_removed": True,
                "no_timestamp_snapshot": True,
            },
        )
        return destination
    except (OSError, RuntimeError, ValueError) as exc:
        log.error("[report-integrity] report quarantine failed: %r", exc)
        return None


def _snapshot_deliverable_report(
    checkpoint: Checkpoint,
    project_root: str,
    *,
    expected_report_sha256: str | None = None,
) -> tuple[Optional[str], Optional[str]]:
    """Return delivery/snapshot paths only for the terminally bound report.

    ``expected_report_sha256`` is captured after the terminal validators have
    accepted the canonical report.  When supplied, re-read the report through
    rooted I/O immediately before and after the optional snapshot and require
    both the canonical and snapshot bytes to retain that exact digest.  A
    missing, replaced, linked, or otherwise unreadable report is therefore not
    returned as a deliverable.
    """
    report_path = Path(project_root) / "AUDIT_REPORT.md"
    if _checkpoint_has_report_integrity_no_ship(checkpoint):
        return None, None

    def _matches_terminal_binding(path: Path) -> bool:
        if expected_report_sha256 is None:
            return path.is_file()
        try:
            raw = rooted_io.read_bytes(
                path,
                label="terminal deliverable report",
                require_single_link=True,
            )
        except (OSError, RuntimeError):
            return False
        return hashlib.sha256(raw).hexdigest() == expected_report_sha256

    if not _matches_terminal_binding(report_path):
        return None, None
    snapshot = _snapshot_report_timestamped(project_root)
    if not _matches_terminal_binding(report_path):
        return None, None
    if snapshot is not None and expected_report_sha256 is not None:
        if not _matches_terminal_binding(Path(snapshot)):
            return None, None
    return str(report_path), (str(snapshot) if snapshot else None)


def _publish_terminal_deliverable_report(
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    phases: Sequence[Phase],
    *,
    expected_report_sha256: str | None,
) -> tuple[Optional[str], Optional[str], bool, Optional[Path]]:
    """Bind and publish the final report, converting late drift to no-ship.

    ``expected_report_sha256`` must come from the successful compare-only P1-K
    receipt validation; this consumer never mints authority from the bytes it
    is deciding whether to publish.  There is deliberately no speculative
    rematerialization here: the report is model-derived, and no authenticated
    immutable byte source exists at this seam from which to recreate it.  A
    disappearance or byte replacement after terminal validation is persisted
    as generic report-integrity debt and the canonical path is withheld.  No
    external product or cause is inferred.
    """
    root = Path(scratchpad)
    project_root = str(config["project_root"])
    no_ship = _checkpoint_has_report_integrity_no_ship(checkpoint)
    issues: list[str] = []
    if not no_ship and (
        not isinstance(expected_report_sha256, str)
        or not re.fullmatch(r"[0-9a-f]{64}", expected_report_sha256)
    ):
        issues.append(
            "authenticated terminal report digest is unavailable after final "
            "validation"
        )

    report_str: Optional[str] = None
    snapshot_str: Optional[str] = None
    if not no_ship and not issues:
        report_str, snapshot_str = _snapshot_deliverable_report(
            checkpoint,
            project_root,
            expected_report_sha256=expected_report_sha256,
        )
        if report_str is None:
            issues.append(
                "terminal deliverable report disappeared, became unreadable, "
                "or changed after final validation"
            )

    if issues:
        delivery_phase = _report_integrity_delivery_phase(phases)
        _commit_report_integrity_no_ship(
            delivery_phase,
            checkpoint,
            root,
            config,
            issues,
        )
        log.error("[report-integrity] terminal delivery failed: %s", "; ".join(issues))
        no_ship = True

    quarantined: Optional[Path] = None
    if no_ship:
        quarantined = _quarantine_report_integrity_no_ship(
            root, project_root, checkpoint
        )
        report_str = None
        snapshot_str = None
    return report_str, snapshot_str, no_ship, quarantined


def _propagate_dedup_absorbed_to_finding_mapping(scratchpad: Path) -> int:
    """Record dedup-absorbed IDs as constituents of their survivor's hypothesis.

    Runs at the dedup post-swap boundary. Two coupling paths, both additive
    (never drops a finding):

    1. ALWAYS writes the driver-owned ``dedup_absorbed_map.md`` sidecar that
       Chain Agent 1 reads and the mechanical chain baseline folds in. This
       guarantees the coupling reaches the report even when chain has not run
       yet at dedup time (the normal SC/L1 ordering: dedup -> chain).
    2. When ``finding_mapping.md`` ALREADY exists (resume after chain, or a
       prior run), it additionally records every absorbed ID as a constituent
       row of its survivor's hypothesis IN-PLACE, so the coupling survives even
       if chain consolidated differently than the dedup survivor mapping.

    Returns the number of absorbed->survivor relationships propagated.
    """
    scratchpad = Path(scratchpad)
    mapping = _dedup_absorbed_survivor_mapping(scratchpad)
    # Always (re)write the sidecar — even an empty one is a clear signal to the
    # chain baseline that propagation ran and there were no merges.
    _write_dedup_absorbed_map(scratchpad, mapping)
    if not mapping:
        return 0

    fm_path = scratchpad / "finding_mapping.md"
    if not fm_path.is_file():
        # Chain has not run yet (normal ordering). The sidecar is the bridge;
        # the chain baseline / Chain Agent 1 will fold it in. Nothing to edit
        # in-place yet.
        return len(mapping)

    try:
        fm_text = fm_path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return len(mapping)

    # Build survivor_id -> hypothesis_id from existing finding_mapping rows:
    #   | <finding_id> | <hypothesis_id> | <status> | <notes> |
    # The canonical typed parser supplies both column roles and the unified ID
    # grammar. Status/Notes citations cannot manufacture a lineage edge.
    survivor_to_hyp: dict[str, list[str]] = {}
    existing_finding_ids: set[str] = set()
    for row in parse_finding_mapping_rows(fm_text):
        source_ids = [str(fid).upper() for fid in row["source_ids"]]
        hypothesis_ids = [str(fid).upper() for fid in row["hypothesis_ids"]]
        for fid in source_ids:
            existing_finding_ids.add(fid)
            targets = survivor_to_hyp.setdefault(fid, [])
            for hid in hypothesis_ids:
                if hid not in targets:
                    targets.append(hid)

    # A survivor can be absent because chain has not assigned it an active
    # hypothesis. Preserve those relations in a separate typed diagnostic
    # table (the driver sidecar is authoritative) instead of inventing an
    # invalid or collision-prone hypothesis identity.
    fallback_relations: dict[str, str] = {}
    for match in re.finditer(
        r"(?im)^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*"
        r"DEDUP_UNMAPPED_SURVIVOR\s*\|",
        fm_text,
    ):
        existing = _normalize_finding_id(match.group(1))
        survivor = _normalize_finding_id(match.group(2))
        if existing and survivor:
            fallback_relations[existing] = survivor

    new_rows: list[str] = []
    fallback_rows: list[str] = []
    resolved_fallback_ids: set[str] = set()
    propagated = 0
    for absorbed, info in sorted(mapping.items()):
        survivor = info.get("survivor", "")
        if not survivor:
            continue
        if absorbed in existing_finding_ids:
            # Already mapped (e.g., chain re-added it); leave as-is.
            continue
        hypothesis_ids = survivor_to_hyp.get(survivor.upper(), [])
        if not hypothesis_ids:
            if absorbed in fallback_relations:
                # The unresolved diagnostic already durably records this edge.
                continue
            coupled = (info.get("coupled") or "").replace("|", "/").strip()
            note = "survivor has no active hypothesis mapping"
            if coupled:
                note += f"; coupled: {coupled}"
            fallback_rows.append(
                f"| {absorbed} | {survivor.upper()} | "
                f"DEDUP_UNMAPPED_SURVIVOR | {note} |"
            )
            propagated += 1
            continue
        if absorbed in fallback_relations:
            resolved_fallback_ids.add(absorbed)
        coupled = (info.get("coupled") or "").replace("|", "/").strip()
        note = (
            f"DEDUP_CONSTITUENT of {survivor}"
            + (f"; coupled: {coupled}" if coupled else "")
        )
        new_rows.append(
            f"| {absorbed} | {', '.join(hypothesis_ids)} | "
            f"DEDUP_ABSORBED | {note} |"
        )
        propagated += 1

    if new_rows or fallback_rows:
        for absorbed in sorted(resolved_fallback_ids):
            fm_text = re.sub(
                rf"(?im)^(\|\s*{re.escape(absorbed)}\s*\|\s*[^|]+\|\s*)"
                r"DEDUP_UNMAPPED_SURVIVOR(\s*\|)",
                r"\1DEDUP_DIAGNOSTIC_RESOLVED\2",
                fm_text,
            )
        chunks = ["\n<!-- dedup-absorbed constituents propagated by driver -->"]
        if new_rows:
            chunks.extend([
                "| Finding ID | Hypothesis ID(s) | Mapping Status | Notes |",
                "|------------|------------------|----------------|-------|",
                *new_rows,
            ])
        if fallback_rows:
            chunks.extend([
                "| Dedup Absorbed ID | Unmapped Survivor ID | Mapping Status | Notes |",
                "|-------------------|----------------------|----------------|-------|",
                *fallback_rows,
            ])
        addition = "\n".join(chunks) + "\n"
        fm_path.write_text(fm_text.rstrip("\n") + "\n" + addition, encoding="utf-8")
    return propagated


def _build_dedup_round_exclusion_block(scratchpad: Path) -> str:
    """Build the ``## Already-decided exclusion list`` carry-forward block.

    Reads decisions already recorded in ``dedup_decisions.md`` (from prior
    rounds) and lists every pair/ID already decided so the next round does NOT
    re-decide them. Per-pair judgment is preserved (each pair is decided exactly
    once); this only prevents oscillation/double-deciding across rounds.
    """
    decided_ids: set[str] = set()
    mapping = _dedup_absorbed_survivor_mapping(scratchpad)
    for absorbed, info in mapping.items():
        decided_ids.add(absorbed)
        if info.get("survivor"):
            decided_ids.add(info["survivor"])
    # Also harvest any explicitly-decided IDs (KEEP SEPARATE / GROUP / PASS)
    # from the decisions status table so they are not re-evaluated.
    dec_path = scratchpad / "dedup_decisions.md"
    if dec_path.is_file():
        try:
            dec_text = dec_path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            dec_text = ""
        # This is proposal scheduling, not applied alias authority: every
        # member already adjudicated in a prior round must be excluded from
        # re-decision even when its destructive merge was later vetoed.  Use
        # the typed proposal parser so both endpoints survive the P0-S removal
        # of raw-proposal alias propagation.
        try:
            from semantic_dedup_authority import parse_dedup_proposals

            for proposal in parse_dedup_proposals(dec_text):
                decided_ids.update(
                    str(member).upper()
                    for member in proposal.get("member_ids", [])
                    if member
                )
        except Exception:
            pass
        for m in re.finditer(
            r"^\|\s*([A-Za-z]+-\d+)\s*\|\s*"
            r"(?:KEEP\s+SEPARATE|GROUP|PASS|MERGED\b)",
            dec_text,
            re.MULTILINE | re.IGNORECASE,
        ):
            decided_ids.add(m.group(1).strip().upper())
    if not decided_ids:
        return ""
    lines = [
        "## Already-decided exclusion list",
        "",
        "These finding IDs were decided in a prior dedup round. Do NOT "
        "re-decide any pair that consists solely of IDs listed here — their "
        "decisions are already recorded in dedup_decisions.md. Evaluate only "
        "this round's candidate rows.",
        "",
    ]
    lines += [f"- {fid}" for fid in sorted(decided_ids)]
    lines += ["", "---", ""]
    return "\n".join(lines) + "\n"


def _stage_dedup_round_packet(scratchpad: Path, round_n: int) -> Optional[Path]:
    """Stage round-N's live packet for the dedup subprocess.

    Copies ``dedup_candidate_pairs_round{N}.md`` into the canonical live file
    ``dedup_candidate_pairs.md`` (which the subprocess reads) with the
    carry-forward ``## Already-decided exclusion list`` block prepended, and
    likewise stages the matching focus inventory. Returns the staged live path
    or None if the round file is absent.

    This is the bounded-OUTPUT mechanism: each round's subprocess sees only
    <=`_DEDUP_ROUND_CHUNK` candidate rows, but every pair is still per-pair
    LLM-judged. No merge is ever applied mechanically here.
    """
    scratchpad = Path(scratchpad)
    round_pairs = scratchpad / f"dedup_candidate_pairs_round{round_n}.md"
    if not round_pairs.is_file():
        return None
    try:
        body = round_pairs.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return None
    exclusion = _build_dedup_round_exclusion_block(scratchpad)
    live = scratchpad / "dedup_candidate_pairs.md"
    live.write_text(exclusion + body, encoding="utf-8")
    # Stage the matching focus inventory if present.
    round_focus = scratchpad / f"dedup_focus_inventory_round{round_n}.md"
    if round_focus.is_file():
        try:
            shutil.copy2(round_focus, scratchpad / "dedup_focus_inventory.md")
        except Exception:
            pass
    return live


def _dedup_round_files(scratchpad: Path) -> list[Path]:
    """Return the sorted list of per-round candidate-pair packets, if any."""
    scratchpad = Path(scratchpad)
    files = sorted(
        scratchpad.glob("dedup_candidate_pairs_round*.md"),
        key=lambda p: _dedup_round_index(p.name),
    )
    return files


def _dedup_round_index(name: str) -> int:
    m = re.search(r"round(\d+)\.md$", name)
    return int(m.group(1)) if m else 0


_VERIFY_RECOVERY_RECEIPT_SCHEMA = "plamen.verification_recovery_execution.v1"
_VERIFY_RECOVERY_MAX_ROWS = 4
_VERIFY_RECOVERY_RECEIPT_FIELDS = frozenset({
    "schema_version", "status", "recovery_id", "recovery_kind",
    "contract_digest", "launch_spec_digest", "ordered_work_item_ids",
    "unresolved_work_item_ids", "issues", "output_sha256",
    "operator_receipt_sha256", "terminal_negative_authority",
    "receipt_digest",
})


def _verify_recovery_phase_stub() -> Any:
    """Return the minimum phase identity required by the foreground launcher."""

    return type("VerificationRecoveryPhase", (), {"name": "verify_recovery"})()


def _verify_recovery_model(config: Mapping[str, Any]) -> str:
    backend = str(config.get("cli_backend") or "claude").strip().lower()
    configured = config.get("_verification_recovery_model")
    if configured not in (None, ""):
        return (
            _resolve_codex_model_alias(str(configured).strip())
            if backend == "codex"
            else resolve_claude_recovery_model(configured)
        )
    if backend == "codex":
        # Use the driver's canonical tier mapping and account-specific fallback
        # behavior instead of creating a recovery-only model namespace.
        phase = type(
            "VerificationRecoveryModelPhase",
            (),
            {"name": "verify_recovery", "model": "opus"},
        )()
        return phase_model(phase, str(config.get("mode") or "core"), dict(config))
    tier = "sonnet" if str(config.get("mode") or "core") == "light" else "opus"
    return _resolve_model_alias(tier)


def _verify_recovery_launch_spec(
    contract: Mapping[str, Any],
    *,
    config: dict[str, Any],
    prompt_bytes_override: bytes | None = None,
    expected_output_files_override: Sequence[str] | None = None,
) -> VerifierLaunchSpec:
    """Compile a foreground-only launch from immutable in-memory bytes.

    Recovery launch authority must be resolvable before any canonical
    recovery artifact exists.  Reading ``prompt.md`` here would force the
    caller to materialize an output before it could arm that output's
    producer, so the validated contract is the sole prompt-byte source.
    """

    backend = str(contract["backend"])
    model = _verify_recovery_model(config)
    project_root = str(Path(config["project_root"]).resolve())
    transport = "exec"
    if backend == "claude":
        transport, _transport_source = _strict_claude_exec_mode(
            config,
            raw_backend=str(config.get("cli_backend") or "claude"),
        )
        # Semantic launch metadata only.  The exact Claude command and child
        # environment are materialized from the provider parent after the
        # durable worker arm; this vector is deliberately not executable.
        argv = list(_selected_claude_backend_argv_prefix())
    else:
        argv = _build_codex_cmd(
            model,
            writable_dirs=[project_root, str(Path(config["scratchpad"]).resolve())],
        )
    timeout = max(
        1,
        int(
            scale_timeout(
                1800,
                project_root,
                str(config.get("language") or "unknown"),
                mode=str(config.get("mode") or "core"),
                hypothesis_count=int(contract["row_count"]),
                backend=backend,
            )
        ),
    )
    prompt_bytes = (
        bytes(prompt_bytes_override)
        if prompt_bytes_override is not None
        else str(contract["prompt_markdown"]).encode("utf-8")
    )
    policy = {
        "allowed": ["Read", "Glob", "Grep", "Bash", "Write", "Edit"],
        "denied": ["mcp__*", "Task", "Agent"],
        "foreground_only": True,
        "child_join_policy": "REQUIRE_JOIN_BEFORE_RECEIPT",
    }
    return VerifierLaunchSpec(
        work_unit_id=str(contract["recovery_id"]).lower(),
        work_unit_resume_digest=str(contract["contract_digest"]),
        backend=backend,
        model=model,
        transport=transport,
        argv=tuple(str(item) for item in argv),
        cwd=project_root,
        timeout_seconds=timeout,
        prompt_sha256=hashlib.sha256(prompt_bytes).hexdigest(),
        prompt_size_bytes=len(prompt_bytes),
        expected_output_files=tuple(
            expected_output_files_override
            if expected_output_files_override is not None
            else contract["expected_model_outputs"]
        ),
        tool_policy_digest=verification_method_stable_digest(policy),
        foreground_only=True,
        background_children_allowed=False,
        child_join_policy="REQUIRE_JOIN_BEFORE_RECEIPT",
        process_group_policy="ISOLATED_PROCESS_GROUP",
        orphan_policy="TERMINATE_TREE_AND_RETAIN_DEBT",
    )


def _publish_verify_recovery_compatibility_projection(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    run_id: str,
    manifest_path: Path,
    prompt_path: Path,
) -> list[str]:
    """Publish legacy recovery paths through an armed deterministic projection.

    The compiler-bound per-unit directory is the authority.  These two global
    files remain only for legacy readers and diagnostics; a fixed producer key
    permits input-driven refresh when a later bounded recovery unit becomes
    current without allowing an unbound overwrite.
    """

    root = Path(scratchpad)
    outputs = (
        "verification_queue_recovery.md",
        "_prompt_verify_recovery.attempt1.md",
    )
    contract = resolve_phase_io_contract(
        pipeline="l1" if str(config.get("pipeline")) == "l1" else "sc",
        mode=str(config.get("mode") or "core").lower(),
        ecosystem=str(config.get("language") or "unknown").lower(),
        backend=str(config.get("cli_backend") or "claude").lower(),
        phase="verify_recovery",
        work_unit_id="compatibility_projection",
        exact_inputs=(
            manifest_path.relative_to(root).as_posix(),
            prompt_path.relative_to(root).as_posix(),
        ),
        exact_outputs=outputs,
        exact_writer="DRIVER",
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    execute, issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=Path(project_root),
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    if issues:
        return issues
    if execute:
        shutil.copy2(manifest_path, root / outputs[0])
        shutil.copy2(prompt_path, root / outputs[1])
        issues.extend(
            _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=Path(project_root),
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
        )
    return list(dict.fromkeys(issues))


def _write_verifier_method_phase_io_contracts(
    *,
    directory: Path,
    scratchpad: Path,
    config: Mapping[str, Any],
    phase_name: str,
    work_unit_id: str,
    model_outputs: Sequence[str],
    operator_receipts: Sequence[str],
    immutable_launch_inputs: Sequence[Path],
    shared_immutable_inputs: Sequence[Path] = (),
    driver_outputs: Sequence[Path],
) -> tuple[Any, Any, Any]:
    """Persist exact model/control PhaseIO shapes for launch and resume.

    ``immutable_launch_inputs`` is the model's complete exact-input
    denominator.  ``shared_immutable_inputs`` identifies members of that
    denominator which were produced by an upstream/shared transaction, not by
    this child prelaunch.  They remain exact model inputs but are deliberately
    excluded from the child's output contract so sibling children cannot
    steal producer ownership merely by consuming the same immutable bytes.
    """

    root = Path(scratchpad)

    def relative(path: Path | str) -> str:
        candidate = Path(path)
        if not candidate.is_absolute():
            return str(PurePosixPath(str(candidate).replace("\\", "/")))
        return candidate.relative_to(root).as_posix()

    common = {
        "pipeline": "l1" if str(config.get("pipeline")) == "l1" else "sc",
        "mode": str(config.get("mode") or "core").lower(),
        "ecosystem": str(config.get("language") or "unknown").lower(),
        "backend": str(config.get("cli_backend") or "claude").lower(),
        "phase": phase_name,
    }
    immutable_input_paths = tuple(
        relative(path) for path in immutable_launch_inputs
    )
    shared_input_paths = tuple(
        relative(path) for path in shared_immutable_inputs
    )
    if len(set(shared_input_paths)) != len(shared_input_paths):
        raise ValueError("shared verifier PhaseIO inputs contain duplicates")
    unknown_shared = set(shared_input_paths) - set(immutable_input_paths)
    if unknown_shared:
        raise ValueError(
            "shared verifier PhaseIO inputs are absent from the model input "
            "denominator: " + ", ".join(sorted(unknown_shared))
        )
    contract_sidecars = tuple(
        relative(directory / name)
        for name in (
            "phase_io_prelaunch_contract.json",
            "phase_io_model_contract.json",
            "phase_io_control_contract.json",
        )
    )
    model_input_paths = tuple(sorted({
        *immutable_input_paths,
        *contract_sidecars,
    }))
    model_contract = resolve_phase_io_contract(
        **common,
        work_unit_id=f"method_model.{work_unit_id}",
        exact_outputs=tuple(str(name).replace("\\", "/") for name in model_outputs),
        exact_inputs=model_input_paths,
    )
    prelaunch_outputs = tuple(
        path
        for path in model_input_paths
        if path not in set(shared_input_paths)
    )
    prelaunch_contract = resolve_phase_io_contract(
        **common,
        work_unit_id=f"method_context.{work_unit_id}",
        exact_outputs=prelaunch_outputs,
        exact_inputs=(),
        exact_writer="DRIVER",
    )
    prelaunch_output_set = set(prelaunch_outputs)
    control_contract = resolve_phase_io_contract(
        **common,
        work_unit_id=f"method_receipt.{work_unit_id}",
        exact_outputs=tuple(
            [
                relative(path)
                for path in driver_outputs
                if relative(path) not in prelaunch_output_set
            ]
            + [str(name).replace("\\", "/") for name in operator_receipts]
        ),
        exact_inputs=model_input_paths,
        exact_writer="DRIVER",
    )
    return prelaunch_contract, model_contract, control_contract


def _materialize_verifier_method_phase_io_contracts(
    directory: Path,
    *,
    prelaunch_contract: PhaseIOContract,
    model_contract: PhaseIOContract,
    control_contract: PhaseIOContract,
) -> None:
    """Persist compiler receipts only after their producer was prebound."""

    Path(directory).mkdir(parents=True, exist_ok=True)
    for name, contract in (
        ("phase_io_prelaunch_contract.json", prelaunch_contract),
        ("phase_io_model_contract.json", model_contract),
        ("phase_io_control_contract.json", control_contract),
    ):
        path = directory / name
        payload = contract.to_dict()
        payload["contract_digest"] = contract.digest
        if path.is_file():
            current = json.loads(path.read_text(encoding="utf-8", errors="strict"))
            if current != payload:
                raise ValueError(f"verifier PhaseIO contract drift: {name}")
        else:
            _atomic_driver_json_record(path, payload)


def _record_verifier_method_phase_io_authority(
    *,
    prelaunch_contract: Any,
    model_contract: Any,
    control_contract: Any,
    launch_spec: VerifierLaunchSpec,
    scratchpad: Path,
    project_root: Path,
    run_id: str,
    include_outputs: bool,
    allow_initialize: bool = True,
) -> list[str]:
    """Register or validate model/control boundaries in the neutral ledger.

    The prelaunch producer is never initialized here: callers must arm it with
    ``_arm_deterministic_driver_work_unit`` before writing a canonical byte and
    commit it immediately after materialization.  ``allow_initialize`` applies
    only to the later model/control boundaries.  A completed-unit resume gate
    passes false so absent historical authority cannot be manufactured after
    execution and used to self-certify old bytes.
    """

    def ledger_launch(contract: Any, *, driver: bool) -> LaunchSpec:
        return LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver" if driver else launch_spec.model,
            timeout_s=launch_spec.timeout_seconds,
            exec_mode="python" if driver else launch_spec.transport,
            tool_policy=(
                ("filesystem",)
                if driver
                else ("filesystem", "shell", "foreground-only")
            ),
        )

    def shared_input_producer_issues() -> list[str]:
        """Require shared model inputs to retain their upstream ownership.

        Per-unit prelaunch outputs are a strict subset of the model's launch
        inputs.  The difference is intentionally shared, so accepting an
        unowned file here would trade the sibling-overwrite bug for an equally
        unsafe producer-less exact-input receipt.
        """

        owned = {output.identity for output in prelaunch_contract.outputs}
        shared = (
            set(model_contract.immutable_inputs)
            | set(model_contract.bounded_lookup_inputs)
        ) - owned
        if not shared:
            return []
        try:
            ledger = read_artifact_ledger(scratchpad)
        except ArtifactLedgerError as exc:
            return [str(exc)]
        model_unit = ledger.get("work_units", {}).get(model_contract.key)
        bindings = (
            model_unit.get("input_bindings", {})
            if isinstance(model_unit, dict)
            else {}
        )
        expected_queue_phase = (
            "verify_queue" if model_contract.pipeline == "l1"
            else "sc_verify_queue"
        )
        expected_queue_owner_keys = {
            canonical_work_unit_key(
                model_contract.pipeline,
                model_contract.mode,
                model_contract.ecosystem,
                model_contract.backend,
                expected_queue_phase,
                work_unit_id,
            )
            for work_unit_id in (
                "routing",
                "t9.live_receipt_last_cas",
            )
        }
        model_work_unit = model_contract.work_unit_id
        verifier_unit_id = (
            model_work_unit.split("method_model.", 1)[1]
            if model_work_unit.startswith("method_model.")
            else ""
        )
        expected_bb_owner_suffix = (
            f"/bb_policy/projection.{verifier_unit_id}"
            if verifier_unit_id
            else ""
        )
        result: list[str] = []
        for identity in sorted(shared):
            producer = ledger.get("artifact_bindings", {}).get(identity)
            binding = bindings.get(identity) if isinstance(bindings, dict) else None
            producer_key = (
                str(producer.get("owner_key") or "")
                if isinstance(producer, dict)
                else ""
            )
            producer_digest = (
                str(producer.get("contract_digest") or "")
                if isinstance(producer, dict)
                else ""
            )
            producer_is_active = (
                isinstance(producer, dict)
                and producer.get("status") == "ACTIVE"
                and producer.get("run_id") == run_id
                and producer.get("writer") == "DRIVER"
                and (
                    producer_key in expected_queue_owner_keys
                    or (
                        bool(expected_bb_owner_suffix)
                        and identity.endswith("/bb_policy_work.json")
                        and producer_key.endswith(
                            expected_bb_owner_suffix
                        )
                    )
                )
                and bool(re.fullmatch(r"[0-9a-f]{64}", producer_digest))
            )
            binding_matches = (
                isinstance(binding, dict)
                and binding.get("status") == "ACTIVE"
                and binding.get("producer_work_unit_key") == producer_key
                and binding.get("producer_contract_digest") == producer_digest
            )
            if not producer_is_active or not binding_matches:
                result.append(
                    f"{identity}: shared immutable input has no active "
                    "upstream producer authority"
                )
        return result

    issues: list[str] = []
    prelaunch_launch = ledger_launch(prelaunch_contract, driver=True)
    prelaunch_issues = validate_work_unit_inputs(
        scratchpad,
        project_root,
        prelaunch_contract,
        prelaunch_launch,
        run_id=run_id,
    ) + validate_work_unit_artifacts(
        scratchpad,
        project_root,
        prelaunch_contract,
        prelaunch_launch,
        run_id=run_id,
        actor="DRIVER",
    )
    if prelaunch_issues:
        return list(dict.fromkeys(prelaunch_issues))
    model_launch = ledger_launch(model_contract, driver=False)
    if allow_initialize:
        record_work_unit_inputs(
            scratchpad, project_root, model_contract, model_launch, run_id=run_id
        )
    issues.extend(validate_work_unit_inputs(
        scratchpad, project_root, model_contract, model_launch, run_id=run_id
    ))
    issues.extend(shared_input_producer_issues())
    if not include_outputs:
        return list(dict.fromkeys(issues))
    if allow_initialize:
        record_work_unit_artifacts(
            scratchpad, project_root, model_contract, model_launch,
            run_id=run_id, actor="MODEL",
        )
    issues.extend(validate_work_unit_artifacts(
        scratchpad, project_root, model_contract, model_launch,
        run_id=run_id, actor="MODEL",
    ))
    control_launch = ledger_launch(control_contract, driver=True)
    if allow_initialize:
        record_work_unit_inputs(
            scratchpad, project_root, control_contract, control_launch, run_id=run_id
        )
    issues.extend(validate_work_unit_inputs(
        scratchpad, project_root, control_contract, control_launch, run_id=run_id
    ))
    if allow_initialize:
        record_work_unit_artifacts(
            scratchpad, project_root, control_contract, control_launch,
            run_id=run_id, actor="DRIVER",
        )
    issues.extend(validate_work_unit_artifacts(
        scratchpad, project_root, control_contract, control_launch,
        run_id=run_id, actor="DRIVER",
    ))
    return list(dict.fromkeys(issues))


def _verify_recovery_execution_receipt_digest(payload: Mapping[str, Any]) -> str:
    return recovery_execution_receipt_digest(payload)


def _load_current_verify_recovery_execution_receipt(
    path: Path,
    *,
    contract: Mapping[str, Any],
    launch_spec: VerifierLaunchSpec,
    scratchpad: Path,
) -> dict[str, Any]:
    payload = json.loads(path.read_text(encoding="utf-8", errors="strict"))
    return validate_recovery_execution_receipt(
        payload,
        contract=contract,
        launch_spec=launch_spec,
        scratchpad=Path(scratchpad),
    )


def _validate_verify_recovery_model_outputs(
    scratchpad: Path,
    contract: Mapping[str, Any],
) -> list[str]:
    issues: list[str] = []
    for row in contract["rows"]:
        work_id = str(row["work_item_id"])
        verify_path = Path(scratchpad) / f"verify_{work_id}.md"
        severity_path = Path(scratchpad) / f"verify_{work_id}.severity_proposal.json"
        operator_path = Path(scratchpad) / f"verify_{work_id}.operator_application.json"
        if not verify_path.is_file():
            issues.append(f"{work_id}: verifier Markdown missing")
        else:
            raw = verify_path.read_bytes()
            text = raw.decode("utf-8", errors="replace")
            if len(raw) < 100:
                issues.append(f"{work_id}: verifier Markdown is below 100-byte floor")
            for field in (("Severity", "Final Severity"), ("Evidence Tag", "Evidence Tags"), ("Verdict", "Final Verdict")):
                if not _field_from_markdown(text, field):
                    issues.append(f"{work_id}: verifier Markdown lacks {field[0]}")
        if not severity_path.is_file():
            issues.append(f"{work_id}: severity proposal missing")
        else:
            try:
                proposal = parse_severity_proposal(severity_path.read_bytes())
                if proposal.get("candidate_id") != work_id:
                    issues.append(f"{work_id}: severity proposal identity mismatch")
            except Exception as exc:
                issues.append(
                    f"{work_id}: severity proposal invalid: {type(exc).__name__}: {exc}"
                )
        if not operator_path.is_file():
            issues.append(f"{work_id}: operator application missing")
    return list(dict.fromkeys(issues))


def _compile_bb_policy_terminal_reconciliation(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Compile and bind the exact run-level BB policy denominator."""

    if not bb_policy_configured(config):
        return None
    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        raise BBVerificationPolicyError(
            "BB terminal reconciliation requires a driver run identity"
        )
    expected_ingress = build_bb_policy_ingress_payload(
        config, driver_run_id=run_id
    )
    ingress = _load_bound_bb_policy_ingress(
        root, expected_ingress or {}
    )

    def canonical_digest(value: Any) -> str:
        return hashlib.sha256(json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")).hexdigest()

    def artifact_digest(path: Path) -> str:
        """Bind the bytes a downstream evidence reference actually opens."""

        return hashlib.sha256(Path(path).read_bytes()).hexdigest()

    def load_json(path: Path, label: str) -> dict[str, Any]:
        try:
            payload = json.loads(
                path.read_text(encoding="utf-8", errors="strict")
            )
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise BBVerificationPolicyError(
                f"{label} is unreadable: {type(exc).__name__}: {exc}"
            ) from exc
        if not isinstance(payload, dict):
            raise BBVerificationPolicyError(
                f"{label} must contain one JSON object"
            )
        return payload

    exact_inputs: set[str] = {BB_POLICY_LOCAL_INGRESS_PATH}
    queue_path = root / "verification_queue.md"
    queue_items = (
        list(_read_typed_queue_work_items(queue_path))
        if queue_path.is_file()
        else []
    )
    if queue_path.is_file():
        exact_inputs.add(queue_path.relative_to(root).as_posix())
    for name in (
        "verification_queue.work_items.json",
        "verification_queue.work_plan.json",
    ):
        if (root / name).is_file():
            exact_inputs.add(name)
    queue_by_id = {
        item.work_item_id: item for item in queue_items
    }

    recovery_contracts: list[tuple[Path, dict[str, Any]]] = []
    recovery_root = root / "_verification_recovery"
    if recovery_root.is_dir():
        for contract_path in sorted(
            recovery_root.glob("VREC-*/contract.json"),
            key=lambda value: value.as_posix(),
        ):
            contract = validate_verification_recovery_contract(
                load_json(contract_path, "BB recovery contract"),
                repo_root=Path(__file__).resolve().parent.parent,
            )
            if str(contract["run_id"]) != run_id:
                raise BBVerificationPolicyError(
                    "BB recovery contract belongs to a different run"
                )
            recovery_contracts.append((contract_path, contract))
            exact_inputs.add(contract_path.relative_to(root).as_posix())

    severity_by_id: dict[str, tuple[str, str]] = {}
    severity_ledger_path = (
        root / SEVERITY_ADJUDICATION_SOURCE_LEDGER_NAME
    )
    if severity_ledger_path.is_file():
        raw_ledger = load_json(
            severity_ledger_path, "BB severity decision ledger"
        )
        raw_decisions = raw_ledger.get("decisions")
        if not isinstance(raw_decisions, list):
            raise BBVerificationPolicyError(
                "BB severity decision ledger roster is malformed"
            )
        source_digests = {
            str(row.get("candidate_id") or ""): str(
                row.get("source_receipt_digest") or ""
            )
            for row in raw_decisions
            if isinstance(row, Mapping)
        }
        ledger = load_severity_decision_ledger(
            severity_ledger_path,
            expected_run_id=run_id,
            expected_source_receipt_digests=source_digests,
        )
        for decision in ledger["decisions"]:
            projected = project_retention_severity(decision)
            severity = _bb_policy_severity_token(projected["severity"])
            severity_by_id[str(decision["candidate_id"])] = (
                severity,
                str(decision["decision_digest"]),
            )
        exact_inputs.add(
            severity_ledger_path.relative_to(root).as_posix()
        )
    if (
        root / SEVERITY_ADJUDICATION_RECONCILIATION_NAME
    ).is_file():
        exact_inputs.add(SEVERITY_ADJUDICATION_RECONCILIATION_NAME)

    expected_consumptions: list[dict[str, Any]] = []
    roster_path = root / _DYNAMIC_VERIFIER_ROSTER_NAME
    if roster_path.is_file():
        roster = _load_dynamic_verifier_roster(root)
        exact_inputs.add(_DYNAMIC_VERIFIER_ROSTER_NAME)
        for unit in roster.work_units:
            missing_ids = [
                work_id
                for work_id in unit.ordered_work_item_ids
                if work_id not in queue_by_id
            ]
            if missing_ids:
                raise BBVerificationPolicyError(
                    "BB primary roster contains candidates absent from the "
                    "typed queue: " + ", ".join(missing_ids)
                )
            expected_consumptions.append({
                "consumer_work_unit_id": unit.work_unit_id,
                "consumer_kind": "PRIMARY",
                "recovery_id": None,
                "work_items": [
                    {
                        "candidate_id": work_id,
                        "severity": _bb_policy_severity_token(
                            queue_by_id[work_id].severity_proposal.level
                        ),
                        "impact_ids": [],
                    }
                    for work_id in unit.ordered_work_item_ids
                ],
            })
    elif queue_items:
        raise BBVerificationPolicyError(
            "BB terminal reconciliation lacks the primary verifier roster"
        )

    recovery_rows_by_candidate: dict[str, list[dict[str, str]]] = {}
    for _contract_path, contract in recovery_contracts:
        consumer_kind = _bb_policy_recovery_consumer_kind(
            str(contract["recovery_kind"])
        )
        expected_consumptions.append({
            "consumer_work_unit_id": str(contract["recovery_id"]),
            "consumer_kind": consumer_kind,
            "recovery_id": str(contract["recovery_id"]),
            "work_items": [
                {
                    "candidate_id": str(
                        row.get("source_work_item_id")
                        or row["work_item_id"]
                    ),
                    "work_item_id": str(row["work_item_id"]),
                    "severity": _bb_policy_severity_token(
                        row.get("severity")
                    ),
                    "impact_ids": [],
                }
                for row in contract["rows"]
            ],
        })
        for row in contract["rows"]:
            candidate_id = str(
                row.get("source_work_item_id")
                or row["work_item_id"]
            )
            recovery_rows_by_candidate.setdefault(
                candidate_id, []
            ).append({
                "recovery_id": str(contract["recovery_id"]),
                "contract_digest": str(contract["contract_digest"]),
                "work_item_id": str(row["work_item_id"]),
                "consumer_kind": consumer_kind,
                "severity": _bb_policy_severity_token(
                    row.get("severity")
                ),
            })

    candidate_ids = sorted({
        *queue_by_id,
        *recovery_rows_by_candidate,
    })
    candidates: list[dict[str, Any]] = []
    for candidate_id in candidate_ids:
        queue_item = queue_by_id.get(candidate_id)
        recovery_rows = sorted(
            recovery_rows_by_candidate.get(candidate_id, []),
            key=lambda row: (
                row["recovery_id"], row["contract_digest"]
            ),
        )
        semantic_recovery_rows = [
            row for row in recovery_rows
            if row["consumer_kind"] != "BB_POLICY_SEVERITY_CHANGE"
        ]
        if candidate_id in severity_by_id:
            current_severity, decision_digest = severity_by_id[
                candidate_id
            ]
        elif semantic_recovery_rows:
            observed = {
                row["severity"] for row in semantic_recovery_rows
                if row["severity"] in {
                    "critical", "high", "medium", "low",
                    "informational",
                }
            }
            current_severity = (
                next(iter(observed))
                if len(observed) == 1
                else "unresolved"
            )
            decision_digest = ""
        elif queue_item is not None:
            current_severity = _bb_policy_severity_token(
                queue_item.severity_proposal.level
            )
            decision_digest = ""
        else:
            current_severity = "unresolved"
            decision_digest = ""
        state = {
            "candidate_id": candidate_id,
            "current_severity": current_severity,
            "impact_ids": [],
            "queue_work_item_sha256": (
                queue_item.digest if queue_item is not None else ""
            ),
            "severity_decision_sha256": decision_digest,
            "recovery_rows": semantic_recovery_rows,
        }
        candidates.append({
            "candidate_id": candidate_id,
            "current_severity": current_severity,
            "impact_ids": [],
            "candidate_state_sha256": canonical_digest(state),
        })

    expected_by_id = {
        row["consumer_work_unit_id"]: row
        for row in expected_consumptions
    }
    record_roots: dict[str, tuple[str, Path]] = {}
    for consumer_id, expected in expected_by_id.items():
        directory = (
            root / _DYNAMIC_VERIFIER_UNIT_DIR / consumer_id
            if expected["consumer_kind"] == "PRIMARY"
            else recovery_root / consumer_id
        )
        record_roots[consumer_id] = (
            expected["consumer_kind"], directory
        )
    observed_policy_parents = {
        path.parent
        for base in (
            root / _DYNAMIC_VERIFIER_UNIT_DIR,
            recovery_root,
        )
        if base.is_dir()
        for leaf in (
            "bb_policy_work.json",
            "bb_policy_application.json",
            "bb_policy_consumption_receipt.json",
        )
        for path in base.glob(f"*/{leaf}")
        if path.is_file()
    }
    expected_parents = {
        directory for _kind, directory in record_roots.values()
    }
    orphan_parents = sorted(
        observed_policy_parents - expected_parents,
        key=lambda value: value.as_posix(),
    )
    if orphan_parents:
        raise BBVerificationPolicyError(
            "BB terminal reconciliation found an orphan policy consumer: "
            + ", ".join(
                path.relative_to(root).as_posix()
                for path in orphan_parents
            )
        )

    consumption_records: list[dict[str, Any]] = []
    artifact_bytes_by_path: dict[str, bytes] = {}
    for consumer_id, expected in expected_by_id.items():
        _kind, directory = record_roots[consumer_id]
        work_path = directory / "bb_policy_work.json"
        application_path = directory / "bb_policy_application.json"
        receipt_path = (
            directory / "bb_policy_consumption_receipt.json"
        )
        present = [
            path for path in (
                work_path, application_path, receipt_path
            )
            if path.is_file()
        ]
        exact_inputs.update(
            path.relative_to(root).as_posix() for path in present
        )
        if len(present) != 3:
            continue
        work = load_json(work_path, "BB terminal work projection")
        application = load_json(
            application_path, "BB terminal policy application"
        )
        receipt = load_json(
            receipt_path, "BB terminal consumption receipt"
        )
        for artifact_path in (work_path, application_path, receipt_path):
            artifact_bytes_by_path[
                artifact_path.relative_to(root).as_posix()
            ] = artifact_path.read_bytes()
        consumption_records.append({
            "consumer_work_unit_id": consumer_id,
            "consumer_kind": expected["consumer_kind"],
            "recovery_id": expected["recovery_id"],
            "work_projection_artifact": (
                work_path.relative_to(root).as_posix()
            ),
            "work_projection_artifact_sha256": artifact_digest(work_path),
            "application_artifact": (
                application_path.relative_to(root).as_posix()
            ),
            "application_artifact_sha256": artifact_digest(
                application_path
            ),
            "receipt_artifact": (
                receipt_path.relative_to(root).as_posix()
            ),
            "receipt_artifact_sha256": artifact_digest(receipt_path),
            "work_projection": work,
            "application": application,
            "receipt": receipt,
        })

    payload = build_bb_policy_terminal_reconciliation(
        ingress,
        candidate_denominator=candidates,
        expected_consumptions=expected_consumptions,
        consumption_records=consumption_records,
        artifact_bytes_by_path=artifact_bytes_by_path,
    )
    target = root / BB_POLICY_TERMINAL_RECONCILIATION_PATH
    exact_output = target.relative_to(root).as_posix()

    def validate_output() -> Sequence[str]:
        try:
            current = validate_bb_policy_terminal_reconciliation(
                load_json(target, "BB terminal reconciliation"),
                expected_ingress_sha256=ingress["ingress_sha256"],
                expected_driver_run_id=run_id,
                expected_candidate_denominator_sha256=payload[
                    "candidate_denominator_sha256"
                ],
            )
        except (
            BBVerificationPolicyError,
            OSError,
            UnicodeError,
            json.JSONDecodeError,
        ) as exc:
            return (
                "BB terminal reconciliation output invalid: "
                f"{type(exc).__name__}: {exc}",
            )
        return (
            ()
            if current == payload
            else (
                "BB terminal reconciliation differs from its exact "
                "denominator",
            )
        )

    transaction_kwargs = {
        "phase_name": "bb_policy",
        "work_unit_id": "terminal_reconciliation",
        "exact_inputs": tuple(sorted(exact_inputs)),
        "exact_outputs": (exact_output,),
        "validate": validate_output,
    }
    current_payload: dict[str, Any] | None = None
    if target.is_file():
        try:
            current_payload = load_json(
                target, "existing BB terminal reconciliation"
            )
        except BBVerificationPolicyError:
            current_payload = None
    if current_payload == payload:
        issues = _validate_existing_p1dm_driver_transaction(
            root, config, **transaction_kwargs
        )
    else:
        contract, launch = _p1dm_contract_and_launch(
            root,
            config,
            phase_name="bb_policy",
            work_unit_id="terminal_reconciliation",
            exact_inputs=tuple(sorted(exact_inputs)),
            exact_outputs=(exact_output,),
            actor="DRIVER",
        )
        if target.is_file():
            try:
                invalidation = authorize_deterministic_work_unit_reexecution(
                    root,
                    Path(str(config.get("project_root") or root.parent)),
                    contract,
                    launch,
                    run_id=run_id,
                )
            except ArtifactLedgerError as exc:
                raise BBVerificationPolicyError(
                    "BB terminal input/output authority is invalid: "
                    + str(exc)
                ) from exc
            if invalidation is None:
                raise BBVerificationPolicyError(
                    "BB terminal output differs without authenticated "
                    "input-denominator drift"
                )
        issues = _record_p1dm_driver_transaction(
            root,
            config,
            **transaction_kwargs,
            action=lambda: _atomic_driver_json_record(
                target, payload
            ),
        )
    if issues:
        raise BBVerificationPolicyError(
            "BB terminal reconciliation PhaseIO binding failed: "
            + "; ".join(issues)
        )
    return payload


def _commit_bb_policy_driver_projection(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    work_unit_id: str,
    exact_inputs: Sequence[str],
    target: Path,
    payload: Mapping[str, Any],
) -> None:
    """Create, replay, or input-refresh one deterministic BB projection."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        raise BBVerificationPolicyError(
            f"BB projection {work_unit_id} lacks a run identity"
        )
    output_relative = Path(target).relative_to(root).as_posix()

    def load_current() -> dict[str, Any] | None:
        try:
            current = json.loads(
                Path(target).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
        except (
            OSError,
            UnicodeError,
            json.JSONDecodeError,
        ):
            return None
        return current if isinstance(current, dict) else None

    def validate() -> Sequence[str]:
        return (
            ()
            if load_current() == dict(payload)
            else (
                f"BB projection {work_unit_id} differs from its exact "
                "deterministic payload",
            )
        )

    transaction_kwargs = {
        "phase_name": "bb_policy",
        "work_unit_id": work_unit_id,
        "exact_inputs": tuple(exact_inputs),
        "exact_outputs": (output_relative,),
        "validate": validate,
    }
    current = load_current()
    if current == dict(payload):
        issues = _validate_existing_p1dm_driver_transaction(
            root, config, **transaction_kwargs
        )
    else:
        contract, launch = _p1dm_contract_and_launch(
            root,
            config,
            phase_name="bb_policy",
            work_unit_id=work_unit_id,
            exact_inputs=tuple(exact_inputs),
            exact_outputs=(output_relative,),
            actor="DRIVER",
        )
        if Path(target).is_file():
            try:
                invalidation = authorize_deterministic_work_unit_reexecution(
                    root,
                    Path(str(config.get("project_root") or root.parent)),
                    contract,
                    launch,
                    run_id=run_id,
                )
            except ArtifactLedgerError as exc:
                raise BBVerificationPolicyError(
                    f"BB projection {work_unit_id} input/output authority is "
                    f"invalid: {exc}"
                ) from exc
            if invalidation is None:
                raise BBVerificationPolicyError(
                    f"BB projection {work_unit_id} changed without "
                    "authenticated input drift"
                )
        issues = _record_p1dm_driver_transaction(
            root,
            config,
            **transaction_kwargs,
            action=lambda: _atomic_driver_json_record(
                Path(target), dict(payload)
            ),
        )
    if issues:
        raise BBVerificationPolicyError(
            f"BB projection {work_unit_id} PhaseIO binding failed: "
            + "; ".join(issues)
        )


def _run_bb_policy_terminal_boundary(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[dict[str, Any] | None, list[str]]:
    """Reconcile policy delivery, run at most one additive severity wave."""

    if not bb_policy_configured(config):
        return None, []
    root = Path(scratchpad)
    issues: list[str] = []
    try:
        terminal = _compile_bb_policy_terminal_reconciliation(
            root, config
        )
        if terminal is None:
            return None, []
        ingress = _load_bound_bb_policy_ingress(
            root,
            build_bb_policy_ingress_payload(
                config,
                driver_run_id=str(config.get("_run_id") or ""),
            )
            or {},
        )
        plan = build_bb_policy_severity_reverification_plan(
            ingress,
            candidate_denominator=terminal[
                "candidate_denominator"
            ],
            reconciliation=terminal,
        )
        plan_path = root / BB_POLICY_SEVERITY_REVERIFICATION_PATH
        _commit_bb_policy_driver_projection(
            scratchpad=root,
            config=config,
            work_unit_id="severity_reverification",
            exact_inputs=(
                BB_POLICY_LOCAL_INGRESS_PATH,
                BB_POLICY_TERMINAL_RECONCILIATION_PATH,
            ),
            target=plan_path,
            payload=plan,
        )
        obligations = list(plan.get("obligations") or [])
        if obligations:
            candidate_by_id = {
                row["candidate_id"]: row
                for row in terminal["candidate_denominator"]
            }
            recovery_rows: list[tuple[str, dict[str, Any]]] = []
            for obligation in obligations:
                candidate_id = str(obligation["candidate_id"])
                candidate = candidate_by_id[candidate_id]
                work_id = (
                    "BBRV-"
                    + str(obligation["recovery_id"])
                    .rsplit("-", 1)[-1]
                )
                recovery_rows.append((
                    work_id,
                    {
                        "work_item_id": work_id,
                        "severity": str(obligation["to_severity"]),
                        "title": (
                            "Bug-bounty policy severity re-verification "
                            f"for {candidate_id}"
                        ),
                        "bug_class": "bb-policy-severity-change",
                        "poc_class": "structural",
                        "location_records": [],
                        "primary_artifacts": [
                            BB_POLICY_TERMINAL_RECONCILIATION_PATH,
                            BB_POLICY_SEVERITY_REVERIFICATION_PATH,
                        ],
                        "mechanism": (
                            "Re-apply the exact verifier-only policy roster "
                            "at the current bound severity."
                        ),
                        "harm": (
                            "Unapplied severity-scoped verification policy "
                            "retains the candidate for review."
                        ),
                        "evidence": (
                            BB_POLICY_SEVERITY_REVERIFICATION_PATH
                        ),
                        "source_candidate_digest": candidate[
                            "candidate_state_sha256"
                        ],
                        "source_work_item_id": candidate_id,
                        "source_identity": candidate_id,
                        "producer_identity": (
                            "bb-policy-severity-plan"
                        ),
                        "required_discriminator_identity": (
                            "independent-recovery-verifier"
                        ),
                        "independent_discriminator_required": True,
                    },
                ))
            recovery_config = dict(config)
            recovery_config["_verification_recovery_kind"] = (
                "BB_POLICY_SEVERITY_CHANGE"
            )
            unresolved = _run_verify_recovery_shard(
                recovery_config, recovery_rows
            )
            issues.extend(
                "BB policy severity re-verification remains unresolved: "
                + work_id
                for work_id in unresolved
            )
            terminal = _compile_bb_policy_terminal_reconciliation(
                root, config
            )
            if terminal is None:
                raise BBVerificationPolicyError(
                    "BB terminal reconciliation disappeared after "
                    "severity re-verification"
                )
            plan = build_bb_policy_severity_reverification_plan(
                ingress,
                candidate_denominator=terminal[
                    "candidate_denominator"
                ],
                reconciliation=terminal,
            )
            _commit_bb_policy_driver_projection(
                scratchpad=root,
                config=config,
                work_unit_id="severity_reverification",
                exact_inputs=(
                    BB_POLICY_LOCAL_INGRESS_PATH,
                    BB_POLICY_TERMINAL_RECONCILIATION_PATH,
                ),
                target=plan_path,
                payload=plan,
            )
        for consumer_kind, work_unit_id, target_name in (
            (
                "SKEPTIC",
                "downstream.skeptic",
                BB_POLICY_SKEPTIC_RECONCILIATION_PATH,
            ),
            (
                "REPORT",
                "downstream.report",
                BB_POLICY_REPORT_RECONCILIATION_PATH,
            ),
        ):
            projection = (
                build_bb_policy_downstream_reconciliation_projection(
                    terminal,
                    consumer_kind=consumer_kind,
                )
            )
            _commit_bb_policy_driver_projection(
                scratchpad=root,
                config=config,
                work_unit_id=work_unit_id,
                exact_inputs=(
                    BB_POLICY_TERMINAL_RECONCILIATION_PATH,
                ),
                target=root / target_name,
                payload=projection,
            )
        unresolved_candidates = [
            row["candidate_id"]
            for row in terminal["candidate_results"]
            if row["reconciliation_state"] != "RECONCILED"
        ]
        issues.extend(
            "BB policy reconciliation retains candidate for requeue/review: "
            + candidate_id
            for candidate_id in unresolved_candidates
        )
        return terminal, list(dict.fromkeys(issues))
    except Exception as exc:
        issues.append(
            "BB policy terminal boundary failed haltlessly: "
            f"{type(exc).__name__}: {exc}"
        )
        _append_phase_io_debt(
            root,
            "bb_policy",
            "BB_POLICY_TERMINAL_RECONCILIATION_DEBT",
            issues[-1],
        )
        return None, list(dict.fromkeys(issues))


def _bb_policy_recovery_consumer_kind(recovery_kind: str) -> str:
    kind = str(recovery_kind or "").strip().upper()
    if kind == "BB_POLICY_SEVERITY_CHANGE":
        return "BB_POLICY_SEVERITY_CHANGE"
    if kind == "MANDATORY_REOPEN":
        return "MANDATORY_REVERIFY"
    if kind in {
        "LATE_OPERATOR_CANDIDATE",
        "POST_VERIFY_SIDE_OBSERVATION",
        "REPORT_INDEX_DROPOUT",
    }:
        return "LATE_REVERIFY"
    return "RECOVERY"


def _expected_verify_recovery_bb_policy(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    contract: Mapping[str, Any],
) -> dict[str, Any] | None:
    if not bb_policy_configured(config):
        return None
    run_id = str(config.get("_run_id") or "").strip()
    ingress = _load_bound_bb_policy_ingress(
        Path(scratchpad),
        build_bb_policy_ingress_payload(
            config, driver_run_id=run_id
        ) or {},
    )
    work_rows: list[dict[str, Any]] = []
    for row in contract["rows"]:
        severity = _bb_policy_severity_token(row.get("severity"))
        work_rows.append({
            "work_item_id": str(row["work_item_id"]),
            "severity": severity,
            "impact_ids": [],
        })
    return build_bb_policy_work_projection(
        ingress,
        consumer_work_unit_id=str(contract["recovery_id"]),
        consumer_kind=_bb_policy_recovery_consumer_kind(
            str(contract["recovery_kind"])
        ),
        work_items=work_rows,
    )


def _prepare_verify_recovery_bb_policy(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    contract: Mapping[str, Any],
    directory: Path,
) -> tuple[dict[str, Any] | None, dict[str, Path]]:
    paths = {
        "work": Path(directory) / "bb_policy_work.json",
        "application": Path(directory) / "bb_policy_application.json",
        "receipt": Path(directory) / "bb_policy_consumption_receipt.json",
        "prompt": Path(directory) / "prompt_with_bb_policy.md",
    }
    projection = _expected_verify_recovery_bb_policy(
        scratchpad=Path(scratchpad),
        config=config,
        contract=contract,
    )
    if projection is None:
        return None, paths
    relative_output = paths["work"].relative_to(scratchpad).as_posix()
    validate_projection = lambda: (
        ()
        if validate_bb_policy_work_projection(json.loads(
            paths["work"].read_text(
                encoding="utf-8", errors="strict"
            )
        )) == projection
        else ("BB recovery work projection denominator mismatch",)
    )
    transaction = (
        _validate_existing_p1dm_driver_transaction
        if paths["work"].is_file()
        else _record_p1dm_driver_transaction
    )
    transaction_kwargs: dict[str, Any] = {
        "phase_name": "bb_policy",
        "work_unit_id": (
            "projection." + str(contract["recovery_id"]).lower()
        ),
        "exact_inputs": (BB_POLICY_LOCAL_INGRESS_PATH,),
        "exact_outputs": (relative_output,),
        "validate": validate_projection,
    }
    if transaction is _record_p1dm_driver_transaction:
        transaction_kwargs["action"] = lambda: _write_or_validate_bb_policy_json(
            paths["work"],
            projection,
            validator=validate_bb_policy_work_projection,
        )
    issues = transaction(
        Path(scratchpad),
        config,
        **transaction_kwargs,
    )
    if issues:
        raise BBVerificationPolicyError(
            "BB recovery work PhaseIO binding failed: "
            + "; ".join(issues)
        )
    return projection, paths


def _build_verify_recovery_bb_policy_receipt(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    contract: Mapping[str, Any],
    work_projection: Mapping[str, Any],
    application_path: Path,
    dispatch_path: Path,
    launch_digest: str,
) -> dict[str, Any]:
    try:
        proposal = json.loads(
            Path(application_path).read_text(
                encoding="utf-8", errors="strict"
            )
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise BBVerificationPolicyError(
            "BB recovery application proposal is absent or malformed"
        ) from exc
    outputs = [
        {
            "work_item_id": str(row["work_item_id"]),
            "artifact": f"verify_{row['work_item_id']}.md",
            "sha256": hashlib.sha256(
                (
                    Path(scratchpad)
                    / f"verify_{row['work_item_id']}.md"
                ).read_bytes()
            ).hexdigest(),
        }
        for row in contract["rows"]
    ]
    output_digest = hashlib.sha256(
        json.dumps(
            {"outputs": outputs},
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    ingress = _load_bound_bb_policy_ingress(
        Path(scratchpad),
        build_bb_policy_ingress_payload(
            config,
            driver_run_id=str(config.get("_run_id") or ""),
        ) or {},
    )
    return build_bb_policy_consumption_receipt(
        ingress,
        work_projection=work_projection,
        proposal=proposal,
        launch_digest=launch_digest,
        method_dispatch_sha256=hashlib.sha256(
            Path(dispatch_path).read_bytes()
        ).hexdigest(),
        verifier_output_sha256=output_digest,
        corroborations=(),
    )


def _bind_verify_recovery_bb_policy_receipt(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    contract: Mapping[str, Any],
    work_projection: Mapping[str, Any],
    paths: Mapping[str, Path],
    work_path: Path,
    application_path: Path,
    receipt_path: Path,
    launch_path: Path,
    launch_digest: str,
) -> dict[str, Any]:
    receipt = _build_verify_recovery_bb_policy_receipt(
        scratchpad=Path(scratchpad),
        config=config,
        contract=contract,
        work_projection=work_projection,
        application_path=Path(application_path),
        dispatch_path=Path(paths["dispatch"]),
        launch_digest=launch_digest,
    )
    exact_inputs = (
        Path(work_path).relative_to(scratchpad).as_posix(),
        Path(application_path).relative_to(scratchpad).as_posix(),
        Path(paths["dispatch"]).relative_to(scratchpad).as_posix(),
        Path(launch_path).relative_to(scratchpad).as_posix(),
        *(
            f"verify_{row['work_item_id']}.md"
            for row in contract["rows"]
        ),
    )
    output_relative = Path(receipt_path).relative_to(
        scratchpad
    ).as_posix()
    issues = _record_p1dm_driver_transaction(
        Path(scratchpad),
        config,
        phase_name="bb_policy",
        work_unit_id=(
            "consumption." + str(contract["recovery_id"]).lower()
        ),
        exact_inputs=exact_inputs,
        exact_outputs=(output_relative,),
        action=lambda: _write_or_validate_bb_policy_json(
            Path(receipt_path),
            receipt,
            validator=validate_bb_policy_consumption_receipt,
        ),
        validate=lambda: (
            ()
            if validate_bb_policy_consumption_receipt(json.loads(
                Path(receipt_path).read_text(
                    encoding="utf-8", errors="strict"
                )
            )) == receipt
            else ("BB recovery consumption receipt input mismatch",)
        ),
    )
    if issues:
        raise BBVerificationPolicyError(
            "BB recovery consumption PhaseIO binding failed: "
            + "; ".join(issues)
        )
    return receipt


def _run_verify_recovery_unit(
    config: dict[str, Any],
    missing: list[tuple[str, dict]],
) -> list[str]:
    scratchpad = Path(config["scratchpad"])
    project_root = Path(config["project_root"])
    repo_root = Path(__file__).resolve().parent.parent
    run_id = str(config.get("_run_id") or "test-unbound")
    backend = str(config.get("cli_backend") or "claude").strip().lower()
    pipeline = "l1" if str(config.get("pipeline")) == "l1" else "sc"
    recovery_kind = str(
        config.get("_verification_recovery_kind") or "RESUME_QUEUE_DROPOUT"
    ).strip().upper()
    rows: list[dict[str, Any]] = []
    for work_id, source in missing:
        row = dict(source)
        row["work_item_id"] = work_id
        rows.append(row)
    try:
        contract = build_verification_recovery_contract(
            run_id=run_id,
            recovery_kind=recovery_kind,
            rows=rows,
            scratchpad=scratchpad,
            project_root=project_root,
            pipeline=pipeline,
            ecosystem=str(config.get("language") or ("rust" if pipeline == "l1" else "evm")).lower(),
            backend=backend,
            repo_root=repo_root,
            max_rows=_VERIFY_RECOVERY_MAX_ROWS,
        )
        validate_verification_recovery_contract(contract, repo_root=repo_root)
        directory = (
            scratchpad
            / PurePosixPath(str(contract["manifest_path"])).parent
        )
        paths = {
            "contract": directory / "contract.json",
            "manifest": scratchpad / PurePosixPath(str(contract["manifest_path"])),
            "context": scratchpad / PurePosixPath(str(contract["context_path"])),
            "dispatch": scratchpad / PurePosixPath(
                str(contract["method_dispatch_path"])
            ),
            "prompt": scratchpad / PurePosixPath(str(contract["prompt_path"])),
        }
        bb_policy_work, bb_paths = _prepare_verify_recovery_bb_policy(
            scratchpad=scratchpad,
            config=config,
            contract=contract,
            directory=directory,
        )
        model_outputs = tuple(contract["expected_model_outputs"])
        launch_prompt_path = paths["prompt"]
        launch_prompt_bytes = str(contract["prompt_markdown"]).encode(
            "utf-8"
        )
        if bb_policy_work is not None:
            application_relative = bb_paths["application"].relative_to(
                scratchpad
            ).as_posix()
            launch_prompt_path = bb_paths["prompt"]
            launch_prompt_bytes += bb_policy_work_prompt_suffix(
                bb_paths["work"].relative_to(scratchpad).as_posix(),
                bb_policy_work,
                application_relative_path=application_relative,
            ).encode("utf-8")
            model_outputs += (application_relative,)
        launch_spec = _verify_recovery_launch_spec(
            contract,
            config=config,
            prompt_bytes_override=launch_prompt_bytes,
            expected_output_files_override=model_outputs,
        )
        launch_path = directory / "launch_spec.json"
        execution_path = directory / "execution_receipt.json"
        (
            prelaunch_io_contract,
            model_io_contract,
            control_io_contract,
        ) = _write_verifier_method_phase_io_contracts(
            directory=directory,
            scratchpad=scratchpad,
            config=config,
            phase_name="verify_recovery",
            work_unit_id=str(contract["recovery_id"]).lower(),
            model_outputs=model_outputs,
            operator_receipts=contract["expected_operator_receipts"],
            immutable_launch_inputs=(
                paths["contract"], paths["manifest"], paths["context"],
                paths["dispatch"], paths["prompt"],
                *(
                    (bb_paths["work"], launch_prompt_path)
                    if bb_policy_work is not None
                    else ()
                ),
                launch_path,
            ),
            shared_immutable_inputs=(
                (bb_paths["work"],)
                if bb_policy_work is not None
                else ()
            ),
            driver_outputs=(
                paths["contract"], paths["manifest"], paths["context"],
                paths["dispatch"], paths["prompt"], launch_path, execution_path,
            ),
        )
        prelaunch_launch = LaunchSpec(
            work_unit_key=prelaunch_io_contract.key,
            pipeline=prelaunch_io_contract.pipeline,
            mode=prelaunch_io_contract.mode,
            ecosystem=prelaunch_io_contract.ecosystem,
            backend=prelaunch_io_contract.backend,
            model="driver",
            timeout_s=launch_spec.timeout_seconds,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        prelaunch_execute, prelaunch_arm_issues = (
            _arm_deterministic_driver_work_unit(
                scratchpad=scratchpad,
                project_root=project_root,
                contract=prelaunch_io_contract,
                launch=prelaunch_launch,
                run_id=run_id,
            )
        )
        if prelaunch_arm_issues:
            raise ValueError(
                "recovery prelaunch arm invalid: "
                + "; ".join(prelaunch_arm_issues)
            )
        if prelaunch_execute:
            materialized = materialize_verification_recovery_contract(
                scratchpad, contract, repo_root=repo_root
            )
            if materialized != paths:
                raise ValueError("recovery canonical path resolution drift")
            if bb_policy_work is not None:
                if launch_prompt_path.is_file():
                    if launch_prompt_path.read_bytes() != launch_prompt_bytes:
                        raise ValueError(
                            "recovery BB launch prompt differs from authority"
                        )
                else:
                    _atomic_driver_bytes(
                        launch_prompt_path, launch_prompt_bytes
                    )
            _atomic_driver_json_record(launch_path, launch_spec.to_dict())
            _materialize_verifier_method_phase_io_contracts(
                directory,
                prelaunch_contract=prelaunch_io_contract,
                model_contract=model_io_contract,
                control_contract=control_io_contract,
            )
            prelaunch_commit_issues = (
                _commit_deterministic_driver_work_unit(
                    scratchpad=scratchpad,
                    project_root=project_root,
                    contract=prelaunch_io_contract,
                    launch=prelaunch_launch,
                    run_id=run_id,
                )
            )
            if prelaunch_commit_issues:
                raise ValueError(
                    "recovery prelaunch commit invalid: "
                    + "; ".join(prelaunch_commit_issues)
                )
        if not launch_path.is_file():
            raise ValueError("recovery launch spec is missing after prelaunch")
        existing_launch = VerifierLaunchSpec.from_json(
            launch_path.read_text(encoding="utf-8", errors="strict")
        )
        if existing_launch != launch_spec:
            raise ValueError("recovery launch spec drift")
        compatibility_issues = (
            _publish_verify_recovery_compatibility_projection(
                scratchpad=scratchpad,
                project_root=project_root,
                config=config,
                run_id=run_id,
                manifest_path=paths["manifest"],
                prompt_path=launch_prompt_path,
            )
        )
        for issue in compatibility_issues:
            _append_phase_io_debt(
                scratchpad,
                "verify_recovery",
                "RECOVERY_COMPATIBILITY_PROJECTION_DEBT",
                issue,
            )
        phase_io_common = {
            "prelaunch_contract": prelaunch_io_contract,
            "model_contract": model_io_contract,
            "control_contract": control_io_contract,
            "launch_spec": launch_spec,
            "scratchpad": scratchpad,
            "project_root": project_root,
            "run_id": run_id,
        }
        if execution_path.is_file():
            resume_io_issues = _record_verifier_method_phase_io_authority(
                **phase_io_common,
                include_outputs=True,
                allow_initialize=False,
            )
            if resume_io_issues:
                raise ValueError(
                    "recovery resume PhaseIO authority invalid: "
                    + "; ".join(resume_io_issues)
                )
            receipt = _load_current_verify_recovery_execution_receipt(
                execution_path,
                contract=contract,
                launch_spec=launch_spec,
                scratchpad=scratchpad,
            )
            if bb_policy_work is not None:
                if not bb_paths["receipt"].is_file():
                    raise ValueError(
                        "recovery BB policy receipt missing on resume"
                    )
                expected_bb_receipt = (
                    _build_verify_recovery_bb_policy_receipt(
                        scratchpad=scratchpad,
                        config=config,
                        contract=contract,
                        work_projection=bb_policy_work,
                        application_path=bb_paths["application"],
                        dispatch_path=paths["dispatch"],
                        launch_digest=launch_spec.digest,
                    )
                )
                recorded_bb_receipt = (
                    validate_bb_policy_consumption_receipt(json.loads(
                        bb_paths["receipt"].read_text(
                            encoding="utf-8", errors="strict"
                        )
                    ))
                )
                if recorded_bb_receipt != expected_bb_receipt:
                    raise ValueError(
                        "recovery BB policy receipt is stale"
                    )
                bb_phaseio_issues = (
                    _bb_policy_consumption_phaseio_issues(
                        scratchpad=scratchpad,
                        config=config,
                        work_unit_id=(
                            "consumption."
                            + str(contract["recovery_id"]).lower()
                        ),
                        exact_inputs=(
                            bb_paths["work"].relative_to(
                                scratchpad
                            ).as_posix(),
                            bb_paths["application"].relative_to(
                                scratchpad
                            ).as_posix(),
                            paths["dispatch"].relative_to(
                                scratchpad
                            ).as_posix(),
                            launch_path.relative_to(
                                scratchpad
                            ).as_posix(),
                            *(
                                f"verify_{row['work_item_id']}.md"
                                for row in contract["rows"]
                            ),
                        ),
                        exact_output=bb_paths["receipt"].relative_to(
                            scratchpad
                        ).as_posix(),
                    )
                )
                if bb_phaseio_issues:
                    raise ValueError(
                        "recovery BB policy PhaseIO authority invalid: "
                        + "; ".join(bb_phaseio_issues)
                    )
            return list(receipt.get("unresolved_work_item_ids") or [])
        preexisting = [
            name for name in model_outputs
            if (scratchpad / name).exists()
        ]
        if preexisting:
            raise ValueError(
                "pre-existing unbound recovery output(s) cannot be adopted: "
                + ", ".join(preexisting)
            )
        phase_io_issues = _record_verifier_method_phase_io_authority(
            **phase_io_common, include_outputs=False
        )
        if phase_io_issues:
            raise ValueError(
                "recovery PhaseIO input authority invalid: "
                + "; ".join(phase_io_issues)
            )
        model_launch = LaunchSpec(
            work_unit_key=model_io_contract.key,
            pipeline=model_io_contract.pipeline,
            mode=model_io_contract.mode,
            ecosystem=model_io_contract.ecosystem,
            backend=model_io_contract.backend,
            model=launch_spec.model,
            timeout_s=launch_spec.timeout_seconds,
            exec_mode=launch_spec.transport,
            tool_policy=("filesystem", "shell", "foreground-only"),
        )
        control_launch = LaunchSpec(
            work_unit_key=control_io_contract.key,
            pipeline=control_io_contract.pipeline,
            mode=control_io_contract.mode,
            ecosystem=control_io_contract.ecosystem,
            backend=control_io_contract.backend,
            model="driver",
            timeout_s=launch_spec.timeout_seconds,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        control_prior = read_artifact_ledger(
            scratchpad
        ).get("work_units", {}).get(control_io_contract.key)
        if not (
            isinstance(control_prior, Mapping)
            and control_prior.get("execution_state")
            == "INPUTS_BOUND_PREEXECUTION"
        ):
            record_work_unit_inputs(
                scratchpad,
                project_root,
                control_io_contract,
                control_launch,
                run_id=run_id,
            )
        control_input_issues = validate_work_unit_inputs(
            scratchpad,
            project_root,
            control_io_contract,
            control_launch,
            run_id=run_id,
        )
        if control_input_issues:
            raise ValueError(
                "recovery control preexecution invalid: "
                + "; ".join(control_input_issues)
            )
        rc = _execute_dynamic_verifier_launch(
            launch_spec,
            prompt_path=launch_prompt_path,
            log_path=directory / "stdio.log",
            scratchpad=scratchpad,
            phase=_verify_recovery_phase_stub(),
            config=config,
            model_io_contract=model_io_contract,
            model_io_launch=model_launch,
        )
        if rc != 0:
            raise RuntimeError(f"recovery verifier exited rc={rc}")
        issues = _validate_verify_recovery_model_outputs(scratchpad, contract)
        if not issues:
            record_work_unit_artifacts(
                scratchpad,
                project_root,
                model_io_contract,
                model_launch,
                run_id=run_id,
                actor="MODEL",
            )
            model_output_issues = validate_work_unit_artifacts(
                scratchpad,
                project_root,
                model_io_contract,
                model_launch,
                run_id=run_id,
                actor="MODEL",
            )
            if model_output_issues:
                raise ValueError(
                    "recovery model output PhaseIO invalid: "
                    + "; ".join(model_output_issues)
                )
        dispatch = contract["method_dispatch"]
        for row in contract["rows"]:
            work_id = str(row["work_item_id"])
            if any(issue.startswith(f"{work_id}:") for issue in issues):
                continue
            try:
                bind_operator_application_receipt(
                    proposal_path=scratchpad / f"verify_{work_id}.operator_application.json",
                    verify_path=scratchpad / f"verify_{work_id}.md",
                    receipt_path=scratchpad / f"verify_{work_id}.operator_receipt.json",
                    dispatch=dispatch,
                    launch_digest=launch_spec.digest,
                    verdict=_verifier_markdown_verdict(scratchpad / f"verify_{work_id}.md"),
                    root=repo_root,
                )
                load_bound_operator_receipt(
                    receipt_path=scratchpad / f"verify_{work_id}.operator_receipt.json",
                    proposal_path=scratchpad / f"verify_{work_id}.operator_application.json",
                    verify_path=scratchpad / f"verify_{work_id}.md",
                    dispatch=dispatch,
                    launch_digest=launch_spec.digest,
                )
            except Exception as exc:
                issues.append(
                    f"{work_id}: operator receipt binding invalid: "
                    f"{type(exc).__name__}: {exc}"
                )
        if bb_policy_work is not None and not issues:
            try:
                _bind_verify_recovery_bb_policy_receipt(
                    scratchpad=scratchpad,
                    config=config,
                    contract=contract,
                    work_projection=bb_policy_work,
                    paths=paths,
                    work_path=bb_paths["work"],
                    application_path=bb_paths["application"],
                    receipt_path=bb_paths["receipt"],
                    launch_path=launch_path,
                    launch_digest=launch_spec.digest,
                )
            except Exception as exc:
                issues.extend(
                    f"{row['work_item_id']}: BB policy consumption invalid: "
                    f"{type(exc).__name__}: {exc}"
                    for row in contract["rows"]
                )
        issues = list(dict.fromkeys(issues))
        unresolved = [
            str(row["work_item_id"])
            for row in contract["rows"]
            if any(issue.startswith(f"{row['work_item_id']}:") for issue in issues)
        ]
        output_hashes = {
            name: hashlib.sha256((scratchpad / name).read_bytes()).hexdigest()
            for name in contract["expected_model_outputs"]
            if (scratchpad / name).is_file()
        }
        operator_hashes = {
            name: hashlib.sha256((scratchpad / name).read_bytes()).hexdigest()
            for name in contract["expected_operator_receipts"]
            if (scratchpad / name).is_file()
        }
        payload: dict[str, Any] = {
            "schema_version": _VERIFY_RECOVERY_RECEIPT_SCHEMA,
            "status": "COMPLETED" if not unresolved else "COMPLETED_WITH_DEBT",
            "recovery_id": contract["recovery_id"],
            "recovery_kind": contract["recovery_kind"],
            "contract_digest": contract["contract_digest"],
            "launch_spec_digest": launch_spec.digest,
            "ordered_work_item_ids": [row["work_item_id"] for row in contract["rows"]],
            "unresolved_work_item_ids": unresolved,
            "issues": issues,
            "output_sha256": output_hashes,
            "operator_receipt_sha256": operator_hashes,
            "terminal_negative_authority": False,
        }
        payload["receipt_digest"] = _verify_recovery_execution_receipt_digest(payload)
        _atomic_driver_json_record(execution_path, payload)
        if not unresolved:
            control_commit_issues = _commit_deterministic_driver_work_unit(
                scratchpad=scratchpad,
                project_root=project_root,
                contract=control_io_contract,
                launch=control_launch,
                run_id=run_id,
            )
            if control_commit_issues:
                raise ValueError(
                    "recovery control output PhaseIO invalid: "
                    + "; ".join(control_commit_issues)
                )
        final_io_issues = _record_verifier_method_phase_io_authority(
            **phase_io_common,
            include_outputs=True,
            allow_initialize=False,
        )
        if unresolved:
            for issue in final_io_issues:
                _append_phase_io_debt(
                    scratchpad,
                    "verify_recovery",
                    "RECOVERY_PHASE_IO_LEDGER_DEBT",
                    issue,
                )
        elif final_io_issues:
            raise ValueError(
                "recovery completion PhaseIO authority invalid: "
                + "; ".join(final_io_issues)
            )
        return unresolved
    except Exception as exc:
        detail = f"{type(exc).__name__}: {exc}"
        _append_phase_io_debt(
            scratchpad,
            "verify_recovery",
            "COMPILER_BOUND_RECOVERY_DEBT",
            detail,
        )
        log.warning("[verify_recovery] compiler-bound recovery retained debt: %s", detail)
        return [work_id for work_id, _row in missing]


def _run_verify_recovery_shard_legacy_retired(
    config: dict,
    missing: list[tuple[str, dict]],
) -> list[str]:
    """Fail closed if any stale caller reaches the retired recovery launcher."""

    raise RuntimeError(
        "legacy verification recovery is retired; use the compiler-bound "
        "_run_verify_recovery_shard"
    )


def _run_verify_recovery_shard(
    config: dict,
    missing: list[tuple[str, dict]],
) -> list[str]:
    """Run every recovery through bounded compiler/context/receipt contracts."""

    unresolved: list[str] = []
    for offset in range(0, len(missing), _VERIFY_RECOVERY_MAX_ROWS):
        unresolved.extend(
            _run_verify_recovery_unit(
                config,
                missing[offset : offset + _VERIFY_RECOVERY_MAX_ROWS],
            )
        )
    return list(dict.fromkeys(unresolved))


def _initial_verifier_operator_receipt_denominator(
    scratchpad: Path,
) -> list[Path]:
    """Enumerate only exact, currently bound primary/recovery receipts.

    Missing expected receipts are denominator debt, never silent omissions.
    The immutable wave-one snapshot prevents operator-generated recoveries from
    expanding their own first-pass denominator during resume.
    """

    root = Path(scratchpad)
    repo_root = Path(__file__).resolve().parent.parent
    wave_one_path = root / "verification_operator_wave_one_denominator.json"
    if wave_one_path.is_file():
        try:
            frozen = json.loads(
                wave_one_path.read_text(encoding="utf-8", errors="strict")
            )
            if set(frozen) != {
                "schema_version", "status", "queue_work_plan_digest",
                "verifier_roster_digest", "expected_work_item_ids",
                "source_receipt_count", "source_receipts", "debt_count",
                "debts", "authority_digest",
            }:
                raise ValueError("wave-one denominator fields are not exact")
            frozen_unsigned = {
                key: value for key, value in frozen.items()
                if key != "authority_digest"
            }
            if frozen["authority_digest"] != verification_method_stable_digest(
                frozen_unsigned
            ):
                raise ValueError("wave-one denominator digest mismatch")
            current_plan = read_queue_work_plan(root)
            current_roster = _load_dynamic_verifier_roster(
                root, require_current_plan=True
            )
            if (
                frozen["queue_work_plan_digest"] != current_plan.digest
                or frozen["verifier_roster_digest"] != current_roster.digest
            ):
                raise ValueError("wave-one queue plan or roster changed")
            valid: list[Path] = []
            replay_debts = list(frozen["debts"])
            for source in frozen["source_receipts"]:
                path = root / str(source["path"])
                actual = (
                    hashlib.sha256(path.read_bytes()).hexdigest()
                    if path.is_file() else None
                )
                if actual != source["sha256"]:
                    semantic = {
                        "debt_code": "EXPECTED_OPERATOR_RECEIPT_MISSING_OR_UNBOUND",
                        "affected_work_item_ids": [source["work_item_id"]],
                        "detail": "immutable wave-one source receipt is missing or changed",
                        "source_identity": source["source_identity"],
                    }
                    replay_debts.append({
                        **semantic,
                        "debt_digest": verification_method_stable_digest(semantic),
                    })
                    continue
                valid.append(path)
            replay_unsigned = {
                **frozen_unsigned,
                "status": "COMPLETED_WITH_DEBT" if replay_debts else frozen["status"],
                "debt_count": len(replay_debts),
                "debts": replay_debts,
            }
            replay = {
                **replay_unsigned,
                "authority_digest": verification_method_stable_digest(replay_unsigned),
            }
            _atomic_driver_json(
                root / "verification_operator_denominator_authority.json", replay
            )
            return valid
        except Exception as exc:
            semantic = {
                "debt_code": "IMMUTABLE_WAVE_ONE_DENOMINATOR_INVALID",
                "affected_work_item_ids": [],
                "detail": f"{type(exc).__name__}: {exc}",
                "source_identity": wave_one_path.name,
            }
            debt_row = {
                **semantic,
                "debt_digest": verification_method_stable_digest(semantic),
            }
            unsigned = {
                "schema_version": "plamen.verification_operator_denominator.v1",
                "status": "COMPLETED_WITH_DEBT",
                "queue_work_plan_digest": None,
                "verifier_roster_digest": None,
                "expected_work_item_ids": [],
                "source_receipt_count": 0,
                "source_receipts": [],
                "debt_count": 1,
                "debts": [debt_row],
            }
            _atomic_driver_json(
                root / "verification_operator_denominator_authority.json",
                {**unsigned, "authority_digest": verification_method_stable_digest(unsigned)},
            )
            return []
    sources: dict[str, dict[str, Any]] = {}
    debts: list[dict[str, Any]] = []
    expected_ids: list[str] = []
    queue_plan_digest: str | None = None
    roster_digest: str | None = None

    def debt(code: str, ids: Sequence[str], detail: str, source: str) -> None:
        affected = list(dict.fromkeys(str(value) for value in ids if str(value)))
        semantic = {
            "debt_code": code,
            "affected_work_item_ids": affected,
            "detail": detail,
            "source_identity": source,
        }
        debts.append({**semantic, "debt_digest": verification_method_stable_digest(semantic)})

    try:
        plan = read_queue_work_plan(root)
        roster = _load_dynamic_verifier_roster(root, require_current_plan=True)
        queue_plan_digest = plan.digest
        roster_digest = roster.digest
        expected_ids.extend(roster.ordered_work_item_ids)
        if not roster.ordered_work_item_ids:
            debt(
                "EMPTY_PRIMARY_OPERATOR_DENOMINATOR",
                (),
                "current QueueWorkPlan/roster has no verifier work identities",
                _DYNAMIC_VERIFIER_ROSTER_NAME,
            )
        for unit in roster.work_units:
            unit_paths = _dynamic_verifier_unit_paths(root, unit.work_unit_id)
            try:
                unit_receipt = VerifierUnitReceipt.from_json(
                    unit_paths["receipt"].read_text(encoding="utf-8", errors="strict")
                )
                if (
                    unit_receipt.status != "COMPLETED"
                    or unit_receipt.work_unit_resume_digest != unit.resume_digest
                ):
                    raise ValueError("unit completion receipt is not current and complete")
                launch = VerifierLaunchSpec.from_json(
                    unit_paths["launch_spec"].read_text(
                        encoding="utf-8", errors="strict"
                    )
                )
                if unit_receipt.launch_spec_digest != launch.digest:
                    raise ValueError("unit launch receipt mismatch")
                dispatch = json.loads(
                    unit_paths["method_dispatch"].read_text(
                        encoding="utf-8", errors="strict"
                    )
                )
                gate = json.loads(
                    unit_paths["gate"].read_text(encoding="utf-8", errors="strict")
                )
                if set(gate) != {
                    "schema_version", "state", "work_unit_id",
                    "work_unit_resume_digest", "roster_digest",
                    "launch_spec_digest", "method_dispatch_id",
                    "method_dispatch_sha256", "ordered_work_item_ids",
                    "operator_receipt_digests", "output_sha256",
                }:
                    raise ValueError("unit gate receipt fields are not exact")
                if (
                    gate["schema_version"] != "plamen.verifier_unit_gate_receipt.v1"
                    or gate["state"] != "CLEAN"
                    or gate["work_unit_id"] != unit.work_unit_id
                    or gate["work_unit_resume_digest"] != unit.resume_digest
                    or gate["roster_digest"] != roster.digest
                    or gate["launch_spec_digest"] != launch.digest
                    or gate["method_dispatch_id"] != dispatch.get("dispatch_id")
                    or gate["ordered_work_item_ids"] != list(unit.ordered_work_item_ids)
                    or gate["method_dispatch_sha256"]
                    != hashlib.sha256(unit_paths["method_dispatch"].read_bytes()).hexdigest()
                ):
                    raise ValueError("unit gate receipt binding mismatch")
                if unit_receipt.gate_receipt_digests != (
                    hashlib.sha256(unit_paths["gate"].read_bytes()).hexdigest(),
                ):
                    raise ValueError("unit gate receipt bytes changed")
                output_receipt_digests = tuple(
                    hashlib.sha256(
                        (root / f"verify_{work_id}.receipt.json").read_bytes()
                    ).hexdigest()
                    for work_id in unit.ordered_work_item_ids
                )
                if unit_receipt.output_receipt_digests != output_receipt_digests:
                    raise ValueError("unit output receipt denominator changed")
                operator_digests: list[str] = []
                unit_sources: list[tuple[str, Path, dict[str, Any]]] = []
                for work_id in unit.ordered_work_item_ids:
                    receipt_path = root / f"verify_{work_id}.operator_receipt.json"
                    receipt = load_bound_operator_receipt(
                        receipt_path=receipt_path,
                        proposal_path=root / f"verify_{work_id}.operator_application.json",
                        verify_path=root / f"verify_{work_id}.md",
                        dispatch=dispatch,
                        launch_digest=launch.digest,
                    )
                    source_sha = hashlib.sha256(receipt_path.read_bytes()).hexdigest()
                    operator_digests.append(source_sha)
                    unit_sources.append((work_id, receipt_path, receipt))
                if gate["operator_receipt_digests"] != operator_digests:
                    raise ValueError("unit gate operator denominator mismatch")
                for work_id, receipt_path, receipt in unit_sources:
                    relative = receipt_path.relative_to(root).as_posix()
                    sources[relative] = {
                        "path": relative,
                        "sha256": hashlib.sha256(receipt_path.read_bytes()).hexdigest(),
                        "work_item_id": work_id,
                        "source_kind": "PRIMARY_VERIFIER_UNIT",
                        "source_identity": unit.work_unit_id,
                        "binding_digest": receipt["receipt_digest"],
                    }
            except Exception as exc:
                debt(
                    "EXPECTED_OPERATOR_RECEIPT_MISSING_OR_UNBOUND",
                    unit.ordered_work_item_ids,
                    f"{type(exc).__name__}: {exc}",
                    unit.work_unit_id,
                )
    except Exception as exc:
        debt(
            "PRIMARY_OPERATOR_DENOMINATOR_UNBOUND",
            (),
            f"{type(exc).__name__}: {exc}",
            _DYNAMIC_VERIFIER_ROSTER_NAME,
        )

    recovery_root = root / "_verification_recovery"
    if recovery_root.is_dir():
        for contract_path in sorted(
            recovery_root.glob("VREC-*/contract.json"),
            key=lambda value: value.as_posix(),
        ):
            contract: dict[str, Any] | None = None
            try:
                contract = validate_verification_recovery_contract(
                    json.loads(
                        contract_path.read_text(encoding="utf-8", errors="strict")
                    ),
                    repo_root=repo_root,
                )
                # Operator-generated work is consumed by explicit later waves,
                # never folded back into immutable wave one.
                if contract["recovery_kind"] in {
                    "POST_VERIFY_SIDE_OBSERVATION", "LATE_OPERATOR_CANDIDATE"
                }:
                    continue
                recovery_ids = [str(row["work_item_id"]) for row in contract["rows"]]
                expected_ids.extend(recovery_ids)
                directory = contract_path.parent
                launch = VerifierLaunchSpec.from_json(
                    (directory / "launch_spec.json").read_text(
                        encoding="utf-8", errors="strict"
                    )
                )
                execution = _load_current_verify_recovery_execution_receipt(
                    directory / "execution_receipt.json",
                    contract=contract,
                    launch_spec=launch,
                    scratchpad=root,
                )
                unresolved = set(execution["unresolved_work_item_ids"])
                for work_id, name in zip(
                    recovery_ids, contract["expected_operator_receipts"]
                ):
                    if work_id in unresolved:
                        debt(
                            "RECOVERY_OPERATOR_RECEIPT_UNRESOLVED",
                            (work_id,),
                            "recovery execution receipt retains this work item as unresolved",
                            contract["recovery_id"],
                        )
                        continue
                    receipt_path = root / str(name)
                    receipt = json.loads(
                        receipt_path.read_text(encoding="utf-8", errors="strict")
                    )
                    relative = receipt_path.relative_to(root).as_posix()
                    sources[relative] = {
                        "path": relative,
                        "sha256": hashlib.sha256(receipt_path.read_bytes()).hexdigest(),
                        "work_item_id": work_id,
                        "source_kind": "RECOVERY_EXECUTION",
                        "source_identity": contract["recovery_id"],
                        "binding_digest": receipt["receipt_digest"],
                    }
            except Exception as exc:
                ids = []
                try:
                    if contract is not None:
                        ids = [
                            str(row["work_item_id"])
                            for row in contract["rows"]
                        ]
                except Exception:
                    pass
                debt(
                    "RECOVERY_EXECUTION_RECEIPT_MISSING_OR_UNBOUND",
                    ids,
                    f"{type(exc).__name__}: {exc}",
                    contract_path.parent.name,
                )

    expected_ids = list(dict.fromkeys(expected_ids))
    source_rows = [sources[key] for key in sorted(sources)]
    debts.sort(key=lambda row: (row["debt_code"], row["source_identity"], row["debt_digest"]))
    status = "COMPLETED_WITH_DEBT" if debts else (
        "CLEAN" if source_rows else "CLEAN_NO_EXPECTED_WORK"
    )
    unsigned: dict[str, Any] = {
        "schema_version": "plamen.verification_operator_denominator.v1",
        "status": status,
        "queue_work_plan_digest": queue_plan_digest,
        "verifier_roster_digest": roster_digest,
        "expected_work_item_ids": expected_ids,
        "source_receipt_count": len(source_rows),
        "source_receipts": source_rows,
        "debt_count": len(debts),
        "debts": debts,
    }
    authority = {
        **unsigned,
        "authority_digest": verification_method_stable_digest(unsigned),
    }
    _atomic_driver_json(
        root / "verification_operator_denominator_authority.json", authority
    )
    if not wave_one_path.is_file() and not debts:
        _atomic_driver_json(wave_one_path, authority)
    return [root / source["path"] for source in source_rows]


def _consume_verifier_operator_receipts(
    config: dict[str, Any],
) -> dict[str, list[str]]:
    """Route verifier observations/debt without modifying primary authority."""

    scratchpad = Path(config["scratchpad"])
    result: dict[str, list[str]] = {
        "promoted": [],
        "verified": [],
        "unresolved": [],
    }
    try:
        receipt_paths = _initial_verifier_operator_receipt_denominator(scratchpad)
    except Exception as exc:
        _append_phase_io_debt(
            scratchpad,
            "post_verify_extract",
            "VERIFIER_OPERATOR_DENOMINATOR_DEBT",
            f"{type(exc).__name__}: {exc}",
        )
        return result
    denominator_path = scratchpad / "verification_operator_denominator_authority.json"
    try:
        denominator = json.loads(
            denominator_path.read_text(encoding="utf-8", errors="strict")
        )
        for debt in denominator.get("debts") or []:
            _append_phase_io_debt(
                scratchpad,
                "post_verify_extract",
                str(debt.get("debt_code") or "VERIFIER_OPERATOR_DENOMINATOR_DEBT"),
                str(debt.get("detail") or "operator denominator debt"),
            )
    except Exception as exc:
        _append_phase_io_debt(
            scratchpad,
            "post_verify_extract",
            "VERIFIER_OPERATOR_DENOMINATOR_AUTHORITY_DEBT",
            f"{type(exc).__name__}: {exc}",
        )
    if not receipt_paths:
        return result

    # Three is a hard recursion bound. Wave 3 is consumed into proposal/debt
    # authority but is deliberately not launched again; residual candidates
    # remain report-visible human-review work instead of creating an unbounded
    # verifier-observation loop.
    for wave in range(1, 4):
        authority_path = scratchpad / (
            "verification_operator_consumer_authority.json"
            if wave == 1
            else f"verification_operator_consumer_authority.wave{wave}.json"
        )
        try:
            authority = build_verifier_operator_consumer_authority(
                run_id=str(config.get("_run_id") or "test-unbound"),
                receipt_paths=receipt_paths,
                scratchpad=scratchpad,
                max_rows_per_shard=_VERIFY_RECOVERY_MAX_ROWS,
            )
            write_or_validate_verifier_operator_consumer_authority(
                authority_path, authority
            )
            authority = validate_verifier_operator_consumer_authority(authority)
        except Exception as exc:
            _append_phase_io_debt(
                scratchpad,
                "post_verify_extract",
                "VERIFIER_OPERATOR_CONSUMER_DEBT",
                f"wave {wave}: {type(exc).__name__}: {exc}",
            )
            return result
        candidate_ids = [
            str(row["candidate_id"]) for row in authority["candidates"]
        ]
        result["promoted"].extend(candidate_ids)
        if not candidate_ids:
            break
        if wave == 3:
            result["unresolved"].extend(candidate_ids)
            _append_phase_io_debt(
                scratchpad,
                "post_verify_extract",
                "VERIFIER_OBSERVATION_RECURSION_BOUND",
                "bounded late-verification reached wave 3; retained proposal-only "
                "human-review candidates: " + ", ".join(candidate_ids),
            )
            break
        unresolved: set[str] = set()
        recovery_config = dict(config)
        recovery_config["_verification_recovery_kind"] = "POST_VERIFY_SIDE_OBSERVATION"
        for shard in authority["late_verification_shards"]:
            shard_rows = [
                (str(row["work_item_id"]), dict(row))
                for row in shard["rows"]
            ]
            unresolved.update(
                _run_verify_recovery_shard(recovery_config, shard_rows)
            )
        result["unresolved"].extend(
            work_id for work_id in candidate_ids if work_id in unresolved
        )
        result["verified"].extend(
            work_id for work_id in candidate_ids if work_id not in unresolved
        )
        receipt_paths = [
            scratchpad / f"verify_{work_id}.operator_receipt.json"
            for work_id in candidate_ids
            if work_id not in unresolved
            and (scratchpad / f"verify_{work_id}.operator_receipt.json").is_file()
        ]
        if not receipt_paths:
            break
    for key in result:
        result[key] = list(dict.fromkeys(result[key]))
    return result


def _verifier_operator_candidate_rows(
    scratchpad: Path,
) -> dict[str, dict[str, Any]]:
    """Reconstruct full late rows only from recomputed operator authorities."""

    root = Path(scratchpad)
    paths = [root / "verification_operator_consumer_authority.json"] + [
        root / f"verification_operator_consumer_authority.wave{wave}.json"
        for wave in range(2, 4)
    ]
    rows: dict[str, dict[str, Any]] = {}
    for path in paths:
        if not path.is_file():
            continue
        authority_raw = path.read_bytes()
        authority = validate_verifier_operator_consumer_authority(
            json.loads(authority_raw.decode("utf-8", errors="strict")),
            scratchpad=root,
        )
        work_by_id = {
            str(work["work_item_id"]): work
            for shard in authority["late_verification_shards"]
            for work in shard["rows"]
        }
        for ordinal, candidate in enumerate(authority["candidates"], start=1):
            candidate_id = str(candidate["candidate_id"])
            work = dict(work_by_id.get(candidate_id) or {})
            rows[candidate_id] = {
                **work,
                "finding id": candidate_id,
                "severity": str(work.get("severity") or "Unknown"),
                "title": candidate["title"],
                "location": candidate["location"],
                "mechanism": candidate["mechanism"],
                "evidence": candidate["evidence"],
                "source_candidate_digest": candidate["candidate_digest"],
                "source_work_item_id": candidate["source_work_item_id"],
                "source_operator_receipt": candidate["source_operator_receipt"],
                "source_operator_receipt_sha256": candidate[
                    "source_operator_receipt_sha256"
                ],
                "source_operator_receipt_digest": candidate[
                    "source_operator_receipt_digest"
                ],
                "source_kind": "VERIFIER_OPERATOR_AUTHORITY",
                "source_authority_artifact": path.name,
                "source_authority_sha256": hashlib.sha256(
                    authority_raw
                ).hexdigest(),
                "source_record_ordinal": ordinal,
                "source_record_digest": candidate["candidate_digest"],
            }
    return rows


def _route_post_verify_late_candidates(config: dict[str, Any]) -> dict[str, list[str]]:
    """Independently verify and retain an immutable late-candidate delta."""
    scratchpad = Path(config["scratchpad"])
    run_id = str(config.get("_run_id") or "test-unbound")

    # The legacy extractor is parsed before receipt consumption.  Its
    # independent verification can itself emit operator observations, which
    # must be included in wave 1 rather than silently deferred to a later run.
    parsed = parse_post_verify_candidate_proposals(scratchpad)
    legacy_rows: list[tuple[str, dict[str, Any]]] = []
    for proposal in parsed["proposals"]:
        work_id = str(proposal["work_item_id"])
        legacy_rows.append((work_id, {
            "finding id": work_id,
            "candidate identity": work_id,
            "severity": proposal["severity"],
            "title": proposal["title"],
            "location": proposal["location"],
            "mechanism": proposal["mechanism"],
            "harm": proposal["harm"],
            "evidence": proposal["evidence"],
            "primary artifact": proposal["primary_artifact"],
            "poc class": "structural",
            "evidence debt": proposal["evidence_debt"],
            "origin assessment": proposal["origin_assessment"],
            "source_record_digest": proposal["source_record_digest"],
        }))

    legacy_unresolved: set[str] = set()
    if legacy_rows:
        try:
            with _phase_heartbeat_thread(
                display,
                "post_verify_extract:independent_verify",
                scratchpad,
            ):
                recovery_config = dict(config)
                recovery_config["_verification_recovery_kind"] = "POST_VERIFY_SIDE_OBSERVATION"
                legacy_unresolved.update(
                    _run_verify_recovery_shard(recovery_config, legacy_rows)
                )
        except Exception as exc:
            legacy_unresolved.update(fid for fid, _row in legacy_rows)
            _append_phase_io_debt(
                scratchpad,
                "post_verify_extract",
                "LATE_CANDIDATE_VERIFICATION_DEBT",
                f"{type(exc).__name__}: {exc}",
            )

    operator_result = _consume_verifier_operator_receipts(config)
    operator_rows = _verifier_operator_candidate_rows(scratchpad)
    delta = write_or_validate_post_verify_candidate_delta(
        scratchpad,
        run_id=run_id,
        operator_proposals=operator_rows.values(),
    )
    delta_rows = {
        str(row["work_item"]["work_item_id"]): row
        for row in delta["rows"]
    }
    delta_ids = list(delta_rows)
    legacy_by_id = {fid: row for fid, row in legacy_rows}
    verified = {
        fid for fid in legacy_by_id if fid not in legacy_unresolved
    }
    verified.update(operator_result["verified"])
    verified.intersection_update(delta_rows)
    unresolved = set(delta_rows) - verified
    unresolved.update(
        fid for fid in operator_result["unresolved"] if fid in delta_rows
    )
    verified.difference_update(unresolved)
    result = {
        "promoted": delta_ids,
        "verified": [fid for fid in delta_ids if fid in verified],
        "unresolved": [fid for fid in delta_ids if fid in unresolved],
    }
    try:
        late_authority = write_or_validate_late_verification_authority(
            scratchpad,
            run_id=run_id,
            repo_root=Path(__file__).resolve().parent.parent,
        )
        authority_verified = {
            str(row["candidate_id"])
            for row in late_authority["rows"]
            if row["delivery_state"]
            == "INDEPENDENT_VERIFICATION_RECORDED"
        }
        result["verified"] = [
            fid for fid in delta_ids if fid in authority_verified
        ]
        result["unresolved"] = [
            fid for fid in delta_ids if fid not in authority_verified
        ]
        for debt in late_authority["debts"]:
            _append_phase_io_debt(
                scratchpad,
                "post_verify_extract",
                str(
                    debt.get("debt_code")
                    or "LATE_VERIFICATION_AUTHORITY_DEBT"
                ),
                str(debt.get("detail") or "late verification authority debt"),
            )
    except Exception as exc:
        # A summary produced by this same routing function cannot substitute
        # for the independently replayed recovery evidence chain.
        result["verified"] = []
        result["unresolved"] = list(delta_ids)
        _append_phase_io_debt(
            scratchpad,
            "post_verify_extract",
            "LATE_VERIFICATION_AUTHORITY_INVALID",
            f"{type(exc).__name__}: {exc}",
        )

    unresolved_rows = [
        (
            fid,
            operator_rows.get(fid)
            or legacy_by_id.get(fid)
            or {
                "finding id": fid,
                "title": fid,
                "severity": "Unknown",
                "mechanism": delta_rows[fid]["claim"]["premise"],
                "harm": delta_rows[fid]["claim"]["harm"],
                "evidence": delta_rows[fid]["claim"]["evidence"],
            },
        )
        for fid in result["unresolved"]
    ]
    fallback_written = set(
        _write_late_unverified_fallback(
            scratchpad,
            unresolved_rows,
            owner_phase="post_verify_extract",
        )
    )
    if unresolved_rows:
        _append_phase_io_debt(
            scratchpad,
            "post_verify_extract",
            "LATE_CANDIDATE_UNVERIFIED",
            "independent recovery did not execute for: "
            + ", ".join(result["unresolved"]),
        )
    missing_fallback = {fid for fid, _row in unresolved_rows} - fallback_written
    if missing_fallback:
        _append_phase_io_debt(
            scratchpad,
            "post_verify_extract",
            "LATE_CANDIDATE_RETENTION_WRITE_DEBT",
            ", ".join(sorted(missing_fallback)),
        )

    # The mechanical executor is the only route to proof-grade evidence. It is
    # safe to rerun over all immutable verifier outputs; successor receipts are
    # append-only and downstream consumers bind them independently.
    if result["verified"]:
        try:
            import importlib

            executor = importlib.import_module("mechanical_verify")
            with _phase_heartbeat_thread(
                display, "post_verify_extract:mechanical_verify", scratchpad
            ):
                executor.run_phase5b_mechanical_verify(
                    scratchpad,
                    Path(config["project_root"]),
                    config.get("language", ""),
                )
        except Exception as exc:
            _append_phase_io_debt(
                scratchpad,
                "post_verify_extract",
                "LATE_CANDIDATE_MECHANICAL_EXECUTION_DEBT",
                f"{type(exc).__name__}: {exc}",
            )

    _generate_verify_core_if_missing(scratchpad)
    delivery_rows = []
    for fid in result["promoted"]:
        verify_path = scratchpad / f"verify_{fid}.md"
        try:
            verify_sha = hashlib.sha256(verify_path.read_bytes()).hexdigest()
        except Exception:
            verify_sha = None
        source = operator_rows.get(fid) or legacy_by_id.get(fid) or {}
        delta_row = delta_rows[fid]
        delivery_rows.append(
            {
                "candidate_id": fid,
                "delivery_state": (
                    "INDEPENDENT_VERIFICATION_RECORDED"
                    if fid in result["verified"]
                    else "UNVERIFIED_HUMAN_REVIEW"
                ),
                "verify_artifact": verify_path.name,
                "verify_sha256": verify_sha,
                "source_candidate_digest": (
                    source.get("source_candidate_digest")
                    or delta_row["source_record_digest"]
                ),
                "source_work_item_id": source.get("source_work_item_id"),
                "source_operator_receipt": source.get("source_operator_receipt"),
                "source_operator_receipt_sha256": source.get(
                    "source_operator_receipt_sha256"
                ),
                "source_operator_receipt_digest": source.get(
                    "source_operator_receipt_digest"
                ),
                "finding_lifecycle_obligation_id": source.get(
                    "finding_lifecycle_obligation_id"
                ),
            }
        )
    payload = {
        "schema_version": "plamen.post_verify_late_delivery.v1",
        "proof_authority": "NONE",
        "row_count": len(delivery_rows),
        "rows": delivery_rows,
    }
    payload["receipt_sha256"] = hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    _atomic_driver_json(
        scratchpad / "post_verify_late_delivery.json",
        payload,
    )
    return result


def _clear_stale_verify_retry_hint_after_reshard(
    scratchpad: Path,
    phase_name: str,
    assigned_rows: list[dict[str, str]],
) -> bool:
    """Drop verify retry hints whose IDs no longer belong to this shard.

    Verify shard manifests are regenerated on resume. After a shard-splitting
    fix, a prior retry hint can point at IDs that moved to a later shard; if
    injected, it steers the subprocess outside its current manifest.
    """
    if not assigned_rows:
        return False
    try:
        hint = _read_retry_hint(scratchpad, phase_name)
    except Exception:
        return False
    if not hint:
        return False

    assigned_ids = {
        str(row.get("finding id") or row.get("Finding ID") or "").strip().upper()
        for row in assigned_rows
    }
    assigned_ids.discard("")
    mentioned_ids = {m.group(0).upper() for m in _VERIFY_HINT_ID_RE.finditer(hint)}
    if mentioned_ids and assigned_ids and not mentioned_ids.issubset(assigned_ids):
        _clear_retry_hint(scratchpad, phase_name)
        log.info(
            f"[{phase_name}] cleared stale retry hint after verify re-shard; "
            f"hint_ids={sorted(mentioned_ids)[:8]} assigned_ids={sorted(assigned_ids)[:8]}"
        )
        return True
    return False


_HEARTBEAT_INTERVAL = 0.1  # seconds between proc.wait polls (governs spinner fps ~10)
_HEARTBEAT_DISPLAY_INTERVAL = 15  # seconds between heartbeat display lines
_ARTIFACT_SCAN_INTERVAL = 3  # seconds between scratchpad scans (avoid thrashing iterdir)
_EARLY_COMPLETE_IDLE_GRACE_SECONDS = int(os.environ.get(
    "PLAMEN_EARLY_COMPLETE_IDLE_SECONDS", "600"
))


_RUNAWAY_TOOL_RESULT_BYTES = 500_000
_TOOL_RESULT_SCAN_INTERVAL_S = 60.0


def _claude_project_dir_name(path) -> str:
    """Encode an absolute cwd the way Claude Code names its
    ``~/.claude/projects/<dir>`` session directory.

    Verified against on-disk dirs: ``D:\\Programming\\...\\repo`` ->
    ``D--Programming-...-repo``. Every non-alphanumeric char maps to a single
    ``-`` WITHOUT collapsing runs (``D:\\`` -> ``D--``).
    """
    return re.sub(r"[^A-Za-z0-9]", "-", os.path.abspath(str(path)))


def _scan_claude_tool_results_for_runaways(
    start_time: float, already_warned: set[str], scratchpad: Path
) -> list[tuple[str, int]]:
    """Detect single tool-result blobs exceeding the runaway threshold.

    A subagent that issues a Bash/Glob/Read against a huge directory (e.g.
    %TEMP%, $HOME, ~/.cache) can dump multi-MB results into the claude session's
    tool-results dir, which blocks the coordinator and produces no audit value.

    SCOPED to THE CURRENT RUN only. Claude keys its project dir by the
    coordinator's cwd, which is this run's PROJECT_ROOT == ``scratchpad.parent``.
    Earlier this scanned EVERY dir under ``~/.claude/projects/`` filtered only by
    mtime, so a *concurrent* audit (or a Codex run, which writes its sessions
    elsewhere entirely) would surface another run's huge tool-result and
    misattribute it to THIS phase ("a subagent likely read outside
    PROJECT_ROOT -- coordinator may stall"). Scoping to the current run's own
    project dir kills that cross-run false positive: on a Codex run the current
    run's Claude project dir has no fresh blobs (Codex doesn't write there), and
    a sibling Claude run's blobs live under a DIFFERENT encoded dir that is no
    longer scanned. If the current run's project dir can't be located, there are
    no current-run tool-results to police -- scanning others is pure
    false-positive risk with zero benefit, so return nothing.

    Returns list of (path, size) for newly-detected runaways. Mutates
    already_warned so each path is reported once.
    """
    try:
        projects = Path.home() / ".claude" / "projects"
        if not projects.is_dir():
            return []
    except Exception:
        return []
    try:
        target_norm = _claude_project_dir_name(Path(scratchpad).parent).casefold()
    except Exception:
        return []
    out: list[tuple[str, int]] = []
    try:
        for proj_dir in projects.iterdir():
            if not proj_dir.is_dir():
                continue
            # Only THIS run's project dir (cwd-keyed). casefold tolerates
            # drive-letter case differences on Windows.
            if proj_dir.name.casefold() != target_norm:
                continue
            for sess in proj_dir.iterdir():
                if not sess.is_dir():
                    continue
                tr = sess / "tool-results"
                if not tr.is_dir():
                    continue
                try:
                    for f in tr.iterdir():
                        if not f.is_file():
                            continue
                        try:
                            st = f.stat()
                            if st.st_mtime < start_time:
                                continue
                            if st.st_size < _RUNAWAY_TOOL_RESULT_BYTES:
                                continue
                        except OSError:
                            continue
                        key = str(f)
                        if key in already_warned:
                            continue
                        already_warned.add(key)
                        out.append((key, st.st_size))
                except OSError:
                    continue
    except OSError:
        pass
    return out


def _breadth_manifest_complete_reason(scratchpad: Path, phase: Phase) -> Optional[str]:
    """Return a reason when every manifest-declared breadth output is substantial."""
    outputs = parse_breadth_manifest_outputs(scratchpad) or []
    if not outputs:
        return None
    missing: list[str] = []
    for name in outputs:
        path = scratchpad / name
        if not path.exists():
            missing.append(name)
            continue
        try:
            if path.stat().st_size < phase.min_artifact_bytes:
                missing.append(f"{name} (stub)")
        except OSError:
            missing.append(name)
    if missing:
        return None
    return (
        f"all {len(outputs)} manifest breadth outputs are present and "
        f">= {phase.min_artifact_bytes} bytes"
    )


def _run_early_complete_check(checker: Callable[[], Optional[str]]) -> Optional[str]:
    return checker.__call__()


def _scratchpad_activity_signature(scratchpad: Path) -> tuple[tuple[str, int, int], ...]:
    entries: list[tuple[str, int, int]] = []
    try:
        for p in scratchpad.rglob("*"):
            try:
                if not p.is_file():
                    continue
                rel = p.relative_to(scratchpad).as_posix()
                if rel.startswith("_"):
                    continue
                st = p.stat()
                entries.append((rel, st.st_size, st.st_mtime_ns))
            except OSError:
                continue
    except OSError:
        pass
    return tuple(sorted(entries))


def _wait_with_heartbeat(
    proc: subprocess.Popen,
    timeout: float,
    scratchpad: Path,
    phase_name: str,
    start_time: float,
    protected_patterns: tuple[str, ...] = (),
    early_complete: Optional[Callable[[], Optional[str]]] = None,
) -> int:
    """Poll proc every _HEARTBEAT_INTERVAL (3s), printing artifact progress.

    Short poll interval ensures halt responds within ~3 seconds.
    Display output is throttled to _HEARTBEAT_DISPLAY_INTERVAL (15s).

    Returns:
      >=0  normal subprocess exit code
      -2   timeout (caller should also check subprocess.TimeoutExpired)
      -3   user pressed Esc (halt) — subprocess terminated, driver stays alive

    Raises subprocess.TimeoutExpired if the process exceeds *timeout*.
    """
    deadline = start_time + timeout
    known_artifacts: set[str] = set()
    known_artifact_stats: dict[str, tuple[int, int]] = {}
    try:
        for p in scratchpad.iterdir():
            if not p.name.startswith("_"):
                known_artifacts.add(p.name)
                try:
                    st = p.stat()
                    known_artifact_stats[p.name] = (st.st_size, st.st_mtime_ns)
                except OSError:
                    pass
        scip_dir = scratchpad / "scip"
        if scip_dir.is_dir():
            for p in scip_dir.iterdir():
                known_artifacts.add(f"scip/{p.name}")
    except Exception:
        pass

    tool_calls_file = scratchpad / "tool_calls.jsonl"
    last_tc_size = tool_calls_file.stat().st_size if tool_calls_file.exists() else 0
    last_activity_tc_size = last_tc_size
    last_activity_signature = _scratchpad_activity_signature(scratchpad)
    last_display_time = time.time()
    last_scan_time = time.time()
    last_tool_result_scan_time = time.time()
    tool_result_warned: set[str] = set()
    early_complete_since: Optional[float] = None
    early_complete_last_activity: Optional[float] = None
    early_complete_reason: Optional[str] = None
    _ALIVE_INTERVAL = 300

    # Accumulate new artifacts between display ticks
    pending_artifacts: list[str] = []

    while True:
        try:
            rc = proc.wait(timeout=_HEARTBEAT_INTERVAL)
            # Process exited — flush any pending artifacts
            display._clear_spinner()
            if pending_artifacts:
                elapsed = int(time.time() - start_time)
                display.print_phase_heartbeat(phase_name, elapsed, new_artifacts=pending_artifacts)
            return rc
        except subprocess.TimeoutExpired:
            pass
        except KeyboardInterrupt:
            display._clear_spinner()
            _terminate_process_tree(proc, grace_s=10)
            raise

        # Esc halt: terminate subprocess, return -3 so driver can offer resume
        if display.graceful_stop.requested:
            display._clear_spinner()
            _terminate_process_tree(proc, grace_s=_HALT_TERMINATE_GRACE_S)
            return -3

        now = time.time()

        if now > deadline:
            display._clear_spinner()
            raise subprocess.TimeoutExpired(proc.args, timeout)

        elapsed = int(now - start_time)

        # Spin the inline indicator every poll (~4fps)
        display.spin(elapsed)

        # Scan for new artifacts at a slower cadence (every 3s)
        if now - last_scan_time >= _ARTIFACT_SCAN_INTERVAL:
            last_scan_time = now
            observed_activity = False
            try:
                for p in scratchpad.iterdir():
                    if not p.name.startswith("_") and p.name in known_artifacts:
                        try:
                            st = p.stat()
                            sig = (st.st_size, st.st_mtime_ns)
                        except OSError:
                            sig = (0, 0)
                        if known_artifact_stats.get(p.name) != sig:
                            known_artifact_stats[p.name] = sig
                            if protected_patterns and _matches_any_pattern(
                                p.name, list(protected_patterns)
                            ):
                                display._clear_spinner()
                                log.error(
                                    f"[{phase_name}] live containment abort: "
                                    f"protected downstream artifact changed: {p.name}"
                                )
                                _terminate_process_tree(proc, grace_s=_HALT_TERMINATE_GRACE_S)
                                return -4
                        continue
                    if not p.name.startswith("_") and p.name not in known_artifacts:
                        pending_artifacts.append(p.name)
                        known_artifacts.add(p.name)
                        try:
                            st = p.stat()
                            known_artifact_stats[p.name] = (st.st_size, st.st_mtime_ns)
                        except OSError:
                            known_artifact_stats[p.name] = (0, 0)
                        if protected_patterns and _matches_any_pattern(
                            p.name, list(protected_patterns)
                        ):
                            # F7: depth's chain/synthesis writes are benign
                            # post-completion overruns — quarantine post-run
                            # rather than killing the subprocess mid-run.
                            if (
                                phase_name == "depth"
                                and _is_benign_depth_foreign_artifact(p.name)
                            ):
                                log.warning(
                                    f"[{phase_name}] foreign-artifact leak "
                                    f"(benign, will quarantine post-run): "
                                    f"{p.name}"
                                )
                            else:
                                display._clear_spinner()
                                log.error(
                                    f"[{phase_name}] live containment abort: "
                                    f"protected downstream artifact appeared: {p.name}"
                                )
                                _terminate_process_tree(proc, grace_s=_HALT_TERMINATE_GRACE_S)
                                return -4
                scip_dir = scratchpad / "scip"
                if scip_dir.is_dir():
                    for p in scip_dir.iterdir():
                        key = f"scip/{p.name}"
                        if key not in known_artifacts:
                            pending_artifacts.append(key)
                            known_artifacts.add(key)
            except Exception:
                pass

            cur_activity_signature = _scratchpad_activity_signature(scratchpad)
            cur_activity_tc_size = (
                tool_calls_file.stat().st_size if tool_calls_file.exists() else 0
            )
            if (
                cur_activity_signature != last_activity_signature
                or cur_activity_tc_size > last_activity_tc_size
            ):
                observed_activity = True
                last_activity_signature = cur_activity_signature
                last_activity_tc_size = cur_activity_tc_size

            # Runaway tool-result watchdog: a subagent that lists a huge
            # out-of-scope directory (e.g. system temp, home dir) can dump
            # multi-MB results that block the coordinator and produce no
            # audit value. Warn so the operator can halt early.
            if now - last_tool_result_scan_time >= _TOOL_RESULT_SCAN_INTERVAL_S:
                last_tool_result_scan_time = now
                for path, size in _scan_claude_tool_results_for_runaways(
                    start_time, tool_result_warned, scratchpad
                ):
                    log.warning(
                        f"[{phase_name}] runaway tool result detected: "
                        f"{size / 1024:.0f} KB at {path} -- a subagent likely "
                        f"read outside PROJECT_ROOT/SCRATCHPAD. Coordinator "
                        f"may stall waiting for that subagent."
                    )

            if early_complete:
                try:
                    reason = _run_early_complete_check(early_complete)
                except Exception as exc:
                    log.debug(f"[{phase_name}] early completion check skipped: {exc}")
                    reason = None
                if reason:
                    if early_complete_since is None:
                        early_complete_since = now
                        early_complete_last_activity = now
                        early_complete_reason = reason
                        log.info(
                            f"[{phase_name}] manifest complete: {reason}; "
                            "waiting for subprocess to go idle before cutover"
                        )
                    elif observed_activity:
                        early_complete_last_activity = now
                    idle_for = now - (early_complete_last_activity or now)
                    if idle_for >= _EARLY_COMPLETE_IDLE_GRACE_SECONDS:
                        display._clear_spinner()
                        log.info(
                            f"[{phase_name}] early completion after idle grace: "
                            f"{early_complete_reason or reason}; no scratchpad/tool "
                            f"activity for {int(idle_for)}s"
                        )
                        _terminate_process_tree(proc, grace_s=_HALT_TERMINATE_GRACE_S)
                        return 0
                else:
                    early_complete_since = None
                    early_complete_last_activity = None
                    early_complete_reason = None

        since_display = now - last_display_time

        # Show new artifacts immediately (spinner line → artifact line)
        if pending_artifacts and since_display >= _ARTIFACT_SCAN_INTERVAL:
            names = ", ".join(pending_artifacts[:4])
            extra = f" +{len(pending_artifacts) - 4} more" if len(pending_artifacts) > 4 else ""
            display.print_phase_heartbeat(phase_name, elapsed, new_artifacts=pending_artifacts)
            mins, secs = divmod(elapsed, 60)
            log.info(f"[{phase_name}] {mins}:{secs:02d} | +{names}{extra}")
            pending_artifacts = []
            last_display_time = now
        elif not pending_artifacts and since_display >= _ALIVE_INTERVAL:
            mins, secs = divmod(elapsed, 60)
            cur_tc_size = tool_calls_file.stat().st_size if tool_calls_file.exists() else 0
            if cur_tc_size > last_tc_size:
                delta_kb = (cur_tc_size - last_tc_size) / 1024
                display.print_phase_heartbeat(phase_name, elapsed, tool_calls_delta_kb=delta_kb)
                log.info(f"[{phase_name}] {mins}:{secs:02d} | working (+{delta_kb:.0f}KB tool calls)")
                last_tc_size = cur_tc_size
            else:
                display.print_phase_heartbeat(phase_name, elapsed)
                log.info(f"[{phase_name}] {mins}:{secs:02d} | waiting")
            last_display_time = now


class _PhaseHeartbeatThread:
    """Context manager that pulses a live terminal heartbeat while a long
    *synchronous, in-process* step runs — e.g. the recon mechanical prepass
    (Slither/graph bake, build/dep-install) which can block 1-3+ minutes with
    zero output and look like a dead launch (the chronic 0-byte-stdio class).

    It reuses ``display.print_phase_heartbeat`` so the pulse line matches the
    worker-phase loops, and mirrors their new-artifact computation (set diff of
    files in ``scratchpad`` since start).

    A daemon thread does the pulsing; ``__exit__`` always sets the stop Event
    and joins with a small timeout in a ``finally``-equivalent path, so the
    thread can never leak. Degrades to a complete no-op when ``display`` is
    None / lacks ``print_phase_heartbeat`` — it never raises into the caller.
    """

    def __init__(self, display_mod, phase_name, scratchpad, interval=12):
        self._display = display_mod
        self._phase_name = phase_name
        try:
            self._scratch = Path(scratchpad) if scratchpad else None
        except Exception:
            self._scratch = None
        try:
            self._interval = max(1, int(interval or 12))
        except Exception:
            self._interval = 12
        self._stop = threading.Event()
        self._thread = None
        self._start_mono = None
        self._baseline: set[str] = set()
        # Only pulse when there is a usable display sink. The module-level
        # display already degrades to stderr when Rich is unavailable, but a
        # caller may pass None (non-interactive / no display) — then no-op.
        self._enabled = bool(
            self._display is not None
            and hasattr(self._display, "print_phase_heartbeat")
        )

    def _snapshot(self) -> set[str]:
        if self._scratch is None:
            return set()
        try:
            return {p.name for p in self._scratch.iterdir() if p.is_file()}
        except Exception:
            return set()

    def _run(self):
        # wait() returns True only when the stop Event is set; on timeout it
        # returns False. So this pulses every `interval` seconds (NOT at t=0 —
        # the up-front status line covers the immediate notice) until stopped.
        while not self._stop.wait(self._interval):
            try:
                elapsed = int(time.monotonic() - (self._start_mono or time.monotonic()))
                new = sorted(self._snapshot() - self._baseline)
                if new:
                    self._display.print_phase_heartbeat(
                        self._phase_name, elapsed, new_artifacts=new)
                else:
                    self._display.print_phase_heartbeat(self._phase_name, elapsed)
            except Exception:
                # The heartbeat is pure UX; never let it crash the run.
                pass

    def __enter__(self):
        if not self._enabled:
            return self
        try:
            self._start_mono = time.monotonic()
            self._baseline = self._snapshot()
            self._thread = threading.Thread(
                target=self._run,
                name=f"heartbeat-{self._phase_name}",
                daemon=True,
            )
            self._thread.start()
        except Exception:
            self._thread = None
        return self

    def __exit__(self, exc_type, exc, tb):
        try:
            self._stop.set()
            t = self._thread
            if t is not None and t.is_alive():
                t.join(timeout=2.0)
        except Exception:
            pass
        # Never suppress an exception raised inside the wrapped step.
        return False


def _phase_heartbeat_thread(display_mod, phase_name, scratchpad, interval=12):
    """Return a context manager that pulses a live heartbeat around a long
    synchronous in-process step. See :class:`_PhaseHeartbeatThread`."""
    return _PhaseHeartbeatThread(display_mod, phase_name, scratchpad, interval)


# ===========================================================================
# Artifact-gated PTY supervision (Ship 6 of the supervision plan)
# ===========================================================================

# Row-aware phases. These have structured per-output status helpers, so
# missing-only repair can name exactly which spawned worker rows are incomplete.
# Other Claude PTY phases still participate in the disposable gate-repair loop
# when run_phase() sees concrete expected_artifacts / any_of / dynamic verify
# gates; they use the generic gate_missing repair prompt instead of row status.
#
# Adding a phase here REQUIRES a structured per-row status helper in
# `compute_phase_row_statuses` AND a prompt that emits PLAMEN markers.
PTY_SUPERVISED_PHASES: frozenset[str] = frozenset({"breadth", "depth"})


def _model_owned_supervision_phase(phase: Phase) -> Phase:
    """Return the disk contract a live model worker is allowed to satisfy.

    Most phases let the model write the phase's canonical artifacts directly,
    so their model-worker and outer phase gates are identical. Instantiate is
    deliberately different: the model owns ``spawn_manifest_proposal.md`` and
    the deterministic driver publishes ``spawn_manifest.md`` only after the
    PTY returns and the typed reconciliation transaction succeeds.

    The PTY supervisor must therefore wait for (and repair) the proposal. If
    it waits for the canonical artifact, its missing-only prompt contradicts
    the model prompt and can strand an interactive Claude session at a safety
    question while the driver waits for that session to finish.
    """

    if phase.name != "instantiate":
        return phase
    return replace(
        phase,
        expected_artifacts=["spawn_manifest_proposal.md"],
        any_of=[],
        min_artifacts_count=1,
    )


def _pty_supervision_cache_dir() -> Path:
    """Cache directory for the empirical preflight (Ship 4).

    Lives under ``plamen_home()/cache`` so it survives across audits
    on the same machine without polluting per-project scratchpads.
    """
    return plamen_home() / "cache"


def _row_id_from_artifact_name(name: str) -> str:
    """Derive a human/agent row id from a spawned-worker artifact
    filename. Strips the family prefix (``analysis_`` for breadth,
    ``depth_`` for depth) and the suffix (``_findings.md`` or ``.md``).

      analysis_access_control.md   -> access_control
      depth_token_flow_findings.md -> token_flow

    Used only as a fallback when no transcript-derived AGENT_ROW handle
    is available for the row.
    """
    base = name
    for suffix in ("_findings.md", ".md"):
        if base.endswith(suffix):
            base = base[: -len(suffix)]
            break
    for prefix in ("analysis_", "depth_"):
        if base.startswith(prefix):
            base = base[len(prefix):]
            break
    return base


def _build_continuation_message(
    *,
    phase_name: str,
    row_statuses: list[dict[str, Any]],
    handles_by_row: dict[str, dict[str, str]],
    agentid_resume_supported: bool,
    gate_missing: list[str] | None = None,
) -> str:
    """Build the user-message text that the supervision loop sends to
    the coordinator after a failed in-session gate check.

    The message lists ONLY rows whose status is NOT ``complete`` --
    rows that already passed structural completeness are never re-run.
    Each row carries its current status, expected output filename,
    and (if ``agentid_resume_supported`` and a handle is known) the
    ``agentId`` for SendMessage-style resume; otherwise the handle
    column is dropped and the coordinator is told to respawn.

    ``row_statuses`` is the output of
    ``compute_phase_row_statuses(scratchpad, phase)``. ``handles_by_row`` is
    the output of ``parse_transcript_agentids(transcript_path)``.

    ``gate_missing`` is included as a footer for forensics when the structured
    row list is empty. Production recovery no longer sends this message into a
    live PTY, but tests keep it as the row-scoping contract.
    """
    incomplete: list[dict[str, Any]] = [
        r for r in (row_statuses or [])
        if r.get("status") and r["status"] != "complete"
    ]

    lines: list[str] = []
    lines.append(
        f"The driver's artifact-complete gate did not pass for phase "
        f"`{phase_name}`."
    )
    lines.append("")

    if incomplete:
        if agentid_resume_supported:
            lines.append(
                "Incomplete manifest artifacts (act ONLY on these; do NOT "
                "re-spawn rows whose file already contains "
                "`<!-- PLAMEN_STATUS: COMPLETE -->`):"
            )
            lines.append("")
            lines.append("| Row | Expected Output | Status | Handle (if known) |")
            lines.append("| --- | --- | --- | --- |")
            for r in incomplete:
                name = r["name"]
                # Derive a row id from the filename: analysis_<focus>.md -> focus
                # (matches the AGENT_ROW marker in the dispatch prompt). Falls
                # back to filename when handle lookup is unavailable.
                handle_entry = None
                for h in handles_by_row.values():
                    if h.get("expected_output") == name:
                        handle_entry = h
                        break
                row_id = (
                    handle_entry.get("agent_id")
                    if handle_entry
                    else _row_id_from_artifact_name(name)
                )
                handle = handle_entry.get("handle") if handle_entry else ""
                handle_cell = handle if handle else "(no handle; respawn required)"
                lines.append(
                    f"| {row_id} | {name} | {r['status'].upper()} | {handle_cell} |"
                )
            lines.append("")
            lines.append(
                "For each row above:\n"
                "1. If the row has a non-empty Handle AND status is "
                "IN_PROGRESS, attempt `SendMessage` to that handle asking "
                "it to finish writing the assigned file and emit "
                "`<!-- PLAMEN_STATUS: COMPLETE -->` at the end.\n"
                "2. If SendMessage is unsupported or fails, OR status is "
                "MISSING / STUB / STRUCTURAL_FAIL / LEGACY_UNMARKED, "
                "re-spawn ONLY that row using the §Subagent Prompt "
                "Template. Re-spawned subagents MUST include "
                "`AGENT_ROW: <row>` and `EXPECTED_OUTPUT: <filename>` "
                "lines in their dispatch prompt (per template).\n"
                "3. Do NOT re-run rows whose file already contains "
                "`<!-- PLAMEN_STATUS: COMPLETE -->`."
            )
        else:
            lines.append(
                "Incomplete manifest artifacts (act ONLY on these; do NOT "
                "re-spawn rows whose file already contains "
                "`<!-- PLAMEN_STATUS: COMPLETE -->`):"
            )
            lines.append("")
            lines.append("| Row | Expected Output | Status |")
            lines.append("| --- | --- | --- |")
            for r in incomplete:
                name = r["name"]
                row_id = _row_id_from_artifact_name(name)
                # Prefer the transcript-derived agent_id when available.
                for h in handles_by_row.values():
                    if h.get("expected_output") == name:
                        row_id = h.get("agent_id") or row_id
                        break
                lines.append(
                    f"| {row_id} | {name} | {r['status'].upper()} |"
                )
            lines.append("")
            lines.append(
                "Re-spawn ONLY the rows above using the §Subagent Prompt "
                "Template. Respawn is the only available continuation "
                "path on this Claude Code version (the driver's preflight "
                "disabled handle-based resume). Re-spawned subagents "
                "MUST include `AGENT_ROW: <row>` and "
                "`EXPECTED_OUTPUT: <filename>` lines in their dispatch "
                "prompt. Do NOT re-run rows whose file already contains "
                "`<!-- PLAMEN_STATUS: COMPLETE -->`."
            )
    else:
        # No structured detail available (e.g. supervision wired into a
        # phase whose row-status helper isn't shipped yet). Fall back to
        # the gate's aggregated failure detail.
        lines.append(
            "Structured per-row status is not available for this phase. "
            "Gate detail:"
        )
        lines.append("")
        for item in (gate_missing or []):
            lines.append(f"- {item}")
        lines.append("")
        lines.append(
            "Re-run the phase's completion loop until every expected "
            "artifact contains `<!-- PLAMEN_STATUS: COMPLETE -->`."
        )

    lines.append("")
    lines.append(
        "Return `DONE` only when every listed artifact contains "
        "`<!-- PLAMEN_STATUS: COMPLETE -->`."
    )
    return "\n".join(lines)


def _argv_bootstrap_instruction(snap_path: Any) -> str:
    """Single source of truth for the positional bootstrap instruction baked
    into a PTY argv when ``PLAMEN_BOOTSTRAP_IN_ARGV=1``. Production (run_phase)
    and the Ship 8.16 respawn rewrite MUST emit byte-identical text so the
    model treats a continuation respawn exactly like a first launch -- the only
    difference being WHICH prompt file it is told to execute.
    """
    return (
        "Read and fully execute every instruction in "
        f"{Path(snap_path).as_posix()}. When done, output your one-line "
        "DONE summary."
    )


def _rewrite_argv_positional_prompt(
    argv: list[str], snapshot: Path
) -> list[str]:
    """Ship 8.16: point a respawn's argv at the continuation/missing-only
    SNAPSHOT instead of the original phase prompt.

    When the prompt is delivered via argv (``PLAMEN_BOOTSTRAP_IN_ARGV=1``, the
    default PTY transport), the positional prompt is the final argv element, and
    ``send_bootstrap`` is a no-op. Both
    ``_respawn_via_resume`` and ``_respawn_missing_only`` previously preserved
    that ORIGINAL positional verbatim, so the model re-ran the full phase
    prompt instead of the compact continuation (codex #1 / T1+T1b -- the Ship
    8.11/8.12 synthetic proof never asserted argv delivery).

    Returns a NEW argv with the positional rewritten to execute ``snapshot``.
    If the argv carries no positional prompt (headless mode),
    it is returned unchanged -- there ``send_bootstrap`` delivers the snapshot
    via ``prompt_path`` and no argv rewrite is needed.
    """
    out = list(argv)
    if out and str(out[-1]).startswith(
        "Read and fully execute every instruction in "
    ):
        out[-1] = _argv_bootstrap_instruction(snapshot)
        return out
    for i in range(len(out) - 1, -1, -1):
        if out[i] == "--":
            if i + 1 < len(out):
                out[i + 1] = _argv_bootstrap_instruction(snapshot)
            return out
    return out


def _build_resume_cmd_and_snapshot(
    *,
    session_id: str,
    continuation: str,
    base_cmd: list[str],
    prompt_path: Path,
    now_ts: int | None = None,
) -> tuple[list[str], Path]:
    """Construct the argv and continuation-snapshot path for a
    ``claude --resume <session_id>`` respawn.

    Pure helper: no spawn, no PTY, no subprocess. Returns
    ``(resume_cmd, continuation_snapshot_path)``. The continuation
    message is written to a sibling of ``prompt_path`` named
    ``<original-stem>.continuation.<unix_ts>.md`` so each respawn gets
    its own forensic record.

    The resume command strips any ``--session-id <uuid>`` pair from
    ``base_cmd`` (``--session-id`` and ``--resume`` are mutually
    exclusive in the Claude Code CLI) and inserts
    ``--resume <session_id>`` immediately after the program name.
    Other flags are preserved verbatim and in order.

    Ship 6 of the artifact-complete PTY supervision plan.
    """
    resume_cmd: list[str] = []
    skip_next = False
    for tok in base_cmd:
        if skip_next:
            skip_next = False
            continue
        if tok == "--session-id":
            skip_next = True
            continue
        resume_cmd.append(tok)
    if not resume_cmd:
        # Defensive: an empty base_cmd shouldn't happen; the caller
        # builds it from CLAUDE_BIN + flags. If it does, propagate
        # the failure rather than producing a bogus claude command.
        raise ValueError(
            "_build_resume_cmd_and_snapshot: base_cmd is empty after "
            "stripping --session-id"
        )
    # Insert --resume right after the program name (consistent CLI ordering).
    resume_cmd = [resume_cmd[0], "--resume", session_id] + resume_cmd[1:]

    ts = now_ts if now_ts is not None else int(time.time())
    snapshot = prompt_path.with_name(
        f"{prompt_path.stem}.continuation.{ts}{prompt_path.suffix}"
    )
    snapshot.write_text(continuation, encoding="utf-8")

    return resume_cmd, snapshot


def _respawn_via_resume(
    *,
    session_id: str,
    continuation: str,
    base_cmd: list[str],
    cwd: str,
    env: dict[str, str],
    log_file: Any,
    prompt_path: Path,
    provider_dispatch_authority: Callable[[], None] | None = None,
) -> ClaudePtySession:
    """Spawn a NEW ``ClaudePtySession`` resuming the same Claude
    session by ID. Writes the continuation message to a fresh
    snapshot file used as the new session's bootstrap prompt.

    Returns the new (spawned + bootstrapped) session. The caller is
    responsible for terminating this session in its existing
    ``finally`` block. The supervision loop replaces its in-scope
    ``session`` variable with this return value before continuing the
    loop, so the outer terminator targets the live session.
    """
    resume_cmd, snapshot = _build_resume_cmd_and_snapshot(
        session_id=session_id,
        continuation=continuation,
        base_cmd=base_cmd,
        prompt_path=prompt_path,
    )
    # Ship 8.16: point the argv positional prompt at the continuation snapshot.
    # Without this, PLAMEN_BOOTSTRAP_IN_ARGV makes the resumed session re-run
    # the ORIGINAL phase prompt (send_bootstrap is suppressed in argv mode).
    resume_cmd = _rewrite_argv_positional_prompt(resume_cmd, snapshot)
    new_session = ClaudePtySession(
        resume_cmd,
        cwd=cwd,
        env=env,
        session_id=session_id,
        prompt_path=snapshot,
        log_file=log_file,
    )
    if provider_dispatch_authority is not None:
        provider_dispatch_authority()
    new_session.spawn()
    new_session.send_bootstrap()
    return new_session


# ---------------------------------------------------------------------------
# Ship 8.11/8.12: missing-only continuation subprocess
# ---------------------------------------------------------------------------


def _build_fresh_session_cmd(
    base_cmd: list[str], new_session_id: str
) -> list[str]:
    """Minimal shared PTY-argv builder (Correction 1): return ``base_cmd``
    with the ``--session-id`` value replaced by ``new_session_id``.

    ``base_cmd`` is the production interactive-PTY command the driver built
    in ``run_phase`` -- it already carries the exact production flags
    (model, both ``--add-dir``, and the isolation set
    ``--disallowedTools mcp__* --settings <iso> --strict-mcp-config
    --mcp-config <iso>``). Transforming it (rather than reconstructing)
    GUARANTEES the missing-only subprocess uses an identical command shape
    with ZERO drift. Ship 8.10 will extract a from-scratch constructor for
    the preflight (which has no base_cmd to transform) and may converge
    both onto one builder then.
    """
    out = list(base_cmd)
    for i, tok in enumerate(out):
        if tok == "--session-id" and i + 1 < len(out):
            out[i + 1] = new_session_id
            return out
    # Defensive: a PTY base_cmd should always carry --session-id. If it
    # somehow does not, insert one right after the program name.
    if out:
        return [out[0], "--session-id", new_session_id] + out[1:]
    return ["--session-id", new_session_id]


def _build_missing_only_prompt(
    phase: Phase,
    scratchpad: Path,
    row_statuses: list[dict[str, Any]],
    prompt_path: Path,
    gate_missing: list[Any] | None = None,
    now_ts: int | None = None,
) -> Path:
    """Write a COMPACT missing-only continuation bootstrap prompt to a
    snapshot sibling of ``prompt_path``; return its path.

    Correction 2: the prompt carries FULL row metadata pointers so the
    missing-only subprocess reconstructs the same-quality agent prompts --
    not shallow generic files. It points to ``spawn_manifest.md``, lists
    the incomplete expected outputs, names the Subagent Prompt Template
    file (read on demand via ``--add-dir plamen_home`` -- NOT inlined, so
    the base prompt stays ~1-2 KB and compaction-resistant), names the
    per-row opengrep shard path convention, and forbids touching COMPLETE
    files. Completion is disk-derived (Ship 8.8 rule).
    """
    incomplete = [
        r for r in (row_statuses or [])
        if r.get("status") and r["status"] != "complete"
    ]
    template = (
        plamen_home() / "prompts" / "shared" / "v2"
        / ("phase4b-depth.md" if phase.name == "depth" else "phase3-breadth.md")
    )
    lines: list[str] = []
    lines.append(f"# MISSING-ONLY CONTINUATION (phase: {phase.name})")
    lines.append("")

    if phase.name not in {"breadth", "depth"}:
        if phase.name in L1_VERIFY_PHASE_NAMES or phase.name in SC_VERIFY_PHASE_NAMES:
            lines.append(
                "A prior verifier shard turn ended with the Python driver's "
                "disk gate still failing. Your ONLY job this turn is to "
                "write the missing verifier files listed below. Do not "
                "rewrite verifier files that already exist and are not "
                "listed here."
            )
            lines.append("")
            lines.append("## Missing Verifier Rows")
            lines.append("")
            lines.append("| Finding ID | Expected Output | Severity | Title |")
            lines.append("| --- | --- | --- | --- |")
            missing_rows = [
                r for r in incomplete
                if str(r.get("status") or "") != "complete"
            ]
            for r in missing_rows:
                row = r.get("row") if isinstance(r.get("row"), dict) else {}
                fid = str(r.get("finding_id") or row.get("finding id") or "").strip()
                severity = str(row.get("severity") or "").replace("|", "/")
                title = str(row.get("title") or "").replace("|", "/")
                lines.append(
                    f"| {fid or '(unknown)'} | {r.get('name')} | "
                    f"{severity or '-'} | {title or '-'} |"
                )
            lines.append("")
            if gate_missing:
                lines.append("## Gate Failure Detail")
                lines.append("")
                for item in gate_missing:
                    lines.append(f"- {item}")
                lines.append("")
            lines.append("## Verification Method")
            lines.append("")
            lines.append(
                f"1. Read the original verifier shard prompt snapshot at "
                f"`{prompt_path.as_posix()}` for the exact verification "
                "methodology, verdict schema, evidence tags, and shard "
                "manifest path."
            )
            lines.append(
                "2. Verify ONLY the Missing Verifier Rows above. Preserve "
                "every existing `verify_*.md` file that is not listed above."
            )
            lines.append(
                "3. For each missing row, write exactly the expected output "
                "`verify_<finding_id>.md` with the canonical verifier fields: "
                "Finding ID, Severity, Verdict, Evidence Tag, Preferred Tag, "
                "and concise evidence/reasoning."
            )
            lines.append(
                "4. Do not advance to later pipeline phases and do not create "
                "report, aggregate, skeptic, or crossbatch artifacts."
            )
            lines.append("")
            lines.append("## Completion")
            lines.append("")
            lines.append(
                "Before emitting DONE, verify on disk that every expected "
                "output in the table exists and is substantive. Then emit: "
                f"`DONE: {phase.name} missing verifier rows complete`."
            )
            lines.append("")
            ts = now_ts if now_ts is not None else int(time.time())
            snapshot = prompt_path.with_name(
                f"{prompt_path.stem}.missing_only.{ts}{prompt_path.suffix}"
            )
            snapshot.write_text("\n".join(lines) + "\n", encoding="utf-8")
            return snapshot

        lines.append(
            "A prior coordinator turn for this phase ended with the Python "
            "driver's disk gate still failing. Your ONLY job this turn is to "
            "repair the listed gate failures for this same phase. Do not "
            "create any artifact outside the listed expected outputs."
        )
        lines.append("")
        lines.append("## Gate failure detail")
        lines.append("")
        detail = [str(x) for x in (gate_missing or [])]
        if detail:
            for item in detail:
                lines.append(f"- {item}")
        else:
            lines.append("- gate failed without structured detail; inspect expected outputs")
        lines.append("")
        lines.append("## Expected artifact contract")
        lines.append("")
        expected = list(getattr(phase, "expected_artifacts", None) or [])
        if expected:
            for item in expected:
                lines.append(f"- `{item}`")
        else:
            lines.append(
                "- dynamic expected artifacts; inspect the original phase "
                "prompt and relevant manifests"
            )
        any_of = list(getattr(phase, "any_of", None) or [])
        if any_of:
            lines.append("")
            lines.append("Any-of alternatives:")
            for item in any_of:
                lines.append(f"- `{item}`")
        lines.append("")
        lines.append("## Repair method")
        lines.append("")
        lines.append(
            f"1. Read the original phase prompt snapshot at "
            f"`{prompt_path.as_posix()}` only for methodology needed to "
            "repair the gate failures above."
        )
        lines.append(
            "2. Treat disk artifacts as the source of truth. Preserve any "
            "artifact that is already complete and not explicitly listed as "
            "invalid."
        )
        lines.append(
            "3. Repair only missing, stub, structurally invalid, or "
            "gate-failing artifacts for this phase. Do not write any artifact "
            "outside this phase's expected output contract."
        )
        if getattr(phase, "appends_existing_artifact", False):
            lines.append(
                "4. This phase appends/enriches an existing artifact. Preserve "
                "existing content and add only the missing phase-owned section "
                "or repair requested by the gate."
            )
        else:
            lines.append(
                "4. If a failed artifact exists but is invalid, rewrite that "
                "artifact only; do not rewrite unrelated complete outputs."
            )
        lines.append("")
        lines.append("## Completion")
        lines.append("")
        lines.append(
            "Before emitting DONE, verify on disk that the failed artifact(s) "
            "now exist, are substantive, satisfy the phase-specific format, "
            "and contain no unresolved placeholder text. Then emit: "
            f"`DONE: {phase.name} gate repair complete`."
        )
        lines.append("")
        ts = now_ts if now_ts is not None else int(time.time())
        snapshot = prompt_path.with_name(
            f"{prompt_path.stem}.missing_only.{ts}{prompt_path.suffix}"
        )
        snapshot.write_text("\n".join(lines) + "\n", encoding="utf-8")
        return snapshot

    if phase.name == "depth":
        lines.append(
            "A prior depth coordinator turn ended with one or more depth role "
            "artifacts incomplete. Your ONLY job this turn is to complete the "
            "depth rows listed below. Do NOT use any breadth manifest; "
            "depth rows are defined by this phase's role/output contract and "
            "the original depth prompt snapshot."
        )
        lines.append("")
        lines.append("## Incomplete Depth Rows")
        lines.append("")
        lines.append("| Role | Expected Output | Status |")
        lines.append("| --- | --- | --- |")
        for r in incomplete:
            name = str(r.get("name") or "")
            role = name
            if role.startswith("depth_"):
                role = role[len("depth_"):]
            if role.endswith("_findings.md"):
                role = role[: -len("_findings.md")]
            lines.append(f"| {role or '(unknown)'} | {name} | {str(r.get('status','')).upper()} |")
        if gate_missing:
            lines.append("")
            lines.append("Gate detail:")
            for item in gate_missing:
                lines.append(f"- {item}")
        lines.append("")
        lines.append("## Methodology")
        lines.append("")
        lines.append(
            f"1. Read the original depth prompt snapshot at "
            f"`{prompt_path.as_posix()}` for the exact methodology, mode "
            "requirements, language templates, semantic proof blocks, graph "
            "artifact obligations, and marker contract."
        )
        lines.append(
            f"2. Read `{template.as_posix()}` only as the shared depth "
            "methodology reference. Do not follow breadth coordinator "
            "instructions; do not read breadth manifests; do not use "
            "breadth static-analysis shard conventions."
        )
        lines.append(
            "3. Repair ONLY the expected output files listed above. Preserve "
            "every depth file that already has final "
            "`<!-- PLAMEN_STATUS: COMPLETE -->` and is not listed here."
        )
        lines.append(
            "4. If you need to spawn Task agents, spawn only the listed depth "
            "roles, wait for them to finish, and verify their files on disk. "
            "Each Task prompt must include `AGENT_ROW`, `EXPECTED_OUTPUT`, "
            "the IN_PROGRESS-first marker write, the depth role methodology, "
            "and the SCOPE line that forbids other outputs."
        )
        lines.append("")
        lines.append("## Completion")
        lines.append("")
        lines.append(
            "Before emitting DONE, verify ON DISK that every listed depth "
            "artifact exists, is substantive, has a final COMPLETE marker, "
            "and contains either `### Finding [` / `## Finding [` blocks or "
            "a `## No Findings` rationale. Then emit: "
            "`DONE: missing depth rows completed`."
        )
        lines.append("")
        ts = now_ts if now_ts is not None else int(time.time())
        snapshot = prompt_path.with_name(
            f"{prompt_path.stem}.missing_only.{ts}{prompt_path.suffix}"
        )
        snapshot.write_text("\n".join(lines) + "\n", encoding="utf-8")
        return snapshot

    lines.append(
        "A prior coordinator turn for this phase ended (possibly after a "
        "context compaction) with some manifest outputs incomplete. Your "
        "ONLY job this turn: complete the incomplete rows listed below. Do "
        "NOT touch any file that already contains "
        "`<!-- PLAMEN_STATUS: COMPLETE -->` -- those rows are done."
    )
    lines.append("")
    lines.append("## Incomplete rows (the ONLY work for this turn)")
    lines.append("")
    lines.append("| Expected Output | Status |")
    lines.append("| --- | --- |")
    for r in incomplete:
        lines.append(f"| {r['name']} | {str(r.get('status','')).upper()} |")
    lines.append("")
    lines.append("## How to run each incomplete row (FULL methodology, not a shortcut)")
    lines.append("")
    lines.append(
        f"1. Read `{(scratchpad / 'spawn_manifest.md').as_posix()}`. For each "
        "incomplete Expected Output above, find its manifest row: Agent ID, "
        "Focus Area, and skill/template binding."
    )
    lines.append(
        f"2. Read the Subagent Prompt Template in `{template.as_posix()}` and "
        "construct each subagent's Task() prompt EXACTLY per that template "
        "(same recon reads, same methodology, same PLAMEN marker contract). "
        "Do not summarize or weaken it."
    )
    lines.append(
        "3. Each subagent's assigned opengrep obligation shard, if present, is "
        f"at `{scratchpad.as_posix()}/opengrep_obligations_<agent_id>_"
        "<focus_area_slug>.md` (telemetry; not a completeness gate)."
    )
    if phase.name == "breadth":
        lines.append(
            "4. Spawn ONLY the incomplete rows above, as background Task calls "
            "in a single assistant message (`run_in_background: true` for each "
            "Task), then keep this coordinator alive and monitor/collect until "
            "disk verification passes. Do NOT re-spawn or overwrite rows "
            "already COMPLETE on disk."
        )
    else:
        lines.append(
            "4. Spawn ONLY the incomplete rows above, as foreground Task calls "
            "in a single message. Do NOT re-spawn or overwrite rows already "
            "COMPLETE on disk."
        )
    lines.append("")
    lines.append("## Completion (disk-derived; never trust memory or a compaction summary)")
    lines.append("")
    lines.append(
        "Before emitting DONE, verify ON DISK that EVERY incomplete row above "
        "now exists with a final `<!-- PLAMEN_STATUS: COMPLETE -->` and either "
        "a `## Finding [` block or a `## No Findings` rationale. Use targeted "
        "grep / file checks, NOT full-body reads. Only then emit: "
        f"`DONE: <N> missing {phase.name} rows completed`."
    )
    lines.append("")
    ts = now_ts if now_ts is not None else int(time.time())
    snapshot = prompt_path.with_name(
        f"{prompt_path.stem}.missing_only.{ts}{prompt_path.suffix}"
    )
    snapshot.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return snapshot


def _respawn_missing_only(
    *,
    phase: Phase,
    scratchpad: Path,
    row_statuses: list[dict[str, Any]],
    base_cmd: list[str],
    cwd: str,
    env: dict[str, str],
    log_file: Any,
    prompt_path: Path,
    gate_missing: list[Any] | None = None,
    provider_dispatch_authority: Callable[[], None] | None = None,
) -> ClaudePtySession:
    """Spawn a FRESH PTY session (new uuid, NOT --resume) with a compact
    missing-only continuation prompt. Returns the new (spawned +
    bootstrapped) session.

    Ship 8.11: this is the third continuation transport, available even
    when preflight reports live=False AND resume=False. It runs the SAME
    missing agents a whole-phase retry would, with a smaller base prompt
    and without re-running already-COMPLETE rows -- so cost is <= a full
    retry, and on success it avoids the full retry entirely.
    """
    new_session_id = str(uuid.uuid4())
    fresh_cmd = _build_fresh_session_cmd(base_cmd, new_session_id)
    snapshot = _build_missing_only_prompt(
        phase, scratchpad, row_statuses, prompt_path,
        gate_missing=gate_missing,
    )
    # Ship 8.16: point the argv positional prompt at the compact missing-only
    # snapshot. Without this, PLAMEN_BOOTSTRAP_IN_ARGV makes the fresh session
    # re-run the ORIGINAL full phase prompt (send_bootstrap is suppressed in
    # argv mode) -- defeating the entire missing-only optimization.
    fresh_cmd = _rewrite_argv_positional_prompt(fresh_cmd, snapshot)
    new_session = ClaudePtySession(
        fresh_cmd,
        cwd=cwd,
        env=env,
        session_id=new_session_id,
        prompt_path=snapshot,
        log_file=log_file,
    )
    if provider_dispatch_authority is not None:
        provider_dispatch_authority()
    new_session.spawn()
    new_session.send_bootstrap()
    return new_session


def _write_continuation_record(
    scratchpad: Path,
    phase_name: str,
    attempt: int,
    continuation: str,
    gate_missing: list[str],
) -> None:
    """Persist a forensic record of an in-session continuation. The
    file is best-effort -- write failures are logged at debug level
    and do not affect the supervision loop. One file per attempt
    keeps the audit trail straightforward; the supervision loop
    appends a new one for each iteration.
    """
    try:
        path = scratchpad / f"_continuation_{phase_name}_{attempt}.md"
        body = []
        body.append(f"# Continuation record: {phase_name} attempt {attempt}")
        body.append("")
        body.append("## Gate failure detail")
        body.append("")
        for item in (gate_missing or []):
            body.append(f"- {item}")
        body.append("")
        body.append("## Continuation message sent to coordinator")
        body.append("")
        body.append(continuation)
        path.write_text("\n".join(body) + "\n", encoding="utf-8")
    except Exception as exc:
        log.debug(
            f"[{phase_name}] continuation record write failed: {exc}"
        )


def _run_supervised_pty_loop(
    *,
    session: ClaudePtySession,
    scratchpad: Path,
    project_root: str,
    phase: Phase,
    config: dict,
    preflight: dict,
    timeout: float,
    quiescence_s: float,
    on_poll: Any,
    base_cmd: list[str],
    cwd: str,
    env: dict[str, str],
    log_file: Any,
    prompt_path: Path,
    phase_started_at: float | None = None,
    provider_dispatch_authority: Callable[[], None] | None = None,
) -> tuple[int, ClaudePtySession]:
    """Drive the artifact-complete supervision loop for a single phase.

    Returns ``(rc, final_session)``. ``final_session`` may differ from
    the input ``session`` because incomplete phases are recovered by
    terminating the old coordinator and spawning a fresh missing-only
    interactive Claude session.

    Production policy: no live PTY continuation and no ``--resume``. A
    Claude PTY is a disposable phase worker; disk artifacts are the durable
    state. If the gate rejects a turn, the driver computes incomplete rows
    from disk and starts a new missing-only session scoped to those rows.

    rc semantics:

      - ``0``  -- disk gate passed (artifacts are COMPLETE +
        structurally OK).
      - ``1``  -- rate-limited (the existing rate-limit retry logic
        in the outer loop handles backoff).
      - ``-2`` -- whole-phase retry sentinel: budget exhausted, no
        structured row status available, hang (no end_turn within
        ``timeout``), old PTY refused to terminate, or missing-only
        respawn failed. The outer driver retries the phase from scratch;
        COMPLETE rows on disk are skipped by the phase prompt's
        disk-verification loop, so progress is preserved.

    The ``_PtyStop`` foreign-artifact containment exception raised by
    ``on_poll`` propagates out of this function unchanged -- the
    caller's existing except-handler converts it to ``rc = stop.rc``.
    """
    model_phase = _model_owned_supervision_phase(phase)
    budget = int(config.get("pty_continuation_budget", 3))
    attempt = 0

    # Ship 8.13: emit the auto-compaction telemetry at most ONCE per phase
    # run. It is INFO, not WARNING: disk gates remain authoritative.
    compaction_warned = False

    while True:
        attempt += 1
        state = session.wait_for_turn_complete(
            timeout,
            quiescence_s=quiescence_s,
            on_poll=on_poll,
        )

        if state.rate_limited:
            return 1, session

        # Ship 8.17: context-overflow / autocompact-thrash fast-fail. The wait
        # loop returned early (instead of burning the full deadline) because
        # the turn was emitting compaction churn with zero forward progress for
        # >= _CONTEXT_THRASH_LOOP_S. This is NOT a new halt: we simply let the
        # existing gate + missing-only / whole-phase recovery below take over
        # immediately, exactly as on a timeout. If the gate happens to have
        # passed (work landed on disk before thrash), the gate_passed branch
        # below returns 0 unchanged. Diagnostic WARNING, emitted at most once.
        if getattr(state, "context_thrash", False):
            log.warning(
                f"[{phase.name}] context-overflow thrash detected after "
                f"~{int(_CONTEXT_THRASH_LOOP_S)}s with no new productive "
                f"output; abandoning this turn and recovering missing rows "
                f"instead of waiting the full {timeout}s timeout"
            )

        # Run the in-session gate.
        try:
            gate_passed, gate_missing = gate_passes(
                scratchpad, project_root, model_phase
            )
        except Exception as exc:
            log.error(
                f"[{phase.name}] supervised gate check failed: {exc}; "
                f"falling back to whole-phase retry"
            )
            return -2, session

        if gate_passed:
            # Semantic-dedup compaction-continue. The driver pre-writes a
            # crash-safety PASSTHROUGH scaffold (dedup_decisions.md +
            # findings_inventory_deduped.md) BEFORE this subprocess so a
            # timeout never loses findings. That scaffold satisfies the
            # generic artifact gate from turn 1 — so without this guard the
            # loop returns 0 immediately and NEVER spends its continuation
            # budget, even when the subprocess compacted mid-write and left
            # the scaffold unchanged while live candidate pairs remain. That
            # is the exact "passes on the safety net, never actually dedups"
            # no-op. Treat an unchanged PASSTHROUGH + live pairs the same as
            # any other incomplete artifact: drive a FRESH missing-only
            # continuation (clean context, immune to the prior compaction)
            # up to the same budget breadth/depth use. When the budget is
            # spent, ACCEPT the passthrough floor (return 0) — never -2 —
            # because this phase is critical=True and a -2 would cascade to
            # whole-phase retries and ultimately a critical halt. The
            # mechanical passthrough disposition + supplemental dedup +
            # the Python-native report_dedup remain the recall-safe net.
            if _dedup_passthrough_should_continue(
                phase.name, attempt, budget, scratchpad
            ):
                log.info(
                    f"[{phase.name}] gate passes on the pre-written "
                    f"PASSTHROUGH scaffold but live candidate pairs remain "
                    f"(attempt {attempt}/{budget}); driving a fresh "
                    f"missing-only continuation instead of accepting the "
                    f"no-op (compaction-continue, same as breadth/depth)."
                )
                gate_passed = False
                if not gate_missing:
                    gate_missing = [
                        "dedup_decisions.md still carries Status: PASSTHROUGH "
                        "while dedup_candidate_pairs.md has live rows — "
                        "evaluate every candidate pair and OVERWRITE the "
                        "passthrough with real MERGE / KEEP SEPARATE decisions"
                    ]
            else:
                return 0, session

        # Ship 8.13: DONE-then-gate-miss telemetry. When the turn reached
        # end_turn (state.complete -> the coordinator emitted DONE) yet the
        # disk gate REJECTED it, and the transcript shows an auto-compaction
        # fingerprint, this is the verified premature-DONE signature from a prior run.
        # Diagnostic ONLY -- it never gates the phase and never alters
        # control flow (the missing-only / live / resume continuation below
        # handles recovery regardless). Emitted at most once per phase run.
        if state.complete and not compaction_warned:
            try:
                if transcript_shows_compaction(session.transcript_path):
                    log.info(
                        f"[{phase.name}] coordinator emitted DONE after "
                        f"Claude context compaction, but disk gate rejected "
                        f"completion; continuing missing rows. This is not "
                        f"a phase failure."
                    )
                    compaction_warned = True
            except Exception:
                pass

        process_exited = not session.is_alive()

        # Build the repair scope from disk. Breadth/depth return structured
        # per-row status; all other gate-backed phases return [] and fall
        # back to gate_missing detail for the generic artifact repair prompt.
        try:
            row_statuses = compute_phase_row_statuses(scratchpad, model_phase)
        except Exception as exc:
            log.warning(
                f"[{phase.name}] compute_phase_row_statuses failed: {exc}"
            )
            row_statuses = []

        incomplete_count = sum(
            1 for r in row_statuses
            if r.get("status") and r["status"] != "complete"
        )
        if incomplete_count <= 0 and gate_missing:
            incomplete_count = len(gate_missing)
        if incomplete_count <= 0:
            log.warning(
                f"[{phase.name}] gate failed but no structured incomplete "
                "rows were available; falling back to whole-phase retry"
            )
            return -2, session

        timed_out_without_end = not state.complete and not process_exited
        is_verify_shard = (
            phase.name in L1_VERIFY_PHASE_NAMES
            or phase.name in SC_VERIFY_PHASE_NAMES
        )
        if timed_out_without_end and not is_verify_shard:
            log.warning(
                f"[{phase.name}] PTY turn at attempt {attempt} did not "
                f"reach end_turn within {timeout}s; falling back to "
                f"whole-phase retry"
            )
            return -2, session

        if attempt > budget:
            log.warning(
                f"[{phase.name}] in-session continuation budget ({budget}) "
                f"exhausted; falling back to whole-phase retry"
            )
            return -2, session
        if timed_out_without_end:
            log.warning(
                f"[{phase.name}] PTY turn at attempt {attempt} did not "
                f"reach end_turn within {timeout}s; starting missing-only "
                f"verifier recovery for {incomplete_count} incomplete row(s)"
            )

        # Permanent subscription-preserving policy: never try to keep
        # driving the same interactive PTY, and never depend on --resume /
        # transcript handles. The old coordinator is disposable; the durable
        # state is the set of files on disk. Each recovery turn starts a
        # fresh Claude interactive session with a compact missing-only prompt.
        log.info(
            f"[{phase.name}] continuation #{attempt} via fresh missing-only "
            f"PTY ({incomplete_count} incomplete rows)"
        )
        try:
            display.print_phase_heartbeat(
                phase.name,
                int(time.time() - phase_started_at) if phase_started_at else 0,
                status=(
                    f"gate repair: fresh PTY for {incomplete_count} "
                    "incomplete artifact(s)"
                ),
            )
        except Exception:
            pass
        # Old-PTY termination guarantee + defined refusal (Correction 3):
        # never spawn a second coordinator into the same scratchpad while the
        # old one is alive.
        try:
            session.terminate(grace_s=_HALT_TERMINATE_GRACE_S)
        except Exception:
            pass
        _term_deadline = time.time() + 5.0
        while session.is_alive() and time.time() < _term_deadline:
            time.sleep(0.2)
        if session.is_alive():
            log.error(
                f"[{phase.name}] old PTY refused to terminate before "
                f"missing-only continuation; refusing to spawn a second "
                f"coordinator into the same scratchpad -- falling back to "
                f"whole-phase retry"
            )
            return -2, session
        try:
            _respawn_kwargs: dict[str, Any] = {
                "phase": model_phase,
                "scratchpad": scratchpad,
                "row_statuses": row_statuses,
                "base_cmd": base_cmd,
                "cwd": cwd,
                "env": env,
                "log_file": log_file,
                "prompt_path": prompt_path,
                "gate_missing": gate_missing,
            }
            # Preserve the historical helper call shape for every non-recon
            # phase.  Recon alone needs the fresh-spawn authority callback.
            if provider_dispatch_authority is not None:
                _respawn_kwargs["provider_dispatch_authority"] = (
                    provider_dispatch_authority
                )
            session = _respawn_missing_only(
                **_respawn_kwargs,
            )
        except ReconPrepassDispatchBlocked:
            raise
        except Exception as exc:
            log.error(
                f"[{phase.name}] missing-only respawn failed: {exc}; "
                f"falling back to whole-phase retry"
            )
            return -2, session
        continue


# ===========================================================================
# Python-scheduled recon worker PTYs
# ===========================================================================

_RECON_WORKER_CONCURRENCY = 4
_RECON_WORKER_ROUNDS_PER_PHASE_ATTEMPT = 2


def _recon_worker_attempt_ordinal(
    phase_attempt: int,
    worker_round: int,
) -> int:
    """Map an outer recon attempt and its local round to one unique ordinal."""

    if (
        type(phase_attempt) is not int
        or phase_attempt < 1
        or type(worker_round) is not int
        or not 1 <= worker_round <= _RECON_WORKER_ROUNDS_PER_PHASE_ATTEMPT
    ):
        raise ValueError("recon worker attempt coordinates are invalid")
    return (
        (phase_attempt - 1) * _RECON_WORKER_ROUNDS_PER_PHASE_ATTEMPT
        + worker_round
    )


def _recon_outer_attempt_from_worker(worker_attempt: int) -> int:
    """Invert a recon worker ordinal to its outer semantic attempt."""

    if type(worker_attempt) is not int or worker_attempt < 1:
        raise ValueError("recon worker attempt ordinal is invalid")
    return (
        (worker_attempt - 1) // _RECON_WORKER_ROUNDS_PER_PHASE_ATTEMPT
    ) + 1


_RECON_RETRY_PLAN_FIELDS = {
    "schema", "run_id", "phase_name", "work_unit_id", "attempt",
    "input_digest", "output_digest_before", "contract_digest",
    "launch_digest", "required_output_schema", "failed_predicates",
    "semantic_retry",
}
_RECON_RETRY_PREDICATE_FIELDS = {
    "gate_id", "gate_class", "message", "affected_identities",
    "input_digest", "output_digest", "contract_digest", "evidence_paths",
    "repair_owner", "fallback_policy", "allowed_fallback", "schema_id",
    "schema_version", "denominator_count", "denominator_digest",
    "predicate_digest", "failure_instance_id",
}


def _validated_recon_retry_plan(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    worker_attempt: int,
    phase: Phase | None = None,
) -> dict[str, Any]:
    """Read and authenticate the retry plan consumed by a recon leaf.

    A missing plan is a typed absence used by transport-only retries. Once a
    plan exists it is production-strict: duplicate/foreign fields, stale run
    or attempt identity, non-semantic authorization, and malformed predicate
    denominators all fail before a model can launch.
    """

    outer_attempt = _recon_outer_attempt_from_worker(worker_attempt)
    if outer_attempt <= 1:
        return {"state": "NOT_APPLICABLE", "outer_attempt": outer_attempt}
    path = Path(scratchpad) / "recon_retry_plan.json"
    try:
        before = path.lstat()
    except FileNotFoundError:
        return {"state": "MISSING", "outer_attempt": outer_attempt}
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or _driver_vector_reparse(before)
        or before.st_size > 1024 * 1024
    ):
        raise ValueError("recon retry plan is not a bounded regular file")
    raw = path.read_bytes()
    after = path.lstat()
    identity_before = (
        before.st_dev, before.st_ino, before.st_size,
        before.st_mtime_ns, before.st_ctime_ns,
    )
    identity_after = (
        after.st_dev, after.st_ino, after.st_size,
        after.st_mtime_ns, after.st_ctime_ns,
    )
    if identity_before != identity_after or len(raw) != after.st_size:
        raise ValueError("recon retry plan changed while it was read")
    try:
        payload = json.loads(
            raw.decode("utf-8"), object_pairs_hook=_reject_duplicate_json_pairs
        )
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        raise ValueError(f"recon retry plan is malformed: {exc}") from exc
    if not isinstance(payload, dict) or set(payload) != _RECON_RETRY_PLAN_FIELDS:
        raise ValueError("recon retry plan field set is malformed")
    run_id = config.get("_run_id")
    if not isinstance(run_id, str) or not run_id:
        raise ValueError("recon retry plan requires current run identity")
    plan_attempt = payload.get("attempt")
    semantic_plan = plan_attempt == 2 and outer_attempt == 2
    transport_successor = plan_attempt == 2 and outer_attempt == 3
    if (
        payload.get("schema") != "plamen.retry-plan/v1"
        or payload.get("run_id") != run_id
        or payload.get("phase_name") != "recon"
        or payload.get("work_unit_id") != "phase"
        or not (semantic_plan or transport_successor)
        or payload.get("semantic_retry") is not True
    ):
        raise ValueError("recon retry plan identity or authorization is stale")
    for name in (
        "input_digest", "output_digest_before", "contract_digest",
        "launch_digest",
    ):
        if not isinstance(payload.get(name), str) or not re.fullmatch(
            r"[0-9a-f]{64}", payload[name]
        ):
            raise ValueError(f"recon retry plan {name} is malformed")
    required = payload.get("required_output_schema")
    if not isinstance(required, list) or not required:
        raise ValueError("recon retry plan output schema is empty")
    for row in required:
        if (
            not isinstance(row, dict)
            or set(row) != {"pattern", "minimum_bytes", "minimum_count"}
            or not isinstance(row.get("pattern"), str)
            or not row["pattern"]
            or type(row.get("minimum_bytes")) is not int
            or row["minimum_bytes"] < 0
            or type(row.get("minimum_count")) is not int
            or row["minimum_count"] < 0
        ):
            raise ValueError("recon retry plan output schema is malformed")
    if phase is not None:
        expected = [
            {
                "pattern": pattern,
                "minimum_bytes": phase.min_artifact_bytes,
                "minimum_count": phase.min_artifacts_count,
            }
            for pattern in phase.expected_artifacts
        ]
        if required != expected:
            raise ValueError("recon retry plan output schema is foreign")
        current_digests = {
            "input_digest": _resolved_phase_input_digest(phase, dict(config)),
            "contract_digest": _resolved_phase_contract_digest(
                phase, dict(config)
            ),
            "launch_digest": _resolved_phase_launch_digest(
                phase, dict(config)
            ),
        }
        if any(payload[name] != digest for name, digest in current_digests.items()):
            raise ValueError("recon retry plan phase digest authority is stale")
    predicates = payload.get("failed_predicates")
    if not isinstance(predicates, list) or not predicates or len(predicates) > 4096:
        raise ValueError("recon retry plan predicate denominator is malformed")
    validated: list[GateFailure] = []
    for row in predicates:
        if not isinstance(row, dict) or set(row) != _RECON_RETRY_PREDICATE_FIELDS:
            raise ValueError("recon retry plan predicate field set is malformed")
        try:
            failure = GateFailure.from_dict(row)
            recompute_row = dict(row)
            recompute_row["predicate_digest"] = ""
            recompute_row["failure_instance_id"] = ""
            recomputed = GateFailure.from_dict(recompute_row)
        except RuntimeError as exc:
            raise ValueError(f"recon retry predicate is malformed: {exc}") from exc
        if (
            failure.to_dict() != row
            or row["predicate_digest"] != recomputed.predicate_digest
            or row["failure_instance_id"] != recomputed.failure_instance_id
        ):
            raise ValueError("recon retry predicate is not canonical")
        if not failure.gate_id.startswith("recon."):
            raise ValueError("recon retry predicate has a foreign gate namespace")
        if failure.contract_digest != payload["contract_digest"]:
            raise ValueError("recon retry predicate contract digest is foreign")
        validated.append(failure)
    return {
        "state": "PRESENT",
        "outer_attempt": outer_attempt,
        "plan_attempt": plan_attempt,
        "transport_successor": transport_successor,
        "sha256": hashlib.sha256(raw).hexdigest(),
        "raw": raw,
        "payload": payload,
        "failures": tuple(validated),
    }


def _recon_retry_authority_prompt_block(
    scratchpad: Path,
    config: Mapping[str, Any],
    *,
    worker_attempt: int,
    agent_role: str = "",
    assigned_output: str = "",
) -> str:
    authority = _validated_recon_retry_plan(
        scratchpad, config, worker_attempt=worker_attempt
    )
    if authority["state"] == "NOT_APPLICABLE":
        return ""
    if authority["state"] == "MISSING":
        return (
            "\n## HARD Retry Authority\n\n"
            "- Retry plan state: `MISSING` (typed absence).\n"
            "- This is transport-only authority. Re-run the unchanged work "
            "denominator; no semantic repair or scope change is authorized.\n"
        )
    relevant_failures = tuple(
        failure for failure in authority["failures"]
        if not failure.affected_identities
        or assigned_output in failure.affected_identities
        or f"scratchpad:{assigned_output}" in failure.affected_identities
    )
    lines = [
        "\n## HARD Retry Authority\n",
        "The authenticated retry plan is part of this worker's immutable input "
        "denominator. This remains one isolated recon leaf: repair only typed "
        "predicates applicable to the assigned role/output; quarantined or "
        "stale outputs are not evidence.\n",
        f"- Plan SHA-256: `{authority['sha256']}`",
        f"- Semantic outer attempt: `{authority['outer_attempt']}`",
        f"- Authenticated predicate count: `{len(authority['failures'])}`",
        f"- Assigned role: `{agent_role or 'unspecified'}`",
        f"- Sole output: `scratchpad:{assigned_output}`",
        (
            "- Transport-successor state: `ACTIVE`; this invocation inherits "
            "the immediately preceding semantic plan and may not add or alter "
            "repair predicates."
            if authority["transport_successor"]
            else "- Transport-successor state: `NOT_APPLICABLE`."
        ),
        (
            "- Read the exact registered PhaseIO input "
            "`scratchpad:recon_retry_plan.json`. Apply only rows whose "
            "`affected_identities` contain this sole output, plus genuinely "
            "phase-wide rows with an empty affected denominator. Never repair "
            "another recon role or write an alternate/canonical output."
        ),
        "- The following at-most-16 applicable rows are a navigation projection; "
        "the plan digest above remains authoritative.",
    ]
    if not relevant_failures:
        lines.append(
            "- No authenticated predicate is assigned to this output; rerun the "
            "unchanged role denominator and do not infer additional repair work."
        )
    for failure in relevant_failures[:16]:
        affected = ", ".join(failure.affected_identities[:8]) or "(phase)"
        message = " ".join(failure.message.split())[:320]
        lines.append(
            f"- `{failure.gate_id}` [{affected}]: {message} "
            f"(predicate `{failure.predicate_digest}`)"
        )
    return "\n".join(lines) + "\n"


def _build_recon_direct_retry_prompt(
    *,
    scratchpad: Path,
    config: Mapping[str, Any],
    supervised_attempt: int,
) -> str:
    """Render the bounded prompt for a typed private recon retry.

    A direct retry is not the legacy V1 recon coordinator.  Its PhaseIO
    contract has one exact scratchpad input (the authenticated retry plan) and
    a private replacement for every canonical recon artifact.  Reusing the V1
    prompt here made the restricted-Claude consistency gate correctly reject
    dozens of foreign reads, writes, shell commands, and coordinator actions
    before the provider could start.
    """

    if type(supervised_attempt) is not int or supervised_attempt not in {2, 3}:
        raise ValueError("direct recon retry attempt must be 2 or 3")
    authority = _pending_recon_direct_retry_authority(
        Path(scratchpad), config
    )
    if not isinstance(authority, Mapping):
        raise ValueError("direct recon retry prompt lacks launch authority")
    raw = _recon_retry_regular_bytes(
        Path(scratchpad) / "recon_retry_plan.json",
        label="recon retry plan",
    )
    if hashlib.sha256(raw).hexdigest() != authority.get("retry_plan_sha256"):
        raise ValueError("direct recon retry prompt plan digest drifted")
    try:
        plan = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=_reject_duplicate_json_pairs,
        )
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        raise ValueError(f"direct recon retry prompt plan is malformed: {exc}") from exc
    if (
        not isinstance(plan, Mapping)
        or plan.get("schema") != "plamen.retry-plan/v1"
        or plan.get("phase_name") != "recon"
        or plan.get("semantic_retry") is not True
        or plan.get("attempt") != authority.get("semantic_attempt")
    ):
        raise ValueError("direct recon retry prompt plan identity drifted")

    pipeline = str(config.get("pipeline") or "sc").strip().lower()
    private_outputs = recon_direct_retry_output_paths(
        pipeline, supervised_attempt
    )
    from plamen_mechanical import (  # pylint: disable=import-outside-toplevel
        _canonical_merge_output_names,
    )

    canonical_outputs = tuple(_canonical_merge_output_names(pipeline)[:-1])
    if len(private_outputs) != len(canonical_outputs):
        raise ValueError("direct recon retry output mapping drifted")
    output_lines = "\n".join(
        f"- `scratchpad:{name}`" for name in private_outputs
    )
    mapping_lines = "\n".join(
        f"| `{private}` | `{canonical}` |"
        for private, canonical in zip(private_outputs, canonical_outputs)
    )
    failures = plan.get("failed_predicates")
    if not isinstance(failures, list) or not failures:
        raise ValueError("direct recon retry prompt has no failed predicates")
    failure_lines = []
    for row in failures[:32]:
        if not isinstance(row, Mapping):
            raise ValueError("direct recon retry prompt predicate is malformed")
        gate_id = str(row.get("gate_id") or "UNKNOWN").replace("|", "\\|")
        message = " ".join(str(row.get("message") or "").split())
        failure_lines.append(
            f"| `{gate_id}` | {message[:600].replace('|', '\\|')} |"
        )

    skill_block = ""
    if pipeline == "sc":
        root = plamen_home()
        catalog = bindable_skill_selection_rows(
            skill_index_path=root / "rules" / "skill-index.md",
            skill_root=root / "agents" / "skills",
            ecosystem=str(config.get("language") or "unknown"),
            pipeline=pipeline,
        )
        catalog_lines = "\n".join(
            f"- `{row['skill_id']}`" for row in catalog
        )
        skill_block = f"""

## Closed skill identifiers

For the template-recommendations replacement, include exactly one single-line
`PLAMEN_SIGNALS` JSON comment. Every selected identifier must be copied from
this closed list; an empty list is valid when source evidence triggers none.

{catalog_lines}
"""

    return f"""# RECON DIRECT RETRY

This is one bounded private replacement transaction. It is not a coordinator
and it does not run another pipeline phase. The authenticated retry plan is the
sole scratchpad evidence input. Production source may be inspected only within
the safe search roots shown in the supervisor block that follows this prompt.

## Registered input file to read

- `scratchpad:recon_retry_plan.json`

Apply the authenticated failed predicates without inventing another repair
scope. Preserve uncertainty when evidence is unavailable.
Never use a shell or run commands.
Never spawn workers or search the scratchpad.
Never write canonical root artifacts or any additional file.

## Authenticated failed predicates

| Gate | Failure |
|---|---|
{chr(10).join(failure_lines)}

## Output files to write

{output_lines}

Each private output must be a complete, substantive Markdown replacement of at
least 100 bytes for the canonical artifact shown below. Cite concrete production
source paths and line numbers when supported. Build/tool status must remain
`NOT_ATTEMPTED` unless it is already established by the registered retry plan.

| Private output | Canonical content contract |
|---|---|
{mapping_lines}
{skill_block}

Finish only after all listed private outputs are complete. Return one concise
completion message.
"""


def _route_recon_direct_retry_prompt(
    prompt: str,
    *,
    phase_name: str,
    scratchpad: Path,
    config: Mapping[str, Any],
    attempt: int,
) -> str:
    """Replace legacy recon prose only for an armed typed direct retry."""

    if (
        phase_name != "recon"
        or not _recon_direct_retry_uses_typed_transaction(config)
        or _pending_recon_direct_retry_authority(
            Path(scratchpad), config
        ) is None
    ):
        return prompt
    return _build_recon_direct_retry_prompt(
        scratchpad=Path(scratchpad),
        config=config,
        supervised_attempt=attempt,
    )


_RECON_PREPASS_RETRY_BASELINE_DIR = "_recon_prepass_retry_baseline"
_RECON_PREPASS_RETRY_BASELINE_SCHEMA = "plamen.recon-prepass-retry-baseline.v1"


def _recon_retry_regular_bytes(path: Path, *, label: str) -> bytes:
    try:
        before = path.lstat()
    except OSError as exc:
        raise ValueError(f"{label} is absent: {exc}") from exc
    attributes = int(getattr(before, "st_file_attributes", 0))
    reparse_tag = int(getattr(before, "st_reparse_tag", 0))
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or attributes & 0x400
        or reparse_tag != 0
        or before.st_size > 32 * 1024 * 1024
    ):
        raise ValueError(f"{label} is not a bounded regular file")
    raw = path.read_bytes()
    after = path.lstat()
    if (
        (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns,
         before.st_ctime_ns)
        != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns,
            after.st_ctime_ns)
        or len(raw) != after.st_size
    ):
        raise ValueError(f"{label} changed while read")
    return raw


def _recon_prepass_retry_receipt_authority(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[Mapping[str, Any], tuple[str, ...], dict[str, str], bytes]:
    from recon_prepass import _prepass_output_names, _prepass_read_receipt

    receipt = _prepass_read_receipt(Path(scratchpad))
    pipeline = str(config.get("pipeline") or "sc").strip().lower()
    selected = tuple(_prepass_output_names(pipeline)[:-1])
    receipt_path = Path(scratchpad) / "recon_prepass_publication_receipt.json"
    receipt_raw = _recon_retry_regular_bytes(
        receipt_path, label="recon prepass publication receipt"
    )
    if (
        not isinstance(receipt, Mapping)
        or tuple(receipt.get("selected_outputs") or ()) != selected
    ):
        raise ValueError("recon prepass publication receipt is not authoritative")
    hashes = receipt.get("selected_output_sha256")
    if (
        not isinstance(hashes, Mapping)
        or set(hashes) != set(selected)
        or any(
            not isinstance(hashes.get(name), str)
            or not re.fullmatch(r"[0-9a-f]{64}", str(hashes[name]))
            for name in selected
        )
    ):
        raise ValueError("recon prepass receipt output denominator is malformed")
    return receipt, selected, {name: str(hashes[name]) for name in selected}, receipt_raw


def _validated_recon_prepass_retry_baseline(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> dict[str, Any] | None:
    _receipt, selected, expected_hashes, receipt_raw = (
        _recon_prepass_retry_receipt_authority(scratchpad, config)
    )
    root = Path(scratchpad) / _RECON_PREPASS_RETRY_BASELINE_DIR
    if not root.exists():
        return None
    if root.is_symlink() or not root.is_dir():
        raise ValueError("recon prepass retry baseline root is unsafe")
    manifest_raw = _recon_retry_regular_bytes(
        root / "manifest.json", label="recon prepass retry baseline manifest"
    )
    try:
        manifest = json.loads(
            manifest_raw.decode("utf-8"),
            object_pairs_hook=_reject_duplicate_json_pairs,
        )
    except (UnicodeError, ValueError, json.JSONDecodeError) as exc:
        raise ValueError(f"recon prepass retry baseline is malformed: {exc}") from exc
    run_id = str(config.get("_run_id") or config.get("run_id") or "")
    if (
        not isinstance(manifest, dict)
        or set(manifest) != {"schema", "run_id", "receipt_sha256", "files"}
        or manifest.get("schema") != _RECON_PREPASS_RETRY_BASELINE_SCHEMA
        or manifest.get("run_id") != run_id
        or manifest.get("receipt_sha256")
        != hashlib.sha256(receipt_raw).hexdigest()
        or not isinstance(manifest.get("files"), list)
    ):
        raise ValueError("recon prepass retry baseline identity is stale")
    rows = manifest["files"]
    if (
        len(rows) != len(selected)
        or any(
            not isinstance(row, dict)
            or set(row) != {"name", "sha256", "size"}
            for row in rows
        )
        or [row["name"] for row in rows] != list(selected)
    ):
        raise ValueError("recon prepass retry baseline denominator is malformed")
    payloads: dict[str, bytes] = {}
    for row in rows:
        name = str(row["name"])
        raw = _recon_retry_regular_bytes(
            root / name, label=f"recon prepass retry baseline {name}"
        )
        digest = hashlib.sha256(raw).hexdigest()
        if (
            row.get("sha256") != digest
            or row.get("size") != len(raw)
            or expected_hashes[name] != digest
        ):
            raise ValueError(f"recon prepass retry baseline changed: {name}")
        payloads[name] = raw
    return {
        "selected": selected,
        "hashes": expected_hashes,
        "payloads": payloads,
    }


def _ensure_recon_prepass_retry_baseline(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Capture exact authenticated prepass bytes before the first leaf."""
    try:
        if _validated_recon_prepass_retry_baseline(scratchpad, config) is not None:
            return []
        _receipt, selected, expected_hashes, receipt_raw = (
            _recon_prepass_retry_receipt_authority(scratchpad, config)
        )
        payloads: dict[str, bytes] = {}
        for name in selected:
            raw = _recon_retry_regular_bytes(
                Path(scratchpad) / name,
                label=f"live recon prepass baseline {name}",
            )
            if hashlib.sha256(raw).hexdigest() != expected_hashes[name]:
                raise ValueError(
                    f"live recon prepass output differs from receipt: {name}"
                )
            payloads[name] = raw
        run_id = str(config.get("_run_id") or config.get("run_id") or "")
        producer_issues = semantic_input_prebind_producer_authority_issues(
            Path(scratchpad),
            Path(str(config.get("project_root") or "")),
            tuple(
                [f"scratchpad:{name}" for name in selected]
                + ["scratchpad:recon_prepass_publication_receipt.json"]
            ),
            run_id=run_id,
        )
        if producer_issues:
            raise ValueError(
                "recon prepass producer bundle is not active: "
                + "; ".join(producer_issues)
            )
        root = Path(scratchpad) / _RECON_PREPASS_RETRY_BASELINE_DIR
        stage = Path(scratchpad) / (
            _RECON_PREPASS_RETRY_BASELINE_DIR + f".tmp.{uuid.uuid4().hex}"
        )
        stage.mkdir(parents=False, exist_ok=False)
        try:
            rows = []
            for name in selected:
                target = stage / name
                target.write_bytes(payloads[name])
                rows.append({
                    "name": name,
                    "sha256": expected_hashes[name],
                    "size": len(payloads[name]),
                })
            manifest = {
                "schema": _RECON_PREPASS_RETRY_BASELINE_SCHEMA,
                "run_id": run_id,
                "receipt_sha256": hashlib.sha256(receipt_raw).hexdigest(),
                "files": rows,
            }
            (stage / "manifest.json").write_text(
                json.dumps(manifest, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            stage.rename(root)
        finally:
            if stage.exists():
                shutil.rmtree(stage, ignore_errors=True)
        _validated_recon_prepass_retry_baseline(scratchpad, config)
        return []
    except (ArtifactLedgerError, OSError, RuntimeError, TypeError, ValueError) as exc:
        return [str(exc)]


def _restore_recon_prepass_retry_baseline(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Require the live prepass bundle to remain the captured generation.

    A model retry may consume an unchanged, still-active prepass generation.
    It may not consume a byte-copied reconstruction: finalizing such a copy as
    a semantic mutation creates a virtual producer, which the strict model
    prebind correctly rejects.  A changed member therefore fails closed here;
    a committed canonical-merge predecessor is handled by the separately
    authenticated canonical retry-generation transaction.
    """
    try:
        baseline = _validated_recon_prepass_retry_baseline(scratchpad, config)
        if baseline is None:
            raise ValueError("recon prepass retry baseline was never captured")
        selected = tuple(baseline["selected"])
        run_id = str(config.get("_run_id") or config.get("run_id") or "")
        project_root = Path(str(config.get("project_root") or ""))
        identities = tuple(
            [f"scratchpad:{name}" for name in selected]
            + ["scratchpad:recon_prepass_publication_receipt.json"]
        )
        producer_issues = semantic_input_prebind_producer_authority_issues(
            Path(scratchpad), project_root, identities, run_id=run_id
        )
        if producer_issues:
            raise ValueError(
                "live recon prepass bundle has no authenticated producer: "
                + "; ".join(producer_issues)
            )
        for name in selected:
            path = Path(scratchpad) / name
            current = _recon_retry_regular_bytes(
                path, label=f"live recon retry input {name}"
            )
            expected = baseline["payloads"][name]
            if current != expected:
                raise ValueError(
                    "live recon prepass output changed after baseline capture: "
                    + name
                )
        return []
    except (ArtifactLedgerError, OSError, RuntimeError, TypeError, ValueError) as exc:
        return [str(exc)]


def _recon_retry_predecessor_kind(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[str, list[str]]:
    """Select the sole authenticated recon retry predecessor generation."""

    try:
        from plamen_mechanical import (
            _canonical_merge_dimensions,
            _canonical_merge_output_names,
        )

        pipeline, mode, ecosystem, backend = _canonical_merge_dimensions(config)
        key = canonical_work_unit_key(
            pipeline,
            mode,
            ecosystem,
            backend,
            "recon",
            "canonical_merge",
        )
        ledger = read_artifact_ledger(Path(scratchpad))
        units = ledger.get("work_units")
        prior = units.get(key) if isinstance(units, Mapping) else None
        run_id = str(config.get("_run_id") or config.get("run_id") or "")
        if prior is not None:
            expected = tuple(
                f"scratchpad:{name}"
                for name in _canonical_merge_output_names(pipeline)
            )
            issues = active_committed_work_unit_authority_issues(
                ledger,
                work_unit_key=key,
                run_id=run_id,
                expected_artifact_identities=expected,
            )
            if issues:
                return "", [
                    "recon canonical-merge predecessor is present but not an "
                    "exact active commit: " + "; ".join(issues)
                ]
            return "canonical_merge", []
        issues = _restore_recon_prepass_retry_baseline(scratchpad, config)
        return ("prepass", []) if not issues else ("", issues)
    except (ArtifactLedgerError, OSError, RuntimeError, TypeError, ValueError) as exc:
        return "", [str(exc)]


def _rate_limit_retry_dispatch(
    phase: Phase,
    config: Mapping[str, Any],
    scratchpad: Path,
    *,
    current_attempt: int,
    shallow_gate_passed: bool,
) -> dict[str, Any]:
    """Choose transport replay without consuming semantic retry identity."""
    direct_state = (
        _recon_direct_retry_durable_state(Path(scratchpad), config)[0]
        if phase.name == "recon"
        else "ABSENT"
    )
    pending_direct = direct_state != "ABSENT"
    recon_retry = (
        phase.name == "recon"
        and (
            pending_direct
            or
            bool(config.get("_recon_force_direct_retry"))
            or _should_use_recon_worker_pool(dict(config), Path(scratchpad))
        )
    )
    return {
        "skip_spawn": bool(
            shallow_gate_passed
            and phase.expected_artifacts
            and not getattr(phase, "appends_existing_artifact", False)
            and not recon_retry
        ),
        "attempt": (
            current_attempt
            if recon_retry or current_attempt >= 3
            else 2
        ),
        "recon_transport_replay": recon_retry,
    }


def _recon_worker_log_state(
    scratchpad: Path,
) -> dict[str, tuple[int, int, int, str]]:
    """Fingerprint worker logs so phase stdio includes this invocation only."""

    state: dict[str, tuple[int, int, int, str]] = {}
    for path in sorted(Path(scratchpad).glob("_stdio_recon_worker_*.log")):
        try:
            before = path.stat()
            raw = path.read_bytes()
            after = path.stat()
        except OSError:
            continue
        if (
            before.st_size != after.st_size
            or before.st_mtime_ns != after.st_mtime_ns
            or before.st_ctime_ns != after.st_ctime_ns
        ):
            continue
        state[path.name] = (
            int(after.st_size),
            int(after.st_mtime_ns),
            int(after.st_ctime_ns),
            hashlib.sha256(raw).hexdigest(),
        )
    return state


def _recon_worker_logs_generated_since(
    scratchpad: Path,
    before: Mapping[str, tuple[int, int, int, str]],
) -> tuple[Path, ...]:
    """Return only logs created or overwritten after the bound prestate."""

    after = _recon_worker_log_state(Path(scratchpad))
    return tuple(
        Path(scratchpad) / name
        for name in sorted(after)
        if before.get(name) != after[name]
    )


def _recon_direct_retry_durable_state(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[str, Mapping[str, Any] | None, str]:
    """Classify exact canonical quarantine as absent, active, or invalid."""

    try:
        from plamen_mechanical import (
            _canonical_merge_dimensions,
            _canonical_merge_output_names,
        )

        pipeline, _mode, _ecosystem, _backend = (
            _canonical_merge_dimensions(config)
        )
        canonical = tuple(_canonical_merge_output_names(pipeline)[:-1])
        qdir = Path(scratchpad) / "_retry_quarantine" / "recon"
        present = tuple(name for name in canonical if (qdir / name).exists())
        if not present:
            return "ABSENT", None, ""
        if set(present) != set(canonical):
            return (
                "INVALID",
                None,
                "canonical direct-retry quarantine is partial",
            )
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        return "INVALID", None, str(exc)

    try:
        authority = dict(
            validate_recon_direct_retry_launch_authority(
                Path(scratchpad), config
            )
        )
        return "ACTIVE", authority, ""
    except (
        CanonicalMergeAuthorityError,
        ArtifactLedgerError,
        OSError,
        RuntimeError,
        TypeError,
        ValueError,
    ) as exc:
        return "INVALID", None, str(exc)


def _pending_recon_direct_retry_authority(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> Mapping[str, Any] | None:
    """Replay durable direct-retry authority without changing state."""

    state, authority, _issue = _recon_direct_retry_durable_state(
        scratchpad, config
    )
    return authority if state == "ACTIVE" else None


def _should_use_recon_worker_pool(config: dict, scratchpad: Path) -> bool:
    """Return True when recon should use driver-owned role workers."""
    direct_state, _authority, _issue = _recon_direct_retry_durable_state(
        scratchpad, config
    )
    if config.get("_recon_force_direct_retry") or direct_state != "ABSENT":
        # An ACTIVE canonical-merge predecessor is retried through its sealed
        # direct candidate generation.  Entering the leaf pool after those
        # predecessor files move to quarantine would guarantee missing-input
        # prelaunch debt and could never establish successor authority.
        return False
    if os.environ.get("PLAMEN_DISABLE_RECON_WORKER_POOL") == "1":
        return False
    if str(config.get("pipeline") or "").lower() not in {"sc", "l1"}:
        return False
    return True


