_L1_GRAPH_COVERAGE_SHARD_ROWS = 40
_L1_GRAPH_PANIC_SHARD_ROWS = 150


def _l1_graph_queue_name(output: str) -> str:
    return f"_graph_sweep_queue_{Path(output).stem}.json"


def _l1_graph_table_rows(
    path: Path,
    *,
    required_tokens: tuple[str, ...] = (),
) -> list[str]:
    """Return stable source-bearing Markdown rows, excluding table syntax."""
    if not path.is_file():
        return []
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return []
    rows: list[str] = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line.startswith("|") or re.fullmatch(r"\|?[\s:|\-]+\|?", line):
            continue
        lower = line.lower()
        if not any(
            suffix in lower for suffix in (".go", ".rs", ".move", ".proto")
        ):
            continue
        if required_tokens and not any(
            token.lower() in lower for token in required_tokens
        ):
            continue
        if re.search(r"(?i)\|\s*(file|location|entry)\s*\|", line):
            continue
        rows.append(line)
    return list(dict.fromkeys(rows))


def _prepare_l1_graph_sweep_plan(
    scratchpad: Path,
    config: dict,
) -> list[dict[str, Any]]:
    """Materialize an exact, bounded L1 graph-sweep work denominator."""
    root = Path(scratchpad)
    if (
        str(config.get("pipeline") or "").lower() != "l1"
        or str(config.get("mode") or "").lower() != "thorough"
    ):
        raise ValueError("L1 graph-sweep plan requires L1 Thorough")

    stats = _parse_subsystem_coverage_gap(root)
    low_coverage = (
        float(stats.get("uncited") or 0) > 0
        and float(stats.get("coverage") or 0) < 60.0
    )
    coverage_rows = (
        _l1_graph_table_rows(
            root / "subsystem_coverage_gap.md",
            required_tokens=("uncited", "leftover", "unread", "notread"),
        )
        if low_coverage
        else []
    )
    if low_coverage and not coverage_rows:
        coverage_rows = [
            "Coverage is mechanically below 60%, but no parseable per-file "
            "row was available; reconcile the complete bound coverage artifact."
        ]

    panic_rows = (
        _l1_graph_table_rows(root / "scip" / "panic_sites.md")
        if _panic_sites_available(root)
        else []
    )
    if _panic_sites_available(root) and not panic_rows:
        panic_rows = [
            "The panic-site predicate fired, but no parseable row was "
            "available; reconcile the complete bound panic artifact."
        ]

    jobs: list[dict[str, Any]] = []

    def _append(
        role: str,
        output: str,
        rows: list[str],
        *,
        sources: tuple[str, ...],
    ) -> None:
        ordinal = len(jobs) + 1
        queue = _l1_graph_queue_name(output)
        jobs.append(
            {
                "agent_id": f"G{ordinal:03d}",
                "role": role,
                "output": output,
                "queue": queue,
                "rows": list(rows),
                "sources": list(sources),
            }
        )

    for index in range(0, len(coverage_rows), _L1_GRAPH_COVERAGE_SHARD_ROWS):
        _append(
            "coverage_fill",
            f"coverage_fill_{index // _L1_GRAPH_COVERAGE_SHARD_ROWS + 1}.md",
            coverage_rows[index:index + _L1_GRAPH_COVERAGE_SHARD_ROWS],
            sources=("subsystem_coverage_gap.md", "scip/repo_map.md"),
        )
    for index in range(0, len(panic_rows), _L1_GRAPH_PANIC_SHARD_ROWS):
        _append(
            "panic_audit",
            f"panic_audit_{index // _L1_GRAPH_PANIC_SHARD_ROWS + 1}.md",
            panic_rows[index:index + _L1_GRAPH_PANIC_SHARD_ROWS],
            sources=(
                "scip/panic_sites.md",
                "scip/xref_map.md",
                "scip/call_graph_p2p.md",
                "scip/call_graph_consensus.md",
                "scip/call_graph_execution.md",
            ),
        )

    xref = root / "scip" / "xref_map.md"
    if xref.is_file() and xref.stat().st_size > 0:
        _append(
            "symmetric_pair",
            "symmetric_pair_findings.md",
            ["Enumerate every generic semantic counterpart in the bound xref map."],
            sources=("scip/xref_map.md",),
        )
    if _field_validation_sweep_relevant(root):
        _append(
            "field_validation",
            "field_validation_matrix.md",
            ["Enumerate the complete externally supplied field denominator."],
            sources=(
                "scip/repo_map.md",
                "scip/type_hierarchy.md",
                "scip/xref_map.md",
            ),
        )
    if _primitive_sweep_relevant(root):
        _append(
            "primitive_correctness",
            "primitive_correctness_findings.md",
            ["Enumerate every primitive/serialization candidate in the repo map."],
            sources=("scip/repo_map.md", "scip/xref_map.md"),
        )
    if _network_amplification_sweep_relevant(root):
        _append(
            "network_amplification",
            "network_amplification_findings.md",
            ["Enumerate ingress-to-egress network amplification paths."],
            sources=(
                "scip/call_graph_p2p.md",
                "scip/concurrency_inventory.md",
                "scip/xref_map.md",
            ),
        )
    if _lifecycle_replay_sweep_relevant(root):
        _append(
            "lifecycle_replay",
            "lifecycle_replay_findings.md",
            ["Enumerate cache lifecycles and signed/identity replay surfaces."],
            sources=(
                "scip/repo_map.md",
                "scip/xref_map.md",
                "scip/call_graph_consensus.md",
                "scip/call_graph_p2p.md",
                "scip/concurrency_inventory.md",
            ),
        )

    for job in jobs:
        queue_payload = {
            "schema": "plamen.l1_graph_sweep_queue.v1",
            "agent_id": job["agent_id"],
            "role": job["role"],
            "output": job["output"],
            "source_artifacts": job["sources"],
            "row_count": len(job["rows"]),
            "rows": job["rows"],
        }
        queue_payload["queue_sha256"] = hashlib.sha256(
            json.dumps(
                queue_payload,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
            ).encode("utf-8")
        ).hexdigest()
        (root / str(job["queue"])).write_text(
            json.dumps(
                queue_payload,
                indent=2,
                sort_keys=True,
                ensure_ascii=False,
            )
            + "\n",
            encoding="utf-8",
            newline="\n",
        )

    public_jobs = [
        {key: value for key, value in job.items() if key != "rows"}
        for job in jobs
    ]
    plan = {
        "schema": "plamen.l1_graph_sweep_plan.v1",
        "pipeline": "l1",
        "mode": "thorough",
        "ecosystem": str(config.get("language") or "unknown"),
        "coverage_denominator": (
            int(float(stats.get("uncited") or 0)) if low_coverage else 0
        ),
        "panic_denominator": len(panic_rows),
        "expected_outputs": [str(job["output"]) for job in jobs],
        "jobs": public_jobs,
    }
    plan["plan_sha256"] = hashlib.sha256(
        json.dumps(
            plan,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    ).hexdigest()
    (root / "_graph_sweep_plan.json").write_text(
        json.dumps(plan, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return public_jobs


def _build_l1_graph_sweep_worker_prompt(
    *,
    job: dict[str, Any],
    scratchpad: Path,
    project_root: str,
    config: dict,
    attempt: int,
    retry_reasons: list[str] | None = None,
) -> str:
    output = str(job["output"])
    queue = str(job["queue"])
    role = str(job["role"])
    agent_id = str(job["agent_id"])
    retry = ""
    if retry_reasons:
        retry = "\n".join(f"- {value}" for value in retry_reasons)
        retry = f"\n## Previous Gate Failure\n\n{retry}\n"
    role_method = {
        "coverage_fill": (
            "For every assigned file row, inspect every function and record "
            "boundary/length validation, panic safety, authentication before "
            "state, amplification/loop bounds, and serialization symmetry. "
            "Give every assigned row an evidence-backed disposition."
        ),
        "panic_audit": (
            "For every assigned panic/unwrap/expect/assert row, determine "
            "reachability and input control. Use only SAFE, EXPLOITABLE, or "
            "NEEDS_REVIEW; SAFE requires concrete exclusion evidence."
        ),
        "symmetric_pair": (
            "Mechanically enumerate semantic counterparts such as encode/decode, "
            "accept/reject, insert/remove, request/respond, and validate/produce. "
            "Audit inverted preconditions and asymmetric state effects."
        ),
        "field_validation": (
            "Enumerate externally supplied objects and every field. Trace replay, "
            "identity/signature/domain/parent/time/length/persistence binding. "
            "A row may be SAFE only with a concrete validator path."
        ),
        "primitive_correctness": (
            "Enumerate every bound primitive candidate and apply edge vectors for "
            "empty/singleton/multi-element cases, exact lengths, all-input "
            "influence, encode/decode cursor equality, numeric boundaries, "
            "determinism, domain separation, and early rejection."
        ),
        "network_amplification": (
            "Enumerate each ingress-to-egress path with dedup, validation, egress "
            "fanout, timeout/concurrency bounds, and success/failure semantics."
        ),
        "lifecycle_replay": (
            "Enumerate every cache object's insert/consume/evict/error/reorg/expiry "
            "legs and every identity-bearing message's replay, sender, domain, "
            "and consumption binding."
        ),
    }[role]
    prompt = f"""# L1 GRAPH-SWEEP ROW WORKER

You are one bounded L1 graph-sweep worker launched directly by the Python
driver. You are already the worker: do not spawn agents or act as a coordinator.

## Assignment

- PROJECT_ROOT: `{project_root}`
- SCRATCHPAD: `{scratchpad.as_posix()}`
- Agent ID: `{agent_id}`
- Role: `{role}`
- Queue: `{scratchpad.as_posix()}/{queue}`
- Output: `{output}`
- Attempt: `{attempt}`

## Output Allowlist

Write exactly this file and no other scratchpad artifact:

`{scratchpad.as_posix()}/{output}`

Do not write `graph_sweep_summary.md`, `panic_audit_summary.md`, inventory,
verification, report, another worker's output, or any coordination artifact.
The driver owns plan construction and deterministic summaries.
{retry}
## Exact Denominator

Read `_graph_sweep_plan.json` and your exact queue `{queue}`. Preserve and
disposition every queue row. Read only the bound supporting graph/recon
artifacts named by the queue and project source necessary to resolve those
rows. Missing edges remain `NEEDS_REVIEW`; they are never a SAFE conclusion.

## Method

{role_method}

Do not run tests, fuzzers, PoCs, builds, package managers, graph generators,
static analyzers, or verification commands in this discovery phase.

## Required File Contract

Start with these exact transport markers:

`<!-- PLAMEN_ARTIFACT: {output} -->`
`<!-- PLAMEN_OWNER: {agent_id} -->`
`<!-- PLAMEN_STATUS: IN_PROGRESS -->`
`<!-- PLAMEN_PHASE: graph_sweeps -->`
`<!-- PLAMEN_VERSION: 1 -->`
`<!-- GRAPH_SWEEP_ROLE: {role} -->`
`<!-- EXPECTED_OUTPUT: {output} -->`

Include the exact queue digest and one disposition for every assigned row.
Findings must use the normal finding format and concrete file:line evidence. End with
`<!-- PLAMEN_STATUS: COMPLETE -->` only after verifying the file on disk.

When done, return exactly:

`DONE: {output} complete`
"""
    return _compile_typed_worker_prompt(
        prompt,
        config=config,
        phase_name="graph_sweeps",
        agent_id=agent_id,
        output=output,
        attempt=attempt,
    )


def _l1_graph_sweep_output_complete(
    scratchpad: Path,
    job: Mapping[str, Any],
) -> tuple[bool, list[str]]:
    output = str(job["output"])
    path = Path(scratchpad) / output
    if not path.is_file():
        return False, ["missing"]
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        return False, [f"unreadable: {exc}"]
    issues: list[str] = []
    if len(text.encode("utf-8", errors="ignore")) < 200:
        issues.append("stub or too small")
    for marker in (
        f"PLAMEN_ARTIFACT: {output}",
        f"PLAMEN_OWNER: {job['agent_id']}",
        "PLAMEN_PHASE: graph_sweeps",
        "PLAMEN_STATUS: COMPLETE",
    ):
        if marker not in text:
            issues.append(f"missing marker {marker}")
    return not issues, issues


def _strip_l1_graph_transport(text: str) -> str:
    return re.sub(
        r"(?m)^\s*<!--\s*(?:PLAMEN_(?:ARTIFACT|OWNER|STATUS|PHASE|VERSION)|"
        r"AGENT_ROW|EXPECTED_OUTPUT|GRAPH_SWEEP_ROLE)\s*:.*?-->\s*$",
        "",
        text,
    ).strip()


def _finalize_l1_graph_sweep_outputs(
    scratchpad: Path,
    config: dict,
    jobs: Sequence[Mapping[str, Any]],
) -> set[str]:
    """Write timestamp-free summaries without rewriting worker findings."""
    root = Path(scratchpad)
    written: set[str] = set()
    panic_sections: list[str] = []
    lines = [
        "# Graph-Sharded Audit Sweeps",
        "",
        "**Status**: COMPLETE",
        "",
        "## Exact Worker Denominator",
        "",
    ]
    for job in jobs:
        output = str(job["output"])
        path = root / output
        size = path.stat().st_size if path.is_file() else 0
        state = f"committed ({size} bytes)" if size else "missing"
        lines.append(
            f"- `{job['agent_id']}` / `{job['role']}` -> `{output}`: {state}"
        )
        if str(job["role"]) == "panic_audit" and path.is_file():
            panic_sections.append(
                f"## {output}\n\n"
                + _strip_l1_graph_transport(
                    path.read_text(encoding="utf-8", errors="replace")
                )
            )
    lines.extend(
        [
            "",
            "## Handoff",
            "",
            "Every detected sweep surface was converted into an exact driver-owned "
            "queue and a single-writer model leaf. Missing outputs remain explicit "
            "phase debt; this summary never converts absence into a safe verdict.",
            "",
        ]
    )
    (root / "graph_sweep_summary.md").write_text(
        "\n".join(lines).rstrip() + "\n",
        encoding="utf-8",
        newline="\n",
    )
    written.add("graph_sweep_summary.md")
    if panic_sections:
        (root / "panic_audit_summary.md").write_text(
            "# Panic Audit Summary\n\n"
            "This is a lossless deterministic projection of every panic shard; "
            "EXPLOITABLE and NEEDS_REVIEW rows remain visible below.\n\n"
            + "\n\n".join(panic_sections)
            + "\n",
            encoding="utf-8",
            newline="\n",
        )
        written.add("panic_audit_summary.md")
    return written


_L1_LOCATION_WORKLIST_OUTPUTS = (
    "_location_recovery_worklist.json",
    "_location_recovery_inventory_preimage.md",
)


def _l1_location_driver_contract_and_launch(
    config: Mapping[str, Any],
    *,
    work_unit_id: str,
    outputs: tuple[str, ...],
) -> tuple[PhaseIOContract, LaunchSpec]:
    contract = resolve_phase_io_contract(
        pipeline="l1",
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="location_recovery",
        work_unit_id=work_unit_id,
        exact_outputs=outputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=30,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _validate_l1_location_worklist(root: Path) -> list[str]:
    try:
        payload = json.loads(
            (root / "_location_recovery_worklist.json").read_text(
                encoding="utf-8"
            )
        )
        preimage = (
            root / "_location_recovery_inventory_preimage.md"
        ).read_bytes()
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        return [
            "location-recovery worklist unreadable: "
            f"{type(exc).__name__}: {exc}"
        ]
    if payload.get("schema") != "plamen.l1_location_recovery_worklist.v1":
        return ["location-recovery worklist schema is invalid"]
    expected = payload.get("expected_finding_ids")
    rows = payload.get("rows")
    if not isinstance(expected, list) or not isinstance(rows, list):
        return ["location-recovery worklist denominator is malformed"]
    row_ids = [
        str(row.get("finding_id") or "")
        for row in rows
        if isinstance(row, dict)
    ]
    if row_ids != expected or len(expected) != len(set(expected)):
        return ["location-recovery worklist row/ID parity failed"]
    actual_sha = hashlib.sha256(preimage).hexdigest()
    if payload.get("inventory_preimage_sha256") != actual_sha:
        return ["location-recovery inventory preimage digest mismatch"]
    return []


def _run_l1_location_recovery_worklist_transaction(
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    """Freeze the exact unresolved-ID denominator before model launch."""
    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["location-recovery worklist transaction has no run_id"]
    try:
        contract, launch = _l1_location_driver_contract_and_launch(
            config,
            work_unit_id="worklist",
            outputs=_L1_LOCATION_WORKLIST_OUTPUTS,
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return list(dict.fromkeys(issues))
        if not execute:
            return _validate_l1_location_worklist(root)

        inventory_path = root / "findings_inventory.md"
        inventory_bytes = inventory_path.read_bytes()
        records = _validate_inventory_evidence(root, str(project_root))
        rows: list[dict[str, str]] = []
        for raw_id, raw_record in sorted(records.items()):
            record = raw_record if isinstance(raw_record, Mapping) else {}
            if str(record.get("location_status") or "").upper() in {
                "OK",
                "RECOVERED_BASENAME",
            }:
                continue
            finding_id = (
                _normalize_finding_id(str(raw_id)) or str(raw_id).strip()
            )
            rows.append(
                {
                    "finding_id": finding_id,
                    "location": str(record.get("location") or ""),
                    "location_status": str(
                        record.get("location_status") or "UNRESOLVED"
                    ),
                    "source_status": str(
                        record.get("source_status") or "UNKNOWN"
                    ),
                }
            )
        payload: dict[str, Any] = {
            "schema": "plamen.l1_location_recovery_worklist.v1",
            "inventory_preimage_sha256": hashlib.sha256(
                inventory_bytes
            ).hexdigest(),
            "expected_finding_ids": [
                row["finding_id"] for row in rows
            ],
            "rows": rows,
        }
        payload["worklist_sha256"] = hashlib.sha256(
            json.dumps(
                payload,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
            ).encode("utf-8")
        ).hexdigest()
        _atomic_driver_bytes(
            root / "_location_recovery_inventory_preimage.md",
            inventory_bytes,
        )
        _atomic_driver_bytes(
            root / "_location_recovery_worklist.json",
            (
                json.dumps(
                    payload,
                    indent=2,
                    sort_keys=True,
                    ensure_ascii=False,
                )
                + "\n"
            ).encode("utf-8"),
        )
        validation = _validate_l1_location_worklist(root)
        if validation:
            return validation
        return _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
    except (
        ArtifactLedgerError,
        OSError,
        RuntimeError,
        ValueError,
    ) as exc:
        return [
            "location-recovery worklist transaction failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _escape_location_recovery_cell(value: object) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip().replace("|", r"\|")


def _derive_l1_location_recovery_projection(
    root: Path,
    project_root: Path,
) -> bytes:
    worklist = json.loads(
        (root / "_location_recovery_worklist.json").read_text(
            encoding="utf-8"
        )
    )
    proposal_text = (
        root / "location_recovery_proposals.md"
    ).read_text(encoding="utf-8", errors="replace")
    headers, proposal_rows = _parse_markdown_table(
        proposal_text,
        ["finding id", "verdict", "new location", "evidence"],
    )
    keys = [_norm_key(header) for header in headers]
    proposals: dict[str, list[dict[str, str]]] = {}
    for row in proposal_rows:
        record = {
            keys[index]: row[index].strip()
            for index in range(min(len(keys), len(row)))
        }
        finding_id = (
            _normalize_finding_id(record.get("finding id", ""))
            or record.get("finding id", "").strip()
        )
        if finding_id:
            proposals.setdefault(finding_id, []).append(record)

    source_index = _project_source_index(str(project_root))
    output_rows: list[str] = []
    for work_row in worklist.get("rows") or []:
        finding_id = str(work_row.get("finding_id") or "")
        candidates = proposals.get(finding_id, [])
        verdict = "UNRECOVERED"
        location = ""
        evidence = "MODEL_OMISSION"
        if len(candidates) > 1:
            evidence = "DUPLICATE_PROPOSALS"
        elif len(candidates) == 1:
            candidate = candidates[0]
            proposed_verdict = str(candidate.get("verdict") or "").upper()
            proposed_location = str(candidate.get("new location") or "").strip()
            proposed_evidence = str(candidate.get("evidence") or "").strip()
            if proposed_verdict == "RECOVERED" and proposed_location:
                status, resolved, reason = _resolve_inventory_location(
                    str(project_root), source_index, proposed_location
                )
                if status in {"OK", "RECOVERED_BASENAME"} and resolved:
                    verdict = "RECOVERED"
                    location = resolved
                    evidence = proposed_evidence or "MECHANICALLY_RESOLVED"
                else:
                    evidence = (
                        "INVALID_RECOVERY_LOCATION: "
                        + (reason or proposed_location)
                    )
            elif proposed_verdict == "UNRECOVERED":
                evidence = proposed_evidence or "MODEL_UNRECOVERED"
            else:
                evidence = "INVALID_MODEL_VERDICT"
        output_rows.append(
            "| "
            + " | ".join(
                _escape_location_recovery_cell(value)
                for value in (
                    finding_id,
                    verdict,
                    location,
                    evidence,
                )
            )
            + " |"
        )
    text = (
        "# Location Recovery\n\n"
        "This canonical table is a deterministic projection of the exact "
        "unresolved-finding worklist. Model recovery claims are accepted only "
        "when the proposed source location resolves mechanically.\n\n"
        "| Finding ID | Verdict | New Location | Evidence |\n"
        "|---|---|---|---|\n"
        + "\n".join(output_rows)
        + "\n"
    )
    return text.encode("utf-8")


def _run_l1_location_recovery_reconcile_transaction(
    scratchpad: Path,
    config: dict[str, Any],
) -> list[str]:
    root = Path(scratchpad)
    project_root = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "").strip()
    if not run_id:
        return ["location-recovery reconciliation has no run_id"]
    try:
        contract, launch = _l1_location_driver_contract_and_launch(
            config,
            work_unit_id="reconcile",
            outputs=("location_recovery.md",),
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return list(dict.fromkeys(issues))
        if execute:
            _atomic_driver_bytes(
                root / "location_recovery.md",
                _derive_l1_location_recovery_projection(
                    root, project_root
                ),
            )
        projection = (
            root / "location_recovery.md"
        ).read_text(encoding="utf-8", errors="replace")
        expected = json.loads(
            (root / "_location_recovery_worklist.json").read_text(
                encoding="utf-8"
            )
        ).get("expected_finding_ids") or []
        projected = re.findall(
            r"(?m)^\|\s*(INV-[A-Za-z0-9_-]+)\s*\|",
            projection,
        )
        if projected != expected:
            return [
                "location-recovery canonical projection denominator mismatch"
            ]
        if not execute:
            return []
        return _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
    except (
        ArtifactLedgerError,
        OSError,
        RuntimeError,
        ValueError,
        json.JSONDecodeError,
    ) as exc:
        return [
            "location-recovery reconciliation failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _build_l1_location_recovery_proposal_prompt(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    attempt: int,
    retry_reasons: list[str] | None = None,
) -> str:
    output = "location_recovery_proposals.md"
    retry = ""
    if retry_reasons:
        retry = (
            "\n## Previous Gate Failure\n\n"
            + "\n".join(f"- {reason}" for reason in retry_reasons)
            + "\n"
        )
    prompt = f"""# L1 LOCATION-RECOVERY PROPOSAL WORKER

You are a bounded evidence-recovery worker launched directly by the Python
driver. There is no coordinator. Do not spawn agents.

## Assignment

- PROJECT_ROOT: `{project_root}`
- SCRATCHPAD: `{scratchpad.as_posix()}`
- Exact worklist: `{scratchpad.as_posix()}/_location_recovery_worklist.json`
- Frozen inventory preimage:
  `{scratchpad.as_posix()}/_location_recovery_inventory_preimage.md`
- Output: `{output}`
- Attempt: `{attempt}`

## Output Allowlist

Write exactly this file and no other scratchpad artifact:

`{scratchpad.as_posix()}/{output}`

Do not edit canonical `location_recovery.md`, `findings_inventory.md`, source,
graph artifacts, manifests, or later-phase files. The driver validates every
proposed location and owns the canonical projection.
{retry}
## Exact Method

Process every `expected_finding_ids` row in the bound worklist exactly once.
Use the frozen finding title/location/source provenance, `scip/repo_map.md`,
and targeted read-only source searches to locate the cited root cause.

Write exactly one Markdown table:

`| Finding ID | Verdict | New Location | Evidence |`

Verdict is only `RECOVERED` or `UNRECOVERED`. A RECOVERED row requires a
project-relative source path with a line number and concrete source evidence.
UNRECOVERED is preferable to a guessed path. Do not assess exploitability,
severity, safety, or false-positive status and do not generate new findings.
Do not run tests, fuzzers, PoCs, builds, package managers, graph generators,
or verification commands.

## Required File Contract

Start with:

`<!-- PLAMEN_ARTIFACT: {output} -->`
`<!-- PLAMEN_OWNER: location_recovery -->`
`<!-- PLAMEN_STATUS: IN_PROGRESS -->`
`<!-- PLAMEN_PHASE: location_recovery -->`
`<!-- PLAMEN_VERSION: 1 -->`
`<!-- EXPECTED_OUTPUT: {output} -->`

End with `<!-- PLAMEN_STATUS: COMPLETE -->` only after every exact worklist ID
has one row and the file is verified on disk.

When done, return exactly:

`DONE: {output} complete`
"""
    return _compile_typed_worker_prompt(
        prompt,
        config=config,
        phase_name="location_recovery",
        agent_id="location_recovery",
        output=output,
        attempt=attempt,
    )


def _l1_location_proposal_complete(
    scratchpad: Path,
) -> tuple[bool, list[str]]:
    root = Path(scratchpad)
    proposal = root / "location_recovery_proposals.md"
    if not proposal.is_file():
        return False, ["missing"]
    try:
        text = proposal.read_text(encoding="utf-8", errors="replace")
        worklist = json.loads(
            (root / "_location_recovery_worklist.json").read_text(
                encoding="utf-8"
            )
        )
    except (OSError, json.JSONDecodeError) as exc:
        return False, [f"unreadable: {exc}"]
    issues: list[str] = []
    if len(text.encode("utf-8", errors="ignore")) < 200:
        issues.append("stub or too small")
    for marker in (
        "PLAMEN_ARTIFACT: location_recovery_proposals.md",
        "PLAMEN_OWNER: location_recovery",
        "PLAMEN_PHASE: location_recovery",
        "PLAMEN_STATUS: COMPLETE",
    ):
        if marker not in text:
            issues.append(f"missing marker {marker}")
    headers, rows = _parse_markdown_table(
        text,
        ["finding id", "verdict", "new location", "evidence"],
    )
    if not headers:
        issues.append("missing exact recovery proposal table")
    else:
        keys = [_norm_key(header) for header in headers]
        row_ids = []
        for row in rows:
            record = {
                keys[index]: row[index].strip()
                for index in range(min(len(keys), len(row)))
            }
            finding_id = (
                _normalize_finding_id(record.get("finding id", ""))
                or record.get("finding id", "").strip()
            )
            if finding_id:
                row_ids.append(finding_id)
        expected = worklist.get("expected_finding_ids") or []
        if row_ids != expected:
            issues.append(
                "proposal/worklist denominator mismatch: "
                f"expected={expected!r} actual={row_ids!r}"
            )
    return not issues, issues


def _recon_worker_complete(
    scratchpad: Path,
    output: str,
    job: dict[str, str] | None = None,
    config: Mapping[str, Any] | None = None,
) -> tuple[bool, list[str]]:
    p = scratchpad / output
    reasons: list[str] = []
    if not p.exists():
        return False, ["missing"]
    try:
        text = p.read_text(encoding="utf-8", errors="replace")
    except Exception as exc:
        return False, [f"unreadable: {exc}"]
    if p.stat().st_size < 400:
        reasons.append("stub or too small")
    if f"PLAMEN_ARTIFACT: {output}" not in text:
        reasons.append(f"missing marker PLAMEN_ARTIFACT: {output}")
    if "PLAMEN_PHASE: recon" not in text:
        reasons.append("missing marker PLAMEN_PHASE: recon")
    if "PLAMEN_STATUS: COMPLETE" not in text:
        reasons.append("missing COMPLETE marker")
    if job is not None:
        expected_owner = str(job.get("agent_id") or "")
        expected_role = str(job.get("role") or "")
        if expected_owner and f"PLAMEN_OWNER: {expected_owner}" not in text:
            reasons.append(f"missing marker PLAMEN_OWNER: {expected_owner}")
        if expected_role and f"RECON_ROLE: {expected_role}" not in text:
            reasons.append(f"missing marker RECON_ROLE: {expected_role}")
        if f"EXPECTED_OUTPUT: {output}" not in text:
            reasons.append(f"missing marker EXPECTED_OUTPUT: {output}")
        if expected_role in {
            "templates_patterns",
            "inventory_templates",
            "l1_templates_patterns",
            "l1_build_templates",
        } and config is not None:
            root = plamen_home()
            rows = bindable_skill_selection_rows(
                skill_index_path=root / "rules" / "skill-index.md",
                skill_root=root / "agents" / "skills",
                ecosystem=str(config.get("language") or "unknown"),
                pipeline=str(config.get("pipeline") or "sc"),
            )
            reasons.extend(
                "skill selection signal: "
                + json.dumps(issue, sort_keys=True, separators=(",", ":"))
                for issue in selection_signal_issues(
                    text, rows, required=True
                )
            )
    return not reasons, reasons


def _install_recon_command_guard(scratchpad: Path, env: dict[str, str]) -> dict[str, str]:
    """Prepend recon-only command wrappers that block later-phase fanout.

    Prompt boundaries are necessary but not sufficient when Claude runs with
    Bash permissions. Recon build diagnosis needs `forge build`, while dependency
    materialization must finish before snapshot binding and tests/fuzzers belong to
    later phases. These wrappers make that boundary deterministic for common
    EVM tool commands without blocking normal file-inspection tools.
    """
    guarded = dict(env)
    guard_dir = scratchpad / "_recon_command_guard"
    try:
        guard_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        return guarded

    def _real(name: str) -> str:
        value = shutil.which(name, path=env.get("PATH") or os.environ.get("PATH"))
        return Path(value).as_posix() if value else ""

    reals = {
        "forge": _real("forge"),
        "npx": _real("npx"),
        "npm": _real("npm"),
        "yarn": _real("yarn"),
        "git": _real("git"),
        "slither": _real("slither"),
    }
    for key, value in reals.items():
        if value:
            guarded[f"PLAMEN_REAL_{key.upper()}"] = value

    scripts: dict[str, str] = {
        "forge": r'''#!/usr/bin/env bash
set -euo pipefail
real="${PLAMEN_REAL_FORGE:-}"
if [[ -z "$real" ]]; then echo "PLAMEN_RECON_COMMAND_BLOCKED: real forge not found" >&2; exit 127; fi
sub="${1:-}"
case "$sub" in
  build)
    has_path=0
    for arg in "${@:2}"; do
      case "$arg" in
        -*|[0-9]*) ;;
        *.sol|contracts/*|src/*) has_path=1 ;;
      esac
    done
    if [[ "$has_path" == "0" && ( -d "test" || -d "tests" || -d ".medusa-tests" || -d "contracts/.medusa-tests" ) ]]; then
      echo "PLAMEN_RECON_COMMAND_BLOCKED: bare forge build would include test/fuzz surfaces; pass explicit production contract paths during recon" >&2
      exit 126
    fi
    guard_root="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    lock_dir="${PLAMEN_RECON_BUILD_LOCK:-$guard_root/forge_build.lock}"
    if ! mkdir "$lock_dir" 2>/dev/null; then
      echo "PLAMEN_RECON_COMMAND_BLOCKED: concurrent forge build already running or previous recon build timed out; recon must not stack compiler processes" >&2
      exit 126
    fi
    trap 'rmdir "$lock_dir" 2>/dev/null || true' EXIT INT TERM
    "$real" "$@"
    ;;
  remappings|config|clean|--version|-V|--help|-h)
    exec "$real" "$@"
    ;;
  install|soldeer)
    echo "PLAMEN_RECON_COMMAND_BLOCKED: forge install mutates bound audit inputs; dependency materialization must occur before snapshot binding" >&2
    exit 126
    ;;
  test|coverage|snapshot|script|create|verify-contract)
    echo "PLAMEN_RECON_COMMAND_BLOCKED: forge $sub is a later-phase verification/test command; recon is diagnosis-only" >&2
    exit 126
    ;;
  *)
    echo "PLAMEN_RECON_COMMAND_BLOCKED: forge $sub is outside recon build-repair allowlist" >&2
    exit 126
    ;;
esac
''',
        "npx": r'''#!/usr/bin/env bash
set -euo pipefail
real="${PLAMEN_REAL_NPX:-}"
if [[ -z "$real" ]]; then echo "PLAMEN_RECON_COMMAND_BLOCKED: real npx not found" >&2; exit 127; fi
args=" $* "
if [[ "$args" == *" test"* || "$args" == *" forge test"* || "$args" == *" hardhat test"* ]]; then
  echo "PLAMEN_RECON_COMMAND_BLOCKED: npx test/verification commands are not allowed during recon" >&2
  exit 126
fi
if [[ "${1:-}" == "hardhat" && ( "${2:-}" == "compile" || "${2:-}" == "clean" || "${2:-}" == "--version" ) ]]; then
  exec "$real" "$@"
fi
echo "PLAMEN_RECON_COMMAND_BLOCKED: npx is limited to hardhat compile/clean/version during recon" >&2
exit 126
''',
        "npm": r'''#!/usr/bin/env bash
set -euo pipefail
real="${PLAMEN_REAL_NPM:-}"
if [[ -z "$real" ]]; then echo "PLAMEN_RECON_COMMAND_BLOCKED: real npm not found" >&2; exit 127; fi
case "${1:-}" in
  --version|-v) exec "$real" "$@" ;;
  install|ci) echo "PLAMEN_RECON_COMMAND_BLOCKED: dependency installation mutates bound audit inputs; materialize before snapshot binding" >&2; exit 126 ;;
  *) echo "PLAMEN_RECON_COMMAND_BLOCKED: npm is limited to version probes during recon" >&2; exit 126 ;;
esac
''',
        "yarn": r'''#!/usr/bin/env bash
set -euo pipefail
real="${PLAMEN_REAL_YARN:-}"
if [[ -z "$real" ]]; then echo "PLAMEN_RECON_COMMAND_BLOCKED: real yarn not found" >&2; exit 127; fi
case "${1:-}" in
  --version|-v) exec "$real" "$@" ;;
  install) echo "PLAMEN_RECON_COMMAND_BLOCKED: dependency installation mutates bound audit inputs; materialize before snapshot binding" >&2; exit 126 ;;
  *) echo "PLAMEN_RECON_COMMAND_BLOCKED: yarn is limited to version probes during recon" >&2; exit 126 ;;
esac
''',
        "git": r'''#!/usr/bin/env bash
set -euo pipefail
real="${PLAMEN_REAL_GIT:-}"
if [[ -z "$real" ]]; then echo "PLAMEN_RECON_COMMAND_BLOCKED: real git not found" >&2; exit 127; fi
if [[ "${1:-}" == "submodule" && "${2:-}" == "update" ]]; then
  echo "PLAMEN_RECON_COMMAND_BLOCKED: submodule update mutates bound audit inputs; materialize before snapshot binding" >&2
  exit 126
fi
if [[ "${1:-}" == "rev-list" || "${1:-}" == "status" ]]; then exec "$real" "$@"; fi
echo "PLAMEN_RECON_COMMAND_BLOCKED: git is limited to read-only status/rev-list during recon" >&2
exit 126
''',
        "slither": r'''#!/usr/bin/env bash
set -euo pipefail
real="${PLAMEN_REAL_SLITHER:-}"
if [[ -z "$real" ]]; then echo "PLAMEN_RECON_COMMAND_BLOCKED: real slither not found" >&2; exit 127; fi
case "${1:-}" in
  --version|-V|version) exec "$real" "$@" ;;
  *) echo "PLAMEN_RECON_COMMAND_BLOCKED: slither target/detector runs are not allowed during recon worker build repair" >&2; exit 126 ;;
esac
''',
    }
    deny_all = r'''#!/usr/bin/env bash
echo "PLAMEN_RECON_COMMAND_BLOCKED: this fuzzer/verification command is not allowed during recon" >&2
exit 126
'''
    for name in ("medusa", "echidna", "halmos"):
        scripts[name] = deny_all
    deny_compiler_mutation = r'''#!/usr/bin/env bash
echo "PLAMEN_RECON_COMMAND_BLOCKED: compiler installation/selection mutates the bound toolchain; materialize before snapshot binding" >&2
exit 126
'''
    for name in ("svm", "solc-select"):
        scripts[name] = deny_compiler_mutation

    for name, body in scripts.items():
        try:
            path = guard_dir / name
            path.write_text(body, encoding="utf-8", newline="\n")
            try:
                path.chmod(0o755)
            except Exception:
                pass
        except Exception:
            pass

    old_path = guarded.get("PATH") or os.environ.get("PATH") or ""
    guarded["PATH"] = str(guard_dir) + os.pathsep + old_path
    guarded["PLAMEN_RECON_COMMAND_GUARD"] = str(guard_dir)
    return guarded


def _run_single_recon_worker_pty(
    *,
    job: dict[str, str],
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
    retry_reasons: list[str] | None = None,
    allowed_outputs: list[str] | None = None,
    protected_input_names: set[str] | None = None,
    inputs_prebound: bool = False,
) -> dict[str, Any]:
    output = job["output"]
    allowed_output_set = set(allowed_outputs or [output])
    protected_input_set = set(protected_input_names or set())
    if not inputs_prebound:
        fatal_binding_issues = _prepare_typed_model_worker_launch(
            phase=phase,
            config=config,
            scratchpad=scratchpad,
            project_root=project_root,
            agent_id=str(job.get("agent_id") or output),
            agent_role=str(job.get("role") or "") or None,
            focus_area=str(job.get("focus") or ""),
            output=output,
            timeout_s=timeout,
            attempt=attempt,
        )
        if fatal_binding_issues:
            return {
                "output": output,
                "rc": -2,
                "status": "input_authority_debt",
                "reasons": fatal_binding_issues,
            }
    session_id = str(uuid.uuid4())
    try:
        prompt = _build_recon_worker_prompt(
            job=job,
            scratchpad=scratchpad,
            project_root=project_root,
            config=config,
            attempt=attempt,
            retry_reasons=retry_reasons,
        )
        snap = scratchpad / (
            f"_prompt_recon_worker_{Path(output).stem}.attempt{attempt}.md"
        )
        snap.write_text(prompt, encoding="utf-8", newline="\n")
    except (ArtifactLedgerError, OSError, RuntimeError, TypeError, ValueError) as exc:
        issue = f"retry prompt authority invalid: {exc}"
        _append_phase_io_debt(
            scratchpad,
            "recon",
            "RECON_WORKER_PRESPAWN_INPUT_DEBT",
            f"{output}: {issue}",
        )
        return {
            "output": output,
            "rc": -2,
            "status": "input_authority_debt",
            "reasons": [issue],
        }
    pre_spawn_issues = _validate_typed_model_worker_inputs(
        phase=phase,
        config=config,
        scratchpad=scratchpad,
        project_root=project_root,
        agent_id=str(job.get("agent_id") or output),
        output=output,
        timeout_s=timeout,
        attempt=attempt,
    )
    fatal_pre_spawn_issues = [
        issue for issue in pre_spawn_issues
        if _typed_worker_input_issue_is_fatal(output, issue)
    ]
    if fatal_pre_spawn_issues:
        for issue in fatal_pre_spawn_issues:
            _append_phase_io_debt(
                scratchpad,
                "recon",
                "RECON_WORKER_PRESPAWN_INPUT_DEBT",
                f"{output}: {issue}",
            )
        return {
            "output": output,
            "rc": -2,
            "status": "input_authority_debt",
            "reasons": fatal_pre_spawn_issues,
        }
    cmd = _build_fresh_session_cmd(base_cmd, session_id)
    cmd = _rewrite_argv_positional_prompt(cmd, snap)
    worker_env = _install_recon_command_guard(scratchpad, env)
    log_path = scratchpad / (
        f"_stdio_recon_worker_{Path(output).stem}.attempt{attempt}.log"
    )
    known_stats: dict[str, tuple[int, int]] = {}
    try:
        for p in scratchpad.iterdir():
            if p.is_file() and not p.name.startswith("_"):
                try:
                    st = p.stat()
                    known_stats[p.name] = (st.st_size, st.st_mtime_ns)
                except OSError:
                    known_stats[p.name] = (0, 0)
    except Exception:
        known_stats = {}

    def _worker_poll(_now: float, _state: Any) -> None:
        try:
            for p in scratchpad.iterdir():
                if p.name.startswith("_") or not p.is_file():
                    continue
                known_names = set(known_stats)
                try:
                    st = p.stat()
                    sig = (st.st_size, st.st_mtime_ns)
                except OSError:
                    sig = (0, 0)
                old_sig = known_stats.get(p.name)
                known_stats[p.name] = sig
                if _worker_artifact_name_allowed(p.name, allowed_output_set):
                    continue
                if old_sig == sig:
                    continue
                if p.name in protected_input_set:
                    continue
                if _worker_artifact_is_benign_duplicate_copy(p.name, known_names):
                    moved = _quarantine_worker_duplicate_copy(
                        scratchpad=scratchpad,
                        path=p,
                        phase_name="recon",
                        worker_output=output,
                    )
                    if moved is not None:
                        log.info(
                            "[recon] worker %s quarantined benign duplicate "
                            "scratchpad copy: %s -> %s",
                            output,
                            p.name,
                            moved.relative_to(scratchpad).as_posix(),
                        )
                    continue
                log.error(
                    "[recon] worker %s wrote or modified out-of-scope artifact: %s",
                    output,
                    p.name,
                )
                raise _PtyStop(-4)
        except _PtyStop:
            raise
        except Exception:
            pass

    with log_path.open("w", encoding="utf-8", errors="replace") as out:
        session = ClaudePtySession(
            cmd,
            cwd=project_root,
            env=worker_env,
            session_id=session_id,
            prompt_path=snap,
            log_file=out,
        )
        _register_active_worker_session(session)
        try:
            out.write(f"CLAUDE_TRANSCRIPT={session.transcript_path}\n")
            out.flush()
            if str(job.get("agent_id") or "").strip().upper() == "R-EXT":
                # Conditional dependency research is launched only after the
                # canonical recon successor replaces prepass outputs.  Its
                # exact typed worker-input binding, not the retired prepass,
                # is the applicable producer authority.
                late_issues = _validate_typed_model_worker_inputs(
                    phase=phase,
                    config=config,
                    scratchpad=scratchpad,
                    project_root=project_root,
                    agent_id=str(job.get("agent_id") or output),
                    agent_role=str(job.get("role") or "") or None,
                    output=output,
                    timeout_s=timeout,
                    attempt=attempt,
                )
                # This is the final R-EXT launch boundary.  Unlike the earlier
                # preparation pass there is no safe interval left in which a
                # soft mismatch can be repaired, so *every* replay issue is a
                # launch veto (not merely the subset classified fatal during
                # preparation).
                late_issues = [
                    str(issue).strip() for issue in late_issues
                    if str(issue).strip()
                ]
                if late_issues:
                    blocked = ReconPrepassDispatchBlocked(
                        "recon external-dependency spawn authority failed: "
                        + "; ".join(late_issues)
                    )
                    try:
                        _record_recon_prepass_dispatch_debt(
                            scratchpad, blocked
                        )
                    except Exception as debt_exc:
                        raise ReconPrepassDispatchBlocked(
                            f"{blocked}; durable failure projection failed: "
                            f"{type(debt_exc).__name__}: {debt_exc}"
                        ) from debt_exc
                    raise blocked
                session.spawn()
            else:
                _call_recon_provider_with_dispatch_authority(
                    config, scratchpad, session.spawn
                )
            session.send_bootstrap()
            state = session.wait_for_turn_complete(
                timeout,
                quiescence_s=quiescence_s,
                on_poll=_worker_poll,
            )
            if state.rate_limited:
                _finalize_depth_fuzz_workspace(scratchpad, job)
                # A transient 529/overloaded is provider-wide, NOT a 429
                # account/usage cap. It must NOT escalate to the phase-level
                # usage-cap pause that stops the whole worker pool — Claude
                # Code's own retry loop (exp backoff, up to 10x) usually
                # self-recovers it. Classify it as a retriable worker failure
                # so the gate re-spawns just this one worker. Mirrors the
                # single-subprocess overload path (detect_overloaded backoff).
                if getattr(state, "overloaded", False):
                    return {"output": output, "rc": 1, "status": "overloaded",
                            "reasons": ["transient 529 overloaded -- retriable"]}
                return {"output": output, "rc": 1, "status": "rate_limited"}
            ok, reasons = _recon_worker_complete(
                scratchpad, output, job, config
            )
            if ok:
                contract_issues = _record_typed_model_worker_artifact(
                    phase=phase,
                    config=config,
                    scratchpad=scratchpad,
                    project_root=project_root,
                    agent_id=str(job.get("agent_id") or output),
                    agent_role=str(job.get("role") or "") or None,
                    focus_area=str(job.get("focus") or ""),
                    output=output,
                    timeout_s=timeout,
                    attempt=attempt,
                )
                if contract_issues:
                    ok = False
                    reasons = [
                        *reasons,
                        *[f"typed artifact contract: {item}" for item in contract_issues],
                    ]
            return {
                "output": output,
                "rc": 0 if ok else -2,
                "status": "complete" if ok else "incomplete",
                "reasons": reasons,
                "log": str(log_path),
            }
        except ReconPrepassDispatchBlocked:
            raise
        except _PtyStop as stop:
            return {
                "output": output,
                "rc": stop.rc,
                "status": "containment",
                "reasons": ["worker wrote protected out-of-scope artifact"],
                "log": str(log_path),
            }
        except Exception as exc:
            return {
                "output": output,
                "rc": EXIT_ERROR,
                "status": "error",
                "reasons": [str(exc)],
                "log": str(log_path),
            }
        finally:
            try:
                session.terminate(grace_s=_HALT_TERMINATE_GRACE_S)
            except Exception:
                pass
            finally:
                _unregister_active_worker_session(session)
            try:
                if session.transcript_path.exists():
                    out.write("\n\n# Claude session transcript tail\n")
                    with session.transcript_path.open("rb") as tf:
                        tf.seek(0, 2)
                        size = tf.tell()
                        tf.seek(max(0, size - 65536))
                        out.write(tf.read().decode("utf-8", errors="replace"))
                    out.flush()
            except Exception:
                pass


def _driver_vector_contract_launch(
    config: Mapping[str, Any],
    *,
    work_unit_id: str,
    exact_inputs: tuple[str, ...],
    exact_outputs: tuple[str, ...],
) -> tuple[PhaseIOContract, LaunchSpec]:
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend="backend-neutral",
        phase="recon",
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
        exact_outputs=exact_outputs,
        exact_writer="DRIVER",
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _driver_vector_preexecution_authority(
    *,
    scratchpad: Path,
    project_root: Path,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    outputs: Mapping[str, bytes | None],
) -> dict[str, Any]:
    ledger = read_artifact_ledger(scratchpad)
    prestates = _output_prestate_records(
        scratchpad,
        project_root,
        contract,
        ledger,
        run_id=run_id,
    )
    ordered = tuple(spec.path for spec in contract.outputs)
    rows = []
    for name in ordered:
        raw = outputs[name]
        rows.append({
            "path": name,
            "state": "PRESENT" if raw is not None else "ABSENT",
            "sha256": hashlib.sha256(raw).hexdigest() if raw is not None else "",
            "size": len(raw) if raw is not None else 0,
        })
    unsigned = {
        "schema": "plamen.driver-output-vector-preexecution-authority.v1",
        "work_unit_key": contract.key,
        "run_id": run_id,
        "contract_digest": contract.digest,
        "launch_digest": launch.digest,
        "ordered_outputs": list(ordered),
        "output_prestates": prestates,
        "output_prestate_digest": _output_prestate_digest(prestates),
        "candidate_rows": rows,
    }
    return {**unsigned, "authority_sha256": _stable_payload_digest(unsigned)}


def _stored_preexecution_authority(
    scratchpad: Path,
    work_unit_key: str,
) -> dict[str, Any] | None:
    unit = read_artifact_ledger(scratchpad).get("work_units", {}).get(work_unit_key)
    authority = unit.get("preexecution_authority") if isinstance(unit, Mapping) else None
    return dict(authority) if isinstance(authority, Mapping) else None


def _driver_vector_reparse(metadata: os.stat_result) -> bool:
    return bool(
        int(getattr(metadata, "st_file_attributes", 0))
        & int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    )


def _driver_vector_directory_entries(
    directory: Path,
    *,
    label: str,
) -> tuple[Path, ...]:
    """Enumerate one transaction directory without legacy-path or link following."""

    metadata = rooted_io.lstat(directory)
    if (
        stat.S_ISLNK(metadata.st_mode)
        or _driver_vector_reparse(metadata)
        or not stat.S_ISDIR(metadata.st_mode)
    ):
        raise ValueError(f"{label} is not one contained regular directory")
    with rooted_io.scandir(directory) as entries:
        names = sorted(entry.name for entry in entries)
    if any(
        not name
        or name in {".", ".."}
        or Path(name).name != name
        for name in names
    ):
        raise ValueError(f"{label} contains an invalid entry name")
    return tuple(directory / name for name in names)


def _remove_driver_vector_tree(directory: Path) -> None:
    """Remove a driver-owned transaction tree without following aliases."""

    for child in _driver_vector_directory_entries(
        directory,
        label="driver vector cleanup directory",
    ):
        metadata = rooted_io.lstat(child)
        if stat.S_ISLNK(metadata.st_mode) or _driver_vector_reparse(metadata):
            raise ArtifactLedgerError(
                f"driver vector cleanup rejects symlink/reparse: {child.name}"
            )
        if stat.S_ISDIR(metadata.st_mode):
            _remove_driver_vector_tree(child)
            continue
        if (
            not stat.S_ISREG(metadata.st_mode)
            or int(getattr(metadata, "st_nlink", 1) or 1) != 1
        ):
            raise ArtifactLedgerError(
                f"driver vector cleanup rejects non-regular/multilink entry: "
                f"{child.name}"
            )
        rooted_io.unlink(child)
    rooted_io.rmdir(directory)


def _validated_driver_vector_recovery(
    *,
    descriptor_path: Path,
    pending: Path,
    scratchpad: Path,
    project_root: Path,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    ordered: tuple[str, ...],
    targets: Mapping[str, Path],
) -> tuple[dict[str, bytes | None], dict[str, bytes | None], bool]:
    """Authenticate recovery evidence before permitting any mutation/deletion."""
    descriptor_stat = rooted_io.lstat(descriptor_path)
    if (
        stat.S_ISLNK(descriptor_stat.st_mode)
        or _driver_vector_reparse(descriptor_stat)
        or not stat.S_ISREG(descriptor_stat.st_mode)
        or int(getattr(descriptor_stat, "st_nlink", 1) or 1) != 1
    ):
        raise ValueError("descriptor is not one contained regular no-follow file")
    descriptor_identity = (
        int(getattr(descriptor_stat, "st_dev", 0)),
        int(getattr(descriptor_stat, "st_ino", 0)),
    )
    for child in _driver_vector_directory_entries(
        pending,
        label="driver vector pending entry",
    ):
        child_stat = rooted_io.lstat(child)
        if stat.S_ISLNK(child_stat.st_mode) or _driver_vector_reparse(child_stat):
            raise ValueError("driver vector pending entry is a symlink/reparse")
        if not stat.S_ISREG(child_stat.st_mode):
            raise ValueError("driver vector pending entry is not a regular file")
        if int(getattr(child_stat, "st_nlink", 1) or 1) != 1:
            raise ValueError("driver vector pending entry is multilinked")
        if child != descriptor_path and (
            int(getattr(child_stat, "st_dev", 0)),
            int(getattr(child_stat, "st_ino", 0)),
        ) == descriptor_identity:
            raise ValueError("descriptor has a staged hardlink alias")
    descriptor_identity = _physical_file_identity(descriptor_path)
    raw_descriptor = rooted_io.read_bytes(
        descriptor_path,
        label="driver vector descriptor",
        require_single_link=True,
    )
    if (
        _physical_file_identity(descriptor_path) != descriptor_identity
        or rooted_io.read_bytes(
            descriptor_path,
            label="driver vector descriptor replay",
            require_single_link=True,
        )
        != raw_descriptor
    ):
        raise ValueError("descriptor changed during authentication")
    descriptor = json.loads(
        raw_descriptor.decode("utf-8"),
        object_pairs_hook=_reject_duplicate_json_pairs,
    )
    if not isinstance(descriptor, dict):
        raise ValueError("descriptor is not an object")
    canonical_raw = (
        json.dumps(descriptor, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    if canonical_raw != raw_descriptor:
        raise ValueError("descriptor encoding is not canonical")
    if set(descriptor) != {
        "schema",
        "state",
        "work_unit_key",
        "run_id",
        "contract_digest",
        "launch_digest",
        "ordered_outputs",
        "transaction_authority_sha256",
        "rows",
        "descriptor_sha256",
    }:
        raise ValueError("descriptor field denominator mismatch")
    if (
        descriptor.get("schema") != "plamen.driver-output-vector.v2"
        or descriptor.get("state") != "STAGED"
        or descriptor.get("work_unit_key") != contract.key
        or descriptor.get("run_id") != run_id
        or descriptor.get("contract_digest") != contract.digest
        or descriptor.get("launch_digest") != launch.digest
        or tuple(descriptor.get("ordered_outputs", ())) != ordered
    ):
        raise ValueError("foreign vector descriptor")
    rows = descriptor.get("rows")
    if not isinstance(rows, list) or len(rows) != len(ordered):
        raise ValueError("descriptor row count mismatch")
    old: dict[str, bytes | None] = {}
    new: dict[str, bytes | None] = {}
    exact_row_fields = {
        "path",
        "old_state",
        "old_sha256",
        "old_size",
        "old_b64",
        "new_state",
        "new_sha256",
        "new_size",
        "new_b64",
    }
    for expected_name, row in zip(ordered, rows):
        if not isinstance(row, dict) or set(row) != exact_row_fields:
            raise ValueError("descriptor row field denominator mismatch")
        if row.get("path") != expected_name:
            raise ValueError("descriptor row order/path mismatch")
        for prefix, destination in (("old", old), ("new", new)):
            state = row.get(f"{prefix}_state")
            encoded = row.get(f"{prefix}_b64")
            size = row.get(f"{prefix}_size")
            digest = row.get(f"{prefix}_sha256")
            if state not in {"PRESENT", "ABSENT"} or type(size) is not int:
                raise ValueError("descriptor row state/size is malformed")
            if not isinstance(encoded, str) or not isinstance(digest, str):
                raise ValueError("descriptor row bytes/digest is malformed")
            if state == "ABSENT":
                if encoded or digest or size != 0:
                    raise ValueError("ABSENT descriptor row carries bytes")
                decoded = None
            else:
                decoded = base64.b64decode(encoded, validate=True)
                if base64.b64encode(decoded).decode("ascii") != encoded:
                    raise ValueError("descriptor row base64 is not canonical")
                if size != len(decoded) or digest != hashlib.sha256(decoded).hexdigest():
                    raise ValueError("descriptor row hash/size mismatch")
            destination[expected_name] = decoded
    unsigned = dict(descriptor)
    recorded_digest = unsigned.pop("descriptor_sha256")
    if (
        not isinstance(recorded_digest, str)
        or recorded_digest != _stable_payload_digest(unsigned)
    ):
        raise ValueError("descriptor digest mismatch")

    ledger = read_artifact_ledger(scratchpad)
    unit = ledger.get("work_units", {}).get(contract.key)
    if (
        not isinstance(unit, Mapping)
        or unit.get("run_id") != run_id
        or unit.get("contract_digest") != contract.digest
        or unit.get("launch_digest") != launch.digest
        or unit.get("semantic_status") not in {"INPUTS_BOUND", "ACTIVE"}
        or unit.get("execution_state")
        not in {"INPUTS_BOUND_PREEXECUTION", "OUTPUT_COMMITTED"}
    ):
        raise ValueError("descriptor has no current ledger transaction owner")
    authority = unit.get("preexecution_authority")
    authority_digest = unit.get("preexecution_authority_digest")
    if (
        not isinstance(authority, Mapping)
        or authority_digest != descriptor.get("transaction_authority_sha256")
        or authority.get("authority_sha256") != authority_digest
    ):
        raise ValueError("descriptor transaction authority is missing or foreign")
    authority_unsigned = dict(authority)
    authority_unsigned.pop("authority_sha256", None)
    if authority_digest != _stable_payload_digest(authority_unsigned):
        raise ValueError("descriptor transaction authority digest mismatch")
    if (
        authority.get("schema")
        != "plamen.driver-output-vector-preexecution-authority.v1"
        or authority.get("work_unit_key") != contract.key
        or authority.get("run_id") != run_id
        or authority.get("contract_digest") != contract.digest
        or authority.get("launch_digest") != launch.digest
        or tuple(authority.get("ordered_outputs", ())) != ordered
        or authority.get("output_prestates") != unit.get("output_prestates")
        or authority.get("output_prestate_digest") != unit.get("output_prestate_digest")
        or authority.get("output_prestate_digest")
        != _output_prestate_digest(dict(unit.get("output_prestates") or {}))
    ):
        raise ValueError("descriptor transaction/prestate authority mismatch")
    candidate_rows = authority.get("candidate_rows")
    expected_candidates = [
        {
            "path": name,
            "state": "PRESENT" if new[name] is not None else "ABSENT",
            "sha256": hashlib.sha256(new[name]).hexdigest() if new[name] is not None else "",
            "size": len(new[name]) if new[name] is not None else 0,
        }
        for name in ordered
    ]
    if candidate_rows != expected_candidates:
        raise ValueError("descriptor new vector differs from transaction authority")
    prestates = unit.get("output_prestates")
    for name in ordered:
        identity = f"scratchpad:{name}"
        prestate = prestates.get(identity) if isinstance(prestates, Mapping) else None
        if not isinstance(prestate, Mapping):
            raise ValueError("descriptor prestate identity is missing")
        expected_old = old[name]
        if bool(prestate.get("existed")) != (expected_old is not None):
            raise ValueError("descriptor old state differs from ledger prestate")
        if expected_old is None:
            if prestate.get("sha256") or prestate.get("size") != 0:
                raise ValueError("descriptor absent prestate is not clean")
        elif (
            prestate.get("sha256") != hashlib.sha256(expected_old).hexdigest()
            or prestate.get("size") != len(expected_old)
        ):
            raise ValueError("descriptor old bytes differ from ledger prestate")
    actual = {
        name: (targets[name].read_bytes() if targets[name].is_file() else None)
        for name in ordered
    }
    if any(actual[name] not in {old[name], new[name]} for name in ordered):
        raise ValueError("public vector is neither bound old nor bound new state")
    committed = (
        unit.get("semantic_status") == "ACTIVE"
        and unit.get("execution_state") == "OUTPUT_COMMITTED"
        and not validate_work_unit_artifacts(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
            preexecution_authority=authority,
        )
    )
    if committed and actual != new:
        raise ValueError("committed vector bytes drifted")
    return old, new, committed


def _recoverable_driver_output_vector(
    *,
    scratchpad: Path,
    project_root: Path,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    outputs: Mapping[str, bytes | None],
    conditional_receipts: Mapping[str, ConditionalOutputReceipt] | None = None,
    failure_injector: Callable[[str], None] | None = None,
    prepublish_validator: Callable[[], Sequence[str]] | None = None,
    already_armed: bool = False,
    successor_plan: Mapping[str, Any] | None = None,
    retain_authenticated_stage_on_prepublish_rejection: bool = False,
) -> tuple[bool, list[str]]:
    """Publish one fixed DRIVER vector as verified all-old or committed all-new."""

    root = Path(scratchpad)
    project = Path(project_root)
    ordered = tuple(spec.path for spec in contract.outputs)
    if tuple(outputs) != ordered:
        return False, [f"{contract.key}: output-vector denominator mismatch"]
    if len({name.casefold() for name in ordered}) != len(ordered):
        return False, [f"{contract.key}: output-vector case alias"]
    targets = {name: root / PurePosixPath(name) for name in ordered}
    root_resolved = root.resolve(strict=True)
    for name, path in targets.items():
        if path.parent.resolve(strict=True) != root_resolved or path.is_symlink():
            return False, [f"{contract.key}: non-contained output target {name}"]
        if path.exists() and not path.is_file():
            return False, [f"{contract.key}: output target is not a file {name}"]
        attrs = int(getattr(path.lstat(), "st_file_attributes", 0)) if path.exists() else 0
        if attrs & int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)):
            return False, [f"{contract.key}: reparse output target {name}"]
    existing = [(name, path) for name, path in targets.items() if path.exists()]
    for index, (left_name, left) in enumerate(existing):
        for right_name, right in existing[index + 1 :]:
            if os.path.samefile(left, right):
                return False, [
                    f"{contract.key}: output hardlink alias {left_name}/{right_name}"
                ]

    vector_root = root / "_driver_vector_transactions"
    stage_parent = vector_root / hashlib.sha256(
        f"{run_id}\0{contract.key}".encode("utf-8")
    ).hexdigest()

    def restore(prestates: Mapping[str, bytes | None]) -> list[str]:
        problems: list[str] = []
        for name in ordered:
            path = targets[name]
            before = prestates[name]
            try:
                if before is None:
                    if path.exists() or path.is_symlink():
                        rooted_io.unlink(path)
                else:
                    _atomic_driver_bytes(path, before)
                observed = path.read_bytes() if path.is_file() else None
                if observed != before:
                    problems.append(f"{contract.key}: rollback mismatch {name}")
            except OSError as exc:
                problems.append(f"{contract.key}: rollback failed {name}: {exc}")
        return problems

    def event(name: str) -> None:
        if failure_injector is not None:
            failure_injector(name)

    with _ledger_transaction_lock(root):
        # Recover only transaction directories for this exact unit/run. A mixed
        # or foreign descriptor never becomes authority.
        recovered_vector = False
        if rooted_io.lexists(stage_parent):
            try:
                pending_entries = _driver_vector_directory_entries(
                    stage_parent,
                    label="driver vector recovery parent",
                )
            except (OSError, rooted_io.RootedPathIOError, ValueError):
                return False, [f"{contract.key}: invalid vector recovery parent"]
            for pending in pending_entries:
                try:
                    pending_stat = rooted_io.lstat(pending)
                except OSError:
                    return False, [f"{contract.key}: invalid vector recovery entry"]
                if (
                    stat.S_ISLNK(pending_stat.st_mode)
                    or _driver_vector_reparse(pending_stat)
                    or not stat.S_ISDIR(pending_stat.st_mode)
                ):
                    return False, [f"{contract.key}: invalid vector recovery entry"]
                descriptor_path = pending / "descriptor.json"
                try:
                    old, new, committed = _validated_driver_vector_recovery(
                        descriptor_path=descriptor_path,
                        pending=pending,
                        scratchpad=root,
                        project_root=project,
                        contract=contract,
                        launch=launch,
                        run_id=run_id,
                        ordered=ordered,
                        targets=targets,
                    )
                    if not committed:
                        if prepublish_validator is not None:
                            prepublish_issues = list(prepublish_validator())
                            if prepublish_issues:
                                raise ValueError("; ".join(prepublish_issues))
                        for name in ordered:
                            raw = new[name]
                            if raw is None:
                                if targets[name].exists() or targets[name].is_symlink():
                                    rooted_io.unlink(targets[name])
                            else:
                                _atomic_driver_bytes(targets[name], raw)
                        if any(
                            (targets[name].read_bytes() if targets[name].is_file() else None)
                            != new[name]
                            for name in ordered
                        ):
                            raise ValueError("recovered new vector verification failed")
                        authority = _stored_preexecution_authority(root, contract.key)
                        if not isinstance(authority, Mapping):
                            raise ValueError("recovery transaction authority disappeared")
                        commit_issues = _commit_deterministic_driver_work_unit(
                            scratchpad=root,
                            project_root=project,
                            contract=contract,
                            launch=launch,
                            run_id=run_id,
                            conditional_receipts=conditional_receipts,
                            expected_output_records=(
                                {
                                    f"scratchpad:{name}": {
                                        "sha256": hashlib.sha256(raw).hexdigest(),
                                        "size": len(raw),
                                    }
                                    for name, raw in new.items()
                                    if raw is not None
                                }
                                if all(raw is not None for raw in new.values())
                                else None
                            ),
                            preexecution_authority=authority,
                        )
                        if commit_issues:
                            raise ValueError("; ".join(commit_issues))
                        final_issues = validate_work_unit_artifacts(
                            root,
                            project,
                            contract,
                            launch,
                            run_id=run_id,
                            actor="DRIVER",
                            preexecution_authority=authority,
                        )
                        if final_issues:
                            raise ValueError("; ".join(final_issues))
                        recovered_vector = True
                except (
                    ArtifactLedgerError,
                    json.JSONDecodeError,
                    KeyError,
                    OSError,
                    rooted_io.RootedPathIOError,
                    TypeError,
                    UnicodeError,
                    ValueError,
                ) as exc:
                    return False, [f"{contract.key}: vector recovery failed: {exc}"]
                _remove_driver_vector_tree(pending)
            try:
                rooted_io.rmdir(stage_parent)
            except OSError:
                pass
            try:
                rooted_io.rmdir(vector_root)
            except OSError:
                pass
        if recovered_vector:
            return True, []

        prior = read_artifact_ledger(root).get("work_units", {}).get(contract.key)
        stored_authority = (
            prior.get("preexecution_authority")
            if isinstance(prior, Mapping)
            and prior.get("run_id") == run_id
            and (
                (
                    prior.get("semantic_status") == "INPUTS_BOUND"
                    and prior.get("execution_state") == "INPUTS_BOUND_PREEXECUTION"
                )
                or (
                    prior.get("semantic_status") == "ACTIVE"
                    and prior.get("execution_state") == "OUTPUT_COMMITTED"
                )
            )
            else None
        )
        if isinstance(stored_authority, Mapping):
            vector_authority = dict(stored_authority)
        else:
            vector_authority = _driver_vector_preexecution_authority(
                scratchpad=root,
                project_root=project,
                contract=contract,
                launch=launch,
                run_id=run_id,
                outputs=outputs,
            )

        if already_armed:
            try:
                record_work_unit_inputs(
                    root,
                    project,
                    contract,
                    launch,
                    run_id=run_id,
                    successor_plan=successor_plan,
                    preexecution_authority=vector_authority,
                )
                execute, issues = True, []
            except ArtifactLedgerError as exc:
                return False, [f"{contract.key}: vector authority arm failed: {exc}"]
        else:
            execute, issues = _arm_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project,
                contract=contract,
                launch=launch,
                run_id=run_id,
                successor_plan=successor_plan,
                preexecution_authority=vector_authority,
            )
            if issues or not execute:
                return False, list(dict.fromkeys(issues))
        input_issues = validate_work_unit_inputs(
            root,
            project,
            contract,
            launch,
            run_id=run_id,
            preexecution_authority=vector_authority,
        )
        if input_issues:
            return False, list(dict.fromkeys(input_issues))

        stage = stage_parent / uuid.uuid4().hex
        rooted_io.ensure_directory(stage, parents=True, label="driver vector stage")
        prestates = {
            name: (path.read_bytes() if path.is_file() else None)
            for name, path in targets.items()
        }
        rows = []
        for name in ordered:
            old = prestates[name]
            new = outputs[name]
            rows.append({
                "path": name,
                "old_state": "PRESENT" if old is not None else "ABSENT",
                "old_sha256": hashlib.sha256(old).hexdigest() if old is not None else "",
                "old_size": len(old) if old is not None else 0,
                "old_b64": base64.b64encode(old).decode("ascii") if old is not None else "",
                "new_state": "PRESENT" if new is not None else "ABSENT",
                "new_sha256": hashlib.sha256(new).hexdigest() if new is not None else "",
                "new_size": len(new) if new is not None else 0,
                "new_b64": base64.b64encode(new).decode("ascii") if new is not None else "",
            })
        descriptor_unsigned = {
            "schema": "plamen.driver-output-vector.v2",
            "state": "STAGED",
            "work_unit_key": contract.key,
            "run_id": run_id,
            "contract_digest": contract.digest,
            "launch_digest": launch.digest,
            "ordered_outputs": list(ordered),
            "transaction_authority_sha256": vector_authority["authority_sha256"],
            "rows": rows,
        }
        descriptor = {
            **descriptor_unsigned,
            "descriptor_sha256": _stable_payload_digest(descriptor_unsigned),
        }
        published = False
        committed = False
        prepublish_rejected = False
        try:
            for name in ordered:
                raw = outputs[name]
                if raw is not None:
                    _atomic_driver_bytes(stage / name, raw)
                event(f"after_stage:{name}")
            _atomic_driver_bytes(
                stage / "descriptor.json",
                (json.dumps(descriptor, indent=2, sort_keys=True) + "\n").encode("utf-8"),
            )
            event("after_descriptor")
            for name in ordered:
                raw = outputs[name]
                if raw is not None and rooted_io.read_bytes(
                    stage / name,
                    label=f"staged driver vector output {name}",
                    require_single_link=True,
                ) != raw:
                    raise ArtifactLedgerError(f"staged vector drifted: {name}")
            if prepublish_validator is not None:
                prepublish_issues = list(prepublish_validator())
                if prepublish_issues:
                    prepublish_rejected = True
                    raise ArtifactLedgerError("; ".join(prepublish_issues))
            event("before_first_replace")
            for name in ordered:
                raw = outputs[name]
                if raw is None:
                    if targets[name].exists() or targets[name].is_symlink():
                        rooted_io.unlink(targets[name])
                else:
                    _atomic_driver_bytes(targets[name], raw)
                published = True
                event(f"after_replace:{name}")
            if any(
                (targets[name].read_bytes() if targets[name].is_file() else None)
                != outputs[name]
                for name in ordered
            ):
                raise ArtifactLedgerError("published vector verification mismatch")
            event("before_commit")
            commit_issues = _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project,
                contract=contract,
                launch=launch,
                run_id=run_id,
                conditional_receipts=conditional_receipts,
                expected_output_records=(
                    {
                        f"scratchpad:{name}": {
                            "sha256": hashlib.sha256(raw).hexdigest(),
                            "size": len(raw),
                        }
                        for name, raw in outputs.items()
                        if raw is not None
                    }
                    if all(raw is not None for raw in outputs.values())
                    else None
                ),
                preexecution_authority=vector_authority,
            )
            if commit_issues:
                raise ArtifactLedgerError("; ".join(commit_issues))
            committed = True
            published = False
            event("after_commit")
            final_issues = validate_work_unit_artifacts(
                root,
                project,
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
                preexecution_authority=vector_authority,
            )
            if final_issues:
                raise ArtifactLedgerError("; ".join(final_issues))
            return True, []
        except BaseException:
            # Once any public output is replaced, the signed descriptor and
            # INPUTS_BOUND ledger row are the sole recovery authority.  Leave
            # both intact for authenticated all-new roll-forward; restoring
            # bytes here would silently change physical identity and erase the
            # crash evidence the successor validates.
            raise
        finally:
            if (committed or not published) and not (
                retain_authenticated_stage_on_prepublish_rejection
                and prepublish_rejected
            ):
                if rooted_io.lexists(stage):
                    _remove_driver_vector_tree(stage)
                try:
                    rooted_io.rmdir(stage_parent)
                except OSError:
                    pass
                try:
                    rooted_io.rmdir(vector_root)
                except OSError:
                    pass


def _dependency_phase_io_pair(
    config: Mapping[str, Any],
    *,
    work_unit_id: str,
) -> tuple[PhaseIOContract, LaunchSpec]:
    """Resolve the caller-neutral DRIVER authority for dependency publication."""
    outputs = (
        ("external_dependency_obligations.json",)
        if work_unit_id == "dependency_obligations"
        else (
            "external_dependency_research.md",
            "report_semantic_dependency_research.md",
        )
    )
    inputs = (
        ("dependency_obligations_preexecution_authority.json",)
        if work_unit_id == "dependency_obligations"
        else (
            "dependency_reconcile_preexecution_authority.json",
            "external_dependency_obligations.json",
        )
    )
    return _driver_vector_contract_launch(
        config,
        work_unit_id=work_unit_id,
        exact_inputs=inputs,
        exact_outputs=outputs,
    )


def _reject_duplicate_json_pairs(
    pairs: list[tuple[str, Any]],
) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def _dependency_authority_payload(
    *,
    config: Mapping[str, Any],
    kind: str,
    obligations: Mapping[str, Any],
    research: Mapping[str, Any] | None = None,
    admitted_files: DependencyFileCensus | Iterable[Path] | None = None,
) -> dict[str, Any]:
    """Build the canonical signed preexecution dependency denominator."""
    original_project = Path(str(config.get("project_root") or "."))
    census = (
        collect_unvendored_files(original_project)
        if admitted_files is None
        else validate_unvendored_files(original_project, admitted_files)
    )
    project = census.root
    source_rows: list[dict[str, Any]] = []
    suffixes = {".sol", ".vy", ".rs", ".go", ".move", ".daml"}
    for path in census:
        if (
            not path.is_file()
            or path.is_symlink()
            or path.suffix.casefold() not in suffixes
        ):
            continue
        relative = path.relative_to(project)
        raw = path.read_bytes()
        source_rows.append({
            "path": relative.as_posix(),
            "sha256": hashlib.sha256(raw).hexdigest(),
            "size": len(raw),
        })
    config_projection = {
        name: config.get(name)
        for name in ("pipeline", "mode", "language", "cli_backend")
    }
    capture_contract, capture_launch, _capture_output = _dependency_capture_pair(
        config,
        kind=kind,
        research_active=bool(
            kind == "RECONCILE"
            and isinstance(research, Mapping)
            and research.get("state") == "ACTIVE"
        ),
    )
    unsigned: dict[str, Any] = {
        "schema": f"plamen.dependency-{kind.casefold()}-preexecution-authority.v2",
        "kind": kind,
        "run_id": str(config.get("_run_id") or "").strip(),
        "pipeline": str(config.get("pipeline") or "sc"),
        "mode": str(config.get("mode") or "core"),
        "ecosystem": str(config.get("language") or "unknown"),
        "backend": str(config.get("cli_backend") or "claude"),
        "capture_work_unit_key": capture_contract.key,
        "capture_contract_digest": capture_contract.digest,
        "capture_launch_digest": capture_launch.digest,
        "project_root": str(project),
        "project_root_sha256": hashlib.sha256(str(project).encode("utf-8")).hexdigest(),
        "project_root_identity": census.root_identity.payload(),
        "project_root_identity_sha256": _stable_payload_digest(
            census.root_identity.payload()
        ),
        "source_rows": source_rows,
        "source_tree_sha256": _stable_payload_digest(source_rows),
        "config_projection": config_projection,
        "config_projection_sha256": _stable_payload_digest(config_projection),
        "enumeration_schema": str(obligations.get("schema") or ""),
        "enumeration_provider": str(obligations.get("provider") or ""),
        "observed_count": obligations.get("observed_count"),
        "retained_count": obligations.get("retained_count"),
        "truncated": obligations.get("truncated"),
        "overflow_ids": list(obligations.get("overflow_ids") or ()),
        "obligations_sha256": _stable_payload_digest(dict(obligations)),
        "research": dict(research or {"state": "NOT_APPLICABLE"}),
    }
    # Replay the bound native root after reading every signed source.  A
    # same-path, byte-identical directory replacement is not the same
    # preexecution authority.
    validate_unvendored_files(original_project, census)
    return {**unsigned, "authority_sha256": _stable_payload_digest(unsigned)}


def _current_dependency_authority_payload(
    *,
    config: Mapping[str, Any],
    kind: str,
) -> dict[str, Any]:
    """Derive one dependency capture solely from current independent state."""
    run_id = config.get("_run_id")
    if not isinstance(run_id, str) or not run_id.strip() or run_id != run_id.strip():
        raise ArtifactLedgerError("dependency capture requires canonical current run_id")
    original_project = Path(str(config.get("project_root") or "."))
    census = collect_unvendored_files(original_project)
    project = census.root
    obligations_path = Path(str(config.get("scratchpad") or project / ".scratchpad")) / (
        "external_dependency_obligations.json"
    )
    if kind == "OBLIGATIONS":
        obligations = enumerate_dependency_obligations(
            project,
            dict(config),
            admitted_files=census,
        )
        research = None
    elif kind == "RECONCILE":
        if not obligations_path.is_file():
            raise ArtifactLedgerError("dependency reconcile obligations input is missing")
        try:
            obligations = json.loads(
                obligations_path.read_text(encoding="utf-8"),
                object_pairs_hook=_reject_duplicate_json_pairs,
            )
        except (json.JSONDecodeError, TypeError, ValueError) as exc:
            raise ArtifactLedgerError(
                f"dependency reconcile obligations input is not canonical JSON: {exc}"
            ) from exc
        if not isinstance(obligations, dict):
            raise ArtifactLedgerError("dependency reconcile obligations input is not an object")
        research = _dependency_research_authority(obligations_path.parent, config)
    else:
        raise ArtifactLedgerError(f"unsupported dependency capture kind: {kind}")
    return _dependency_authority_payload(
        config=config,
        kind=kind,
        obligations=obligations,
        research=research,
        admitted_files=census,
    )


def _validate_current_dependency_authority(
    payload: Mapping[str, Any],
    *,
    config: Mapping[str, Any],
    kind: str,
) -> bytes:
    expected = _current_dependency_authority_payload(config=config, kind=kind)
    supplied = (json.dumps(dict(payload), indent=2, sort_keys=True) + "\n").encode(
        "utf-8"
    )
    canonical = (json.dumps(expected, indent=2, sort_keys=True) + "\n").encode(
        "utf-8"
    )
    if supplied != canonical:
        raise ArtifactLedgerError(
            f"dependency {kind} capture does not match current run authority"
        )
    return canonical


def _current_dependency_authority_bytes(
    *,
    config: Mapping[str, Any],
    kind: str,
) -> bytes:
    """Return a fresh canonical authority without consulting a caller alias."""
    current = _current_dependency_authority_payload(config=config, kind=kind)
    return (json.dumps(current, indent=2, sort_keys=True) + "\n").encode("utf-8")


def _dependency_capture_pair(
    config: Mapping[str, Any],
    *,
    kind: str,
    research_active: bool = False,
) -> tuple[PhaseIOContract, LaunchSpec, str]:
    if kind == "OBLIGATIONS":
        work_unit_id = "dependency_obligations.source_capture"
        inputs: tuple[str, ...] = ()
        output = "dependency_obligations_preexecution_authority.json"
    elif kind == "RECONCILE":
        work_unit_id = (
            "dependency_reconcile.source_capture.active_research"
            if research_active
            else "dependency_reconcile.source_capture"
        )
        inputs = (
            (
                "external_dependency_obligations.json",
                "recon_external_dependency_research.md",
            )
            if research_active
            else ("external_dependency_obligations.json",)
        )
        output = "dependency_reconcile_preexecution_authority.json"
    else:
        raise ValueError(f"unsupported dependency capture kind: {kind}")
    contract, launch = _driver_vector_contract_launch(
        config,
        work_unit_id=work_unit_id,
        exact_inputs=inputs,
        exact_outputs=(output,),
    )
    return contract, launch, output


def _publish_dependency_capture(
    *,
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    payload: Mapping[str, Any],
    expected_current_authority: Mapping[str, Any],
    failure_injector: Callable[[str], None] | None = None,
) -> str:
    kind = str(expected_current_authority.get("kind") or "")
    if str(payload.get("kind") or "") != kind:
        raise ArtifactLedgerError("dependency capture expected-authority kind mismatch")
    expected_raw = _validate_current_dependency_authority(
        expected_current_authority, config=config, kind=kind
    )
    supplied_raw = (
        json.dumps(dict(payload), indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    if supplied_raw != expected_raw:
        raise ArtifactLedgerError(
            f"dependency {kind} capture differs from explicit expected authority"
        )
    research = expected_current_authority.get("research")
    contract, launch, output = _dependency_capture_pair(
        config,
        kind=kind,
        research_active=bool(
            kind == "RECONCILE"
            and isinstance(research, Mapping)
            and research.get("state") == "ACTIVE"
        ),
    )
    run_id = str(config.get("_run_id") or "").strip()
    raw = bytes(expected_raw)
    path = Path(scratchpad) / output
    existing_differs = path.is_file() and path.read_bytes() != raw

    # This join deliberately follows the read-only existing-output inspection
    # but dominates successor authorization, vector recovery, arm, stage, and
    # every ledger/public mutation.
    current_raw = _current_dependency_authority_bytes(config=config, kind=kind)
    if current_raw != raw:
        raise ArtifactLedgerError(
            f"dependency {kind} capture freshness changed before vector arm"
        )
    if existing_differs:
        binding = read_artifact_ledger(Path(scratchpad)).get(
            "artifact_bindings", {}
        ).get(f"scratchpad:{output}")
        if isinstance(binding, Mapping) and binding.get("owner_key") == contract.key:
            existing_issues = validate_work_unit_artifacts(
                Path(scratchpad),
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
                actor="DRIVER",
                preexecution_authority=_stored_preexecution_authority(
                    Path(scratchpad), contract.key
                ),
            )
            if existing_issues:
                raise ArtifactLedgerError("; ".join(existing_issues))
            reexecution = authorize_deterministic_work_unit_reexecution(
                Path(scratchpad),
                Path(project_root),
                contract,
                launch,
                run_id=run_id,
            )
            if reexecution is None:
                raise ArtifactLedgerError(
                    f"dependency {kind} capture changed without input drift"
                )

    def _validate_capture_freshness() -> list[str]:
        try:
            fresh_raw = _current_dependency_authority_bytes(
                config=config, kind=kind
            )
            if fresh_raw != raw:
                return [f"dependency {kind} capture drifted before publication"]
            authority = _stored_preexecution_authority(
                Path(scratchpad), contract.key
            )
            expected_candidate = [{
                "path": output,
                "state": "PRESENT",
                "sha256": hashlib.sha256(raw).hexdigest(),
                "size": len(raw),
            }]
            if (
                not isinstance(authority, Mapping)
                or authority.get("work_unit_key") != contract.key
                or authority.get("run_id") != run_id
                or authority.get("contract_digest") != contract.digest
                or authority.get("launch_digest") != launch.digest
                or authority.get("ordered_outputs") != [output]
                or authority.get("candidate_rows") != expected_candidate
            ):
                return [f"dependency {kind} capture staged authority drifted"]
            return []
        except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
            return [
                f"dependency {kind} capture drifted before publication: {exc}"
            ]

    _published, issues = _recoverable_driver_output_vector(
        scratchpad=Path(scratchpad),
        project_root=Path(project_root),
        contract=contract,
        launch=launch,
        run_id=run_id,
        outputs={output: raw},
        failure_injector=failure_injector,
        prepublish_validator=_validate_capture_freshness,
        retain_authenticated_stage_on_prepublish_rejection=True,
    )
    if issues:
        raise ArtifactLedgerError("; ".join(issues))
    if not path.is_file() or path.read_bytes() != raw:
        raise ArtifactLedgerError(f"dependency {kind} capture replay drifted")
    validation = validate_work_unit_artifacts(
        Path(scratchpad),
        Path(project_root),
        contract,
        launch,
        run_id=run_id,
        actor="DRIVER",
        preexecution_authority=_stored_preexecution_authority(
            Path(scratchpad), contract.key
        ),
    )
    if validation:
        raise ArtifactLedgerError("; ".join(validation))
    return output


def _validated_dependency_research_authority(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Capture only a fully replayable transactional R-EXT authority."""
    root = Path(scratchpad)
    ledger = read_artifact_ledger(root)
    rows = [
        (str(key), row)
        for key, row in ledger.get("work_units", {}).items()
        if re.search(
            r"/recon/dependency_research(?:\.attempt-[0-9]{4})?$",
            str(key),
        )
        and isinstance(row, Mapping)
        and row.get("run_id") == str(config.get("_run_id") or "").strip()
        and row.get("semantic_status") == "ACTIVE"
        and row.get("execution_state") == "OUTPUT_COMMITTED"
    ]
    output = root / "recon_external_dependency_research.md"
    if not rows:
        return {"state": "EXPLICIT_ABSENCE", "identity": "scratchpad:recon_external_dependency_research.md"}
    if len(rows) != 1 or not output.is_file():
        raise ArtifactLedgerError("dependency research producer authority is ambiguous")
    key, row = rows[0]
    raw = output.read_bytes()
    record = row.get("artifacts", {}).get(
        "scratchpad:recon_external_dependency_research.md"
    )
    if (
        not isinstance(record, Mapping)
        or record.get("sha256") != hashlib.sha256(raw).hexdigest()
        or record.get("size") != len(raw)
    ):
        raise ArtifactLedgerError("dependency research producer output drifted")
    execution_authority = row.get("execution_authority")
    commit_authority = row.get("commit_authority")
    if (
        not isinstance(execution_authority, Mapping)
        or not isinstance(commit_authority, Mapping)
        or commit_authority.get("output_authority_source")
        != "WORKER_TRANSACTION_CAS"
    ):
        raise ArtifactLedgerError(
            "dependency research lacks transactional CAS execution authority"
        )
    match = re.search(
        r"/recon/dependency_research(?:\.attempt-([0-9]{4}))?$", key
    )
    if match is None:
        raise ArtifactLedgerError("dependency research work-unit key is invalid")
    attempt = int(match.group(1) or "1")
    launch_manifest = row.get("launch_manifest")
    timeout_s = (
        launch_manifest.get("timeout_s")
        if isinstance(launch_manifest, Mapping)
        else None
    )
    if isinstance(timeout_s, bool) or not isinstance(timeout_s, int):
        raise ArtifactLedgerError("dependency research launch timeout is invalid")
    phase = next(value for value in SC_PHASES if value.name == "recon")
    project_root = Path(str(config.get("project_root") or root.parent))
    contract, launch = _typed_model_worker_contract_and_launch(
        phase=phase,
        config=dict(config),
        scratchpad=root,
        project_root=str(project_root),
        agent_id="R-EXT",
        agent_role="external_dependency_research",
        output="recon_external_dependency_research.md",
        timeout_s=timeout_s,
        attempt=attempt,
    )
    if contract.key != key:
        raise ArtifactLedgerError("dependency research owner key drifted")
    replay_issues = validate_work_unit_artifacts(
        root,
        project_root,
        contract,
        launch,
        run_id=str(config.get("_run_id") or "test-unbound"),
        actor="MODEL",
    )
    if replay_issues:
        raise ArtifactLedgerError(
            "dependency research transactional replay failed: "
            + "; ".join(replay_issues)
        )

    # Structural CAS replay is necessary but R-EXT additionally requires its
    # bounded web/write semantic gate to remain live. Replay the gate against
    # the incorporated bytes so missing, denied, fabricated, or drifted
    # receipts can never be accepted merely because a canonical file exists.
    completion_relative = str(
        execution_authority.get("attempt_completion_relative_path") or ""
    )
    completion = (root / completion_relative).resolve(strict=True)
    completion.relative_to(root.resolve(strict=True))
    plan_path = completion.parent / "view" / "plan.json"
    plan = json.loads(
        plan_path.read_text(encoding="utf-8", errors="strict"),
        object_pairs_hook=_reject_duplicate_json_pairs,
    )
    if not isinstance(plan, Mapping):
        raise ArtifactLedgerError("dependency research work plan is malformed")
    plan_digest = str(plan.get("work_plan_digest") or "")
    unsigned_plan = {
        name: value for name, value in plan.items()
        if name != "work_plan_digest"
    }
    if (
        plan_digest != execution_authority.get("work_plan_digest")
        or _stable_payload_digest(unsigned_plan) != plan_digest
    ):
        raise ArtifactLedgerError("dependency research work plan drifted")
    completion_policy = plan.get("completion_policy")
    gate = (
        completion_policy.get("staged_semantic_gate")
        if isinstance(completion_policy, Mapping)
        else None
    )
    if not isinstance(gate, Mapping):
        raise ArtifactLedgerError(
            "dependency research staged receipt gate is absent"
        )
    backend = str(config.get("cli_backend") or "claude").strip().lower()
    if backend == "codex":
        expected_gate_callable = (
            "codex_dependency_research:"
            "staged_codex_dependency_research_validator"
        )
        gate_implementation = Path(
            codex_dependency_research_authority.__file__
        ).resolve(strict=True)
    else:
        expected_gate_callable = (
            "claude_phase_tool_policy:"
            "staged_dependency_research_receipt_validator"
        )
        gate_implementation = Path(
            claude_phase_tool_policy.__file__
        ).resolve(strict=True)
    if gate.get("callable") != expected_gate_callable:
        raise ArtifactLedgerError(
            "dependency research staged receipt validator drifted"
        )
    gate_unsigned = {
        name: value for name, value in gate.items()
        if name != "binding_sha256"
    }
    if _stable_payload_digest(gate_unsigned) != gate.get("binding_sha256"):
        raise ArtifactLedgerError(
            "dependency research staged receipt gate digest drifted"
        )
    implementation_sha = hashlib.sha256(
        gate_implementation.read_bytes()
    ).hexdigest()
    if gate.get("implementation_sha256") != implementation_sha:
        raise ArtifactLedgerError(
            "dependency research staged receipt validator implementation drifted"
        )
    gate_context = gate.get("context")
    if not isinstance(gate_context, Mapping):
        raise ArtifactLedgerError(
            "dependency research staged receipt context is malformed"
        )
    attempt_relative = completion.parent.relative_to(root).as_posix()
    output_relative = f"{attempt_relative}/output"
    replacements = {
        "__PLAMEN_ATTEMPT_OUTPUT_DIRECTORY__": (
            root / output_relative
        ).as_posix(),
        "__PLAMEN_ATTEMPT_OUTPUT_RELATIVE_PATH__": output_relative,
        "__PLAMEN_ATTEMPT_RELATIVE_PATH__": attempt_relative,
        "__PLAMEN_ATTEMPT_ID__": str(
            execution_authority.get("attempt_id") or ""
        ),
    }

    def materialize(value: Any) -> Any:
        if isinstance(value, str):
            for token, replacement in replacements.items():
                value = value.replace(token, replacement)
            return value
        if isinstance(value, list):
            return [materialize(item) for item in value]
        if isinstance(value, Mapping):
            return {name: materialize(item) for name, item in value.items()}
        return value

    live_context = materialize(gate_context)
    if backend == "codex":
        gate_issues = (
            codex_dependency_research_authority
            .staged_codex_dependency_research_validator(
                {"recon_external_dependency_research.md": raw}, live_context
            )
        )
    else:
        gate_issues = (
            claude_phase_tool_policy.staged_dependency_research_receipt_validator(
                {"recon_external_dependency_research.md": raw}, live_context
            )
        )
    if gate_issues:
        raise ArtifactLedgerError(
            "dependency research staged receipt replay failed: "
            + "; ".join(str(value) for value in gate_issues)
        )
    if backend == "codex":
        fetch_transaction = {
            "phase_name": "recon",
            "work_unit_id": "codex_dependency_fetch",
            "exact_inputs": ("recon_external_dependency_research.md",),
            "exact_outputs": (
                codex_dependency_research_authority.FETCH_RECEIPT_FILE,
            ),
        }
        fetch_contract, fetch_launch = _p1dm_contract_and_launch(
            root,
            config,
            actor="DRIVER",
            **fetch_transaction,
        )
        fetch_issues = validate_work_unit_inputs(
            root,
            project_root,
            fetch_contract,
            fetch_launch,
            run_id=str(config.get("_run_id") or "test-unbound"),
        )
        fetch_issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            fetch_contract,
            fetch_launch,
            run_id=str(config.get("_run_id") or "test-unbound"),
            actor="DRIVER",
        ))
        fetch_issues.extend(
            codex_dependency_research_authority.validate_fetch_receipt(
                output,
                root / codex_dependency_research_authority.FETCH_RECEIPT_FILE,
            )
        )
        if fetch_issues:
            raise ArtifactLedgerError(
                "Codex dependency fetch receipt replay failed: "
                + "; ".join(fetch_issues)
            )
    return {
        "state": "ACTIVE",
        "identity": "scratchpad:recon_external_dependency_research.md",
        "producer_work_unit_key": row.get("work_unit_key"),
        "producer_contract_digest": row.get("contract_digest"),
        "producer_launch_digest": row.get("launch_digest"),
        "producer_receipt_digest": row.get("commit_authority", {}).get("receipt_digest"),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "size": len(raw),
    }


def _dependency_research_authority(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Return ACTIVE only after strict replay, otherwise typed invalid debt.

    An invalid same-run row must remain visible as evidence, but it must not
    make deterministic FETCH_FAILED reconciliation throw while handling that
    very failure.  Downstream code treats every state other than ACTIVE as a
    zero-claim producer.
    """

    identity = "scratchpad:recon_external_dependency_research.md"
    try:
        return _validated_dependency_research_authority(scratchpad, config)
    except Exception as exc:  # fail closed; never catches process termination
        reason = f"{type(exc).__name__}: {exc}".replace("\x00", " ")[:2048]
        return {
            "state": "INVALID",
            "identity": identity,
            "limitation": "R-EXT authority failed strict transactional replay",
            "issues": [reason],
        }


def _dependency_research_base_shard_issues(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Require every selected SC base-recon shard to be committed and live.

    R-EXT is wave B.  A file merely present on disk is not enough: each base
    shard must be the exact artifact of one ACTIVE/OUTPUT_COMMITTED model work
    unit for this run, and its recorded bytes must still match the file.
    """

    if str(config.get("pipeline") or "").lower() != "sc":
        return ["R-EXT is registered only for the SC pipeline"]
    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "test-unbound")
    jobs = _recon_worker_jobs(dict(config))
    expected = {
        f"scratchpad:{str(job['output'])}": dict(job)
        for job in jobs
    }
    if not expected:
        return ["selected recon mode has no base shard denominator"]
    ledger = read_artifact_ledger(root)
    work_units = ledger.get("work_units", {})
    issues: list[str] = []
    for identity, job in sorted(expected.items()):
        matching: list[tuple[str, Mapping[str, Any]]] = []
        for key, row in work_units.items():
            if (
                isinstance(row, Mapping)
                and row.get("run_id") == run_id
                and row.get("semantic_status") == "ACTIVE"
                and row.get("execution_state") == "OUTPUT_COMMITTED"
                and identity in (row.get("artifacts") or {})
            ):
                matching.append((str(key), row))
        if len(matching) != 1:
            issues.append(
                f"{identity}: expected one active committed base producer, "
                f"observed {len(matching)}"
            )
            continue
        output = root / str(job["output"])
        try:
            raw = output.read_bytes()
        except OSError:
            issues.append(f"{identity}: committed base shard is unreadable")
            continue
        producer_key, producer = matching[0]
        record = (producer.get("artifacts") or {}).get(identity)
        if (
            not isinstance(record, Mapping)
            or record.get("sha256") != hashlib.sha256(raw).hexdigest()
            or record.get("size") != len(raw)
        ):
            issues.append(f"{identity}: committed base shard bytes drifted")
            continue
        agent_id = str(job.get("agent_id") or job["output"])
        expected_unit = re.escape(_typed_worker_unit_id(agent_id, 1))
        owner_match = re.search(
            rf"/recon/({expected_unit}(?:\.attempt-([0-9]{{4}}))?)$",
            producer_key,
        )
        if owner_match is None:
            issues.append(
                f"{identity}: committed base shard has wrong producer owner"
            )
            continue
        producer_attempt = int(owner_match.group(2) or "1")
        launch_manifest = producer.get("launch_manifest")
        producer_timeout = (
            launch_manifest.get("timeout_s")
            if isinstance(launch_manifest, Mapping)
            else None
        )
        if (
            isinstance(producer_timeout, bool)
            or not isinstance(producer_timeout, int)
        ):
            issues.append(f"{identity}: committed base launch is malformed")
            continue
        try:
            contract, launch = _typed_model_worker_contract_and_launch(
                phase=next(value for value in SC_PHASES if value.name == "recon"),
                config=dict(config),
                scratchpad=root,
                project_root=str(config.get("project_root") or root.parent),
                agent_id=agent_id,
                agent_role=str(job.get("role") or "") or None,
                output=str(job["output"]),
                timeout_s=producer_timeout,
                attempt=producer_attempt,
            )
            if contract.key != producer_key:
                raise ArtifactLedgerError("owner key differs from selected job")
            authority_issues = validate_work_unit_artifacts(
                root,
                Path(str(config.get("project_root") or root.parent)),
                contract,
                launch,
                run_id=run_id,
                actor="MODEL",
                # The canonical recon merge intentionally supersedes the
                # prepass projections these workers consumed.  Reconfirm the
                # frozen committed generation and its live output bytes, but
                # do not require those retired input producers to remain the
                # current owners after their registered successor commits.
                require_live_input_authority=False,
            )
        except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
            authority_issues = [str(exc)]
        if authority_issues:
            issues.append(
                f"{identity}: committed base producer authority is invalid: "
                + "; ".join(str(value) for value in authority_issues)
            )
            continue
        complete, reasons = _recon_worker_complete(
            root, str(job["output"]), job, config
        )
        if not complete:
            issues.append(
                f"{identity}: base shard content is incomplete: "
                + "; ".join(str(value) for value in reasons)
            )
    return issues


def _dependency_research_degrade(
    *,
    scratchpad: Path,
    project_root: Path,
    config: dict[str, Any],
    obligations: dict[str, Any],
    status: str,
    reasons: Sequence[str],
) -> dict[str, Any]:
    """Publish complete unresolved parity and durable, explicit R-EXT debt."""

    normalized = [str(value) for value in reasons if str(value).strip()]
    if not normalized:
        normalized = ["bounded external-research authority was unavailable"]
    for issue in normalized:
        _append_phase_io_debt(
            Path(scratchpad),
            "recon",
            "DEPENDENCY_RESEARCH_RECEIPT_DEBT",
            issue,
        )
    coverage = _publish_dependency_reconcile(
        Path(scratchpad),
        Path(project_root),
        config,
        obligations,
        worker_text="",
    )
    return {
        "status": status,
        "reasons": normalized,
        "provider_invocations": 0,
        **coverage,
    }


def _arm_dependency_phase_io(
    *,
    scratchpad: Path,
    project_root: Path,
    contract: PhaseIOContract,
    launch: LaunchSpec,
    run_id: str,
    authority: Mapping[str, Any],
    config: Mapping[str, Any],
) -> tuple[bool, list[str]]:
    """Arm or replay one dependency DRIVER unit without output-side effects."""
    try:
        payload = dict(authority)
        kind = str(payload.get("kind") or "")
        capture_raw = _validate_current_dependency_authority(
            payload, config=config, kind=kind
        )
        expected_digest = str(payload.pop("authority_sha256", ""))
        if expected_digest != _stable_payload_digest(payload):
            raise ArtifactLedgerError("dependency capture digest mismatch")
        payload["authority_sha256"] = expected_digest
        capture_name = (
            "dependency_obligations_preexecution_authority.json"
            if kind == "OBLIGATIONS"
            else "dependency_reconcile_preexecution_authority.json"
        )
        capture_path = Path(scratchpad) / capture_name
        if not capture_path.is_file() or capture_path.read_bytes() != capture_raw:
            raise ArtifactLedgerError("dependency capture/current authority mismatch")
        capture_contract, capture_launch, resolved_name = _dependency_capture_pair(
            {
                "pipeline": contract.pipeline,
                "mode": contract.mode,
                "language": contract.ecosystem,
            },
            kind=kind,
            research_active=bool(
                kind == "RECONCILE"
                and isinstance(payload.get("research"), Mapping)
                and payload["research"].get("state") == "ACTIVE"
            ),
        )
        if resolved_name != capture_name:
            raise ArtifactLedgerError("dependency capture identity mismatch")
        capture_issues = validate_work_unit_artifacts(
            scratchpad,
            project_root,
            capture_contract,
            capture_launch,
            run_id=run_id,
            actor="DRIVER",
            preexecution_authority=_stored_preexecution_authority(
                Path(scratchpad), capture_contract.key
            ),
        )
        if capture_issues:
            raise ArtifactLedgerError("; ".join(capture_issues))
    except (ArtifactLedgerError, KeyError, OSError, TypeError, ValueError) as exc:
        return False, [f"{contract.key}: dependency authority failed: {exc}"]
    prior_inputs = validate_work_unit_inputs(
        scratchpad,
        project_root,
        contract,
        launch,
        run_id=run_id,
    )
    prior_outputs = validate_work_unit_artifacts(
        scratchpad,
        project_root,
        contract,
        launch,
        run_id=run_id,
        actor="DRIVER",
    )
    if not prior_inputs and not prior_outputs:
        return False, []
    # Publication owns the actual arm because only it has the complete new
    # vector needed for the ledger-bound preexecution authority.  Returning
    # execute here grants no mutation authority.
    return True, []


def _publish_dependency_obligations(
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    *,
    failure_injector: Callable[[str], None] | None = None,
) -> dict[str, Any]:
    # A committed unit is a read-only replay.  Decode the already-bound output
    # first so dependency enumeration and rendering cannot run before the
    # producer-backed capture and both ledger units have been authenticated.
    root = Path(scratchpad)
    replay_output = root / "external_dependency_obligations.json"
    replay_capture = root / "dependency_obligations_preexecution_authority.json"
    if replay_output.is_file() and replay_capture.is_file():
        try:
            obligations = json.loads(replay_output.read_text(encoding="utf-8"))
            authority = _dependency_authority_payload(
                config=config, kind="OBLIGATIONS", obligations=obligations
            )
            expected_capture = (
                json.dumps(authority, indent=2, sort_keys=True) + "\n"
            ).encode("utf-8")
            if replay_capture.read_bytes() != expected_capture:
                raise ArtifactLedgerError("dependency obligations capture drifted")
            contract, launch = _dependency_phase_io_pair(
                config, work_unit_id="dependency_obligations"
            )
            capture_contract, capture_launch, _ = _dependency_capture_pair(
                config, kind="OBLIGATIONS"
            )
            run_id = str(config.get("_run_id") or "").strip()
            capture_authority = _stored_preexecution_authority(
                root, capture_contract.key
            )
            output_authority = _stored_preexecution_authority(root, contract.key)
            issues = [
                *validate_work_unit_artifacts(
                    root,
                    Path(project_root),
                    capture_contract,
                    capture_launch,
                    run_id=run_id,
                    actor="DRIVER",
                    preexecution_authority=capture_authority,
                ),
                *validate_work_unit_inputs(
                    root,
                    Path(project_root),
                    contract,
                    launch,
                    run_id=run_id,
                    preexecution_authority=output_authority,
                ),
                *validate_work_unit_artifacts(
                    root,
                    Path(project_root),
                    contract,
                    launch,
                    run_id=run_id,
                    actor="DRIVER",
                    preexecution_authority=output_authority,
                ),
            ]
            if issues:
                raise ArtifactLedgerError("; ".join(issues))
            return dict(obligations)
        except (json.JSONDecodeError, OSError, TypeError, ValueError) as exc:
            raise ArtifactLedgerError(
                f"dependency obligations replay authority failed: {exc}"
            ) from exc
    census = collect_unvendored_files(Path(project_root))
    obligations = enumerate_dependency_obligations(
        project_root,
        dict(config),
        admitted_files=census,
    )
    contract, launch = _dependency_phase_io_pair(
        config, work_unit_id="dependency_obligations"
    )
    run_id = str(config.get("_run_id") or "").strip()
    authority = _dependency_authority_payload(
        config=config,
        kind="OBLIGATIONS",
        obligations=obligations,
        admitted_files=census,
    )
    _publish_dependency_capture(
        scratchpad=Path(scratchpad),
        project_root=Path(project_root),
        config=config,
        payload=authority,
        expected_current_authority=authority,
        failure_injector=failure_injector,
    )
    execute, issues = _arm_dependency_phase_io(
        scratchpad=scratchpad,
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
        authority=authority,
        config=config,
    )
    if issues:
        raise ArtifactLedgerError("; ".join(issues))
    if execute:
        raw = render_dependency_obligations(obligations)

        def _validate_obligations_capture() -> list[str]:
            try:
                current = _current_dependency_authority_payload(
                    config=config, kind="OBLIGATIONS"
                )
                current_raw = (
                    json.dumps(current, indent=2, sort_keys=True) + "\n"
                ).encode("utf-8")
                capture_path = root / "dependency_obligations_preexecution_authority.json"
                if not capture_path.is_file() or capture_path.read_bytes() != current_raw:
                    return ["dependency obligations input capture drifted before publication"]
                current_obligations = enumerate_dependency_obligations(
                    Path(project_root), dict(config)
                )
                if render_dependency_obligations(current_obligations) != raw:
                    return ["dependency obligations candidate drifted before publication"]
                return []
            except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
                return [f"dependency obligations freshness validation failed: {exc}"]

        _published, commit_issues = _recoverable_driver_output_vector(
            scratchpad=scratchpad,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            outputs={"external_dependency_obligations.json": raw},
            failure_injector=failure_injector,
            prepublish_validator=_validate_obligations_capture,
        )
        if commit_issues:
            raise ArtifactLedgerError("; ".join(commit_issues))
    return obligations


def _publish_dependency_reconcile(
    scratchpad: Path,
    project_root: Path,
    config: Mapping[str, Any],
    obligations: dict[str, Any],
    *,
    worker_text: str,
    failure_injector: Callable[[str], None] | None = None,
) -> dict[str, Any]:
    root = Path(scratchpad)
    research = _dependency_research_authority(root, config)
    authority = _dependency_authority_payload(
        config=config,
        kind="RECONCILE",
        obligations=obligations,
        research=research,
    )
    current_research_binding = read_artifact_ledger(root).get(
        "artifact_bindings", {}
    ).get("scratchpad:external_dependency_research.md")
    current_research_owner = (
        str(current_research_binding.get("owner_key") or "")
        if isinstance(current_research_binding, Mapping)
        else ""
    )
    current_reconcile_unit = read_artifact_ledger(root).get(
        "work_units", {}
    ).get(current_research_owner)
    current_capture_input = (
        current_reconcile_unit.get("input_bindings", {}).get(
            "scratchpad:dependency_reconcile_preexecution_authority.json"
        )
        if isinstance(current_reconcile_unit, Mapping)
        else None
    )
    current_capture_owner = (
        str(current_capture_input.get("producer_work_unit_key") or "")
        if isinstance(current_capture_input, Mapping)
        else ""
    )
    reconcile_work_unit_id = (
        "dependency_reconcile.active_research"
        if current_research_owner.endswith(
            "/recon/dependency_reconcile.active_research"
        )
        or (
            research.get("state") == "ACTIVE"
            and (
            (
                current_research_owner.endswith("/recon/dependency_reconcile")
                and not current_capture_owner.endswith(
                    "/recon/dependency_reconcile.source_capture.active_research"
                )
            )
            )
        )
        else "dependency_reconcile"
    )
    replay_output = root / "external_dependency_research.md"
    replay_capture = root / "dependency_reconcile_preexecution_authority.json"
    if replay_output.is_file() and replay_capture.is_file():
        expected_capture = (
            json.dumps(authority, indent=2, sort_keys=True) + "\n"
        ).encode("utf-8")
        if replay_capture.read_bytes() == expected_capture:
            contract, launch = _dependency_phase_io_pair(
                config, work_unit_id=reconcile_work_unit_id
            )
            capture_contract, capture_launch, _ = _dependency_capture_pair(
                config,
                kind="RECONCILE",
                research_active=bool(
                    isinstance(authority.get("research"), Mapping)
                    and authority["research"].get("state") == "ACTIVE"
                ),
            )
            run_id = str(config.get("_run_id") or "").strip()
            capture_authority = _stored_preexecution_authority(
                root, capture_contract.key
            )
            output_authority = _stored_preexecution_authority(root, contract.key)
            issues = [
                *validate_work_unit_artifacts(
                    root,
                    Path(project_root),
                    capture_contract,
                    capture_launch,
                    run_id=run_id,
                    actor="DRIVER",
                    preexecution_authority=capture_authority,
                ),
                *validate_work_unit_inputs(
                    root,
                    Path(project_root),
                    contract,
                    launch,
                    run_id=run_id,
                    preexecution_authority=output_authority,
                ),
                *validate_work_unit_artifacts(
                    root,
                    Path(project_root),
                    contract,
                    launch,
                    run_id=run_id,
                    actor="DRIVER",
                    preexecution_authority=output_authority,
                ),
            ]
            if issues:
                raise ArtifactLedgerError("; ".join(issues))
            expected_ids = [
                str(row.get("obligation_id") or "").upper()
                for row in obligations.get("obligations", ())
            ]
            text = replay_output.read_text(encoding="utf-8")
            parity_ok, parity_issues = validate_dependency_ledger_parity(
                obligations, text
            )
            if not parity_ok:
                # Artifact authentication proves who wrote these bytes, not
                # that the projection still satisfies the exact obligation
                # denominator.  Authorize one journaled deterministic refresh
                # and deliberately discard all model claims for the repair.
                for issue in parity_issues:
                    _append_phase_io_debt(
                        root,
                        "recon",
                        "DEPENDENCY_RECONCILE_SEMANTIC_REPLAY_DEBT",
                        str(issue),
                    )
                worker_text = ""
                if current_research_owner.endswith(
                    "/recon/dependency_reconcile"
                ):
                    # Use the one registered DRIVER projection successor.
                    # Its fresh arm binds the authenticated malformed bytes as
                    # predecessor and replaces them transactionally with the
                    # deterministic full-unresolved projection.
                    reconcile_work_unit_id = (
                        "dependency_reconcile.active_research"
                    )
                else:
                    # There is deliberately no reverse or self-replacement
                    # authority.  A malformed successor is fail-closed rather
                    # than silently laundering output-only semantic drift.
                    raise ArtifactLedgerError(
                        "dependency reconcile semantic replay is invalid and "
                        "has no registered repair successor: "
                        + "; ".join(parity_issues)
                    )
            else:
                unresolved = sum(
                    1
                    for line in text.splitlines()
                    if line.startswith("| DEP-")
                    and (
                        "| NEEDS_DEPENDENCY_RESEARCH |" in line
                        or "| FETCH_FAILED |" in line
                    )
                )
                return {
                    "expected_ids": expected_ids,
                    "researched": len(expected_ids) - unresolved,
                    "unresolved": unresolved,
                    "truncated": bool(obligations.get("truncated")),
                }
        # R-EXT is a conditional producer.  The baseline reconcile capture is
        # intentionally bound to EXPLICIT_ABSENCE before that worker runs.  A
        # subsequently committed, ledger-authenticated R-EXT output changes
        # the current authority to ACTIVE.  Fall through to the deterministic
        # same-run capture/output refresh; _publish_dependency_capture proves
        # the old receipt and authorizes the exact successor before mutation.
    _publish_dependency_capture(
        scratchpad=root,
        project_root=Path(project_root),
        config=config,
        payload=authority,
        expected_current_authority=authority,
        failure_injector=failure_injector,
    )
    contract, launch = _dependency_phase_io_pair(
        config, work_unit_id=reconcile_work_unit_id
    )
    run_id = str(config.get("_run_id") or "").strip()
    execute, issues = _arm_dependency_phase_io(
        scratchpad=root,
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
        authority=authority,
        config=config,
    )
    if issues:
        raise ArtifactLedgerError("; ".join(issues))
    rendered = reconcile_dependency_research_ledger(
        root, obligations, worker_text=worker_text, publish=False
    )
    outputs = dict(rendered.pop("_rendered_outputs"))
    if execute:
        limitation_identity = "scratchpad:report_semantic_dependency_research.md"
        limitation_present = limitation_identity.removeprefix("scratchpad:") in outputs
        receipts = {
            limitation_identity: ConditionalOutputReceipt(
                work_unit_key=contract.key,
                contract_digest=contract.digest,
                artifact_identity=limitation_identity,
                condition_id="dependency_research_debt_present",
                state="PRODUCED" if limitation_present else "NOT_TRIGGERED",
                expected_denominator=1 if limitation_present else 0,
                produced_identities=(limitation_identity,) if limitation_present else (),
            )
        }
        vector = {
            "external_dependency_research.md": outputs["external_dependency_research.md"],
            "report_semantic_dependency_research.md": outputs.get(
                "report_semantic_dependency_research.md"
            ),
        }

        def _validate_reconcile_capture() -> list[str]:
            try:
                current = _current_dependency_authority_payload(
                    config=config, kind="RECONCILE"
                )
                current_raw = (
                    json.dumps(current, indent=2, sort_keys=True) + "\n"
                ).encode("utf-8")
                capture_path = root / "dependency_reconcile_preexecution_authority.json"
                if not capture_path.is_file() or capture_path.read_bytes() != current_raw:
                    return ["dependency reconcile input capture drifted before publication"]
                current_obligations = json.loads(
                    (root / "external_dependency_obligations.json").read_text(
                        encoding="utf-8"
                    ),
                    object_pairs_hook=_reject_duplicate_json_pairs,
                )
                current_rendered = reconcile_dependency_research_ledger(
                    root,
                    current_obligations,
                    worker_text=worker_text,
                    publish=False,
                )
                if dict(current_rendered.get("_rendered_outputs") or {}) != outputs:
                    return ["dependency reconcile candidate drifted before publication"]
                return []
            except (
                ArtifactLedgerError,
                json.JSONDecodeError,
                OSError,
                TypeError,
                ValueError,
            ) as exc:
                return [f"dependency reconcile input capture validation failed: {exc}"]

        _published, commit_issues = _recoverable_driver_output_vector(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
            outputs=vector,
            conditional_receipts=receipts,
            failure_injector=failure_injector,
            prepublish_validator=_validate_reconcile_capture,
        )
        if commit_issues:
            raise ArtifactLedgerError("; ".join(commit_issues))
    return rendered


def _run_recon_dependency_research_wave(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
) -> dict[str, Any]:
    """Run conditional recon wave B and enforce obligation-row parity.

    The deterministic unresolved ledger is written before the worker starts,
    so a crash, timeout, missing MCP service, or malformed response cannot turn
    a detected dependency into an empty/stub ledger.
    """
    obligations = _publish_dependency_obligations(
        Path(scratchpad), Path(project_root), config
    )
    if not obligations.get("obligations"):
        baseline = _publish_dependency_reconcile(
            Path(scratchpad), Path(project_root), config, obligations, worker_text=""
        )
        return {"status": "not_applicable", "provider_invocations": 0, **baseline}

    base_issues = _dependency_research_base_shard_issues(
        Path(scratchpad), config
    )
    if base_issues:
        return _dependency_research_degrade(
            scratchpad=Path(scratchpad),
            project_root=Path(project_root),
            config=config,
            obligations=obligations,
            status="input_authority_debt",
            reasons=base_issues,
        )

    # The legacy PTY route has no typed Pre/Post web receipt authority.  It may
    # preserve base recon, but it may never mint RESEARCHED dependency rows.
    return _dependency_research_degrade(
        scratchpad=Path(scratchpad),
        project_root=Path(project_root),
        config=config,
        obligations=obligations,
        status="unsupported_backend_receipts",
        reasons=(
            "legacy Claude PTY has no bounded WebSearch/WebFetch receipt lane; "
            "all dependency obligations remain FETCH_FAILED/unresolved",
        ),
    )

def _ensure_recon_dependency_parity(
    scratchpad: Path, project_root: str, config: dict
) -> dict[str, Any]:
    """Backend-independent fallback: detected dependencies can never be empty."""
    obligations = _publish_dependency_obligations(
        Path(scratchpad), Path(project_root), config
    )
    research_text = ""
    try:
        research_authority = _dependency_research_authority(
            Path(scratchpad), config
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        research_authority = {"state": "INVALID"}
        _append_phase_io_debt(
            Path(scratchpad),
            "recon",
            "DEPENDENCY_RESEARCH_RECEIPT_DEBT",
            f"R-EXT committed authority was invalid during parity repair: {exc}",
        )
    if research_authority.get("state") == "ACTIVE":
        producer = Path(scratchpad) / "recon_external_dependency_research.md"
        try:
            research_text = producer.read_text(
                encoding="utf-8", errors="strict"
            )
        except (OSError, UnicodeError) as exc:
            research_text = ""
            _append_phase_io_debt(
                Path(scratchpad),
                "recon",
                "DEPENDENCY_RESEARCH_RECEIPT_DEBT",
                f"R-EXT authenticated output was unreadable: {exc}",
            )
    # Never use external_dependency_research.md as producer input.  It is a
    # DRIVER-owned reconciled projection and may contain stale rows from an
    # earlier failed/retried attempt.
    result = _publish_dependency_reconcile(
        Path(scratchpad), Path(project_root), config, obligations, worker_text=research_text
    )
    ledger = (Path(scratchpad) / "external_dependency_research.md").read_text(
        encoding="utf-8", errors="replace"
    )
    ok, issues = validate_dependency_ledger_parity(obligations, ledger)
    if not ok:
        raise RuntimeError("external dependency ledger parity failed: " + "; ".join(issues))
    return result


def _run_recon_worker_pool_pty(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
) -> int:
    jobs = _recon_worker_jobs(config)
    if not jobs:
        log.warning("[recon] worker-pool unavailable: no jobs")
        return -2
    concurrency = min(_RECON_WORKER_CONCURRENCY, max(1, len(jobs)))
    pool_started = time.time()
    retry_reasons_by_output: dict[str, list[str]] = {}
    try:
        (scratchpad / "_recon_worker_pool_contract.json").write_text(
            json.dumps(
                {
                    "version": 1,
                    "phase": "recon",
                    "pipeline": config.get("pipeline", "sc"),
                    "mode": config.get("mode", "core"),
                    "outputs": [str(job.get("output") or "") for job in jobs],
                    "jobs": jobs,
                    "created_at": datetime.now(timezone.utc).isoformat(),
                },
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )
    except Exception as exc:
        log.warning(f"[recon] could not write worker-pool contract marker: {exc}")

    def _finalize_recon_outputs(final_attempt: int):
        _merge_recon_worker_shards_and_arm_finalization(
            scratchpad,
            config,
            supervised_attempt=_recon_outer_attempt_from_worker(final_attempt),
        )
        if str(config.get("pipeline") or "sc").lower() == "sc":
            research = _run_recon_dependency_research_wave(
                scratchpad=scratchpad,
                project_root=project_root,
                config=config,
                phase=phase,
                base_cmd=base_cmd,
                env=env,
                timeout=timeout,
                quiescence_s=quiescence_s,
                attempt=final_attempt,
            )
            log.info(
                "[recon] external-dependency wave: status=%s researched=%s "
                "unresolved=%s truncated=%s",
                research.get("status"),
                research.get("researched", 0),
                research.get("unresolved", 0),
                research.get("truncated", False),
            )
        passed, missing = gate_passes(scratchpad, project_root, phase)
        return passed, missing

    budget = _RECON_WORKER_ROUNDS_PER_PHASE_ATTEMPT
    for pool_attempt in range(1, budget + 1):
        worker_attempt = _recon_worker_attempt_ordinal(attempt, pool_attempt)
        open_jobs = []
        for job in jobs:
            ok, _reasons = _recon_worker_complete(
                scratchpad, job["output"], job, config
            )
            if not ok:
                open_jobs.append(job)
        if not open_jobs:
            try:
                passed, missing = _finalize_recon_outputs(worker_attempt)
            except ReconPrepassDispatchBlocked:
                raise
            except (CanonicalMergeAuthorityError, ArtifactLedgerError) as exc:
                log.error(
                    "[recon] finalize authority failed closed: %r", exc
                )
                return -4
            except Exception as exc:
                log.warning(f"[recon] finalize/research wave failed: {exc!r}")
                return -2
            if passed:
                return 0
            log.warning(f"[recon] worker-pool canonical gate failed: {missing}")
            return -2
        log.info(
            f"[recon] worker PTY pool attempt {pool_attempt}: "
            f"{len(open_jobs)} open shard(s), concurrency={concurrency}"
        )
        pool_allowed_outputs = [str(job["output"]) for job in open_jobs]
        input_snapshot = _snapshot_worker_input_artifacts(
            scratchpad,
            set(pool_allowed_outputs),
        )
        protected_input_names = set(input_snapshot)
        results: list[dict[str, Any]] = []
        runnable_jobs: list[dict[str, str]] = []
        worker_timeout = max(900, timeout)
        # Serialize ledger binding before the concurrent pool starts.  The
        # leaf runner repeats this only when invoked outside the pool (for
        # example the conditional dependency-research wave).
        for job in open_jobs:
            fatal_binding_issues = _prepare_typed_model_worker_launch(
                phase=phase,
                config=config,
                scratchpad=scratchpad,
                project_root=project_root,
                agent_id=str(job.get("agent_id") or job["output"]),
                output=str(job["output"]),
                timeout_s=worker_timeout,
                attempt=worker_attempt,
            )
            if fatal_binding_issues:
                results.append({
                    "output": str(job["output"]),
                    "rc": -2,
                    "status": "input_authority_debt",
                    "reasons": fatal_binding_issues,
                })
            else:
                runnable_jobs.append(job)
        display.print_phase_heartbeat(
            "recon",
            int(time.time() - pool_started),
            status=_format_worker_pool_progress_status(
                complete=len(jobs) - len(open_jobs),
                total=len(jobs),
                active_outputs=[j["output"] for j in runnable_jobs[:concurrency]],
                queued=max(0, len(runnable_jobs) - concurrency),
                phase_label="recon",
            ),
        )
        try:
            with _JoiningWorkerPool(
                max_workers=concurrency,
                thread_name_prefix="plamen-recon-worker",
            ) as executor:
                fut_to_job = {
                    executor.submit(
                        _run_single_recon_worker_pty,
                        job=job,
                        scratchpad=scratchpad,
                        project_root=project_root,
                        config=config,
                        phase=phase,
                        base_cmd=base_cmd,
                        env=env,
                        # full scaled budget per worker (parity with breadth/
                        # rescan/depth); the 2400 cap starved workers below
                        # scale_timeout on large repos.
                        timeout=worker_timeout,
                        quiescence_s=quiescence_s,
                        attempt=worker_attempt,
                        retry_reasons=retry_reasons_by_output.get(job["output"]),
                        allowed_outputs=pool_allowed_outputs,
                        protected_input_names=protected_input_names,
                        inputs_prebound=True,
                    ): job
                    for job in runnable_jobs
                }
                pending_futs: set[concurrent.futures.Future] = set(fut_to_job)
                last_progress = time.time()
                while pending_futs:
                    done, pending_futs = concurrent.futures.wait(
                        pending_futs,
                        timeout=_WORKER_POOL_UI_POLL_S,
                        return_when=concurrent.futures.FIRST_COMPLETED,
                    )
                    now = time.time()
                    elapsed = int(now - pool_started)
                    display.spin(elapsed)
                    if display.graceful_stop.requested:
                        _cancel_pending_worker_futures(pending_futs, executor)
                        raise _PtyStop(-3)
                    for fut in done:
                        try:
                            result = fut.result()
                        except ReconPrepassDispatchBlocked:
                            _cancel_pending_worker_futures(
                                pending_futs, executor
                            )
                            raise
                        results.append(result)
                        output = result.get("output", "(unknown)")
                        status = result.get("status")
                        log.info(f"[recon] worker {output}: {status}")
                        display.print_phase_heartbeat(
                            "recon",
                            elapsed,
                            status=f"worker {output}: {status}",
                        )
                        if result.get("status") == "rate_limited":
                            log.warning(
                                "[recon] worker %s hit rate limit; stopping "
                                "remaining workers and surfacing phase-level "
                                "rate-limit pause",
                                output,
                            )
                            _cancel_pending_worker_futures(pending_futs, executor)
                            return 1
                        last_progress = now
                    if pending_futs and now - last_progress >= _WORKER_POOL_HEARTBEAT_S:
                        display.print_phase_heartbeat(
                            "recon",
                            elapsed,
                            status=(
                                f"recon worker pool active: {len(pending_futs)} "
                                "worker(s) still running"
                            ),
                        )
                        last_progress = now
        finally:
            restored_inputs = _restore_worker_input_artifacts(
                scratchpad,
                input_snapshot,
            )
            if restored_inputs:
                log.info(
                    "[recon] restored %d pre-existing scratchpad input "
                    "artifact(s) modified during worker batch: %s",
                    len(restored_inputs),
                    restored_inputs[:10],
                )
        if any(r.get("status") == "rate_limited" for r in results):
            return 1
        if any(r.get("rc") == -4 for r in results):
            log.error("[recon] worker-pool containment violation")
            return -4
        remaining_jobs = []
        for job in jobs:
            ok, _reasons = _recon_worker_complete(
                scratchpad, job["output"], job, config
            )
            if not ok:
                remaining_jobs.append(job)
        if not remaining_jobs:
            try:
                passed, missing = _finalize_recon_outputs(worker_attempt)
            except ReconPrepassDispatchBlocked:
                raise
            except (CanonicalMergeAuthorityError, ArtifactLedgerError) as exc:
                log.error(
                    "[recon] finalize authority failed closed: %r", exc
                )
                return -4
            except Exception as exc:
                log.warning(f"[recon] finalize/research wave failed: {exc!r}")
                return -2
            if passed:
                return 0
            log.warning(f"[recon] worker-pool canonical gate failed: {missing}")
            return -2
        retry_reasons_by_output = {
            str(r.get("output")): [
                f"status={r.get('status')}",
                *[str(x) for x in (r.get("reasons") or [])],
            ]
            for r in results
            if r.get("status") != "complete"
        }
    log.warning("[recon] worker-pool retry budget exhausted")
    # Haltless tail: rather than discarding the work of every worker that DID
    # reach COMPLETE, merge the completed shards and see whether the canonical
    # gate is satisfied. A partial merge never overwrites a complete mechanical
    # artifact (the >=100B merge branch preserves the mechanical body at top and
    # appends the shard as a Recon Worker Addendum).
    completed_jobs = []
    remaining_jobs = []
    for job in jobs:
        ok, _reasons = _recon_worker_complete(
            scratchpad, job["output"], job, config
        )
        if ok:
            completed_jobs.append(job)
        else:
            remaining_jobs.append(job)
    try:
        passed, missing = _finalize_recon_outputs(
            _recon_worker_attempt_ordinal(attempt, budget)
        )
    except ReconPrepassDispatchBlocked:
        raise
    except (CanonicalMergeAuthorityError, ArtifactLedgerError) as exc:
        log.error(
            "[recon] finalize authority failed closed: %r", exc
        )
        return -4
    except Exception as exc:
        log.warning(f"[recon] partial finalize/research failed: {exc!r}")
        return -2
    if passed:
        log.info(
            "[recon] partial-merge over %d/%d completed shards passed canonical "
            "gate; continuing haltless",
            len(completed_jobs),
            len(jobs),
        )
        return 0
    degraded, _new_missing = _try_recon_prepass_marker_degrade(
        scratchpad, config, list(missing)
    )
    if degraded:
        return 0
    log.warning(
        "[recon] partial-merge over %d/%d completed shards did not satisfy "
        "the canonical gate: %s",
        len(completed_jobs),
        len(jobs),
        missing,
    )
    return -2


def _run_and_publish_recon_worker_pool_attempt(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
    log_path: Path,
    canonical: Path,
    started_at: float,
) -> int:
    """Execute one pool invocation and publish only its fresh transcripts."""
    recon_worker_logs_before = _recon_worker_log_state(scratchpad)
    try:
        rc = _run_recon_worker_pool_pty(
            scratchpad=scratchpad,
            project_root=project_root,
            config=config,
            phase=phase,
            base_cmd=base_cmd,
            env=env,
            timeout=timeout,
            quiescence_s=quiescence_s,
            attempt=attempt,
        )
    except _PtyStop as stop:
        rc = stop.rc
    duration = time.time() - started_at
    try:
        with log_path.open("w", encoding="utf-8", errors="replace") as out:
            out.write(
                f"recon worker-pool completed rc={rc} "
                f"after {duration:.0f}s\n\n"
            )
            for worker_log in _recon_worker_logs_generated_since(
                scratchpad, recon_worker_logs_before
            ):
                out.write(f"\n\n# {worker_log.name}\n")
                try:
                    out.write(
                        worker_log.read_text(
                            encoding="utf-8", errors="replace"
                        )
                    )
                except Exception as exc:
                    out.write(f"[could not read worker log: {exc}]\n")
            if rc == 1:
                out.write(
                    "\nPLAMEN_RATE_LIMIT_DETECTED=1 "
                    "api_error_status=429 "
                    "type=rate_limit_error "
                    "phase=recon source=recon_worker_pool\n"
                )
        canonical.write_bytes(log_path.read_bytes())
    except Exception:
        pass
    log.info(
        f"[{phase.name}] PTY worker pool completed rc={rc} "
        f"after {duration:.0f}s"
    )
    return rc


