def _breadth_manifest_jobs(scratchpad: Path) -> list[dict[str, str]]:
    """Return one concrete worker job per breadth manifest output."""
    outputs = parse_breadth_manifest_outputs(scratchpad) or []
    agents = parse_breadth_manifest_agents(scratchpad) or []
    jobs: list[dict[str, str]] = []
    for idx, name in enumerate(outputs):
        agent = agents[idx] if idx < len(agents) else {}
        stem = name
        if stem.startswith("analysis_"):
            stem = stem[len("analysis_"):]
        if stem.endswith(".md"):
            stem = stem[:-3]
        focus = agent.get("focus_area") or stem
        agent_id = agent.get("agent_id") or f"B{idx + 1}"
        jobs.append({
            "agent_id": str(agent_id),
            "focus_area": str(focus),
            "output": str(name),
        })
    return jobs


def _truthy_l1_flag(text: str, flag: str) -> bool:
    flag_re = re.escape(flag)
    patterns = (
        rf"\b{flag_re}\b\s*[:=|]\s*(?:true|yes|present|detected|enabled|1)\b",
        rf"\b{flag_re}\b[^\n\r]{{0,80}}(?:true|yes|present|detected|enabled)",
        rf"(?:true|yes|present|detected|enabled)[^\n\r]{{0,80}}\b{flag_re}\b",
    )
    false_re = re.compile(
        rf"\b{flag_re}\b\s*[:=|]\s*(?:false|no|absent|none|disabled|0)\b",
        re.IGNORECASE,
    )
    if false_re.search(text or ""):
        return False
    return any(re.search(p, text or "", re.IGNORECASE) for p in patterns)


def _false_l1_flag(text: str, flag: str) -> bool:
    return bool(
        re.search(
            rf"\b{re.escape(flag)}\b\s*[:=|]\s*(?:false|no|absent|none|disabled|0)\b",
            text or "",
            re.IGNORECASE,
        )
    )


def _l1_breadth_active_layer_defs(scratchpad: Path) -> list[dict[str, Any]]:
    blobs: list[str] = []
    for name in (
        "recon_summary.md",
        "subsystem_map.md",
        "attack_surface.md",
        "trust_boundaries.md",
        "template_recommendations.md",
    ):
        p = scratchpad / name
        try:
            if p.exists():
                blobs.append(p.read_text(encoding="utf-8", errors="replace")[:200_000])
        except Exception:
            pass
    text = "\n".join(blobs)
    active: list[dict[str, Any]] = []
    for layer in _L1_BREADTH_LAYERS:
        flags = tuple(str(f) for f in layer.get("flags") or ())
        if any(_truthy_l1_flag(text, f) for f in flags):
            active.append(layer)
            continue
        if flags and all(_false_l1_flag(text, f) for f in flags):
            continue
        layer_name = str(layer["layer"]).replace("_", "[-_ ]?")
        if re.search(rf"\b{layer_name}\b", text, re.IGNORECASE):
            active.append(layer)
    if not active:
        # Conservative fallback: if recon used an unexpected flag format, keep
        # recall by covering every L1 layer rather than passing a small quorum.
        active = list(_L1_BREADTH_LAYERS)
    return active


def _l1_breadth_group_has_high_difficulty(job: list[dict[str, Any]]) -> bool:
    return any(str(x.get("difficulty")) == "HIGH" for x in job)


def _merge_l1_breadth_layers(
    layers: list[dict[str, Any]],
    mode: str,
) -> list[list[dict[str, Any]]]:
    # Soft caps mirror the audit-mode intent. HIGH layers are never merged
    # with another HIGH layer; if the target cap cannot be met without doing
    # that, preserve quality and exceed the cap.
    target = {"light": 3, "core": 5, "thorough": 7}.get(
        (mode or "core").lower(),
        5,
    )
    jobs = [[layer] for layer in layers]

    while len(jobs) > target:
        merge_idx: tuple[int, int] | None = None
        for i in range(len(jobs)):
            if len(jobs[i]) >= 3:
                continue
            for j in range(i + 1, len(jobs)):
                if len(jobs[i]) + len(jobs[j]) > 3:
                    continue
                if (
                    _l1_breadth_group_has_high_difficulty(jobs[i])
                    and _l1_breadth_group_has_high_difficulty(jobs[j])
                ):
                    continue
                merge_idx = (i, j)
                break
            if merge_idx:
                break
        if not merge_idx:
            break
        i, j = merge_idx
        jobs[i] = jobs[i] + jobs[j]
        del jobs[j]
    return jobs


def _l1_breadth_jobs(scratchpad: Path, config: dict) -> list[dict[str, str]]:
    layer_defs = _l1_breadth_active_layer_defs(scratchpad)
    merged = _merge_l1_breadth_layers(layer_defs, str(config.get("mode", "core")))
    jobs: list[dict[str, str]] = []
    for idx, group in enumerate(merged, start=1):
        names = [str(layer["layer"]) for layer in group]
        primary = names[0]
        output = f"analysis_layer_{primary}.md"
        focus = ", ".join(names)
        skills = "; ".join(str(layer.get("skills") or "") for layer in group)
        difficulty = "/".join(str(layer.get("difficulty") or "") for layer in group)
        jobs.append({
            "agent_id": f"L1B{idx}",
            "focus_area": focus,
            "output": output,
            "layers": ",".join(names),
            "skills": skills,
            "difficulty": difficulty,
        })
    return jobs


def _breadth_worker_jobs(scratchpad: Path, config: dict) -> list[dict[str, str]]:
    if (config.get("pipeline") or "sc") == "l1":
        return _l1_breadth_jobs(scratchpad, config)
    return _breadth_manifest_jobs(scratchpad)


def _breadth_open_jobs(
    scratchpad: Path,
    phase: Phase,
    jobs: list[dict[str, str]],
) -> list[dict[str, str]]:
    statuses = {
        r.get("name"): r.get("status")
        for r in compute_breadth_row_statuses(scratchpad, phase)
    }
    return [
        job for job in jobs
        if statuses.get(job["output"]) not in ("complete", "legacy_unmarked")
    ]


def _should_use_breadth_worker_pool(config: dict, scratchpad: Path) -> bool:
    """Return True when breadth can be scheduled as driver-owned workers."""
    if (config.get("pipeline") or "sc") == "l1":
        try:
            return bool(_l1_breadth_jobs(scratchpad, config))
        except Exception:
            return False
    manifest = scratchpad / "spawn_manifest.md"
    if not manifest.exists():
        return False
    try:
        return bool(parse_breadth_manifest_outputs(scratchpad))
    except Exception:
        return False


# FIX (recall #1): condensed Rule-13 anti-normalization + a mandate to
# PROMOTE matrix-cell divergences to findings. Surfaced to every SC breadth
# worker (the rule otherwise lives only in generic-security-rules.md, which the
# breadth prompt never reads). Kept short on purpose — the 5-Question core +
# the promotion mandate, not the full 38-line rule block — so it sharpens
# recall without diluting attention.
_BREADTH_ANTI_NORMALIZATION_DIRECTIVE = """
## Anti-Normalization & Divergence Promotion (MANDATORY — Rule 13)

Do NOT close a real divergence with "intended" / "by design" / "correct
architecture" inside a self-check or interaction matrix. A matrix/checklist cell
that identifies a divergence from a documented invariant (effective value !=
documented value; unbounded user input; retroactive/stale parameter; asymmetric
deposit/withdraw or create/consume path; a fee/rate that stacks or exceeds its
documented cap) MUST be promoted to a `## Finding [` block. A divergence left in
a matrix cell is a recall failure. "intended"/"by design" describes a MECHANISM,
not a disposition — it is acceptable ONLY with cited intent evidence
(spec/test/comment).

Before marking any behavior a non-issue because it looks intentional, answer the
5-Question Test: (1) Who is harmed (specific user class)? (2) Can affected users
avoid the harm through their own actions, or is it imposed? (3) Is the harm
documented (informed consent)? (4) Could the protocol achieve the same goal
without the harm? (5) Does the function fulfill its stated purpose completely (no
missing case/asset/state)? Verdict: harmed AND unavoidable AND undocumented ->
FINDING; harmed AND (documented OR avoidable) -> INFO finding; no one harmed ->
genuine non-issue. Also model PASSIVE attacks (timing normal operations at a
favorable state), not only active front-running.
"""


def _load_breadth_semantic_operator_kernel() -> str:
    """Load the single versioned SC breadth floor, or degrade loudly.

    The Markdown file is the source shared with the Codex adapter. Keeping the
    content out of this module prevents backend copies from drifting. A broken
    install remains haltless, but cannot masquerade as complete coverage.
    """
    path = (
        plamen_home()
        / "prompts"
        / "shared"
        / "v2"
        / "breadth-semantic-operator-kernel.md"
    )
    try:
        text = path.read_text(encoding="utf-8").strip()
        if (
            "PLAMEN_BREADTH_SEMANTIC_KERNEL: BEGIN v1.0.0" not in text
            or "PLAMEN_BREADTH_SEMANTIC_KERNEL: END v1.0.0" not in text
        ):
            raise ValueError("version markers missing")
        return text
    except Exception as exc:
        log.error(f"[breadth] semantic-operator kernel unavailable: {exc!r}")
        return (
            "## [BREADTH-KERNEL-UNAVAILABLE] Human review required\n\n"
            f"The mandatory SC breadth kernel could not be loaded from `{path}`. "
            "Do not treat this worker as complete security-method coverage."
        )


# Per-program PAYABLE-IMPACT steering. Generic, names no protocol — the program
# specifics live ONLY in the generated `impact_map.md` DATA artifact (rendered by
# the gitignored bounty bracket into the harness/PROJECT_ROOT). This block is
# surfaced to recon/breadth/depth ONLY when that file is present, so paid audits
# (no impact_map.md) are entirely unaffected: it STEERS the finite attention an
# agent already has toward terminal payable impacts WITHOUT cutting coverage.
_IMPACT_MAP_DIRECTIVE = """
## Payable-Impact Steering (impact_map.md present)

Read the exact registered evidence projection `{IMPACT_MAP_EVIDENCE}`. It is
the authoritative PAYABLE-IMPACT ranking for this engagement: per the program's own severity rules
and declared in-scope impacts, it lists which concrete consequences are payable
and at what tier. For every candidate you investigate, answer: "which payable
row in the evidence projection does this candidate's TERMINAL impact realize, and at what
tier?" — and trace the candidate to that impact first. Spend depth on the
highest-payable rows first.

This STEERS where your finite attention goes; it does NOT narrow what you may
report and does NOT cut coverage. The projection lists IMPACTS that matter, NOT
vulnerabilities that exist — it is not a checklist of bugs to confirm; you must
still discover the mechanism that produces the impact. A finding that realizes
no payable row is out of payout scope: record it, but do not spend depth budget
prioritizing it. If the projection declares primacy-of-impact, an unlisted impact
still pays at its universal VSC baseline — do not de-prioritize a real impact
merely because it is unlisted.
"""


# Recon variant: recon's job is to PROPAGATE the map into design_context.md so
# every downstream phase inherits the steering even where impact_map.md isn't
# surfaced directly. Generic, names no protocol.
_IMPACT_MAP_RECON_NOTE = """
## Payable-Impact Map (impact_map.md present)

Read the exact registered evidence projection `{IMPACT_MAP_EVIDENCE}` — the
program's PAYABLE-IMPACT ranking (payable consequences and tiers from its own
severity rules). Include its "Payable impacts" table and derived Operational
Implications in your assigned recon shard so the driver can merge them into the
canonical design context. Do not write `design_context.md` or any alternate
output. This propagates the payable focus downstream; it does not narrow scope.
"""


def _impact_map_block(
    project_root: str,
    scratchpad: Path,
    kind: str = "analysis",
) -> str:
    """Return the payable-impact steering directive iff `impact_map.md` exists in
    PROJECT_ROOT (BB harness root). Empty for paid audits — clean unconditional
    injection at the splice point. File-presence-gated so the committed driver
    carries only this generic seam; all program specifics live in the artifact.

    `kind="recon"` returns the propagate-into-design_context note; otherwise the
    candidate-prioritization directive for breadth/depth."""
    try:
        if project_root and (Path(project_root) / "impact_map.md").is_file():
            template = (
                _IMPACT_MAP_RECON_NOTE if kind == "recon"
                else _IMPACT_MAP_DIRECTIVE
            )
            return template.format(
                IMPACT_MAP_EVIDENCE=(
                    Path(scratchpad) / _IMPACT_MAP_EVIDENCE_FILE
                ).resolve(strict=False).as_posix()
            )
    except Exception:
        pass
    return ""


def _materialize_impact_map_evidence(
    *, project_root: str, scratchpad: Path,
) -> list[str]:
    """Snapshot the optional project impact map into exact PhaseIO evidence."""

    project = Path(project_root)
    source = project / "impact_map.md"
    if not rooted_io.lexists(source):
        return []
    try:
        canonical_project = project.resolve(strict=True)
        canonical_source = source.resolve(strict=True)
        if canonical_source != canonical_project / "impact_map.md":
            raise ValueError(
                "impact_map.md resolves outside its exact project-root name"
            )
        checked = rooted_io.checked_file(
            source,
            label="impact-map source",
            require_single_link=True,
            verify_ancestors=True,
            verify_exact_name=True,
        )

        def stable_row() -> tuple[int, ...]:
            row = rooted_io.lstat(checked)
            return (
                int(row.st_dev),
                int(row.st_ino),
                int(row.st_size),
                int(row.st_mtime_ns),
                int(row.st_ctime_ns),
                int(getattr(row, "st_file_attributes", 0)),
                int(getattr(row, "st_reparse_tag", 0)),
                int(getattr(row, "st_nlink", 1)),
            )

        before = stable_row()
        if before[2] > _IMPACT_MAP_MAX_BYTES:
            raise ValueError(
                f"impact_map.md exceeds {_IMPACT_MAP_MAX_BYTES} bytes"
            )
        raw = rooted_io.read_bytes(
            checked,
            label="impact-map source",
            require_single_link=True,
            verify_ancestors=True,
            verify_exact_name=True,
            max_bytes=_IMPACT_MAP_MAX_BYTES,
        )
        after = stable_row()
        if (
            before != after
            or len(raw) != before[2]
            or len(raw) > _IMPACT_MAP_MAX_BYTES
        ):
            raise ValueError("impact_map.md changed during its bounded read")
        text = raw.decode("utf-8", errors="strict")
        source_sha256 = hashlib.sha256(raw).hexdigest()
        payload = (
            "<!-- PLAMEN_IMPACT_MAP_EVIDENCE_V1 -->\n"
            "<!-- SOURCE_IDENTITY: project:impact_map.md -->\n"
            f"<!-- SOURCE_SHA256: {source_sha256} -->\n\n"
            "# Bound Payable-Impact Evidence\n\n"
            "The payload below is a byte-faithful UTF-8 snapshot of the "
            "engagement input.\n\n"
            "## Source Payload\n\n"
            + text
        ).encode("utf-8")
        destination = Path(scratchpad) / _IMPACT_MAP_EVIDENCE_FILE
        if rooted_io.lexists(destination):
            existing = rooted_io.read_bytes(
                destination,
                label="impact-map evidence destination",
                require_single_link=True,
                verify_ancestors=True,
                verify_exact_name=True,
                max_bytes=_IMPACT_MAP_MAX_BYTES + 2048,
            )
            if existing == payload:
                return []
        _atomic_driver_bytes(destination, payload)
        return []
    except (
        OSError,
        UnicodeError,
        ValueError,
        rooted_io.RootedPathIOError,
    ) as exc:
        return [
            "impact_map.md could not be snapshotted into typed evidence: "
            f"{type(exc).__name__}: {exc}"
        ]


def _skill_checklist_step_ids(path: Path) -> list[str]:
    """Extract stable top-level methodology obligations from SKILL.md.

    Prefer the explicit Step Execution Checklist table.  Legacy skills without
    that section fall back to explicit ``Step N`` headings and bare numbered
    H2 methodology headings.  A methodology that still cannot be enumerated is
    represented by a durable WHOLE_METHOD obligation, never an empty/closable
    set.
    """
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return []
    in_checklist = False
    ids: list[str] = []
    for raw in lines:
        line = raw.strip()
        if re.match(r"^#{2,6}\s+Step Execution Checklist\b", line, re.I):
            in_checklist = True
            continue
        if in_checklist and re.match(r"^#{1,2}\s+", line):
            break
        if not in_checklist:
            continue
        if line.startswith("|"):
            cells = [c.strip().strip("`*") for c in line.strip("|").split("|")]
            if not cells or not cells[0] or cells[0].lower() in {"section", "step", "id"}:
                continue
            if all(set(cell) <= {"-", ":", " "} for cell in cells):
                continue
            match = re.match(r"^([0-9]+[a-z]?(?:\.[0-9]+[a-z]?)?)\b", cells[0], re.I)
            if match and match.group(1) not in ids:
                ids.append(match.group(1))
            continue
        match = re.match(r"^(?:[-*]\s+)?(?:\[[ xX]\]\s*)?([0-9]+[a-z]?)\s*[.)-]", line)
        if match and match.group(1) not in ids:
            ids.append(match.group(1))
    if ids:
        return ids

    excluded_title = re.compile(
        r"\b(?:output(?:\s+schema|\s+format|\s+template)?|finding\s+template|"
        r"references?|cross[- ]references?|integration(?:\s+notes?)?|"
        r"known\s+bug\s+exemplars?)\b",
        re.IGNORECASE,
    )
    for raw in lines:
        line = raw.strip()
        explicit = re.match(
            r"^#{2,3}\s+Step\s+([0-9]+[a-z]?(?:\.[0-9]+[a-z]?)?)"
            r"(?:\s*[:.)-]|\s+)",
            line,
            re.IGNORECASE,
        )
        if explicit:
            step_id = explicit.group(1)
            title = line[explicit.end():].strip()
            if not excluded_title.search(title) and step_id not in ids:
                ids.append(step_id)
            continue
        numbered_h2 = re.match(
            r"^##\s+([0-9]+[a-z]?(?:\.[0-9]+[a-z]?)?)\s*[.)]\s+(.+)$",
            line,
            re.IGNORECASE,
        )
        if numbered_h2:
            step_id, title = numbered_h2.groups()
            if not excluded_title.search(title) and step_id not in ids:
                ids.append(step_id)
    if ids:
        return ids

    # Final generic fallback: substantive H2 headings are stable typed
    # obligations even when a legacy skill has no numbered checklist. Exclude
    # presentation/reference/coordinator sections rather than converting the
    # entire file into one untestable WHOLE_METHOD claim.
    excluded_h2 = re.compile(
        r"\b(?:output(?:\s+format|\s+schema)?|finding\s+template|"
        r"report(?:ing)?\s+template|references?|common\s+dimensions\s+reference|"
        r"agent\s+prompt\s+template|test\s+file\s+template|"
        r"poc\s+script\s+templates?|your\s+inputs?|why\s+(?:a\s+)?(?:niche|dedicated)|"
        r"when\s+this\s+agent\s+spawns?|chain\s+summary)\b",
        re.IGNORECASE,
    )
    headings: list[tuple[str, str]] = []
    for raw in lines:
        match = re.match(r"^##\s+(.+?)\s*$", raw.strip())
        if not match:
            continue
        title = re.sub(r"\s+", " ", match.group(1)).strip(" `*#:-")
        if not title or excluded_h2.search(title):
            continue
        base = re.sub(r"[^a-z0-9]+", "-", title.casefold()).strip("-")
        if base:
            headings.append((title, base[:80]))
    if headings:
        counts: dict[str, set[str]] = {}
        for title, base in headings:
            counts.setdefault(base, set()).add(title.casefold())
        out: list[str] = []
        seen_titles: set[str] = set()
        for title, base in headings:
            title_key = title.casefold()
            if title_key in seen_titles:
                continue
            seen_titles.add(title_key)
            slug = base
            if len(counts[base]) > 1:
                suffix = hashlib.sha256(title_key.encode("utf-8")).hexdigest()[:8]
                slug = f"{base}-{suffix}"
            out.append(f"h2:{slug}")
        if out:
            return out
    return ["WHOLE_METHOD/UNENUMERATED"]


def _skill_dispatch_descriptor(name: str, path: Path) -> dict[str, Any]:
    data = path.read_bytes()
    step_ids = _skill_checklist_step_ids(path)
    return {
        "skill": str(name).strip().upper().replace("-", "_"),
        "path": path.as_posix(),
        "sha256": hashlib.sha256(data).hexdigest(),
        "top_level_checklist_step_ids": step_ids,
        "enumeration_status": (
            "UNENUMERATED_WHOLE_METHOD"
            if step_ids == ["WHOLE_METHOD/UNENUMERATED"]
            else "ENUMERATED"
        ),
    }


def _l1_breadth_skill_descriptors(job: dict[str, str]) -> list[dict[str, Any]]:
    """Resolve the L1 layer's prose skill list against the installed catalog."""
    haystack = str(job.get("skills") or "").lower()
    base = plamen_home() / "agents" / "skills" / "injectable" / "l1"
    out: list[dict[str, Any]] = []
    try:
        candidates = sorted(base.glob("*/SKILL.md"))
    except OSError:
        candidates = []
    for path in candidates:
        slug = path.parent.name.lower()
        # Layer definitions may use a shortened phrase (e.g. "fork-choice")
        # only when no exact catalog slug is present. Prefer exact installed
        # slugs; shortened prose is surfaced as an unresolved label by the
        # existing L1 layer block rather than guessed across methodologies.
        if re.search(rf"(?<![a-z0-9-]){re.escape(slug)}(?![a-z0-9-])", haystack):
            out.append(_skill_dispatch_descriptor(slug, path))
    return out


def _breadth_job_skill_descriptors(
    job: dict[str, str], scratchpad: Path, config: dict
) -> list[dict[str, Any]]:
    pipeline = str(config.get("pipeline", "sc"))
    if pipeline == "l1":
        return _l1_breadth_skill_descriptors(job)
    language = str(config.get("language", ""))
    breadth_map, _ = _parse_sc_skill_bindings(
        scratchpad,
        language,
        pipeline=pipeline,
        mode=str(config.get("mode") or "core"),
        backend=str(config.get("cli_backend") or "claude"),
    )
    names = breadth_map.get(str(job.get("focus_area") or "").lower(), [])
    descriptors: list[dict[str, Any]] = []
    for name in names:
        path = _sc_skill_path_for_name(name, language)
        if path is not None:
            descriptors.append(_skill_dispatch_descriptor(name, path))
    return descriptors


def _skill_dispatch_prompt_block(
    descriptors: list[dict[str, Any]], *, agent_kind: str,
    inline_content: bool = False,
) -> str:
    if not descriptors:
        return ""
    lines = [
        "", "## ASSIGNED SKILL METHODOLOGY (MANDATORY)", "",
        "The Python driver resolved these exact, content-bound methodology files:",
    ]
    for item in descriptors:
        step_ids = ", ".join(item["top_level_checklist_step_ids"])
        if item.get("projection_kind") == "DRIVER_RENDERED_EXACT_SECTION":
            lines.append(
                f"- `{item['skill']}`: apply the driver-rendered exact section "
                f"projection below (source SHA-256 `{item['sha256']}`, "
                f"projection SHA-256 `{item['projection_sha256']}`). Its "
                f"Step Execution Checklist IDs are: {step_ids}. Do not open "
                "the multi-worker source template."
            )
        else:
            if inline_content:
                logical = Path(item["path"]).resolve(strict=True).relative_to(
                    plamen_home().resolve(strict=True)
                ).as_posix()
                lines.append(
                    f"- `{item['skill']}`: apply the exact bound projection below "
                    f"(logical source `{logical}`, SHA-256 `{item['sha256']}`). "
                    f"Its Step Execution Checklist IDs are: {step_ids}."
                )
            else:
                lines.append(
                    f"- `{item['skill']}`: read `{item['path']}` (SHA-256 "
                    f"`{item['sha256']}`). Its Step Execution Checklist IDs are: "
                    f"{step_ids}."
                )
    lines.extend([
        "",
        f"As this {agent_kind} worker, apply every listed methodology to the assigned scope. "
        "Prompt delivery is not application proof: record each executed/partial/unexecuted "
        "step with concrete evidence in the output's Step Execution Trace.",
        "",
    ])
    if inline_content:
        lines.extend([
            "## Bound skill methodology projections",
            "",
            "These projections are the complete assigned skill inputs. Do not "
            "attempt to re-open their installed source paths.",
            "",
        ])
        for item in descriptors:
            if item.get("projection_kind") == "DRIVER_RENDERED_EXACT_SECTION":
                continue
            lines.append(_render_bound_methodology_projection(
                Path(str(item["path"])),
                title=f"skill {item['skill']}",
                expected_sha256=str(item["sha256"]),
            ))
    return "\n".join(lines)


def _build_breadth_worker_prompt(
    *,
    job: dict[str, str],
    scratchpad: Path,
    project_root: str,
    config: dict,
    attempt: int,
    retry_reasons: list[str] | None = None,
    skill_descriptors: list[dict[str, Any]] | None = None,
    dispatch_contract_sha256: str | None = None,
) -> str:
    output = job["output"]
    agent_id = job["agent_id"]
    focus = job["focus_area"]
    pipeline = str(config.get("pipeline", "sc"))
    methodology_path = (
        plamen_home() / "prompts" / "l1" / "phase3-breadth-driver.md"
        if pipeline == "l1"
        else plamen_home() / "prompts" / "shared" / "v2" / "phase3-breadth.md"
    )
    finding_format_path = (
        plamen_home() / "rules" / "finding-output-format.md"
    )
    methodology_projection = _render_bound_methodology_projection(
        methodology_path,
        title="breadth execution procedure projection v1",
        expected_sha256=_BOUND_BREADTH_METHODOLOGY_SOURCE_SHA256[
            "l1_execution" if pipeline == "l1" else "sc_execution"
        ],
        effective_text=(
            _L1_BREADTH_WORKER_EXECUTION_PROJECTION
            if pipeline == "l1"
            else _SC_BREADTH_WORKER_EXECUTION_PROJECTION
        ),
    )
    finding_format_projection = _render_bound_methodology_projection(
        finding_format_path,
        title="finding output format",
        expected_sha256=_BOUND_BREADTH_METHODOLOGY_SOURCE_SHA256[
            "finding_format"
        ],
    )
    # Runtime placeholder expansion belongs to the worker wrapper, never to
    # authenticated methodology bytes. Insert all bound projections only after
    # the legacy wrapper has been rendered so braces inside a SKILL.md cannot
    # be rewritten while retaining the source's advertised digest.
    methodology_projection_slot = "<!-- PLAMEN_BOUND_BREADTH_PROCEDURE_SLOT -->"
    finding_format_projection_slot = "<!-- PLAMEN_BOUND_FINDING_FORMAT_SLOT -->"
    skill_projection_slot = "<!-- PLAMEN_BOUND_BREADTH_SKILLS_SLOT -->"
    shard = scratchpad / _opengrep_shard_filename(agent_id, focus)
    shard_line = (
        f"- Assigned opengrep shard: `{shard.as_posix()}`"
        if shard.exists()
        else (
            f"- Assigned opengrep shard: `{shard.as_posix()}` "
            "(not present; use recon/source context)"
        )
    )
    registered_inputs = _typed_worker_registered_input_paths(
        phase_name="breadth",
        scratchpad=scratchpad,
        config=config,
        agent_id=agent_id,
        output=output,
        focus_area=focus,
        attempt=attempt,
    )
    evidence_lines = "\n".join(
        f"- `scratchpad:{path}`" for path in registered_inputs
    )
    # The plan resolves these exactly once. Re-resolution here would allow a
    # manifest/methodology edit between planning and rendering to make the
    # prompt differ from the persisted dispatch.
    if skill_descriptors is None:
        skill_descriptors = _breadth_job_skill_descriptors(job, scratchpad, config)
    bound_skill_block = _skill_dispatch_prompt_block(
        skill_descriptors,
        agent_kind="breadth",
        inline_content=True,
    )
    contract_entry = {
        "worker_id": str(agent_id),
        "output": str(output),
        "methodologies": list(skill_descriptors),
    }
    dispatch_contract_sha256 = (
        dispatch_contract_sha256
        or worker_dispatch_contract_sha256("breadth", contract_entry)
    )
    dispatch_markers = worker_dispatch_markers(
        "breadth", str(agent_id), str(output), dispatch_contract_sha256
    )
    dispatch_marker_contract = "`\n   `".join(dispatch_markers.splitlines())
    l1_block = ""
    if pipeline == "l1":
        layers = job.get("layers", focus)
        skills = job.get("skills", "")
        difficulty = job.get("difficulty", "")
        l1_block = f"""
## L1 Layer Assignment

- Layers: `{layers}`
- Difficulty: `{difficulty}`
- L1 skills to apply: {skills}

Follow the bound L1 breadth layer-decomposition methodology projected below.
For each assigned layer, perform trust-boundary audit, opengrep
cross-reference, skill-directed analysis, concurrency/panic checks where
applicable, and write the mandatory Chain Summary table.
{skill_projection_slot if bound_skill_block else ""}
"""
    retry_block = ""
    if retry_reasons:
        retry_block = (
            "\n## Previous Gate Failure\n\n"
            + "\n".join(f"- {r}" for r in retry_reasons)
            + "\n"
        )
    # P1: inject the recon-selected skills bound to this focus area (SC only;
    # L1 already injects via l1_block above).
    sc_skill_block = ""
    if pipeline != "l1":
        sc_skill_block = skill_projection_slot if bound_skill_block else ""
    # FIX (recall #1): Rule-13 anti-normalization + divergence-promotion.
    # R13 lives only in generic-security-rules.md and was never surfaced to the
    # breadth worker — so a real divergence observed inside a self-check matrix
    # row ("...combined effective rate > sum, intended") was closed by the word
    # "intended" and never became a finding. Inject the condensed 5-Question
    # test + a mandate that a matrix-cell divergence MUST be promoted to a
    # `## Finding` block. SC only (L1 carries its own anti-normalization).
    r13_block = "" if pipeline == "l1" else _BREADTH_ANTI_NORMALIZATION_DIRECTIVE
    # R0-1: the compact security-reasoning floor survives an empty or missed
    # recon skill selection. L1 owns a separate layer methodology.
    semantic_kernel_block = (
        "" if pipeline == "l1" else _load_breadth_semantic_operator_kernel()
    )
    # Payable-impact steering (BB mode only — gated on impact_map.md presence in
    # PROJECT_ROOT; inert for paid audits). Applies to L1 and SC bounty lanes.
    impact_map_block = _impact_map_block(project_root, scratchpad)
    step_trace_contract = ""
    if skill_descriptors:
        obligations = [
            f"`{item['skill']}` / `{step_id}`"
            for item in skill_descriptors
            for step_id in item["top_level_checklist_step_ids"]
        ]
        step_trace_contract = f"""
5. Include exactly one `## Step Execution Trace` section immediately before
   the final COMPLETE marker. Its authoritative representation is JSON between
   these exact sentinel lines (a Markdown table may follow only as a projection):

   `{TRACE_JSON_BEGIN}`
   `{{"schema_version":1,"rows":[{{"skill":"...","step":"...","executed":"yes|partial|no|unknown","evidence":"relative/source.ext:L42","result":"step-specific result"}}]}}`
   `{TRACE_JSON_END}`

   Include exactly one typed JSON object with exactly the five shown string
   fields for every dispatched skill/step pair: {', '.join(obligations)}.
   Preserve typed step IDs exactly (`1.1` is not `11`). `Executed=yes` requires
   step-specific concrete source evidence. Delivery and this producer trace are
   attestations, never proof. SAFE/no-finding/N/A and generic results cannot
   close their own obligation and will be routed to independent skepticism.
   `WHOLE_METHOD/UNENUMERATED` is a durable whole-method obligation and cannot
   be closed as N/A merely because no checklist table was parsed.
"""
    prompt = f"""# BREADTH ROW WORKER

You are a single breadth worker launched directly by the Python Plamen driver.
There is no Claude phase coordinator. Your job is to produce exactly one
artifact and then stop.

## Assignment

- PROJECT_ROOT: `{project_root}`
- SCRATCHPAD: `{scratchpad.as_posix()}`
- LANGUAGE: `{config.get('language', 'unknown')}`
- MODE: `{config.get('mode', 'unknown')}`
- PIPELINE: `{config.get('pipeline', 'sc')}`
- SUBSYSTEM_SCOPE: `{config.get('subsystem_scope') or '(none)'}`
- SCOPE_FILE: `{config.get('scope_file') or '(none)'}`
- SCOPE_NOTES: `{config.get('scope_notes') or '(none)'}`
- Agent ID: `{agent_id}`
- Focus area: `{focus}`
- Output file: `{output}`
- Attempt: `{attempt}`
{shard_line}
{l1_block}

## Finding Identity Contract

Every finding heading in this artifact MUST use `[{agent_id}-<N>]`, where N is
a positive decimal integer starting at 1 (for example `[{agent_id}-1]`). Do not
prefix the worker ID with a focus abbreviation or add another hyphen-delimited
namespace. This producer-local identity is validated before inventory.

## Output Allowlist

Write exactly this file and no other scratchpad artifact:

`{scratchpad.as_posix()}/{output}`

Do not infer, invent, or create any other output file. If any methodology text
asks for a different output filename, ignore that output request and write only
the file above.
{retry_block}
## Methodology

The breadth execution procedure and finding format are projected below as
content-bound prompt inputs. Do not attempt to read their installed source
paths. The breadth procedure is not vulnerability coverage. You are already
the worker; do not spawn Task/Agent subagents and do not follow any coordinator
instructions.

{methodology_projection_slot}
{finding_format_projection_slot}
The complete registered scratchpad
evidence denominator for this row is finite and listed below; do not enumerate
the scratchpad, guess alternate artifacts, or read another breadth output:

{evidence_lines}

The assigned opengrep shard is an obligation projection, not proof. If a
listed input is absent, report that evidence gap instead of probing substitutes.
{semantic_kernel_block}
{sc_skill_block}{r13_block}{impact_map_block}
## Required File Contract

The output file must:

1. Start with these markers:
   `{dispatch_marker_contract}`
   `<!-- PLAMEN_ARTIFACT: {output} -->`
   `<!-- PLAMEN_OWNER: {agent_id} -->`
   `<!-- PLAMEN_STATUS: IN_PROGRESS -->`
   `<!-- PLAMEN_PHASE: breadth -->`
   `<!-- PLAMEN_VERSION: 1 -->`
   `<!-- AGENT_ROW: {agent_id} -->`
   `<!-- EXPECTED_OUTPUT: {output} -->`
2. Contain substantive security analysis for the assigned focus area.
3. Include either real `## Finding [` / `### Finding [` blocks or a
   `## No Findings` rationale.
4. End with a final `<!-- PLAMEN_STATUS: COMPLETE -->` marker only after the
   file is fully written and verified on disk.
{step_trace_contract}

When done, return exactly one line:

`DONE: {output} complete`
"""
    rendered = _render_runtime_placeholders(prompt, config)
    for slot, projection in (
        (methodology_projection_slot, methodology_projection),
        (finding_format_projection_slot, finding_format_projection),
        (skill_projection_slot, bound_skill_block),
    ):
        expected = 1 if slot in prompt else 0
        if rendered.count(slot) != expected or slot in projection:
            raise ValueError("bound breadth methodology projection slot drifted")
        if expected:
            rendered = rendered.replace(slot, projection)
    return _compile_typed_worker_prompt(
        rendered,
        config=config,
        phase_name="breadth",
        agent_id=agent_id,
        output=output,
        focus_area=focus,
        exact_inputs=registered_inputs,
        attempt=attempt,
    )


def _breadth_dispatch_plan(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    attempt: int,
    retry_reasons_by_output: dict[str, list[str]] | None = None,
) -> list[dict[str, Any]]:
    """Render the canonical per-row breadth prompts for every backend.

    Backend launchers consume this plan rather than reconstructing a
    coordinator prompt. Thus Claude PTY, Claude headless, and Codex receive
    identical ecosystem-resolved SKILL.md directives for a given manifest row;
    only the backend transport wrapper may differ afterward.
    """
    reasons = retry_reasons_by_output or {}
    plan: list[dict[str, Any]] = []
    for job in _breadth_worker_jobs(scratchpad, config):
        skill_dispatch = _breadth_job_skill_descriptors(job, scratchpad, config)
        contract_entry = {
            "worker_id": str(job.get("agent_id") or ""),
            "output": str(job.get("output") or ""),
            "methodologies": skill_dispatch,
        }
        dispatch_contract_sha256 = worker_dispatch_contract_sha256(
            "breadth", contract_entry
        )
        prompt = _build_breadth_worker_prompt(
            job=job,
            scratchpad=scratchpad,
            project_root=project_root,
            config=config,
            attempt=attempt,
            retry_reasons=reasons.get(str(job.get("output") or "")),
            skill_descriptors=skill_dispatch,
            dispatch_contract_sha256=dispatch_contract_sha256,
        )
        plan.append({
            "job": job,
            "prompt": prompt,
            "prompt_sha256": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
            "skill_dispatch": skill_dispatch,
            "dispatch_contract_sha256": dispatch_contract_sha256,
        })
    return plan


def _write_breadth_dispatch_contract(
    scratchpad: Path,
    config: dict,
    backend: str,
    plan: list[dict[str, Any]],
    dispatched_outputs: set[str] | None = None,
) -> None:
    """Persist scheduling metadata plus the authoritative per-row dispatch.

    On a mixed retry, replace only entries whose workers are actually launched.
    Completed rows retain their last-executed prompt/contract identity rather
    than being rebound to a retry prompt they never received.
    """
    rows = []
    planned_entries: dict[str, dict[str, Any]] = {}
    for entry in plan:
        job = dict(entry["job"])
        rows.append({
            **job,
            "prompt_sha256": entry["prompt_sha256"],
        })
        application_entry = {
            "worker_id": str(job.get("agent_id") or ""),
            "output": str(job.get("output") or ""),
            "prompt_sha256": entry["prompt_sha256"],
            "prompt_snapshot_required": True,
            "prompt_snapshot_glob": "_prompt_breadth_worker_*.attempt*.md",
            "methodologies": list(entry.get("skill_dispatch") or []),
            "dispatch_contract_sha256": str(
                entry.get("dispatch_contract_sha256") or ""
            ),
        }
        planned_entries[application_entry["output"]] = application_entry

    selected = (
        set(planned_entries)
        if dispatched_outputs is None
        else {str(value) for value in dispatched_outputs}
    )
    existing_by_output: dict[str, dict[str, Any]] = {}
    try:
        existing_payload = json.loads(
            (scratchpad / "skill_dispatch.json").read_text(encoding="utf-8")
        )
        existing_phase = existing_payload.get("phases", {}).get("breadth", {})
        for old_entry in existing_phase.get("entries", []):
            if isinstance(old_entry, dict) and old_entry.get("output"):
                existing_by_output[str(old_entry["output"])] = old_entry
    except (OSError, json.JSONDecodeError, TypeError, AttributeError):
        pass

    application_entries: list[dict[str, Any]] = []
    for output in [str(row.get("output") or "") for row in rows]:
        if output in selected:
            application_entries.append(planned_entries[output])
        elif output in existing_by_output:
            application_entries.append(existing_by_output[output])
        else:
            # A legacy/resumed output has no observed launch contract. Keep it
            # measurable as an explicit gap; never invent an executed prompt.
            unobserved = dict(planned_entries[output])
            unobserved["prompt_sha256"] = "0" * 64
            unobserved["launch_state"] = "NOT_OBSERVED"
            application_entries.append(unobserved)
    phase_dispatch = write_phase_dispatch(
        scratchpad,
        phase="breadth",
        backend=backend,
        entries=application_entries,
    )
    payload = {
        "version": 2,
        "phase": "breadth",
        "backend": backend,
        "pipeline": config.get("pipeline", "sc"),
        "outputs": [str(row.get("output") or "") for row in rows],
        "jobs": rows,
        "skill_dispatch_file": "skill_dispatch.json",
        "skill_dispatch_sha256": phase_dispatch["dispatch_sha256"],
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    try:
        (scratchpad / "_breadth_worker_pool_contract.json").write_text(
            json.dumps(payload, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
    except Exception as exc:
        log.warning(f"[breadth] could not write dispatch contract: {exc}")


_METHODOLOGY_REPAIR_OUTPUT = "analysis_methodology_repair_breadth.md"
_METHODOLOGY_REPAIR_ATTEMPT = "methodology_repair_attempt_breadth.json"


def _methodology_repair_output(source_phase: str) -> str:
    if source_phase == "depth":
        # Depth runs after inventory. Use the typed feeder family consumed by
        # the normal pre-verify depth-promotion bridge; an analysis_* repair
        # would otherwise wait until the report-time orphan harvest.
        return "depth_methodology_repair_findings.md"
    return f"analysis_methodology_repair_{source_phase}.md"


def _methodology_repair_attempt_file(source_phase: str) -> str:
    return f"methodology_repair_attempt_{source_phase}.json"


def _methodology_application_mode(config: dict) -> str:
    """Return the experiment-gated *accepted-boundary* control mode.

    Exact, digest-bound methodology delivery and producer JSON traces are
    always part of the hardened discovery contract.  This switch controls only
    what happens after the accepted breadth/depth producer barrier: ``off``
    performs no post-boundary validation, ``observe`` emits deterministic
    application debt, and ``repair`` adds one bounded exact-gap producer.

    Therefore ``off`` is not a byte-for-byte legacy prompt control.  Fair A/B
    comparisons must pin the legacy implementation hash rather than mislabel
    this switch as disabling delivery.  The old config/env names remain aliases
    for compatibility; the explicit ``*_BOUNDARY_MODE`` names are preferred.
    """
    default_mode = (
        "repair"
        if str(config.get("mode") or "core").lower() in {"core", "thorough"}
        else "off"
    )
    raw = str(
        config.get("methodology_application_boundary_mode")
        or config.get("methodology_application_mode")
        or os.environ.get("PLAMEN_METHODOLOGY_APPLICATION_BOUNDARY_MODE")
        or os.environ.get("PLAMEN_METHODOLOGY_APPLICATION_MODE")
        or default_mode
    ).strip().lower()
    if raw not in {"off", "observe", "repair"}:
        log.warning(
            "[methodology-application] unknown mode %r; using mode default %r",
            raw, default_mode,
        )
        return default_mode
    return raw


def _atomic_driver_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(
        json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    os.replace(temporary, path)


def _methodology_exact_gap_descriptors(
    result: dict[str, Any], trusted_root: Path
) -> list[dict[str, Any]]:
    """Project only exact, trusted GAP rows into repair methodologies."""
    grouped: dict[tuple[str, str, str], dict[str, Any]] = {}
    root = trusted_root.resolve()
    for row in result.get("rows", []):
        completeness = str(row.get("application_completeness") or "").upper()
        if completeness:
            if completeness not in {"MISSING", "INVALID"}:
                continue
        elif row.get("disposition") != "GAP":
            continue
        skill = str(row.get("skill") or "").strip()
        raw_path = str(row.get("methodology_path") or "").strip()
        sha = str(row.get("methodology_sha256") or "").strip().lower()
        step = str(row.get("step") or "").strip()
        if not skill or skill.startswith("[") or not raw_path or not step:
            continue
        try:
            path = Path(raw_path).resolve()
            if path != root and not path.is_relative_to(root):
                continue
            if hashlib.sha256(path.read_bytes()).hexdigest() != sha:
                continue
        except (OSError, ValueError):
            continue
        key = (skill, path.as_posix(), sha)
        descriptor = grouped.setdefault(
            key,
            {
                "skill": skill,
                "path": path.as_posix(),
                "sha256": sha,
                "top_level_checklist_step_ids": [],
                "source_gap_obligations": [],
            },
        )
        if step not in descriptor["top_level_checklist_step_ids"]:
            descriptor["top_level_checklist_step_ids"].append(step)
        descriptor["source_gap_obligations"].append(
            {
                "obligation_id": str(row.get("obligation_id") or ""),
                "worker_id": str(row.get("worker_id") or ""),
                "output": str(row.get("output") or ""),
                "output_sha256": str(row.get("output_sha256") or ""),
                "step": step,
                "original_evidence": str(
                    row.get("original_evidence") or row.get("evidence") or ""
                ),
                "original_result": str(
                    row.get("original_result") or row.get("result") or ""
                ),
                "reason": str(row.get("reason") or ""),
            }
        )
    return list(grouped.values())


def _build_methodology_repair_plan(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    source_result: dict[str, Any],
    source_phase: str = "breadth",
) -> dict[str, Any] | None:
    """Build one backend-neutral producer prompt for exact GAP obligations."""
    repair_source = source_result
    queue_path = Path(scratchpad) / f"methodology_repair_queue_{source_phase}.json"
    if queue_path.is_file():
        try:
            queue_payload = json.loads(queue_path.read_text(encoding="utf-8"))
            application_states.validate_queue_payload(
                queue_payload, expected_kind="repair"
            )
            if queue_payload.get("phase") != source_phase:
                raise ValueError("repair queue phase mismatch")
            repair_source = {"rows": list(queue_payload["rows"])}
        except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
            log.warning(
                "[methodology-application] authoritative repair queue invalid; "
                "retaining debt instead of parsing Markdown: %r",
                exc,
            )
            return None
    methodologies = _methodology_exact_gap_descriptors(repair_source, plamen_home())
    if not methodologies:
        return None
    phase_token = re.sub(r"[^A-Z0-9]+", "_", source_phase.upper()).strip("_")
    worker_id = f"METHODOLOGY_APPLICATION_REPAIR_{phase_token}"
    output = _methodology_repair_output(source_phase)
    finding_id_prefix = {
        "breadth": "MAB",
        "rescan": "MAR",
        "depth": "MAD",
    }.get(source_phase, "MAP")
    contract_entry = {
        "worker_id": worker_id,
        "output": output,
        "methodologies": methodologies,
    }
    contract_sha = worker_dispatch_contract_sha256(
        f"{source_phase}_repair", contract_entry
    )
    markers = worker_dispatch_markers(
        f"{source_phase}_repair", worker_id, output, contract_sha
    )
    obligations: list[str] = []
    methodology_lines: list[str] = []
    for descriptor in methodologies:
        steps = descriptor["top_level_checklist_step_ids"]
        try:
            exact_methodology = Path(descriptor["path"]).read_bytes().decode("utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            log.warning(
                "[methodology-application] exact bound methodology became "
                "unreadable before repair prompt construction: %r",
                exc,
            )
            return None
        methodology_lines.append(
            f"- `{descriptor['skill']}`: `{descriptor['path']}` (SHA-256 "
            f"`{descriptor['sha256']}`), exact GAP steps: "
            + ", ".join(f"`{step}`" for step in steps)
            + "\n"
            + f"<PLAMEN_METHOD_BYTES skill=\"{descriptor['skill']}\" "
            + f"sha256=\"{descriptor['sha256']}\">\n"
            + exact_methodology
            + f"\n</PLAMEN_METHOD_BYTES skill=\"{descriptor['skill']}\">"
        )
        for source in descriptor["source_gap_obligations"]:
            obligations.append(
                "- obligation `{}`; skill `{}` step `{}` from worker `{}` / "
                "`{}` (source SHA-256 `{}`); original evidence `{}`; original "
                "result `{}`; repair reason: {}".format(
                    source["obligation_id"] or "[LEGACY-UNBOUND]",
                    descriptor["skill"],
                    source["step"],
                    source["worker_id"],
                    source["output"],
                    source["output_sha256"] or "[UNAVAILABLE]",
                    source["original_evidence"] or "[NONE]",
                    source["original_result"] or "[NONE]",
                    source["reason"],
                )
            )
    prompt = f"""# TARGETED METHODOLOGY APPLICATION REPAIR

You are one independent repair producer. The deterministic driver found exact
    methodology-attestation GAP rows after the accepted {source_phase} producer barrier.
Execute ONLY those rows. Do not rerun {source_phase}, do not review non-GAP steps, do
not disposition an earlier finding, and do not claim that your own trace is
proof. Any candidate you discover must use the normal finding format so later
inventory and verification stages judge it independently.

## Assignment

- PROJECT_ROOT: `{project_root}`
- SCRATCHPAD: `{scratchpad.as_posix()}`
- OUTPUT: `{scratchpad.as_posix()}/{output}`
- LANGUAGE: `{config.get('language', 'unknown')}`
- PIPELINE: `{config.get('pipeline', 'sc')}`
- MODE: `{config.get('mode', 'unknown')}`

## Exact content-bound methodologies

{chr(10).join(methodology_lines)}

## Exact GAP obligations

{chr(10).join(obligations)}

The exact methodology bytes above were re-read and SHA-256 verified by the
driver during prompt construction. Apply only their listed steps, the cited
source outputs for context, and project source needed to execute them. A GAP
reason is routing metadata, not an expected vulnerability answer.

## Output contract

Write exactly `{scratchpad.as_posix()}/{output}` and no other artifact. Start
with these exact markers:

{markers}
<!-- PLAMEN_ARTIFACT: {output} -->
<!-- PLAMEN_OWNER: {worker_id} -->
<!-- PLAMEN_STATUS: IN_PROGRESS -->
<!-- PLAMEN_PHASE: {source_phase}_repair -->
<!-- PLAMEN_VERSION: 1 -->
<!-- AGENT_ROW: {worker_id} -->
<!-- EXPECTED_OUTPUT: {output} -->

Include either normal `## Finding [` blocks for newly discovered candidates or
a substantive `## No Findings` account. Immediately before the final COMPLETE
marker, write exactly one `## Step Execution Trace` and authoritative JSON:

Finding IDs MUST use `{finding_id_prefix}-<N>` (for example
`{finding_id_prefix}-1`) so downstream typed promotion and reconciliation can
preserve identity without guessing from prose.

{TRACE_JSON_BEGIN}
{{"schema_version":1,"rows":[{{"skill":"...","step":"...","executed":"yes|partial|no|unknown","evidence":"relative/source.ext:L42","result":"step-specific result"}}]}}
{TRACE_JSON_END}

Emit exactly one typed row per GAP step listed above. Preserve typed step IDs.
Source evidence must resolve under PROJECT_ROOT. SAFE/no-finding/N/A or generic
producer results remain independent-skeptic obligations; your trace never
certifies itself. End only when fully written with:

<!-- PLAMEN_STATUS: COMPLETE -->

Return exactly: `DONE: {output} complete`
"""
    prompt = _render_runtime_placeholders(prompt, config)
    prompt = _compile_typed_worker_prompt(
        prompt,
        config=config,
        phase_name=source_phase,
        agent_id="methodology_repair",
        output=output,
        source_phase=source_phase,
        work_category=(
            "standard" if source_phase == "depth"
            else "rescan" if source_phase == "rescan"
            else "*"
        ),
    )
    prompt_sha = hashlib.sha256(prompt.encode("utf-8")).hexdigest()
    entry = {
        **contract_entry,
        "prompt_sha256": prompt_sha,
        "prompt_snapshot_required": True,
        "prompt_snapshot_glob": (
            f"_prompt_{source_phase}_repair_worker_{worker_id}.attempt*.md"
        ),
        "dispatch_contract_sha256": contract_sha,
        "source_phase": source_phase,
        "source_dispatch_sha256": str(source_result.get("dispatch_sha256") or ""),
    }
    return {"job": {"agent_id": worker_id, "output": output}, "prompt": prompt, "entry": entry}


def _load_json_object(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
        return value if isinstance(value, dict) else {}
    except (OSError, UnicodeError, json.JSONDecodeError):
        return {}


def _run_methodology_repair_producer(
    *,
    plan: dict[str, Any],
    phase: Phase,
    config: dict,
    scratchpad: Path,
) -> int:
    """Launch one bounded repair using existing hardened backend runners."""
    backend = str(config.get("cli_backend") or "claude").lower()
    model = phase_model(phase, str(config.get("mode") or "core"), config)
    timeout = max(
        60.0,
        min(1800.0, float(config.get("methodology_repair_timeout_s") or 900.0)),
    )
    job = dict(plan["job"])
    prompt = str(plan["prompt"])
    output = str(job["output"])
    source_phase = re.sub(
        r"[^a-z0-9]+", "_", str(plan.get("entry", {}).get("source_phase") or phase.name).lower()
    ).strip("_") or "methodology"
    label_prefix = f"{source_phase}_repair_worker"
    model_contract, model_launch = _typed_model_worker_contract_and_launch(
        phase=phase,
        config=config,
        scratchpad=Path(scratchpad),
        project_root=str(config["project_root"]),
        agent_id="methodology_repair",
        output=output,
        timeout_s=timeout,
        source_phase=source_phase,
        attempt=1,
    )
    if backend == "codex":
        return _run_one_codex_exec(
            prompt=prompt,
            phase=phase,
            config=config,
            scratchpad=scratchpad,
            attempt=1,
            label=f"{label_prefix}_{job['agent_id']}",
            expected_outputs=[output],
            timeout=timeout,
            effective_model=model,
            phase_io_contract=model_contract,
            phase_io_launch=model_launch,
        )
    # Claude PTY and headless breadth both use the configured Claude provider,
    # model, isolation, timeout, cost, and error machinery. The bounded repair
    # is deliberately a one-turn `claude -p` producer, not another coordinator.
    return _run_one_claude_headless_breadth_worker(
        prompt=prompt,
        job=job,
        phase=phase,
        config=config,
        scratchpad=scratchpad,
        attempt=1,
        timeout=timeout,
        effective_model=model,
        label_prefix=label_prefix,
        source_phase=source_phase,
        phase_io_contract=model_contract,
        phase_io_launch=model_launch,
    )


def _run_methodology_application_boundary(
    phase: Phase,
    config: dict,
    scratchpad: Path,
    *,
    source_phase: str = "breadth",
) -> dict[str, Any] | None:
    """Validate accepted breadth and optionally run one exact-gap repair.

    This is haltless by construction. All failures become durable human-review
    debt; the normal phase is never rerun and no finding receives a disposition.
    """
    mode = _methodology_application_mode(config)
    if mode == "off":
        return None
    try:
        source_result = validate_phase_application(
            scratchpad,
            Path(config["project_root"]),
            phase=source_phase,
            trusted_methodology_roots=[plamen_home()],
        )
    except Exception as exc:
        source_result = {
            "status": "UNMEASURABLE",
            "phase": source_phase,
            "rows": [],
            "reason": f"application validator failed haltlessly: {exc!r}",
        }
        log.warning("[methodology-application] validation degraded: %r", exc)

    if mode != "repair" or source_result.get("status") not in {"GAPS", "UNMEASURABLE"}:
        write_human_review_projection(
            scratchpad,
            source_phase=source_phase,
            source_result=source_result,
            repair_enabled=False,
            repair_attempted=False,
        )
        return source_result

    plan = _build_methodology_repair_plan(
        scratchpad=scratchpad,
        project_root=str(config["project_root"]),
        config=config,
        source_result=source_result,
        source_phase=source_phase,
    )
    if plan is None:
        write_human_review_projection(
            scratchpad,
            source_phase=source_phase,
            source_result=source_result,
            repair_enabled=True,
            repair_attempted=False,
        )
        return source_result

    write_phase_dispatch(
        scratchpad,
        phase=f"{source_phase}_repair",
        backend=str(config.get("cli_backend") or "claude"),
        entries=[plan["entry"]],
    )
    attempt_path = scratchpad / _methodology_repair_attempt_file(source_phase)
    prior = _load_json_object(attempt_path)
    source_digest = str(source_result.get("dispatch_sha256") or "")
    already_attempted = (
        prior.get("source_dispatch_sha256") == source_digest
        and prior.get("state") in {"RUNNING", "FINISHED"}
    )
    rc: int | None = None
    if not already_attempted:
        _atomic_driver_json(
            attempt_path,
            {
                "schema_version": 1,
                "state": "RUNNING",
                "source_dispatch_sha256": source_digest,
                "repair_prompt_sha256": plan["entry"]["prompt_sha256"],
                "started_at": datetime.now(timezone.utc).isoformat(),
            },
        )
        try:
            repair_output = _methodology_repair_output(source_phase)
            repair_timeout = max(
                60.0,
                min(
                    1800.0,
                    float(config.get("methodology_repair_timeout_s") or 900.0),
                ),
            )
            fatal_binding_issues = _prepare_typed_model_worker_launch(
                phase=phase,
                config=config,
                scratchpad=scratchpad,
                project_root=str(config["project_root"]),
                agent_id="methodology_repair",
                output=repair_output,
                timeout_s=repair_timeout,
                source_phase=source_phase,
                debt_phase=f"{source_phase}_repair",
                debt_code="METHODOLOGY_REPAIR_PRELAUNCH_INPUT_DEBT",
            )
            if fatal_binding_issues:
                rc = -2
            else:
                before = _snapshot_worker_input_artifacts(
                    scratchpad, {repair_output}
                )
                rc = _run_methodology_repair_producer(
                    plan=plan, phase=phase, config=config, scratchpad=scratchpad
                )
                restored = _restore_worker_input_artifacts(scratchpad, before)
                if restored:
                    log.warning(
                        "[methodology-application] repair modified protected inputs; "
                        "restored=%s",
                        restored,
                    )
            if rc == 0 and (scratchpad / repair_output).is_file():
                contract_issues = _record_typed_model_worker_artifact(
                    phase=phase,
                    config=config,
                    scratchpad=scratchpad,
                    project_root=str(config["project_root"]),
                    agent_id="methodology_repair",
                    output=repair_output,
                    timeout_s=repair_timeout,
                    source_phase=source_phase,
                )
                if contract_issues:
                    rc = -2
                    log.warning(
                        "[methodology-application] typed repair artifact debt: %s",
                        "; ".join(contract_issues),
                    )
        except Exception as exc:
            rc = EXIT_ERROR
            log.warning("[methodology-application] repair failed haltlessly: %r", exc)
        _atomic_driver_json(
            attempt_path,
            {
                "schema_version": 1,
                "state": "FINISHED",
                "source_dispatch_sha256": source_digest,
                "repair_prompt_sha256": plan["entry"]["prompt_sha256"],
                "return_code": rc,
                "finished_at": datetime.now(timezone.utc).isoformat(),
            },
        )

    try:
        repair_result = validate_phase_application(
            scratchpad,
            Path(config["project_root"]),
            phase=f"{source_phase}_repair",
            trusted_methodology_roots=[plamen_home()],
        )
    except Exception as exc:
        repair_result = {
            "status": "UNMEASURABLE",
            "phase": f"{source_phase}_repair",
            "rows": [],
            "reason": f"repair validator failed haltlessly: {exc!r}",
        }
    write_human_review_projection(
        scratchpad,
        source_phase=source_phase,
        source_result=source_result,
        repair_result=repair_result,
        repair_enabled=True,
        repair_attempted=True,
    )
    return repair_result


_APPLICATION_SKEPTIC_BASE_PHASES = ("breadth", "rescan", "depth")
_CANDIDATE_NEGATIVE_BASE_PHASES = (
    "breadth",
    "rescan",
    "depth",
    "attention_repair",
    "axis_coverage",
)


def _candidate_negative_phase_artifacts(
    phase: Phase,
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[CandidateNegativeArtifactInput]:
    """Enumerate accepted producer Markdown by declared/registered contract."""

    root = Path(scratchpad)
    patterns = list(getattr(phase, "expected_artifacts", ()) or ())
    for group in getattr(phase, "any_of", ()) or ():
        patterns.extend(group)
    patterns.extend(
        _registered_producer_patterns(
            "resume_hashing", owner_phase=phase.name
        )
    )
    # Attention findings are conditional and not part of the legacy phase's
    # single required summary artifact.
    if phase.name == "attention_repair":
        patterns.append("attention_repair_findings.md")
    patterns = list(dict.fromkeys(patterns))

    dispatch_entries: dict[str, Mapping[str, Any]] = {}
    try:
        dispatch = json.loads((root / "skill_dispatch.json").read_text("utf-8"))
        phase_entry = (dispatch.get("phases") or {}).get(phase.name) or {}
        for entry in phase_entry.get("entries") or ():
            if isinstance(entry, Mapping) and str(entry.get("output") or ""):
                dispatch_entries[
                    Path(str(entry["output"])).as_posix().casefold()
                ] = entry
    except (OSError, UnicodeError, json.JSONDecodeError, TypeError):
        dispatch_entries = {}

    seen: set[Path] = set()
    artifacts: list[CandidateNegativeArtifactInput] = []
    for pattern in patterns:
        for candidate in sorted(root.glob(pattern)):
            try:
                resolved = candidate.resolve(strict=True)
                if resolved in seen or not candidate.is_file():
                    continue
                relative = candidate.relative_to(root).as_posix()
            except (OSError, ValueError):
                continue
            seen.add(resolved)
            if candidate.suffix.casefold() != ".md":
                continue
            if relative.startswith("_") or relative.startswith("candidate_negative_"):
                continue
            entry = dispatch_entries.get(relative.casefold(), {})
            producer = str(
                entry.get("worker_id")
                or entry.get("agent_id")
                or f"{phase.name.upper()}::{relative}"
            )
            invocation = str(
                entry.get("producer_invocation_id")
                or entry.get("launch_id")
                or entry.get("prompt_sha256")
                or (
                    "CNPINV-"
                    + hashlib.sha256(
                        "\0".join(
                            (
                                str(config.get("_run_id") or "unbound"),
                                phase.name,
                                relative,
                            )
                        ).encode("utf-8")
                    ).hexdigest()[:24].upper()
                )
            )
            try:
                content = candidate.read_bytes()
            except OSError:
                continue
            artifacts.append(
                CandidateNegativeArtifactInput(
                    relative_path=relative,
                    content=content,
                    producer_identity=producer,
                    producer_invocation_id=invocation,
                )
            )
    return artifacts


def _candidate_negative_harvest_contract_and_launch(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    exact_inputs: tuple[str, ...],
    exact_output: str,
) -> tuple[PhaseIOContract, LaunchSpec]:
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="candidate_negative_authority",
        work_unit_id=f"harvest.{phase.name}",
        exact_outputs=(exact_output,),
        exact_inputs=exact_inputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _record_candidate_negative_harvest_io(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    exact_inputs: tuple[str, ...],
    exact_output: str,
    domain_issues: Sequence[str] = (),
) -> list[str]:
    """Commit a candidate-negative harvest that was armed before its write."""
    contract, launch = _candidate_negative_harvest_contract_and_launch(
        phase=phase,
        config=config,
        scratchpad=scratchpad,
        exact_inputs=exact_inputs,
        exact_output=exact_output,
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    project_root = Path(config.get("project_root") or Path(scratchpad).parent)
    return _commit_deterministic_driver_work_unit(
        scratchpad=Path(scratchpad),
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
        domain_issues=domain_issues,
    )


def _harvest_axis_clear_candidate_negative(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> list[str]:
    """Project final typed CLEAR rows, never axis Markdown safe-language.

    The adapter consumes `axis_disposition_receipt.json` and the exact AXW
    worklist. It preserves every `work_item_id` whose final disposition is
    `CLEAR` and `application_record_complete`, but grants proof scope NONE.
    """

    root = Path(scratchpad)
    worklist_path = root / "axis_disposition_worklist.json"
    application_path = root / "axis_disposition_receipt.json"
    run_id = str(config.get("_run_id") or "").strip()
    project = Path(config.get("project_root") or root.parent)
    exact_inputs = tuple(sorted({
        worklist_path.name,
        application_path.name,
        "axis_execution_evidence_authority.json",
        *_AXIS_PRIOR_OUTPUTS,
        *_axis_project_source_inputs(project),
    }))
    output = "candidate_negative_proposals_axis_coverage.json"
    try:
        contract, launch = _candidate_negative_harvest_contract_and_launch(
            phase=phase,
            config=config,
            scratchpad=root,
            exact_inputs=exact_inputs,
            exact_output=output,
        )
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues:
            return list(dict.fromkeys(issues))
        if execute:
            ledger = build_axis_clear_candidate_negative_ledger(
                worklist_path=worklist_path,
                application_receipt_path=application_path,
                expected_run_id=run_id,
                project_root=project,
                expected_pipeline=str(config.get("pipeline") or "sc"),
                expected_mode=str(config.get("mode") or "thorough"),
                expected_ecosystem=str(
                    config.get("language") or "unknown"
                ),
            )
            write_candidate_negative_ledger(root, ledger)
            domain_issues = [
                str(row.get("code") or row)
                for row in ledger.get("issues", ())
                if isinstance(row, Mapping)
            ]
            issues.extend(_commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=domain_issues,
            ))
        else:
            ledger = parse_candidate_negative_ledger_bytes(
                (root / output).read_bytes(),
                expected_phase="axis_coverage",
            )
            validate_axis_clear_candidate_negative_ledger(
                ledger,
                worklist_path=worklist_path,
                application_receipt_path=application_path,
                expected_run_id=run_id,
                project_root=project,
                expected_pipeline=str(config.get("pipeline") or "sc"),
                expected_mode=str(config.get("mode") or "thorough"),
                expected_ecosystem=str(
                    config.get("language") or "unknown"
                ),
            )
        return list(dict.fromkeys(
            str(issue) for issue in issues if str(issue)
        ))
    except Exception as exc:
        return [
            "typed axis candidate-negative harvest failed haltlessly: "
            f"{type(exc).__name__}: {exc}"
        ]


def _harvest_candidate_negative_phase(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> list[str]:
    """Harvest structured producer negatives after the accepted barrier.

    A malformed prior append-only ledger is never overwritten as if empty.
    The failure remains visible debt and the original bytes remain intact.
    """

    if phase.name not in _CANDIDATE_NEGATIVE_BASE_PHASES:
        return []
    root = Path(scratchpad)
    if phase.name == "axis_coverage":
        if not _axis_is_scheduled(config):
            return []
        return _harvest_axis_clear_candidate_negative(
            phase, config, root
        )
    ledger_path = root / f"candidate_negative_proposals_{phase.name}.json"
    prior: dict[str, Any] | None = None
    if ledger_path.is_file():
        try:
            candidate = parse_candidate_negative_ledger_bytes(
                ledger_path.read_bytes(), expected_phase=phase.name
            )
            prior = candidate
        except (
            OSError,
            UnicodeError,
            json.JSONDecodeError,
            TypeError,
            CandidateNegativeAuthorityError,
        ) as exc:
            return [
                "candidate-negative prior ledger invalid; preserved without "
                f"overwrite: {type(exc).__name__}: {exc}"
            ]
    artifacts = _candidate_negative_phase_artifacts(phase, root, config)
    exact_inputs = tuple(sorted(
        {
            *(artifact.relative_path for artifact in artifacts),
            *(
                ("skill_dispatch.json",)
                if (root / "skill_dispatch.json").is_file()
                else ()
            ),
        }
    ))
    try:
        ledger = build_candidate_negative_ledger(
            phase=phase.name,
            artifacts=artifacts,
            methodology_path=plamen_home() / "rules" / "finding-output-format.md",
            prior_ledger=prior,
        )
        validate_candidate_negative_ledger(ledger)
        contract, launch = _candidate_negative_harvest_contract_and_launch(
            phase=phase,
            config=config,
            scratchpad=root,
            exact_inputs=exact_inputs,
            exact_output=ledger_path.name,
        )
        run_id = str(config.get("_run_id") or "test-unbound")
        project_root = Path(config.get("project_root") or root.parent)
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if arm_issues or not execute:
            return arm_issues
        write_candidate_negative_ledger(root, ledger)
    except Exception as exc:
        return [
            "candidate-negative harvest failed haltlessly: "
            f"{type(exc).__name__}: {exc}"
        ]
    domain_issues = [
        str(row.get("code") or row)
        for row in ledger.get("issues", ())
        if isinstance(row, Mapping)
    ]
    issues = _record_candidate_negative_harvest_io(
        phase=phase,
        config=config,
        scratchpad=root,
        exact_inputs=exact_inputs,
        exact_output=ledger_path.name,
    )
    return list(dict.fromkeys([*domain_issues, *issues]))


def _prepare_candidate_negative_ledger_union(
    scratchpad: Path, config: dict[str, Any]
) -> None:
    """Materialize empty ledgers only for producer phases not in this run."""

    root = Path(scratchpad)
    active = set(config.get("_active_phase_names") or ())
    method = plamen_home() / "rules" / "finding-output-format.md"
    for source in _CANDIDATE_NEGATIVE_BASE_PHASES:
        if source == "axis_coverage":
            # Axis has no generic Markdown/empty-ledger fallback. Its ledger
            # exists only after exact v2 final application authority.
            continue
        path = root / f"candidate_negative_proposals_{source}.json"
        if source in active or path.is_file():
            continue
        ledger = build_candidate_negative_ledger(
            phase=source,
            artifacts=(),
            methodology_path=method,
        )
        write_candidate_negative_ledger(root, ledger)


def _candidate_negative_phases_for_run(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return only ledgers with legitimate scheduling/producer authority."""

    phases = [
        source for source in _CANDIDATE_NEGATIVE_BASE_PHASES
        if source != "axis_coverage"
    ]
    axis_ledger = (
        Path(scratchpad)
        / "candidate_negative_proposals_axis_coverage.json"
    )
    if _axis_is_scheduled(config):
        axis_required = axis_ledger.is_file()
        try:
            axis_required = axis_required or bool(
                axis_disposition_authority.load_axis_worklist_v2(
                    Path(scratchpad)
                    / axis_disposition_authority.WORKLIST_NAME
                ).get("requires_execution")
            )
        except Exception:
            pass
        if axis_required:
            phases.append("axis_coverage")
    return tuple(phases)


def _candidate_negative_assessor_identity(
    config: dict[str, Any], plan_digest: str, shard_id: str
) -> tuple[str, str]:
    assessor = (
        "CANDIDATE_NEGATIVE_SKEPTIC_"
        + shard_id.upper().replace("-", "_")
    )
    invocation = "CNSI-" + hashlib.sha256(
        "\0".join(
            (
                str(config.get("_run_id") or "unbound"),
                plan_digest,
                shard_id,
            )
        ).encode("utf-8")
    ).hexdigest()[:24].upper()
    return assessor, invocation


def _skeptic_provider_environment(
    config: Mapping[str, Any], scratchpad: Path
) -> tuple[dict[str, str], tuple[str, ...]]:
    """Build the explicit environment for the no-tool skeptic provider."""

    if "skeptic_execution_environment" in config:
        raw = config.get("skeptic_execution_environment")
        names = config.get("skeptic_execution_environment_allowlist", ())
        if not isinstance(raw, Mapping):
            raise ValueError("skeptic execution environment must be a mapping")
        allowlist = tuple(sorted(str(name) for name in names))
        environment = {
            str(name): str(raw[name]) for name in allowlist if name in raw
        }
        if set(environment) != set(allowlist):
            raise ValueError(
                "skeptic execution environment differs from its allowlist"
            )
        return environment, allowlist

    del scratchpad
    parent = _filtered_child_subprocess_environ()
    parent_by_case = {key.casefold(): value for key, value in parent.items()}
    selected = (
        "PATH",
        "SYSTEMROOT",
        "COMSPEC",
        "TEMP",
        "TMP",
        "USERPROFILE",
        "APPDATA",
        "LOCALAPPDATA",
        "HOME",
        "TMPDIR",
        "LANG",
        "LC_ALL",
        "SSL_CERT_FILE",
        "SSL_CERT_DIR",
        "HTTPS_PROXY",
        "HTTP_PROXY",
        "NO_PROXY",
        "ANTHROPIC_API_KEY",
    )
    environment = {
        name: str(parent_by_case[name.casefold()])
        for name in selected
        if parent_by_case.get(name.casefold())
    }
    environment.update(_CLAUDE_UPDATE_DISABLE_ENV)
    return environment, tuple(sorted(environment))


def _skeptic_snapshot_binding(config: Mapping[str, Any]) -> dict[str, Any]:
    snapshot = config.get("_audit_snapshot") or config.get("audit_snapshot")
    if isinstance(snapshot, Mapping) and snapshot:
        return dict(snapshot)
    # Direct helper tests and legacy pre-checkpoint callers remain haltless, but
    # their unbound context is explicit and can never masquerade as source proof.
    return {
        "schema_version": "plamen.skeptic_snapshot_binding_debt.v1",
        "binding_state": "UNBOUND_INPUT_DEBT",
        "run_id": str(config.get("_run_id") or "test-unbound"),
    }


def _attach_skeptic_provider_debt(
    receipt: Mapping[str, Any], issues: Sequence[str]
) -> dict[str, Any]:
    """Make transport/input debt durable without changing semantic outcomes."""

    informational = (
        "quarantined legacy unauthenticated assessment",
    )
    details = list(
        dict.fromkeys(
            str(issue)
            for issue in issues
            if str(issue)
            and not any(token in str(issue) for token in informational)
        )
    )
    if not details:
        return dict(receipt)
    source_issues = list(receipt.get("source_input_issues") or [])
    existing = {
        (str(row.get("code") or ""), str(row.get("detail") or ""))
        for row in source_issues
        if isinstance(row, Mapping)
    }
    for detail in details:
        row = {"code": "SKEPTIC_PROVIDER_AUTHORITY_DEBT", "detail": detail}
        if (row["code"], row["detail"]) not in existing:
            source_issues.append(row)
    unsigned = {
        **{
            key: value for key, value in receipt.items()
            if key not in {"receipt_digest", "status", "source_input_issues"}
        },
        "status": (
            "PARTIAL" if receipt.get("status") == "PARTIAL"
            else "COMPLETED_WITH_DEBT"
        ),
        "source_input_issues": source_issues,
    }
    return {
        **unsigned,
        "receipt_digest": hashlib.sha256(
            json.dumps(
                unsigned,
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest(),
    }


_APPLICATION_SKEPTIC_DELIVERY_FILE = (
    "application_skeptic_delivery_binding.json"
)


def _skeptic_receipt_digest(unsigned: Mapping[str, Any]) -> str:
    return hashlib.sha256(
        json.dumps(
            unsigned,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _application_skeptic_preservation_context(
    plan: Mapping[str, Any], config: Mapping[str, Any]
) -> dict[str, Any]:
    """Bind last-good delivery to this exact run and snapshot mapping."""

    snapshot = _skeptic_snapshot_binding(config)
    run_id = str(config.get("_run_id") or snapshot.get("run_id") or "test-unbound")
    snapshot_id = str(
        snapshot.get("snapshot_id")
        or snapshot.get("snapshot_digest")
        or snapshot.get("run_id")
        or f"unbound-{run_id}"
    )
    snapshot_binding_sha256 = _skeptic_receipt_digest(snapshot)
    return build_application_skeptic_preservation_context(
        plan,
        run_id=run_id,
        snapshot_id=snapshot_id,
        snapshot_binding_sha256=snapshot_binding_sha256,
    )


def _prepare_positive_last_good_preservation(
    current_receipt: Mapping[str, Any],
    last_good_receipt: Mapping[str, Any] | None,
    *,
    assessed_work_item_ids: Sequence[str],
) -> tuple[dict[str, Any], bool]:
    """Expose only failed current positive rows to last-good preservation.

    The adjudicator intentionally creates a fresh proof-scope-NONE candidate
    when an assessment is unavailable.  If the same exact plan already has a
    delivered positive candidate, preserving that exact identity is preferable
    to fragmenting it into a new generic candidate.  Terminal-negative rows are
    never selected, and a work item assessed in the current attempt is never
    replaced.
    """

    if not isinstance(last_good_receipt, Mapping):
        return dict(current_receipt), False
    assessed = {str(value) for value in assessed_work_item_ids if str(value)}
    prior_positive = {
        str(row.get("work_item_id") or "")
        for row in last_good_receipt.get("work_dispositions", [])
        if isinstance(row, Mapping)
        and str(row.get("disposition") or "").upper()
        == "REGISTRY_CANDIDATE_PROPOSED"
    }
    targets = prior_positive - assessed
    if not targets:
        return dict(current_receipt), False

    rows: list[dict[str, Any]] = []
    removed_proposal_ids: set[str] = set()
    changed = False
    for raw in current_receipt.get("work_dispositions", []):
        if not isinstance(raw, Mapping):
            rows.append(raw)
            continue
        row = dict(raw)
        work_id = str(row.get("work_item_id") or "")
        if (
            work_id in targets
            and str(row.get("disposition") or "").upper()
            == "REGISTRY_CANDIDATE_PROPOSED"
        ):
            proposal_id = str(row.get("proposal_id") or "")
            if proposal_id:
                removed_proposal_ids.add(proposal_id)
            row = {
                "work_item_id": work_id,
                "obligation_id": row.get("obligation_id"),
                "input_row_ids": list(row.get("input_row_ids") or []),
                "disposition": "UNRESOLVED_DEBT",
                "reason_code": "CURRENT_PROVIDER_REASSESSMENT_UNAVAILABLE",
                "detail": (
                    "current provider authority was unavailable; exact prior "
                    "positive delivery may be preserved if its binding replays"
                ),
            }
            changed = True
        rows.append(row)
    if not changed:
        return dict(current_receipt), False

    proposals = [
        dict(row)
        for row in current_receipt.get("registry_candidate_proposals", [])
        if isinstance(row, Mapping)
        and str(row.get("proposal_id") or "") not in removed_proposal_ids
    ]
    input_dispositions = sorted(
        (
            {
                "input_row_id": input_id,
                "work_item_id": row["work_item_id"],
                "disposition": row["disposition"],
            }
            for row in rows
            if isinstance(row, Mapping)
            for input_id in row.get("input_row_ids", [])
        ),
        key=lambda row: row["input_row_id"],
    )
    unresolved = sorted(
        str(row.get("work_item_id") or "")
        for row in rows
        if isinstance(row, Mapping)
        and str(row.get("disposition") or "").upper() == "UNRESOLVED_DEBT"
    )
    unsigned = {
        **{
            key: value
            for key, value in current_receipt.items()
            if key
            not in {
                "receipt_digest",
                "status",
                "work_dispositions",
                "input_dispositions",
                "unresolved_work_item_ids",
                "registry_candidate_proposals",
            }
        },
        "status": "COMPLETED_WITH_DEBT",
        "work_dispositions": rows,
        "input_dispositions": input_dispositions,
        "unresolved_work_item_ids": unresolved,
        "registry_candidate_proposals": proposals,
    }
    return {**unsigned, "receipt_digest": _skeptic_receipt_digest(unsigned)}, True


def _execute_application_skeptic_provider_shard(
    *,
    workflow: str,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    plan: Mapping[str, Any],
    plan_name: str,
    shard: Mapping[str, Any],
    output_name: str,
    assessor_id: str,
    assessor_invocation_id: str,
    effective_model: str,
    timeout_seconds: int,
) -> tuple[list[dict[str, Any]] | None, bool, list[str]]:
    """Execute or replay one provider-owned, stdout-only skeptic shard."""

    root = Path(scratchpad)
    shard_id = str(shard.get("shard_id") or "")
    backend = str(config.get("cli_backend") or "claude").strip().lower()
    if backend == "codex":
        return None, False, [
            f"{shard_id} CODEX_BACKEND_UNSUPPORTED_DEBT: equivalent no-tool "
            "stdout provider authority is not implemented; shard remains unresolved"
        ]
    fixture_backend = backend == "fixture-subprocess" and bool(
        config.get("_skeptic_execution_test_fixture")
    )
    if backend != "claude" and not fixture_backend:
        return None, False, [
            f"{shard_id} unsupported skeptic provider backend {backend!r}; "
            "shard remains unresolved"
        ]

    issues: list[str] = []
    output_path = root / output_name
    run_id = str(config.get("_run_id") or "test-unbound")
    request = None
    try:
        rendered = build_application_skeptic_shard_prompt(
            plan,
            shard_id,
            trusted_methodology_roots=[plamen_home()],
            output_path=None,
            output_transport="STDOUT",
            context_transport="PACKET",
            assessor_id=assessor_id,
            assessor_invocation_id=assessor_invocation_id,
        )
        context = application_skeptic_packet_context(
            plan,
            shard,
            trusted_methodology_roots=[plamen_home()],
            project_root=Path(config.get("project_root") or root.parent),
            scratchpad=root,
            max_context_bytes=max(
                1,
                int(
                    config.get("application_skeptic_context_limit_bytes")
                    or 16 * 1024 * 1024
                ),
            ),
        )
        output_schema = application_skeptic_output_schema(
            plan,
            shard,
            assessor_id=assessor_id,
            assessor_invocation_id=assessor_invocation_id,
        )
        layout = skeptic_execution_layout(
            root,
            workflow=workflow,
            run_id=run_id,
            plan_digest=str(plan["work_plan_digest"]),
            shard_id=shard_id,
            canonical_output=output_name,
        )
        provider_dir = root / ".worker_execution_receipts" / layout.provider_shard_id
        # A pre-v2 model-authored assessment has no provider chain.  Preserve it
        # in quarantine, then launch through the new authority.  If any provider
        # evidence exists, do not heal around it: replay must validate or fail.
        if (
            output_path.exists()
            and not provider_dir.exists()
            and backend != "claude"
        ):
            prior_provider_projection = layout.authority_sidecar_path.is_file()
            moved, failed = _quarantine_foreign_phase_writes(
                root,
                str(config.get("project_root") or root.parent),
                "application_skeptic",
                [output_name],
            )
            if moved:
                issues.append(
                    f"{shard_id} quarantined legacy unauthenticated assessment"
                )
            if failed or output_path.exists():
                return None, False, issues + [
                    f"{shard_id} legacy unauthenticated assessment remains live"
                ]
            if prior_provider_projection:
                return None, False, issues + [
                    f"{shard_id} skeptic provider evidence was lost after a prior "
                    "authority projection; automatic relaunch is forbidden"
                ]
        policy = canonical_tool_policy(
            backend=backend,
            read_roots=[],
            staged_output=str(layout.staged_output_path),
        )
        environment, allowlist = _skeptic_provider_environment(config, root)
        if fixture_backend:
            raw_argv = config.get("_skeptic_execution_fixture_argv")
            if (
                isinstance(raw_argv, (str, bytes))
                or not isinstance(raw_argv, Sequence)
                or not raw_argv
            ):
                raise ValueError("fixture skeptic backend requires an argv vector")
            argv = tuple(str(value) for value in raw_argv)
            provider_model = "fixture-python"
        else:
            provider_model = str(effective_model)
            argv = canonical_backend_argv(
                backend="claude",
                executable=_selected_claude_backend_argv_prefix()[0],
                model=provider_model,
                tool_policy=policy,
                expected_output_schema=output_schema,
            )
            argv = _replace_claude_executable_with_selected_front(argv)
        consumer_invocation = "SKCI-" + hashlib.sha256(
            "\0".join(
                (
                    run_id,
                    workflow,
                    str(plan["work_plan_digest"]),
                    shard_id,
                )
            ).encode("utf-8")
        ).hexdigest()[:24].upper()
        request = prepare_skeptic_execution(
            scratchpad=root,
            project_root=Path(config.get("project_root") or root.parent),
            workflow=workflow,
            run_id=run_id,
            plan_path=root / plan_name,
            expected_plan_digest=str(plan["work_plan_digest"]),
            shard=shard,
            context=context,
            snapshot=_skeptic_snapshot_binding(config),
            rendered_prompt=str(rendered["prompt"]),
            expected_output_schema=output_schema,
            backend=backend,
            model=provider_model,
            argv=argv,
            tool_policy=policy,
            worker_identity=assessor_id,
            worker_invocation_id=assessor_invocation_id,
            assessor_identity="PLAMEN_SKEPTIC_PROVIDER_RECONCILER",
            assessor_invocation_id=consumer_invocation,
            canonical_output=output_name,
            timeout_seconds=max(1, int(timeout_seconds)),
            cwd=root,
            environment=environment,
            environment_allowlist=allowlist,
            parser_digest=application_skeptic_stdout_digest,
        )
        ordinal = int(shard_id.rsplit("-", 1)[-1])
        worker_id = (
            f"worker.{ordinal:04d}"
            if workflow == "application_skeptic"
            else f"negative.worker.{ordinal:04d}"
        )
        authority_name = request.layout.authority_sidecar_path.relative_to(
            root
        ).as_posix()
        transactional_claude = backend == "claude"
        (
            worker_contract,
            worker_launch,
            worker_execute,
            worker_arm_issues,
        ) = _arm_application_skeptic_io(
            scratchpad=root,
            config=config,
            phase=phase,
            work_unit_id=worker_id,
            actor=("MODEL" if transactional_claude else "DRIVER"),
            exact_outputs=(
                (output_name,)
                if transactional_claude
                else (output_name, authority_name)
            ),
            exact_inputs=(
                (request.packet_path.relative_to(root).as_posix(),)
                if transactional_claude
                else ()
            ),
            model=effective_model,
            timeout_s=int(timeout_seconds),
            tool_policy=("filesystem",),
            committed_model_methodology_digests=(
                (request.request_digest,) if transactional_claude else ()
            ),
        )
        if worker_arm_issues:
            if output_path.exists():
                quarantine_skeptic_provider_output(
                    request,
                    reason="PhaseIO provider publication was not prebound",
                )
            return None, False, issues + [
                f"{shard_id} skeptic provider PhaseIO arm invalid: {issue}"
                for issue in worker_arm_issues
            ]
        project_root = Path(config.get("project_root") or root.parent)
        if transactional_claude and worker_execute:
            startup_binding, prelaunch_capability = (
                _replay_explicit_claude_headless_launch_boundary(
                    phase=phase,
                    config=config,
                    scratchpad=root,
                    contract=worker_contract,
                    launch=worker_launch,
                )
            )
            packet_text = request.packet_path.read_text(
                encoding="utf-8", errors="strict"
            )
            from worker_transaction import (
                attempt_output_directory,
                compile_attempt_write_scope,
            )
            attempt_id = f"attempt-{uuid.uuid4().hex[:24]}"
            attempt_scope = compile_attempt_write_scope(
                run_id=run_id,
                phase=worker_contract.phase,
                work_unit_id=worker_contract.work_unit_id,
                attempt_id=attempt_id,
            )
            output_directory = attempt_output_directory(root, attempt_scope)
            boundary = _prepare_claude_phase_tool_boundary(
                phase=phase,
                scratchpad=root,
                config=config,
                attempt=1,
                prompt_snapshot=request.packet_path,
                transaction_output_directory=output_directory,
                contract=worker_contract,
                launch=worker_launch,
            )
            if not isinstance(boundary, Mapping):
                raise SkepticExecutionWorkError(
                    "skeptic restricted file-output boundary is unavailable"
                )
            source_snapshot_sha256 = (
                _security_obligation_source_snapshot_digest(config)
            )
            authority = _compile_claude_driver_provider_authority(
                phase=phase,
                config=config,
                scratchpad=root,
                project_root=project_root.resolve(strict=True),
                cwd=root.resolve(strict=True),
                launch=worker_launch,
                session_id=claude_semantic_session_id(
                    work_unit_id=worker_contract.work_unit_id,
                    work_unit_resume_digest=request.request_digest,
                    prompt_sha256=hashlib.sha256(
                        request.packet_path.read_bytes()
                    ).hexdigest(),
                ),
                startup_authority_binding=startup_binding,
                source_snapshot_sha256=source_snapshot_sha256,
            )

            def command_builder(
                routed_output_directory: Path,
            ) -> Sequence[str]:
                del routed_output_directory
                return authority.base_argv_template

            if (
                _replay_explicit_claude_headless_launch_boundary(
                    phase=phase,
                    config=config,
                    scratchpad=root,
                    contract=worker_contract,
                    launch=worker_launch,
                )
                != (startup_binding, prelaunch_capability)
            ):
                raise SkepticExecutionWorkError(
                    "skeptic Claude boundary changed before launch"
                )
            public = authority.public_arguments
            execute_headless_worker(
                scratchpad=root,
                project_root=project_root.resolve(strict=True),
                run_id=run_id,
                phase_io_contract=worker_contract,
                phase_io_launch=worker_launch,
                prompt=packet_text,
                command_builder=command_builder,
                cwd=root.resolve(strict=True),
                environment=dict(public["environment"]),
                environment_allowlist=tuple(public["environment_allowlist"]),
                source_snapshot_digest=source_snapshot_sha256,
                methodology_digests=(request.request_digest,),
                startup_authority_binding=startup_binding,
                parser_digest=application_skeptic_stdout_digest,
                provider_stdout_evidence_configuration=public.get(
                    "provider_stdout_evidence_configuration"
                ),
                claude_launch_security=public.get("claude_launch_security"),
                claude_launch_security_request=public.get(
                    "claude_launch_security_request"
                ),
                claude_provider_preparation=authority.preparation,
                claude_runtime_local_inputs=authority.runtime_local_inputs,
                claude_bound_settings_bytes=authority.bound_settings_bytes,
                claude_selected_mcp_config_bytes=(
                    authority.selected_mcp_config_bytes
                ),
                cancel_token=_current_worker_cancel_token(),
                attempt_id=attempt_id,
            )
        elif not transactional_claude:
            containment_before = _snapshot_application_skeptic_child_boundary(
                root, project_root
            )
            try:
                observed = execute_or_resume_skeptic_execution(
                    request,
                    parser_digest=application_skeptic_stdout_digest,
                    startup_authority_binding=(
                        _current_auxiliary_writable_root_startup_binding(
                            root,
                            config,
                        )
                    ),
                )
            except BaseException:
                issues.extend(
                    _reconcile_application_skeptic_provider_attempt(
                        scratchpad=root,
                        project_root=project_root,
                        config=config,
                        shard_id=shard_id,
                        before_state=containment_before,
                        phase_io_contract=worker_contract,
                        provider_layout=request.layout,
                    )
                )
                raise
            containment_issues = _reconcile_application_skeptic_provider_attempt(
                scratchpad=root,
                project_root=project_root,
                config=config,
                shard_id=shard_id,
                before_state=containment_before,
                phase_io_contract=worker_contract,
                provider_layout=request.layout,
            )
            issues.extend(containment_issues)
            if containment_issues:
                raise SkepticExecutionWorkError(
                    "application-specific provider containment failed: "
                    + "; ".join(containment_issues)
                )
            validate_skeptic_provider_authority(
                request,
                observed.authority_sidecar_path,
                parser_digest=application_skeptic_stdout_digest,
            )
        loaded = load_application_skeptic_assessments(
            output_path,
            plan,
            shard_id,
            assessor_id=assessor_id,
            assessor_invocation_id=assessor_invocation_id,
        )
        if worker_execute and not transactional_claude:
            worker_commit_issues = _commit_application_skeptic_io(
                scratchpad=root,
                config=config,
                contract=worker_contract,
                launch=worker_launch,
            )
            if worker_commit_issues:
                quarantine_skeptic_provider_output(
                    request,
                    reason="PhaseIO provider publication commit failed",
                )
                return None, True, issues + [
                    f"{shard_id} skeptic provider PhaseIO commit invalid: {issue}"
                    for issue in worker_commit_issues
                ]
        return loaded, True, issues
    except SkepticExecutionIncomplete as exc:
        if request is not None:
            quarantine_skeptic_provider_output(
                request, reason="provider incomplete before consumer import"
            )
        debt = f"; provider debt: {exc.provider_debt_path}" if exc.provider_debt_path else ""
        return None, True, issues + [
            f"{shard_id} skeptic provider incomplete: {exc}{debt}"
        ]
    except (
        ApplicationSkepticError,
        SkepticExecutionWorkError,
        OSError,
        UnicodeError,
        ValueError,
    ) as exc:
        if request is not None:
            quarantine_skeptic_provider_output(
                request, reason="provider or consumer validation failed"
            )
        return None, False, issues + [
            f"{shard_id} skeptic provider unavailable: {type(exc).__name__}: {exc}"
        ]


def _record_candidate_negative_skeptic_io(**kwargs: Any) -> list[str]:
    return _record_application_skeptic_io(**kwargs)


def _refresh_central_negative_closure_authority(
    scratchpad: Path,
    issues: list[str],
) -> Any:
    """Replay the one live negative authority without making it a halt gate."""

    try:
        return write_central_negative_closure_authority(scratchpad)
    except Exception as exc:
        issues.append(
            "central negative-closure authority publish failed; all terminal "
            f"negative proposals reopen: {type(exc).__name__}: {exc}"
        )
    try:
        # A readable prior ledger is still replayed against current provider
        # artifacts.  Stale/tampered state becomes broker debt, never authority.
        return load_central_negative_closure_authority(scratchpad)
    except Exception as exc:
        issues.append(
            "central negative-closure authority replay failed; all terminal "
            f"negative proposals reopen: {type(exc).__name__}: {exc}"
        )
        return None


def _run_candidate_negative_skeptic_boundary(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> tuple[dict[str, Any], list[str]]:
    """Run a separate candidate/entity-negative discriminator subworkflow."""

    root = Path(scratchpad)
    issues: list[str] = []
    try:
        _prepare_candidate_negative_ledger_union(root, config)
    except Exception as exc:
        issues.append(
            "candidate-negative denominator preparation failed: "
            f"{type(exc).__name__}: {exc}"
        )
    candidate_phases = _candidate_negative_phases_for_run(root, config)
    plan = build_candidate_negative_application_plan(
        root,
        phases=candidate_phases,
        max_items_per_shard=max(
            1, int(config.get("application_skeptic_shard_size") or 12)
        ),
    )
    (
        planning_contract,
        planning_launch,
        planning_execute,
        planning_issues,
    ) = _arm_application_skeptic_io(
        scratchpad=root,
        config=config,
        phase=phase,
        work_unit_id="negative.planning",
        actor="DRIVER",
        exact_inputs=tuple(
            f"candidate_negative_proposals_{source}.json"
            for source in candidate_phases
        ),
    )
    issues.extend(planning_issues)
    if planning_execute:
        write_candidate_negative_application_plan(root, plan)
        issues.extend(
            _commit_application_skeptic_io(
                scratchpad=root,
                config=config,
                contract=planning_contract,
                launch=planning_launch,
            )
        )
    elif not planning_issues:
        try:
            current_plan = json.loads(
                (root / CANDIDATE_NEGATIVE_SKEPTIC_WORK_PLAN_FILE).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            if current_plan != plan:
                issues.append(
                    "candidate-negative committed plan differs from current "
                    "exact input union"
                )
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            issues.append(
                "candidate-negative committed plan replay failed: "
                f"{type(exc).__name__}: {exc}"
            )

    receipt_path = root / "candidate_negative_skeptic_receipt.json"
    prior: dict[str, Any] | None = None
    last_good_receipt: dict[str, Any] | None = None
    try:
        candidate = json.loads(receipt_path.read_text(encoding="utf-8"))
        if (
            isinstance(candidate, dict)
            and candidate.get("work_plan_digest") == plan["work_plan_digest"]
        ):
            last_good_receipt = validate_candidate_negative_receipt_for_resume(
                plan, candidate
            )
            if candidate.get("status") == "PARTIAL":
                prior = candidate
    except (
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        CandidateNegativeAuthorityError,
        ApplicationSkepticError,
    ):
        pass

    pending = set(application_skeptic_pending_ids(plan, prior))
    assessments: list[dict[str, Any]] = []
    imported_assessment_outputs: list[str] = []
    model_was_invoked = False
    effective_model = phase_model(
        phase, str(config.get("mode") or "core"), config
    )
    timeout = max(
        60.0,
        min(
            3600.0,
            float(config.get("application_skeptic_timeout_s") or phase.base_timeout_s),
        ),
    )
    for shard in plan.get("shards", []):
        shard_ids = list(shard.get("work_item_ids") or [])
        if not pending.intersection(shard_ids):
            continue
        shard_id = str(shard["shard_id"])
        ordinal = int(shard_id.rsplit("-", 1)[-1])
        output_name = (
            f"candidate_negative_skeptic_assessments_{ordinal:04d}.json"
        )
        assessor, invocation = _candidate_negative_assessor_identity(
            config, plan["work_plan_digest"], shard_id
        )
        loaded, invoked, shard_issues = (
            _execute_application_skeptic_provider_shard(
                workflow="candidate_negative",
                phase=phase,
                config=config,
                scratchpad=root,
                plan=plan,
                plan_name=CANDIDATE_NEGATIVE_SKEPTIC_WORK_PLAN_FILE,
                shard=shard,
                output_name=output_name,
                assessor_id=assessor,
                assessor_invocation_id=invocation,
                effective_model=effective_model,
                timeout_seconds=int(timeout),
            )
        )
        model_was_invoked = model_was_invoked or invoked
        issues.extend(shard_issues)
        if loaded is not None:
            assessments.extend(
                row for row in loaded if row["work_item_id"] in pending
            )
            imported_assessment_outputs.append(output_name)

    (
        reconcile_contract,
        reconcile_launch,
        reconcile_execute,
        reconcile_arm_issues,
    ) = _arm_application_skeptic_io(
        scratchpad=root,
        config=config,
        phase=phase,
        work_unit_id="negative.reconcile",
        actor="DRIVER",
        exact_inputs=tuple(sorted(set(imported_assessment_outputs))),
    )
    issues.extend(reconcile_arm_issues)

    closure_authority = _refresh_central_negative_closure_authority(root, issues)
    receipt = adjudicate_candidate_negative(
        plan,
        assessments,
        prior_receipt=prior,
        candidate_sink=lambda _proposal: None,
        defer_missing=False,
        model_invoked=(
            model_was_invoked or bool((prior or {}).get("model_invoked"))
        ),
        closure_authority=closure_authority,
    )
    receipt = _attach_skeptic_provider_debt(receipt, issues)
    current_receipt = receipt
    preservation_input, preservation_eligible = (
        _prepare_positive_last_good_preservation(
            receipt,
            last_good_receipt,
            assessed_work_item_ids=[
                str(row.get("work_item_id") or "")
                for row in assessments
                if isinstance(row, Mapping)
            ],
        )
    )
    receipt, preserved_last_good = preserve_last_good_reopened_candidates(
        plan,
        current_receipt=(
            preservation_input if preservation_eligible else receipt
        ),
        last_good_receipt=last_good_receipt,
    )
    if preservation_eligible and not preserved_last_good:
        # Never let an invalid/tampered cache turn a current proof-scope-NONE
        # additive fallback into bare debt.
        receipt = current_receipt
    if preserved_last_good:
        issues.append(
            "candidate-negative last-good reopened candidate delivery preserved "
            "after failed current reassessment"
        )
    ledgers: list[dict[str, Any]] = []
    for source_phase in candidate_phases:
        try:
            payload = parse_candidate_negative_ledger_bytes(
                (
                    root
                    / f"candidate_negative_proposals_{source_phase}.json"
                ).read_bytes(),
                expected_phase=source_phase,
            )
            if isinstance(payload, dict):
                ledgers.append(payload)
        except (
            OSError,
            UnicodeError,
            json.JSONDecodeError,
            CandidateNegativeAuthorityError,
        ) as exc:
            issues.append(
                f"candidate-negative {source_phase} ledger unavailable during "
                f"reconciliation: {type(exc).__name__}: {exc}"
            )
    delivered_projection: Path | None = (
        root / CANDIDATE_NEGATIVE_SKEPTIC_PROJECTION
    )
    denominator = validate_candidate_negative_denominator(
        ledgers=ledgers,
        plan=plan,
        receipt=receipt,
        projection_path=(
            delivered_projection
            if delivered_projection.is_file()
            else None
        ),
    )
    if reconcile_execute:
        try:
            _atomic_driver_json(receipt_path, receipt)
            write_application_skeptic_proposal_projection(
                root,
                receipt.get("registry_candidate_proposals", []),
                projection_name=CANDIDATE_NEGATIVE_SKEPTIC_PROJECTION,
            )
            delivered_projection = (
                root / CANDIDATE_NEGATIVE_SKEPTIC_PROJECTION
            )
            denominator = validate_candidate_negative_denominator(
                ledgers=ledgers,
                plan=plan,
                receipt=receipt,
                projection_path=delivered_projection,
            )
            write_candidate_negative_denominator(root, denominator)
            issues.extend(
                _commit_application_skeptic_io(
                    scratchpad=root,
                    config=config,
                    contract=reconcile_contract,
                    launch=reconcile_launch,
                )
            )
        except Exception as exc:
            issues.append(
                "candidate-negative proposal publication failed: "
                f"{type(exc).__name__}: {exc}"
            )
    if denominator.get("status") != "COMPLETE":
        issues.extend(str(issue) for issue in denominator.get("issues", []))
    if receipt.get("status") in {"COMPLETED_WITH_DEBT", "PARTIAL"}:
        issues.extend(
            str(issue.get("code") or issue)
            for issue in receipt.get("source_input_issues", [])
        )
        issues.extend(
            f"unresolved candidate-negative disposition {work_id}"
            for work_id in receipt.get("unresolved_work_item_ids", [])
        )
    return receipt, list(dict.fromkeys(issue for issue in issues if issue))

_EXPLORATION_CLEAR_ALIAS_SCHEMA = CANONICAL_PRIOR_ALIAS_SCHEMA
_EXPLORATION_CLEAR_ATTEMPT_SCHEMA = "plamen.exploration_clear_repair_attempt.v1"
_EXPLORATION_CLEAR_ALIAS_NAME = CANONICAL_PRIOR_ALIAS_NAME
_EXPLORATION_CLEAR_ATTEMPT_NAME = "exploration_clear_repair_attempt.json"
_EXPLORATION_CLEAR_RESPONSE_NAME = "exploration_clear_repair_response.md"


def _exploration_clear_prior_alias_payload(scratchpad: Path) -> dict[str, Any]:
    """Return the shared, typed canonical-prior authority projection."""

    return derive_canonical_prior_authority(
        Path(scratchpad) / "_canonical_finding_ids.json"
    ).payload


def _load_exploration_clear_aliases(scratchpad: Path) -> dict[str, str]:
    return dict(load_canonical_prior_authority(Path(scratchpad)).aliases)


def _exploration_clear_contract_launch(
    *,
    phase: Phase,
    config: dict[str, Any],
    work_unit_id: str,
    exact_outputs: tuple[str, ...] = (),
    exact_inputs: tuple[str, ...] = (),
    actor: str,
    model: str,
    timeout_s: int,
) -> tuple[Any, LaunchSpec]:
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "thorough"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="exploration_clear",
        work_unit_id=work_unit_id,
        exact_outputs=exact_outputs,
        exact_inputs=exact_inputs,
    )
    backend = str(config.get("cli_backend") or "claude").lower()
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model=model,
        timeout_s=max(1, int(timeout_s)),
        exec_mode=(
            "python" if actor == "DRIVER" else
            ("codex" if backend == "codex" else "headless")
        ),
        tool_policy=("filesystem",),
    )
    return contract, launch


def _record_exploration_clear_io(
    *,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    work_unit_id: str,
    exact_outputs: tuple[str, ...],
    exact_inputs: tuple[str, ...],
    actor: str,
    model: str,
    timeout_s: int,
) -> list[str]:
    del (
        scratchpad, phase, config, work_unit_id, exact_outputs, exact_inputs,
        actor, model, timeout_s,
    )
    return [
        "exploration-clear legacy retro-binding is retired; use a prebound "
        "immutable DRIVER transaction"
    ]


def _exploration_clear_driver_transaction(
    *,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    work_unit_id: str,
    exact_outputs: tuple[str, ...],
    exact_inputs: tuple[str, ...],
    materialize: Callable[[Path], None],
) -> list[str]:
    """Stage, prebind, publish, and commit one rollback-safe projection."""

    root = Path(scratchpad)
    project = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    contract, launch = _exploration_clear_contract_launch(
        phase=phase,
        config=config,
        work_unit_id=work_unit_id,
        exact_outputs=exact_outputs,
        exact_inputs=exact_inputs,
        actor="DRIVER",
        model="driver",
        timeout_s=120,
    )

    output_paths: dict[str, Path] = {}
    for spec in contract.outputs:
        if spec.root != "scratchpad":
            return [
                f"{contract.key}: exploration-clear DRIVER outputs must be "
                "scratchpad-owned"
            ]
        output_paths[spec.path] = root / PurePosixPath(spec.path)

    def restore_outputs(prestates: Mapping[str, bytes | None]) -> list[str]:
        restore_issues: list[str] = []
        for relative, before in prestates.items():
            path = output_paths[relative]
            try:
                if before is None:
                    if path.exists() or path.is_symlink():
                        rooted_io.unlink(path)
                else:
                    _atomic_driver_bytes(path, before)
            except OSError as exc:
                restore_issues.append(
                    f"{contract.key}: rollback failed for {relative}: {exc}"
                )
                continue
            try:
                current = path.read_bytes() if path.is_file() else None
            except OSError as exc:
                restore_issues.append(
                    f"{contract.key}: rollback verification failed for "
                    f"{relative}: {exc}"
                )
                continue
            if current != before:
                restore_issues.append(
                    f"{contract.key}: rollback verification mismatch for {relative}"
                )
        return restore_issues

    with _ledger_transaction_lock(root):
        execute, issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if issues or not execute:
            return list(dict.fromkeys(issues))
        before_write = validate_work_unit_inputs(
            root, project, contract, launch, run_id=run_id
        )
        if before_write:
            return [
                *before_write,
                f"{contract.key}: semantic input changed after prebind",
            ]

        stage_parent = root / "_exploration_clear_transactions"
        stage = stage_parent / uuid.uuid4().hex
        rooted_io.ensure_directory(
            stage,
            parents=True,
            label="exploration-clear transaction stage",
        )
        prestates: dict[str, bytes | None] = {}
        published = False
        try:
            materialize(stage)
            staged_paths = {
                relative: stage / PurePosixPath(relative)
                for relative in output_paths
            }
            missing = [
                relative
                for relative, path in staged_paths.items()
                if not path.is_file() or path.is_symlink()
            ]
            staged_files = {
                path.relative_to(stage).as_posix()
                for path in stage.rglob("*")
                if path.is_file()
            }
            if missing or staged_files != set(staged_paths):
                return [
                    f"{contract.key}: staged output denominator mismatch; "
                    f"missing={sorted(missing)!r}; "
                    f"extra={sorted(staged_files - set(staged_paths))!r}"
                ]
            after_stage = validate_work_unit_inputs(
                root, project, contract, launch, run_id=run_id
            )
            if after_stage:
                return [
                    *after_stage,
                    f"{contract.key}: semantic input changed after prebind",
                ]
            for relative, path in output_paths.items():
                if path.exists() or path.is_symlink():
                    if not path.is_file() or path.is_symlink():
                        return [
                            f"{contract.key}: output prestate is not a regular "
                            f"file: {relative}"
                        ]
                    prestates[relative] = path.read_bytes()
                else:
                    prestates[relative] = None
            for relative, path in output_paths.items():
                _atomic_driver_bytes(path, staged_paths[relative].read_bytes())
            published = True
            after_write = validate_work_unit_inputs(
                root, project, contract, launch, run_id=run_id
            )
            if after_write:
                return [
                    *after_write,
                    f"{contract.key}: semantic input changed after prebind",
                    *restore_outputs(prestates),
                ]
            commit_issues = _commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project,
                contract=contract,
                launch=launch,
                run_id=run_id,
            )
            if commit_issues:
                return [*commit_issues, *restore_outputs(prestates)]
            published = False
            return []
        except BaseException:
            if published:
                restore_outputs(prestates)
            raise
        finally:
            if stage.exists():
                shutil.rmtree(stage)
            try:
                stage_parent.rmdir()
            except OSError:
                pass


def _exploration_clear_project_locus_inputs(
    text: str, project_root: Path,
) -> tuple[str, ...]:
    """Bind raw bytes for every existing production file cited as a locus."""

    results: set[str] = set()
    pattern = re.compile(
        r"(?<![A-Za-z0-9_:/\\])"
        r"(?P<path>(?![A-Za-z]:[\\/])"
        r"(?:[A-Za-z0-9_. -]+[\\/])*[A-Za-z0-9_. -]+)"
        r"(?::(?:L)?|#L)[1-9][0-9]*(?![A-Za-z0-9])",
        re.ASCII,
    )
    root = Path(project_root).resolve(strict=False)
    for match in pattern.finditer(text):
        relative = match.group("path").strip().replace("\\", "/")
        parsed = PurePosixPath(relative)
        if (
            not relative
            or parsed.is_absolute()
            or any(part in {"", ".", ".."} for part in parsed.parts)
        ):
            continue
        candidate = root.joinpath(*parsed.parts).resolve(strict=False)
        try:
            candidate.relative_to(root)
        except ValueError:
            continue
        if candidate.is_file():
            results.add(f"project::{parsed.as_posix()}")
    return tuple(sorted(results))


def _exploration_clear_active_unit(
    scratchpad: Path, suffix: str, *, run_id: str,
) -> bool:
    try:
        ledger = read_artifact_ledger(Path(scratchpad))
    except ArtifactLedgerError:
        return False
    for key, unit in ledger.get("work_units", {}).items():
        if (
            str(key).endswith(f"/exploration_clear/{suffix}")
            and isinstance(unit, Mapping)
            and unit.get("run_id") == run_id
            and unit.get("semantic_status") == "ACTIVE"
            and unit.get("execution_state") == "OUTPUT_COMMITTED"
        ):
            return True
    return False


def _exploration_clear_active_model_response(
    *,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    model: str,
    timeout_s: int,
) -> tuple[bool, list[str]]:
    contract, launch = _exploration_clear_contract_launch(
        phase=phase,
        config=config,
        work_unit_id="worker.0001",
        exact_outputs=(_EXPLORATION_CLEAR_RESPONSE_NAME,),
        exact_inputs=(
            "exploration_clear_repair_plan.json",
            _EXPLORATION_CLEAR_ATTEMPT_NAME,
        ),
        actor="MODEL",
        model=model,
        timeout_s=timeout_s,
    )
    root = Path(scratchpad)
    project = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    issues = validate_work_unit_inputs(
        root, project, contract, launch, run_id=run_id
    )
    issues.extend(validate_work_unit_artifacts(
        root,
        project,
        contract,
        launch,
        run_id=run_id,
        actor="MODEL",
    ))
    return not issues, list(dict.fromkeys(issues))


def _quarantine_exploration_clear_proposal(
    scratchpad: Path, name: str,
) -> Path | None:
    path = Path(scratchpad) / name
    if not path.is_file():
        return None
    quarantine = Path(scratchpad) / "_exploration_clear_quarantine"
    quarantine.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    target = quarantine / f"{name}.{digest}.proposal"
    if target.exists():
        path.unlink()
        return target
    os.replace(path, target)
    return target


def _bind_exploration_clear_worker_inputs(
    *,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    model: str,
    timeout_s: int,
) -> tuple[Any, LaunchSpec, list[str]]:
    contract, launch = _exploration_clear_contract_launch(
        phase=phase,
        config=config,
        work_unit_id="worker.0001",
        exact_outputs=(_EXPLORATION_CLEAR_RESPONSE_NAME,),
        exact_inputs=(
            "exploration_clear_repair_plan.json",
            _EXPLORATION_CLEAR_ATTEMPT_NAME,
        ),
        actor="MODEL",
        model=model,
        timeout_s=timeout_s,
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    root = Path(config.get("project_root") or Path(scratchpad).parent)
    try:
        record_work_unit_inputs(
            scratchpad, root, contract, launch, run_id=run_id
        )
        return contract, launch, validate_work_unit_inputs(
            scratchpad, root, contract, launch, run_id=run_id
        )
    except (ArtifactLedgerError, ValueError) as exc:
        return contract, launch, [f"exploration-clear worker input binding failed: {exc}"]


def _record_exploration_clear_worker_output(
    *,
    scratchpad: Path,
    config: dict[str, Any],
    contract: Any,
    launch: LaunchSpec,
) -> list[str]:
    run_id = str(config.get("_run_id") or "test-unbound")
    root = Path(config.get("project_root") or Path(scratchpad).parent)
    try:
        input_issues = validate_work_unit_inputs(
            scratchpad, root, contract, launch, run_id=run_id
        )
        record_work_unit_artifacts(
            scratchpad,
            root,
            contract,
            launch,
            run_id=run_id,
            actor="MODEL",
        )
        return input_issues + validate_work_unit_artifacts(
            scratchpad,
            root,
            contract,
            launch,
            run_id=run_id,
            actor="MODEL",
        )
    except ArtifactLedgerError as exc:
        return [f"exploration-clear worker output binding failed: {exc}"]


def _exploration_clear_repair_prompt(
    *,
    plan: Any,
    scratchpad: Path,
    project_root: Path,
) -> str:
    items = "\n".join(
        f"- {item.obligation_id}: finding={item.source_finding}; "
        f"axis={item.axis}; instance={item.instance}; "
        f"original={item.original_disposition}; evidence={item.original_evidence}"
        for item in plan.items
    )
    return f"""You are an independent exploration-completeness repair worker.

Analyze only the exact obligations in the driver-owned plan below. Inspect the
authorized production source when needed. You may CLEAR an obligation only
with an exact existing production `relative/file.ext:L<number>` locus or an
exact canonical prior identity recorded in
`{(scratchpad / _EXPLORATION_CLEAR_ALIAS_NAME).as_posix()}`. If analysis reveals
a candidate, use ADD with one new stable action ID; this is unverified generator
output that must enter the normal independent verification path. Otherwise use
UNRESOLVED. You may not delete, merge, downgrade, or certify any finding.

Project root: {project_root.as_posix()}
Source exploration artifact: {(scratchpad / 'exploration_skeptic_findings.md').as_posix()}
Plan file: {(scratchpad / 'exploration_clear_repair_plan.json').as_posix()}
Output file: {(scratchpad / _EXPLORATION_CLEAR_RESPONSE_NAME).as_posix()}

Exact obligations:
{items}

Write exactly this Markdown structure, with one row for every obligation and no
additional table rows:

# Exploration Clear Repair

**Plan ID**: {plan.plan_id}
**Plan Hash**: {plan.plan_hash}

## Repair Dispositions

| Obligation ID | Disposition | Evidence | Action ID | Rationale |
|---|---|---|---|---|
| ECLR-... | CLEAR / ADD / UNRESOLVED | exact evidence | action ID only for ADD | concise rationale |

SCOPE: Write ONLY to your assigned output file. Do NOT read or write other agents' output files. Do NOT proceed to subsequent pipeline phases. Return your findings and stop.
"""


def _attempt_matches_plan(payload: Any, plan: Any) -> bool:
    return bool(
        isinstance(payload, dict)
        and payload.get("schema_version") == _EXPLORATION_CLEAR_ATTEMPT_SCHEMA
        and payload.get("plan_id") == plan.plan_id
        and payload.get("plan_hash") == plan.plan_hash
        and payload.get("source_receipt_hash") == plan.source_receipt_hash
    )


def _load_exploration_clear_attempt(path: Path) -> dict[str, Any] | None:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return None
    return payload if isinstance(payload, dict) else None


def _exploration_clear_response_binds_plan(path: Path, plan: Any) -> bool:
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return False
    plan_id = re.findall(
        r"(?im)^\s*\*\*Plan ID\*\*\s*:\s*(\S+)\s*$", text
    )
    plan_hash = re.findall(
        r"(?im)^\s*\*\*Plan Hash\*\*\s*:\s*([0-9a-f]+)\s*$", text
    )
    return plan_id == [plan.plan_id] and [value.lower() for value in plan_hash] == [plan.plan_hash]


def _read_exploration_clear_response(path: Path) -> str:
    """Read without universal-newline rewriting so the receipt hashes bytes."""
    with path.open("r", encoding="utf-8", newline="") as handle:
        return handle.read()


def _exploration_clear_resume_issues(
    scratchpad: Path,
    project_root: Path,
    *,
    mode: str,
) -> list[str]:
    """Side-effect-free structural validation for resume/commit decisions."""
    if str(mode).lower() != "thorough":
        return []
    root = Path(scratchpad)
    issues: list[str] = []
    try:
        receipt = load_lifecycle_receipt(root / "exploration_clear_receipt.json")
    except ExplorationClearError as exc:
        return [f"exploration-clear receipt invalid: {exc}"]
    try:
        aliases = _load_exploration_clear_aliases(root)
    except ExplorationClearError as exc:
        issues.append(str(exc))
        aliases = {}
    try:
        queue = json.loads(
            (root / "exploration_clear_obligations.json").read_text(encoding="utf-8")
        )
        if queue != exploration_clear_obligation_queue(receipt):
            issues.append("exploration-clear obligation queue does not match receipt")
    except (OSError, UnicodeError, json.JSONDecodeError):
        issues.append("exploration-clear obligation queue is missing or malformed")
    if receipt.obligations and receipt.repair_attempts == 0:
        issues.append("exploration-clear obligations were committed before the one-shot repair")
    plan_path = root / "exploration_clear_repair_plan.json"
    if receipt.repair_attempts:
        try:
            plan = load_repair_plan(plan_path)
            if plan.source_artifact_sha256 != receipt.artifact_sha256:
                issues.append("exploration-clear repair plan source digest mismatch")
            attempt = _load_exploration_clear_attempt(
                root / _EXPLORATION_CLEAR_ATTEMPT_NAME
            )
            if not _attempt_matches_plan(attempt, plan):
                issues.append("exploration-clear repair attempt is absent or misbound")
        except ExplorationClearError as exc:
            issues.append(f"exploration-clear repair plan invalid: {exc}")
    if receipt.repair_response_sha256:
        response = root / _EXPLORATION_CLEAR_RESPONSE_NAME
        try:
            digest = hashlib.sha256(response.read_bytes()).hexdigest()
        except OSError:
            digest = ""
        if digest != receipt.repair_response_sha256:
            issues.append("exploration-clear repair response digest mismatch")
    try:
        initial = compile_initial_receipt(
            root / "exploration_skeptic_findings.md",
            production_root=project_root,
            canonical_prior_ids=aliases,
        )
        expected = initial
        expected_plan = build_repair_plan(initial)
        if receipt.repair_attempts:
            if expected_plan is None:
                raise ExplorationClearError(
                    "terminal receipt has no mechanically derived repair plan"
                )
            stored_plan = load_repair_plan(
                root / "exploration_clear_repair_plan.json"
            )
            if stored_plan != expected_plan:
                raise ExplorationClearError(
                    "stored repair plan differs from semantic re-derivation"
                )
            if receipt.repair_response_sha256:
                ledger = read_artifact_ledger(root)
                binding = ledger.get("artifact_bindings", {}).get(
                    f"scratchpad:{_EXPLORATION_CLEAR_RESPONSE_NAME}"
                )
                unit = (
                    ledger.get("work_units", {}).get(binding.get("owner_key"))
                    if isinstance(binding, Mapping)
                    else None
                )
                if (
                    not isinstance(binding, Mapping)
                    or not isinstance(unit, Mapping)
                    or binding.get("status") != "ACTIVE"
                    or unit.get("semantic_status") != "ACTIVE"
                    or unit.get("execution_state") != "OUTPUT_COMMITTED"
                    or not str(binding.get("owner_key") or "").endswith(
                        "/exploration_clear/worker.0001"
                    )
                ):
                    raise ExplorationClearError(
                        "repair response lacks an active MODEL producer"
                    )
                expected = reconcile_repair_attempt(
                    initial,
                    expected_plan,
                    _read_exploration_clear_response(
                        root / _EXPLORATION_CLEAR_RESPONSE_NAME
                    ),
                    production_root=project_root,
                    canonical_prior_ids=aliases,
                )
            else:
                failure = json.loads(
                    (
                        root / "exploration_clear_repair_failure.json"
                    ).read_text(encoding="utf-8")
                )
                expected = record_repair_unavailable(
                    initial,
                    expected_plan,
                    reason=str(failure.get("reason") or "UNKNOWN"),
                )
        if expected != receipt:
            issues.append(
                "exploration-clear semantic re-derivation mismatch"
            )
    except (
        ArtifactLedgerError,
        ExplorationClearError,
        OSError,
        UnicodeError,
        json.JSONDecodeError,
    ) as exc:
        issues.append(
            f"exploration-clear semantic re-derivation failed: {exc}"
        )
    if (root / "exploration_skeptic.instance_gap").exists():
        issues.append("legacy exploration instance-gap sentinel survived typed migration")
    return list(dict.fromkeys(issues))


def _run_exploration_clear_lifecycle(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> list[str]:
    """Compile and repair through distinct arm-before-write transactions."""

    if str(config.get("mode") or "core").lower() != "thorough":
        return []
    root = Path(scratchpad)
    project = Path(config.get("project_root") or root.parent)
    source = root / "exploration_skeptic_findings.md"
    run_id = str(config.get("_run_id") or "test-unbound")
    issues: list[str] = []

    # A terminal same-run projection is immutable.  Resume validates it by
    # re-derivation below; it never rewrites or blesses current bytes.
    if _exploration_clear_active_unit(
        root, "repair_reconcile", run_id=run_id
    ) or _exploration_clear_active_unit(
        root, "initial_compile.clean", run_id=run_id
    ):
        try:
            receipt = load_lifecycle_receipt(
                root / "exploration_clear_receipt.json"
            )
        except ExplorationClearError as exc:
            return [f"exploration-clear receipt invalid: {exc}"]
        issues.extend(_exploration_clear_resume_issues(
            root, project, mode="thorough"
        ))
        issues.extend(str(item) for item in receipt.debt)
        issues.extend(
            f"unresolved exploration-clear obligation {item.obligation_id}: "
            f"{item.reason}"
            for item in receipt.obligations
        )
        return list(dict.fromkeys(issue for issue in issues if issue))

    alias_inputs = (
        ("_canonical_finding_ids.json",)
        if (root / "_canonical_finding_ids.json").is_file()
        else ()
    )
    if not _exploration_clear_active_unit(
        root, "alias_authority", run_id=run_id
    ):
        _quarantine_exploration_clear_proposal(
            root, _EXPLORATION_CLEAR_ALIAS_NAME
        )
    issues.extend(_exploration_clear_driver_transaction(
        scratchpad=root,
        phase=phase,
        config=config,
        work_unit_id="alias_authority",
        exact_outputs=(_EXPLORATION_CLEAR_ALIAS_NAME,),
        exact_inputs=alias_inputs,
        materialize=lambda stage: _atomic_driver_json(
            stage / _EXPLORATION_CLEAR_ALIAS_NAME,
            _exploration_clear_prior_alias_payload(root),
        ),
    ))
    if issues:
        return list(dict.fromkeys(issues))
    try:
        aliases = _load_exploration_clear_aliases(root)
        source_text = _read_exploration_clear_response(source)
        provisional = compile_initial_receipt(
            source,
            production_root=project,
            canonical_prior_ids=aliases,
        )
    except (ExplorationClearError, OSError, UnicodeError) as exc:
        return [f"exploration-clear initial derivation failed: {exc}"]
    provisional_plan = build_repair_plan(provisional)
    initial_kind = "repair" if provisional_plan is not None else "clean"
    initial_outputs = (
        "exploration_clear_receipt.json",
        "exploration_clear_obligations.json",
    )
    initial_inputs = (
        "exploration_skeptic_findings.md",
        _EXPLORATION_CLEAR_ALIAS_NAME,
        *_exploration_clear_project_locus_inputs(source_text, project),
    )
    if not _exploration_clear_active_unit(
        root, f"initial_compile.{initial_kind}", run_id=run_id
    ):
        for name in initial_outputs:
            _quarantine_exploration_clear_proposal(root, name)

    derived: dict[str, Any] = {}

    def materialize_initial(stage: Path) -> None:
        current_aliases = _load_exploration_clear_aliases(root)
        current_receipt = compile_initial_receipt(
            source,
            production_root=project,
            canonical_prior_ids=current_aliases,
        )
        current_plan = build_repair_plan(current_receipt)
        if bool(current_plan) != bool(provisional_plan):
            raise ExplorationClearError(
                "initial lifecycle shape changed after prebind"
            )
        derived["receipt"] = current_receipt
        derived["plan"] = current_plan
        write_lifecycle_artifacts(stage, current_receipt)

    try:
        issues.extend(_exploration_clear_driver_transaction(
            scratchpad=root,
            phase=phase,
            config=config,
            work_unit_id=f"initial_compile.{initial_kind}",
            exact_outputs=tuple(initial_outputs),
            exact_inputs=tuple(initial_inputs),
            materialize=materialize_initial,
        ))
    except ExplorationClearError as exc:
        issues.append(str(exc))
    if issues:
        return list(dict.fromkeys(issues))
    receipt = derived.get("receipt") or load_lifecycle_receipt(
        root / "exploration_clear_receipt.json"
    )
    if provisional_plan is None:
        issues.extend(_exploration_clear_resume_issues(
            root, project, mode="thorough"
        ))
        return list(dict.fromkeys(issue for issue in issues if issue))

    plan_path = root / "exploration_clear_repair_plan.json"
    if not _exploration_clear_active_unit(
        root, "repair_plan", run_id=run_id
    ):
        _quarantine_exploration_clear_proposal(root, plan_path.name)
    plan_derived: dict[str, Any] = {}

    def materialize_plan(stage: Path) -> None:
        current_receipt = compile_initial_receipt(
            source,
            production_root=project,
            canonical_prior_ids=_load_exploration_clear_aliases(root),
        )
        current_plan = build_repair_plan(current_receipt)
        if current_plan is None or current_plan != provisional_plan:
            raise ExplorationClearError(
                "repair plan changed after dedicated producer prebind"
            )
        _atomic_driver_json(
            stage / plan_path.name,
            asdict(current_plan),
        )
        if load_repair_plan(stage / plan_path.name) != current_plan:
            raise ExplorationClearError(
                "staged repair plan failed exact semantic replay"
            )
        plan_derived["plan"] = current_plan

    try:
        issues.extend(_exploration_clear_driver_transaction(
            scratchpad=root,
            phase=phase,
            config=config,
            work_unit_id="repair_plan",
            exact_outputs=(plan_path.name,),
            exact_inputs=tuple(initial_inputs),
            materialize=materialize_plan,
        ))
    except ExplorationClearError as exc:
        issues.append(str(exc))
    if issues:
        return list(dict.fromkeys(issues))
    plan = plan_derived.get("plan") or load_repair_plan(plan_path)

    model = phase_model(
        phase, str(config.get("mode") or "thorough"), config
    )
    timeout = int(max(
        60.0,
        min(
            3600.0,
            float(
                config.get("exploration_clear_timeout_s")
                or phase.base_timeout_s
            ),
        ),
    ))
    attempt_path = root / _EXPLORATION_CLEAR_ATTEMPT_NAME
    if not _exploration_clear_active_unit(
        root, "repair_arm", run_id=run_id
    ):
        _quarantine_exploration_clear_proposal(
            root, _EXPLORATION_CLEAR_ATTEMPT_NAME
        )
    invocation_id = "ECRA-" + hashlib.sha256(
        "\0".join((
            run_id,
            plan.plan_hash,
            str(config.get("cli_backend") or "claude"),
        )).encode("utf-8")
    ).hexdigest()[:24].upper()
    attempt = {
        "schema_version": _EXPLORATION_CLEAR_ATTEMPT_SCHEMA,
        "plan_id": plan.plan_id,
        "plan_hash": plan.plan_hash,
        "source_receipt_hash": plan.source_receipt_hash,
        "invocation_id": invocation_id,
        "status": "ARMED",
        "backend": str(config.get("cli_backend") or "claude").lower(),
        "model": model,
        "return_code": None,
    }
    issues.extend(_exploration_clear_driver_transaction(
        scratchpad=root,
        phase=phase,
        config=config,
        work_unit_id="repair_arm",
        exact_outputs=(_EXPLORATION_CLEAR_ATTEMPT_NAME,),
        exact_inputs=("exploration_clear_repair_plan.json",),
        materialize=lambda stage: _atomic_driver_json(
            stage / attempt_path.name, attempt
        ),
    ))
    if issues:
        return list(dict.fromkeys(issues))

    response_path = root / _EXPLORATION_CLEAR_RESPONSE_NAME
    model_committed, _model_validation = (
        _exploration_clear_active_model_response(
            scratchpad=root,
            phase=phase,
            config=config,
            model=model,
            timeout_s=timeout,
        )
    )
    rc: int | None = None
    worker_issues: list[str] = []
    if not model_committed:
        if response_path.is_file():
            _quarantine_exploration_clear_proposal(
                root, _EXPLORATION_CLEAR_RESPONSE_NAME
            )
        worker_contract, worker_launch, input_issues = (
            _bind_exploration_clear_worker_inputs(
                scratchpad=root,
                phase=phase,
                config=config,
                model=model,
                timeout_s=timeout,
            )
        )
        worker_issues.extend(input_issues)
        if not worker_issues:
            prompt = _exploration_clear_repair_prompt(
                plan=plan, scratchpad=root, project_root=project
            )
            try:
                if str(
                    config.get("cli_backend") or "claude"
                ).lower() == "codex":
                    rc = _run_one_codex_exec(
                        prompt=prompt,
                        phase=phase,
                        config=config,
                        scratchpad=root,
                        attempt=1,
                        label="exploration_clear_repair",
                        expected_outputs=[_EXPLORATION_CLEAR_RESPONSE_NAME],
                        timeout=float(timeout),
                        effective_model=model,
                        phase_io_contract=worker_contract,
                        phase_io_launch=worker_launch,
                    )
                else:
                    rc = _run_one_claude_headless_breadth_worker(
                        prompt=prompt,
                        job={
                            "agent_id": "EXPLORATION_CLEAR_REPAIR",
                            "output": _EXPLORATION_CLEAR_RESPONSE_NAME,
                        },
                        phase=phase,
                        config=config,
                        scratchpad=root,
                        attempt=1,
                        timeout=float(timeout),
                        effective_model=model,
                        label_prefix="exploration_clear",
                        phase_io_contract=worker_contract,
                        phase_io_launch=worker_launch,
                    )
            except Exception as exc:
                rc = EXIT_ERROR
                worker_issues.append(
                    "exploration-clear repair launch failed: "
                    f"{type(exc).__name__}: {exc}"
                )
            if (
                rc == 0
                and response_path.is_file()
                and _exploration_clear_response_binds_plan(response_path, plan)
            ):
                worker_issues.extend(
                    _record_exploration_clear_worker_output(
                        scratchpad=root,
                        config=config,
                        contract=worker_contract,
                        launch=worker_launch,
                    )
                )
                model_committed, model_commit_issues = (
                    _exploration_clear_active_model_response(
                        scratchpad=root,
                        phase=phase,
                        config=config,
                        model=model,
                        timeout_s=timeout,
                    )
                )
                worker_issues.extend(model_commit_issues)
            elif not worker_issues:
                worker_issues.append(
                    f"exploration-clear response unavailable after worker rc={rc}"
                )

    failure_path = root / "exploration_clear_repair_failure.json"
    if not model_committed:
        reason = (
            f"WORKER_RC_{rc}"
            if rc not in {None, 0}
            else "MODEL_PHASEIO_DEBT"
            if worker_issues
            else "RESPONSE_MISSING_OR_PLAN_MISMATCH"
        )
        failure_payload = {
            "schema_version": "plamen.exploration_clear_repair_failure.v1",
            "plan_id": plan.plan_id,
            "plan_hash": plan.plan_hash,
            "attempt_invocation_id": invocation_id,
            "reason": reason,
            "issues": list(dict.fromkeys(worker_issues)),
        }
        if not _exploration_clear_active_unit(
            root, "repair_terminal", run_id=run_id
        ):
            _quarantine_exploration_clear_proposal(
                root, failure_path.name
            )
        issues.extend(_exploration_clear_driver_transaction(
            scratchpad=root,
            phase=phase,
            config=config,
            work_unit_id="repair_terminal",
            exact_outputs=(failure_path.name,),
            exact_inputs=(
                "exploration_clear_repair_plan.json",
                _EXPLORATION_CLEAR_ATTEMPT_NAME,
            ),
            materialize=lambda stage: _atomic_driver_json(
                stage / failure_path.name, failure_payload
            ),
        ))
    issues.extend(worker_issues)

    reconcile_inputs = [
        "exploration_skeptic_findings.md",
        _EXPLORATION_CLEAR_ALIAS_NAME,
        "exploration_clear_repair_plan.json",
        _EXPLORATION_CLEAR_ATTEMPT_NAME,
    ]
    response_text = ""
    if model_committed:
        response_text = _read_exploration_clear_response(response_path)
        reconcile_inputs.append(_EXPLORATION_CLEAR_RESPONSE_NAME)
        reconcile_inputs.extend(
            _exploration_clear_project_locus_inputs(
                response_text, project
            )
        )
    else:
        reconcile_inputs.append(failure_path.name)
    final: dict[str, Any] = {}

    def materialize_final(stage: Path) -> None:
        base = compile_initial_receipt(
            source,
            production_root=project,
            canonical_prior_ids=_load_exploration_clear_aliases(root),
        )
        exact_plan = build_repair_plan(base)
        if exact_plan is None or exact_plan.plan_hash != plan.plan_hash:
            raise ExplorationClearError(
                "repair plan changed after reconcile prebind"
            )
        if model_committed:
            result = reconcile_repair_attempt(
                base,
                exact_plan,
                _read_exploration_clear_response(response_path),
                production_root=project,
                canonical_prior_ids=_load_exploration_clear_aliases(root),
            )
        else:
            failure = json.loads(failure_path.read_text(encoding="utf-8"))
            result = record_repair_unavailable(
                base, exact_plan, reason=str(failure.get("reason") or "UNKNOWN")
            )
        final["receipt"] = result
        write_lifecycle_artifacts(stage, result)

    try:
        issues.extend(_exploration_clear_driver_transaction(
            scratchpad=root,
            phase=phase,
            config=config,
            work_unit_id="repair_reconcile",
            exact_outputs=(
                "exploration_clear_receipt.json",
                "exploration_clear_obligations.json",
            ),
            exact_inputs=tuple(reconcile_inputs),
            materialize=materialize_final,
        ))
    except (ExplorationClearError, OSError, UnicodeError, json.JSONDecodeError) as exc:
        issues.append(f"exploration-clear reconciliation failed: {exc}")
    receipt = final.get("receipt")
    if receipt is None:
        try:
            receipt = load_lifecycle_receipt(
                root / "exploration_clear_receipt.json"
            )
        except ExplorationClearError as exc:
            issues.append(f"exploration-clear final receipt invalid: {exc}")
            return list(dict.fromkeys(issue for issue in issues if issue))
    issues.extend(str(item) for item in receipt.debt)
    issues.extend(
        f"unresolved exploration-clear obligation {item.obligation_id}: "
        f"{item.reason}"
        for item in receipt.obligations
    )
    issues.extend(_exploration_clear_resume_issues(
        root, project, mode="thorough"
    ))
    return list(dict.fromkeys(issue for issue in issues if issue))


def _enumgap_disposition_contract_and_launch(
    *,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    work_unit_id: str,
    exact_inputs: tuple[str, ...],
) -> tuple[PhaseIOContract, LaunchSpec]:
    del phase
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="enumgap_disposition",
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _record_enumgap_disposition_io(
    *,
    scratchpad: Path,
    phase: Phase,
    config: dict[str, Any],
    work_unit_id: str,
    exact_inputs: tuple[str, ...],
    domain_issues: Sequence[str] = (),
) -> list[str]:
    """Commit an enumgap projection that was armed before materialization."""
    contract, launch = _enumgap_disposition_contract_and_launch(
        scratchpad=scratchpad,
        phase=phase,
        config=config,
        work_unit_id=work_unit_id,
        exact_inputs=exact_inputs,
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    project = Path(config.get("project_root") or Path(scratchpad).parent)
    return _commit_deterministic_driver_work_unit(
        scratchpad=Path(scratchpad),
        project_root=project,
        contract=contract,
        launch=launch,
        run_id=run_id,
        domain_issues=domain_issues,
    )


def _prepare_enumgap_disposition_worklist(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> tuple[dict[str, Any], list[str]]:
    root = Path(scratchpad)
    input_names = tuple(
        name
        for name in (
            "_enumeration_obligations.json",
            "exploration_clear_receipt.json",
            "exploration_clear_obligations.json",
        )
        if (root / name).is_file()
    )
    contract, launch = _enumgap_disposition_contract_and_launch(
        scratchpad=root,
        phase=phase,
        config=config,
        work_unit_id="planning",
        exact_inputs=input_names,
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    project = Path(config.get("project_root") or root.parent)
    execute, issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=project,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    if execute:
        worklist = compile_enumgap_worklist(root)
        cas_issues = validate_work_unit_inputs(
            root, project, contract, launch, run_id=run_id
        )
        if cas_issues:
            issues.extend(cas_issues)
            issues.append(
                f"{contract.key}: semantic input changed after prebind"
            )
        else:
            write_enumgap_worklist(root, worklist)
            post_write_issues = validate_work_unit_inputs(
                root, project, contract, launch, run_id=run_id
            )
            if post_write_issues:
                issues.extend(post_write_issues)
                issues.append(
                    f"{contract.key}: semantic input changed after prebind"
                )
            else:
                issues.extend(_commit_deterministic_driver_work_unit(
                    scratchpad=root,
                    project_root=project,
                    contract=contract,
                    launch=launch,
                    run_id=run_id,
                ))
    else:
        try:
            worklist = load_enumgap_worklist(
                root / "enumgap_worklist.json"
            )
        except EnumgapDispositionError:
            worklist = compile_enumgap_worklist(root)
    issues.extend(str(issue) for issue in worklist.get("input_debt", []))
    return worklist, list(dict.fromkeys(issue for issue in issues if issue))


def _enumgap_output_producer_issues(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    worklist: Mapping[str, Any],
) -> list[str]:
    """Require the exact active MODEL or explicit empty DRIVER producer."""

    root = Path(scratchpad)
    project = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    try:
        if not bool(worklist.get("requires_execution")):
            contract = resolve_phase_io_contract(
                pipeline=str(config.get("pipeline") or "sc"),
                mode=str(config.get("mode") or "core"),
                ecosystem=str(config.get("language") or "unknown"),
                backend=str(config.get("cli_backend") or "claude"),
                phase="enumgap_exploration",
                work_unit_id="empty_stub",
                exact_inputs=("enumgap_worklist.json",),
            )
            launch = LaunchSpec(
                work_unit_key=contract.key,
                pipeline=contract.pipeline,
                mode=contract.mode,
                ecosystem=contract.ecosystem,
                backend=contract.backend,
                model="driver",
                timeout_s=120,
                exec_mode="python",
                tool_policy=("filesystem",),
            )
            actor = "DRIVER"
        else:
            contract, launch = _typed_model_phase_contract_and_launch(
                phase, root, config
            )
            if contract is None or launch is None:
                return ["enumgap output has no exact MODEL producer contract"]
            actor = "MODEL"
        issues = validate_work_unit_inputs(
            root, project, contract, launch, run_id=run_id
        )
        issues.extend(validate_work_unit_artifacts(
            root,
            project,
            contract,
            launch,
            run_id=run_id,
            actor=actor,
        ))
        if issues:
            return [
                "enumgap output lacks an exact ACTIVE/OUTPUT_COMMITTED "
                f"{actor} producer: {issue}"
                for issue in dict.fromkeys(issues)
            ]
        return []
    except (ArtifactLedgerError, OSError, ValueError) as exc:
        return [f"enumgap MODEL producer authority failed: {exc}"]


def _run_enumgap_empty_stub_transaction(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> tuple[dict[str, Any], list[str]]:
    """Materialize the explicit zero-work output as its own DRIVER unit."""

    root = Path(scratchpad)
    project = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="enumgap_exploration",
        work_unit_id="empty_stub",
        exact_inputs=("enumgap_worklist.json",),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    output = root / "enumgap_exploration_findings.md"
    execute, issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=project,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    if execute:
        output.write_text(
            "# Enumeration-Obligation Exploration\n\n"
            "_No enumeration obligations were produced by the exact "
            "driver-owned worklist._\n\n"
            "## Coverage Record\n\n"
            "| Obligation | Relationship | Disposition | Evidence |\n"
            "|------------|--------------|-------------|----------|\n"
            "| (none) | (none) | CLEAR | no obligations produced |\n",
            encoding="utf-8",
            newline="\n",
        )
        issues.extend(_commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
        ))
    return {
        "schema_version": "plamen.enumgap_empty_stub_receipt.v1",
        "status": "EMPTY",
        "output_sha256": (
            hashlib.sha256(output.read_bytes()).hexdigest()
            if output.is_file() else ""
        ),
    }, list(dict.fromkeys(issues))


def _reconcile_enumgap_dispositions(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> tuple[dict[str, Any], list[str]]:
    root = Path(scratchpad)
    output_path = root / "enumgap_exploration_findings.md"
    worklist = load_enumgap_worklist(root / "enumgap_worklist.json")
    producer_issues = _enumgap_output_producer_issues(
        phase, config, root, worklist
    )
    try:
        with output_path.open("r", encoding="utf-8", newline="") as handle:
            output = handle.read()
    except (OSError, UnicodeError) as exc:
        raise EnumgapDispositionError(
            f"cannot read enumgap exploration output: {exc}"
        ) from exc
    alias_issue = ""
    if (root / _EXPLORATION_CLEAR_ALIAS_NAME).is_file():
        try:
            aliases = _load_exploration_clear_aliases(root)
        except ExplorationClearError as exc:
            aliases = {}
            alias_issue = f"CANONICAL_PRIOR_AUTHORITY_INVALID: {exc}"
    else:
        aliases = {}
    reconcile_inputs = [
        "enumgap_worklist.json",
        "enumgap_exploration_findings.md",
    ]
    if (root / _EXPLORATION_CLEAR_ALIAS_NAME).is_file():
        reconcile_inputs.append(_EXPLORATION_CLEAR_ALIAS_NAME)
    reconcile_inputs.extend(
        _exploration_clear_project_locus_inputs(
            output, Path(config.get("project_root") or root.parent)
        )
    )
    contract, launch = _enumgap_disposition_contract_and_launch(
        scratchpad=root,
        phase=phase,
        config=config,
        work_unit_id="reconcile",
        exact_inputs=tuple(reconcile_inputs),
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    project = Path(config.get("project_root") or root.parent)
    execute, issues = _arm_deterministic_driver_work_unit(
        scratchpad=root,
        project_root=project,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    if producer_issues:
        receipt = reconcile_enumgap_output(
            worklist,
            "",
            production_root=Path(
                config.get("project_root") or root.parent
            ),
            canonical_prior_ids=aliases,
        )
        receipt["debt"] = list(dict.fromkeys([
            *receipt.get("debt", []),
            *producer_issues,
        ]))
        receipt["status"] = "COMPLETED_WITH_DEBT"
        issues.extend(producer_issues)
        execute = False
    else:
        receipt = reconcile_enumgap_output(
            worklist,
            output,
            production_root=Path(
                config.get("project_root") or root.parent
            ),
            canonical_prior_ids=aliases,
        )
    if execute:
        cas_issues = validate_work_unit_inputs(
            root, project, contract, launch, run_id=run_id
        )
        if cas_issues:
            issues.extend(cas_issues)
            issues.append(
                f"{contract.key}: semantic input changed after prebind"
            )
        else:
            write_enumgap_disposition_artifacts(root, receipt)
            post_write_issues = validate_work_unit_inputs(
                root, project, contract, launch, run_id=run_id
            )
            if post_write_issues:
                issues.extend(post_write_issues)
                issues.append(
                    f"{contract.key}: semantic input changed after prebind"
                )
            else:
                issues.extend(_commit_deterministic_driver_work_unit(
                    scratchpad=root,
                    project_root=project,
                    contract=contract,
                    launch=launch,
                    run_id=run_id,
                ))
    if alias_issue:
        issues.append(alias_issue)
    try:
        loaded = (
            load_enumgap_disposition_receipt(
                root / "enumgap_disposition_receipt.json",
                output_artifact=output_path,
            )
            if not producer_issues
            else receipt
        )
        residual = residual_enumgap_queue(loaded)
        if residual.get("count") != len(loaded["unresolved_work_item_ids"]):
            issues.append("enumgap residual queue count mismatch")
    except EnumgapDispositionError as exc:
        issues.append(f"enumgap disposition receipt invalid after write: {exc}")
    issues.extend(str(issue) for issue in receipt.get("debt", []))
    issues.extend(
        f"unresolved enumgap work item {identity}"
        for identity in receipt.get("unresolved_work_item_ids", [])
    )
    return receipt, list(dict.fromkeys(issue for issue in issues if issue))


def _enumgap_disposition_resume_issues(
    scratchpad: Path,
    project_root: Path,
    *,
    mode: str,
) -> list[str]:
    del mode
    root = Path(scratchpad)
    authority_issues: list[str] = []
    try:
        if (root / _EXPLORATION_CLEAR_ALIAS_NAME).is_file():
            try:
                aliases = _load_exploration_clear_aliases(root)
            except ExplorationClearError as exc:
                aliases = {}
                authority_issues.append(
                    f"CANONICAL_PRIOR_AUTHORITY_INVALID: {exc}"
                )
        else:
            aliases = {}
        validate_enumgap_disposition_authority(
            root,
            production_root=project_root,
            canonical_prior_ids=aliases,
        )
        return authority_issues
    except (
        EnumgapDispositionError,
        OSError,
        UnicodeError,
        json.JSONDecodeError,
    ) as exc:
        return authority_issues + [
            f"enumgap disposition lifecycle invalid: {exc}"
        ]


def _promote_enumgap_exploration_transaction(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> dict[str, Any]:
    """Run the live enumgap inventory append under exact PhaseIO ownership."""

    del phase
    root = Path(scratchpad)
    project = Path(config.get("project_root") or root.parent)
    run_id = str(config.get("_run_id") or "test-unbound")
    inputs = (
        "enumgap_exploration_findings.md",
        "enumgap_disposition_receipt.json",
        "enumgap_residual_obligations.json",
    )
    try:
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="enumgap_delivery",
            work_unit_id="inventory_append",
            exact_inputs=inputs,
        )
        launch = LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver",
            timeout_s=120,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        execute, prebind_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        if prebind_issues:
            return {
                "parsed": 0,
                "emitted": 0,
                "debt": prebind_issues,
            }
        if not execute:
            import enumeration_gate as _eg

            try:
                parsed = len(_eg.parse_enumgap_exploration_findings(
                    (
                        root / "enumgap_exploration_findings.md"
                    ).read_bytes().decode("utf-8", errors="strict")
                ))
            except (OSError, UnicodeError):
                parsed = 0
            return {"parsed": parsed, "emitted": 0}

        import enumeration_gate as _eg

        inventory = root / "findings_inventory.md"
        before_raw = inventory.read_bytes()
        before_text = before_raw.decode("utf-8", errors="strict")
        before_ids = tuple(sorted(
            str(row["id"])
            for row in _eg._inventory_finding_block_records(before_text)
        ))
        outcome = _eg.promote_enumgap_exploration_to_inventory(root)
        domain_issues = [
            str(issue) for issue in outcome.get("debt") or ()
        ]
        if domain_issues:
            return outcome
        after_raw = inventory.read_bytes()
        after_text = after_raw.decode("utf-8", errors="strict")
        after_ids = tuple(sorted(
            str(row["id"])
            for row in _eg._inventory_finding_block_records(after_text)
        ))
        event = DriverMergeEvent(
            work_unit_key=contract.key,
            contract_digest=contract.digest,
            artifact_identity="scratchpad:findings_inventory.md",
            before_sha256=hashlib.sha256(before_raw).hexdigest(),
            after_sha256=hashlib.sha256(after_raw).hexdigest(),
            source_identities=tuple(
                f"scratchpad:{name}" for name in inputs
            ),
            identities_before=before_ids,
            identities_after=after_ids,
        )
        commit_issues = _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run_id,
            merge_events={event.artifact_identity: event},
        )
        if commit_issues:
            outcome["debt"] = list(dict.fromkeys(commit_issues))
        return outcome
    except (
        ArtifactLedgerError,
        OSError,
        TypeError,
        UnicodeError,
        ValueError,
    ) as exc:
        return {
            "parsed": 0,
            "emitted": 0,
            "debt": [
                "enumgap inventory delivery PhaseIO failed: "
                f"{type(exc).__name__}: {exc}"
            ],
        }


def _severity_adjudication_methodology_files(
    pipeline: str,
) -> dict[str, Path]:
    """Return one non-conflicting severity methodology bundle per pipeline."""

    home = plamen_home()
    shared = {
        "finding-output-format": home / "rules" / "finding-output-format.md",
        "poc-execution": home / "rules" / "phase5-poc-execution.md",
    }
    pipeline_name = str(pipeline).lower()
    if pipeline_name == "l1":
        return {
            **shared,
            "l1-severity-matrix": (
                home / "docs" / "l1-mode" / "severity-matrix.md"
            ),
        }
    if pipeline_name == "sc":
        return {
            **shared,
            "report-template": home / "rules" / "report-template.md",
        }
    raise ValueError(f"unsupported severity methodology pipeline {pipeline!r}")


def _severity_adjudication_environment(
    config: dict[str, Any], scratchpad: Path
) -> tuple[dict[str, str], tuple[str, ...]]:
    """Build the explicit, privacy-preserving leaf-worker environment."""

    if "severity_adjudication_environment" in config:
        raw_environment = config.get("severity_adjudication_environment")
        raw_allowlist = config.get(
            "severity_adjudication_environment_allowlist", ()
        )
        if not isinstance(raw_environment, dict):
            raise ValueError("severity adjudication environment must be a mapping")
        allowlist = tuple(sorted(str(name) for name in raw_allowlist))
        environment = {
            str(name): str(value)
            for name, value in raw_environment.items()
            if str(name) in set(allowlist)
        }
        if set(environment) != set(allowlist):
            raise ValueError(
                "severity adjudication environment differs from its allowlist"
            )
        return environment, allowlist

    parent = _filtered_child_subprocess_environ()
    selected_names = (
        "PATH", "Path", "SystemRoot", "ComSpec", "TEMP", "TMP",
        "USERPROFILE", "APPDATA", "LOCALAPPDATA",
    )
    environment = {
        name: parent[name]
        for name in selected_names
        if name in parent and parent[name]
    }
    environment.update({
        **_CLAUDE_UPDATE_DISABLE_ENV,
        "ANTHROPIC_DEFAULT_OPUS_MODEL": str(PLAMEN_OPUS_MODEL),
        "ANTHROPIC_DEFAULT_SONNET_MODEL": str(PLAMEN_SONNET_MODEL),
        "ANTHROPIC_DEFAULT_HAIKU_MODEL": str(PLAMEN_HAIKU_MODEL),
        "PLAMEN_SCRATCHPAD": str(Path(scratchpad).resolve()),
        "BASH_MAX_OUTPUT_LENGTH": str(
            parent.get("BASH_MAX_OUTPUT_LENGTH", "30000")
        ),
        "MAX_MCP_OUTPUT_TOKENS": str(
            parent.get("MAX_MCP_OUTPUT_TOKENS", "8000")
        ),
    })
    allowlist = tuple(sorted(environment))
    return environment, allowlist


def _build_severity_adjudication_worker_launch_spec(
    *,
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
    plan: Mapping[str, Any],
    shard: Mapping[str, Any],
) -> dict[str, Any]:
    """Derive one headless leaf launch from the immutable worker plan."""

    del phase, shard
    backend = str(plan.get("backend") or "").lower()
    environment, allowlist = _severity_adjudication_environment(
        config, scratchpad
    )
    timeout_seconds = int(plan["timeout_seconds_per_worker"])
    if backend == "claude":
        # Semantic metadata only; the provider parent compiles the executable
        # vector after the durable worker arm.
        argv = list(_selected_claude_backend_argv_prefix())
    elif backend == "codex":
        argv = [
            str(CODEX_BIN), "exec",
            "--model", str(plan["effective_model"]),
            "--ephemeral",
            "--dangerously-bypass-approvals-and-sandbox",
            "--skip-git-repo-check",
            "--ignore-user-config",
            "--ignore-rules",
            "-",
        ]
    else:
        raise ValueError(
            f"unsupported live severity adjudication backend {backend!r}"
        )
    return {
        "argv": argv,
        "environment": environment,
        "environment_allowlist": allowlist,
        "timeout_seconds": timeout_seconds,
    }


def _severity_adjudication_containment_offenders(
    scratchpad: Path,
    project_root: Path,
    before: dict[str, tuple[int, int, str]],
    shard: Mapping[str, Any],
) -> list[str]:
    """Detect every child-boundary mutation outside its exact transaction."""

    after = _snapshot_application_skeptic_child_boundary(
        scratchpad, project_root
    )
    staging_prefix = str(shard["staging_output_scope"]).replace("\\", "/") + "/"
    provider_prefix = (
        ".worker_execution_receipts/" + str(shard["shard_id"]) + "/"
    )
    allowed = {
        str(value).replace("\\", "/")
        for value in (shard.get("expected_outputs") or {}).values()
    }
    suffix = Path(str(shard["launch_intent_file"])).name.split(".")[-2]
    allowed.add(f"severity_adjudication_worker_run.{suffix}.json")
    offenders: list[str] = []
    for name in sorted(set(before) | set(after)):
        if before.get(name) == after.get(name):
            continue
        normalized = name.replace("\\", "/")
        if (
            normalized in allowed
            or normalized.startswith(staging_prefix)
            or normalized.startswith(provider_prefix)
        ):
            continue
        offenders.append(normalized)
    return offenders


def _ensure_preverification_trust_boundary(
    scratchpad: Path,
    *,
    run_id: str,
    config: Mapping[str, Any] | None = None,
) -> list[str]:
    """Install a ledger-owned zero-authority sentinel before trust consumers."""

    root = Path(scratchpad)
    run = str(run_id or "").strip()
    cfg = dict(config or {})
    cfg.setdefault("pipeline", "sc")
    cfg.setdefault("mode", "thorough")
    cfg.setdefault("language", "evm")
    cfg.setdefault("cli_backend", "claude")
    cfg.setdefault("project_root", str(root.parent))
    cfg.setdefault("_run_id", run)
    try:
        planned = build_trust_evidence_provider_state(root, run_id=run)
        contract, launch = _trust_provider_contract_and_launch(
            root,
            cfg,
            planned[1],
            phase_name="startup",
            work_unit_id="trust_evidence_initial",
        )
        project = Path(str(cfg.get("project_root") or root.parent))
        state = read_artifact_ledger(root)
        bindings = state.get("artifact_bindings", {})
        expected = {spec.identity for spec in contract.outputs}
        existing_rows = {
            identity: bindings.get(identity)
            for identity in expected
            if isinstance(bindings, Mapping)
        }
        active_owners = {
            str(row.get("owner_key") or "")
            for row in existing_rows.values()
            if isinstance(row, Mapping) and row.get("status") == "ACTIVE"
        }
        if active_owners and all(
            isinstance(existing_rows.get(identity), Mapping)
            and existing_rows[identity].get("status") == "ACTIVE"
            for identity in expected
        ):
            provider_issues = list(
                validate_trust_evidence_provider_state(root, run_id=run)
            )
            if not provider_issues:
                return []
            # A later post-severity owner must never be overwritten backwards
            # by the startup producer.  Invalid bytes remain fail-closed debt.
            if any(
                owner.endswith(
                    "/severity_adjudication_shadow/trust_evidence_reconcile"
                )
                for owner in active_owners
            ):
                return provider_issues

        # Preserve an out-of-tree/unowned predecessor before the CREATE-like
        # first transaction.  A crash after this move is fail-closed (canonical
        # provider files are absent), and the original evidence is retained.
        quarantine = root / "_quarantine" / "trust_provider_startup"
        for spec in contract.outputs:
            path = root / spec.identity.split(":", 1)[1]
            row = (
                bindings.get(spec.identity)
                if isinstance(bindings, Mapping)
                else None
            )
            if not path.is_file() or isinstance(row, Mapping):
                continue
            raw = path.read_bytes()
            quarantine.mkdir(parents=True, exist_ok=True)
            suffix = hashlib.sha256(raw).hexdigest()[:16]
            target = quarantine / f"{suffix}.{path.name}"
            ordinal = 1
            while target.exists():
                target = quarantine / f"{suffix}.{ordinal}.{path.name}"
                ordinal += 1
            path.replace(target)

        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run,
        )
        if arm_issues or not execute:
            return arm_issues
        write_trust_evidence_provider_state(
            root, run_id=run, planned_state=planned
        )
        domain_issues = validate_trust_evidence_provider_state(
            root, run_id=run
        )
        return _commit_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project,
            contract=contract,
            launch=launch,
            run_id=run,
            domain_issues=domain_issues,
        )
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        return [
            "trust evidence startup PhaseIO failed; negative authority "
            f"remains disabled: {type(exc).__name__}: {exc}"
        ]


def _run_startup_trust_boundary_before_consumers(
    scratchpad: Path,
    *,
    run_id: str,
    config: Mapping[str, Any] | None = None,
    consumers: Iterable[Callable[[], Any]] = (),
) -> list[str]:
    """Establish driver ownership before any completed-run trust consumer.

    ``consumers`` is intentionally a narrow sequencing seam: startup uses the
    empty default and then enters its ordinary repair/reconciliation flow, while
    event-order fixtures can execute probes through the same boundary.  A
    provider failure remains explicit debt and cannot grant negative authority;
    production trust consumers additionally require the provider receipt.
    """

    issues = _ensure_preverification_trust_boundary(
        Path(scratchpad), run_id=str(run_id or "").strip(), config=config
    )
    for consumer in consumers:
        consumer()
    return issues


def _trust_provider_contract_and_launch(
    scratchpad: Path,
    config: Mapping[str, Any],
    receipt: Mapping[str, Any],
    *,
    phase_name: str = "severity_adjudication_shadow",
    work_unit_id: str = "trust_evidence_reconcile",
) -> tuple[Any, LaunchSpec]:
    bindings = receipt.get("input_bindings") or []
    if not isinstance(bindings, list):
        raise ValueError("trust provider input bindings are not a list")
    exact_inputs: list[str] = []
    for row in bindings:
        if not isinstance(row, Mapping):
            raise ValueError("trust provider input binding is malformed")
        path = str(row.get("path") or "").replace("\\", "/").strip()
        if not path or Path(path).is_absolute() or ".." in Path(path).parts:
            raise ValueError("trust provider input path is unsafe")
        exact_inputs.append(path)
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase=phase_name,
        work_unit_id=work_unit_id,
        exact_inputs=tuple(sorted(dict.fromkeys(exact_inputs))),
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model="driver",
        timeout_s=120,
        exec_mode="python",
        tool_policy=("filesystem",),
    )
    return contract, launch


def _trust_provider_debt_messages(receipt: Mapping[str, Any]) -> list[str]:
    messages = [
        f"trust provider global debt: {code}"
        for code in receipt.get("global_debts") or []
        if str(code).strip()
    ]
    for row in receipt.get("candidate_debts") or []:
        if not isinstance(row, Mapping):
            messages.append("trust provider candidate debt row is malformed")
            continue
        finding_id = str(row.get("finding_id") or "unknown")
        codes = ", ".join(str(code) for code in row.get("debt_codes") or [])
        messages.append(
            f"{finding_id} trust authority unavailable ({codes or 'UNSPECIFIED'}); "
            "retained upstream severity and verification"
        )
    return messages


def _reconcile_trust_evidence_provider_state(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Prebind and publish the post-severity no-authority state."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    project_root = Path(str(config.get("project_root") or root.parent))
    issues: list[str] = []
    try:
        planned: tuple[dict[str, Any], dict[str, Any]] | None = None
        contract: PhaseIOContract | None = None
        launch: LaunchSpec | None = None
        execute = False
        for _attempt in range(3):
            candidate = build_trust_evidence_provider_state(
                root, run_id=run_id
            )
            candidate_contract, candidate_launch = (
                _trust_provider_contract_and_launch(
                    root, config, candidate[1]
                )
            )
            prior = read_artifact_ledger(root).get("work_units", {}).get(
                candidate_contract.key
            )
            if (
                isinstance(prior, Mapping)
                and prior.get("semantic_status") == "INPUTS_BOUND"
                and prior.get("execution_state") == "INPUTS_BOUND_PREEXECUTION"
                and prior.get("artifacts") == {}
                and prior.get("contract_digest") != candidate_contract.digest
            ):
                recover_uncommitted_driver_input_denominator(
                    root,
                    project_root,
                    candidate_contract,
                    candidate_launch,
                    run_id=run_id,
                    reason_code=(
                        "DYNAMIC_INPUT_DENOMINATOR_DRIFT_BEFORE_OUTPUT_COMMIT"
                    ),
                )
                execute = True
                arm_issues: list[str] = []
            else:
                execute, arm_issues = _arm_deterministic_driver_work_unit(
                    scratchpad=root,
                    project_root=project_root,
                    contract=candidate_contract,
                    launch=candidate_launch,
                    run_id=run_id,
                )
            issues.extend(arm_issues)
            if arm_issues:
                break
            after = build_trust_evidence_provider_state(root, run_id=run_id)
            if after == candidate:
                planned = candidate
                contract = candidate_contract
                launch = candidate_launch
                break
        if planned is None or contract is None or launch is None:
            issues.append(
                "trust provider inputs did not stabilize before output write"
            )
            return list(dict.fromkeys(issues))
        if execute:
            write_trust_evidence_provider_state(
                root, run_id=run_id, planned_state=planned
            )
            domain_issues = list(
                validate_trust_evidence_provider_state(root, run_id=run_id)
            )
            current = build_trust_evidence_provider_state(root, run_id=run_id)
            if current != planned:
                domain_issues.append(
                    "trust provider inputs changed after PhaseIO prebind; "
                    "negative authority remains disabled"
                )
            issues.extend(_commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
                domain_issues=domain_issues,
            ))
        issues.extend(_trust_provider_debt_messages(planned[1]))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        issues.append(
            "trust evidence provider PhaseIO reconciliation failed; negative "
            f"authority remains disabled: {type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(str(item) for item in issues if str(item)))


def _trust_evidence_provider_resume_issues(
    scratchpad: Path,
    config: Mapping[str, Any],
) -> list[str]:
    """Side-effect-free completion check for the post-severity provider state."""

    root = Path(scratchpad)
    run_id = str(config.get("_run_id") or "").strip()
    project_root = Path(str(config.get("project_root") or root.parent))
    issues = list(validate_trust_evidence_provider_state(root, run_id=run_id))
    try:
        _ledger, expected_receipt = build_trust_evidence_provider_state(
            root, run_id=run_id
        )
        contract, launch = _trust_provider_contract_and_launch(
            root, config, expected_receipt
        )
        issues.extend(validate_work_unit_inputs(
            root, project_root, contract, launch, run_id=run_id
        ))
        issues.extend(validate_work_unit_artifacts(
            root,
            project_root,
            contract,
            launch,
            run_id=run_id,
            actor="DRIVER",
        ))
    except (ArtifactLedgerError, OSError, TypeError, ValueError) as exc:
        issues.append(
            "trust evidence provider resume authority invalid: "
            f"{type(exc).__name__}: {exc}"
        )
    return list(dict.fromkeys(str(item) for item in issues if str(item)))


def _run_severity_adjudication_shadow_phase(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> tuple[dict[str, Any], list[str]]:
    """Run the provider-bound, direction-neutral severity observer haltlessly."""

    root = Path(scratchpad)
    issues: list[str] = []
    source_ledger = root / SEVERITY_ADJUDICATION_SOURCE_LEDGER_NAME
    if not source_ledger.is_file():
        empty, empty_reason = is_verification_queue_empty(
            root, str(config.get("pipeline") or "sc")
        )
        stale_decisions = sorted(
            path.name
            for path in root.glob("verify_*.severity_decision.json")
            if path.is_file()
        )
        if empty and not stale_decisions:
            # A canonical zero-row verification transaction has no verifier
            # invocation from which severity_runtime could derive a ledger.
            # Materialize that exact empty denominator here.  Every other
            # missing-ledger state remains runtime debt and is caught by the
            # haltless outer phase boundary; it is never forged into safety.
            write_severity_decision_ledger(
                source_ledger,
                str(config.get("_run_id") or ""),
                (),
            )
            log.info(
                "[severity_adjudication_shadow] initialized exact empty "
                "source ledger (%s)",
                empty_reason,
            )
    snapshot = config.get("_audit_snapshot") or {}
    components = snapshot.get("components") if isinstance(snapshot, dict) else {}
    audit_config = (
        components.get("audit_config") if isinstance(components, dict) else {}
    )
    backend = str(config.get("cli_backend") or "claude").lower()
    if backend == "fixture-subprocess":
        effective_model = "fixture-python"
    else:
        effective_model = phase_model(
            phase, str(config.get("mode") or "core"), config
        )
    environment, allowlist = _severity_adjudication_environment(config, root)
    timeout_raw = config.get(
        "severity_adjudication_timeout_s", phase.base_timeout_s
    )
    timeout_seconds = int(float(timeout_raw))
    if timeout_seconds <= 0 or float(timeout_raw) != float(timeout_seconds):
        raise ValueError(
            "severity_adjudication_timeout_s must be a positive whole second"
        )
    plan = prepare_adjudication_work(
        root,
        run_id=str(config.get("_run_id") or ""),
        audit_snapshot_digest=str(snapshot.get("snapshot_digest") or ""),
        audit_config_digest=str(
            (audit_config or {}).get("digest") or ""
        ),
        methodology_files=_severity_adjudication_methodology_files(
            str(config.get("pipeline") or "sc")
        ),
        backend=backend,
        transport="headless-subprocess",
        effective_model=effective_model,
        working_directory=root,
        source_root=Path(config["project_root"]),
        tool_policy=(
            "read-bound-inputs-and-source",
            "write-assigned-staging-only",
            "no-shell-network-or-subagents",
        ),
        environment_allowlist_digest=environment_allowlist_sha256(allowlist),
        adjudicator_identity="independent-severity-adjudicator",
        invocation_prefix=(
            "severity-" + hashlib.sha256(
                (str(config.get("_run_id") or "") + ":" + backend).encode(
                    "utf-8"
                )
            ).hexdigest()[:20]
        ),
        timeout_seconds_per_worker=timeout_seconds,
    )
    reconciliation = reconcile_adjudication_work(root)
    project_root = Path(config["project_root"])
    for shard in plan.get("shards") or []:
        shard_states = {
            reconciliation.get("states", {}).get(candidate_id)
            for candidate_id in shard.get("candidate_ids") or []
        }
        if not shard_states.intersection({"PENDING", "OUTPUT_UNATTESTED"}):
            continue
        before = _snapshot_application_skeptic_child_boundary(
            root, project_root
        )
        try:
            spec = _build_severity_adjudication_worker_launch_spec(
                phase=phase,
                config=config,
                scratchpad=root,
                plan=plan,
                shard=shard,
            )
            provider_executor = None
            if backend == "claude":
                shard_id = str(shard["shard_id"])
                exact_inputs = tuple(dict.fromkeys((
                    SEVERITY_ADJUDICATION_WORK_PLAN_NAME,
                    SEVERITY_ADJUDICATION_MANIFEST_NAME,
                    str(shard["launch_intent_file"]),
                    str(shard["context_file"]),
                    str(shard["prompt_file"]),
                    str(shard["tool_policy_file"]),
                )))
                exact_outputs = tuple(
                    str(value)
                    for _candidate, value in sorted(
                        (shard.get("expected_outputs") or {}).items()
                    )
                )
                worker_contract = resolve_phase_io_contract(
                    pipeline=str(config.get("pipeline") or "sc"),
                    mode=str(config.get("mode") or "core"),
                    ecosystem=str(config.get("language") or "unknown"),
                    backend="claude",
                    phase="severity_adjudication_shadow",
                    work_unit_id=shard_id,
                    exact_inputs=exact_inputs,
                    exact_outputs=exact_outputs,
                )
                worker_launch = LaunchSpec(
                    work_unit_key=worker_contract.key,
                    pipeline=worker_contract.pipeline,
                    mode=worker_contract.mode,
                    ecosystem=worker_contract.ecosystem,
                    backend="claude",
                    model=effective_model,
                    timeout_s=timeout_seconds,
                    exec_mode="headless",
                    tool_policy=("filesystem",),
                )
                committed_worker_replay = _replay_committed_model_worker(
                    scratchpad=root,
                    project_root=project_root,
                    run_id=str(
                        config.get("_run_id") or "test-unbound"
                    ),
                    contract=worker_contract,
                    launch=worker_launch,
                    methodology_digests=(str(plan["plan_digest"]),),
                    source_snapshot_digest=(
                        _security_obligation_source_snapshot_digest(config)
                    ),
                )
                if committed_worker_replay is None:
                    worker_execute, worker_arm_issues = (
                        _arm_deterministic_driver_work_unit(
                            scratchpad=root,
                            project_root=project_root,
                            contract=worker_contract,
                            launch=worker_launch,
                            run_id=str(
                                config.get("_run_id") or "test-unbound"
                            ),
                        )
                    )
                else:
                    worker_execute, worker_arm_issues = False, []
                if worker_arm_issues:
                    raise AdjudicationWorkError(
                        "severity transactional PhaseIO arm failed: "
                        + "; ".join(worker_arm_issues)
                    )
                if worker_execute:
                    prompt_path = root / str(shard["prompt_file"])
                    prompt_text = prompt_path.read_text(
                        encoding="utf-8", errors="strict"
                    )
                    startup_binding, prelaunch_capability = (
                        _replay_explicit_claude_headless_launch_boundary(
                            phase=phase,
                            config=config,
                            scratchpad=root,
                            contract=worker_contract,
                            launch=worker_launch,
                        )
                    )
                    from worker_transaction import (
                        attempt_output_directory,
                        compile_attempt_write_scope,
                    )
                    attempt_id = f"attempt-{uuid.uuid4().hex[:24]}"
                    attempt_scope = compile_attempt_write_scope(
                        run_id=str(config.get("_run_id") or "test-unbound"),
                        phase=worker_contract.phase,
                        work_unit_id=worker_contract.work_unit_id,
                        attempt_id=attempt_id,
                    )
                    output_directory = attempt_output_directory(
                        root, attempt_scope
                    )
                    boundary = _prepare_claude_phase_tool_boundary(
                        phase=phase,
                        scratchpad=root,
                        config=config,
                        attempt=1,
                        prompt_snapshot=prompt_path,
                        transaction_output_directory=output_directory,
                        contract=worker_contract,
                        launch=worker_launch,
                    )
                    if not isinstance(boundary, Mapping):
                        raise AdjudicationWorkError(
                            "severity restricted tool boundary is unavailable"
                        )
                    source_snapshot_sha256 = (
                        _security_obligation_source_snapshot_digest(config)
                    )
                    authority = _compile_claude_driver_provider_authority(
                        phase=phase,
                        config=config,
                        scratchpad=root,
                        project_root=project_root.resolve(strict=True),
                        cwd=root.resolve(strict=True),
                        launch=worker_launch,
                        session_id=claude_semantic_session_id(
                            work_unit_id=worker_contract.work_unit_id,
                            work_unit_resume_digest=str(plan["plan_digest"]),
                            prompt_sha256=hashlib.sha256(
                                prompt_path.read_bytes()
                            ).hexdigest(),
                        ),
                        startup_authority_binding=startup_binding,
                        source_snapshot_sha256=source_snapshot_sha256,
                    )

                    def run_transactional_severity_provider():
                        if (
                            _replay_explicit_claude_headless_launch_boundary(
                                phase=phase,
                                config=config,
                                scratchpad=root,
                                contract=worker_contract,
                                launch=worker_launch,
                            )
                            != (startup_binding, prelaunch_capability)
                        ):
                            raise AdjudicationWorkError(
                                "severity Claude boundary changed before launch"
                            )

                        def command_builder(
                            routed_output_directory: Path,
                        ) -> Sequence[str]:
                            del routed_output_directory
                            return authority.base_argv_template

                        public = authority.public_arguments
                        result = execute_headless_worker(
                            scratchpad=root,
                            project_root=project_root.resolve(strict=True),
                            run_id=str(
                                config.get("_run_id") or "test-unbound"
                            ),
                            phase_io_contract=worker_contract,
                            phase_io_launch=worker_launch,
                            prompt=prompt_text,
                            command_builder=command_builder,
                            cwd=root.resolve(strict=True),
                            environment=dict(public["environment"]),
                            environment_allowlist=tuple(
                                public["environment_allowlist"]
                            ),
                            source_snapshot_digest=source_snapshot_sha256,
                            methodology_digests=(str(plan["plan_digest"]),),
                            startup_authority_binding=startup_binding,
                            parser_digest=severity_adjudication_output_digest,
                            provider_stdout_evidence_configuration=public.get(
                                "provider_stdout_evidence_configuration"
                            ),
                            claude_launch_security=public.get(
                                "claude_launch_security"
                            ),
                            claude_launch_security_request=public.get(
                                "claude_launch_security_request"
                            ),
                            claude_provider_preparation=authority.preparation,
                            claude_runtime_local_inputs=(
                                authority.runtime_local_inputs
                            ),
                            claude_bound_settings_bytes=(
                                authority.bound_settings_bytes
                            ),
                            claude_selected_mcp_config_bytes=(
                                authority.selected_mcp_config_bytes
                            ),
                            cancel_token=_current_worker_cancel_token(),
                            attempt_id=attempt_id,
                        )
                        return result.execution.provider_execution

                    provider_executor = run_transactional_severity_provider
                else:
                    def recover_transactional_severity_provider():
                        if committed_worker_replay is None:
                            raise AdjudicationWorkError(
                                "severity committed worker replay is absent"
                            )
                        normalized, _worker_plan = committed_worker_replay
                        return _completed_execution_from_worker_replay(
                            scratchpad=root,
                            authority=normalized,
                            exact_outputs=exact_outputs,
                        )

                    provider_executor = recover_transactional_severity_provider
            execute_adjudication_worker(
                root,
                shard_id=str(shard["shard_id"]),
                argv=spec["argv"],
                startup_authority_binding=(
                    _current_auxiliary_writable_root_startup_binding(
                        root,
                        config,
                    )
                ),
                environment=spec["environment"],
                environment_allowlist=spec["environment_allowlist"],
                timeout_seconds=spec["timeout_seconds"],
                provider_executor=provider_executor,
            )
        except Exception as exc:
            issues.append(
                f"{shard['shard_id']} worker/provider debt: "
                f"{type(exc).__name__}: {exc}"
            )
        finally:
            offenders = (
                []
                if backend == "claude"
                else _severity_adjudication_containment_offenders(
                    root, project_root, before, shard
                )
            )
            if offenders:
                issues.append(
                    f"{shard['shard_id']} worker containment violation: "
                    + ", ".join(offenders)
                )
        reconciliation = reconcile_adjudication_work(root)

    for candidate_id in list(
        reconciliation.get("states", {})
    ):
        state = reconciliation["states"].get(candidate_id)
        if state == "RECEIPT_PENDING_DECISION_COMMIT":
            _written, recovery_issues = (
                recover_receipt_pending_decision_commit(root, candidate_id)
            )
            issues.extend(recovery_issues)
    reconciliation = reconcile_adjudication_work(root)

    for candidate_id in list(reconciliation.get("bind_ready_ids") or []):
        try:
            worker_run = validate_completed_worker_run_for_candidate(
                root, candidate_id
            )
            _written, bind_issues = bind_shadow_adjudication_for_candidate(
                root,
                candidate_id,
                backend=str(worker_run["backend"]),
                launch_digest=str(worker_run["receipt_digest"]),
                run_id=str(worker_run["run_id"]),
                worker_identity=str(worker_run["worker_identity"]),
                invocation_id=str(worker_run["invocation_id"]),
            )
            issues.extend(bind_issues)
        except Exception as exc:
            issues.append(
                f"{candidate_id} adjudication bind debt: "
                f"{type(exc).__name__}: {exc}"
            )
    reconciliation = reconcile_adjudication_work(root)
    issues.extend(validate_severity_adjudication_reconciliation(root))
    for candidate_id, state in reconciliation.get("states", {}).items():
        if state != "COMPLETED":
            detail = reconciliation.get("details", {}).get(candidate_id, "")
            issues.append(
                f"{candidate_id} unresolved severity adjudication state "
                f"{state}: {detail}".rstrip()
            )
    return reconciliation, list(dict.fromkeys(issue for issue in issues if issue))


def _refresh_severity_report_shadow_projection(
    checkpoint: Checkpoint,
    scratchpad: Path,
    config: dict[str, Any],
    *,
    stage: str,
) -> list[str]:
    """Observe severity delivery drift without authorizing report mutation."""

    root = Path(scratchpad)
    stage_name = str(stage or "").strip().upper()
    if stage_name == "PRE_ASSEMBLE":
        work_unit = "report_projection"
        output_name = "severity_report_shadow_receipt.json"
        tracked = [
            root / "report_index.md",
            root / "report_critical_high.md",
            root / "report_medium.md",
            root / "report_low_info.md",
        ]
    elif stage_name == "POST_REPORT_FLOOR":
        work_unit = "final_report_projection"
        output_name = "severity_final_report_shadow_receipt.json"
        tracked = [Path(config["project_root"]) / "AUDIT_REPORT.md"]
    else:
        return [f"unsupported severity report projection stage {stage!r}"]
    before = {
        str(path.resolve()): path.read_bytes()
        for path in tracked
        if path.is_file()
    }
    issues: list[str] = []
    receipt: dict[str, Any] = {}
    try:
        contract = resolve_phase_io_contract(
            pipeline=str(config.get("pipeline") or "sc"),
            mode=str(config.get("mode") or "core"),
            ecosystem=str(config.get("language") or "unknown"),
            backend=str(config.get("cli_backend") or "claude"),
            phase="severity_adjudication_shadow",
            work_unit_id=work_unit,
        )
        launch = LaunchSpec(
            work_unit_key=contract.key,
            pipeline=contract.pipeline,
            mode=contract.mode,
            ecosystem=contract.ecosystem,
            backend=contract.backend,
            model="driver",
            timeout_s=120,
            exec_mode="python",
            tool_policy=("filesystem",),
        )
        run_id = str(config.get("_run_id") or checkpoint.run_id)
        project_root = Path(config["project_root"])
        receipt = write_shadow_report_severity_receipt(
            root,
            run_id=run_id,
            projection_stage=stage_name,
            project_root=(
                project_root
                if stage_name == "POST_REPORT_FLOOR"
                else None
            ),
            persist=False,
        )
        for event in receipt.get("drift_events") or []:
            issues.append(
                "severity report projection drift: "
                f"{event.get('candidate_id', 'unknown')} "
                f"{event.get('surface', 'unknown')} "
                f"{event.get('drift_kind', 'UNKNOWN')}"
            )
        for candidate_id in receipt.get("unresolved_candidate_ids") or []:
            issues.append(
                f"{candidate_id} severity remains unresolved; report observation "
                "uses retention severity"
            )
        execute, arm_issues = _arm_deterministic_driver_work_unit(
            scratchpad=root,
            project_root=project_root,
            contract=contract,
            launch=launch,
            run_id=run_id,
        )
        issues.extend(arm_issues)
        if execute:
            _atomic_driver_json_record(root / output_name, receipt)
            issues.extend(_commit_deterministic_driver_work_unit(
                scratchpad=root,
                project_root=project_root,
                contract=contract,
                launch=launch,
                run_id=run_id,
            ))
    except Exception as exc:
        issues.append(
            "severity report projection receipt/authority failed: "
            f"{type(exc).__name__}: {exc}"
        )
    after = {
        str(path.resolve()): path.read_bytes()
        for path in tracked
        if path.is_file()
    }
    if before != after:
        issues.append(
            "severity shadow projection mutated a report artifact"
        )

    child = Phase(
        "severity_adjudication_shadow",
        [f"Severity shadow {stage_name}"],
        [output_name],
        base_timeout_s=120,
        model="sonnet",
        critical=False,
    )
    controller = PhaseCommitController(
        checkpoint, root, config["project_root"], config
    )
    issues = list(dict.fromkeys(str(issue) for issue in issues if issue))
    if issues:
        failures = _gate_failures_from_issues(
            child,
            issues,
            contract_digest=_resolved_phase_contract_digest(child, config),
            output_digest=_resolved_phase_artifact_digest(
                child, root, config["project_root"]
            ),
            scratchpad=root,
            input_digest=_resolved_phase_input_digest(child, config),
        )
        controller.commit(
            child,
            "COMPLETED_WITH_DEBT",
            failures,
            work_unit_id=work_unit,
            clean_transients=False,
        )
    else:
        controller.commit(
            child,
            "CLEAN",
            (),
            work_unit_id=work_unit,
            clean_transients=True,
        )
    return issues


def _prepare_application_skeptic_queue_union(
    scratchpad: Path, config: dict[str, Any]
) -> None:
    """Materialize explicit empty queues only for known non-triggered work.

    Missing output from an active producer/repair attempt remains missing and
    is classified as INPUT_DEBT by the planner.  This helper never turns an
    unexplained absence into an empty queue.
    """

    active = set(config.get("_active_phase_names") or ())
    root = Path(scratchpad)
    for source in _APPLICATION_SKEPTIC_BASE_PHASES:
        source_queue = root / f"methodology_skeptic_queue_{source}.json"
        if source not in active:
            application_states.write_application_queues(root, [], phase=source)
        elif not source_queue.is_file():
            # Active source absence is deliberately left for the exact-union
            # planner to retain as input debt.
            pass

        repair_phase = f"{source}_repair"
        repair_queue = root / f"methodology_skeptic_queue_{repair_phase}.json"
        attempt = root / _methodology_repair_attempt_file(source)
        if not attempt.is_file():
            application_states.write_application_queues(
                root, [], phase=repair_phase
            )
        elif not repair_queue.is_file():
            # A recorded attempt with no queue is a producer/dropout failure,
            # not a legitimate zero-work condition.
            pass


def _application_skeptic_assessor_identity(
    config: dict[str, Any], plan_digest: str, shard_id: str
) -> tuple[str, str]:
    assessor_id = f"APPLICATION_SKEPTIC_{shard_id.upper().replace('-', '_')}"
    invocation = "ASKI-" + hashlib.sha256(
        "\0".join((
            str(config.get("_run_id") or "unbound"),
            plan_digest,
            shard_id,
        )).encode("utf-8")
    ).hexdigest()[:24].upper()
    return assessor_id, invocation


def _application_skeptic_io_contract_launch(
    *,
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
    work_unit_id: str,
    actor: str,
    exact_outputs: tuple[str, ...] = (),
    exact_inputs: tuple[str, ...] = (),
    model: str = "driver",
    timeout_s: int = 120,
    tool_policy: tuple[str, ...] = ("filesystem",),
) -> tuple[PhaseIOContract, LaunchSpec]:
    contract = resolve_phase_io_contract(
        pipeline=str(config.get("pipeline") or "sc"),
        mode=str(config.get("mode") or "core"),
        ecosystem=str(config.get("language") or "unknown"),
        backend=str(config.get("cli_backend") or "claude"),
        phase="application_skeptic",
        work_unit_id=work_unit_id,
        exact_outputs=exact_outputs,
        exact_inputs=exact_inputs,
    )
    launch = LaunchSpec(
        work_unit_key=contract.key,
        pipeline=contract.pipeline,
        mode=contract.mode,
        ecosystem=contract.ecosystem,
        backend=contract.backend,
        model=model,
        timeout_s=max(1, int(timeout_s)),
        exec_mode=(
            "python" if actor == "DRIVER" else
            ("codex" if contract.backend == "codex" else "headless")
        ),
        tool_policy=tool_policy,
    )
    return contract, launch


def _arm_application_skeptic_io(
    *,
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
    work_unit_id: str,
    actor: str,
    exact_outputs: tuple[str, ...] = (),
    exact_inputs: tuple[str, ...] = (),
    model: str = "driver",
    timeout_s: int = 120,
    tool_policy: tuple[str, ...] = ("filesystem",),
    committed_model_methodology_digests: tuple[str, ...] = (),
) -> tuple[PhaseIOContract, LaunchSpec, bool, list[str]]:
    contract, launch = _application_skeptic_io_contract_launch(
        scratchpad=scratchpad,
        config=config,
        phase=phase,
        work_unit_id=work_unit_id,
        actor=actor,
        exact_outputs=exact_outputs,
        exact_inputs=exact_inputs,
        model=model,
        timeout_s=timeout_s,
        tool_policy=tool_policy,
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    project_root = Path(config.get("project_root") or Path(scratchpad).parent)
    if actor == "MODEL" and committed_model_methodology_digests:
        committed = _replay_committed_model_worker(
            scratchpad=Path(scratchpad),
            project_root=project_root,
            run_id=run_id,
            contract=contract,
            launch=launch,
            methodology_digests=committed_model_methodology_digests,
            source_snapshot_digest=(
                _security_obligation_source_snapshot_digest(config)
            ),
        )
        if committed is not None:
            return contract, launch, False, []
    execute, issues = _arm_deterministic_driver_work_unit(
        scratchpad=Path(scratchpad),
        project_root=project_root,
        contract=contract,
        launch=launch,
        run_id=run_id,
    )
    return contract, launch, execute, issues


def _commit_application_skeptic_io(
    *,
    scratchpad: Path,
    config: dict[str, Any],
    contract: PhaseIOContract,
    launch: LaunchSpec,
) -> list[str]:
    return _commit_deterministic_driver_work_unit(
        scratchpad=Path(scratchpad),
        project_root=Path(
            config.get("project_root") or Path(scratchpad).parent
        ),
        contract=contract,
        launch=launch,
        run_id=str(config.get("_run_id") or "test-unbound"),
    )


def _record_application_skeptic_io(
    *,
    scratchpad: Path,
    config: dict[str, Any],
    phase: Phase,
    work_unit_id: str,
    actor: str,
    exact_outputs: tuple[str, ...] = (),
    exact_inputs: tuple[str, ...] = (),
    model: str = "driver",
    timeout_s: int = 120,
) -> list[str]:
    """Commit an already-armed skeptic boundary; never adopt live bytes."""

    contract, launch = _application_skeptic_io_contract_launch(
        scratchpad=scratchpad,
        config=config,
        phase=phase,
        work_unit_id=work_unit_id,
        actor=actor,
        exact_outputs=exact_outputs,
        exact_inputs=exact_inputs,
        model=model,
        timeout_s=timeout_s,
    )
    run_id = str(config.get("_run_id") or "test-unbound")
    project_root = Path(config.get("project_root") or Path(scratchpad).parent)
    try:
        issues = validate_work_unit_inputs(
            scratchpad,
            project_root,
            contract,
            launch,
            run_id=run_id,
        )
        if issues:
            return list(dict.fromkeys(
                str(issue) for issue in issues if str(issue)
            ))
        return _commit_application_skeptic_io(
            scratchpad=scratchpad,
            config=config,
            contract=contract,
            launch=launch,
        )
    except (ArtifactLedgerError, ValueError) as exc:
        return [f"{type(exc).__name__}: {exc}"]


def _snapshot_application_skeptic_child_boundary(
    scratchpad: Path,
    project_root: Path,
) -> dict[str, tuple[int, int, str]]:
    """Snapshot the exact filesystem boundary around one skeptic child.

    ``application_skeptic`` is a custom sharded phase and therefore does not
    pass through the ordinary ``run_phase`` post-attempt containment hook.  A
    prompt-scoped output contract is not an enforcement boundary: a fast child
    can write a future artifact (or the project-root report) and exit before
    the heartbeat observes it.  Capture both the scratchpad and the project
    tree so the driver can deterministically reconcile what changed after the
    child returns.

    Driver-owned control files are retained in the snapshot and filtered by
    the reconciler below.  The only directory omitted is ``.git``: its object
    database is not an audit artifact, can be enormous, and is not writable by
    any application-skeptic contract.  The scratchpad is scanned exactly once
    via ``_snapshot_file_state`` and excluded from the project-tree walk.
    """

    root = Path(project_root).absolute()
    scratch = Path(scratchpad).absolute()
    state: dict[str, tuple[int, int, str]] = {}

    def _fingerprint(path: Path) -> tuple[int, int, str] | None:
        try:
            stat = path.stat()
            digest = hashlib.sha256()
            with path.open("rb") as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(chunk)
            return stat.st_mtime_ns, stat.st_size, digest.hexdigest()
        except OSError:
            return None

    excluded_scratch_dirs = {
        "_overflow", "_retry_quarantine", ".pytest_cache", "__pycache__",
    }
    try:
        for path in scratch.rglob("*"):
            try:
                relative = path.relative_to(scratch)
            except ValueError:
                continue
            if relative.parts and relative.parts[0] in excluded_scratch_dirs:
                continue
            if not path.is_file():
                continue
            fingerprint = _fingerprint(path)
            if fingerprint is not None:
                state[relative.as_posix()] = fingerprint
    except OSError:
        pass

    try:
        for path in root.rglob("*"):
            try:
                relative = path.relative_to(root)
            except ValueError:
                continue
            if ".git" in relative.parts:
                continue
            try:
                absolute_path = path.absolute()
                if absolute_path == scratch or absolute_path.is_relative_to(scratch):
                    continue
            except (OSError, ValueError):
                pass
            if not path.is_file():
                continue
            fingerprint = _fingerprint(path)
            if fingerprint is not None:
                state[f"../{relative.as_posix()}"] = fingerprint
    except OSError:
        pass
    return state


def _application_skeptic_typed_provider_control(
    name: str,
    *,
    phase_io_contract: PhaseIOContract | None,
    provider_layout: Any | None,
) -> bool:
    """Admit only the exact PhaseIO outputs and typed WER transaction paths."""

    if not name or name.startswith("../") or "\\" in name:
        return False
    phase_io_outputs = {
        str(output.path)
        for output in ((phase_io_contract.outputs if phase_io_contract else ()))
        if str(output.root) == "scratchpad"
    }
    if name in phase_io_outputs:
        return True
    if provider_layout is None:
        return False
    exact_wer_paths = {
        str(provider_layout.staged_output_relative),
        str(provider_layout.containment_debt_relative),
        str(provider_layout.retry_intent_relative),
    }
    if name in exact_wer_paths:
        return True
    provider_ids = {
        str(provider_layout.provider_shard_id),
        str(provider_layout.retry_provider_shard_id),
    }
    return any(
        name.startswith(f"{root_name}/{provider_id}/")
        for root_name in (
            ".worker_execution_receipts",
            ".skeptic_execution_quarantine",
        )
        for provider_id in provider_ids
    )


def _application_skeptic_child_containment_offenders(
    scratchpad: Path,
    project_root: Path,
    before_state: dict[str, tuple[int, int, str]],
    *,
    exact_output: str,
    phase_io_contract: PhaseIOContract | None = None,
    provider_layout: Any | None = None,
) -> list[str]:
    """Return every child-time write outside its one declared output.

    A closed filename grammar admits only driver runtime controls created by
    the launchers (prompt snapshots, stdio, isolation config, cost telemetry,
    and orphan diagnostics).  A leading underscore is never authority: typed
    checkpoints, semantic ledgers, near-miss assessment names, arbitrary
    siblings, future-phase files, and every project-root write remain foreign.
    """

    after_state = _snapshot_application_skeptic_child_boundary(
        scratchpad, project_root
    )
    offenders: list[str] = []
    for name in sorted(set(before_state) | set(after_state)):
        if before_state.get(name) == after_state.get(name):
            continue
        if name == exact_output:
            continue
        if _application_skeptic_typed_provider_control(
            name,
            phase_io_contract=phase_io_contract,
            provider_layout=provider_layout,
        ):
            continue
        offenders.append(name)
    return sorted(set(offenders))


def _reconcile_application_skeptic_provider_attempt(
    *,
    scratchpad: Path,
    project_root: Path,
    config: dict[str, Any],
    shard_id: str,
    before_state: dict[str, tuple[int, int, str]],
    phase_io_contract: PhaseIOContract,
    provider_layout: Any,
) -> list[str]:
    """Quarantine and durably bind one application provider attempt."""

    exact_outputs = [
        str(output.path)
        for output in phase_io_contract.outputs
        if str(output.root) == "scratchpad"
    ]
    workflow = str(provider_layout.workflow)
    assessment_output = str(provider_layout.canonical_output_relative)
    authority_output = str(provider_layout.authority_sidecar_relative)

    def safe_scratchpad_relative(identity: str) -> bool:
        parsed = PurePosixPath(identity)
        return (
            bool(identity)
            and "\\" not in identity
            and ":" not in identity
            and not parsed.is_absolute()
            and parsed.as_posix() == identity
            and all(part not in {"", ".", ".."} for part in parsed.parts)
        )

    if (
        workflow not in {"application_skeptic", "candidate_negative"}
        or not safe_scratchpad_relative(assessment_output)
        or not safe_scratchpad_relative(authority_output)
        or assessment_output == authority_output
        or len(exact_outputs) != 2
        or exact_outputs.count(assessment_output) != 1
        or exact_outputs.count(authority_output) != 1
    ):
        return [
            "application_skeptic containment PhaseIO assessment/authority "
            "denominator is not exact"
        ]
    offenders = _application_skeptic_child_containment_offenders(
        scratchpad,
        project_root,
        before_state,
        exact_output=assessment_output,
        phase_io_contract=phase_io_contract,
        provider_layout=provider_layout,
    )
    if not offenders:
        return []
    try:
        moved, failed = _quarantine_foreign_phase_writes(
            scratchpad,
            str(project_root),
            "application_skeptic",
            offenders,
        )
    except Exception:
        moved, failed = [], list(offenders)
    moved = sorted(set(str(name) for name in moved) & set(offenders))
    failed = sorted(set(str(name) for name in failed) & set(offenders))
    unaccounted = sorted(set(offenders) - set(moved) - set(failed))
    event_issues = _write_application_skeptic_containment_event(
        scratchpad,
        config=config,
        shard_id=shard_id,
        offenders=offenders,
        moved=moved,
        failed=failed,
    )
    issues = list(event_issues)
    if failed:
        issues.append(
            "application_skeptic phase containment: foreign child write "
            "could not be quarantined: " + ", ".join(failed)
        )
    if unaccounted:
        issues.append(
            "application_skeptic phase containment: child mutation was not "
            "accounted by quarantine: " + ", ".join(unaccounted)
        )
    return list(dict.fromkeys(issues))


_APPLICATION_SKEPTIC_CONTAINMENT_NAME = (
    "_application_skeptic_containment.json"
)
_APPLICATION_SKEPTIC_CONTAINMENT_SCHEMA = (
    "plamen.application_skeptic_containment.v1"
)


def _application_skeptic_containment_path(
    scratchpad: Path, project_root: Path, name: str
) -> Path:
    if name.startswith("../"):
        return Path(project_root) / name[3:]
    return Path(scratchpad) / name


def _load_application_skeptic_containment_receipt(
    scratchpad: Path,
) -> dict[str, Any] | None:
    path = Path(scratchpad) / _APPLICATION_SKEPTIC_CONTAINMENT_NAME
    if not path.is_file():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
        if (
            not isinstance(payload, dict)
            or set(payload) != {
                "schema_version", "events", "receipt_sha256"
            }
            or payload.get("schema_version")
            != _APPLICATION_SKEPTIC_CONTAINMENT_SCHEMA
            or not isinstance(payload.get("events"), list)
            or not payload.get("events")
        ):
            raise ValueError("schema mismatch")
        event_hashes: set[str] = set()
        for event in payload["events"]:
            if not isinstance(event, dict) or set(event) != {
                "run_id", "shard_id", "offenders", "moved", "failed",
                "event_sha256",
            }:
                raise ValueError("event schema mismatch")
            if not str(event.get("run_id") or "").strip() or not str(
                event.get("shard_id") or ""
            ).strip():
                raise ValueError("event identity is empty")
            normalized_lists: dict[str, list[str]] = {}
            for field_name in ("offenders", "moved", "failed"):
                values = event.get(field_name)
                if (
                    not isinstance(values, list)
                    or any(
                        not isinstance(value, str) or not value.strip()
                        for value in values
                    )
                    or values != sorted(set(values))
                ):
                    raise ValueError(f"event {field_name} is not canonical")
                normalized_lists[field_name] = list(values)
            offenders = set(normalized_lists["offenders"])
            moved = set(normalized_lists["moved"])
            failed = set(normalized_lists["failed"])
            if (
                not offenders
                or not moved.issubset(offenders)
                or not failed.issubset(offenders)
                or moved & failed
            ):
                raise ValueError("event containment sets are inconsistent")
            event_unsigned = {
                key: value for key, value in event.items()
                if key != "event_sha256"
            }
            event_expected = hashlib.sha256(
                json.dumps(
                    event_unsigned,
                    ensure_ascii=True,
                    allow_nan=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            if event.get("event_sha256") != event_expected:
                raise ValueError("event digest mismatch")
            if event_expected in event_hashes:
                raise ValueError("duplicate containment event")
            event_hashes.add(event_expected)
        unsigned = {
            key: value for key, value in payload.items()
            if key != "receipt_sha256"
        }
        expected = hashlib.sha256(
            json.dumps(
                unsigned,
                ensure_ascii=True,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if payload.get("receipt_sha256") != expected:
            raise ValueError("digest mismatch")
        return payload
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as exc:
        raise RuntimeError(
            f"application_skeptic containment receipt invalid: {exc}"
        ) from exc


def _write_application_skeptic_containment_event(
    scratchpad: Path,
    *,
    config: dict[str, Any],
    shard_id: str,
    offenders: list[str],
    moved: list[str],
    failed: list[str],
) -> list[str]:
    path = Path(scratchpad) / _APPLICATION_SKEPTIC_CONTAINMENT_NAME
    try:
        try:
            prior = _load_application_skeptic_containment_receipt(scratchpad)
        except RuntimeError:
            prior = None
        events = list((prior or {}).get("events") or [])
        event_unsigned = {
            "run_id": str(config.get("_run_id") or "test-unbound"),
            "shard_id": str(shard_id),
            "offenders": sorted(set(offenders)),
            "moved": sorted(set(moved)),
            "failed": sorted(set(failed)),
        }
        event = {
            **event_unsigned,
            "event_sha256": hashlib.sha256(
                json.dumps(
                    event_unsigned,
                    ensure_ascii=True,
                    allow_nan=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
        }
        if not any(
            isinstance(row, dict)
            and row.get("event_sha256") == event["event_sha256"]
            for row in events
        ):
            events.append(event)
        unsigned = {
            "schema_version": _APPLICATION_SKEPTIC_CONTAINMENT_SCHEMA,
            "events": events,
        }
        payload = {
            **unsigned,
            "receipt_sha256": hashlib.sha256(
                json.dumps(
                    unsigned,
                    ensure_ascii=True,
                    allow_nan=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
        }
        temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
        temporary.write_text(
            json.dumps(payload, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        os.replace(temporary, path)
        return []
    except Exception as exc:
        return [
            "application_skeptic containment receipt write failed: "
            f"{type(exc).__name__}: {exc}"
        ]


def _application_skeptic_durable_containment_debt(
    scratchpad: Path,
    project_root: Path,
) -> list[str]:
    try:
        receipt = _load_application_skeptic_containment_receipt(scratchpad)
    except RuntimeError as exc:
        return [str(exc)]
    if receipt is None:
        return []
    issues: list[str] = []
    for event in receipt.get("events") or []:
        if not isinstance(event, dict):
            issues.append(
                "application_skeptic containment receipt has malformed event"
            )
            continue
        offenders = set(event.get("offenders") or [])
        moved = set(event.get("moved") or [])
        failed = set(event.get("failed") or [])
        for name in sorted(failed):
            if _application_skeptic_containment_path(
                scratchpad, project_root, str(name)
            ).is_file():
                issues.append(
                    "application_skeptic phase containment: foreign child "
                    f"write remains live from prior attempt: {name}"
                )
        for name in sorted(offenders - moved - failed):
            issues.append(
                "application_skeptic phase containment: child mutation could "
                f"not be quarantined (path may have been deleted): {name}"
            )
    return list(dict.fromkeys(issues))


def _run_application_skeptic_phase(
    phase: Phase,
    config: dict[str, Any],
    scratchpad: Path,
) -> tuple[dict[str, Any], list[str]]:
    """Run the conditional pre-candidate discriminator haltlessly."""

    root = Path(scratchpad)
    _prepare_application_skeptic_queue_union(root, config)
    plan = build_application_skeptic_work_plan(
        root,
        max_items_per_shard=max(
            1, int(config.get("application_skeptic_shard_size") or 12)
        ),
    )
    (
        planning_contract,
        planning_launch,
        planning_execute,
        issues,
    ) = _arm_application_skeptic_io(
        scratchpad=root,
        config=config,
        phase=phase,
        work_unit_id="planning",
        actor="DRIVER",
    )
    if planning_execute:
        written_plan = write_application_skeptic_work_plan(
            root,
            max_items_per_shard=max(
                1, int(config.get("application_skeptic_shard_size") or 12)
            ),
        )
        if written_plan != plan:
            issues.append(
                "application-skeptic plan changed between arm and write"
            )
        else:
            issues.extend(
                _commit_application_skeptic_io(
                    scratchpad=root,
                    config=config,
                    contract=planning_contract,
                    launch=planning_launch,
                )
            )
    elif not issues:
        try:
            current_plan = json.loads(
                (root / APPLICATION_SKEPTIC_WORK_PLAN_FILE).read_text(
                    encoding="utf-8", errors="strict"
                )
            )
            if current_plan != plan:
                issues.append(
                    "application-skeptic committed plan differs from current "
                    "exact input union"
                )
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            issues.append(
                "application-skeptic committed plan replay failed: "
                f"{type(exc).__name__}: {exc}"
            )
    issues.extend(
        _application_skeptic_durable_containment_debt(
            root, Path(config.get("project_root") or root.parent)
        )
    )

    prior: dict[str, Any] | None = None
    last_good_receipt: dict[str, Any] | None = None
    last_good_delivery: dict[str, Any] | None = None
    receipt_path = root / "application_skeptic_receipt.json"
    preservation_context = _application_skeptic_preservation_context(
        plan, config
    )
    try:
        candidate = json.loads(receipt_path.read_text(encoding="utf-8"))
        if (
            isinstance(candidate, dict)
            and candidate.get("work_plan_digest") == plan["work_plan_digest"]
        ):
            last_good_receipt = candidate
            if candidate.get("status") == "PARTIAL":
                prior = candidate
    except (OSError, UnicodeError, json.JSONDecodeError):
        pass
    try:
        delivery = json.loads(
            (root / _APPLICATION_SKEPTIC_DELIVERY_FILE).read_text(
                encoding="utf-8"
            )
        )
        if isinstance(delivery, dict):
            last_good_delivery = delivery
    except (OSError, UnicodeError, json.JSONDecodeError):
        pass

    pending = set(application_skeptic_pending_ids(plan, prior))
    assessments: list[dict[str, Any]] = []
    imported_assessment_outputs: list[str] = []
    model_was_invoked = False
    effective_model = phase_model(
        phase, str(config.get("mode") or "core"), config
    )
    timeout = max(
        60.0,
        min(
            3600.0,
            float(config.get("application_skeptic_timeout_s") or phase.base_timeout_s),
        ),
    )
    for shard in plan.get("shards", []):
        shard_ids = list(shard.get("work_item_ids") or [])
        if not pending.intersection(shard_ids):
            continue
        shard_id = str(shard["shard_id"])
        ordinal = int(shard_id.rsplit("-", 1)[-1])
        output_name = f"application_skeptic_assessments_{ordinal:04d}.json"
        assessor_id, invocation_id = _application_skeptic_assessor_identity(
            config, plan["work_plan_digest"], shard_id
        )
        loaded, invoked, shard_issues = (
            _execute_application_skeptic_provider_shard(
                workflow="application_skeptic",
                phase=phase,
                config=config,
                scratchpad=root,
                plan=plan,
                plan_name=APPLICATION_SKEPTIC_WORK_PLAN_FILE,
                shard=shard,
                output_name=output_name,
                assessor_id=assessor_id,
                assessor_invocation_id=invocation_id,
                effective_model=effective_model,
                timeout_seconds=int(timeout),
            )
        )
        model_was_invoked = model_was_invoked or invoked
        issues.extend(shard_issues)
        if loaded is not None:
            assessments.extend(
                row for row in loaded if row["work_item_id"] in pending
            )
            imported_assessment_outputs.append(output_name)

    (
        reconcile_contract,
        reconcile_launch,
        reconcile_execute,
        reconcile_arm_issues,
    ) = _arm_application_skeptic_io(
        scratchpad=root,
        config=config,
        phase=phase,
        work_unit_id="reconcile",
        actor="DRIVER",
        exact_inputs=tuple(sorted(set(imported_assessment_outputs))),
    )
    issues.extend(reconcile_arm_issues)

    registry_proposals: list[dict[str, Any]] = []
    closure_authority = _refresh_central_negative_closure_authority(root, issues)
    receipt = adjudicate_application_skeptic(
        plan,
        assessments,
        prior_receipt=prior,
        candidate_sink=registry_proposals.append,
        defer_missing=False,
        model_invoked=(
            model_was_invoked or bool((prior or {}).get("model_invoked"))
        ),
        closure_authority=closure_authority,
    )
    receipt = _attach_skeptic_provider_debt(receipt, issues)
    current_receipt = receipt
    preservation_input, preservation_eligible = (
        _prepare_positive_last_good_preservation(
            receipt,
            last_good_receipt,
            assessed_work_item_ids=[
                str(row.get("work_item_id") or "")
                for row in assessments
                if isinstance(row, Mapping)
            ],
        )
    )
    receipt, preserved_last_good = preserve_last_good_application_candidates(
        plan,
        current_receipt=(
            preservation_input if preservation_eligible else receipt
        ),
        last_good_receipt=last_good_receipt,
        current_context=preservation_context,
        last_good_delivery=last_good_delivery,
    )
    if preservation_eligible and not preserved_last_good:
        # Invalid or stale preservation authority cannot suppress the current
        # recall-positive policy fallback.
        receipt = current_receipt
    if preserved_last_good:
        issues.append(
            "application-skeptic last-good additive candidate delivery "
            "preserved after failed current reassessment"
        )
    if reconcile_execute:
        try:
            write_application_skeptic_receipt(root, receipt)
            write_application_skeptic_proposal_projection(
                root, receipt.get("registry_candidate_proposals", [])
            )
            projection_path = root / "application_skeptic_proposals.md"
            delivery = build_application_skeptic_delivery_binding(
                plan,
                receipt,
                context=preservation_context,
                proposal_projection_sha256=hashlib.sha256(
                    projection_path.read_bytes()
                ).hexdigest(),
                delivered_proposal_ids=sorted(
                    str(row.get("proposal_id") or "")
                    for row in receipt.get(
                        "registry_candidate_proposals", []
                    )
                    if isinstance(row, Mapping) and row.get("proposal_id")
                ),
            )
            _atomic_driver_json(
                root / _APPLICATION_SKEPTIC_DELIVERY_FILE, delivery
            )
            issues.extend(
                _commit_application_skeptic_io(
                    scratchpad=root,
                    config=config,
                    contract=reconcile_contract,
                    launch=reconcile_launch,
                )
            )
        except Exception as exc:
            issues.append(
                "registered proposal projection failed: "
                f"{type(exc).__name__}: {exc}"
            )
    if receipt.get("status") in {"COMPLETED_WITH_DEBT", "PARTIAL"}:
        issues.extend(
            str(issue.get("code") or issue)
            for issue in receipt.get("source_input_issues", [])
        )
        issues.extend(
            f"unresolved independent disposition {work_id}"
            for work_id in receipt.get("unresolved_work_item_ids", [])
        )
    return receipt, list(dict.fromkeys(issue for issue in issues if issue))


def _breadth_early_complete_ready(
    *,
    out_path: Path,
    expected_output: str,
    phase: Phase,
    last_growth_at: float | None,
    now: float,
    idle_grace_s: float = _EARLY_COMPLETE_IDLE_GRACE_SECONDS,
) -> tuple[bool, float]:
    """STEP 1D triple-gate for the disk-marker early-complete cutover.

    Returns ``(ready, idle_for_seconds)``. ``ready`` is True ONLY when ALL of:
    (1) the worker's own output exists with the PLAMEN_STATUS COMPLETE marker
        (``is_artifact_complete``),
    (2) the file's PLAMEN_ARTIFACT / EXPECTED_OUTPUT markers match THIS assigned
        row (``validate_breadth_artifact_ownership``) -- this matches on the
        worker's OWN markers, not a driver-side role-name guess, so it
        reconciles every ecosystem's role-name shapes generically, and
    (3) the worker has been disk-idle for at least ``idle_grace_s``.

    A missing/non-COMPLETE marker => not ready. An ownership mismatch => not
    ready. So it can never falsely complete an unfinished or mis-owned worker.
    Never raises.
    """
    try:
        complete = is_artifact_complete(
            out_path, max(phase.min_artifact_bytes, 500)
        )
    except Exception:
        complete = False
    if not complete:
        return False, 0.0
    try:
        owned, _own_reasons = validate_breadth_artifact_ownership(
            out_path, expected_output=expected_output
        )
    except Exception:
        owned = False
    if not owned:
        return False, 0.0
    anchor = last_growth_at if last_growth_at is not None else now
    idle_for = max(0.0, now - anchor)
    return (idle_for >= idle_grace_s), idle_for


def _run_single_breadth_worker_pty(
    *,
    job: dict[str, str],
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
    retry_reasons: list[str] | None = None,
    allowed_outputs: list[str] | None = None,
    rendered_prompt: str | None = None,
    inputs_prebound: bool = False,
) -> dict[str, Any]:
    output = job["output"]
    allowed_output_set = set(allowed_outputs or [output])
    if not inputs_prebound:
        fatal_binding_issues = _prepare_typed_model_worker_launch(
            phase=phase,
            config=config,
            scratchpad=scratchpad,
            project_root=project_root,
            agent_id=str(job.get("agent_id") or output),
            agent_role=str(job.get("role") or "") or None,
            output=output,
            timeout_s=timeout,
            work_category=str(job.get("category") or "*"),
            focus_area=str(job.get("focus_area") or job.get("focus") or ""),
            attempt=attempt,
        )
        if fatal_binding_issues:
            return {
                "output": output,
                "rc": -2,
                "status": "input_authority_debt",
                "reasons": fatal_binding_issues,
            }
    session_id = str(uuid.uuid4())
    prompt = rendered_prompt or _build_breadth_worker_prompt(
        job=job,
        scratchpad=scratchpad,
        project_root=project_root,
        config=config,
        attempt=attempt,
        retry_reasons=retry_reasons,
    )
    snap = scratchpad / (
        f"_prompt_breadth_worker_{Path(output).stem}.attempt{attempt}.md"
    )
    snap.write_text(prompt, encoding="utf-8", newline="\n")
    cmd = _build_fresh_session_cmd(base_cmd, session_id)
    cmd = _rewrite_argv_positional_prompt(cmd, snap)
    log_path = scratchpad / (
        f"_stdio_breadth_worker_{Path(output).stem}.attempt{attempt}.log"
    )
    known_stats: dict[str, tuple[int, int]] = {}
    try:
        for p in scratchpad.iterdir():
            if p.is_file() and not p.name.startswith("_"):
                try:
                    st = p.stat()
                    known_stats[p.name] = (st.st_size, st.st_mtime_ns)
                except OSError:
                    known_stats[p.name] = (0, 0)
    except Exception:
        known_stats = {}

    # STEP 1D disk-idle tracker: timestamp of the last observed growth/mtime
    # change in ANY tracked (non-underscore) scratchpad file. Mutable holder so
    # the poll closure can update it. ``None`` until first observed growth.
    _last_disk_growth_at: list[float | None] = [None]
    out_path = scratchpad / output

    def _worker_poll(_now: float, _state: Any) -> None:
        try:
            observed_growth = False
            for p in scratchpad.iterdir():
                if p.name.startswith("_") or not p.is_file():
                    continue
                known_names = set(known_stats)
                try:
                    st = p.stat()
                    sig = (st.st_size, st.st_mtime_ns)
                except OSError:
                    sig = (0, 0)
                old_sig = known_stats.get(p.name)
                known_stats[p.name] = sig
                if old_sig != sig:
                    observed_growth = True
                if _worker_artifact_name_allowed(p.name, allowed_output_set):
                    continue
                if old_sig == sig:
                    continue
                if _worker_artifact_is_benign_duplicate_copy(p.name, known_names):
                    moved = _quarantine_worker_duplicate_copy(
                        scratchpad=scratchpad,
                        path=p,
                        phase_name="breadth",
                        worker_output=output,
                    )
                    if moved is not None:
                        log.info(
                            "[breadth] worker %s quarantined benign duplicate "
                            "scratchpad copy: %s -> %s",
                            output,
                            p.name,
                            moved.relative_to(scratchpad).as_posix(),
                        )
                    continue
                log.error(
                    "[breadth] worker %s wrote or modified out-of-scope "
                    "artifact: %s",
                    output,
                    p.name,
                )
                raise _PtyStop(-4)

            if observed_growth:
                _last_disk_growth_at[0] = _now

            # STEP 1D: path-independent early-complete cutover. Anchor the idle
            # clock to now on the first poll where no prior growth was observed
            # (artifact already complete on disk before the first poll), so the
            # grace window is still honoured.
            if _last_disk_growth_at[0] is None:
                _last_disk_growth_at[0] = _now
            ready, idle_for = _breadth_early_complete_ready(
                out_path=out_path,
                expected_output=output,
                phase=phase,
                last_growth_at=_last_disk_growth_at[0],
                now=_now,
            )
            if ready:
                log.info(
                    "[breadth] worker %s early-complete cutover: "
                    "artifact present + COMPLETE marker + owned, "
                    "disk-idle for %ds",
                    output,
                    int(idle_for),
                )
                raise _PtyEarlyComplete()
        except _PtyStop:
            raise
        except Exception:
            pass

    with log_path.open("w", encoding="utf-8", errors="replace") as out:
        session = ClaudePtySession(
            cmd,
            cwd=project_root,
            env=env,
            session_id=session_id,
            prompt_path=snap,
            log_file=out,
        )
        _register_active_worker_session(session)
        try:
            out.write(f"CLAUDE_TRANSCRIPT={session.transcript_path}\n")
            out.flush()
            session.spawn()
            session.send_bootstrap()
            state = session.wait_for_turn_complete(
                timeout,
                quiescence_s=quiescence_s,
                on_poll=_worker_poll,
            )
            if state.rate_limited:
                # A transient 529/overloaded is provider-wide, NOT a 429
                # account/usage cap. It must NOT escalate to the phase-level
                # usage-cap pause that stops the whole worker pool — Claude
                # Code's own retry loop (exp backoff, up to 10x) usually
                # self-recovers it. Classify it as a retriable worker failure
                # so the gate re-spawns just this one worker. Mirrors the
                # single-subprocess overload path (detect_overloaded backoff).
                if getattr(state, "overloaded", False):
                    return {"output": output, "rc": 1, "status": "overloaded",
                            "reasons": ["transient 529 overloaded -- retriable"]}
                return {"output": output, "rc": 1, "status": "rate_limited"}
            status_rows = compute_breadth_row_statuses(scratchpad, phase)
            status = next(
                (r for r in status_rows if r.get("name") == output),
                {"status": "missing", "reasons": []},
            )
            ok = status.get("status") == "complete"
            reasons = list(status.get("reasons") or [])
            if ok:
                contract_issues = _record_typed_model_worker_artifact(
                    phase=phase, config=config, scratchpad=scratchpad,
                    project_root=project_root,
                    agent_id=str(job.get("agent_id") or output),
                    agent_role=str(job.get("role") or "") or None,
                    output=output, timeout_s=timeout,
                    work_category=str(job.get("category") or "*"),
                    focus_area=str(
                        job.get("focus_area") or job.get("focus") or ""
                    ),
                    attempt=attempt,
                )
                if contract_issues:
                    ok = False
                    reasons.extend(
                        f"typed artifact contract: {item}"
                        for item in contract_issues
                    )
            return {
                "output": output,
                "rc": 0 if ok else -2,
                "status": status.get("status") if ok else "incomplete",
                "reasons": reasons,
                "log": str(log_path),
            }
        except _PtyEarlyComplete:
            # Disk-marker early-complete cutover: resolve the row via the normal
            # status computation so it lands 'complete' and frees the slot
            # cleanly, rather than the 'containment' label.
            status_rows = compute_breadth_row_statuses(scratchpad, phase)
            status = next(
                (r for r in status_rows if r.get("name") == output),
                {"status": "missing", "reasons": []},
            )
            ok = status.get("status") == "complete"
            reasons = list(status.get("reasons") or [])
            if ok:
                contract_issues = _record_typed_model_worker_artifact(
                    phase=phase, config=config, scratchpad=scratchpad,
                    project_root=project_root,
                    agent_id=str(job.get("agent_id") or output),
                    agent_role=str(job.get("role") or "") or None,
                    output=output, timeout_s=timeout,
                    work_category=str(job.get("category") or "*"),
                    focus_area=str(
                        job.get("focus_area") or job.get("focus") or ""
                    ),
                    attempt=attempt,
                )
                if contract_issues:
                    ok = False
                    reasons.extend(
                        f"typed artifact contract: {item}"
                        for item in contract_issues
                    )
            return {
                "output": output,
                "rc": 0 if ok else -2,
                "status": status.get("status") if ok else "incomplete",
                "reasons": reasons,
                "log": str(log_path),
            }
        except _PtyStop as stop:
            return {
                "output": output,
                "rc": stop.rc,
                "status": "containment",
                "reasons": ["worker wrote protected out-of-scope artifact"],
                "log": str(log_path),
            }
        except Exception as exc:
            return {
                "output": output,
                "rc": EXIT_ERROR,
                "status": "error",
                "reasons": [str(exc)],
                "log": str(log_path),
            }
        finally:
            try:
                session.terminate(grace_s=_HALT_TERMINATE_GRACE_S)
            except Exception:
                pass
            finally:
                _unregister_active_worker_session(session)
            try:
                if session.transcript_path.exists():
                    out.write("\n\n# Claude session transcript tail\n")
                    with session.transcript_path.open("rb") as tf:
                        tf.seek(0, 2)
                        size = tf.tell()
                        tf.seek(max(0, size - 65536))
                        out.write(tf.read().decode("utf-8", errors="replace"))
                    out.flush()
            except Exception:
                pass


def _worker_artifact_name_allowed(name: str, allowed_outputs: set[str]) -> bool:
    """Return True for allowed final artifacts and their atomic-write temps."""
    if name in allowed_outputs:
        return True
    for output in allowed_outputs:
        if name.startswith(output + ".tmp"):
            return True
        if name.startswith(output + ".part"):
            return True
    return False


_WORKER_DUPLICATE_COPY_RE = re.compile(r"^(.+?)\s+\d+(\.[^./\\]+)$")


def _worker_duplicate_copy_base_name(name: str) -> str | None:
    """Return canonical sibling name for Claude-created ``foo 2.md`` copies."""
    match = _WORKER_DUPLICATE_COPY_RE.match(name)
    if not match:
        return None
    return f"{match.group(1)}{match.group(2)}"


def _worker_artifact_is_benign_duplicate_copy(
    name: str,
    known_names: set[str],
) -> bool:
    """Detect duplicate-copy scratchpad artifacts produced beside inputs.

    Claude occasionally creates files like ``meta_buffer 2.md`` when an input
    artifact already exists and the model attempts a write/copy despite the
    one-output worker contract. These are not consumed by gates and should not
    fail every concurrent worker that happens to observe the same stray file.
    """
    base = _worker_duplicate_copy_base_name(name)
    return bool(base and base in known_names)


def _quarantine_worker_duplicate_copy(
    *,
    scratchpad: Path,
    path: Path,
    phase_name: str,
    worker_output: str,
) -> Path | None:
    """Move a benign duplicate-copy artifact out of the live scratchpad."""
    try:
        if not path.exists() or not path.is_file():
            return None
        target_dir = scratchpad / "_overflow" / "worker_strays"
        target_dir.mkdir(parents=True, exist_ok=True)
        stem = Path(worker_output).stem
        stamp = int(time.time() * 1000)
        target = target_dir / f"{phase_name}_{stem}_{stamp}_{path.name}"
        n = 1
        while target.exists():
            target = target_dir / f"{phase_name}_{stem}_{stamp}_{n}_{path.name}"
            n += 1
        path.replace(target)
        return target
    except Exception:
        return None


def _snapshot_worker_input_artifacts(
    scratchpad: Path,
    output_names: set[str],
) -> dict[str, bytes]:
    """Capture pre-existing scratchpad inputs before a worker batch.

    Worker pools run multiple Claude PTYs against one scratchpad. A live poller
    cannot reliably attribute a pre-existing input artifact's mtime/content
    change to one worker, and killing the whole pool loses more audit signal
    than it protects. Snapshot inputs instead: worker outputs stay strictly
    gated, while accidental edits to prior-phase inputs are restored after the
    batch.
    """
    snapshot: dict[str, bytes] = {}
    try:
        for p in scratchpad.iterdir():
            if (
                not p.is_file()
                or p.name.startswith("_")
                or p.name.startswith(".")
                or p.name in output_names
            ):
                continue
            try:
                snapshot[p.name] = p.read_bytes()
            except OSError:
                continue
    except Exception:
        pass
    return snapshot


def _restore_worker_input_artifacts(
    scratchpad: Path,
    snapshot: dict[str, bytes],
) -> list[str]:
    """Restore worker-pool input artifacts that changed during the batch."""
    restored: list[str] = []
    for name, before in snapshot.items():
        p = scratchpad / name
        try:
            if not p.exists() or not p.is_file():
                continue
            try:
                current = p.read_bytes()
            except OSError:
                continue
            if current == before:
                continue
            tmp = p.with_name(
                f"{p.name}.restore.{os.getpid()}.{uuid.uuid4().hex[:12]}"
            )
            tmp.write_bytes(before)
            tmp.replace(p)
            restored.append(name)
        except Exception:
            continue
    return restored


_WORKER_POOL_HEARTBEAT_S = 300
_WORKER_POOL_UI_POLL_S = 0.10


def _format_worker_pool_progress_status(
    *,
    complete: int,
    total: int,
    active_outputs: list[str],
    queued: int,
    phase_label: str,
) -> str:
    active = max(0, len(active_outputs))
    parts = [
        f"worker pool: {active} running",
        f"{max(0, queued)} queued/missing",
    ]
    if active_outputs:
        names = ", ".join(
            Path(name).stem
            .removeprefix("analysis_")
            .removeprefix("depth_")
            for name in active_outputs[:3]
        )
        extra = f" +{len(active_outputs) - 3}" if len(active_outputs) > 3 else ""
        parts.append(f"active {names}{extra}")
    else:
        parts.append(f"{phase_label} scheduler polling")
    return "; ".join(parts)


def _breadth_worker_pool_progress_status(
    scratchpad: Path,
    phase: Phase,
    jobs: list[dict[str, str]],
    active_outputs: list[str],
) -> str:
    try:
        rows = compute_breadth_row_statuses(scratchpad, phase)
    except Exception:
        rows = []
    complete = sum(1 for r in rows if r.get("status") == "complete")
    queued = max(0, len(jobs) - complete - len(active_outputs))
    return _format_worker_pool_progress_status(
        complete=complete,
        total=len(jobs),
        active_outputs=active_outputs,
        queued=queued,
        phase_label="breadth",
    )


def _run_breadth_worker_pool_pty_core(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
) -> int:
    """Run breadth as bounded top-level Claude PTY workers, one per artifact.

    This is the unmodified baseline roster runner (Wave 0) — the M3 hard
    recall floor. See `_run_breadth_worker_pool_pty` below for the thin
    wave-gating wrapper; this function's body/behavior is byte-identical to
    pre-M3.
    """
    dispatch_plan = _breadth_dispatch_plan(
        scratchpad=scratchpad,
        project_root=project_root,
        config=config,
        attempt=attempt,
    )
    jobs = [dict(entry["job"]) for entry in dispatch_plan]
    if not jobs:
        log.warning("[breadth] worker-pool unavailable: no manifest jobs")
        return -2
    budget = int(config.get("pty_continuation_budget", 3))
    concurrency = min(_BREADTH_WORKER_CONCURRENCY, max(1, len(jobs)))
    retry_reasons_by_output: dict[str, list[str]] = {}
    pool_started = time.time()
    for pool_attempt in range(1, budget + 2):
        round_plan = _breadth_dispatch_plan(
            scratchpad=scratchpad,
            project_root=project_root,
            config=config,
            attempt=pool_attempt,
            retry_reasons_by_output=retry_reasons_by_output,
        )
        open_jobs = _breadth_open_jobs(scratchpad, phase, jobs)
        open_outputs = {str(job["output"]) for job in open_jobs}
        _write_breadth_dispatch_contract(
            scratchpad,
            config,
            "claude-pty",
            round_plan,
            dispatched_outputs=open_outputs,
        )
        if not open_jobs:
            passed, missing = gate_passes(scratchpad, project_root, phase)
            if passed:
                return 0
            log.warning(f"[breadth] worker-pool gate failed: {missing}")
            return -2
        if pool_attempt > budget + 1:
            break
        round_by_output = {
            str(entry["job"]["output"]): entry for entry in round_plan
        }
        log.info(
            f"[breadth] worker PTY pool attempt {pool_attempt}: "
            f"{len(open_jobs)} open row(s), concurrency={concurrency}"
        )
        pool_allowed_outputs = [str(job["output"]) for job in open_jobs]
        results: list[dict[str, Any]] = []
        runnable_jobs: list[dict[str, str]] = []
        for job in open_jobs:
            fatal_binding_issues = _prepare_typed_model_worker_launch(
                phase=phase,
                config=config,
                scratchpad=scratchpad,
                project_root=project_root,
                agent_id=str(job.get("agent_id") or job["output"]),
                agent_role=str(job.get("role") or "") or None,
                output=str(job["output"]),
                timeout_s=timeout,
                work_category=str(job.get("category") or "*"),
                focus_area=str(
                    job.get("focus_area") or job.get("focus") or ""
                ),
                attempt=pool_attempt,
            )
            if fatal_binding_issues:
                results.append({
                    "output": str(job["output"]),
                    "rc": -2,
                    "status": "input_authority_debt",
                    "reasons": fatal_binding_issues,
                })
            else:
                runnable_jobs.append(job)
        display.print_phase_heartbeat(
            "breadth",
            int(time.time() - pool_started),
            status=_breadth_worker_pool_progress_status(
                scratchpad,
                phase,
                jobs,
                [j["output"] for j in runnable_jobs[:concurrency]],
            ),
        )
        with _JoiningWorkerPool(
            max_workers=concurrency,
            thread_name_prefix="plamen-breadth-worker",
        ) as executor:
            fut_to_job = {
                executor.submit(
                    _run_single_breadth_worker_pty,
                    job=job,
                    scratchpad=scratchpad,
                    project_root=project_root,
                    config=config,
                    phase=phase,
                    base_cmd=base_cmd,
                    env=env,
                    timeout=timeout,
                    quiescence_s=quiescence_s,
                    attempt=pool_attempt,
                    retry_reasons=retry_reasons_by_output.get(job["output"]),
                    allowed_outputs=pool_allowed_outputs,
                    rendered_prompt=str(round_by_output[job["output"]]["prompt"]),
                    inputs_prebound=True,
                ): job
                for job in runnable_jobs
            }
            pending_futs: set[concurrent.futures.Future] = set(fut_to_job)
            last_progress = time.time()
            while pending_futs:
                done, pending_futs = concurrent.futures.wait(
                    pending_futs,
                    timeout=_WORKER_POOL_UI_POLL_S,
                    return_when=concurrent.futures.FIRST_COMPLETED,
                )
                now = time.time()
                elapsed = int(now - pool_started)
                display.spin(elapsed)
                if display.graceful_stop.requested:
                    _cancel_pending_worker_futures(pending_futs, executor)
                    raise _PtyStop(-3)
                for fut in done:
                    result = fut.result()
                    results.append(result)
                    output = result.get("output", "(unknown)")
                    status = result.get("status")
                    log.info(f"[breadth] worker {output}: {status}")
                    display.print_phase_heartbeat(
                        "breadth",
                        elapsed,
                        status=f"worker {output}: {status}",
                    )
                    if result.get("status") == "rate_limited":
                        log.warning(
                            "[breadth] worker %s hit rate limit; stopping "
                            "remaining workers and surfacing phase-level "
                            "rate-limit pause",
                            output,
                        )
                        _cancel_pending_worker_futures(pending_futs, executor)
                        return 1
                    last_progress = now
                if pending_futs and now - last_progress >= _WORKER_POOL_HEARTBEAT_S:
                    active_outputs = [
                        fut_to_job[fut]["output"]
                        for fut in pending_futs
                        if fut in fut_to_job
                    ][:concurrency]
                    display.print_phase_heartbeat(
                        "breadth",
                        elapsed,
                        status=_breadth_worker_pool_progress_status(
                            scratchpad,
                            phase,
                            jobs,
                            active_outputs,
                        ),
                    )
                    last_progress = now
        if any(r.get("status") == "rate_limited" for r in results):
            return 1
        if any(r.get("rc") == -4 for r in results):
            log.error("[breadth] worker-pool containment violation")
            return -4
        retry_reasons_by_output = {
            str(r.get("output")): [
                f"status={r.get('status')}",
                *[str(x) for x in (r.get("reasons") or [])],
            ]
            for r in results
            if r.get("status") != "complete"
        }
        passed, missing = gate_passes(scratchpad, project_root, phase)
        if passed:
            return 0
        log.info(
            f"[breadth] worker-pool attempt {pool_attempt} incomplete: {missing}"
        )
    log.warning("[breadth] worker-pool retry budget exhausted")
    return -2


# ===========================================================================
# Breadth Wave Gating (Wave-4 M3) — yield-gated ADDITIVE breadth waves
# ===========================================================================
#
# Baseline breadth (Wave 0, `_run_breadth_worker_pool_pty_core` above) is the
# HARD RECALL FLOOR and is completely unmodified by this section: it always
# runs in full regardless of yield. Everything below is strictly ADDITIVE and
# strictly opt-in (`breadth_wave_gating_enabled` config flag, default OFF, AND
# mode must be Thorough) — the default/off path never even evaluates a wave
# decision. See `_breadth_wave_gating_enabled`.
#
# FOLLOW-UP (flagged, intentionally not implemented here): wave jobs are run
# via a dedicated best-effort pool (`_breadth_run_wave_extension`) OUTSIDE the
# baseline roster's generic retry/gate loop (`_breadth_open_jobs` /
# `compute_breadth_row_statuses`), because that loop's completion tracking is
# keyed off `spawn_manifest.md` (or the JSON worker-pool contract as an
# EXCLUSIVE fallback only when the manifest is absent) — wave outputs are
# deliberately not manifest-declared, so folding them into that loop would
# either (a) require mutating the shared, heavily-tested
# `compute_breadth_row_statuses` completion-gating code (plamen_validators.py)
# to union contract-only outputs with manifest outputs, or (b) spin every
# wave job through the full retry budget every attempt because its status can
# never read "complete". Both are exactly the "reshaping the pool runner" /
# "half-landed spawn loop" risk this item calls out — so wave completion is
# instead judged independently and mechanically, straight off disk
# (`_breadth_wave_count_above_info`), never via that shared gate.

_BREADTH_WAVE_EXTRA_JOBS_PER_WAVE = 2
_BREADTH_WAVE_OUTPUT_RE = re.compile(r"^analysis_wave(\d+)_\d+\.md$")
_BREADTH_WAVE_SEVERITY_LINE_RE = re.compile(
    r"(?im)^\s*(?:[*_]{0,2})severity(?:[*_]{0,2})\s*:\s*([A-Za-z /]+)"
)


def _breadth_wave_gating_enabled(config: dict) -> bool:
    """M3: additive breadth waves are Thorough-only and strictly opt-in.

    Absent (or falsy) `breadth_wave_gating_enabled` -> disabled — the
    default/off path, byte-identical to pre-M3 behavior. Light/Core modes
    are NEVER wave-gated even if the flag is set (hard mode gate, matches
    the AUDIT MODES table: waves are a Thorough-only concept). The L1
    pipeline's breadth jobs use a different shape (layers/skills/difficulty,
    no `focus_area` roster to rotate) and are intentionally NOT wave-gated
    yet — flagged as a follow-up, not silently mis-handled.
    """
    if not config.get("breadth_wave_gating_enabled"):
        return False
    if str(config.get("mode", "core")).lower() != "thorough":
        return False
    if (config.get("pipeline") or "sc") == "l1":
        return False
    return True


def _breadth_wave_count_above_info(scratchpad: Path, outputs: list[str]) -> int:
    """Mechanically count above-Info findings across the given output files.

    Reuses `_iter_finding_blocks` (the same `## Finding [ID]` / `### Finding
    [ID]` parser `_compute_depth_confidence` uses) plus `try_normalize_severity`
    for the severity token on each block's `**Severity**:` line — no new
    finding format is invented, per the M3 mandate to reuse existing
    finding counters/parsers. A block with no recognizable severity line is
    conservatively NOT counted (never inflates yield on malformed output).
    """
    count = 0
    for name in outputs:
        try:
            text = (scratchpad / name).read_text(
                encoding="utf-8", errors="replace"
            )
        except Exception:
            continue
        for _finding_id, block in _iter_finding_blocks(text):
            sev_m = _BREADTH_WAVE_SEVERITY_LINE_RE.search(block)
            if not sev_m:
                continue
            norm = try_normalize_severity(sev_m.group(1))
            if norm and norm != "Informational":
                count += 1
    return count


def _breadth_wave_yield_threshold(prior_yields: list[int]) -> float:
    """Running-percentile (median) of prior wave yields. Empty -> 0.0."""
    if not prior_yields:
        return 0.0
    ordered = sorted(prior_yields)
    n = len(ordered)
    mid = n // 2
    if n % 2:
        return float(ordered[mid])
    return (ordered[mid - 1] + ordered[mid]) / 2.0


def _breadth_wave_should_spawn_next(
    *,
    prior_yields: list[int],
    this_wave_yield: int,
    waves_spawned_so_far: int,
    max_extra_waves: int = 2,
) -> tuple[bool, str]:
    """Decide whether to spawn one more additive wave.

    `this_wave_yield` is the most recently completed wave's mechanical
    above-Info finding count (wave 0's yield, the first time this is
    evaluated); `prior_yields` is every wave's yield strictly BEFORE that
    one. Spawn iff still productive (yield >= the running median of
    everything before it — a wave that is at least as productive as the
    series so far keeps the series going) AND the hard extra-wave cap has
    not been reached. A wave with zero yield never spawns a follow-up,
    regardless of history.
    """
    if waves_spawned_so_far >= max_extra_waves:
        return False, (
            f"hard wave cap reached ({waves_spawned_so_far}/{max_extra_waves})"
        )
    if this_wave_yield <= 0:
        return False, "zero-yield wave -- stopping additive spawn"
    if not prior_yields:
        return True, "first measured wave was productive -- sampling next wave"
    threshold = _breadth_wave_yield_threshold(prior_yields)
    if this_wave_yield >= threshold:
        return True, (
            f"yield {this_wave_yield} >= running median {threshold} -- continuing"
        )
    return False, (
        f"yield {this_wave_yield} < running median {threshold} -- stopping"
    )


def _breadth_wave_extra_jobs(
    baseline_jobs: list[dict[str, str]],
    wave_number: int,
) -> list[dict[str, str]]:
    """Build a small additive batch of breadth jobs for wave `wave_number`.

    Reuses the exact job-dict shape `_breadth_manifest_jobs` produces
    (agent_id/focus_area/output) so the existing worker spawn path (prompt
    builder, PTY runner) needs no changes to consume these jobs; only the
    focus areas are rotated (a fresh angle on the baseline roster, echoing
    the Phase 3b/3c re-scan convention of broader/overlapping scope) and
    output filenames are wave-namespaced (`analysis_wave{N}_{i}.md`) so they
    never collide with the baseline or an earlier wave's artifact.
    """
    if not baseline_jobs or wave_number < 1:
        return []
    focus_areas = [
        str(j.get("focus_area") or "") for j in baseline_jobs if j.get("focus_area")
    ]
    jobs: list[dict[str, str]] = []
    for i in range(1, _BREADTH_WAVE_EXTRA_JOBS_PER_WAVE + 1):
        rotated = (
            focus_areas[(i - 1) % len(focus_areas)] if focus_areas
            else "full codebase"
        )
        jobs.append({
            "agent_id": f"BW{wave_number}-{i}",
            "focus_area": (
                f"Wave {wave_number} additive re-scan (fresh angle on: "
                f"{rotated}) -- broader/overlapping scope, do not re-report "
                f"prior wave findings"
            ),
            "output": f"analysis_wave{wave_number}_{i}.md",
        })
    return jobs


def _breadth_wave_completed_extra_yields(
    scratchpad: Path, max_extra_waves: int
) -> list[int]:
    """Reconstruct per-wave yields for extra waves already run, from disk.

    Stateless by design (mirrors the driver's disk-gate recovery philosophy
    used throughout the pipeline): walks contiguous `analysis_wave{N}_*.md`
    files starting at N=1 and stops at the first gap, so a resumed/retried
    breadth phase re-derives exactly where the wave series left off without
    a separate state file.
    """
    by_wave: dict[int, list[str]] = {}
    for p in scratchpad.glob("analysis_wave*_*.md"):
        m = _BREADTH_WAVE_OUTPUT_RE.match(p.name)
        if not m:
            continue
        n = int(m.group(1))
        if 1 <= n <= max_extra_waves:
            by_wave.setdefault(n, []).append(p.name)
    yields: list[int] = []
    n = 1
    while n in by_wave:
        yields.append(
            _breadth_wave_count_above_info(scratchpad, sorted(by_wave[n]))
        )
        n += 1
    return yields


def _breadth_wave_decide(
    scratchpad: Path,
    config: dict,
    baseline_jobs: list[dict[str, str]],
    max_extra_waves: int = 2,
) -> tuple[int, int | None, list[dict[str, str]], str]:
    """Shared decision core for `_breadth_wave_plan` and live wave execution.

    Returns ``(waves_completed, next_wave_number_or_None, next_wave_jobs,
    reason)``. ``next_wave_jobs`` is ``[]`` when no further wave is
    warranted (cap reached or yield fell off); ``next_wave_number`` is
    ``None`` in that case.
    """
    extra_yields = _breadth_wave_completed_extra_yields(
        scratchpad, max_extra_waves
    )
    waves_completed = len(extra_yields)
    if waves_completed >= max_extra_waves:
        return waves_completed, None, [], (
            f"hard wave cap reached ({waves_completed}/{max_extra_waves})"
        )
    baseline_yield = _breadth_wave_count_above_info(
        scratchpad, [str(j["output"]) for j in baseline_jobs]
    )
    full_yields = [baseline_yield] + extra_yields
    this_wave_yield = full_yields[-1]
    prior_yields = full_yields[:-1]
    should_spawn, reason = _breadth_wave_should_spawn_next(
        prior_yields=prior_yields,
        this_wave_yield=this_wave_yield,
        waves_spawned_so_far=waves_completed,
        max_extra_waves=max_extra_waves,
    )
    if not should_spawn:
        return waves_completed, None, [], reason
    next_wave_number = waves_completed + 1
    return (
        waves_completed,
        next_wave_number,
        _breadth_wave_extra_jobs(baseline_jobs, next_wave_number),
        reason,
    )


def _breadth_wave_plan(
    scratchpad: Path,
    config: dict,
    baseline_jobs: list[dict[str, str]],
    max_extra_waves: int = 2,
) -> list[dict[str, str]]:
    """Return the additive-wave job list for THIS breadth planning check.

    HARD RECALL FLOOR: ``baseline_jobs`` (Wave 0) is always the head of the
    returned list, unmodified — this function only ever APPENDS, never
    removes or reorders baseline entries. Returns ``baseline_jobs`` itself
    (same object, byte-identical) when the M3 feature is off, the mode
    isn't Thorough, or the pipeline is L1 — the default/off path.
    Reconstructs wave state from disk (see `_breadth_wave_completed_extra_yields`)
    so replanning is idempotent and safe to call repeatedly / after a resume.
    """
    if not baseline_jobs or not _breadth_wave_gating_enabled(config):
        return baseline_jobs
    jobs = list(baseline_jobs)
    waves_completed, next_wave_number, next_jobs, reason = _breadth_wave_decide(
        scratchpad, config, baseline_jobs, max_extra_waves
    )
    for n in range(1, waves_completed + 1):
        jobs.extend(_breadth_wave_extra_jobs(baseline_jobs, n))
    log.info(
        f"[breadth] wave gating: {waves_completed} extra wave(s) completed -> "
        f"{'SPAWN wave ' + str(next_wave_number) if next_jobs else 'STOP'} "
        f"({reason})"
    )
    if next_jobs:
        jobs.extend(next_jobs)
    return jobs


def _breadth_run_wave_extension(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    baseline_jobs: list[dict[str, str]],
    max_extra_waves: int = 2,
) -> None:
    """M3 live wiring: run yield-gated additive breadth waves AFTER the
    baseline roster (the hard recall floor) has already gate-passed.

    Best-effort and strictly additive: never raises, never influences the
    caller's return code — a wave that fails to spawn, times out, or writes
    a low-yield artifact simply stops the series (see
    `_breadth_wave_should_spawn_next`); it can never fail the phase, because
    the phase already succeeded on the baseline roster before this runs.
    Wave-job completion is judged by this function's OWN mechanical finding
    count (`_breadth_wave_count_above_info`), never via
    `compute_breadth_row_statuses` — see the module note above this section
    for why wave outputs are intentionally not manifest-declared.
    """
    if not _breadth_wave_gating_enabled(config):
        return
    try:
        for _round in range(max_extra_waves):
            _waves_completed, wave_number, wave_jobs, reason = (
                _breadth_wave_decide(
                    scratchpad, config, baseline_jobs, max_extra_waves
                )
            )
            if not wave_jobs:
                log.info(f"[breadth] wave extension: stopping ({reason})")
                break
            log.info(
                f"[breadth] wave extension: spawning wave {wave_number} "
                f"({len(wave_jobs)} job(s)) -- {reason}"
            )
            runnable_wave_jobs: list[dict[str, str]] = []
            for job in wave_jobs:
                fatal_binding_issues = _prepare_typed_model_worker_launch(
                    phase=phase,
                    config=config,
                    scratchpad=scratchpad,
                    project_root=project_root,
                    agent_id=str(job.get("agent_id") or job["output"]),
                    output=str(job["output"]),
                    timeout_s=timeout,
                )
                if not fatal_binding_issues:
                    runnable_wave_jobs.append(job)
            if not runnable_wave_jobs:
                log.warning(
                    "[breadth] wave extension: no rows had stable prelaunch inputs"
                )
                break
            concurrency = min(
                _BREADTH_WORKER_CONCURRENCY, max(1, len(runnable_wave_jobs))
            )
            with _JoiningWorkerPool(
                max_workers=concurrency,
                thread_name_prefix="plamen-breadth-wave-worker",
            ) as executor:
                futs = [
                    executor.submit(
                        _run_single_breadth_worker_pty,
                        job=job,
                        scratchpad=scratchpad,
                        project_root=project_root,
                        config=config,
                        phase=phase,
                        base_cmd=base_cmd,
                        env=env,
                        timeout=timeout,
                        quiescence_s=quiescence_s,
                        attempt=1,
                        retry_reasons=None,
                        allowed_outputs=[j["output"] for j in wave_jobs],
                        inputs_prebound=True,
                    )
                    for job in runnable_wave_jobs
                ]
                for fut in concurrent.futures.as_completed(futs):
                    try:
                        result = fut.result()
                        log.info(
                            f"[breadth] wave worker {result.get('output')}: "
                            f"{result.get('status')}"
                        )
                    except Exception as exc:
                        log.warning(f"[breadth] wave worker failed: {exc!r}")
    except Exception as exc:
        log.warning(
            f"[breadth] wave extension aborted (best-effort, non-fatal): "
            f"{exc!r}"
        )


def _run_breadth_worker_pool_pty(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
) -> int:
    """Run the baseline breadth roster, then (opt-in, Thorough-only) run
    best-effort additive yield-gated waves on top of it.

    DEFAULT/OFF PATH IS BYTE-IDENTICAL to `_run_breadth_worker_pool_pty_core`:
    when `breadth_wave_gating_enabled` is unset/false (or mode isn't
    Thorough, or the pipeline is L1), this wrapper does nothing but forward
    the core call's return code unchanged.
    """
    rc = _run_breadth_worker_pool_pty_core(
        scratchpad=scratchpad,
        project_root=project_root,
        config=config,
        phase=phase,
        base_cmd=base_cmd,
        env=env,
        timeout=timeout,
        quiescence_s=quiescence_s,
        attempt=attempt,
    )
    if rc == 0 and _breadth_wave_gating_enabled(config):
        baseline_jobs = _breadth_worker_jobs(scratchpad, config)
        _breadth_run_wave_extension(
            scratchpad=scratchpad,
            project_root=project_root,
            config=config,
            phase=phase,
            base_cmd=base_cmd,
            env=env,
            timeout=timeout,
            quiescence_s=quiescence_s,
            baseline_jobs=baseline_jobs,
        )
    return rc


# ===========================================================================
# Python-scheduled rescan worker PTYs
# ===========================================================================

_RESCAN_WORKER_CONCURRENCY = 3


def _rescan_worker_jobs(scratchpad: Path) -> list[dict[str, Any]]:
    manifest = scratchpad / "rescan_manifest.md"
    if not manifest.exists():
        return []
    try:
        declared = _parse_rescan_manifest_files(
            manifest.read_text(encoding="utf-8", errors="replace")
        )
    except Exception:
        return []
    broad_names = [name for name in declared if name.startswith("analysis_rescan_")]
    broad_count = len(broad_names)
    jobs: list[dict[str, Any]] = []
    rescan_i = 0
    per_i = 0
    for name in declared:
        if name.startswith("analysis_percontract_"):
            per_i += 1
            agent_id = f"PC{per_i}"
            cluster = re.sub(
                r"^analysis_percontract_|\.md$", "", name, flags=re.IGNORECASE
            )
            focus = (
                "Per-contract/cluster rescan for the exact manifest scope "
                f"`{cluster}`; apply the full localized RS-PC operator"
            )
            methodology_steps = ["RS-X", "RS-PC"]
        else:
            rescan_i += 1
            agent_id = f"R{rescan_i}"
            if broad_count <= 2:
                partitions = {
                    1: (
                        ["RS-X", "RS-0", "RS-1", "RS-2", "RS-5"],
                        "under-explored cross-function state, asymmetric branch, "
                        "and time/lifecycle surfaces",
                    ),
                    2: (
                        ["RS-X", "RS-0", "RS-3", "RS-4"],
                        "under-explored paired-parameter/encoding and economic "
                        "edge-condition surfaces",
                    ),
                }
            else:
                partitions = {
                    1: (
                        ["RS-X", "RS-0", "RS-1", "RS-5"],
                        "under-explored cross-function state and time/lifecycle surfaces",
                    ),
                    2: (
                        ["RS-X", "RS-0", "RS-2", "RS-3"],
                        "under-explored asymmetric and paired-parameter/encoding surfaces",
                    ),
                    3: (
                        ["RS-X", "RS-0", "RS-4"],
                        "under-explored economic and boundary-condition surfaces",
                    ),
                }
            methodology_steps, focus = partitions.get(
                rescan_i,
                (["RS-X", "RS-0", "RS-1", "RS-2", "RS-3", "RS-4", "RS-5"],
                 "independent under-explored-surface cross-check"),
            )
        jobs.append({
            "agent_id": agent_id,
            "focus_area": focus,
            "output": name,
            "methodology_steps": methodology_steps,
        })
    return jobs


def _rescan_output_complete(
    scratchpad: Path,
    phase: Phase,
    output: str,
) -> bool:
    p = scratchpad / output
    try:
        if not p.exists() or p.stat().st_size < max(phase.min_artifact_bytes, 1000):
            return False
        text = p.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    markers = dict(
        (m.group(1).strip().upper(), m.group(2).strip().upper())
        for m in re.finditer(r"<!--\s*PLAMEN_([A-Z_]+):\s*([^>]+?)\s*-->", text)
    )
    if markers and markers.get("STATUS") != "COMPLETE":
        return False
    ok, _reasons = _structural_completeness_ok(
        p,
        required_headings=(),
        placeholder_strings=("TODO", "FILL_ME", "<placeholder>"),
    )
    return ok


def _rescan_open_jobs(
    scratchpad: Path,
    phase: Phase,
    jobs: list[dict[str, str]],
) -> list[dict[str, str]]:
    return [
        job for job in jobs
        if not _rescan_output_complete(scratchpad, phase, job["output"])
    ]


def _should_use_rescan_worker_pool(config: dict, scratchpad: Path) -> bool:
    """Use driver-owned workers when a rescan manifest declares exact rows.

    ``rescan_prepare`` now constructs the manifest mechanically before this
    phase.  Therefore Claude PTY, Claude headless, and Codex can all consume
    the same exact row plan; transport is not a reason to fall back to an
    untyped monolithic coordinator.
    """
    jobs = _rescan_worker_jobs(scratchpad)
    if not jobs:
        return False
    try:
        phase = next(p for p in SC_PHASES if p.name == "rescan")
        missing = _rescan_manifest_exact_missing(scratchpad, phase)
    except Exception:
        missing = None
    if missing and any("rescan_manifest.md" in str(item) for item in missing):
        # Manifest shape itself is invalid (for example no per-contract row).
        # Let the canonical rescan coordinator rewrite the manifest instead of
        # trapping the audit in a worker pool that can only repair declared rows.
        return False
    return True


def _build_rescan_worker_prompt(
    *,
    job: dict[str, str],
    scratchpad: Path,
    project_root: str,
    config: dict,
    attempt: int,
    retry_reasons: list[str] | None = None,
    methodology_descriptors: list[dict[str, Any]] | None = None,
    dispatch_contract_sha256: str | None = None,
) -> str:
    output = job["output"]
    agent_id = job["agent_id"]
    focus = job["focus_area"]
    methodology_path = (
        plamen_home() / "prompts" / "shared" / "v2" / "phase3b-rescan.md"
    )
    finding_format_path = plamen_home() / "rules" / "finding-output-format.md"
    methodology_projection = _render_bound_methodology_projection(
        methodology_path,
        title="rescan worker execution procedure projection v1",
        expected_sha256=_BOUND_RESCAN_METHODOLOGY_SOURCE_SHA256["execution"],
        effective_text=_SC_RESCAN_WORKER_EXECUTION_PROJECTION,
    )
    finding_format_projection = _render_bound_methodology_projection(
        finding_format_path,
        title="finding output format",
        expected_sha256=_BOUND_RESCAN_METHODOLOGY_SOURCE_SHA256["finding_format"],
    )
    methodology_projection_slot = "<!-- PLAMEN_BOUND_RESCAN_PROCEDURE_SLOT -->"
    finding_format_projection_slot = "<!-- PLAMEN_BOUND_RESCAN_FINDING_FORMAT_SLOT -->"
    if methodology_descriptors is None:
        methodology_descriptors = [_rescan_methodology_descriptor(job)]
    contract_entry = {
        "worker_id": str(agent_id),
        "output": str(output),
        "methodologies": list(methodology_descriptors),
    }
    dispatch_contract_sha256 = (
        dispatch_contract_sha256
        or worker_dispatch_contract_sha256("rescan", contract_entry)
    )
    dispatch_markers = worker_dispatch_markers(
        "rescan", str(agent_id), str(output), dispatch_contract_sha256
    )
    dispatch_marker_contract = "`\n   `".join(dispatch_markers.splitlines())
    methodology_block = _skill_dispatch_prompt_block(
        methodology_descriptors, agent_kind="rescan"
    )
    obligations = [
        f"`{item['skill']}` / `{step_id}`"
        for item in methodology_descriptors
        for step_id in item["top_level_checklist_step_ids"]
    ]
    work_category = (
        "per_contract"
        if str(output).startswith("analysis_percontract_")
        else "rescan"
    )
    finding_id_prefix = (
        str(agent_id)
        if work_category == "per_contract"
        else "RS" + re.sub(r"\D+", "", str(agent_id))
    )
    registered_inputs = _typed_worker_registered_input_paths(
        phase_name="rescan",
        scratchpad=Path(scratchpad),
        config=config,
        agent_id=str(agent_id),
        agent_role=str(job.get("role") or "rescan"),
        output=str(output),
        work_category=work_category,
        focus_area=str(focus),
        attempt=attempt,
    )
    evidence_roster = "\n".join(
        f"- `{scratchpad.as_posix()}/{name}`"
        for name in registered_inputs
    )
    retry_block = ""
    if retry_reasons:
        retry_block = (
            "\n## Previous Gate Failure\n\n"
            + "\n".join(f"- {r}" for r in retry_reasons)
            + "\n"
        )
    prompt = f"""# RESCAN ROW WORKER

You are a single rescan worker launched directly by the Python Plamen driver.
There is no Claude phase coordinator for this repair attempt. Your job is to
produce exactly one rescan artifact from the existing rescan manifest.

## Assignment

- PROJECT_ROOT: `{project_root}`
- SCRATCHPAD: `{scratchpad.as_posix()}`
- LANGUAGE: `{config.get('language', 'unknown')}`
- MODE: `{config.get('mode', 'unknown')}`
- PIPELINE: `{config.get('pipeline', 'sc')}`
- SUBSYSTEM_SCOPE: `{config.get('subsystem_scope') or '(none)'}`
- SCOPE_FILE: `{config.get('scope_file') or '(none)'}`
- SCOPE_NOTES: `{config.get('scope_notes') or '(none)'}`
- Agent ID: `{agent_id}`
- Focus area: `{focus}`
- Output file: `{output}`
- Attempt: `{attempt}`
{retry_block}
## Finding Identity Contract

Every finding heading in this artifact MUST use `[{finding_id_prefix}-<N>]`,
where N is a positive decimal integer starting at 1 (for example
`[{finding_id_prefix}-1]`). Do not use the dispatch worker label `{agent_id}`
as the finding prefix when it differs from `{finding_id_prefix}`. This exact
producer-local namespace is validated before inventory.

## Logical Output Contract

The sole logical output is `{output}`. Do not write the canonical scratchpad
path for this artifact: it is read-only during the transaction. The final
`Runtime output routing (supervisor authority)` block supplies the one exact
attempt-owned filesystem destination you may Write/Edit. Use that destination
verbatim even if an earlier methodology example refers to a canonical path.

Do not infer, invent, or create any other output file. Do not update
`rescan_manifest.md` or any other agent's output. A denied tool call invalidates
the whole attempt even when later analysis is complete, so do not probe or
write a different path first.

## Methodology

The rescan execution procedure and finding format are projected below as
content-bound prompt inputs. Do not attempt to read their installed source
paths. You are already the worker; do not spawn Task/Agent subagents or follow
coordinator instructions. Do not proceed outside this assigned worker contract.
{methodology_block}
{methodology_projection_slot}
{finding_format_projection_slot}

Read `{scratchpad.as_posix()}/rescan_manifest.md` to understand why this exact
output was declared. Apply the bound finding format above. The following finite
evidence roster is the complete scratchpad read authority for this worker; read
only the entries relevant to the assigned focus and do not search, glob, list,
or enumerate the scratchpad root:

{evidence_roster}

When searching prior evidence, invoke Grep with `path` equal to one exact file
from that roster. Never Grep the scratchpad directory, PROJECT_ROOT, `.`, an
omitted path, or a parent directory to search several inputs at once. Search
each explicitly registered file separately; a directory-wide search is denied
and invalidates otherwise valid staged output.

You may inspect in-scope source files under PROJECT_ROOT. Do not read another
rescan worker's output unless it is explicitly listed above as prior breadth
evidence. Do not infer additional scratchpad inputs.
Do not proceed outside this assigned worker contract.

## Required File Contract

The output file must:

1. Start with these markers:
   `{dispatch_marker_contract}`
   `<!-- PLAMEN_ARTIFACT: {output} -->`
   `<!-- PLAMEN_OWNER: {agent_id} -->`
   `<!-- PLAMEN_STATUS: IN_PROGRESS -->`
   `<!-- PLAMEN_PHASE: rescan -->`
   `<!-- PLAMEN_VERSION: 1 -->`
   `<!-- AGENT_ROW: {agent_id} -->`
   `<!-- EXPECTED_OUTPUT: {output} -->`
2. Contain substantive rescan analysis for the declared focus.
3. Include either real `## Finding [` / `### Finding [` blocks or a
   `## No Findings` rationale.
4. End with a final `<!-- PLAMEN_STATUS: COMPLETE -->` marker only after the
   file is fully written and verified on disk.
5. Include exactly one `## Step Execution Trace` immediately before the final
   COMPLETE marker, with authoritative JSON between these exact sentinels:

   `{TRACE_JSON_BEGIN}`
   `{{"schema_version":1,"rows":[{{"skill":"...","step":"...","executed":"yes|partial|no|unknown","evidence":"relative/source.ext:L42","result":"step-specific result"}}]}}`
   `{TRACE_JSON_END}`

   Emit exactly one five-string-field row for every dispatched pair:
   {', '.join(obligations)}. Preserve step IDs exactly. `executed=yes` requires
   step-specific source evidence. The trace is producer attestation, never
   semantic proof; SAFE/no-finding/N/A cannot close its own obligation.

SCOPE: Write ONLY to your assigned output file. Do NOT read or write other
agents' output files. Do NOT continue after the assigned file is complete.
Return your findings and stop.

When done, return exactly one line:

`DONE: {output} complete`
"""
    rendered = _render_runtime_placeholders(prompt, config)
    for slot, projection in (
        (methodology_projection_slot, methodology_projection),
        (finding_format_projection_slot, finding_format_projection),
    ):
        if rendered.count(slot) != 1 or slot in projection:
            raise ValueError("bound rescan methodology projection slot drifted")
        rendered = rendered.replace(slot, projection)
    return _compile_typed_worker_prompt(
        rendered,
        config=config,
        phase_name="rescan",
        agent_id=str(agent_id),
        agent_role=str(job.get("role") or "rescan"),
        output=str(output),
        work_category=work_category,
        focus_area=str(focus),
        exact_inputs=registered_inputs,
        attempt=attempt,
    )


def _rescan_methodology_descriptor(job: dict[str, Any]) -> dict[str, Any]:
    """Bind one rescan row to exact bytes and an explicit step partition."""
    path = plamen_home() / "prompts" / "shared" / "v2" / "phase3b-rescan.md"
    return {
        "skill": "RESCAN_METHOD",
        "path": path.resolve().as_posix(),
        "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
        "projection_kind": "DRIVER_RENDERED_EXACT_SECTION",
        "projection_sha256": hashlib.sha256(
            _SC_RESCAN_WORKER_EXECUTION_PROJECTION.encode("utf-8")
        ).hexdigest(),
        "top_level_checklist_step_ids": list(job.get("methodology_steps") or []),
    }


def _rescan_dispatch_plan(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    attempt: int,
    jobs: list[dict[str, Any]] | None = None,
    retry_reasons_by_output: dict[str, list[str]] | None = None,
) -> list[dict[str, Any]]:
    """Render the canonical backend-neutral prompt for every rescan row."""
    scheduled = list(jobs) if jobs is not None else _rescan_worker_jobs(scratchpad)
    reasons = retry_reasons_by_output or {}
    plan: list[dict[str, Any]] = []
    for job in scheduled:
        methodologies = [_rescan_methodology_descriptor(job)]
        contract_entry = {
            "worker_id": str(job.get("agent_id") or ""),
            "output": str(job.get("output") or ""),
            "methodologies": methodologies,
        }
        contract_sha = worker_dispatch_contract_sha256("rescan", contract_entry)
        prompt = _build_rescan_worker_prompt(
            job=job,
            scratchpad=scratchpad,
            project_root=project_root,
            config=config,
            attempt=attempt,
            retry_reasons=reasons.get(str(job.get("output") or "")),
            methodology_descriptors=methodologies,
            dispatch_contract_sha256=contract_sha,
        )
        plan.append({
            "job": job,
            "prompt": prompt,
            "prompt_sha256": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
            "methodology_dispatch": methodologies,
            "dispatch_contract_sha256": contract_sha,
        })
    return plan


def _write_rescan_dispatch_contract(
    scratchpad: Path,
    config: dict,
    backend: str,
    plan: list[dict[str, Any]],
    dispatched_outputs: set[str] | None = None,
) -> None:
    """Persist actual rescan launches while preserving completed retry rows."""
    planned: dict[str, dict[str, Any]] = {}
    jobs: list[dict[str, Any]] = []
    for item in plan:
        job = dict(item["job"])
        jobs.append({**job, "prompt_sha256": item["prompt_sha256"]})
        output = str(job.get("output") or "")
        planned[output] = {
            "worker_id": str(job.get("agent_id") or ""),
            "output": output,
            "prompt_sha256": str(item.get("prompt_sha256") or ""),
            "prompt_snapshot_required": True,
            "prompt_snapshot_glob": "_prompt_rescan_worker_*.attempt*.md",
            "methodologies": list(item.get("methodology_dispatch") or []),
            "dispatch_contract_sha256": str(
                item.get("dispatch_contract_sha256") or ""
            ),
        }
    selected = (
        set(planned) if dispatched_outputs is None
        else {str(output) for output in dispatched_outputs}
    )
    existing: dict[str, dict[str, Any]] = {}
    try:
        payload = json.loads(
            (scratchpad / "skill_dispatch.json").read_text(encoding="utf-8")
        )
        for entry in payload.get("phases", {}).get("rescan", {}).get("entries", []):
            if isinstance(entry, dict) and entry.get("output"):
                existing[str(entry["output"])] = entry
    except (OSError, UnicodeError, json.JSONDecodeError, TypeError, AttributeError):
        pass
    entries: list[dict[str, Any]] = []
    for output in [str(job.get("output") or "") for job in jobs]:
        if output in selected:
            entries.append(planned[output])
        elif output in existing:
            entries.append(existing[output])
        else:
            unobserved = dict(planned[output])
            unobserved["prompt_sha256"] = "0" * 64
            unobserved["launch_state"] = "NOT_OBSERVED"
            entries.append(unobserved)
    phase_dispatch = write_phase_dispatch(
        scratchpad, phase="rescan", backend=backend, entries=entries
    )
    receipt = {
        "version": 2,
        "phase": "rescan",
        "backend": backend,
        "pipeline": config.get("pipeline", "sc"),
        "mode": config.get("mode", "thorough"),
        "outputs": [str(job.get("output") or "") for job in jobs],
        "jobs": jobs,
        "skill_dispatch_file": "skill_dispatch.json",
        "skill_dispatch_sha256": phase_dispatch["dispatch_sha256"],
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    try:
        (scratchpad / "_rescan_worker_pool_contract.json").write_text(
            json.dumps(receipt, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
    except Exception as exc:
        log.warning("[rescan] could not write dispatch contract: %s", exc)


def _run_single_rescan_worker_pty(
    *,
    job: dict[str, Any],
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
    retry_reasons: list[str] | None = None,
    allowed_outputs: list[str] | None = None,
    rendered_prompt: str | None = None,
    inputs_prebound: bool = False,
) -> dict[str, Any]:
    output = job["output"]
    allowed_output_set = set(allowed_outputs or [output])
    if not inputs_prebound:
        fatal_binding_issues = _prepare_typed_model_worker_launch(
            phase=phase,
            config=config,
            scratchpad=scratchpad,
            project_root=project_root,
            agent_id=str(job.get("agent_id") or output),
            agent_role=str(job.get("role") or "") or None,
            output=output,
            timeout_s=timeout,
            work_category=str(job.get("category") or "rescan"),
            focus_area=str(job.get("focus_area") or job.get("focus") or ""),
            attempt=attempt,
        )
        if fatal_binding_issues:
            return {
                "output": output,
                "rc": -2,
                "status": "input_authority_debt",
                "reasons": fatal_binding_issues,
            }
    session_id = str(uuid.uuid4())
    prompt = rendered_prompt or _build_rescan_worker_prompt(
        job=job, scratchpad=scratchpad, project_root=project_root,
        config=config, attempt=attempt, retry_reasons=retry_reasons,
    )
    snap = scratchpad / f"_prompt_rescan_worker_{Path(output).stem}.attempt{attempt}.md"
    snap.write_text(prompt, encoding="utf-8", newline="\n")
    cmd = _build_fresh_session_cmd(base_cmd, session_id)
    cmd = _rewrite_argv_positional_prompt(cmd, snap)
    log_path = scratchpad / f"_stdio_rescan_worker_{Path(output).stem}.attempt{attempt}.log"
    known_stats: dict[str, tuple[int, int]] = {}
    try:
        for p in scratchpad.iterdir():
            if p.is_file() and not p.name.startswith("_"):
                try:
                    st = p.stat()
                    known_stats[p.name] = (st.st_size, st.st_mtime_ns)
                except OSError:
                    known_stats[p.name] = (0, 0)
    except Exception:
        known_stats = {}

    def _worker_poll(_now: float, _state: Any) -> None:
        try:
            for p in scratchpad.iterdir():
                if p.name.startswith("_") or not p.is_file():
                    continue
                known_names = set(known_stats)
                try:
                    st = p.stat()
                    sig = (st.st_size, st.st_mtime_ns)
                except OSError:
                    sig = (0, 0)
                old_sig = known_stats.get(p.name)
                known_stats[p.name] = sig
                if _worker_artifact_name_allowed(p.name, allowed_output_set):
                    continue
                if old_sig == sig:
                    continue
                if _worker_artifact_is_benign_duplicate_copy(p.name, known_names):
                    moved = _quarantine_worker_duplicate_copy(
                        scratchpad=scratchpad,
                        path=p,
                        phase_name="rescan",
                        worker_output=output,
                    )
                    if moved is not None:
                        log.info(
                            "[rescan] worker %s quarantined benign duplicate "
                            "scratchpad copy: %s -> %s",
                            output,
                            p.name,
                            moved.relative_to(scratchpad).as_posix(),
                        )
                    continue
                log.error(
                    "[rescan] worker %s wrote or modified out-of-scope artifact: %s",
                    output,
                    p.name,
                )
                raise _PtyStop(-4)
        except _PtyStop:
            raise
        except Exception:
            pass

    with log_path.open("w", encoding="utf-8", errors="replace") as out:
        session = ClaudePtySession(
            cmd,
            cwd=project_root,
            env=env,
            session_id=session_id,
            prompt_path=snap,
            log_file=out,
        )
        _register_active_worker_session(session)
        try:
            out.write(f"CLAUDE_TRANSCRIPT={session.transcript_path}\n")
            out.flush()
            session.spawn()
            session.send_bootstrap()
            state = session.wait_for_turn_complete(
                timeout,
                quiescence_s=quiescence_s,
                on_poll=_worker_poll,
            )
            if state.rate_limited:
                # A transient 529/overloaded is provider-wide, NOT a 429
                # account/usage cap. It must NOT escalate to the phase-level
                # usage-cap pause that stops the whole worker pool — Claude
                # Code's own retry loop (exp backoff, up to 10x) usually
                # self-recovers it. Classify it as a retriable worker failure
                # so the gate re-spawns just this one worker. Mirrors the
                # single-subprocess overload path (detect_overloaded backoff).
                if getattr(state, "overloaded", False):
                    return {"output": output, "rc": 1, "status": "overloaded",
                            "reasons": ["transient 529 overloaded -- retriable"]}
                return {"output": output, "rc": 1, "status": "rate_limited"}
            ok = _rescan_output_complete(scratchpad, phase, output)
            contract_issues: list[str] = []
            if ok:
                contract_issues = _record_typed_model_worker_artifact(
                    phase=phase,
                    config=config,
                    scratchpad=scratchpad,
                    project_root=project_root,
                    agent_id=str(job.get("agent_id") or output),
                    agent_role=str(job.get("role") or "") or None,
                    output=output,
                    timeout_s=timeout,
                    work_category=str(job.get("category") or "rescan"),
                    focus_area=str(
                        job.get("focus_area") or job.get("focus") or ""
                    ),
                    attempt=attempt,
                )
                if contract_issues:
                    ok = False
            return {
                "output": output,
                "rc": 0 if ok else -2,
                "status": "complete" if ok else "incomplete",
                "reasons": (
                    [] if ok else (
                        [f"typed artifact contract: {item}" for item in contract_issues]
                        if contract_issues
                        else ["missing or below rescan size floor"]
                    )
                ),
                "log": str(log_path),
            }
        except _PtyStop as stop:
            return {
                "output": output,
                "rc": stop.rc,
                "status": "containment",
                "reasons": ["worker wrote protected out-of-scope artifact"],
                "log": str(log_path),
            }
        except Exception as exc:
            return {
                "output": output,
                "rc": EXIT_ERROR,
                "status": "error",
                "reasons": [str(exc)],
                "log": str(log_path),
            }
        finally:
            try:
                session.terminate(grace_s=_HALT_TERMINATE_GRACE_S)
            except Exception:
                pass
            finally:
                _unregister_active_worker_session(session)
            try:
                if session.transcript_path.exists():
                    out.write("\n\n# Claude session transcript tail\n")
                    with session.transcript_path.open("rb") as tf:
                        tf.seek(0, 2)
                        size = tf.tell()
                        tf.seek(max(0, size - 65536))
                        out.write(tf.read().decode("utf-8", errors="replace"))
                    out.flush()
            except Exception:
                pass


def _rescan_worker_pool_progress_status(
    scratchpad: Path,
    phase: Phase,
    jobs: list[dict[str, str]],
    active_outputs: list[str],
) -> str:
    complete = sum(
        1 for job in jobs
        if _rescan_output_complete(scratchpad, phase, job["output"])
    )
    queued = max(0, len(jobs) - complete - len(active_outputs))
    return _format_worker_pool_progress_status(
        complete=complete,
        total=len(jobs),
        active_outputs=active_outputs,
        queued=queued,
        phase_label="rescan",
    )


def _run_rescan_worker_pool_pty(
    *,
    scratchpad: Path,
    project_root: str,
    config: dict,
    phase: Phase,
    base_cmd: list[str],
    env: dict[str, str],
    timeout: float,
    quiescence_s: float,
    attempt: int,
) -> int:
    jobs = _rescan_worker_jobs(scratchpad)
    if not jobs:
        log.warning("[rescan] worker-pool unavailable: no manifest jobs")
        return -2
    budget = int(config.get("pty_continuation_budget", 3))
    retry_reasons_by_output: dict[str, list[str]] = {}
    pool_started = time.time()
    for pool_attempt in range(1, budget + 2):
        open_jobs = _rescan_open_jobs(scratchpad, phase, jobs)
        if not open_jobs:
            passed, missing = gate_passes(scratchpad, project_root, phase)
            if passed:
                return 0
            log.warning(f"[rescan] worker-pool gate failed: {missing}")
            return -2
        concurrency = min(_RESCAN_WORKER_CONCURRENCY, max(1, len(open_jobs)))
        log.info(
            f"[rescan] worker PTY pool attempt {pool_attempt}: "
            f"{len(open_jobs)} open row(s), concurrency={concurrency}"
        )
        dispatch_plan = _rescan_dispatch_plan(
            scratchpad=scratchpad,
            project_root=project_root,
            config=config,
            attempt=pool_attempt,
            jobs=jobs,
            retry_reasons_by_output=retry_reasons_by_output,
        )
        open_outputs = {str(job["output"]) for job in open_jobs}
        _write_rescan_dispatch_contract(
            scratchpad,
            config,
            "claude-pty",
            dispatch_plan,
            dispatched_outputs=open_outputs,
        )
        dispatch_by_output = {
            str(item["job"]["output"]): item for item in dispatch_plan
        }
        pool_allowed_outputs = [str(job["output"]) for job in open_jobs]
        results: list[dict[str, Any]] = []
        runnable_jobs: list[dict[str, Any]] = []
        for job in open_jobs:
            fatal_binding_issues = _prepare_typed_model_worker_launch(
                phase=phase,
                config=config,
                scratchpad=scratchpad,
                project_root=project_root,
                agent_id=str(job.get("agent_id") or job["output"]),
                agent_role=str(job.get("role") or "") or None,
                output=str(job["output"]),
                timeout_s=timeout,
                work_category=str(job.get("category") or "rescan"),
                focus_area=str(
                    job.get("focus_area") or job.get("focus") or ""
                ),
                attempt=pool_attempt,
            )
            if fatal_binding_issues:
                results.append({
                    "output": str(job["output"]),
                    "rc": -2,
                    "status": "input_authority_debt",
                    "reasons": fatal_binding_issues,
                })
            else:
                runnable_jobs.append(job)
        display.print_phase_heartbeat(
            "rescan",
            int(time.time() - pool_started),
            status=_rescan_worker_pool_progress_status(
                scratchpad,
                phase,
                jobs,
                [j["output"] for j in runnable_jobs[:concurrency]],
            ),
        )
        with _JoiningWorkerPool(
            max_workers=concurrency,
            thread_name_prefix="plamen-rescan-worker",
        ) as executor:
            fut_to_job = {
                executor.submit(
                    _run_single_rescan_worker_pty,
                    job=job,
                    scratchpad=scratchpad,
                    project_root=project_root,
                    config=config,
                    phase=phase,
                    base_cmd=base_cmd,
                    env=env,
                    timeout=timeout,
                    quiescence_s=quiescence_s,
                    attempt=pool_attempt,
                    retry_reasons=retry_reasons_by_output.get(job["output"]),
                    allowed_outputs=pool_allowed_outputs,
                    rendered_prompt=str(
                        dispatch_by_output[str(job["output"])]["prompt"]
                    ),
                    inputs_prebound=True,
                ): job
                for job in runnable_jobs
            }
            pending_futs: set[concurrent.futures.Future] = set(fut_to_job)
            last_progress = time.time()
            while pending_futs:
                done, pending_futs = concurrent.futures.wait(
                    pending_futs,
                    timeout=_WORKER_POOL_UI_POLL_S,
                    return_when=concurrent.futures.FIRST_COMPLETED,
                )
                now = time.time()
                elapsed = int(now - pool_started)
                display.spin(elapsed)
                if display.graceful_stop.requested:
                    _cancel_pending_worker_futures(pending_futs, executor)
                    raise _PtyStop(-3)
                for fut in done:
                    result = fut.result()
                    results.append(result)
                    output = result.get("output", "(unknown)")
                    status = result.get("status")
                    log.info(f"[rescan] worker {output}: {status}")
                    display.print_phase_heartbeat(
                        "rescan",
                        elapsed,
                        status=f"worker {output}: {status}",
                    )
                    if result.get("status") == "rate_limited":
                        log.warning(
                            "[rescan] worker %s hit rate limit; stopping "
                            "remaining workers and surfacing phase-level "
                            "rate-limit pause",
                            output,
                        )
                        _cancel_pending_worker_futures(pending_futs, executor)
                        return 1
                    last_progress = now
                if pending_futs and now - last_progress >= _WORKER_POOL_HEARTBEAT_S:
                    active_outputs = [
                        fut_to_job[fut]["output"]
                        for fut in pending_futs
                        if fut in fut_to_job
                    ][:concurrency]
                    display.print_phase_heartbeat(
                        "rescan",
                        elapsed,
                        status=_rescan_worker_pool_progress_status(
                            scratchpad,
                            phase,
                            jobs,
                            active_outputs,
                        ),
                    )
                    last_progress = now
        if any(r.get("status") == "rate_limited" for r in results):
            return 1
        if any(r.get("rc") == -4 for r in results):
            log.error("[rescan] worker-pool containment violation")
            return -4
        retry_reasons_by_output = {
            str(r.get("output")): [
                f"status={r.get('status')}",
                *[str(x) for x in (r.get("reasons") or [])],
            ]
            for r in results
            if r.get("status") != "complete"
        }
        passed, missing = gate_passes(scratchpad, project_root, phase)
        if passed:
            return 0
        log.info(
            f"[rescan] worker-pool attempt {pool_attempt} incomplete: {missing}"
        )
    log.warning("[rescan] worker-pool retry budget exhausted")
    return -2


